INSERT INTO `npc_questions` VALUES (1, '', '', '', '', 'Je suis un des #5 percepteurs de la guilde #1.\\nJe peux stocker jusqu\\\'? #2 pods d\\\'objets.\\nMa prospection de #3 me permet de r?cup?rer les objets des combats, apr?s que les aventuriers se soient servis.\\nMa sagesse de #4 me permet de faire progresser ma guilde.');
INSERT INTO `npc_questions` VALUES (2, '', '', '', '', 'Je suis le percepteur de la guilde #1.\\nElle n\\\'est pas tr?s en forme, en ce moment.\\nJe crois qu\\\'exceptionnellement, je ne participerai pas aux combats.');
INSERT INTO `npc_questions` VALUES (25, '144;365;357', '', '', '0', 'Bonjour, je suis Kelog Korflex, c?l?bre Boulanger d\\\'Amakna. \\nJ\\\'ai quelques petits travaux pour vous si vous ?tes int?ress');
INSERT INTO `npc_questions` VALUES (29, '81;377;326;82', '', '', '', 'Bonjour, je suis Bowisse, le plus r?put? des cordonniers... Et grand ma?tre de l\\\'Ordre du Cul Bott?, sp?cialit? martiale des cordonniers d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (30, '272;270', '', '', '0', 'H? bien, on ne peut pas dire que l\\\'on ch?me en ce moment avec ma petite Shika... Nous sommes d?bord?s ! \\nHeureusement que les r?coltes s\\\'annoncent plut?t bonnes. \\n \\nSi vous avez du temps, j\\\'ai du travail pour vous.');
INSERT INTO `npc_questions` VALUES (32, '', '', '', '', 'Encore une journ?e bien charg?e... J\\\'esp?re que Farle s\\\'en sort avec sa moisson. N\\\'h?sitez pas ? aller le voir si vous recherchez du travail.');
INSERT INTO `npc_questions` VALUES (33, '279;281', '', '', '0', 'Grumph, je me suis encore fait piquer par ces satan?s Moskitos...Maman me dit que c\\\'est ? cause de ma peau de p?che, elle est trop sucr?e... \\nJe pense que vous pourriez me venir en aide.');
INSERT INTO `npc_questions` VALUES (34, '', '', '', '', 'Bonjour compagnon ! \\nJ\\\'ai besoin de quelques ingr?dients pour donner du go?t ? mes pains. Si vous me rapportez une cawotte, je vous donnerai un sachet de sel pour vous r?compenser.');
INSERT INTO `npc_questions` VALUES (35, '282;283;561', '', '', '', 'Bonjour ? toi ?tranger.  \\nJe suis une Bijouti?re incontournable d\\\'Amakna, tout le monde s\\\'arrache mes nouvelles cr?ations. \\nEn cons?quence, je suis un peu d?bord?e ces derniers temps;\\r\\n            si vous cherchez du travail, je peux vous en donner.');
INSERT INTO `npc_questions` VALUES (36, '', '', '', '', 'Youha ! Quelqu\\\'un qui vient me rendre visite, ?a fait plaisir. Il n\\\'y a jamais personne de ce c?t? d\\\'Amakna. Ca me fait tellement plaisir que je vais accepter de r?pondre ? vos questions, aussi idiotes soient-elles.');
INSERT INTO `npc_questions` VALUES (37, '275', '', '', '', 'Bonjour, je suis Abely Bobeule, Sculpteur sur Bois renomm?, j\\\'exerce avec talent, les professions de Sculpteur de Baguettes, Sculpteur d\\\'Arcs, et Sculpteurs de B?tons.');
INSERT INTO `npc_questions` VALUES (38, '341;508', '', '', '0', 'Je suis Graham Finame, tout le monde me conna?t ici, et les monstres qui ont connu le tranchant de mes lames sont tous morts. J\\\'ai tout ce qu\\\'il faut en vente pour exercer le m?tier de Forgeron si vous ?tes int?ress');
INSERT INTO `npc_questions` VALUES (39, '', '', '', '', 'Bonjour, je suis Hanniboul Smisse, je suis le chef Forgeron d\\\'une c?l?bre agence secr?te, mais j\\\'ai perdu de vue mes compatriotes depuis notre derni?re op?ration secr?te, essayez de les retrouver et pr?venez-moi d?s que possible.');
INSERT INTO `npc_questions` VALUES (48, '', '', '', '', 'Vous exercez d?j? ce m?tier, je n\\\'ai plus rien ? vous apprendre.');
INSERT INTO `npc_questions` VALUES (53, '', '', '', '', 'Nom de nom, mais il y avait bien un passage pour aller dans une mine ici... C\\\'est pas possible, plus moyen de remettre la main dessus... Je commence ? me faire vieux...');
INSERT INTO `npc_questions` VALUES (60, '200;198', '', '', '0', 'Ah je souffre, que c\\\'est d?lectable, huhu, mes ailes me font mal, j\\\'ai pass? la nuit ? les fouetter brrrr...');
INSERT INTO `npc_questions` VALUES (81, '80;7453;7', '', '', '0', 'Bonjour, je sens que vous voulez en savoir plus sur mon histoire.');
INSERT INTO `npc_questions` VALUES (82, '7', '', '', '0', 'J\\\'ai longtemps cherch? comment immobiliser les monstres.');
INSERT INTO `npc_questions` VALUES (83, '', '', '', '', 'En fait je n\\\'ai jamais trouv? comment faire.');
INSERT INTO `npc_questions` VALUES (84, '', '', '', '', 'Mais vous ?tes un monstre !');
INSERT INTO `npc_questions` VALUES (85, '630', '', '', '', 'C\\\'est un ordre dans lequel il est d?licat de rentrer. \\nHogmeiser ?tait le chef de l\\\'Ordre du Cul Bott?, mais il a disparu depuis des ann?es, ne laissant derri?re lui que ses vieilles bottes us?es.  \\n');
INSERT INTO `npc_questions` VALUES (86, '', '', '', '', 'Je ne vends pas de bottes ? n\\\'importe qui, voyons !');
INSERT INTO `npc_questions` VALUES (87, '', '', '', '', 'Bonjour, je suis Charlotte, mais tout le monde ici m\\\'appelle Charlot pour des raisons que j\\\'ignore encore. Aidez-moi ? comprendre pourquoi en me ramenant une preuve ?crite et je saurai vous r?compenser. \\nSinon, je recherche de la Farine de Bl? pour faire quelques brioches, si vous me donnez une unit? de Farine de Bl?, je vous donnerai en ?change une Ficelle en Lin.');
INSERT INTO `npc_questions` VALUES (90, '111;109;110;209;37', '', '', '0', 'Bonjour, je suis Edrige Valling, tireuse ? l\\\'arc renomm?e, je me ferais un plaisir de r?pondre ? vos questions sur les Arcs ou sur la fa?on de les fabriquer.');
INSERT INTO `npc_questions` VALUES (91, '', '', '', '', 'Bonjour, je suis Elya Wood, j\\\'ai besoin de manger un Champignon pour redonner un peu de couleur ? mes ailes. \\nSi vous m\\\'en ramenez un, je vous donnerai ma Tailladeuse de Baguette, qui vous permettra de sculpter des baguettes si vous avez le m?tier correspondant.');
INSERT INTO `npc_questions` VALUES (92, '', '', '', '', 'Hyooohooo, j\\\'ai besoin de me confectionner des bretelles en cuir pour que mon pagne ne tombe plus ! Ramenez-moi du cuir de Bouftou, et je vous donnerai en ?change ma Tailladeuse de B?ton : elle permet de sculpter des b?tons si vous ma?trisez le m?tier correspondant.');
INSERT INTO `npc_questions` VALUES (93, '164', '', '', '', 'Bonjour, j\\\'ai besoin d\\\'att?nuer mes souffrances, car je me suis arrach? une moustache en me battant avec un Mulou, alors si tu as du pain en trop n\\\'h?site pas ? me le donner. \\nJe parie que tu ne connais pas Wiss Catz.');
INSERT INTO `npc_questions` VALUES (98, '', '', '', '', 'Brrr, je suis Rigal Main Crochue, tout le monde me respecte ici, car tout le monde sait que je suis un membre des Roublards...');
INSERT INTO `npc_questions` VALUES (100, '203;37', '', '', '0', 'Bonjour, je suis Rish Claymore, Ma?tre d\\\'armes respect? dans tout Amakna. Si vous cherchez une Pierre ? Eguiser, vous avez de la chance, j\\\'en vends une.');
INSERT INTO `npc_questions` VALUES (101, '', '', '', '', 'Bonjour, je revends la Pioche de mon mari si vous ?tes int?ress?. Bon ?tat g?n?ral, tr?s peu servi.');
INSERT INTO `npc_questions` VALUES (102, '143;113;112', '', '', '0', 'Bonjour, je suis Laura Soho, serveuse dans cette taverne, que puis-je vous servir ?');
INSERT INTO `npc_questions` VALUES (103, '', '', '', '', 'Hum, h? bien petit, je pars bient?t en retraite, et je revends mon manuel de Forgeur de Pelles. Si tu es int?ress?, j\\\'ai m?me le marteau pour forger les pelles qui va avec ! Je suis d?sormais incapable de le soulever avec mon arthrose...*soupir*');
INSERT INTO `npc_questions` VALUES (108, '', '', '', '', 'Quel lieu cherchez vous ?');
INSERT INTO `npc_questions` VALUES (111, '', '', '', '', 'Vous n\\\'avez pas assez de kamas pour acheter un ticket de tombola, il vous faut au moins 10 kamas.');
INSERT INTO `npc_questions` VALUES (121, '374;215', '', '', '', 'Bonjour, je suis Hugo B?lo, jeune Ma?tre F?ca, j\\\'adore chatouiller mes Bouftous pour les faire couiner. ');
INSERT INTO `npc_questions` VALUES (127, '65', '', '', '0', 'La corde des arcs est en g?n?ral faite ? partir de Ficelle en Lin tress?e. Je passe beaucoup de temps ? confectionner des cordes pour mes arcs, les miennes sont particuli?rement robustes et souples ? la fois. \\nSi vous cherchez de la Ficelle de Lin pour les cordes de vos arcs, je peux vous en donner en ?change d\\\'une unit? de Lin.');
INSERT INTO `npc_questions` VALUES (128, '', '', '', '', 'Tous les bois sont utilis?s dans la confection des arcs. Certains sont bien meilleurs que d\\\'autres, et il n\\\'est pas surprenant qu\\\'un arc en Bois de Fr?ne soit moins efficace qu\\\'un arc en Bois d\\\'If. Les arcs les plus performants sont en g?n?ral compos?s de plusieurs Bois diff?rents, ce qui complique g?n?ralement la confection de ces arcs et demande d\\\'avoir de bonnes relations avec les B?cherons.');
INSERT INTO `npc_questions` VALUES (129, '', '', '', '', 'Les arcs aux pouvoirs magiques sont rares et d?licats ? confectionner, il faut souvent allier des Bois rares ? des m?taux ou des pierres pr?cieuses pour rendre un arc magique et efficace.');
INSERT INTO `npc_questions` VALUES (130, '', '', '', '', 'De temps en temps, des f?tes sont organis?es dans la taverne, des m?nestrels viennent jouer pour r?chauffer l\\\'ambiance, les Tofus grill?s sont g?n?ralement ? moiti? prix les soirs de f?te. Des r?unions sont parfois organis?es ? la Taverne entre membres de m?me guilde, ou entre groupes d\\\'amis.');
INSERT INTO `npc_questions` VALUES (131, '142', '', '', '0', 'La Bi?re est produite par les Brasseurs d\\\'Amakna, il existe plusieurs vari?t?s de Bi?re, qui sont issues, entre autres, du Malt, du Houblon et de l\\\'Orge. Les bi?res les plus puissantes peuvent avoir des effets spectaculaires et inattendus.');
INSERT INTO `npc_questions` VALUES (132, '', '', '', '', 'Xavier le Boulanger est tr?s c?l?bre dans le milieu de la Boulangerie. Je pense que ?a n\\\'est pas justifi?, il n\\\'est pas aussi charismatique que moi, ses pains ne sont pas aussi dor?s que les miens, et tout ce que l\\\'on raconte ? son sujet n\\\'est que l?gendes. Tout le monde pense que je suis jaloux, mais c\\\'est faux.');
INSERT INTO `npc_questions` VALUES (134, '121;1003;138;116', '', '', '0', 'Bonjour, je suis Grizmine, je suis passionn? par les jeux de hasard, je peux vous proposer de participer ? la Grande Tombola d\\\'Amakna si vous le d?sirez. \\nVous pouvez ?galement jouer avec moi au jeu \\\"Les Chopines du Hasard\\\" ou au jeu de cartes \\\"Tragic The Gardening\\\".');
INSERT INTO `npc_questions` VALUES (135, '118;141', '', '', '0', 'C\\\'est tr?s simple, il vous suffit d\\\'acheter un ticket de tombola ? 10 Kamas, et vous aurez peut-?tre une chance de gagner la cagnotte qui s\\\'?l?ve ? 20000 Kamas !');
INSERT INTO `npc_questions` VALUES (136, '131', '', '', '0', '(Grizmine inscrit votre nom sur une grille, lance des d?s ? 37 faces en l\\\'air, les rattrape, fait des calculs ?tranges, se gratte les moustaches et r?fl?chit...)');
INSERT INTO `npc_questions` VALUES (137, '', '', '', '', 'Mais vous ne pouvez pas jouer, vous n\\\'avez pas assez de kamas pour miser cette somme. Misez moins ou revenez avec plus de kamas.');
INSERT INTO `npc_questions` VALUES (138, '133;134;135;136', '', '', '0', '(Grizmine met le d? dans la chopine en Bronze, bouge tr?s rapidement les chopines, le d? semble passer d\\\'une chopine ? l\\\'autre sans que vous puissiez comprendre comment il fait) \\n \\nAlors dans quelle chopine se trouve le d? mon ami ?');
INSERT INTO `npc_questions` VALUES (140, '', '', '', '', 'Fantastique, quelle chance ! Vous avez gagn?, et cela faisait longtemps que ?a n\\\'?tait pas arriv? dans cette taverne. \\n \\n(Grizmine vous donne les kamas en se grattant les moustaches et en ronronnant)');
INSERT INTO `npc_questions` VALUES (144, '122;130;141', '', '', '0', 'C\\\'est tr?s simple, je cache un d? sous une chopine de Bi?re, je bouge les chopines dans tous les sens, et vous devez trouver dans quelle chopine se cache le d? pour remporter le double de la somme que vous avez mis');
INSERT INTO `npc_questions` VALUES (145, '124;126;127;128', '', '', '0', '(Grizmine met le d? dans la chopine en Bronze, bouge tr?s rapidement les chopines, le d? semble passer d\\\'une chopine ? l\\\'autre sans que vous puissiez comprendre comment il fait) \\n \\nAlors dans quelle chopine se trouve le d? mon ami ?');
INSERT INTO `npc_questions` VALUES (147, '', '', '', '', 'Ola, m?fie-toi ! Dans nos contr?es, les passagers clandestins, on les passe par-dessus bord. \\nTu ne poss?des pas assez de kamas pour embarquer sur mon bateau, reviens me voir quand tu auras les moyens.');
INSERT INTO `npc_questions` VALUES (163, '', '', '', '', 'Fantastique, quelle chance ! Vous avez gagn?, et cela faisait longtemps que ?a n\\\'?tait pas arriv? dans cette taverne. \\n \\n(Grizmine vous donne les kamas en se grattant les moustaches et en ronronnant)');
INSERT INTO `npc_questions` VALUES (164, '', '', '', '', 'D?sol?, mais vous avez perdu. Vous aurez peut-?tre plus de chance la prochaine fois, n\\\'h?sitez pas ? retenter votre chance.');
INSERT INTO `npc_questions` VALUES (166, '134', '', '', '0', 'Vous n\\\'avez pas de set de cartes \\\"Tragic the Gardening\\\", vous ne pouvez donc pas jouer avec moi ? ce jeu. Revenez me voir lorsque vous aurez trouv? un set de cartes.');
INSERT INTO `npc_questions` VALUES (167, '', '', '', '', 'Je n\\\'?changerai les miens contre rien au monde, except? contre des sets plus puissants encore. Si vous recherchez des sets, adressez-vous aux personnes qui aiment jouer, vous croiserez s?rement au fil de vos voyages, d\\\'autres joueurs de \\\"Tragic the Gardening\\\" qui accepteront de vous en ?changer.');
INSERT INTO `npc_questions` VALUES (168, '', '', '', '', 'Depuis que la brasserie du village a ?t? d?truite par un Craqueleur assoiff?, les Brasseurs sont au ch?mage, mais le g?rant de la taverne a d?cid? de leur pr?ter la cave de la Taverne pour qu\\\'ils y installent une brasserie et puissent continuer ? produire leur d?licieuse Bi?re. \\nJ\\\'esp?re que la Brasserie sera bient?t op?rationnelle, car nos r?serves de Bi?re diminuent ? vue d\\\'oeil !');
INSERT INTO `npc_questions` VALUES (169, '', '', '', '', 'J\\\'ai besoin de Bois de Fr?ne pour alimenter la chemin?e de la taverne, mais je n\\\'ai plus le temps d\\\'aller en chercher moi-m?me, si vous m\\\'en ramenez une unit?, je vous donnerai de l\\\'eau en ?change.');
INSERT INTO `npc_questions` VALUES (170, '', '', '', '', 'Pour faire du pain, il faut de la Farine, de l\\\'Eau et parfois de la Levure de Boulanger. En g?n?ral, les meilleurs pains sont ceux compos?s de multiples farines, mais ils sont ?galement beaucoup plus complexes ? cuire.');
INSERT INTO `npc_questions` VALUES (171, '145;146', '', '', '0', 'Bienvenue ? la taverne, nous pouvons vous fournir de quoi ?tancher votre soif si vous le d?sirez. \\nQu\\\'est-ce que je vous sers ?');
INSERT INTO `npc_questions` VALUES (172, '', '', '', '', 'Cette Taverne est ici depuis que je suis toute petite, mon p?re m\\\'y emmenait r?guli?rement, et j\\\'ai fini par d?cider d\\\'y travailler comme serveuse.  \\nLe tavernier, qui est propri?taire de cet endroit est un homme riche et appr?ci? pour sa g?n?rosit?, n\\\'h?sitez pas ? lui parler si vous cherchez un peu de travail, il est souvent d?bord');
INSERT INTO `npc_questions` VALUES (173, '', '', '', '', 'Le Tavernier m\\\'a demand? de lui ramener du Houblon pour qu\\\'il le donne ? ses associ?s brasseurs, mais je n\\\'ai pas le temps d\\\'aller en acheter ? Farle Ingalsse le Paysan. \\nSi vous me ramenez une unit? de Houblon, je vous offrirai une Bi?re en ?change.');
INSERT INTO `npc_questions` VALUES (174, '', '', '', '', 'Ssssshhhh...Passhhhh ton cheminssshhhh jeune troudboulsshhh...Seuls les ?tres les plus vilsssshhhh peuvent ?tre re?us par ma?tre Vil Smisse... \\nSssshhhhhhh....Asssshhhhhh....Uuuuuusssshhh');
INSERT INTO `npc_questions` VALUES (175, '', '', '', '', 'Ssssshhhhhhh...Notre clansshhhh nous impose...Ssshhhh...de parlessshhh de parler comme ?assshhh...Para?t que ca renforce notre c?t? m?ssshhhhanssshhh...');
INSERT INTO `npc_questions` VALUES (176, '', '', '', '', 'Huummmm...#1, le disciple d\\\'Oto Mustam, que puis-je faire pour un vil Br?kmarien comme toi ?');
INSERT INTO `npc_questions` VALUES (185, '', '', '', '', 'Les Roublards sont les ?tres les plus vils et les plus cruels, ils sont redout?s de tout Amakna. Je suis un membre de cette Confr?rie depuis des ann?es d?j?, et je ne regrette rien, je suis devenu plus puissant, plus respect? gr?ce ? eux.');
INSERT INTO `npc_questions` VALUES (191, '', '', '', '', 'Le repaire de la Confr?rie des Roublards est bien cach? et surtout bien prot?g?, il est entour? d\\\'eau, son entr?e est situ?e dans une zone particuli?rement dangereuse et gard?e par des membres de la Confr?rie.  \\n \\nSeules les personnes les plus cruelles peuvent esp?rer rentrer dans ce rep?re et rencontrer le Ma?tre de la Confr?rie des Roublards.');
INSERT INTO `npc_questions` VALUES (197, '', '', '', '', 'Entrer dans le labyrinthe ? Laisse-moi rire, j\\\'entends d\\\'ici tes genoux s\\\'entrechoquer ! Ha ! Ha ! Reviens lorsque tu seras un peu plus exp?riment');
INSERT INTO `npc_questions` VALUES (199, '165', '', 'PG=6', '200', 'Hoho, un joueur ! Si vous pouvez me ramener un tr?fle ? cinq feuilles, alors je vous pr?senterai Wiss Catz, le l?gendaire Ecaflip tomb? dans la marmite de soupe de tr?fles ?tant petit.');
INSERT INTO `npc_questions` VALUES (200, '', '', '', '', 'Il n\\\'y a pas de gloire ? rouler les moins chanceux... Les Ecaflips ne parient que face ? d\\\'autres Ecaflips.');
INSERT INTO `npc_questions` VALUES (201, '', '', '', '', 'Tr?s bien, je vais vous amener ? Wiss Catz. Mais surtout, ne lui donnez pas de tr?fle : il est au r?gime.');
INSERT INTO `npc_questions` VALUES (202, '', '', 'PG=6', '', 'Le bluff ne marche pas avec les Ecaflips, vous devriez le savoir. Vous n\\\'avez pas ce que je vous ai demand');
INSERT INTO `npc_questions` VALUES (203, '', '', '', '', 'Impressionnant ! Cet ongle est sans doute l\\\'un des plus vieux qu\\\'il m\\\'ait ?t? donn? de voir et sentir.. (Lanseuft hume l\\\'ongle ? plein nez) Us? et malodorant ? souhait ! \\n \\nTr?s bien, tu peux passer si tu n\\\'as pas peur.');
INSERT INTO `npc_questions` VALUES (204, '', '', '', '', 'Hum. D?sol?, mais Wiss Catz m\\\'a inform? qu\\\'il ne pariait jamais s\\\'il n\\\'?tait pas s?r de gagner. Il d?cline donc votre offre... Tenez je vous rends votre tr?fle.');
INSERT INTO `npc_questions` VALUES (205, '', '', '', '0', 'Les dopeuls sont des ?tres qui copient les actions des autres pour survivre. On ne sait pas trop d\\\'o? ils viennent. Un jour ils sont apparus en masse et ont tent? d\\\'envahir la contr?e. Nous avons gagn? cette guerre et depuis on en voit assez peu.');
INSERT INTO `npc_questions` VALUES (209, '', '', '', '', 'Tr?s bien. Tu as l\\\'air d\\\'avoir suffisamment d\\\'assurance pour affronter le Mulou. Tu peux passer.');
INSERT INTO `npc_questions` VALUES (212, '1504', '', '', '', 'Si tu veux affronter un Dopeul, je te conseille de te pr?parer. Alors ? pr?t ?');
INSERT INTO `npc_questions` VALUES (238, '', '', '', '', 'Whaaaa ! Mais que... ?  Mais qui... ? Mais... ? Ha ! Ha ! Vous ?tes perdu vous non ? Allez, ouste ! Laissez-moi passer ! j\\\'ai du travail moi m?ssieur !');
INSERT INTO `npc_questions` VALUES (239, '', '', '', '', 'Ha ! Ha ! Je le savais ! Vous ?tes perdus ! La sortie ? Je n\\\'en sais rien, ?a fait des ann?es que je la cherche. Oh ?a va hein ! Effacez ce sourire moqueur ! je sais tr?s bien o? je suis d\\\'abord. Je suis... euh... Ha non, je ne sais pas.');
INSERT INTO `npc_questions` VALUES (240, '', '', '', '', 'Mais qui ?tes-vous ? Allez-vous-en ! Haaa... Je vois ! vous essayez de voler mon tr?sor ! Mais il est ? moi ! ? moi ! De toute fa?on, je ne vous dirai pas o? il est ! pas un mot ! Rien !');
INSERT INTO `npc_questions` VALUES (241, '', '', '', '', 'Je vous r?p?te que je ne vous dirai rien ! Jamais je ne vous dirai qu\\\'il est cach? dans une grotte, dont l\\\'entr?e se trouve ? l\\\'ombre d\\\'un buisson lumineux. Oups... bah, l\\\'entr?e est scell?e de toute fa?on, et je ne sais m?me plus o? se trouve ce buisson...');
INSERT INTO `npc_questions` VALUES (242, '', '', '', '', 'Vous ?tes collant, vous ! Bon. J\\\'en ai marre d\\\'?tre seul ici... Et puis j\\\'ai peur du noir. Amenez-moi 10 plumes de tofu et 2 gel?es bleut?es, que je puisse me confectionner des ailes pour m\\\'enfuir d\\\'ici. Je vous donnerai la cl? de ma grotte en ?change.');
INSERT INTO `npc_questions` VALUES (243, '196;195;566', '', '', '0', 'Bonjour, je me nomme Lanseuft, je viens de Troille. Sache que derri?re ce bosquet se trouve un inqui?tant d?dale de v?g?tations dont je suis le gardien. Nombreux sont ceux qui se sont aventur?s dans ce labyrinthe, partant ? la recherche des fabuleux tr?sors qu\\\'il est cens? dissimuler, mais peu en sont ressortis.');
INSERT INTO `npc_questions` VALUES (244, '', '', '', '', 'Laisse-moi te mettre en garde. Ce d?dale abrite de nombreux monstres, tels les malheureux aventuriers y ayant laiss? la vie. Ils hantent d?sormais ce sombre et hostile lieu. Mieux vaut ?tre aguerri avant d\\\'oser y p?n?trer.');
INSERT INTO `npc_questions` VALUES (245, '197', '', '', '0', 'Tr?s bien, tu sembles d?cid? ? mourir, c\\\'est ton choix, que tu l\\\'assumes ou le regrettes. Mais avant de te laisser passer, il me faut une preuve de ta valeur. Am?ne-moi un ongle de chevaucheur de Karne, leur odeur fait fuir bon nombre de monstres et me prot?ge. Si tu es capable d\\\'en arracher ? l\\\'un de ces fiers combattants, alors je saurai que je peux te laisser passer.');
INSERT INTO `npc_questions` VALUES (246, '', '', '', '', 'D?sol?, mais je ne te laisserai pas entrer tant que tu ne seras pas capable d\\\'arracher un ongle ? un Karne. J\\\'ai bien peur que sinon ce ne soit toi qui t\\\'en fasses arracher plus d\\\'un dans le labyrinthe...');
INSERT INTO `npc_questions` VALUES (247, '199', '', 'PG=2', '248', 'C\\\'est vraiment gentil ? toi, mais me frapper est un privil?ge qu\\\'il faut m?riter.');
INSERT INTO `npc_questions` VALUES (248, '', '', '', '', 'Que pourrais-tu bien conna?tre ? l\\\'art du fouet ? Reviens quand tu auras une queue fourchue et des cornes !');
INSERT INTO `npc_questions` VALUES (249, '', '', '', '', 'Je n\\\'ai pas la t?te ? ?a pour l\\\'instant, mais tu peux t\\\'amuser avec nos dopeuls si tu veux. Va voir Brigitebardo Peule, c\\\'est elle qui les ?l?ve.');
INSERT INTO `npc_questions` VALUES (251, '376', '', '', '', 'Il permet de forger des marteaux de qualit? ? condition d\\\'exercer le m?tier correspondant. J\\\'en vends justement, mais si tu n\\\'as pas d\\\'argent, on peut quand m?me s\\\'arranger. J\\\'aurais besoin de Cornes de Bouftou, leur forme et leur texture sont parfaites pour... enfin, ?a ne te regarde pas.');
INSERT INTO `npc_questions` VALUES (253, '', '', '', '', 'Il m\\\'arrive de livrer des combats amicalement, lorsque l\\\'adversaire est de valeur.');
INSERT INTO `npc_questions` VALUES (254, '', '', '', '', 'M\\\'affronter en duel est un privil?ge que je r?serve aux membres de ma classe. Face aux autres, je ne d?gaine que pour tuer.');
INSERT INTO `npc_questions` VALUES (258, '1005;1141', '', '', '0', 'Bonjour, je suis Aria Knofob. Je suis install?e depuis peu dans la province d\\\'Amakna, et pensais avoir ?t? tr?s chanceuse de trouver cette maison ? vendre pour quelques kamas.\\nIl faut dire que le cadre est agr?able, mais le bosquet qui l\\\'entoure regorge d\\\'Araknes. La lumi?re les attire, et je suis envahie. Ils se sont install?s dans le grenier.');
INSERT INTO `npc_questions` VALUES (259, '', '', '', '', 'Oh merci ! Si vous parvenez ? me d?barrasser de ces satan?es bestioles, je saurai vous r?compenser. Hum... Perdez cet air pervers, je vous paierai en biens mat?riels !');
INSERT INTO `npc_questions` VALUES (260, '336', '', 'RO=973,1', '', 'Oh ! merci mille fois ! Tenez, j\\\'ai trouv? ce parchemin magique au grenier lorsque j\\\'ai emm?nag?, je suis s?re qu\\\'il pourrait vous ?tre utile.');
INSERT INTO `npc_questions` VALUES (261, '', '', '', '', 'D?sol? mais il reste encore des ind?sirables dans mon grenier, je les entends marcher sur le plancher. Revenez lorsque vous aurez ce que je vous ai demand');
INSERT INTO `npc_questions` VALUES (262, '', '', '', '', 'En tant que Cr?, vous pouvez acc?der ? l\\\'?tage, mais il est actuellement occup? par mon entraineur de dopeul.');
INSERT INTO `npc_questions` VALUES (263, '', '', '', '', 'Cette partie du magasin est interdite aux personnes ?trang?res ? la classe des Cr?s.');
INSERT INTO `npc_questions` VALUES (265, '', '', '', '', 'Si tu veux affronter un Dopeul, il faudra faire une donation de Ficelle de lin au temple...');
INSERT INTO `npc_questions` VALUES (268, '', '', '', '', 'Convaincre les novices par les mots est bien trop long, allez voir Juhdo Peule au sous-sol et demandez lui de vous entra?ner.');
INSERT INTO `npc_questions` VALUES (270, '21', '', '', '0', 'Si tu veux affronter un Dopeul, je te conseille de te pr?parer. Alors ? pr?t ?');
INSERT INTO `npc_questions` VALUES (274, '', '', '', '', 'Vous dites n\\\'importe quoi ! \\nCela fait partie des choses que vous devriez conna?tre en tant que repr?sentant des Eniripsa.');
INSERT INTO `npc_questions` VALUES (275, '', '', '', '', 'Que pourriez-vous bien conna?tre aux vertus des champignons ? Vous n\\\'?tes m?me pas Eniripsa.');
INSERT INTO `npc_questions` VALUES (278, '22', '', '', '0', 'Gni ! Hi ! Hi ! Bonjour ? toi ! Je me nomme Mori Arty, je suis le plus grand brigand de tous les temps. Je me suis fait arr?t?, et j\\\'ai d? ?plucher des patates pendant plus de dix ans. Mais ? pr?sent je suis ? nouveau libre, et je vais recommencer la m?me chose que chaque nuit : tenter de conqu?rir le monde !');
INSERT INTO `npc_questions` VALUES (280, '', '', '', '', 'Hmmm... Mouiiii ! Je le savais ! Haaa ! Quel g?nie ! Quelle intelligence ! J\\\'ai mis au point un plan que je qualifierais de g?nial. Mais pour le moment j\\\'ai besoin de rallier assez de personnes ? ma cause, je pense qu\\\'une quarantaine de voleurs devrait faire l\\\'affaire...');
INSERT INTO `npc_questions` VALUES (281, '', '', '', '', 'Ha ! Ha ! Pensez-vous vraiment que je vais d?voiler mes plans diaboliquement g?niaux au premier venu ? Je ne partagerai mes id?es qu\\\'avec un v?ritable malfaiteur. \\n(En grommelant) Pfff... Il devient difficile de nos jours de trouver de la main-d\\\'oeuvre qualifi?e... \\n');
INSERT INTO `npc_questions` VALUES (282, '', '', '', '', 'Hin ! Hin ! Hin ! Ma diabolique intelligence vous impressionne, n\\\'est-ce pas ? Vous voulez faire partie des miens, tr?s bien. Si vous me ramenez quatre-vingts fleurs de pissenlit diabolique, je ferai de vous l\\\'un des miens et vous r?compenserai. Ce sont les seules fleurs qui s\\\'accordent avec ma prodigieuse intelligence.');
INSERT INTO `npc_questions` VALUES (283, '226', '', '', '0', 'Hello ! Je me nomme Simgood, et je suis marin. J\\\'ai parcouru toutes les mers du globe, mais mon r?ve est d\\\'ouvrir une boutique de souvenirs, qui se vendront par milliers - par millions que dis-je ! - ? travers le monde. Les gens se les arracheront, juste pour pouvoir dire qu\\\'ils poss?dent un souvenir de Simgood le marin. Je pense commencer en taillant ou d?corant des pinces de crabe.');
INSERT INTO `npc_questions` VALUES (284, '', '', '', '', 'Ma foi pourquoi pas ! Si tu me rapportes des pinces de crabe, je te paierai. Pour chaque lot de trois pinces de crabe que tu me ram?neras, je te donnerai des graines de pavot, qui parfument si bien les pains d\\\'un bon boulanger.');
INSERT INTO `npc_questions` VALUES (285, '228;227', '', '', '', 'Hello. Je dis ! moi ?twre Hipipee Houwrax. Je veniwr du pays des angles dwroits, and je vouloiwr lancer new wrestauwrant. Ma sp?cialit? ?twre le gigot de sanglier ? la menthe accompagn? de cewrvoise ti?de. \\nhmm... Je dis! Ceci est delicious, n\\\'est-il pas ? \\nJe dis. But je avoiwr besoin de gel?e menthe, and je ?twre bloqu? ici pouwr suwrveiller la cewrvoise ti?diwr. Cwruel dilemne !');
INSERT INTO `npc_questions` VALUES (286, '', '', '', '', 'Je dis. je boiwre une tasse d\\\'eau chaude jeudi, avec un nuage de lait.');
INSERT INTO `npc_questions` VALUES (287, '', '', '', '', 'Oh gwreat ! je dis ! Ca c\\\'est un mowrceau de chance ! Vous ?twre wreally un gentil homme. Amenez ? moi 25 menthes gel?es, et je vous offwriwr en ?change une bleue pwr?cieuse piewrwre. Secouons-nous les mains pouwr concluwre notre cowrdial accowrd !');
INSERT INTO `npc_questions` VALUES (288, '', '', '', '', 'Oh ! Un visiteur ! Je ne r?ve pas ?! Youpi !  Bonjour ? vous ! Je me pr?sente : je m\\\'appelle Ale One. Je vis ici depuis un peu plus de dix ans, et vous ?tes le premier visiteur que je vois depuis bien longtemps. J\\\'ai eu ce terrain pour une bouch?e de pain ? l\\\'?poque, je comprends pourquoi le vendeur avait ce rire moqueur ? pr?sent. D\\\'ailleurs, j\\\'ai mis ce terrain ? vendre depuis 9 ans, 10 mois et 17 jours.');
INSERT INTO `npc_questions` VALUES (289, '', '', '', '', 'Je vends ce terrain pour une bouch?e de pain ! pour tout achat de terrain, la maison est offerte ! Vous verrez, on y vit tr?s bi... tr?s bi... tr?s b... tr?s mal en fait. J\\\'en peux plus de vivre ici, mais je n\\\'ai pas assez d\\\'argent pour me racheter une maison...');
INSERT INTO `npc_questions` VALUES (290, '', '', '', '', 'On manque de tout ici. Pas de voisins, pas d\\\'eau courante, rien pour se distraire, m?me pas un supermarch? ? proximit? ! Je n\\\'ai plus rien ? manger depuis 9 ans, 11 mois et 26 jours. Croyez-moi, sucer des cailloux ?a va bien un moment, mais on s\\\'en lasse vite. Si vous pouviez me ramener des c?tes de Rib, j\\\'en r?ve depuis au moins dix ans ! Haaa... des c?tes de Riiib. J\\\'offre des graines de s?same en ?change.');
INSERT INTO `npc_questions` VALUES (291, '231', '', '', '', 'Bonjour, vous avez affaire ? une l?gende, je suis Kwaker Vans. Cet imposteur de Kelog Korflex m\\\'a pris ma place de leader sur le march? du pain en Amakna. Mais je pr?pare une contre-attaque, le Pain au curry sans curry !');
INSERT INTO `npc_questions` VALUES (292, '232;233', '', '', '', 'C\\\'est une id?e r?volutionnaire, mais elle demande beaucoup d\\\'exp?rimentations. Je me sers du F?mur du Chafer Archer r?duit en poudre pour simuler le go?t du curry. Mais le bon dosage est difficile ? trouver et je suis en manque de f?murs.');
INSERT INTO `npc_questions` VALUES (293, '', '', '', '', 'Je vous donnerai une unit? de farine compl?te. Mais vous pouvez aussi avoir le privil?ge de tester un de mes prototypes de pain au curry, l\\\'effet n\\\'est pas garanti, mais il pourrait bien vous surprendre. En g?n?ral pour les test, je me sers de mon apprenti, mais il est un peu r?ticent ces derniers temps.');
INSERT INTO `npc_questions` VALUES (294, '', '', '', '', 'J\\\'?change un pain au curry sans curry contre 5 fleurs de pissenlit diabolique. J\\\'en ai besoin pour masquer les odeurs de pain rassis.');
INSERT INTO `npc_questions` VALUES (295, '', '', '', '', 'Bonjour, je m\\\'appelle Allen Dechakal, je suis l\\\'apprenti de Kwaker Vans et le fianc? d\\\'Edrige Valling. Le probl?me c\\\'est qu\\\'elle ne supporte plus mon haleine depuis que je teste les Pains au curry sans curry. ? chaque fois que je veux lui parler, je dois avaler de la Gel?e Menthe, mais j\\\'ai de plus en plus de mal ? en trouver. Aidez-moi s\\\'il vous pla?t. ');
INSERT INTO `npc_questions` VALUES (296, '', '', '', '', 'Je n\\\'ai que la Farine Blanche ? vous proposer. Edrige s\\\'en sert comme fond de teint, mais on peut en faire de tr?s bons pains. Une unit? de Farine Blanche contre une Gel?e Menthe, c\\\'est honn?te, non? \\n');
INSERT INTO `npc_questions` VALUES (297, '', '', '', '', 'Bonjour. Je me nomme Bellus, Sel Bellus. Je suis le gardien de cette grotte. Je ne laisse passer que les guerriers exp?riment?s, susceptibles de tenir plus de 20 secondes face ? la terrible cr?ature qui hante ces lieux. De plus, je vous demanderai de me ramener quatre Poils de Sanglier ainsi que deux de leurs D?fenses. Mon fils m\\\'a demand? de lui fabriquer un masque et ce travail me retient ici.');
INSERT INTO `npc_questions` VALUES (298, '', '', '', '', 'Merci beaucoup. ? pr?sent regardez-moi dans les yeux, je saurais voir si vous avez ne serait-ce que l\\\'ombre d\\\'une chance de battre le terrible Mulou. Si oui, je vous laisserai passer.');
INSERT INTO `npc_questions` VALUES (299, '', '', '', '', 'Je vous ai demand? quatre Poils de Sanglier et deux D?fenses. Vous trouvez qu\\\'il s\\\'agit d\\\'un abus de pouvoir de ma part ? Effectivement, c\\\'en est un.');
INSERT INTO `npc_questions` VALUES (300, '242;237', '', '', '', 'Victime...');
INSERT INTO `npc_questions` VALUES (301, '', '', '', '', 'D?sol?, mais j\\\'ai pour mission d\\\'emp?cher les jeunes inconscients dans votre genre d\\\'aller se faire ?ventrer en deux temps trois mouvements. Revenez lorsque vous vous serez entra?n?. Je vous rends vos objets.');
INSERT INTO `npc_questions` VALUES (302, '244;238', '', '', '', 'Ne tombe plus dans la d?prime...');
INSERT INTO `npc_questions` VALUES (303, '248;245', '', '', '', 'Vengeur...');
INSERT INTO `npc_questions` VALUES (304, '240;246', '', '', '', 'A l\\\'instant critique quand tout le monde craque...');
INSERT INTO `npc_questions` VALUES (305, '247;249', '', '', '', 'Kat... Kat... Kat...?kit');
INSERT INTO `npc_questions` VALUES (306, '', '', '', '', 'Salut ? toi, je vois que tu connais l\\\'hymne des Kat?kit, les rangers du risque. Quand tu es d?vor? par la panique, crie \\\" Os court \\\" et je rapplique. Je tire ma force du Nutelli, et pour faire du Nutelli il faut des noisettes et beaucoup d\\\'amour. Je suis preneur des deux. J\\\'?change 5 noisettes contre un F?mur de Chafer Archer.');
INSERT INTO `npc_questions` VALUES (307, '', '', '', '', 'Non ! C\\\'est pas ?a !');
INSERT INTO `npc_questions` VALUES (308, '', '', '', '', 'Salutations ! Je me pr?sente : Lara Soft. Je suis une ancienne arch?ologue ? la retraite. En fait, je me suis rendue compte que le commerce de peaux et la confection de manteaux en peau rapportaient plus. Toutes les grandes dames d\\\'Amakna en portent. Je suis devenue la fournisseuse officielle de manteaux en peau pour toutes les grandes soir?es mondaines d\\\'Amakna, et mes blousons se vendent comme des petits pains.');
INSERT INTO `npc_questions` VALUES (309, '', '', '', '', 'Depuis que j\\\'ai gagn? la confiance de mes consommatrices, j\\\'arrive ? leur faire croire n\\\'importe quoi. Tenez, en ce moment je leur vends des manteaux en peau et poils de souris, en leur affirmant que c\\\'est tendance. Et bien, j\\\'ai tellement de commandes que je ne sais pas si j\\\'aurai assez de poils pour satisfaire toutes mes clientes...');
INSERT INTO `npc_questions` VALUES (310, '', '', '', '', 'Oh oui ! Si vous pouvez me ramener des poils de souris, alors je vous les ?changerai contre mon stock de cuir de bouftou. Il m\\\'en reste de la saison derni?re, et je ne sais vraiment pas quoi en faire.');
INSERT INTO `npc_questions` VALUES (311, '', '', '', '', 'Salut, Frankie ? ton service. Je suis trouveuse de potions g?niales. Contrairement ? ceux qui cherchent, moi je trouve. Je suis ? l\\\'origine de la c?l?bre potion Ghetto Raide. Tu la connais s?rement pour son incroyable efficacit');
INSERT INTO `npc_questions` VALUES (312, '', '', '', '', 'C\\\'est vrai, tu as raison, cette potion n\\\'est pas plus efficace qu\\\'un pain classique ! Je suis nulle, je ne trouve plus rien de bien !');
INSERT INTO `npc_questions` VALUES (313, '', '', '', '', 'Ce n\\\'est pas la peine de se voiler la face, la potion Ghetto raide est un ?chec retentissant. Je dois me reprendre, sinon c\\\'est la faillite.');
INSERT INTO `npc_questions` VALUES (314, '', '', '', '', 'Ma derni?re  trouvaille... c\\\'est une potion encore plus puissante que la Ghetto Raide ! Un jour, mon g?nie sera reconnu, j\\\'en suis s?re.');
INSERT INTO `npc_questions` VALUES (315, '', '', '', '', 'Au lieu de te moquer, trouve-moi plut?t une dizaine d\\\'Ailes de Moskito. Je dois absolument trouver un truc g?nial et il me faut des Ailes de Moskito, ?a m\\\'aide ? r?fl?chir. Tu ne le m?rites sans doute pas, mais je saurais te r?compenser.');
INSERT INTO `npc_questions` VALUES (316, '', '', '', '', 'C\\\'est gentil de ta part, mais je dois m\\\'en sortir seule. Si tu pouvais juste me trouver une dizaine d\\\'Ailes de Moskito. Ca m\\\'aide ? r?fl?chir. Bien s?r, je saurais te r?compenser en ?change.');
INSERT INTO `npc_questions` VALUES (318, '259;329', '[bankCost]', '', '0', 'Bonjour, nous sommes les banquiers. Vous pouvez ouvrir un compte dans notre banque et vous aurez un coffre ? disposition pour d?poser vos biens. Mais attention, chaque consultation de votre compte vous co?tera #1 Kamas.');
INSERT INTO `npc_questions` VALUES (325, '', '', '', '', 'Notre Clan est secret, nous sommes les ?tres les plus vils, les plus cruels et les plus redout?s de toute la province d\\\'Amakna. Nous sommes parfois employ?s en tant que mercenaires par d\\\'importantes personnalit?s, qui ne d?sirent pas se charger de certaines t?ches peu reluisantes...');
INSERT INTO `npc_questions` VALUES (326, '292;366', '', '', '', 'Personne n\\\'a p?n?tr? le trou, ma mission se poursuit. Tiens, mais qui ?tes-vous ?! Vous n\\\'?tes pas Hanniboul... Laissez-moi tranquille, je suis en mission tr?s sp?ciale. \\nSinon aucun rapport, mais j\\\'ai un stock de parchemins ? changer.');
INSERT INTO `npc_questions` VALUES (327, '', '', '', '', 'Parmi ceux qui iront, certains n\\\'en reviendront pas. Et m?me ceux qui en reviendront, ils n\\\'en reviendront pas. Et si vous en revenez tous, alors c\\\'est moi qui n\\\'en reviendrai pas.');
INSERT INTO `npc_questions` VALUES (328, '', '', '', '', 'D?sol?, mon jeune ami, mais il me semble qu\\\'un nourrisson ait plus d\\\'ardeur que vous n\\\'en ayez actuellement. Je ne voudrais pas qu\\\'il vous arrive malheur. Entra?nez-vous et je vous laisserai passer.');
INSERT INTO `npc_questions` VALUES (329, '', '', '', '', 'Vous ?tes obstin?. Je vois, je vois... Oh, et si... non... mais si ! mais non... Quoique si en fait. Ramenez moi de quoi me d?fendre contre l\\\'inf?me cr?ature qui hante cette grotte ?trangement humide, et je vous laisserai p?n?trer le trou. J\\\'aurai donc besoin de testicules de Mulou, de sporme de Champ Champ et d\\\'un slip en cuir du Capitaine Chafer. Je pense qu\\\'avec ?a, je pourrai repousser ses ardeurs.');
INSERT INTO `npc_questions` VALUES (330, '', '', '', '', 'Oh magnifique ! Avec ?a, je n\\\'aurai plus jamais froid aux fesses ! Merci ! Quel magnifique cadeau ! Tr?s bien, vous pouvez vous aventurer dans l\\\'intimit? de ce trou.');
INSERT INTO `npc_questions` VALUES (331, '', '', '', '', 'Vous n\\\'avez pas tout ce que je vous ai demand? ! Ne tentez pas de m\\\'escroquer, o? j\\\'appelle mon ami Baracouilla afin qu\\\'il vous botte les fesses ! Au secouuuurs !');
INSERT INTO `npc_questions` VALUES (333, '', '', '', '', 'Je suis vwaiment ?touwdi, le couloiw menant ? la salle secwete est impwatiquable suite ? un ?boulement. \\nPlusieuws wobots sont en twain de d?blayew l\\\'acc?s. \\nA moins que vous pweniez ? dwoite dans le passage dewwi?we moi, vous awwivewez au quawtiew wabbit des fowces sp?ciales. Mais il wisquent de vous attaquew, ils sont un peu taw?s.');
INSERT INTO `npc_questions` VALUES (334, '271', '', '', '0', 'C\\\'est certainement le plus beau m?tier du monde, apr?s celui de Gardien de phare de l\\\'?le de Moon, Percepteur, P?tissier Magicien, Dompteur de Greu, et Empailleur de Bwork Mages. Il faut juste savoir accepter les al?as climatiques et faire fi des politiques de restrictions qui nous forcent ? mettre nos champs en jach?re. \\nC\\\'est un m?tier difficile, mais id?al pour ceux qui aiment ?tre en phase avec la nature, et je me ferai un plaisir de transmettre mon savoir ? quiconque le d?sire.');
INSERT INTO `npc_questions` VALUES (335, '', '', '', '0', 'Voil?, vous disposez maintenant des bases n?cessaires pour exercer ce m?tier, mais n\\\'oubliez pas qu\\\'il vous faut l\\\'outil ad?quat pour exercer votre m?tier. Regardez les outils que je vends.');
INSERT INTO `npc_questions` VALUES (336, '', '', '', '', 'D?sol?, je ne peux pas vous apprendre ce m?tier, vous n\\\'?tes pas assez entra?n? dans votre autre m?tier. Vous ne pouvez pas apprendre de nouveau m?tier tant que vous ne ma?trisez pas suffisamment votre m?tier actuel. Revenez me voir lorsque vous aurez progress');
INSERT INTO `npc_questions` VALUES (337, '', '', '', '', 'J\\\'ai besoin d\\\'aide pour terminer ma moisson.');
INSERT INTO `npc_questions` VALUES (338, '', '', '', '', 'Vous n\\\'exercez pas le m?tier de Paysan, vous ne pouvez pas m\\\'aider, revenez lorsque vous serez  Paysan.');
INSERT INTO `npc_questions` VALUES (339, '', '', '', '', 'Il risque de pleuvoir, et j\\\'ai peur que les grains de bl? ne germent sur place. Allez me faucher 100 unit?s de Bl? et je vous donnerai une de mes meilleures Faux en ?change.');
INSERT INTO `npc_questions` VALUES (341, '350;351;352', '', '', '', 'Les sculpteurs travaillent diff?rentes essences de bois suivant leurs besoins, mais il leur faut parfois d\\\'autres ?l?ments rares comme des pierres pr?cieuses ou des m?taux rares. \\nPlus vous progressez dans votre m?tier de Sculpteur, plus vous pouvez sculpter des objets puissants. \\nJe peux vous apprendre des m?tiers de sculpture, mais attention, l\\\'apprentissage d\\\'un m?tier est tr?s long, et il faudra pour progresser, vous exercer de nombreuses fois. ');
INSERT INTO `npc_questions` VALUES (342, '', '', '', '', 'D\\\'accord, voil? une potion contre la myxomawose, inutile de revenir je n\\\'en fais qu\\\'une par personne car ses effets sont ? vie...');
INSERT INTO `npc_questions` VALUES (344, '280', '', '', '0', 'On ne peut devenir B?cheron sans passion, couper des arbres ? longueur de journ?e demande une volont? cons?quente. Certains arbres sont plus simples ? couper que d\\\'autres, et il vous faudra de l\\\'exp?rience en b?cheronnage pour esp?rer pouvoir couper les plus gros arbres. Il vous faut imp?rativement une hache pour couper un arbre, je peux vous en vendre une s\\\'il le faut.  \\nJe peux ?galement vous apprendre les bases du m?tier de B?cheron.');
INSERT INTO `npc_questions` VALUES (345, '', '', '', '', 'Hello, J\\\'ai trouv? un parchemin dans le grenier de ma grand-m?re...Je ne sais pas du tout ? quoi il sert, mais je me doute qu\\\'il servira bien ? quelqu\\\'un de plus malin. Je l\\\'?change contre 120 sourcils de Moskito, dont je fais collection. Ca au moins, c\\\'est utile.');
INSERT INTO `npc_questions` VALUES (346, '287;369;286;288', '', '', '', 'J\\\'ai diff?rents travaux ? vous proposer : l\\\'extermination des Moskitos, la collecte de bois d\\\'Abraknyde,  la cr?ation d\\\'un B?ton en Racine d\\\'Abraknyde et l\\\'extermination de l\\\'Abraknyde Ancestral.\\n');
INSERT INTO `npc_questions` VALUES (347, '284', '', '', '', 'Pour devenir Bijoutier, il faut avant tout aimer les bijoux, aimer les pierres pr?cieuses et les m?taux rares. Ce m?tier demande ?norm?ment de minutie et beaucoup d\\\'imagination. Je peux vous enseigner ce m?tier si vous le d?sirez, mais il vous faudra tout de m?me m\\\'acheter l\\\'outil n?cessaire pour pouvoir l\\\'exercer. \\nLes Bijoutiers utilisent comme outil, un Sertisseur.');
INSERT INTO `npc_questions` VALUES (348, '361', '', '', '', 'J\\\'ai besoin d\\\'une amulette confectionn?e enti?rement en bois pour compl?ter ma collection, si mes souvenirs sont bons, Agrid le B?cheron en porte une autour du cou, il accepterait peut-?tre de vous l\\\'?changer contre un peu d\\\'aide. \\nSi vous ramenez cette amulette, je vous donnerai un parchemin qui pourrait vous ?tre utile, en ?change. \\n \\nSi vous aimez l\\\'aventure, je vous recommande d\\\'aller voir l\\\'?leveur de Dragoeuf, pr?s du village abandonn?, il propose une belle r?compense pour les Bijoutiers.');
INSERT INTO `npc_questions` VALUES (349, '', '', '', '', 'Je hais les Moskitos, ces petits monstres insupportables, qui m\\\'agressent sans raison lorsque je vais couper du bois. \\nSi vous me ramenez 10 ailes de Moskitos, je vous donnerai une Hache du B?cheron. \\nSi vous m\\\'en ramenez 100 d\\\'un seul coup, je vous donnerai mon Amulette du B?cheron. \\n \\nVous trouverez des Moskitos un peu partout, surtout pr?s des arbres coupables aux alentours du lac.');
INSERT INTO `npc_questions` VALUES (350, '', '', '', '', 'J\\\'ai besoin de refaire le manche de ma hache, pour qu\\\'il amortisse correctement les vibrations, il me faut du Bois d\\\'Abraknyde. Vous en trouverez en tuant des Abraknydes, qui sommeillent pr?s des arbres coupables. Je sais qu\\\'il en reste quelques-uns entre la ferme de Farle et Shika Ingalsse et le lac d\\\'Amakna. \\n \\nRamenez-moi 10 Racines d\\\'Abraknydes et 10 ?corces d\\\'Abraknydes, et je vous donnerai une bonne hache en ?change.');
INSERT INTO `npc_questions` VALUES (351, '289', '', '', '', 'J\\\'ai besoin rapidement d\\\'un B?ton en Racine d\\\'Abraknyde pour l\\\'offrir ? mon ami Farle Ingalsse qui s\\\'en servira pour garder ses troupeaux de Bouftous. Si vous pouviez faire appel ? un bon Sculpteur de B?tons, pour qu\\\'il vous en fasse un et que vous me le ramenez, je vous donnerai une ressource tr?s rare : la S?ve d\\\'Abraknyde Retravaill?e.');
INSERT INTO `npc_questions` VALUES (352, '', '', '', '', 'Cette s?ve est presque magique, correctement utilis?e, elle permet de redonner vie ? un B?ton en Racine d\\\'Abraknyde, pour le rendre extr?mement puissant. Renseignez-vous aupr?s d\\\'un Sculpteur de B?tons de tr?s haut niveau, il pourra s?rement vous fabriquer un tel b?ton si vous lui ramenez cette s?ve... \\nFaites attention, cette s?ve retravaill?e est ? utiliser avec pr?caution, elle a  ?t? retravaill?e par un Alchimiste de renom, Adam Haihaive. Il s\\\'est m?me transform? en Abraknyde pendant quelques heures en ingurgitant un peu de cette s?ve.');
INSERT INTO `npc_questions` VALUES (353, '', '', '', '', 'Bouldiou de bouldiou, j\\\'suis ben crevaille...Min bien el plu pr?chieux ? dichparu, minche alors.');
INSERT INTO `npc_questions` VALUES (354, '', '', '', '', 'Bonjour mon ami. J\\\'ai sur moi les meilleurs parchemins d\\\'Amakna. \\n \\nProuvez-moi que vous avez tu? 100 larves bleues en me rapportant leurs peaux et je vous donnerai un petit parchemin de force. \\nMieux encore ! Pour 5 diamants, je vous donnerai un petit parchemin de sort. \\nVous savez ce qu\\\'il vous reste ? faire !');
INSERT INTO `npc_questions` VALUES (355, '', '', '', '', 'C\\\'est dans les environs, j\\\'en suis s?r ! Je la retrouverai bien, cette satan?e entr?e de mine... C\\\'est pas loin, je le sens.');
INSERT INTO `npc_questions` VALUES (356, '', '', '', '', 'Ce sont des parchemins d\\\'agilit?, que ma grande m?re m\\\'a laiss?s en h?ritage. Paix ? son ?me. Je les ?change contre 70 glands. J\\\'adore les glands. Je me demande bien pourquoi...');
INSERT INTO `npc_questions` VALUES (357, '294;293', '', '', '', 'Bonjour ! Je me nomme Lee Aibig. Je suis un vieux paysan, et j\\\'ai quelques soucis li?s ? mon ?ge : je perds mes dents. Je ne peux plus rien m?cher et je ne me nourris plus que de soupe. J\\\'adore tout particuli?rement la soupe aux glands. Ramenez-moi les ingr?dients dont j\\\'ai besoin, je vous donnerai des parchemins d\\\'agilit? en ?change. Je n\\\'en ai plus l\\\'utilit?, ils sont devenus inefficaces ? cause mon arthrose...');
INSERT INTO `npc_questions` VALUES (358, '', '', '', '', 'Dans une marmite, faites revenir 80 Glands, 80 Langues de Pissenlit Diabolique, 80 P?tales de Rose, et agr?mentez le tout d\\\'une vingtaine de doses de Sporme de Champ Champ. Vous obtiendrez une d?licieuse soupe velout?e.  \\nJe m\\\'en l?che les babines d\\\'avance.');
INSERT INTO `npc_questions` VALUES (359, '', '', '', '', 'Faites bouillir dans une marmite 75 Glands, 75 Langues de Pissenlit Diabolique et 70 P?tales de Rose, et vous obtiendrez une d?licieuse soupe aux glands !  \\nMiam, c\\\'est si bon !');
INSERT INTO `npc_questions` VALUES (360, '300', '', '', '', 'Salut, je m\\\'appelle Lou, Lou Pachoups et j\\\'adore les sucettes. J\\\'ai appris ? en faire, mais je n\\\'ai plus assez d\\\'ingr?dients.');
INSERT INTO `npc_questions` VALUES (361, '', '', '', '', 'Pour faire un lot de sucettes, il me faut 60 unit?s de Gel?e Bleut?e, 30 unit?s de Gel?e Fraise, 25 unit?s de Gel?e Menthe, 1 unit? de Gel?e Bleut?e Royale et 1 unit? Gel?e Fraise Royale. Si tu me trouves tout ?a, je te donnerai un truc cool.');
INSERT INTO `npc_questions` VALUES (362, '296', '', '', '', 'Bonjour. Mon nom est Ronsha Nesto. Je suis veuve. En fait, je suis m?me quatre fois veuve. Tous mes maris ont ?t? retrouv?s morts, un Pic de Prespic plant? dans le coeur. Les autorit?s n\\\'ont jamais r?ussi ? retrouver le Prespic ? l\\\'origine de ces horreurs.');
INSERT INTO `npc_questions` VALUES (363, '', '', '', '', 'Je pr?pare mon cinqui?me mariage. J\\\'ai de la chance, mon prochain mari est tr?s attentionn?, et tr?s... riche. Par contre, je suis ? court de Pic de Prespic. Apporte-moi en 80 et je t\\\'offrirai un Petit Parchemin de Force en ?change.');
INSERT INTO `npc_questions` VALUES (364, '297', '', '', '0', 'Bonjour, je suis Ness Laye et le bonheur m\\\'appartient. Je suis la seule ? pouvoir r?ussir la recette de bonheur en flocons.');
INSERT INTO `npc_questions` VALUES (365, '', '', '', '', 'C\\\'est un secret de famille, tout ce que je peux te dire c\\\'est qu\\\'il me manque encore quelques ingr?dients. Trouve-les-moi et je te donnerai un parchemin magique. Il me faudrait 60 unit?s de Gel?e Bleut?e, 25 unit?s de Gel?e Fraise et 20 unit?s de Gel?e Menthe.');
INSERT INTO `npc_questions` VALUES (366, '', '', '', '', 'Ah, je vois que vous avez de l\\\'audace, si vous gagnez vous remporterez la totalit? de la cagnotte ! \\nSinon la moiti? de cette somme sera ajout?e au gros lot...');
INSERT INTO `npc_questions` VALUES (367, '301;300', '', '', '', 'Salut ! Je m\\\'appelle Quincy Pra?ze. Je fabrique des oeufs-surprises avec mon p?re, Quin Pra?ze. On a besoin d\\\'ingr?dients, donc si tu veux bien nous aider tu pourras avoir une belle r?compense.');
INSERT INTO `npc_questions` VALUES (368, '', '', '', '', 'Il nous faudrait 80 unit?s de Gel?e Bleut?e et 30 unit?s de Gel?e Menthe.');
INSERT INTO `npc_questions` VALUES (369, '', '', '', '', 'En ?change des ingr?dients, je peux te donner un parchemin magique.');
INSERT INTO `npc_questions` VALUES (370, '303;302', '', '', '', 'Bonjour ! Je suis Otho Laringo, le forgeron. Je recherche un assistant pour m\\\'aider dans la fabrication de mes armes. Tous ceux que j\\\'ai eus se sont enfuis apr?s une demi-journ?e de travail... Tsss, tous des froussards ! J\\\'ai besoin des ressources n?cessaires ? la fabrication de mes armes. Je vous paierai, bien s?r.');
INSERT INTO `npc_questions` VALUES (371, '', '', '', '', 'Tr?s bien. Alors ramenez-moi 70 Pics de Prespic, et 70 Pinces de Crabe. Je m\\\'en sers pour forger de solides boucliers orn?s de pics. R?sistants, effrayants, et tr?s chers. Que puis-je esp?rer de mieux ? \\nHa oui, votre r?compense... Je vous donnerai un Parchemin de Force si vous me ramenez tout ce que je vous ai demand');
INSERT INTO `npc_questions` VALUES (372, '304', '', '', '', 'Un courageux, enfin ! Alors ramenez moi 75 Pics de Prespic, 75 Pinces de Crabe, 45 C?tes de Rib et 30 Silex. J\\\'en ferai de solides boucliers, aux bords tranchants comme des lames de rasoir. Parfaits pour se d?fendre, efficaces en attaque, faciles ? vendre ? prix ?lev?. Le r?ve ! \\nJe vous donnerai un Puissant Parchemin de Force en ?change.');
INSERT INTO `npc_questions` VALUES (373, '305', '', '', '0', 'Salut, moi c\\\'est Ariz. Je me fais des bonbons ? base de gomme. Et pour faire de la gomme, il faut beaucoup de gel?e.');
INSERT INTO `npc_questions` VALUES (374, '', '', '', '', 'L\\\'utilit? des c?tes de Rib ? Aucune pour la fabrication de boucliers, c\\\'est juste pour avoir de quoi manger pendant mes pauses.');
INSERT INTO `npc_questions` VALUES (375, '', '', '', '', 'Il me faut surtout de la Gel?e Bleut?e, comme elle n\\\'a pas vraiment de go?t, on peut mettre n\\\'importe quel parfum. Mais comme il m\\\'en faut beaucoup, je la prends uniquement par lot de 100 unit?s.');
INSERT INTO `npc_questions` VALUES (376, '306', '', '', '', 'Bonjour. Je me nomme T?ha Chicks. Je fais partie des adorateurs du Grand Gourou. Alors que j\\\'?tais ?gar?e, cet homme a su me montrer la voie. Depuis je crois en lui, surtout lorsque je viens de manger un beignet aux Champignons... C\\\'est Skippy qui m\\\'a donn? la recette.');
INSERT INTO `npc_questions` VALUES (377, '', '', '', '', 'Oh, rien de bien compliqu?. Un peu de p?te ? beignet fourr?e de champignons. C\\\'est d?licieux, et tout le monde est gentil avec vous lorsque vous en mangez. Tenez, ne pourriez vous pas me ramener une centaine de ces d?licieux champignons ? Je vous donnerai un Petit Parchemin de Sagesse en ?change. Je n\\\'en ai plus besoin depuis que je mange ces beignets.');
INSERT INTO `npc_questions` VALUES (378, '', '', '', '', 'Yeah maaan ! Balance man ! Cadence Man ! Glisse sur les bl?s ! C\\\'est le Bob Man ! Depuis que Skippy, notre Gourou, m\\\'a donn? la recette de ces beignets aux Champignons et aux Graines de Tournesol, je me sens en accord avec les dieux. C\\\'est fantastique ! D\\\'ailleurs, je suis ? cours de ressources pour m\\\'en faire. Ram?ne-moi 80 Champignons et 60 Graines de Tournesol, et je t\\\'offrirai un Parchemin de Sagesse en ?change.');
INSERT INTO `npc_questions` VALUES (379, '', '', '', '', 'Bonjour. J\\\'ai besoin d\\\'aide pour r?unir les ingr?dients n?cessaires ? la confection du plus grand beignet aux champignons et aux graines jamais r?alis? ! \\nC\\\'est pour la prochaine c?l?bration en l\\\'honneur de Skippy le grand Gourou. Si vous me ramenez 90 Champignons, 70 Graines de Tournesol et 40 Graines de Chanvre, je vous donnerai un Grand Parchemin de Sagesse en ?change.');
INSERT INTO `npc_questions` VALUES (382, '308', '', '', '', 'Salut, je suis le grand Bolzano Vieilletrasse, je suppose que tu as entendu parler de moi. Je fabrique toutes sortes de choses inutiles et bizarres avec des morceaux d\\\'animaux et de plantes. Je travaille actuellement sur un grand projet, mais il me manque de la mati?re pour donner libre cours ? ma cr?ativit');
INSERT INTO `npc_questions` VALUES (383, '', '', '', '', 'Il me faudrait plusieurs choses, j\\\'ai m?me fait une liste. Voyons voir... \\n60 Pattes d\\\'Arakne, 55 Tr?fles ? Cinq Feuilles, 40 Ongles de Chevaucheurs de Karne et 15 Queues de Mulou. \\nJe n\\\'ai pas envie de me fatiguer, alors je prends tout en un seul lot contre un parchemin magique.');
INSERT INTO `npc_questions` VALUES (384, '309', '', '', '', 'Bonjour. Je me nomme He?l Leise, et voici mon fils adoptif Max. Je r?ve d\\\'aventure et j\\\'ai voulu partir pour une longue odyss?e, mais mon Max m\\\'a retenu lorsque j\\\'ai essay? de me mettre en route. \\\"P?re ! He?l Leise ! Reviens !\\\" Criait-il. \\nTel est Max. Ca m\\\'a fendu le coeur, alors je suis rest?. \\nJe n\\\'ai donc plus besoin de mes Grands Parchemins de Force. \\nJe les ?change ? qui en veut.');
INSERT INTO `npc_questions` VALUES (385, '', '', '', '', 'J\\\'offre un Grand Parchemin de Force ? celui qui sera capable de me ramener 70 pics de Prespic, 75 pinces de Crabe et 40 c?tes de Rib. Avec autant de troph?es, je pourrai ais?ment faire croire ? P?n?loppe - la femme dont je suis ?pris - que j\\\'ai v?cu de formidables aventures et esp?rer la s?duire ainsi.');
INSERT INTO `npc_questions` VALUES (386, '310', '[name]', '', '0', 'Bonjour #1, je suis l\\\'assistant d\\\'Otoma?. C\\\'est l\\\'un des rares enchanteurs d\\\'Amakna. \\nJe l\\\'aide ? cr?er des enchantements d\\\'arme, mais aussi des potions ou des parchemins magiques. \\nQue puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (387, '', '', '', '', 'Ma devise est la suivante \\\"Ne donne ? autrui que ce qu\\\'il poss?de d?j?\\\". \\nSi tu souhaites que je te fabrique un parchemin, ram?ne-moi les ingr?dients ainsi que la recette...');
INSERT INTO `npc_questions` VALUES (388, '', '', '', '', 'Bon alors, il me faudrait 75 Pattes d\\\'Arakne, 60 Tr?fles ? Cinq Feuilles et 40 Ongles de Chevaucheurs de Karne.');
INSERT INTO `npc_questions` VALUES (389, '', '', '', '', 'Bonjour. J\\\'adore le Nutelli que pr?pare Karim Kat?kit. Mais mon p?re dit que c\\\'est trop cher... Du coup, j\\\'ai essay? de l\\\'imiter. Si on m?lange 70 glands avec 70 langues de Pissenlit Diabolique, on obtient une p?te qui se rapproche de celle de M. Kat?kit. Ramenez-moi de quoi en faire, et je vous offrirai un Parchemin d\\\'Agilit');
INSERT INTO `npc_questions` VALUES (390, '314', '', '', '', 'Bonjour, je suis Koussein Trengon, mais je ne suis pas Duc du Koussein. Enfin, pas encore. Je me laisse constamment porter par ma bonne ?toile. Elle m\\\'apporte tout ce dont j\\\'ai besoin. Par exemple, je parie que vous allez bient?t m\\\'apporter les ingr?dients qu\\\'il me manque pour pr?parer une potion.');
INSERT INTO `npc_questions` VALUES (391, '', '', '', '', 'Ce n\\\'est pas du jeu si vous connaissez ce dont j\\\'ai besoin. Il faudra le trouver vous-m?me. D\\\'ailleurs, je n\\\'ai pas la liste sur moi.');
INSERT INTO `npc_questions` VALUES (393, '', '', '', '', 'Vous avez de la chance, on dirait que je l\\\'ai sous la main. Il me manque 90 Pattes d\\\'Arakne et 65 Tr?fles ? Cinq Feuilles.');
INSERT INTO `npc_questions` VALUES (394, '315', '', '', '', 'Bonjour, je suis Ali Akelle, peintre illustrateur. Comme mes illustrations sont en noir et blanc, j\\\'utilise des Pattes d\\\'Arakne r?duites en poudre pour faire ma peinture. D\\\'ailleurs, j\\\'en cherche, j\\\'ai une commande urgente.');
INSERT INTO `npc_questions` VALUES (395, '', '', '', '', 'Comme je dois faire un grand format qui sera ensuite r?duit par proc?d? magique, il me faut 80 Pattes d\\\'Arakne.');
INSERT INTO `npc_questions` VALUES (396, '316', '', '', '', 'Bonjour ? vous, je m\\\'appelle Ozen et je suis sage. Je suis un grand sp?cialiste de la relaxation par les plantes. Je suis actuellement ? la recherche de divers ingr?dients pour la pr?paration du relaxant ultime.');
INSERT INTO `npc_questions` VALUES (397, '', '', '', '', 'C\\\'est gentil ? vous. En fait, il me faudrait 60 Peaux de Larve Bleue, 50 Peaux de Larve Orange, 50 Peaux de Larve Verte, 40 Ailes de Tofu Mal?fique et 30 unit?s de Sang de Vampire. \\nSi vous pouvez me ramener tout ?a, je vous donnerai un parchemin tr?s puissant.');
INSERT INTO `npc_questions` VALUES (398, '317', '', '', '0', 'Bonjour, je suis Eow?ne Fiole. Je suis la grande sp?cialiste des potions. C\\\'est votre jour de chance, j\\\'ai besoin d\\\'ingr?dients. Aidez-moi ? en trouver et vous serez r?compens');
INSERT INTO `npc_questions` VALUES (399, '', '', '', '', 'Je cherche ? mettre au point une nouvelle potion, je l\\\'appellerai la Polie Nectar. Pour cela, il me faut 50 Peaux de Larve Bleue, 40 Peaux de Larve Orange, 40 Peaux de Larve Verte.');
INSERT INTO `npc_questions` VALUES (400, '318', '', '', '', 'Hello, restons simples, appelle-moi l\\\'?talon. Hier j\\\'ai mang? du jambon de Dragon Cochon. On m\\\'en avait vant? certaines vertus, mais cela s\\\'est av?r? ?tre une bien mauvaise id?e, les effets r?sultants n\\\'?taient pas ceux que j\\\'esp?rais... Bref, j\\\'aurai besoin de quelques ingr?dients pour me soigner.');
INSERT INTO `npc_questions` VALUES (401, '', '', '', '', 'Il me faut 45 Peaux de Larve Bleue, 45 Peaux de Larve Orange, 45 Peaux de Larve Verte et 30 Ailes de Tofu Mal?fique. ');
INSERT INTO `npc_questions` VALUES (402, '320;319', '', '', '0', 'Chut. Silence. C\\\'est une biblioth?que ici. Si vous avez besoin d\\\'un livre, venez me demander. Mais pas un mot ! Shhhht ! Pas un mot j\\\'ai dit. Allez vous asseoir en silence ? pr?sent. \\nEt que je ne vous entende plus. \\nPas m?me un chuchotement.');
INSERT INTO `npc_questions` VALUES (403, '607', '', '', '0', 'Shhht !');
INSERT INTO `npc_questions` VALUES (404, '', '', '', '', 'Le m?tier de Mineur est un m?tier difficile, il faut aimer l\\\'obscurit?, et ne pas avoir peur d\\\'affronter un Craqueleur avec une pioche. \\nCe m?tier est cependant assez gratifiant, vous pouvez, sans trop de difficult?s, devenir riche ? condition de travailler dans les meilleures mines. \\nL\\\'outil par excellence du mineur est la pioche, prenez soin de la v?tre et ne la laissez pas rouiller.');
INSERT INTO `npc_questions` VALUES (405, '', '', '', '', 'Des mines, il y en a presque partout sur les flancs de la montagne, mais certaines sont presque vides, ou alors infest?es de monstres peu recommandables. \\nLongez la montagne, et vous finirez bien par trouver les entr?es qui m?nent vers les diff?rentes mines de la Province d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (406, '', '', '', '', 'Sans sa pioche, un mineur n\\\'est rien, mais rappelez-vous, la pioche ne fait pas le mineur. \\nEn r?gle g?n?rale, les meilleures pioches permettent avant tout de mieux se d?fendre face aux monstres qui peuplent les mines, ou face aux r?deurs qui s\\\'attaquent aux mineurs. \\nSi vous cherchez une pioche, nous pouvons nous arranger, j\\\'ai un petit travail ? vous demander en ?change d\\\'une pioche.');
INSERT INTO `npc_questions` VALUES (407, '', '', '', '', 'J\\\'ai besoin de Bois de Fr?ne pour consolider ma mine et ?viter qu\\\'elle ne s\\\'effondre. \\nMais je suis un pi?tre B?cheron, la derni?re fois que j\\\'ai voulu couper un arbre, j\\\'ai march? sur la racine d\\\'un vieil Abraknyde, qui m\\\'a poursuivi et a fait le si?ge de ma mine pendant une dizaine de jours.  \\nSi vous me ramenez 10 unit?s de Bois de Fr?ne, je vous donnerai une pioche de mineur en ?change. \\nN\\\'h?sitez pas ? faire appel ? un B?cheron, si vous ne voulez pas perdre trop de temps.');
INSERT INTO `npc_questions` VALUES (408, '327;328', '', '', '', 'Le cordonnier travaille essentiellement le cuir, pour en faire des ceintures, mais ?galement des bottes. \\nIl arrive parfois que les cordonniers utilisent du bois ou des m?taux pr?cieux pour d?corer leurs cr?ations ou alors les renforcer. Le cordonnier utilise une dague appel?e \\\"Coupe Cuir\\\" comme outil pour travailler le cuir. \\nSi vous cherchez ce genre d\\\'outil, je peux vous en donner un en ?change d\\\'un peu d\\\'aide.');
INSERT INTO `npc_questions` VALUES (409, '', '', '', '', 'J\\\'ai besoin de faire un bon flan aux oeufs de Tofu, pour f?ter le retour de mon cousin, mais il me manque justement un Oeuf de tofu, si vous m\\\'en ramenez un, je vous donnerai un de mes Coupes Cuir en ?change.');
INSERT INTO `npc_questions` VALUES (410, '', '', '', '', 'Vous pouvez d?poser des kamas, mais ?galement des objets dans votre coffre. \\nVous n\\\'avez le droit qu\\\'? un seul coffre. \\nChaque acc?s ? votre coffre, m?me si vous ne fa?tes que le consulter, est payant. \\nLe prix ? payer pour consulter votre coffre d?pend du nombre d\\\'objets que vous y entreposez.');
INSERT INTO `npc_questions` VALUES (411, '334;1269;333', '', '', '0', 'Que puis-je faire pour vous aider ?');
INSERT INTO `npc_questions` VALUES (414, '', '', '', '', 'La meilleure fa?on d\\\'apprendre un m?tier, c\\\'est de demander ? une personne de vous l\\\'apprendre. \\nMalheureusement, tr?s peu de personnes sont assez exp?riment?es pour apprendre ? d\\\'autres leur m?tier. \\nAllez directement dans le B?timent rattach? au corps de m?tiers qui vous int?resse, par exemple, allez voir Kelog Korflex ? la boulangerie pour devenir boulanger, ou allez voir Abely Bobeule dans l\\\'atelier pour apprendre les m?tiers de sculpture.');
INSERT INTO `npc_questions` VALUES (415, '337;338;340', '', '', '0', 'La province d\\\'Amakna est paisible, mais parfois vous serez amen? ? combattre des monstres, ? vous d?fendre d\\\'agresseurs, ? ch?tier des agresseurs, ou ? d?fier d\\\'autres personnes.');
INSERT INTO `npc_questions` VALUES (417, '', '', '', '', 'Si le coeur d\\\'Amakna est paisible, ses alentours le sont parfois nettement moins. \\nLes cr?atures qui se prom?nent ? la p?riph?rie d\\\'Amakna ne sont pas agressives, il faut s\\\'en approcher de tr?s pr?s pour qu\\\'elles se mettent ? vous attaquer. \\nMais plus vous vous ?loignez du centre d\\\'Amakna, plus les cr?atures sont agressives, et elles peuvent vous attaquer sans raison apparente. \\nNe vous d?placez pas hors du village si vous n\\\'?tes pas accompagn? d\\\'autres aventuriers, vous pourriez faire de mauvaises rencontres.');
INSERT INTO `npc_questions` VALUES (418, '', '', '', '', 'Certains guerriers originaires d\\\'Amakna ont d?cid? de rejoindre les rangs de grande puissance comme Bonta ou Br?kmar. \\nAfin d\\\'?tendre leur id?ologie, ils attaquent parfois des habitants de la r?gion d\\\'Amakna, pour inciter les gens ? rejoindre leurs rangs. Tant que vous resterez en terre neutre, la garnison d\\\'Amakna vous viendra en aide, par contre en dehors de cette zone, ce sera ? vos risques et p?rils...');
INSERT INTO `npc_questions` VALUES (420, '', '', '', '', 'Si vous aimez combattre pour le plaisir, vous pouvez d?fier d\\\'autres personnes en leur proposant un d?fi. \\nLes d?fis sont tol?r?s m?me au sein du village, nous consid?rons cela comme un divertissement, ou un moyen de s\\\'entra?ner avant de partir chasser des cr?atures par exemple.');
INSERT INTO `npc_questions` VALUES (421, '343;384;342;345;344', '', '', '0', 'Il faut beaucoup de pratique pour devenir un bon Forgeron.  \\nIl faut ?galement savoir travailler les m?taux et les diff?rentes essences de bois pour forger les armes de base. \\nLes armes les plus puissantes n?cessitent souvent des pierres pr?cieuses ou des m?taux rares aux propri?t?s magiques.');
INSERT INTO `npc_questions` VALUES (422, '347', '', '', '0', 'Les ?p?es sont les armes favorites des Iop et des Ecaflip, elles n?cessitent en g?n?ral beaucoup de force pour ?tre utilis?es, mais font souvent d\\\'importants d?g?ts. \\nLes Forgeurs d\\\'?p?es utilisent comme outil, un Marteau de Forgeur d\\\'?p?es.');
INSERT INTO `npc_questions` VALUES (423, '346', '', '', '0', 'Les Sram sont les sp?cialistes des dagues. les dagues sont tr?s rapides, mais elles font en g?n?ral peu de d?g?ts. Leurs coups critiques sont en revanche impressionnants. \\nLes dagues n?cessitent souvent beaucoup d\\\'agilit? pour ?tre utilis?es, en effet, il faut pouvoir s\\\'approcher de son adversaire, le frapper et se sauver ensuite. \\nLes Forgeurs de Dagues utilisent comme outil, un Marteau de Forgeur de Dagues.');
INSERT INTO `npc_questions` VALUES (424, '348', '', '', '0', 'Les Enutrof sont les principaux amateurs de pelles, ils aiment pouvoir creuser le sol ? la recherche de tr?sors, et se d?fendre avec leur outil.  \\nLes pelles peuvent faire d\\\'importants d?g?ts, mais n?cessitent d\\\'avoir beaucoup de chance pour pouvoir ?tre utilis?es. \\nLes Forgeurs de Pelles utilisent comme outil, un Marteau de Forgeur de Pelles.');
INSERT INTO `npc_questions` VALUES (425, '349', '', '', '0', 'Les Osamodas et les X?lor appr?cient ?norm?ment les marteaux. Ces derniers n?cessitent en r?gle g?n?rale, un peu de force pour ?tre utilis?s, mais surtout de l\\\'intelligence. En effet, la majorit? des marteaux disposent de puissants effets magiques. \\nLes Forgeurs de Marteaux utilisent comme outil, un Marteau de Forgeur de Marteaux. ');
INSERT INTO `npc_questions` VALUES (426, '353', '', '', '', 'Les Eniripsas affectionnent particuli?rement les baguettes. Ces derni?res demandent souvent beaucoup d\\\'intelligence et un peu de sagesse pour pouvoir ?tre utilis?es. Les baguettes font rarement d\\\'importants dommages, mais conf?rent souvent d\\\'importants pouvoirs magiques ? leurs porteurs. \\nLes sculpteurs de Baguettes utilisent comme outil, une Tailladeuse de Baguettes. \\n');
INSERT INTO `npc_questions` VALUES (427, '354', '', '', '', 'Les Arcs sont les armes pr?f?r?es des Cr?s, qui aiment attaquer leurs ennemis ? distance. \\nLes arcs font rarement d\\\'importants d?g?ts, mais leurs coups critiques sont en g?n?ral surprenants. \\nIls n?cessitent une bonne agilit? et de la force pour pouvoir ?tre utilis?s. \\nLes Sculpteurs d\\\'arcs utilisent comme outil, une Tailladeuse d\\\'arcs.');
INSERT INTO `npc_questions` VALUES (428, '355', '', '', '', 'Les b?tons sont des armes peu efficaces en combat rapproch?, mais conf?rent d\\\'importants pouvoirs ? leur porteur. \\nLes Sadidas et les F?cas manient tr?s bien les B?tons. Ces derniers demandent en g?n?ral un peu de force et beaucoup d\\\'intelligence pour pouvoir ?tre utilis?s. \\nLes sculpteurs de b?tons utilisent comme outil, une Tailladeuse de B?tons.');
INSERT INTO `npc_questions` VALUES (429, '', '', '', '', 'Bonjour disciple, je suis un des six ma?tres roublards, et Vil Smisse est notre Ma?tre ? tous. \\nSi vous voulez progresser et avoir plus de responsabilit?s au sein du clan, il va falloir accomplir de nombreuses qu?tes et autres travaux pour nous prouver votre valeur.');
INSERT INTO `npc_questions` VALUES (430, '', '', '', '', 'J\\\'ai plusieurs missions ? proposer, mais pour certaines il me faut des hommes dignes de confiance qui ont prouv? leur d?vouement pour le clan des roublards. \\nIl est possible de se sp?cialiser dans plusieurs domaines comme le vol ou l\\\'assassinat, mais j\\\'ai aussi besoin de coursiers pour faire l\\\'interm?diaire entre les diff?rents ma?tres roublards de la r?gion.');
INSERT INTO `npc_questions` VALUES (432, '358', '', '', '0', 'Les Boulangers sont des personnes respectables qui cuisent du pain pour les autres. \\nNous autres Boulangers sommes respect?s, dans la mesure o? nous permettons aux aventuriers affaiblis de reprendre des forces en mangeant nos pains.  \\nPlus un Boulanger est exp?riment?, plus il cuit de bons pains, et plus les pains sont bons, plus ils restaurent la sant? des aventuriers affaiblis. \\nLes Boulangers utilisent un Rouleau P?trisseur pour faire leur p?te ? pain.');
INSERT INTO `npc_questions` VALUES (433, '359', '', '', '0', 'Bonjour aventurier, je suis un des seuls ?leveurs de Dragoeuf de cette contr?e, je les ?l?ve et les dresse depuis des lustres. Je suis la seule personne ? m?me de les comprendre et de les dompter. \\nMais j\\\'ai quelques soucis depuis quelques ann?es d?j?, peut-?tre pourriez-vous m\\\'aider ?');
INSERT INTO `npc_questions` VALUES (434, '360', '', '', '0', 'Mon grand-p?re vivait dans ce village lorsque l\\\'invasion de ces cr?atures s\\\'est produite. Il m\\\'a expliqu? qu\\\'un dragoeuf, si il est captur? peu apr?s sa naissance, est inoffensif. Mais avec l\\\'?ge, il m\\\'est impossible d\\\'approcher d\\\'assez pr?s les dragoeufs pour voler des oeufs. \\nSi vous pensez en ?tre capable, il me faut des Oeufs de Dragoeufs Blancs, et le seul moyen d\\\'en obtenir, c\\\'est de les combattre.');
INSERT INTO `npc_questions` VALUES (435, '4840', '', '', '', 'Une fois que vous m\\\'aurez ramen? 10 Oeufs de Dragoeufs Blancs, je vous donnerai un Vieil Os de Dragoeuf en ?change. \\nCet os est magique, Azra Lazarus la Bijouti?re est persuad?e que l\\\'on pourrait l\\\'utiliser pour confectionner de pr?cieux bijoux. \\nAllez la voir, elle vous en parlera plus en d?tail.');
INSERT INTO `npc_questions` VALUES (436, '', '', '', '', 'Il attend depuis des ann?es pr?s du pont, pour pr?venir les ?ventuels aventuriers du danger qui les attend. \\nApr?s tout, il est responsable de ce d?sastre, qui nous a forc? ? nous exiler ici et ? reconstruire notre village. \\nSi vous arrivez ? l\\\'aider, il vous donnera de toute ?vidence son Vieil Os de Dragoeuf, c\\\'est un os magique. Correctement utilis? dans la confection d\\\'une amulette, il lui donnera d\\\'importants pouvoirs.');
INSERT INTO `npc_questions` VALUES (437, '', '', '', '', 'Mon stagiaire est mort dans le four ? pain, et je n\\\'ai plus personne pour m\\\'apporter du bois pour faire chauffer mon four. Si vous me ramenez une unit? de Bois de Fr?ne, je vous donnerai de la Levure de Boulanger en ?change. \\n \\nJ\\\'ai ?galement besoin de Graines de S?same pour mes prochains pains, si vous m\\\'en ramenez 5, je vous donnerai un p?trisseur en ?change. C\\\'est un outil indispensable si vous voulez exercer le m?tier de Boulanger.');
INSERT INTO `npc_questions` VALUES (438, '', '', '', '', 'Ah, vous connaissez Hanniboul Smisse ? C\\\'est notre chef, c\\\'est lui qui organise toutes les op?rations et qui fait le n?cessaire pour venir me sauver lorsque certains fous me prennent pour un fou et d?cident de m\\\'enfermer.  \\nMais je ne devrais pas vous parler de tout ?a.');
INSERT INTO `npc_questions` VALUES (441, '', '', '', '', 'Bonjour, je suis Hagal le gardien de cette banque, seules les personnes respectables qui ne sont pas hors-la-loi ont le droit d\\\'y rentrer.');
INSERT INTO `npc_questions` VALUES (442, '370', '', '', '', 'Cet Abraknyde est un des plus vieux de toute la province d\\\'Amakna, il a d?j? tu? beaucoup de mes amis b?cherons, mais il a surtout tu? ma famille lors d\\\'une nuit ? la belle ?toile en pleine for?t. \\nCe fut un v?ritable carnage sylvestre, je suis le seul ? avoir surv?cu... \\nJe veux me venger, mais je ne peux pas le faire moi-m?me, je vous demande de le faire pour moi, allez tuer ce monstre pour moi et je saurai vous r?compenser.');
INSERT INTO `npc_questions` VALUES (443, '371', '', '', '', 'Pour me venger de cette cr?ature monstrueuse, il me faudrait garder un souvenir imp?rissable d\\\'elle... \\nUne fois que vous l\\\'aurez tu?e, prenez-lui un Ambre ancestral et essayez de forger des Dagues Ancestrales avec cet ambre. \\n \\nRamenez-moi ensuite ces dagues  et je vous donnerai du Bois Ancestral en ?change, qui devrait vous permettre de confectionner une Amulette aux pouvoirs ?blouissants et peut-?tre m?me, de reforger la l?gendaire Fendeuse d\\\'Abraknyde Ancestral, une hache qui fera de son porteur, un des plus puissants guerriers d\\\'Amakna. \\nMais attention, vous devrez trouver un Forgeur de Dagues tr?s exp?riment? pour r?ussir ? forger les dagues que je recherche, et pour confectionner l\\\'amulette dont je vous parle ou pour forger cette fameuse hache, vous devrez faire appel ? des artisans d\\\'exception. \\nUne derni?re chose, ne sous-estimez pas la puissance de cet Abraknyde Ancestral...');
INSERT INTO `npc_questions` VALUES (444, '', '', '', '', 'Il est plus vieux que le plus vieux des Enutrofs, plus fourbe que le plus fourbe des Roublards, et plus dangereux qu\\\'un Bwork Mage saoul.  \\nVous ne devriez pas aller le rencontrer seul, il se prom?ne souvent avec une arm?e d\\\'Araknes dans les for?ts pr?s de la scierie du sud, il est toujours en qu?te de nouveaux b?cherons ? d?vorer. \\nUne derni?re chose... faites attention ? sa magie, elle a d?j? failli ?ter la vie ? Brouce Boulgoure le B?cheron l\\\'hiver dernier.');
INSERT INTO `npc_questions` VALUES (445, '', '', '', '', 'Il n\\\'y a que deux solutions, l\\\'entra?nement et les parchemins de force. Le probl?me des parchemins, c\\\'est qu\\\'on ne peut pas les utiliser si on est trop fort. Ca fait longtemps que c\\\'est le cas pour moi. Si vous voulez, je peux vous ?changer un Petit Parchemin de Force contre une centaine d\\\'Epines de Champ Champ.');
INSERT INTO `npc_questions` VALUES (446, '', '', '', '', 'Je n\\\'ai besoin de rien d\\\'autre. Par contre, je collectionne les ceintures, les Ceintures de Chance pour ?tre pr?cise. Si vous m\\\'en trouvez une centaine, je vous donnerai un Petit Parchemin d\\\'Intelligence.');
INSERT INTO `npc_questions` VALUES (447, '', '', '', '', 'Pour cela, il y a les parchemins, je suppose que vous ne parliez pas d\\\'entra?nement. Je peux vous ?changer 100 D?fenses de Sanglier contre un Petit Parchemin de Vitalit? si vous le voulez.');
INSERT INTO `npc_questions` VALUES (448, '', '', '', '', 'Si on ne veut pas s\\\'entra?ner, il reste toujours les parchemins. Je collectionne les anneaux Agilesque, amenez-m\\\'en une centaine et je vous donnerai un Petit Parchemin d\\\'Agilit');
INSERT INTO `npc_questions` VALUES (449, '', '', '', '', 'Si le marteau ne t\\\'int?resse pas, je peux toujours t\\\'?changer des Cornes de Bouftou contre un Petit Parchemin de Sagesse, mais il en faudra une centaine.');
INSERT INTO `npc_questions` VALUES (450, '378', '', '', '', 'Les fameuses Bottes de Klime... \\nC\\\'est Lee Chainedarpenteur, un illustre cordonnier ?tourdit, manquant de sommeil, qui un soir a tent? de confectionner les fameuses Puissantes Bottes de Klime...personne ne sait comment il a fait, mais les premiers exemplaires qu\\\'il a fabriqu?s ?taient ?trangement  puissants, et lorsqu\\\'il s\\\'est aper?u de tout ?a il ?tait trop tard... \\n');
INSERT INTO `npc_questions` VALUES (451, '', '', '', '', 'Il a donc fait appel ? l\\\'ordre du Cul Bott? pour faire ?changer sans le consentement  de ses clients, ces fameuses bottes trop puissantes par les Surpuissantes Bottes de Klime... aussi puissantes, mais plus difficiles ? porter. \\n \\nL\\\'ordre du Cul Bott? a d? mener une op?ration d\\\'envergure et cela n\\\'a pas ?t? facile, beaucoup de clients se sont aper?us du changement de bottes et se sont mis ? traquer et menacer le pauvre cordonnier, qui a depuis quitt? Amakna ? jamais... \\nAujoud\\\'hui, c\\\'est l\\\'Ordre du Cul Bott? qui assure le service client et pour les personnes qui ont des difficult?s ? porter les Surpuissantes Bottes de Klime qui leur ont ?t? donn?es, nous leur donnons en ?change de ces bottes, une paire de Puissantes Bottes de Klime, nouveau mod?le, qui sont, je dois l\\\'admettre, tr?s courues ces derniers temps. Si vous voulez faire cet ?change, n\\\'h?sitez pas je suis ? votre disposition.');
INSERT INTO `npc_questions` VALUES (456, '38', '', '', '0', 'Les B?cherons sont les principaux amateurs de haches, ils ont souvent besoin d\\\'un outil qui puisse leur servir d\\\'arme s\\\'ils sont attaqu?s.  \\nPour forger une hache, il faut g?n?ralement trouver du bois de qualit? pour confectionner un manche r?sistant, et des m?taux adapt?s pour la lame. \\nJe peux vous apprendre ce m?tier si vous le d?sirez.');
INSERT INTO `npc_questions` VALUES (457, '386', '', '', '', 'Bonjour, voil? plusieurs semaines que j\\\'essaye sans succ?s d\\\'apprivoiser ces dragodindes pour les chevaucher. J\\\'aurais tant aim? en faire un commerce...');
INSERT INTO `npc_questions` VALUES (458, '', '', '', '', 'J\\\' ai captur? ces trois-l? lors de ma randonn?e dans les montagnes au nord-est du village. J\\\'ai eu de la chance, car ils sont tr?s craintifs, et il est donc difficile de les approcher.');
INSERT INTO `npc_questions` VALUES (459, '', '', '', '', 'Tout perdu...J\\\'ai tout perdu...L\\\'id?e ?tait bonne, j\\\'avais ?crit tous les livres n?cessaires pour former des apprentis ? distance...Des capes, des chapeaux...Ils auraient pu tout faire. \\nEt puis, il y a eu ces maudits forgerons sombres, ils ne m\\\'ont laiss? aucune chance, ils m\\\'ont vol? tous mes livres ! Je suis s?r qu\\\'ils les ont cach?s dans leur rep?re...');
INSERT INTO `npc_questions` VALUES (460, '387', '', '', '0', 'Oy? matelot ! Un petit tour, ?a te botte ? J\\\'ai d?couvert en faisant le tour du monde en 80 jours, une petite ?le bien sympathique, habit?e par des cr?atures ?tranges. On en a embroch? quelques-unes, et franchement, leur viande est d?licieuse. Si tu veux te faire un petit voyage gastronomique, je te propose l\\\'aller-retour pour 500 kamas.');
INSERT INTO `npc_questions` VALUES (462, '388', '', '', '0', 'Yop matelot ! Tu as fini ce que tu avais ? faire ?  \\nOn se rentre dans ce cas...');
INSERT INTO `npc_questions` VALUES (464, '', '', '', '', 'Bonjoul mesile, je suis tl?s heuleux de vous voil ? c?t? de moi...Notle pays est envahi pal de t?llibles cl?atules...Et en plus on ne complend lien ? ce qu\\\'elles lacontent.  \\nIls sont alliv?s par la telle et nous ont attaqu? de nuit, on a lien pu faile...C\\\'etait hollible... \\nVous ?tes venus nous sauvel, je le vois bien, vos yeux sont lemplis d\\\'amoul.  \\n \\nFaites attention ? vous gland monsieul cal notle ?le est sp?ciale...La vente y est impossible, tout comme les t?l?poltations...Poul entlel dans le ch?teau du wa, il vous faut obligatoilement des cl?s que vous tlouvelez, ? mon avis, dans la zone envahie pal ces lustle de wabbits...Coulage, l\\\'esplit du dieu lenald est avec vous.');
INSERT INTO `npc_questions` VALUES (465, '', '', '', '', 'Bonjoul ? vous, je vais vous aidel en vous donnant la lecette de la potion qui vous pelmetela d\\\'allel plus haut dans l\\\'?le...Il vous faut tlouvel un bon enchanteul poul vous la pl?palel.  \\nIl faut 1 gel?e de chaque couleul, ? savoil, 1 bleue, 1 velte et 1 louge... \\nBonne chance et que la glande queue du dieu lenald soit avec vous.');
INSERT INTO `npc_questions` VALUES (466, '', '', '', '', 'Lebonjoul, vous en avez fait du chemin, je peux peut-?tle vous lamenel quelque palt?');
INSERT INTO `npc_questions` VALUES (467, '391', '', '', '', 'Whouah Tu es gwand toi, je te pw?viens je suis le Matin qui Pewle...L\\\'un des plus puissants Wabbits du monde...Je suis le Wabbit b?ni de l\\\'astwe chantant...Alows aw?te de me wegawdew comme ?a...Tu ne vas pas m\\\'attaquew quand m?me...J\\\'ai pawticip? ? la destwuction de la gwande Touw Echelle... \\n \\nMais aw?te de me wegawdew...Tu vas pas m\\\'attaquew quant m?me...Je suis tout seul, tout petit, wegawde mes yeux bwillent...C\\\'est impossible de faiwe du mal ? une cw?atuwe aussi mignone que moi, et les gwands comme toi n\\\'attaquent pas les plus petits...Si ?  Euh...Si je te donne une gwosse cl? et tu me laisses twanquille d\\\'accowd?');
INSERT INTO `npc_questions` VALUES (468, '392', '', '', '', 'Whouuuuuu Ahhhh Whooaauuu ! \\nJe suis le tewible Wabbit du Midi Wayonnant, jonction fatale entwe le soiw et le matin...Je n\\\'ai peuw de wien, sachez-le...Si je vous donne cette cl? c\\\'est pawsque vous m\\\'?tes tewiblement sympathique...N\\\'allez pas cwoiwe que j\\\'ai peuw de cette gwosse awme qui pend ? votwe ceintuwe, ?a n\\\'est pas ?a du tout...');
INSERT INTO `npc_questions` VALUES (469, '393', '', '', '', 'L?, ? votwe ceintuwe, je vois bien les deux cl?s de mes fw?wes d\\\'awmes. Ils ont d? ch?wement d?fendwe leur vie...Vous devez ?twe un twwible guewwiew...Je vous donne ma cl?, ?a ne sewt ? wien que je finisse en civet...');
INSERT INTO `npc_questions` VALUES (470, '394;395;396', '', '', '0', 'Fichwte...Vous m\\\'avez gwandement mawave...Je vais avoiw du mal ? m\\\'assoiw pendant quelque temps...Je vous pwopose quelque chose pouw vous wemewcier de ce beau combat qui m\\\'a wappel? ma jeunesse...Choisissez entwe mon b?ton, ma cape ou ma couwonne, je vous en offwe un... \\nSuwtout n\\\'h?sitez pas ? weveniw, on s\\\'est quand m?me bien fendu la cawotte.');
INSERT INTO `npc_questions` VALUES (471, '', '', '', '', 'Bonjoul ? toi ?tlangel...Ca fait du bien de voil un visage chaleuleux...Depuis que ces maudits Wabbits sont alliv?s, ils s?ment telleul et cawottes sul notle petite ?le. \\nIl y a encole quelques ann?es, nous vivions en paix ici, nous noullissant  d\\\'amoul et d\\\'eau flaiche. Et puis ces monstles sont alliv?s, soltant du sol comme des taupes en luth...Ce fut tellible...Le pile c\\\'est que ces l?ches n\\\'attaquent qu\\\'en bande, seuls, ils sont inoffensifs.  \\n \\nMais le dieu Lenald m\\\'a pall? il y a peu et m\\\'a celtifi? qu\\\'un gloupe de valeuleux h?los viendla ? notle secouls...');
INSERT INTO `npc_questions` VALUES (472, '398', '', '', '', 'Bonjouw homme ? la petite cawotte. J\\\'ai un gwos ?change ? te pwoposew, si tu me wappowtes 100 cawottes de chez cawotte je te donne un sowt de mon invention. Mes fw?wes ont peuw de moi et de mes id?es ?twanges, ils m\\\'ont isol? ici en me pwivant de nouwwituwe...Si tu leuw voles ? mangew, mon sowt est ? toi.');
INSERT INTO `npc_questions` VALUES (473, '', '', '', '0', 'Voila, tu pouwwas d?sowmais faiwe poussew des cawottes.');
INSERT INTO `npc_questions` VALUES (477, '402', '', '', '0', 'Wobot matwicule 53, 2?me classe au 11?me w?giment de wobot de la gawde du Wa. \\nHalte-l? !');
INSERT INTO `npc_questions` VALUES (478, '', '', '', '', 'Excusez-moi mon wa je ne vous avais pas weconnu. \\nVotwe majest? souhaite-t-elle acc?dew ? la salle du dofus ?');
INSERT INTO `npc_questions` VALUES (479, '', '', '', '', 'L\\\'acc?s ? cette pawtie de l\\\'?le est wesewv? au wa. Hows de ma vue !');
INSERT INTO `npc_questions` VALUES (480, '', '', '', '', 'Tenez, j\\\'ai not? sur ce parchemin la liste des parchemins que je dois exp?dier, n\\\'h?site pas ? me demander des renseignements.');
INSERT INTO `npc_questions` VALUES (481, '', '', '', '', 'Je suis trop occup? ? chercher le tr?sor d\\\'Halouine, pour l\\\'instant. Tous les ans ? cette p?riode, il parait qu\\\'un passage secret permet de trouver ce tr?sor. Je m\\\'y int?resse car il contiendrait un livre expliquant la mani?re de cr?er un masque citwouille tr?s puissant.');
INSERT INTO `npc_questions` VALUES (482, '', '', '', '', 'Je n\\\'ai aucune demande d\\\'assassinat pour le moment. Va te faire prendre ailleurs !');
INSERT INTO `npc_questions` VALUES (484, '', '', '', '', 'Tenez, j\\\'ai not? sur ce parchemin la liste des missions inachev?es, n\\\'h?sitez pas ? me demander des renseignements.');
INSERT INTO `npc_questions` VALUES (486, '', '', '', '', 'Hahaha, ces missions secr?tes sont r?serv?es aux ma?tres du clan.');
INSERT INTO `npc_questions` VALUES (487, '', '', '', '', 'Hahaha, ces missions secr?tes sont r?serv?es aux ma?tres du clan.');
INSERT INTO `npc_questions` VALUES (488, '', '', '', '', 'J\\\'ai envoy? Yrun Teullair, un de mes disciples, voler le manuel du tailleur d\\\'Amakna. H?las, il n\\\'est toujours pas revenu, et je crains qu\\\'il n\\\'ait d?cid? de se l\\\'approprier. \\nSi vous me ramenez ce manuel intact, je saurais vous r?compenser.');
INSERT INTO `npc_questions` VALUES (489, '', '', '', '', 'Tu as r?ussi ? trouver le manuel. Je ne te dis pas merci, mais je le pense tr?s fort.');
INSERT INTO `npc_questions` VALUES (490, '', '', '', '', 'On ne t\\\'a jamais dit qu\\\'il ne faut jamais voler un voleur. Tu ne poss?des pas assez de kamas, je ne peux rien pour toi.');
INSERT INTO `npc_questions` VALUES (491, '', '', '', '', 'Pour le moment, je n\\\'ai aucune mission pour toi. Va te faire prendre ailleurs !');
INSERT INTO `npc_questions` VALUES (492, '', '', '', '', 'J\\\'ai r?guli?rement des messages ? lui envoyer, si tu lui remets cette missive tu recevras 200 kamas et tu monteras un peu plus dans l\\\'estime de notre clan. \\nTu le trouveras dans les montagnes');
INSERT INTO `npc_questions` VALUES (493, '', '', '', '', 'Je n\\\'ai pas de courrier ? lui remettre pour le moment.');
INSERT INTO `npc_questions` VALUES (494, '', '', '', '', 'J\\\'ai r?guli?rement des messages ? lui envoyer, si vous lui remettez cette missive, vous recevrez 1000 Kamas et vous monterez un peu plus dans l\\\'estime de notre clan. \\nVous le trouverez au sud de la for?t sombre d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (495, '', '', '', '', 'Je n\\\'ai pas de courrier ? lui remettre pour le moment.');
INSERT INTO `npc_questions` VALUES (496, '', '', '', '', 'Les ma?tres Roublards ont chacun un r?le diff?rent et une r?gion ? g?rer. Nous sommes trois situ?s dans la r?gion d\\\'Amakna,  \\nMon r?le est de former et de prendre en charge les apprentis qui veulent entrer dans notre clan. \\n');
INSERT INTO `npc_questions` VALUES (497, '414', '', '', '0', 'Bonjouw, je vois que vous poss?dez les affaiwes du wa, confowm?ment ? nos lois, la pewsonne se pw?sentant ? la salle du Dofus avec les effets pewsonnels du wa peut empowter le dofus. \\nPaw contwe vous devez pouw cela wemettwe ses habits en ma possession. ');
INSERT INTO `npc_questions` VALUES (500, '', '', '', '', 'Tu chewches la sowtie ? \\nJe peux te telepowter ailleuws si tu veux...');
INSERT INTO `npc_questions` VALUES (523, '485;482;479;478', '', '', '0', 'AhAhAhAh ! Je ne suis plus seul ! Mon souhait a ?t? exauc? ! Bienvenue sur l\\\'?le de Moon, colocataire. Je suis Gropinson Cruaul?. Ah, mais peut-?tre me suis-je d?j? pr?sent?. Je ne m\\\'en souviens plus, il y a tellement de nouveaux venus depuis quelque temps AhAhAh !');
INSERT INTO `npc_questions` VALUES (530, '', '', '', '', 'Rassure-toi, voil? 2000 kamas pour te rembourser le prix du pain. Je savais bien que je trouverais quelque chose d\\\'utile ? te faire faire.');
INSERT INTO `npc_questions` VALUES (537, '563;504;473', '', '', '', 'Bonjour, cher futur client. Vous semblez fatigu? de tous ces combats, ce travail ? faire toute la journ?e pour ne r?colter qu\\\'un maigre p?cule. Harass? par le runo-boulot-dodo, vous en perdez l\\\'app?tit, et votre humeur s\\\'en ressent? N\\\'h?sitez plus, l\\\'agence Touriste est l? pour changer tout ?a. Nous vous proposons du bonheur et de la d?tente ? des prix d?fiant toute concurrence. Aujourd\\\'hui, ? titre exceptionnel, notre super promo peut ?tre ? vous. Moins 50% sur nos tarifs normaux. Oui vous avez bien entendu! Vous DEVEZ en profiter !');
INSERT INTO `npc_questions` VALUES (543, '499;461;460', '', '', '0', 'Bien le bonjour ?tranger, on me nomme Kib Roche, futur grand pirate. J\\\'ai ?chou? sur cette ?le en suivant mon tout nouvel achat : une carte au tr?sor parlante. Mais ce damn? perroquet s\\\'est enfui lors de mon arriv?e fracassante par la voie des airs. ');
INSERT INTO `npc_questions` VALUES (544, '462', '', '', '', 'Je pense visiter l\\\'?le, un tr?sor doit certainement ?tre enfoui quelque part. Et j\\\'en profiterai pour r?unir des tas d\\\'objets divers qui me permettront certainement de fabriquer un radeau pour partir d\\\'ici.');
INSERT INTO `npc_questions` VALUES (545, '', '', '', '', 'Entre nous, c\\\'est une longue histoire pleine d\\\'or, de singes, et de personnages peu recommandables. J\\\'en retiens juste une explosion, un formidable vol plan? en bateau, un arrachage de voile pour m\\\'en servir de parachute et ma t?te dans le sable.');
INSERT INTO `npc_questions` VALUES (546, '3933', '', '', '0', 'Toi pas passer ! Toi viande, Kanniboul avoir assez viande jusque prochain repas. Mais repas de maintenant compromis ! Moi probl?me, plus avoir carapace tortue pour ?picer viande! Mais pas pouvoir aller tuer tortue sur plage, car moi devoir tourner soupe. Moi r?fl?chir, mais rien trouver ! ');
INSERT INTO `npc_questions` VALUES (547, '49', '', '', '0', 'Oh nourriture serviable ! Toi rapporter moi 4 carapaces couleurs diff?rentes, et moi pouvoir pr?parer repas. Pour r?compenser viande, toi pourras rentrer village, et attendre pour servir prochain repas.');
INSERT INTO `npc_questions` VALUES (548, '1596;463;488', '', '', '0', 'Hola moussaillon *hic* l\\\'heeure est graave *hic*! Bient?t plus de bo?sson *hic* pour remplir ces c??les *hic*.  \\nMais si ce n\\\'?tait que ?aa *hic* Ma mu?se a disparu *hic* mon graand squelette de bois *hic* mon mood?le aux heures perdues *hic*.');
INSERT INTO `npc_questions` VALUES (549, '', '', '', '', 'Par Grande Baaarbe tu ferais ?a *hic* ? Tu deviendrais mon h???ros *hic* et pour te r?compenser tu auraas *hic* droit d\\\'emporter un tonneau *hic*. \\nRappooorte moi nimporte quoi *hic* sauf de l\\\'eau ?a m\\\'eeffffraye *hic*Une bouteille de rhu?um suffira *hic* pour prendre possession de ta paaaye *hic*');
INSERT INTO `npc_questions` VALUES (550, '466;464;465;482', '', '', '0', 'Bonjour cher client, bienvenue sur l\\\'?le paradisiaque de Moon. \\nJe suis envoy? par l\\\'agence pour vous accueillir et vous pr?senter les diff?rentes activit?s que nous vous proposons.');
INSERT INTO `npc_questions` VALUES (551, '46', '', '', '0', 'Mais cher client, il ?tait bien pr?cis? dans le contrat qu\\\'il s\\\'agissait uniquement d\\\'un aller, le retour n\\\'est pas compris dans l\\\'offre promotionnelle. Il aurait fallu payer un suppl?ment ou choisir une autre destination.');
INSERT INTO `npc_questions` VALUES (552, '47', '', '', '0', 'Ah ! C\\\'est une tr?s bonne question cher client. \\nTout d\\\'abord, la partie Est de l\\\'?le est une immense plage qui vous permettra de vous pr?lasser au soleil et de dorer un peu votre peau, ce qui lui donnera un aspect plus jeune et moins fatigu?. Vous serez alors jalous? par vos coll?gues lorsque vous reprendrez votre activit? de tous les jours. Profitez de vos moments de d?tente sur le sable pour d?guster les merveilleuses Kokos qui sont juste ? votre port?e.');
INSERT INTO `npc_questions` VALUES (553, '', '', '', '', 'Les pirates occupent une partie du Nord de l\\\'?le, ils vous accueilleront les bras ouverts. Ne manquez pas de go?ter leur rhum 120 ans d\\\'?ge. Pensez aussi ? saluer bien bas leur illustre capitaine. Mais surtout ne vous moquez jamais de son cale?on porte chance. Selon la l?gende, son cale?on ridicule lui aurait assur? assez de chance pour ?chapper aux multiples temp?tes lorsqu\\\'il naviguait dans les terribles mers de Kalmar.');
INSERT INTO `npc_questions` VALUES (554, '', '', '', '', 'Les habitants de l\\\'?le sont assez bourrus au premier abord. Mais ne croyez pas qu\\\'ils ont une dent contre vous ! Bien au contraire, ils adorent vraiment les touristes. Rien ne surpasse plus leur compagnie que leur chef lui-m?me. On dit de ce dernier qu\\\'il est l\\\'incarnation du Dieu de l\\\'?le : Moon. Ne vous fiez pas ? son apparence, il est vraiment tr?s intelligent et dr?le.');
INSERT INTO `npc_questions` VALUES (555, '46', '', '', '0', 'Et bien, cher client, je ne peux, h?las, satisfaire votre demande. Notre agence, qui s\\\'engage ? toujours ?tre claire et concise avec vous comme le pr?cise notre slogan, ne peut simplement pas vous faire repartir. Par contre, je peux vous proposer une alternative...');
INSERT INTO `npc_questions` VALUES (556, '505', '', '', '0', 'Et bien, pour une somme modique, 200 kamas, vous pouvez m\\\'acheter un aller direct pour le paradis et cette fois l\\\'agence le garantit ? 100%: satisfait ou rembours?! ');
INSERT INTO `npc_questions` VALUES (558, '47', '', '', '0', 'Faites attention cependant ? ne pas vous blesser avec les quelques bouts d\\\'?paves qui tra?nent un peu partout.  \\nEnsuite, amateur de frissons, je vous propose de faire une ballade vers le Sud de la jungle. Frayeurs garanties avec nos pirates fant?mes locaux. Mais ne craignez rien ils ne sont que peu dangereux...');
INSERT INTO `npc_questions` VALUES (559, '', '', '', '', 'Enfin, je vous invite ? visiter l\\\'Ouest de l\\\'?le. La jungle f?erique vous y attend, sa flore luxuriante et sa faune ?trange vous captiveront un long moment. Avec un peu de chance, vous rencontrerez les habitants de l\\\'?le, d?couvrirez leur folklore tr?s riche, et serez probablement invit? ? leur table. Si vous avez le temps, tentez de courir au Sud de l\\\'?le o? vous aurez sans doute le privil?ge ultime de rencontrer le Chef de l\\\'?le de Moon.');
INSERT INTO `npc_questions` VALUES (560, '474', '', '', '', 'Je vous propose de partir sur une ?le de r?ve, le paradis sur terre. Imaginez-vous : allong? dans le sable fin, le soleil dorant votre peau d?licate, la brise marine vous pourl?chant le visage. Dans votre main un cocktail de lait de Koko. Une fois la journ?e pass?e ? ne rien faire du tout vous vous retrouvez, vous et vos amis, ? la table des habitants locaux, fins cuisiniers, qui seront aux petits oignons pour vous. Le soir, admirez le spectacle f?erique de la lune ?clairant la vaste flore et faune de l\\\'endroit. Et si vous d?sirez vous divertir avec un peu de frissons, des agents sp?cialement form?s depuis cent ans seront ? votre service.');
INSERT INTO `npc_questions` VALUES (561, '', '', '', '', 'Tout ?a pour presque rien! Oui cher client, trois fois rien pr?cis?ment. Le voyage ne co?te que 1000 kamas, cependant pour voyager dans les meilleures conditions nous vous demandons de vous munir d\\\'un casque et de vous ?quiper d\\\'une paire d\\\'ailes directrices. Revenez vite avec ces petits riens pour rapidement profiter de notre offre exceptionnelle, car elle ne sera pas ?ternelle...Et surtout, invitez vos amis, les vacances sont tellement plus dr?les et plus passionnantes ? plusieurs.');
INSERT INTO `npc_questions` VALUES (562, '', '', '', '', 'Bonjour et bienvenue dans Dofus. \\n \\nTe voici ? Tain?la, le berceau d\\\'Amakna, la Province ?ternelle de Dofus. Dans cet endroit, tu apprendras les rudiments que doit conna?tre tout nouvel aventurier. \\n \\nApr?s cette initiation, tu pourras parcourir Amakna ? la recherche des pr?cieux Dofus, les oeufs de dragons aux pouvoirs prodigieux.');
INSERT INTO `npc_questions` VALUES (566, '493', '', '', '0', 'Hum toi approcher, moi pas beaucoup voir toi !');
INSERT INTO `npc_questions` VALUES (567, '', '', '', '', 'Je suis Gropinson Cruaul?, ne vous l\\\'avais-je pas dit ? Je suis vacancier ici depuis 50 ans ahahah. Mon agence m\\\'avait assur? un aller direct pour le paradis. Ils n\\\'avaient pas menti, mais il me reste encore quelques ann?es avant d\\\'y aller AhAhAh!');
INSERT INTO `npc_questions` VALUES (568, '510;480', '', '', '0', 'Vous ?tes sur l\\\'?le de Moon. Votre r?sidence pour les 50 prochaines ann?es ahahah. Heureusement pour vous, l\\\'?le s\\\'anime un peu ces temps-ci. Vous n\\\'allez pas vous ennuyer...la premi?re semaine Ahahah!');
INSERT INTO `npc_questions` VALUES (569, '48', '', '', '0', 'Ahahahah! Vous ?tes donc un touriste ? perp?tuit? de cette nouvelle agence ohoh. Et bien pour occuper votre temps libre l\\\'?le habite des attractions... particuli?res ahahah ! Mais demandez donc ? votre guide qui vient de faire une arriv?e explosive sur la plage ahana ! Dans tous les cas pour visiter l\\\'?le en profondeur il vous faudra payer ohoh.');
INSERT INTO `npc_questions` VALUES (570, '', '', '', '', 'On dit que cette ?le est la cr?ation du dieu Moon. Pour la surveiller, il s\\\'est incarn? dans un ?tre de chair et de sang. Mais nul autre que ses adorateurs ne peut l\\\'approcher ? moins de lui faire une offrande. Concr?tement, pour s\\\'approcher de Moon, il faut poss?der de nombreuses noix de Koko;\\r\\n            ? chaque passage pr?s d\\\'un totem Koko, un nombre ?gal ? sa grandeur vous sera retir? automatiquement, simple non ohoh!');
INSERT INTO `npc_questions` VALUES (571, '483', '', '', '0', 'Les habitants de l\\\'?le? Ahahah ! Il y a bien quelques pirates qui tra?nent au Sud de la jungle. Ils sont assez froids envers les ?trangers ohohoh. Ils ?taient d?j? l? quand je suis arriv? et ils seront probablement l? quand vous repartirez, ? croire qu\\\'ils aiment bien cette ?le Ahaha !');
INSERT INTO `npc_questions` VALUES (572, '484', '', '', '0', 'Ah il y a aussi une tribu locale, tr?s bonne cuisine ! Mais je ne vous la recommande pas Ahahah ! Ils font aussi de tr?s jolis masques ohoh.');
INSERT INTO `npc_questions` VALUES (573, '', '', '', '', 'Recemment il y a le guide touristique de votre agence qui est arriv? en planant sur la plage ahaha. Un apprenti pirate tra?ne aussi au sud de l\\\'?le, je crois qu\\\'il cherche un moyen de partir ahahah.');
INSERT INTO `npc_questions` VALUES (574, '486', '', '', '0', 'Ohoh joli masque! On pourrait presque vous prendre pour un Kanniboul Ahah! Vous n\\\'iriez pas tr?s loin par contre, c\\\'est un masque de sous-fifre. Faudrait penser ? monter en grade ahahah.');
INSERT INTO `npc_questions` VALUES (576, '487', '', '', '0', 'Ohoh mais vous ?tes s?rieux en plus. Bon je veux bien vous aider. Pour monter en grade les Kannibouls sous-fifres se battent entre castes. Le gagnant prend le masque du perdant. Celui qui poss?de le masque des 4 castes les combine pour en faire un nouveau. Si vous me ramenez les 4 masques, je pense pouvoir les combiner.');
INSERT INTO `npc_questions` VALUES (577, '', '', '', '0', 'Attendez une seconde.....Voil?! Il est m?me ? votre taille. Et bien je n\\\'aurais pas surv?cu si longtemps pour rien. Bonne chance, ? votre retour vous me raconterez votre petit p?riple...Si vous revenez bien s?r ahaha.');
INSERT INTO `npc_questions` VALUES (578, '', '', '', '', 'Humm non ?a ne va pas du tout, il manque quelque chose. Il faut 4 masques et...une couleur suppl?mentaire;\\r\\n            rapportez moi les masques et du n?cessaire pour les peindre sinon je ne pourrai faire de masque ressemblant. O? trouver de la peinture ? Ahaha mais comment voulez-vous que je sache ?a Ahah!');
INSERT INTO `npc_questions` VALUES (579, '', '', '', '', 'Ce serait vraaaiment gentillet *hic* sans lui mon g???nie s\\\'est tuuu *hic* Mais il m\\\'en faut un coomplet *hic* mon tr?sor sera alors mooon d? *hic*');
INSERT INTO `npc_questions` VALUES (580, '', '', '', '', 'Pour remeeercier l\\\'aventuurier *hic* voici mon tr?sor incooongru *hic* ce pot qui m\\\'a fait d??buter *hic* ma carri?re de peeintre-po?te disparu *hoc*');
INSERT INTO `npc_questions` VALUES (581, '', '', '', '', 'Mais il en manque un bout *hic* sans lui je ne peux rien faire *hic* je serais comme un gros Bouftou *hic* sans ses cornes et son grand flair *hic*');
INSERT INTO `npc_questions` VALUES (582, '491', '', '', '', 'Oh c\\\'est tr?s aimable ? toi. Si tu me ram?nes le n?cessaire pour construire mon radeau, je te donnerai un animal de compagnie !');
INSERT INTO `npc_questions` VALUES (583, '', '', '', '', '*Hic* Je peux vous donner une partie de la voiluure de mon ex-bateau. C\\\'est la seule *hic* chooose qu\\\'il me reste. Je vouuus l\\\'?change contre 10 noix de Kokoo. *hippps*');
INSERT INTO `npc_questions` VALUES (584, '', '', '', '', 'Merci viande ! Toi pouvoir aller village, toi visiter et ensuite revenir ici pour ?tre cuit ! Toi pas t\\\'?loigner trop !');
INSERT INTO `npc_questions` VALUES (585, '', '', '', '', 'Ca pas aller, moi besoin 4 carapaces diff?rentes. Reviens quand toi avoir ?a.');
INSERT INTO `npc_questions` VALUES (586, '', '', '', '', 'Ah, toi grand Kanniboul important. Tr?s joli masque ! Toi pouvoir passer !');
INSERT INTO `npc_questions` VALUES (587, '', '', '', '', 'H? Qu\\\'est-ce que nourriture faire l? ? Toi attendre un peu pour cuire toi ! Toi pas pouvoir passer, seul Kanniboul important pouvoir !');
INSERT INTO `npc_questions` VALUES (588, '', '', '', '', 'Ohohoh, vous n\\\'avez pas l\\\'air d\\\'?tre un Kanniboul, mais vous semblez ?tre un grand guerrier et j\\\'appr?cie ?a ! En guise de remerciement pour m\\\'avoir tant amus?, je vous montre ma technique secr?te du lancer de marteau, et je vous autorise ? l\\\'utiliser en mon nom. Je vous demanderai ensuite de partir en vitesse du village...');
INSERT INTO `npc_questions` VALUES (589, '3758', '', '', '0', 'Si vous tra?nez trop, vous pourriez finir en civet. Une nourriture aussi habile que vous est certainement dure ? m?cher et ? dig?rer. Je ne veux pas imposer ?a ? mes adorateurs. Surtout que la viande plus tendre abonde en ce moment. Si vous le voulez, je peux vous aider ? quitter ce village rapidement. Dans tous les cas, Adieu !');
INSERT INTO `npc_questions` VALUES (591, '490', '', '', '0', 'Et encore un !...\\\"Profitez du calme d\\\'une ?le d?serte\\\" qu\\\'ils disaient. \\\"Savourez un bon verre de rhum dans un calme apaisant loin des batailles et des pillages\\\" qu\\\'ils affirmaient. Et moi, en plus de la bruyante populace locale, j\\\'ai des touristes qui prennent mon bateau pour une attraction ! Il faut que je r?pare ce trou, tout le monde le prend pour une porte !');
INSERT INTO `npc_questions` VALUES (592, '', '', '', '', 'Ah voil? quelqu\\\'un de compr?hensif ! Pour r?parer ce trou, il me faudrait beaucoup de planches de bois et de pots de kole. Si vous me ramenez 2 planches de bois et un pot de kole, je vous offrirai une bouteille de bon rhum. J\\\'en ai plein !');
INSERT INTO `npc_questions` VALUES (593, '', '', '', '', 'Il semblerait qu\\\'il y a tout ce dont j\\\'ai besoin pour construire mon radeau !');
INSERT INTO `npc_questions` VALUES (596, '', '', '', '', 'Le port du casque n\\\'est pas obligatoire dans les mines, cependant il est fortement conseill?. Il y a peu, j\\\'ai invent? un type de casque encore plus solide. Il faut juste 10 cuirs de Boufton Noir, 10 ficelles en Lin, et 5 laines de Bouftou, et bien s?r l\\\'aide d\\\'un bon tailleur.');
INSERT INTO `npc_questions` VALUES (597, '', '', '', '', 'Oh comment le savez-vous ? Oui j\\\'ai d?j? vol?, j\\\'ai saut? du haut de ma maison et j\\\'ai plan? sur au moins 5 m?tres. Le plus dur ?tait de fabriquer mes ailes en bois...Mon oncle b?cheron et son ami tailleur les ont faites pour moi, je crois qu\\\'ils ont utilis? 4 planches de fr?ne et 10 ficelles de lin pour les confectionner.');
INSERT INTO `npc_questions` VALUES (598, '', '', '', '', 'F?licitations cher client, vous venez d\\\'acqu?rir votre aller direct pour les ?les tropicales, ? vous le soleil, la mer et ce qui va avec. Vous pouvez partir d?s que vous ?tes pr?t, ?quipez-vous de votre casque, de vos ailes, donnez rendez-vous ? vos amis et glissez-vous tous dans le canon. Dans ? peine quelques minutes, vous serez ? destination. Bon voyage et bonnes vacances !');
INSERT INTO `npc_questions` VALUES (599, '', '', '', '', 'D?sol?, nous ne pouvons nous permettre de vous vendre un billet encore moins cher. Je regrette vraiment cher client, mais nous vendons d?j? ? perte pour votre plus grand plaisir, sachez-le ! ?conomisez encore un peu et le billet vers le soleil sera ? vous. Bon courage et ? tr?s bient?t je l\\\'esp?re.');
INSERT INTO `npc_questions` VALUES (600, '', '', '', '', 'Je vois que vous ?tes d?termin?...Je ne vous stopperai pas. Voici une corde, attachez la comme un collier et vous ?tes pr?t ! Bon voyage et envoyez nous une carte postale!');
INSERT INTO `npc_questions` VALUES (601, '', '', '', '', 'Vous n\\\'avez pas assez d\\\'argent pour vous payer ce merveilleux voyage. ?conomisez un peu et revenez me voir.');
INSERT INTO `npc_questions` VALUES (602, '', '', '', '', 'Oh comment le savez-vous? Oui j\\\'avoue j\\\'ai d?j? vol? quelqu\\\'un, mais j\\\'avais besoin de ce pain, j\\\'avais faim et je n\\\'avais plus d\\\'argent. S\\\'il vous pla?t, ne le dites ? personne, je risquerais la prison, je vous en supplie!');
INSERT INTO `npc_questions` VALUES (603, '', '', '', '', 'Oui, j\\\'ai d?j? vol?, plusieurs fois m?me, j\\\'?tais un oiseau, et je planais dans le ciel d\\\'Amakna...De bien jolis r?ves ma foi. J\\\'en ai m?me fait plusieurs toiles.');
INSERT INTO `npc_questions` VALUES (604, '', '', '', '', 'Un casque solide? Et pour quoi faire? Seul un casque impressionnant peut avoir un impact sur le combat, apr?s la qualit? de la lame bien s?r. Seuls les mineurs portent des casques \\\"solides\\\" pff!');
INSERT INTO `npc_questions` VALUES (605, '', '', '', '', 'Moi ? Non, j\\\'ai le vertige, mais j\\\'ai d?j? vu d\\\'autres enfants qui l\\\'ont fait.');
INSERT INTO `npc_questions` VALUES (606, '', '', '', '', 'Ahaha pour ne pas dormir ? la belle ?toile il va falloir vous construire votre maison ou au moins un toit. Pour ce faire, il va vous falloir d?couper du Kokotier!  Avec un tronc de Kokotier vous pouvez faire facilement une planche de bois, avec deux vous pouvez faire une petite poutre.  Pour couper tout ?a vous pouvez aller voir l\\\'apprenti pirate au Sud de la plage, il s\\\'est install? un ?tabli. Cela m\\\'?vitera de vous pr?ter mes outils AhAhAh!');
INSERT INTO `npc_questions` VALUES (607, '', '', '', '', 'Pour construire un radeau il faut au minimum 6 flotteurs, 4 liens pour les attacher, 2 lattes pour faire un sol plat, une poutre, un tronc en guise de m?t, une voile en BON ?tat, et au moins 10 pots de Kole pour fixer tout ?a.');
INSERT INTO `npc_questions` VALUES (608, '512', '', '', '0', 'Ahaha j\\\'ai bien fait de venir sur cette ?le. Il y a certaines choses de valeur ? r?cup?rer, sans compter toutes les personnes faibles ? d?trousser... M?me pas besoin de combattre il suffit d\\\'attendre qu\\\'ils mordent la poussi?re contre un Kanniboul ou un monstre des environs.');
INSERT INTO `npc_questions` VALUES (609, '51', '', '', '0', 'Regarde par exemple ce cale?on rose, il ne paye pas de mine. Pourtant, il s\\\'agit du cale?on magique du capitaine pirate, il porte chance en mer dit-on, je suis s?r de le revendre un bon prix.');
INSERT INTO `npc_questions` VALUES (610, '514', '', '', '0', 'Tu veux me l\\\'acheter ? bah pourquoi pas, ?a me fera gagner du temps. Je te le c?de contre 5000 kamas et 5 peaux de larves orange. J\\\'en ai besoin pour me confectionner une potion d\\\'invisibilit?. ? ce prix-l?, c\\\'est un cadeau que je te fais.');
INSERT INTO `npc_questions` VALUES (611, '', '', '', '', 'Tr?s bien, un march? est un march?, voil? ton cale?on. Au plaisir de faire d\\\'autres affaires avec toi.');
INSERT INTO `npc_questions` VALUES (612, '', '', '', '', 'Vous aimeriez me voler ? Moi ? quelle bonne blague, revenez quand vous serez d?cid? ? payer le faible prix que je vous demande.');
INSERT INTO `npc_questions` VALUES (613, '560;559;518;2582', '', '', '0', 'Les Dieux d\\\'Amakna te b?nissent mon enfant ! Quel miracle a guid? tes pas vers cette modeste demeure c?leste ?');
INSERT INTO `npc_questions` VALUES (614, '2582;560;559', '', '', '0', 'Mon enqu?te pi?tinait, j\\\'allais refaire le tour de la maison lorsque quelqu\\\'un entra dans la pi?ce et m\\\'interpella...');
INSERT INTO `npc_questions` VALUES (615, '', '', '', '', 'Que-vais je faire maintenant ? Mon ma?tre est mort \\nBouhouhouuu...');
INSERT INTO `npc_questions` VALUES (616, '', '', '', '', 'Il me demanda des renseignements sur la victime, a priori ce n\\\'?tait qu\\\'un badaud, mais ma conscience professionnelle me poussa ? le consid?rer comme un suspect. \\nJe lui indiquai donc vaguement qu\\\'il s\\\'agissait du meurtre du propri?taire de la maison et lui demandai o? il se trouvait la nuit pr?c?dente vers 20 heures.');
INSERT INTO `npc_questions` VALUES (617, '', '', '', '', 'Son alibi ?tait assez boiteux, mais ? y r?fl?chir le vrai criminel aurait s?rement trouv? quelque chose d\\\'un peu plus cr?dible, c\\\'?tait donc suffisant pour le disculper.');
INSERT INTO `npc_questions` VALUES (618, '', '', '', '', 'Il me demanda les circonstances de la mort. Au point o? j\\\'en ?tais, je lui r?pondis, et lui expliqua qu\\\'un d?tail m\\\'avait frapp? lors de l\\\'autopsie, en effet sur chacune de ces incisives ?tait inscrit un nombre.');
INSERT INTO `npc_questions` VALUES (619, '', '', '', '', 'Je lui expliquai que ces informations ?taient strictement confidentielles, mais lui laissai sous-entendre qu\\\'en mettant un peu du sien...');
INSERT INTO `npc_questions` VALUES (620, '528', '', '', '', 'Bonjour, qu\\\'est ce que Uba Tess?, alchimiste de g?nie, peut faire pour votre petite personne ?');
INSERT INTO `npc_questions` VALUES (621, '529', '', '', '', 'L\\\'alchimiste est un manipulateur d\\\'?l?ments, magiques ou non. Il transforme des mati?res en d\\\'autres. Mais surtout, ne voyez pas l\\\'alchimiste comme un rat de laboratoire. Un vrai alchimiste passe autant de temps dans son bureau qu\\\'? voyager ? travers le monde ? la recherche d\\\'ingr?dients rares. Et je peux vous dire, par exp?rience, que lorsque votre r?serve de poils de mulou est vide, il faut prendre son courage ? deux mains !');
INSERT INTO `npc_questions` VALUES (622, '', '', '', '', 'Et bien, excellent. Vous ?tes d?j? un vrai alchimiste. A vous de d?velopper votre technique maintenant. Bonne chance confr?re.');
INSERT INTO `npc_questions` VALUES (623, '', '', '', '', 'Croyez-vous qu\\\'il suffit de parler pour pouvoir exercer ce m?tier ? C\\\'est que vous n\\\'avez pas bien compris l\\\'essence m?me du m?tier. Si vous souhaitez vraiment devenir alchimiste allez voir un confr?re instructeur. Il doit ?tre en train d\\\'?tudier les pierres tachet?es ? trois lieues au Nord-Ouest du temple Kanojedo.');
INSERT INTO `npc_questions` VALUES (624, '530', '', '', '', 'Bonjour, comme vous le voyez je suis occup?. J\\\'?tudie ces roches tachet?es. Si vous pouviez donc ne pas trop faire de bruit cela g?ne ma concentration.');
INSERT INTO `npc_questions` VALUES (625, '', '', '', '', 'Ah ! Uba Tess? vous envoie. Je vois, je vois. Humm si vous ?tes venu jusqu\\\'? moi je suppose que vous avez assez de volont? pour devenir alchimiste. H?las, je suis vraiment tr?s occup?. Je vous propose ceci, allez voir un ami ? moi, il effectue un p?lerinage d\\\'?tudes de temple en temple vers le sud d\\\'Amakna. Actuellement, il doit faire une halte dans une toute petite bourgade ? la moiti? de son voyage. ');
INSERT INTO `npc_questions` VALUES (626, '531', '', '', '', 'Bonjour, \\nCe petit temple est vraiment magnifique. Je pense rester un peu ici avant de prendre la direction de ma prochaine destination.');
INSERT INTO `npc_questions` VALUES (627, '544', '', '', '', 'Ah ! Boff Chalon vous envoie, tr?s bien.  Je veux bien vous enseigner les bases de l\\\'alchimie. \\nLes ingr?dients de base de l\\\'alchimie sont souvent des fleurs : tr?fle, lin, orchid?e... Regardez partout o? vous allez durant vos voyages afin d\\\'amasser progressivement un bouquet cons?quent. ');
INSERT INTO `npc_questions` VALUES (628, '532', '', '', '', 'D?cid?ment, cette ?le m\\\'est vraiment sympathique. Je ne m\\\'en lasse pas. ?couter l\\\'eau qui clapote en dessous du pont est l\\\'une de mes activit?s favorites. Ca et cueillir des fleurs.');
INSERT INTO `npc_questions` VALUES (629, '545', '', '', '', 'Voyons voir...Oh ! Vous souhaitez devenir alchimiste ? Oui je suis bien formateur. Tr?s bien alors, ?coutez bien : un alchimiste accompli doit savoir lire l\\\'intensit?, en essence magique, de n\\\'importe quel objet, et pouvoir la manipuler ? sa guise. Posez donc un regard nouveau sur tous les objets pass?s et futurs en votre possession.');
INSERT INTO `npc_questions` VALUES (630, '534', '', '', '', 'Certains ossements du coin sont tout simplement prodigieux. Anim?s d\\\'une vie propre apr?s leur mort. Un sujet vraiment passionnant. Je pourrais moi-m?me y passer ma mort, hahaha!');
INSERT INTO `npc_questions` VALUES (631, '543', '', '', '', 'Oh je vois, tr?s bien. Je ne vous ferai pas l\\\'affront d\\\'un test de qualification. Alchimiste est avant tout un m?tier de passion, et en voyageant ainsi dans tout Amakna pour le devenir vous avez largement prouv? votre d?termination. Voil? votre certificat d\\\'alchimiste. Un dernier conseil pour d?buter : sachez que certains types de fleur poussent partout tandis que d\\\'autres ont des pr?f?rences particuli?res.Ainsi n\\\'oubliez pas de noter les bons coins de r?colte. Bonne chance pour la suite. A bient?t confr?re.');
INSERT INTO `npc_questions` VALUES (632, '', '', '', '', 'Si vous d?sirez des recettes je vous conseille de faire un tour ? la biblioth?que. Un alchimiste a cr?? une encyclop?die en plus de 12 tomes sur les recettes rares.');
INSERT INTO `npc_questions` VALUES (633, '', '', '', '', 'Oubli de la Bo?te de Pandore : 5 vieux tr?fles, 10 lingots d\\\'or, 1 diamant, 1 saphir, 1 ambre ancestral\\nOubli de Rep?rage : 3 os taill?s, 20 Omnicients b?tons-boules de voyante, 1 peinture noire.\\nOubli de compulsion : 4 silex sanglants, 20 anneaux de valeur, 10  ceintures d\\\'endurance,  10 ?crabouilleurs de Iop.\\nOubli de Temp?te du Temps :  5 Immortelles, 50 potions de vieillesse, 5 Cr?nes du Dragon Cochon, 10 Vieux Os de Dragoeuf, 10 Sangs de Likrone.');
INSERT INTO `npc_questions` VALUES (634, '', '', '', '', 'Oubli d\\\'Herbe folle : 5 verveines, 10 Bois d\\\'orme, 40 tiges de pissenlit diabolique, 40 fers, 40 racines d\\\'abraknydes. \\nFl?che d\\\'Expiation : 5 Bois ?lastiques, 5 surpuissants arc du roi des borins, 1 pierre ? aiguiser, 10 sangs de vampire, 10 slips en cuir du Captain Chafer. \\nOubli de Mot de pr?vention : 3 clochettes, 50 lisseurs, 50 louffeurs \\nOubli d\\\'Attirance : 4 Orties, 10 c?l?brit?s, 10 anneaux de satisfaction, 2 capes du coq H? ');
INSERT INTO `npc_questions` VALUES (635, '', '', '', '', 'Si vous d?sirez des recettes je vous conseille de faire un tour ? la biblioth?que. Un alchimiste a cr?? une encyclop?die en plus de 12 tomes sur les recettes rares.');
INSERT INTO `npc_questions` VALUES (636, '', '', '', '', 'Si vous d?sirez des recettes je vous conseille de faire un tour ? la biblioth?que. Un alchimiste a cr?? une encyclop?die en plus de 12 tomes sur les recettes rares.');
INSERT INTO `npc_questions` VALUES (637, '', '', '', '', 'Si vous d?sirez des recettes je vous conseille de faire un tour ? la biblioth?que. Un alchimiste a cr?? une encyclop?die en plus de 12 tomes sur les recettes rares.');
INSERT INTO `npc_questions` VALUES (638, '', '', '', '', 'Si vous d?sirez des recettes je vous conseille de faire un tour ? la biblioth?que. Un alchimiste a cr?? une encyclop?die en plus de 12 tomes sur les recettes rares.');
INSERT INTO `npc_questions` VALUES (640, '', '', '', '', 'Ceci est une fontaine de jouvence ! Elle sert ? r?cup?rer des points de vie.  \\n \\nLorsque tu combats des monstres, tu vas sans doute perdre des points de vie.  \\nSi tu n\\\'es pas encore au niveau 6, tu peux te soigner avec cette fontaine.');
INSERT INTO `npc_questions` VALUES (641, '', '', '', '', 'Pour continuer votre formation, vous devez voir un formateur agr??, je ne le suis pas h?las. Dirigez-vous vers l\\\'?le la plus au Sud. Vous trouverez un formateur alchimiste dans le coin dont j\\\'ai oubli? le nom. Montrez-lui votre parchemin et cette fleur que je vous donne. Symbole d\\\'une premi?re le?on acquise.');
INSERT INTO `npc_questions` VALUES (642, '', '', '', '', 'Voil? je signe ce petit papier...Allez voir l\\\'Alchimiste Examinateur. Je ne sais h?las o? il est. Je peux simplement vous dire qu\\\'il fait actuellement des recherches sur le calcium du cartilage intranasal post-mortem.');
INSERT INTO `npc_questions` VALUES (643, '', '', '', '', '? la douce brise ber?ant sur tes cheveux, l\\\'arme au poing, le sourire aux l?vres, l\\\'exaltation du combat, la mont?e d\\\'adr?naline lorsque tu portes ton coup... Oh ! Je suis d?sol?, je ne t\\\'avais pas vu... \\n \\nBonjour jeune aventurier ! Je suis le Gardien de Tain?la. \\nMes fr?res ont d?j? d? commencer ton apprentissage.  \\nTe voil? donc pr?t ? partir explorer Amakna...  \\nChoisi rapidement ton m?tier. d?couvre de nouveaux territoires, ma?trise le plus d\\\'?quipements et de sortil?ges possibles,... \\nN\\\'oublie pas de toujours rester prudent dans ce monde et m?fie-toi de la sombritude des autres aventuriers.');
INSERT INTO `npc_questions` VALUES (644, '', '', '', '', 'Le monde de Dofus est, il faut bien le reconna?tre, un peu sp?cial.  \\nDe nombreux ?v?nements s\\\'y d?roulent, et, depuis quelque temps des cr?atures malsaines envahissent plaines, champs et montagnes. Pour le moment, seuls les villages restent ? l\\\'abri du mal.  \\nPlus tu ?loigneras tes pas des villages, plus les dangers seront grands, mais c\\\'est le prix de la gloire.  \\n \\nEn Amakna, toute l\\\'?conomie est g?r?e par les guerriers et artisans, les premiers ayant bien souvent besoin des seconds.   \\nEn te comportant mal, tu risques d\\\'?tre consid?r? comme roublard (ailes de d?mon) et d\\\'?tre chass? par les justiciers (ailes d\\\'ange). Fais donc le bon choix ou sois tr?s prudent, car c\\\'est peut-?tre la prison qui t\\\'attend.');
INSERT INTO `npc_questions` VALUES (645, '', '', '', '', 'Il existe de nombreux dieux dans notre univers. Tu as choisi tes croyances il y a bien longtemps, tu connais quelques coups, mais il va te falloir ?voluer.  \\n \\nTu peux mener ta vie de plusieurs fa?ons, il n\\\'y a pas de sots m?tiers.  \\n \\nCertains pr?f?rent se battre, d\\\'autres exercent un m?tier et d\\\'autres encore font les deux. Il n\\\'y a pas de mauvaises fa?ons d\\\'?voluer, juste des choix ? faire.  \\n \\nTu peux  te renseigner sur tes caract?ristiques en cliquant sur le pictogramme rond du brin d\\\'ADN dans l\\\'interface du bas, en haut ? droite de ton portrait. ? chaque passage de niveau, tu gagnes 5 points de caract?ristiques ? r?partir entre la sagesse, la vitalit?, la force, l\\\'intelligence, l\\\'agilit?, la chance.');
INSERT INTO `npc_questions` VALUES (646, '', '', '', '', 'Quel malheur ! Quelle trahison ! O? sont-ils mes valeureux bouftous hier si gentils, si serviables, si protecteurs... et aujourd\\\'hui si m?chants et stupides ! \\n \\nIls ont compl?tement chang? depuis quelques jours. Ils n\\\'ont jamais aussi bien port? leur nom que maintenant !  \\nIls attaquent tous ceux qui bougent. Ils bouffent de tout : cette derni?re heure, 4 Eniripsa, 2 Ecaflip et surtout 1 Iop ont ?t? aval?s par mon seul Bouftou Royal  ! Je suis d?sempar?. Ils ne m\\\'?coutent plus ! Seule la mani?re forte pourra nous sauver !  \\n \\nAidez-moi ? les calmer ! S\\\'il vous pla?t...  \\nLa r?compense en vaudra la chandelle !');
INSERT INTO `npc_questions` VALUES (648, '', '', '', '', 'J\\\'ai depuis longtemps la recette d\\\'un oubli, grav? sur un arc pour ne pas l\\\'oublier. Tenez la voici : \\nOubli de fl?che magique : 4 bois ?lastiques, 5 Anneaux du mental, 10 arcs de cristal pur, 1 eau. \\nJ\\\'esp?re que cela pourra vous aider.');
INSERT INTO `npc_questions` VALUES (652, '', '', '', '', 'Nous avons la recette qu\\\'aucun Enutrof n\\\'utilisera jamais, alors je te la donne volontiers : \\nOubli de Chance : 3 vieux tr?fles ? 4 feuilles, 70 tr?fles ? 5 feuilles, 30 amulettes de krokette \\nAmusant non ? \\n');
INSERT INTO `npc_questions` VALUES (655, '', '', '', '', 'Pardonnez-moi, j\\\'avais mal saisi vos intentions, veuillez accepter en guise d\\\'excuse cette recette : \\nOubli d\\\'Intimidation : 4 silex sanglants, 50 silex, 25 ?p?es du puissant chevalier, 40 argent.');
INSERT INTO `npc_questions` VALUES (657, '', '', '', '', 'Vous songez ? vous marier ? Voil? une nouvelle qui emplit le coeur des Dieux d\\\'Amakna. Pour vous unir par les liens sacr?s et INDESTRUCTIBLES, il faut vous pr?senter tous les deux, habill?s de circonstance et obligatoirement munis de vos alliances. Je c?l?brerai votre union et apr?s l\\\'?change des anneaux, VOUS SEREZ UNIS A TOUT JAMAIS. Car telle est la volont? de nos Dieux.');
INSERT INTO `npc_questions` VALUES (658, '', '', '', '', 'Non ! La mort, surtout d?clench?e ou simul?e, NE PERMET PAS de rompre les liens indestructibles du mariage ! Comment ce n\\\'?tait pas la question ? ah bon ! \\nPour les obs?ques, la maison ne prend rien en charge.  Alors quand vous mourrez : dirigez-vous vers le cimeti?re et trouvez une tombe. Enterrez-vous et les cieux vous enterreront !');
INSERT INTO `npc_questions` VALUES (659, '', '', '', '', 'Je peux vous fabriquer une alliance de mariage, mais pour cela il me faudrait 25 p?pites d\\\'or et 1000 kamas.');
INSERT INTO `npc_questions` VALUES (660, '564', '', '', '0', 'Sur ta route tu rencontreras de nombreuses portes closes, si certaines renferment des cr?atures qu\\\'il ne vaut mieux pas r?veiller, d\\\'autres pourraient te rendre riche et vaillant. \\n \\nLa porte qui se trouve derri?re moi est un donjon d\\\'entra?nement, j\\\'y ai plac? quelques troupeaux de Bouftous, mais pour rentrer il te faudra trouver une cl? que j\\\'ai cach?e sur un de leurs cong?n?res.');
INSERT INTO `npc_questions` VALUES (662, '598', '', '', '0', 'Oh ! Quelqu\\\'un.... Vas-t\\\'en ! Non, viens l? !... Comment t\\\'appelles-tu ? Moi, ?a fait 5 ans et toi ? \\n \\nPourquoi me regardes-tu comme ?a ? J\\\'ai perdu la m?moire, mais je ne me souviens plus comment... commandant Chaferfu, mon capitaine ! J\\\'ai un secret, veux-tu le conna?tre ?');
INSERT INTO `npc_questions` VALUES (663, '', '', '', '', 'Je peux te procurer des Puissants Parchemins de Sagesse, pour cela, je te demande de me ramener 90 Champignons, 75 Graines de Tournesol, 60 Graines de Chanvre ainsi que 200 Ailes de Moskito.');
INSERT INTO `npc_questions` VALUES (664, '573;572;571;574', '', '', '0', 'Depuis que la brise quadramentale a souffl? sur notre monde, beaucoup de choses ont chang?. Petit ? petit, nous commen?ons ? dominer cette nouvelle puissance qui nous est offerte. Bient?t nous la ma?triserons et alors !... Mais parlons plut?t de ce qui vous am?ne ici.');
INSERT INTO `npc_questions` VALUES (665, '', '', '', '', 'Hel Munster c\\\'est moi. Beaucoup de monde s\\\'amuse ? associer mon nom avec la qualit? de meilleur magicien d\\\'Amakna, je ne suis pourtant qu\\\'un humble chercheur qui gravite autour de tout ce qui touche ? la magie. Et en mati?re de recherches je n\\\'ai jamais eu autant de boulot que ces derni?res semaines.');
INSERT INTO `npc_questions` VALUES (666, '2909;2910;2911;2912;2914;2915;2916;2918;2919;2920;2921;2922', '', '', '0', 'Je conc?de ? enseigner les bases de la cr?ation d\\\'?quipements magiques uniquement si deux conditions sont remplies: \\n-il faut tout d\\\'abord ma?triser la fabrication des ?quipements normaux. \\n-il faut ensuite me prouver que l\\\'on m?rite mon enseignement.');
INSERT INTO `npc_questions` VALUES (667, '575;576', '', '', '0', 'Les M?tarias sont des condens?s d\\\'?l?mentaires enrob?s d\\\'une fine membrane ? haut coefficient d\\\'imperm?abilit? ? la magie. Je les ai d?couvertes par hasard, lors d\\\'une joute contre un dragoeuf. Apr?s quelques recherches, j\\\'ai r?ussi ? percer leurs myst?res.');
INSERT INTO `npc_questions` VALUES (668, '', '', '', '', 'Selon la l?gende populaire, cette for?t est ? ?viter ? tout prix. Le sombre myst?re teint? de sang qu\\\'elle renferme suscite les plus grandes peurs. Mais je ne partage gu?re ce point de vue. Cette for?t est pour moi un d?lice de magies en tout genre, d\\\'odeurs enchanteresses et de bruits f??riques. J\\\'ai depuis longtemps perc? son myst?re, mais je n\\\'en parlerai pas. Tout comme je ne prendrais parti pour quelqu\\\'un. Je peux cependant vous vendre un livre qui vous narrera la l?gende de la for?t.');
INSERT INTO `npc_questions` VALUES (669, '', '', '', '', 'Deux possibilit?s: \\n-trouver des M?tarias ? l\\\'?tat naturel dans les entrailles d\\\'un monstre. \\n-les fabriquer gr?ce ? un compresseur de mon invention, en utilisant des ressources ? fort potentiel ?l?mentaire, et une sph?re de r?sistance que je vends ? un prix d?risoire. Toutes les recettes sont ?crites dans un livre que je peux vous fournir.');
INSERT INTO `npc_questions` VALUES (670, '', '', '', '', 'Les M?tarias sont une mati?re ? l\\\'?tat brut. Travaill?es par un alchimiste, elles donneront des potions ?l?mentaires puissantes qui vont permettre d\\\'impr?gner certains objets d\\\'un ?l?ment. Mes derniers travaux montrent l\\\'efficacit? de cette m?thode sur des armes, mais aussi la difficult? de m?langer le r?el et le magique. C\\\'est pourquoi j\\\'ai d?velopp? une m?thode pour y parvenir et que j\\\'enseigne ? certaines personnes.');
INSERT INTO `npc_questions` VALUES (671, '', '', '', '', 'Je vois que vous ?tes assez dou?. Tr?s bien, si vous d?sirez suivre mon enseignement il va vous falloir tout d\\\'abord trouver puis ?tudier une cr?ation aux pouvoirs magiques extraordinaires. Ensuite vous m\\\'apporterez une preuve de cette ?tude. Je vous nomme donc apprenti Cr?ateurmage. Une fois vos preuves faites je vous donnerai le mat?riel n?cessaire ? la cr?ation d\\\'armes magiques.');
INSERT INTO `npc_questions` VALUES (672, '', '', '', '', 'Un fragment du socle de l\\\'arme la plus magique que je connaisse. Ce bout de pierre est uniquement impr?gn? de l\\\'essence magique de l\\\'arme et permet donc son ?tude sans subir les fluctuations du mat?riel en lui m?me. \\nVous avez brillamment r?ussi l\\\'?preuve, voici un outil magique qui permettra vos cr?ations magiques. Ainsi qu\\\'un petit livre, sorte d\\\'aide-m?moire pour tous les cr?ateurs d\\\'armes magiques. \\n');
INSERT INTO `npc_questions` VALUES (673, '', '', '', '', 'Vous d?sirez un autre outil magique ? \\nTr?s bien je veux bien vous en vendre un pour un prix raisonnable. 2000 Kamas et il est ? vous !');
INSERT INTO `npc_questions` VALUES (674, '599;600', '', '', '0', 'Qui t\\\'as dit que j\\\'avais un secret ! Tu m\\\'espionnes, hein ! Tu voudrais bien conna?tre le secret de l\\\'invocation de Chaferfu. C\\\'est ?a que tu veux !');
INSERT INTO `npc_questions` VALUES (675, '602;601', '', '', '0', 'Voil? tu connais l\\\'invocation du point de croix ! Ah, non ! C\\\'est l\\\'invocation du Chaferfu... Chaferfu a dit : Dites \\\" Bonjour ! \\\".');
INSERT INTO `npc_questions` VALUES (676, '', '', '', '', 'Apprendre quoi ? Tu veux apprendre le tricot ! Mais, moi je ne fais que de la broderie ! C\\\'est ?a mon secret... Veux-tu apprendre mon secret ?');
INSERT INTO `npc_questions` VALUES (677, '605', '', '', '0', 'F?licitations, vous avez r?ussi avec brio l\\\'?preuve de ce donjon. \\n \\nPour vous r?compenser, je vous offre cet animal de compagnie, il pourrait vous ?tre tr?s utile dans votre qu?te.');
INSERT INTO `npc_questions` VALUES (678, '608', '', '', '0', 'Que voulez-vous ? ');
INSERT INTO `npc_questions` VALUES (679, '', '', '', '', 'Effectivement,  les tomes Annexes de l\\\'Encyclop?die d\\\'Alchimie sont introuvables. Non seulement ?a, mais aussi les r??ditions qui sont cens?es nous parvenir. Les rumeurs affirment que les pr?cieux manuscrits sont vol?s discr?tement. Nul doute que ces voleurs doivent en avoir une certaine utilit?, mais laquelle ?');
INSERT INTO `npc_questions` VALUES (680, '', '', '', '', 'Cherchez un peu, le test perdrait de sa valeur sinon.  Pour la preuve ? me rapporter : ne d?gradez pas la cr?ation, jamais ! Vous pouvez par contre vous int?resser ? son support. Un morceau de cuir du fourreau d\\\'une ?p?e, un fragment du socle d\\\'un vase... la t?che est grande, mais pas impossible. C\\\'est un peu comme chercher une aiguille x?lor dans une toile d\\\'arakne voleuse, souvenez-vous en !');
INSERT INTO `npc_questions` VALUES (681, '618', '', '', '0', 'Moi, Don Rouann, suis tellement attrist?\\nDe voir tant de personnes ainsi\\nHeureuses, car ignorantes de l\\\'oubli\\nD\\\'une chose essentielle, voire une n?cessit');
INSERT INTO `npc_questions` VALUES (682, '619', '', '', '0', 'Un espoir vint alors m\\\'?clairer.\\nEn votre personne qui cherche ? comprendre,\\nA vous ce secret je veux bien l\\\'enseigner,\\nOui ? vous je veux bien vous l\\\'apprendre.');
INSERT INTO `npc_questions` VALUES (683, '620', '', '', '0', '3 ?tapes, il vous faudra franchir. \\nComme autant de sujets de m?ditation \\nLa premi?re est un acte de motivation, \\nLe courage qui vous emp?chera de fuir.');
INSERT INTO `npc_questions` VALUES (684, '', '', '', '', 'Chercher donc un objet fort d\\\'un symbole \\nDe puissance, de grandeur et de vanit? \\nDe protection on peut lui donner le r?le \\nA la mer vous devrez l\\\'arracher');
INSERT INTO `npc_questions` VALUES (685, '', '', '', '', 'Voil? une Ic?ne que je v?n?re particuli?rement \\nVotre esprit s\\\'est ?lev? ? pr?sent \\nMaintenant il vous faut travailler votre communication \\nQui sera essentielle ? cette communion');
INSERT INTO `npc_questions` VALUES (686, '', '', '', '', 'R?pondez ? ces 3 questions \\nUniquement par des affirmations. \\nLa premi?re est la plus facile, \\nPour son amour combien d?penser de mille ?');
INSERT INTO `npc_questions` VALUES (687, '', '', '', '', 'Et voil? la seconde question, \\nD\\\'apr?s vous comment se mesure l\\\'attention \\nAu sein d\\\'un couple amoureux, \\nEn terme de quantit? se sera mieux.');
INSERT INTO `npc_questions` VALUES (688, '', '', '', '', 'Et voil? la seconde question, \\nD\\\'apr?s vous comment se mesure l\\\'attention \\nAu sein d\\\'un couple amoureux, \\nEn terme de quantit? se sera mieux.');
INSERT INTO `npc_questions` VALUES (689, '', '', '', '', 'Voici l\\\'ultime interrogation, \\nPuis nous ?valuerons la situation. \\nInteressons nous aux petits calins, \\nLe soir, le midi, ou le matin ? \\n');
INSERT INTO `npc_questions` VALUES (690, '636', '', '', '', 'Ces fameuses bottes us?es, sont vraiment en mauvais ?tat, mais un cordonnier tr?s habile devrait pouvoir leur redonner leur puissance d\\\'origine et leur caract?re particulier.');
INSERT INTO `npc_questions` VALUES (691, '', '', '', '', 'Voici l\\\'ultime interrogation, \\nPuis nous ?valuerons la situation. \\nInteressons nous aux petits calins, \\nLe soir, le midi, ou le matin ? \\n');
INSERT INTO `npc_questions` VALUES (692, '', '', '', '', 'La deception s\\\'abat sur moi \\nCette ?preuve vous est fatale \\n');
INSERT INTO `npc_questions` VALUES (693, '', '', '', '', 'Hogmeiser a perdu ses bottes lors d\\\'un terrible combat contre un Chef de Guerre Bouftou, le jour de la F?te du Slip du  Captain Chafer, alors qu\\\'il ?tait sous l\\\'emprise de substances aux effets peu communs.\\nIl s\\\'est r?veill? le lendemain matin, tout nu au milieu des mar?cages, sans ses bottes.');
INSERT INTO `npc_questions` VALUES (694, '', '', '', '', 'Je tiens ? vous faire mes hommages. \\nEnfin quelqu\\\'un comprenant le message, \\nNul chose en amour n\\\'est d?termin?e, \\nA chacun de choisir sa destin?e.');
INSERT INTO `npc_questions` VALUES (695, '', '', '', '', 'Il vous suffira juste de m?diter. \\nA l\\\'heure nulle vous reviendrez. \\nCette heure secrete qui vaut bien un baiser, \\nLa patience sera votre alli?e.');
INSERT INTO `npc_questions` VALUES (696, '', '', '', '', 'La joie m\\\'inonde de larmes, \\nEt ce, uniquement gr?ce ? vous. \\nLa graine de connaissance s\\\'est log?e dans votre ?me, \\nVoici le secret attendu, il s\\\'agit du \\\"Bisous\\\"...');
INSERT INTO `npc_questions` VALUES (697, '', '', '', '', 'Je peux vous fournir un stock de 100 ficelles classiques si vous me donnez  100 unit?s de Lin.');
INSERT INTO `npc_questions` VALUES (701, '', '', '', '', 'Avant de sortir de ce temple, adresse toi ? mon fr?re Tarazed, il t\\\'apprendra un moyen pour te gu?rir par la m?ditation. \\nSi tu n\\\'es pas assez patient, il faudra te soigner gr?ce aux pains vendus par les boulangers, ou par les potions fabriqu?es par les alchimistes.  \\nN\\\'oublie pas d\\\'?conomiser quelques kamas pour en acheter.');
INSERT INTO `npc_questions` VALUES (702, '', '', '', '', 'Je vois que tu ma?trises d?j? la m?ditation curative, je n\\\'ai donc plus rien ? t\\\'apprendre. \\nTu devrais ?tre capable de te d?brouiller seul, d?sormais.');
INSERT INTO `npc_questions` VALUES (710, '', '', '', '', 'Alerte ! Un d?mon est entr? dans Bonta ! Mais que fait la milice ?.... J\\\'oubliais, c\\\'est moi la milice.');
INSERT INTO `npc_questions` VALUES (711, '664', '', '', '0', 'Bonjour jeune aventurier, je suis le ma?tre d\\\'arme de la milice de Bonta. \\n \\nSi tu veux rejoindre les rangs de la milice, aide-moi ? r?cup?rer quelques ?p?es de boisaille pour entra?ner mes gars. Il faudrait aller m\\\'en chercher une dizaine dans le quartier des forgerons, ? l\\\'Est de la ville. ');
INSERT INTO `npc_questions` VALUES (712, '', '', '', '', 'Les t?cherons que j\\\'entra?ne en ce moment ne sont pas tr?s brillants... Ca te dirait de me montrer ce que tu vaux en combat ?');
INSERT INTO `npc_questions` VALUES (713, '', '', '', '', 'Tu vas peut-?tre pouvoir m\\\'aider ? nouveau. Il para?t que Dame Cloude, la tenanci?re de la taverne de la Bagrutte, au nord-ouest de la ville, se fait harceler par un ivrogne ces temps-ci. Tu pourrais aller la voir et te renseigner sur ce qui s\\\'est pass? ?');
INSERT INTO `npc_questions` VALUES (714, '', '', '', '', 'Je n\\\'ai plus de temps ?  t\\\'accorder aujourd\\\'hui, mais.... Par contre si tu veux te rendre utile, tu peux aller me chercher 20 pains au bl? complet, y\\\'a mes petits gars qui se chopent une fringale. Nous ne sommes pas loin du quartier des boulangers, tu en trouveras s?rement l?-bas.');
INSERT INTO `npc_questions` VALUES (715, '', '', '', '', 'Pour me rattraper, j\\\'ai une mission un peu plus int?ressante pour toi. \\nMon ami Ned est persuad? de faire des prouesses dans le domaine des soins dentaires, il lui faudrait juste des dents de rechange pour faire un dentier complet. \\nJe pense que tu peux t\\\'occuper de ?a, non ?');
INSERT INTO `npc_questions` VALUES (716, '', '', '', '', 'Tu me restes fid?le jeune recrue, voil? une chose que tu ne regretteras pas. Je vais ? nouveau te mettre ? l\\\'?preuve. Je te propose un petit entra?nement avec le milicien Torche. Quand il a vu les nouvelles dents de son fr?re Tarche, je lui ai dit que c\\\'?tait toi qui te chargeais de les enlever. Ai-je bien fait ?');
INSERT INTO `npc_questions` VALUES (717, '', '', '', '', 'Salut petit scarafeuille, j\\\'esp?re que tu n\\\'as pas de trous dans tes bottes, car tu vas devoir t\\\'en servir : Je prends toujours une bi?re chez un coll?gue tavernier vers l\\\'est de la ville. J\\\'aime profiter de ce moment de d?tente pour ?changer quelques cartes sp?ciales avec lui. Il m\\\'en doit une depuis notre derni?re rencontre, tu peux y aller pour moi ?');
INSERT INTO `npc_questions` VALUES (718, '', '', '', '', 'Un corbac a vol? le collier de la fille du maire ce matin. \\nIl doit certainement tra?ner du c?t? de la tour de Bonta, je sais que ce n\\\'est pas une mission tr?s reluisante, mais la jeunette a tellement insist?...  \\n?tant donn? que tous mes hommes sont occup?s, montre-moi que tu es plus fort qu\\\'un corbac et rapporte-moi ce collier, hahaha.');
INSERT INTO `npc_questions` VALUES (719, '', '', '', '', 'Apparemment Torche n\\\'?tait pas ? son poste la derni?re fois que tu l\\\'as affront?. Pour me rendre service, il faudrait que tu fasses le tour des tavernes pour m\\\'apporter la liste des miliciens fain?ants dans son genre. \\nDis-leur que tu fais un recensement, et que tu dois r?cup?rer leurs badges jusqu\\\'? ce soir.');
INSERT INTO `npc_questions` VALUES (720, '', '', '', '', 'Bon #1, tu as fait preuve de bravoure jusqu\\\'? maintenant. J\\\'ai une mission plus p?rilleuse pour toi, il faut que tu ailles explorer Br?kmar, mais ne te fais pas surprendre. \\nExamine le fonctionnement des engrenages de la porte de leur ville. Toutes les informations nous seront utiles. Ne reviens pas tant que tu n\\\'es pas s?r d\\\'avoir trouv? quelque chose...');
INSERT INTO `npc_questions` VALUES (721, '', '', '', '', 'D\\\'apr?s tes derni?res informations, je pense avoir trouv? un moyen de saboter la porte de Br?kmar. Je vais aller en parler ? mes sup?rieurs. Je te remercie.');
INSERT INTO `npc_questions` VALUES (722, '', '', '', '', 'Me voici de retour #1, mes sup?rieurs te f?licitent. \\nCette semaine j\\\'apprends le maniement du b?ton ? mes hommes, il me faudrait une vingtaine de b?tons de boisaille, je sais que tu as des connaissances chez des sculpteurs. \\nPrends ton temps je n\\\'en ai besoin que dans plusieurs jours.');
INSERT INTO `npc_questions` VALUES (723, '', '', '', '', 'Le tavernier de la Tabasse a aussi une dette envers moi, j\\\'aimerais que tu ailles lui r?clamer. N\\\'h?site pas ? user de la force s\\\'il le faut, car ce coquin a toujours de bonnes excuses pour ne pas payer. \\nCes 100000 kamas devraient permettre de refaire la lame de mon katana, ?a co?te une petite fortune.');
INSERT INTO `npc_questions` VALUES (724, '', '', '', '', 'Nous avons un agent double dans les rangs de la milice de Br?kmar il se nomme Bishom Pot, infiltre-toi l? bas et demande-lui les informations que je lui ai command?es. \\nPour le contacter, il te suffira de lui dire : \\\"Br?kmar est une ville putride en cette saison\\\".');
INSERT INTO `npc_questions` VALUES (725, '', '', '', '', 'Va n?gocier de la poudre ? Moub Reicifitra, nos nouveaux canons sont sortis de l\\\'entrep?t et nous devons les essayer lors de notre prochain assaut de Br?kmar. \\nCe sera ? tes frais cette fois, donc fait preuve de tact pour le prix d\\\'achat, il m\\\'en faut pour une dizaine de pods.');
INSERT INTO `npc_questions` VALUES (726, '', '', '', '', 'Je n\\\'ai plus rien pour toi cette fois-ci, demande aux gardes ? l\\\'entr?e il para?t qu\\\'ils ont besoin d\\\'un coup de main.');
INSERT INTO `npc_questions` VALUES (727, '', '', '', '', 'Si tu veux un jour faire partie de l\\\'?lite de la milice essaye donc de tuer des chafers d\\\'?lite. \\nLes Br?kmariens utilisent des Chafers lors de leurs assauts, et il est vital de conna?tre leurs faiblesses. \\nRam?ne-moi 15 casques de chafer pour me prouver tes exploits.');
INSERT INTO `npc_questions` VALUES (728, '', '', '', '', 'J\\\'ai 4 caisses d\\\'armes blanches ? transf?rer ? l\\\'avant-poste de Bonta, au Sud. \\nAttention, elles p?sent chacune dans les 500 pods, tu vas devoir faire des aller-retours.');
INSERT INTO `npc_questions` VALUES (729, '', '', '', '', 'Y\\\'a un type qui tient une foire dans les plaines, j\\\'aimerais que tu inspectes si ce n\\\'est pas une ruse de l\\\'ennemi pour cacher un campement pr?s de Bonta. \\n \\nVa parler ? Ture Inge, il fabrique des tests infaillibles pour d?tecter les Br?kmariens.');
INSERT INTO `npc_questions` VALUES (730, '', '', '', '', '____J\\\'ai une mission p?rilleuse pour toi. Il s\\\'agit de prot?ger un des paysans qui travaille au sud d\\\'Amakna. Les bworks qui pullulent dans ce coin-l? ne sont pas des tendres et risquent de l\\\'attaquer. \\n \\n? charge pour toi, d\\\'assurer la protection du paysan. Je d?teste faire l\\\'oiseau de mauvais augure. S\\\'il meurt, ce sera ? toi d\\\'aller l\\\'annoncer ? sa famille.');
INSERT INTO `npc_questions` VALUES (731, '', '', '', '', 'Une voyante m\\\'a r?v?l? ce matin que le capitaine Tsog avait des informations de la plus haute importance ? me r?v?ler avant de mourir. \\nTrouve un moyen de rentrer en communication avec lui au cimeti?re ? l\\\'est de Bonta et ram?ne-moi ces derniers mots. \\nDemande au Capitaine Alrok si tu veux plus d\\\'informations sur l\\\'emplacement de sa tombe.');
INSERT INTO `npc_questions` VALUES (732, '', '', '', '', 'Tu as d?sormais suffisamment d\\\'exp?rience dans la milice pour choisir une sp?cialit?, adresse-toi au ma?tre des ordres si cela t\\\'int?resse. \\nSinon j\\\'ai un petit service ? te demander, il me faudrait une vingtaine d\\\'anneaux d\\\'agilit?, je vais essayer d\\\'en mettre deux par doigt pour voir si c\\\'est efficace !');
INSERT INTO `npc_questions` VALUES (733, '', '', '', '', 'Hier, nous avons subi une d?faite terrible contre Br?kmar, ils ont utilis? une invocation inconnue jusqu\\\'alors. \\nJ\\\'aimerais que tu te renseignes sur cette cr?ature aupr?s de Zeurg le ma?tre de classe des Osamodas, il a toujours de tr?s bons conseils ? ce sujet.');
INSERT INTO `npc_questions` VALUES (734, '', '', '', '', 'Aujourd\\\'hui est un jour particuli?rement agr?able.');
INSERT INTO `npc_questions` VALUES (735, '', '', '', '', 'C\\\'est ton jour de chance mon ami. Tu es de corv?e de patate ! \\nTu y as ?chapp? jusque maintenant, mais cette fois-ci tu n\\\'y ?chapperas pas. \\nRam?ne 200 pods de patate ?pluch?s au cuisinier !');
INSERT INTO `npc_questions` VALUES (736, '', '', '', '', 'Un colonel de la milice a ?t? transform? en abraknyde, lors d\\\'un voyage vers le port d\\\'Amakna. \\nJe pense qu\\\'il a ?t? captur? et qu\\\'il se trouve dans la partie Est de la for?t des abraknydes. Ram?ne-le ? la tour des mages de Bonta pour qu\\\'on lui fasse retrouver sa forme humaine.');
INSERT INTO `npc_questions` VALUES (737, '', '', '', '', 'J\\\'ai parl? de toi ? Danathor, l\\\'intendant de Bonta il y a quelque temps, et il d?sire te rencontrer. J\\\'ignore pourquoi, je suppose qu\\\'il a un service ? te demander ou quelque chose ? t\\\'offrir...');
INSERT INTO `npc_questions` VALUES (738, '', '', '', '', 'Mon ami Rimaraf est d?c?d? cette nuit dans des circonstances ?tranges, il a ?t? empoisonn? avec un Blopisier au scorbute. \\nJ\\\'aimerais que tu enqu?tes et que tu me trouves le coupable ! ');
INSERT INTO `npc_questions` VALUES (739, '', '', '', '', 'Mon tabi n\\\'a pas la forme en ce moment.\\nUn bon repas lui ferait du bien, son plat favori consiste ? concasser 4 fleurs de blop diff?rentes.\\nAllez #1 un peu d\\\'exercice contre des blops te fera du bien !');
INSERT INTO `npc_questions` VALUES (740, '', '', '', '', 'Mon neveu Dike Tarak, s\\\'amuse souvent dans le quartier nord, fait expr?s de perdre contre lui, ?a lui fera plaisir, et s\\\'il est heureux... je le suis aussi. Tu piges ?');
INSERT INTO `npc_questions` VALUES (741, '', '', '', '', 'Je n\\\'ai pas vraiment le moral pour le moment. \\nDemande au Capitaine Essacarf s\\\'il a besoin d\\\'aide...');
INSERT INTO `npc_questions` VALUES (742, '', '', '', '', 'Mon neveu est tout fier de t\\\'avoir battu, il m\\\'a bien fait rire. \\nPar contre, il m\\\'a dit que des amis ? lui allaient faire des choses pas tr?s bontariennes dans le quartier des boulangers, j\\\'aimerais que tu ailles faire une petite inspection pour mettre de l\\\'ordre dans tout ?a !');
INSERT INTO `npc_questions` VALUES (743, '', '', '', '', 'Tu vas devoir effectuer une mission de reconnaissance, il va falloir explorer le cimeti?re des Tortur?s ? l\\\'Est de Br?kmar, pr?viens moi quand tu seras pr?t ? partir.');
INSERT INTO `npc_questions` VALUES (744, '', '', '', '', 'Nous avons besoin de main d\\\'oeuvre pour construire une extension au b?timent de la milice, il me reste deux boulots ? te proposer, choisis-en un et je donnerais l\\\'autre ? Torche. \\nTout d\\\'abord, si tu te sens l\\\'?me d\\\'un coupeur de bois, il nous faut une vingtaine de planches de fr?ne pour fabriquer le plancher. \\nSinon, si tu as envie d\\\'un peu plus d\\\'action, il me faudrait une dizaine de racines d\\\'abraknyde pour construire les jonctions entre les poutres.');
INSERT INTO `npc_questions` VALUES (745, '', '', '', '', 'Je n\\\'ai pas une minute de r?pit avec toi, ? peine t\\\'ai-je donn? une mission que tu m\\\'en r?clames une autre. \\nPour l\\\'instant je n\\\'ai rien ? te proposer, par contre j\\\'ai re?u une lettre pour toi.');
INSERT INTO `npc_questions` VALUES (746, '', '', '', '', 'Ne me d?range pas pour le moment, je suis en pleine m?ditation.');
INSERT INTO `npc_questions` VALUES (747, '', '', '', '', 'Pour affaiblir l\\\'?conomie de Br?kmar, nous avons d?cid? de les attaquer sans rel?che. Tous les miliciens devront m\\\'apporter 10 badges Br?kmariens pour me prouver leur valeur au combat !');
INSERT INTO `npc_questions` VALUES (748, '', '', '', '', 'Le cuisinier ?tait content de toi la derni?re fois, il a encore un plat particulier ? r?aliser aujourd\\\'hui, et je crois qu\\\'il a besoin de toi.');
INSERT INTO `npc_questions` VALUES (749, '', '', '', '', 'William Lenglad commence ? saouler s?rieusement les habitants de la cit?, va lui mettre une racl?e, ? lui et son groupe, pour me faire plaisir. \\nIl se trouve ? l\\\'Ouest de Bonta.');
INSERT INTO `npc_questions` VALUES (750, '', '', '', '', 'Le milicien Hou? Dapyus a ?t? captur? ce midi, alors qu\\\'il faisait une reconnaissance pr?s de Br?kmar, il faut que tu ailles dans le b?timent de leur milice pour le d?livrer.');
INSERT INTO `npc_questions` VALUES (751, '', '[name]', '', '0', 'Une nouvelle race de rat est apparue dans les ?gouts de notre ville, on les reconnait facilement par leur couleur verte et leur odeur naus?abonde...\\nPour lutter contre leur prolif?ration, nous avons d?cid? de demander ? chaque soldat d\\\'en tuer 4, tu sais donc ce qu\\\'il te reste ? faire #1...');
INSERT INTO `npc_questions` VALUES (752, '', '', '', '', 'Je vais bient?t avoir ? nouveau besoin de toi. Entraine-toi bien pour ?tre en forme le moment venu.');
INSERT INTO `npc_questions` VALUES (753, '', '', '', '', 'J\\\'ai une enqu?te ? te donner : il faut chercher des informations sur AncestralZ. C\\\'est un pseudo justicier masqu? qui pr?tend faire la loi, mais la loi ici c\\\'est moi.\\nAdresse toi ? tous les habitants de Bonta et trouve qui est cette ordure.\\n\\n(L\\\'un d\\\'entre eux ment et d\\\'autres le couvrent, le but est de trouver le bon.)');
INSERT INTO `npc_questions` VALUES (754, '', '', '', '', 'Tu connais le ma?tre corbac? J\\\'aimerais que tu lui piques sa faux, je voudrais tester si elle coupe mieux que mon sabre.\\nComment ?a j\\\'abuse de mon autorit? ? Au travail #1 !');
INSERT INTO `npc_questions` VALUES (755, '', '', '', '', '');
INSERT INTO `npc_questions` VALUES (756, '', '', '', '', 'Tu te souviens du prisonnier que tu as delivr? ? \\nIl est sur pied et d?sire pourfendre des squelettes avec toi !');
INSERT INTO `npc_questions` VALUES (757, '', '', '', '', 'Pour montrer ton d?vouement ? la milice tu vas devoir trouver deux jeunes recrues, leurs donner ce coupon et leur dire de venir s\\\'inscrire ? la milice, en venant me voir.');
INSERT INTO `npc_questions` VALUES (758, '', '', '', '', 'Ram?ne moi 100 bandeaux, c\\\'est pour une troupe d\\\'?lite qui part au nord dans des r?gions qu\\\'il ne vaut mieux pas que tu connaisses pour le moment.');
INSERT INTO `npc_questions` VALUES (759, '', '', '', '', 'Bon #1, un petit test de connaissance sur l\\\'art de la tactique, voir si tu m?rite mon estime. \\nSi tu ?choue tu seras de nouveau de corv?e de patate haha !');
INSERT INTO `npc_questions` VALUES (760, '', '', '', '', 'Depuis bient?t 100 ans, nous avons abandonn? le cimeti?re de Bonta de l\\\'Est. Depuis de nombreuses cr?atures se sont inflitr?es dans ses murs. \\nIl y en a une qui est particuli?rement corriace : la momie Nova. \\nPrend ?a comme une ?preuve, mais si tu me ram?nes des morceaux de ses bandages, je te nommerais officier de la milice de Bonta.');
INSERT INTO `npc_questions` VALUES (761, '', '', '', '', 'Je n\\\'ai plus de mission pour toi avant un petit moment #1, reviens me voir ? la prochaine mise ? jour de nos effectifs....');
INSERT INTO `npc_questions` VALUES (762, '', '', '', '', 'Ah #1 je t\\\'attendais, je dois entra?ner mes gars demain, et avec le soleil de plomb qu\\\'il y a en ce moment, j\\\'aimerais que tu me trouves un champo de taille respectable, pour pouvoir rester ? l\\\'ombre.');
