INSERT INTO `npc_questions` VALUES (811, '728', '', '', '', 'Haha, une ?me innocente dans ces lieux, si tu veux faire partie des n?tres, ram?ne-moi 10 dagues de boisailles, je dois entra?ner mes gus demain.');
INSERT INTO `npc_questions` VALUES (812, '', '', '', '', 'Les chafers sont fort utiles comme premi?re ligne dans les batailles contre Bonta, mais on ne peut pas dire qu\\\'ils excellent au combat. \\nD\\\'ailleurs, va donc te battre avec Mak que je vois un peu ton habilet? contre un chafer. Si tu perds contre ce tas d\\\'os je saurais ? quoi m\\\'en tenir.');
INSERT INTO `npc_questions` VALUES (813, '', '', '', '', 'Le patron de la taverne du Chabrul? a ?t? ?gorg? la nuit derni?re, essaye de savoir qui l\\\'a tu? et ram?ne-moi son nom ! \\nJe voudrais le f?liciter et l\\\'engager comme assassin, il a fait un boulot tr?s propre.');
INSERT INTO `npc_questions` VALUES (814, '', '', '', '', 'Nous avons subi une dure d?faite aujourd\\\'hui, tous les hommes sont fatigu?s et souffrants. \\nHummm, tout compte fait  tu pourrais peut-?tre me servir... \\nVa chercher des potions Pahoa Raide ? un alchimiste, y\\\'en a trois qui risquent de ne pas passer la nuit sinon.');
INSERT INTO `npc_questions` VALUES (815, '', '', '', '', 'J\\\'ai une mission amusante ? te donner, le but est d\\\'arracher des dents ? des bouftous.  \\nVa demander au boucher Bout d\\\'chair il t\\\'expliquera, comment faire. \\nQuand t\\\'en auras suffisamment pour faire un dentier. Ram?ne-les-moi, ?a me servira pour rafistoler un incapable. \\nNe m\\\'en ram?ne pas trop ! S\\\'amuser c\\\'est bien mais il faut savoir s\\\'arr?ter ! Gare ? toi si tu m\\\'en ram?nes trop.');
INSERT INTO `npc_questions` VALUES (816, '', '', '', '', 'Maintenant qu\\\'il a retrouv? des dents, Mak veut prendre sa revanche, il est toujours aussi t?tu, enfin bref, avec ses nouvelles dents et son ?quipement flambant neuf il compte bien te mettre une d?rouill?e ! Accepte, je veux voir tes progr?s depuis ton dernier combat.');
INSERT INTO `npc_questions` VALUES (817, '', '', '', '', 'On a cass? beaucoup d\\\'armes ? l\\\'entra?nement des recrues. Beaucoup de cr?nes aussi, mais c\\\'est moins important. Les nouveaux stocks sont arriv?s, va me les chercher ? la Tour. Il doit y avoir 10 caisses en tout.');
INSERT INTO `npc_questions` VALUES (818, '', '', '', '', 'Un ?cureuil a vol? la cl? de la salle du Prisme de Br?kmar, ne me demande pas pourquoi ni comment, mais plusieurs soldats l\\\'ont vu. \\nSi on ne la retrouve pas, tu risques la pendaison, tu vois o? je veux en venir.... ? \\nJ\\\'ai d?j? des gardes qui surveillent le pont, l\\\'?cureuil ne peut pas s\\\'?chapper !');
INSERT INTO `npc_questions` VALUES (819, '', '', '', '', 'J\\\'ai appris que certains de mes soldats n\\\'allaient pas boire ? la taverne pendant leurs heures de garde. \\nTrouve-moi le nom des idiots, qui ne vont jamais prendre de pause ! ');
INSERT INTO `npc_questions` VALUES (820, '', '', '', '', 'Ton travail me satisfait pleinement que veux-tu d\\\'autre ?');
INSERT INTO `npc_questions` VALUES (821, '', '', '', '', 'Pour clouer le bec ? ces idiots de Bonta, nous allons tous nous entra?ner au marteau. \\nPar contre, nous sommes en rade, et si tu ne m\\\'am?nes pas quelques marteaux de boisaille, il y a 10 personnes qui ne vont pas participer ? l\\\'entra?nement... dont toi.');
INSERT INTO `npc_questions` VALUES (822, '', '', '', '', 'J\\\'ai un message ? faire transmettre ? Vil Smisse au cimeti?re d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (823, '', '', '', '', 'Nous avons un fourbe ? notre service dans la milice de Bonta, il se nomme Finche Aticus. \\nJe lui ai demand? de faire la liste des syst?mes de d?fense de Bonta, trouve-le et ram?ne-moi son rapport.');
INSERT INTO `npc_questions` VALUES (824, '', '', '', '', 'Notre r?serve de poison est ? sec, tu peux aller tuer quelques scorbutes pour r?cup?rer leur poison ?\\nEssaye d\\\'en ramener pour au moins 20 pods... Non ! R?ussis ? en ramener au moins 20 pods, o? on s\\\'occupera de toi, #1 !');
INSERT INTO `npc_questions` VALUES (825, '', '', '', '', 'Demande au garde qui est ? l\\\'entr?e si il a pas besoin d\\\'un coup de main, personnellement, je n\\\'ai rien ? te donner.');
INSERT INTO `npc_questions` VALUES (826, '', '', '', '', 'Y\\\'a des chafers un peu plus fut?s que les n?tres au cimeti?re, va en tabasser quelques-uns, et ram?ne-moi leurs casques d\\\'?lite, il m\\\'en faut une dizaine. Peut-?tre qu\\\'avec ?a, nos chafers survivront plus d\\\'une minute en combat...');
INSERT INTO `npc_questions` VALUES (827, '', '', '', '', 'Y\\\'a un loup enrag? qui r?de autour de la ville dans la fa?ade de Br?kmar, met lui une rouste, en esp?rant qu\\\'il ne revienne plus...');
INSERT INTO `npc_questions` VALUES (828, '', '', '', '', 'Ram?ne-moi une bouillie de Fleurs de Blop concass?es, j\\\'esp?re bien empoissonner le tabi de mon rival Amayiro en y associant un peu de poison de scorbute. \\nCet idiot ne lui donne que cette mixture, il devrait ?tre facile ? un de mes agents de la lui faire avaler.');
INSERT INTO `npc_questions` VALUES (829, '', '', '', '', 'Bon allez, dis ? ton ma?tre ce qu\\\'il s\\\'est pass');
INSERT INTO `npc_questions` VALUES (830, '', '', '', '', 'J\\\'ai nomm? 5 de mes meilleurs agents pour un raid sp?cial sur Bonta...Tu devines pourquoi h?h?. Dans tous les cas, il leur faut une cape br?kmarienne chacun, pour recouvrir le tabi et ainsi signer leur m?fait. Ram?ne-les-moi. On n\\\'a pas le temps de faire les boutiques avec la pr?paration psychologique que je leur fais subir.');
INSERT INTO `npc_questions` VALUES (831, '', '', '', '', 'J\\\'ai appris ce matin, qu\\\'on pouvait communiquer avec les morts quand on est transform? en esprit. \\nJ\\\'aimerais donc que tu te donnes la mort, et que tu essayes de retrouver le corps de mon p?re dans le cimeti?re de Br?kmar pour lui demander o? il a cach? son testament, ?a fait des ann?es que je le cherche ! \\nSa tombe se trouve au centre du cimeti?re, il doit encore y avoir une gerbe de fleurs devant...');
INSERT INTO `npc_questions` VALUES (832, '', '', '', '', 'Je n\\\'ai plus un sou, alors ne compte pas sur moi pour te donner une mission...');
INSERT INTO `npc_questions` VALUES (833, '', '', '', '', 'J\\\'ai maintenant un peu d\\\'argent de cot?, mais c\\\'est loin d\\\'?tre suffisant. Bon, une nouvelle taxe militaire payable en main propre vient de voir le jour. Elle s\\\'applique sur toutes les tavernes ? partir d\\\'aujourd\\\'hui. Et toi, mon nouveau r?colteur des imp?ts, tu vas aller la r?clamer pour moi.');
INSERT INTO `npc_questions` VALUES (834, '', '', '', '', 'Et bien, je me suis renflou? gr?ce ? toi ! Haha ! Ne nous arr?tons pas en si bon chemin, j\\\'ai une soudaine envie de richesse. Cela te dirait d\\\'aller voir la grande bijouti?re Azra Lazarus ? J\\\'ai entendu dire qu\\\'elle porte autour du cou un diamant vert nomm? le Poumon des plaines d\\\'une valeur inestimable...Rapporte-le-moi par n\\\'importe quel moyen... !');
INSERT INTO `npc_questions` VALUES (835, '', '', '', '', 'Grr, je suis en f?ch?. Les 3 t?tes ont eu vent de mes richesses et sont venues me d?pouiller. Je suis f?ch? et j\\\'ai faim ! Tiens tu sais qu\\\'on mange des patates au corbac ce midi ? \\nNon ? Hmm, pourtant c\\\'est toi qui les ?pluches, demande au cuistot comment faire, il aura peut-?tre besoin d\\\'un ou deux corbacs en plus, donc charge-toi de lui trouver. Et vite !');
INSERT INTO `npc_questions` VALUES (836, '', '', '', '', 'Bon #1, je vais te faire passer un petit test sur l\\\'art de la fourberie, voir si tu m?rites d\\\'?tre mon disciple.');
INSERT INTO `npc_questions` VALUES (837, '', '', '', '', 'AHAHAH, j\\\'ai entendu les cris de Sbab jusqu\\\'ici ahah ! Magnifique, tu es digne d\\\'?tre ? mes c?t?s. Tu pourrais m?me me faire de l\\\'ombre si tu continues ahahah !  \\nBon tr?ves de plaisanteries, je n\\\'ai plus de nouvelles de Raaga, un de nos plus ing?nieux soldats. Il devait revenir aujourd\\\'hui des mines au nord pour faire son rapport sur les activit?s de la lave. Va me le chercher...Je parle du rapport surtout.');
INSERT INTO `npc_questions` VALUES (838, '', '', '', '', 'Je commence ? m\\\'impatienter...');
INSERT INTO `npc_questions` VALUES (839, '', '', '', '', 'Tu as enfin r?ussi ? capturer ce Bontarien ! Mais, mais...Et les documents ? Ils sont o? les documents ? \\nAh tu les as compl?tement oubli?s ?! Une sentinelle m\\\'a dit que le bontarien les a perdus lors de sa course. Va me les chercher. Passe toutes les landes au peigne fin s\\\'il le faut mais rapporte-les moi, compris !');
INSERT INTO `npc_questions` VALUES (840, '', '', '', '', 'Aaah m?me pour nous d?mon cela fait du bien de souffler un peu. \\nBon c\\\'est pas encore ?a avec mon fils qui me casse les pieds pour me battre en ce moment mais c\\\'est toujours mieux que de devoir attendre le retour d\\\'agents sp?ciaux en mission importante. \\nHmm mais j\\\'y pense puisque tu n\\\'as rien ? faire, va distraire mon fils. Et perds surtout sinon c\\\'est moi qui vais devoir te battre.');
INSERT INTO `npc_questions` VALUES (841, '', '', '', '', 'HMM ? ');
INSERT INTO `npc_questions` VALUES (842, '', '', '', '', 'Les Bontariens sont bien calmes en ce moment. Il ne se passe plus grand chose ? vrai dire. Tu peux en profiter pour te reposer.');
INSERT INTO `npc_questions` VALUES (843, '', '', '', '', 'Les Bontariens sont vraiment trop calmes. Cela cache quelque chose. Un de nos espions a infiltr? Bonta, il s\\\'appelle Trojen Tihpor. Il doit ?tre actuellement de garde autour des remparts dans la cit?. Va le voir discr?tement et rapporte-moi un rapport des activit?s bontariennes.');
INSERT INTO `npc_questions` VALUES (844, '', '', '', '', 'Hummm. Apr?s avoir ?tudi? de fond en comble le plan de la cit? j\\\'ai trouv? une faille potentielle : Les ?gouts de Brakmar. Il va falloir v?rifier ?a de plus pr?s. Comme je t\\\'ai sous la main c\\\'est toi qui va ?tre de corv?e. Va d\\\'abord d?couvrir les ?gouts. Profites-en pour en d?barasser l\\\'entr?e de quelques rats...Et ram?ne leurs carcasses, ?a fera toujours de la viande de plus pour le diner....On est 10 ce soir alors ram?nes-en au moins 10.');
INSERT INTO `npc_questions` VALUES (845, '', '', '', '', ' Il parait qu\\\'il y a eu plusieurs ?boulements dans les ?gouts. Bien que la terre est plutot instable dans le coin certaines rumeurs circulent sur le fait que ces ?boulements ne sont pas naturels. Verifie moi ?a.');
INSERT INTO `npc_questions` VALUES (846, '', '', '', '', 'Mak Gahan s\\\'est occup? des derni?res larves qui tra?naient. Plus de soucis. Pour le r?compenser je lui ai dit que tu lui trouverais un dentier avec des dents en or ? la place de celle de Bouftou. O? tu vas trouver ?a ? C\\\'est pas mon probl?me. ');
INSERT INTO `npc_questions` VALUES (847, '', '', '', '', 'Dep?che toi de r?parer tes b?tises !');
INSERT INTO `npc_questions` VALUES (848, '', '', '', '', 'Certaines t?tes du cartel commencent ? un peu trop...hum..? appr?cier ton travail. Bon puisque tu es si fort je vais pouvoir te donner des missions plus difficile je suppose. Tiens, je viens d\\\'imaginer ton test de passage pour la classe sup?rieure. Va donc me d?pouiller 5 miliciens de bonta et rapporte moi leurs plaqu...non...leurs cale?ons tiens, haha.');
INSERT INTO `npc_questions` VALUES (849, '', '', '', '', 'Ah bah puisque tu es l?, trouve-moi quelqu\\\'un qui sache fabriquer un poison magique. Il doit bien exister une personne dans cette ville qui ait des connaissances pouss?es en empoisonnement !');
INSERT INTO `npc_questions` VALUES (850, '', '', '', '', 'Bon c\\\'est pas tout ?a mais il faudrait que tu files sur le rempart Est. Des Bontariens y tentent une attaque massive et nous commen?ons ? manquer de Chafer. Il va ?tre temps de sortir les armes !');
INSERT INTO `npc_questions` VALUES (851, '', '', '', '', 'On vient de m\\\'apprendre que pendant l\\\'assaut un apprenti-guerrier aurait voulu contourner les ennemis pour les prendre ? revers...Et bien s?r il s\\\'est fait capturer l\\\'abruti. Ce ne serait pas grave si cette bleusaille ignorait tout des plans de notre prochaine attaque de Bonta. Va me le r?cup?rer avant qu\\\'ils ne le questionnent. Oui tu as bien entendu. Embauche d\\\'autres guerriers et faites un raid dans la milice ennemie. La prison se trouve au sous-sol. ');
INSERT INTO `npc_questions` VALUES (852, '', '', '', '', 'De plus en plus de grad?s ont entendu parler de toi. Je suis fier que l\\\'un de mes disciples ait de la renomm?e. Continue ainsi... Mais que ?a ne te monte pas ? la t?te. Tu restes encore qu\\\'une larve rampante ? mes bottes ! Tiens pour ?tre s?r que ?a reste dans ton petit cr?ne, va me tuer 40 larves bleues et ram?ne-moi leurs yeux. ');
INSERT INTO `npc_questions` VALUES (853, '112', '', '', '0', 'Un assassin bontarien, voil? quelque chose que je n\\\'avais jamais envisag?. Quelle meilleure couverture pour tuer un Bontarien que d\\\'?tre soi-m?me un Bontarien. Il faut que tu me trouves des Bontariens dont le coeur n\\\'est pas parfaitement pur. Va demander un b?ton renifleur ? Fryda griffe-de-la-nuit. Ses b?tons ont le pouvoir de renifler le sang impr?gn? sur des personnes, ?a te sera utile.');
INSERT INTO `npc_questions` VALUES (854, '', '', '', '', 'Notre prochain plan est de corrompre un personnage important de Bonta pour avoir un alli?... le moment venu. Je veux que tu trouves quelqu\\\'un de haut plac?, susceptible de trahir Bonta. Je te conseille de fouiller la tour de Bonta pour commencer, il pourrait y avoir des indices l?-bas.');
