INSERT INTO `npc_questions` VALUES (860, '', '', '', '', 'Ah ces corbacs frits! Vraiment inf?me. Cette Sbab ne sait vraiment pas cuisinier. Tu vas lui donner une petite le?on tiens. Sbab adore les Wabbit, tu as d? le remarquer. Elle craque particuli?rement pour les oreilles des Tiwabbits qu\\\'elle trouve \\\"adorables\\\". Rapporte-lui en une dizaine de paires accompagn? de cette petite lettre ?a lui fera tr?s plaisir hinhin !');
