INSERT INTO `npc_questions` VALUES (911, '', '', '', '', 'Diable, un ange dans Br?kmar ! Attrapez-le !');
INSERT INTO `npc_questions` VALUES (915, '', '', '', '', 'Merci #1, toujours aussi serviable. Je vais pouvoir entra?ner mes gars s?rieusement.');
INSERT INTO `npc_questions` VALUES (918, '', '', '', '', 'Bonjour, je me nomme Ture Inge, sp?cialiste en espionnage et en psychologie. Je sais que vous voulez quelque chose de moi.');
INSERT INTO `npc_questions` VALUES (920, '', '', '', '', 'Merci mon gars, tu as ?t? rapide. Tu m\\\'as l\\\'air vif et disciplin?...');
INSERT INTO `npc_questions` VALUES (921, '', '', '', '', 'Bien, va t\\\'entra?ner un peu avec Tarche, le gros milicien qui se garde notre stock de poudre et reviens me voir ensuite.');
INSERT INTO `npc_questions` VALUES (922, '', '', '', '', 'Pas mal je vois que tu as arrach? un cheveu ? ce gros pourceau...Quel Tarche !...Qu\\\'est ce que je vais pouvoir faire de lui. A part frimer, il n\\\'est capable de rien. S\\\'il se fait battre par le premier vagabond venu, je me demande bien ce qu\\\'il pourra faire contre les soldats de Br?kmar...');
INSERT INTO `npc_questions` VALUES (923, '', '', '', '', 'Salut minus qu\\\'est-ce que tu me veux ?');
INSERT INTO `npc_questions` VALUES (924, '', '', '', '', 'Coucou mon mignon. C\\\'est Amayiro qui t\\\'envoie ? J\\\'aurai pr?f?r? qu\\\'il vienne lui-m?me. Enfin, c\\\'est pas grave mon roudoudou, tu n\\\'as qu\\\'? lui donner cette lettre de ma part. Dedans se trouve le nom du pervers qui nous harc?le mes filles et moi.');
INSERT INTO `npc_questions` VALUES (925, '', '', '', '', 'Coucou mon mignon, bienvenue ? la taverne de la Bagrutte !');
INSERT INTO `npc_questions` VALUES (926, '', '', '', '', 'Ho je vois, encore lui, je vais m\\\'en occuper,  ?a ne va pas tra?ner. Merci et n\\\'h?site pas ? repasser me voir.');
INSERT INTO `npc_questions` VALUES (928, '', '', '', '', 'Tu le trouveras dans le quartier des bijoutiers, il se charge de la s?curit? dans ce secteur.');
INSERT INTO `npc_questions` VALUES (929, '', '', '', '', 'Huh ! Tu as d?j? torch? Torche ? Pas mal du tout pour un n?ophyte. Malheureusement pour toi, ? mes yeux tu resteras un petit scarafeuille pendant un bout de temps. Reviens quand bon te semble.');
INSERT INTO `npc_questions` VALUES (930, '', '', '', '', 'C\\\'est toi qui a d?chauss? les dents de mon fr?rot?? N\\\'essaye pas ?a sur moi sinon....');
INSERT INTO `npc_questions` VALUES (932, '', '', '', '', 'Bienvenue ? la taverne du Feubuk, que puis-je faire pour vous jeune ?tranger ?');
INSERT INTO `npc_questions` VALUES (935, '', '', '', '', 'Bonjour, je suis la propri?taire de la bijouterie Bagdor?, que puis-je faire pour vous ?');
INSERT INTO `npc_questions` VALUES (936, '', '', '', '', 'Bonjour l\\\'ami, je suis le meilleur artificier de Bonta, si tu cherches toutes sortes de mati?res explosives, je suis ton homme');
INSERT INTO `npc_questions` VALUES (937, '', '', '', '', 'Bienvenu ? la taverne de la Tabasse, qu\\\'est-ce que je peux faire pour toi ?');
INSERT INTO `npc_questions` VALUES (940, '', '', '', '', 'Bonjour !\\nSavez-vous que la  ville de Bonta a un mur d\\\'enceinte qui compte pas moins de 128.369 pierres de craqueleur ?\\nSavez-vous qu\\\'il a fallu 250 ouvriers pour b?tir ce mur et qu\\\'un 32?me d\\\'entre eux sont morts dans d\\\'atroces souffrances durant les travaux ?\\nNon vous ne le saviez pas ! J\\\'en ?tais s?r.\\n\\nMais vous pouvez concevoir que le budget de la ville qui s\\\'?l?ve ? #1 kamas devra en partie ?tre utilis? pour payer la pension de leurs veuves ? \\n\\nNon, bien s?r. C\\\'est bien ce que je disais. Maintenant, laissez-moi, j\\\'ai ? faire.');
INSERT INTO `npc_questions` VALUES (943, '', '', '', '', '\\\"Hips\\\" l\\\'ami ! Comment ca va bien \\\"hips\\\" aujourd\\\'hui  ? \\nTu veux que je te dise ? Hein, tu veux que je te dise ?... Bah, je te le dis quand m?me : Bonta est la plus belle des cit?s, car c\\\'est pas \\\"hips\\\" ? Braaaakmarrrrrreeee que l\\\'on peut boire de la bi?re comme celle-ci. T\\\'en veux ? Non. Tant mieux, cela en fait plus pour moi.');
INSERT INTO `npc_questions` VALUES (944, '', '', '', '', 'Salut, je suis Bill I?debar le plus fid?le client du Feubuk. Je te conseille vivement la Bi?re du Feubuk, c\\\'est assur?ment la meilleure de Bonta !');
INSERT INTO `npc_questions` VALUES (945, '', '', '', '', 'Bonjour, je suis Kosuke le forgeur de lames. Que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (946, '', '', '', '', 'Salut, j\\\'suis Allen Tokar, je t\\\'offre une p\\\'tite bi?re l\\\'ami !  \\nDis, tu n\\\'aurais pas 4 kamas ? m\\\'avancer, je te les rends d?s que je touche ma solde... En fait 8, ce serait mieux');
INSERT INTO `npc_questions` VALUES (950, '681;673', '', '', '0', 'Puis-je vous renseigner ?');
INSERT INTO `npc_questions` VALUES (951, '677;678;679;680', '', '', '0', 'Puis-je vous renseigner ?');
INSERT INTO `npc_questions` VALUES (952, '', '', '', '', 'Les banques se trouvent ? l\\\'Ouest de la ville. \\nVous pouvez y d?poser votre argent en toute tranquillit?, les dispositifs de s?curit? sont ? toute ?preuve.');
INSERT INTO `npc_questions` VALUES (953, '', '', '', '', 'La porte de cette tour se trouve au Nord-Ouest de Bonta, elle renferme toutes les fonctions administratives de la ville. \\nSi vous cherchez le tr?sorier, ou le maire de Bonta, vous les trouverez certainement l?-bas.');
INSERT INTO `npc_questions` VALUES (954, '', '', '', '', 'Ce fort se trouve au centre de la ville, c\\\'est ? la fois le centre d\\\'entra?nement et le quartier g?n?ral des miliciens. Il faut s\\\'adresser au ma?tre Amayiro pour rejoindre nos rangs.');
INSERT INTO `npc_questions` VALUES (955, '', '', '', '', 'Cette tour se trouve dans la partie basse de la ville, sa biblioth?que est une v?ritable mine d\\\'or pour quiconque s\\\'int?resse ? la magie.');
INSERT INTO `npc_questions` VALUES (956, '', '', '', '', 'Si comme moi tu en as assez de voir cette s?gr?gation qui partage la ville en deux, les riches d\\\'un c?t?, et d\\\'autres riches de l\\\'autre c?t?. Si toi aussi tu penses qu\\\'il devrait y avoir plus d\\\'in?galit?, alors rejoins mon groupe.');
INSERT INTO `npc_questions` VALUES (960, '682;683', '', '', '0', 'Puis-je vous renseigner ?');
INSERT INTO `npc_questions` VALUES (961, '', '', '', '', 'La milice a pour mission principale de d?fendre les habitants de Bonta contre les attaques des guerriers venus de Br?kmar. Nous sommes l? aussi pour vous rendre service et vous informer sur la ville. N\\\'h?sitez pas ? rencontrer le ma?tre Amayiro si vous souhaitez nous rejoindre. Je sais qu\\\'il cherche de nouveaux espions. Vous le trouverez au fort, au milieu de la ville.');
INSERT INTO `npc_questions` VALUES (962, '', '', '', '', 'Les quartiers de Bonta sont d?coup?s en fonction des activit?s exerc?es par les diff?rents artisans. Vous pouvez reconna?tre l\\\'activit? principale d\\\'un quartier par les ornements sur les fa?ades des maisons et aussi par les mats dont les armoiries correspondent au corps de m?tier.');
INSERT INTO `npc_questions` VALUES (965, '', '', '', '', 'Les pierres des fortifications de Bonta ont ?t? taill?es ? partir de la d?pouille des craqueleurs des plaines. \\nUne troupe de Bworks a ?br?ch? celles du nord cette nuit. \\nSi tu veux nous donner un coup de main, ram?ne-moi au moins 4 pierres de craqueleur des plaines pour nous aider ? les reconstruire.');
INSERT INTO `npc_questions` VALUES (968, '', '', '', '', 'Ola, y\\\'en a pour 500 pods par caisse, j\\\'te conseille de te d?charger un peu avant...');
INSERT INTO `npc_questions` VALUES (970, '', '', '', '', 'Capitaine Arlok pour vous servir ! Que puis-je pour vous ?');
INSERT INTO `npc_questions` VALUES (973, '', '', '', '', 'Euh d?sol? #1, je suis trop fatigu? pour un entrainement aujourd\\\'hui...');
INSERT INTO `npc_questions` VALUES (978, '', '', '', '', 'Salut, je suis Anik Mech. Mon oncle, Riorraw, est un grand inventeur, il travaille actuellement sur un engin m?canique permettant de se d?placer ? la vitesse d\\\'un tabi !');
INSERT INTO `npc_questions` VALUES (980, '', '', '', '', 'Avis de recherche ?');
INSERT INTO `npc_questions` VALUES (982, '', '', '', '', 'Tu es #1, qu\\\'Amayiro a envoy? pour m\\\'apporter des dents de bouftou, c\\\'est bien ?a ?');
INSERT INTO `npc_questions` VALUES (983, '', '', '', '', 'Bonjour, je m\\\'appelle Ned Etsith, je m\\\'int?resse ? l\\\'odontostomatologie, passionnant, non ?');
INSERT INTO `npc_questions` VALUES (985, '', '', '', '', 'Oh un visiteuw dans ma fow?t, tu es bien couwageux pour t\\\'aventuwer ici. \\nJ\\\'ai un petit sewvice ? te pwoposew, ? mon ?ge il m\\\'est impossible de me wendwe sur l\\\'?le des wabbits, mais j\\\'aimewais continuew mes wechewches sur cette wace. \\n');
INSERT INTO `npc_questions` VALUES (986, '', '', '', '', 'Utilise la sewingue et pw?l?ves du sang au wabbit GM apw?s l\\\'avoiw assom?. \\nJe te pwomet une w?compense int?wessante si tu me wam?nes l\\\'analyse de son sang.');
INSERT INTO `npc_questions` VALUES (987, '', '', '', '', 'Alows as-tu trouw? ce que je t\\\'avais demand? ?');
INSERT INTO `npc_questions` VALUES (988, '', '', '', '', 'Je vois que tu as trouv? du sang de wabbit GM, par contre j\\\'ai besoin d\\\'une analyse de ce sang, demande ? Otomai l\\\'enchanteur, il sera capable de te faire ?a...');
INSERT INTO `npc_questions` VALUES (989, '68', '', '', '0', 'Mon r?ve est presque r?alis? : ma foire marche bien. \\nMais j\\\'ai encore des projets de nouvelles attractions ? venir plein la t?te. Je ne serais satisfait que lorsque tout sera fini !');
INSERT INTO `npc_questions` VALUES (991, '', '', '', '', 'Bonjour, vous vous trouvez ? l\\\'avant-poste Sud de Bonta, comment puis-je vous servir ?');
INSERT INTO `npc_questions` VALUES (996, '', '', '', '', 'Mais comment es-tu rentr? ici ?');
INSERT INTO `npc_questions` VALUES (1001, '', '', '', '', 'Je me pr?sente : Leonzi Trool, visionnaire de g?nie et humble ap?tre d\\\'Ecaflip. Je mets mes modestes moyens ? contribution afin d\\\'amuser les gens. Aujourd\\\'hui, je pense avoir r?alis? le projet qui a r?volutionn? le monde des loisirs et j\\\'en suis fier. Mais il reste encore ? faire.');
INSERT INTO `npc_questions` VALUES (1007, '', '', '', '', 'Qu\\\'as-tu fait avec ce collier, il est compl?tement d?form? ? \\nJe ne peux pas le rendre dans cet ?tat ? la fille du maire. \\nVa dans le quartier des bijoutiers et arrange-toi pour en r?cup?rer un tout neuf !');
INSERT INTO `npc_questions` VALUES (1008, '', '', '', '', 'Voil? enfin un collier ?tincelant, tu n\\\'as pas ?t? tr?s rapide cette fois....');
INSERT INTO `npc_questions` VALUES (1009, '', '', '', '', 'Pnj(180) et Message(754)');
INSERT INTO `npc_questions` VALUES (1010, '', '', '', '', 'Il m\\\'a parl? d\\\'une similitude entre la dent de bouftou et la n?tre. D?cidemment, cet animal m\\\'?tonnera toujours. Une fois les dents r?cup?r?es, apporte-les ? mon ami au sud-ouest de la ville. \\nJ\\\'esp?re que tu n\\\'es pas assez ignare pour avoir oubli? le nombre de dents que poss?de un ?tre humain.');
INSERT INTO `npc_questions` VALUES (1011, '', '', '', '', 'Tu es en permission jusqu\\\'? demain, reviens me voir plus tard pour obtenir une nouvelle mission. \\nJe suis de bonne humeur, alors prends ces 1000 kamas pour tes frais de d?placement... et pour ta tourn?e ? la taverne... hehe ! Mais n\\\'abuse pas de la boisson et garde la forme, j\\\'aurais rapidement besoin de toi.');
INSERT INTO `npc_questions` VALUES (1012, '', '', '', '', 'D?j? de retour ? Je vais ?tudier les informations que tu m\\\'as apport?es sur la porte de Br?kmar au calme. \\nSinon, j\\\'ai un nouveau travail pour toi. Un sanglier agressif pi?tine les r?coltes au Sud de la ville, essaye de le chasser de l?, pour calmer les paysans.');
INSERT INTO `npc_questions` VALUES (1013, '', '', '', '', 'Bon travail #1. Ce sanglier des plaines devrait nous laisser tranquille pendant un moment.');
INSERT INTO `npc_questions` VALUES (1014, '', '', '', '', 'Merci, j\\\'en connais un qui va pouvoir remanger du steak de bouftou, gr?ce ? toi.\\nSalue Amayiro de ma part !');
INSERT INTO `npc_questions` VALUES (1015, '', '', '', '', 'Pauvres bouftous, tu ne fais pas dans la finesse #1, il n\\\'y en a pas le nombre exact !\\n? moins que tu ne saches pas compter ?\\nPour la peine je prends d?j? celles-ci, et tu vas devoir m\\\'en ramener 32 de plus !');
INSERT INTO `npc_questions` VALUES (1016, '', '', '', '', 'Tu n\\\'en as pas assez, voyons. Amayiro m\\\'avait dit que tu n\\\'?tais pas fut?, je dois reconna?tre qu\\\'il n\\\'avait pas tort...');
INSERT INTO `npc_questions` VALUES (1017, '', '', '', '', 'Tu dois r?cup?rer EXACTEMENT le nombre de dents que poss?de un ?tre humain sur des bouftous, et les apporter ? Ned Etsith au Sud-Ouest de la ville.');
INSERT INTO `npc_questions` VALUES (1018, '', '', '', '', 'J\\\'ai l\\\'impression que tu as oubli? la bi?re, bougre d\\\'?ne. \\nAllez remets-toi en route, et vite !  \\nFaut vraiment tout leur dire ? ces empot?s.');
INSERT INTO `npc_questions` VALUES (1019, '', '', '', '', 'C\\\'est bien tu as pens? ? la bi?re, n\\\'oublie jamais que l\\\'?l?ve qui a soif d\\\'apprendre doit aussi penser ? la soif de son professeur... hehe ! La carte va aller tout droit dans ma collection....');
INSERT INTO `npc_questions` VALUES (1020, '', '', '', '', 'Hmm, j\\\'en connais qui seront surpris ? la prochaine paye.\\nMerci #1, j\\\'irais leur rendre leurs badges personnellement.');
INSERT INTO `npc_questions` VALUES (1021, '', '', '', '', 'Hmm ! Finalement, je suis d?bord? pour m\\\'occuper moi-m?me de mon sabre. \\nVa au quartier des forgerons et demande ? Kosuke de r?parer ma lame.');
INSERT INTO `npc_questions` VALUES (1022, '', '', '', '', 'Jolie ! Elle est aiguis?e comme au premier jour. Le forgeron a fait un travail remarquable.');
INSERT INTO `npc_questions` VALUES (1023, '', '', '', '', 'Bien jou?, tu vas commencer ? conna?tre Br?kmar comme ta poche, dis-moi?!');
INSERT INTO `npc_questions` VALUES (1024, '', '', '', '', 'Merci pour cette poudre, les Br?kmariens n\\\'ont qu\\\'? bien se tenir. Hehe !');
INSERT INTO `npc_questions` VALUES (1025, '', '', '', '', 'Rien ne te r?siste. C\\\'est bien, tu grimpes encore dans mon estime #1.');
INSERT INTO `npc_questions` VALUES (1026, '', '', '', '', 'Tu en as d?j? transf?r? 4, tu es infatigable dis-moi. Pas la peine d\\\'en prendre d\\\'autres.');
INSERT INTO `npc_questions` VALUES (1027, '', '', '', '', 'Hmm, le formulaire 243, tu dois avoir de gros doutes sur une personne pour envisager ce test.');
INSERT INTO `npc_questions` VALUES (1028, '', '', '', '', 'Hmm en fait non, je n\\\'arrive plus ? manier mon sabre quand je les porte, tant pis j\\\'irais les revendre ? la bijouterie.');
INSERT INTO `npc_questions` VALUES (1029, '', '', '', '', '...\\nTu baisses fortement dans mon estime #1. Il ne te reste plus qu\\\'une chose ? faire : allez pr?venir la famille de son d?c?s.\\nReviens me voir quand tu l\\\'auras fait, mais ne te presse pas....');
INSERT INTO `npc_questions` VALUES (1030, '', '', '', '', '/action d?clencher combat/');
INSERT INTO `npc_questions` VALUES (1031, '740', '', '', '', 'Ohoh je vois que tu es rapide ? ob?ir. Tu pourrais ?tre utile au clan infernal. C\\\'est d?cid? je te prends sous mon commandement. Au pire tu serviras de rempla?ant aux chafers. ');
INSERT INTO `npc_questions` VALUES (1032, '', '', '', '', 'Bonjour, mon ?picerie est ouverte 24 heures sur 24, si vous avez besoin d\\\'un aliment n\\\'h?sitez pas ? jeter un oeil ? notre stock.');
INSERT INTO `npc_questions` VALUES (1033, '', '', '', '', 'Interess? par des marchandises hein ? H?h? il va falloir montrer la monnaie d\\\'abord.');
INSERT INTO `npc_questions` VALUES (1034, '731', '', '', '0', 'Que peut faire Musa Tireur de Loup,  pour vous ?');
INSERT INTO `npc_questions` VALUES (1035, '', '', '', '', 'Alors comme ?a c\\\'est toi la recrue d\\\'Amayiro, tu parais bien jeune pour le destin qui t\\\'attend. Bon, je suppose que tu viens chercher la carte. Tes mains sont propres j\\\'esp?re. Ne va pas la tacher de sang ou de je ne sais quoi sur le chemin, Amayiro t\\\'en voudrait certainement.');
INSERT INTO `npc_questions` VALUES (1036, '732', '', '', '0', 'Musa Tueur de Loup est le meilleur chasseur de tout Amakna soyez en s?r. Rien ne me r?siste.');
INSERT INTO `npc_questions` VALUES (1037, '733', '', '', '0', 'Chasser c\\\'est simple ! Il faut juste avoir la bonne arme pour bien frapper l\\\'animal. Si l\\\'animal est trop bless? ou mal tu?, le chasseur ne pourra pas r?colter les morceaux de viande int?ressants qu\\\'il pourrait vendre par la suite.');
INSERT INTO `npc_questions` VALUES (1038, '735', '', '', '0', 'Hol?, Musa Tueur de Loup a dit que c\\\'etait simple mais pas autant que ?a ! Pour pouvoir manipuler les armes de chasseur il faut une certaines dext?rit?, prouvez ? Musa cette dext?rit? et il vous nommera chasseur.');
INSERT INTO `npc_questions` VALUES (1039, '736', '', '', '0', 'Tr?s bien si vous le souhaitez autant...Vous allez devoir tuer un bouftou tr?s rapidement : vous avez deux minutes. Prouvez moi que vous en ?tes capable et vous je vous nommerai chasseur.');
INSERT INTO `npc_questions` VALUES (1040, '', '', '', '', 'Excellent, tu m\\\'?pates sur ce coup l? !');
INSERT INTO `npc_questions` VALUES (1041, '', '', '', '', 'Quelle dext?rit? ! Tr?s bien, comme vous le souhaitiez Musa Tueur de Loup vous nomme chasseur');
INSERT INTO `npc_questions` VALUES (1042, '', '', '', '', '*Cliquetis* *Quetis,Cliquetis* *Cliquetis*-*Cliquecliquetis*, *Clicliquetis*');
INSERT INTO `npc_questions` VALUES (1043, '', '', '', '', 'Hmm ! Ce collier est en tr?s mauvais ?tat, cela vous en co?tera 1000 kamas pour le r?parer.');
INSERT INTO `npc_questions` VALUES (1044, '', '', '', '', 'Le voici ?clatant comme au premier jour.');
INSERT INTO `npc_questions` VALUES (1045, '', '', '', '', 'Bien ! Un peu long quand m?me. Bon tu vaux un peu plus qu\\\'un amas de calcium pourrissant. Je te descends au rang de larbin. Un immense privil?ge si tu veux mon avis. \\nJ\\\'ai m?me un premier travail ? te confier...');
INSERT INTO `npc_questions` VALUES (1046, '', '', '', '', 'Tu n\\\'y vas pas par quatre chemins l\\\'ami, tu as besoin de quelle quantit? de poudre, dis-moi ?');
INSERT INTO `npc_questions` VALUES (1047, '', '', '', '', 'Ah ! Un amateur de canon ? ce que je vois ? Si tu as des questions ? ce sujet, je suis incollable.');
INSERT INTO `npc_questions` VALUES (1048, '', '', '', '', 'Une dizaine de pods seulement ? La milice y va vraiment avec des pincettes, si on veut exterminer Br?kmar un jour, il faut que ?a p?te ! \\nEnfin bon, vu que tu es envoy? par la milice, je te le fais ? -50%, ?a te fera donc 20000 kamas...');
INSERT INTO `npc_questions` VALUES (1049, '75', '', '', '0', 'Oueeeehhhh La pu\\\'d biar el Korgno. A pu\\\'d ziou na plou, meu la kor \\\'vi dbouaaaaaaaaaar !');
INSERT INTO `npc_questions` VALUES (1050, '', '', '', '', 'Euh quelle dette ? Tu dois faire erreur.');
INSERT INTO `npc_questions` VALUES (1051, '', '', '', '', 'Naaaa peu pat porl? toa, t? tro maichan ! Pi ja la bouk tou seuc dfasson.');
INSERT INTO `npc_questions` VALUES (1052, '', '', '', '', 'Boudiou ! dla bonne. M? tai un gro jenti toaaa ! Vin l? min chpott discouiller de chose et dot pour fait? ste tourn?e!');
INSERT INTO `npc_questions` VALUES (1053, '', '', '', '', 'Tu cherches les probl?mes on dirait, tu ne connais donc pas ma r?putation ?');
INSERT INTO `npc_questions` VALUES (1054, '', '', '', '', 'Eul nom deuch tueur pour tin patro ? Mais bieeeeeeeeeen chur queu jeli conio. Tin echle note sur unt bou popi?. Pra cha !');
INSERT INTO `npc_questions` VALUES (1055, '', '', '', '', 'Lui ? Ce bouffon a d? avoir du bol finalement. Enfin, pas merci pour ton travail. Je te donne l\\\'autorisation de faire ce que tu veux. L?, j\\\'ai pas le temps de m\\\'occuper de toi alors d?gage !');
INSERT INTO `npc_questions` VALUES (1056, '', '', '', '', 'Quel exemple d\\\'ob?issance. Tu iras loin toi, enfin, si je le veux. \\nTiens pour te r?compenser, je te propose, un petit divertissement.');
INSERT INTO `npc_questions` VALUES (1057, '', '', '', '', 'Ah voil?. Un dentier tout neuf. C\\\'est Mak qui va ?tre content.');
INSERT INTO `npc_questions` VALUES (1058, '', '', '', '', 'Je t\\\'avais pourtant pr?venu de savoir t\\\'arr?ter ! \\nEnfin, je suis de bonne humeur aujourd\\\'hui. Tu vas donc tout simplement recommencer.');
INSERT INTO `npc_questions` VALUES (1060, '', '', '', '', 'Hmm int?ressant ce petit combat.  \\nBon si tu as fini de t\\\'amuser il reste du boulot pour le clan.');
INSERT INTO `npc_questions` VALUES (1061, '', '', '', '', 'Qu\\\'est ce que tu m\\\'veux !');
INSERT INTO `npc_questions` VALUES (1062, '', '', '', '', 'Ah c\\\'est pour l\\\'entra?nement. Tiens prend ?a, et d?p?che-toi !');
INSERT INTO `npc_questions` VALUES (1064, '', '', '', '', 'Merci mon gars. Tu as ?t? efficace... mais bon, ce n\\\'est pas cela qui fera de toi le plus grand des ?tripeurs de Br?kmar.');
INSERT INTO `npc_questions` VALUES (1065, '', '', '', '', 'Hum, laisse-moi, tu vois bien que je fais ma pause !');
INSERT INTO `npc_questions` VALUES (1066, '', '', '', '', 'Ah je vois vous voulez balancer les miliciens qui ne font pas de pause ? C\\\'est bien ! Je l\\\'aurais bien fait moi m?me, mais je suis trop fain?ant. Bon je ne peux pas vous dire qui ne fait pas de pause, mais par contre je confirme la pr?sence quotidienne de Brank Thoof, Haco Norss, Jack Rottance, Kad Maxy. Tenez, je vous les note.');
INSERT INTO `npc_questions` VALUES (1068, '', '', '', '', 'Aoouh sitoi, marchi kor. Ti veu rediscouiller un pou?');
INSERT INTO `npc_questions` VALUES (1069, '', '', '', '', 'Pad problaime monnami. Tin donc ! Repache kant veu.');
INSERT INTO `npc_questions` VALUES (1070, '', '', '', '', 'Humm tu vois pas que je suis occup? !');
INSERT INTO `npc_questions` VALUES (1071, '', '', '', '', 'Je suis en patrouille, tu me g?nes. Va-t\\\'en !');
INSERT INTO `npc_questions` VALUES (1072, '', '', '', '', 'ZZZZZzzzzz ZZZZZzzzzz');
INSERT INTO `npc_questions` VALUES (1074, '', '', '', '', 'hmm ?');
INSERT INTO `npc_questions` VALUES (1075, '', '', '', '', 'Pourquoi devrais-je te parler ? Tu vois bien que je bosse !');
INSERT INTO `npc_questions` VALUES (1076, '', '', '', '', 'Rien ? signaler monsieur !');
INSERT INTO `npc_questions` VALUES (1077, '', '', '', '', 'Oui ?');
INSERT INTO `npc_questions` VALUES (1078, '', '', '', '', 'Arg vous saviez ? Oui j\\\'avoue j\\\'y vais plus ? cette taverne miteuse, leur pisse de chat a vraiment trop le go?t de bi?re, c\\\'est r?voltant. ');
INSERT INTO `npc_questions` VALUES (1079, '', '', '', '', 'Oui c\\\'est vrai, je n\\\'ai plus le coeur d\\\'y aller ces temps-ci. Je...Vous savez je.... Ah voil? je suis amoureux c\\\'est pour ?a, d?sol? je peux pas en dire plus.');
INSERT INTO `npc_questions` VALUES (1080, '', '', '', '', 'Qu\\\'est ce que tu veux toi !');
INSERT INTO `npc_questions` VALUES (1081, '', '', '', '', 'Bien s?r que je prends, Cet ivrogne de Mili va entendre parler de moi. Il est toujours saoul quand je le vois.');
INSERT INTO `npc_questions` VALUES (1082, '', '', '', '', 'Quoi? Un vieil alcoolique ne me voit pas et vous trouvez que c\\\'est une preuve ? Laissez-moi rire, bien s?r que j\\\'en prends.');
INSERT INTO `npc_questions` VALUES (1083, '', '', '', '', 'C\\\'est bon ! C\\\'est bon ! Oui j\\\'avoue, je trouve ce syst?me totalement stupide, on ne pourra jamais prendre Bonta avec des lois pareilles croyez-moi.');
INSERT INTO `npc_questions` VALUES (1084, '', '', '', '', 'Ahah voil? qui est fort int?ressant ! J\\\'en connais qui vont avoir droit au fouet ce soir, et pas pour leur plaisir cette fois ! Bien jou? !');
INSERT INTO `npc_questions` VALUES (1085, '', '', '', '', 'Humm, c\\\'est bien. Mais quelque chose me dit qu\\\'il en manque. Cherchez mieux !');
INSERT INTO `npc_questions` VALUES (1086, '', '', '', '', 'Voici ta lame toute neuve ! Comment ?a, j\\\'ai ?t? rapide ? Je ne suis pas le plus c?l?bre forgeur de lame de Bonta pour rien....');
INSERT INTO `npc_questions` VALUES (1087, '', '', '', '', 'Merci, je ne pensais pas recevoir ces armes aussi vite. Cela va nous ?tre fort utile !');
INSERT INTO `npc_questions` VALUES (1088, '', '', '', '', 'Rien pour le moment. Ce soir je vais parler de toi ? la r?union des trois t?tes. \\nJe te donne une journ?e compl?te de perme. Va fol?trer dans les tavernes tu l\\\'as bien m?rit?. ');
INSERT INTO `npc_questions` VALUES (1089, '', '', '', '', 'Tu es en perm j\\\'ai dit !');
INSERT INTO `npc_questions` VALUES (1090, '', '', '', '', 'Alors ta perm s\\\'est bien pass?e ? \\nJ\\\'ai bien l\\\'impression que tu as oubli? de ramener une bi?re ? ton chef... pour la peine va m\\\'en chercher une ? la Tabasse. \\nAh j\\\'allais oublier, cette taverne se trouve ? Bonta, je te souhaite donc bonne chance... \\nTu n\\\'as qu\\\'? capturer un paysan et l\\\'envoyer la chercher ? ta place ! Haha !');
INSERT INTO `npc_questions` VALUES (1091, '', '', '', '', 'Ahlala je suis crev');
INSERT INTO `npc_questions` VALUES (1092, '', '', '', '', 'Tiens je te le pr?te, mais faudra penser ? me le rendre... Burrrp. Oh ! je ne me sens pas bien. Une bi?re devrait m\\\'aider ? passer ce cap difficile. Reviens me voir quand tu veux l\\\'ami... Yhooo !');
INSERT INTO `npc_questions` VALUES (1093, '', '', '', '', 'Hmm, tu m\\\'as pas l\\\'air d\\\'?tre un bout en train toi. Tiens prends mon badge pour ton recensement.');
INSERT INTO `npc_questions` VALUES (1094, '', '', '', '', 'Olala, t\\\'as pas confiance ?  Prends-le, mais n\\\'oublie pas de me le rendre.');
INSERT INTO `npc_questions` VALUES (1095, '', '', '', '', 'Hmm, je vois que tu fais partie de la milice Bontarienne.\\nAmayiro m\\\'a command? un rapport que j\\\'ai justement fini de r?diger. \\nLe voici, et que la d?esse Jiva te prot?ge #1.');
INSERT INTO `npc_questions` VALUES (1096, '', '', '', '', 'Hmm, Tsog ?tait un brillant soldat, il est mort en h?ros. Mais ce vieux fou a voulu ?tre enterr? dans le cimeti?re abandonn? ? l\\\'Est de Bonta...');
INSERT INTO `npc_questions` VALUES (1097, '', '', '', '', 'Voil? pour toi, reviens me voir quand il t\\\'en faudra davantage.');
INSERT INTO `npc_questions` VALUES (1098, '', '', '', '', 'Il en existe de nombreux types, mais tout est question de dosage. \\nPour la milice je pr?pare de la poudre de Nocabregor. Elle ? l\\\'avantage d\\\'?tre peu on?reuse, stable et de ne demander qu\\\'une faible quantit? d\\\'?nergie pour provoquer la combustion. \\nPour les feux d\\\'artifice, j\\\'utilise une poudre avec tr?s peu de salp?tre pour ?viter les risques inutiles. \\nJe fabrique aussi des mines, ou j\\\'utilise une grosse quantit? de soufre. \\nEnfin... la question est trop vaste pour en parler davantage.');
INSERT INTO `npc_questions` VALUES (1099, '', '', '', '', 'Hmm leurs canons ne sont pas mauvais ils sont fabriqu?s dans l\\\'atelier ? c?t? d\\\'ici. \\nLe seul probl?me c\\\'est qu\\\' Amayiro ne jure que par les armes blanches, donc ils sont souvent laiss?s ? l\\\'entrep?t pendant les batailles...');
INSERT INTO `npc_questions` VALUES (1100, '', '', '', '', 'Hmm non, cette recette est secr?te et assez compliqu?e, j\\\'ai m?me ?t? oblig? de la noter sur une feuille et la cacher dans ma maison pour m\\\'en souvenir haha !\\n');
INSERT INTO `npc_questions` VALUES (1101, '', '', '', '', 'Bon tu m\\\'es sympathique donc, je te donne cette poudre ? canon gratuitement .');
INSERT INTO `npc_questions` VALUES (1102, '', '', '', '', 'Bienvenue cher client. Ici nous taillons tout sur-mesure moyennant finance bien s?r. Chemises, pi?ces d\\\'armures, gorges, n\\\'importe quoi du moment que l\\\'on peut le tailler ? vif avec nos couteaux.');
INSERT INTO `npc_questions` VALUES (1103, '', '', '', '', 'Hummm dis-moi mon petit, aurais-tu vu mes fr?res tra?ner dans le coin ? \\nJe dois absolument les retrouver au plus vite. Ils ont tendance ? tout casser puis, quand quelqu\\\'un leur r?siste, ? leur jeter plein d\\\'objets ? la t?te.');
INSERT INTO `npc_questions` VALUES (1104, '', '', '', '', 'Ah l\\\'air naus?abond, l\\\'obscurit? permanente, les ombres sur les murs...Que cette triste ville de Br?kmar est belle.');
INSERT INTO `npc_questions` VALUES (1105, '84', '', '', '0', 'Aaaaaah de la viande fraaaa?che... N\\\'ayez pas peur, je ne parle pas de vous, vous ?tes bien trop maigre pour valoir quelque chose sur le march?. Faudrait vous nourrir un peu. D\\\'ailleurs que diriez-vous d\\\'acheter de la bonne viande ?');
INSERT INTO `npc_questions` VALUES (1106, '', '', '', '', 'Passez votre chemin, je ne cherche pas l\\\'affrontement en venant ici. Je souhaite simplement r?cup?rer mes ?p?es.');
INSERT INTO `npc_questions` VALUES (1107, '', '', '', '', 'Raaaaah ! Ma corne ! O? est ma cooorne !');
INSERT INTO `npc_questions` VALUES (1108, '', '', '', '', 'Pourquoi tu me d?visages toi ?! Tu crois peut-?tre que parce que je suis petite je ne vais rien dire ? ');
INSERT INTO `npc_questions` VALUES (1109, '111', '', '', '0', 'On m\\\'a toujours dit que je portais malheur aux gens qui croisaient ma route. Croyez-vous ?chapper ? cette sordide  destin?e ?');
INSERT INTO `npc_questions` VALUES (1110, '', '', '', '', 'Enchant?e, je me nomme Fulsura. L\\\'aphrodite de Br?kmar, la reine de la beaut?. Que voulez-vous ? Si vous venez me voir pour ?a, n\\\'y pensez m?me pas. D\\\'une, vous ?tes horrible. De deux, vous n\\\'auriez jamais les poches assez pleines.');
INSERT INTO `npc_questions` VALUES (1111, '', '', '', '', 'Plein de gens me prennent pour une fille. *sob* et quand ils se rendent compte que je suis un gar?on ils me tra?tent de tous les noms *sob*.  Mais je les ai tous retenus *snif* et un jour je me vengerai ! haha!');
INSERT INTO `npc_questions` VALUES (1112, '', '', '', '', 'Je hais cette ville, elle sent mauvais et les gens qui y vivent sont malsains...');
INSERT INTO `npc_questions` VALUES (1113, '', '', '', '', 'Hey dis dis dis dis, t\\\'as pas des kamas pour moi ? Non, mais sinon je peux te trouver des armes pas ch?res ! T\\\'as pas des kamas pour moi ? Si tu veux, je vole n\\\'importe qui pour toi ! T\\\'as pas des kamas pour moi ? Je sais comment te dupliquer des objets, tu sais ! T\\\'as pas des kamas pour moi ? T\\\'as pas des kamas pour moi ? Allez file-moi tous tes kamas !');
INSERT INTO `npc_questions` VALUES (1114, '', '', '', '', 'hummm. J\\\'ai des chaussuuuures, qui se multiplient. Et j\\\'en peeeerds le contr?le !... \\nNON CA NE VA PAS ! Arg ! Je suis un ca?d moi, pas un chanteur ! Comment je vais r?ussir ? lui aligner deux mots pour la charmer...  \\nHa heu, excusez-moi, je r?fl?chissais tout haut... D?sol?..');
INSERT INTO `npc_questions` VALUES (1115, '', '', '', '', '*Cet homme vous jette un regard glacial et ne dit mot*');
INSERT INTO `npc_questions` VALUES (1116, '', '', '', '', 'Meeeouw.... FFFfffffffffffffff !');
INSERT INTO `npc_questions` VALUES (1117, '', '', '', '', 'Quoi qu\\\'est-ce que tu veux ? T\\\'es pas jouasse ? Je te prends quand tu veux ! Attends, je vais chercher mes potes et on va te casser en deux !... T\\\'as de la chance que mes 50 ne soient pas l?, sinon t\\\'avais plus de t?te. Va-t\\\'en ! Bon, c\\\'est moi qui m\\\'en vais.');
INSERT INTO `npc_questions` VALUES (1118, '', '', '', '', 'Qu\\\'est ce que tu veux fiston, j\\\'ai tout ce que tu d?sires ici: L\\\'argent l\\\'argent et l\\\'argent ! Avec ?a tu peux acheter tout ce que tu veux. Pouvoir, amis....tout ! Mais je te d?conseille de tenter de me voler. M?me simplement y penser pourrait me forcer ? t\\\'arracher les yeux.');
INSERT INTO `npc_questions` VALUES (1119, '', '', '', '', 'Merci beaucoup, avec ?a mon Tabi devrait reprendre du poil de la b?te.');
INSERT INTO `npc_questions` VALUES (1120, '', '', '', '', 'Merci la Protectrice Jiva te remerciera.');
INSERT INTO `npc_questions` VALUES (1121, '', '', '', '', 'Hors de mon chemin, cloporte. Je n\\\'ai pas le temps de jouer, je dois calmer mon fr?re.');
INSERT INTO `npc_questions` VALUES (1122, '', '', '', '', 'Ma cit? natale est bien plus jolie, mais celle-ci a son charme aussi.');
INSERT INTO `npc_questions` VALUES (1123, '805;806', '', '', '0', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nTu veux savoir pourquoi je rigole. Donne-moi 5 kamas et je t\\\'explique. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !  \\n');
INSERT INTO `npc_questions` VALUES (1124, '', '', '', '', 'Tu veux un pain dans les dents? Tu es bien tomb? alors h?h?h');
INSERT INTO `npc_questions` VALUES (1125, '', '', '', '', 'Je te pr?viens : approche tes mains de moi et je t\\\'enverrai rejoindre tes anc?tres.');
INSERT INTO `npc_questions` VALUES (1126, '', '', '', '', 'C\\\'est moi le plus grand, le plus magique, le plus dou? des forgemages du monde. Mes armes sont surpuissantes et chacune est une pi?ce unique. Et toi que veux-tu ?');
INSERT INTO `npc_questions` VALUES (1127, '', '', '', '', 'Cliquotis cliquotecliquote clicliquotis, Cliquolicquotis.');
INSERT INTO `npc_questions` VALUES (1128, '', '', '', '', 'Mauvais jour pour la chasse aux tofus !');
INSERT INTO `npc_questions` VALUES (1129, '797;798', '', '', '0', 'On peut ?tre d?moniaque et suivre la mode, ne pensez-vous pas ?');
INSERT INTO `npc_questions` VALUES (1130, '805;806', '', '', '', 'Pr?te-moi 5 kamas. Je te promets de te les rendre.');
INSERT INTO `npc_questions` VALUES (1131, '', '', '', '', 'Ah enfin quelqu\\\'un de sens');
INSERT INTO `npc_questions` VALUES (1132, '', '', '', '', 'Peu importe, on voit bien ? vos habits que vous n\\\'y connaissez rien.');
INSERT INTO `npc_questions` VALUES (1133, '', '', '', '', 'Ne d?rangez pas le grand zolTAN en pleine m?ditation transhypnotique. Cela pourrait l\\\'?nerver.');
INSERT INTO `npc_questions` VALUES (1134, '', '', '', '', 'Ce sont des jolis marteaux dis-moi, il ne faisait pas les m?mes en noir ?');
INSERT INTO `npc_questions` VALUES (1135, '', '', '', '', 'Interressant. L\\\'heure approche o? nous pourrons d?truire Bonta, l\\\'usurpatrice. Les nouvelles que tu m\\\'apportes vont nous permettre d\\\'am?liorer notre plan de bataille.');
INSERT INTO `npc_questions` VALUES (1136, '', '', '', '', 'Haha je suis un homme riche ! \\n*Parcours le testament* \\nHmm, j\\\'ai l\\\'impression que mon p?re avait surtout beaucoup de dettes... hmm tu n\\\'aurais pas quelques kamas ? me donner, apr?s tout c\\\'est un peu ta faute !');
INSERT INTO `npc_questions` VALUES (1137, '', '', '', '', 'J\\\'ai un doute sur l\\\'efficacit? de ce venin, tu ne voudrais pas en go?ter un pour me prouver que ce n\\\'est pas du jus de blop ? \\nComment ?a, tu n\\\'veux pas mourir ? Les jeunes recrues n\\\'ont vraiment plus de respect envers leur sup?rieur. Allez file !');
INSERT INTO `npc_questions` VALUES (1138, '', '', '', '', 'Certains sont un peu caboss?s, t\\\'aurais pu les tabasser moins fort.\\nEnfin bon ?a devrait faire l\\\'affaire. Tu seras bient?t des n?tres #1.');
INSERT INTO `npc_questions` VALUES (1139, '', '', '', '', 'Rapide, efficace, silencieux, autant d\\\'adjectifs qui ne te correspondent pas.\\n#1, tu as vu le temps que tu as mis pour me ramener de la bouillie ?\\nEnfin de toute fa?on je viens d\\\'apprendre que son satan? tabi ?tait immunis? aux poisons communs. Seul un magique ferait l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (1140, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nJe rigole, car tu viens de perdre 5 kamas.  \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA ! ');
INSERT INTO `npc_questions` VALUES (1141, '', '', '', '', 'Hein ! De quoi tu me parles ? Tu me prends pour un mendiant, c\\\'est ?a. Jamais, je ne t\\\'ai demand? que 5 kamas.');
INSERT INTO `npc_questions` VALUES (1142, '', '', '', '', 'Hmm j\\\'y pense, tu n\\\'as pas l\\\'?ge l?gal pour boire du vin de Gloutovore. \\nQuel dommage, je ne vais pas pouvoir le partager avec toi. \\nPar contre il parait que tu devais me donner une lettre... Merci. Mais quel incomp?tence quand m?me. La prochaine fois c\\\'est le cachot compris ?!');
INSERT INTO `npc_questions` VALUES (1143, '', '', '', '', 'Voil? la lettre. Fais vite, c\\\'est tr?s urgent.');
INSERT INTO `npc_questions` VALUES (1144, '', '', '', '', 'Pas merci. Cela nous aidera pour les prochaines batailles contre les chiens de Bonta.');
INSERT INTO `npc_questions` VALUES (1145, '', '', '', '', 'Argh, mais je ne t\\\'ai pas demand? de me ramener une dent, ? moins que tu veuilles que j\\\'ai la rage contre toi ?');
INSERT INTO `npc_questions` VALUES (1146, '', '', '', '', 'Oh! les terribles capes... J\\\'esp?re que mes gars ne manqueront pas de les d?poser sur de la fourrure jaune. Tu peux partir inquiet #1... Yarrk Yark !');
INSERT INTO `npc_questions` VALUES (1147, '', '', '', '', 'Hmm je vois la situation est pire que ce que je pensais.... \\nJe vais t\\\'?crire ma r?ponse tout de suite.');
INSERT INTO `npc_questions` VALUES (1148, '', '', '', '', 'Voil?, remet ceci ? ton ma?tre, il devrait ?tre ravi. \\nEt dis lui de surveiller ses arri?res, certains de mes disciples ne le portent pas dans leur coeur, mouhaha !');
INSERT INTO `npc_questions` VALUES (1149, '', '', '', '', 'Bienvenue ? la taverne du Alakarte. Si vous voulez une boisson, vous n\\\'avez qu\\\'? demander la carte...');
INSERT INTO `npc_questions` VALUES (1150, '818;819;1239', '', '', '0', 'Mon livreur de fournitures s\\\'est tromp? et m\\\'a fourni quatre fois trop de poudre soignante pour familier. Ne voulant pas trop perdre de cette erreur, je solde cette poudre exceptionnellement ? 1000 Kamas, demandez-moi si vous ?tes int?ress');
INSERT INTO `npc_questions` VALUES (1151, '3576;820', '', '', '0', 'Vous ?tes dans un chanil. Ce b?timent est le refuge de tous les petits familiers. Nous les gardons lorsque leur ma?tre doit partir occire du dragon. Nous les bichonnons et nous nous assurons qu\\\'ils sont bien trait?s. Nous pouvons m?me reprendre un fant?me de familier et vous donner en ?change un nouveau familier.');
INSERT INTO `npc_questions` VALUES (1152, '', '', '', '', 'Je me nomme Oshimo Li\\\'Kross Babine. Je viens de loin pour apporter ma connaissance en mati?re d\\\'animaux. Quand j\\\'ai entendu la nouvelle sur la peste famili?re j\\\'ai accouru ? dos de tabi. Et j\\\'ai d?cid? ensuite de rester.');
INSERT INTO `npc_questions` VALUES (1153, '', '', '', '', 'Avant de sortir de ce temple j\\\'aimerais te faire passer un petit test. \\nJe vais te poser quelques questions pour ?tre sur que tu sois aptes ? d?couvrir le monde, si tu le passes avec succ?s je t\\\'apprendrai une technique de meditation fortement utile.');
INSERT INTO `npc_questions` VALUES (1154, '822', '', '', '', 'Nous gardons vos familiers moyennant finance. \\nLors d\\\'un premier ?change, vous me confiez votre familier et une somme d\\\'argent pour le placer. Et je vous donne un contrat de bons soins. \\nLorsque vous reviendrez, montrez moi le certificat et une somme d\\\'argent et je vous rendrai votre familier');
INSERT INTO `npc_questions` VALUES (1156, '', '', '', '', 'La somme d\\\'argent de d?part d?pend de la date de son dernier repas. Je demande 10 kamas par heure depuis son dernier repas ainsi qu\\\'un petit forfait qui d?pend de la difficult? ? nourrir le familier.\\nLa somme d\\\'argent pour le reprendre d?pend du nombre d\\\'heures pendant lesquelles votre familier est rest? dans le chanil. Je demande 10 kamas par heure plus une somme symbolique d\\\'un kama.');
INSERT INTO `npc_questions` VALUES (1157, '', '', '', '', 'Tout d\\\'abord, si tu rencontres un inconnu qui pr?tend ?tre un gardien de Tain?la, tout comme moi, et qu\\\'il te demande le code pour rentrer dans ta maison, que lui r?ponds-tu ?');
INSERT INTO `npc_questions` VALUES (1158, '', '', '', '', 'Non, les aigles de Tain?la n\\\'ont pas besoin du code de ta maison pour rentrer chez toi, n\\\'oublie pas qu\\\'ils ont des ailes, ne donne donc jamais ton code ? un inconnu !');
INSERT INTO `npc_questions` VALUES (1159, '', '', '', '', 'F?licitation, tu as bien m?rit? que je t\\\'apprenne ma technique de m?ditation. \\nLes blessures inflig?es par les cr?atures qui r?dent en ce monde sont pour la plupart superficielles. \\nPour te soigner par m?ditation, il te faut t\\\'asseoir et laisser ton corps s\\\'envahir de la magie eniripsienne qui fl?ne en ce monde. \\n \\nAllez, le monde ext?rieur n\\\'attend plus que toi !');
INSERT INTO `npc_questions` VALUES (1160, '', '', '', '', 'Oh qu\\\'il est beau, qu\\\'il est beau, qu\\\'il est beau mon enclos ! Je veux que ?a continue encore et encore !  \\nMais malheureusement, les sangliers, c\\\'est comme les cochons. Plus ?a devient vieux et plus ?a devient b?te ! \\n \\nMe faut de la jeunesse ! Am?ne moi un marcassin, je te l\\\'ach?terai ? bon prix. Tu ne seras pas perdant, parole de Nissacram.');
INSERT INTO `npc_questions` VALUES (1161, '', '', '', '', 'J\\\'ach?te ton petit de marcassin coco ! 5000 kamas ! Pas de discussions possibles...');
INSERT INTO `npc_questions` VALUES (1162, '', '', '', '', 'Hum... quoi qu\\\'y a, encore ? Y a donc pas moyen de dormir un peu, dans c\\\'coin ? \\nBon, qu\\\'est-ce tu veux, petit ?');
INSERT INTO `npc_questions` VALUES (1163, '', '', '', '', 'Mon m?tier ? Ca s\\\'voit pas ? Je surveille les larves. \\nElles font peur aux pauv\\\' \\\'tits lapins, et faut que j\\\'les retienne. \\nEnfin... entre 2 roupillons....');
INSERT INTO `npc_questions` VALUES (1164, '', '', '', '', 'C\\\'est quoi, ce papelard ? Un rapport ? Pour Tarazed ? \\nAllez, c\\\'est quand m?me lui qui m\\\'paye, j\\\'peux bien remplir ?a...');
INSERT INTO `npc_questions` VALUES (1165, '', '', '', '', 'Bon, voil?, tu l\\\'as, maintenant, ce satan? papelard. \\nJe peux retourner pioncer tranquille ?');
INSERT INTO `npc_questions` VALUES (1167, '839;838', '', '', '', 'Bonjour, si tu viens me voir dans cette modeste demeure entour?e de pierre et de cailloux, c\\\'est que, toi aussi tu as la fi?vre du p?cheur ! Ou alors c\\\'est pour parler avec moi d\\\'amour et d\\\'autres choses.');
INSERT INTO `npc_questions` VALUES (1168, '840', '', '', '', 'Tr?s bien, mais avant, tu vas devoir me rendre un petit service. Aga dou a des app?ts pour moi, j\\\'en ai besoin tr?s rapidement. Voil? le deal : ram?ne-les en moins de 5 minutes et je t\\\'apprendrai les ficelles du m?tier.');
INSERT INTO `npc_questions` VALUES (1169, '', '', '', '', 'Euh reviens me voir un peu plus tard... un poisson m\\\'appelle...');
INSERT INTO `npc_questions` VALUES (1170, '', '', '', '', 'C\\\'est parti, je t\\\'attends.');
INSERT INTO `npc_questions` VALUES (1171, '', '', '', '', 'Tu es rapide comme le vent qui souffle derri?re les collines.Tu m\\\'as fait gagner du temps, je vais te donner un peu du mien pour apprendre le m?tier de p?cheur.');
INSERT INTO `npc_questions` VALUES (1172, '843;844', '', '', '', 'Tu es trop lent, je suis s?r qu\\\'ils ne sont plus bons. Va m\\\'en chercher d\\\'autres !');
INSERT INTO `npc_questions` VALUES (1173, '', '', '', '', 'Oui que voulez-vous ?');
INSERT INTO `npc_questions` VALUES (1174, '', '', '', '', 'Ah je vois, les app?ts de Bhan Laka. Tenez et d?p?chez-vous, il est tr?s peu patient.');
INSERT INTO `npc_questions` VALUES (1175, '845;846', '', '', '', 'Un peu trop lent... \\nMais tu peux retenter.');
INSERT INTO `npc_questions` VALUES (1176, '', '', '', '', 'Un supp?t du mal, ici, au sein m?me de la cit? blanche ? \\nHors de ma vue !');
INSERT INTO `npc_questions` VALUES (1177, '', '', '', '', 'Salutations fid?le disciple de Menalt, je vois que tu t\\\'es endurci depuis notre derni?re rencontre !\\nQue puis-je faire pour toi #1 ?');
INSERT INTO `npc_questions` VALUES (1178, '849', '', '', '0', 'Toi tu veux ?tre boucher ? Bah apr?s tout, le m?tier est tr?s simple, tu prends un gros couteau, un bout de bidoche et tu frappes. C\\\'est la m?me chose que lors des batailles. Le mouvement du poignet est juste un peu plus souple. Tu veux vraiment que je te montre ?');
INSERT INTO `npc_questions` VALUES (1179, '', '', '', '', 'Voil?, tu sais manier la hachette du boucher. Avec un peu d\\\'entra?nement en tant que boucher tu arriveras m?me ? r?cup?rer de la viande en plein milieu d\\\'une bataille haha! \\nN\\\'oublie pas d\\\'acheter une hachette pour exercer ton m?tier : j\\\'en vends si tu veux.');
INSERT INTO `npc_questions` VALUES (1180, '', '', '', '', 'Bonjour, bonjour ! Que d?sirez-vous, poulet, boeuf, cochon ? \\nNous avons de quoi satisfaire m?me les plus exigeants clients. Demandez donc ?');
INSERT INTO `npc_questions` VALUES (1181, '851;6140', '', '', '0', 'Tu veux devenir boucher ? Mais c\\\'est tr?s simple mon ami. La technique initiale utilise la m?me base que celle ancestrale de d?coupe de monstres. Une fois le coup pris c\\\'est une simple affaire d\\\'exp?rience. \\nToujours tent? ?');
INSERT INTO `npc_questions` VALUES (1182, '', '', '', '', 'Tu fais maintenant partie de la grande famille des bouchers. Bon courage ! \\nAh oui, n\\\'oublie pas d\\\'acheter une petite machette pour d?couper la viande. Tu ne pourras rien faire sans. Si tu veux, j\\\'en vends.');
INSERT INTO `npc_questions` VALUES (1183, '852', '', '', '0', 'Hum, mais quelle est cette mauvaise odeur ? Ce n\\\'est pourtant pas mes poissons qui sentent comme ?a...Ah, bonjour, que voulez-vous ?');
INSERT INTO `npc_questions` VALUES (1184, '853', '', '', '0', 'Vous savez, poissonnier n\\\'est pas un m?tier tr?s facile. M?me si on accepte de toucher des trucs gluants et collants toute la journ?e. Si on supporte une odeur infernale du lever du soleil ? la fin, voire plus... Suffit de couper la t?te de ces maudits poissons ! Vous le d?sirez vraiment ?');
INSERT INTO `npc_questions` VALUES (1185, '', '', '', '', 'Comme je disais : \\\'rien de plus fa... Ahem...\\\'. Bon courage pour ce m?tier. Ah n\\\'oubliez pas de vous procurer un hachoir ? poisson, indispensable pour exercer votre m?tier. J\\\'en vends si vous le d?sirez.');
INSERT INTO `npc_questions` VALUES (1186, '', '', '', '', 'Cette tour ? Il s\\\'agit du point de rencontre des trois plus puissants Ordres de Bonta : l\\\'Ordre de L\\\'Oeil Attentif, celui de l\\\'Esprit Salvateur et celui de l\\\'ordre du Coeur Vaillant.');
INSERT INTO `npc_questions` VALUES (1187, '', '', '', '', 'Le Coeur Vaillant regroupe les plus valeureux guerriers de Bonta. Bravoure, courage et d?termination sont n?cessaires pour y entrer. \\nNotre devise pourrait ?tre : \\\'Frappons vite et fort, le Mal ne se rel?vera pas\\\'');
INSERT INTO `npc_questions` VALUES (1188, '', '', '', '', 'L\\\'Oeil Attentif est charg? au sein de Bonta des missions n?cessitant d?licatesse et discr?tion. Certains disent que nous faisons de l\\\'espionnage ou du sabotage, mais personnellement je pr?f?re parler de prise d\\\'informations et de nettoyage ? grande ?chelle...');
INSERT INTO `npc_questions` VALUES (1189, '', '', '', '', 'L\\\'Ordre de l\\\'Esprit Salvateur est celui qui ma?trise le mieux les arcanes de la magie et de la gu?rison. \\nNous sommes vou?s au bien des autres, et ? la protection de la cit? contre les attaques d?moniaques des adeptes d\\\'H?cate de Br?kmar.');
INSERT INTO `npc_questions` VALUES (1190, '', '', '', '', 'Les Ordres sont des groupes arm?s, charg?s de faire respecter l\\\'honneur et l\\\'?quit? au sein de notre monde. \\nLes trois grands Ordres de Bonta sont l\\\'Oeil Attentif, l\\\'Esprit Salvateur et le Coeur Vaillant. \\nBien ?videmment, chacun d\\\'entre eux a ses us et coutumes, ses propres m?thodes pour arriver ? mener sa t?che ? bien. \\nIl me faudrait des heures pour vous expliquer toutes les subtilit?s des trois Ordres.');
INSERT INTO `npc_questions` VALUES (1191, '', '', '', '', 'Voyons voir... Oui, tu sembles avoir commenc? la formation de ce brave Amayiro. \\nIl est peut-?tre temps pour toi de choisir un ordre et de te sp?cialiser au mieux pour servir les int?r?ts de Bonta ! \\n \\nJe suis moi-m?me le ma?tre de l\\\'ordre du Coeur Vaillant, pour te renseigner sur un autre ordre, je te conseille de visiter les autres ?tages de la tour...');
INSERT INTO `npc_questions` VALUES (1192, '', '', '', '', 'Il me semble que tu n\\\'es pas encore pr?t ? rejoindre nos rangs.  \\nIl te faut d?j? suivre une formation. Va voir Amayiro, ? la caserne de la milice. Il t\\\'expliquera la marche ? suivre.');
INSERT INTO `npc_questions` VALUES (1193, '', '', '', '', 'Pour trouver sa tombe, il te suffit d\\\'aller jusqu\\\'? cet endroit que je viens de marquer sur ta carte. \\nDevant sa tombe se trouvent des fleurs que j\\\'y ai d?pos?es r?cemment, tu ne devrais pas la rater...');
INSERT INTO `npc_questions` VALUES (1194, '', '', '', '', 'Bonjour camarade Br?kmarien, que puis-je faire pour ton service ? \\n');
INSERT INTO `npc_questions` VALUES (1195, '', '', '', '', 'Hmm je vois, Oto Mustam t\\\'envoie pour r?cup?rer le rapport. \\nCela tombe bien je viens juste de le terminer. J\\\'esp?re qu\\\'il te sera utile, j\\\'ai h?te que les rues de cette ville s\\\'assombrissent.');
INSERT INTO `npc_questions` VALUES (1198, '', '', '', '', 'Tr?s bien, tu as donc d?j? retenu ma premi?re le?on : bien r?fl?chir aux diff?rents choix avant de prendre une d?cision d?finitive. \\nReviens d?s que tu seras s?r de toi.');
INSERT INTO `npc_questions` VALUES (1199, '', '', '', '', 'Bien, tu souhaites donc continuer sous ma tutelle, au sein de l\\\'Ordre du Coeur Vaillant. Choix judicieux que tu ne devrais pas regretter. \\nToutefois, pour valider ton adh?sion, il te faudra retrouver le greffier de l\\\'Ordre. Depuis que son chat de compagnie l\\\'a quitt?, il ?cume les tavernes. Ram?ne-le ici et nous confirmerons ta demande.');
INSERT INTO `npc_questions` VALUES (1200, '', '', '', '', 'Bien, tu souhaites donc continuer sous ma tutelle, au sein de l\\\'Ordre de l\\\'Oeil Attentif. Choix judicieux que tu ne devrais pas regretter. \\nToutefois, pour valider ton adh?sion, il te faudra retrouver le greffier de l\\\'Ordre de l\\\'Oeil Attentif. Depuis que  sa souris de compagnie l\\\'a quitt?, il ?cume les tavernes. Ram?ne-le ici et nous confirmerons ta demande.');
INSERT INTO `npc_questions` VALUES (1201, '', '', '', '', 'Bien, tu souhaites donc continuer sous ma tutelle, au sein de l\\\'Ordre de l\\\'Esprit Salvateur. Choix judicieux que tu ne devrais pas regretter. \\nToutefois, pour valider ton adh?sion, il te faudra retrouver la greffi?re de l\\\'Esprit Salvateur. Depuis que ses deux fr?res ont des ?tats d\\\'?me, elle ?cume les tavernes pour les retrouver. Ram?ne-la ici et nous confirmerons ta demande.');
INSERT INTO `npc_questions` VALUES (1202, '', '', '', '', 'Tu as donc tous les ?l?ments pour rejoindre l\\\'Ordre de l\\\'Esprit Salvateur. \\nEs-tu toujours s?r de ton choix ?');
INSERT INTO `npc_questions` VALUES (1203, '', '', '', '', 'Tu as donc tous les ?l?ments pour rejoindre l\\\'Ordre de l\\\'Oeil Attentif. \\nEs-tu toujours s?r de ton choix ?');
INSERT INTO `npc_questions` VALUES (1204, '', '', '', '', 'Tu as donc tous les ?l?ments pour rejoindre l\\\'Ordre du Coeur Vaillant. \\nEs-tu toujours s?r de ton choix ?');
INSERT INTO `npc_questions` VALUES (1205, '', '', '', '', 'Vous venez de la part de Jerhyn ? \\nJe n\\\'ai ni la force ni le courage de vous accompagner. \\nMais prenez ce badge, Jerhyn l\\\'utilisera pour ratifier votre adh?sion.');
INSERT INTO `npc_questions` VALUES (1206, '', '', '', '', 'Laissez-moi avec mon malheur... Il est parti, vous entendez ? Parti !');
INSERT INTO `npc_questions` VALUES (1207, '', '', '', '', 'Moi ? Vous suivre ? D?sol?, je ne peux pas... Tout ceci est trop r?cent.... \\nMais prenez mon badge, cela devrait suffire !');
INSERT INTO `npc_questions` VALUES (1208, '', '', '', '', 'Laissez moi tranquille avec mon chagrin...');
INSERT INTO `npc_questions` VALUES (1209, '', '', '', '', 'C\\\'est Elviana qui vous envoie ? Je vous aurais bien suivi, mais je dois retrouver mes deux fr?res, Aigurraf et Tabach. Ils seraient capables de toutes les folies, au vu de leur d?tresse. \\nVous avez l\\\'air d\\\'?tre quelqu\\\'un de confiance. Je vous laisse mon badge, montrez-le ? Elviana.');
INSERT INTO `npc_questions` VALUES (1210, '', '', '', '', 'Que fais-tu ici, esclave du bien ? \\nPrends garde que le Chaos ne te d?truise !');
INSERT INTO `npc_questions` VALUES (1211, '', '', '', '', 'Tu me sembles encore h?siter entre la facilit? et la d?ch?ance du bien et la gloire du mal. \\nSi le choix est difficile, va voir Oto Mutsam, il t\\\'aidera ? te d?cider.');
INSERT INTO `npc_questions` VALUES (1212, '', '', '', '', 'Tu me sembles avoir besoin d\\\'encore un peu d\\\'entrainement. \\nRetourne voir Oto Mustam.');
INSERT INTO `npc_questions` VALUES (1213, '', '', '', '', 'Salutations #1, je ne t\\\'ai pas vu arriver, je vois que tu as am?lior? ta force depuis notre derni?re rencontre ! \\nQue puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (1214, '', '', '', '', 'Tu es d?sormais pr?t ? rejoindre nos lignes. \\nQuel Ordre souhaites tu int?grer ? \\nLes Guerriers de l\\\'Ordre du Coeur Saignant, les Soigneurs de l\\\'Ordre de l\\\'Esprit Malsain ou encore l\\\'Ordre de l\\\'Oeil Putride ? \\nAttention, ce choix est important, il ne te sera pas permis d\\\'en changer par la suite ! \\n');
INSERT INTO `npc_questions` VALUES (1215, '', '', '', '', 'Pour rejoindre notre Ordre, montre nous un minimum ta valeur en rapportant 1 oeil de Corbac.');
INSERT INTO `npc_questions` VALUES (1216, '', '', '', '', 'Pour rejoindre notre Ordre, montre nous un minimum ta valeur en rapportant 1 Os de Chafer');
INSERT INTO `npc_questions` VALUES (1217, '', '', '', '', 'Pour rejoindre notre Ordre, montre nous un minimum ta valeur en rapportant 1 Poil de Barbe de Bwork Mage.');
INSERT INTO `npc_questions` VALUES (1218, '', '', '', '', 'Merci, et bienvenue ? toi, fr?re !');
INSERT INTO `npc_questions` VALUES (1219, '', '', '', '', 'Merci, et bienvenue ? toi, fr?re !');
INSERT INTO `npc_questions` VALUES (1220, '', '', '', '', 'Merci, et bienvenue ? toi, fr?re !');
INSERT INTO `npc_questions` VALUES (1221, '', '', '', '', 'Bonjour noble voyageur, que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (1223, '', '', '', '', 'Stop ! On ne passe pas !');
INSERT INTO `npc_questions` VALUES (1224, '', '', '', '', 'S\\\'entendre ? \\nA 10.000 kamas, on pourrait trouver un terrain d\\\'entente...');
INSERT INTO `npc_questions` VALUES (1225, '', '', '', '', 'Hein ? Non, il ne me pla?t pas. Recule-toi du mur, maintenant. \\nEt vite !');
INSERT INTO `npc_questions` VALUES (1226, '', '', '', '', 'Bonjour toi ! Tu vas bien ?  Je cherche ? renouveler ma garde-robe. Le quartier est r?put? pour ses c?l?bres tailleurs : Paro Cabanne, Laurent Saint-Yves, Caca Chonel et bien d\\\'autres.');
INSERT INTO `npc_questions` VALUES (1227, '', '', '', '', 'Je n\\\'ai jamais vu un sang aussi g?n?tiquement modifi?. \\nEn tout cas voici son analyse comme tu me l\\\'as demand');
INSERT INTO `npc_questions` VALUES (1228, '', '', '', '', 'Tu ne vois pas que je suis en patrouille ? Va-t\\\'en !');
INSERT INTO `npc_questions` VALUES (1229, '', '', '', '', 'Prends cette pince ! Pour retirer une dent ? un bouftou, c\\\'est un jeu d\\\'enfant, tu mets un pied sur la b?te, tu choisis une dent, et tu tires un coup sec avec la pince !');
INSERT INTO `npc_questions` VALUES (1230, '92', '', '', '0', 'Bienvenue ? la taverne du Chabrul?, vous venez f?ter la mort du patron ?');
INSERT INTO `npc_questions` VALUES (1231, '', '', '', '', 'Je ne travaillais pas hier soir, il n\\\'y a que l\\\'ivrogne l?-bas qui ?tait pr?sent...');
INSERT INTO `npc_questions` VALUES (1232, '', '', '', '', 'Hmm elle n\\\'est pas fra?che, elle a d? se r?chauffer pendant le voyage. \\nTu as de la chance, c\\\'est comme ?a que je les pr?f?re !');
INSERT INTO `npc_questions` VALUES (1233, '', '', '', '', 'Hmm je vois, c\\\'est encore un coup de Mustam, ? chaque fois que quelqu\\\'un le saoule, il me l\\\'envoie, la derni?re fois c\\\'etait Lothar Murofud, quel impatient celui l?... \\nJ\\\'ai un petit service ? te demander, va dire ? Tink Berval qu\\\'il me remplace. J\\\'en ai marre de surveiller cette porte !');
INSERT INTO `npc_questions` VALUES (1234, '', '', '', '', 'On aime pas trop les Br?kmariens par ici, tu ferais mieux de te tirer...');
INSERT INTO `npc_questions` VALUES (1235, '', '', '', '', 'Neuf pods seulement ? La milice y va vraiment avec des pincettes, si on veut exterminer Br?kmar un jour, il faut que ?a p?te ! \\nEnfin bon, vu que tu es envoy? par la milice et que tu m\\\'as l\\\'air sympathique, je te le fais ? -50%, ?a te fera donc 18000 kamas...');
INSERT INTO `npc_questions` VALUES (1237, '', '', '', '', 'Bonjour ? vous. Je vous prie de m\\\'excuser pour les grands mouvements dangereux que je fais. C\\\'est mon entra?nement quotidien vous savez.');
INSERT INTO `npc_questions` VALUES (1238, '', '', '', '', 'Quel beau soleil n\\\'est ce pas.');
INSERT INTO `npc_questions` VALUES (1239, '', '', '', '', 'Humm...il me faut des chaussures...');
INSERT INTO `npc_questions` VALUES (1240, '', '', '', '', 'Bonjour, que d?sirez vous ?');
INSERT INTO `npc_questions` VALUES (1241, '', '', '', '', 'Bonjour, n\\\'ayez pas peur surtout, je ne suis pas m?chant. Je suis un gentil sorcier vous savez. La plupart des sorciers n\\\'ont d\\\'ailleurs pas le cot? mauvais que la r?putation leur donne je vous assure.');
INSERT INTO `npc_questions` VALUES (1242, '', '', '', '', 'Nous vendons de tout et tout le temps, pour le plaisir de tout le monde. Je vous en prie prenez votre temps.');
INSERT INTO `npc_questions` VALUES (1243, '', '', '', '', 'Hmm, cette recette doit probablement venir des entrep?ts de Bonta, je me demande comment elle est arriv?e entre tes mains, enfin... \\nIl faut donc 3 mesures de poudre de Perlinpainpain et 1 huile de Koode par poudre, il faudrait aussi que tu me pr?te un silex pour que je r?alise la recette.');
INSERT INTO `npc_questions` VALUES (1244, '', '', '', '', 'Voil? de la poudre fra?chement moulue !');
INSERT INTO `npc_questions` VALUES (1245, '', '', '', '', 'Bonjouuur, je suis le grand Paro Cabanne, g?n?reux cr?ateur, incroyable styliste et g?nial proph?te. Que puis-je faire pour votre petite personne ?');
INSERT INTO `npc_questions` VALUES (1246, '', '', '', '', 'Bon c\\\'etait la derni?re fois, je veux bien ?tre aimable et femer les yeux sur la provenance de cette recette, mais il ne faut pas abuser de ma bont?...');
INSERT INTO `npc_questions` VALUES (1247, '', '', '', '', 'Enchant?, que puis-je faire pour vous ? Si vous cherchez quelconques pains ou brioches vous avez frapp? ? la bonne porte.');
INSERT INTO `npc_questions` VALUES (1248, '', '', '', '', 'Hmm, il veux que je le remplace ? la porte Nord ? Bon, j\\\'irais apr?s ma pause au Chabrul?. \\nPfff, je te remercie pas.');
INSERT INTO `npc_questions` VALUES (1249, '', '', '', '', '*hic* du jus de gloutovore ! *hic* \\nSi tu m\\\'en *hic* ram??ne au moins 4 je te ferais du v*hic* !');
INSERT INTO `npc_questions` VALUES (1250, '', '', '', '', 'Tu n\\\'es pas d?brouillard ! Pour faire de la bouillie il suffit de concasser 4 fleurs de Blop diff?rentes ? l\\\'aide d\\\'un concasseur Munster !');
INSERT INTO `npc_questions` VALUES (1251, '', '', '', '', 'Les capes Br?kmariennes ? N\\\'importe quel tailleur sait les fabriquer, 1 teinture sombre, 1 laine de boufton noir et 1 os de chafer et le tour est jou');
INSERT INTO `npc_questions` VALUES (1252, '', '', '', '', 'Gr?ce ? tes indications, 10 de tes coll?gues ont r?ussi un raid particuli?rement redoutable sur Br?kmar. Ils sont convi?s demain ? la c?r?monie pour leur remettre une m?daille. Ah mais j\\\'y pense...revenant juste de leur mission compl?tement ext?nu?s, ils n\\\'auront probablement pas le temps de qu?rir de nouvelles capes propres. Pourrais-tu leur en apporter ?');
INSERT INTO `npc_questions` VALUES (1253, '', '', '', '', 'Tu devrais trouver le Capitaine Koda et ses hommes au dortoir principal de la milice, ils ont bien m?rit? un peu de repos. ');
INSERT INTO `npc_questions` VALUES (1254, '', '', '', '', 'Quel type de capes ? des Capes Bontariennes bien ?videmment. Celles utilis?es pour toutes les c?r?monies officielles de la ville. Tout bon tailleur sait en coudre une avec une teinture magique bleue, une plume de corbac et une laine de boufton blanc.');
INSERT INTO `npc_questions` VALUES (1255, '', '', '', '', 'Voil? qui est g?n?reux de ta part. Donne-leur cette lettre d\\\'invitation par la m?me occasion. Mais fais bien attention de la leur donner avant demain.');
INSERT INTO `npc_questions` VALUES (1256, '', '', '', '', 'Ah ! Tr?s bien, voyons voir... \\n14 diamants ?! \\nPfff, un bon coup d\\\'?p?e et ce sera r?gl? ! Et en plus ce sera plus jouissif ! C\\\'est d?cid? j\\\'abandonne l\\\'histoire du poison, trop raffin? ? mon go?t h?h?. ');
INSERT INTO `npc_questions` VALUES (1257, '', '', '', '', 'Ahah pourquoi te donnerai-je cette recette ? Il faudrait me donner 1000 Kamas au moins pour me d?lier la langue.');
INSERT INTO `npc_questions` VALUES (1258, '', '', '', '', 'Merci ahahaha, je t\\\'ai bien eu. Comment une petite fille comme moi pourrait conna?tre la recette d\\\'un poison magique. ahahah !');
INSERT INTO `npc_questions` VALUES (1259, '', '', '', '', 'Pfff tu n\\\'as m?me pas assez de kamas. ');
INSERT INTO `npc_questions` VALUES (1260, '', '', '', '', 'Un poison magique, j\\\'ai pas en stock ?a.');
INSERT INTO `npc_questions` VALUES (1261, '', '', '', '', 'Et tu veux ?a pourquoi ? Attends je devine... Ah pour le tabi de Amayiro. C\\\'est donc ?a le jeu du moment d\\\'Oto. \\nBah je veux bien t\\\'en c?der une, mais contre 1000Kamas.');
INSERT INTO `npc_questions` VALUES (1262, '', '', '', '', 'Voil?, maintenant file voir ton ma?tre. ');
INSERT INTO `npc_questions` VALUES (1263, '', '', '', '', 'Mais tu n\\\'as m?me pas 1000 Kamas ! Reviens me voir quand tu seras plus riche. C\\\'est 1000 ou rien.');
INSERT INTO `npc_questions` VALUES (1264, '', '', '', '', 'Vous avez vraiment une fa?on tr?s ?trange d\\\'encourager les hommes de r?ves vous. \\nVous ne comprenez donc pas la joie qu\\\'apporte ma foire ? Ou alors vous ?tes jaloux... Enfin de toute fa?on voil? votre formulaire rempli.');
INSERT INTO `npc_questions` VALUES (1265, '', '', '', '', 'Hmm, merci. J\\\'irais apporter ?a ? Ture Inge pour qu\\\'il l\\\'analyse en profondeur.');
INSERT INTO `npc_questions` VALUES (1266, '', '', '', '', 'testA');
INSERT INTO `npc_questions` VALUES (1268, '', '', '', '', 'Bon on a un probl?me de taille, le puits de la milice est bouch?, je ne vois qu\\\'un seul homme capable de d?boucher le puits rapidement : toi ! \\n \\nDans le sous-sol de la milice il y a une salle d\\\'entra?nement appel? \\\'la cave aux scorpions\\\', le but est simple. \\nSurvivre ? l\\\'assaut de 8 scorpions, dans le but de s\\\'habituer au poison et d?velopper une r?sistance naturelle ? ses effets. \\nParle au garde ? l\\\'entr?e, il te fera rentrer et aura une surprise pour toi.');
INSERT INTO `npc_questions` VALUES (1269, '', '', '', '', 'tu es un chasseur de lvl 30+ et tu ?quipes ton arme.');
INSERT INTO `npc_questions` VALUES (1271, '', '', '', '', 'Quelle horreur, la prochaine fois nettoie un peu ce que je te demande de rapporter.');
INSERT INTO `npc_questions` VALUES (1272, '', '', '', '', 'Je suis le chef cuistot de la milice, alors \\\"bas les p?tes\\\" de ma cuisine.');
INSERT INTO `npc_questions` VALUES (1273, '', '', '', '', 'Laisse-moi tranquille !');
INSERT INTO `npc_questions` VALUES (1274, '', '', '', '', 'Ok ok #1, c\\\'est toi le plus fort...');
INSERT INTO `npc_questions` VALUES (1275, '', '', '', '', 'Alors #1, tu n\\\'as pas envie de te faire refaire les dents ? Pour toi ?a ne co?tera que 10 000 Kamas.\\nJe ne refuse jamais d\\\'aider un ami quand il en a besoin !');
INSERT INTO `npc_questions` VALUES (1276, '', '', '', '', 'Bienvenue ? la taverne de la Tabasse, qu\\\'est-ce que je peux faire pour toi #1 ? \\nD?sol? pour la derni?re fois, parfois j\\\'ai des trous de m?moire...');
INSERT INTO `npc_questions` VALUES (1277, '', '', '', '', 'Il para?t qu\\\'il y a une faiblesse dans les remparts de Br?kmar au Nord-Ouest du cimeti?re, je voudrais donc que tu trouves ce passage et que tu essayes d\\\'?valuer les risques. \\nAttention aux Chafers archers de Br?kmar, leur chef est capable de tuer un homme avec une seule fl?che, autant dire qu\\\'y aller seul serait du suicide....');
INSERT INTO `npc_questions` VALUES (1280, '', '', '', '', 'C\\\'est donc toi #1 qui est de corv?e cette semaine ? Prends des pommes de terres dans le tas ? terre et ?pluche-les sur la table du fond. \\nQuand t\\\'en auras ?pluch? 200 pods apporte-les-moi.');
INSERT INTO `npc_questions` VALUES (1281, '', '', '', '', 'Quel g?chis, tu les as coup?es au sabre ces patates ma parole ?');
INSERT INTO `npc_questions` VALUES (1282, '', '', '', '', 'Merci je vais ?tudier ?a tranquillement, j\\\'esp?re que tu as profit? de ta balade, les prochaines missions ne seront pas de tout repos...');
INSERT INTO `npc_questions` VALUES (1283, '', '', '', '', 'Vraiment tu veux te battre avec moi ? Dans ce cas, rentrons dans la maison qui se trouve derri?re moi. \\nC\\\'est la salle o? je m\\\'entra?ne habituellement.');
INSERT INTO `npc_questions` VALUES (1284, '', '', '', '', 'Bois donc un coup si t\\\'es un Homme ! Haha !');
INSERT INTO `npc_questions` VALUES (1285, '', '', '', '', 'Vous pas avoir peur. Nous pouvoir frapper vous, tuer vous, mais tout le monde cit? peut. Donc nous ?tre comme tout le monde.');
INSERT INTO `npc_questions` VALUES (1286, '', '', '', '', 'Je suis le Capitaine Essacarf, gardien de prison de la milice. \\nM?me si je suis tr?s vigilant, les Br?kmariens ont la f?cheuse tendance ? s\\\'?vader ? la moindre occasion...');
INSERT INTO `npc_questions` VALUES (1287, '', '', '', '', 'Buvez pour Br?kmar ! La meilleure cit? du monde ! Je servirai toujours pour ma ville !');
INSERT INTO `npc_questions` VALUES (1288, '248', '', '', '0', 'Nous avons am?nag? cette prison et sa luminosit? en prenant Br?kmar comme mod?le. J\\\'esp?re que vous vous y plairez. Hahaha !');
INSERT INTO `npc_questions` VALUES (1289, '', '', '', '', 'Buvez buvez... vive Br?kmar, vive Br?kmar...Pff ! Suis-je vraiment oblig?e de dire ?a ? ');
INSERT INTO `npc_questions` VALUES (1290, '', '', '', '', 'Bienvenue dans la noirceur de cette taverne. Je vous en prie, prenez donc place.');
INSERT INTO `npc_questions` VALUES (1291, '', '', '', '', 'Cliquotis Cliquequotis Clicliquotis Cliquotis Cliquotis Cliquot Cliquotis quotis !');
INSERT INTO `npc_questions` VALUES (1292, '', '', '', '', 'Criquatis Criquatquatis Criquatis CriCri Criquatis Criciquatis');
INSERT INTO `npc_questions` VALUES (1293, '', '', '', '', 'Hmm, une cr?ature rouge, qui crache du feu, et qui se d?place sur deux pieds ? \\nLa seule cr?ature qui ressemble ? ta description et qui vit dans la r?gion de Br?kmar est l\\\'Holba?d. Prends cette lettre et donne-la ? Amayiro, j\\\'y indique comment vaincre ce d?mon...');
INSERT INTO `npc_questions` VALUES (1294, '', '', '', '', 'Vous avez eu de la chance, j\\\'ai perdu, car j\\\'avais le soleil dans les yeux. \\nRevenez demain pour que je prenne ma revanche...');
INSERT INTO `npc_questions` VALUES (1295, '', '', '', '', 'Haha, j\\\'ai battu un milicien ! \\nQuand je vais raconter ?a ? mon oncle il sera fier de moi!');
INSERT INTO `npc_questions` VALUES (1296, '', '', '', '', 'QUOI ! Mais quel arnaqueur cet Oto. Allez tiens prends ?a. Apr?s tout, je n\\\'ai pas ? me plaindre avec le nombre d\\\'officiers qui atterrissent ici.');
INSERT INTO `npc_questions` VALUES (1297, '', '', '', '', 'QUOI ! il faudra me passer sur le corps plut?t !');
INSERT INTO `npc_questions` VALUES (1298, '', '', '', '', 'Bonjour, noble concitoyen, je suis l\\\'intendant de cette ville. Puis-je te renseigner ?');
INSERT INTO `npc_questions` VALUES (1299, '', '', '', '', 'Bonjour #1, Amayiro a fait pas mal d\\\'?loges ? ton ?gard. C\\\'est pourquoi j\\\'ai un petit service ? te demander.');
INSERT INTO `npc_questions` VALUES (1300, '', '', '', '', 'Grrr, va-t\\\'en toi et ton argent. Et dis ? Oto qu\\\'? partir d\\\'aujourd\\\'hui je ne lui fais plus cr?dit.');
INSERT INTO `npc_questions` VALUES (1301, '', '', '', '', 'Te voila #1, approche-toi, je ne voudrais pas que notre conversation s\\\'?bruite... \\nAlors, as-tu apport? ce que je t\\\'ai demand? ?');
INSERT INTO `npc_questions` VALUES (1302, '', '', '', '', 'Un nouvel imp?t ? Oto Mustam n\\\'a aucun scrupule ! Il d?valorise notre belle cit? ! Jamais je ne paierai cet imp?t !');
INSERT INTO `npc_questions` VALUES (1303, '', '', '', '', 'Bien, j\\\'ai un march? ? te proposer, il faudrait que tu ?limines quelqu\\\'un pour moi en ?change de 10000 kamas. Un d?nomm? Rimaraf habite au Sud Ouest de la ville. C\\\'est un milicien de haut rang, ce n\\\'est pas un mauvais bougre, mais il me fait de plus en plus d\\\'ombre. J\\\'aimerais que tu t\\\'introduises chez lui et que tu lui apportes un dessert empoisonn?. \\nIl a un faible pour les g?teaux, donc il mangera forcement de ce Blopisier empoisonn? ! \\nPour ?a il va falloir que tu demandes ? un boulanger de te fabriquer un g?teau avec ces ingr?dients ainsi que du poison.');
INSERT INTO `npc_questions` VALUES (1304, '', '', '', '', 'Reviens me voir un soir vers 21 h avec les ?l?ments qui sont indiqu?s sur cette liste pour que je t\\\'explique les d?tails de ta mission.');
INSERT INTO `npc_questions` VALUES (1305, '', '', '', '', 'Tu m\\\'as battu noblement. Et malgr? ma r?ticence envers ton sup?rieur, je te r?compenserai en payant cet imp?t.');
INSERT INTO `npc_questions` VALUES (1306, '', '', '', '', 'Bonjour mon ami #1, que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (1307, '', '', '', '', 'Encore un nouvel imp?t ? Prenez donc ce ch?que.');
INSERT INTO `npc_questions` VALUES (1308, '', '', '', '', 'Cliquot Cliquotis  ! Cliquotis Cliquequotis quotis Clicliquotis Cliquotis Cliquotis! !');
INSERT INTO `npc_questions` VALUES (1309, '', '', '', '', 'Ahahah, quelle bande d\\\'idiots ! Tu es tr?s efficace !');
INSERT INTO `npc_questions` VALUES (1310, '', '', '', '', 'Hey ! Tous les ch?ques ne sont pas l? ! Tu essaies de me rouler ou quoi ?');
INSERT INTO `npc_questions` VALUES (1311, '', '', '', '', 'Mais qu\\\'est ce que tu fais ? Tu essaies d\\\'?tre gentil ? Mais c\\\'est compl?tement idi...Hmmm, attends voir...Tu tentes de m\\\'amadouer, de la corruption en somme ! C\\\'est mal ! Tr?s mal ! Bravo ! \\n');
INSERT INTO `npc_questions` VALUES (1312, '', '', '', '', 'Pourquoi me proposer de l\\\'argent que tu n\\\'as pas ? Tu cherches ? me ridiculiser ? Tu violes l\\\'une des lois les plus importantes l? : ne pas ridiculiser quelqu\\\'un de plus fort que soi ! Je laisse passer pour cette fois, file !');
INSERT INTO `npc_questions` VALUES (1313, '', '', '', '', 'Que je m\\\'ennuie ! Toute la journ?e et toute la nuit ? surveiller cette bijouterie. Et en plus, il ne se passe jamais rien. Ca devient de plus en plus dur de garder les yeux ouverts.');
INSERT INTO `npc_questions` VALUES (1314, '', '', '', '', 'zzzZZZzzz');
INSERT INTO `npc_questions` VALUES (1315, '', '', '', '', 'Je vois, vous voulez mon poumon des plaines. Je pr?f?rerais mourir plut?t que de vous le donner. Gaaaaarde !');
INSERT INTO `npc_questions` VALUES (1316, '', '', '', '', 'Oh, Amayiro a enfin envoy? quelqu\\\'un ? mon secours ? \\nLib?re-moi vite et aide-moi ? m\\\'?chapper !');
INSERT INTO `npc_questions` VALUES (1317, '', '', '', '', 'Je suis le colonel Lyeno de la milice de Bonta, j\\\'attends que cette andouille d\\\'Amayiro daigne envoyer quelqu\\\'un ? mon secours...');
INSERT INTO `npc_questions` VALUES (1318, '', '', '', '', 'Oh quelle merveille ! Je suis riche hahahahaha ! Tu peux filer toi !');
INSERT INTO `npc_questions` VALUES (1319, '987;98', '', '', '0', 'Escalope Amaknaise !  Spaghettis bworkoni?ses! Raaaaavioliiiis ! gratin de corbac friiit ! \\nHeu,hum...Qu\\\'est-ce que vous voulez ? \\n');
INSERT INTO `npc_questions` VALUES (1320, '', '', '', '', 'Ah c\\\'est votre tour de corv?e ? Si vous pouviez m\\\'?plucher 20 patates, vous seriez un ange. Et si ?a ne vous g?ne pas vous pourriez aussi m\\\'apporter 6 pattes de corbac et 3 yeux pour le go?t ? Je vous en remercie d\\\'avance. Faites bien attention ? ne pas vous couper.');
INSERT INTO `npc_questions` VALUES (1322, '', '', '', '', 'Merci mille fois, je vais pouvoir finir le repas.');
INSERT INTO `npc_questions` VALUES (1323, '', '', '', '', 'Ah je vous prie de m\\\'excuser, je n\\\'ai pas d? bien m\\\'exprimer, j\\\'ai besoin de 20 pommes de terre ?pluch?es, 6 pattes et  3 yeux de corbacs. Excusez-moi encore.');
INSERT INTO `npc_questions` VALUES (1324, '', '', '', '', 'Je m\\\'appelle Sbab. J\\\'ai ?t? captur?e il y a 1 mois de cela lors d\\\'un raid de vos guerriers sur Bonta. Arriv?e ici on m\\\'a laiss? le choix entre faire ?ternellement la cuisine ou mourir imm?diatement. Vous devinez quel fut mon choix.');
INSERT INTO `npc_questions` VALUES (1325, '', '', '', '', 'Oh ! Cet Oto est vraiment le plus mauvais homme que je connaisse. Et le plus cruel aussi. Je n\\\'aime pas les d?mons de Br?kmar par principe, mais je respecte au moins ceux qui ont de l\\\'honneur. Tr?s peu de d?mons respectent encore l\\\'ancien code aujourd\\\'hui. Je comprends votre situation, si vous voulez garder votre honneur je peux faire en sorte de mentir sur le fait que vous m\\\'ayez remis ces oreilles.');
INSERT INTO `npc_questions` VALUES (1326, '', '', '', '', 'En ?tes-vous s?r ? Ce genre de secret p?se lourd . Un d?mon de l\\\'ancien temps n\\\'est gu?re appr?ci? chez les idiots d\\\'aujourd\\\'hui. Cela peut changer votre future destin?e ?');
INSERT INTO `npc_questions` VALUES (1327, '', '', '', '', 'Je vois, vous n\\\'?tes peut-?tre gu?re diff?rent. Faites comme bon vous semble.');
INSERT INTO `npc_questions` VALUES (1328, '', '', '', '', 'C\\\'est un beau champo, dis-moi, je m\\\'attendais ? r?cup?rer un truc tout trou? venant de ta part. Haha !');
INSERT INTO `npc_questions` VALUES (1329, '', '', '', '', 'Que je suis contente ! Les d?mons ne sont pas tous des idiots, je le savais. Gardez toujours votre honneur ! Peut-?tre que cette guerre ressemblerait ? quelque chose si tout le monde ?tait comme vous. Bon je vais crier sur tous les toits. Filez maintenant !');
INSERT INTO `npc_questions` VALUES (1330, '', '', '', '', 'HYYAAAAH Par Jiva, les pauvres Wabbits ! VOUS ?TES UN MONSTRE, ALLEZ-VOUS-EN !');
INSERT INTO `npc_questions` VALUES (1331, '', '', '', '', 'ENCORE VOUS ? ALLEZ-VOUS-EN ! JE NE VEUX PAS VOUS VOIR !');
INSERT INTO `npc_questions` VALUES (1332, '', '', '', '', 'M?me si cela para?t trop facile, il va bien falloir me r?soudre ? inculper cet Oni Tnec. \\nMaintenant, il faut mettre la main dessus, je vais essayer d\\\'avoir des renseignements sur lui.');
INSERT INTO `npc_questions` VALUES (1333, '', '', '', '', 'Hmm, il fait un coupable id?al mais il manque encore quelque chose...');
INSERT INTO `npc_questions` VALUES (1334, '', '', '', '', 'Bonjour je suis le capitaine Koda, je suis tr?s occup?, car je pr?pare un assaut important de Br?kmar avec neuf de mes hommes.');
INSERT INTO `npc_questions` VALUES (1335, '', '', '', '', 'Je suis ext?nu?, mais fier d\\\'avoir mis une d?rouill?e ? Br?kmar. \\nMes hommes sont partis f?ter ?a, mais moi je vais aller faire une bonne nuit.');
INSERT INTO `npc_questions` VALUES (1336, '', '', '', '', 'Oh je vois, nous sommes invit?s par Danathor, pour recevoir une m?daille d\\\'honneur ! Mais j\\\'y pense, sans cape Bontarienne nous ne pourrons jamais assister ? cette c?r?monie...');
INSERT INTO `npc_questions` VALUES (1337, '', '', '', '', 'Je te remercie, gr?ce ? toi nous pourrons assister ? la c?r?monie d\\\'honneur. Bon je vais pouvoir faire une sieste jusque ce soir, maintenant.');
INSERT INTO `npc_questions` VALUES (1338, '', '', '', '', 'Vous avez de la chance j\\\'ai justement une potion de d?senvoutement sur moi. \\nVoil? colonel, vous avez retrouv? votre apparence normale.');
INSERT INTO `npc_questions` VALUES (1339, '', '', '', '', 'Ah bonjour Lyeno, vous avez maigri, non ? La derni?re fois que je vous ai vu, vous ?tiez envelopp? et raide comme du bois...');
INSERT INTO `npc_questions` VALUES (1340, '', '', '', '', 'Rendez moi ce m?daillon !');
INSERT INTO `npc_questions` VALUES (1342, '', '', '', '', 'Vous ne passerez pas ! Bande de Bontariens !');
INSERT INTO `npc_questions` VALUES (1343, '', '', '', '', 'J\\\'abandonne vous ?tes une proie trop grosse pour moi, je vais aller attaquer des araknes. \\nMouhaha !');
INSERT INTO `npc_questions` VALUES (1345, '1004;100', '', '', '0', 'Tu veux jouer ? \\\"Pierre-Feuille-ciseaux\\\" avec moi ? Insolent, tu ne sais donc pas que je suis le champion d\\\'Amakna ? ce jeu. De toute fa?on je ne joue pas sans argent... \\nLa partie se joue en 3 manches, 10 kamas la manche et tu t\\\'arr?tes quand tu veux. \\nPour gagner il faut absolument remporter les 3 manches.');
INSERT INTO `npc_questions` VALUES (1346, '1006;1007;100', '', '', '0', '*Agite la main*');
INSERT INTO `npc_questions` VALUES (1347, '', '', '', '', 'Hmm, si tu gagnes une partie, je t\\\'apprends ? y jouer n\\\'importe o? et avec n\\\'importe qui.');
INSERT INTO `npc_questions` VALUES (1348, '1010;101', '', '', '0', '*Ciseaux* \\nHmm, j\\\'ai perdu, tu n\\\'es pas si mauvais, passons ? la 2eme manche.');
INSERT INTO `npc_questions` VALUES (1349, '', '', '', '', '*Pierre* \\nHmm, j\\\'ai perdu, tu n\\\'es pas si mauvais, passons ? la 2eme manche.');
INSERT INTO `npc_questions` VALUES (1350, '1014;101', '', '', '0', '*Feuille* \\nHmm, j\\\'ai perdu, tu n\\\'es pas si mauvais, passons ? la 2eme manche.');
INSERT INTO `npc_questions` VALUES (1351, '1017;1016;101', '', '', '0', '*Agite la main*');
INSERT INTO `npc_questions` VALUES (1352, '', '', '', '', '*Ciseaux* \\nHmm, j\\\'ai perdu, tu es plut?t bon, passons ? la 3eme manche.');
INSERT INTO `npc_questions` VALUES (1353, '', '', '', '', '*Pierre* \\nHmm, j\\\'ai perdu, tu es plut?t bon, passons ? la 3eme manche.');
INSERT INTO `npc_questions` VALUES (1354, '', '', '', '', '*Feuille* \\nHmm, j\\\'ai perdu, tu es plut?t bon, passons ? la 3eme manche.');
