INSERT INTO `npc_questions` VALUES (1358, '', '', '', '', '*Agite la main*');
INSERT INTO `npc_questions` VALUES (1359, '', '', '', '', 'Tu n\\\'as m?me pas 10 kamas sur toi, esp?ce de roublard !');
INSERT INTO `npc_questions` VALUES (1360, '', '', '', '', '*Ciseaux* \\nHmm, mais comment ? Ce n\\\'est pas possible ? Tricheur !');
INSERT INTO `npc_questions` VALUES (1361, '', '', '', '', '*Feuille* \\nHmm, mais comment ? Ce n\\\'est pas possible ? Tricheur !');
INSERT INTO `npc_questions` VALUES (1362, '', '', '', '', '*Pierre* \\nHmm, mais comment ? Ce n\\\'est pas possible ? Tricheur !');
INSERT INTO `npc_questions` VALUES (1366, '', '', '', '', 'Comme promis, voici ta r?compense, mais je me demande bien comment tu as r?ussi ? gagner...');
INSERT INTO `npc_questions` VALUES (1367, '', '', '', '', 'Bonjour, je me nomme Hertuen, mon r?le est de d?fendre la porte de la garnison d\\\'Amakna. Que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (1368, '', '', '', '', 'La garnison a pour fonction de prot?ger les habitants du village, lorsqu\\\'ils se font agresser par des guerriers venu de l\\\'Est.');
INSERT INTO `npc_questions` VALUES (1369, '', '', '', '', 'Humm laissez moi travailler tranquille.');
INSERT INTO `npc_questions` VALUES (1370, '', '', '', '', 'Ah ! Le rapport sur les changements d\\\'activit?s volcaniques de la r?gion ! Je l\\\'ai compl?tement oubli? celui l?.  Voyez vous en cherchant pr?s des mines j\\\'ai d?couvert des ossements d\\\'animaux d?moniaques primaires qui semblent dater de la toute premi?re guerre Divine...');
INSERT INTO `npc_questions` VALUES (1371, '', '', '', '', 'Oui ! Oui ! J\\\'ai compris ! Pour ?tre franc je n\\\'ai pas fait ce rapport. Si vous en voulez un il va falloir que vous bougiez vos fesses pour moi. Ces ossements sont trop importants pour que je les abandonne.');
INSERT INTO `npc_questions` VALUES (1372, '', '', '', '', 'Vous n\\\'aviez pas d\\\'autres choix de toute fa?on. Si vous reveniez voir Oto sans le rapport je suis certain que...Enfin bref ! Il faut que vous collectiez des ?chantillons de lave situ?es sur un p?rim?tre de 5 lieux environ. Trouvez de petites pointes sortant du sol pour votre collecte, c\\\'est l? que vous risquerez le moins de mourir. ');
INSERT INTO `npc_questions` VALUES (1373, '', '', '', '', 'Vous avez trouv? les ?chantillons que je vous ai demand?s ?');
INSERT INTO `npc_questions` VALUES (1374, '', '', '', '', 'Merci, commen?ons.........Mais....Sang de Djaul ! La lave n\\\'a pas les caract?ristiques attendues ! Tout s\\\'accorde ? dire que le courant magmatique est en mouvement. Il faut absolument savoir ce qu\\\'il se passe la dessous. Il y a une entr?e vers une grotte au Sud-Est d\\\'ici. Au fond de cette grotte une rivi?re de lave coule. Je pense que c\\\'est le meilleur endroit pour ?tudier le ph?nom?ne. H?las la grotte est infest?e de monstres. Vous allez donc m\\\'y emmener et me servir de bouclier.');
INSERT INTO `npc_questions` VALUES (1375, '', '', '', '', 'Mais il en manque, je ne peux pas faire de rapport correct si je n\\\'ai pas des ?chantillons qui couvrent toute la superficie d\\\'?tude.');
INSERT INTO `npc_questions` VALUES (1376, '', '', '', '', 'Je vois, je vois...Patientez un petit peu je vous prie.......Voil?. \\nBon il semblerait que la masse magmatique bouge effectivement, mais de mani?re totalement chaotique. Br?kmar a donc peu de chance d\\\'?tre ensevelie sous les flots de lave. J\\\'aimerai bien conna?tre ce qui provoque ces perturbations cela dit...Je vais rester un peu ici. Tenez votre d?sir? rapport.');
INSERT INTO `npc_questions` VALUES (1377, '', '', '', '', 'Etrange, tr?s ?trange. Ce qui provoque des perturbations du courant magmatique est un tr?s puissant flux magique. Encore plus ?trange j\\\'ai d?couvert un peu plus loin la porte d\\\'une esp?ce de forteresse. Un m?canisme semble contr?ler l\\\'ouverture. Avec un peu de temps je percerai le myst?re.');
INSERT INTO `npc_questions` VALUES (1378, '', '', '', '', 'Humm...Je suis occup? pour le moment.');
INSERT INTO `npc_questions` VALUES (1379, '', '', '', '', 'Des perturbations...gnagnagna...Flux magique...gnagnagna....Ah ! Pas de risques importants pour Br?kmar. Voil? ce qui m\\\'int?ressait. Le reste c\\\'est bon pour les scientifiques, qu\\\'est ce qu\\\'on en a ? faire !  \\nParce que tu vois pendant que tu glandouillais dans les cavernes une division d\\\'espions Bontarien a p?n?tr? Br?kmar ! Bon on les a tous chopp? sauf un. Mais celui-l? a reussi ? s\\\'enfuir avec des documents importants! Rattrape-le et r?cup?re les documents et vite ! N\\\'h?site pas ? demander aux gardes et sentinelles que tu croiseras s\\\'ils ne l\\\'ont pas aper?u.');
INSERT INTO `npc_questions` VALUES (1380, '', '', '', '', 'Ichitik, iki ink nikiril, cimmik pivik iki itilik ?');
INSERT INTO `npc_questions` VALUES (1381, '', '', '', '', 'Lik millik privik kik jik\\\'i pivik tik dinnik iki dik tik pirtigik mik pivik dik clirvinikik. Rippirtik mik quilikik chisik ii migik itk sik tik fik binik chisix tik iki clirviniki ispisik ink instik.');
INSERT INTO `npc_questions` VALUES (1383, '', '', '', '', 'Si tu cherches le guerrier de Bonta il s\\\'est enfui vers le Nord. Tu devrais pouvoir les suivre facilement ? la trace. Essaye de croiser les sentinelles pour savoir si elles l\\\'ont vu');
INSERT INTO `npc_questions` VALUES (1384, '', '', '', '', 'Mircik tik, sik tik bisik dik mik limirik ivinirik, n\\\'isik pik i rivinirk mik nirrik !');
INSERT INTO `npc_questions` VALUES (1385, '', '', '', '', 'Tik nik triviris pis tijirs lik ripinsik dik tinik dictinnirik, riflichik ink pik ii lik fi?inik dik nirrik ink nikirik...');
INSERT INTO `npc_questions` VALUES (1386, '', '', '', '', 'Rien ? signaler ici.');
INSERT INTO `npc_questions` VALUES (1387, '', '', '', '', 'Un homme en blanc vient de passer en courant. Quand il m\\\'a vu il s\\\'est engouffr? vers l\\\'Est');
INSERT INTO `npc_questions` VALUES (1388, '', '', '', '', 'Un magicien vient de passer en courant, je n\\\'ai pas r?ussi ? l\\\'arr?ter il allait beaucoup trop vite. Vous pouvez encore l\\\'attraper, il est parti vers le nord-ouest');
INSERT INTO `npc_questions` VALUES (1389, '', '', '', '', 'Rien ? signaler dans le coin.');
INSERT INTO `npc_questions` VALUES (1390, '', '', '', '', 'Un Bontarien m\\\'a surpris et m\\\'a assomm?. Je n\\\'ai m?me pas pu distinguer ses traits car son visage se fondait dans la nuit., j\\\'ai honte par Djaul ! Les traces qu\\\'il a laiss?es semblent se diriger vers l\\\'Ouest j\\\'esp?re qu\\\'il n\\\'a pas pris trop d\\\'avance.');
INSERT INTO `npc_questions` VALUES (1391, '', '', '', '', 'Faites attention vous vous rapprochez du front de la guerre. Rien ? signaler de ce cot? ci en tout cas.');
INSERT INTO `npc_questions` VALUES (1392, '', '', '', '', 'Attention vous arrivez ? la Gorge de Sidimote, un etranglement de terrain, passage quasi-unique entre Bonta et Br?kmar. Autant dire que les affrontements y sont courant. En tout cas ici c\\\'est calme pour le moment.');
INSERT INTO `npc_questions` VALUES (1393, '', '', '', '', 'J\\\'ai aper?u au loin un homme v?tu d\\\'une cape bleue qui courait vers le Nord. Etait-ce un Bontarien en fuite ? Si c\\\'est le cas il n\\\'a pas bien choisi son chemin : Il fon?ait droit vers la Gorge de Sidimote o? nos guerriers patrouillent');
INSERT INTO `npc_questions` VALUES (1394, '', '', '', '', 'On vient de coincer un Bontarien en fuite Ahaha ! Il a d? se croire sauv? en apercevant la gorge de Sidimote. Dommage pour lui que nous ?tions l? Ahah! Hu ? Vous le cherchiez ? Bah l\\\'un de mes gars doit l\\\'emmener dans les quartiers d\\\'interrogation de la prison. ');
INSERT INTO `npc_questions` VALUES (1395, '', '', '', '', 'Que voulez-vous ? Nous sommes dans une zone tr?s dangereuse. On peut se faire attaquer ? chaque moment par ces satan?s Bontariens ! Vous feriez mieux de ne pas rester dans les parages.');
INSERT INTO `npc_questions` VALUES (1396, '', '', '', '', 'Ah vous n\\\'avez pas acc?s aux quartiers d\\\'interrogations ? Je vois, je vais vous donner un laisser-passer temporaire...Votre nom ? #1 ? Ah mais je me souviens, Oto m\\\'a parl? de vous aux derni?res r?unions. Du bon boulot ! Je vous en fait un d?finitif du coup. Tenez.');
INSERT INTO `npc_questions` VALUES (1397, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (1398, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (1399, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (1400, '', '', '', '', 'Nee mee d??raangeez paas. Jee suuiis een traaiin d\\\'eetuudiieer dees doossieer d??liicaats.');
INSERT INTO `npc_questions` VALUES (1401, '', '', '', '', 'Voouus toombeez biieen ! Il paaraait quee voouus poourriez ideentiifiieer lee boontaarieen quuii a attaaqu??? braakmaar? ');
INSERT INTO `npc_questions` VALUES (1402, '', '', '', '', 'Voil? le poison en question, d?pose le gateau dans son buffet, il a l\\\'habitude de se faire livrer, il le trouvera certainement demain matin. \\nBonne chance !');
INSERT INTO `npc_questions` VALUES (1403, '', '', '', '', 'Es-tu vraiment certain de ne pas vouloir ob?ir ? un ordre de l\\\'intendant de Bonta ?');
INSERT INTO `npc_questions` VALUES (1404, '', '', '', '', 'Tr?s bien, je trouverais bien quelqu\\\'un d\\\'autre pour effectuer cette besogne. \\nMais ne t\\\'avise pas d\\\'en parler ? quiconque o? tu subiras le m?me sort que Rimaraf !');
INSERT INTO `npc_questions` VALUES (1405, '', '', '', '', 'Qu\\\'as- tu fait des graines que je t\\\'avais donn?es ? Bon si tu en veux d\\\'autres cela te co?tera 1000 kamas !');
INSERT INTO `npc_questions` VALUES (1406, '', '', '', '', 'OUI J\\\'AIME LE BLEU CIEL ! ET ALORS ?! JE SUIS QUAND MEME UN HABITANT DE BRAKMAR !');
INSERT INTO `npc_questions` VALUES (1407, '', '', '', '', 'La justice Br?kmarienne m\\\'a toujours fait rire avec ses jugements cruels, exag?r?s et totalement sadiques. Aujourd\\\'hui, bizarrement j\\\'en ris beaucoup moins');
INSERT INTO `npc_questions` VALUES (1408, '', '', '', '', 'Mais il faut vraiment ?tre idiot pour ne pas voir le vrai coupable !');
INSERT INTO `npc_questions` VALUES (1409, '', '', '', '', 'C\\\'eest ?traange ceelaa ne coorreespoond paas aaveec lees infoormaations foournies paar lees seentinelles. Voous ooseez meentiir deevaant uun triibunaal braakmaarieen ? Jee n\\\'aai quee faaire dees d??moons quii nee reespeectent pluus lee prootoccolle aalleez voous een. \\n');
INSERT INTO `npc_questions` VALUES (1411, '', '', '', '', 'Effeectiiveement ceelaa coorreespoond aaveec lees t??mooignaagees dees seentiineelles. \\nMeercii poouur vootree aaide. Teneez cee peetiit pr??eseent poouur r??coommpeenseer vootre vaaleuur d??mooniaaque.');
INSERT INTO `npc_questions` VALUES (1412, '', '', '', '', 'Lee cooupaablee est paarmiis eeux, j\\\'een suuis s??r. Sii voous nee saaveez paas diites lee mooi fraancheemeent !');
INSERT INTO `npc_questions` VALUES (1413, '', '', '', '', 'Voouus voouus fiicheez de moooi ! Voous voouuleez quee 3 innooceeents meuurent ? Jeee vooois voos ??tees paarmiis cees jeeunes d??moons saans ceervelle. Alleez voous eeen ne reeveeneez jaamaaais iccii. Jee deeteeste lees d??moons cooomme vouus, siii jee voous reevoois jee vouus feeraai paayeer ceet affroont !');
INSERT INTO `npc_questions` VALUES (1415, '', '', '', '', 'Les champos ? Ce sont les ma?tres bolet qui les portent, tu en trouveras dans les champs au Sud de Bonta. \\nInutile de prendre un champo destin? au combat, le premier venu fera l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (1416, '', '', '', '', 'Je doute qu\\\'il s\\\'agisse d\\\'un membre de la milice, car seuls les boulangers de Bonta connaissent la recette du Blopisier. \\nDemande ? Ture Inge, il poss?de s?rement des documents sur la fa?on de mener un interrogatoire...');
INSERT INTO `npc_questions` VALUES (1417, '', '', '', '', 'Bon dans ce cas, il faudrait que tu rapportes du venin de scorbute, car notre r?serve diminue, il y en a plein dans les landes de Sidimote. \\nQuand tu en auras pr?lev? 30 pods, apporte-les-moi.');
INSERT INTO `npc_questions` VALUES (1418, '', '', '', '', 'Parfait, je vais pouvoir reprendre la s?ance de torture avec Trof Hapyus.');
INSERT INTO `npc_questions` VALUES (1419, '', '', '', '', 'J\\\'ai entendu dire que des villageois d\\\'Amakna ?taient partis vers l\\\'Est pour prendre partie ? la guerre qui oppose Bonta et Br?kmar. \\nPendant quelques jours,  je propose de changer les papiers de ceux qui ont d?sert? et qui souhaitent venir se r?installer dans notre province. \\nEn revanche, je ne peux rien pour les personnes d\\\'un haut grade, car leurs chefs les retrouveraient trop facilement...');
INSERT INTO `npc_questions` VALUES (1420, '', '', '', '', 'Que puis-je pour toi habitant de Br?kmar ?');
INSERT INTO `npc_questions` VALUES (1421, '', '', '', '', 'Que puis-je pour toi habitant de Bonta ?');
INSERT INTO `npc_questions` VALUES (1422, '', '', '', '', 'Revenir habiter ? Amakna est possible, mais tu perdras ton grade au sein de ta milice et tous les avantages qui sont li?s. \\nSi tu es toujours d?cid?, il est n?cessaire de changer tes papiers et d\\\'enregistrer ? nouveau dans le registre d\\\'Amakna, ces frais peuvent varier suivant le rang que tu as obtenu aupr?s de ta milice.');
INSERT INTO `npc_questions` VALUES (1423, '', '', '', '', '#1, tu es de nouveau un habitant d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (1424, '1073;1250;1077', '', '', '0', 'Doh mon anneau !');
INSERT INTO `npc_questions` VALUES (1425, '', '', '', '', 'Tu es d?j? de retour ? Je pensais que Danathor te donnerait une mission, enfin bon, si tu as du temps libre, demande au cuisinier, il recherche des ingr?dients pour le repas de ce soir.');
INSERT INTO `npc_questions` VALUES (1426, '', '', '', '', 'Salut #1, tu viens me donner un coup de main pour ce soir ?\\nIl me faut de la viande d\\\'oiseau : une dizaine de cuisses de tofu, essaye de trouver un chasseur qui acceptera de t\\\'en vendre !');
INSERT INTO `npc_questions` VALUES (1427, '', '', '', '', 'Merci, voil? 200 kamas pour la course, n\\\'h?site pas ? revenir me voir, je recherche r?guli?rement des ingr?dients.');
INSERT INTO `npc_questions` VALUES (1428, '', '', '', '', 'Hmm, on dirait que tu as trouv? le coupable, je vais attendre le rapport des autres enqu?teurs et surveiller ce lascar de pr?s !');
INSERT INTO `npc_questions` VALUES (1429, '', '', '', '', 'Il n\\\'y a aucun suspect potentiel dans ton rapport d\\\'enqu?te, tu devrais continuer les interrogatoires....');
INSERT INTO `npc_questions` VALUES (1430, '1074', '', '', '', 'Vous ?tes devant ? la pichine. Ma cr?ation.');
INSERT INTO `npc_questions` VALUES (1431, '1078', '', '', '', 'Je trouvais fatigant de devoir me balader avant de trouver un coin tranquille alors j\\\'ai amen? le coin tranquille ? moi. J\\\'y ai plac? un tas de poissons et voil');
INSERT INTO `npc_questions` VALUES (1432, '', '', '', '', 'Je n\\\'ai plus rien ? te dire #1, de toute fa?on je suis trop occup');
INSERT INTO `npc_questions` VALUES (1433, '', '', '', '', 'Mince, te voil? dans de beaux draps, tu devrais fabriquer de fausses preuves et trouver un coupable, car Amayiro n\\\'abandonnera pas aussi facilement.\\nD\\\'ailleurs, tu devrais te m?fier de lui, j\\\'ai l\\\'impression qu\\\'il commence ? te jalouser...');
INSERT INTO `npc_questions` VALUES (1435, '', '', '', '', 'En donnant ? manger aux pichons ce matin j\\\'ai fait tomber mon anneau au fond. Ca m\\\'arrive tout le temps.');
INSERT INTO `npc_questions` VALUES (1436, '1079', '', '', '', 'Bah en fait j\\\'y ai mis tous les poissons que j\\\'ai pu trouver...Apr?s quelques incidents une nouvelle esp?ce semble ?tre apparue. Je l\\\'ai nomm? Pichon. ');
INSERT INTO `npc_questions` VALUES (1437, '', '', '', '', 'Les pichons sont une esp?ce assez particuli?re, vous savez. Ces poissons ont une taille qui peut varier ?norm?ment. Cela a attir? nombre de p?cheurs. Ils parlaient tout le temps d\\\'eud\\\'compet entre eux, j\\\'ai jamais bien compris, mais du coup j\\\'ai d?cid? de surnommer le pichon, pichon eud\\\'compet.');
INSERT INTO `npc_questions` VALUES (1438, '', '', '', '', 'Hmm tu cherches des documents pour mener ? bien un interrogatoire ? \\nJe te conseille le formulaire d\\\'enqu?te n? 36, mais je le vends 500 kamas l\\\'exemplaire...');
INSERT INTO `npc_questions` VALUES (1439, '', '', '', '', 'Montre ? Amayiro ce poison en disant que tu l\\\'a retrouv? pas loin de la maison de Rimaraf. \\nJ\\\'y ai inscrit le nom \\\'Oni Tnec\\\' sur la preuve d\\\'achat. \\nSi cela ne marche pas, demande ? Anik Mech de te fabriquer un nouveau badge ? ce nom pour une mission soi-disant confidentielle...');
INSERT INTO `npc_questions` VALUES (1440, '', '', '', '', 'Humm ! Amayiro veut encore plus de preuves, prend ces aveux cela para?tra plus cr?dible... \\nSinon, je n\\\'ai plus trop d\\\'id?es, demande ? Ture Inge comment mener une enqu?te, il aura peut-?tre des suggestions...');
INSERT INTO `npc_questions` VALUES (1441, '', '', '', '', 'Tu veux un badge de milice pour une mission secr?te au nom de \\\'Oni Tnec\\\' ? \\nHumm ! d\\\'accord, mais cela te co?tera 1000 kamas, la prochaine fois demande ? Amayiro une feuille de mission, je voudrais pas que ?a me retombe sur les doigts...');
INSERT INTO `npc_questions` VALUES (1442, '', '', '', '', 'Trr?s bieen. Jee pr??f??re uun d??mon fraanc, quii aassuume laa d?faaite et reespeectueeuux de cees ancieens quee lees eceervell??s d\\\'auujouurd\\\'huii. Voous pouuveez diispooser.');
INSERT INTO `npc_questions` VALUES (1443, '', '', '', '', 'Humm ! Tu cherches de l\\\'aide pour mener ? bien un interrogatoire ? \\nJe te conseille le formulaire d\\\'enqu?te n? 33, mais je le vends 700 kamas l\\\'exemplaire...');
INSERT INTO `npc_questions` VALUES (1444, '', '', '', '', 'Ah enfin ! Tout rentre dans l\\\'ordre. Je ne te remercie pas, tu as ?t? beaucoup trop lent.');
INSERT INTO `npc_questions` VALUES (1445, '', '', '', '', 'Ah je veux me battre ! Je veux me battre ! Mais je suis le plus fort c\\\'est pour ?a que personne ne veut se battre contre moi ! Tout le monde a peur de moi ! Ahah ! Hey toi ! Tu veux te faire battre ou vas-tu ramper ? mes pieds comme les autres ? ');
INSERT INTO `npc_questions` VALUES (1446, '', '', '', '', 'Allez hop encore une racl?e ? un couard de guerrier. Qu\\\'est-ce que tu m\\\'veux toi ? Tu veux aussi ta racl?e ? Naaah je suis un peu fatigu? aujourd\\\'hui, tu n\\\'auras pas l\\\'honneur de me combattre.');
INSERT INTO `npc_questions` VALUES (1447, '', '', '', '', 'OK, c\\\'est du bon boulot, j\\\'esp?re que je n\\\'entendrais plus parler de ces crapules... \\nJe vais donner cet acte de propri?t? ? Danathor pour qu\\\'il fasse le n?cessaire.');
INSERT INTO `npc_questions` VALUES (1448, '', '', '', '', 'MAIS JE T\\\'AVAIS DEMANDE DE PERDRE ! Tu vas comprendre ma col?re !');
INSERT INTO `npc_questions` VALUES (1449, '', '', '', '', 'Ah parfait ! Tr?s bien on peut passer ? des choses plus s?rieuses...Hum, un idiot a incendi? les r?serves de bois de chauffage de la milice. Si tu ne veux pas dormir au frais, va chercher 10 ?corces d\\\'abraknydes et rapporte-les ici. 10 hein n\\\'oublie pas : tiens un pense-b?te, vu comme tu es ?tourdi.');
INSERT INTO `npc_questions` VALUES (1450, '', '', '', '', 'TU TE MOQUES DE MOI ? Il EST ACCOURU EN PLEURANT ! Tu vas go?ter ? ma col?re !');
INSERT INTO `npc_questions` VALUES (1451, '', '', '', '', 'Bien, au moins si vous mourez ce soir, ?a ne sera pas de froid ahah !');
INSERT INTO `npc_questions` VALUES (1452, '1968;3998;739', '', '', '', 'J\\\'ai dit 10 ?corces minimum ! ');
INSERT INTO `npc_questions` VALUES (1454, '', '', '', '', 'Huff ?a va mieux. C\\\'est bon, je te pardonne. C\\\'est vrai qu\\\'il ?tait infernal...comme son papa. Enfin bref. On n\\\'a plus de bois pour se chauffer...et c\\\'est toi qui vas t\\\'y coller. Ram?ne-nous 10 ?corces d\\\'abraknydes. Tiens un pense-b?te...ce serait idiot que tu oublies les ordres encore une fois n\\\'est-ce pas ?');
INSERT INTO `npc_questions` VALUES (1457, '', '', '', '', 'Halte, ceci est l\\\'entr?e vers la salle des interrogations, personne ne peut passer sans laisser-passer !');
INSERT INTO `npc_questions` VALUES (1458, '', '', '', '', 'Tricheur, voleur, menteur ! Je vais le dire ? mon p?re ! Ouuiiin !');
INSERT INTO `npc_questions` VALUES (1459, '', '', '', '', 'Ahahah tu ?tais ridicule. Tu ne vaux vraiment rien du tout. Allez, file, je suis d\\\'assez bonne humeur aujourd\\\'hui pour te laisser partir entier.');
INSERT INTO `npc_questions` VALUES (1461, '', '', '', '', 'Combien de temps ? \\nTa date d\\\'incarc?ration est indiqu?e sur le papier de d?tention que tu as obtenu en arrivant, sachant que tu es emprisonn? pour une heure, ? toi de faire le calcul !');
INSERT INTO `npc_questions` VALUES (1462, '', '', '', '', 'Tr?s bien #1, je savais que je pouvais compter sur toi, mais ? partir du moment o? tu acceptes tu ne pourras plus revenir sur ta d?cision...');
INSERT INTO `npc_questions` VALUES (1463, '', '', '', '', 'Bon alors, on y va ?');
INSERT INTO `npc_questions` VALUES (1464, '4840', '', '', '', 'Halte-l? ! Si vous traversez ce pont, vous rentrez en territoire hostile. Le village de nos a?eux se trouvait sur cette presqu\\\'?le, mais en l\\\'an 493, une colonie de dragoeufs l\\\'a envahi et a fait fuir la population vers le Nord. \\nArmez-vous solidement si vous d?sirez sortir de ce village en un seul morceau...');
INSERT INTO `npc_questions` VALUES (1465, '', '', '', '', 'Siviz-visik qik sik inik itimik ititik isik grisik qik inik immiblik dik trizik itigis, ik sinik nik iritik lik grisirik dik inik grinik dik silik itik siritik ik siptimik itigik itik lisik ilictrinik dik lik primirik cichik ristirintik incirik invisiblisik ik lik ilik nik itik sirintik sirik lik primirik itik dirnirik itigi ?');
INSERT INTO `npc_questions` VALUES (1466, '', '', '', '', 'Jik itrik inik nikiril ibindinnik, imirik binik ritrivirik mik miminik misik jik cririk qik illik ik itik ciptirik...');
INSERT INTO `npc_questions` VALUES (1467, '', '', '', '', 'Kik vik sik jilisik inik cik bis mindik, iksitik cimmik cilik kik dirik sik limpik. Ik pik sintik lik bris kik vik pir lik frippik, mis nik lik vik pis.\\t');
INSERT INTO `npc_questions` VALUES (1468, '', '', '', '', 'Siviz-visik qik pirik sivirik ik qillik distincik ik iclitik lik fidri, ik cimptizik lisik sicindisik intrik lik iclirik itik lik cipik dik tinnirri chiqik sicindik riprisintik invirinik tricis picis.');
INSERT INTO `npc_questions` VALUES (1469, '', '', '', '', 'Mes humbles excuses, je ne peux vous parler. Je suis en patrouille.');
INSERT INTO `npc_questions` VALUES (1470, '', '', '', '', '(Mais qu\\\'est ce que tu fais l? toi, c\\\'est pas fait pour un d?mon comme toi ici, et tu vas faire sauter ma couverture, allez, file ou j\\\'appelle la garde)');
INSERT INTO `npc_questions` VALUES (1471, '', '', '', '', 'C\\\'est tout ? Tu es venu ? Bonta rien que pour ?a ? Oto veut ta mort ou quoi. Je lui aurais envoy? demain par kwak comme d\\\'habitude. Bon, tiens, que tu ne sois pas venu pour rien. Et file maintenant !');
INSERT INTO `npc_questions` VALUES (1472, '', '', '', '', 'Un assassin bontarien ? Huhu !');
INSERT INTO `npc_questions` VALUES (1473, '', '', '', '', 'Bien ! Maintenant que tu connais un peu les ?gouts, tu vas pouvoir t\\\'y enfoncer un peu plus.');
INSERT INTO `npc_questions` VALUES (1474, '', '', '', '', 'Je t\\\'ai dit que ce soir nous serions 10 pour le repas. Tu vas donc me chercher au minimum 10 carcasses de suite !');
INSERT INTO `npc_questions` VALUES (1475, '', '', '', '', 'Des bestioles qui bouffent nos murs ?! Plut?t dangereux ?a...J\\\'esp?re qu\\\'elles n\\\'ont pas cr?? de trous dans nos d?fenses...Il faut s\\\'en assurer de suite : Prend Mac avec toi, frayez-vous un chemin dans le plus profond des ?gouts et v?rifiez qu\\\'il n\\\'y ait pas de sortie !');
INSERT INTO `npc_questions` VALUES (1476, '', '', '', '', 'Un b?ton renifleur? De sang je suppose. Je n\\\'en fabrique plus ces temps-ci. Si tu en veux il va te falloir m\\\'apporter du sang de vampire, je m\\\'occupe du reste des ingr?dients. Un bocal environ par b?ton et 100 Kamas pour la prestation.');
INSERT INTO `npc_questions` VALUES (1477, '', '', '', '', 'Attends quelques petites secondes... Voil?, un b?ton renifleur ! Tu le diriges sur un joueur et tu l\\\'utilises. Il fonctionne sur une distance de 20 m?tres environ. N\\\'h?site pas ? repasser me voir s\\\'il t\\\'en faut d\\\'autres.');
INSERT INTO `npc_questions` VALUES (1478, '', '', '', '', 'Ahah ! Bien jou?, je vais faire transmettre ?a ? notre ?quipe de recrutement. Ils seront ravis.');
INSERT INTO `npc_questions` VALUES (1479, '', '', '', '', 'Qu\\\'est ce que tu veux que ?a me fasse ?! Va prendre un autre b?ton et trouve-moi un Bontarien qui empeste la mort !');
INSERT INTO `npc_questions` VALUES (1480, '', '', '', '', 'Eh, alors j\\\'esp?re que le message est pass?, j\\\'ai toujours un oeil sur toi h?h?. Tiens....il y a quelque chose de plus dans ton sac d\\\'yeux...UNE GRAPPE D\\\'OEUFS ! Mais tu es inconscient ?! Tu sais ce qui va se passer si ?a ?clot ici...ARG TROP TARD, Assume !');
INSERT INTO `npc_questions` VALUES (1481, '', '', '', '', 'Humm, tu as trop de chose dans la t?te en ce moment. On ne peut pas tout apprendre en m?me temps. Reviens me voir quand ta t?te sera un peu plus libre et que tu ma?triseras un peu plus tes autres m?tiers.');
INSERT INTO `npc_questions` VALUES (1482, '', '', '', '', 'Mais quel imb?cile ! On ne t\\\'a jamais dit qu\\\'une grappe de larves est aussi dangereuse qu\\\'un kol?rat ? Une grappe de cette taille peut entra?ner une ville ? sa perte, submerg?e par les larves. Enfin tu as bien r?agi. Elles semblent toutes mortes sauf la dor?e qui te sui...UNE DOREE ? Mais tu portes la poisse ! ');
INSERT INTO `npc_questions` VALUES (1483, '', '', '', '', 'Mais tu es vraiment inculte ! La larve dor?e est une larve l?gendaire. Investie du pouvoir des dieux et tout le toutim ! Ahlala, bon je ne vais pas te raconter toute l\\\'histoire, il y a la biblioth?que pour ?a. La seule chose que tu dois retenir c\\\'est qu\\\'il faut que tu ram?nes cette larve ? ses parents. ET VITE ! ');
INSERT INTO `npc_questions` VALUES (1484, '', '', '', '', 'Une larve ? quelle larve...AH ! Une larve dor?e !  C\\\'est une larve l?gendaire ! Selon la l?gende ce n\\\'est qu\\\'un b?b? qui ..AH !, mais nous n\\\'avons pas beaucoup de temps. Il faut que vous rameniez cette larve aupr?s de ses parents avant qu\\\'ils ne viennent la chercher.');
INSERT INTO `npc_questions` VALUES (1485, '', '', '', '', 'C\\\'est simple, il suffit que vous trouviez l\\\'entr?e de la grotte l?gendaire aux larves dor?es. Selon la l?gende elle se trouverait un peu ? l\\\'Ouest d\\\'Amakna. Les pouvoirs secrets de la larve dor?e vous permettront d\\\'y rentrer. ');
INSERT INTO `npc_questions` VALUES (1486, '', '', '', '', 'Humm. Je ne peux t\\\'apprendre les bases du m?tier. Tu es d?j? en formation. Reviens me voir quand tu ma?triseras un peu mieux tes autres m?tiers.');
INSERT INTO `npc_questions` VALUES (1487, '', '', '', '', 'P?cheur est avant tout un m?tier de patience. Tu devras absolument m\\\'acheter une canne ? p?che pour te faire la main. Bon courage pour la suite.');
INSERT INTO `npc_questions` VALUES (1488, '', '', '', '', 'Je ne puis t\\\'apprendre les rudiments de p?cheur, car tu es encore en formation pour une autre activit?. Reviens me voir quand tu auras progress? dans ce m?tier.');
INSERT INTO `npc_questions` VALUES (1489, '', '', '', '', 'Il va te falloir d\\\'abord finir la formation dans laquelle tu es engag?. Reviens me voir quand tu auras progress? dans cet autre m?tier.');
INSERT INTO `npc_questions` VALUES (1490, '', '', '', '', 'Tu es efficace, mais vraiment b?te parfois. Bon, il te faut un dentier comme ceux des chafers ?lites. Tu peux envisager d\\\'en d?monter un ou deux, mais je te pr?viens ils sont plut?t bien fix?s sur leurs cr?nes. Tu peux aussi d?goter un cr?ne de chafer, un peu moins dur ? obtenir ?a, et y demander ? faire fondre de l\\\'or dessus par un forgeron.');
INSERT INTO `npc_questions` VALUES (1491, '', '', '', '', 'Je n\\\'en ai rien ? faire de tes cale?ons, idiot. Une des t?tes du cartel t\\\'appelle, ne la fais pas attendre ou j\\\'aurais le plaisir de te tuer. Elle se trouve actuellement en inspection du sous-sol de la tour.');
INSERT INTO `npc_questions` VALUES (1492, '', '', '', '', 'Tu vas tout me r?v?ler ?');
INSERT INTO `npc_questions` VALUES (1493, '', '', '', '', 'Tu refuses vraiment ? Tu pr?f?res te ranger du c?t? de ces deux menteuses de vieilles t?tes ?');
INSERT INTO `npc_questions` VALUES (1494, '', '', '', '', 'Ha je savais que tu n\\\'?tais pas si b?te comme disciple. Ces 2 t?tes pensantes, du fait de leurs opinions convergentes, veulent s\\\'emparer du pouvoir. Heureusement que la 3?me est assez forte pour r?sister. \\nMais le moment n\\\'est pas ? l\\\'action. Toi, il faut que tu t\\\'entra?nes. Va sur l\\\'?le de Moon, va te battre contre ses fameuses tortues. Tu progresseras vite. Tues en au moins 10 avant de revenir.');
INSERT INTO `npc_questions` VALUES (1495, '', '', '', '', 'Je vois..je vois......C\\\'est bien, tu as su garder le secret qu\\\'un sup?rieur hi?rarchique t\\\'a donn?. Je suis fier de toi. Bon, il n\\\'y a pas trop de chose ? te donner l?...Un petit voyage ou bien...Lors d\\\'une exp?dition sur une ?le lointaine, j\\\'avais go?t? un petit vin d?licieux, il se nommait \\\"Vin de Gloutovore\\\", essaye de voir pour m\\\'en ramener un peu, je te ferais go?ter. Promis !');
INSERT INTO `npc_questions` VALUES (1496, '', '', '', '', 'Hein ? Qu\\\'est-ce que tu veux que... Humm, attends ! Tu as pris du galon ces derniers temps. Il faut que tu le montres. Va t\\\'acheter les ?quipements standards de Br?kmar. Voil? un peu d\\\'argent extorqu? gr?ce aux taxes, h?h?, et la liste des ?quipements standards. Va t\\\'acheter tout ?a. Et montre-moi ce que ?a donne.');
INSERT INTO `npc_questions` VALUES (1497, '', '', '', '', 'Voil? que tu ressembles ? autre chose qu\\\'? une d?jection de bouftou. C\\\'est bien. Ne les salis pas !  Tu n\\\'es pas oblig? de porter cela tout le temps, mais pour les c?r?monies officielles de guerriers c\\\'est imp?ratif.');
INSERT INTO `npc_questions` VALUES (1498, '', '', '', '', 'HUH ? On peut savoir pourquoi tu remues du popotin comme ?a devant moi ?! J\\\'ai demand? que tu ailles chercher des habits officiels, pas que tu fasses les boutiques pour me montrer tes jolis habits ! Reviens me voir quand tu endosseras la tenue standard et pas autre chose.');
INSERT INTO `npc_questions` VALUES (1499, '', '', '', '', 'Mais quel empot? ! Si tu ne sais pas o? aller, va demander ? quelqu\\\'un qui saura. Le biblioth?caire d\\\'Amakna, lui qui sait tout, doit peut-?tre savoir. Allez, FILE !');
INSERT INTO `npc_questions` VALUES (1500, '', '', '', '', 'Je suis capable de forger les plus puissantes des armes. Rien ne leur r?siste. Mais tout a un prix, h?h');
INSERT INTO `npc_questions` VALUES (1501, '', '', '', '', 'Oui c\\\'est possible. Rapporte-moi 16 morceaux d\\\'or et un cr?ne de chafer et je le ferai...pour 200 kamas bien s?r.');
INSERT INTO `npc_questions` VALUES (1502, '', '', '', '', 'Et voil?, un dentier en or, r?plique exacte de ceux des chafers ?lites.');
INSERT INTO `npc_questions` VALUES (1503, '', '', '', '', 'On surveille ce c?t? de pr?s. La terre est ? port?e d\\\'une bonne corde ou d\\\'un bon t?l?port. Il faut donc faire attention.');
INSERT INTO `npc_questions` VALUES (1504, '', '', '', '', 'La premi?re vague est pass?e... \\nHey toi ! Tu viens pour aider j\\\'esp?re?');
INSERT INTO `npc_questions` VALUES (1505, '', '', '', '', 'Bien, chope la corde ! Voil?. Poss?des-tu une attaque tr?s longue port?e ? parce que tu vas en avoir besoin l');
INSERT INTO `npc_questions` VALUES (1506, '', '', '', '', 'Plus le temps de toute fa?on, je distingue une vague d\\\'ennemis arriver. Pr?pare-toi ! CHAFER PR?PAREZ LES ARCS ! VISEZ...');
INSERT INTO `npc_questions` VALUES (1507, '', '', '', '', 'Ah tu ne pourras pas faire grand-chose, il serait pr?f?rable que tu ailles chercher un arc vite fait chez les forgeurs. ? moins que tu ne veuilles faire que du soutien.');
INSERT INTO `npc_questions` VALUES (1508, '', '', '', '', 'Hmm, apparemment ce n\\\'est pas encore le meilleur endroit pour attaquer...');
INSERT INTO `npc_questions` VALUES (1509, '', '', '', '', 'Je souhaitais te rencontrer jeune disciple d\\\'Oto Mustam. Ces derniers temps, tu as accompli pas mal d\\\'exploits pour Br?kmar. Et il est ?crit dans les t?n?bres que cela ne s\\\'arr?tera pas l?.  \\nMais certaines choses sur Br?kmar te sont ENCORE cach?es. Cette vision pourrait changer ta fa?on de voir Br?kmar. \\nSouhaites-tu l\\\'entendre ?');
INSERT INTO `npc_questions` VALUES (1510, '', '', '', '', 'Autrefois la guerre entre Bonta et Br?kmar ?tait de nature divine, plus pr?cis?ment une guerre entre les Gardiens des mois. Br?kmar ?tait la ville construite afin d\\\'honorer Rushu et d\\\'assurer sa souverainet? sur Amakna. La guerre atteint un point culminant puis les deux villes disparurent d\\\'un coup. Depuis aucun gardien n\\\'a fait parler de lui.');
INSERT INTO `npc_questions` VALUES (1511, '', '', '', '', 'En es-tu s?r ? Refuser de parler avec moi signifie que tu te dresses contre l\\\'une des t?tes de Br?kmar.');
INSERT INTO `npc_questions` VALUES (1512, '', '', '', '', 'Il y a peu, Br?kmar et Bonta ont soudainement refait surface, caprice des dieux ou des gardiens, personne ne le sait encore. Les Amakneens vers?s dans les cultes sombres migr?rent en petite partie ? Brakmar et, ? l\\\'inverse, ceux de la lumi?re ? Bonta. Les nouveaux habitants de Br?kmar ?lurent 3 repr?sentants, un par culte sombre majeur : Djaul, H?cate, Brumaire pour gouverner au mieux la cit?. Je suis celui de Brumaire.');
INSERT INTO `npc_questions` VALUES (1513, '', '', '', '', 'Ah je vois de quoi tu veux parler, mon oncle m\\\'a apport? des arcs tout neufs, et il m\\\'a dit que des miliciens viendraient les chercher. \\nIl m\\\'a aussi demand? de les vendre 1000 Kamas l\\\'unit?, \\\"les affaires sont les affaires\\\" comme il dit... \\nAttention, car ils ne sont pas r?sistants, une fois ?quip?s ils casseront au bout d\\\'un seul combat.');
INSERT INTO `npc_questions` VALUES (1514, '', '', '', '', 'Tout le monde vivait tranquillement dans son coin, ? red?couvrir l\\\'histoire des gardiens et des dieux quand soudain des guerriers de Bonta prirent d\\\'assaut Br?kmar. Ce fut un massacre. Apr?s avoir r?ussi tant bien que mal ? repousser les Bontariens nous avons ?lu ? l\\\'unanimit? la clause de vengeance que tous les cultes sombres v?n?rent. Et ainsi, la guerre a d?but?. \\n');
INSERT INTO `npc_questions` VALUES (1515, '', '', '', '', 'Tant que vengeance ne sera pas rendue, la guerre continuera pour nous. Nous avons pour devoir d\\\'honorer les morts tomb?s au combat. Une fois notre rage ?teinte, les t?tes se rassembleront et d?clareront l\\\'arr?t des hostilit?s.');
INSERT INTO `npc_questions` VALUES (1516, '', '', '', '', 'Le probl?me, jeune impatient, vient de l\\\'?mergence d\\\'adorateurs de Djaul. De plus en plus de br?kmariens adoptent le culte du d?mon sans honneur. De plus en plus de personnes ne veulent plus simplement rendre coup pour coup, mais veulent la mort de toutes choses, et pas seulement de Bonta. L\\\'?quilibre sombre est menac?, la t?te repr?sentant le culte de Djaul menace de guerre civile. Tous les br?kmariens ont cette passion commune pour les t?n?bres, mais d?sormais ils se s?parent par la fa?on de les honorer.');
INSERT INTO `npc_questions` VALUES (1517, '', '', '', '', 'Je veux simplement que tu r?fl?chisses, quel culte v?n?res-tu ? Veux-tu la mort de Bonta et honorer notre vengeance ? Ou souhaites-tu le pouvoir absolu et la mort de toutes choses ? As-tu de l\\\'honneur ? Ou es-tu comme Oto, qui ferait tout pour arriver ? ses fins ? Ton choix importe beaucoup. Prends cette bague. Lorsque tu conna?tras la r?ponse, reviens me voir. Rends-la-moi si tu es du mouvement de Djaul.');
INSERT INTO `npc_questions` VALUES (1518, '', '', '', '', 'Qu\\\'il en soit ainsi \\nApporte cette lettre ? Oto Mustam.');
INSERT INTO `npc_questions` VALUES (1519, '', '', '', '', 'As tu une r?ponse ? me donner ?');
INSERT INTO `npc_questions` VALUES (1520, '', '', '', '', 'Es-tu s?r ? D?sires-tu donc obtenir le pouvoir absolu, et ce par n\\\'importe quel moyen ?');
INSERT INTO `npc_questions` VALUES (1521, '', '', '', '', 'Es-tu s?r ? Souhaites-tu la mort de tes ennemis et non pas de tout le monde ? ');
INSERT INTO `npc_questions` VALUES (1522, '', '', '', '', 'Qu\\\"il en soit ainsi... \\nVa porter cette lettre ? Oto. Et continue ton chemin.');
INSERT INTO `npc_questions` VALUES (1523, '', '', '', '', 'Qu\\\'il en soit ainsi... \\nVa porter cette lettre ? Oto Mustam. Et continue ton p?riple.');
INSERT INTO `npc_questions` VALUES (1524, '', '', '', '', 'C\\\'est parfait. Tu as maintenant une assurance du combat acceptable. Maintenant que je sais que tu peux m\\\'?tre r?ellement utile, je n\\\'h?siterai pas ? te contacter. Jusque l? il faut se faire discret. \\nAh tu devais me remettre une lettre aussi...merci. Fais attention de ne pas oublier la prochaine fois.');
INSERT INTO `npc_questions` VALUES (1525, '', '', '', '', 'Une dizaine j\\\'ai dit, sinon ?a ne sert ? rien. Retournes-y.');
INSERT INTO `npc_questions` VALUES (1526, '', '', '', '', 'Qu\\\'est ce que tu racontes ! Tu n\\\'es m?me pas encore all? le voir. Me prends-tu pour un idiot ?');
INSERT INTO `npc_questions` VALUES (1527, '', '', '', '', 'Il semble que ce fut la derni?re vague. Ahaha, quelle bande de nuls ces Bontariens.');
INSERT INTO `npc_questions` VALUES (1528, '', '', '', '', 'Ahlala m?me pas le temps de s\\\'amuser avec ces faiblards.');
INSERT INTO `npc_questions` VALUES (1529, '', '', '', '', 'Hmm ton visage ne me rappelle rien, tu es nouveau ? \\nJe peux savoir comment tu as connu ce lieu ?');
INSERT INTO `npc_questions` VALUES (1530, '1164', '', '', '', 'Bonjour l\\\'ami, si tu cherches du pain ? la bi?re ou de la bi?re au pain tu es ? la bonne adresse !');
INSERT INTO `npc_questions` VALUES (1531, '1165', '', '', '', 'Oh, c\\\'est un quartier calme, les boulangers font leur travail consciencieusement, et les habitants me rendent r?guli?rement une petite visite. \\nHmm, et le soir il y a un peu d\\\'agitation au Nord avec la maison de Ufot...');
INSERT INTO `npc_questions` VALUES (1532, '1166;1167', '', '', '', 'C\\\'est une maison priv?e, seuls les habitu?s connaissent le code pour y rentrer.');
INSERT INTO `npc_questions` VALUES (1533, '', '', '', '', 'Hmm, je vois que tu sais parler aux taverniers, le code de cette maison est  \\\"11115555\\\". \\nLe soir Ufot y organise des paris sur des combats de Tofu, pas tr?s l?gal tout ?a...');
INSERT INTO `npc_questions` VALUES (1534, '', '', '', '', 'Oh, tr?s bien, inutile de s\\\'?nerver, le code pour rentrer est \\\"11115555\\\".');
INSERT INTO `npc_questions` VALUES (1535, '', '', '', '', 'Je savais que mes fr?res ne me laisseraient pas pourrir dans cette prison qui empeste la bonne odeur. \\nVite, allons-nous-en.');
INSERT INTO `npc_questions` VALUES (1536, '', '', '', '', 'Voil? 2000 kamas pour te remercier, les ouvriers seront contents d\\\'apprendre qu\\\'ils peuvent continuer les travaux.');
INSERT INTO `npc_questions` VALUES (1537, '', '', '', '', 'C\\\'est bien !  Enfin de toute fa?on nous avons d?cid? de changer nos plans d\\\'attaque. Double surprise comme ?a.');
INSERT INTO `npc_questions` VALUES (1538, '', '', '', '', 'Bonjour #1, ce soir j\\\'ai d?cid? de cuisiner de la cervelle de tortue, mais je ne peux pas me rendre moi-m?me sur l\\\'?le de Moon, en plus si la cervelle n\\\'est pas cuisin?e dans les 5 minutes apr?s que la b?te soit morte, le plat est immangeable... \\nMais heureusement, tu vas me donner un coup de main !');
INSERT INTO `npc_questions` VALUES (1539, '', '', '', '', 'Cette cervelle est pourrie, elle est bonne ? jeter aux ordures, tu n\\\'as pas ?t? assez rapide...');
INSERT INTO `npc_questions` VALUES (1540, '', '', '', '', 'Merci, je suis sauv?, je vais pouvoir pr?parer mon festin, prend cette cuisse de bouftou r?ti en guise de remerciement.');
INSERT INTO `npc_questions` VALUES (1541, '', '', '', '', 'Ah, je vois que tu as re?u mon message... \\nEn fait, ce que j\\\'ai ? te demander n\\\'est pas tr?s compliqu?, des ?lections approchent, et je voudrais que tu interroges Paro Cabanne pour savoir si je vais renouveler mon mandat ou non... \\nLa plupart de ses pr?dictions se sont av?r?es, donc tu peux lui faire confiance.');
INSERT INTO `npc_questions` VALUES (1542, '', '', '', '', 'Vous voulez des r?v?lations sur votre avenir, tr?s bien cela vous co?tera 50 kamas.');
INSERT INTO `npc_questions` VALUES (1543, '', '', '', '', 'Ha, les ?lections, je dois dire que j\\\'excelle dans ce genre de pr?dictions, par contre pour que cela soit vraiment fiable, il me faut de la poussi?re d\\\'Oni. \\nSi tu veux savoir qui sera notre prochain intendant, cela te co?tera 200 kamas et un sachet de cette fameuse poussi?re.');
INSERT INTO `npc_questions` VALUES (1544, '', '', '', '', 'Hmm je vois des cr?atures atroces... je vois des lieux exotiques et ?tranges... je vous vois en train de combattre des monstres gigantesques... vous avez d?cupl? vos forces, et vos sens... vos nombreux combats vous ont donn? de l\\\'exp?rience, vous serez un grand guerrier #1 !');
INSERT INTO `npc_questions` VALUES (1546, '', '', '', '', 'Vous ?tes motiv?. Vous avez de grandes ambitions et des id?es lumineuses. Gr?ce ? cela les kamas ne vous manqueront pas.');
INSERT INTO `npc_questions` VALUES (1547, '', '', '', '', 'Votre soif d\\\'aventures, vous conduira inexorablement ? des tr?sors cach?s, mais aussi ? une mort certaine...');
INSERT INTO `npc_questions` VALUES (1548, '', '', '', '', 'Les circonstances sont favorables pour vous mettre en valeur. Ces occasions-l? ne les ratez pas !');
INSERT INTO `npc_questions` VALUES (1549, '', '', '', '', 'Vous tra?nez trop souvent dans les for?ts ou les champs, au lieu de sortir ? Bonta. Bougez et tout ira mieux !');
INSERT INTO `npc_questions` VALUES (1550, '', '', '', '', 'Hmm, je vois Danathor en mauvaise posture, son rival T?deor gagnant du terrain peu ? peu dans le coeur des Bontariens.... Mais je vois aussi un accident terrible, quelque chose de myst?rieux, un retournement de situation... je vois Danathor couronn?, oui il sera malgr? tout encore intendant pour ces prochaines ann?es, c\\\'est certain !');
INSERT INTO `npc_questions` VALUES (1551, '', '', '', '', 'Suivez les conseils de vos amis, leur exp?rience permettra de mettre un terme ? vos angoisses concernant le travail.');
INSERT INTO `npc_questions` VALUES (1552, '', '', '', '', 'On recherche votre collaboration ? Bonta et cela correspond en tout point ? une demande pr?cise. C\\\'est parfait pour vous !');
INSERT INTO `npc_questions` VALUES (1553, '', '', '', '', 'Ah vous voil? #1, vous avez donc re?u ma lettre. \\nJ\\\'ai besoin d\\\'un ingr?dient assez rare pour ma prochaine recette, il me faut de la poussi?re d\\\'Oni. Ces cr?atures vivent au fin fond de la for?t mal?fique d\\\'Amakna. \\nVous ?tes la seule personne que je sais capable de m\\\'en rapporter.');
INSERT INTO `npc_questions` VALUES (1554, '', '', '', '', 'Magnifique je savais que vous seriez ? la hauteur ! Pour vous r?compenser, prenez cet oeuf de Bwak, d\\\'habitude je m\\\'en sers pour concevoir des potions, mais vous lui trouverez peut-?tre une autre utilit');
INSERT INTO `npc_questions` VALUES (1555, '', '', '', '', 'Vous voulez encore m\\\'aider ? C\\\'est vraiment gentil de votre part, mais je ne recherche plus rien pour le moment. Si vous voulez encore faire preuve d\\\'altruisme, Grace Malcean est venue me voir ce matin pour que je soigne son tabi, mais je n\\\'avais pas le rem?de qu\\\'elle cherchait, elle se trouve ? l\\\'Ouest de Bonta.');
INSERT INTO `npc_questions` VALUES (1556, '', '', '', '', 'Je suis pr?occup?e, mon tabi a ?t? piqu? par un scorbute lors de mon passage dans les landes de Sidimote, et il ne semble pas aller tr?s bien...');
INSERT INTO `npc_questions` VALUES (1557, '', '', '', '', 'Merci, mais la seule chose qui pourrait gu?rir mon tabi, c\\\'est un miracle, j\\\'ai demand? aux plus grands sp?cialistes, qu\\\'ils soient m?decins, enchanteurs ou mages, ils n\\\'ont rien pu faire. \\nUn miracle... c\\\'est tout ce que je demande...');
INSERT INTO `npc_questions` VALUES (1558, '', '', '', '', 'Moo oom holp m\\\'om plos\\\'om moo oom.');
INSERT INTO `npc_questions` VALUES (1559, '', '', '', '', 'Moo oom thonks om lot moo oom !');
INSERT INTO `npc_questions` VALUES (1560, '', '', '', '', 'Moo oom foond\\\'om morocl\\\'om sqoorrol\\\'om nord\\\'om ost\\\'om oxtorom bontom moo oom.');
INSERT INTO `npc_questions` VALUES (1561, '', '', '', '', 'C\\\'est un miracle ! Mon tabi va mieux, je remercie les dieux de m\\\'?tre venu en aide !');
INSERT INTO `npc_questions` VALUES (1562, '', '', '', '', 'Ne dites surtout pas ? mes parents que je suis ici !');
INSERT INTO `npc_questions` VALUES (1563, '', '', '', '', 'Ne dis surtout pas ? Amayiro que je me trouve ici !');
INSERT INTO `npc_questions` VALUES (1564, '', '', '', '', 'Ne dis surtout pas ? ma femme que je suis ici !');
INSERT INTO `npc_questions` VALUES (1565, '', '', '', '', 'Mince, je ne pensais pas que la milice viendrait fouiner dans mes affaires. Tu ne crois pas que vous devriez vous occuper de Br?kmar, plut?t que d\\\'emb?ter les gens qui exercent leur m?tier...');
INSERT INTO `npc_questions` VALUES (1566, '', '', '', '', 'Hmm, je vois que tu es intelligent, tu n\\\'as qu\\\'? dire ? Amayiro que tu as r?gl? l\\\'affaire. \\nJe te donne la totalit? des recettes de la semaine en ?change, soit 10.000 kamas...');
INSERT INTO `npc_questions` VALUES (1567, '', '', '', '', 'Tr?s bien, h?h?, n\\\'h?site pas ? venir parier sur un combat de tofu ? l\\\'occasion... \\nJe te donne aussi cette broche en guise de mon amiti');
INSERT INTO `npc_questions` VALUES (1568, '', '', '', '', 'Comment vais-je nourrir ma femme et mes enfants si vous fermez ma boutique ? Piti? !');
INSERT INTO `npc_questions` VALUES (1569, '', '', '', '', 'Pfff, prends mon acte de propri?t? et ne reviens plus.');
INSERT INTO `npc_questions` VALUES (1570, '', '', '', '', 'Tout de suite ? Pour d?fendre les remparts ? Grmph je n\\\'en ai plus en stock. Quoique...L\\\'occasion est bonne pour tester ma nouvelle cr?ation. Elle est fragile, mais tire tr?s loin...L\\\'inconv?nient c\\\'est qu\\\'elle est trop puissante et on ne peut pas tirer ? courte port?e.');
INSERT INTO `npc_questions` VALUES (1571, '', '', '', '', 'Comme tu voudras.');
INSERT INTO `npc_questions` VALUES (1572, '', '', '', '', 'Haha j\\\'ai bien failli perdre ma boutique, mais Danathor, qui est un habitu? de la maison, n\\\'?tait pas du m?me avis que Amayiro, il va essayer de faire voter une loi pour autoriser le combat de tofu !');
INSERT INTO `npc_questions` VALUES (1573, '', '', '', '', 'Hihi salut #1, tu viens t\\\'amuser un peu ?');
INSERT INTO `npc_questions` VALUES (1574, '', '', '', '', 'Mais tu en as d?j? un !');
INSERT INTO `npc_questions` VALUES (1575, '', '', '', '', 'Je serais donc bien le prochain intendant, quelle triste nouvelle cependant pour ce cher T?deor... \\n? propos, tu ne voudrais pas me rendre un autre service, jeune disciple ?');
INSERT INTO `npc_questions` VALUES (1576, '', '', '', '', 'Piti? je veux sortir de cette prison sordide !');
INSERT INTO `npc_questions` VALUES (1577, '', '', '', '', 'Content de te revoir Hou? Dapyus, mais tu n\\\'es quand m?me vraiment pas dou? pour te faire avoir comme ?a !');
INSERT INTO `npc_questions` VALUES (1578, '', '', '', '', 'H?h? j\\\'esp?re qu\\\'il va retenir la le?on !');
INSERT INTO `npc_questions` VALUES (1579, '', '', '', '', 'F?licitations, tu es un des premiers ? m\\\'en ramener dix.');
INSERT INTO `npc_questions` VALUES (1580, '', '', '', '', 'Comme un fleuve de lave s?pare la rive des remparts, demande ? la ni?ce de Mech Riorraw pour que son oncle te fabrique une arme ? longue port?e...');
INSERT INTO `npc_questions` VALUES (1581, '', '', '', '', 'Ce n\\\'est pas pour moi personnellement, mais j\\\'ai rencontr? une certaine Grace Malcean un peu au sud d\\\'ici qui a des probl?mes avec son tabi. \\nElle fait partie du Parlement Bontarien, donc il serait mauvais pour mon ?lectorat qu\\\'elle d?prime en ce moment...');
INSERT INTO `npc_questions` VALUES (1582, '', '', '', '', 'La loyaut? n\\\'est pas h?r?ditaire, il ne faut donc pas croire que tous les gens de Bonta sont respectables.');
INSERT INTO `npc_questions` VALUES (1583, '', '', '', '', 'Je d?pense la totalit? de mon salaire chez les tailleurs du quartier, enfin celui de mes parents...');
INSERT INTO `npc_questions` VALUES (1584, '', '', '', '', 'Sik tik vixik prifitirik dik pivirik miricilixik ilik tik fidrik inik binnik risinik itik mik dinnik ink glindik...');
INSERT INTO `npc_questions` VALUES (1585, '', '', '', '', 'Prifitik dik tinik pivirik itik sivik cik tibik !');
INSERT INTO `npc_questions` VALUES (1586, '', '', '', '', 'Ah ! C\\\'est ma?tre Kwelsh qui t\\\'envoie. H?te-toi donc, je joue ma vie pour m\\\'acquitter de cette dette ! \\nBon comme pr?vu, la carte contre la feuille ?');
INSERT INTO `npc_questions` VALUES (1587, '', '', '', '', 'Souhaites-tu me rendre la bague ?');
INSERT INTO `npc_questions` VALUES (1588, '', '', '', '', 'Qu\\\'il en soit ainsi.');
INSERT INTO `npc_questions` VALUES (1589, '', '', '', '', 'Allez file maintenant !');
INSERT INTO `npc_questions` VALUES (1590, '', '', '', '', 'Baisse bous branquille, tu ne bois pas qu\\\'on boue aux d?s, l? ? \\nSi tu beux buitter botre bimension, utilise la borte bagique ? bauche...');
INSERT INTO `npc_questions` VALUES (1591, '1219;1215;1216', '', '', '0', 'Que beux-tu bumain ? Bomment ose tu me b?ranger bendant bette bartie ?');
INSERT INTO `npc_questions` VALUES (1592, '', '', '', '', 'Tu es boriace toi, moi et mes br?res allons te b?duire en bouillie.');
INSERT INTO `npc_questions` VALUES (1593, '', '', '', '', 'Tu te b?brouilles pas mal toi, on bisque b?me de s\\\'y bettre ? beux pour te bettre une bacl?e....');
INSERT INTO `npc_questions` VALUES (1594, '1223;1215;1216', '', '', '0', 'Que beux-tu bumain ? Bomment ose tu me b?ranger bendant bette bartie ?');
INSERT INTO `npc_questions` VALUES (1595, '1217;1215;1216', '', '', '0', 'Que beux-tu bumain ? Bomment ose tu me b?ranger bendant bette bartie ?');
INSERT INTO `npc_questions` VALUES (1596, '1221;1215;1216', '', '', '0', 'Que beux-tu bumain ? Bomment ose tu me b?ranger bendant bette bartie ?');
INSERT INTO `npc_questions` VALUES (1597, '', '', '', '', 'Tu n\\\'as pas encore gagn? le niveau 2. \\nRetourne t\\\'entra?ner face ? cette Arakne.');
INSERT INTO `npc_questions` VALUES (1598, '', '', '', '', 'Ah, je vois que tu as atteint le deuxi?me niveau. F?licitations !');
INSERT INTO `npc_questions` VALUES (1599, '', '', '', '', 'Lorsque tu gagnes un niveau, ton personnage devient un petit peu plus puissant. Ainsi tu gagnes 5 points ? r?partir dans tes caract?ristiques et 1 point de bonus permettant de booster tes sorts. Si tu veux, je peux te montrer comment utiliser tes points de caract?ristique. Sinon passe directement ? la salle suivante. Je te montrerai comment faire ?voluer tes sorts !');
INSERT INTO `npc_questions` VALUES (1600, '', '', '', '', 'Tu as les 3 objets que je t\\\'ai demand?s ? Bien ! \\nEquipes les, et tu pourras passer dans la salle suivante.');
INSERT INTO `npc_questions` VALUES (1601, '', '', '', '', 'Il te manque encore un objet... Je te rappelle qu\\\'il te faut ?quiper une amulette, une ceinture et un bandeau. \\nReviens me voir lorsque tu auras ces trois objets.');
INSERT INTO `npc_questions` VALUES (1602, '', '', '', '', 'Tu as d?j? un des 3 objets que je t\\\'ai demand?. C\\\'est un bon d?but. \\nIl te faut ?quiper une amulette, un bandeau et une ceinture, que tu peux trouver sur les monstres pr?sents dans cette pi?ce. \\nReviens me voir lorsque ce sera fait.');
INSERT INTO `npc_questions` VALUES (1603, '', '', '', '', 'Voil? tout est dit. Si tu as des questions particuli?res, n\\\'h?site pas ? me les poser avant de partir...');
INSERT INTO `npc_questions` VALUES (1604, '', '', '', '', 'Equiper un objet, c\\\'est le sortir de son inventaire pour le porter sur soi. \\nDe cette mani?re, on peut profiter de ses effets magiques.');
INSERT INTO `npc_questions` VALUES (1606, '1240', '', '', '', 'Cette poudre permet de soigner n\\\'importe quel familier. Donnez lui comme si vous lui donniez de la nourriture traditionnelle. Et au bout de quelques instants votre familier se sentira d?j? beaucoup mieux. Notez bien que cela ne constitue en aucun cas un repas pour lui. Alors int?ress? ?');
INSERT INTO `npc_questions` VALUES (1607, '', '', '', '', 'Voil? votre poudre. N\\\'h?sitez pas ? revenir me voir.');
INSERT INTO `npc_questions` VALUES (1608, '', '', '', '', 'D?sol? vous n\\\'avez pas assez d\\\'argent.');
INSERT INTO `npc_questions` VALUES (1609, '1241', '', '', '', 'Bonjour, vous me semblez en bonne sant? ! C\\\'est le moment de nous c?der un peu de votre sang afin que l\\\'on ait quelques r?serves en cas de coup dur.');
INSERT INTO `npc_questions` VALUES (1610, '', '', '', '', 'Notre peuple gagne petit ? petit sa place dans ce Monde. Tr?s r?cemment, la d?esse nous a d?voil? l\\\'art ultime et sublime des Sacrieurs. Nous partageons ce savoir avec les Sacrieurs dignes de conna?tre ces techniques de combat.');
INSERT INTO `npc_questions` VALUES (1611, '', '', '', '', 'Vous savez maintenant ?couter le sang sauvage qui coule dans vos veines et le contr?ler... plus ou moins !');
INSERT INTO `npc_questions` VALUES (1615, '', '', '', '', 'Vous savez d?sormais acc?l?rer le processus de gu?rison gr?ce au sang. Cela vous sera utile dans vos p?riples !');
INSERT INTO `npc_questions` VALUES (1617, '', '', '', '', 'Voil?, ce sort n\\\'est pas fait pour l\\\'offensive, mais il est pourtant redoutable.');
INSERT INTO `npc_questions` VALUES (1619, '', '', '', '', 'J\\\'ai le vertige, si si, m?me si c\\\'est ?trange pour une habitante de ce village, j\\\'ai peur du vide depuis que je suis toute petite. Pour me calmer ma m?re me donnait des bonbons ? la gel?e, elle savait que j\\\'adorais ?a.');
INSERT INTO `npc_questions` VALUES (1620, '1246;1247;1248;1249;2420;2421;305', '', '', '0', 'J\\\'aime beaucoup voyager, c\\\'est pourquoi j\\\'ai d?cid? de proposer un transport gratuit pour tous les amis et membres du village. \\nIl te suffit de choisir une destination pour t\\\'y rendre !');
INSERT INTO `npc_questions` VALUES (1621, '', '', '', '', 'Salut, quel bon vent t\\\'am?ne dans la cit? des nuages ? \\nAvec un ami nous fabriquons des potions pour se d?placer plus vite qu\\\'une rafale ! N\\\'en parle pas ? Girle Pylote, elle ne jure que par les engins m?caniques...');
INSERT INTO `npc_questions` VALUES (1622, '', '', '', '', 'Laisse-moi passer ! J\\\'ai perdu l\\\'inducto-r?duleur de mon Bumper, du coup impossible de rentrer chez moi. Si seulement il me restait assez d\\\'energie Oclitique pour r?parer mon mod?le BZ4A...');
INSERT INTO `npc_questions` VALUES (1623, '1251', '', '', '0', 'Vous voulez vous amuser ? attraper le plus gros pichon ? Soit, je peux vous louer la canne ? p?che sp?ciale pichon pour 100 Kamas.');
INSERT INTO `npc_questions` VALUES (1624, '', '', '', '', 'Et voil?, bonne p?che !');
INSERT INTO `npc_questions` VALUES (1625, '', '', '', '', 'Vous n\\\'avez pas assez d\\\'argent');
INSERT INTO `npc_questions` VALUES (1626, '', '', '', '', 'Je suis d?sol?e, mais je ne parle pas aux inconnus...');
INSERT INTO `npc_questions` VALUES (1627, '125', '', '', '0', 'Toi c\\\'est bon ! Tu peux passer, mais gare ? toi si tu t\\\'approches trop pr?s des ch?rubins ! Tu sais ce qui risquerait  de t\\\'arriver hein !');
INSERT INTO `npc_questions` VALUES (1628, '', '', '', '', 'HEY STOP COCO ! Tu crois aller o? comme ?a ?! Hors de question que tu t\\\'approches de mes enfants ! Je ne veux pas que quelqu\\\'un d\\\'aussi faiblard que toi les approches. Ils ne doivent avoir que les meilleurs exemples pour ?tre les meilleurs par la suite !');
INSERT INTO `npc_questions` VALUES (1629, '', '', '', '', 'Merci ! Ma m?re me disait toujours : \\\"Si tu manges des Rougely et des Vertgely, ne mange jamais 4 Blugely en m?me temps !\\\"');
INSERT INTO `npc_questions` VALUES (1630, '', '', '', '', 'Merci ! Ma m?re me disait toujours : \\\"Si tu manges des Blugely et des Rougely, ne mange jamais 3 Vertgely en m?me temps !\\\"');
INSERT INTO `npc_questions` VALUES (1631, '', '', '', '', 'Merci ! Ma m?re me disait toujours : \\\"Si tu manges des Bluegely et des Vertgely, ne mange jamais 2 Rougely en m?me temps !\\\"');
INSERT INTO `npc_questions` VALUES (1632, '', '[name]', '', '', 'Comment allez-vous #1? Par un froid pareil, il ne fait pas bon se promener dans Amakna. \\nAh, j\\\'ai crois? quelqu\\\'un ce matin qui vous transmet ses amiti?s... roooh je ne me souviens plus de son nom !? Aidez moi, c\\\'est l\\\'Enutrof le plus classe du pays ! Mais si ? Non vraiment ? Tant pis...');
INSERT INTO `npc_questions` VALUES (1633, '250', '', '', '0', 'Tr?s bien tu as pay? pour ton crime, un garde va maintenant te ramener ? la fronti?re.');
INSERT INTO `npc_questions` VALUES (1634, '', '', '', '', 'Bien, en effet, il existe des ?tres vils dans Amakna, qui usurpent sans scrupule des identit?s pour d?pouiller les honn?tes citoyens comme toi, ne fais donc pas confiance ? ceux qui semblent en vouloir ? tes richesses. \\n \\nVoici la question suivante : Lorsque tu seras un grand guerrier et que tu croiseras un jeune apprenti qui te demandera de l\\\'aide, que lui r?pondras-tu ?');
INSERT INTO `npc_questions` VALUES (1635, '', '', '', '', 'Tr?s bien, l\\\'altruisme est une vertu qui se perd de nos jours, et il est toujours bon pour la d?fense du pays, d\\\'avoir de nouveaux guerriers pour d?fendre nos villes. \\n \\nDerni?re question : Si un joueur se moque de ta fa?on de te battre, ou de ton allure, que fais-tu ?');
INSERT INTO `npc_questions` VALUES (1636, '', '', '', '', 'Tu as tout faux, l\\\'entraide est la cl? de voute de la survie d\\\'Amakna, sans elle les cr?atures qui r?dent aux alentours prendraient le contr?le de nos villages, il ne faut donc jamais refuser d\\\'aider les d?butant.');
INSERT INTO `npc_questions` VALUES (1637, '', '', '', '', 'Ne perds pas ton temps avec ce genre d\\\'individu, si il insiste pr?vient un aigle ou envoie un message au gardien d\\\'Amakna. Mais inutile de rentrer dans son jeu, car cela pourrait se retourner contre toi...');
INSERT INTO `npc_questions` VALUES (1638, '', '', '', '', 'Tu es suffisamment aguerri pour te d?brouiller seul d?sormais, inutile de retourner ? l\\\'int?rieur.');
INSERT INTO `npc_questions` VALUES (1639, '', '', '', '', 'Pour parfaire tes connaissances, je te sugg?re d\\\'aller visiter le temple de ta classe, le ma?tre d\\\'arme qui s\\\'y trouve t\\\'apprendra quelques techniques et aura certainement quelques missions ? te confier.');
INSERT INTO `npc_questions` VALUES (1640, '', '[name]', '', '0', '#1, je t\\\'attendais. D\\\'ailleurs, je connais d?j? la question que tu vas me poser, tu es si pr?visible... \\n \\nJe sais aussi que tu allais oublier de payer les 100 kamas pour me poser une question, je pr?f?re donc te le rappeler tout de suite.');
INSERT INTO `npc_questions` VALUES (1641, '', '', '', '', 'Le temple Feca se trouve ? l\\\'Est sur la c?te d\\\'Asse, adresse toi ? Hirpine F?calamit? pour continuer ta formation.');
INSERT INTO `npc_questions` VALUES (1642, '127', '', '', '0', 'Bonjour, voulez-vous de ces fabuleuses et d?licieuses sucreries ? Nous avons de tout : qui pique, qui colle, qui tache. La seule que nous ne vendons pas c\\\'est la multigely, mais on ne peut pas nous en vouloir pour ?a hihi.');
INSERT INTO `npc_questions` VALUES (1643, '', '', '', '', 'La multygely ? C\\\'est un croisement maudit de bonbon gely. Plus personne n\\\'en vend car elle a provoqu? la disparition de nombreux enfants. Il parait qu\\\'elle envoie la personne qui la mange dans ses pires cauchemars.');
INSERT INTO `npc_questions` VALUES (1644, '', '', '', '', 'Leonzi Trool nous a expos? son r?ve, en l\\\'entendant nous avons compris que notre destin ?tait de l\\\'aider ? monter cette foire. Et nous l\\\'avons fait !');
INSERT INTO `npc_questions` VALUES (1645, '', '', '', '', 'Cette foire est une v?ritable r?ussite, les gens s\\\'y amusent, se rencontrent, les enfants rient. C\\\'est un endroit magique');
INSERT INTO `npc_questions` VALUES (1646, '1273', '13450', '', '0', 'Approchez, approchez, la richesse appartient ? ceux qui osent.\\nLa cagnotte s\\\'?l?ve maintenant ? #1 kamas !\\n\\n100 Kamas pour participer, si le bouftou mange la pomme ? vous la grande vie !');
INSERT INTO `npc_questions` VALUES (1647, '', '', '', '', 'Bonjour ! Bienvenu chez Maxims ! Le meilleur restaurant de tout le parc, voire plus ! Que d?sirez vous ? Un repas presque ?quilibr? ? Qui se pr?pare tr?s rapidement ? Bougez pas j\\\'ai ce qu\\\'il vous faut ! Il suffit de demander !');
INSERT INTO `npc_questions` VALUES (1648, '130', '', '', '0', 'Bonjour, vous ?tes sur le stand d\\\'?change de jetons. Ici j\\\'echange vos pr?cieux jetons durement gagn?s sur les autres stands contre des objets divers.');
INSERT INTO `npc_questions` VALUES (1649, '', '', '', '', 'Venez ici vous rafraichir un peu en d?gustant une de nos d?licieuses glaces. Nous avons de nombreux choix de parfums n\\\'h?sitez pas ? jeter un coup d\\\'oeil sur notre carte.');
INSERT INTO `npc_questions` VALUES (1650, '', '', '', '', 'Il me faut d\\\'avantage de pr?cisions, il faut que j\\\'oriente ma divination sur un lieu pr?cis avant de consulter ma boule de cristal.');
INSERT INTO `npc_questions` VALUES (1651, '1284;128', '', '', '0', 'Sur quelle cr?ature veux tu que je jette mon ?il divinatoire ?');
INSERT INTO `npc_questions` VALUES (1652, '', '', '', '', 'Les habitants de ce village sont tr?s ing?nieux, mais ils n\\\'ont pas r?ussi pour autant ? rendre leur village imprenable.  \\n* frotte sa boule de cristal * \\nLes troupes de Bonta contr?lent le village pour le moment, mais peut-?tre plus pour tr?s longtemps...');
INSERT INTO `npc_questions` VALUES (1653, '', '', '', '', 'Les habitants de ce village sont tr?s ing?nieux, mais ils n\\\'ont pas reussi pour autant ? rendre leur village imprenable.  \\n* frotte sa boule de cristal * \\nLes troupes de Br?kmar contr?le le village pour le moment, mais peut-?tre plus pour tr?s longtemps...');
INSERT INTO `npc_questions` VALUES (1654, '', '', '', '', 'Le territoire des Dopeuls, hmm, c\\\'est un lieu qui regorge de magie. Les cr?atures qui y r?sident prennent l\\\'apparence de tout ce qu\\\'ils rencontrent. \\n* frotte sa boule de cristal * \\nJe vois qu\\\'il y\\\'a des boulversements d\\\'alignement fr?quent l? bas, pour le moment ce sont les troupes de  \\nBonta qui contr?lent cette zone.');
INSERT INTO `npc_questions` VALUES (1655, '', '', '', '', 'Le territoire des Dopeuls, hmm, c\\\'est un lieu qui regorge de magie. Les cr?atures qui y r?sident prennent l\\\'apparence de tout ce qu\\\'ils rencontrent. \\n* frotte sa boule de cristal * \\nJe vois qu\\\'il y\\\'a des boulversements d\\\'alignement fr?quent l? bas, pour le moment ce sont les troupes de  \\nBr?kmar qui contr?lent cette zone.');
INSERT INTO `npc_questions` VALUES (1656, '', '', '', '', 'Les brigandins sont dou?s dans la r?paration, leur nouveau prisme est d?j? actif, mais il ne le restera pas ?ternellement...');
INSERT INTO `npc_questions` VALUES (1657, '', '', '', '', 'Le prisme a ?t? d?truit il y a peu, et il n\\\'a toujours pas ?t? r?par');
INSERT INTO `npc_questions` VALUES (1658, '', '', '', '', 'Je ressens une energie importante dans la salle du prisme, le territoire des Dopeuls est donc vuln?rable aux attaques en ce moment.');
INSERT INTO `npc_questions` VALUES (1659, '', '', '', '', 'Le prisme de cette zone n\\\'a pas encore ?t? reconstruit, le territoire des Dopeuls est inattaquable pour le moment.');
INSERT INTO `npc_questions` VALUES (1660, '', '', '', '', 'Venez admirrrer pourr la modique somme de 10 Kamas, toutes sorrtes de monstrres, des errreurs de sirre Silvoss, ma?trre de la naturre,  prrobablement d?concentrr? parr un esprrit malin ! \\nNe mettez pas la main entrre les barrreaux des cages, ne vous apprrochez pas trrop et il ne vous arrrivera prrobablement rrien h?h?h?h? !');
INSERT INTO `npc_questions` VALUES (1661, '130', '', '', '0', 'Vous! je suis s?r que vous avez la dext?rit? n?cessaire pour attraper un canard, je vous assure, ce n\\\'est pas cher, et ?a peux vous rapporter gros, si si ! Essayez ! Pas de mais ! Ca fera plaisir ? vos enfants...oui m?me si vous n\\\'en avez pas...m?me si vous en ?tes un vous m?me. Donnez-moi des Kamas et essayez !');
INSERT INTO `npc_questions` VALUES (1662, '', '', '', '', 'Prenez un peu de temps pour acheter un objet symbolique du parc. Il vous permettra de vous rem?morer vos merveilleux moments pass?s ici ? vous amuser durant vos longues soir?es d\\\'hiver. Cela dit vous pourrez aussi revenir nous voir, nous sommes ouverts toute l\\\'ann?e !');
INSERT INTO `npc_questions` VALUES (1663, '', '', '', '', 'Le dark vlad a refait surface, il hante de nouveau la for?t mal?fique !');
INSERT INTO `npc_questions` VALUES (1664, '', '', '', '', 'Le dark vlad n\\\'a toujours pas refait surface...  \\nPour 1000 kamas de plus je peux essayer de deviner dans combien de temps il r?appara?tra !');
INSERT INTO `npc_questions` VALUES (1665, '', '', '', '', 'Je sens une pr?sence mal?fique dans le donjon du dragon cochon !');
INSERT INTO `npc_questions` VALUES (1666, '', '', '', '', 'Et oui ! Depuis qu\\\'il a quitt? son ancienne grotte d?labr?e, il passe tout son temps dans son nouveau donjon grand confort.');
INSERT INTO `npc_questions` VALUES (1667, '128', '', '', '0', 'VENEZ MESURER VOTRE ADRESSE ! DE NOMBREUX LOTS A GAGNER ! Oh bonjour, je sens que vous ?tes dou? pour le tir ? distance vous ! J\\\'h?site ? vous faire jouer, j\\\'ai bien peur que vous ne remportiez tous les lots. Bon allez, je vous y autorise, car cela vous fera plaisir ! C\\\'est seulement 20 Kamas la partie.');
INSERT INTO `npc_questions` VALUES (1668, '', '', '', '', 'Tr?s simple, 3 ballons sont face ? vous, vous avez 3 ?p?es. Vous allez en lancer une ? la fois en visant un ballon. Cliquez n\\\'importe o? sur l\\\'?cran d?s que votre ?p?e est align?e en ligne droite avec un ballon. \\n3 Ballons explos?s et c\\\'est le gros lot !');
INSERT INTO `npc_questions` VALUES (1669, '', '', '', '', 'Et voil?, ah pas trop de chance, peut ?tre un plus gros lot sur le prochain koinkoin');
INSERT INTO `npc_questions` VALUES (1670, '', '', '', '', 'Merci #1, les rats d\\\'Hyoactifs sont une vraie plaie pour la productivit? de notre ville, leur Hyoactivit? pousse les gens ? prendre des cong?s et aller s\\\'amuser ? la foire du Trool !');
INSERT INTO `npc_questions` VALUES (1671, '', '', '', '', 'Qui a d?truit par le feu p?rira par le feu ! Si tu veux de la poudre ? canon, je suis ton homme, mais attention ? ne pas te br?ler les doigts.');
INSERT INTO `npc_questions` VALUES (1672, '1290;1291;128', '', '', '0', 'OYEZ ! OYEZ ! METTEZ ? L\\\'?PREUVE VOTRE MEMOIRE ! REVELEZ VOS CAPACITES CACHEES ! Vous, oui vous l? ! Je sens votre potentiel ! Cela vous dit de les d?voiler au grand jour ? C\\\'est seulement 20 Kamas et cela peut rapporter de nombreux jetons !');
INSERT INTO `npc_questions` VALUES (1673, '', '', '', '', 'C\\\'est simple, il y a deux types de d?fi qui se basent sur le m?me principe. Des faux blops vont construire une s?quence en bougeant chacun leur tour. Une fois celle-ci finie il vous faudra la reproduire en appuyant sur ces blops. Dans le premier mode, plus facile, les blops gardent la m?me s?quence de base et y ajoutent ? chaque tour un mouvement de plus. Dans le mode difficile, la s?quence est nouvelle ? chaque fois. Cela vous tente ?');
INSERT INTO `npc_questions` VALUES (1675, '', '', '', '', 'Tr?s bien, mettez-vous en face de la roulette bouftou, et tournez la roue !');
INSERT INTO `npc_questions` VALUES (1676, '', '', '', '', 'Tr?s bien, mettez-vous en face de la roulette bouftou, et tournez la roue !');
INSERT INTO `npc_questions` VALUES (1677, '129', '', '', '0', 'VENEZ ?VACUER VOTRE STRESS TOUT EN VOUS AMUSANT GRACE A NOS PETITES B?TES JAUNES FAVORITES !  \\nBonjour, je lis dans vos yeux que vous avez besoin de vous d?fouler, de rel?cher la pression de la routine zaapo, crafto, dodo. Et bien n\\\'allez pas plus loin, je vous propose de le faire et en plus vous avez gros ? gagner ! Seulement 20 Kamas pour tout ?a !');
INSERT INTO `npc_questions` VALUES (1678, '', '', '', '', 'Facile ! Des tofus vont appara?tre al?atoirement sur la surface de jeu, et dispara?tre rapidement apr?s. Le but est de frapper les tofus avant qu\\\'ils ne disparaissent. Mais attention ! Il ne faut taper que les tofus JAUNES, si vous frappez un tofu ORANGE vous avez perdu !  \\nQuel challenge non ? \\nSi vous parvenez ? frapper 60 tofus sans erreur, le gros lot est ? vous.');
INSERT INTO `npc_questions` VALUES (1680, '', '', '', '', 'Bienvenue dans l\\\'ar?ne de Gladiatrooll ! Cette attraction est ferm?e pour le moment, mais prochainement, ici se d?roulera le plus grand combat de monstres de tous les temps !');
INSERT INTO `npc_questions` VALUES (1681, '1299;129', '', '', '0', 'LES LARVES LES PLUS RAPIDES DE TOUT AMAKNA ! VENEZ PARIER SUR VOS LARVES FAVORITES ! FACILE PAS CHER ET CELA RAPPORTE GROS ! Bonjour, vous d?sirez assister ? une course de larve pour 40 kamas ?');
INSERT INTO `npc_questions` VALUES (1682, '', '', '', '', 'C\\\'est simple, pour 40 kamas, vous pouvez assister et pariez ? une course de larves. 4 Larves sont en lice, vous en choisissez une avant la course et si elle gagne vous gagnez le pactole ! Soit 40 Jetons.');
INSERT INTO `npc_questions` VALUES (1684, '', '', '', '', 'F?licitations, vous avez vaincu brillamment ce monstre, mais en ferez vous de m?me avec le prochain. \\n? vous de choisir, partir avec votre lot ou continuer l\\\'aventure !');
INSERT INTO `npc_questions` VALUES (1685, '', '', '', '', 'Bienvenue dans l\\\'ar?ne de Gladiatrooll ! Venez tester votre endurance dans une s?rie de combats contre des monstres terrifiants! \\nIci, les Kamas ne sont pas accept?s, pour jouer il vous faudra d?penser 100 jetons de la foire du trool ! \\n \\nLes r?gles sont simples, il suffit de survivre et essayer d\\\'aller le plus loin possible, apr?s chaque combat vous avez la possibilit? de vous arr?ter, ou de continuer. \\nAttention, pour que ce ne soit pas trop facile, avant chaque combat vous aurez une mal?diction magique qui r?duira vos capacit?s...');
INSERT INTO `npc_questions` VALUES (1686, '1302', '', '', '0', 'Bienvenue ? la foire du Trooll ! \\nL\\\'entr?e co?te 10 kamas pour les adultes. Pour les enfants, s\\\'ils passent sous le bras du Iop, ils ne payent pas l\\\'entr?e ! \\nAttention, le ticket n\\\'est valable que 24 heures...');
INSERT INTO `npc_questions` VALUES (1687, '', '', '', '', 'Je commence ? ?conomiser des jetons, il parait qu\\\'il en faudra pour participer au Gladiatrooll.');
INSERT INTO `npc_questions` VALUES (1688, '', '', '', '', 'Il suffit de me donner 10 kamas, je vous donne une canne, vous avez un essai pour p?cher un koinkoin, si vous r?ussissez vous venez me donner le canard et je vous donne une r?compense.');
INSERT INTO `npc_questions` VALUES (1690, '1311;1310;1309;1307;130', '', '', '0', 'Choisis le montant de jetons');
INSERT INTO `npc_questions` VALUES (1691, '1312;1313;1314;1315;131', '', '', '0', 'Choisis ton cadeau');
INSERT INTO `npc_questions` VALUES (1692, '1330;133', '', '', '0', 'Choisis ton cadeau');
INSERT INTO `npc_questions` VALUES (1693, '1332;133', '', '', '0', 'Choisis ton cadeau');
INSERT INTO `npc_questions` VALUES (1694, '1317;1318;1319;1320;1321;135', '', '', '0', 'Choisis ton cadeau');
