INSERT INTO `npc_questions` VALUES (1758, '6697;6772;1419;1509', '', '', '0', 'Les x?lors ont horreur de perdre du temps, il est donc assez difficile de trouver un X?lor exp?riment? avec qui faire un entra?nement. C\\\'est pourquoi j\\\'ai eu l\\\'id?e d\\\'entrainer des Dopeuls ? notre style de combat, pour qu\\\'ils nous servent d\\\'adversaires durant notre formation.');
