INSERT INTO `npc_questions` VALUES (1767, '6697;6772;1419;1509', '', 'Ce=0', '1834', 'J\\\'ai entra?n? des Dopeuls pour qu\\\'ils apprennent les techniques de combat Cr?. Ainsi ils font d\\\'excellents adversaires pour s\\\'entra?ner, et ce quel que soit ton niveau. \\nMon but est d\\\'entrainer un dopeul jusqu\\\'a ce qu\\\'il soit aussi puissant que Leffe L?godas, le fameux cr? qui vient de la terre du Bigleux.');
