INSERT INTO `npc_questions` VALUES (1815, '', '', '', '', 'Heltan, le forgeron de notre temple a disparu dans une faille temporelle, et mes Dopeuls refusent de se battre si ils n\\\'ont pas un petit marteau de Boisaille ? chaque combat... \\nSi tu veux en affronter un il faudra m\\\'apporter un de ces marteaux, en attendant qu\\\'on retrouve Faurge Heltan...');
INSERT INTO `npc_questions` VALUES (1816, '', '', '', '', 'Nous avons retrouv? Heltan, malheureusement, il a fortement vieilli. Il nous a demand? ? tous de lui ramener de la boue pour faire des bains. Et comme il le dit si bien \\\"On ne peut pas compter sur la charit? des X?lors, tu n\\\'as qu\\\'? demander un seau de boue du Boo avant chaque combat contre un dopeul.\\\"...');
INSERT INTO `npc_questions` VALUES (1817, '', '', '', '', 'Amine veut des peaux de Serpentin pour d?corer le temple, et encore une fois il m\\\'a demand? de vous les r?clamer... Il y a des jours comme ?a o? Amine r?ve de cr?er des temples pyramidaux ou d\\\'?crire avec des pictogrammes ?tranges, mieux vaux ne pas chercher ? comprendre...');
INSERT INTO `npc_questions` VALUES (1818, '', '', '', '', 'J\\\'ai besoin de Bandelettes pour refaire ma momification, je pense que les Ouginaks en utilisent et je suis sur que contre un petit combat de Dopeul, tu pourrais m\\\'en procurer !');
