INSERT INTO `npc_questions` VALUES (1838, '1599', '', 'QE!26', '2829', '... hmm mais pourtant tout co?ncide, ce vieux manuscrit est formel... \\nOh, excusez-moi je ne vous avais pas remarqu?, que puis-je faire pour vous ? Ou plut?t que pouvez-vous faire pour moi ? \\n');
INSERT INTO `npc_questions` VALUES (1839, '1600;1601', '', '', '0', 'Lors de mes recherches en cartographie, j\\\'ai trouv? un manuscrit qui indique la position de certains souterrains, l\\\'un d\\\'eux d?bute dans le sous-sol de la biblioth?que, mais impossible de comprendre le m?canisme pour y acc?der, je doute que quelqu\\\'un comme vous r?ussisse ? y p?n?trer...');
INSERT INTO `npc_questions` VALUES (1840, '1746', '', 'QE!9', '2069', 'Hey ! La fin du monde est imminente... les dieux sont en col?re, nous avons r?veill?... vestiges du pass?... nous sommes tous maudits ! Peuh ! \\nConstruire un abri... ?viter l\\\'explosion ! Aide-moi ou tu p?riras !');
INSERT INTO `npc_questions` VALUES (1841, '1637;1636', '', 'QE!3', '1881', 'Une Eriaxis Rigida Acrimonieuse, haha, je tiens l? un joli sp?cimen. Voyez par vous-m?me, tendez l\\\'oreille ? cette orchid?e, et vous serez de mauvaise humeur toute la journ?e ! \\nOh, je n\\\'ai pas fait attention ? l\\\'heure, il faut que je nourrisse ma plante Audrey, une Br?kmaris Acerbe d\\\'une extr?me raret?... pouvez-vous me donner un coup de main et aller l\\\'arroser ? ');
INSERT INTO `npc_questions` VALUES (1842, '1602', '', '', '0', 'Miaaaoow ! \\n*ce chacha semble bien triste*');
INSERT INTO `npc_questions` VALUES (1843, '1724', '', '', '0', 'Maow ? \\n*Vous ne comprenez gu?re ce qu\\\'il veut, peut-?tre a-t-il soif ? Un bol de lailait sans doute*');
INSERT INTO `npc_questions` VALUES (1844, '160', '', '', '0', '*Le chacha sent le lailait, le lape un peu, puis vide son ?cuelle* \\n*Il reprend ensuite sa complainte m?lancolique* \\nMaaaooooow');
INSERT INTO `npc_questions` VALUES (1845, '', '', '', '', '*peut ?tre a-t-il faim maintenant* \\n *il faudrait se renseigner sur l\\\'alimentation d\\\'un chacha et lui donner ? manger*');
INSERT INTO `npc_questions` VALUES (1846, '', '', '', '', '*Le chacha mange sans trop de conviction, puis reprend sa lente complainte* \\nMaaaaoowwww  ');
INSERT INTO `npc_questions` VALUES (1847, '', '', '', '', '*Peut-?tre l\\\'accompagner dans une petite promenade autour de la ville lui ferait du bien.\\nPour une bonne balade il faut passer par le parc, puis humer la bonne odeur de poisson ? l\\\'hotel de vente, puis respirer les fleurs de la marchande pour revenir ensuite ici*');
INSERT INTO `npc_questions` VALUES (1848, '', '', '', '', '*le chacha semble ?puis?, il se rassoit, regarde devant lui et recommence ? miauler* \\nMiaaaoww');
INSERT INTO `npc_questions` VALUES (1849, '', '', '', '', '*vous comprenez soudain la raison : la chacha rose en face ! \\nMais comment faire pour qu\\\'elle s\\\'int?resse ? lui ? il faudrait trouver quelque chose pour que ce chacha attire son attention.');
INSERT INTO `npc_questions` VALUES (1850, '', '', '', '', 'Meow !');
INSERT INTO `npc_questions` VALUES (1851, '', '', '', '', 'Maow ! \\n*Ce chacha semble heureux*');
INSERT INTO `npc_questions` VALUES (1852, '1610', '', '', '0', 'Ah que faire ?! Depuis peu ma cave est remplie de sousouris, en plus de faire un bruit effroyable et une odeur insupportable cela attire tous les chachas du quartier ! Du coup mon kwikwi a peur ! Et si mon Kwikwi ? peur je ne suis pas contente !');
INSERT INTO `npc_questions` VALUES (1853, '', '', '', '', 'boubou');
INSERT INTO `npc_questions` VALUES (1854, '', '', '', '', 'Oh c\\\'est vrai ? Vous ?tes bien aimable. Faites attention, ils sont quand m?me f?roces. \\nKwikwi sera bien content.');
INSERT INTO `npc_questions` VALUES (1855, '', '', '', '', 'Merci beaucoup. Tenez voici un peu d\\\'argent de poche, vous l\\\'avez bien m?rit?. Je me demande quand m?me ce que ces sousouris viennent faire ici. Je suis sure que c\\\'est ? cause de toute cette pagaille dans les souterrains. Ca fait remonter les sousouris ?a... Kwikwi est d\\\'accord avec moi !');
INSERT INTO `npc_questions` VALUES (1856, '1612;1613', '', 'QE!14', '2133', 'Bienvenuuue cher client, oh quel physique de r???ve vous avez l?, il faut  \\nabsoolument que vous achetiez mes habiits ! Ils mettront si bien vos  \\nformes en valeuur. Ah mais quelle impolitesse, je suis Alit Elfminate Le  \\nseul tailleur de moode du moonde, ou presque.');
INSERT INTO `npc_questions` VALUES (1857, '', '', '', '', 'La cr?ation de nouveaux v?tements est assez ?prouvante en soit. Utiliser des patrons est d?j? un peu plus facile, et encore...Un bon tailleur se doit d\\\'avoir un r?seau de fournisseur important, il ne fera pas grand-chose sinon. Sans compter qu\\\'il faut beaucoup d\\\'exp?rience pour faire des v?tements dignes des plus grands.');
INSERT INTO `npc_questions` VALUES (1858, '1649', '', '', '0', 'Ah ?a je ne dis pas non ? un petit coup de main. Nous avons besoin d\\\'un bon stock de laine de boufton, si d\\\'aventure vous alliez tondre quelques bestiaux...');
INSERT INTO `npc_questions` VALUES (1859, '', '', '', '', 'Merci beaucoup... Tenez : voil? le genre de cape que l\\\'on peut faire avec ?a. \\nAh vous ?tes chouux avec cette cape ! Ah mais il vous faut une doublure pour les soir?es d\\\'hiver ! Il me faudrait de la laine de bouftou standard, bien moins belle mais terriblement plus chaude, rapportez-moi votre cape et 5 laines et je vous arrange ?a, tut tut, on ne dit pas non !');
INSERT INTO `npc_questions` VALUES (1860, '', '', '', '', 'Vous voil? par? pour l\\\'hiver ! Quoique...vos oreilles...?a ne vas pas du  \\ntout, ?a !  Il faudrait quelque chose qui souligne vos jolis yeux tout en  \\nlissant la courbe de votre visage.  Lais-sez-moi-faire, je SAIS ce qu\\\'il vous  \\nfaut !');
INSERT INTO `npc_questions` VALUES (1861, '', '', '', '', 'Un cache oreilles voil? ce qu\\\'il vous faut ! Non vos oreilles sont tr???s joliies. Mais pour le froid d\\\'hiver il faut les prot?ger ! On n\\\'est pas ? l\\\'abri d\\\'une froidure telle qu\\\'en 22, n\\\'est-ce pas ? Je vais vous faire une cr?ation uniique ! Pour cel?, j\\\'ai besoin de mati?re premi?re plus rare...');
INSERT INTO `npc_questions` VALUES (1862, '', '', '', '', 'Pour l\\\'arceau, j\\\'ai besoin d\\\'une base solide, une d?fense de sanglier, que j\\\'entourerai d\\\'?toffe, donc deux ?toffes de sanglier. Deux pics de prespic pour le coeur des caches, et de la fourrure qui constituera le noyau doux...Enfin le plus dur, mais indispensable pour la douceur, une ?toffe faite de poils de milimulou pour les finitions, tout cela doit se trouver dans la for?t proche, ?a vaut le coup je vous l\\\'assure...');
INSERT INTO `npc_questions` VALUES (1863, '', '', '', '', 'Cela vous va troop bieen. Ouh, j\\\'en ai des frissons, sisi. Vous allez en faire craquer un paquet avec ?a ! Mais n\\\'h?sitez pas ? en changer cela dit. Les Tailleurs peuvent faire beaucoup de cr?ations qui vous donne un look unique ! ');
INSERT INTO `npc_questions` VALUES (1864, '', '', '', '', 'Voil? que je deviens fou, ma maison ?tait de l\\\'autre cot? de la rue, je fais une petite balade ? Br?kmar, je reviens et Pouf ! Plus de maisonnette. Qui aurait pu voler une maison comme celle-l? ? Vous ? Vous semblez louche d\\\'ailleurs.');
INSERT INTO `npc_questions` VALUES (1865, '', '', '', '', 'Drol : pff non...un gringalet dans votre genre n\\\'aurait jamais os? se mesurer ? moi. Passez donc votre chemin');
INSERT INTO `npc_questions` VALUES (1866, '', '', '', '', 'hum, je vous crois, ? vue d\\\'oeil vous ne pouvez pas faire grand-chose de toute fa?on.');
INSERT INTO `npc_questions` VALUES (1867, '', '', '', '', 'Vous d?sirez m\\\'aider ? Soit je vous l\\\'accorde, allez chercher d\\\'abord un maximum d\\\'indices, vous serez r?compens? pour chaque indice int?ressant, je note l\\\'emplacement de mon ex-maison sur votre carte.');
INSERT INTO `npc_questions` VALUES (1868, '', '', '', '', 'Alors ?');
INSERT INTO `npc_questions` VALUES (1869, '', '', '', '', 'Ainsi les oiseaux auraient mang? toute ma maison ? Une hypoth?se ? ?tayer, je me souviens que l\\\'un d\\\'eux m\\\'a regard? en coin de son oeil pervers l\\\'autre jour.');
INSERT INTO `npc_questions` VALUES (1870, '', '', '', '', ' Ah AH ! Une petite fille, peut-?tre est ce une voleuse, ou pire une magicienne jalouse de mes pouvoirs ! Tout s\\\'?claire gr?ce ? ?a ! Enfin ne nous pr?cipitons pas, notons cela comme une hypoth?se probable.');
INSERT INTO `npc_questions` VALUES (1871, '', '', '', '', 'Les Roublards hein ? Hummm, quels int?r?ts auraient-ils eu ? faire dispara?tre ma maison ?');
INSERT INTO `npc_questions` VALUES (1872, '', '', '', '', 'Ce morceau de tissu pourrait amener ? une conclusion fort simple, un voleur aurait trouv? ma maison fort jolie et l\\\'aurait d?rob?. Hum, un peu surr?aliste, ils ?taient peut ?tre deux... ');
INSERT INTO `npc_questions` VALUES (1873, '', '', '', '', 'Bon, R?fl?chissez ? tout ?a et aller me chercher le coupable, ne revenez pas sans ! Aller parler ? l\\\'alchimiste si vous avez quelque chose ? analyser, n\\\'h?sitez pas ? faire peur ou ? soudoyer les personnes que vous interrogerez, je VEUX savoir o? est ma MAISON !');
INSERT INTO `npc_questions` VALUES (1874, '', '', '', '', 'D?sol?e, mais je n\\\'ai pas le temps de bavarder avec toi. Mon p?re compte sur moi : je m\\\'occupe du troupeau de Bouftous familial. Il dit que c\\\'est une partie importante de ma formation. Bon je te laisse j\\\'en entends un qui mugit...');
INSERT INTO `npc_questions` VALUES (1875, '', '', '', '', 'J\\\'esp?re que vous connaissez le coupable ?');
INSERT INTO `npc_questions` VALUES (1876, '', '', '', '', 'Hmm, quelques morceaux font partie de ma maison sans aucun doute, mais on dirait plus des copeaux tomb?s. Par contre il y a une barrette ici...mais c\\\'est celle de Marp ? MARP ?');
INSERT INTO `npc_questions` VALUES (1877, '', '', '', '', 'comment ?a Marp ? Ce n\\\'est pas possible, elle ne se moquerait pas de moi ains...hum....Marp ? MARP ?');
INSERT INTO `npc_questions` VALUES (1878, '', '', '', '', 'Marp est une petite farceuse, elle est gentille dans le fond, mais de vous ? moi elle est un peu sp?ciale.');
INSERT INTO `npc_questions` VALUES (1879, '', '', '', '', 'Vous ?tes ici chez moi, ne faites pas de b?tises sinon vous aurez affaire ? moi...');
INSERT INTO `npc_questions` VALUES (1880, '', '', '', '', 'Rien dans les muscles, un peu dans le cerveau et ?a se permet  \\nd\\\'arr?ter mon petit jeu ! Ah lala, oui c\\\'est moi qui l\\\'ai d?plac?e. Je l\\\'ai mise  \\ndans le jardin, pour ?viter qu\\\'elle ne se fasse squatter par les chienchiens du voisinage.');
INSERT INTO `npc_questions` VALUES (1881, '', '', '', '', 'Voici mon adresse au Sud de la ville, vous ne pouvez pas rater la maison, il y a un tas de v?g?tation tout autour ! \\nIl y a un puits un peu ? l\\\'Ouest de ma maison, si vous ne savez pas o? aller chercher de l\\\'eau... ');
INSERT INTO `npc_questions` VALUES (1882, '', '', '', '', 'Grand Dieu merci ! Je suis tellement absorb? par mon travail, que j\\\'en oublierais presque o? j\\\'habite, haha ! Puisque je vois que tu aimes rendre service, ne voudrais-tu pas me ramener une fleur de pissenlit diabolique, j\\\'en croise souvent en allant dans les champs au Nord-Est du village... \\nJ\\\'aimerais comparer la composition de leurs graines avec de l\\\'Epyss Sauvage que j\\\'ai ramass?e hier !');
INSERT INTO `npc_questions` VALUES (1883, '', '', '', '', 'Fascinant, mes d?ductions ?taient exactes, ces deux plantes ont une origine commune. Ah oui, j\\\'ai omis de te pr?ciser ! Je suis ?crivain, et actuellement je r?dige un ouvrage sur l\\\'apparition des plantes agressives ? Amakna. J\\\'ai d?couvert dans d\\\'anciens manuscrits, qu\\\'avant les ann?es 150 les fleurs ?taient amicales, voire m?me serviables ! Je me demande vraiment ce qui les a rendu si agressives !');
INSERT INTO `npc_questions` VALUES (1884, '', '', '', '', 'Tes informations sont int?ressantes, mais il faudrait que j\\\'en sache davantage pour tirer des conclusions fiables. J\\\'ai une connaissance ? Amakna, un certain Trois-Fleurs, demande lui de te faire d?couvrir la v?g?tation de sa r?gion, et ram?ne-moi un rapport quand tu repasseras ? Astrub ! Aller va, jeune disciple, haha !');
INSERT INTO `npc_questions` VALUES (1885, '1638', '', 'QE!24', '1887', 'Tout mon stock de metaria et de runes a disparu. Arg ! Satan? voleur ! Pourquoi moi ? Pourquoi aujourd\\\'hui ? Comment vais-je faire ? Mon rendez-vous de ce soir va ?tre catastrophique... Je n\\\'ai plus le  \\ntemps d\\\'aller les r?cup?rer...');
INSERT INTO `npc_questions` VALUES (1886, '1639', '', '', '0', 'Oh vous feriez ?a pour moi ? Alors voil?, je vous explique : ce soir j\\\'avais un rendez-vous galant avec dame Seria - c\\\'est pr?vu depuis un mois. Mais demoiselle Fita est revenue de son voyage aujourd\\\'hui m?me : elle m\\\'a invit? chez elle ce soir ! L\\\'heure ? laquelle dame Seria doit me quitter correspond ? l\\\'heure o? je dois ?tre chez Fita mais les deux lieux sont trop ?loign?s...');
INSERT INTO `npc_questions` VALUES (1887, '2115', '', '', '0', 'Bon on va se partager les t?ches, pourriez vous aller m\\\'acheter deux roses ? Je vous indique le vendeur sur votre carte si vous voulez. Pendant ce temps l? je me pr?pare et j\\\'analyse les traces laiss?es par le voleur');
INSERT INTO `npc_questions` VALUES (1888, '2119', '', '', '0', 'Bonjour, que d?sirez vous ?');
INSERT INTO `npc_questions` VALUES (1889, '', '', '', '', 'Oh, je vois, hihi, votre demoiselle ? bien de la chance. J\\\'aimerais bien que l\\\'on m\\\'offre juste une petite rose moi aussi. Une petite rose de rien du tout. H?las il ne m\\\'en reste pas, je suis confuse. Je ne peux aller en chercher tout de suite mais je peux vous indiquer o? en trouver.');
INSERT INTO `npc_questions` VALUES (1890, '', '', '', '', 'Prenez ces ciseaux - ne vous battez qu\\\'avec cette arme sinon vous ab?merez la fleur. Allez chasser de la rose d?moniaque au Nord Ouest d\\\'ici, vous en trouverez dans les champs pr?s de la ferme.');
INSERT INTO `npc_questions` VALUES (1891, '', '', '', '', ' C\\\'est pour moi ? Bien que je suis marchande de fleur, votre geste me touche beaucoup. Merci...');
INSERT INTO `npc_questions` VALUES (1892, '', '', '', '', 'J\\\'ai toujours r?v? d\\\'avoir un apprenti comme toi, tu sais le genre qu\\\'on envoie faire des commissions ? l\\\'autre bout du pays et qui revient toujours avec le sourire... Enfin bref, si tu veux aller un peu sur le terrain, je voudrais que tu sillonnes les alentours et que tu r?pertories trois endroits dans les champs o? poussent le plus souvent des fleurs, j\\\'aimerais faire un recoupement topographique des esp?ces les plus courantes !');
INSERT INTO `npc_questions` VALUES (1893, '', '', '', '', 'Merci beaucoup, cela me retire une ?pine de rose du pied haha ! ');
INSERT INTO `npc_questions` VALUES (1894, '', '', '', '', 'Pour ma part, j\\\'ai briqu? mon ?paulette et j\\\'ai trouv? quelques traces int?ressantes : des petits cailloux... *il r?fl?chit* Il faudrait ? pr?sent v?rifier d\\\'o? ces petits cailloux proviennent. ');
INSERT INTO `npc_questions` VALUES (1895, '1642', '', 'QE!13', '2289', 'Pffuu, chaque jour, c\\\'est la m?me chose, si je ne monte pas la garde toute la nuit, je retrouve une partie de mon troupeau massacr?e. J\\\'ai aper?u plusieurs fois une cr?ature ressemblant ? un milimulou avec beaucoup plus de poils, mais pas moyen de l\\\'attraper... Je ne sais pas ? qui m\\\'adresser pour en savoir plus, il doit bien y avoir quelqu\\\'un ? Astrub qui est sp?cialiste de ce genre de cr?atures, non ?');
INSERT INTO `npc_questions` VALUES (1896, '', '', '', '', 'Pourriez-vous visiter les diff?rents lieux suspects ? Analysez les cailloux, faites en une petite description et rapportez-moi vos r?sultats. Je pense notamment ? 3 endroits. Le premier, juste ? la sortie de la ville au Sud. Le deuxi?me est sur le chemin nord qui conduit ? l\\\'or?e de la for?t. Et le troisi?me conduit aux grottes. Vous les trouverez facilement en partant vers le nord et en vous dirigeant ? droite au carrefour des chemins.');
INSERT INTO `npc_questions` VALUES (1897, '', '', '', '', 'Merci beaucoup. Il faut faire vite, il ne me reste plus beaucoup de temps avant le premier rendez-vous.  Bon voyons...');
INSERT INTO `npc_questions` VALUES (1898, '', '', '', '', 'Les cailloux que j\\\'ai r?cup?r?s sur le tapis proviennent sans nul doute de la grotte au nord-Est donc, Allons-y ? deux, nous aurons plus de chance. Partez devant je vous rejoins...');
INSERT INTO `npc_questions` VALUES (1899, '', '', '', '', 'Un ours dis tu ? En tous cas si tu veux trouver ses traces, je l\\\'ai vu tra?ner ? l\\\'Ouest d\\\'ici, la nuit derni?re. Merci pour tes efforts mon ami, tu seras r?compens? ? ta juste valeur !');
INSERT INTO `npc_questions` VALUES (1900, '', '', '', '', 'Comment faire pour qu\\\'il arr?te de penser ? ces deux idiotes...J\\\'ai bien une id?e  \\nmais il risque d\\\'?tre tr?s triste, et en col?re s\\\'il apprend que c\\\'est  \\nmoi... Ahh que c\\\'est dur *soupir*');
INSERT INTO `npc_questions` VALUES (1901, '', '', '', '', 'Arg ! C\\\'est de pire en pire, je n\\\'ai pas pu aller aux rendez-vous, je me suis donc fait pardonner en les invitant ? la foire du Trool... Mais du coup j\\\'ai trois rendez-vous en m?me temps.\\nComment faire ?\\n');
INSERT INTO `npc_questions` VALUES (1902, '', '', '', '', 'H? toi jeune F?ca ! Arr?te de r?vasser !... on dirait que tu viens de tomber du ciel ! J\\\'aurais bien besoin d\\\'un coup de main...');
INSERT INTO `npc_questions` VALUES (1903, '1648;1647;1947', '', 'QE!10', '2117', 'Bienvenue ? la boulangerie Croa, ici nous fabriquons du pain ? l\\\'ancienne ! Chaque pain fabriqu? ici est fait en respectant l\\\'ancienne tradition ! Vous le sentirez tout de suite au go?t, je vous le dit...');
INSERT INTO `npc_questions` VALUES (1904, '1946', '', '', '0', 'Trouver, s?lectionner puis acheter les bonnes farines aux paysans. Fabriquer la p?te, la p?trir et la former, puis la cuire, repr?sente tout le travail d\\\'un boulanger. Mais ne vous y trompez pas, chacune de ses ?tapes demande une attention et un savoir faire tr?s particulier. C\\\'est pourquoi il existe autant de sorte de pain. \\n');
INSERT INTO `npc_questions` VALUES (1905, '1641', '', '', '0', 'Vous tombez bien, ? vrai dire mon livreur vient de tomber malade et je ne peux assurer la livraison d\\\'une commande sp?ciale. J\\\'ai besoin de bras forts, et de jambes rapides pour livrer ces g?teaux aux quatre coins de la ville. Je paierai bien, cela vous int?resse-t-il ? ');
INSERT INTO `npc_questions` VALUES (1906, '', '', '', '', 'Merci beaucoup, voil? je vous donne une liste de personnes ? livrer. Il faut qu\\\'ils aient re?u leurs g?teaux pour dans...environ 20 minutes. Les g?teaux sont d?j? pay?s mais pas la livraison. Ce sera votre paye.');
INSERT INTO `npc_questions` VALUES (1907, '', '', '', '', 'Merci beaucoup, pourriez-vous me rendre un autre petit service dans la foul?e ? J\\\'ai eu vent que mon livreur n\\\'?tait pas malade du tout... Il pr?f?re courir les filles que de livrer mes commandes. J\\\'aimerais que vous puissiez le surveiller pour voir si cela est vrai...');
INSERT INTO `npc_questions` VALUES (1908, '', '', '', '', 'Il s\\\'appelle Louc Drif : \\\"livreur ind?pendant professionnel\\\" qu\\\'il disait ! Il habite le quartier Iop. Si vous me donnez votre carte, je vous note l\\\'emplacement de sa maison. Revenez me voir quand vous serez s?r qu\\\'il est r?ellement malade... ou pas !');
INSERT INTO `npc_questions` VALUES (1909, '', '', '', '', 'Ah, te voil? ! Je m\\\'appelle Allisteria. Tu pourrais m\\\'aider un peu ? Je dois m\\\'occuper de mon troupeau de Bouftous, mais depuis les ?boulements, je ne m\\\'en sors pas !');
INSERT INTO `npc_questions` VALUES (1910, '1856', '', 'QE!11', '2239', 'Ma peluuuche, ouiiin, on me l\\\'a vol?e?! J\\\'avais eu tant de mal ? la gagner ? la foire du Trool..... Pourriez-vous m\\\'aider ? la r?cup?rer?? Ce sont ces bandits... dans la for?t au Nord du village, ils m\\\'ont... ils m\\\'ont attaqu?e, et ont vol? ma peluuche... ');
INSERT INTO `npc_questions` VALUES (1911, '', '', '', '', 'Bah que croyez vous, j\\\'ai un rendez-vous et j\\\'ai un p?pin alors... ah... kof kof, euh je suis malade en plus. Je ne peux bouger de chez moi avant ce soir, ordre du m?decin. Pas de livraison exceptionnellement aujourd\\\'hui.');
INSERT INTO `npc_questions` VALUES (1912, '', '', '', '', 'J\\\'ai 3 rendez-vous en m?me temps, comment croyez-vous que je vais ? Je... Ah... Euh je suis malade... Oh et puis mince ! Je vais tr?s bien, je me doute bien que c\\\'est le boulanger qui vous envoie... Pr?sentez lui ma d?mission ! Je ne livrerai plus que des trucs dangereux maintenant ! Je m\\\'ennuie trop sinon...');
INSERT INTO `npc_questions` VALUES (1913, '', '', '', '', 'Il d?missionne ? Je le vire avant ouais ! Bon ! Vous allez me trouver un nouveau livreur ! D?sol?, je n\\\'ai que vous sur la main... \\n');
INSERT INTO `npc_questions` VALUES (1914, '', '', '', '', 'Je vous explique : il me faut quelqu\\\'un d\\\'assez fort pour tracter 1500 pods de pain, et qui sache courir vite - ce qui veut dire ?tre agile... Cherchez une personne qui ressemble ? ?a, et parlez lui. Si vous pensez qu\\\'elle convient, remplissez cette fiche et posez la paume de sa main en bas. Vous saurez ainsi directement si votre choix est le bon...');
INSERT INTO `npc_questions` VALUES (1915, '', '', '', '', 'Finalement tous les candidats ?taient plut?t mous. Je pense que je vais embaucher des gens motiv?s au jour le jour. Il y a de la demande pour ce genre de petit boulot ! Vous pouvez effectuer la premi?re livraison du jour pour moi ? Exceptionnellement je te paierai le double du tarif. Tu auras le droit de revenir me voir pour refaire une livraison sit?t apr?s - si le coeur t\\\'en dit ?videmment !');
INSERT INTO `npc_questions` VALUES (1916, '', '', '', '', 'Notre cave ? bl? est encombr?e de gravats. Et je dois continuer d\\\'engraisser mes Bouftous en attendant que tout soit d?gag? par les Enutrofs. A d?faut de bl?, de la bi?re ferait l\\\'affaire... \\nSi je te donne 10 Kamas pour aller m\\\'en chercher, tu pourras m\\\'aider ? J\\\'aurais besoin de 5 bi?res. Prends la moins ch?re, mes petits pr?f?rent la quantit? ? la qualit');
INSERT INTO `npc_questions` VALUES (1917, '', '', '', '', 'Pnj(471) et Message(1909)');
INSERT INTO `npc_questions` VALUES (1918, '2008;1655;1657', '', 'QE!5', '1923', 'Bienvenue dans ma modeste boutique, je ne vends que tr?s peu de choses ici, mais je forme des apprentis. Mes cr?ations sont uniques et le plus souvent sur commande...');
INSERT INTO `npc_questions` VALUES (1919, '', '', '', '', 'La cr?ation de bijoux demande un r?el savoir faire et une patience ? toute ?preuve, cela n?cessite aussi un grand sens de l\\\'art... H?las, je ne serai jamais aussi dou?e que Azra Lazarus du village d\\\'Amakna...');
INSERT INTO `npc_questions` VALUES (1920, '', '', '', '', 'Merci beaucoup. Va voir le tavernier Tek Abir, il commence ? avoir l\\\'habitude.');
INSERT INTO `npc_questions` VALUES (1921, '1658', '', '', '0', 'Actuellement j\\\'ai besoin de main d\\\'oeuvre : j\\\'ai de plus en plus d\\\'apprentis et mes stocks d\\\'ingr?dients se vident. J\\\'ai encore assez de mati?res premi?res gr?ce aux nombreux mineurs et b?cheron qui m\\\'aident, mais je suis tomb? ? cours de mati?res rares. Voudriez-vous m\\\'en apporter ? Je vous payerai.');
INSERT INTO `npc_questions` VALUES (1922, '', '', '', '', 'En plus du bois et des minerais, les bijoutiers utilisent beaucoup de mati?res vivantes et naturelles provenant des monstres des environs. Elles servent ? travailler la mati?re en elle-m?me, ou en tirer une essence magique propre aux enchantements. J\\\'aurai besoin justement de pattes d\\\'Araknes... Son essence donne une teinte particuli?re - en plus de poss?der un petit plus magique !');
INSERT INTO `npc_questions` VALUES (1923, '', '', '', '', 'Vous avez r?ussi ? en trouver ?');
INSERT INTO `npc_questions` VALUES (1924, '', '', '', '', 'Merci beaucoup, tenez voici un ?chantillon de ce que nous pouvons faire, n\\\'h?sitez pas ? repasser. Ah tant que je vous tiens. Seriez vous int?ress? pour un peu d\\\'argent facile ? Il me faudrait d\\\'autre ?l?ments...');
INSERT INTO `npc_questions` VALUES (1925, '', '', '', '', 'Je vous remercie beaucoup. J\\\'ai un peu honte, mais il me faudrait encore autre chose.');
INSERT INTO `npc_questions` VALUES (1926, '', '', '', '', 'J\\\'ai compl?tement oubli? que nous utiliserons les ?pines de champ champ pour la cr?ation d\\\'aujourd\\\'hui... Il risque d\\\'en manquer pour les ?preuves... Si cela ne vous d?range pas j\\\'en aurai besoin d\\\'une demi-douzaine...');
INSERT INTO `npc_questions` VALUES (1927, '', '', '', '', 'Mille mercis. Les ?preuves vont pouvoir se d?rouler sans risque maintenant. Et c\\\'est en grande partie gr?ce ? vous. Les apprentis et moi-m?me vous en sommes reconnaissants. Tenez pour vous r?compenser je vous donne un anneau cr?? lors des ?preuves pr?c?dentes. Il n\\\'est pas encore actif, ? vous de faire surgir ses pouvoirs magiques !');
INSERT INTO `npc_questions` VALUES (1928, '', '', '', '', 'Pour activer les pouvoirs de l\\\'anneau, il vous faut le soumettre ? ce que j\\\'appelle des \\\"ondes magiques\\\". Le plus simple est d\\\'aller chasser un Abraknyde au plus profond de la for?t. Cette esp?ce d\\\'arbre est enti?rement m?e par la magie : lorsqu\\\'il meurt la magie qu\\\'il lib?re est consid?rable. Elle sera suffisante pour activer l\\\'anneau. Attention les Abraknydes se r?v?lent tr?s dangereux... n\\\'h?sitez pas ? engager des mercenaires !');
INSERT INTO `npc_questions` VALUES (1929, '', '', '', '', 'Voici l\\\'anneau. Comme monstre, je vous sugg?re l\\\'abraknyde qui tra?ne dans la for?t. Les  ondes magiques qui se propagent quand il meurt sont les plus susceptibles d\\\'activer l\\\'anneau. Bonne chance. Faites attention, l\\\'abraknyde peut se r?v?ler dangereux, n\\\'h?sitez pas ? demander de l\\\'aide. L\\\'anneau est ? vous dans tout les cas');
INSERT INTO `npc_questions` VALUES (1930, '1662', '[name]', '', '0', 'Bienvenue #1 ! Haha ! Comment je connais ton nom ? Facile, ici c\\\'est le meilleur centre d\\\'information de la ville, tu peux apprendre beaucoup de choses en sirotant une bi?re. ');
INSERT INTO `npc_questions` VALUES (1931, '', '', '', '', 'Il parait que les enutrofs ont d?couvert des galeries en dessous de la ville. Si vous voulez mon avis, il se trame un truc pas net l?-dessous.');
INSERT INTO `npc_questions` VALUES (1932, '', '', '', '', 'D?sol?, la maison ne fait plus cr?dit.');
INSERT INTO `npc_questions` VALUES (1933, '', '', '', '', 'Salut ! Tu tombes bien ! Je t\\\'explique : Mon ma?tre n\\\'a pas la possibilit? de se d?placer - me fais pas dire ce que j\\\'ai pas dit, c\\\'est pas un rhumatisme sur pattes, hein... ahem ! Il est tr?s occup?, et tu sembles faire partie de ses projets. Il sait tooooout ce qui se passe par ici... ');
INSERT INTO `npc_questions` VALUES (1934, '', '', '', '', 'Alors te voil?, c\\\'est pas trop t?t ! Tu ne m\\\'as pas l\\\'air d\\\'?tre tr?s d?gourdi, mais ?a va vite changer, tu verras. Pour l\\\'instant, j\\\'ai une t?che ? te confier.');
INSERT INTO `npc_questions` VALUES (1935, '', '', '', '', 'Merci pour le rapport.... Je suis vraiment entour? d\\\'une bande d\\\'incapables ! Et puis, de quoi il me parle lui... j\\\'arrive m?me pas ? le relire... ?quipe de fouille... une autre d?couverte... bon sang ! Je veux savoir ce que c\\\'est ! ');
INSERT INTO `npc_questions` VALUES (1936, '', '', '', '', 'Arrghhh... j\\\'ai un de z? mal de gr?ne, on dirait gue je me zuis fait pi?tiner par un droupeau d\\\'Abraknyde... ');
INSERT INTO `npc_questions` VALUES (1937, '180', '[name]', '', '0', 'Yo #1 ! T\\\'es venu pr?ter main forte ? notre petite entreprise ? Y\\\'en a s?rieusement b\\\'soin, crois moi. En fait on manque carr?ment de courageux... pourtant y\\\'a de l\\\'or ? se faire ! Alors ?a te dit ?...  ouais ! J\\\'en ?tais s?r ! J\\\'ai besoin que tu te fasses assurer, ?a pourrait ?tre dangereux l? d\\\'sous...  hahahahah ! Regardez moi ch\\\'te t?te ! Je plaisantais hein ! Il s\\\'agit juste d\\\'apporter une lettre ? un bon ami ! Haha... \\nIl s\\\'appelle Howard le Simaisrien, un Iop. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole, tu ne pourras pas le louper ! ');
INSERT INTO `npc_questions` VALUES (1938, '', '', '', '', 'Comment ? Moi ? Cesser mes affaires ? J\\\'esp?re qu\\\'il plaisante ! Tu le lui as dit, hein ?Hors de question ! Non mais ! Manquerait plus que ?a... hahaha ! Allez, va vite pr?venir mes hommes l? d\\\'sous, qu\\\'on leur envoie un peu d\\\'monde ! Ah ! Et tiens, prends cette pelle, ?a te sera s?rement aussi utile que ta chance. Un bon coup de pelle, y\\\'a bien qu\\\'un Sram pour y survivre. Haha ! ');
INSERT INTO `npc_questions` VALUES (1939, '180', '', '', '0', 'Ahhh de l\\\'action ! Ahahaha ! Dis ? ton ma?tre qu\\\'on va s\\\'occuper de ?a ! Y\\\'a ici plein de nouvelles recrues qui ne demandent que ?a ! Nous allons tout de m?me avoir besoin de soutien, pourquoi ne pas pr?venir nos amis Eniripsa et Feca ?');
INSERT INTO `npc_questions` VALUES (1940, '', '', '', '', 'Vous ?tes une nouvelle recrue, n\\\'est-ce pas ?... je doute fort pouvoir vous convaincre de ne pas aller l? dessous, mais j\\\'aimerais tout de m?me que cessent ces fouilles ? c\\\'est une telle pagaille ! Je vais informer les membres de ma guilde, dites ? Joe Pierlivet de mettre ses affaires en suspend, par prudence.');
INSERT INTO `npc_questions` VALUES (1941, '', '', '', '', 'La sagesse a guid? vos pas mon jeune ami. Vous apprendrez avec moi l\\\'art de soigner les maux et les plaies les plus douloureuses qui aient jamais exist?, m?me le pire de tous : L\\\'Ass? Phal?. Mais avant tout, il vous faut les bons instruments, en l\\\'occurrence, une baguette. Pouvons nous commencer ? ');
INSERT INTO `npc_questions` VALUES (1942, '', '', '', '', 'Ho tr?s bien ! Je vois en vous un certain don pour les relations, c\\\'est une tr?s bonne chose. Je vais m\\\'occuper de cr?er votre baguette. *Nepra verse l\\\'extrait de Dzibi sur une simple tige de bois, qui semble d\\\'un coup reprendre vie, une fleur pousse ? son extr?mit?, ressemble ?trangement ? une de ces fleurs de Dzibi*. Voici votre baguette! prenez-en soin, c\\\'est elle qui vous sortira des mauvais pas... En parlant de mauvais pas, j\\\'ai pour vous une premi?re mission...');
INSERT INTO `npc_questions` VALUES (1943, '', '', '', '', 'De l\\\'extrait de Dzibi, oui bien s?r ! Vous ?tes un nouvel apprenti ? De qui ? De Nepra ?... ahh... Nepra... hmmm... charmante, n\\\'est ce pas ? Je me rappelle quand j\\\'?tais moi-m?me son ?l?ve, j\\\'aurais pu passer des heures ?... *soupir*');
INSERT INTO `npc_questions` VALUES (1944, '', '', '', '', 'Bien sympathique cette auberge, dommage que la bi?re ne soit pas aussi excellente que la feubuk ! Tiens rapproche toi...parait que le patron coupe sa bi?re avec de l\\\'eau, tu te rends compte ? Je paierais cher pour savoir si c\\\'est vrai.');
INSERT INTO `npc_questions` VALUES (1945, '', '', '', '', 'Maintenant que tu as les bibines, tu peux en donner une ? chacun des Bouftous. Attention ? ne pas faire de jaloux ! Reviens me voir quand tu auras fini... Ton aide sera la bienvenue.');
INSERT INTO `npc_questions` VALUES (1946, '', '', '', '', 'Je..Je...Ah je suis fini *soupir*.');
INSERT INTO `npc_questions` VALUES (1947, '', '', '', '', '*Sigh* croyez-moi ou pas, je ne coupe pas la bi?re par radinerie. Mais je n\\\'ai pas le choix. Mon stock de bi?re s\\\'amenuise et toujours pas de nouvelle livraison. Sans bi?re, plus de clients, sans client plus de taverne, sans taverne plus de Tek. *soupir*');
INSERT INTO `npc_questions` VALUES (1948, '', '', '', '', 'Vous m\\\'aideriez ? C\\\'est vrai ? Vous me faites bien plaisir. Mes livraisons de bi?re arrivent d\\\'Amakna par la grande route du Sud, je sais qu\\\'il doit en partir une chaque jour, mais jamais elle n\\\'arrive ici. Longez la grande route du sud vous devriez croisez un livreur. Escortez la livraison jusqu\\\' ici s\\\'il vous plait.');
INSERT INTO `npc_questions` VALUES (1949, '', '', '', '', 'Tu n\\\'as pas encore fait ce que je t\\\'ai demand? ? Tu te moques de moi ? Aller d?p?che-toi s\\\'il te plait.');
INSERT INTO `npc_questions` VALUES (1950, '', '', '', '', 'Pnj(464) et Message(1948)');
INSERT INTO `npc_questions` VALUES (1951, '', '', '', '', 'Je te remercie infiniment ! Tu sais, je suis vraiment d?bord?e. Tu veux bien demander au boucher de tuer un des Bouftous que je lui ai confi? ? Je suis si sensible... en m?me temps, j\\\'adore le boudin bouilli de Bouftou ! Miam ! Pas question d\\\'y renoncer ! Ach?te aussi 2 citrons ? Seth Sourcet. Tiens, voil? encore 5 Kamas pour les citrons.');
INSERT INTO `npc_questions` VALUES (1952, '', '', '', '', 'C\\\'est gentil. ');
INSERT INTO `npc_questions` VALUES (1953, '', '', '', '', 'Je suis le livreur de bi?re, aujourd\\\'hui j\\\'ai d?cid? de passer, alors je vais passer !');
INSERT INTO `npc_questions` VALUES (1954, '', '', '', '', 'Tr?s bien vous m\\\'avez l\\\'air honn?te, je vous suis...');
INSERT INTO `npc_questions` VALUES (1955, '', '', '', '', 'La bi?re est livr?e, merci beaucoup. Vous avez emp?ch? celle-ci de se faire voler aujourd\\\'hui,mais demain ? Pourrez vous faire quelque chose ?');
INSERT INTO `npc_questions` VALUES (1956, '', '', '', '', 'Il faudrait pouvoir entrer en contact direct avec eux, ou savoir o? les rencontrer. Et faire cesser ce vol. Difficile ?a...hmmm !');
INSERT INTO `npc_questions` VALUES (1957, '', '', '', '', 'Te fiches pas moi ! C\\\'est la c?l?bre r?plique de... heuuu... m\\\'enfin si, tu sais bien !');
INSERT INTO `npc_questions` VALUES (1958, '', '', '', '', 'C\\\'est toi qui vois... Ceci dit, je ne me rapelle pas que mon ma?tre ait jamais laiss? s\\\'?chapper une proie. Plus s?rieusement, sois sympa ! Je risque de me faire passer un savon.');
INSERT INTO `npc_questions` VALUES (1959, '', '', '', '', 'Passe par l\\\'entrep?t de bois ? c?t? d\\\'ici, et trouve l\\\'entr?e de sa planque, c\\\'est une trappe dissimul?e. Evidemment, la discr?tion est de rigueur, si tu es captur? ou tu?... tu connais la chanson.... \\nJe t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (1960, '', '', '', '', 'Merci beaucoup. Je vais vite cuisiner ?a. Tu sais, notre famille est r?put?e pour son boudin bouilli de bouftou ! Nous avons une fa?on sp?ciale de les gaver, ce qui donne un go?t particulier ? leur viande... Tu m\\\'en diras des nouvelles !');
INSERT INTO `npc_questions` VALUES (1961, '', '', '', '', 'Qu\\\'est ce que tu veux toi ? Oh mais tu ne serais pas celui qui a d?figur? cet idiot de Kaba ? Et tu oses te pointer la bouche en coeur...D?sires tu vraiment mourir ?');
INSERT INTO `npc_questions` VALUES (1962, '', '', '', '', 'Des explications ? Te crois tu en position de force pour demander des explications ?!');
INSERT INTO `npc_questions` VALUES (1963, '', '', '', '', 'Tr?s bien ! Alors tu vas retrouver un de mes agents, il doit se trouver quelque part dans l\\\'ombre de ces Enutrofs. Il devrait avoir pour moi des informations primordiales. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (1964, '', '', '', '', 'Houla, tu sors le grand jeu, peu de gens peuvent voir les chefs, ? la limite un haut grad?... Si tu le d?sires vraiment, je te l\\\'accorderai... mais pour prouver ta bonne foi il faudra me ramener 2500 kamas, et me rendre la cape d?chir?e que tu poss?des. Sinon, tu peux toujours invoquer la r?gle de puissance, rahaha !');
INSERT INTO `npc_questions` VALUES (1965, '', '', '', '', 'Les temps sont durs l\\\'ami, surtout pour celui qui joue au malin...');
INSERT INTO `npc_questions` VALUES (1966, '', '', '', '', 'Ah de l\\\'argent, merci beaucoup ahah. C\\\'est moi le chef, qu\\\'est ce que tu veux ?');
INSERT INTO `npc_questions` VALUES (1967, '', '', '', '', 'Une loi du plus fort, hahaha, Allez c\\\'est d\\\'accord : Loofi, Delminss, tuez le !');
INSERT INTO `npc_questions` VALUES (1968, '', '', '', '', 'Joli travail m?me si le combat ?tait plut?t mou, c\\\'est moi le chef que veux tu ?');
INSERT INTO `npc_questions` VALUES (1969, '', '', '', '', 'Une raison ? Mes hommes ont besoin de se d?tendre, c\\\'est tout.');
INSERT INTO `npc_questions` VALUES (1970, '', '', '', '', 'Tu te prends pour qui ? Je vais te...Hmm..attends, tu dis que la Tavernier mise sa vie sur cette bi?re...int?ressant...Tr?s bien nous ne lui voleront plus sa bi?re s\\\'il accepte de nous en fournir ? un prix tr?s bas. Convainc le s\\\'il ne veut pas. Va !');
INSERT INTO `npc_questions` VALUES (1971, '', '', '', '', 'Je n\\\'ai pas le temps de trouver un gars d\\\'exp?rience, c\\\'est toi qui vas y aller dans ces souterrains ! Prends cette dague, ?a pourra servir en cas de coups durs. A moins que ta l?gendaire agilit? ne fasse le reste ! Gnh?h?h? !  \\n-Crac- A?e mon lumbago ! ');
INSERT INTO `npc_questions` VALUES (1972, '', '', '', '', 'Demander un autre compromis ?!');
INSERT INTO `npc_questions` VALUES (1973, '', '', '', '', 'Quoi ?! C\\\'est du VOL ! Humm, bah je couperai leur bi?re avec de l\\\'eau, c\\\'est d\\\'accord.');
INSERT INTO `npc_questions` VALUES (1974, '', '', '', '', 'Ouais za va hein ! J\\\'ai bien zentit que j\\\'avais comme une marque de pelle zur la face, mais le brobl?me n\\\'est bas l? ! J\\\'ai des infos zuper imbortantes, mais l\\\'Enutrof gui m\\\'a surbris a maintenant mon rabbort en sa bossession, et s\\\'il z\\\'en zert, z\\\'en est fini de moi ! Tu combrends ?!');
INSERT INTO `npc_questions` VALUES (1975, '', '', '', '', 'Bon, on va faire zimble : Je zuis grill? et je ne peux pas m\\\'abbrocher de cet Enutrof, alors z\\\'est toi qui va aller r?cub?rer mon rabbort. Et zi tu bouvais ne pas trop barler de zet inzident au ma?tre... ze zerait bien zymba.');
INSERT INTO `npc_questions` VALUES (1976, '', '', '', '', 'JE LE SAVAIS ! J\\\'en ?tais s?r, tiens voil? une chtite r?compense pour toi.');
INSERT INTO `npc_questions` VALUES (1977, '', '', '', '', 'Et alors ?! Il est o? ce rapport ?');
INSERT INTO `npc_questions` VALUES (1978, '', '', '', '', 'Voyons voir... vous n\\\'avez pas de capuche, pas d\\\'air sournois, vous me semblez honn?te... s?rement trop.');
INSERT INTO `npc_questions` VALUES (1979, '', '', '', '', 'Ze beu faire guelgue chose bour vous ? *sniff*');
INSERT INTO `npc_questions` VALUES (1980, '', '', '', '', 'Que faire, que faire, mon amie est gravement malade. Mais je ne peux pas l\\\'abandonner ici pour aller chercher un rem?de. Que faire ?');
INSERT INTO `npc_questions` VALUES (1981, '', '', '', '', 'Locette est une milicienne de Bonta. Elle est revenue de l\\\'une de ses missions avec une sorte de maladie. Elle trouvait tous les aliments fades. Le m?decin ne vit rien d\\\'anormal. Le lendemain ses oreilles bourdonnaient en permanence et nous devions ?crire pour communiquer. Par la suite elle perdit la vue... puis la parole... et elle finit par perdre connaissance...');
INSERT INTO `npc_questions` VALUES (1982, '', '', '', '', 'Je ne sais pas qui vous ?tes, mais si vous avez r?ussi ? entrer ici, je doute que vous soyez capable d\\\'en ressortir si facilement...');
INSERT INTO `npc_questions` VALUES (1983, '', '', '', '', 'Le m?decin ne conna?t pas pareille maladie, mais il refuse d\\\'abandonner Locette ? son triste sort;\\r\\n            il m\\\'a demand? s\\\'il pouvait essayer diff?rents rem?des. J\\\'ai bien s?r accept?, mais il lui manque des ingr?dients, il ne peut se d?placer et je n\\\'arrive pas ? me r?soudre ? la laisser seule. Voudriez-vous m\\\'aider ?');
INSERT INTO `npc_questions` VALUES (1984, '', '', '', '', 'Mille merci ! L\\\'ingr?dient manquant est une fleur assez rare. Toute blanche, je crois qu\\\'on la trouve ? l\\\'Est d\\\'ici. Apportez cette fleur ? l\\\'alchimiste Nib? Lulle s\\\'il vous plait !');
INSERT INTO `npc_questions` VALUES (1985, '', '', '', '', 'Tr?s bien, voil? comment vous allez proc?der : Allez voir Touh Flowa, un ami Sadida. Il vous fournira une fleur de Dizbi. Mais pour l\\\'extrait, il vous faudra l\\\'aide de Nib? Lulle, un de mes anciens ?l?ves, d?sormais Alchimiste. Donnez moi votre carte, je vais vous indiquer les coordonn?es de Touh Flowa... Ta boussole guidera tes pas. \\nBonne route.');
INSERT INTO `npc_questions` VALUES (1986, '', '', '', '', 'Sans cet extrait nous ne pouvons avancer, faites un effort...');
INSERT INTO `npc_questions` VALUES (1987, '', '', '', '', 'Il vous manque quelque chose pour que je puisse vous parler d\\\'Eniripsa ? Eniripsa... Ah oui, je sais : ?tre un Eniripsa !');
INSERT INTO `npc_questions` VALUES (1988, '', '', '', '', 'Merci beaucoup. \\n*Yol se tourne vers Locette et lui fait boire la potion*');
INSERT INTO `npc_questions` VALUES (1989, '', '', '', '', 'Le rem?de n\\\'a pas fonctionn?, j\\\'esp?re que le m?decin aura une autre id');
INSERT INTO `npc_questions` VALUES (1990, '', '', '', '', 'Merci encore  \\n*Yol fait boire la potion ? Locette, celle-ci r?agit ? la puanteur et le piquant de la potion, ouvre les yeux et tousse fortement*');
INSERT INTO `npc_questions` VALUES (1991, '', '', '', '', 'Nos amis Enutrofs ont des soucis. Lors de leurs recherches ils ont d?couvert des choses... qui ont des r?percussions inqui?tantes. Vous trouverez un groupe de fouille dans les galeries sous la ville, mais n\\\'y allez pas seul, ce n\\\'est pas s?r. Tenez-moi au courant de vos avancements. Bonne chance !');
INSERT INTO `npc_questions` VALUES (1992, '', '', '', '', 'Cela l\\\'a sorti de son coma, mais ses sens sont toujours sens dessus dessous que faire ? \\nPouvez vous retourner voir Nepra ? Je vais tenter de la soutenir d\\\'ici l');
INSERT INTO `npc_questions` VALUES (1993, '', '', '', '', 'Merci et encore merci ! Locette va bien depuis, elle doit juste se reposer encore un peu pour retrouver l\\\'usage de ses sens');
INSERT INTO `npc_questions` VALUES (1994, '', '', '', '', '... \\n*Cette fille semble dormir profond?ment, Yol vous regarde d\\\'un oeil m?chant alors que vous l\\\'observez intens?ment*');
INSERT INTO `npc_questions` VALUES (1995, '', '', '', '', 'zzz \\n*Locette dort profond?ment, mais a l\\\'air plus vivante*');
INSERT INTO `npc_questions` VALUES (1996, '', '', '', '', 'Hey salut ! Ca groove ?! Tu veux un p\\\'tit peu de ma nouvelle invention ? Avec ?a, plus besoin de tes ailes pour wiiizzzz... Mais en fait, t\\\'es venu pour quelque chose non ?');
INSERT INTO `npc_questions` VALUES (1997, '', '', '', '', 'De la fleur de Dizbi ?! Yeah ! T\\\'as frapp? ? la bonne porte ! J\\\'ai ce qu\\\'il te faut ! Et comme je vous connais, vous autres Eniripsa, vous pr?f?rez les infusions. Nib? Lulle doit pouvoir te faire ?a. D\\\'ailleurs, si en passant tu peux m\\\'en rapporter un peu... ');
INSERT INTO `npc_questions` VALUES (1998, '', '', '', '', 'C\\\'est l\\\'heure de la sieste l?... *baille* ');
INSERT INTO `npc_questions` VALUES (1999, '', '', '', '', 'Du tout, je vous pr?pare ?a tout de suite !... hum ? Deux ? Il en faut aussi pour Touh le Sadida ? Tr?s bien, apr?s tout, ?a tombe bien, j\\\'en ai toujours en trop... Voil?, et bonne chance !');
INSERT INTO `npc_questions` VALUES (2000, '', '', '', '', 'Qu\\\'entendez-vous par l? ?! Bon ! Je vous pr?pare ?a tout de suite !... Tr?s bien, ?a va ?tre vite exp?di? !... Voil?, et bon vent ! *grmbl...*');
INSERT INTO `npc_questions` VALUES (2001, '', '', '', '', 'Je r?fl?chis ? de nouvelles m?thodes de travail, pour encourager mes employ?s ? se surpasser, mais ce n\\\'est pas suffisant, la demande est toujours trop cons?quente ! \\nSi tu souhaites te faire quelques kamas, j\\\'aurais besoin de main-d\\\'oeuvre prochainement pour livrer des Pizailles ? plusieurs clients dans la cit? !');
INSERT INTO `npc_questions` VALUES (2002, '178', '', '', '0', 'Hey toi ! P\\\'pa veut t\\\'parler... il est l?-bas, vers le sud, pr?s du lac... Attends, Je t\\\'indique ?a sur ta carte, tu n\\\'auras qu\\\'a suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2003, '', '', '', '', 'De l\\\'extrait de Dzibi ! Kwool ! Si t\\\'as besoin de quelque chose un jour, n\\\'h?site surtout pas. D\\\'ailleurs, tu serais p\\\'tet int?ress? par une assurance ? Non ? P\\\'tet plus tard alors. Allez, bonne sieste ! heuu... bonne chance je voulais dire !');
INSERT INTO `npc_questions` VALUES (2004, '', '', '', '', 'Si P\\\'pa n\\\'te vois pas pr?s de moi. Il va t\\\'gronder !');
INSERT INTO `npc_questions` VALUES (2005, '', '', '', '', 'Pour de l\\\'extrait de Dizbi, la premi?re chose ? savoir, c\\\'est qu\\\'il faut une fleur de Dzibi...');
INSERT INTO `npc_questions` VALUES (2006, '', '', '', '', 'Perdu ta fleur de Dizbi ?! Du pur g?chis !... tiens, en voil? une autre, et prends en soin, c\\\'est assez pr?cieux comme ?a !');
INSERT INTO `npc_questions` VALUES (2007, '', '', '', '', 'J\\\'ai appris que je devais te faire un arc, Alors tu m\\\'as ramen? l\\\'arc et la laine  ?');
INSERT INTO `npc_questions` VALUES (2008, '', '', '', '', 'A?e, mais arr?te... tu vises comme un pied. On va se faire gronder s\\\'il appartient ? quelqu\\\'un. Pauvre Bouftou, il a ?t? tu? sur le coup. J\\\'crois que personne t\\\'as vu. Bon, va vite donner l\\\'arc ? l\\\'alchimiste Nib? Lulle, il va am?liorer la corde. Enfin... Pas s?re que ?a vienne de l\\\'arc...');
INSERT INTO `npc_questions` VALUES (2009, '', '', '', '', 'Alors tu veux vraiment m\\\'entra?ner ? Bon, si tu insistes... Un petit combat ne me fera pas de mal... Enfin, je te dis tout de suite. Je ne suis pas aussi faible que p?re le pense... Aller pr?pare toi, ?a va chauffer...');
INSERT INTO `npc_questions` VALUES (2010, '', '', '', '', 'Aaaah ! Ram?ne moi mon Bouftou ! Ca remplacera celui que tu viens d\\\'abattre !');
INSERT INTO `npc_questions` VALUES (2011, '', '', '', '', 'Et les Iops sont au courant ? Quelle mis?re ! Manquerait plus que les Sacrieurs... faut vraiment tout faire ici ! Coffre fort, et maintenant gardes du corps... ');
INSERT INTO `npc_questions` VALUES (2012, '170', '', '', '0', 'Ahlala ! J\\\'enrage ! Ces fichus Ecaflips ont encore gagn? leur pari ! Mais je ne vais pas me laisser avoir une fois de plus par leur ind?cente chance au jeu. Et tu vas m\\\'aider, en ?change de quoi je t\\\'enseignerai de puissants sortil?ges !');
INSERT INTO `npc_questions` VALUES (2013, '', '', '', '', 'Je savais que ?a te plairait. Alors jetons un oeil dans l\\\'avenir, et pour cela... Comment ?! De la triche ?!... Sache mon jeune apprenti, que les Xelors ne trichent jamais ! Ils font juste souvent preuve d\\\'anticipation, une marque d\\\'intelligence ! Bon, je disais donc, il va me falloir quelques composants : deux fioles de cristal de p?le Anthir que tu obtiendras aupr?s de Nib? Lulle l\\\'Alchimiste, du grain d\\\'Epyss qu\\\'un des employ?s de l\\\'entrep?t de nourriture devrait pouvoir te fournir, et du bois de chez Oli Venders. Du bois de simple facture, pas de fioriture ! Le bois d?termine la port?e, et je ne d?sire obtenir qu\\\'une vision du futur proche.');
INSERT INTO `npc_questions` VALUES (2014, '', '', '', '', 'Pnj(473) et Message(2012)');
INSERT INTO `npc_questions` VALUES (2015, '', '', '', '', 'Des fioles cristal de p?le Anthir, hummm... tu d?sires voir l\\\'avenir ? Tu me sembles un peu inexp?riment? pour cela. Enfin, fais bien attention, nombre de gens ont perdu la vue en usant de ces cristaux. Tiens, voil? pour toi.');
INSERT INTO `npc_questions` VALUES (2016, '', '', '', '', 'J\\\'aimerais savoir ce que ces Xelors peuvent faire du grain d\\\'Epyss. Il a beau ?tre rare, il n\\\'y a qu\\\'eux pour en faire usage si souvent : le go?t est fade, on ne peut quasiment rien faire avec ?a ! Enfin, pour une plante qui peut pousser pratiquement au coeur des volcans, c\\\'est une chance qu\\\'elle n\\\'explose pas !');
INSERT INTO `npc_questions` VALUES (2017, '', '', '', '', 'Du bois classique, m?me pas sculpt?, pas de d?tails ? C\\\'est d?primant pour moi vous savez ! Allez, je vous mets discr?tement un bois de meilleure qualit?, sans fioritures, enfin, un p\\\'tit peu quand m?me, hein, il en va de mon honneur !');
INSERT INTO `npc_questions` VALUES (2018, '', '', '', '', 'Ah vous voil? ! Vous avez tout ? C\\\'est formidable, l\\\'heure de notre revanche a sonn? ! Allons, je vais assembler tout ceci... *elle regarde le morceau de bois, semble intrigu?e, puis poursuit la construction de l\\\'objet*...');
INSERT INTO `npc_questions` VALUES (2019, '', '', '', '', 'Voil? ! Le SABLIER DE XELOR est pr?t ! C\\\'est mon support pr?f?r? pour la divination... Tr?s bien, jetons-y un oeil... - Montrakwartz se concentre sur l\\\'?coulement de l\\\'Epyss, puis quelque chose la foudroie, elle laisse tomber le sablier qui se brise ? Enfer ! Qu\\\'est-ce que c\\\'est que cette vision ?! Laissez-moi reprendre mes esprits... mis?ricorde, nous avons un probl?me !');
INSERT INTO `npc_questions` VALUES (2020, '', '', '', '', 'Vous... Vous faisiez partie de ma vision ! Vous rejoindrez d\\\'autres aventuriers et participerez aux fouilles Enutrof dans les galeries sous la ville ! C\\\'est tr?s important ! Tenez, prenez ce marteau, il vous sera tr?s utile, mais l\\\'intelligence et la sagesse seront vos meilleures alli?es... Ce bois est d?cid?ment ?trange...');
INSERT INTO `npc_questions` VALUES (2021, '', '', '', '', 'Humm...La d?esse des Sacrieurs me susurre ? l\\\'oreille que tu es digne d\\\'?tre parmi nous, mais je pr?f?re le v?rifier de mes propre mains... Dans la vie d\\\'un Sacrieur, il y a 3 choses importantes. La premi?re, c\\\'est de toujours se faire frapper en premier en combat. La deuxi?me : savoir encaisser un maximum. La derni?re, je l\\\'ai oubli?e... ');
INSERT INTO `npc_questions` VALUES (2022, '', '', '', '', 'Arr?te de me regarder comme ?a !...Vas-y frappe MOI !  .. Frappe moi fort, ALLEZ !');
INSERT INTO `npc_questions` VALUES (2023, '', '', '', '', 'Vous pr?voyez dans un futur proche de vous mettre ? la divination ?! J\\\'en doute... Je le saurais d?j? !');
INSERT INTO `npc_questions` VALUES (2024, '', '', '', '', 'BAamm... Oui c\\\'est ?a !  Observe ma force monter en puissance. N\\\'oublie pas : en combat, lance tes sorts de ch?timent avant de prendre des coups, et comme moi tu sentiras ta force bouillir !');
INSERT INTO `npc_questions` VALUES (2025, '', '', '', '', 'Visez moi cette hampe de bois sculpt?e ! C\\\'est pas de l\\\'ouvrage ?a ?!');
INSERT INTO `npc_questions` VALUES (2026, '', '', '', '', 'Bim... Tzzz arr?te de me caresser. Je n\\\'ai pas besoin de tendresse. Reviens me voir quand tu pourras blesser un Tofu...');
INSERT INTO `npc_questions` VALUES (2027, '', '', '', '', 'HaHa...Tu es path?tique...On ne peut vraiment rien tirer de toi. Reviens quand tu seras digne d\\\'?tre ce que tu es...');
INSERT INTO `npc_questions` VALUES (2028, '171', '', '', '0', 'Gaaarrrde ? vous ! On n\\\'est pas l? pour plaisanter ! Ici, on marche au pas et on ne discute pas ! Allez, plus s?rieusement... La gloire ne poussant pas sur les arbres, nos amis Enutrofs se sont mis en quatre pour nous l\\\'apporter sur un plateau.');
INSERT INTO `npc_questions` VALUES (2029, '1718;171', '', '', '0', 'N\\\'est-ce pas ? Mais avant de penser ? la gloire, il vous faut une arme, une bonne ?p?e. J\\\'ai un tr?s bon ami forgeron nomm? Deudoin?. Il vous aidera ? en fabriquer une et je pourrai y apposer la marque de notre maison. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole. Bon courage ! ');
INSERT INTO `npc_questions` VALUES (2030, '1952', '', '', '0', 'Je suis un peu ? court de philtres ces temps-ci, beaucoup de gens m\\\'en demandent... ahem ! Enfin, que puis-je faire pour vous ?');
INSERT INTO `npc_questions` VALUES (2031, '', '', '', '', 'Vous ?tes plut?t rapide, c\\\'est une bonne chose. Mais ce qui compte c\\\'est la force que vous mettrez dans vos attaques, et le courage d\\\'aller au bout de vos convictions. Et, par dessus tout, rester juste... Ce sont les ma?tres mots de notre maison, ne l\\\'oubliez pas. Maintenant, donnez moi votre ?p?e, pour que j\\\'y appose la marque qui scellera votre destin... *Rok utilise divers outils mais n\\\'a pas l\\\'air tr?s habile de ses dix doigts si ce n\\\'est avec une ep?e*... Voil?, c\\\'est termin? !');
INSERT INTO `npc_questions` VALUES (2032, '', '', '', '', 'Voici les faits : les Enutrofs ont requis notre aide. Depuis quelques temps, des ?v?nements ?tranges se produisent lors de leurs fouilles. Ils pr?sentent un danger, et qui dit danger dit Iop ! Vous ?tes maintenant par? ? leur pr?ter main forte. Rejoignez l\\\'?quipe de fouilles dans les galeries ! Et restez sur vos gardes...');
INSERT INTO `npc_questions` VALUES (2033, '', '', '', '', 'Tu vas peut-?tre pouvoir m\\\'aider... Quelque chose ne coule pas rond dans cette ville, mais si tu gardes ton sang froid, tout ira bien. Je sais qu\\\'il se passe de dr?les de choses, dans les souterrains...');
INSERT INTO `npc_questions` VALUES (2034, '', '', '', '', 'Te voil? de retour ! Tr?s bien, montre moi ?? ! Parfait... allons-y pour l\\\'assemblage final !... Et voil? ! Une superbe ?p?e, assez simple finalement, mais ce n\\\'est pas l\\\'?p?e qui fait le guerrier apr?s tout ! Bonne chance, et fa?tes bien attention ? vos doigts ! ? Deudoin? semble songeur sur ces derniers mots.');
INSERT INTO `npc_questions` VALUES (2035, '', '', '', '', 'On dit qu\\\'un Enutrof du chantier a ?t? chang? en mineur sombre dans les souterrains! Le malheureux a gard? ses bonnes vieilles habitudes : il teste r?guli?rement l\\\'eau de vie du tavernier. Il faut que tu ram?nes une goutte de son sang ? Nib? lulle, l\\\'alchimiste. Il saura en tirer quelque chose. Mais avant tout, va parler ? Nib? Lulle. Il te donnera une seringue. Tu t\\\'en serviras apr?s avoir affaibli le mineur sombre. Je t\\\'ai indiqu? o? trouver Nib? Lulle. Tu n\\\'as qu\\\'? suivre ta boussole. Tiens moi au courant...');
INSERT INTO `npc_questions` VALUES (2036, '', '', '', '', 'Je vous attendais ! Vous savez, la poign?e d\\\'une ?p?e est primordiale ! Nombre de guerriers ont p?ri ? cause d\\\'une poign?e mal fa?onn?e. Ici, vous aurez les meilleures ! C\\\'est une tradition familiale, depuis plus de cent cinquante ans. Et je vous pr?conise celle-ci, puissante, raffin?e, faite de bois d\\\'Abraknyde incrust?e d\\\'une plume de Dragodinde ! Essayez l?, vous verrez !... ');
INSERT INTO `npc_questions` VALUES (2037, '', '', '', '', 'Ah ! Encore un initi? Iop je suppose ! En effet, je peux t\\\'expliquer comment fabriquer cette arme, mais il nous faudrait de quoi fabriquer la poign?e. Va donc demander ?a ?  Oli Venders, il doit en avoir une paire en stock, h?h? ! Je commence ? battre le fer, ne tra?ne pas. ');
INSERT INTO `npc_questions` VALUES (2038, '', '', '', '', 'Impressionnant, tr?s impressionnant, le vieil Enutrof a fait preuve d\\\'ing?niosit? pour garder ses secrets... \\nDites-moi, vous avez eu un sacr? coup de veine pour trouver la combinaison, si vous voulez on peut faire ?quipe, pour combiner votre chance ? mon intelligence ! \\nLa seconde grotte dont ce livre fait mention se trouve ? deux pas au sud du zaap d\\\'Amakna, essayez de jeter un oeil ? l\\\'int?rieur !');
INSERT INTO `npc_questions` VALUES (2039, '', '', '', '', 'Te voil? de retour ! Tr?s bien, montre-moi ?a ! Parfait... Allons-y pour l\\\'assemblage final ! ... Et voil? ! Une superbe ?p?e, assez simple finalement, mais ce n\\\'est pas l\\\'?p?e qui fait le guerrier apr?s tout ! Retourne voir ton ma?tre de classe, il t\\\'en apprendra le maniement. \\nBonne chance, et faites bien attention ? vos doigts ! *songeur*');
INSERT INTO `npc_questions` VALUES (2040, '', '', '', '', 'Inutile de revenir me voir sans ?p?e, jeune Iop !');
INSERT INTO `npc_questions` VALUES (2041, '', '', '', '', 'Salut ? toi ! Je me pr?sente, je suis Nib? Lulle, l\\\'achimiste de cette bonne vieille cit?. Que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (2042, '', '', '', '', 'Oui, c\\\'est vrai j\\\'allais oublier. Tiens, voila une seringue pour bouftou. Bon, elle n\\\'est pas tr?s fine mais dans ton cas, elle fera l\\\'affaire, n\\\'est ce pas ? Reviens me voir avec le sang. Je saurai le faire parler. Heu, c\\\'est une fa?on de parler bien s?r ! Apr?s quelques analyses, je comprendrai de quel mal ce pauvre Enutrof a ?t? frapp? !');
INSERT INTO `npc_questions` VALUES (2043, '', '', '', '', 'Sans poign?e, pas d\\\'?p?e. Va voir Oli Venders le B?cheron.');
INSERT INTO `npc_questions` VALUES (2044, '', '', '', '', 'Je pense qu\\\'il est temps pour moi de te faire confiance. Cet alchimiste ne vaut m?me pas 2 kamas. Il n\\\'a rien trouv?...Pffff... Bon sang ! Qu\\\'est-ce qui se passe dans les souterrains ? On a jet? un sort ? ce pauvre Enutrof ? Il a mang? quelque chose de pas rago?tant ?');
INSERT INTO `npc_questions` VALUES (2045, '', '', '', '', 'Ne me regarde pas comme ?a ! D?brouille-toi pour en savoir plus ! Tu n\\\'as qu\\\'? aller voir Joe Pierlivet le Maitre de Guilde Enutrof et lui proposer tes services... 3 ou 5 coups de pelle bien encaiss?s et tu seras en pleine forme...  Wouah ! Infiltrer, espionner... Tu vas mener une vie de Sram !  Reviens vite me voir.');
INSERT INTO `npc_questions` VALUES (2046, '', '', '', '', 'Je parie 10 kamas que tu viens chercher l\\\'aventure ! Entre Ecaflips, on se comprend, pas vrai ? Figure toi que je viens de d?lester Montrakwartz, la pr?tresse X?lor, de 1000 kamas ! ');
INSERT INTO `npc_questions` VALUES (2047, '', '', '', '', 'H? bien, elle a pari? que les Enutrofs n\\\'?taient pas assez courageux pour se risquer dans les souterrains \\\" avec les cr?atures qui r?dent alentours, et patati, et patata \\\". \\\" Bien au contraire \\\", que je lui ai dit : \\\" ils vont s\\\'y ruer pour chercher fortune ! \\\".');
INSERT INTO `npc_questions` VALUES (2048, '', '', '', '', 'H? oui ! Bien malin qui gagne un pari contre une X?lor, n\\\'est-ce pas ? On dit qu\\\'ils lisent l\\\'avenir, mais je crois savoir qu\\\'elle est amoureuse, ce qui occupe toutes ses pens?es, alors l\\\'avenir, tu parles...');
INSERT INTO `npc_questions` VALUES (2049, '', '', '', '', 'Mais je vois que tu n\\\'as pas d\\\'arme... Tiens, en tant qu\\\'a?n? Ecaflip, je t\\\'offre cette bourse, tu pourras t\\\'en procurer une... En m?me temps, je me demande si Montrakwartz ne m\\\'a pas jou? un tour. Il se pourrait bien que ce m?tal ne disparaisse bient?t si personne ne s\\\'en occupe !');
INSERT INTO `npc_questions` VALUES (2050, '', '', '', '', 'Ca y est, tu as le sang du mineur sombre ? Bon je vais l\\\'analyser. J\\\'enverrai les r?sultats de mes recherches ? ton ma?tre.');
INSERT INTO `npc_questions` VALUES (2051, '', '', '', '', 'D?p?che toi d\\\'aller chez le forgeron. Il fondra ces kamas pour t\\\'en faire une lame digne de ton bras.');
INSERT INTO `npc_questions` VALUES (2052, '', '', '', '', 'Rend toi chez Nibe Lulle, l\\\'alchimiste. Une fois le m?tal transmut?, la magie X?lor sera annul?e !');
INSERT INTO `npc_questions` VALUES (2053, '', '', '', '', 'Voici ! En deux coups de soufflet, ta lame est forg?e. Va voir l\\\'alchimiste de ma part, et demande-lui de la tremper dans sa fameuse eau de lune, elle n\\\'en sera que plus solide...');
INSERT INTO `npc_questions` VALUES (2054, '', '', '', '', 'C\\\'est... Erty... env..oie ? Content... voir...... d?vorer par... une plant....... le bougre... \\n \\n* Trois-Fleurs sort un papier de sa poche, o? il est ?crit \\\" D?sol?, je suis aphone depuis hier matin ! \\\" * \\n \\nJ\\\'ai... nouvelles... int?ressante... une rose obsc..ure... champs... des Ingalsses..., rapporte une... fleur de cette... rose ? Erty... ! \\n \\nIl pa...ra?t...que d\\\'?tran...ges... motifs ont ?t?... taill?s... dans.... le bl?... Tu les recon...na?tras ?... ce d?tail...');
INSERT INTO `npc_questions` VALUES (2055, '', '', '', '', 'Etrange ce m?tal... N\\\'y aurait-il pas de la magie X?lor l?-dessous ? Qui sait ! Je l\\\'ai transmut?, c\\\'est maintenant un m?tal noble et pur. Va voir le forgeron de ma part. Il forgera ta lame, elle sera l?g?re et fera vibrer l\\\'air !');
INSERT INTO `npc_questions` VALUES (2056, '', '', '', '', 'Tu viens de la part de mon vieil ami Deudoin? ? Il aimerait conna?tre mes secrets, tu sais ? Mon eau de lune est connue jusqu\\\'? Bonta, haha ! Aussit?t dit, aussit?t fait : reprends ton ?p?e jeune Ecaflip ! L\\\'?l?ment feu vit d?sormais dans ta lame !');
INSERT INTO `npc_questions` VALUES (2057, '', '', '', '', 'Sacr?s Enutrofs ! Ils ont encore creus? n\\\'importe o? et r?veill? une bestiole mal?fique... Haaa ! Si une telle cr?ature vivait sous cette cit?, on l\\\'aurait su depuis longtemps, encore que... Qu\\\'est-ce qu\\\'ils nous cachent encore ? Retourne dans les souterrains, on va bien finir par savoir ce qu\\\'il se trame l?-dessous. ');
INSERT INTO `npc_questions` VALUES (2058, '', '', '', '', 'Une ?p?e ? Tu viens de la part de Nibe Lulle n\\\'est-ce pas ? Ce bonhomme en conna?t un bout sur le m?tal et la vie en g?n?ral... Voil?, ta lame est  forg?e et aff?t?e, elle est maintenant l?g?re et redoutable.');
INSERT INTO `npc_questions` VALUES (2059, '', '', '', '', 'Quesce tu veux ? ');
INSERT INTO `npc_questions` VALUES (2060, '', '', '', '', 'Comment ?a : \\\" Je n\\\'ai pas d\\\'?p?e ? \\\". Reviens me voir lorsque tu en auras trouv? une !');
INSERT INTO `npc_questions` VALUES (2061, '', '', '', '', 'Tiens te revoil? ! Montre moi ton ?p?e... Nom d\\\'un carr? d\\\'as, c\\\'est du bel ouvrage ! Je te fais l\\\'honneur d\\\'y apposer la marque des Ecaflips : tu es des n?tres d?sormais ! Mais tout cela ne me dit pas ce que fabriquent ces Enutrofs. J\\\'en mettrais ma patte au feu, il y a de l\\\'or l?-dessous ! Et si tu allais ?trenner ta lame du c?t? des souterrains ? Prend garde toutefois : ne joue pas ta vie sur un coup de t?te ! ');
INSERT INTO `npc_questions` VALUES (2062, '', '', '', '', 'Tu nous proposes tes services ? Ha, ha, je vous aime bien, vous les Sacrieurs, toujours pr?ts ? passer en premier dans les souterrains, hein ? Ouais t\\\'es le bienv\\\'nu.... Mais gare ? tes basques, l\\\'un des n?tres est port? disparu depuis quelques jours. Il doit y avoir quelque chose de pas tr?s net l?-dessous. On nous a m?me oblig? d\\\'arr?ter d\\\'creuser, Yep, j\\\'en ai d?j? trop dit. J\\\'t\\\'appellerai quand j\\\'aurai b\\\'soin toi !');
INSERT INTO `npc_questions` VALUES (2063, '', '', '', '', 'Salut ! J\\\'ai envoy? ma gamine te chercher. Tu sais elle est bourr?e d\\\'?nergie, si vigoureuse.. Comme son p?re \\n! Ahaha !  Je dois repr?senter les Cr?s au conseil d\\\'Astrub. Et j\\\'aurais besoin de tes services.');
INSERT INTO `npc_questions` VALUES (2064, '1841', '', '', '0', 'Salut l\\\'ami !  T\\\'es venu ?couter les fleurs pousser ? A moins que ce ne soit pour autre chose n\\\'est-ce pas ? J\\\'en ?tais s?r ! Mais tu devrais quand m?me t\\\'arr?ter pour ?couter la nature, t\\\'es trop stress? ! La nature parle au ralenti, mais c\\\'est un puits de connaissances mill?naires !');
INSERT INTO `npc_questions` VALUES (2065, '', '', '', '', 'Comme je te le dit ! Elle m\\\'avait pr?dit ta venue d\\\'ailleurs. Enfin, comme tout bon initi?, tu devrais cr?er ton premier lien avec elle. Pour se faire, la nature accepte de sacrifier un peu de ses biens, mais en contrepartie tu devras la prot?ger. Va voir le b?cheron : il a s?rement ce qu\\\'il te faut, une branche de bois d\\\'Arash, et reviens me voir apr?s cela.');
INSERT INTO `npc_questions` VALUES (2066, '', '', '', '', 'Tu comprends, je ne peux pas laisser ma petite toute seule pendant ce temps. Et elle ne peut pas venir avec moi non plus, tu comprends...c\\\'est impossible. Elle courrait partout et d?rangerait tout le monde, moi le premier ! J\\\'ai une faveur ? te demander, peux tu la garder quelques minutes. Ca ne sera pas long...');
INSERT INTO `npc_questions` VALUES (2067, '', '', '', '', 'Le bois d\\\'Arash est tr?s rare, en effet, mais n\\\'importe quel autre bois aurait fait l\\\'affaire... Enfin, mon acolyte est pr?t ? s\\\'occuper de cela. Pour l\\\'heure, je suis ?puis?, ?a fait plus d\\\'une heure que j\\\'?coute la nature... *baille* ');
INSERT INTO `npc_questions` VALUES (2068, '', '', '', '', 'Merci ? toi. Ah, j\\\'ai oubli? de te dire. Si elle se met ? courir, ne la l?che pas d\\\'une semelle. Je veux que tu sois toujours coll? ? elle. Comme ?a je suis s?r qu\\\'elle ne fera pas de b?tises. Bon je pense que tout se passera bien... je te la confie. A tout de suite.');
INSERT INTO `npc_questions` VALUES (2069, '', '', '', '', 'Hey, il me faut une pelle en boisaille, oh oui une pelle... je suis sauv? ! Creuser... toujours plus... \\n... Sous-terre, c\\\'est la protection...');
INSERT INTO `npc_questions` VALUES (2070, '', '', '', '', 'Yeah ! T\\\'es l?  pour le b?ton ? Evidemment que t\\\'es l? pour ?a... bon, je vais te confectionner ce b?ton avec le bois d\\\'Arash que tu m\\\'as ramen? ! Ahem ! Alors, je crois que c\\\'est comme ?a qu\\\'il faut faire... un peu ? droite, un coup ? gauche... *doute*... et un peu au milieu aussi... je cr..., enfin non ! Je suis s?r ! Voil?, et c\\\'est... ah oui ! L\\\'incantation !... ahouummm redi fo ki koa s? pa sh? !... voil? !');
INSERT INTO `npc_questions` VALUES (2071, '', '', '', '', 'Ben mate moi ?a, un pur lien avec la nature, comme dirait ma?tre Sadadi. Et je crois que ?a va ?tre super utile: la nature a senti quelque chose de n?faste dans les galeries, et des Enutrofs sont en danger ! Si t\\\'as le temps avant ta sieste, tu peux aller voir s\\\'qui s\\\'trame. Moi, je dois seconder le ma?tre dans sa lourde t?che... ');
INSERT INTO `npc_questions` VALUES (2072, '', '', '', '0', 'Du bois d\\\'Arash... c\\\'est devenu une denr?e rare par ici l\\\'ami, tellement rare que les seuls qui pourraient encore en poss?der sont les Enutrofs. Mais rien n\\\'est s?r ! Je peux te faire quelque chose qui s\\\'en rapproche hein, j\\\'ai des bois tr?s similaires !');
INSERT INTO `npc_questions` VALUES (2073, '', '', '', '', 'Non ? Vraiment ? Tant pis, tu ne sais pas ce que tu rates !');
INSERT INTO `npc_questions` VALUES (2074, '185', '', '', '0', 'Ouch ! Du bois d\\\'Arash, rien qu\\\'?a !? Tu sais d\\\'ouk ?a pousse au moins ? Ben moi non plus, c\\\'est des marchands qui passent parfois dans l\\\'coin qui nous en rapportent. D\\\'apr?s eux, c\\\'est rare, t\\\'as pas id?e ! Enorme, hein ?');
INSERT INTO `npc_questions` VALUES (2075, '', '', '', '', 'Je m\\\'en doutais... Tu restes un peu sur ta faim non ? Bon alors je vais faire un effort pour te remercier. Je vais t\\\'enseigner l\\\'art des Cr?s ! Hein ? Comment ?a ? Je n\\\'ai pas l\\\'air d\\\'un guerrier ? De toute fa?on, c\\\'est pas la mode. La vraie classe c\\\'est d\\\'avoir la panoplie du bouftou, un vrai attrape minettes.... H?H?... Excuse moi, je m\\\'?gare...');
INSERT INTO `npc_questions` VALUES (2076, '', '', '', '', 'Je vais t\\\'apprendre ? tirer... ? l\\\'arc ! Belle r?compense non ? Mais avant tout, il te faut un arc ! Mon temps est pr?cieux, mais Ticra t\\\'aidera. Tu verras, elle est presque aussi habile que moi... j\\\'ai dit presque...');
INSERT INTO `npc_questions` VALUES (2077, '', '', '', '', 'Ah ! J\\\'te saoule, j\\\'vois bien ! Tiens il doit m\\\'en rester un petit bout de bois d\\\'Arash, mais fais y gaffe, c\\\'est rare !');
INSERT INTO `npc_questions` VALUES (2078, '', '', '', '', 'Il faut donc que tu ailles demander du bois ? notre c?l?bre b?cheron Oli Venders, puis que tu montres ton bout de bois ? la tailleuse d\\\'arc. Va ensuite chercher de la laine bouftou, Allisteria la berg?re t\\\'en donnera volontiers. Elle a un faible pour moi... Tu n\\\'as plus qu\\\'? apporter le tout ? ma fille, elle te fera un arc tout ? fait convenable pour d?buter.');
INSERT INTO `npc_questions` VALUES (2079, '', '', '', '', 'Alors ?a ! Nous aidons les Enutrofs dans leur recherches et tout ce que nous r?coltons, ce sont des animaux malades. Et quelles maladies ! Genre qu\\\'on ne puisse soigner nous-m?me ! Heureusement, qu\\\'il y a les Eniripsas...');
INSERT INTO `npc_questions` VALUES (2080, '', '', '', '', 'D?sol? mais je suis un Cr? tr?s occup?. Je n\\\'ai pas le temps de faire connaissance.');
INSERT INTO `npc_questions` VALUES (2081, '', '', '', '', 'C\\\'est simple, Nepra Lido a mis au point un rem?de. J\\\'ai besoin de quelqu\\\'un pour aller le chercher rapidement... une talentueuse soigneuse cette Nepra... Ahem ! Je peux compter sur toi ?');
INSERT INTO `npc_questions` VALUES (2082, '', '', '', '', 'Trouve Nepra. Tu lui demanderas du Suborhube, et tu le porteras ? Clint Pot, un Enutrof qui s\\\'occupe des cr?atures que nous leur confions. Ne t\\\'occupes pas de l\\\'apparence du rem?de, c\\\'est tr?s efficace. ');
INSERT INTO `npc_questions` VALUES (2083, '176', '', '', '0', 'Salut ! T\\\'veux bien jouer avec moi ? Tu fais la cible et moi l\\\'chasseur ? *Elle prend une fl?che et pointe son arc vers vous*');
INSERT INTO `npc_questions` VALUES (2084, '', '', '', '', 'N?pra n\\\'est pas l?... Vous cherchez du Suborhube ? Mais bien s?r ! Il serait tout de m?me plus courtois de la part des Enutrofs de venir le chercher eux-m?mes. Enfin, je n\\\'ai pas encore trouv? de rem?de contre ce fl?au obsessionnel qui les pousse toujours ? creuser partout o? il ne faudrait pas...');
INSERT INTO `npc_questions` VALUES (2085, '', '', '', '', 'Ahlala ! Quelle r?leuse c\\\'te Nepra ! Elle est comme ?a, mais en fait, elle a un bon fond... Ahahah ! Merci, j\\\'te r\\\'vaudrai ?a !');
INSERT INTO `npc_questions` VALUES (2086, '', '', '', '', 'Ah ?a oui ! Je dois r\\\'conna?tre que c\\\'est pas la voie d\\\'administration qui m\\\'r?jouit ! Les Tofus non plus d\\\'ailleurs... Tu n\\\'veux pas t\\\'en occuper toi-m?me ? Non... ?videment ! Allez, bonne journ?e quand m?me ! ');
INSERT INTO `npc_questions` VALUES (2087, '', '', '', '', 'Ah ces Enutrofs ! Tu sais que nous les aidons dans leurs recherches ? H? bien nous voil? emb?t?s : ? force de tra?ner dans les souterrains, ils tombent malades, les Enutrofs. Et ? qui ils refilent leurs germes ?! A nos Tofus pardi ! Et le rhume d\\\'Enutrof, je ne sais pas comment ?a se soigne, moi... Mes pauvres Tofus... Heureusement qu\\\'il y a les Eniripsas...');
INSERT INTO `npc_questions` VALUES (2088, '', '', '', '', 'Nepra Lido a mis au point un rem?de... Une talentueuse soigneuse cette Nepra, particuli?rement dou?e pour les massages... Ahum ! Trouve-la et demande-lui du Suborhube. Porte-le ensuite ? Clint Pot - c\\\'est un Enutrof - il s\\\'occupera de nos Tofus. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2089, '', '', '', '', 'C\\\'est bien la premi?re fois que les Enutrofs ont besoin de ce rem?de... J\\\'ai comme un doute sur ce qui se passe l?-dessous. Voudrais-tu aller enqu?ter, et me rapporter tout ce qui te para?t ?trange ? Tiens, prends ce marteau, il te sera tr?s utile.  \\nJe t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2090, '', '', '', '', 'Bonjour jeune Feca. Je me nomme Fallanster. Ma fille Allisteria m\\\'a expliqu? tout ce que vous aviez fait. Elle n\\\'a pas eu le temps de venir vous apporter du boudin bouilli de Bouftou, tout avait d?j? ?t? mang? !');
INSERT INTO `npc_questions` VALUES (2091, '', '', '', '', 'J\\\'aimerais lui enseigner l\\\'art de la magie. Mais, vous comprenez je n\\\'en ai pas vraiment le temps. Vous feriez un tr?s bon professeur. Apprenez lui tous vos sorts, cela lui fera d?j? un tr?s bon entra?nement. N\\\'est ce pas Allisteria ? *Elle ne r?pond pas*');
INSERT INTO `npc_questions` VALUES (2092, '', '', '', '', 'Tr?s bien,  je vous retrouverai ici.');
INSERT INTO `npc_questions` VALUES (2093, '', '', '', '', 'Je vous assure que cette mission est tr?s importante !');
INSERT INTO `npc_questions` VALUES (2094, '', '', '', '', 'Pnj(498) et Message(2093)');
INSERT INTO `npc_questions` VALUES (2095, '', '', '', '', 'Bien bien... Sacr?e petite on voit vraiment de qui elle tient. J\\\'ai une derni?re faveur ? vous demander. Avec tout ce remue-m?nage, quelques-uns de nos bouftous se sont ?chapp?s, certains se sont ?gar?s du c?t? des souterrains.');
INSERT INTO `npc_questions` VALUES (2096, '', '', '', '', 'Contrairement ? nous Feca, l\\\'intelligence n\\\'est pas le point fort de ces sacr?es bestioles. Il nous manque un Bouftou. Pourriez-vous aller ? sa recherche ? Je crois qu\\\'il est du c?t? des souterrains.');
INSERT INTO `npc_questions` VALUES (2097, '', '', '', '', 'Merci, je savais que je pouvais compter sur vous.');
INSERT INTO `npc_questions` VALUES (2098, '', '', '', '', 'Je crois que vous n\\\'avez pas bien compris. Enfin si c\\\'est votre dernier mot. C\\\'est que je me suis tromp? sur vous.');
INSERT INTO `npc_questions` VALUES (2099, '', '', '', '', 'Oula...toi tu commences mal ! *elle se met ? crier* Papa, Papa ! ');
INSERT INTO `npc_questions` VALUES (2100, '', '', '', '', 'Ha, ha, je savais qu\\\'une personne aussi fut?e que toi saisirait une telle occasion ! \\nAlors c\\\'est simple, tu as exactement 10 minutes pour livrer Erty Trapchet qui se trouve au parc au centre de la cit?, si tu ?choues, tu payeras la pizaille de ta poche !');
INSERT INTO `npc_questions` VALUES (2101, '', '', '', '', 'Vas-y tu peux partir, je n\\\'aurai pas de mal ? trouver d\\\'autres jeunes bien plus fut?s que toi.');
INSERT INTO `npc_questions` VALUES (2102, '', '', '', '', 'Je comprends. Dans ce cas d?sol?. Si tu changes d\\\'avis, tu sais o? me trouver.');
INSERT INTO `npc_questions` VALUES (2103, '', '', '', '', 'Pnj(457) et Message(1849)');
INSERT INTO `npc_questions` VALUES (2104, '', '', '', '', 'A voir la dext?rit? de ta main, tu ne sais pas jouer au Goh ! Inutile donc de me faire perdre mon temps sinon je ne le trouverai jamais !');
INSERT INTO `npc_questions` VALUES (2105, '', '', '', '', 'Le \\\"Coup-Devin\\\" bien s?r ! Celui gr?ce auquel je deviendrai riche et c?l?bre ! Si tu veux en savoir davantage, assieds toi, prend une bi?re et ?coute-moi l\\\'ami, c\\\'est une histoire fantastique ! ');
INSERT INTO `npc_questions` VALUES (2106, '', '', '', '', 'Un soir alors que j\\\'?tais au cimeti?re d\\\'Amakna pour... hmm, la raison pour laquelle je m\\\'y ?tais rendu est sans importance... Bref, alors que je traversais le cimeti?re, j\\\'ai entendu des voix qui semblaient venir de la tombe de mon grand-p?re, elles disaient \\\"Yke Harou... le grenier... mon Gohbal... tu trouveras le Coup-Devin !\\\". \\nBien qu\\\'initi? au jeu de Goh, je n\\\'avais pas connaissance de ce coup l?gendaire ? cette ?poque, j\\\'ai donc entrepris quelques recherches et j\\\'ai d?couvert la l?gende \\\"Celui qui trouvera le Coup-Devin au Goh sera capable de pr?dire le temps et l\\\'espace \\\". \\nJe sais que tu vas penser que je suis rest? trop longtemps ? la table de cette taverne, mais la suite est encore plus palpitante...');
INSERT INTO `npc_questions` VALUES (2107, '', '', '', '', 'Je suis donc all? le lendemain dans l\\\'ancienne maison de mon grand-p?re, j\\\'ai visit? son grenier et tout ce que j\\\'y ai trouv?, c\\\'est un jeu de Goh au centre de la pi?ce. En touchant le plateau du jeu, j\\\'ai vu jaillir une flamme, c\\\'est la seule chose dont je me souviens, car je me suis ?vanoui, et lorsque je me suis r?veill? treize jours plus tard en pleine rue, la maison de mon grand-p?re avait ?t? vendue par mes parents. \\nDepuis, les nouveaux propri?taires refusent de me laisser y rentrer de nouveau, donc je tra?ne ? la taverne ? la recherche d\\\'adversaires, dans l\\\'espoir de trouver ce fameux coup... ');
INSERT INTO `npc_questions` VALUES (2108, '', '', '', '', 'Saketsu m\\\'a pr?venu de ta venue. Grand merci ! Je saurai faire parler cette goutte de sang. Heu, c\\\'est une fa?on de parler bien s?r ! Apr?s quelques analyses, je comprendrai de quel mal il a ?t? frapp? !');
INSERT INTO `npc_questions` VALUES (2109, '', '', '', '', 'Je vais bient?t faire passer l\\\'?preuve d\\\'initiation ? mes apprentis, et il me faut un stock massif de bave de bouftous. Pourriez vous m\\\'en apporter une dizaine ?');
INSERT INTO `npc_questions` VALUES (2110, '', '', '', '', 'Grand merci, tu nous rends un fier service !');
INSERT INTO `npc_questions` VALUES (2111, '', '', '', '', 'Ah d?sol? ! Trop occup? pour m\\\'occuper de toi maintenant !');
INSERT INTO `npc_questions` VALUES (2112, '', '', '', '', 'Tu parles pas Iop toi ? C\\\'est dommage...');
INSERT INTO `npc_questions` VALUES (2113, '', '', '', '', 'Salut ! Reviens me voir lorsque tu seras plus vert !');
INSERT INTO `npc_questions` VALUES (2114, '', '', '', '', 'Tu n\\\'es pas Ecaflip, toi, hein ?');
INSERT INTO `npc_questions` VALUES (2115, '1973;1832', '', '', '0', 'D?sol? mais j\\\'ai pas le temps de bavarder avec toi. J\\\'ai plein de bestioles ? ?gorger... Tu veux que je te montre ? ');
INSERT INTO `npc_questions` VALUES (2116, '', '', '', '', 'Alors, ca y est ? Tu crois que tu peux me toucher maintenant ? Alors vas-y FRAPPE MOI !');
INSERT INTO `npc_questions` VALUES (2117, '2138', '', '', '', 'Alors cette livraison ? Ca avance ?');
INSERT INTO `npc_questions` VALUES (2118, '', '', '', '', 'Merci pour cette petite fiche, j\\\'esp?re que se sera un grand livreur');
INSERT INTO `npc_questions` VALUES (2119, '', '', '', '', 'Merci beaucoup, revenez me voir bient?t si cela vous dit. Vous ?tes un bon travailleur !');
INSERT INTO `npc_questions` VALUES (2120, '', '', '', '', 'Vous n\\\'auriez pas vu Jim Fleps par hasard ?');
INSERT INTO `npc_questions` VALUES (2121, '', '', '', '', 'Un complot ! La ville est menac?e... population en danger... Hey ! Les roublards... fuyez !');
INSERT INTO `npc_questions` VALUES (2122, '', '', '', '', 'La pelle... inefficace... le sol... trop dur... pas creuser... il me faut des planches ! Deux planches de Ch?taigner... ! \\nNourriture ! Survivre, il me faut du pain... trois pains d\\\'Amakna !');
INSERT INTO `npc_questions` VALUES (2123, '', '', '', '', 'Viens l? que je te valide tes quetes');
INSERT INTO `npc_questions` VALUES (2124, '', '', '', '', 'Je suis Louc, sisis');
INSERT INTO `npc_questions` VALUES (2125, '', '', '', '', 'Il faudrait aller livrer ce g?teau ? grand-m?re, ne trainez pas en route, et fa?tes attention, des rats semblent r?der autour de sa maison. Il ne faut pas qu\\\'ils mangent le g?teau.');
INSERT INTO `npc_questions` VALUES (2126, '', '', '', '', 'Merci mon gars, tu seras toujours le bienvenu ici. Si jamais tu as un p?pin d\\\'argent il y aura toujours un petit boulot pour toi.');
INSERT INTO `npc_questions` VALUES (2127, '', '', '', '', 'Oh un g?teau, c\\\'est pour moi ?');
INSERT INTO `npc_questions` VALUES (2128, '', '', '', '', 'Merci beaucoup, vous ?tes un chou.');
INSERT INTO `npc_questions` VALUES (2129, '', '', '', '', 'D\\\'apr?s toi, l\\\'homme Ours n\\\'a quasiment plus aucun pouvoir ?');
INSERT INTO `npc_questions` VALUES (2130, '', '', '', '', 'Vous cherchez du Suborhube ? Mais bien s?r ! Il serait tout de m?me plus courtois de la part des Enutrofs de venir le chercher eux-m?mes. Enfin, je n\\\'ai pas encore trouv? de rem?de contre ce fl?au obsessionnel qui les pousse toujours ? creuser partout o? il ne faudrait pas...');
INSERT INTO `npc_questions` VALUES (2131, '', '', '', '', 'Toujours pas de nouvelles de Nib? Lulle. Es-tu s?r de lui avoir ramen? le sang de ce satan? mineur sombre ?');
INSERT INTO `npc_questions` VALUES (2132, '', '', '', '', 'Saketsu aura les r?sultats en moins de deux.');
INSERT INTO `npc_questions` VALUES (2133, '', '', '', '', 'Si vous pouviez m\\\'apporter 5 laines de boufton de chaque couleur, je vous taillerai une petite cape sp?cialement pour vous !');
INSERT INTO `npc_questions` VALUES (2134, '', '', '', '', 'Vous avez de quoi faire la doublure ? J\\\'ai besoin de 5 laines de bouftons et de la cape que je vous ai confectionn?e.');
INSERT INTO `npc_questions` VALUES (2135, '', '', '', '', 'Merci beaucoup, patientez deux petites secondes s\\\'il vous plait...Voil?, c\\\'est PAR-FAIT, cela vous va ? ravir, je suis d?cidemment g?-ni-al, il n\\\'y a paaas d\\\'auutre mooot.');
INSERT INTO `npc_questions` VALUES (2136, '', '', '', '', 'Encore toi ? Va pr?venir Mon\\\'Hawt\\\'Wit\\\' chez les Eniripsas avant que Joe ne perde patience ! Le temps c\\\'est des kamas, et les kamas Joe aime ?a, alors cours !');
INSERT INTO `npc_questions` VALUES (2137, '', '', '', '', 'Si tu continues ? tout oublier comme ?a, Joe t\\\'enverra au fond d\\\'une mine pour faire mumuse avec les Tofus des Osamodas ! Allez ! Plus vite ! Va voir Clyde Peus de la guilde F?ca !');
INSERT INTO `npc_questions` VALUES (2138, '', '', '', '', 'C\\\'est bien, tu as pr?venu tout le monde... Mais qu\\\'attends-tu ? Retourne voir Joe Pierlivet pour lui faire ton rapport !');
INSERT INTO `npc_questions` VALUES (2139, '', '', '', '', 'Allez r?veille toi ! Va transmettre le message aux autres guildes...');
INSERT INTO `npc_questions` VALUES (2140, '', '', '', '', 'Que veux-tu ? Je n\\\'ai pas la patience de discuter de la pluie et du beau temps, laisse-moi tranquille...');
INSERT INTO `npc_questions` VALUES (2141, '', '', '', '', 'Tu as ta r?ponse ? Bon alors transmets la ? ce vieux gripsou de Joe.');
INSERT INTO `npc_questions` VALUES (2142, '', '', '', '', 'Oui oui ! C\\\'est bon je suis au courant, tu es d?j? pass? me voir ! Serais tu aussi g?teux que Joe malgr? ton jeune ?ge ?');
INSERT INTO `npc_questions` VALUES (2143, '', '', '', '', 'Tout, tout, tout ! Nous les F?cas, on doit s\\\'occuper de tout ici ! A croire que nous sommes les seuls ? poss?der un cerveau... et ne me parlez surtout pas des Iops ! ');
INSERT INTO `npc_questions` VALUES (2144, '', '', '', '', 'Ohhh c\\\'est pas cool ?a... Allez steupl? fais un effort quoi... Ram?ne moi l\\\'extrait de fleur de Dizbi comme ?a je pourrais en renifler tranquillement tout en contemplant la nature au coin de mon chataignier f?tiche.');
INSERT INTO `npc_questions` VALUES (2145, '', '', '', '', 'Tu m\\\'as pas l\\\'air tr?s fortiche ! Allez retourne t\\\'entra?ner.');
INSERT INTO `npc_questions` VALUES (2146, '', '', '', '', 'H? bien, elle a pari? que les Enutrofs n\\\'?taient pas assez courageux pour se risquer dans les souterrains avec les cr?atures qui r?dent alentours, et patati, et patata. \\\" Bien au contraire \\\", que je lui ai dit : \\\" ils vont s\\\'y ruer pour chercher fortune ! \\\".');
INSERT INTO `npc_questions` VALUES (2147, '', '', '', '', 'H? oui ! Bien malin celui qui gagne un pari contre une X?lor, n\\\'est-ce pas ? On dit qu\\\'ils lisent l\\\'avenir, mais je crois savoir qu\\\'elle est amoureuse, ce qui occupe toutes ses pens?es, alors lire l\\\'avenir, tu parles...');
INSERT INTO `npc_questions` VALUES (2148, '', '', '', '', 'Mais je vois que tu n\\\'as pas d\\\'arme ? Tiens, avec cette bourse pleine de Kamas que Montrakwartz m\\\'a gentiment donn?  tu pourras t\\\'en procurer une... En m?me temps, je me demande si elle ne m\\\'a pas jou? un tour. Il se pourrait bien que ces pi?ces ne disparaisse bient?t si personne ne s\\\'en occupe !');
INSERT INTO `npc_questions` VALUES (2149, '', '', '', '', 'Pnj(495) et Message(2148)');
INSERT INTO `npc_questions` VALUES (2150, '', '', '', '', 'D?p?che toi d\\\'aller chez le forgeron. Il fondra ces kamas pour t\\\'en faire une lame digne de ton bras. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole. Reviens me voir apr?s.');
INSERT INTO `npc_questions` VALUES (2151, '', '', '', '', 'Rend toi chez Nib? Lulle, l\\\'alchimiste. Il fondra ces kamas pour t\\\'en faire une lame digne de ton bras. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2152, '', '', '', '', 'Marp explique moi ?a de suite !');
INSERT INTO `npc_questions` VALUES (2153, '', '', '', '', 'Pas de sang ? Tu n\\\'as pas trouv? Radlu Minite Le Mineur Sombre ? Il para?t qu\\\'il passe son temps ? go?ter l\\\'eau de vie du Tavernier. Reviens me voir avec quelques gouttes de son sang.');
INSERT INTO `npc_questions` VALUES (2154, '', '', '', '', 'Oh un visiteuw dans ma fow?t, tu es bien couwageux pour t\\\'aventuwer ici.');
INSERT INTO `npc_questions` VALUES (2155, '', '', '', '', 'Tiens je te donne tout');
INSERT INTO `npc_questions` VALUES (2156, '', '', '', '', 'Tiens une quete');
INSERT INTO `npc_questions` VALUES (2157, '', '', '', '', 'Toi pabo ! Toi degage !');
INSERT INTO `npc_questions` VALUES (2158, '', '', '', '', 'Tiens je reprends tout');
INSERT INTO `npc_questions` VALUES (2159, '', '', '', '', 'Ca y est, j\\\'ai fini l\\\'analyse du sang... Euh va voir Saketsu, il t\\\'expliquera...');
INSERT INTO `npc_questions` VALUES (2160, '', '', '', '', 'Une cruche remplie a moiti?, est-elle a moiti? vide ?');
INSERT INTO `npc_questions` VALUES (2161, '', '', '', '', 'Vous vous aimez bien que tout soit rempli je ne me trompe ? Bon alors j\\\'ai un petit travail pour vous. Il faut que vous blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab blablablab. Bon accpetez vous ?');
INSERT INTO `npc_questions` VALUES (2162, '', '', '', '', 'Voila tu as reussi ? remplir ta cruche c\\\'est bien ! D?gage maintenant !');
INSERT INTO `npc_questions` VALUES (2163, '1991;1992', '', '', '0', 'Bien le bonjour ! Tu es int?ress? par une arme je suppose ? D?sol? mais j\\\'ai des commandes ? n\\\'en plus voir le bout. Reviens quand les larves auront des dents... erf !');
INSERT INTO `npc_questions` VALUES (2164, '', '', '', '', 'Proposer ses services');
INSERT INTO `npc_questions` VALUES (2165, '', '', '', '', 'Rendez-vous, rendez-vous, l?l?l');
INSERT INTO `npc_questions` VALUES (2166, '', '', '', '', 'Hummm ? Ah *kof*kof* Ah lala, je suis malade comme un chienchien. Impossible de travailler aujourd\\\'hui.');
INSERT INTO `npc_questions` VALUES (2167, '', '', '', '', 'Bon maintenant que tu poss?des ta propre ?p?e, ?quipe toi et va tuer deux arakn?es ! Tu me montreras ainsi de quoi tu es capable. Si tu t\\\'en montres digne, je te confierai ensuite une mission plus importante.');
INSERT INTO `npc_questions` VALUES (2168, '', '', '', '', 'Bonjour cher client, que puis-je pour vous aujourd\\\'hui ? Je vends des tas de choses : conservateurs, pr?paration pour poisson, pour viande, levure, fruits et l?gumes pour la plus grande partie. Un seul mot de votre part : acheter ! et c\\\'est parti ! Je reprends aussi tous vos objets contre un peu d\\\'argent si vous le souhaitez...');
INSERT INTO `npc_questions` VALUES (2169, '', '', '', '', 'Aurais tu peur des arakn?es pour revenir si vite ?');
INSERT INTO `npc_questions` VALUES (2170, '', '', '', '', 'Je savais que tu n\\\'?tais pas une mauviette ! Passons aux choses s?rieuses maintenant !');
INSERT INTO `npc_questions` VALUES (2171, '', '', '', '', 'Pnj(475) et Message(1965)');
INSERT INTO `npc_questions` VALUES (2172, '', '', '', '', 'Hmmmhmmmhmmmm... *sifflote*');
INSERT INTO `npc_questions` VALUES (2173, '', '', '', '', 'Merci beaucoup. Cette r?union ?tait d\\\'une importance capitale. Voila quelques kamas pour te r?compenser. Reviens me voir quand tu veux. Je t\\\'offrirai un peu de mon pr?cieux temps...');
INSERT INTO `npc_questions` VALUES (2174, '', '', '', '', 'Quoi ?! Tu n\\\'es pas all? voir Howard ? Mais qu\\\'attends tu ? Un coup de pelle, peut-?tre ?');
INSERT INTO `npc_questions` VALUES (2176, '', '', '', '', 'Bonjour... Mmh, tu sais que je suis assez c?l?bre ici... Tu as d? voir mon portrait affich? dans le coin non ?');
INSERT INTO `npc_questions` VALUES (2177, '', '', '', '', 'Cher #1... Tu sais pourtant que nous autres Srams, nous avons la facult? de nous d?doubler ! Et l?, tu causes ? mon double, petit... H? oui. Je me ferais un plaisir de t\\\'expliquer tout ?a si on se rencontre du c?t? de Br?kmar... En attendant, j\\\'ai une mission ? te confier !');
INSERT INTO `npc_questions` VALUES (2178, '', '', '', '', 'Si vous pouviez faire moins de bruit, Locette dort profond?ment. Elle avait mal ? la t?te en rentrant de mission. J\\\'esp?re qu\\\'elle n\\\'a rien.');
INSERT INTO `npc_questions` VALUES (2179, '', '', '', '', 'Ah c\\\'est la fleur que j\\\'ai demand?e pour le rem?de de Locette ? Tr?s bien, je vais pr?parer la potion. Je dois vous pr?venir que son cas d?passe mes comp?tences, j\\\'esp?re que cela marchera...Voil?, rapportez vite cette potion ? Yol.');
INSERT INTO `npc_questions` VALUES (2180, '', '', '', '', 'Arg c\\\'est bien ce que je craignais, mes talents ont leurs limites. Cela dit, ceux de Nepra Lido n\\\'en ont pas ! Je lui en ai touch? deux mots, je crois qu\\\'elle pourra aider Locette, allez vite lui parler.');
INSERT INTO `npc_questions` VALUES (2181, '', '', '', '', 'Ah vous ?tes l? pour Locette, j\\\'ai r?fl?chi ? son cas. J\\\'ai pens? ? un rem?de ancestral qui pourrait convenir ici : Une potion si piquante et si puante que ses sens seront vivifi?s. Combattre le mal par le mal, voil? ma devise. Pour ?a il me faut, de la bave de bouftou en grande quantit?, un peu de bave de rose d?moniaque, et des ?pines de champ champ. Rapportez-moi tout ?a s\\\'il vous plait !');
INSERT INTO `npc_questions` VALUES (2182, '', '', '', '', 'Merci, attendez ce ne sera pas long...Voil?, donnez cette potion ? Yold. Il devrait pouvoir r?veiller Locette.');
INSERT INTO `npc_questions` VALUES (2183, '', '', '', '', 'Locette s\\\'est r?veill?e ? Bien, je craignais qu\\\'elle ne succombe si elle passait une nuit de plus sans ses sens. Vous n\\\'imaginez pas ? quel point chacun d\\\'entre eux a sa place dans l\\\'essence m?me de la vie. Bon pour le d?sordre de sens : on continue les rem?des ancestraux. Allez chercher une pierre au fond de la grotte Ouest. Et amenez-la le plus vite possible ? la bijouti?re Shani, elle vous expliquera pourquoi il est n?cessaire que cela soit rapide.');
INSERT INTO `npc_questions` VALUES (2184, '', '', '', '', 'Une pierre de soin fuyard ? Vite donnez moi ?a.... \\n*Shani file dans son atelier pour revenir deux minutes apr?s, la pierre est sertie dans le m?tal* \\nUne fois extraite de la roche, la pierre ?puise son pouvoir tr?s vite. Seul ce m?tal conserve le pouvoir de cette pierre...');
INSERT INTO `npc_questions` VALUES (2185, '', '', '', '', 'Une pierre de soin ? Vous avez mis trop de temps pour me l\\\'apporter... sa puissance est retourn?e ? la nature. Il faut que vous me l\\\'apportiez en moins de 20 minutes, et je la sertirai dans un m?tal de confinement.');
INSERT INTO `npc_questions` VALUES (2186, '', '', '', '', 'Ton arc est d?j? pr?s! Moi j\\\' trouve que les arcs d\\\'Enileda n\\\'sont pas vraiment rapides. J\\\'ai remplac? la corde par la laine de bouftou que j\\\'ai tress? 3 fois. Com\\\' ?a j\\\'suis sure que la corde est bien serr?e.... Voila, maint\\\'nant c\\\'est un bon arc ?a... Bon, j\\\'vais enfin pouvoir t\\\'apprendre ? tirer. Aller, on va l\\\'essayer ! Fais attention, il est assez dur ? prendre en main au d?but...');
INSERT INTO `npc_questions` VALUES (2187, '', '', '', '', 'Il y a des pissenlits dans les champs au Nord-Est de la ville, si j\\\'ai bonne m?moire...');
INSERT INTO `npc_questions` VALUES (2188, '', '', '', '', 'Alors le livreur est sauf ? Pas encore ? Courage j\\\'ai confiance en vous.');
INSERT INTO `npc_questions` VALUES (2189, '', '', '', '', 'Hummm... laisse-moi r?fl?chir... si tu me montres ton bout de bois comme ?a, c\\\'est s?rement pour que je te taille un arc, n\\\'est-ce pas ? Ca me va... mais tu vas devoir sortir tes kamas !');
INSERT INTO `npc_questions` VALUES (2190, '1981;1980', '', '', '0', 'Je ne sais pas ce qu\\\'il se passe en ce moment mais il y a de plus en plus d\\\'aventuriers dans cette cit?. Je suis vraiment d?bord?e...');
INSERT INTO `npc_questions` VALUES (2191, '', '', '', '', 'C\\\'est mon petit Setsinbol ch?ri qui t\\\'envoie ? C\\\'est bon pour cette fois... Je veux bien te le faire gratuitement ! C\\\'est du bon bois j\\\'esp?re ?');
INSERT INTO `npc_questions` VALUES (2192, '', '', '', '', 'C\\\'est un beau morceau que tu as la ! Bon, ?a ne sera pas long... Reviens me voir dans un instant...');
INSERT INTO `npc_questions` VALUES (2193, '', '', '', '', 'Voil? le chef d\\\'oeuvre... La corde n\\\'est pas tr?s tendue mais elle reste tr?s correcte pour un d?butant. Maintenant, tu n\\\'as plus qu\\\'? trouver quelqu\\\'un qui veuille bien t\\\'enseigner son art. Mon Setsinbol ch?ri fera parfaitement l\\\'affaire... mais tout le monde sait que la meilleure c\\\'est bien Ticra, sa fille.');
INSERT INTO `npc_questions` VALUES (2194, '', '', '', '', 'Voila le chef d\\\'oeuvre... Il ne te reste plus qu\\\'a trouver quelqu\\\'un qui sache fixer la corde. Setsinbol ch?ri fera parfaitement l\\\'affaire mais tout le monde sait que le meilleur c\\\'est bien Ticr?, son fils.');
INSERT INTO `npc_questions` VALUES (2195, '', '', '', '', 'D?p?chez vous de me ramener tout avant que les Ecaflips ne viennent me d?fier ? nouveau ! ');
INSERT INTO `npc_questions` VALUES (2196, '', '', '', '', 'Mais c\\\'est quoi ?a ?! Je viens d\\\'assister ? ta mort... Ne t\\\'inqui?te pas ce n\\\'est pas pour tout de suite. Ma vision est un peu trop lointaine... ?a doit ?tre ? cause de ce bois ? Je t\\\'avais bien dit sans fioriture ! Ah ce vieux Oli Venders ! Bon, il va me falloir une peau de larve bleue en plus pour pr?ciser ma vision. Tiens ! Prends ce marteau et ram?ne m\\\'en une.');
INSERT INTO `npc_questions` VALUES (2197, '', '', '', '', 'Une peau de larve bleue, c\\\'est tout ce dont j\\\'ai encore besoin ! \\nAllez jeter un oeil ? l\\\'entr?e Nord d\\\'Astrub, c\\\'est l? que vous trouverez les meilleures larves.');
INSERT INTO `npc_questions` VALUES (2198, '', '', '', '', 'Parfait. Nous y voil?, Ahahah ! Ahem ! Excusez-moi ! Tr?s bien, jetons-y un oeil... *Montrakwartz se concentre sur l\\\'?coulement de l\\\'Epyss, puis quelque chose la foudroie, elle laisse tomber le sablier qui se brise*  Enfer ! Qu\\\'est ce que c\\\'est que cette vision ! Laissez-moi reprendre mes esprits... mis?ricorde, nous avons un probl?me.');
INSERT INTO `npc_questions` VALUES (2199, '', '', '', '', 'Vous... Vous faisiez partie de ma vision ! Vous rejoindrez d\\\'autres aventuriers et participerez aux fouilles Enutrof dans les galeries sous la ville ! C\\\'est tr?s important ! L\\\'intelligence et la sagesse seront vos meilleures alli?es...');
INSERT INTO `npc_questions` VALUES (2200, '184', '', '', '0', 'Je savais que ?a te plairait. Alors jetons un oeil dans l\\\'avenir... Comment ? De la triche ?... Sache mon jeune apprenti, que les Xelors ne trichent jamais ! Ils font juste souvent preuve d\\\'anticipation, une marque d\\\'intelligence ! Bon, je disais donc, il va me falloir quelques composants : deux fioles de cristal de p?le Anthir que tu obtiendras aupr?s de Nib? Lulle l\\\'Alchimiste, du grain d\\\'Epyss qu\\\'un des employ?s de l\\\'entrep?t de nourriture devrait pouvoir te fournir, et un bois de simple facture chez Oli Venders. Pas de fioriture, le bois d?termine la port?e, et je ne d?sire obtenir qu\\\'une vision du futur proche. Pour commencer, je t\\\'ai indiqu? l\\\'atelier de Nib? Lulle. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2201, '', '', '', '', 'Tu viens s?rement de la part de ce cher Setsinbol... Mouai... Toi aussi tu veux de la laine de Bouftou, non ? T\\\'as de la chance il m\\\'en reste un peu. Tiens, prends-la, je te la donne.');
INSERT INTO `npc_questions` VALUES (2202, '', '', '', '', 'De rien... Tu devrais aller voir Enileda, elle te sculptera l\\\'arc qu\\\'il te faut.');
INSERT INTO `npc_questions` VALUES (2203, '', '', '', '', 'Ah ?a oui ! Je dois r\\\'conna?tre que c\\\'est pas la voie d\\\'administration qui m\\\'r?jouit ! Les Tofus non plus d\\\'ailleurs... Tu n\\\'veux pas t\\\'en occuper toi-m?me ? Non... ?videment ! Allez, bonne journ?e quand m?me ! ');
INSERT INTO `npc_questions` VALUES (2204, '', '', '', '', 'Euh, j\\\' veux pas ?tre m?chante mais ? part MacGivrer, j\\\'connais personne qui peut t\\\'faire un bon arc avec si peu de choses...');
INSERT INTO `npc_questions` VALUES (2205, '212', '', '', '0', 'Comme je te le dis ! Elle m\\\'avait pr?dit ta venue d\\\'ailleurs... Enfin ! Comme tout bon initi?, tu devrais cr?er ton premier lien avec elle. Pour ce faire, la nature accepte de sacrifier un peu de ses biens. Mais en contrepartie tu devras la prot?ger ! Va voir Oli Venders, le b?cheron : il a s?rement ce qu\\\'il te faut pour faire un bon b?ton : une branche de bois d\\\'Arash. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole. Reviens me voir apr?s cela...');
INSERT INTO `npc_questions` VALUES (2206, '', '', '', '', 'Vraiment ? Tant pis, tu ne sais pas ce que tu rates !');
INSERT INTO `npc_questions` VALUES (2207, '', '', '', '', 'Tant pis ! Tu ne sais pas ce que tu rates. Va donc voir Clint Pot, il devrait pouvoir t\\\'aider... \\nJe t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2208, '185', '', '', '0', 'Ah ! J\\\'te saoule, j\\\'vois bien ! Tiens il doit m\\\'en rester un petit bout de bois d\\\'Arash, mais fais-y gaffe, c\\\'est rare !');
INSERT INTO `npc_questions` VALUES (2209, '', '', '', '', 'Ben mate moi ?a, un pur lien avec la nature, comme dirait ma?tre Sadadi. Et je crois que ?a va ?tre super utile: la nature a senti quelque chose de n?faste dans les galeries, et des Enutrofs sont en danger ! Si t\\\'as le temps avant ta sieste, tu peux aller voir s\\\'qui s\\\'trame. Moi, je dois seconder le ma?tre dans sa lourde t?che... ');
INSERT INTO `npc_questions` VALUES (2210, '2015;2014', '', '', '0', 'Pas le temps, moustique ! Trop de bois ? vendre !');
INSERT INTO `npc_questions` VALUES (2211, '', '', '', '', 'Trois-Fleur r?side dans la r?gion qui se trouve au sud, demande ? la taverne du village d\\\'Amakna je suis sur qu\\\'ils sauront te dire o? il se trouve, haha ! Il a toujours eu un faible pour la bi?re...');
INSERT INTO `npc_questions` VALUES (2212, '', '', '', '', 'Merci beaucoup ! Mais... les fleuurs ! Ouiiin, je... je voulais tant offrir un bouquet ? ma maman ! \\nJe n\\\'ose plus aller dans cette for?t maintenant, s\\\'il vous pla?t, allez me chercher un bouquet de quatre fleurs de Lin ! Il n\\\'est pas facile de cueillir des... des fleurs soigneusement, si vous ne savez pas, faites vous aider par... par un alchimiste.');
INSERT INTO `npc_questions` VALUES (2213, '', '', '', '', 'Je... je ne retrouve plus ma maison.... tout ce que je me rappelle c\\\'est que ma m?re m\\\'emm?ne souvent au parc du village, et qu\\\'il est tr?s proche de l? o? j\\\'habite...');
INSERT INTO `npc_questions` VALUES (2214, '', '', '', '', 'Ah ! C\\\'est vous les renforts ?! Bon ben, on va faire avec... Voil? le topo : les Osamodas nous ont pr?t? des Tofus qui reniflent les ?manations de gaz. Y nous pr?viennent quand ?a d\\\'vient dangereux, t\\\'vois quoi ? Nous autres, on les appelle les \\\"ranifftous\\\". \\nJ\\\'crois qu\\\'y z\\\'ont senti quequ\\\'chose qui n\\\'est pas du gaz... Certains en sont r\\\'venus dans un sale ?tat, et j\\\'doute que du Suborhube puisse y faire quequ\\\'chose. Les n?tres sont partis ? la r\\\'cherche des ranifftous, ?a va faire un bout d\\\'temps... J\\\'ai peur qu\\\'ils ne se soient fait capturer par ces fichus rats. Retrouvez-les, j\\\'vous en prie ! \\n');
INSERT INTO `npc_questions` VALUES (2215, '', '', '', '', 'A l\\\'aide ! L\\\'a bouff? mes Tofus ranifftous ! Il en veut ? not\\\' peau !');
INSERT INTO `npc_questions` VALUES (2216, '', '', '', '', 'Par le Bauxite, le Fer et le Mangan?se, merci ! Sans toi, on servait de repas ? ce rat g?ant ! Jamais rien vu sur pattes qui soit aussi gros ! On patrouillait dans ct\\\'e souterrain et des bestioles nous sont tomb?es d\\\'sus. On est rest?s coinc?s ici, bloqu?s par ce monstre. Y doit encore y avoir de la bagarre, mais j\\\'saurai pas dire par o?, avec tous ces ?chos... Mais qu\\\'est-ce qui s\\\'passe ? Astrub, nom d\\\'une pioche ?');
INSERT INTO `npc_questions` VALUES (2217, '', '', '', '', 'Euuh, j\\\'passe ? deux doigts d\\\'la mort et tu causes min?raux ? Bon beeh, minerais, m?taux, pour un mineur, y\\\'a rien d\\\'plus beau ! Dans les mains d\\\'un bon alchimiste ?a f\\\'ra des potions, dans les mains d\\\'un forgeur d\\\'?p?e, ?a f\\\'ra des bonnes lames... Et des ?p?es, on va en avoir b\\\'soin, j\\\'te l\\\'dis !');
INSERT INTO `npc_questions` VALUES (2218, '', '', '', '', 'Par l?-bas, c\\\'est Amakna. J\\\'va te dire, y commence ? y\\\'avoir de dr?les d\\\'histoires sur c\\\'qui s\\\'passe de s\\\'c?t?. Mais j\\\'vois bien ? ta t?te qu\\\'c\\\'est pas fait pour te d?plaire, hein ?');
INSERT INTO `npc_questions` VALUES (2219, '1727', '', '', '', 'Oh, une Calanthe Triplicata Maussade, hmm, je n\\\'avais pas vu un tel sp?cimen de plante depuis mon s?jour sur l\\\'?le de Moon... D?cid?ment ce jardin public regorge de surprises !');
INSERT INTO `npc_questions` VALUES (2220, '', '', '', '', 'Alors ? La charmante Nepra Lido t\\\'a donn? le suborhube ?');
INSERT INTO `npc_questions` VALUES (2221, '', '', '', '', 'Mes pauvres Tofus ! Seul un Osamodas peut m\\\'aider ? trouver un rem?de pour les soigner.');
INSERT INTO `npc_questions` VALUES (2222, '', '', '', '', 'Qu\\\'attendez vous pour aller porter le rem?de aux Enutrofs ?');
INSERT INTO `npc_questions` VALUES (2223, '', '', '', '', 'N\\\'oublie pas d\\\'aller dire ? ton ma?tre que j\\\'moccupe d\\\'ses Tofus !');
INSERT INTO `npc_questions` VALUES (2224, '', '', '', '', 'Ah merci pour le g?teau, tenez pour la livraison.');
INSERT INTO `npc_questions` VALUES (2226, '', '', '', '', 'Oula que veux-tu que je fasse avec cet arc ? Je ne suis pas archer ?');
INSERT INTO `npc_questions` VALUES (2227, '', '', '', '', 'Hummm... Je crois que je vais pouvoir t\\\'aider. Je vais verser une potion qui va raidir la corde. Tu verras, ton arc aura une pr?cision ? toute ?preuve. Bouge pas, je te fais ?a tout de suite.');
INSERT INTO `npc_questions` VALUES (2228, '1910', '', '', '', 'Ah enfin, le client qui me l\\\'a command? est d?j? parti. Je le mangerai moi-m?me du coup. Pas question que je paye la livraison !');
INSERT INTO `npc_questions` VALUES (2229, '', '', '', '', 'Oh merrcii mon chouu. Ce petit go?ter n\\\'est certes pas bon pour la ligne, mais cela me donne une p?che d\\\'enfer !');
INSERT INTO `npc_questions` VALUES (2230, '', '', '', '', 'Merci mon chou, tu es un peu en retard, mon pr?cieux go?ter a perdu un peu de sa fra?cheur. Je suis obliiig? de r?duire un peu le co?t de livraison.');
INSERT INTO `npc_questions` VALUES (2231, '', '', '', '', 'AAAhh, mon g?teau, rien ne vaut un peu de sucre entre deux ?p?es ! Tiens mon gars, pile poil quand il fallait.');
INSERT INTO `npc_questions` VALUES (2232, '', '', '', '', 'Hmm, g?teau ? Ah oui, celui que j\\\'attendais tout ? l\\\'heure ?! J\\\'ai perdu patience et j\\\'ai entam? une nouvelle ?p?e... Pose-le dans un coin et merci pour le d?placement !');
INSERT INTO `npc_questions` VALUES (2233, '', '', '', '', 'Cool ! Reviens me voir dans 5 minutes. Je vais t\\\'faire un arc du tonnerre...');
INSERT INTO `npc_questions` VALUES (2234, '', '', '', '', 'Comment t\\\'veux avoir un bon arc si tu m\\\'files pas de la laine pour changer la corde ?');
INSERT INTO `npc_questions` VALUES (2235, '', '', '', '', 'Ha, merci pour ce g?teau, c\\\'est pour Oz. Avec ?a, je peux faire de lui ce que je veux h?h?... D?lai tenu pour la livraison, tiens.');
INSERT INTO `npc_questions` VALUES (2236, '', '', '', '', 'Merci pour la laine... Mais t\\\'veux j\\\'en fasse quoi sans arc ?');
INSERT INTO `npc_questions` VALUES (2237, '', '', '', '', 'Ha oui, le g?teau que j\\\'avais command? pour Oz... h?las il ne m\\\'est plus d\\\'aucune utilit?, il vient de s\\\'empiffrer de pain...');
INSERT INTO `npc_questions` VALUES (2238, '', '', '', '', 'Qu\\\'attends-tu ? Va donc voir Oli Venders ! Il pourra tr?s certainement te fournir du bois d\\\'arash.');
INSERT INTO `npc_questions` VALUES (2239, '', '', '', '', 'A...avez vous retrouv? ma... peluche... ?');
INSERT INTO `npc_questions` VALUES (2240, '', '', '', '', 'Eh bin ! Qu\\\'attends-tu pour aller porter l\\\'bois ? ton ma?tre ?');
INSERT INTO `npc_questions` VALUES (2241, '', '', '', '', 'Mon vieux ! Regarde-moi ce minerai... \\n*tend une pierre difforme ressemblant ?trangement ? du minerai de fer* \\n?a doit valoir une petite fortune, non ?');
INSERT INTO `npc_questions` VALUES (2242, '', '', '', '', '*contemple une petite fleur de lin*  \\nRegarde-moi cette beaut? ! Ceci est un don de la nature, une pure merveille qu\\\'elle nous offre si d?licatement. Prenons soin d\\\'elle et pr?servons-la.');
INSERT INTO `npc_questions` VALUES (2243, '', '', '', '', 'Laisse-moi me reposer et va porter le bois ? mon apprenti, il sait ce qu\\\'il a ? faire.');
INSERT INTO `npc_questions` VALUES (2244, '', '', '', '', 'D?sol?, je n\\\'ai pas de temps ? vous consacrer... J\\\'entra?ne mes Tofus ? descendre sous terre pour aider les Enutrofs.');
INSERT INTO `npc_questions` VALUES (2245, '1878', '', 'QT!43', '2295', 'Grmbl... J\\\'en ai assez de ces fichues bestioles ! Elle d?vorent mes fruits ! Tu ne pourrais pas m\\\'aider ? m\\\'en d?barasser ?');
INSERT INTO `npc_questions` VALUES (2246, '', '', '', '', 'Tu sais tout d?sormais... Que ton destin te guide jeune apprenti !');
INSERT INTO `npc_questions` VALUES (2247, '', '', '', '', 'Tu veux faire un pari avec moi ? *lance une pi?ce* Allez tente ta chance ! ');
INSERT INTO `npc_questions` VALUES (2248, '2131', '', '', '0', '*Se passe la main dans les cheveux* Oui ? Vous d?sirez ?');
INSERT INTO `npc_questions` VALUES (2249, '', '', '', '', 'Ha ok... Dans ce cas le prochain bouftou que je vais ?gorger sera le sien.');
INSERT INTO `npc_questions` VALUES (2250, '', '', '', '', 'Voil? ! Regarde, il est pas beau comme ca ? Allisteria n\\\'aura besoin que des quatres cuisses. J\\\'ai l\\\'habitude de garder le reste.');
INSERT INTO `npc_questions` VALUES (2251, '', '', '', '', 'Alors c\\\'est bon ? Tu m\\\'as ramen? les quatre cuisses de mon pauvre Bouftou et les deux citrons que je t\\\'avais demand? ?');
INSERT INTO `npc_questions` VALUES (2252, '', '', '', '', 'Bah tu n\\\'as rien ? Qu\\\'est-ce que tu attends ? Va chercher de la bi?re chez le Tavernier...');
INSERT INTO `npc_questions` VALUES (2253, '', '', '', '', 'Merci pour les citrons mais... pour le boudin bouilli de Bouftou il faut des cuisses de Bouftou... Ca para?t logique, non? Vite ! D?p?che-toi ! J\\\'ai faim...');
INSERT INTO `npc_questions` VALUES (2254, '', '', '', '', 'Merci pour les cuisses... Il me manque encore les 2 citrons pour ma recette... Vite ! D?p?che toi ! J\\\'ai faim...');
INSERT INTO `npc_questions` VALUES (2255, '', '', '', '', 'Ah ! C\\\'est vous les renforts ?! Bon ben, on va faire avec... Voil? le topo : les Osamodas nous ont pr?t? des Tofus qui reniflent les ?manations de gaz. Y nous pr?viennent quand ?a d\\\'vient dangereux, t\\\'vois quoi ? Nous autres, les appelle les \\\" ranifftou \\\".');
INSERT INTO `npc_questions` VALUES (2256, '', '', '', '', 'Quoi ? Un bouftou ? Pas le temps ! Faut qu\\\'on descende... J\\\'crois qu\\\'y z\\\'ont senti quequ\\\'chose qui n\\\'est pas du gaz... Certains en sont r\\\'venus dans un sale ?tat, et j\\\'doute que du Suborhube puisse y faire quequ\\\'chose. Les n?tres sont partis ? la r\\\'cherche des ranifftous, ?a va faire un bout d\\\'temps... Retrouvez les, j\\\'vous en prie !');
INSERT INTO `npc_questions` VALUES (2257, '', '', '', '', 'Merci pour l\\\'entra?nement, ?a m\\\'a fait du bien. J\\\'ai une derni?re faveur ? te demander. Apr?s, je te laisserai continuer ta route... Avec tout ce remue-m?nage, quelques-uns de nos Bouftous se sont ?chapp?s, et certains se sont ?gar?s du c?t? des souterrains...');
INSERT INTO `npc_questions` VALUES (2258, '', '', '', '', 'Contrairement ? nous autres Feca, l\\\'intelligence n\\\'est pas le point fort de ces sacr?es bestioles ! Bien... il nous manque un Bouftou : pourrais-tu aller ? sa recherche ? Je crois qu\\\'il est du c?t? des souterrains. Va voir Gasdaure, si quelqu\\\'un l\\\'a aper?u de ce c?t?, ?a ne peut ?tre qu\\\'elle...');
INSERT INTO `npc_questions` VALUES (2259, '', '', '', '', 'Merci, je savais que je pouvais compter sur toi... Tiens, j\\\'allais oublier. Prends ce pain : il te gu?rira de tes blessures...');
INSERT INTO `npc_questions` VALUES (2260, '', '', '', '', 'La carte et ta g?oposition te seront tr?s utiles pour te d?placer dans le monde. Les lieux les plus importants y sont marqu?s par diff?rentes ic?nes. Tu pourras aussi t\\\'en servir pour marquer une destination cl? ? l\\\'aide du drapeau bleu. Ta boussole indiquera alors ce lieu.');
INSERT INTO `npc_questions` VALUES (2261, '', '', '', '', 'Cr?er un groupe te permet de communiquer simplement et rapidement avec les aventuriers que tu auras rassembl?s au cours d\\\'une session de jeu. \\nNe confonds pas \\\"Groupe\\\" et \\\"Guilde\\\". Le Groupe est temporaire, la Guilde est permanente et soumise ? certaines conditions. ');
INSERT INTO `npc_questions` VALUES (2262, '', '', '', '', 'Mais qu\\\'est-ce que tu as fait ? Ca ne m\\\'int?resse pas de conna?tre les personnes qui ne conviennent pas pour ce boulot. Reprends une feuille et cherche mieux cette fois...');
INSERT INTO `npc_questions` VALUES (2263, '', '', '', '', 'Pourquoi faut-il que les gens aient des cheveux aussi diff?rents ?  \\nJ\\\'ai recens? onze types de cheveux diff?rents dans le monde dont voici la liste, je suis s?re qu\\\'avec ton habilit? tu seras capable de me ramener une m?che de chaque !');
INSERT INTO `npc_questions` VALUES (2264, '', '', '', '', 'Vous m\\\'impressionnez, il est regrettable que vous ne soyez pas int?ress? par ma profession, j\\\'aurais tant aim? avoir un assistant comme vous...');
INSERT INTO `npc_questions` VALUES (2265, '1898', '', '', '0', 'Zut, je viens encore d\\\'ab?mer ma paire de ciseaux ! Il m\\\'en faudrait une neuve, mais je ne peux pas laisser ma boutique sans surveillance... \\nSi tu peux aller m\\\'en chercher une paire ? l\\\'h?tel des ventes de la forge, je t\\\'en serais tr?s reconnaissant... Adresse toi ? un certain Deudoin?, il fait ?a tr?s bien...');
INSERT INTO `npc_questions` VALUES (2266, '', '', '', '', 'Alors, as-tu r?ussi ? te procurer des ciseaux?digne de ce nom ?');
INSERT INTO `npc_questions` VALUES (2267, '', '', '', '', 'Je t\\\'ai d?j? dit : je n\\\'ai pas de bois d\\\'Arash.\\nJ\\\'ai bien ce magnifique bois d\\\'orme, regarde-moi cette belle pi?ce : ca vaut bien mieux que de l\\\'Arash !');
INSERT INTO `npc_questions` VALUES (2268, '', '', '', '', 'Mais mais mais ? Qu\\\'avez vous fait de cette feuille ? Vous l\\\'avez jet?e ? Ce sera 5 kamas pour vous en filer une autre...');
INSERT INTO `npc_questions` VALUES (2269, '', '', '', '', 'Merci beaucoup! Tiens, prends mes ciseaux abim?s tu en auras peut ?tre besoin !  \\n \\nPendant ton absence, j\\\'ai essay? de vendre une perruque de Sadidette ? un Iop, mais pas moyen de le convaincre !  \\nTu serais adorable si tu m\\\'aidais ? r?pertorier tous les types de cheveux diff?rents...');
INSERT INTO `npc_questions` VALUES (2270, '', '', '', '', 'Les souterrains n\\\'sont pas s?rs ces temps-ci. Et les Tofus en reviennent malades, c\\\'est bizarre... Quelques-uns des n?tres sont partis patrouiller et voir c\\\'qui s\\\'y passe l?-d\\\'dans.');
INSERT INTO `npc_questions` VALUES (2271, '1903;1904', '', '', '0', 'Bien le bonjour, ouaaaiiiss. T\\\'ouvres des grands yeux tout ronds toi... Mouaaaiiiisss, m\\\'est avis qu\\\'un brin de causette avec un vieux mercenaire comme moi ne te fera pas mal.');
INSERT INTO `npc_questions` VALUES (2272, '1905', '', '', '0', 'H?????... Alors, on veut en savoir plus sur les cr?atures qui r?dent dans les parages, heiiiin ? C\\\'est pas tr?s compliqu? ouaiiisss... Plus tu t\\\'enfonces loin vers le Nord ou vers le Sud, plus les cr?atures que tu rencontres sont dangereuses, et moins t\\\'as de chance de rentrer vivant. \\nAlentours, et jusqu\\\'? Amakna, tu trouves rien de bien f?roce... Encore que dans les coins sombres d\\\'Astrub, c\\\'est devenu peu s?r ces derniers temps... ');
INSERT INTO `npc_questions` VALUES (2273, '1906', '', '', '0', 'Baaah... la vie est rude ici-bas. Ouaiiis ouais... Et si une cr?ature vient ? bout de ta vitalit?, tu mordras la poussi?re. Il te faudra t\\\'asseoir pour te refaire une sant?. Mange du pain que tu auras achet? ? un boulanger, bois une potion de soin -certains alchimistes en fabriquent d\\\'excellentes- et tu mordras la vie ? pleines dents, s\\\'il t\\\'en reste, heeeinnn...');
INSERT INTO `npc_questions` VALUES (2274, '', '', '', '', 'Des rumeurs, ouaaaiiisss... Ca en parle dans tout Astrub... Mais bon, va pas te fier ? la t?te des cr?atures que tu croises... Si t\\\'es seul et peu exp?riment?, t\\\'avises pas d\\\'enquiquiner un vieux Bouftou, hein ! Ces b?tes-l?, ?a t\\\'arrache la peau des fesses comme une touffe d\\\'herbe. Et ?a m?che longtemps apr?s en te regardant droit dans les yeux... Mouais...*Nakuneul semble songeur*');
INSERT INTO `npc_questions` VALUES (2275, '', '', '', '', 'Apprends ? conna?tre les Eniripsas. Ce sont de bons soigneurs. Ah ouaaaiiis, et aussi : il y a ce jeune ma?tre F?ca, ? l\\\'Est d\\\'Amakna... comment il s\\\'appelle d?j? ? Me souviens plus... Mais c\\\'est un fameux ?leveur de Bouftous, plusieurs fois m?daill? ? la foire du Trool. Il poss?de des Petits Parchemins de Vitalit?. Trouve-le, et il te renseignera ? ce sujet, pour s?r !');
INSERT INTO `npc_questions` VALUES (2276, '1907;1908', '', '', '0', 'On s\\\'est d?j? vu quelque part nous, non ? Laisse-moi r?fl?chir... c\\\'?tait pas du c?t? des plaines de Cania, pour chasser les Porkass ? Ou alors c\\\'?tait pendant la campagne de l\\\'?le de Moon !? Rh?? tu te souviens de ces foutues tortues !?');
INSERT INTO `npc_questions` VALUES (2277, '1909', '', '', '0', 'H??? ouaaiiis ! Impossible de me tromper ! Rhahahaha ! Je sais reconna?tre le visage des braves ! Et tu te souviens, lorsqu\\\'on a guerroy? de Sidimote jusqu\\\'? Bonta pour mettre le cap sur l\\\'?le des Wabbits et revenir ? Br?kmar ? J\\\'en avais plein les jambes cette fois-l? et ?a m\\\'a co?t? neuf orteils !... Si on avait utilis? les zaaps, plut?t que de tout se taper ? pied, ?\\\'aurait ?t? plus facile !');
INSERT INTO `npc_questions` VALUES (2278, '1910', '', '', '0', 'Tu sais, ces arches de pierre r?parties un peu partout dans le Monde !? Lorsque tu en verras une, approche t\\\'en. Elle gardera le souvenir de ton passage. Tu pourras ensuite t\\\'y t?l?porter ? partir d\\\'un autre Zaap, moyennant quelques kamas.');
INSERT INTO `npc_questions` VALUES (2279, '1911', '', '', '0', '*marmonne* \\nQue le dieu Iop te donne Vitalit?, que ton ?p?e crisse et soit aff?t?e, que ton bras soit long avec Compulsion ! ');
INSERT INTO `npc_questions` VALUES (2280, '1912', '', '', '0', 'Je prie... Nous sommes ? l\\\'image des dieux qui nous ont cr??s, et nous devrions toujours les ?couter... Pour comprendre cela, il m\\\'a fallu perdre un bout d\\\'oreille, mais j\\\'ai gagn? la foi !');
INSERT INTO `npc_questions` VALUES (2281, '1913', '', '', '0', 'Chaque ?tre qui foule ces terres devrait prendre le temps de trouver son dieu, et honorer de sa pr?sence le temple qui lui est consacr');
INSERT INTO `npc_questions` VALUES (2282, '1914', '', '', '0', 'Cherche... et tu trouveras ! Les temples sont regroup?s dans la province d\\\'Amakna, et ceux de ta race te renseigneront.');
INSERT INTO `npc_questions` VALUES (2283, '', '', '', '', 'Une histoire b?te... Nous ?tions avec des mercenaires Sram, et un pi?ge ? Meulou s\\\'est referm? au mauvais moment. Ca m\\\'a co?t? la moiti? de mon oreille, mais moi ?a va encore. Pour mon fr?re Kouy ?\\\'a ?t? plus dur...');
INSERT INTO `npc_questions` VALUES (2284, '191', '', '', '0', 'Salut ? toi ! Que puis-je pour toi ?');
INSERT INTO `npc_questions` VALUES (2285, '191', '', '', '0', 'Nos contr?es sont peupl?es de cr?atures toutes plus fascinantes les unes que les autres. Rien de tel que d\\\'aller ? la rencontre de la faune et de la flore locales pour parfaire tes connaissances zoologiques et botaniques. Un coeur l?ger, des intentions pures, ?a suffit ? les amadouer la plupart du temps.');
INSERT INTO `npc_questions` VALUES (2286, '191', '', '', '0', 'Une chose ? savoir cependant : Si par m?garde il t\\\'arrivait d\\\'offusquer l\\\'une d\\\'entre-elles, elle en voudra sans doute ? ta vie... Rien de bien m?chant, mais il est possible qu\\\'elle veuille se gaver de tes tripes ! Il est probable aussi qu\\\'elle souhaite broyer tes os ! Alors, ?coute moi bien....');
INSERT INTO `npc_questions` VALUES (2287, '191', '', '', '0', 'Tout comme toi, toutes les cr?atures ici-bas sont r?sistantes ou sensibles aux quatre ?l?ments primordiaux : air, terre, feu, eau. Apprends ? reconna?tre les forces et faiblesses de chacune (et les tiennes !). Et le Monde sera s?r pour toi. Ou presque.');
INSERT INTO `npc_questions` VALUES (2288, '', '', '', '', 'Je te le dirai bien... Mais ensuite, je devrai faire un noeud avec ta jolie petite langue rose pour que ne puisses en parler ? quiconque... *petit sourire pas engageant du tout*');
INSERT INTO `npc_questions` VALUES (2289, '', '', '', '', 'Il me semble que les ma?tres Osamodas ont pas mal de connaissances sur les cr?atures, mais je n\\\'en connais aucun personnellement...');
INSERT INTO `npc_questions` VALUES (2290, '', '', '', '', 'Une cr?ature poilue de la taille d\\\'un milimulou, qui s\\\'attaque aux bouftous la nuit ? Hmm, on dirait que l\\\'homme Ours a encore frapp?... Nous sommes au courant des agissements d\\\'un homme qui contr?le des Ours, sa puissance provient d\\\'un vieux manuscrit Osamodas. \\nSi tu veux le lui voler, et ainsi arr?ter le massacre de bouftous, il faudra l\\\'attaquer avec un bon groupe d\\\'aventuriers, sans quoi je ne pense pas qu\\\'il prenne le risque d\\\'utiliser ce livre en combat... \\nMais avant ?a, il te faudra trouver sa tani?re. Essaye de remonter sa piste, ce genre de cr?ature laisse toujours des traces derri?re elle...');
INSERT INTO `npc_questions` VALUES (2291, '', '', '', '', 'Beeeek ?');
INSERT INTO `npc_questions` VALUES (2292, '', '', '', '', 'Pas trop le temps, je suis occup?, l?...');
INSERT INTO `npc_questions` VALUES (2293, '', '', '', '', 'Huuum ? Je r?fl?chis... Laisse-moi s\\\'il te pla?t...');
INSERT INTO `npc_questions` VALUES (2294, '', '', '', '', '*le bouftou ne fait qu\\\'une bouch?e de la bi?re et sa chope* Glurp... Hic !');
INSERT INTO `npc_questions` VALUES (2295, '', '', '', '', 'Des glands empoisonn?s... non, ils sont s?rement trop malins pour ce pi?ge... Peut-?tre qu\\\'avec une autre poup?e... fichus ?cureuils... *grmbl*');
INSERT INTO `npc_questions` VALUES (2296, '', '', '', '', '*Chantonne* \\nJ\\\'entends le meulou, le lenald et la beletteeeuuhhh...');
INSERT INTO `npc_questions` VALUES (2297, '', '', '', '', '*chantonne* \\nJe fais des coupes, des p\\\'tites coupes, encore des p\\\'tites coupes...');
INSERT INTO `npc_questions` VALUES (2298, '', '', '', '', 'Maow !');
INSERT INTO `npc_questions` VALUES (2299, '', '', '', '', 'Tu n\\\'as pas fini de leur donner leur bi?re. Regarde celui-l?, il en a l\\\'eau ? la bouche...');
INSERT INTO `npc_questions` VALUES (2300, '', '', '', '', 'Ohhh... Je savais les Eniripsas susceptibles, mais quand m?me. Enfin, merci d\\\'avoir essay');
INSERT INTO `npc_questions` VALUES (2301, '', '', '', '', 'Nib? Lulle, l\\\'Alchimiste doit pouvoir concocter une bonne infusion ? base de fleur de Dzibi. C\\\'est savoureux tu verras...');
INSERT INTO `npc_questions` VALUES (2302, '', '', '', '', 'Oh voici ma pizaille v?g?tarienne ! J\\\'ai encore oubli? mon parchemin de fid?lit?, je n\\\'aurai d?cid?ment jamais ma pizaille offerte ! \\nJ\\\'esp?re que la Lactuta sativa qu\\\'ils ont utilis?e sera plus fra?che que la derni?re fois...');
INSERT INTO `npc_questions` VALUES (2303, '', '', '', '', 'Je crois que papa est revenu de sa r?union, il est retourn? pr?s du lac. \\nMerci encore pour l\\\'arakne');
INSERT INTO `npc_questions` VALUES (2304, '', '', '', '', 'Kof ! Kof ! Kof ! *vieille toux maladive venant du fond du gosier*');
INSERT INTO `npc_questions` VALUES (2305, '', '', '', '', 'Keuf ! Kof ! Keuf ! *?ructe bizarrement*');
INSERT INTO `npc_questions` VALUES (2306, '', '', '', '', 'Keuf ! Kof ! Keuf ! *?ructe bizarrement*');
INSERT INTO `npc_questions` VALUES (2307, '', '', '', '', 'Rhhh?keuf ! Keuf ! Snirfl... *haleine de Tofu pas saine du tout*');
INSERT INTO `npc_questions` VALUES (2308, '', '', '', '', 'Bon maintenant que tu poss?des ta propre ?p?e, ?quipe toi et va tuer deux arakn?es ! Tu me montreras ainsi de quoi tu es capable. Si tu t\\\'en montres digne, je te confierais ensuite une mission plus importante.');
INSERT INTO `npc_questions` VALUES (2309, '', '', '', '', 'Rhhh???aaatchaaah ! Snirfl *renifle bruyamment*');
INSERT INTO `npc_questions` VALUES (2310, '', '', '', '', 'Voici les faits : les Enutrofs ont requis notre aide. Depuis quelques temps, des ?v?nements ?tranges se produisent lors de leurs fouilles. Ils pr?sentent un danger, et qui dit danger dit Iop ! Vous ?tes maintenant par? ? leur pr?ter main forte. Rejoignez Gasdaure dans les galeries ! Et restez sur vos gardes...');
INSERT INTO `npc_questions` VALUES (2311, '', '', '', '', 'Euh, tu n\\\'as rien du tout ? Ni citron, ni cuisses de Bouftou ? Qu\\\'est-ce que tu attends ? Aller zou...');
INSERT INTO `npc_questions` VALUES (2312, '', '', '', '', 'Ugh! Tu n\\\'m\\\'as pas l\\\'air tr?s costaud toi... T\\\'es s?r que tu manges assez ?! J\\\'te propose un p\\\'tit job, histoire de t\\\'remplir un peu les poches, et surtout l\\\'estomac h?h?!...');
INSERT INTO `npc_questions` VALUES (2313, '', '', '', '', 'Oulah! Je crois apercevoir un semblant de muscles ! Ceci dit, c\\\'est pas encore ?a. Je vais mettre la barre un peu plus haut...');
INSERT INTO `npc_questions` VALUES (2314, '', '', '', '', 'Argh! Tu m\\\'as fait peur, j\\\'ai cru que c\\\'?tait encore un de ces rats d\\\'?go?tants... En parlant de rats, j\\\'ai p\\\'tet encore de quoi te remplir les poches... ');
INSERT INTO `npc_questions` VALUES (2315, '', '', '', '', 'T\\\'as d? remarquer qu\\\'il y a certaines choses ?tranges dans c\\\'te souterrain. Mais Gasdaure semble en savoir plus long qu\\\'moi sur cette affaire. Tu devrais lui en toucher deux mots...');
INSERT INTO `npc_questions` VALUES (2316, '', '', '', '', 'H?h?h????? ! Bien jou? ! Je vois qu\\\'on va pouvoir faire affaire ! Alors nous disions... *se frotte les mains*');
INSERT INTO `npc_questions` VALUES (2317, '', '', '', '', 'Pnj(543) et Message(2312)');
INSERT INTO `npc_questions` VALUES (2318, '', '', '', '', 'On fait d\\\'bons sandwiches avec des pattes d\\\'Araknes... pour peu qu\\\'on ne soit pas fin gourmet ! Je dirais m?me, qu\\\'pour survivre, c\\\'est indispensable d\\\'en poss?der soi-m?me. Et ? ce propos j\\\'aimerais renouveler mon stock. Tu peux me rapporter 10 pattes de ces bestioles ?... ?a devrait faire l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (2319, '', '', '', '', 'Il y\\\'a une bonne quantit? de tofus malades dans ces galeries. Les Eniripsas nous ont demand? de r?cup?rer quelques plumes pour des analyses. Le probl?me c\\\'est qu\\\'ils ne se laissent pas faire... Il m\\\'en faudrait un bon lot, en dehors du fait que les Eniripsas en ont besoin, ?a rapporte un max ! 10 plumes de ces Tofus malades devraient faire l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (2320, '', '', '', '', 'Alors ca y est tu as amen? l\\\'arc ? Nib? Lulle ?');
INSERT INTO `npc_questions` VALUES (2321, '', '', '', '', 'Mais tu n\\\'as rien fait ? Va voir Nib? Lulle, il devrait trouver un truc pour ton arc...');
INSERT INTO `npc_questions` VALUES (2322, '', '', '', '', 'Les Eniripsas m\\\'ont dit qu\\\'il n\\\'y avait aucun \\\"nageant infecte cieux\\\" dans les plumes de tofus malades... je n\\\'ai pas bien compris ce que cela signifiait. Mais quelque chose me dit qu\\\'il n\\\'y a rien ? craindre. Leurs oeufs pourraient fortement int?resser les Eniripsas... et moi par la m?me occasion, h?h?h? ! Alors... nous disons... 10 oeufs de Tofus pourraient faire l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (2323, '', '', '', '', 'Nos amis Cr?, y zont de dr?les d\\\'id?es parfois. Figure toi qu\\\'ils profitent d\\\'un \\\"nageant infecte cieux\\\" cont\\\'nu dans les pattes de ces Araknes. Z\\\'en font des fl?ches empoisonn?es ! Bizarre, mais bon, ?a paye... et plut?t bien... Si ?a t\\\'int?resse de t\\\'faire un peu de bl?, rapporte moi 20 pattes de ces Araknes. Quequ\\\'chose me dit que j\\\'vais d\\\'voir jeter mes sandwiches... *soupir*');
INSERT INTO `npc_questions` VALUES (2324, '', '', '', '', 'De quoi ? ah oui les rats d\\\'?goutants... *soupir*... ils nuisent gravement ? mes affaires. Il y en a plein, dans les profondeurs des galeries. Je n\\\'ose pas trop les approcher, mais peut-?tre toi... tu pourrais me rendre ce service. En tuant au moins 14 de ces rats par petits groupes de un, deux ou trois. Tu devrais faire assez peur aux autres et les affaires pourront reprendre !');
INSERT INTO `npc_questions` VALUES (2325, '', '', '', '', 'T\\\'as d? les rencontrer, ces vermines... P\\\'tet m?me que t\\\'en as combattu ? Apparement quand on les tue, y reviennent par centaines... incroyab\\\' ! Mais encore une fois le vieux Ant a trouv? la solution pour s\\\'y r\\\'trouver ! hahaha !... ahem... z\\\'ont des crocs tr?s reluisants, et les Xelors semblent particuli?rement int?ress?s par celles-ci... probablement pour mettr\\\' des aiguilles sur leurs sabliers ! ahaha ! Bon, t\\\'vois o? j\\\'veux en venir n\\\'est-ce pas ? J\\\'en ?tais s?r ! J\\\'pense que 10 de ces objets feront l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (2326, '', '', '', '', 'HUmff ? gnark rhhhhr :');
INSERT INTO `npc_questions` VALUES (2327, '', '', '', '', 'zzZZZ...  hummmM ket la ?');
INSERT INTO `npc_questions` VALUES (2328, '1932', '', '', '0', 'Snifff ! *elle ?touffe un gros sanglot*');
INSERT INTO `npc_questions` VALUES (2329, '', '', '', '', 'Mon ?cureuil s\\\'est encore ?chapp? ! *sniffff*  \\nIl n\\\'arr?te pas de se sauver... Et j\\\'en ai assez ! Cette fois-ci, j\\\'ai mis un avis de recherche pour qu\\\'on le retrouve... Va d\\\'abord le lire. Si tu le croises ensuite dans Astrub, et que tu essaies de l\\\'attraper, il va s?rement se d?fendre... Il est adorable - quoique les chachas du quartier en ont peur...');
INSERT INTO `npc_questions` VALUES (2330, '1936;1937', '', '', '0', 'Bonjour, et bienvenue dans mon h?tel de vente. J\\\'esp?re que vous y trouverez tout ce que vous cherchez. \\nEn quoi puis-je vous ?tre utile ?');
INSERT INTO `npc_questions` VALUES (2331, '1954', '', '', '0', 'Il y a plusieurs r?gles importantes ? conna?tre concernant la vente d\\\'objets. \\n \\nPour vendre des objets dans un h?tel de vente, vous devez choisir le prix et la quantit? d\\\'objets que vous voulez vendre. \\nMais il faut faire attention, car une taxe sera pr?lev?e lors de la mise en vente. \\nCette taxe ne sera pas r?cup?r?e lorsque vous aurez vendu l\\\'objet ou lorsque vous d?ciderez de reprendre votre objet avant qu\\\'il ne soit vendu.');
INSERT INTO `npc_questions` VALUES (2332, '4840', '', '', '', 'Pour acheter des objets dans les h?tels de vente, vous devez d\\\'abord choisir quel type d\\\'objet puis la quantit? d\\\'objets que vous recherchez. \\nSi plusieurs objets identiques sont mis en vente, seul le moins cher vous est propos');
INSERT INTO `npc_questions` VALUES (2333, '', '', '', '', 'Qu\\\'est ce que tu veux toi ? Si tu tiens ? ta vie, d?gage ! Et tu n\\\'as rien vu...sinon...');
INSERT INTO `npc_questions` VALUES (2334, '', '', '', '', 'Cette canaille ne me fait pas peur ! Je vais la r?duire en bouillie, si tu as peur va-t-en, tu me g?nerais plus qu\\\'autre chose. Je dois livrer cette bi?re et je la livrerai !');
INSERT INTO `npc_questions` VALUES (2335, '', '', '', '', 'Si tu cherches une mousse qui te remplisse bien l\\\'vendre... t\\\'as sonn? ? la bonne porte. La bi?re d\\\'Astrub n\\\'est pas connue pour sa l?g?ret?. Hahaha... Ach?te-m\\\'en un peu!');
INSERT INTO `npc_questions` VALUES (2336, '', '', '', '', 'Je... aphone... revenez... plus tard... !');
INSERT INTO `npc_questions` VALUES (2337, '', '', '', '', 'Une rose obscure, dis-tu ! Quelle nouvelle palpitante ! La mutation des fleurs ?volue donc encore, pour former des esp?ces de plus en plus puissantes ! \\nD\\\'apr?s les informations que tu m\\\'as apport?es, j\\\'ai pens? ? une petite exp?rience que je voudrais que tu effectues pour moi. \\nJ\\\'aimerais que tu utilises ces graines de rose obscure dans les champs d\\\'Astrub. D\\\'apr?s mes calculs si tu les plantes l?-bas sous un rocher, on devrait avoir une petite surprise ! Haha !');
INSERT INTO `npc_questions` VALUES (2338, '', '', '', '', 'Ces souterrains n\\\'sont pas s?rs... Les Tofus qui en reviennent sont malades ! Tu ne devrais pas tra?ner par ici... c\\\'est dangereux pour les petits jeunes comme toi. Et le port du casque est obligatoire, surtout si tu n\\\'as pas d\\\'assurance.');
INSERT INTO `npc_questions` VALUES (2339, '', '', '', '', 'Hmm en effet, c\\\'est bien le manuscrit Osamodas d\\\'invocation de l\\\'ours, un grand merci ? toi de nous l\\\'avoir rendu. Tu peux pr?venir Menge Paca, que son troupeau ne craint plus rien !');
INSERT INTO `npc_questions` VALUES (2340, '', '', '', '', 'Tu as trouv? d\\\'o? venait la b?te qui ravage mon troupeau ? Reviens me voir quand tu seras certain qu\\\'il soit neutralis? !');
INSERT INTO `npc_questions` VALUES (2341, '', '', '', '', 'J\\\'me d\\\'mande si les Eniripsas vont trouver quequ\\\'chose de louche dans ces pattes d\\\'Araknes... je ne voudrais pas avoir ? m\\\'s?parer de tout mon stock...*soupir*');
INSERT INTO `npc_questions` VALUES (2342, '1948', '', '', '0', 'Nous sommes d?bord?s, nous autres les paysans ! Heureusement que les r?coltes s\\\'annoncent plut?t bonnes.');
INSERT INTO `npc_questions` VALUES (2343, '', '', '', '', 'La guigne ! Impossible de les approcher, t\\\'as vu ?... ');
INSERT INTO `npc_questions` VALUES (2344, '', '', '', '', 'Tu veux une paire de ciseaux forg?e par mes soins ? Hmm c\\\'est encore cette charmante mademoiselle Pouque qui a cass? ses ciseaux, h?h? ? \\nPour cela il me faudrait trois morceaux de fer, mais je n\\\'en ai plus...  Demande ? un mineur, il t\\\'aidera ? trouver ?a. Quand tu auras trouv? ce dont j\\\'ai besoin, je te ferai ces ciseaux gratuitement !');
INSERT INTO `npc_questions` VALUES (2345, '', '', '', '', '* Deudoin? sort deux doigts de sa poche, attrape les morceaux de fer un ? un, et avec une force incroyable les assemble pendant que ses deux autres doigts mart?lent le fer ? coup de marteau *   \\nVoil? vos ciseaux m\\\'sieur, faites une bise ? Pouque de ma part !');
INSERT INTO `npc_questions` VALUES (2346, '', '', '', '', 'Allez d?gage maintenant');
INSERT INTO `npc_questions` VALUES (2347, '1953', '', '', '0', 'L\\\'alchimiste est un manipulateur d\\\'?l?ments, magiques ou non. Il transforme des mati?res en d\\\'autres. Mais surtout, ne voyez pas l\\\'alchimiste comme un rat de laboratoire. Un vrai alchimiste passe autant de temps dans son bureau qu\\\'? voyager ? travers le monde ? la recherche d\\\'ingr?dients rares. Et je peux vous dire, par exp?rience, que lorsque notre r?serve de poils de mulou est vide, il faut prendre son courage ? deux mains!');
INSERT INTO `npc_questions` VALUES (2348, '2120', '', '', '0', 'Croyez-vous qu\\\'il suffit de parler pour pouvoir exercer ce m?tier ? C\\\'est que vous n\\\'avez pas bien compris l\\\'essence m?me du m?tier. Si vous souhaitez vraiment devenir alchimiste, allez voir le chef des instructeurs en Amakna, je vous indique sa position sur votre carte si vous le d?sirez.');
INSERT INTO `npc_questions` VALUES (2349, '', '', '', '', 'Vous ne pouvez pas vendre autant d\\\'objets que vous le d?sirez en m?me temps. \\nVous devez attendre d\\\'en avoir vendu certains pour en remettre d\\\'autres en vente. \\nAu bout d\\\'un certain temps, les objets que vous avez mis en vente, s\\\'ils n\\\'ont pas ?t? vendus, sont retir?s de l\\\'h?tel de vente, et sont rapport?s directement dans votre coffre en banque.');
INSERT INTO `npc_questions` VALUES (2350, '', '', '', '', 'Y\\\'a du gros monstre par l?-bas... Pire, c\\\'est des esp?ces inconnues de mon grand papy, et qui fileraient la p?toche ? un Iop ! Et pis y\\\'a toutes ces vieilles l?gendes l?...');
INSERT INTO `npc_questions` VALUES (2351, '', '', '', '', 'Ben tu sais bien, les Dofus, tout ?a... Moi ce que j\\\'en dis, c\\\'est que des oeufs de Dragon qui donnent des pouvoirs, ?a court pas les ruelles... Pis avec tous ces aventuriers qui d?barquent, c\\\'est la ru?e vers l\\\'oeuf ! Bon, c\\\'est pas tout ?a... Je te souhaite bonne route ! Et que les pierres soient douces sous tes pieds !');
INSERT INTO `npc_questions` VALUES (2352, '', '', '', '', 'Voyons voir...Oh ! Vous souhaitez vraiment devenir alchimiste ? Oui je suis bien formateur. Tr?s bien alors, ?coutez bien : un alchimiste accompli doit savoir lire l\\\'intensit?, en essence magique, de n\\\'importe quel objet, et pouvoir la manipuler ? sa guise. Posez donc un regard nouveau sur tous les objets pass?s et futurs en votre possession. ');
INSERT INTO `npc_questions` VALUES (2353, '', '', '', '', 'Ben... tout ce que je sais, c\\\'est que le conseil nous a d\\\'mand? d\\\'patrouiller dans ces fichus souterrains... Y doivent en savoir plus long que moi l? d\\\'ssus ! Pour s?r, et c\\\'est pas les vieilles l?gendes qui vont calmer l\\\'affaire...');
INSERT INTO `npc_questions` VALUES (2354, '', '', '', '', '... Dans les temps pass?s y aurait eu une sacr?e castagne du c?t? d\\\'Amakna... mais moi, j\\\'suis un Astrub?en pur souche. J\\\'ai jamais rien vu d\\\'tout ?a ! En tous cas, j\\\'sais qu\\\'?a bouge par l?-bas, et ?a ne me dit rien qui vaille... Retourne voir Gasdaure, elle en sait plus qu\\\'elle n\\\'en dit !');
INSERT INTO `npc_questions` VALUES (2355, '', '', '', '', 'Voil? j\\\'ai sign?e ce petit papier... C\\\'est officiel : tu es maintenant alchimiste. Retourne voir Nib? Lulle si tu as des questions.');
INSERT INTO `npc_questions` VALUES (2356, '', '', '', '', 'J\\\'aimerais que tu utilises ces graines de Vhan r?cup?r?es de cette Rose obscure dans les champs d\\\'Astrub. D\\\'apr?s mes calculs si tu les plantes ? cet endroit sous un rocher, on devrait avoir une petite surprise ! Haha !');
INSERT INTO `npc_questions` VALUES (2357, '1962;1967;1968', '', '', '0', 'Qu\\\'est-ce que tu veux ?');
INSERT INTO `npc_questions` VALUES (2358, '1963', '', '', '0', 'Je suis chasseur ?a ne se voit pas ? D\\\'ailleurs, va voir ailleurs si j\\\'y suis...');
INSERT INTO `npc_questions` VALUES (2359, '1964', '', '', '0', 'Chasser n\\\'est pas si facile ! Il faut avoir la bonne arme pour bien frapper l\\\'animal. Si l\\\'animal est trop bless? ou mal tu?, le chasseur ne pourra pas r?colter les morceaux de viande int?ressants qu\\\'il pourrait vendre par la suite.');
INSERT INTO `npc_questions` VALUES (2360, '', '', '', '', 'Ecoute bien Wilde, c\\\'est mon fr?re. Il explique vachement bien et quand y parle on comprend tout c\\\'qui dit ! D?j? quand j\\\'?tais tout petit, y m\\\'expliquait tout un tas de trucs super compliqu?s et je les comprenais... Et l? y m\\\'a dit : pas question qu\\\'on bouge tant que y\\\'a un rat dans les parages ! Alors t\\\'y retournes dare dare !');
INSERT INTO `npc_questions` VALUES (2361, '1965', '', '', '', 'Hol?, je t\\\'ai dit que ce n\\\'?tait pas un m?tier facile et tu veux quand m?me devenir chasseur ? Pour pouvoir manipuler les armes de chasseur il faut une certaine dext?rit?, prouve moi cette dext?rit? et j\\\'te nommerai chasseur.');
INSERT INTO `npc_questions` VALUES (2362, '1966', '', '', '', 'Tr?s bien si tu le souhaites autant...Tu vas devoir tuer un Bouftou tr?s rapidement : En fait j\\\'te donne deux minutes. Prouve-moi que t\\\'en es capable et je t\\\'nommerai chasseur.');
INSERT INTO `npc_questions` VALUES (2363, '', '', '', '', 'Patrouillez, patrouillez qui disaient ! On a failli y rester nous aut\\\' !');
INSERT INTO `npc_questions` VALUES (2364, '', '', '', '', 'Ouai pas mal... Tr?s bien, comme tu le souhaitais je vais te nommer chasseur. Tu devras m\\\'acheter un outil de chasseur pour r?cup?rer les morceaux de tes proies.');
INSERT INTO `npc_questions` VALUES (2365, '', '', '', '', 'Par l?-bas, c\\\'est Amakna. J\\\'va te dire, y commence ? y\\\'avoir de dr?les d\\\'histoires sur c\\\'qui s\\\'passe de s\\\'c?t?. Mais j\\\'vois bien ? ta t?te qu\\\'c\\\'est pas fait pour te d?plaire, hein ?');
INSERT INTO `npc_questions` VALUES (2366, '', '', '', '', 'Y\\\'a du gros monstre par l?-bas... Pire, c\\\'est des esp?ces inconnues de mon grand papy, et qui fileraient la p?toche ? un Iop ! Et pis y\\\'a toutes ces vieilles l?gendes l?...');
INSERT INTO `npc_questions` VALUES (2367, '', '', '', '', 'Ben tu sais bien, les Dofus, tout ?a... Moi ce que j\\\'en dis, c\\\'est que des oeufs de Dragon qui donnent des pouvoirs, ?a court pas les ruelles... Pis avec tous ces aventuriers qui d?barquent, c\\\'est la ru?e vers l\\\'oeuf ! Bon, c\\\'est pas tout ?a... Je te souhaite bonne route ! Et que les pierres soient douces sous tes pieds !');
INSERT INTO `npc_questions` VALUES (2368, '', '', '', '', 'Comment ? On s\\\'en retourne l? ? Mais tu n\\\'as pas tu? le rat ! Ca va pas non ?');
INSERT INTO `npc_questions` VALUES (2369, '1971;1972', '', '', '0', 'Bienvenue ? la cit? d\\\'Astrub noble aventurier. \\nSi tu as des questions sur la ville et ses alentours, les mercenaires feront de leur mieux pour r?pondre ? tes questions.');
INSERT INTO `npc_questions` VALUES (2370, '1975;1976;1977;1978;2025;545', '', '', '0', 'Je t\\\'?coute, de quel b?timent d\\\'h?tel des ventes cherches-tu l\\\'emplacement ?');
INSERT INTO `npc_questions` VALUES (2371, '5730', '', '', '', 'Ah pour ?a il faut demander ? Ahenn, elle se situe au rez-de-chauss?e du b?timent des m?tiers. Voulez-vous que je vous indique son emplacement ?');
INSERT INTO `npc_questions` VALUES (2372, '', '', '', '', 'Tiens tiens, v\\\'la la terreur du rat d\\\'?go?t ! Avec c\\\'que tu lui as mis, tu dois ?tre connu de tous les rats d\\\'Astrub maint\\\'nant ! Qu\\\'est-ce qui t\\\'am?ne ?');
INSERT INTO `npc_questions` VALUES (2373, '', '', '', '', 'Des vieilles l?gendes tout ?a ! Laisse toi pas r\\\'tourner la caboche com\\\' tous les aut\\\' ! Y ne savent pas la moiti? de c\\\'que j\\\'sais, et y r\\\'muent ciel et terre pour trouver des oeufs... Rh??? kof kof *toux silicos?e*');
INSERT INTO `npc_questions` VALUES (2374, '', '', '', '', 'Hummm... Le monde des Onze est en train d\\\'changer, ouais. Ainsi tu convoites les Dofus ? Tu devras d\\\'abord amadouer leurs gardiens, ou les combattre... Sont puissants, les gardiens... et jaloux... C\\\'est des aventuriers exp?riment?s qui pourront s\\\'y frotter !');
INSERT INTO `npc_questions` VALUES (2375, '', '', '', '', 'Je suis sculpteuse sur bois, experte en sp?cialit? baguette, b?ton et surtout arc, que j\\\'appr?cie particuli?rement. \\nLe m?tier de sculpteur est assez dur en soi, la mati?re premi?re est assez rare, et il faut trouver un b?cheron chevronn? pour s\\\'approvisionner correctement.');
INSERT INTO `npc_questions` VALUES (2376, '1983;1982;1984', '', '', '0', 'Je ne peux vous enseigner qu\\\'une sp?cialit? : sculpteur de baguette, de b?ton ou d\\\'arc. Cela dit, si vous ?tes courageux et que vous avez beaucoup de temps, rien ne vous emp?che d\\\'en pratiquer deux.');
INSERT INTO `npc_questions` VALUES (2377, '1986;1985', '', '', '', 'Etes vous s?r de vouloir d?buter une carri?re de sculpteur d\\\'Arc ?');
INSERT INTO `npc_questions` VALUES (2378, '1988;1987', '', '', '', 'Etes vous s?r de vouloir d?buter une carri?re de sculpteur de B?ton ?');
INSERT INTO `npc_questions` VALUES (2379, '1990;1989', '', '', '', 'Etes vous s?r de vouloir d?buter une carri?re de sculpteur de Baguette ?');
INSERT INTO `npc_questions` VALUES (2380, '4840', '', '', '', 'Etre forgeron cela demande beaucoup de temps, et pas mal de connaissances. Impossible d\\\'?tre forgeron sans conna?tre un bon mineur et un bon b?cheron pour les mati?res premi?res. Enfin il y a toujours l\\\'H?tel de Vente pour r?cuperer tout ?a ? bon prix, mais moi j\\\'aime pas trop.');
INSERT INTO `npc_questions` VALUES (2381, '1995;1993;1997;1996;1994', '', '', '', 'Hol?, on ne devient pas un forgeron comme moi tout de suite. Tu dois choisir quelles armes tu d?cides de forger. Rien ne t\\\'emp?che d\\\'en prendre plusieurs, mais cela va te prendre forc?ment une partie de ton temps.');
INSERT INTO `npc_questions` VALUES (2382, '1999;1998', '', '', '', 'Etes-vous s?r de vouloir d?buter une carri?re de forgeur d\\\'Ep');
INSERT INTO `npc_questions` VALUES (2383, '2001;2000', '', '', '', 'Etes-vous s?r de vouloir d?buter une carri?re de forgeur de Dagues ?');
INSERT INTO `npc_questions` VALUES (2384, '2003;2002', '', '', '', 'Etes-vous s?r de vouloir d?buter une carri?re de forgeron de Pelle ?');
INSERT INTO `npc_questions` VALUES (2385, '2005;2004', '', '', '', 'Etes-vous s?r de vouloir d?buter une carri?re de forgeron de Marteau ?');
INSERT INTO `npc_questions` VALUES (2386, '2007;2006', '', '', '', 'Etes-vous certain de vouloir d?buter une carri?re de forgeur de hache ?');
INSERT INTO `npc_questions` VALUES (2387, '2010;2009', '', '', '', 'En es-tu s?r ? Ce m?tier est assez difficile, il demande beaucoup de temps et d\\\'argent ');
INSERT INTO `npc_questions` VALUES (2388, '', '', '', '', 'Tr?s bien, te voil? mon apprenti. Pour pratiquer ton m?tier tu dois acheter un sertisseur, j\\\'en vends ? bas prix si cela t\\\'interesse. Equipe le et tu pourras utiliser les tables de travail con?ues sp?cialement pour les bijoutiers. Tu les reconnaitras vite, il y a toujours quelques joyaux qui trainent dessus. Comme dans cette salle d\\\'ailleurs.');
INSERT INTO `npc_questions` VALUES (2389, '', '', '', '', 'Tiens, v\\\'l? le retour des renforts ! Alors tu t\\\'en es tir? ? ce que je vois ! Et les fr?res Pyrite aussi... mais ils sont dans un dr?le d\\\'?tat les pauvres ! Bah... le bon air de Pandala les remettra d\\\'aplomb ! Tu devrais aller y faire un tour, tu m\\\'as l\\\'air p?lot toi aussi... Va voir Surivitna, il est le Shaman de Pandala !');
INSERT INTO `npc_questions` VALUES (2390, '4840', '', '', '', 'Tr?s bien te voil? devenu mon apprenti. D?bute par des petites armes, je les ai not?s dans ton carnet de forge. Pour forger il te faut un marteau con?u sp?cialement pour l\\\'arme que tu souhaites forger. J\\\'en vends de toute sorte si tu veux. Ne te trompe pas dans le choix du marteau ! Une fois celui-ci en main, utilise nos ?tablis pour forger ce que tu souhaites.');
INSERT INTO `npc_questions` VALUES (2391, '2013;2011;2037', '', '', '0', 'Bonjour l\\\'ami, si tu viens me voir ici, c\\\'est que toi aussi tu as la fi?vre du p?cheur ! Ou alors c\\\'est pour parler avec moi d\\\'amour et d\\\'autres choses.');
INSERT INTO `npc_questions` VALUES (2392, '', '', '', '', 'Alors Mercenaire, tu es en qu?te de proies et de kamas ? Ca tombe bien ! Lis les Avis de Recherche, ils te renseigneront sur les individus qu\\\'il faut nous ramener.');
INSERT INTO `npc_questions` VALUES (2393, '', '', '', '', 'Tr?s bien te voil? devenu mon apprenti. D?bute par des petites cr?ations, j\\\'en ai dessin? les plans dans ton carnet. Pour sculpter il te faut des tailladeuses con?ues sp?cialement pour l\\\'oeuvre que tu souhaites sculpter. J\\\'en vends de toute sorte si tu veux. Ne te trompe pas dans le choix de tailladeuse ! Une fois celle-ci en main, utilise nos ?tablis pour sculpter ce que tu souhaites.');
INSERT INTO `npc_questions` VALUES (2394, '2024', '', '', '', 'Tr?s bien, mais avant, tu vas devoir me rendre un petit service. Le poissonier a des app?ts pour moi, j\\\'en ai besoin tr?s rapidement. Voil? le deal : ram?ne-les en moins de 5 minutes et je t\\\'apprendrai les ficelles du m?tier.');
INSERT INTO `npc_questions` VALUES (2395, '', '', '', '', 'Hmpf, je suis sculpteur de baguettes mais surtout expert b?cheron. Aucun arbre ne me r?siste, pas m?me le grand Orme. Ce m?tier est plut?t facile quand on a le temps. Il faut juste conna?tre les bons emplacements.');
INSERT INTO `npc_questions` VALUES (2396, '2017;2016', '', '', '', 'Es-tu s?r de vouloir devenir b?cheron ? Je peux te faire devenir mon apprenti mais il faut que tu sois motiv? !');
INSERT INTO `npc_questions` VALUES (2397, '', '', '', '', 'Te voil? mon apprenti, ne me d??ois pas ! Pour couper des arbres, il te faut une bonne hache, tu peux commencer par acheter l\\\'une des miennes, je te ferai un bon prix. Une fois celle-ci en main, choisis simplement un arbre et coupe-le ! Enfin, ne choisis pas d\\\'arbre trop dur, tiens je te note dans ton carnet de b?cheron les arbres simples ? couper qui te permettront de te faire la main.');
INSERT INTO `npc_questions` VALUES (2398, '2029;2030;2031;2032;2033;2034;536', '', '', '0', 'Je t\\\'?coute, de quel b?timent d\\\'h?tel des ventes cherches-tu l\\\'emplacement ?');
INSERT INTO `npc_questions` VALUES (2399, '2028;2027', '', '', '0', 'Miner c\\\'est toute ma vie, le clinquement des pioches contre la pierre, le reflet de la pierre pr?cieuse que l\\\'on d?couvre, ha je crois que je ne m\\\'en lasserai jamais h?h');
INSERT INTO `npc_questions` VALUES (2400, '', '', '', '0', 'Mineur c\\\'est une vocation, cela prend beaucoup de temps, mais ce m?tier peut s\\\'av?rer avec le temps ?tre tr?s rentable. Au d?but, on ne d?niche que du fer ou de la vulgaire caillasse... C\\\'est une question de temps. Mais avec de l\\\'exp?rience on arrive ? extraire de l\\\'or et parfois m?me, des pierres pr?cieuses !');
INSERT INTO `npc_questions` VALUES (2401, '2036;2035', '', '', '0', 'Es-tu s?r de vouloir passer beaucoup de temps dans le noir ? Devenir mineur est vraiment une vocation tu sais ?');
INSERT INTO `npc_questions` VALUES (2402, '', '', '', '', 'Te voil? un apprenti mineur maintenant ! Ah il te faut une pioche pour miner, c\\\'est indispensable. Je peux t\\\'en fournir une pas ch?re si tu le souhaites. Une fois celle-ci en main il te suffira de tailler la roche. Commence par des gisements faciles, je te les note sur ton carnet de mineur. Si tu tentes des gisements plus durs ou plus pr?cieux, tu risques de perdre gros.');
INSERT INTO `npc_questions` VALUES (2403, '2043;2044', '', '', '0', 'Hmm, l\\\'odeur du cuir tann? me fait vibrer, oh pardon ! Je ne veux pas vous effrayer, je suis Ygat, le meilleur cordonnier de la r?gion. Ceinture, chaussure, je peux tout faire !');
INSERT INTO `npc_questions` VALUES (2404, '', '', '', '', 'Cordonnier est un m?tier difficile, cela prend du temps et de l\\\'argent. Il vous faut de bons contacts pour pouvoir obtenir tout le cuir et les mati?res premi?res n?cessaires ? la confection de bonnes ceintures ou de bonnes bottes. Mais cela paye croyez moi !');
INSERT INTO `npc_questions` VALUES (2405, '2046;2045', '', '', '0', 'Etes vous s?r de vouloir devenir Cordonnier ? ');
INSERT INTO `npc_questions` VALUES (2406, '', '', '', '', 'Ahah un apprenti de plus ! Pour commencer votre m?tier il va vous falloir acqu?rir un coupe cuir indispensable. Je peux vous en vendre un ? l\\\'occasion. Une fois celui-ci en main, utilisez nos confortables ?tablis sp?cialement ?tudi?s pour faciliter la coupe du cuir. Commencez par des mod?les simples, tenez je vous les note dans votre carnet de Cordonnier.');
INSERT INTO `npc_questions` VALUES (2407, '2047', '', '', '', 'Oui, que voulez-vous ?');
INSERT INTO `npc_questions` VALUES (2408, '', '', '', '', 'Ah je vois, les appas de Kana Petch. Tenez et d?p?chez-vous, il est tr?s peu patient.');
INSERT INTO `npc_questions` VALUES (2409, '', '', '', '', 'Qu\\\'as tu fais de la paire que je t\\\'ai donn?e? M?me s\\\'ils sont abim?s, ils ont une certaine valeur... Si tu en veux une autre paire, cela te co?tera 50 kamas...');
INSERT INTO `npc_questions` VALUES (2410, '', '', '', '', 'Salut, je ne suis qu\\\'un jeune apprenti... Si tu veux en savoir plus sur notre art, va voir Nib? Lulle. Il passe tout son temps ? l\\\'h?tel de vente depuis sa r?cente ouverture.');
INSERT INTO `npc_questions` VALUES (2411, '', '', '', '', 'Salut, je ne suis qu\\\'un jeune apprenti... Si tu veux en savoir plus sur notre art, va voir Deudoin?. Il passe tout son temps ? l\\\'h?tel de vente depuis sa r?cente ouverture.');
INSERT INTO `npc_questions` VALUES (2412, '2050;2051', '', '', '0', 'Bonjour, vous cherchez un travail ? Si c\\\'est le cas vous ?tes l? o? il faut. Je peux vous renseigner sur les diff?rents m?tiers, ainsi que vous renseigner sur la localisation d\\\'un ?ventuel ma?tre.');
INSERT INTO `npc_questions` VALUES (2413, '2051;2052', '', '', '0', 'Nous divisons les m?tiers en deux grandes cat?gories : les m?tiers de r?colte et les m?tiers d\\\'artisanat. La seconde cat?gorie ne peut rien faire sans les premiers.  \\nDans les m?tiers de r?colte on trouve : les paysans, les b?cherons, les p?cheurs, les chasseurs et les mineurs. \\nDans les m?tiers d\\\'artisanat on trouve : les diff?rents forgeurs, les diff?rents sculpteurs, les bijoutiers, les cordonniers et les tailleurs. \\nL\\\'alchimie poss?de le statut particulier d\\\'?tre ? la fois un m?tier de r?colte et d\\\'artisanat.');
INSERT INTO `npc_questions` VALUES (2414, '', '', '', '', 'Un m?tier de r?colte consiste toujours ? r?cuperer une mati?re premi?re directement ? la source. Ainsi un mineur va aller piocher les veines de m?tal dans les mines, l\\\'alchimiste ira r?cup?rer des fleurs dans la for?t et ainsi de suite. Cette mati?re premi?re, apr?s une l?g?re transformation, du bl? en farine par exemple, est toute pr?te pour la vente. Elle servira en particulier aux m?tiers d\\\'artisanat.');
INSERT INTO `npc_questions` VALUES (2415, '', '', '', '', 'Le m?tier d\\\'artisan consiste ? cr?er des objets ? partir de mati?res premi?res le plus souvent achet?es aux personnes ayant un m?tier de r?colte, mais aussi avec des mat?riaux rares, que l\\\'aventurier pourra trouver au cours de ses p?r?grinations. C\\\'est donc un m?tier plus difficile, qui demande plus de ressources financi?res qu\\\'un m?tier de r?colte. Mais cela en vaut la peine.');
INSERT INTO `npc_questions` VALUES (2416, '', '', '', '', 'Salut, je ne suis qu\\\'une jeune apprentie... Si tu veux en savoir plus sur notre art, va voir Enileda, elle est notre mod?le ? tous. Elle passe tout son temps ? l\\\'h?tel de vente depuis sa r?cente ouverture.');
INSERT INTO `npc_questions` VALUES (2417, '2055;205', '', '', '0', 'Vous d?sirez des informations pr?cises sur un type de m?tier particulier ? A quelle cat?gorie appartient-il ?');
INSERT INTO `npc_questions` VALUES (2418, '2060;2056;2059;2058;206', '', '', '0', 'Lequel d\\\'entre eux ?');
INSERT INTO `npc_questions` VALUES (2419, '2086;2083;2067;2066;2088;2062;2063;206', '', '', '0', 'Quel m?tier en particulier ?');
INSERT INTO `npc_questions` VALUES (2420, '', '', '', '', 'Ce m?tier convient bien aux petits jeunes dans le dur monde des m?tiers. Assez facile et peu couteux, son principal inter?t est de faire de la farine pour les boulangers.');
INSERT INTO `npc_questions` VALUES (2421, '', '', '', '', 'Ce m?tier consiste ? couper des arbres bien ?videmment. Le bois ainsi r?colt? sert dans de nombreuses recettes de m?tiers d\\\'artisans, du sculpteur comme mati?re premi?re ? leurs b?tons, baguettes ou arcs, au forgeron comme mati?re secondaire pour ses manches d\\\'armes. Les applications sont diverses et la demande est grande. Les arbres sont cependant longs ? couper et certains assez rares.');
INSERT INTO `npc_questions` VALUES (2422, '', '', '', '', 'Le mineur r?colte le m?tal qui servira comme mati?re premi?re aux bijoutiers et aux forgerons. Certaines de leurs pierres seront aussi convoit?es pour leur magie. En prime le mineur n\\\'est pas ? l\\\'abri de d?nicher une pierre pr?cieuse comme le diamant avec un peu de chance. Il faut cependant savoir que les mines sont assez rares et que de nombreux mineurs se les disputent.');
INSERT INTO `npc_questions` VALUES (2423, '', '', '', '', 'Le m?tier de p?cheur r?clame plus de patience que n\\\'importe quel m?tier. Basiquement un p?cheur attrape des poissons qu\\\'il videra avant de les revendre aux poissonniers. Mais attraper du poisson n\\\'est pas facile au d?but. Il faut faire attention ? l\\\'heure o? l\\\'on p?che, ? l\\\'endroit...Et m?me ainsi on n\\\'est jamais ? l\\\'abri d\\\'une prise nulle.');
INSERT INTO `npc_questions` VALUES (2424, '', '', '', '', 'S?rement le plus dur des m?tiers de r?colte, et le plus diff?rent. Le chasseur trouve sa mati?re premi?re directement sur les monstres .Cela est un avantage lorsque l\\\'on est un aventurier solide qui d?cime les rangs des monstres, puisque l\\\'on pratique son m?tier en m?me temps que son hobby. On dit que certains chasseurs iraient m?me chasser du dragon.');
INSERT INTO `npc_questions` VALUES (2425, '', '', '', '', 'Il existe plusieurs types de forgerons, un par type d\\\'armes forg?es : ?p?es, dagues, pelles, marteaux, haches. Ces m?tiers utilisent beaucoup de m?taux et un peu de bois. Comme tout m?tier d\\\'artisanat il faut pas mal d\\\'argent ou de connaissances pour poursuivre son apprentissage. Mais tout le monde reconnait que les meilleures armes du monde sont forg?es par les sp?cialistes forgerons.');
INSERT INTO `npc_questions` VALUES (2426, '', '', '', '', 'Il existe plusieurs types de sculpteurs, un par type d\\\'armes sculpt?es : b?tons, baguettes, armes. Ces m?tiers utilisent beaucoup de bois et un peu de mati?res diverses. Comme tout m?tier d\\\'artisanat il faut pas mal d\\\'argent ou de connaissances pour poursuivre son apprentissage. Mais tout le monde reconnait que les meilleures armes en bois du monde sont sculpt?es par les sp?cialistes sculpteurs.');
INSERT INTO `npc_questions` VALUES (2427, '', '', '', '', 'Le bijoutier fabrique des anneaux et des colliers, le plus souvent magiques. Du simple anneau de m?tal aux colliers conf?rant de  terribles pouvoirs ?l?mentaires, ce m?tier puise son essence dans le m?tal, les pierres pr?cieuses et les mat?riaux magiques. Cela en fait h?las un m?tier on?reux et parfois difficile. ');
INSERT INTO `npc_questions` VALUES (2428, '', '', '', '', 'Le cordonnier fabrique ? partir de cuir et d\\\'un peu de m?tal, des ceintures et des bottes de toute beaut?. Associ?es aux bonnes ressources magiques, certaines ceintures pr?tent ? leurs porteurs de terrifiants pouvoirs.');
INSERT INTO `npc_questions` VALUES (2429, '', '', '', '', 'Le tailleur est toujours ? la pointe de la mode. Les tailleurs cr?ent des chapeaux et des capes magiques, qui, en plus de donner certains pouvoirs ? leurs porteurs, leur donnent une apparence unique. Ce m?tier est tr?s difficile, tant les premiers v?tements sont peu inspir?s. Sans compter que les tailleurs jalousent leurs secrets et leurs enseignements sont plus rares que certaines de leurs cr?ations.');
INSERT INTO `npc_questions` VALUES (2430, '', '', '', '', 'Il se situe ? l\\\'ext?rieur de la ville, dans la ferme du Nord-Est.');
INSERT INTO `npc_questions` VALUES (2431, '', '', '', '', 'Merci beaucoup, vous m\\\'avez sauv? la vie !');
INSERT INTO `npc_questions` VALUES (2432, '', '', '', '', 'Le ma?tre n\\\'est pas ? la scierie en ce moment, il se trouve ? l\\\'h?tel des ventes de bois.');
INSERT INTO `npc_questions` VALUES (2433, '', '', '', '', 'Le ma?tre est parti ? la mine, il est ? l\\\'exterieur de la ville, ? l\\\'entr?e des mines au nord-est d\\\'ici.');
INSERT INTO `npc_questions` VALUES (2434, '', '', '', '', 'Il vous faudra faire un petit d?tour, il se trouve sur la presqu\\\'?le au centre du lac.');
INSERT INTO `npc_questions` VALUES (2435, '', '', '', '', 'Il doit ?tre en train de chasser dans la for?t.');
INSERT INTO `npc_questions` VALUES (2436, '', '', '', '', 'La scierie se trouve ? l\\\'or?e du bois.');
INSERT INTO `npc_questions` VALUES (2437, '', '', '', '', 'Toutes les activit?s relatives aux poissons se trouvent dans le b?timent en forme de kralamour.');
INSERT INTO `npc_questions` VALUES (2438, '', '', '', '', 'Les ?tablis pour travailler la viande du chasseur se situent dans l\\\'arri?re-salle de la boucherie.');
INSERT INTO `npc_questions` VALUES (2439, '', '', '', '', 'Le boulanger fabrique du bon pain, fid?le aux traditions. Ce pain permet de se restaurer facilement lors d\\\'un p?riple. Il d?pend ?norm?ment du paysan qui lui livre ses farines, mati?re premi?re de tous les pains. La rumeur veut que manger du pain rende plus vigoureux.');
INSERT INTO `npc_questions` VALUES (2440, '', '', '', '', 'Le poissonnier pr?pare le poisson que lui attrape le p?cheur. Il le cuit et l\\\'assaisonne. En fait, c\\\'est un aliment tr?s nourrissant et revitalisant. Et en plus, selon l\\\'adage courant, cela peut rendre plus intelligent.');
INSERT INTO `npc_questions` VALUES (2441, '', '', '', '', 'Le boucher pr?pare la viande que le chasseur lui ram?ne, il la pr?pare pour qu\\\'elle puisse ?tre mang?e, en la cuisant de temps ? autre. Cela r?gale les grands carnivores, et il parait que cela rend plus fort, alors pourquoi s\\\'en priver ?');
INSERT INTO `npc_questions` VALUES (2442, '', '', '', '', 'Nos contr?es sont peupl?es de cr?atures toutes plus fascinantes les unes que les autres. Rien de tel que d\\\'aller ? la rencontre de la faune et de la flore locales pour parfaire tes connaissances zoologiques et botaniques. Un coeur l?ger, des intentions pures, ?a suffit ? les amadouer la plupart du temps.');
INSERT INTO `npc_questions` VALUES (2443, '', '', '', '', 'Une chose ? savoir cependant : si par m?garde il t\\\'arrivait d\\\'offusquer l\\\'une d\\\'entre elles, elle risquerait de t\\\'en vouloir... Rien de bien m?chant, mais il est possible qu\\\'elle veuille se gaver de tes tripes ! Il est probable aussi qu\\\'elle souhaite broyer tes os ! Alors, ?coute-moi bien...');
INSERT INTO `npc_questions` VALUES (2444, '', '', '', '', 'Tout comme toi, toutes les cr?atures ici-bas sont r?sistantes ou sensibles aux quatre ?l?ments primordiaux : air, terre, feu, eau. Apprends ? reconna?tre les forces et faiblesses de chacune (et les tiennes ! ). Et le monde des Onze sera s?r pour toi. Ou presque.');
INSERT INTO `npc_questions` VALUES (2445, '', '', '', '', 'Tu les reconna?tras facilement. Ce sont de grandes arches de pierres r?parties un peu partout dans le monde. Lorsque tu en verras une, approche-t\\\'en. Elle gardera le souvenir de ton passage. Tu pourras ensuite t\\\'y t?l?porter ? partir d\\\'un autre Zaap, moyennant quelques kamas.');
INSERT INTO `npc_questions` VALUES (2446, '2095;2096;2099;2100;2098', '', '', '0', 'Je t\\\'?coute, quel h?tel de vente recherches-tu ?');
INSERT INTO `npc_questions` VALUES (2447, '', '', '', '', 'La vie est rude ici-bas. Si une cr?ature vient ? bout de ta vitalit?, tu mordras la poussi?re. Il te faudra t\\\'asseoir pour te remettre de tes petites blessures. Si c\\\'est plus grave, mange du pain que tu auras achet? ? un boulanger ou bois une potion de soin, certains alchimistes en fabriquent d\\\'excellentes. Tu mordras ensuite la vie ? pleines dents, s\\\'il t\\\'en reste...');
INSERT INTO `npc_questions` VALUES (2448, '', '', '', '', 'En effet ? chaque fois que tu perds un combat, tu perds aussi un peu de ton Energie. Autant te dire que si tu ne fais pas attention, tu te retrouveras vite dans l\\\'autre monde. Il parait que certaines personnes savent manipuler l\\\'Energie au moyen de potions et de pains enchant?s.');
INSERT INTO `npc_questions` VALUES (2449, '', '', '', '', 'Salut ? toi aventurier, bienvenue en la demeure du clan des Mercenaires. Nous sommes un groupe de mercenaires d?vou?s au peuple, pr?ts ? ?x?cuter tout type de contrat. Moyennant quelques kamas nous pourrons t\\\'aider ? retrouver l\\\'objet que tu cherches tant, t\\\'accompagner en aventure, ?liminer ton pire ennemi ou bien d\\\'autres choses encore... N\\\'h?site pas ? entrer pour nous rencontrer ou ? contacter un ma?tre du clan si tu cherches ? faire partie des n?tres.');
INSERT INTO `npc_questions` VALUES (2450, '2114;2111;2551;2554;2112;2113;2108;2553;2550;2109;2552', '', '', '0', 'Ici sont enferm?s les pires chenapans du coin. C\\\'est ? moi que vous devez vous adresser pour enfermer vos prises.');
INSERT INTO `npc_questions` VALUES (2451, '', '', '', '', 'Belle prise, mercenaire.');
INSERT INTO `npc_questions` VALUES (2452, '', '', '', '', 'Ah la grosse m?g?re, bien jou? !');
INSERT INTO `npc_questions` VALUES (2453, '', '', '', '', 'Celui-l? restera bien calme d?sormais.');
INSERT INTO `npc_questions` VALUES (2454, '', '', '', '', 'Hol? ! La brute que voil?, ?a n\\\'a pas d? ?tre une partie de plaisir, mais la r?compense est ? la hauteur de la prise de risque.');
INSERT INTO `npc_questions` VALUES (2455, '', '', '', '', 'Je le croyais plus grand !');
INSERT INTO `npc_questions` VALUES (2456, '', '', '', '', 'Euh, c\\\'est une blague ? Montrez-moi l\\\'avis de recherche.');
INSERT INTO `npc_questions` VALUES (2457, '', '', '', '', 'Voil? une ombre ? l\\\'ombre pour bien longtemps.');
INSERT INTO `npc_questions` VALUES (2458, '', '', '', '', 'Bien jou?. Tu as compris comment te servir de ta boussole. Maintenant il faut que tu saches que tu peux t\\\'asseoir ? tout moment si tu as besoin de soigner des blessures l?g?res apr?s un combat.');
INSERT INTO `npc_questions` VALUES (2459, '', '', '', '', 'Tout au long de ton p?riple, tu seras amen? ? vivre de nombreuses aventures. Toutes ces missions seront inscrites dans ton livre de qu?tes. Tu vois ce vieux livre en bas (? c?t? de l\\\'inventaire), il facilitera le fonctionnement de ta boussole. Garde toujours un oeil dessus. Il deviendra bien plus qu\\\'un guide pour toi : un v?ritable t?moignage de ta progression.');
INSERT INTO `npc_questions` VALUES (2460, '', '', '', '', 'Formidable ! Je commence ? comprendre le m?canisme de mutation des plantes ! \\nJe crains le pire pour l\\\'avenir, mais je pense que l\\\'on devrait pouvoir trouver un rem?de...');
INSERT INTO `npc_questions` VALUES (2461, '', '', '', '', 'Trois-Fleur ? En effet, c\\\'est un de nos plus fid?les clients ! Il se trouve souvent l?-bas, sur la c?te d\\\'Asse...');
INSERT INTO `npc_questions` VALUES (2462, '', '', '', '', 'Salut ! Comme moi, tu aimes la douceur du bois ? Va voir Oli Venders, c\\\'est le meilleur b?cheron d\\\'Astrub. Si tu te d?brouilles bien, il pourra m?me prendre le temps de t\\\'apprendre les bases de son m?tier. Je t\\\'ai indiqu? le chemin. Tu n\\\'as qu\\\'? suivre ta boussole.');
INSERT INTO `npc_questions` VALUES (2463, '2121', '', '', '0', 'J\\\'ai trouv? cette machine dans les landes de Sidimote, elle n?cessite un jeton sp?cial de Bworker pour fonctionner.');
INSERT INTO `npc_questions` VALUES (2464, '', '', '', '', 'T\\\'as du pain sur la planche, non ?');
INSERT INTO `npc_questions` VALUES (2466, '', '', '', '', 'Parle plut?t ? mon fr?re Wilde. Il explique vachement bien et quand y parle on comprend tout c\\\'qui dit !');
INSERT INTO `npc_questions` VALUES (2467, '', '', '', '', 'Salut l\\\'ami ! \\nSi comme moi tu sens ton sang bouillir au fond de tes veines, je te conseille vivement d\\\'aller voir Saketsu, notre ma?tre de classe . Il saura te montrer le chemin qui t\\\'a ?t? destin?. Je peux t\\\'indiquer o? le trouver si tu veux. Tu n\\\'auras qu\\\'? suivre ta boussole. Mais attention c\\\'est une vraie boucherie ? l\\\'int?rieur ! \\n');
INSERT INTO `npc_questions` VALUES (2468, '', '', '', '', 'Je n\\\'ai pas le temps de te parler. Laisse-moi...');
INSERT INTO `npc_questions` VALUES (2469, '', '', '', '', 'Tu apprends vite jeune #1. Je pense que tu peux d\\\'ores et d?j? retourner ? la cit? d\\\'Astrub. Non attends ! J\\\'allais oublier. N\\\'oublie pas que ce monde est peupl? de nombreux aventuriers comme toi. N\\\'h?site pas ? discuter avec les autres au moyen de ta zone de communication (en bas ? gauche). Certains auront besoin d\\\'aide, certains t\\\'aideront et d\\\'autres auront m?me des qu?tes ? te proposer. Commence ? regarder pr?s de la statue, tu les rep?reras facilement...');
INSERT INTO `npc_questions` VALUES (2470, '', '', '', '', 'Merci beaucoup de votre aide. J\\\'esp?re que vous apprecierez ma modeste r?compense: cette rune.');
INSERT INTO `npc_questions` VALUES (2471, '', '', '', '', 'Bon ok. Si tu veux vraiment faire tes preuves, va donc voir Ant Emicheun. Il a de dr?les de probl?mes dans ses affaires... *soupir*. Si tu peux l\\\'aider, tu pourras peut-?tre m\\\'aider aussi quand tu seras plus fort...');
INSERT INTO `npc_questions` VALUES (2472, '', '', '', '', 'Jouer, jouer et encore jouer... J\\\'adore le jeu...');
INSERT INTO `npc_questions` VALUES (2473, '', '', '', '', 'J\\\'ai tout perdu... plus un seul kama.');
INSERT INTO `npc_questions` VALUES (2474, '', '', '', '', 'Pour un pont, c\\\'est un beau pont ! On leur a apport? un sacr? coup de main, aux Pandawas. Mais il faut qu\\\'on colmate ces br?ches, sinon tout risque de s\\\'?crouler. Mouais... de l\\\'ambre, c\\\'est bien ?a qu\\\'il nous faudrait.');
INSERT INTO `npc_questions` VALUES (2475, '', '', '', '', 'De l\\\'ambre, ?a se trouve pas sur n\\\'importe quel arbre, hein. Faudrait demander ?a ? un Abraknyde, je suis s?r qu\\\'il t\\\'en donnera avec plaisir... (grand sourire).');
INSERT INTO `npc_questions` VALUES (2476, '', '', '', '', 'Y\\\'a plus qu\\\'? colmater tout ?a ! Merci bien !');
INSERT INTO `npc_questions` VALUES (2477, '', '', '', '', 'Tous ces bambous qui se fendillent, c\\\'est si triste... Sans ambre, on peut rien faire !');
INSERT INTO `npc_questions` VALUES (2478, '', '', '', '', 'Sur Pandala, y para?trait qu\\\'ils font fermenter des larves bleues dans de la bave de Bouftou, et que c\\\'est go?teux ! La premi?re chose que je ferai en allant sur cette ?le, c\\\'est lamper c\\\'t\\\'alcool, foi d\\\'Enutrof ! Mais tout ?a nous dit pas o? est pass? Toyo Dzink. S\\\'il revient pas avec l\\\'ambre, on va jamais le colmater, ce pont !');
INSERT INTO `npc_questions` VALUES (2479, '', '', '', '', 'Si je le savais ! On l\\\'a vu prendre la route d\\\'Amakna, et puis plus de nouvelles... ');
INSERT INTO `npc_questions` VALUES (2480, '', '', '', '', 'Bizarre que ces bambous se fendillent aussi vite. J\\\'ai jamais vu ?a : on dirait qu\\\'ils ont ?t? rong?s par une bestiole. Heureusement que nous autres Enutrofs, on sait y faire. Avec un peu d\\\'ambre, ?a se r?pare ?a dare dare !');
INSERT INTO `npc_questions` VALUES (2481, '', '', '', '', 'Merci bien ! Je vais pouvoir r?parer ?a ! R?flexion faite, c\\\'est pas une bestiole qui a pu faire ?a. On dirait que le bambou a ?t? br?l? par une sorte d\\\'acide... Jamais rien vu de pareil !');
INSERT INTO `npc_questions` VALUES (2482, '', '', '', '', 'Il me faut de l\\\'Ambre, qu\\\'est-ce qu\\\'ils font les autres ? Ca doit pas ?tre si dur ? trouver quand m?me !');
INSERT INTO `npc_questions` VALUES (2483, '', '', '', '', 'Ah merci ! Gr?ce ? toi on va pouvoir se remettre ? travailler... (il baille).');
INSERT INTO `npc_questions` VALUES (2484, '', '', '', '', 'Tu cherches de l\\\'Ambre par ici ? M\\\'est avis qu\\\'il te faut aller vers le Sud d\\\'Amakna pour en trouver, vers la for?t.');
INSERT INTO `npc_questions` VALUES (2485, '', '', '', '', 'Ah merci ! Gr?ce ? toi on va pouvoir se remettre ? travailler... (il baille).');
INSERT INTO `npc_questions` VALUES (2486, '', '', '', '', '\\\"Va chercher de l\\\'ambre !\\\" qui disait Mangan?ze. Ouais, facile ? dire. O?  je pourrais bien trouver de l\\\'ambre ? Sur des arbres ouais, mais lesquels ?  Aide-moi camarade, je te donnerai un petit parchemin de Vitalit?...');
INSERT INTO `npc_questions` VALUES (2487, '', '', '', '', 'Rhhhhaaaaa de l\\\'ambre ! Merci ! Voici ta r?compense !');
INSERT INTO `npc_questions` VALUES (2488, '', '', '', '', 'Te revoil? toi ? tu te souviens ? Il me faut cinq ambres !');
INSERT INTO `npc_questions` VALUES (2489, '', '', '', '', 'Bien le bonjour ! T\\\'as pas vu Toyo Dzink des fois ? C\\\'est un de mes coll?gues. Il cherche de l\\\'Ambre. Et moi je le cherche... Para?trait qu\\\'il est sur la route qui va d\\\'Astrub ? Amakna. C\\\'est pas l? qui va en trouver, de l\\\'ambre, faut aller vers le Sud ! Tu lui rendrais un fier service si tu lui en donnais.');
INSERT INTO `npc_questions` VALUES (2490, '', '', '', '', 'QuooOooOOoooiii ? J\\\'ai l\\\'air d\\\'une GrenooOOouille ? Je vais acheter une paire de booOOoottines pour te boOotter les fesses jusqu\\\'? Pandala, nom de moOoi ! C\\\'est de l\\\'autre c??OO??t? de la ville hein ! A coup de pied l? o? tu sais, ?a risque de faire loOong !');
INSERT INTO `npc_questions` VALUES (2491, '', '', '', '', 'Moi je dis, ils sont braves dans ma famille ! Trois de mes fr?res se relaient pour patrouiller dans les souterrains, et mon oncle Mangan?ze est parti aider les Pandas ? construire leur pont... En plus, il y a des saboteurs par l?-bas ! (Elle prie). OooOooOOhhh dieu EnutroooOOOoof, je t\\\'en prie veille sur eux...');
INSERT INTO `npc_questions` VALUES (2492, '', '', '', '', 'H?ho ! On s\\\'en va au boulot !');
INSERT INTO `npc_questions` VALUES (2493, '', '', '', '', 'Joli coin par ici, pas vrai ?');
INSERT INTO `npc_questions` VALUES (2494, '', '', '', '', 'Mmmh ? Demande ?a ? Mangan?ze, je suis occup? !');
INSERT INTO `npc_questions` VALUES (2495, '2143;2146;2144', '', '', '0', 'Etranger, je te salue ! Ouvre grand les fioles qui te servent d\\\'oreilles, je ne le r?p?terai pas deux fois : \\\" Par ordre du Grandapan chaque aventurier qui pose un orteil sur l\\\'?le de Pandala doit s\\\'acquitter de la taxe sur la Pandrista \\\".');
INSERT INTO `npc_questions` VALUES (2496, '4840', '', '', '', 'Parfait ! Va donc voir un de nos fabuleux marchands ambulants ! Ils sont habilit?s ? percevoir la taxe par le Grandapan, et te soulageront volontiers de quelques kamas. Vive Pandala ! Vive le Grandapan !');
INSERT INTO `npc_questions` VALUES (2497, '2145', '', '', '0', 'Pas de taxe sur la Pandarista, pas de Pandala !');
INSERT INTO `npc_questions` VALUES (2498, '', '', '', '', 'C\\\'est quoi la Pandarista??');
INSERT INTO `npc_questions` VALUES (2499, '4840', '', '', '', 'Une sp?cialit? locale. Il y en a de nombreuses sur l\\\'?le de Pandala : la Pandneken, la Panderbrau, la Pandaburg...  tu apprendras ? les d?couvrir... (clin d\\\'oeil complice).');
INSERT INTO `npc_questions` VALUES (2500, '', '', '', '', 'N\\\'esp?re pas parler ? un Pandawa si tu n\\\'as pas pay? la taxe sur la Pandrista.');
INSERT INTO `npc_questions` VALUES (2501, '2151;2147', '', '', '', 'Hola ! Ton oeil est vif, c\\\'est un signe d\\\'intelligence ! Toi et moi, on va s\\\'entendre... Tu viens r?gler la taxe sur la Pandrista ? Alors ach?te-moi ce superbe couvre-chef Pandawan cousu main, et tu seras quitte.');
INSERT INTO `npc_questions` VALUES (2502, '2148', '', '', '', 'Je vois, tu es dur en affaires... Comme ils ont d?j? ?t? port?s, je vais te faire un bon prix...');
INSERT INTO `npc_questions` VALUES (2503, '2150', '', '', '', 'Mais je me tue ? te dire que la taxe se paye en achetant un couvre-chef Pandawa...');
INSERT INTO `npc_questions` VALUES (2504, '', '', '', '', 'Parfait ! En portant ce Pandawa, tu montres que tu as pay? la taxe ! Maintenant, je te conseille d\\\'aller voir le Shaman Surivitna. Ce dr?le de bruit, l?, ?a vient de ton ventre, hein ? C\\\'est ce qui arrive lorsqu\\\'on porte un Pandawa ? Pandala sans ?tre un Pandawa de Pandala : on attrape la Pandrista...');
INSERT INTO `npc_questions` VALUES (2505, '', '', '', '', 'Vive Pandala !');
INSERT INTO `npc_questions` VALUES (2506, '', '', '', '', 'Vive le Grandapan ! (Lance un regard per?ant).');
INSERT INTO `npc_questions` VALUES (2507, '', '', '', '', 'Int?ressant ! Votre globe oculaire est VRAIMENT glauque... Laissez moi deviner : primo, votre haleine sent comme une vieille dragodinde constip?e... Secundo, votre dernier repas cherche ? fuir par tous vos orifices en m?me temps. Tertio, vous portez un Pandawa ? Pandala sans ?tre un Pandawa de Pandala ! Pas de doute : vous avez la Pandrista !');
INSERT INTO `npc_questions` VALUES (2508, '', '', '', '', 'R?p?tez cinq fois : \\\"la Pandrista, c\\\'est pas pour moi !\\\" et vous serez gu?ri. Mais je dois vous avertir : notre ?le peut s\\\'av?rer dangereuse pour les aventuriers insouciants !');
INSERT INTO `npc_questions` VALUES (2509, '', '', '', '', 'Certains d\\\'entre-nous sont nerveux depuis que de nouveaux arrivants foulent notre ?le ancestrale. Et tous les Pandawas n\\\'ob?issent pas aux lois du Grandapan ! Les Pandikazes, ces rebelles, sont les pires de tous ! D\\\'ailleurs ce marchand qui vous a refourgu? ce chapeau est peut-?tre l\\\'un d\\\'eux... Et cette myst?rieuse maladie qui touche les Enutrofs d\\\'Astrub n\\\'arrange rien... Restez sur vos gardes...');
INSERT INTO `npc_questions` VALUES (2510, '', '', '', '', 'Oyahoh ! M\\\'est avis que tu t\\\'en reviens d\\\'Astrub, ?a se voit ? ton oeil tout bouffi.... J\\\'me suis dit : ?a c\\\'est un oeil qui en a vu de belles, et qui a vu sauver une patrouille d\\\'Enutrof ! Ahahah ! Tu m\\\'reconnais ?');
INSERT INTO `npc_questions` VALUES (2511, '', '', '', '', 'H????? je suis Pyrite ! Les souterrains d\\\'Astrub ! Le rat d\\\'?go?tant ! Eh oui ! On t\\\'doit une fi?re chandelle ! Bref : j\\\'ai entendu ta conversation avec le Shaman ? un chic Pandawa ?ui l? ? tu devrais aller voir le Grandapan. C\\\'est lui qui fait la pluie et le beau temps par ici. Si tu es en qu?te de Dofus, et je pense que c\\\'est le cas, va le voir, il aura probablement quelques informations int?ressantes.');
INSERT INTO `npc_questions` VALUES (2512, '', '', '', '', 'Tiens, tu lui remettras cette sublime r?plique de Dofus de la part des Enutrofs d\\\'Astrub.');
INSERT INTO `npc_questions` VALUES (2513, '', '', '', '', 'Ouais, enfin un faux Dofus... mais sculpt? dans du minerai pr?cieux, par une Enutrofette habile de ses mains, j\\\'te le dis !');
INSERT INTO `npc_questions` VALUES (2514, '', '', '', '', '... avec l\\\'ouverture de l\\\'?le, le culte de la d?esse Pandawa va s\\\'?tendre au Monde ! Gr?ce ? ce flux de nouveaux adorateurs, notre d?esse va gagner une part de march? divin, et nous arroser de ses b?n?fices ! (Il vous jette un coup d\\\'oeil m?fiant) Hum ! Je crois que les murs ont des oreilles par ici...');
INSERT INTO `npc_questions` VALUES (2515, '', '', '', '', 'Bonjour citoyen d\\\'ailleurs ! Avant toute chose, sachez que la vente de produits ferment?s est strictement r?glement?e sur cette ?le. Ces produits sont ? consommer avec la mod?ration la plus absolue. Mais nos ?choppes vous sont grandes ouvertes, ? vous et ? vos kamas !');
INSERT INTO `npc_questions` VALUES (2516, '', '', '', '', '...le r?ceptacle aux Dofus est d?sormais accessible ? tous?! Nombreux sont ceux qui veulent le voir, et acheter des souvenirs de notre ?le?! (Il se frotte les mains). Lou? soit le Grandapan?! Mmh... Puis-je vous aider??');
INSERT INTO `npc_questions` VALUES (2517, '', '', '', '', '...le r?ceptacle aux Dofus est d?sormais accessible ? tous ! Nombreux sont ceux qui veulent le voir, et acheter des souvenirs de notre ?le ! (Il se frotte les mains). Lou? soit le Grandapan ! Mmh... Puis-je vous aider ?');
INSERT INTO `npc_questions` VALUES (2518, '', '', '', '', '...Quelle aubaine cette l?gende ? propos des oeufs de dragon ! Nos coffres seront bient?t pleins ? craquer ! Mmh... vous d?sirez un renseignement ?');
INSERT INTO `npc_questions` VALUES (2519, '', '', '', '', '...ce faux oeuf de dragon tombe ? pic ! Et si on cr?ait des r?pliques authentiques \\\" fabriqu?es ? Pandala \\\" ? Il suffirait de teindre des oeufs de Dragodinde. Les aventuriers n\\\'y verront que du feu !  Ca va se vendre comme du pain d\\\'Amakna, croyez-moi ! Ahah je suis un g?nie...Hmm mais il faut que j\\\'arr?te de penser tout haut...');
INSERT INTO `npc_questions` VALUES (2520, '', '', '', '', 'Psshh... Dofus... psshh... Grandapan.... Psshh... Conqu?te du Monde... psshhpsshh... ahahahah?!');
INSERT INTO `npc_questions` VALUES (2521, '', '', '', '', 'Psshh... L?gende... psshhpsshh... ahahahah?! Psshh... inonder le march?... psshh... Grandapan....');
INSERT INTO `npc_questions` VALUES (2522, '', '', '', '', 'Psshh... b?n?fices ?normes... psshh... beaucoup de kamas....');
INSERT INTO `npc_questions` VALUES (2523, '', '', '', '', 'Le Grandapan demande de porter ses pri?res ? Pandawa, notre d?esse bien-aim?e ? C\\\'est une mission sacr?e... Accompagne-moi !');
INSERT INTO `npc_questions` VALUES (2524, '', '', '', '', 'Ooh PAndawAaa ! Ecoute ma pri?re : \\\" D?esse, un p\\\'tit verre, on a soif, D?esse, un p\\\'tit verre, on a soif !... \\\" Ah mais, il me manque l\\\'essentiel : une fiole de Pandneken ! Impossible de boire un coup ? la sant? de Pandawa - enfin... de lui faire une libation - sans une fiole de Pandneken ! Tu en trouveras sur le port chez un marchand ambulant ! Va vite, la d?esse s\\\'impatiente !');
INSERT INTO `npc_questions` VALUES (2525, '', '', '', '', '\\\"C\\\'est ? Boire ? boire ? boireuuuhhh, c\\\'est ? boire qu\\\'il me faut WoOooooh\\\". Que veux-tu ? Je prie. Et quand je prie, j\\\'ai soif...');
INSERT INTO `npc_questions` VALUES (2526, '', '', '', '', 'Shh, \\n*tout bas*\\navant de me parler il faut absolument que tu r?gles le probl?me de taxe, jusque l? tu n\\\'es pas le bienvenu ici. Je ne peux donc pas te parler librement, question de tradition.\\nReviens me voir apr?s on pourra discuter.');
INSERT INTO `npc_questions` VALUES (2527, '2223;2224;2225;2226;2164', '', '', '', 'Salut ! J\\\'ai toute sortes de boissons ferment?es ici : qu\\\'est-ce que tu veux ?');
INSERT INTO `npc_questions` VALUES (2528, '', '', '', '', 'C\\\'est pour une libation ? la d?esse ?');
INSERT INTO `npc_questions` VALUES (2529, '', '', '', '', 'C\\\'est pour une libation ? la d?esse ?');
INSERT INTO `npc_questions` VALUES (2530, '', '', '', '', 'Mmhh... V?n?rer notre d?esse nous honore tous, nous autres Pandawas ! Ton oeil brille comme l\\\'astre du jour, c\\\'est un signe qui ne trompe pas : je peux t\\\'accorder ma confiance... Va faire tes libations et reviens me voir !');
INSERT INTO `npc_questions` VALUES (2531, '', '', '', '', 'Notre Grandapan (gloire au Grandapan que je respecte !) est un peu... illumin? : depuis qu\\\'il a fait le grand voyage astral pour rencontrer la d?esse, il n\\\'a plus les pieds sur terre. Enfin, il para?t qu\\\'il n\\\'a plus toute sa t?te... Et ses conseillers en profitent !');
INSERT INTO `npc_questions` VALUES (2532, '', '', '', '', 'N\\\'as-tu pas vu tous ces vendeurs de statuettes de la d?esse ? Tous ces faux oeufs de dragon ? Les conseillers ont pr?vu d\\\'envahir toutes les ?choppes du Monde avec des produits bon march? fabriqu?s ? Pandala ! Et pendant ce temps, les valeurs ancestrales des Pandawas se perdent !');
INSERT INTO `npc_questions` VALUES (2533, '', '', '', '', 'Tu as remarqu? ? Tu r?p?tes tout le temps la fin de mes phrases... C\\\'est bizarre cette manie... Bref ! Les anc?tres des Pandawas ?taient autrefois de solides gaillards. Biberonn?s d?s leur plus tendre enfance au lait de bambou ferment?, nos a?euls apprenaient tr?s t?t les trois B...');
INSERT INTO `npc_questions` VALUES (2534, '', '', '', '', 'Les trois commandements de la d?esse commencent par un B : Boire, B?frer, se Battre. Un conseil : rends toi aupr?s du sage L?nald... lui seul sur cette ?le saura te dire la v?rit? ! Prends cette amulette, il saura que tu viens en ami !');
INSERT INTO `npc_questions` VALUES (2535, '', '', '', '', 'Notre d?esse te remercie par ma bouche : ce Dofus est tr?s ressemblant ! Le Grandapan admire les aventuriers tels que toi, pr?ts ? risquer leur vie pour les pr?cieux oeufs de dragon. Demande au Grandapan ce que tu veux...');
INSERT INTO `npc_questions` VALUES (2536, '', '', '', '', 'Le Grandapan sait beaucoup de choses ! As-tu seulement vu l\\\'authentique relique des temps anciens, notre r?ceptacle aux Dofus ? N\\\'est-ce pas la preuve que la l?gende dit vrai ? N\\\'h?site pas ? aller la voir de tes propres yeux, cela ach?vera de te convaincre. Oh !? As-tu ressenti la sagesse impr?gner ta personne en regardant l\\\'antique statue de notre D?esse ? Il faut que tu voies ?a au plus vite ! ');
INSERT INTO `npc_questions` VALUES (2537, '', '', '', '', 'L\\\'assistant de Surivitna va t\\\'y accompagner. Il est charg? de remercier la d?esse de ses bienfaits. Notre d?esse est TRES susceptible, tu sais... M?me le Grandapan n\\\'oublie pas de la remercier dans ses pri?res, c\\\'est dire...');
INSERT INTO `npc_questions` VALUES (2538, '', '', '', '', 'Parce que le Grandapan a un pied dans Pandala et un pied dans le royaume des dieux ! ');
INSERT INTO `npc_questions` VALUES (2539, '', '', '', '', 'Ce n\\\'est pas une l?gende ! La d?esse a dit au Grandapan que lorsque les Dofus seront r?unis, l\\\'?lu sera b?ni des dieux !');
INSERT INTO `npc_questions` VALUES (2540, '', '', '', '', 'Bonjoul ! Soil le bienvenul dans ma demeule, noble ?tlanger. Tu as l\\\'oeil scintillant comme l\\\'astle de la nuit... et l\\\'amulette de Fleurawa : c\\\'est notre signe de reconnaissance. Que puis-je poul toi ?');
INSERT INTO `npc_questions` VALUES (2541, '', '', '', '', 'J\\\'en sais bien peul, mon amil, mais assez toutefoil poul te contenter. Polte une fiole de Pandapiler ? mon vieil ami, le ma?tre du village d\\\'Akwadala, et je te dilai tout ce que je sais sur le Dofus de Pandala.');
INSERT INTO `npc_questions` VALUES (2542, '', '', '', '', 'J\\\'ai dit : d\\\'abord apporter une Pandapiler au ma?tre d\\\'Akwadala !');
INSERT INTO `npc_questions` VALUES (2543, '', '', '', '', '\\\" Si tu viens une fiole ? la main, je te veux du bien \\\", c\\\'est un dicton d\\\'Akwadala... que tu connaissais apparemment ! Laisse-moi go?ter ce breuvage... Glups ! C\\\'est de l\\\'eau ! De l\\\'eau dans une fiole de Pandapiler ! Sacril?ge ! Ca ne tourne pas rond dans ta petite t?te ? Je vais la trancher de ce pas !');
INSERT INTO `npc_questions` VALUES (2544, '', '', '', '', 'Ahahah ! Ne t\\\'inqui?te pas : c\\\'est un signe de reconnaissance entre le sage L?nald et moi. Sois le bienvenu parmi nous ! Puis-je savoir ce qui t\\\'am?ne dans nos parages ?');
INSERT INTO `npc_questions` VALUES (2545, '', '', '', '', 'Ah ! Le vieux sage t\\\'a parl? de cette vieille l?gende... et tu l\\\'as cru ! M?me parmi le peuple L?nald, peu croient encore ? cette histoire... Mais le sage L?nald en est convaincu : jadis les L?nalds prot?geaient un oeuf de dragon... c\\\'?tait il y a longtemps... qui s\\\'en souvient ?');
INSERT INTO `npc_questions` VALUES (2546, '', '', '', '', '...J\\\'ai entendu dire qu\\\'un messager ?tait venu du continent. Il aurait apport? un Dofus dans l\\\'?le... Le fou ! Si les Pandikazes apprennent son identit?, je ne donne pas cher de sa peau... Avec ces rebelles qui sabotent ? tout va, un accident est vite arriv? (il sourit de toutes ses dents).');
INSERT INTO `npc_questions` VALUES (2547, '', '', '', '', 'J\\\'imagine ta t?te si les Pandikazes apprenaient que c\\\'est TOI qui a apport? le Dofus au Grandapan !');
INSERT INTO `npc_questions` VALUES (2548, '', '', '', '', 'Mmh... changeons de sujet : le sage L?nald est content de la blague que tu as faite au Ma?tre d\\\'Akwadala... \\\" Dis-lui de se rendre ? l\\\'Aerdala et de plaisanter avec le chef... \\\" ? moins qu\\\'il ait dit Terrdala, avec son accent, je ne sais plus trop... Enfin, fais bien attention ? toi !');
INSERT INTO `npc_questions` VALUES (2549, '', '', '', '', 'Il a ajout??: \\\"?dis-lui bien qu\\\'il ne pleut pas nous lefuser cet honneul, avec ce que nous savons ? son ploplos...?\\\" ');
INSERT INTO `npc_questions` VALUES (2550, '', '', '', '', 'Je vois ? ton oeil que tu viens nous pr?ter main forte?! (H? oui, les nouvelles vont vite ? Pandala?!)?Tous mes Pandawas sont occup?s, et j\\\'ai besoin de quelqu\\\'un de confiance pour porter des Bambous chez le Forgeur de Boucliers.');
INSERT INTO `npc_questions` VALUES (2551, '', '', '', '', 'Tu le trouveras dans le village de Pandala.');
INSERT INTO `npc_questions` VALUES (2552, '', '', '', '', 'Si tu refuses, tu m\\\'offenses. Si tu m\\\'offenses, tu offenses tous les Pandawas, sans parler de notre d?esse... Ne compte pas apr?s ?a obtenir le moindre renseignement sur le Dofus de Pandala... C\\\'est pour ?a que tu es ici, non??');
INSERT INTO `npc_questions` VALUES (2553, '', '', '', '', 'Tu as fait preuve de vaillance ! Tu m?rites de tout savoir sur le Dofus de Pandala... c\\\'est ce que pense le sage L?nald. C\\\'est lui qui m\\\'envoie... Te sens-tu pr?t ?');
INSERT INTO `npc_questions` VALUES (2554, '', '', '', '', 'Tu tiens vraiment ? ce que ta t?te parfume un tonneau de Pandneken ? Tu n\\\'as plus le choix de toutes fa?ons...');
INSERT INTO `npc_questions` VALUES (2555, '', '', '', '', 'Une r?union secr?te se tient en ce moment m?me ? Aerdala. Nous autres ignorons ce qui se trame l?-bas... Mais une chose est s?re : il y sera question des Dofus...');
INSERT INTO `npc_questions` VALUES (2556, '', '', '', '', 'Alors vil chasseur de Dofus, destructeur de monde, chaotique touriste, quelque chose ? dire ?');
INSERT INTO `npc_questions` VALUES (2557, '', '', '', '', 'Inutile de mentir, vermine insolente ! Ces oeufs diaboliques s?ment violence et d?solation partout o? ils se trouvent ! Comprends moi bien : un oeuf de dragon ne ferait pas de mal ? un Moskito : c\\\'est toute la bande d\\\"aventuriers cupides ? dont tu fais partie - qu\\\'il faut exterminer... n\\\'est-ce pas ?');
INSERT INTO `npc_questions` VALUES (2558, '', '', '', '', 'Ne nie pas?! Je sais que tu as apport? un de ces maudits Dofus sur notre ?le?! On t\\\'a vu sortir de la maison du Shaman?! Tu as enfreint la r?gle n?1 des Pandikazes?: \\\"z?ro Dofus sur Pandala\\\". Je te condamne ? l\\\'ingestion de Pandweiser jusqu\\\'? ce que mort s\\\'ensuive?! Tu seras ex?cut? demain. Qu\\\'on le m?ne ? la prison, et bonne nuit?!');
INSERT INTO `npc_questions` VALUES (2559, '', '', '', '', 'Te voil? libre?! Gr?ce ? toi, nous en savons assez... Le sage L?nald t\\\'attend?! H?te-toi vers la v?rit??!');
INSERT INTO `npc_questions` VALUES (2560, '', '', '', '', 'Je vois ? ton oeil injectl? de sang que tu tles acquittl? de ta mission ! Tu m?ritles de conna?tle l\\\'histoile de notle peuple. ');
INSERT INTO `npc_questions` VALUES (2561, '', '', '', '', 'Les L?nalds ?taient jadlis les plotecteurs d\\\'un Dofus. Jalous?s par les Pandawas de Feudala, ceux-ci complot?rent avec ces inf?mes Wabbits ! Et nous, les L?nalds, f?mes chass?s de notle ?le... Mais la v?lit? est ailleuls... Lends-toi sur l\\\'?le des Wabbits, et tu saulas !');
INSERT INTO `npc_questions` VALUES (2562, '', '', '', '', 'Palmi les Dofus se cachent des faux... Les authentiques Dofus sont pondus pal des dlagons. Il faut vraiment ?tle na?f pour penser qu\\\'une Cawotle pond des oeufs ! Le Dofus Cawotle est une Cawotle enchant?e par le Wa en personne, ce qui lui conf?le tout de m?me des pouvoils puissants...');
INSERT INTO `npc_questions` VALUES (2563, '', '', '', '', 'H? oui ! Les Dofus ?taient nagu?le gald?s par des dlagons... Mais l\\\'Histoire s\\\'est chalg?e de les dispelser aux quatle coins du Monde. Ils sont d?solmais aux mains de cr?atules sans foi ni loi, folles et destluctlices... Jadis les Dofus ?taient polteuls d\\\'une aula d\\\'halmonie sul le monde. D?solmais ce temps est l?volu...');
INSERT INTO `npc_questions` VALUES (2564, '', '', '', '', 'Je sais que l\\\'une d\\\'entle elles vit dans la fol?t mal?fique. Trouve-la, et elle te dila quel Dofus elle galde... enfin si tu ne sombles pas dans la folie ! Suis mon conseil et va te recueillir dans ton temple pour te pr?parer ? cette aventure. \\nLolsque tu seras en face de cette cr?ature, pose lui cette simple question : \\\"dans les plunelles de Lazeliane se lefl?tait jadis une couleul... Quelle est cette couleul ?\\\" Et polte la r?ponse au Sage L?nald de Feudala ! Bonne chance !');
INSERT INTO `npc_questions` VALUES (2565, '', '', '', '', 'Je sais que tu reviens de loin. Le Dark Vlad est entr? dans les brumes de la folie, il y a fort longtemps... Personne ne sort indemne de cette rencontre?: ton esprit est plus fort maintenant?! ');
INSERT INTO `npc_questions` VALUES (2566, '', '', '', '', 'Apprend ceci?: j\\\'?tais autrefois un L?nald puissant, le plus puissant d\\\'entre tous. J\\\'?tais le gardien du Dofus?! Et lorsque les Wabbits ont envahi notre ?le, j\\\'ai emport? l\\\'oeuf pr?cieux avec moi. ');
INSERT INTO `npc_questions` VALUES (2567, '', '', '', '', 'Tu as compris?: le Dofus n\\\'a pas quitt? Pandala depuis tout ce temps... Il est sur cette ?le?: un Dofus blanc, immacul?, qu\\\'aucun ?tre n\\\'a touch? depuis lustres... Je l\\\'ai cach? dans le donjon de la presqu\\\'?le, au nord-est de Pandala !');
INSERT INTO `npc_questions` VALUES (2568, '', '', '', '', 'J\\\'ai beaucoup ? faire avec tous ces Enutrofs souffrants... tout cela ne me dit rien qui vaille...');
INSERT INTO `npc_questions` VALUES (2569, '', '', '', '', 'Merci bien ! Les pri?res montent plus vite aux cieux lorsqu\\\'elles sont arros?es d\\\'une bonne Pandneken ! Tu peux te balader le temps que je finisse la Pandn...pri?re.');
INSERT INTO `npc_questions` VALUES (2570, '', '', '', '', 'Va vels le polt : l?-bas t\\\'embalquer tu poulas. Ou alors, tu plends tes pieds, mais c\\\'est plus long et fatigant...');
INSERT INTO `npc_questions` VALUES (2571, '', '', '', '', 'Je vois ? tes pieds que tu as palcouru un long chemin pour venil me voil. Alors ?coutle-moi?: palmi les Dofus se cachent des faux... Les authentiques Dofus sont pondus pal des dlagons. Il faut vraiment ?tle na?f pour penser qu\\\'une Cawotte pond des oeufs?! Le Dofus Cawotte est une Cawotte enchant?e par le Wa Wabbit en pelsonne, ce qui lui conf?le tout de m?me des pouvoils puissants...');
INSERT INTO `npc_questions` VALUES (2572, '', '', '', '', 'Les Dofus ?taient nagu?le gald?s pal des dlagons... Mais l\\\'Histoire s\\\'est chalg?e de les dispelser aux quatle coins du Monde. Ils sont d?solmais aux mains de cl?atules sans foi ni loi, folles et destluctlices... Jadis les Dofus ?taient polteurs d\\\'une aula d\\\'halmonie sul le monde. D?solmais ce temps est l?volu...');
INSERT INTO `npc_questions` VALUES (2573, '', '', '', '', 'Je sais que l\\\'une d\\\'entle elles vit dans la fol?t mal?fique. Tlouve-la, et elle te dira quel Dofus elle galde... La rencontler te tlansformelas ? jamais. Tu leviendlas me voil, et tu saulas le seclet de Pandala !');
INSERT INTO `npc_questions` VALUES (2574, '', '', '', '', 'Je sais que tu leviens de loin. Le Dark Vlad est entl? dans les blumes de la folie, il y a folt longtemps... Personne ne solt indemne de cette rencontle : ton esplit est plus folt maintenant !  \\nTu lui as pos? la question et il ta l?pondu... Le Dark Vlad galde donc le Dofus Emelaude !');
INSERT INTO `npc_questions` VALUES (2575, '', '', '', '', 'Applend ceci : j\\\'?tais autlefois un L?nald puissant, le plus puissant d\\\'entle tous. J\\\'?tais le galdien d\\\'un Dofus ! Et lolsque les Wabbits ont envahi notle ?le, j\\\'ai empolt? l\\\'oeuf pl?cieux avec moi. ');
INSERT INTO `npc_questions` VALUES (2576, '', '', '', '', 'Tu as complis : le Dofus n\\\'a pas quitt? Pandala depuis tout ce temps... Il est sul cette ?le : un Dofus blanc, immacul?, qu\\\'aucun ?tle n\\\'a touch? depuis des lustles... Je l\\\'ai cach? dans le donjon de la plesqu\\\'?le, au nold-est de Pandala. Et les Pandikazes, ces bandits, ont fait sabot? le pont... et lolsque j\\\'ai su que le Dalk Vlad poss?dait un Dofus, j\\\'ai clu qu\\\'il s\\\'en ?tait empal? !');
INSERT INTO `npc_questions` VALUES (2577, '', '', '', '', 'Ils sont beaux mes chapeaux, ils sont beaux ! Des couvre-chefs Pandawas presque tout neufs ! Approchez ! Y\\\'en aura pas pour tout le monde !');
INSERT INTO `npc_questions` VALUES (2578, '', '', '', '', 'Je vois ? ton oeil que tu viens nous pr?ter main forte ! (H? oui, les nouvelles vont vite ? Pandala !) Tous mes Pandawas sont occup?s, et j\\\'ai besoin de quelqu\\\'un de confiance pour porter des Bambous chez le Forgeur de Boucliers.');
INSERT INTO `npc_questions` VALUES (2579, '', '', '', '', 'Si tu refuses, tu m\\\'offenses. Si tu m\\\'offenses, tu offenses tous les Pandawas, sans parler de notre d?esse... Ne compte pas apr?s ?a obtenir le moindre renseignement sur le Dofus de Pandala... C\\\'est pour ?a que tu es ici, non ?');
INSERT INTO `npc_questions` VALUES (2580, '', '', '', '', 'Pnj(641) et Message(2579)');
INSERT INTO `npc_questions` VALUES (2581, '', '', '', '', 'Parfait ! Ram?ne ces 10 Bambous au Forgeur de Boucliers, je suis sur qu\\\'il saura se montrer g?n?reux envers toi.');
INSERT INTO `npc_questions` VALUES (2582, '', '', '', '', '...contaminer les coiffes Pandawas avec les germes de la Pandrista ?tait une id?e de g?nie ! Et le vent a port? d\\\'autres maladies aux quatre coins de l\\\'?le : ces maudits aventuriers risquent d\\\'?tre surpris...');
INSERT INTO `npc_questions` VALUES (2583, '', '', '', '', 'Halte l? ! On ne passe pas !');
INSERT INTO `npc_questions` VALUES (2584, '', '', '', '', 'RroOon PsSscCchHhhh (il dort).');
INSERT INTO `npc_questions` VALUES (2585, '', '', '', '', 'Il ne suffit pas de l\\\'acheter, mon brave, il faut maintenant l\\\'utiliser... avant de le porter, renifle-le ? plein nez comme tu le ferais d\\\'une fleur...');
INSERT INTO `npc_questions` VALUES (2586, '', '', '', '', 'Ta route a ?t? longue, disciple, mais tu es sur la bonne voie : celle qui m?ne ? la for?t mal?fique...  Avant de t\\\'y aventurer, tu devrais discuter avec notre dresseur de Dopeuls. Si tu le peux, fais toi la main sur l\\\'une de ses bestioles: rien de tel pour am?liorer tes techniques de combat ! Tu risques d\\\'en avoir besoin une fois l?-bas : on dit que cette for?t est oubli?e des dieux...');
INSERT INTO `npc_questions` VALUES (2587, '', '', '', '', 'oOom Pandawa oOm - Chut ! Les paroles de la d?esse ne vont pas tarder ? affluer jusqu\\\'? mes tympans sacr?s !');
INSERT INTO `npc_questions` VALUES (2588, '', '', '', '', 'Ta route a ?t? longue, disciple, mais tu es sur la bonne voie : celle qui m?ne ? la for?t mal?fique...  Avant de t\\\'y aventurer, tu devrais discuter avec notre dresseur de Dopeuls. Si tu le peux, fais toi la main sur l\\\'une de ses bestioles: rien de tel pour am?liorer tes techniques de combat ! Tu risques d\\\'en avoir besoin une fois l?-bas : on dit que cette for?t est oubli?e des dieux...');
