INSERT INTO `npc_questions` VALUES (2599, '', '', '', '', 'Ta route a ?t? longue, disciple, mais tu es sur la bonne voie : celle qui m?ne ? la for?t mal?fique...  Avant de t\\\'y aventurer, tu devrais discuter avec notre dresseur de Dopeuls. Fais-toi la main sur l\\\'une de ses bestioles: rien de tel pour am?liorer tes techniques de combat ! Tu risques d\\\'en avoir besoin une fois l?-bas : on dit que cette for?t est oubli?e des dieux... Si tu n\\\'es pas capable de battre un Dopeul, je t\\\'interdis d\\\'envisager de fouler la terre maudite, ce serait du suicide.');
INSERT INTO `npc_questions` VALUES (2600, '2222;2432', '', '', '', 'Disciple, tu sembles avoir encore beaucoup de choses ? apprendre sur les Pandawas. Que veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (2601, '', '', '', '', 'Les Pandawas sont surtout habiles avec les haches et les b?tons. Trouve un forgeur de haches ou un sculpteur de b?ton pour t\\\'?quiper, et tu seras un Pandawa combl? !');
INSERT INTO `npc_questions` VALUES (2602, '', '', '', '', 'Mmh... tu n\\\'as pas pay? de taxe ! Je ne suis pas autoris?e ? te parler !');
INSERT INTO `npc_questions` VALUES (2603, '', '', '', '', 'D\\\'apr?s l\\\'article 33, du code panda?que du Grandapan, \\\"Il est formellement interdit de vendre les boissons ? base de Bambou aux personnes non habilit?es\\\". Je suis d?sol?e !');
INSERT INTO `npc_questions` VALUES (2604, '', '', '', '', 'N\\\'as tu point lencontl? mon messager ? Tu dois te lendre ? Telldala, et pl?sente toi au chef qui se situe souvent ? l\\\'extelieul du village. Fais vite!');
INSERT INTO `npc_questions` VALUES (2605, '', '', '', '', 'Ahah ! Ma livraison de bambou, je vais pouvoir fabriquer de nombreux boucliers gr?ce ? toi, en voil? un petit pour toi...');
INSERT INTO `npc_questions` VALUES (2606, '', '', '', '', 'Tr?s bien, reviens me voir si tu trouves quelque chose... Adieu, en somme!');
INSERT INTO `npc_questions` VALUES (2607, '', '', '', '', 'Vous insinuez que ce souterrain m?ne au rep?re d\\\'une cr?ature atroce ? \\nHmm, je comprends maintenant la signification de cette grosse t?te de mort sur la page de mon manuscrit. \\nHmm, voyons voir... oui alors... le prochain se trouve au Nord du village, vous ne devriez pas le rater si vous vous dirigez vers la for?t des Abraknydes... Je suis s?r que vous mourrez d\\\'envie de tester une nouvelle fois votre chance!');
INSERT INTO `npc_questions` VALUES (2608, '', '', '', '', 'Vous avez r?ussi ! Trois coups de chance successifs, je dois dire que c\\\'est peu courant! \\nDans \\\"Un pont d\\\'?rable\\\", mon dernier livre de chevet consacr? ? l\\\'accouplement des Abraknydes, les m?les qui r?ussissaient ? survivre ? trois combats contre un f?ca ?taient surnomm?s \\\'kokoko koku\\\', fascinant non ? \\n \\nBon! Fid?le assistant, cette fois-ci, il va falloir vous rendre sur la presqu\\\'?le des Dragoeufs ! ? l\\\'ouest sur le flanc de la montagne, se trouve une porte ? peu pr?s semblable aux pr?c?dentes, c\\\'est l? que se situe votre prochain d?fi!');
INSERT INTO `npc_questions` VALUES (2609, '', '', '', '', 'Alors, j\\\'esp?re que vous avez appr?ci? votre s?jour chez les cracheurs de feu ? \\nIl y avait donc encore un totem magique ? Je commence ? comprendre... cette vieille l?gende... ? propos de Maimane... \\nEnfin peu importe, mon assistant n\\\'a pas besoin d\\\'en savoir plus, passons au souterrain suivant ! \\n \\nIl y a un Bwork dessin? sur cette page et il n\\\'a pas l\\\'air tr?s accueillant... Rendez-vous ? leurs villages, il doit y avoir une entr?e quelque part !');
INSERT INTO `npc_questions` VALUES (2610, '', '', '', '', 'Nous arrivons ? la fin du premier chapitre de ce manuscrit ! \\nLe prochain souterrain ? l\\\'air particuli?rement compliqu?... \\nUn message d\\\'avertissement sans queue ni t?te indique : \\\"Il est pr?f?rable de porter un collier en soude au cou !\\\"');
INSERT INTO `npc_questions` VALUES (2611, '', '', '', '', 'Tu le sais peut-?tre, l\\\'Horloge Divine de X?lor est r?gl?e sur les battements des Dofus : la pulsation de chaque Dofus se produit en m?me temps que celle de tous les autres... Si tu tends l\\\'oreille, tu entendras peut-?tre une pulsation l?g?re... alors ?  Mmh... tant pis ! Je vais te dire ce que tu aurais d? d?couvrir par toi-m?me :  de cette pulsation d?pend l\\\'harmonie de notre Monde !  \\nOr de plus en plus d\\\'explorateurs remuent ciel et terre pour trouver les oeufs de dragon... Tout ce tohu-bohu n\\\'est pas bon pour les Dofus ! Je les sens agit?s... c\\\'est comme s\\\'ils se d?r?glaient, et l\\\'Horloge Divine avec eux ! Et si le temps n\\\'arrive pas ? ce stabiliser, la porte temporelle sera ouverte...');
INSERT INTO `npc_questions` VALUES (2612, '222', '', '', '0', 'Toi ?tre futur mari de moi ? Non, toi pas ?tre, toi sembler trop faible, toi pas sentir bon, et toi pas beau. Toi d?gager de vue ? Poochan.');
INSERT INTO `npc_questions` VALUES (2613, '222', '', '', '0', 'Toi ?tre stupide, ?a ?tre pouvoir de sources Jus-Sang-Ki-Eau. Pouvoir transformer Poochan en chacha pour retrouver futur mari, mais poochan pas trouver. Toi vouloir aider moi ?');
INSERT INTO `npc_questions` VALUES (2614, '223', '', '', '0', 'Toi bien me servir, toi pas bouger, poochan reprendre apparence normale, toi pas profiter pour me regarder nue sinon poochan devoir tuer serviteur.');
INSERT INTO `npc_questions` VALUES (2615, '', '', '', '', 'Poochan se sentir mieux ainsi, ? ton tour, toi prendre ?a, toi boire extrait  de source chacha et chercher personne ayant peur de toi, si toi trouver, toi pr?venir poochan');
INSERT INTO `npc_questions` VALUES (2616, '', '', '', '', 'Toi avoir trouv?  ?');
INSERT INTO `npc_questions` VALUES (2617, '', '', '', '', 'Lui avoir r?ussi ? ?chapper ? poochan, mais moi arracher morceau de v?tement ? lui et trouver ?tiquette avec son nom : Lanma Metoasa. Poochan connaitre p?re Metoasa, lui vivre pr?s de Dojo principal. Si Lanma fuir, moi forcer lui ? venir. Toi aller voir p?re, et convaincre lui de donner son fils ? Poochan, lui respecter ancienne tradition. Toi prendre ce plat avec toi, toi comprendre une fois l? bas.');
INSERT INTO `npc_questions` VALUES (2618, '', '', '', '', 'Toi avoir trouver p?re Metoassa et convaincre lui ?');
INSERT INTO `npc_questions` VALUES (2619, '', '', '', '', 'Grmph');
INSERT INTO `npc_questions` VALUES (2620, '', '', '', '', 'Groumph grumph \\n<Il vous indique rapidement qu\\\'il ne sait rien du tout>');
INSERT INTO `npc_questions` VALUES (2621, '', '', '', '', 'Grouuph \\n<il fait des roulades sur le sol pour vous amuser>');
INSERT INTO `npc_questions` VALUES (2622, '', '', '', '', 'Garouph \\n<il coince un ballon sur son museau et commence ? danser>');
INSERT INTO `npc_questions` VALUES (2623, '', '', '', '', 'Grimph \\n<Il fait mine de grignoter un bambou qui tra?ne>');
INSERT INTO `npc_questions` VALUES (2624, '', '', '', '', 'Arg ! Comment as-tu devin? que je n\\\'?tais pas un vrai Pandawa?! ');
INSERT INTO `npc_questions` VALUES (2625, '', '', '', '', 'Tu veux mon fils ! Mais vous vous ?tes tous donn? le mot ou quoi !  \\n*tout bas* Qu\\\'est ce qui le rend si populaire...ses cheveux ? \\nD?sol? mais mon fils est d?j? promis ? la fille du propri?taire du Dojo. Jamais je ne pourrai le c?der ? nouveau pour une somme inf?rieure ? 100000 Kamas.');
INSERT INTO `npc_questions` VALUES (2626, '', '', '', '', 'Cependant, vous avez l\\\'air s?rieusement amoureux, et cela compte beaucoup pour moi, si vous saviez comme j\\\'aime mon fils ! Je vous le c?de ? 50 000 !');
INSERT INTO `npc_questions` VALUES (2627, '', '', '', '', 'Et encore, je sens qu\\\'il pourra vraiment trouver le bonheur avec quelqu\\\'un tel que vous, 25 000 suffiront march? conclu !');
INSERT INTO `npc_questions` VALUES (2628, '', '', '', '', 'ah..euh...oui.. \\n*tout bas* mince je n\\\'ai pas l\\\'habitude que l\\\'on dise oui \\nEuh nous disions combien ?');
INSERT INTO `npc_questions` VALUES (2629, '', '', '', '', 'Oh et cette promesse n\\\'?tait pas quelque chose de vraiment s?rieux, si vous m\\\'offrez 5000 Kamas on peut n?gocier.');
INSERT INTO `npc_questions` VALUES (2630, '', '', '', '', 'Pnj(652) et Message(2627)');
INSERT INTO `npc_questions` VALUES (2631, '', '', '', '', 'Combien donc ?tes-vous pr?t ? mettre pour mon fils ?');
INSERT INTO `npc_questions` VALUES (2632, '', '', '', '', 'Mon fils contre un simple plat ?...VENDU ! \\n*il prend le plat et le mange le plus vite possible* \\nIl vous faudra cependant convaincre le chef de la famille Dento d\\\'annuler lui aussi la promesse \\n');
INSERT INTO `npc_questions` VALUES (2633, '', '', '', '', 'Bonjour noble aventurier, Sli Dento s\\\'incline devant vous, puis-je vous renseigner d\\\'une quelconque mani?re ?');
INSERT INTO `npc_questions` VALUES (2634, '', '', '', '', 'Pardon ?');
INSERT INTO `npc_questions` VALUES (2635, '', '', '', '', 'GEMMPAAA! \\n*souffle fort*\\nIl s\\\'agit d\\\'un malentendu, je ne peux rompre la promesse pour ma part sinon ma pauvre fille n\\\'aura plus personne pour se marier comprenez vous ?');
INSERT INTO `npc_questions` VALUES (2636, '', '', '', '', 'Que..quoi ? Euh...connaissez-vous ma fille ?  \\nEt puis vous ?tes...euh...enfin ici a Pandala tout est possible alors... \\nAh et puis zut, d?brouillez vous avec elle, c\\\'est elle qui choisira.');
INSERT INTO `npc_questions` VALUES (2637, '', '', '', '', 'Poochan ? poochan....Ah la petite pandawette ! Mais c\\\'est une fille ! Ah c\\\'est vrai qu\\\'? Pandala tout est possible...Nakunne pourrait le prendre mal... \\nD?sol? je ne peux pas, je laisse le choix ? Nakunne, d?brouillez -vous avec elle. \\n');
INSERT INTO `npc_questions` VALUES (2638, '', '', '', '', 'QUOI ! ROMPRE MON MARIAGE POUR ME MARIER AVEC QUI ?! \\nEcoute bien r?sidu de pandrista, JAMAIS DE LA VIE! Il faudra me passer sur le corps pour ?a !');
INSERT INTO `npc_questions` VALUES (2639, '', '', '', '', 'Quoi ? Tu veux me passer sur... Ah un d?fi ! \\nC\\\'est d\\\'accord ! Je vais t\\\'?crabouiller, te r?duire en pat? que je donnerai ? la pandawette qui te sers de chef une fois que je l\\\'aurais noy?e dans sa source ! Rendez-vous dans le dojo !');
INSERT INTO `npc_questions` VALUES (2640, '', '', '', '', 'Lanma ?tre libre ?');
INSERT INTO `npc_questions` VALUES (2641, '', '', '', '', 'Poochan tr?s contente, poochan donner secret ? vous pour utiliser source sans effet secondaire');
INSERT INTO `npc_questions` VALUES (2642, '', '', '', '', 'Je suis la personne la plus populaire de cette ?le, la plus jolie, la plus forte et je ne crains rien ni personne mouahahahaha. Hmm oui excusez-moi que voulez-vous ?');
INSERT INTO `npc_questions` VALUES (2643, '', '', '', '', 'AAAAAAAAAAAAAAH Va-t\\\'en ! Va-t\\\'en ! Va-t\\\'en ! Va-t\\\'en !');
INSERT INTO `npc_questions` VALUES (2644, '', '', '', '', '*Gasp* Poochan !  \\nBon..bonjour');
INSERT INTO `npc_questions` VALUES (2645, '', '', '', '', 'Gempa ? Hmm ? cette heure ci il doit s\\\'entrainer au Dojo, o? chercher de la nourriture en grande quantit');
INSERT INTO `npc_questions` VALUES (2646, '', '', '', '', 'Je pense que je vais vite devoir pr?parer un nouveau voyage initiatique.');
INSERT INTO `npc_questions` VALUES (2647, '', '', '', '', 'Toi devoir convaincre Maitre Dento de rompre promesse ? Poochan pas vouloir savoir comment toi faire mais toi r?ussir vite. ');
INSERT INTO `npc_questions` VALUES (2648, '', '', '', '', 'Pourquoi ma fille a ce caract?re si sp?cial, je n\\\'arriverai jamais ? la marier.');
INSERT INTO `npc_questions` VALUES (2649, '', '', '', '', 'Je me pr?pare et j\\\'arrive, toi la larve bleue, tu m\\\'attends au Dojo !');
INSERT INTO `npc_questions` VALUES (2650, '2259;2262;2260', '', '', '', 'Le Pandasiman, ou \\\'maitrise de l\\\'esquive au bouclier\\\', est l\\\'une des ?coles Pandawushu les plus efficaces. Contrairement ? l\\\'art du bouclier Feca qui a d?velopp? une technique de protection pure, cette ?cole apprend ? utiliser le bouclier comme un moyen de parer. La particularit? de cet art est donc d\\\'utiliser le bouclier non pas passivement mais activement.');
INSERT INTO `npc_questions` VALUES (2651, '', '', '', '', 'L\\\'art n?cessitant beaucoup de mouvements avec le bouclier, les boucliers d?butants seront l?gers et pas n?cessairement solides. Cependant les ma?tres Pandasiman arrivent ? ma?triser leurs mouvements avec de tr?s lourds et solides boucliers, presque ?quivalent aux anciens boucliers feca, qu\\\'ils manient avec rapidit? et fluidit?. Cumulant ainsi la protection passive pure ? la technique de parade.');
INSERT INTO `npc_questions` VALUES (2652, '', '', '', '', 'La sagesse provoque vos paroles, ou cela est de la stupidit?. Cet art a effectivement une faiblesse, qui se trouve ?tre une force en m?me temps. L\\\'art Pandasiman s\\\'est developp? pour limiter les pertes lors des guerres pandawaiennes. Tous nos boucliers, ainsi que toutes les parades sont developp?s pour un adversaire particulier, un style de combat particulier. ');
INSERT INTO `npc_questions` VALUES (2653, '', '', '', '', 'Nous avons int?gr? les ?coles de combat les plus c?l?bres : griffe joueuse d\\\'Ecaflip, magie naturelle des Sadidas...Nous excellons donc en duel contre ces derniers, mais quand il s\\\'agit de combattre un adversaire moins connu...Notre ?cole est en pleine ?volution, et nul doute que bient?t notre art englobera la connaissance de tout les styles de combat existant, et donc sera universellement efficace.');
INSERT INTO `npc_questions` VALUES (2654, '', '', '', '', 'Le plus simple pour apprendre : s\\\'?quiper de l\\\'un de nos boucliers, et combattre. Nos boucliers sont sp?cialement contruits pour favoriser un mouvement de parade instinctif. Ainsi nous gagnons du temps pour entra?ner les nouveaux. Ce mouvement de base est nomm? Pare-Pandasiman, c\\\'est l\\\'essence de notre art.  \\nCelui-ci se d?cline ensuite en mouvements du plus en plus complexes que seuls les ma?tres sont aptes ? r?aliser.');
INSERT INTO `npc_questions` VALUES (2655, '', '', '', '', 'Le forgeur de bouclier t\\\'envoie ?  Tr?s bien, ?quipe-toi de ton bouclier d\\\'entrainement, si tu es pr?t, dis-le moi.');
INSERT INTO `npc_questions` VALUES (2656, '', '', '', '', 'Demande au ma?tre de Pandasiman de te montrer un peu comment l\\\'utiliser au mieux. Il doit ?tre dans le Dojo.');
INSERT INTO `npc_questions` VALUES (2657, '', '', '', '', 'Quoi tu as perdu ton bouclier avant l\\\'entra?nement ?\\nSi tu veux que je t\\\'en fabrique un nouveau apporte-moi 10 bois de bambou');
INSERT INTO `npc_questions` VALUES (2658, '', '', '', '', 'Le dieu X?lor m\\\'a fait l\\\'honneur de me nommer Surveillant du Temps. A moins que tu ne d?cides de me tuer, il est hors de question que tu prennes ma place.');
INSERT INTO `npc_questions` VALUES (2659, '', '', '', '', 'J\\\'ai effectivement un service ? te demander, j\\\'aimerais que tu rendes visite ? Amine au temple X?lor, et que tu lui transmettes cette lettre pour le pr?venir des dangers vers lesquels nous nous dirigeons in?luctablement... de mon c?t?, je continue de chercher un moyen de stopper l\\\'in?vitable... \\n \\nJe rajouterai quelques pr?cieuses minutes au sablier de ton esp?rance de vie si tu effectues cette course pour moi...');
INSERT INTO `npc_questions` VALUES (2660, '', '', '', '', 'D?sol?, je n\\\'ai pas de temps ? t\\\'accorder : l\\\'Horloge Divine semble se d?r?gler... Cela semble impossible mais un d?calage dans la trame temporelle peut survenir ? tout moment ! En tant que surveillant du temps, je ne peux quitter ces horloges des yeux ! \\n \\nDurant les 5 minutes pr?c?dant chaque heure, je peux exceptionnellement rel?cher ma vigilance, reviens me parler ? ce moment-l?...');
INSERT INTO `npc_questions` VALUES (2661, '', '', '', '', 'L\\\'Horloge Divine vit sa propre vie, et elle se stabilise d\\\'elle-m?me malgr? les interf?rences magiques du Monde et de l\\\'Univers. Lorsqu\\\'elles deviennent importantes, il arrive que les portes du temps s\\\'entrouvent... suffisamment pour que des d?mons redoutables s\\\'infiltrent dans notre Monde : \\\"Les d?mons des heures\\\". \\nDepuis quelque temps, l\\\'agitation qui se cr?e autour des Dofus, provoque des fluctuations temporelles de plus en plus importantes, je te laisse donc deviner la suite...');
INSERT INTO `npc_questions` VALUES (2662, '', '', '', '', 'Tu as fait vite, merci infiniment ! \\nDonc selon toi Amine me sugg?re d\\\'utiliser du Kouartz ? Je vois o? il veut en venir... il veut que j\\\'utilise le pouvoir ancestral des X?lors pour remonter le temps et emp?cher que cette br?che temporelle ne se forme ! \\n \\nMais il y a deux probl?mes ? ?a... premi?rement, je n\\\'ai pas de Kouartz, et deuxi?mement je ne peux pas invoquer ce sort sur moi m?me... je crois que l\\\'avenir de notre monde repose sur toi, si tu vois ce que je veux dire...');
INSERT INTO `npc_questions` VALUES (2663, '', '', '', '', 'Tr?s bien ! Gr?ce ? ce Kouartz on devrait pouvoir r?aliser une B.E.T.A. (une Balade dans l\\\'Espace et le Temps d\\\'Amakna). \\nJe vais t\\\'envoyer dans le village d\\\'Amakna durant l\\\'ann?e 633, avant que tout cette agitation ne se produise. Comme je n\\\'ai confiance qu\\\'en moi-m?me, tu devras simplement me donner cette lettre... enfin... la donner au \\\"moi\\\" du pass?... \\n \\nTu es pr?t ?');
INSERT INTO `npc_questions` VALUES (2664, '', '', '', '', 'Je pense que je vais finir par installer un m?canisme pour prot?ger l\\\'entr?e de cette salle de l\\\'horlogerie, il y a de plus en plus de personnes dans ce village qui prennent ce b?timent pour un moulin ! \\n \\nJe n\\\'ai pas beaucoup de temps ? t\\\'accorder, en tant que surveillant du temps, je ne peux quitter ces horloges des yeux... je t\\\'?coute ?');
INSERT INTO `npc_questions` VALUES (2665, '', '', '', '', 'Hmm, je ne suis pas r?ellement surpris que tu viennes du futur, je re?ois la visite d\\\'un coursier inter-temporel environ toutes les semaines ! \\nMais je n\\\'avais jamais re?u de message du futur pour un ?v?nement aussi proche, cette nouvelle concernant les d?mons des heures est forte inqui?tante...');
INSERT INTO `npc_questions` VALUES (2666, '', '', '', '', 'Des innocents sont en danger au cimeti?re, moi Nergal, serviteur du dieu Iop, de la veuve et de l\\\'orphelin, je prie ta personne de me c?der une rune de t?l?portation vers ce lieu afin de m\\\'y rendre le plus promptement possible !');
INSERT INTO `npc_questions` VALUES (2667, '', '', '', '', 'Si tu veux troquer des objets avec moi, recule de cinq pas, et d?pose-les par terre, et je ferais de m?me, h?h?h?...');
INSERT INTO `npc_questions` VALUES (2668, '', '', '', '', 'Je souffre, mon dernier combat a failli m\\\'?tre fatal, tu n\\\'aurais pas une pomme pour que je puisse me soigner ?');
INSERT INTO `npc_questions` VALUES (2669, '', '', '', '', 'Ne te fie pas ? mon apparence, je ferais un adversaire redoutable si tu veux me d?fier...');
INSERT INTO `npc_questions` VALUES (2670, '', '', '', '', 'de rien.  Que la d?esse vous prot?ge touri...aventurier !');
INSERT INTO `npc_questions` VALUES (2671, '', '', '', '', 'L\\\'?tat des Enutrofs que je soigne ici m\\\'inqui?te, la plupart viennent des mines d\\\'Astrub, allez voir Gasdaure, c\\\'est elle qui m\\\'envoie tout ces malades. Si vous voulez m\\\'aider, aidez-la !');
INSERT INTO `npc_questions` VALUES (2672, '2560', '', '', '0', 'OoOoMm Pandawa OoOoMm - (il prie)');
INSERT INTO `npc_questions` VALUES (2673, '', '', '', '', 'Je te conseille d\\\'aller te reposer ? l\\\'auberge du village central, tu as l\\\'air ?puis? d\\\'avoir parcouru toute l\\\'?le pour m\\\'apporter cette fiole.');
INSERT INTO `npc_questions` VALUES (2674, '', '', '', '', 'Tiens, tiens... Alors toi, on peut dire que tu es n? de la derni?re pluie, hein ? Sois le bienvenu dans le Monde des Douze ! Ouvre grand tes yeux : tu viens de na?tre sur l\\\'?le ancestrale de notre peuple. Face ? toi se trouve la statue de notre d?esse bien-aim?e.');
INSERT INTO `npc_questions` VALUES (2675, '', '', '', '', 'Que la mousse de la c?leste chopine t\\\'?touffe, toi et tes descendants pour des si?cles et des si?cles ! On peut dire que tu commences bien dans la vie... En fait tu n\\\'as pas le choix !');
INSERT INTO `npc_questions` VALUES (2676, '', '', '', '', 'Ne reviens pas me voir avant de m\\\'apporter ce que je t\\\'ai demand? : une Pandapils !');
INSERT INTO `npc_questions` VALUES (2677, '', '', '', '', 'Parfait ! Va donc voir un de nos fabuleux marchands ambulants ! Ils poss?dent de quoi contenter la d?esse...');
INSERT INTO `npc_questions` VALUES (2678, '', '', '', '', 'Aah ! Maintenant tu es des NOTRES ! Que le bambou fleurisse sous tes pas, et fermente gr?ce ? ton haleine ! Va voir le Shaman Surivitna, il t\\\'enseignera ce que tout Pandawa doit savoir.');
INSERT INTO `npc_questions` VALUES (2679, '', '', '', '', 'Prier, c\\\'est bien. Faire des offrandes, c\\\'est mieux ! D\\\'ailleurs la d?esse fronce les sourcils en me parlant de ton cas. Ne serais-tu pas digne d\\\'?tre un de ses disciples ? Hum... Je sais !  Pour qu\\\'elle te reconnaisse comme l\\\'un de ses disciples, il faudrait que tu lui offres une de ces boissons qui la rendent euphorique... \\n');
INSERT INTO `npc_questions` VALUES (2680, '', '', '', '', 'Ahahahah ! Ce n\\\'est pas ? un Pandawa que je vais apprendre ?a ! \\n');
INSERT INTO `npc_questions` VALUES (2681, '', '', '', '', 'Hola ! Tu aimes ce doux parfum de bambou ferment? ?! Alors on va s\\\'entendre... Qu\\\'est-ce que tu veux ?');
INSERT INTO `npc_questions` VALUES (2682, '', '', '', '', 'Hola ! Tu aimes ce doux parfum de bambou ferment? ?! Alors on va s\\\'entendre... Qu\\\'est-ce que tu veux ?');
INSERT INTO `npc_questions` VALUES (2683, '', '', '', '', 'Hola ! Tu aimes ce doux parfum de bambou ferment? ?! Alors on va s\\\'entendre... Qu\\\'est-ce que tu veux ?');
INSERT INTO `npc_questions` VALUES (2684, '', '', '', '', 'Triple chope ! Les amateurs de boissons ferment?es, je les reconnais ? cent pas ! Que puis-je te servir ?');
INSERT INTO `npc_questions` VALUES (2685, '', '', '', '', 'Tu veux ?tancher ta soif ? Ne cherche plus, je suis la Pandawa qu\\\'il te faut ! Tu d?sires ?');
INSERT INTO `npc_questions` VALUES (2686, '', '', '', '', 'Tu jouis de rien du tout, sinon je te colle ma main en travers de la figure !');
INSERT INTO `npc_questions` VALUES (2687, '', '', '', '', 'Par les pintes de la d?esse ! Tu as besoin d\\\'un petit remontant ? J\\\'ai de quoi te contenter. Que souhaites-tu acheter ?');
INSERT INTO `npc_questions` VALUES (2688, '', '', '', '', 'Par les pintes de la d?esse ! Tu as besoin d\\\'un petit remontant ? J\\\'ai de quoi te contenter. Que souhaites-tu acheter ?');
INSERT INTO `npc_questions` VALUES (2689, '3719;2532', '', '', '', 'Je suis le meilleur fabriquant de bouclier pandawa?en au monde ! Mais met mes apprentis au d?fi de me surpasser, c\\\'est comme ?a que l\\\'on progresse le plus vite, autant eux, que moi, retenez bien cela.');
INSERT INTO `npc_questions` VALUES (2690, '', '', '', '', 'Je suis le meilleur fabricant de bouclier pandawa?en au monde ! Et je mets mes apprentis au d?fi de me surpasser, c\\\'est comme ?a que l\\\'on progresse le plus vite, autant eux, que moi, retenez bien cela.');
INSERT INTO `npc_questions` VALUES (2691, '', '', '', '', 'Bien bien, si vous ?tes ici pour la livraison, vous pouvez m\\\'expliquer pourquoi vous n\\\'avez pas la totalit? de la commande ? Si vous en avez perdu en route ce n\\\'est pas mon probl?me, je veux 10 bois de bambous, pas un de moins. Faites attention, tout le monde n\\\'est pas aussi gentil que moi !');
INSERT INTO `npc_questions` VALUES (2692, '', '', '', '', 'H? bien ! Qui voil? ?! Un disciple de la d?esse Pandawa : sois bienvenu parmi nous ! C\\\'est pour une initiation ? Pas le temps !');
INSERT INTO `npc_questions` VALUES (2693, '', '', '', '', 'Effectivement, tu as l\\\'air bien plus solide ! Je peux maintenant partager mes soucis avec toi. Figure-toi que certains d\\\'entre-nous sont nerveux depuis que de nouveaux arrivants foulent notre ?le ancestrale. De plus en plus n\\\'ob?issent plus aux lois du Grandapan ! Les Pandikazes, ces rebelles, sont les pires de tous ! Et cette myst?rieuse maladie qui touche les Enutrofs d\\\'Astrub, n\\\'arrange rien ! Chaque jour de nouveaux Enutrofs arrivent ici... Je suis d?bord? ! Voyez par vous m?me, discutez donc avec Pyrite...');
INSERT INTO `npc_questions` VALUES (2694, '', '', '', '', 'Oyahoh ! Les amis de mes amis sont mes amis ! Et comme les Pandawas sont tous mes amis, t\\\'es forc?ment un ami !');
INSERT INTO `npc_questions` VALUES (2695, '', '', '', '', 'Enchant? ! Sans me vanter, j\\\'ai vaillamment prot?g? ma ville, la belle cit? d\\\'Astrub contre une invasion de bestioles pas rago?tantes ! Bref : j\\\'ai entendu ta conversation avec le Shaman (un chic Pandawa ?ui l?) tu devrais aller voir le Grandapan. C\\\'est lui qui fait la pluie et le beau temps par ici.');
INSERT INTO `npc_questions` VALUES (2696, '', '', '', '', 'Tiens, tu lui remettras cette sublime r?plique de Dofus de la part des Enutrofs d\\\'Astrub. Nous autres, on est coinc?s en quarantaine.');
INSERT INTO `npc_questions` VALUES (2697, '', '', '', '', 'Ouais, enfin un faux Dofus... mais sculpt? dans du minerai pr?cieux, par une Enutrofette habile de ses mains, j\\\'te le dis !');
INSERT INTO `npc_questions` VALUES (2698, '', '', '', '', 'Chut ! Ecoute... Tu entends ? Notre d?esse te remercie par ma bouche : il est vrai que ce Dofus est tr?s ressemblant ! Le Grandapan admire les pr?cieux Dofus... Demande au Grandapan ce que tu veux...');
INSERT INTO `npc_questions` VALUES (2699, '', '', '', '', 'Le Grandapan sait beaucoup de choses ! As-tu seulement vu l\\\'authentique relique des temps anciens, notre r?ceptacle aux Dofus ? N\\\'est-ce pas la preuve que la l?gende dit vrai ? Vas-y voir, je te laisse juger par toi-m?me.');
INSERT INTO `npc_questions` VALUES (2700, '', '', '', '', 'L\\\'oeil de la d?esse est braqu? sur toi... Elle me susurre qu\\\'un destin glorieux t\\\'attend. Tu ferais bien de voir le R?ceptacle aux Dofus. Ensuite, rends toi aupr?s du Sage L?nald qui habite pas loin de l');
INSERT INTO `npc_questions` VALUES (2701, '', '', '', '', 'Parce que le Grandapan a un pied dans Pandala et un pied dans le royaume des dieux ! Je suis l? et je ne suis pas l?. Et j\\\'entends battre le coeur des Dofus, de tous les Dofus ! La d?esse a dit au Grandapan que lorsque les Dofus seront r?unis, l\\\'?lu sera b?ni des dieux ! \\n');
INSERT INTO `npc_questions` VALUES (2702, '', '', '', '', 'Bonjoul ! Soil le bienvenul dans ma demeule. Tu as l\\\'oeil scintillant comme l\\\'astle de la nuit : ton coeul est pul... Que puis-je poul toi ?');
INSERT INTO `npc_questions` VALUES (2703, '', '', '', '', 'J\\\'en sais bien peul, mon amil, mais assez toutefoil poul te contenter. Polte une fiole de Pandapiler ? mon vieil ami,  le maitre du village d\\\'Akwadala, et je te dilai tout ce que je sais sur le Dofus de Pandala.');
INSERT INTO `npc_questions` VALUES (2704, '', '', '', '', 'J\\\'ai dit : d\\\'aborl apporter une Pandapiler ? mon vieil ami, le Maitre d\\\'Akwadala');
INSERT INTO `npc_questions` VALUES (2705, '', '', '', '', 'Tu as fait un don de ta personne pour notre peuple, tu as appris ses coutumes et tu commences ? t\\\'impr?gner de notre art de combattre aussi. Tu m?rites de tout savoir sur le Dofus de Pandala... c\\\'est ce que pense le sage L?nald. C\\\'est lui qui m\\\'envoie... Te sens tu pr?t ?');
INSERT INTO `npc_questions` VALUES (2706, '', '', '', '', 'Je vois ? ton oeil injectl? de sang que tu tles acquittl? de ta mission ! Tu m?ritles de conna?tle l\\\'histoile de notle peuple... qui est li?e ? celle des Dofus !');
INSERT INTO `npc_questions` VALUES (2707, '', '', '', '', 'Les L?nalds ?taient jadis les plotecteurs d\\\'un Dofus. Jalous?s par les Pandawas de Feudala, ceux-ci complot?rent avec ces inf?mes Wabbits ! Et nous, les L?nalds, nous avons ?t? chass?s de notle ?le... Quant au Dofus, nul ne sait ce qu\\\'il en est advenu... Une chose est sule : ni les Pandawas de Feu ni les Pandikazes ne l\\\'ont... ils l\\\'aulaient ploclam? haut et folt ! Quant aux Pandawas d\\\'Akwadala ils sont mes amis. Restent ceux d\\\'Aerdala... Tu me lendlais un fiel selvice si tu allais y jeter un coup d\\\'oeul... Encole l? ? Qu\\\'attends-tu ?');
INSERT INTO `npc_questions` VALUES (2708, '', '', '', '', 'Tu tiens ? ce que ta t?te parfume un tonneau de Pandneken ? Tu n\\\'as plus le choix de toutes fa?ons...');
INSERT INTO `npc_questions` VALUES (2709, '', '', '', '', 'Une r?union secr?te se tient en ce moment m?me ? Aerdala. Nous autres ignorons ce qui se trame l?-bas... Mais une chose est s?re : il y sera question des Dofus. Le sage Lenald souhaite t\\\'envoyer toi, il est difficile de faire confiance ? l\\\'un des n?tres en ce moment, les pandikazes sont partout. Mais Ma?tre Lenald est certain qu\\\'il peut te faire confiance. Fais attention : Plus d\\\'un aventurier s\\\'est fait mal accueillir en allant ? Aerdala. On les dit alli?s des Pandawas rebels, ceux qui sabotent tous les acc?s de l\\\'?le. Il faut que tu t\\\'infiltres et que tu nous rapportes un maximum d\\\'information. Retourne voir le sage... si tu reviens en vie.');
INSERT INTO `npc_questions` VALUES (2710, '', '', '', '', 'YohOohHhOo Pandawa, b?nis mes boucliers steuplait ! Mmmh ? Ah, je ne t\\\'avais pas vu ! Je peux t\\\'aider ?');
INSERT INTO `npc_questions` VALUES (2711, '', '', '', '', 'Je forge un bouclier pour le Pandasiman... C\\\'est un ma?tre dans l\\\'art du combat au bouclier. Il n\\\'utilise que d\\\'un bouclier b?ni par mes soins, et le sien lui ? ?t? d?rob? par les Pandikazes.');
INSERT INTO `npc_questions` VALUES (2712, '', '', '', '', 'Mieux on en sait sur eux, mieux on se porte !');
INSERT INTO `npc_questions` VALUES (2713, '', '', '', '', '... Et tous ces aventuriers qui infestent notre ?le seront bient?t malades de la Pandrista !... Mais ? Nous avons de la visite ?! Une nouvelle recrue Pandikaze on dirait ?');
INSERT INTO `npc_questions` VALUES (2714, '', '', '', '', 'Notre mission est de bouter la vermine aventuri?re hors de notre ?le bien-aim?e. Pour cela, tous les moyens sont bons : saboter les ponts, voler toutes les chaussures gauches, empoisonner les... tra?tres. Bien ! Si tu veux ?tre des n?tres, tu connais certainement la r?ponse ? cette ?nigme :\\nTout le monde connait le son produit par deux chopes qui trinquent, mais quel est le son d\\\'une seule chope ?');
INSERT INTO `npc_questions` VALUES (2715, '', '', '', '', 'Faux et archifaux ! Je doute que tu sois venu ici pour devenir un Pandikaze...');
INSERT INTO `npc_questions` VALUES (2716, '', '', '', '', 'En qu?te d\\\'un Dofus, hein ? Ces oeufs attirent violence et d?solation partout o? ils se trouvent... A Pandala, on parle beaucoup d\\\'eux depuis quelques temps... Mais j\\\'ai mon id?e sur le sujet : les oeufs sont inoffensifs ! C\\\'est toute la bande d\\\'aventuriers cupides ? dont tu fais partie - qu\\\'il faudrait exterminer pour avoir la paix...');
INSERT INTO `npc_questions` VALUES (2717, '', '', '', '', 'Ne nie pas ! Je sais que tu as apport? un de ces maudits Dofus sur notre ?le ! On t\\\'a vu sortir de la maison du Shaman ! Tu as enfreint la r?gle n?1 des Pandikazes : \\\" Z?ro Dofus sur Pandala \\\". Je te condamne ? l\\\'ingestion de Pandneken jusqu\\\'? ce que mort s\\\'ensuive ! Tu seras ex?cut? demain. Qu\\\'on le m?ne ? la prison, et bonne nuit !');
INSERT INTO `npc_questions` VALUES (2718, '', '', '', '', 'La d?esse Pandawa garde toujours un oeil sur son verre, et un oeil sur toi, souviens-t\\\'en');
INSERT INTO `npc_questions` VALUES (2719, '2327', '10000', '', '', 'La d?esse t\\\'a bien inspir? en guidant tes pas jusqu\\\'au Dojo. Je vais t\\\'enseigner de ce pas l\\\'art ultime et sublime que l\\\'on nomme Pandawushu... La cotisation s\\\'?l?ve ? 10000 kamas, payables d\\\'avance...');
INSERT INTO `npc_questions` VALUES (2720, '', '', '', '', 'On le dit. Ses chemins sont tortueux et les cr?atures qui la hantent sont peu amicales. Mais un certain Wally Elconom a r?ussi ? en dresser la carte. Il serait utile que tu le rencontres. On le voit souvent du c?t? d\\\'Amakna.');
