INSERT INTO `npc_questions` VALUES (2732, '', '', '', '', 'On le dit. Ses chemins sont tortueux et les cr?atures qui la hantent sont peu amicales. Mais un certain Wally Elconom ? r?ussi ? en dresser la carte. Il serait utile que tu le rencontres. On le voit souvent du c?t? d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (2733, '', '', '', '', 'Vous ?tes bien s?r de vous pour m\\\'aborder de cette fa?on. De quoi s\\\'agit-il ?');
INSERT INTO `npc_questions` VALUES (2734, '', '', '', '', 'Une carte ? N\\\'exag?rons rien ! Disons un simple aide-m?moire... A dire vrai, je n\\\'ai pas encore eu le temps de dessiner une carte de la for?t mal?fique qui soit digne de ce nom...Ce que je d?sirais faire c\\\'est un livre qui rassemble toutes les bonnes balades qu\\\'il y a ? faire l?-bas. C\\\'est un endroit id?al pour les aventuriers vous savez.');
INSERT INTO `npc_questions` VALUES (2735, '', '', '', '', 'Mettre les pieds dans un endroit pareil, moi ? Jamais ! Mais je me suis enquis de la route la plus courte aupr?s des autochtones. Je tiens ? pr?ciser que j\\\'ai ?t? tr?s s?lectif dans mes recherches : je n\\\'ai interrog? que ceux qui disaient ?tre revenus de la for?t ET A QUI IL MANQUAIT DES MEMBRES. \\nComme vous m\\\'?tes presque sympathique, je vous confie cet ouvrage. Jamais eu le temps de le finir, il n\\\'y a que cette route qui vous m?nera ? la clairi?re du Dark Vlad, de toute fa?on je doute qu\\\'il y ait autre chose d\\\'int?ressant l?-bas.');
INSERT INTO `npc_questions` VALUES (2736, '', '', '', '', 'Nous autres ? Pandala, on s\\\'y entend ? faire fermenter des choses diverses et avari?es. On trouve toujours un moyen d\\\'en faire une gn?le de premi?re qualit? ! Mais attention, n\\\'abuse pas des boissons fortes : elles pourraient te conduire ? attaquer des percepteurs et... ? les ?pargner.');
INSERT INTO `npc_questions` VALUES (2737, '', '', '', '', 'Crois-en un vieux Pandawa qui a navigu? sur les mers de ce Monde : ici, tu d?penseras beaucoup de kamas dans la boisson et les armes. Et le reste, tu le gaspilleras... A propos d\\\'armes, ?a me rappelle la fois, quand j\\\'?tais disciple Pandawushuka... comment ? Je t\\\'ai pas racont? ? Alors une fois, je me trouve en face de cinq Pandawas rebelles. Ils ?taient en train de saboter... ou quelque chose dans le genre... Heureusement, j\\\'avais une Pandarium Tremens sur moi ! Bref, je d?gaine ma fiole, on fait la paix, et en un rien de temps, on ?tait copains comme des vieux Porkass... Depuis j\\\'en garde pr?cieusement sur moi, c\\\'est toujours utile pour faire une tr?ve. Et une autre fois, blablablabla...');
INSERT INTO `npc_questions` VALUES (2738, '', '', '', '', 'Tu savais que Simgood le marin voulait prendre sa retraite ? J\\\'en reviens pas ! Mais c\\\'est pas ? un vieux Pandawa qu\\\'on append ? trinquer, comme on dit. C\\\'est sans doute un de ses trucs pour me piquer mes points de p?che... Ce vieux mulou de mer doit ?tre en train de pr?parer un coup, je te le dis. Pas honn?tes pour un kama, ces gens de Madrestam.');
INSERT INTO `npc_questions` VALUES (2739, '2358', '', '', '', 'Tu cherches ? t\\\'embarquer ? Tu fais bien de venir me voir ! Pour 100 kamas, je t\\\'emm?ne au port de Madrestam. C\\\'est l?-bas que se trouve le bateau du captain Lily, lorsqu\\\'il est en cale s?che. Un fier navire et un sacr? bout de femme, je te le dis. Je me laisserai bien tenter, tu sais... Malheureusement, les coutumes de Pandala et D\\\'Amakna divergent, et divergent c\\\'est ?norme.');
INSERT INTO `npc_questions` VALUES (2740, '', '', '', '', 'Bonjour Disciple #1, nous sommes Samedi, il est peut-?tre temps de me montrer ce que tu as appris ? \\nN\\\'oublie pas de mettre ta tenue, pour commencer le test.');
INSERT INTO `npc_questions` VALUES (2741, '2368;2369', '', '', '', 'Tu montres de l\\\'ardeur ? vouloir t\\\'entra?ner, et cela me pla?t. Mais si tu comptes fouler le sol de mon Dojo habill? de la sorte, tu te trompes. Lourdement. Et rien ne me prouve que tu sois en bonne sant? : d\\\'ailleurs, on t\\\'as d?j? dit que tu avais le fond de l\\\'oeil rouge?tre ? Non ? H? bien maintenant c\\\'est fait ! Mets toi en qu?te d\\\'un certificat shamanique, et d\\\'une tenue d\\\'entra?nement. \\n \\n');
INSERT INTO `npc_questions` VALUES (2742, '2359', '', '', '', 'Que mille bambous te flattent l\\\'?chine, noble aventurier ! Tu m\\\'es sympathique, laisse-moi te dire ceci... ');
INSERT INTO `npc_questions` VALUES (2743, '2360', '', '', '', 'Prend soin d\\\'?viter les sources maudites : Tu sais peut-?tre que notre d?esse a pris une seule cuite dans sa vie, mais qu\\\'elle dure depuis mille ans ? H? bien, sa divine beuverie lui fit rendre tripes et boyaux, ce qui a cr?? des petites sources d\\\'eau magique au carrefour d\\\'ici, de Terrdala et d\\\'Akwadala. Gare ? toi ! cette eau avait le pouvoir d\\\'emprisonner l\\\'?me de la premi?re personne y tombant...certainement ? cause de l\\\'odeur. Toute personne qui y tombe subit la mal?diction de l\\\'eau : elle se transforme et prend l\\\'apparence de la derni?re ?me emprisonn?e... qui essaye ainsi probablement de sortir de cette eau croupie.');
INSERT INTO `npc_questions` VALUES (2744, '2366', '', '', '0', 'Je vois ? tes piels que tu as palcoulu un long chemin pour venil me voil, que d?siles tu ?');
INSERT INTO `npc_questions` VALUES (2745, '', '', '', '', 'Je vois, laisse-moi te laconter l\\\'histoile du Dofus Cawotte  : Lolsque le Wa Wabbit nous a chass? de notle ?le, il a l?pendu la lumeur qu\\\'il d?tenait un Dofus, attilant ainsi de nombleux aventuliers qu\\\'il pouvait facilement d?pouiller gl?ce ? ses glands pouvoirs. Se diveltil en s\\\'enlichissant, voil? une activit? qui lendait le Wa heuleux.');
INSERT INTO `npc_questions` VALUES (2746, '', '', '', '', 'Oui, une lumeul. Le Wa a affilm? qu\\\'il d?tenait le Dofus d\\\'une Cawotte Dlaconesque : le Dofus Cawotte. Et je pl?cise bien lumeul, cal nul ne pouvait d?cemment confilmer ou infilmer la chose. Petit ? petit celtains aventuliers sont levenus d\\\'un intletien avec le Wa en ayant vu un oeuf magique, ce qui a contlibu? ? rendle cl?dible la lumeul...poultant, il ne faut jamais ?tle s?l de soi, et c\\\'est l? la molale de mon histoile.');
INSERT INTO `npc_questions` VALUES (2747, '', '', '', '', 'Te rends-tu compte ? Pour les garder frais, il faut cueillir les Bambous avec la queue. Moi, j\\\'ai d?j? du mal avec une main ! Enfin bref ! Je pr?f?re cueillir du Bambou que d\\\'arnaquer les aventuriers. Chez les marchands, y\\\'a des fieff?s coquins : m\\\'?tonnerait pas qu\\\'on essaye de te refiler un dofus pondu par une dragodinde. Tu vois le genre...');
INSERT INTO `npc_questions` VALUES (2748, '', '', '', '', 'Tu trouveras ici le meilleur choix de boissons ferment?es de toute l\\\'?le. Et si d\\\'autres t\\\'ont dit ?a, ils mentent. Une chose ? savoir avant de boire : si tu te livres ? la boisson de fa?on exag?r?e, ?te de ton esprit l\\\'envie d\\\'aller te soulager derri?re un bambou. Si un garde te voyait, le trop plein de ta vessie serait le dernier de tes soucis.');
INSERT INTO `npc_questions` VALUES (2749, '', '', '', '', 'Je vois dans tes yeux que tu d?sires te rendre ? la for?t mal?fique, exact ?');
INSERT INTO `npc_questions` VALUES (2750, '', '', '', '', 'Tu d?sires te balader dans la for?t maudite ? Il faut que tu passes une petite ?preuve pour cela : Bats ce dopeul et tu nous prouveras que tu es digne de t\\\'aventurer dans la for?t maudite. Et uniquement faire un petit tour, hein, n\\\'esp?re pas provoquer le Dark Vlad en duel !');
INSERT INTO `npc_questions` VALUES (2751, '', '', '', '', 'Le Shaman me semble ?tre quelqu\\\'un de comp?tent en mati?re de certificat. Va le trouver.');
INSERT INTO `npc_questions` VALUES (2752, '', '', '', '', 'La tenue pour pratiquer le Pandawushu se compose d\\\'une cape traditionnel et d\\\'un bandeau Bandeau Pandawushu, n\\\'importe quel tailleur doit ?tre capable de la r?aliser \\nIl est n?cessaire de porter cette tenue pour chaque passage de grade, donc prends-en grand soin !');
INSERT INTO `npc_questions` VALUES (2753, '', '', '', '', 'Que veux tu savoir jeune disciple #1 ?');
INSERT INTO `npc_questions` VALUES (2754, '', '', '', '', 'Tu es courageux, mais es-tu suffisamment fort ? Je te mets au d?fi de battre l\\\'un de mes ?l?ves. Il a rev?tu sa tenue de combat sp?cialement pour toi !');
INSERT INTO `npc_questions` VALUES (2755, '', '', '', '', 'Si tu r?ponds ? ces questions concernant l\\\'art Pandawushu, et que tu es suffisamment exp?riment?, tu obtiendras ton grade.');
INSERT INTO `npc_questions` VALUES (2756, '', '', '', '', 'Tu es fort, mais es-tu suffisamment intelligent ? Je te mets au d?fi de battre un autre de mes ?l?ves. Il a rev?tu sa tenue de combat sp?cialement pour toi !');
INSERT INTO `npc_questions` VALUES (2757, '', '', '', '', 'Tu pr?tends au grade de Yonkwan ? Permets-moi de te poser quelques questions tactiques : ');
INSERT INTO `npc_questions` VALUES (2758, '', '', '', '', 'Pour passer le grade de Gokwa, tu devras battre un disciple du m?me grade que toi en d?fi singulier devant moi ! \\nN\\\'oubliez pas de vous ?quiper de votre tenue !');
INSERT INTO `npc_questions` VALUES (2759, '', '', '', '', 'Pour passer le grade de Rokwa, tu devras battre un disciple du m?me grade que toi en d?fi singulier devant moi ! \\nN\\\'oubliez pas de vous ?quiper de votre tenue !');
INSERT INTO `npc_questions` VALUES (2760, '', '', '', '', 'Hormis le Pandawushu originel, combien de styles compte notre art martial ?');
INSERT INTO `npc_questions` VALUES (2761, '', '', '', '', 'Je dois m\\\'occuper du passage de grade de nombreux adeptes, si tu veux retenter un passage, reviens me voir d\\\'ici une heure au minimum !');
INSERT INTO `npc_questions` VALUES (2762, '', '', '', '', 'Admettons que tu aies un Pandawa de Feu pour ami - ce n\\\'est qu\\\'une supposition, nous sommes d\\\'accord... Tu souhaites lui faire un cadeau digne de ce nom afin qu\\\'il puisse ravager et d?truire en tout qui?tude... Quelle cape lui offriras-tu ?');
INSERT INTO `npc_questions` VALUES (2763, '', '', '', '', 'Jadis, il n\\\'?tait pas rare que les anciens Pandawas offrent de g?n?reuses libations ? leur d?esse, Pandawa la bien-nomm?e.  \\nAu terme des c?r?monies certains Pandawas entraient dans une sorte de transe d?e aux vapeurs capiteuses du bambou ferment?... puis s\\\'effondraient lourdement. Dans un ?lan fraternel, les fid?les n\\\'h?sitaient pas ? porter les plus titubants d\\\'entre eux jusqu\\\'? leurs chaumi?res. C\\\'est ici que l\\\'histoire rejoint la l?gende : on ne sait pas trop s\\\'ils ?taient assaillis par des hallucinations d\\\'ivrognes ou par les cr?atures malfaisantes des environs, mais les Pandawas livraient toujours combat sur le chemin du retour ! Gesticulations et baffes donn?es ? l\\\'aveuglette sont donc ? l\\\'origine des techniques d\\\'autod?fense des Pandawas.');
INSERT INTO `npc_questions` VALUES (2764, '', '', '', '', 'Si tu te sens pr?t, viens le Samedi au Dojo. Tu pr?senteras tes techniques pour obtenir ton grade.');
INSERT INTO `npc_questions` VALUES (2765, '', '', '', '', 'Parfait ! Tu ma?trises les bases du Pandawushu. Les choses s?rieuses vont maintenant commencer : ? partir de maintenant je t\\\'accorderai un entrainement particulier chaque jour ! Tu t\\\'entra?neras pour obtenir les grades sup?rieurs, les Danwas...');
INSERT INTO `npc_questions` VALUES (2766, '', '', '', '', 'Mille et un grain de riz ont ?clos dans les rizi?res de notre ?le depuis notre derni?re rencontre. Je sais que tu te sens pr?t pour passer un Danwa. Lequel me pr?senteras-tu ?');
INSERT INTO `npc_questions` VALUES (2767, '', '', '', '', 'Tu as encore beaucoup ? apprendre, tu veux faire un entra?nement contre moi, #1? \\n');
INSERT INTO `npc_questions` VALUES (2768, '', '', '', '', 'Tu te sens pr?t pour pr?senter le grade de Shodanwa ? Si tel est le cas, tu n\\\'?prouveras pas de difficult?s ? affronter un combattant de ce grade. Bats-le pour me prouver ta valeur.');
INSERT INTO `npc_questions` VALUES (2769, '', '', '', '', 'Tu te sens pr?t pour pr?senter le grade de Nidanwa ? Parfait ! D?fie en combat singulier un combattant de ce grade. Bats-le pour me prouver ta valeur. \\n');
INSERT INTO `npc_questions` VALUES (2770, '', '', '', '', 'Tu te sens pr?t pour pr?senter le grade de Sandanwa ? Parfait ! Chaque jour, ici-m?me, tu d?fieras en combat singulier un ma?tre de Pandawushuka. Bats-le pour me prouver ta valeur.');
INSERT INTO `npc_questions` VALUES (2771, '', '', '', '', 'Tu es trop jeune pour passer ce grade, reviens me voir dans quelques ann?e quand tu aura plus de 100 ans, hahaha... Mais je serai enchant? de te battre chaque jour !');
INSERT INTO `npc_questions` VALUES (2772, '', '', '', '', 'Tu te sens pr?t pour pr?senter le grade de Yondanwa ? Parfait ! S\\\'il en est ainsi, tu n\\\'?prouveras pas de difficult?s ? affronter un combattant de ce grade. Bats-le, et reviens la semaine suivante pour en faire de m?me. Ces deux victoires prouveront ta valeur.');
INSERT INTO `npc_questions` VALUES (2773, '', '', '', '', 'Bonjoul ! Soil le bienvenul dans ma demeule. Tu as l\\\'oeil scintillant comme l\\\'astle de la nuit... ');
INSERT INTO `npc_questions` VALUES (2774, '', '', '', '', 'Tr?s bien, tu es d?sormais apte ? t\\\'entra?ner au Dojo. Sache juste que tu peux venir pratiquer chaque jour de la semaine, mais que le Samedi est r?serv? aux passages de grade !');
INSERT INTO `npc_questions` VALUES (2775, '', '', '', '', 'Alors, tu as besoin d\\\'un certificat Shamanique pour pratiquer le Pandawushu ?  \\n*Le shaman s\\\'approche de vous, pose ses gros doigts sur vos paupi?res et regarde fixement au plus profond de vos yeux* \\n \\nLe test de Br?cknawa est formel, un fond de l\\\'oeil excellent et aucun trouble de r?fraction, je ne m\\\'oppose pas ? la pratique du Pandawushu. \\n');
INSERT INTO `npc_questions` VALUES (2776, '', '', '', '', 'Ah je vois, si tu viens avec les recommandations d\\\'un ma?tre de temple, je veux bien te laisser passer. \\nMais uniquement cette fois ci !');
INSERT INTO `npc_questions` VALUES (2777, '', '', '', '', 'Si tu r?ussis le test et que tu obtiens assez de renseignements aupr?s de Wally, va parler ? Lanseuft, il garde l\\\'entr?e de la for?t maudite. Dis lui que tu nous connais et il te laissera passer. Un dernier conseil : Si tu connais d\\\'autres aventuriers, formez un groupe solide pour la for?t : ainsi te reverrais-je peut-?tre un jour.');
INSERT INTO `npc_questions` VALUES (2778, '', '', '', '', 'HYAAAAAAAAAAAAAAAAK HAHAHA! Me rencontrer c\\\'est passer dans le royaume des ombres... hinhinhin... J\\\'?coute ta requ?te, ensuite je prendrai ton ?me !');
INSERT INTO `npc_questions` VALUES (2779, '', '', '', '', 'Hin ?');
INSERT INTO `npc_questions` VALUES (2780, '', '', '', '', 'D?s que tu as fini ton entrainement, viens me voir, je t\\\'attends en dehors du Dojo. ');
INSERT INTO `npc_questions` VALUES (2781, '', '', '', '', 'Bah alors, tu apportes ce Dofus au Grandapan ?');
INSERT INTO `npc_questions` VALUES (2782, '', '', '', '', 'Psh...blabla...Pshh...faux....pashh...dofus...blah..shh... \\nHmm mais je parle tout seul moi ?');
INSERT INTO `npc_questions` VALUES (2783, '', '', '', '', 'J\\\'pense que je vais rester un peu ici, le temps que tous mes amis soient r?tablis. Et puis... j\\\'ai crois? la route d\\\'une charmante vendeuse dont le poil ?tait aussi doux que ma barbe ! Ses yeux sont deux rubis et...par la barbe d\\\'Enutrof...elle picole plus que moi ! Je ne partirai pas sans avoir tent? un coup de pioche dans son p\\\'tit coeur j\\\'te l\\\'dit ! J\\\'suis m?me pr?t ? sortir mon sac de bijoux, c\\\'est dire ! Ma jeunesse r?afflue dans mes veines !');
INSERT INTO `npc_questions` VALUES (2784, '', '', '', '', 'Kweeeh *kof kof*');
INSERT INTO `npc_questions` VALUES (2785, '', '', '', '', 'Psttt...maintenant que ce gros balourd est parti, on a une chance de se tirer...');
INSERT INTO `npc_questions` VALUES (2786, '', '', '', '', 'Je suis pas un bwak, je suis juste tomb?e dans une des sources maudites en essayant de fuir ces abrutis !');
INSERT INTO `npc_questions` VALUES (2787, '', '', '', '', 'Ecoute : Ils ont fait un roulement de garde depuis mon arriv?e. Les nouveaux ne connaissent pas mon probl?me, et ont fait l\\\'erreur de te mettre avec moi...Je t\\\'explique : toi tu ne peux passer les barreaux, mais moi je le peux sous cette forme... malheureusement je suis myope comme un enutrof bourr?. Tu vas me guider ? travers la pi?ce pour que je trouve et ram?ne la clef. C\\\'est le garde le plus proche de la sortie qui a cette clef.');
INSERT INTO `npc_questions` VALUES (2788, '', '', '', '', 'Je connais plus ou moins le chemin jusqu\\\'au garde du fond... Je l\\\'entends ronfler comme ? son habitude. Observe calmement la pi?ce : si tu vois que je peux avancer un peu sans me faire rep?rer, donne un coup sur le sol.  \\nLes gardes d\\\'ici sont assez m?thodiques : observe les et tu devrais pouvoir me guider. Le lourdaud du fond dort plus ou moins profond?ment, ?coute ses ronflements et dis-moi quand lui sauter dessus sans risque ! Si tu as tout compris on va faire un essai.');
INSERT INTO `npc_questions` VALUES (2789, '', '', '', '', 'Bien jou?, sortons d\\\'ici, on se s?pare pour brouiller les pistes maintenant, bonne chance !');
INSERT INTO `npc_questions` VALUES (2790, '', '', '', '', 'Je parie que tu veux aller dans la for?t mal?fique toi !');
INSERT INTO `npc_questions` VALUES (2791, '', '', '', '', 'Serais-tu en qu?te de la protection ultime avant de p?n?trer dans la for?t maudite ?');
INSERT INTO `npc_questions` VALUES (2792, '', '', '', '', 'Toi, tu as envie de dresser les monstres de la for?t maudite !');
INSERT INTO `npc_questions` VALUES (2793, '', '', '', '', 'Je vois dans tes yeux que tu es attir? par les tr?sors secrets de la for?t maudite.');
INSERT INTO `npc_questions` VALUES (2794, '', '', '', '', 'Ne dis rien ! Je sens la mort r?der pr?t de toi... tu d?sires rentrer dans l\\\'obscurit? de la for?t interdite... n\\\'est-ce pas ?');
INSERT INTO `npc_questions` VALUES (2795, '', '', '', '', 'Ainsi le temps est venu pour toi d\\\'aller l? o? le temps s\\\'est arr?t? pour \\\"celle dont on doit taire le nom\\\"...');
INSERT INTO `npc_questions` VALUES (2796, '', '', '', '', 'Hmm, je ressens chez toi l\\\'envie de fouler les terres maudites du labyrinthe, serais-tu assez fou pour envisager de soigner Dark Vlad ?');
INSERT INTO `npc_questions` VALUES (2797, '', '', '', '', 'Je sens en toi l\\\'envie de te mesurer ? Vlad ! Ou simplement d\\\'affronter les dangers de la for?t maudite ?');
INSERT INTO `npc_questions` VALUES (2798, '', '', '', '', 'L\\\'appel de la for?t, m?me maudite, t\\\'appelle me semble-t-il...');
INSERT INTO `npc_questions` VALUES (2799, '', '', '', '', 'L\\\'appel de la for?t, m?me maudite, te fait vibrer disciple.');
INSERT INTO `npc_questions` VALUES (2800, '', '', '', '', 'Ton sang bouillonne ? l\\\'id?e de se r?pandre dans un endroit maudit...Chercherais-tu ? entrer dans le labyrinthe ?');
INSERT INTO `npc_questions` VALUES (2801, '', '', '', '', '... \\nEmeraude est cette couleur...  \\nRazeriane aime ? contempler sa beaut? dans la coquille si lisse du Dofus... \\n...Pars maintenant...');
INSERT INTO `npc_questions` VALUES (2802, '', '', '', '', '...Pars...');
INSERT INTO `npc_questions` VALUES (2803, '', '', '', '', 'Vous ?tes ? l\\\'entr?e du Village d\\\'Akwadala, seuls ceux qui ont prouv? leur force peuvent y rentrer.');
INSERT INTO `npc_questions` VALUES (2804, '', '', '', '', 'Ah je vois, circonstance exceptionnelle, je vais vous amener directement au Maitre, et je vous raccompagnerai vers la sortie imm?diatement apr?s votre entretien.');
INSERT INTO `npc_questions` VALUES (2805, '', '', '', '', 'Vous ?tes ici au village de Terrdala, mais personne ne peut y entrer sauf ceux qui nous ont prouv? r?cemment leur force.');
INSERT INTO `npc_questions` VALUES (2806, '', '', '', '', 'Je vois, nous sommes redevables au sage Lenald, je vais vous escorter jusqu\\\'au Maitre.');
INSERT INTO `npc_questions` VALUES (2807, '', '', '', '', 'Que viens tu faire ici ? C\\\'est mon endroit, ma salle, mon panier. Nul autre que moi et mes amis n\\\'ont le droit de fouler ces dalles. Pars donc maintenant ! Que dis-je, fuis ! Avant qu\\\'elle n\\\'?merge et te tue.');
INSERT INTO `npc_questions` VALUES (2808, '', '', '', '', 'Avant de pr?tendre ? un grade de Pandawushu, tu ferais bien de lire ton manuel !');
INSERT INTO `npc_questions` VALUES (2809, '', '', '', '', 'Tr?s bien ! Une derni?re question : \\nQui est l\\\'auteur du livre \\\"L\\\'art Pandawushu\\\" ?');
INSERT INTO `npc_questions` VALUES (2810, '', '', '', '', 'Tu n\\\'es pas pr?t. Reviens me voir lorsque tu le seras....');
INSERT INTO `npc_questions` VALUES (2811, '', '', '', '', 'Bonne r?ponse, maintenant admettons que tu aies un Pandawa qui ?tudie le Pandawushu de Terre pour ami et que tu souhaites lui offrir un bouclier, lequel lui correspondra le mieux : le Bouclier d\\\'Asse, le Ftalmo, le Cadran de Feu ou le Bouclier Abraknyde ?');
INSERT INTO `npc_questions` VALUES (2812, '2431;2430;2560', '', '', '0', 'Tu es sur la voie de l\\\'Illumination, mais le chemin est long... R?ponds ? ce kwan, et peut-?tre que ton esprit s\\\'embrasera gr?ce ? la lumi?re de la connaissance : \\nConnais-tu la diff?rence entre un Boufton et un Pandawa ?');
INSERT INTO `npc_questions` VALUES (2813, '', '', '', '', 'Le Boufton est blanc avec une queue noire, alors que le Pandawa est noir avec... des bambous dans le dos ! Le chemin est long sur la voie de l\\\'illumination ! Un jour peut-?tre, petit Scarafeuille...');
INSERT INTO `npc_questions` VALUES (2814, '', '', '', '', 'Mmh, tu pars de loin, toi... Un kwan est une question courte, pos?e par le Ma?tre ? son Disciple.');
INSERT INTO `npc_questions` VALUES (2815, '', '', '', '', 'Comme tu le sais peut-?tre si tu as lu le livre de Myamowa Musashwan, les Pandawas sont aussi habiles dans un ?l?ment que dans un autre. A toi de trouver ta voie parmi les quatre possibles !');
INSERT INTO `npc_questions` VALUES (2816, '', '', '', '', 'C\\\'est pour une offrande ? la d?esse ?');
INSERT INTO `npc_questions` VALUES (2817, '', '', '', '', 'Tiens, retourne tout de suite faire ton offrande, avant que les bulles ne disparaissent.');
INSERT INTO `npc_questions` VALUES (2818, '', '', '', '', 'Ecoute mon p\\\'tit nouveau, je devrais t\\\'apprendre la base des 3 B \\\"Boire, Battre, B?frer\\\", mais je n\\\'ai pas le temps... Cours voir Gasdaure : tu lui passes le bonjour de ma part, et tu lui dis que c\\\'est moi qui t\\\'envoie. \\nQuitte l\\\'?le par le pont et rends toi ? Astrub, ? l\\\'Est. Rends toi dans la cit? des Mercenaires. Gasdaure y habite... Ne reviens pas avant d\\\'?tre un guerrier exp?riment?. Et n\\\'oublie pas de go?ter les boissons locales, tu n\\\'en appr?cieras que mieux les n?tres ? ton retour. \\n');
INSERT INTO `npc_questions` VALUES (2819, '', '', '', '', 'Voici le pont qui m?ne ? Astrub, suivez-le et vous tomberez sur la cit? Mercenaire.');
INSERT INTO `npc_questions` VALUES (2820, '', '', '', '', 'Hum, tu n\\\'as pas pay? la taxe... je ne peux te parler...');
INSERT INTO `npc_questions` VALUES (2821, '', '', '', '', 'D?sol?, je ne peux vendre de trucs forts aux touristes comme toi.');
INSERT INTO `npc_questions` VALUES (2822, '', '', '', '', 'D?sol? je ne peux pas te vendre d\\\'alcool, tu n\\\'y survivrais pas !');
INSERT INTO `npc_questions` VALUES (2823, '', '', '', '', 'Tu es trop timide pour demander ? un pratiquant de combattre avec toi je suppose ? Bon, ne bouge pas, je vais appeler quelqu\\\'un de ton grade pour que tu puisses t\\\'exercer ! Si je n\\\'en trouve pas, reviens dans 24 heures...');
INSERT INTO `npc_questions` VALUES (2824, '', '', '', '', 'En tr?s peu de temps tu es devenu un pandawa digne de Pandawa. Notre D?esse te f?licite. Ma?tre Lenald a maintenant pleinement confiance en toi, et te confie une t?che importante. Si tu la r?ussis, il acc?dera enfin ? ta requ?te.');
INSERT INTO `npc_questions` VALUES (2825, '', '', '', '', 'Une r?union secr?te se tient en ce moment m?me ? Aerdala. Nous autres ignorons ce qui se trame l?-bas... Mais une chose est s?re : il y sera question des Dofus. Le sage Lenald souhaite t\\\'envoyer toi, il est difficile de faire confiance ? l\\\'un des n?tres en ce moment, les pandikazes sont partout. Mais Ma?tre Lenald est certain que tu n\\\'en es pas un.  Mais fais attention : des ?tranges disparitions de pandawa ont eu lieu l? bas. On dit que les Pandikazes seraient les coupables, et qu\\\'ils seraient li?s aux habitants d\\\'Aerdala. Il faut que tu t\\\'infiltres et que tu nous rapportes un maximum d\\\'information. Retourne voir le sage si tu reviens en vie.');
INSERT INTO `npc_questions` VALUES (2826, '', '', '', '', 'Alors confr?re, on trahit les siens par soif de pouvoir  hein ?');
INSERT INTO `npc_questions` VALUES (2827, '', '', '', '', 'Nous les pandikazes repr?sentons la v?ritable essence des Pandawas ! Ce Grandipan n\\\'est qu\\\'un illustre idiot...Ouvrir l\\\'?le aux ?trangers, partager avec eux nos l?gendes. Promouvoir la chasse aux Dofus...Ne comprends tu pas que les Dofus n\\\'am?nent que d?solation et destruction ?! Comprends-moi bien, les Dofus n\\\'y sont pour rien, les coupables sont les aventuriers avides tels que TOI ! Vous semez le chaos sur votre passage en pr?textant toujours la m?me excuse! C\\\'est inadmissible !');
INSERT INTO `npc_questions` VALUES (2828, '', '', '', '', 'Silence ! Je ne suis pas idiot ! Tu ne me laisses aucun choix, demain tu dispara?tras pour toujours, nous te plongerons dans un bassin de Pandka pure...tu en sais trop confr?re. Il faut parfois faire des sacrifices pour arriver ? ses fins ! \\n');
INSERT INTO `npc_questions` VALUES (2829, '', '', '', '', '...Hum Terra Cogita ? donc ?labor? tout ceci dans un seul but... Mais oui, j\\\'y suis ! Tout simplement pour ?viter que cela se reproduise !... Maimane avait donc d?j? tout pr?vu... \\n \\n* Wally prend son carnet et griffonne quelques sch?mas *');
INSERT INTO `npc_questions` VALUES (2830, '', '', '', '', 'Aujourd\\\'hui, c\\\'est mon jour de m?ditation, alors ne trouble pas ma concentration ! \\n \\n... zZZzzzz Zzz... zzz...');
INSERT INTO `npc_questions` VALUES (2831, '244', '', '', '0', 'Salutations. L\\\'entr?e de cette tour est r?serv?e aux plus fid?les habitants de Bonta, les membres des Ordres. Si vous voulez devenir l\\\'un des n?tres, allez voir Amayiro, dans la caserne de la milice.');
INSERT INTO `npc_questions` VALUES (2832, '', '', '', '', 'use later');
INSERT INTO `npc_questions` VALUES (2833, '', '', '', '', 'Pour quitter notre ordre il te faudra faire don d\\\'une guildalogemme ? la cit');
INSERT INTO `npc_questions` VALUES (2834, '', '', '', '', 'La nuit derni?re, des Br?kmariens ont br?l? plusieurs entrep?ts de nourriture destin?s ? l\\\'alimentation des dragodindes de la milice. Comme les r?serves s\\\'?puisent rapidement, il faut trouver un moyen de faire pousser les c?r?ales plus vite. Merlan l\\\'Encha?neur, ? l\\\'atelier des alchimistes, pourra peut-?tre l\\\'aider. \\n \\nJe compte sur toi !');
INSERT INTO `npc_questions` VALUES (2835, '', '', '', '', 'Voyons voir... Oui, tu sembles avoir commenc? la formation de ce brave Amayiro. \\nIl est peut-?tre temps pour toi de choisir un ordre et de te sp?cialiser au mieux pour servir les int?r?ts de Bonta ! \\n \\nJe suis moi-m?me le ma?tre de l\\\'ordre de l\\\'Oeil Attentif, pour te renseigner sur un autre ordre, je te conseille de visiter les autres ?tages de la tour...');
INSERT INTO `npc_questions` VALUES (2836, '', '', '', '', 'Salutations #1, je ne t\\\'ai pas vu arriver, je vois que tu as am?lior? ta discr?tion depuis notre derni?re rencontre ! \\nQue puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (2837, '', '', '', '', 'Plus tard !');
INSERT INTO `npc_questions` VALUES (2838, '', '', '', '', 'Alors comme ?a tu veux devenir espion ? Ca tombe bien, j\\\'ai une mission pour toi. \\nTu es sans doute au courant que des Br?kmariens ont incendi? les entrep?ts de nourriture des dragodindes de la milice. Du coup, tu te demandes pourquoi ils ont fait ?a, n\\\'est-ce pas ? Et bien voil? pour toi l\\\'occasion de le savoir. \\nTu vas imm?diatement te rendre ? la Tour de Br?kmar et trouver des indices sur ce que les Br?kmariens manigancent. Tu profiteras d\\\'?tre dans la cit? ennemie pour rendre visite ? Fidji Merline et lui remettre ceci, elle comprendra. Lorsqu\\\'elle aura pris connaissance du contenu de cette lettre, suis ses instructions ? la lettre, je compte sur toi.');
INSERT INTO `npc_questions` VALUES (2839, '', '', '', '', 'Salutations #1, tu resplendis tel un phoenix jeune disciple. \\nQue puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (2840, '', '', '', '', 'Voyons voir... Oui, tu sembles avoir commenc? la formation de ce brave Amayiro. \\nIl est peut-?tre temps pour toi de choisir un ordre et de te sp?cialiser au mieux pour servir les int?r?ts de Bonta ! \\n \\nJe suis moi-m?me le ma?tre de l\\\'Ordre de l\\\'Esprit Salvateur, pour te renseigner sur un autre ordre, je te conseille de visiter les autres ?tages de la tour...');
INSERT INTO `npc_questions` VALUES (2841, '', '', '', '', 'Un membre de l\\\'Ordre de l\\\'Oeil Attentif nous a rapport? les d?pouilles de trois ren?gats bontariens. Nous avons besoin de les interroger mais les m?thodes classiques de r?surrection ne fonctionnent pas. \\nTu vas aller me chercher un ouvrage intitul? \\\"La b?n?diction d\\\'Erazal\\\" ? la biblioth?que.');
INSERT INTO `npc_questions` VALUES (2842, '', '', '', '', 'Souhaitez vous revenir, je vais vous raccompagner jusqu\\\'au zaap du village, et de l? vous rejoindrez le Zaap central');
INSERT INTO `npc_questions` VALUES (2843, '', '', '', '', 'Bienvenue dans la chocolaterie Bonnawa ! Vous ne trouverez pas de meilleurs chocolats ailleurs, il est m?me fort possible que vous n\\\'en trouviez pas d\\\'autres ! \\nN\\\'h?sitez pas ? vous faire plaisir en achetant quelques produits dans mon magasin, car comme le dit la devise de la maison : \\\"Ce qui fait du bien au palais, ne fait pas de mal ? l\\\'?me... \\\" !');
INSERT INTO `npc_questions` VALUES (2844, '', '', '', '', 'Bienvenu ? la taverne du Pandawa Ivre, que puis-je vous servir ?');
INSERT INTO `npc_questions` VALUES (2845, '', '', '', '', 'Mmh... J\\\'irai bien faire une sieste...');
INSERT INTO `npc_questions` VALUES (2846, '', '', '', '', 'Y\\\'a du soleil ? PandaladirLAaAdaAada... Pardon ? Je suis occup?e, d?sol?e de ne pouvoir t\\\'aider.');
INSERT INTO `npc_questions` VALUES (2847, '', '', '', '', 'Bien, continuons. Comment se nomme le 5eme grade Pandawushu ?');
INSERT INTO `npc_questions` VALUES (2848, '', '', '', '', 'Bravo, je te nomme au grade de Sankwa !');
INSERT INTO `npc_questions` VALUES (2849, '', '', '', '', 'Bien, et si tu poss?des un chapeau Goyave et un chapeau Kannipiou, lequel des deux est-il pr?f?rable de porter pour gagner un maximum d\\\'exp?rience en combat ?');
INSERT INTO `npc_questions` VALUES (2850, '', '', '', '', 'Toi pas avoir compris, toi pas juste fermer yeux, toi t\\\'?loigner sinon pas changer.');
INSERT INTO `npc_questions` VALUES (2851, '', '', '', '', 'Tu te crois brave ? Va ? Pandala et accomplis ce que tu dois !');
INSERT INTO `npc_questions` VALUES (2852, '', '', '', '', 'Tu crois vraiment que nous allons laisser sortir d\\\'ici un Bontarien de ton niveau ? Hahaha ! \\nTa seule chance serait que des compatriotes viennent te d?livrer, mais n\\\'esp?re pas trop !');
INSERT INTO `npc_questions` VALUES (2853, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 64000 kamas de caution, ou attendre 1 heure 10 avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2854, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 32000 kamas de caution, ou attendre 1 heure avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2855, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 16000 kamas de caution, ou attendre 50 minutes avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2856, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 8000 kamas de caution, ou attendre 40 minutes avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2857, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 4000 kamas de caution, ou attendre 30 minutes avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2858, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 2000 kamas de caution, ou attendre 20 minutes avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2859, '250', '', '', '0', 'Pour sortir d\\\'ici, tu as le choix entre payer 1000 kamas de caution, ou attendre 2 minutes avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rables que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2860, '', '', '', '', 'Tu pourras sortir d\\\'ici 5 minutes, la prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2861, '4663;484', '', '', '0', 'Je n\\\'ai rien ? t\\\'apprendre pour l\\\'instant. Reviens me voir plus tard.');
INSERT INTO `npc_questions` VALUES (2862, '', '', '', '', 'Tu es d?sormais pr?t ? rejoindre nos lignes. \\nQuel Ordre souhaites tu int?grer ? \\nLes Guerriers de l\\\'Ordre du Coeur Saignant, les Soigneurs de l\\\'Ordre de l\\\'Esprit Malsain ou encore l\\\'Ordre de l\\\'Oeil Putride ? \\nAttention, ce choix est important, il ne te sera pas permis d\\\'en changer par la suite !');
INSERT INTO `npc_questions` VALUES (2863, '', '', '', '', 'Tu es d?sormais pr?t ? rejoindre nos lignes. \\nQuel Ordre souhaites tu int?grer ? \\nLes Guerriers de l\\\'Ordre du Coeur Saignant, les Soigneurs de l\\\'Ordre de l\\\'Esprit Malsain ou encore l\\\'Ordre de l\\\'Oeil Putride ? \\nAttention, ce choix est important, il ne te sera pas permis d\\\'en changer par la suite !');
INSERT INTO `npc_questions` VALUES (2864, '', '', '', '', 'Salutations #1, ton aura mal?fique grossit de jour en jour, je suis fier de toi ! \\nQue puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (2865, '', '', '', '', 'J\\\'avais envoy? des Br?kmariens saigner les dragodindes de la milice de Bonta et voler leur stock de nourriture, mais ces idiots ont ?t? apeur?s par les nombreux gardes post?s devant les enclos et comme ils ?taient sur le point de se faire prendre, ils n\\\'ont rien trouv? de plus intelligent ? faire que de br?ler les entrep?ts de nourriture pour couvrir leur fuite. Par cons?quent, les Bontariens disposent toujours de leurs dragodindes et les entrep?ts de nourriture de Br?kmar n\\\'ont pas ?t? ravitaill?s. \\n \\nTu vas aller ? Astrub et trouver Raymond Santho, un marchand en relation avec Bonta. Tu dois le gagner ? notre cause quelque soit les moyens employ?s.');
INSERT INTO `npc_questions` VALUES (2866, '', '', '', '', 'Tu arrives ? temps pour m\\\'aider. Des miliciens ont captur? une ?me et nous devons l\\\'interroger. Comme il va ?tre difficile de la forcer ? parler, nous devons d\\\'abord lui redonner son corps. Le souci est que pour une raison inconnue, la m?thode de r?surrection classique ne fonctionne pas. Si tu parviens ? ressusciter l\\\'?me en question, tu int?greras les rangs de mes apprentis.');
INSERT INTO `npc_questions` VALUES (2867, '', '', '', '', 'Inutile d\\\'esp?rer aller plus loin. Les Pandikazes ont sabot? le pont qui menait ? la presqu\\\'?le.');
INSERT INTO `npc_questions` VALUES (2868, '', '', '', '', 'Bonjour, nous sommes les banquiers. Vous pouvez ouvrir un compte dans ma banque et vous aurez un coffre ? disposition pour d?poser vos biens. Mais attention, chaque consultation de votre compte vous co?tera #1 Kamas.');
INSERT INTO `npc_questions` VALUES (2869, '', '', '', '', 'Bonjour, nous sommes les banquiers. Vous pouvez ouvrir un compte dans ma banque et vous aurez un coffre ? disposition pour d?poser vos biens. Mais attention, chaque consultation de votre compte vous co?tera #1 Kamas.');
INSERT INTO `npc_questions` VALUES (2870, '', '', '', '', 'Bonjour, nous sommes les banquiers. Vous pouvez ouvrir un compte dans ma banque et vous aurez un coffre ? disposition pour d?poser vos biens. Mais attention, chaque consultation de votre compte vous co?tera #1 Kamas.');
INSERT INTO `npc_questions` VALUES (2871, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (2872, '', '', '', '', 'Bonjour, nous sommes les banquiers. Vous pouvez ouvrir un compte dans ma banque et vous aurez un coffre ? disposition pour d?poser vos biens. Mais attention, chaque consultation de votre compte vous co?tera #1 Kamas.');
INSERT INTO `npc_questions` VALUES (2873, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (2874, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (2875, '', '', '', '', 'Vous pouvez d?poser des kamas, mais ?galement des objets dans votre coffre. \\nVous n\\\'avez le droit qu\\\'? un seul coffre. \\nChaque acc?s ? votre coffre, m?me si vous ne fa?tes que le consulter, est payant. \\nLe prix ? payer pour consulter votre coffre d?pend de sa taille, et la taille du coffre d?pend de votre anciennet? aupr?s de la banque. Chaque personne vivant dans la province d\\\'Amakna se voit attribuer un compte en banque. \\n \\nAinsi, vous payez plus de Kamas au fil du temps pour acc?der ? votre coffre, mais vous avez un coffre de plus en plus grand.');
INSERT INTO `npc_questions` VALUES (2876, '', '', '', '', 'Tu as r?ussi l\\\'?preuve, aventurier ! La for?t t\\\'attend !');
INSERT INTO `npc_questions` VALUES (2877, '', '', '', '', 'Tu as r?ussi l\\\'?preuve, aventurier ! La for?t t\\\'attend !');
INSERT INTO `npc_questions` VALUES (2878, '', '', '', '', 'Tu as r?ussi l\\\'?preuve, aventurier ! La for?t t\\\'attend !');
INSERT INTO `npc_questions` VALUES (2879, '', '', '', '', '\\\"Que mille roses fleurissent sous vos pas, parfument vos orteils d\\\'une douce senteur printani?re, et fasse se h?ter la belle saison ! \\\". Ainsi parle le Grandapan, le sage qui r?gne sur l\\\'?le de PANDALA ! \\nSi comme lui tu trouves que le printemps tarde ? arriver, c\\\'est qu\\\'il est temps de te bouger ! D?p?che-toi ! A PANDALA, une flop?e de h?ros au coeur pur et ? l\\\'haleine fra?che affrontent d?j? des monstres sanguinaires (mais pas trop quand m?me). Encore mieux : en te rendant ? PANDALA, peut-?tre conna?tras-tu (enfin) la v?rit? sur ces oeufs de dragon qu\\\'on nomme Dofus ! T\\\'es encore l? ? \\n');
INSERT INTO `npc_questions` VALUES (2880, '250', '', '', '0', 'Bonjour ? vous. \\n \\nBeau temps, n\\\'est-il pas, pour tenter de capturer des ?mes errantes ? \\n \\nMais tr?ve de bavardages, en quoi puis-je vous ?tre utile ?');
INSERT INTO `npc_questions` VALUES (2881, '', '', '', '', 'Pour capturer un groupe d\\\'?mes, rien de plus simple. Vous devez garder en main durant tout le combat une pierre d\\\'?me pr?te ? recevoir ces ?mes, et lancer un sortil?ge ? la fin du combat, ce qui vous permettra de voir les ?mes s\\\'envoler et de tenter de les capturer. \\n \\nAttention, si le sortil?ge est lanc? trop t?t, il s\\\'estompera et vous ne serez pas ? m?me de capturer l\\\'?me errante. \\n \\nConcernant ce sortil?ge, et bien... Je ne puis vous l\\\'apprendre. Mais on dit qu\\\'on peut le trouver dans les tr?fonds de l\\\'?le de Pandala.');
INSERT INTO `npc_questions` VALUES (2882, '', '', '', '', 'Ecoute-moi bien : je m\\\'en vais t\\\'expliquer le fonctionnement de nos ar?nes. Il te faut tout d\\\'abord obtenir un sort sp?cial qui te servira ? affronter les monstres dans nos belles ar?nes. Ce sort t\\\'est indispensable pour capturer l\\\'?me de la cr?ature que tu convoites. \\nEnsuite, lorsque tu te seras ?quip? de cette Rune, tu provoqueras un combat avec la cr?ature en question. Utilise le pouvoir de la Rune pendant ce combat : il te faut d?clencher son pouvoir et triompher de la cr?ature. Plus ta Rune est puissante, plus tu as de chance de r?cup?rer l\\\'?me de la cr?ature. Tu pourras enfin affronter cette cr?ature dans une ar?ne, seul ou avec un groupe d\\\'autres aventuriers.');
INSERT INTO `npc_questions` VALUES (2883, '', '', '', '', 'Primo : obtiens un sort de capture d\\\'?me. Ce sort est disponible dans le donjon d\\\'Akwadala. \\nSecundo : Equipe toi d\\\'une Rune de Capture. \\nTertio : Attaque une c?ature dont tu convoites l\\\'?me. Lance le sort de capture d\\\'?me pendant le combat et sois vainqueur ! \\nQuatro : Si tu tues la cr?ature pendant que ton sort est actif, alors tu as une chance de r?cup?rer l\\\'?me du monstre. \\n \\nNaturellement, il n\\\'est pas possible de recapturer l\\\'?me de la cr?ature dans l\\\'ar?ne...');
INSERT INTO `npc_questions` VALUES (2884, '', '', '', '', 'Pour sortir d\\\'ici, tu as le choix entre payer 128000 kamas de caution, ou attendre 1 heure 20 avant de pouvoir sortir. \\nLa prison est trop petite pour que nous gardions des ?tres aussi mis?rable que toi ind?finiment...');
INSERT INTO `npc_questions` VALUES (2885, '', '', '', '', 'Personne n\\\'a le droit de s\\\'approcher du receptacle, bien que le Grandapan le consid?re comme une attraction touristique. Cet objet attire ici des monstres f?roces qui le gardent. Seul les plus forts peuvent p?n?trer le village...et les pandawas, pour leur rituel d\\\'initiation');
INSERT INTO `npc_questions` VALUES (2886, '', '', '', '', 'Bien, ferme les yeux et ne les ouvre pas avant que je te le dise. Ne fais pas attention aux cris que tu vas entendre surtout.');
INSERT INTO `npc_questions` VALUES (2887, '', '', '', '', 'Si tu es pr?t ? repartir, je te ram?ne ? l\\\'entr?e du village.');
INSERT INTO `npc_questions` VALUES (2888, '2528', '', '', '', 'Bulbavo ! Bilbulubu bu ba bi bobo bu bulbi bi bo.... \\nBi bu bi bebe ibu ob eb bort be bune.');
INSERT INTO `npc_questions` VALUES (2890, '', '', '', '', 'Poochan remercier toi, poochan te permettre d\\\'utiliser les sources sans danger, toi demander, toi juste donner 2000 Kamas ? Poochan pour nettoyer source apr?s.');
INSERT INTO `npc_questions` VALUES (2891, '', '', '', '', 'Ouch ! Mon sac est si lourd ! Je reviens de Pandala, j\\\'y ai fait des tonnes de bonnes affaires ! C\\\'est DEMENT !');
INSERT INTO `npc_questions` VALUES (2892, '', '', '', '', 'Ouch ! Mon sac est si lourd ! Il faut dire qu\\\'? Pandala, on trouve tout ce qu\\\'on veut ! C\\\'est DEMENT !');
INSERT INTO `npc_questions` VALUES (2893, '', '', '', '', 'Ouch ! Mon sac est si lourd ! Je reviens de Pandala, j\\\'y ai fait des tonnes de bonnes affaires ! C\\\'est DEMENT !');
INSERT INTO `npc_questions` VALUES (2894, '', '', '', '', 'qu\\\'est ce que tu fais ici ? allez prend la clef et fuis vite fait');
INSERT INTO `npc_questions` VALUES (2895, '2533', '', '', '', 'Ahh quel noble metier ! Un veritable forgeur de boucliers met son talent au service des plus faibles, car sans bouclier il est difficile d\\\'encaisser les coups de vos assaillants. Toutefois, n\\\'ouliez pas que vous ne pourrez stopper les coups de vos adversaires que si vous les connaissez bien. Un bouclier sera donc inutile si vous attaquez des monstres. \\nPour commencer votre apprentissage il vous faudra le marteau du forgeur de bouclier. Seul un forgeur de marteau sera ? m?me de vous le fournir.');
INSERT INTO `npc_questions` VALUES (2896, '', '', '', '', 'Pnj(645) et Message(2690)');
INSERT INTO `npc_questions` VALUES (2897, '', '', '', '', 'Je dois m\\\'occuper du passage de grade de nombreux adeptes, si tu veux retenter un passage, reviens me voir d\\\'ici deux heures au minimum !');
INSERT INTO `npc_questions` VALUES (2898, '', '', '', '', 'Je dois m\\\'occuper du passage de grade de nombreux adeptes, si tu veux retenter un passage, reviens me voir d\\\'ici trois heures au minimum !');
INSERT INTO `npc_questions` VALUES (2899, '', '', '', '', 'Je dois m\\\'occuper du passage de grade de nombreux adeptes, si tu veux retenter un passage, reviens me voir d\\\'ici quatres heures au minimum !');
INSERT INTO `npc_questions` VALUES (2900, '', '', '', '', 'Je dois m\\\'occuper du passage de grade de nombreux adeptes, si tu veux retenter un passage, reviens me voir d\\\'ici cinq heures au minimum !');
INSERT INTO `npc_questions` VALUES (2901, '', '', '', '', 'Je dois m\\\'occuper du passage de grade de nombreux adeptes, si tu veux retenter un passage, reviens me voir d\\\'ici six heures au minimum !');
INSERT INTO `npc_questions` VALUES (2902, '', '', '', '', 'Bon, derni?re question : \\nSi tu donnes une langue de Pissenlit diabolique ? un wabbit cela le rendra-t-il plus intelligent, plus chanceux, ou plus agile??');
INSERT INTO `npc_questions` VALUES (2903, '', '', '', '', 'F?licitation, tu es d?sormais un disciple Pandawushu du grade Gokwa!');
INSERT INTO `npc_questions` VALUES (2904, '', '', '', '', 'Bien, et si tu poss?de un chapeau Goyave et un chapeau Kannipiou, lequel des deux est-il pr?f?rable de porter pour gagner un maximum de vitalit? en combat ?');
INSERT INTO `npc_questions` VALUES (2905, '', '', '', '', 'Belle prise, mercenaire !');
INSERT INTO `npc_questions` VALUES (2906, '', '', '', '', 'Bien jou?, mercenaire !');
INSERT INTO `npc_questions` VALUES (2907, '', '', '', '', 'Bien jou?, mercenaire !');
INSERT INTO `npc_questions` VALUES (2908, '', '', '', '', 'Bien jou?, mercenaire !');
INSERT INTO `npc_questions` VALUES (2909, '', '', '', '', 'Ah la grosse m?g?re, bien jou? !');
INSERT INTO `npc_questions` VALUES (2910, '', '', '', '', 'OoOoMm Pandawa OoOoMm - (il prie)');
INSERT INTO `npc_questions` VALUES (2911, '', '', '', '', 'Tu as d?shonor? ta cit? en manquant de loyaut? durant tes combats. Ton compte bancaire restera donc bloqu? jusqu\\\'? ce que tu rattrapes tes mauvaises actions.');
INSERT INTO `npc_questions` VALUES (2912, '', '', '', '', 'Que me vaut ta visite fid?le Ecuyer ? \\nNe devrais-tu pas t\\\'entra?ner avec la milice ? cette heure-ci ?');
INSERT INTO `npc_questions` VALUES (2913, '', '', '', '', 'Je n\\\'aime pas la mani?re dont Br?kmar agit ces derniers temps. Nous sommes beaucoup trop passifs, il faudrait les attaquer et les an?antir une bonne fois pour toutes... \\nTu voulais me dire quelque chose ?');
INSERT INTO `npc_questions` VALUES (2916, '', '', '', '', 'Tu es peut-?tre au courant que nous avons captur? et interrog? des ren?gats bontariens. Ces gredins ont d?voil? ? nos ennemis l\\\'existence de deux statuettes symbolisant les biens et les maux de l\\\'humanit?. Maimane aurait offert ces statuettes ? Sumens et ? pr?sent Br?kmar cherche ? les r?cup?rer. \\nA l\\\'heure actuelle, nous savons que ces statuettes sont li?es d\\\'une mani?re ou d\\\'une autre ? la famille Terra. Setag, le ma?tre de classe des Enutrofs, sait sans doute quelque chose ? ce sujet c\\\'est pourquoi tu dois aller le voir.');
INSERT INTO `npc_questions` VALUES (2917, '', '', '', '', 'J\\\'esp?re que tu m\\\'apportes de bonnes nouvelles jeune espion #1 ! \\nQue puis-je pour toi ?');
INSERT INTO `npc_questions` VALUES (2918, '', '', '', '', 'Bonjour, tes parties de chasse sont-elles fructueuses?');
INSERT INTO `npc_questions` VALUES (2921, '', '', '', '', 'J\\\'ai une mauvaise nouvelle : des Bontariens se sont ralli?s ? Br?kmar. Je n\\\'ai aucun chasseur de ren?gats sous la main donc si tu souhaites int?grer leurs rangs, ram?ne-moi la d?pouille des ren?gats bontariens. J\\\'ignore o? ils se trouvent exactement mais notre espion Bishom Pot en saura peut-?tre plus ? leur sujet.');
INSERT INTO `npc_questions` VALUES (2922, '', '', '', '', 'Que me vaut la visite d\\\'un de mes apprentis ?');
INSERT INTO `npc_questions` VALUES (2923, '', '', '', '', 'Salutations jeune adepte. Voir ta mine resplendissante me r?chauffe le c?ur. \\nComment puis-je t\\\'aider ?');
INSERT INTO `npc_questions` VALUES (2926, '', '', '', '', 'Bien le bonjour, ami de la culture. On vient s\\\'instruire, hein ? H? bien, c\\\'est pas trop t?t. Mais bon, comme on dit, il n\\\'est jamais trop tard pour commencer...  Si vous avez besoin d\\\'un livre, venez me demander.');
INSERT INTO `npc_questions` VALUES (2927, '2561;2562', '', '', '', 'Je vois que tu connais l\\\'existence des fortifiants ?l?mentaires que seuls les grands ma?tres Pandawushu sont capables d\\\'ex?cuter ! \\nEn tant que ma?tre du Pandawushu Air je peux t\\\'apporter un souffle revigorant pour tes prochains combats...');
INSERT INTO `npc_questions` VALUES (2928, '', '', '', '', 'Que le tourbillon sacr? vienne ? toi, que sa v?locit? t\\\'emporte, et t\\\'apporte la dext?rit? divine !');
INSERT INTO `npc_questions` VALUES (2929, '2564;2565', '', '', '0', 'Je vois que tu connais l\\\'existence des fortifiants ?l?mentaires que seuls les grands ma?tres Pandawushu sont capables d\\\'ex?cuter ! \\nEn tant que ma?tre du Pandawushu Feu je peux t\\\'apporter une flamme qui pourra raviver ton ?me de combattant pour tes prochains combats...');
INSERT INTO `npc_questions` VALUES (2930, '', '', '', '', 'Que le feu sacr? vienne ? toi, que sa chaleur te r?conforte, et que sa flamme divine t\\\'illumine !');
INSERT INTO `npc_questions` VALUES (2931, '2567;2568', '', '', '0', 'Je vois que tu connais l\\\'existence des fortifiants ?l?mentaires que seuls les grands ma?tres Pandawushu sont capables d\\\'ex?cuter ! \\nEn tant que ma?tre du Pandawushu de l\\\'Eau je peux dissiper la vague de danger qui te m?nace continuellement et t\\\'apporter un bouillonnement protecteur pour tes prochains combats...');
INSERT INTO `npc_questions` VALUES (2932, '', '', '', '', 'Que le torrent sacr? t\\\'inonde de sa bont?, que sa puissance t\\\'emporte, et que son ?toile divine guide tes actes !');
INSERT INTO `npc_questions` VALUES (2933, '2570;2571', '', '', '', 'Je vois que tu connais l\\\'existence des fortifiants ?l?mentaires que seuls les grands ma?tres Pandawushu sont capables d\\\'ex?cuter ! \\nEn tant que ma?tre du Pandawushu de la terre je peux te faire devenir une v?ritable force de la nature pour tes prochains combats...');
INSERT INTO `npc_questions` VALUES (2934, '', '', '', '', 'Que la flore sacr?e enracine sa force en toi et que sa s?ve divine coule dans tes veines !');
INSERT INTO `npc_questions` VALUES (2935, '', '', '', '', 'F?licitation tu t\\\'es tr?s bien battu ! Je valide donc ton passage de grade...');
INSERT INTO `npc_questions` VALUES (2936, '', '', '', '', 'Le Dark Vlad reviendra du royaume des morts dans ? peu pr?s #1 minutes !');
INSERT INTO `npc_questions` VALUES (2937, '', '', '', '', 'Haha, vous ?tes un vrai explorateur de souterrain l\\\'ami ! Bon, j\\\'arr?te de vous importuner, j\\\'ai assez d\\\'?l?ments pour essayer de trouver une th?orie et dessiner les plans de ce que vous avez explor?... je tiens peut-?tre enfin mon best-seller ! \\n \\nIl reste encore une foultitude de souterrains ?nigmatiques expliqu?s dans ce livre: dans le donjon des forgerons sombres, dans la ville de Sufokia... Repassez me voir dans quelque temps, j\\\'aurais peut-?tre encore besoin de vos services pour explorer tout ?a !');
INSERT INTO `npc_questions` VALUES (2938, '2575', '', '', '0', 'F?licitations, vous avez r?ussi ? me vaincre, mes sbires et moi. Acceptez ce cadeau en guise de reconnaissance.');
INSERT INTO `npc_questions` VALUES (2939, '', '', '', '', 'Donner la cl? et rentrer.');
INSERT INTO `npc_questions` VALUES (2940, '2576', '', '', '0', 'Hum, je vois que vous avez une cl? de ce repaire... Je vais donc vous laisser rentrer, mais attention, je pense que mes confr?res  ne vous faciliteront pas la t?che, le Ma?tre Pandore qui a ?lu domicile dans ce repaire a recrut? les meilleurs Pandikazes pour assurer sa protection. Etes-vous certain de vouloir rentrer ?');
INSERT INTO `npc_questions` VALUES (2941, '2579', '', '', '0', 'Attention aventurier, de terribles cr?atures habitent ce donjon. Seul un groupe d\\\'au moins trois aventuriers peut esp?rer en sortir vivant. Es-tu certain de vouloir rentrer ?');
INSERT INTO `npc_questions` VALUES (2942, '2578', '', '', '0', 'Je suis impressionn?, rares sont les aventuriers qui arrivent ? r?sister ? mes coups de boules. Pour te r?compenser, je vais te donner mon familier, cet adorable Chienchien noir.');
INSERT INTO `npc_questions` VALUES (2943, '2577', '', '', '0', 'J\\\'ai perdu mon petit familier dans cette caverne obscure et je n\\\'ose pas aller le chercher moi-m?me. Nombreux sont ceux qui ont essay? d\\\'aller le chercher, mais tous ceux qui y sont all?s avec un groupe de moins de sept aventuriers n\\\'en sont jamais revenus. Etes-vous certain de vouloir rentrer dans cette caverne ?');
INSERT INTO `npc_questions` VALUES (2944, '2580', '', '', '', 'Wouaf wouf, wuf Wouhouaf...');
INSERT INTO `npc_questions` VALUES (2945, '', '', '', '', 'Je pense que vous n\\\'avez rien ? faire par ici.');
INSERT INTO `npc_questions` VALUES (2949, '', '', '', '', 'Hmm');
INSERT INTO `npc_questions` VALUES (2950, '', '', '', '', 'Comment est-ce possible, vous d?sirez rompre ? jamais les liens du mariage qui vous unissaient ? Avez-vous au moins une bonne raison ?');
INSERT INTO `npc_questions` VALUES (2951, '2591;2592', '', '', '0', 'Quel dommage... Mais je vous comprends apr?s tout, j\\\'ai moi-m?me v?cu il y a bien longtemps une exp?rience similaire. Ah oui, j\\\'ai oubli? de vous pr?venir, j\\\'ai r?ellement besoin de faire quelques travaux dans mon ?glise avant de pouvoir divorcer votre couple, peut-?tre pourriez-vous m\\\'aider... J\\\'ai besoin de 10000 kamas pour m\\\'acheter une nouvelle soutane, 15000 kamas pour refaire les vitraux de mon ?glise, 5000 kamas pour entretenir ma barbe, et 20000 kamas pour acheter le vin de messe... Bon il me faudrait donc 50000 kamas.');
INSERT INTO `npc_questions` VALUES (2952, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2953, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2954, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2955, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2956, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2957, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2958, '', '', '', '', 'Pnj(163) et Message(2950)');
INSERT INTO `npc_questions` VALUES (2959, '', '', '', '', 'Voil?, vous ?tes d?sormais libre...');
INSERT INTO `npc_questions` VALUES (2960, '', '', '', '', 'Ouuuulalalala ! Vous avez l\\\'air bien fatigu?. Continuez comme ?a et mon p?re ne fera qu\\\'une bouch?e de vous. \\nLe contraire m\\\'arrangerait plus en fait car j\\\'ai toujours r?v? de devenir Bworker ? la place de Bworkie. \\nPrenez ces poils et vous pourrez reprendre votre chemin ici, quand vous aurez repris des forces.');
INSERT INTO `npc_questions` VALUES (2961, '', '', '', '', 'Vous revoil? ! Je savais que vous n\\\'?tiez pas un l?che. Rendez-moi mes poils et je vous montre le chemin jusqu\\\'? l\\\'endroit o? vos forces vous ont abandonn');
INSERT INTO `npc_questions` VALUES (2963, '', '', '', '', '<B> test </B> \\n<I>test </I> \\n<U>test </U>');
INSERT INTO `npc_questions` VALUES (2964, '2596;2595', '', '', '0', 'En v?rit?, je te le dis, la d?esse Pandawa m\\\'a parl? cette nuit ! Elle m\\\'a dit qu\\\'un d?luge allait s\\\'abattre sur le Monde ! Et pas un d?luge de bi?re, un d?luge d\\\'eau... ?a va pas ?tre joli ? voir. Et donc, la d?esse m\\\'a demand? de sauver deux sp?cimens de chaque cr?ature de ce Monde ! J\\\'ai d?j? r?ussi ? en r?unir une bonne partie, mais il me manque des oeufs de Tofu... Tu serais bien aimable de m\\\'en rapporter deux ! Tu m\\\'as l\\\'air ?tourdi toi, pas vrai ? Note ?a dans ton livre, l?. Consulte-le pour conna?tre les qu?tes que tu as en cours...');
INSERT INTO `npc_questions` VALUES (2965, '278', '', '', '0', 'Grand merci ! Deux oeufs de Tofus, voil? qui est pr?cieux ! Il y a un m?le et une femelle au moins ? Tu n\\\'en es pas s?r ? H? bien il faudrait aller demander ?a au Mage Ax... Il en sait long sur le Monde et ses cr?atures celui-l?, et je devais aller le voir de toutes fa?on... Figure-toi que j\\\'ai mis la main sur un Dofus et tu va avoir le privil?ge d\\\'en porter un jusqu\\\'au Mage Ax. Cet oeuf de Dragon me semble fragile, et j\\\'ignore pourquoi... Demande au Mage ce qu\\\'il en est ! Les Dofus sont l\\\'une de ses sp?cialit?s...');
INSERT INTO `npc_questions` VALUES (2966, '', '', '', '', 'Alors, tu es de retour ? Mais tu ne m\\\'as pas ramen? des oeufs de Tofu ? Qu\\\'est-ce que tu attends ?');
INSERT INTO `npc_questions` VALUES (2967, '260', '', '', '0', 'Bien le bonjour, aventurier, que puis-je pour ton service ?');
INSERT INTO `npc_questions` VALUES (2968, '', '', '', '', 'Pnj(726) et Message(2967)');
INSERT INTO `npc_questions` VALUES (2969, '260', '', '', '0', 'Qu\\\'est-ce que j\\\'en sais, moi ? Je ne suis pas ?leveur de Tofu !');
INSERT INTO `npc_questions` VALUES (2970, '260', '', '', '0', 'Oui, je t\\\'?coute.');
INSERT INTO `npc_questions` VALUES (2971, '260', '', '', '0', 'Argh ! Tu oses mettre sous mon nez un Dofawa ! Ceci n\\\'est pas un Dofus, mais une copie cr??e ? partir d\\\'un oeuf de Dragodinde ! Rapporter de tels oeufs dans Astrub est passible de la prison !');
INSERT INTO `npc_questions` VALUES (2972, '260', '', '', '0', 'Ahah ! Le coup classique ! On t\\\'a demand? de le faire, et toi, tu l\\\'as fais ! Tu pensais vraiment que j\\\'allais te croire ? En m?me temps... Un Pandawa, tu dis ? Ca se pourrait bien, ma foi ! Qui serait assez idiot pour se vanter de d?tenir un Dofawa ?');
INSERT INTO `npc_questions` VALUES (2973, '2680;260', '', '', '0', 'Pour ?viter de te m?prendre ? l\\\'avenir, ?coute bien mes paroles. Il y a une mani?re simple de reconna?tre un Dofawa : la magie qui les impr?gne est faible... Pour t\\\'en assurer, consulte ton inventaire : clique sur le Dofawa. Si ses effets sont nuls ou proches de 1, tu te trouves en face d\\\'un Dofus contrefait ! Pour ta gouverne, sache qu\\\'un Dofus est un oeuf de Dragon. Tu n\\\'imagines pas comme ces oeufs sont puissants !');
INSERT INTO `npc_questions` VALUES (2974, '260', '', '', '0', 'Je te confisque cet objet sur le champ ! Je n\\\'ose m?me pas imaginer ce qui adviendrait de toi si les mercenaires d\\\'Astrub te surprenaient avec un Dofawa en poche... Le mieux serait de te renseigner sur les lois en vigueur dans nos contr?es. Cela t\\\'?vitera de courir des risques inutiles : rend-toi dans la prison d\\\'Astrub. Les mercenaires t\\\'en diront plus sur les Dofus et Pandala.');
INSERT INTO `npc_questions` VALUES (2975, '2784', '', '', '0', '(fredonne) Dans le port d\\\'Madrestam, y\\\'a des marins qui chantent...');
INSERT INTO `npc_questions` VALUES (2976, '', '', '', '', 'B\\\'jour ?tranger... Mmh... suis en plein message t?l?pathique avec le Mage Ax.... Non j\\\'ai pas forc? sur la bi?re ! Faudra que je lui dise d\\\'arr?ter, ?a m\\\'colle un de ces mal de cr?ne ? chaque fois !... Enfin bref ! T\\\'as ?t? tromp? ! Et pas par n\\\'importe qui ! J\\\'reconnais-l? la m?thode de ces Pandawas rebelles qu\\\'on appelle Pandikaze. Y\\\'s?vissent sur l\\\'?le de Pandala, et z\\\'ont jur? la perte de tous les aventuriers qui recherchent des Dofus. C\\\'ui-l? s\\\'est bien moqu? de toi ! Si j\\\'t\\\'avais pris avec un Dofawa sur toi, j\\\'t\\\'aurais coll? en prison. Tu ne serais pas le premier ? y croupir !');
INSERT INTO `npc_questions` VALUES (2977, '', '', '', '', 'Ouais, vaudrait mieux. Je te d?conseille de te rendre ? Pandala, avant d\\\'avoir parcouru notre belle cit?. Ici, tu apprendras tout ce qu\\\'un aventurier doit savoir pour rester en vie... D?s que tu le pourras, lis le manuel que je viens de glisser dans ton inventaire. Pour le consulter, il te suffira de mettre la main dessus, comme pour utiliser n\\\'importe quel objet. Et maintenant, bon vent !');
INSERT INTO `npc_questions` VALUES (2978, '', '', '', '', 'Si j\\\'en reprends un ? se balader avec des faux Dofus sur lui, ?a va barder !');
INSERT INTO `npc_questions` VALUES (2979, '', '', '', '', 'Vivement le d?luge !');
INSERT INTO `npc_questions` VALUES (2980, '', '', '', '', 'Pnj(725) et Message(2964)');
INSERT INTO `npc_questions` VALUES (2981, '2610;2611', '', 'QE!127', '2989', 'Entre la vieille outre ? bi?re et l\\\'autre escroc qui cherchent des na?fs ? plumer, pas facile d\\\'entendre le murmure de l\\\'avenir... Que veux-tu ? Laisse-moi deviner... Tu veux conna?tre ton destin !');
INSERT INTO `npc_questions` VALUES (2982, '', '', '', '', 'Bien ! Sans vouloir me vanter, je suis un haruspice plut?t dou? ! Vais-je lire ton avenir dans les entrailles d\\\'un Bouftou ? Dans les visc?res d\\\'un Bwak ? Mmh, non, c\\\'est plut?t la mousse de bi?re qui convient ? ton cas. Demandes-en une ? ce brave Tek Abir, et mets-l? sur ton compte, uhuhuh !');
INSERT INTO `npc_questions` VALUES (2983, '2612', '', '', '0', 'Tu ne le sais pas encore, mais c\\\'est pourtant ton souhait le plus cher.');
INSERT INTO `npc_questions` VALUES (2984, '2615;2616;2613', '', '', '0', 'Slurp ! La bi?re d\\\'Astrub, c\\\'est vraiment ma pr?f?r?e. Cette l?g?re amertume, cette mousse suave... mmhhh.... Reslurp ! Alors, je vois que tu es n? sous une bonne ?toile. Regarde bien, elle se trouve en bas ? gauche, tu saisis ?');
INSERT INTO `npc_questions` VALUES (2985, '', '', '', '', 'Parfait, t?che de t\\\'en souvenir. Ces indications sont pr?cieuses.');
INSERT INTO `npc_questions` VALUES (2986, '', '', '', '', 'Je vois que tu es ?loquent ! N\\\'h?site pas ? consulter ton ?toile, elle t\\\'indiquera comment tu dois parler ? ceux qui t\\\'entourent. Tu sauras charmer le sexe oppos? en montrant tes ?motions, et te faire des amis... Et lorsque tu seras plus aguerri, tu sauras former un Groupe d\\\'aventuriers et leur parler comme un chef. Tu feras partie d\\\'une Guilde, et ceux qui en sont membres t\\\'?couteront ! ');
INSERT INTO `npc_questions` VALUES (2987, '', '', '', '', 'A la fin de notre entretien, je te confierai un livre, tout y sera expliqu');
INSERT INTO `npc_questions` VALUES (2988, '', '', '', '', 'Pnj(729) et Message(2987)');
INSERT INTO `npc_questions` VALUES (2989, '', '', '', '', 'Ne serais-tu point sorti du troud\\\' d\\\'un Bwork ? Regarde autour de toi, on est dans une taverne. C\\\'est le genre d\\\'endroit o? on trouve de la bi?re, pas vrai ? Il te suffit de t\\\'approcher du grand gars baraqu? l?-bas, le tavernier quoi. Tu sais, ce genre de gars adore vendre de la bi?re... (soupire).');
INSERT INTO `npc_questions` VALUES (2990, '', '', '', '', 'Tu pourras apprendre de nouvelles ?motions (aussi appel?es emotes ou smileys) en participant ? des qu?tes. Va trouver Wally Elconom dans la biblioth?que d\\\'Amakna, il te proposera une de ces qu?tes.');
INSERT INTO `npc_questions` VALUES (2991, '', '', '', '', 'Pour ajouter un joueur ? ton carnet, clique sur son personnage, puis sur \\\" Ajouter ? mes amis \\\".');
INSERT INTO `npc_questions` VALUES (2992, '', '', '', '', 'Pour cr?er un groupe, clique sur le personnage que tu d?sires inviter, puis sur \\\" Inviter dans mon groupe \\\". Contrairement ? une guilde, un groupe est cr?? de fa?on temporaire. Les membres d\\\'un m?me groupe ont un canal qui leur est d?di?, et peuvent se localiser plus ais?ment gr?ce ? la boussole.');
INSERT INTO `npc_questions` VALUES (2993, '', '', '', '', 'H? dis donc, c\\\'est pas un peu fini toutes ces questions, oui !');
INSERT INTO `npc_questions` VALUES (2994, '', '', '', '', 'Je le savais bien s?r... Veille ? ce que tes paroles soient exprim?es ? droite de l\\\'?toile, sinon personne ne t\\\'entendra ! Et ne souilles pas de paroles impures l\\\'Air du Monde. Bref, sois toujours poli ! Pas comme Herdegrize... Ce vieil ?rudit a l\\\'insulte facile. Il me voue une haine coriace tu sais... Je pense qu\\\'il ?tait Bouftou dans une vie ant?rieure. Forc?ment, lorsqu\\\'il me voit lire l\\\'avenir dans leurs entrailles, ?a le met en rogne... ');
INSERT INTO `npc_questions` VALUES (2995, '', '', '', '', 'Il s\\\'est veng? en r?turant l\\\'un de mes livres... Je sais que ce livre se nomme \\\" le temps des dragons \\\". On peut trouver des exemplaires de ce livre dans Astrub. Je vois... que tu br?les de me rendre ce service, alors r?cup?res-en un pour moi !');
INSERT INTO `npc_questions` VALUES (2996, '', '', '', '', 'Tu cherches ? me tromper ? Celui-l?, c\\\'est moi qui l\\\'ai ?crit. Tu as d? le trouver dans une biblioth?que ! Retourne chercher une copie du temps des dragons ! ');
INSERT INTO `npc_questions` VALUES (2997, '', '', '', '', 'Alors ? Tu n\\\'as toujours pas trouv? de copie de mon livre ? Cherche dans Astrub, tu devrais pouvoir en trouver un exemplaire !');
INSERT INTO `npc_questions` VALUES (2998, '', '', '', '', 'Fais voir ce torchon ! Tu te rends compte ? Ce vieux schnock a sign? ces livres ? mon nom, en commettant des erreurs ?nooormes ! Il l\\\'a fait expr?s ! Tout ?a pour me discr?diter aux yeux de mes lecteurs ! H? mais... Pas moyen d\\\'y ?crire quoi que ce soit : ce livre est prot?g? par la magie d\\\'Herdegrize ! Rapporte-moi une plume de Piou violet, que je l?ve cet enchantement !');
INSERT INTO `npc_questions` VALUES (2999, '', '', '', '', 'Tu trouves un Piou violet, il y en a plein dans les parages et devant la mine. Tu l\\\'attaques gentiment, sans lui faire peur... et tu r?cup?reras sans doute une plume violette. Si jamais tu n\\\'en as pas, tu recommences. Tu vas bien r?ussir a en avoir une ! A la fin de ton combat, tu vois ce que tu as gagn? en combattant. Les objets sont rang?s dans ton inventaire...');
INSERT INTO `npc_questions` VALUES (3000, '', '', '', '', 'Pas toujours, mais assez souvent ! Chaque cr?ature est susceptible de t\\\'apporter des objets, comme une coiffe ou une paire de bottes,  ou des ressources, comme le cuir ou de l\\\'ambre... Toutes ces trouvailles ont une valeur marchande ? ne pas n?gliger... Et puis, tu pourras avec de la chance, trouver une guildalogemme ! Cette pierre te permettra de cr?er ta propre guilde... Si tu veux en savoir plus ? ce sujet, rends-toi dans le temple des Guildes...');
INSERT INTO `npc_questions` VALUES (3001, '', '', '', '', 'Beau travail, en m?me temps, ?a n\\\'est pas tr?s f?roce un Piou, hein ? ! (Griffonne fr?n?tiquement en marmonnant). Aah ! Le fourbe ! Il ne respecte vraiment rien ! Raah ! Tiens, je te donne ce livre, il est maintenant expurg? de toute erreur... Prends aussi ce manuel, je le range dans ton inventaire, n\\\'h?site pas ? le consulter ! C\\\'est un ouvrage pratique pour les jeunes aventuriers.');
INSERT INTO `npc_questions` VALUES (3002, '', '', '', '', 'Tu n\\\'as pas trouv? de plumes ? Tu sais, on trouve des plumes au bout des volatiles. Et puis, les volatiles, ce sont des animaux qui savent voler, et dans lesquels on peut lire l\\\'avenir si on est dou?. Bref ! Tu trouves un Piou violet, il y en a plein dans les parages. Attaque-le et tu r?cup?reras sans doute une plume violette. Si jamais tu n\\\'en as pas, tu recommences. Tu vas bien r?ussir a en avoir une ! A la fin de ton combat, tu vois ce que tu as gagn? en combattant. Les objets sont rang?s dans ton inventaire...');
INSERT INTO `npc_questions` VALUES (3003, '', '', '', '', 'Tu as parl? ? Majistro ? Et il t\\\'a dit que j\\\'ai ?crit un livre qui t\\\'int?resse ? Comment tu dis ? ?Le choix des dieux\\\' ? Oui, c\\\'est bien moi qui en suis l\\\'auteur ! Comme tu viens de la part de Majistro, je te fais un prix : je te le vends moins cher qu\\\'? la biblioth?que... Allez, 40 kamas !');
INSERT INTO `npc_questions` VALUES (3004, '2639;2644;2647;2650;2656;2653;2674', '', '', '0', 'Demandeeez mes parchemins ! Ils sont enlumin?s et garantis sans fautes d\\\'orthographe ! Je connais aussi les bons plans pour se procurer des parchemins ?l?mentaux, les meilleurs de toute la r?gion !');
INSERT INTO `npc_questions` VALUES (3005, '', '', '', '', 'Ces parchemins te permettront de parfaire rapidement ton entra?nement. Je les ?change contre 100 ? 105 cornes de Bouftou selon les types. D\\\'autres personnes t\\\'?changeront des parchemins dans notre Monde, ? toi de les trouver !');
INSERT INTO `npc_questions` VALUES (3006, '', '', '', '', 'Il vaut 100 kamas.');
INSERT INTO `npc_questions` VALUES (3007, '', '', '', '', 'Il vaut 69 kamas.');
INSERT INTO `npc_questions` VALUES (3008, '2642;2643', '', '', '0', 'Va voir Edrige Valling, dans le temple de la d?esse Cra, une bien belle bougresse, crois-moi.');
INSERT INTO `npc_questions` VALUES (3009, '2645;2646', '', '', '0', 'Va voir Bolzano Vieilletrasse dans la for?t d\\\'Amakna. Si tu lui rend service, il t\\\'en procurera un.');
INSERT INTO `npc_questions` VALUES (3010, '2648;2649', '', '', '0', 'Va voir Rish Claymore, dans le temple de Iop. C\\\'est un fier guerrier, il en a s?rement sur lui.');
INSERT INTO `npc_questions` VALUES (3011, '2651;2652', '', '', '0', 'Va voir Zeurg, dans le temple d\\\'Osamodas, il a des moeurs ?tranges... Mais il poss?de des parchemins de Sagesse, ce qui est plus ?trange encore !');
INSERT INTO `npc_questions` VALUES (3012, '2654;2655', '', '', '0', 'Va voir Hugo B?lo, dans le temple de la d?esse F?ca. Il saura t\\\'en procurer.');
INSERT INTO `npc_questions` VALUES (3013, '2657;2658', '', '', '0', 'Va voir Elya Wood, dans le temple de la d?esse Eniripsa. Elle est intelligente, elle, et n\\\'a plus besoin de ce genre de parchemins !');
INSERT INTO `npc_questions` VALUES (3014, '2660', '', '', '0', 'Ah, vous tombez bien, il m\\\'en reste quelques exemplaires... Ca se vend bien en ce moment, ?a ! Faudrait qu\\\'Herdegrize m\\\'en donne d\\\'autres !');
INSERT INTO `npc_questions` VALUES (3015, '', '', '', '', 'Moi, ce que j\\\'en sais, c\\\'est que ?a se vend bien... (vous regarde tout ? coup avec m?fiance).');
INSERT INTO `npc_questions` VALUES (3016, '2662', '', 'QE!128', '3020', 'OoOooOooohh ! Esprits des guerriers tomb?s lors de la bataille de l\\\'Aurore Pourpre, parlez-moi ! Qu\\\'est-ce qui d?range votre sommeil ? Dites-le moi ! Mmmh ?');
INSERT INTO `npc_questions` VALUES (3017, '2663;2664', '', '', '0', 'Des ph?nom?nes ?tranges troublent la qui?tude de ceux qui sont cens?s se reposer ici. J\\\'essaie de comprendre ce qu\\\'il s\\\'y passe... Si tu n\\\'as pas peur des fant?mes, ni de perdre la boule, viens m\\\'aider !');
INSERT INTO `npc_questions` VALUES (3018, '2667;2666', '', '', '0', 'Je n\\\'en attendais pas moins de toi ! Puisqu\\\'on va causer d\\\'?ternit? avec des fant?mes, j\\\'ai besoin que ton esprit soit pr?par?. Va m?diter sur l\\\'infinit? de l\\\'espace et du temps aupr?s du dieu X?lor. Sa statue se trouve dans l\\\'enceinte de la ville. Prends ta carte, et pointe la statue du dieu ? l\\\'aide d\\\'un drapeau, cela va aimanter l\\\'aiguille de ta boussole vers ta destination. Une fois l?-bas, regarde bien le marteau du dieu, un signe y est grav?. Reviens me voir apr?s cela.');
INSERT INTO `npc_questions` VALUES (3019, '2665', '', '', '0', 'Tu pr?f?res mourir idiot et hanter une vieille tombe pourrie pour l\\\'?ternit? ? Libre ? toi... ');
INSERT INTO `npc_questions` VALUES (3020, '', '', '', '', 'Je ne peux pas faire grand-chose pour toi. OohoOoOohoOo je sens qu\\\'un spectre veut te parler par ma bouche, Sombre andouille, trouve le dieu X?lor, ?a n\\\'est pas si difficile ! Voil?, le message est pass? !');
INSERT INTO `npc_questions` VALUES (3021, '', '', '', '', 'Bien, si tu reviens me voir, c\\\'est que tu as trouv? le signe dont nous avons parl');
INSERT INTO `npc_questions` VALUES (3022, '', '', '', '', 'Bien jou? ! Tu sais sans doute que ce signe est celui de l\\\'infini... OohoOo je sens qu\\\'un spectre veut te parler par ma bouche... ohOho (d\\\'une voix d\\\'outre-tombe) Fais pivoter ce signe de 90? et tu obtiendras un chiffre. Ce chiffre d?signe la premi?re coordonn?e de l\\\'endroit o? tu dois te rendre. Transforme ce chiffre en pla?ant le signe \\\" moins \\\" devant lui. Tu auras la deuxi?me coordonn?e de l\\\'endroit o? tu dois te rendre.');
INSERT INTO `npc_questions` VALUES (3023, '', '', '', '', 'Dans ce cas, je ne peux pas faire grand-chose pour toi. Ton esprit n\\\'est pas pr?t. Tu n?es pas digne. Je ne suis m?me pas s?r que tu sentes bon. Retourne aupr?s du dieu, ou va voir l\\\'un de ses disciples. Un X?lor saura te renseigner.');
INSERT INTO `npc_questions` VALUES (3024, '', '', '', '', 'Salut ? toi, ?tranger. Tu te trouves en un point du Monde o? l\\\'Infini et le N?ant se rejoignent, en tous cas si on en croit les chiffres. On ne dirait pas, hein ? C\\\'est Nistracolamus qui t\\\'envoie ?');
INSERT INTO `npc_questions` VALUES (3025, '', '', '', '', 'L\\\'?me de M?nalt ne peut trouver le repos ! C\\\'est son courroux qui trouble le sommeil des morts... Enterr? l? depuis la bataille de l\\\'Aurore Pourpre, il est rong? par la col?re : sa t?te lui a ?t? d?rob?e et il veut ? tout prix la r?cup?rer ! D\\\'ailleurs, si nous autres, les centaures, sommes devenus Percepteurs, c\\\'est avant tout pour retrouver la t?te disparue de M?nalt... Je pr?f?rerai la trouver avant lui... Crois-moi, s\\\'il r?ussit ? lever une arm?e de morts vivants, on risque d\\\'en entendre parler !');
INSERT INTO `npc_questions` VALUES (3026, '', '', '', '', 'Tu rencontreras d\\\'autres aventuriers du c?t? du Kanojedo en Amakna, il se trouve au centre du Monde. L?-bas tu pourras te renseigner sur les us et coutumes d\\\'Amakna. La taverne d\\\'Amakna est d\\\'ailleurs r?put?e pour ses soir?es... \\nPour voyager ? la vitesse de la pens?e, je te conseille de prendre un Zaap. Ces arches magiques sont tr?s pratiques pour parcourir le Monde. Lorsque tu en vois une, n\\\'oublie pas de la toucher. Tu m?moriseras l\\\'emplacement de ce Zaap, et tu pourras y revenir ult?rieurement. \\nBonne route, et avant de partir, je te remets ce livre ! Tu le trouveras dans ton inventaire. Prends connaissance de ce qu\\\'il contient.');
INSERT INTO `npc_questions` VALUES (3027, '2672', '', '', '0', 'H? l\\\'ami ! Tu aimes la vie au grand air ? Tu cherches une activit? saine qui t\\\'apportera la joie de vivre ? Tu en as assez de la compagnie des Champ Champ et des Larves ? Tu as de la chance de tomber sur moi, j\\\'ai ce qu\\\'il te faut !');
INSERT INTO `npc_questions` VALUES (3028, '', '', '', '', 'Le manuel de la parfaite recrue br?kmarienne ! Avec ?a en poche, tu feras carri?re dans la miliche de notre belle cit? ! Prends ! Tout y est expliqu? ! Bonne lecture ! Si tu d?cides de rejoindre nos rangs, va trouver Oto Mustam, il se trouve du c?t? de la Miliche, dans la ville de Br?kmar !');
INSERT INTO `npc_questions` VALUES (3029, '', '', '', '', 'Nous avons encore battu Bonta la derni?re fois, les braves s\\\'engagent tous chez Br?kmar !');
INSERT INTO `npc_questions` VALUES (3030, '2673', '', '', '0', 'Hol? camarade ! La vie ne vaut la peine d\\\'?tre v?cue que sur un champ de bataille, pas vrai ? Les entra?nements virils, les tours de garde au clair de lune, ?a te tente tout ?a, hein ? Et je ne t\\\'ai m?me pas parl? de la franche camaraderie des milichiens de Bonta ! Alors, c\\\'est d?cid?, tu veux t\\\'engager ?');
INSERT INTO `npc_questions` VALUES (3031, '', '', '', '', 'En attendant, prends ce livre ! C\\\'est le manuel de la parfaite recrue de Bonta. Ensuite, vas trouver Amayiro, le chef de la Miliche. Lui seul d?cidera de t\\\'engager... ou non !');
INSERT INTO `npc_questions` VALUES (3032, '', '', '', '', 'Br?kmar, et son arm?e de t?tards ont encore fuit devant les braves de Bonta. Engagez-vous chez Bonta et vous serrez toujours vainqueur ! ');
INSERT INTO `npc_questions` VALUES (3033, '', '', '', '', 'Quel sera le sujet de mon prochain livre ? Toi, peut-?tre ?');
INSERT INTO `npc_questions` VALUES (3034, '', '', '', '', 'Il faudra que je pense ? ferrer mes sabots lors de ma prochaine visite en ville.');
INSERT INTO `npc_questions` VALUES (3035, '', '', '', '', 'OoOooOooohh ! OoOooOooohh ! OoOooOooohh ! Y a t\\\'il un esprit de disponible pour me tenir compagnie ? OoOooOooohh ! OoOooOooohh ! Personne ? OoOooOooohh ! OoOooOooohh !');
INSERT INTO `npc_questions` VALUES (3036, '2679;2677', '', '', '0', 'J\\\'ai aussi des parchemins coquins ! Mais je ne pense pas que cela int?resse quelqu\\\'un d\\\'aussi chaste que toi ! J\\\'ai aussi un Glossaire : le Glossarius Dofusus, tr?s utile pour comprendre le jargon de certains aventuriers.');
INSERT INTO `npc_questions` VALUES (3037, '', '', '', '', 'Par Ecaflip, c\\\'est toi la nouvelle recrue ?! Bon, je n\\\'ai pas le temps de v?rifier. Le pr?tre d\\\'Astrub m\\\'a fait mander, et j\\\'ai besoin de quelqu\\\'un pour renforcer la garde de ces lascars. Seras-tu des n?tres ? Je t\\\'offrirai une r?compense pour cela !');
INSERT INTO `npc_questions` VALUES (3038, '', '', '', '', 'Par Ecaflip, c\\\'est toi la nouvelle recrue ?! Bon, je n\\\'ai pas le temps de v?rifier. Le pr?tre d\\\'Astrub m\\\'a fait mander, et j\\\'ai besoin de quelqu\\\'un pour renforcer la garde de ces lascars. Seras-tu des n?tres ? Je t\\\'offrirai une r?compense pour cela !');
INSERT INTO `npc_questions` VALUES (3039, '', '', '', '', 'Tiens, je te donne ce manuel : ? lire une fois que tu auras accompli cette mission ! Ouvre l\\\'oeil, et le bon !');
INSERT INTO `npc_questions` VALUES (3040, '', '', '', '', 'Rargh, je me sens faible ! Je n\\\'ai plus beaucoup d\\\'?nergie ! Ce combat aurait pu m\\\'?tre fatal... Et je n\\\'ai m?me pas une potion de soin sur moi... H?h?, heureusement, gr?ce ? mon sens de l\\\'initiative, je me suis tir? d\\\'affaire !');
INSERT INTO `npc_questions` VALUES (3041, '', '', '', '', 'Bien jou? aventurier ! Tu m\\\'as l\\\'air t?m?raire, et le combat ne te fais pas peur. Du c?t? de la prison, tu verras des avis de recherche placard?s sur des poteaux. Si tu veux te faire des kamas, il y a quelques hors-la-loi ? retrouver de part le vaste Monde. Bonne route et longue vie ? toi ! Avant de partir, n\\\'oublie pas de jeter un oeil au livre que je viens de te donner!');
INSERT INTO `npc_questions` VALUES (3042, '', '', '', '', 'Rargh, je me sens faible ! Je n\\\'ai plus beaucoup d\\\'?nergie !');
INSERT INTO `npc_questions` VALUES (3043, '', '', '', '', 'On a toujours besoin des bons offices d\\\'un pr?tre ! Ressusciter les aventuriers peu pr?voyants, c\\\'est ce que je fais le mieux. Tu pourras le devenir toi aussi, si tu pers?v?res dans l\\\'un des Ordres de Bonta ou de Br?kmar... \\nAvant de parvenir ? ce stade avanc?, sache que pour te redonner de l\\\'?nergie, rien ne vaut une bonne potion concoct?e par un alchimiste ! Mais si, tu sais bien, ces boissons go?teuses l?, qu\\\'on appelle les \\\'Raide\\\' : la Pahoa, la Ghetto, et la derni?re la Raide Boule, leur go?t n\\\'est pas fameux, mais ?a te requinque un moribond...');
INSERT INTO `npc_questions` VALUES (3044, '2688;2689', '', 'QE!131', '3047', 'Le ch?teau d\\\'Allister a enfin ouvert ses portes. Le roi se morfondait dans ses appartements pendant tous ces travaux. Maintenant, les baladins, les montreurs de Trools et les troubadours vont de nouveaux affluer. Tu devrais aller visiter les nouveaux am?nagements du ch?teau et de son port.');
INSERT INTO `npc_questions` VALUES (3045, '', '', '', '', 'Un jour, j\\\'esp?re que le roi Allister daignera me faire visiter ses appartements priv?s. Soupir.');
INSERT INTO `npc_questions` VALUES (3046, '', '', '', '', 'Je ne t\\\'avais pas menti, c\\\'est un ch?teau de toute beaut? !');
INSERT INTO `npc_questions` VALUES (3047, '', '', '', '', 'Nous pouvons enfin nous rendre ? nouveau dans le somptueux ch?teau d\\\'Allister.');
INSERT INTO `npc_questions` VALUES (3048, '', '', '', '', 'Bienvenue #1.\\nJe suis surpris qu\\\'aucun Crocodaille ne t\\\'ait d?vor? en arrivant jusqu\\\'ici, tu as d? avoir beaucoup de chance...\\nCe sanctuaire est infest? de terribles fant?mes de familiers, tous ceux que les aventuriers ont abandonn?s. Ils n\\\'ob?issent qu\\\'? leur ma?tre, Oshima, le p?re d\\\'Oshimo, qui tient le Chanil pr?s de Sufokia.\\n');
INSERT INTO `npc_questions` VALUES (3049, '', '', '', '', 'Attention, seuls les fant?mes de familiers peuvent rentrer dans ce sanctuaire #1 !\\nSi tu as avec toi ce genre de cr?ature, tu peux tenter de la faire rentrer, mais attention, elle n\\\'a presque aucune chance de survivre seule, il faudrait qu\\\'elle soit accompagn?e d\\\'autres fant?mes de familiers pour esp?rer sortir de ce sanctuaire.\\nSi ton fant?me de familier r?ussi ? vaincre ceux d\\\'Oshima, il devrait avoir la chance de le rencontrer.\\n\\nEs-tu certain de vouloir faire rentrer dans ce sanctuaire un de tes fant?mes de familiers ?');
INSERT INTO `npc_questions` VALUES (3050, '', '', '', '', 'Visez-moi la bleusaille qui est charg?e de nous garder ! Yaahaaa ! Rebellons nous !');
INSERT INTO `npc_questions` VALUES (3051, '', '', '', '', 'Alors, bande de taulards, on se r?volte ? Vous ne vous attendiez pas ? ce que je revienne si vite ! Rahaayaa !');
INSERT INTO `npc_questions` VALUES (3052, '', '', '', '', 'Alors, bande de taulards, on se r?volte ? Vous ne vous attendiez pas ? ce que je revienne si vite, pas vrai ? Je n\\\'ai qu\\\'un mot ? dire pour qualifier une attitude si vile, abjecte, et carr?ment pas sympa : Rahaayaa !');
INSERT INTO `npc_questions` VALUES (3053, '2721;2722', '', 'QE!139', '3055', 'Notre bon roi Allister a besoin de steaks de Dragodinde bien saignants pour sa table. Peux tu m\\\'en fournir ?');
INSERT INTO `npc_questions` VALUES (3054, '', '', '', '', 'Merci, voil? pour toi.');
INSERT INTO `npc_questions` VALUES (3055, '', '', '', '', 'Le roi Allister a faim. Il veut du steak de Dragodinde. Il en a assez des Wabbits en sauce.');
INSERT INTO `npc_questions` VALUES (3056, '', '', '', '', 'J\\\'ai un petit creux.');
INSERT INTO `npc_questions` VALUES (3057, '2723;2724', '', '', '', 'Le ch?teau d\\\'Allister n\\\'est pas vraiment achev?. Il y a ?norm?ment de petits d?tails ? terminer. J\\\'aurais besoin de plusieurs ressources pour finir la construction de la demeure royale. Pour commencer, j\\\'aurais besoin de planches.');
INSERT INTO `npc_questions` VALUES (3058, '', '', '', '', 'Voil? pour les planches, elles serviront aux infrastructures. Maintenant, j\\\'aurais besoin de rocs pour les murs.');
INSERT INTO `npc_questions` VALUES (3059, '', '', '', '', 'Un beau tas de pierres que voil?, merci. Mes ma?ons ont faim, si tu pouvais me ramener un peu de bl?, je pourrais les nourrir ces gaillards.');
INSERT INTO `npc_questions` VALUES (3060, '', '', '', '', 'Ils ont toujours faim ! Un peu de chair de larves devrait les ragaillardir.');
INSERT INTO `npc_questions` VALUES (3061, '', '', '', '', 'Avec tout ce que tu nous as livr?, nous allons pouvoir avoir un beau ch?teau que le monde entier nous envie d?j');
INSERT INTO `npc_questions` VALUES (3062, '', '', '', '', 'Tu devrais pouvoir tout trouver dans les environs.');
INSERT INTO `npc_questions` VALUES (3063, '', '', '', '', 'Je pourrai dire que j\\\'ai particip? ? la reconstruction du ch?teau d\\\'Allister.');
INSERT INTO `npc_questions` VALUES (3064, '', '', '', '', 'T\\\'es quelqu\\\'un de s?rieux et pleins de ressources. Moi, je suis d?bord? par les travaux au ch?teau d\\\'Allister. Je sais que je peux compter sur toi. J\\\'aimerais faire un d?ner aux chandelles avec ma belle. Elle adore le poisson.');
INSERT INTO `npc_questions` VALUES (3065, '', '', '', '', 'Nous allons nous r?galer ! J\\\'ai pens? ? un petit d?tail pour cl?turer la soir?e, pourrais-tu me trouver une bague de fian?ailles ?');
INSERT INTO `npc_questions` VALUES (3066, '', '', '', '', 'J\\\'ai h?te d\\\'y ?tre, pourrais-tu aller l\\\'inviter de ma part ? \\nElle s\\\'appelle Monabella, elle r?side au ch?teau d\\\'Allister et fl?ne souvent sur les quais. Pr?viens-moi d?s qu\\\'elle est disponible.');
INSERT INTO `npc_questions` VALUES (3067, '', '', '', '', 'Elle ne veut toujours pas ? Elle veut que je bouge ? Allister ne supportera jamais que je d?laisse les chantiers de r?novation de son ch?teau pour de la bagatelle. Bon, bah, essaie avec Verumacha, elle se trouve au port du ch?teau d\\\'Allister. Pr?viens-moi d?s qu\\\'elle est disponible.');
INSERT INTO `npc_questions` VALUES (3068, '', '', '', '', 'Je n\\\'ai d?cid?ment pas de chance avec les dames. Je pr?f?re que tu invites mon ami Guedin Loursgro du coup. Pense ? me ramener un peu de bi?re ? l\\\'occasion.');
INSERT INTO `npc_questions` VALUES (3069, '', '', '', '', 'Vivement la soir?e que je d?guste du poisson aux chandelles en bonne compagnie.');
INSERT INTO `npc_questions` VALUES (3070, '', '', '', '', 'Manger avec ce gros ballot de Kartier Tremai ? T\\\'es pas le premier messager qu\\\'il m\\\'envoie. Le jour o? il viendra lui-m?me, nous en reparlerons !');
INSERT INTO `npc_questions` VALUES (3071, '', '', '', '', 'Kartier Tremai ? A tous les coups, il a encore ?t? remball? par Monabella. J\\\'en ai assez de manger de la poiscaille ! \\nC\\\'est non. Avec un peu de chance, je trouverai un pr?tendant plus galant, plus carnivore et plus fortun? h?h?h');
INSERT INTO `npc_questions` VALUES (3072, '', '', '', '', 'Hors de ma vue galopin ! Goujat ! Malotru !');
INSERT INTO `npc_questions` VALUES (3073, '', '', '', '', 'Kartier Tremai me propose encore une bonne biture ? Excellent, nous allons noyer son chagrin et son poisson dans la bi?re !');
INSERT INTO `npc_questions` VALUES (3074, '2729;273', '', 'QE!136', '3099', 'Il y a un requin qui s?me le trouble dans le port. Trouve-le moi et reviens m\\\'indiquer o? il navigue. ');
INSERT INTO `npc_questions` VALUES (3075, '273', '', '', '0', 'Alors, t\\\'as trouv? le bestiau ?');
INSERT INTO `npc_questions` VALUES (3076, '', '', '', '', 'Je ne parle pas du requin, le poisson. qui vient du mot requiem (la messe des morts) mais d\\\'un forban, un truand qui s?me la terreur dans le port. Tu peux pas le rater il est couleur carmin (rouge pour les ignares de ton acabit). Dis lui de quitter les lieux !');
INSERT INTO `npc_questions` VALUES (3077, '', '', '', '', 'Quoi, il ose tenter de corrompre une offici?re asserment?e du roi Allister dans l\\\'exercice de ses fonctions ? Retourne le voir, ce n\\\'est pas avec ces pi?cettes qu\\\'il va me convaincre.');
INSERT INTO `npc_questions` VALUES (3078, '', '', '', '', 'Voil? qui est mieux, je suis ?reint?e par toutes ces ?motions. Va donc me chercher du lait de cochon de lait brave petit, je te donnerai des bonbons. C\\\'est mauvais pour mes dents.');
INSERT INTO `npc_questions` VALUES (3079, '', '', '', '', 'Encore une journ?e bien remplie et attention aux caries.');
INSERT INTO `npc_questions` VALUES (3080, '', '', '', '', 'Je siroterai bien un peu de lait de cochon tout en jetant quelques morceaux de contrebandiers aux requins...');
INSERT INTO `npc_questions` VALUES (3081, '', '', '', '', 'La vieille Verumacha me cherche des poux ? Ce n\\\'est pas la cheftaine des douanes pour rien. La vie de contrebandier est bien rude de nos jours. Donne lui ces 1000 Kamas. Cela la calmera peut ?tre. Reviens me voir de suite, je te filerai un peu de marchandise interdite pour ce service. Fais vite, sinon je te retrouverai et te donnerai ? manger aux vrais requins !');
INSERT INTO `npc_questions` VALUES (3082, '', '', '', '', 'Elle veut plus ? Ce n\\\'est pas une Enutrof pour rien. Voici encore 1000 Kamas. Reviens vite pour ta r?compense.');
INSERT INTO `npc_questions` VALUES (3083, '', '', '', '', 'Merci pour ta discr?tion. Si tu as un peu de temps devant toi, repasse me voir, j\\\'ai peut-?tre une livraison ? te confier.');
INSERT INTO `npc_questions` VALUES (3084, '', '', '', '', 'Comme tu le sais, je fais dans la contrebande. Le roi Allister a interdit la vente d\\\'aphrodisiaque et de potions de l?che-bottes. Il a peur de faire un arr?t cardiaque au milieu de ses courtisanes ou d\\\'exempter un commer?ant de taxes ? mon avis.');
INSERT INTO `npc_questions` VALUES (3085, '', '', '', '', 'G?nial, il n\\\'y a plus qu\\\'? livrer tout ?a. Va voir si Monabella est toujours int?ress?e.');
INSERT INTO `npc_questions` VALUES (3086, '', '', '', '', 'Elle n\\\'en veut plus la peste ! Essaie avec Haraquiri, le boucher du roi. Je crois qu\\\'il aimerait rentrer dans le coeur du roi afin qu\\\'il augmente ses commandes. S\\\'il la veut vends lui la potion et ram?ne-moi les Kamas, tu auras ta part dans l\\\'affaire. Ne sois pas en retard, sinon tu subiras mon courroux.');
INSERT INTO `npc_questions` VALUES (3087, '', '', '', '', 'Une affaire rondement men?e. Je vais aller boire un peu de lait de cochon avec ma vieille amie Verumacha. Gr?ce ? elle, j\\\'ai pu voir que tu ?tais quelqu\\\'un de confiance.');
INSERT INTO `npc_questions` VALUES (3088, '', '', '', '', '*Chantonne* Vous versez de la mort aux rats dans du venin de cobra.  \\nPour adoucir le m?lange, pressez trois quartiers d\\\'orange...');
INSERT INTO `npc_questions` VALUES (3089, '', '', '', '', 'Je n\\\'ai point besoin de cela pour plaire ? mon roi. Pour le ravir, il me suffit de pointer mon beau minois. Trouve quelqu\\\'un d\\\'autre qui n\\\'a pas mon charisme f?lin.');
INSERT INTO `npc_questions` VALUES (3090, '', '', '', '', 'Cette potion m\\\'int?resse. Elle me para?t fort utile pour mon commerce. Voici les Kamas. Je sens que les affaires vont d?coller et que mes bottes vont ?tre cir?es ? la bave royale.');
INSERT INTO `npc_questions` VALUES (3092, '2735;2736', '', '', '', 'Il y a un requin qui n\\\'arr?te pas de me reluquer dans le port. A chaque fois que je d?charge des tonneaux d\\\'un bateau, j\\\'ai peur de tomber dans l\\\'eau et de me faire d?vorer. Il me faudrait un bon remontant pour l\\\'oublier.');
INSERT INTO `npc_questions` VALUES (3093, '', '', '', '', 'Oui, de la bonne mousse ti?de.');
INSERT INTO `npc_questions` VALUES (3094, '', '', '', '', 'Ayaah !');
INSERT INTO `npc_questions` VALUES (3095, '', '', '', '', 'Eyeeh !');
INSERT INTO `npc_questions` VALUES (3096, '', '', '', '', 'Je vois que tu sais o? trouver de la bonne bi?re. J\\\'aimerais bien en comparer plusieurs.');
INSERT INTO `npc_questions` VALUES (3097, '', '', '', '', 'J\\\'aurais pas d? boire aussi vite. Un peu d\\\'eau me fera le plus grand bien.');
INSERT INTO `npc_questions` VALUES (3098, '', '', '', '', 'Merci ? toi, je suis pr?t ? affronter le requin maintenant !');
INSERT INTO `npc_questions` VALUES (3099, '', '', '', '', 'Si si tu vas trouver, t\\\'es un petit fut? toi.');
INSERT INTO `npc_questions` VALUES (3100, '', '', '', '', 'Je ne sais pas ce qu\\\'il cherche ce requin. Un docker marin? ? la bi?re ?');
INSERT INTO `npc_questions` VALUES (3101, '', '', '', '', 'Tu t\\\'en es s?rement rendu compte, tout le monde veut me vendre quelque chose ou voir mes fesses. En fait, ce que je veux moi, c\\\'est juste une petite maison o? je pourrais vivre loin de tous ces tracas avec un ?tre qui me serait cher.');
INSERT INTO `npc_questions` VALUES (3102, '', '', '', '', 'Merci de vouloir aider une pauvre courtisane. J\\\'aimerais tant habiter dans une jolie petite maison isol?e loin de la cour. Gemf? Labelle m\\\'a parl? d\\\'une ancienne planque ? lui. Tu devrais aller le voir pour lui demander si je peux y vivre.');
INSERT INTO `npc_questions` VALUES (3103, '', '', '', '', 'Quoi ? Habiter avec lui dans cet endroit glauque qui sent la patate pourrie, il se prend pour qui ce vieux taulard ? \\nTrouve plut?t son ancienne planque et reviens me la d?crire.');
INSERT INTO `npc_questions` VALUES (3104, '', '', '', '', 'Cela a l\\\'air tr?s beau, je vais pouvoir fortifier mon teint, cependant c\\\'est loin de la r?gion. Ram?ne-moi une Dragodinde docile. Pense aussi ? trouver de l\\\'huile de tournesol que je puisse oindre mon corps d?licat. Merci, tu seras un chou.');
INSERT INTO `npc_questions` VALUES (3105, '', '', '', '', 'Il ne me manque plus que mon ?tre cher. Un familier doux et ronronnant fera l\\\'affaire. Je veux un Chacha tout blanc comme moi. Trouve-m\\\'en six que je choisisse le plus blanc.');
INSERT INTO `npc_questions` VALUES (3106, '', '', '', '', 'Merci pour tous tes services, je parais un peu capricieuse comme ?a mais si je disais oui ? tout le monde, je serais obliger de courir partout comme toi et mon m?tabolisme ne le supporterait pas.');
INSERT INTO `npc_questions` VALUES (3107, '', '', '', '', 'Olalala, ce que tu peux ?tre lent, mes pr?tendants auraient d?j? finit cette petite chose que je te demande.');
INSERT INTO `npc_questions` VALUES (3108, '', '', '', '', 'Lors de sa derni?re visite au port de Madrestam, le roi Allister a dit de moi que m?me les sir?nes enviaient ma beaut');
INSERT INTO `npc_questions` VALUES (3109, '', '', '', '', 'Ma vieille planque ? Elle est situ?e dans le nord ouest de la montagne des Eleveurs au bord des lacs enchant?s. C\\\'est un bel endroit bucolique et romantique, il est parfait pour roucouler avec sa douce. Je laisse ma planque ? qui l\\\'habitera. Personnellement, je pr?f?re les murs de ma prison. Monabella pourrait venir y habiter avec moi d\\\'ailleurs plut?t que d\\\'aller vivre dans cette r?gion ? moustiques. H?h?h?...');
INSERT INTO `npc_questions` VALUES (3110, '', '', '', '', 'Merci pour les patates. Quand il y en a plus, je m\\\'ennuie. J\\\'aimerais bien une pelle de Boisaille pour les cultiver moi-m?me.');
INSERT INTO `npc_questions` VALUES (3111, '', '', '', '', 'Merci pour la pelle. Pars remercier Rocco Fidelio pour ses sacs de patates. Dis lui qu\\\'ils devraient arr?ter plus de monde pour redonner un peu de vie ? cette belle prison au bord de l\\\'eau. Tu devrais rester avec moi, ?plucher des patates, c\\\'est tout un art !');
INSERT INTO `npc_questions` VALUES (3112, '', '', '', '', 'Chantonnant : \\nSi j\\\'avais un marteau, je planterais des clous \\nSi j\\\'avais une pelle, je planterais des patates \\nSi j\\\'avais un ?conome, j\\\'?plucherais des patates \\nLalalala');
INSERT INTO `npc_questions` VALUES (3113, '2739;2740', '', 'QE!138', '3115', 'Je dois surveiller les prisonniers et la prison. Peux tu apporter ces sacs de patates ? Gemf? Labelle ? Il est ? la prison du Port de Madrestam ? Faut le nourrir avant qu\\\'il ne cr?ve la dalle. Sinon, apr?s, il va trouver une galerie pour s\\\'enfuir.');
INSERT INTO `npc_questions` VALUES (3114, '', '', '', '', 'Le pauvre gar?on, il ne veut pas quitter sa prison. Le roi Allister l\\\'a amnisti? pourtant. Il avait vol? tout un convoi de pommes de tewe en provenance de l\\\'?le des Wabbits.');
INSERT INTO `npc_questions` VALUES (3115, '', '', '', '', 'Pas compliqu? de livrer des patates tout de m?me.');
INSERT INTO `npc_questions` VALUES (3116, '', '', '', '', 'Attention, fais pas le mariole ou tu te retrouveras ? l\\\'ombre ? ?plucher des patates et ? manger de la soupe froide aux asticots. ');
INSERT INTO `npc_questions` VALUES (3117, '', '', '', '', 'Impressionnant, petit familier, tu as r?ussi ? vaincre mes prot?g?s.\\nTu as bien m?rit? que je t\\\'aide en tentant de te ramener ? la vie.\\nJe peux ?changer une poudre de r?surrection et ton corps de fant?me contre une r?surrection, mais elle ne prendra effet que lorsque tu seras sorti d\\\'ici, tu seras alors de nouveau aux c?t?s de ton ma?tre.');
INSERT INTO `npc_questions` VALUES (3118, '2741;2787', '', '', '', 'Impressionnant, petit familier, tu as r?ussi ? vaincre mes prot?g?s. \\nTu as bien m?rit? que je t\\\'aide en tentant de ramener ? la vie un de tes prot?g?s. \\nJe peux ?changer une poudre de r?surrection et le corps fant?me contre une r?surrection, mais elle ne prendra effet que lorsque tu seras sorti d\\\'ici, ton compagnon sera de nouveau ? tes c?t?s.');
INSERT INTO `npc_questions` VALUES (3119, '2742', '', 'NPC=1', '3161', 'N\\\'avance pas d\\\'un pas #1. \\nTu n\\\'es qu\\\'un mis?rable aventurier, et ta mis?rable existence va prendre fin ici ! \\nMais... Comment as-tu fait pour venir jusqu\\\'ici ? Tu as r?ussi ? vaincre les autres Koalaks ? \\nBon, en fait, tu es le bienvenu ici... j\\\'appr?cie les aventuriers t?m?raires comme toi ! \\nMes ma?tresses m\\\'ont demand? de garder l\\\'entr?e de cette caverne, le Koulosse y est enferm?, et seuls les aventuriers qui disposent d\\\'une clef ont le droit de rentrer. As-tu une clef pour y rentrer ?');
INSERT INTO `npc_questions` VALUES (3120, '', '', '', '', 'Mes ma?tresses ont enferm? le Koulosse dans sa propre caverne pour  qu\\\'elles puissent contr?ler la montagne des Koalaks. Pour ?viter qu\\\'un aventurier tente de venir d?livrer le Koulosse, nous enfermons dans cette caverne, les Koalaks les plus agressifs et les plus fous. Le Koulosse est une cr?ature tranquille, mais on raconte qu\\\'il est devenu un peu fou, depuis que le grand Skeunk lui aurait vol? son Dofus. Un Dofus, vous y croyez vraiment ? En tout cas, je ne suis pas ici pour discuter, je dois servir mes ma?tresses et garder cette entr?e !');
INSERT INTO `npc_questions` VALUES (3121, '2744', '', '', '0', 'Tu m\\\'as vaincu... Mais j\\\'ai vraiment appr?ci?... ce combat... \\nC\\\'?tait terrible... La fa?on dont tu te d?hanches... avec un style... incroyable... \\nTu es vraiment trop... rapide... pour moi... \\nTu as vraiment... un style... de combat... particulier... \\nComme moi... tu es un original... \\nJ\\\'esp?re... que tu sais prendre... la vie du bon c?t?...');
INSERT INTO `npc_questions` VALUES (3122, '2745', '', '', '', 'Je suis enferm?... dans ma propre caverne... depuis des lustres... \\nComment... cela est-ce possible ? \\nJe n\\\'en sais... rien... \\nC\\\'est Skeunk... et ses fichues Sadidettes... Ils m\\\'on vol?... mon pr?cieux... mon dofus... le mien... celui que je ch?rissais tant... \\nHum... tu n\\\'es pas le premier ? venir ici... \\nOshar Marif... ? c?t? de moi... a lui aussi tent? de m\\\'affronter... mais... je l\\\'ai vaincu... et il est trop faible... pour repartir seul...');
INSERT INTO `npc_questions` VALUES (3123, '2746', '', '', '', 'J\\\'ai l\\\'impression que... tous les aventuriers en herbe... comme toi, viennent... pour me voler... ce dofus... que l\\\'on m\\\'a d?j? pris... \\nJe t\\\'appr?cie... ton esprit semble... sain, tu es calme... comme une Dragodinde... assom?e... gentil... comme un Piou ?cras?... g?n?reux... comme un Bouftou d?pec?... J\\\'ai bien envie... de te confier un de mes objets... f?tiches... mais tu devras... quitter mon antre... et repartir... au village... avant que d\\\'autres Koalaks ne reviennent...');
INSERT INTO `npc_questions` VALUES (3124, '2747', '', '', '0', 'Quant ? moi... ma place est ici... dans mon antre, avec mes feuilles de Kaliptus... et ces aventuriers... qui viennent me rencontrer... et passer de bon moments... Mais je m\\\'?gare... Tu ?tais s?rement venu... chercher... mon Dofus... Pauvre fou... Je t\\\'ai d?j? expliqu?... C\\\'est Skeunk....et ses Sadidettes... qui me l\\\'ont vol?... Ils se cachent... dans leur rep?re... pr?s de la vall?e... sombre... dangereuse... et malodorante... Mais...');
INSERT INTO `npc_questions` VALUES (3125, '2748', '', '', '', 'Mais... tu ne pourras... y acc?der sans clef... \\nJe sais... que Rigroulak poss?de... une clef... et qu\\\'il a toujours... voulu... que je lui pr?te... ma panoplie... \\nJe suis pr?t... ? t\\\'aider en t\\\'en donnant... une partie cette fois-ci... Je te donnerai... d\\\'autres ?l?ments... si tu me fais le plaisir... de revenir me voir... \\nVois-tu... je m\\\'ennuie un peu...ici...');
INSERT INTO `npc_questions` VALUES (3126, '2749;2750;2751;2752', '', '', '0', 'Mais... tu devras trouver toi-m?me... ce vieux Rigroulak... Je sais... qu\\\'il se cachait... il y a... bien longtemps... dans un cimeti?re... primitif... \\nIl a... toujours voulu... me ressembler... ?tre aussi... calme... tranquille... \\nIl sera... s?rement... tr?s heureux... de te rencontrer... si tu lui apportes... ma panoplie... \\nQuel objet... veux-tu que... je t\\\'offre ? \\n');
INSERT INTO `npc_questions` VALUES (3127, '2754;2753', '', '', '0', 'Enfin te voil? #1 ! \\nJe suis Oshar Marif, l\\\'illustre ?leveur de Dragodindes ! Les Dragodindes, c\\\'est ma grande passion ! \\nJe suis content que tu sois enfin arriv? ici pour me d?livrer, j\\\'ai perdu un terrible combat contre le Koulosse, et je suis tellement ?puis? que je ne peux pas repartir seul au village. J\\\'aurai besoin d\\\'aide...');
INSERT INTO `npc_questions` VALUES (3128, '', '', '', '0', 'La seule chose qui puisse m\\\'aider ? retrouver mes forces, c\\\'est une tisane au Kaliptus.\\nTu sembles surpris #1 ! Tout le monde sait pourtant qu\\\'une tisane au Kaliptus permet de regagner ses forces !\\nVoil? ce que je te propose, d?p?che-toi de me ramener 50 feuilles de Kaliptus et 50 fleurs de Kaliptus afin que je puisse me faire une bonne tisane, et je saurai te faire profiter de mon immense savoir sur les Dragodindes !');
INSERT INTO `npc_questions` VALUES (3129, '2755', '', '', '0', 'Mais c\\\'est parfait, tu as les 50 fleurs et feuilles de Kaliptus qu\\\'il me faut pour faire ma tisane !');
INSERT INTO `npc_questions` VALUES (3130, '2756', '', '', '0', 'Voil? je me sens d?j? beaucoup mieux d?sormais. Tu viens de me sauver la vie, et je compte bien te remercier en te faisant profiter de mes connaissances sur les Dragodindes. Je suis de loin, le meilleur ?leveur de Dragodindes, de tout le continent, il faut le savoir, je suis une personnalit? incontournable, mes ouvrages sont disponibles dans toutes les biblioth?ques s?rieuses, et tout le monde fait appel ? mon savoir !');
INSERT INTO `npc_questions` VALUES (3131, '2757', '', '', '0', 'Avant d\\\'essayer d\\\'?lever une Dragodinde, il faut que tu r?ussisses ? la capturer, et pour cela, il faut tenter de d?tourner son attention, de l\\\'hypnotiser et ensuite, il suffit d\\\'utiliser un filet de capture. Tu dois t\\\'en douter, la seule fa?on d\\\'hypnotiser une Dragodinde, c\\\'est de lui lancer un sortil?ge. Et je suis le seul ? pouvoir t\\\'apprendre ce sortil?ge. Je te dois bien cela, m?me si je parie que tu ne seras jamais un aussi bon ?leveur de Dragodindes que moi.');
INSERT INTO `npc_questions` VALUES (3132, '', '', '', '0', 'Voil?, tu sais d?sormais comment hypnotiser une Dragodinde, il ne te reste plus qu\\\'? acheter mon c?l?bre ouvrage sur l\\\'?levage des Dragodindes pour en savoir plus. \\nBon tu es bien gentil, mais maintenant que je suis en forme, je n\\\'ai plus besoin de toi, et le peuple a besoin de mes connaissances, alors laisse-moi tranquille.');
INSERT INTO `npc_questions` VALUES (3133, '2758', '', '', '0', 'Qu\\\'est-ce que tu me veux jeune insolent ! Je suis le terrible Rigroulak ! \\nJe suis certain que tu m\\\'as pris pour un autre de ces Ma?tres Koalaks, mais il n\\\'en n\\\'est rien, je n\\\'agresse plus les larves comme toi depuis longtemps. \\nAh, je vois, tu viens m\\\'apporter la panoplie du Koulosse ! \\nNon ! Comment ?a ! Jeune effront? !');
INSERT INTO `npc_questions` VALUES (3134, '1970', '', '', '0', 'Bon calme-toi, et je me calmerai... \\nJe parie que tu serais int?ress? par un clef du rep?re de Skeunk ! \\nCet odieux Ma?tre Eniripsa utilise ses quatre petites prot?g?es, de terribles Sadidettes pour contr?ler les Koalaks ! \\nJe ne sais pas quelle magie ces derni?res utilisent, mais elle est tr?s puissante, la quasi totalit? des Koalaks de nos montagnes sont devenus agressifs et esclaves de ces quatre soeurs qui v?n?rent ce terrible Skeunk !');
INSERT INTO `npc_questions` VALUES (3135, '2090', '', '', '0', 'Les Koalaks qui r?sistent ? cet ensorc?lement, vivent reclus au fond de grottes, ou sont enferm?s pour l\\\'?ternit? dans ce cimeti?re primitif, et seuls les ?tres capables de se ressusciter peuvent s\\\'en ?chapper... \\nMais passons, je suis enferm? ? vie dans cet endroit lugubre, et ma derni?re volont?, c\\\'est d\\\'avoir une apparence originale, je veux ressembler ? mon idole, le Koulosse, et pour cela, il me faudrait sa panoplie et je pense que tu pourrais m\\\'aider si tu me ramenais sa panoplie compl?te.');
INSERT INTO `npc_questions` VALUES (3136, '2761', '', '', '0', 'Mais rassure-toi en ?change, je te donnerai la clef pour rentrer dans le rep?re de Skeunk, j\\\'?tais gardien de l\\\'entr?e du rep?re pendant plusieurs ann?es avant d\\\'?tre exhil? ici pour tentative de rebellion. Haha, je vois que tu te demandes quel int?r?t tu aurais ? aller dans le rep?re de Skeunk ? Et bien c\\\'est simple, c\\\'est Skeunk en personne qui a d?rob? le Dofus du Koulosse, si tu vois o? je veux en venir... \\n \\nBon et cette panoplie du Koulosse o? est-elle ?');
INSERT INTO `npc_questions` VALUES (3137, '', '', '', '', 'Parfait, c\\\'est incroyable, mon r?ve se r?alise, je peux enfin avoir autant de prestance que le Koulosse ! \\nTu as bien m?rit? la clef que je viens de te donner, mais rappelle-toi, Skeunk est un ma?tre Eniripsa, il est tr?s dangereux, personne ? ma connaissance n\\\'a encore r?ussi ? le battre ! \\nPour arriver jusqu\\\'? Skeunk, il faudra que tu traverses une vall?e aride peupl?e de dangereux Koalaks, et que tu pr?sentes cette clef au gardien du rep?re de Skeunk... \\n');
INSERT INTO `npc_questions` VALUES (3138, '2762', '', '', '0', 'Halte-l? ! \\nPersonne n\\\'entre dans le repaire du ma?tre sans y avoir ?t? invit? ou sans avoir une clef. Je ne pense pas que le ma?tre Skeunk et ses disciples vous ai invit?, ils n\\\'invitent jamais les manants et les aventuriers de pacotille comme vous dans son repaire ! \\nMais peut-?tre avez-vous une clef ?');
INSERT INTO `npc_questions` VALUES (3139, '2763', '', '', '', 'Mais que fait un ?tre aussi abject que vous dans le repaire de notre grand ma?tre, le v?n?rable Skeunk ? \\nVous ne comptez tout de m?me pas franchir cette porte ? \\nSeuls les aventuriers qui re?oivent la permission des quatre soeurs disciples de Skeunk, ont le droit de franchir cette porte.');
INSERT INTO `npc_questions` VALUES (3140, '2764', '', '', '', 'Rosal t\\\'aurait-il fait manger des fleurs hallucinog?nes sombre idiot ? \\nComment veux-tu que je sache comment tu pourrais obtenir une permission, puisqu\\\'? chaque fois qu\\\'un hurluberlu dans ton genre me pose la question, je lui demande d\\\'aller demander une permission ? chacune des quatre soeurs, et ils ne reviennent jamais. Tous des pleutres.');
INSERT INTO `npc_questions` VALUES (3141, '', '', '', '', 'Je pense que si les quatre soeurs acceptent de vous pr?ter leur broche, c\\\'est qu\\\'elles vous font confiance et que vous m?ritez de franchir cette porte ! Allez donc leur emprunter leurs broches et revenez me voir si vous en avez le courage !');
INSERT INTO `npc_questions` VALUES (3142, '2765', '', 'PO=7935&PO=7936&PO=7937&PO=7938&PO=8073', '3139', 'Ah enfin te revoil? ! \\nBon tu as les quatre broches, j\\\'estime que c\\\'est une preuve suffisante de la confiance que les quatre soeurs te portent, et que tu n\\\'es pas le genre d\\\'aventurier qui oserait me berner. \\nPersonne ne cherche ? berner le grand Frivolak, personne non personne !');
INSERT INTO `npc_questions` VALUES (3143, '2766', '', '', '0', 'Je reconnais que tu sais te d?brouiller en combat, la prochaine fois, je ne te laisserai pas gagner, et tu comprendras ce dont est capable un ma?tre Eniripsa comme moi.');
INSERT INTO `npc_questions` VALUES (3144, '6628;2767', '', '', '0', 'Tu as de la chance d\\\'?tre arriv? jusqu\\\'ici, si les ?l?ments ne s\\\'?taient pas d?cha?n?s en ouvrant une br?che le long de la montagne, je n\\\'aurais pas eu ? subir ta mis?rable pr?sence. \\nBon, tu commences d?j? ? m\\\'insupporter, et je sais que tu es venu me voler mon Dofus, alors prends-le, et vas-t\\\'en, mais avant cela, rends-moi ma clef et les broches de mes disciples, je ne voudrais pas te donner une autre occasion de revenir pour ensuite devoir t\\\'humilier pour de bon.');
INSERT INTO `npc_questions` VALUES (3145, '', '', '', '', 'Ton jour viendra, Skeunk, notre mentor, te punira, tes fesses seront rouges comme... comme... comme... comme celles d\\\'un Piou Rouge !');
INSERT INTO `npc_questions` VALUES (3146, '', '', '', '', 'Que Rushu te br?le ce qu\\\'il te reste de conscience ! Comment as-tu os? t\\\'attaquer ? de si jeunes et fr?les Sadidettes ! \\nTu as m?me os? casser mon boomerang, je vais devoir attendre mon prochain anniversaire, pour que notre Ma?tre Skeunk, m\\\'en offre un nouveau ! \\nHors de ma vue, bourreau d\\\'enfant ! \\n');
INSERT INTO `npc_questions` VALUES (3147, '', '', '', '', 'J\\\'esp?re que tu es fier de toi, tu as march? sur mon boomerang, et il ne fonctionne plus correctement, il ne revient plus dans mes mains, mais dans celles de mes adversaires ! C\\\'est insupportable, tu n\\\'es qu\\\'un coupe-t?te de Pious, un martyriseur d\\\'Arakne, un guillotineur de Dragodinde !');
INSERT INTO `npc_questions` VALUES (3148, '2769', '', '', '', 'Ah enfin des excuses, ?a n\\\'est pas trop t?t ! \\nMais ?a ne suffit pas, il va me falloir reconstruire un autre boomerang, et je t\\\'ordonne de me ramener de quoi en fabriquer un autre ! \\nSi tu me ram?nes 10 boomerangs de Warko Marrons, 10 boomerangs de Koalaks Sanguins, 10 boomerangs de DoK Alako, et 10 boomerangs de Ma?tre Koalak, je devrais pouvoir me fabriquer un nouveau boomerang. \\nSi tu me ram?nes cela, je pourrai te r?compenser et surtout, implorer Skeunk pour qu\\\'il t\\\'?pargne, la prochaine fois qu\\\'il te rencontre !');
INSERT INTO `npc_questions` VALUES (3149, '', '', '', '', 'Enfin, tu en as mis du temps pour me trouver ces boomerangs ! Pendant ce temps-l?, j\\\'?tais presque totalement d?sarm?e, je n\\\'?tais plus la m?me !  \\nComme promis, je tiens ? te r?compenser tout de m?me, en t\\\'apprenant un de mes sortil?ges pr?f?r?s, il permet de lancer des boomerangs magiques. Bref... Je ne pense pas que tu sois assez intelligent pour comprendre tout cela, ?a doit te d?passer j\\\'imagine. Allez donne-moi tout ?a, ?coute bien ce que j\\\'ai ? t\\\'apprendre et ensuite hors de ma vue empaleur de Lenalds !');
INSERT INTO `npc_questions` VALUES (3150, '2772;2771', '[name]', '', '0', 'Bonjour #1 ! Je suis Liroye Merline la soeur de Fidji Merline, une des plus c?l?bres bricoleuses du continent. Nous sommes bricoleurs depuis plusieurs g?n?rations dans ma famille. Ma soeur et moi avons d?cid? de nous installer dans des cit?s rivales afin de faire profiter ? tous de notre savoir et de notre exp?rience. Que veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (3151, '4840', '', '', '', 'Je suis pr?te ? t\\\'apprendre comment bricoler, mais le roi Allister m\\\'a command? de nouveaux abreuvoirs pour ses montures et je suis d?bord?e ! \\nSi tu peux me ramener, 20 planches de bois de Fr?ne, et 15 planches de bois d\\\'Erable, je trouverai le temps de t\\\'apprendre les bases du m?tier. ');
INSERT INTO `npc_questions` VALUES (3152, '', '', '', '', 'C\\\'est un tr?s beau m?tier, mais peut-?tre trop ?prouvant pour une fillette comme toi. \\nJe plaisante ! Nous travaillons essentiellement avec les ?leveurs, en leur construisant de nombreuses machines qui leur ?vitent d\\\'avoir ? s\\\'occuper en permanence de leurs montures. Mais les montures sont assez brutales et nos machines finissent toujours par s\\\'user. Ce qui finalement arrange bien nos affaires !');
INSERT INTO `npc_questions` VALUES (3153, '4840', '', '', '', 'Voil? avec tout ce que je t\\\'ai appris, tu pourras commencer ? cr?er quelques objets pour les ?leveurs, mais il te faudra pour cela l\\\'outil adapt?, un marteau de bricoleur. Je n\\\'en n\\\'ai pas ? te vendre, tu devras trouver un forgeur de marteaux qui acceptera de t\\\'en fabriquer un !');
INSERT INTO `npc_questions` VALUES (3154, '2774;2775', '[name]', '', '0', 'Bonjour #1. Je suis Fidji Merline, la soeur de Liroye Merline, une des plus c?l?bres bricoleuses du continent, nous sommes bricoleurs depuis plusieurs g?n?rations dans ma famille, et ma soeur et moi avons d?cid? de nous installer dans des cit?s rivales afin de faire profiter ? tous de notre savoir et de notre exp?rience. Que veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (3155, '', '', '', '', 'Mais tais-toi, tu es dans la biblioth?que ici ! Esp?ce d\\\'ignorant, tu n\\\'as jamais appris ? respecter le silence dans une biblioth?que !');
INSERT INTO `npc_questions` VALUES (3156, '2776', '[name]', '', '0', 'Bonjour #1 . Je suis Nikos. Nikos Monote. Je suis le plus grand marin de tous les temps, j\\\'ai navigu? l? o? personne n\\\'a navigu?, j\\\'ai trouv? ce qu\\\'il y avait apr?s les oc?ans, j\\\'ai perc? le myst?re du Kralamoure g?ant. Bref je suis le meilleur.');
INSERT INTO `npc_questions` VALUES (3157, '2777', '[name]', '', '0', 'Et sais-tu pourquoi je suis le meilleur ? Non, de toute ?vidence, tu es b?te comme tes pieds #1 et tu ne sais rien, alors je vais t\\\'expliquer.\\nSi je suis le meilleur, c\\\'est parce que j\\\'ai construit le meilleur bateau du continent. Il est plus beau que les champs de fleurs de Rosal, il r?siste aux flammes de Rushu, et est plus rapide qu\\\'un Tofu d?plum?. C\\\'est avec ce bateau que j\\\'ai d?couvert l\\\'?le du Minotoror il y a bien longtemps.');
INSERT INTO `npc_questions` VALUES (3158, '2865', '', '', '0', 'Quelle malchance, la derni?re temp?te a malheureusement ab?m? la coque de mon magnifique bateau. Si tu me ram?nes 15698758? planches en bois de Fr?ne et 100 kamas, je pourrais cependant le r?parer et t\\\'y emmener gratuitement, je suis quelqu\\\'un de g?n?reux... \\nArr?te de r?ver, je plaisantais, je n\\\'ai pas envie d\\\'emmener un plouc comme toi sur mon bateau !');
INSERT INTO `npc_questions` VALUES (3159, '', '', '', '', 'Hors de ma vue Bouftou des Cavernes ! Comment as-tu os? ruiner ma somptueuse coiffure durant ce combat ? J\\\'esp?re que Silvosse te changera en Tournesol Sauvage ou en graine de Kirboule ? poils durs.');
INSERT INTO `npc_questions` VALUES (3160, '', '[name]', '', '', 'Bonjour #1. Je suis Klako, un des meilleurs chasseurs de Dragodindes de la r?gion. Mon ami Oshar Marif, le c?l?bre ?leveur, est parti s\\\'aventurer dans la caverne du Koulosse, mais n\\\'est jamais revenu, si tu pouvais t\\\'y rendre pour l\\\'aider ou pour me ramener sa d?pouille, je te serai reconnaissant. Mais seulement reconnaissant, ne t\\\'attends pas ? ce que je te fasse une ristourne sur mes filets pour autant !');
INSERT INTO `npc_questions` VALUES (3161, '4840', '', '', '', 'Approche, approche si tu n\\\'as pas peur ! Viens me voir en face, que je puisse lire la peur dans ton regard !');
INSERT INTO `npc_questions` VALUES (3162, '2780', '[name]', '', '0', 'Hey, Je suis certain que tu me connais #1 ! Je suis Krakotte, le plus grand chasseur de Craqueleurs de tous les temps ! Je les attrape, je les tords, je les casse, je les \\nd?sassemble, je les d?membre, je les brise, ?a fait \\\"crac\\\", ?a fait \\\"boum\\\" ?a... Je suis vraiment le meilleur chasseur de Craqueleurs comme tu peux le voir.');
INSERT INTO `npc_questions` VALUES (3163, '2781', '', '', '0', 'Je suis certain que tu aimerais savoir ce qu\\\'il se cache sur le sommet de cette montagne, derri?re ces marches ! Et bien c\\\'est simple, j\\\'y ai coinc? le plus gros Craqueleur que j\\\'ai r?ussi ? capturer et il ne peut plus redescendre maintenant qu\\\'il a grossi. Il est ?norme, monstrueux, terrifiant ! Il est tellement dangereux, que j\\\'ai bloqu? l\\\'acc?s ? cet escalier. Si jamais tu as une clef sur toi, je veux bien te laisser rentrer, tu r?aliseras que je ne te mentais pas, et tu auras s?rement tr?s peur, tu crieras comme une fillette en m\\\'appelant ? l\\\'aide, moi Krakotte, le terrible chasseur de Craqueleurs !');
INSERT INTO `npc_questions` VALUES (3164, '', '', '', '', 'Ram?ne-moi quelques ingr?dients que je puisse terminer ma potion.');
INSERT INTO `npc_questions` VALUES (3165, '', '', '', '', 'Qui me parle ? \\nApproche, je ne te vois pas !');
INSERT INTO `npc_questions` VALUES (3166, '2819;2811', '', '', '0', 'Ah, je sens que tu es encore perdu ! \\nComment puis-je t\\\'aider ?');
INSERT INTO `npc_questions` VALUES (3167, '', '', '', '', 'La derni?re fois que j\\\'ai vu le Ma?tre Corbac, il ?tait dans la salle 1 de la biblioth?que... \\n \\nLe Ma?tre Corbac est en 9720 !');
INSERT INTO `npc_questions` VALUES (3168, '', '', '', '', 'Le Ma?tre Corbac est bien sur la carte 9721');
INSERT INTO `npc_questions` VALUES (3169, '', '', '', '', 'Le Ma?tre Corbac est bien sur la carte 9719');
INSERT INTO `npc_questions` VALUES (3170, '', '', '', '', 'Pnj(774) et Message(3166)');
INSERT INTO `npc_questions` VALUES (3171, '', '', '', '', 'Diamantine ? C\\\'est toi ? Je ne te reconnais pas ! Approche s\\\'il te pla?t !');
INSERT INTO `npc_questions` VALUES (3172, '2794', '', '', '0', 'Houh Houh Kraboule bitouf ! Huhuharg. Kirboule kiki ?');
INSERT INTO `npc_questions` VALUES (3173, '2795', '', '', '0', 'Argh ! Bourdule krosse ! Gn? ?');
INSERT INTO `npc_questions` VALUES (3174, '2796', '', '', '', 'Que viens-tu faire dans mon Tofulailler ? Sais-tu que nous ?levons des Tofus depuis plusieurs g?n?rations ? Nous ?levons m?me des esp?ces uniques sur le continent !');
INSERT INTO `npc_questions` VALUES (3175, '2797', '', '', '0', 'Mais... J\\\'ai l\\\'impression de te conna?tre...\\nC\\\'est toi qui t\\\'occupe de nettoyer les ?trons dans le Tofulailler d\\\'habitude !\\nCa tombe bien, il y a beaucoup de boulot pour toi en ce moment ! Haha !');
INSERT INTO `npc_questions` VALUES (3176, '2798;2799;2800', '', '', '0', 'Hey beh mon fiu ! Commin qu\\\'?a va ? st\\\'heure ? \\nTi t\\\'es l? pour ramacher ch?s ?trons deul Tofu Royal comme t\\\'es l? nan ? \\nCr?vindiou tu m\\\'as pas l\\\'air fort robuste pourtant, eut\\\'guiboles sont aussi ?paisses que ch?s ?teules din ces camps. \\nArguette bin l? o? tu mettras tes pieds gamin, tu risquerais eud tomber din un traou ! \\nAlors,d\\\'o? qu\\\' c\\\'est qu\\\' tu va aller tra?ner eut gu?tres, makeud breu ?');
INSERT INTO `npc_questions` VALUES (3177, '2801', '', '', '0', 'Haha, tou n\\\'as aucoun? class? par rapport ? moi, tou es habill? comme oun Ploukoss?, et non pas comme oun Kouloss? ! Haha, qu? tou es laid ! Bouh ! Moi au moins, y? souis habill? en Moulou. Oui en Moulou, et pas en Bouftou comm? ta mama ! Bon tou veux rentrer dans cett? cavern? ? D\\\'anciens aventuriers y ?levaient leurs chienchiens, mais personn? n? sait c? qu\\\'il s\\\'est pass?, il est d?sormais infest? d? terribl?s cr?atoures, y? pens? qu\\\'elles t? toueront sans pein?. Mais attention Boufton, y? n\\\'irai pas t? chercher, m?m? si y? t? entends g?mir comme oun? fillett? !');
INSERT INTO `npc_questions` VALUES (3178, '2802', '', '', '0', 'Hey, bonjour aventurier, comment vas-tu ? Je m\\\'appelle Mawy, je suis n?e sur l\\\'?le des Wabbits, et le c?l?bre Farle Ingalsse est mon oncle. C\\\'est dingue tu ne trouves pas ? \\nJe parie que tu aimerais visiter ma grange ! Mais il te faudra une clef pour y rentrer, j\\\'ai perdu la mienne dans les champs la semaine derni?re, en fl?nant avec mon amant au milieu des bl?s... Avec un peu de chance, tu pourras la retrouver, ? moins qu\\\'une vilaine cr?ature des champs ne l\\\'ait d?j? prise. Si c\\\'est le cas, tu seras s?rement oblig? d\\\'aller les chasser pour la r?cup?rer !');
INSERT INTO `npc_questions` VALUES (3179, '2947;6602', '', '', '0', 'D?j?, avant de commencer, je t\\\'interdis de te moquer de moi ! Je n\\\'y suis pour rien si mes parents m\\\'ont donn? un nom de familier ! Quand j\\\'?tais petite, je passais mes journ?es ? jouer avec les Scarafeuilles, en leur arrachant les ailes ou en leur br?lant les antennes. On savait s\\\'amuser avec peu de choses de mon temps... Mes parents ont trouv? judicieux de me surnommer ainsi, et maintenant tout le monde me conna?t sous ce nom-l?... \\nBon vas-y, dis tout de suite que ma vie ne t\\\'int?resse pas ! Tout ce que tu cherches, c\\\'est rentrer dans cette caverne ? Et bien donne-moi la clef d\\\'abord, car moi aussi j\\\'aimerais y rentrer lorsque je serai plus forte !');
INSERT INTO `npc_questions` VALUES (3180, '', '', '', '', 'Excellente question ! Si j\\\'?tais toi, je me prom?nerai encore un peu dans cette biblioth?que, tu finiras peut-?tre par le rencontrer.');
INSERT INTO `npc_questions` VALUES (3181, '2810', '', '', '0', 'Et bien, il semblerait que le Ma?tre ait appr?ci? ta visite, il s\\\'ennuie beaucoup ces derniers temps, il a d?j? lu tous les ouvrages de cette biblioth?que, et jouer avec vous a d? le distraire quelques instants. Il m\\\'a demand? pour vous remercier, de vous offrir un de ses compagnons.');
INSERT INTO `npc_questions` VALUES (3182, '281', '', '', '0', 'Tu es dans une incroyable biblioth?que labyrinthique. Tu ne r?ussiras peut-?tre jamais ? sortir d\\\'ici vivant. \\nCette biblioth?que est compos?e de seize petites salles. Les seize salles forment une grande biblioth?que de forme carr?e. La seule fa?on de sortir de ces salles, consiste ? affronter le bon groupe de cr?atures. Chaque groupe de cr?atures t\\\'emm?nera dans une nouvelle salle. Il existe deux types de groupes de cr?atures diff?rents. Lorsque tu arriveras ? vaincre un des groupes de cr?atures, ces derni?res te r?compenseront en t\\\'emmenant dans la prochaine salle. Mais attention, ces cr?atures ont leurs petites habitudes et t\\\'emm?neront toujours dans la m?me direction. Il faudra donc affronter des groupes diff?rents, pour ne pas toujours progresser dans la m?me direction, et tourner en rond ind?finiment.');
INSERT INTO `npc_questions` VALUES (3183, '', '', '', '', 'Le Ma?tre Corbac se prom?ne dans les diff?rentes salles de cette biblioth?que. Heureusement pour toi, je t\\\'accompagnerai dans chaque salle, pour t\\\'indiquer o? se situe le Ma?tre Corbac. N\\\'h?site pas ? me le demander d?s que tu te sentiras perdu.');
INSERT INTO `npc_questions` VALUES (3184, '', '', '', '', 'La derni?re fois que j\\\'ai vu le Ma?tre Corbac, il ?tait dans la premi?re salle de la biblioth?que, ou dans la deuxi?me, ou dans la cinqui?me, ou peut-?tre m?me dans la sixi?me, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3185, '', '', '', '', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la premi?re salle, ou la deuxi?me, ou la cinqui?me, ou peut-?tre la sixi?me, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3186, '', '', '', '', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la troisi?me salle, ou la quatri?me, ou la septi?me, ou peut-?tre dans la huiti?me salle, je ne m\\\'en souviens plus.');
