INSERT INTO `npc_questions` VALUES (3188, '', '', '', '0', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la premi?re, ou la deuxi?me, ou la cinqui?me, ou dans la sixi?me salle, je ne m\\\'en souviens plus.');
