INSERT INTO `npc_questions` VALUES (3192, '', '', '', '', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la neuvi?me salle, ou la dixi?me, ou la treizi?me ou peut-?tre dans la quatorzi?me salle, je ne me souviens plus.');
INSERT INTO `npc_questions` VALUES (3193, '', '', '', '0', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la neuvi?me salle, ou la dixi?me, ou la treizi?me, ou peut-?tre dans la quatorzi?me salle, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3194, '', '', '', '0', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la onzi?me salle, ou la douzi?me, ou la quinzi?me, ou peut-?tre dans la seizi?me salle, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3195, '', '', '', '', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la onzi?me salle, ou la douzi?me, ou la quinzi?me, ou peut-?tre dans la seizi?me salle, je ne me souviens plus.');
