INSERT INTO `npc_questions` VALUES (3197, '', '', '', '', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la neuvi?me salle, ou la dixi?me, ou la treizi?me, ou peut-?tre dans la quatorzi?me salle, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3198, '', '', '', '', 'La derni?re fois que j\\\'ai crois? le Ma?tre Corbac, il se cachait dans la onzi?me salle, ou la douzi?me, ou la quinzi?me, ou peut-?tre dans la seizi?me salle, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3199, '', '', '', '', 'La derni?re fois que j\\\'ai rencontr? le Ma?tre Corbac, il se cachait dans la onzi?me salle, ou la douzi?me, ou la quinzi?me, ou peut-?tre dans la seizi?me salle, je ne m\\\'en souviens plus.');
INSERT INTO `npc_questions` VALUES (3200, '2829;661', '', '', '0', 'Es-tu certain de vouloir rentrer dans cette biblioth?que labyrinthique ? As-tu une invitation du Ma?tre Corbac ou une clef de sa biblioth?que ? J\\\'esp?re qu\\\'il est dispos? ? te recevoir, il n\\\'appr?cie gu?re ?tre d?rang? durant ses lectures.');
INSERT INTO `npc_questions` VALUES (3201, '2834;2830', '', '', '0', 'Mais que fais-tu ici mon brave ? \\nTu es dans le labyrinthe du Minotoror, tu vas, comme tant d\\\'autres, t\\\'y perdre, et ne compte pas sur moi pour venir te chercher ! \\nBon, que veux-tu ?');
INSERT INTO `npc_questions` VALUES (3202, '2831', '', '', '', 'C\\\'est un labyrinthe tr?s complexe, alors ?coute bien ce que je vais t\\\'expliquer !\\nTu dois te positionner sur une de ces dalles pour p?n?trer dans la salle correspondante. Le labyrinthe est compos? de 25 salles, qui forment un tr?s grand carr?. Vous ne pouvez pas ouvrir vous-m?me les portes de votre salle, vous ne pouvez ouvrir les portes que de la prochaine salle. Il faut donc que d\\\'autres aventuriers ouvrent les portes de votre propre salle. C\\\'est simple non ?');
INSERT INTO `npc_questions` VALUES (3203, '2846', '', '', '', 'Je sens que tu n\\\'as rien compris... Heureusement, tu as un plan pour te rep?rer, alors il faudra que tu l\\\'utilises, pour t\\\'organiser avec tes co?quipiers. Oui... J\\\'ai oubli? de te pr?venir, tu n\\\'as aucune chance, si tu y vas seul, plus vous serez nombreux, plus vous aurez de chance de progresser dans ce terrible labyrinthe. Une fois dans le labyrinthe, tu remarqueras que chaque porte et chaque levier dispose d\\\'un code de couleur. ');
INSERT INTO `npc_questions` VALUES (3204, '2844;2845', '', '', '0', 'Ah ! Je suis persuad? que tu veux rentrer dans ce labyrinthe et savoir quels tr?sors il renferme ! Je sais quelles cr?atures s\\\'y cachent, puisque je suis un des meilleurs arch?ologues de cette vaste ?le. Certains racontent que c\\\'est parce que je suis le seul, mais ce n\\\'est pas enti?rement vrai ! Si je suis le seul, c\\\'est parce que les autres se sont perdus dans ce labyrinthe tellement ils ?taient mauvais. Hahaha. Bon que veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (3205, '', '', '', '', 'C\\\'est tr?s simple, il te faut une clef pour rentrer ! Autrefois, j\\\'?tais le seul ? en poss?der une, mais les choses ont bien chang?, et je crois avoir perdu mon trousseau de clefs sur cette ?le, mais je ne sais pas o?. Une de ces satan?es cr?atures a s?rement  d? me le subtiliser pendant mon sommeil.');
INSERT INTO `npc_questions` VALUES (3206, '2835', '', '', '0', 'D\\\'accord, je vais t\\\'aider ? sortir d\\\'ici. Tu peux garder ta clef, elle te servira si jamais tu veux revenir. Mais avant de partir, je dois t\\\'attribuer un nouveau point de sauvegarde de position, la mal?diction du Minotoror semble t\\\'avoir fait oublier certaines choses. Alors... Laisse-moi choisir pour toi... Hum, la chambre des soeurs Korkule... Trop dangereuse... La fosse du Bimd\\\'Oule... Trop profonde... La vessie g?ante de Sarlack.... Trop humide... Bon alors tu prendras comme point de sauvegarde celui que tu avais avant ton arriv?e. Et estime-toi heureux, je t\\\'accompagne jusqu\\\'? la sortie.');
INSERT INTO `npc_questions` VALUES (3207, '2836', '', '', '0', 'Alors, tu es d?j? perdu ? Hahaha je m\\\'en doutais, lorsque je t\\\'ai vu arriver, je savais que tu ne serais pas capable de trouver ton chemin, dans ce d?dale de salles. Heureusement, je peux t\\\'aider ? revenir dans la salle des dalles si tu le d?sires.');
INSERT INTO `npc_questions` VALUES (3208, '2837;7640;2842', '', '', '0', 'Ah enfin, tu es presque arriv? au centre de ce labyrinthe. Tu en as mis du temps, j\\\'ai comme l\\\'impression que tu n\\\'as rien compris ? mes explications ! Bon, que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (3209, '661', '', '', '0', 'C\\\'est parfait, je vois que tu as trouv? les reliques n?cessaires pour pouvoir entrer dans la salle du Minotoror ! Allez, suis-moi, je vais essayer de t\\\'amener vivant dans cette fameuse salle, mais je vais te prendre ces deux reliques et la clef du Minotoror que je t\\\'ai donn?e, elles serviront ? payer ma retraite.');
INSERT INTO `npc_questions` VALUES (3210, '2841;6625;2840;2839', '', '', '0', 'Alors franchement, je suis impressionn?, tu as r?ussi ? vaincre cette terrible cr?ature ! Mais quelle chance ! Je n\\\'en reviens pas que quelqu\\\'un comme toi, capable de se perdre dans un labyrinthe aussi simple, puisse ?tre capable de terrasser un Minotoror. Cependant, je suis persuad? que tu ne pourrais pas tenir plus d\\\'une minute face au vrai ma?tre de ces lieux, ? savoir le Minotot ! Mais passons... \\nBon, que veux-tu que je fasse pour toi maintenant ?');
INSERT INTO `npc_questions` VALUES (3211, '', '', '', '', 'Ahaha, tu ne connais m?me pas le Minotot ! Mais je r?ve, d\\\'o? viens-tu ? Tu me fais penser ? tous ces demeur?s, qui n\\\'ont jamais vu la mer Kantile, ou n\\\'ont jamais gravi la colline Kolne. Rassure-moi, tu ne fais pas partie de ces gens-l? ? \\nBon hum... Ce n\\\'est pas grave... Et bien le Minotot est tout simplement le v?ritable ma?tre de ces lieux, le Minotoror n\\\'est que son fid?le disciple. L? o? le Minotoror emploie la force brute, le Minotot lui, utilise une magie d?vastatrice. Je suis le seul ? l\\\'avoir d?j? vaincu, c\\\'?tait il y a bien longtemps, donc je ne m\\\'en souviens plus du tout, et personne ne s\\\'en souvient en fait. Si tu veux toujours affronter cette cr?ature, il te faudra me ramener la clef de sa salle. A mon avis, seul un Bricoleur tr?s exp?riment? pourra t\\\'aider ? confectionner une telle clef.');
INSERT INTO `npc_questions` VALUES (3212, '', '', '', '', 'Le Minotoror est une terrible cr?ature l?gendaire, capable d\\\'?craser un Kirboule d?plum? entre ses sabots ! On raconte qu\\\'il mange des Tofus et qu\\\'il aime les jeter au visage de ses adversaires. J\\\'ai d?j? combattu le Minotoror lorsque j\\\'?tais plus jeune, mais je ne m\\\'en souviens plus, j\\\'?tais saoul et les seuls t?moins pr?sents ont disparu ? jamais dans ce labyrinthe. Si tu veux affronter cette terrible cr?ature, il faudra que tu retrouves des reliques, la relique du Mominotor et celle du D?minoboule. Ces deux cr?atures se prom?nent g?n?ralement dans les salles autour de celle-ci, mais attention, ils ont un caract?re encore plus d?plorable que le tien.');
INSERT INTO `npc_questions` VALUES (3213, '2839', '', '', '0', 'Je n\\\'en reviens pas, comment as-tu fait pour vaincre le seul, l\\\'unique, l\\\'horrible, le  redout?, le malodorant, le Minotot ! \\nBon, il est temps que tu sortes maintenant, je dois t\\\'avouer que tu es franchement quelqu\\\'un d\\\'ennuyeux. \\nSuis-moi, nous repartons ? l\\\'entr?e !');
INSERT INTO `npc_questions` VALUES (3214, '', '', '', '', 'Pour rentrer il te faudra une clef, et je suis le seul ? en poss?der, et je ne suis pas pr?t de la passer aux touristes, tu devras donc te d?brouiller seul ! Cependant, je pense qu\\\'un Bricoleur exp?riment? devrait pouvoir t\\\'aider ? confectionner une clef pour rentrer dans ce labyrinthe, en utilisant les ressources des cr?atures locales... \\nMais attention, une terrible mal?diction s?vit dans ce labyrinthe, tous ceux qui y entrent subissent des pertes de m?moire et oublient g?n?ralement leur point de sauvegarde. Une potion de rappel ne te permettra donc pas de sortir d\\\'ici, mais ne t\\\'en fais pas, je serai ton guide pendant tout ce voyage et si jamais tu te perds, je pourrai t\\\'aider ? retrouver la sortie !');
INSERT INTO `npc_questions` VALUES (3215, '7655;7656', '', '', '', 'Tu as l\\\'air perdu alors que c\\\'est pourtant tr?s simple ! J\\\'ai l\\\'impression d\\\'?tre encore tomb? sur un touriste abruti ! \\nIl faut que tu saches qu\\\'? n\\\'importe quel moment, je peux te ramener au point de d?part si tu te sens perdu. \\nEt surtout, un de tes co?quipier devra peut-?tre visiter le cimeti?re de ce donjon pour faire progresser le reste du groupe...');
INSERT INTO `npc_questions` VALUES (3216, '2847;2849', '', '', '0', 'Salut l\\\'aventurier, comment vas-tu ? Tu veux une Greuvette ? \\nNe r?ponds pas, en fait je m\\\'en fiche. \\nBon, je suis certain que tu cherches ? rentrer dans ce labyrinthe, mais je sens que tu n\\\'y connais rien ! Tu dois poss?der une clef pour esp?rer rentrer, et ne compte pas sur moi pour t\\\'en offrir une, en g?n?ral, je les vole aux aventuriers comme toi. \\n');
INSERT INTO `npc_questions` VALUES (3217, '2850', '', '', '', 'Je ne sais pas si tu connais le labyrinthe du Minotoror, tu as l\\\'air de n\\\'?tre jamais sorti de ton trou ! \\nBon, moi je ne suis jamais sorti de cette caverne, mais c\\\'est diff?rent. \\nEt bien en fait ce labyrinthe pr?sente la m?me particularit? que celui du Minotoror, il est maudit, et les aventuriers qui s\\\'y aventurent perdent g?n?ralement la m?moire et oublient l\\\'emplacement de leur point de sauvegarde, ils ne peuvent donc plus utiliser de potion de rappel pour sortir de ce labyrinthe. Heureusement pour toi mon goret, je serai ? tes c?t?s pour te guider dans ce labyrinthe ! J\\\'ai ?t? form? par le meilleur guide et arch?ologue de tout le continent, l\\\'illustre, le remarquable, le ventripotent, Lorkos ! Sa phrase pr?f?r?e lorsqu\\\'il emmenait les touristes dans le labyrinthe, c\\\'?tait  \\\"je connais le chemin !\\\". Hahaha, le pauvre fou, cet arch?ologue s\\\'est perdu dans son propre mus?e ! Mais passons... J\\\'ai comme l\\\'impression de parler dans le vide.');
INSERT INTO `npc_questions` VALUES (3218, '2851', '', '', '', 'Ah oui... Nous parlions de ce labyrinthe... \\nPour esp?rer rentrer dans la salle des dalles, il te faudra une clef sp?ciale, que tu devras peut-?tre confectionner ? partir des restes des Porkass. \\nEnsuite, une fois dans la salle des dalles, tu peux choisir ta salle de destination en choisissant la bonne dalle. Ensuite, ? toi de te d?brouiller pour arriver jusqu\\\'? la porte de l\\\'antre du Dragon Cochon ! Cependant, je dois te pr?venir, il te faudra une autre clef pour entrer dans cette antre, et tu ne la trouveras que sur leurs propri?taires, les terribles Porcos pr?sents dans ce labyrinthe.');
INSERT INTO `npc_questions` VALUES (3219, '2857', '', '', '', 'Je te d?conseille de t\\\'aventurer seul dans ce labyrinthe, mais attention, les portes de chaque salle se referment apr?s chaque passage, il est donc tr?s difficile de progresser en ?quipe en traversant les m?mes salles au m?me moment ! Je te conseille d\\\'utiliser ton plan pour progresser dans ce labyrinthe, sinon, tu risques vite de tourner en rond. En effet, certains aventuriers rapportent qu\\\'en allant toujours dans la m?me direction, ils finissent par retomber sur leurs pas. C\\\'est amusant non ? N\\\'oublie pas que le fonctionnement de ce labyrinthe est assez complexe, mais logique, si tu cherches ? progresser dans une direction, les portes se fermeront derri?re et devant toi, tu devras en permanence changer de direction. Si jamais tu te retrouves coinc?, n\\\'h?site pas ? appeler d\\\'autres aventuriers, ils peuvent ouvrir les portes de ta salle en s\\\'en rapprochant et en se dirigeant dans la bonne direction. Tu vois c\\\'est simple finalement !');
INSERT INTO `npc_questions` VALUES (3220, '2853;2852', '', '', '', 'Et bien que veux-tu, tu es d?j? perdu ? Tu cherches ta m?man !');
INSERT INTO `npc_questions` VALUES (3221, '2854', '', '', '', 'Bienvenue dans la salle des dalles ! Place-toi sur une de ces dalles et tu seras directement transport? dans une des salles de ce surprenant labyrinthe rempli de gros Porkass. Si je me fie ? ton odeur, tu ne devrais pas t\\\'y sentir trop d?pays? ! ');
INSERT INTO `npc_questions` VALUES (3222, '2855', '', '', '', 'Tu as peur petit cochon ? Ce n\\\'est pas grave, arr?te de pleurnicher, je vais te faire sortir d\\\'ici et te donner un nouveau point de sauvegarde car tu sembles avoir oubli? le tien. Alors voyons voir ce qu\\\'il me reste... L\\\'Occiput du Culbute ?a t\\\'int?resse ? Non je ne pense pas, tes fesses sont trop roses... Les ?curies Dogiasse ? Non trop effroyable... L\\\'antre  du Gorgor ? Non trop dangereux... Bon et bien, je vais choisir pour toi, ?a sera le Zaap du Ch?teau d\\\'Amakna, tu devrais t\\\'y sentir comme un poisson dans l\\\'eau !');
INSERT INTO `npc_questions` VALUES (3223, '2856', '', '', '', 'Te voil? enfin devant la porte de l\\\'antre du Dragon Cochon ! J\\\'esp?re que tu as r?ussi ? emprunter une clef aux Porcos ! \\nJe vais te demander de me donner tes deux clefs si tu veux rentrer, la clef de l\\\'Antre du Dragon Cochon, et la clef du Donjon du Dragon Cochon. \\nArr?te de prendre cet air ?tonn?, les touristes sont faits pour ?tre arnaqu?s, c\\\'est bien connu. Je te laisserai te promener dans son antre et je te retrouverai ? la sortie.');
INSERT INTO `npc_questions` VALUES (3224, '2858', '', '', '', 'Je pourrais te raconter ce que je sais ? propos du peuple Porco Rusto et du Dragon Cochon, j\\\'aime instruire les touristes un peu niais dans ton genre. Commen?ons par la l?gende, la vraie...\\nGoultard ?tait le nom de l\\\'?p?e l?gendaire de Garathgoul le c?l?bre Ecaflip. Garathgoul partit en qu?te du Dragon Cochon, car il savait que le Dragon Cochon recelait dans son antre le fameux Dofus Turquoise. Il trouva le Dragon Cochon et le combattit ? l\\\'aide de sa magie et de son ?p?e ! Garathgoul ferrailla pour sauver sa peau et son ?p?e Goultard fut asperg?e du sang odorant de Dragon Cochon. Ensuite, une ?tincelle jaillit lorsque l\\\'Ecaflip lan?a son sort f?tiche. L\\\'?tincelle tomba dans une flaque de boue, et on dit qu\\\'elle fit na?tre le peuple des Porcos Rustos. Voil? je t\\\'ai racont? tout ce que je savais ? propos de cette l?gende.');
INSERT INTO `npc_questions` VALUES (3225, '2859', '', '', '', 'Je peux ?galement te parler du peuple Porco Rusto ! Ces cr?atures sont frustes et born?es. Elles ne vivent que pour satisfaire leurs besoins primaires : b?ffrer, boire et se baigner dans la boue ! Que dire de plus ? Ah oui ! Ils se m?fient de tout ceux qui ne portent pas un groin au milieu du visage...\\n');
INSERT INTO `npc_questions` VALUES (3226, '2860', '', '', '', 'Quoi d\\\'autre ? Ah oui ! Les Porcos Rustos sont nomades. Ils bivouaquent ? la belle ?toile jusqu\\\'? ce qu\\\'ils s\\\'emparent des territoires qui leur conviennent. Parfois m?me, ils envahissent les campements des aventuriers lorsqu\\\'ils en ont envie, comme ce fut le cas au sud d\\\'Amakna...');
INSERT INTO `npc_questions` VALUES (3227, '2861', '', '', '', 'Malgr? les apparences, les Porcos sont des cr?atures tr?s pieuses et le culte du Dragon Cochon est tr?s r?pandu chez les Porcos ! Il y a aussi Ougah, une divinit? mineure ? t?te de Champ. Mon grand p?re disait toujours qu\\\'il ne croyait pas en Ougah, mais que parfois il lui faisait peur... H? bien moi, je vais t\\\'avouer que je crois en Ougah, mais la seule chose dont j\\\'ai peur, c\\\'est du Dragon Cochon ! Et pourtant Ougah est grand, mon fr?re !');
INSERT INTO `npc_questions` VALUES (3228, '2863', '', '', '', 'Comment cela, tu veux continuer cette discussion ? Je t\\\'ai d?j? consacr? suffisamment de temps ! Et je t\\\'ai dit tout ce que je savais ? propos des Porcos ! ');
INSERT INTO `npc_questions` VALUES (3229, '', '', '', '', 'Les Porcos sont des cr?atures tr?s pieuses. Le culte du Dragon Cochon est anim? par un Sorcier Shonouh dont personne ne conna?t l\\\'identit?. Tous les Porcos v?n?rent donc le Dragon Cochon comme leur dieu. Les Porcos consid?rent les Champ Champ comme des dieux mineurs, les porcs adorent les champignons, et les sangliers sont chercheurs de truffes. La divinit? embl?matique de ce culte se nomme Ougah le Champ Champ. Des aventuriers lui offrent aussi des offrandes dans un but qu\\\'eux seuls connaissent. Diff?rents autels sont dispers?s au quatre coin du continent pour le culte de ce dieu mineur. Mon grand p?re disait toujours qu\\\'il ne croyait pas en Ougah, mais que parfois il lui faisait peur, et bien moi, je vais t\\\'avouer que je crois en Ougah, mais la seule chose dont j\\\'ai peur, c\\\'est le Dragon Cochon. Et pourtant Ougah est grand mon fr?re !\\n');
INSERT INTO `npc_questions` VALUES (3230, '', '', '', '', 'Comment cela, tu veux continuer cette discussion ? Je t\\\'ai d?j? consacr? suffisamment de temps ! Et je t\\\'ai dit tout ce que je savais ? propos des Porcos.');
INSERT INTO `npc_questions` VALUES (3231, '', '', '', '', 'J\\\'ai regard? comment tu te bats, et franchement, je suis impressionn?.\\nJe ne plaisante pas, tu ne ressembles ? rien, tu t\\\'habilles mal, tu as un horrible accent... Tu me fais penser ? ces ploucs qui viennent du sud ! Heureusement, tu sais te battre, ?a compense beaucoup de choses...\\nBon je suppose que tu veux que je te sorte d\\\'ici ?');
INSERT INTO `npc_questions` VALUES (3232, '2866', '', '', '0', 'Et bien, tu en as mis du temps, je suis persuad? que tu as r?ussi ? te perdre sur cette ?le ! \\nSi tu veux partir, c\\\'est le moment o? jamais, je peux te ramener pour la modique somme de 200 Kamas, c\\\'est ? peine deux fois plus que pour l\\\'aller ! Ne fais-pas cette t?te-l?, nous devons naviguer ? contre-courant cette fois-ci, et la coque de mon navire va s\\\'user beaucoup plus !');
INSERT INTO `npc_questions` VALUES (3233, '', '', '', '', 'Haha, tou es presqu? aussi immeprezionnant qu? moi lorsqu? j\\\'avais toun? ?g? !');
INSERT INTO `npc_questions` VALUES (3234, '2874', '', '', '0', 'Yiiihhhaaaaa, des kamas, des kamas. \\nVous en voulez ?');
INSERT INTO `npc_questions` VALUES (3235, '', '', '', '', 'N\\\'abuse pas de ma g?n?rosit?. Tu es d?j? assez riche comme ?a.  \\nYiiiiihoouuuu houuu...');
INSERT INTO `npc_questions` VALUES (3236, '2876;2877;2878', '', '', '0', 'Bonjour, je m\\\'appelle Ziho, je suis le gardien de ce temple en ruines, je connais les moindres recoins de ce village, et de cette ?le. \\nJ\\\'ai l\\\'habitude de rencontrer des aventuriers comme toi, qui ne semblent pas prendre au s?rieux l\\\'histoire de ces lieux, et qui ne reviennent jamais... \\nLaisse-moi te faire profiter de mes conseils. Que veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (3237, '', '', '', '', 'Le gros trou que tu vois ici, m?ne dans ce que nous appelons commun?ment le Sanctuaire des Dragoeufs. Nous savons tr?s peu de choses sur cet endroit myst?rieux, il est habit? depuis des lustres par diff?rentes esp?ces de Dragoeufs. Beaucoup d\\\'aventuriers ont tent? d\\\'y p?n?trer et de percer les secret de ce sanctuaire, peu d\\\'entre eux sont revenus. Ce que nous savons, c\\\'est que ce sanctuaire a ?t? construit il y a tr?s longtemps par les disciples d\\\'Osamodas, afin de prot?ger et de faciliter la reproduction de ses Dragons.');
INSERT INTO `npc_questions` VALUES (3238, '', '', '', '', 'Le village dans lequel tu te trouves, n\\\'est autre que l\\\'ancien village d\\\'Amakna. \\nSes habitants y v?curent tranquillement pendant de longues ann?es, jusqu\\\'? ce que de myst?rieux Dragoeufs viennent d?vaster ce village en d?vorant et br?lant la majorit? de ses habitants. Ceux qui ont surv?cu, se sont r?fugi?s il y a bien longtemps dans ce que nous appelons maintenant le ch?teau d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (3239, '', '', '', '', 'Apr?s plusieurs ann?es pass?es dans l\\\'enceinte du ch?teau, les rescap?s de ce village, aid?s par des Astrubiens, ont d?cid? de reconstruire leur ancien village, mais ? proximit? du ch?teau. C\\\'est le village d\\\'Amakna que nous connaissons tous aujourd\\\'hui. \\nDe nos jours, seuls les aventuriers en qu?te de sensations fortes, et les ?quarrisseurs de Dragoeufs s\\\'aventurent dans ce village d?vast?. On y rencontre parfois quelques Roublards et brigands, qui viennent piller ce qui a ?t? abandonn? dans les maisons, ou tout simplement pour trouver refuge, dans un endroit o? peu de personnes n\\\'osent s\\\'aventurer...');
INSERT INTO `npc_questions` VALUES (3240, '', '', '', '', 'Les grands Sages de ce monde rapportent que cette invasion de Dragoeufs, n\\\'?tait qu\\\'une punition divine, les Dragoeufs ?taient emprisonn?s dans le sanctuaire de cette ?le, et Osamodas n\\\'a fait que les lib?rer. Mais les habitants du village avaient tous oubli? ce que leur anc?tres avaient fait aux Dragoeufs, et que leurs propres habitations avaient ?t? b?ties sur le Sanctuaire des Dragoeufs, afin d\\\'en cacher l\\\'existence, comme s\\\'ils avaient voulu cacher au Dieu Osamodas, leurs m?faits, et leur folie.');
INSERT INTO `npc_questions` VALUES (3241, '', '', '', '', 'Lorsque Osamodas a d?cid? de lib?rer les Dragoeufs, ils ont refait surface et ont attaqu? le village et ses habitants, ils sortaient directement du sol, ?ventrant les parquets des maisons et brisant les dalles les plus solides. Cette attaque par surprise n\\\'a laiss? quasiment aucune chance aux habitants. Ici, la nature a d?sormais repris ses droits, ce village n\\\'est plus que l\\\'ombre de lui-m?me, mais ses ruines r?sistent aux affres du temps, comme si Osamodas avait voulu graver un message, un avertissement, dans nos m?moires et dans celles des g?n?rations futures. \\n');
INSERT INTO `npc_questions` VALUES (3242, '', '', '', '', 'Ces disciples ?taient les habitants m?me de ce village. Ils ont voulu reproduire ? outrance les Dragons du dieu Osamodas qu\\\'ils avaient r?ussi ? apprivoiser. Mais leurs intentions n\\\'?taient pas louables, chacun sait que ce sont les Dragons qui sont ? l\\\'origine des Dofus. Ainsi, ils n\\\'ont cess?, pendant plusieurs g?n?rations, de reproduire inlassablement les Dragons, afin d\\\'obtenir d\\\'autres Dofus. Ils n\\\'auraient pas d? oublier que ces oeufs ?taient maudits et que les Dragons ne sont pas des cr?atures apprivoisables comme les autres...');
INSERT INTO `npc_questions` VALUES (3243, '', '', '', '', 'En effet, ils ont fini par perdre totalement le contr?le de cet ?levage. Ils n\\\'arrivaient plus ? apprivoiser les nouvelles g?n?rations de Dragons, Dragoeufs, et Dragoss qu\\\'ils avaient cr??es. On ne change pas la nature de cr?atures comme les Dragons ! On ne peut pas r?ellement les apprivoiser... Ces cr?atures concentrent bien trop de puissance et de magie pour ?tre contr?l?es par des mortels. A la suite de plusieurs incidents, ces apprentis ?leveurs de Dragons ont d?cid? d\\\'abandonner leurs croisements et leurs recherches de Dofus. Ils ont donc referm? ? jamais ce sanctuaire, emprisonnant ? jamais tous leurs occupants.');
INSERT INTO `npc_questions` VALUES (3244, '', '', '', '', 'Ta-ta-ta-t\\\'as envie d\\\'te faire plein d\\\'fric? Rien d\\\'t.. t\\\'... t\\\'... d\\\'tel que d\\\'te faire artisan! Et pour t\\\'faire conna?tre, maint\\\'nant, t\\\'as des ru... ru... runes!');
INSERT INTO `npc_questions` VALUES (3245, '', '', '', '', 'B.. B.. Ben, tu vois, une rune, c\\\'t\\\'un truc vachement mystique et super puissant, mais j\\\'ai pas t... t... trop d\\\'infos dessus non plus. J\\\'sais juste qu.. qu.. que d?s... d?s... d?s que tu l\\\'utilises, t\\\'es, comme qui dirait, publi? dans l\\\'aura du monde, t... t... tu vois, un truc du genre. Et n\\\'... n\\\'... n\\\'importe qui peut, comme qui dirait, te remarquer en tant qu\\\'artisan! Et ?a y\\\'est! T\\\'... T\\\'... T\\\'es connu, reconnu, et ? toi les Kamas!');
INSERT INTO `npc_questions` VALUES (3246, '', '', '', '', 'T... T... T\\\'es un dur ? la comprenette, toi, non? Bon, j\\\'vais t\\\'expliquer en clair: t\\\'utilises une rune de r?f?rencement, t\\\'?quipes ton outil d\\\'artisan, et hop! T\\\'es dans la li...li...liste. T\\\'enl?ves ton outil, et hop, t\\\'y es plus. Quand t\\\'es dans la li...li...liste, tout l\\\'monde peut te voir en tant que tel. Ca y\\\'est, t\\\'as pig');
INSERT INTO `npc_questions` VALUES (3247, '', '', '', '', 'Priv?s de lumi?re et de nourriture, les Dragons, Dragoeufs et Dragoss enferm?s dans le sanctuaire, rentr?rent dans une profonde hibernation pendant plusieurs centaines d\\\'ann?es. Mais le dieu Osamodas n\\\'avait pas oubli? cet affront, cette trahison de la part de ses propres sujets. Pour se venger, il r?veilla les cr?atures prisonni?res de ce sanctuaire, qui ne tard?rent pas ? sortir et ? d?vaster ce village et ses habitants.');
INSERT INTO `npc_questions` VALUES (3248, '', '', '', '', 'Aujourd\\\'hui, tout est fini, les Dragoeufs se sont habitu?s ? la lumi?re naturelle de l\\\'ext?rieur et peuplent les ruines de cette ?le. Les autres Dragons vivent encore dans ce sanctuaire et semblent se nourrir des aventuriers qui s\\\'y risquent... \\nSi tu d?sires t\\\'y aventurer je peux t\\\'aider, je suis en quelque sorte, le gardien des lieux...');
INSERT INTO `npc_questions` VALUES (3249, '', '', '', '', 'Il te faudra de toute ?vidence une clef pour rentrer dans ce sanctuaire. La seule fa?on d\\\'en obtenir une, c\\\'est de faire appel ? un Bricoleur exp?riment?. Pour fabriquer cette fameuse clef, il lui faudra retrouver des fragments de coquille que seuls quatre gardiens Dragoeufs poss?dent. Je ne sais pas o? tu peux trouver ces gardiens Dragoeufs, on peut parfois les voir sortir des habitations abandonn?es une fois la nuit tomb?e. Si j\\\'?tais toi, j\\\'irais explorer les diff?rentes maisons de ce village.');
INSERT INTO `npc_questions` VALUES (3250, '', '', '', '', 'Une fois que tu seras rentr? dans ce Sanctuaire des Dragoeufs, tu pourras mesurer la folie qui anima jadis ces disciples d\\\'Osamodas ! L\\\'int?rieur de ce sanctuaire est ? l\\\'image de ses occupants, grandiose, terrifiant, myst?rieux, mais mortel... \\nAvant que tu ne d?cides de partir ? la recherche de ces fragments de coquille, je dois t\\\'avertir d\\\'une chose, il existe dans ce sanctuaire, une porte magique, qui m?ne ? la chambre cr??e pour la reproduction des Dragons...');
INSERT INTO `npc_questions` VALUES (3251, '', '', '', '', 'Cette chambre est prot?g?e, seuls quatre des plus vaillants Dragoss de ce sanctuaire ont re?u le pouvoir d\\\'utiliser cette porte magique. Ils portent en eux un objet, une relique, ou un artefact qui leur permet de franchir cette porte sans que les Dragons eux-m?mes ne les transportent dans leur chambre. Si tu trouves ces objets, tu devrais pouvoir acc?der ? cette fameuse chambre ! Mais il te faudra TOUS les trouver, les quatre vaillants Dragoss ne peuvent franchir la porte qu\\\'ensemble, car le pouvoir de ces objets ne semble s\\\'exprimer que lorsqu\\\'ils sont r?unis.');
INSERT INTO `npc_questions` VALUES (3252, '', '', '', '', 'Je ne sais pas ce que tu peux esp?rer trouver dans ce sanctuaire et cette chambre... si ce n\\\'est une mort certaine ! Et aussi la preuve que la qu?te des Dofus n\\\'est peut-?tre pas ? la port?e de mortels comme nous.');
INSERT INTO `npc_questions` VALUES (3253, '', '', '', '', 'Je t\\\'ai suivi discr?tement durant ton p?riple, et je suis impressionn? par ta bravoure. J\\\'esp?re que ce que tu as vu ici, t\\\'aidera ? comprendre ? quel point la qu?te des Dofus est une qu?te vaine, qui peut mener ? sa perte, un village entier...\\nIl est temps pour toi de quitter cet endroit, Osamodas ne saurait appr?cier ce que tu as fait ? ses prot?g?s !');
INSERT INTO `npc_questions` VALUES (3254, '', '', '', '', 'Pfiouuuuuuu... Fait vraiment trop chaud ici... \\nT\\\'en as jamais marre d\\\'tout ce soleil, c\\\'te chaleur ? \\n \\n*transpire ? grosses gouttes* \\n \\nHum j\\\'ai bien envie de r\\\'tourner sur mon ?le moi...');
INSERT INTO `npc_questions` VALUES (3255, '', '', '', '', 'Tiens, tu veux d\\\'j? r\\\'partir ?');
INSERT INTO `npc_questions` VALUES (3257, '', '', '', '', 'Bah en fait c\\\'est pas vraiment une ?le... Enfin si mais non... On dirait plut?t une esp?ce d\\\'gla?on g?ant qui flotte sur l\\\'eau. \\nD\\\'ailleurs il bouge le gla?on, l\\\'capitaine dit qu\\\'on n\\\'pourra bient?t plus l\\\'atteindre... \\n \\n*soupire* \\n \\nQuel g?chis... C\\\'t\\\'un endroit magique... Y a des tr?sors par terre, aux pieds d\\\'Abraknydes bizarres... L\\\'paradis des Enutrofs...');
INSERT INTO `npc_questions` VALUES (3258, '2901;2898', '', '', '', 'Bah oui des tr?sors par terre, le soleil t\\\'a fait fondre la cervelle ou quoi ? \\nFaut arr?ter de faire r?p?ter ce que disent les gens comme ?a, ?a devient tr?s vite aga?ant tu sais... \\n \\nBon je retourne sur mon ?le tant qu\\\'elle est l?, d?cide-toi, je t\\\'emm?ne ou pas ? \\n');
INSERT INTO `npc_questions` VALUES (3259, '', '', '', '', 'Bien, j\\\'esp?re que tu as un bon cache-oreilles !\\nEuh au fait...\\nJe pose la question juste pour la forme, mais tu n\\\'es pas un mioche d?guis? en adulte n\\\'est-ce pas ?\\nTes parents veulent bien que tu viennes ?\\nParce que le dernier moutard que j\\\'ai emmen?, il est pas r\\\'venu...\\nA tous les coups il a pas voulu quitter mon ?le, mais sa m?re elle me poursuit partout depuis...\\n\\n*regarde par dessus son ?paule*\\n\\nBon, hum... D?p?ches-toi, moi j\\\' me sauve ! ');
INSERT INTO `npc_questions` VALUES (3260, '', '', '', '', 'Bah c\\\'est pas l\\\'appel de l\\\'aventure qui t\\\'?touffe toi. \\nAllez file, tu m\\\'donnes chaud.');
INSERT INTO `npc_questions` VALUES (3261, '', '', '', '', 'Hum... Tu m\\\'as l\\\'air d\\\'une belle chochotte toi... \\nBon t\\\'as de la chance, je dois retourner ? Madrestam. \\nAllez monte.');
INSERT INTO `npc_questions` VALUES (3262, '', '', '', '', 'Ouf tu m\\\'as fait peur. \\nJe n\\\'sais pas ce qu\\\'ils ont tous, mais j\\\'ai d\\\'j? fait r\\\'partir une vingtaine de Iops pleurnichards qui promettaient de n\\\'plus jamais ?tre m?chants d\\\'toute leur vie. \\nToi au moins t\\\'as des... tripes ! \\nAllez on s\\\'revoit plus tard !');
INSERT INTO `npc_questions` VALUES (3263, '', '', '', '', 'Le?on n?1 : \\nUne grande personne comme toi devrait savoir qu\\\'on ne ment pas ? une dame comme moi n\\\'est-ce pas ? \\nAlors si tu sais o? est mon petit gar?on tu me le dis tout de suite... ');
INSERT INTO `npc_questions` VALUES (3264, '', '', '', '', 'Oui, avant j\\\'?tais ma?tresse... d\\\'?cole.  \\nIl y a des habitudes qui restent... \\nTu sais o? est mon fils ?');
INSERT INTO `npc_questions` VALUES (3265, '', '', '', '', 'Tu es bien comme les autres toi... \\nTant pis je trouverai seule !');
INSERT INTO `npc_questions` VALUES (3266, '', '', '', '', 'Mon petit bout de chou, mon petit fiston ? moi, il a disparu depuis une semaine... \\nIl a suivi un vieil Enutrof bizarre sur une ?le encore plus bizarre au nord... \\nIl m\\\'en a ramen? cette superbe cape, pour sa maman...  \\n \\n*renifle* \\n \\nEt puis il est reparti avec ce... Hector Nowel, et plus de nouvelles ! \\nEt ce vieillard s?nile me fuit depuis ce jour l?. \\nIl tra?ne ? Madrestam en ce moment, si je le trouve... \\n \\n*montre une vieille pelle caboss?e* \\n \\nJe lui apprends la le?on num?ro 2... \\n \\n');
INSERT INTO `npc_questions` VALUES (3267, '', '', '', '', 'Oui bien s?r... Si jamais tu trouves mon fiston, dis-lui que sa maman le cherche !');
INSERT INTO `npc_questions` VALUES (3268, '', '', '', '', 'Bonjour testeur de l\\\'extr?me ! \\nJe suis persuad? que tu aimerais tester les anciens et les nouveaux m?tiers !');
INSERT INTO `npc_questions` VALUES (3269, '', '', '', '', 'Quel m?tier veux-tu apprendre ?');
INSERT INTO `npc_questions` VALUES (3270, '', '', '', '', 'Quel m?tier veux-tu apprendre ?');
INSERT INTO `npc_questions` VALUES (3271, '2926', '', '', '0', 'Bonjour je suis Josette. La c?l?bre Josette Taplane, enlev?e ? mes parents et transform?e en Abraknyde vers l\\\'?ge de 5 mois, puis ?lev?e par une famille de Tronknydes de la clairi?re de Liroye Merline. Je d?fends depuis ma plus tendre enfance, la cause des honn?tes gens transform?s en Abraknydes et qui l\\\'assument, et je cherche ? retrouver mes racines. Ca te pose un probl?me ? Tu n\\\'aimes pas les Abraknydes ? Bon... \\n \\nQue veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (3272, '6605', '', '', '0', 'Je suis la gardienne de ce donjon, qui renferme une partie des habitants de cette for?t. Je pourrais  t\\\'accompagner si tu le d?sires, mais je resterai loin derri?re, je ne cours pas aussi vite que toi, mes racines sont us?es. \\nSi tu veux rentrer, donne-moi la clef de ce donjon.');
INSERT INTO `npc_questions` VALUES (3273, '', '', '', '', 'Allez, approche, et essaye de ne pas tomber b?tement dans un trou, regarde o? tu poses les pieds ! Sur Chaque dalle, il y a un num?ro qui t\\\'indique le nombre de dalles pi?g?es sur les 8 dalles adjacentes. Par d?duction, tu dois donc facilement pouvoir deviner quelles sont les dalles pi?g?es et quelles sont les dalles qui t\\\'am?neront de l\\\'autre c?t');
INSERT INTO `npc_questions` VALUES (3274, '2928', '', '', '', 'Ah enfin, tu es arriv? jusqu\\\'ici, je commen?ais ? prendre racine ! \\nAllez suis-moi.');
INSERT INTO `npc_questions` VALUES (3275, '2929', '', '', '0', 'Bravo, tu viens de vaincre l\\\'Abraknyde Ancestral alors qu\\\'il ?tait ? peine r?veill?. Je suis certain que tu t\\\'en vanteras dans tout Amakna d?s ce soir... Heureusement, la mal?diction de la for?t des Abraknydes semble t\\\'avoir ?pargn?. Je n\\\'aurai pas ? te subir plus longtemps !');
INSERT INTO `npc_questions` VALUES (3276, '2930', '', '', '0', 'Encore un petit effort et tu pourras peut-?tre acc?der ? la prochaine salle avec toutes tes dents !');
INSERT INTO `npc_questions` VALUES (3277, '', '', '', '', 'Cette somptueuse clef peut t\\\'amener directement l? o? se cache le Ch?ne Mou, ou presque, il te faudra peut-?tre ?liminer quelques ind?sirables entre temps. Es-tu certain de vouloir y aller ?');
INSERT INTO `npc_questions` VALUES (3278, '2932', '', '', '0', 'Je suis subjugu?e, tu viens de vaincre le Ch?ne Mou, cette cr?ature mythique, cet arbre vivant qui a travers? les temp?tes sans se d?raciner, et les automnes sans perdre ses feuilles.\\nComment un mis?rable petit mortel impuissant comme toi a pu terrasser une cr?ature aussi imposante et puissante ?\\nLa nature est d?cid?ment pleine de surprises.');
INSERT INTO `npc_questions` VALUES (3279, '2946', '', '', '0', 'J\\\'ai l\\\'impression que tu as ?t? mordu par un Abraknyde... Je pense que tu risques de subir la terrible mal?diction de cette for?t. J\\\'ai bien peur que d\\\'une minute ? l\\\'autre, tu ne commences ? te transformer, tu devrais te d?p?cher de sortir de ce donjon tant qu\\\'il en est encore temps, la sortie est devant toi.');
INSERT INTO `npc_questions` VALUES (3280, '2933', '', '', '', 'Silvosse semble ?tre avec toi, tu gu?ris ? vue d\\\'oeil, la mal?diction te quitte. \\nDommage, je te trouvais tr?s bien en Abraknyde ! \\n \\nSi j\\\'?tais toi, je ne perdrais pas mon temps et j\\\'essaierai de me sauver de ce donjon en courant pendant qu\\\'il en est encore temps.');
INSERT INTO `npc_questions` VALUES (3281, '195', '', '', '0', 'Bonjour, je suis Igloute, le c?l?bre capitaine ! Je suis persuad? que tu as d?j? entendu parler de moi. \\nAvant d\\\'?tre capitaine de navire sans navire, j\\\'?tais cuisinier. \\nOui cuisinier, je pr?parais le poisson comme personne, je prenais les poissons vivants, oui vivants monsieur ! \\nEnsuite, je les ?crasais vivants, et je rajoutais du sel, et des herbes magiques, elles aussi encore vivantes ! \\nEt mon poisson permettait ? ceux qui le mangeaient, de respirer sous l\\\'eau s\\\'ils nageaient ? l\\\'envers. Comment ?a tu ne me crois-pas ! Mais si je t\\\'assure, tout ce que je dis est v?ridique.');
INSERT INTO `npc_questions` VALUES (3282, '293', '', '', '0', 'Comme je te l\\\'ai expliqu?, avant d\\\'?tre cuisinier pour Allister, je naviguais sur le plus beau et gros bateau de tout l\\\'oc?an. Tu vois celui de Nikos Monote ? Et bien le mien ?tait douze fois plus grand que le sien. Ca t\\\'en bouche un coin mon gars, n\\\'est-ce pas ? \\nMalheureusement, il ?tait trop grand pour le port d\\\'Amakna, il ne rentrait m?me pas. Je ne sais pas si tu r?alises ce que je te raconte. \\nIl ?tait tellement grand, qu\\\'il s\\\'est ?chou? dans cette calanque lorsque je suis arriv? sur l\\\'?le de Moon.  \\nEt oui, il ?tait tellement grand, qu\\\'il touchait des deux c?t?s et rejoignait l\\\'?le de Moon et cette calanque !');
INSERT INTO `npc_questions` VALUES (3283, '293', '', '', '0', 'Je ne plaisante pas, tu aurais d? le voir de tes propres yeux pour r?aliser ? quel point c\\\'?tait impressionnant. \\nJ\\\'en ai profit? pour utiliser mon bateau comme un pont, et faire payer les touristes pour aller jusqu\\\'? l\\\'ile de Moon sans passer par ce stupide canon. \\nJe suis devenu tellement riche gr?ce ? cette id?e brillante, que j\\\'ai financ? la construction du pont de Pandala, et j\\\'ai financ? la reconstruction de la muraille de Bonta, pour le plaisir. \\nPlus tard, mon bateau a disparu, aspir? au fond de la mer d\\\'Asse, par le Kralamoure G?ant de l\\\'?le de Moon.');
INSERT INTO `npc_questions` VALUES (3284, '293', '', '', '0', 'Le Kralamoure m\\\'a aval? mais s\\\'est ?touff? avec mes objets en mousse. Il m\\\'a recrach? 2 mois plus tard, j\\\'?tais encore en vie, j\\\'avais mang? du poisson pr?dig?r? dans son estomac pour survivre. \\nTu ne me croiras peut-?tre pas, mais c\\\'?tait tr?s bon. C\\\'est l? que j\\\'ai eu de nouvelles id?es de recettes ? base de poisson pr?dig?r? et ferment? ? l\\\'huile de Koode. Il ne me manque que les clients et je pourrais ouvrir une nouvelle franchise. \\nMais je m\\\'?gare...');
INSERT INTO `npc_questions` VALUES (3285, '2944', '', '', '0', 'J\\\'ai ensuite d?couvert qu\\\'il y avait un ch?teau de sable assez ?trange dans cette calanque, je m\\\'y suis aventur?, tel un brave homme en qu?te de r?demption, ou de digestion, je ne me souviens plus exactement. \\nJ\\\'y ai pourfendu les cr?atures les plus abjectes qui hantent les fonds marins, m?me elles, n\\\'auraient pas peur en te voyant. \\nC\\\'est l? que j\\\'ai r?cup?r? mes objets en mousse, en d?pe?ant une ?norme mousse des mers, une ?ponge marine, l\\\'illustre Mob l\\\'Eponge.');
INSERT INTO `npc_questions` VALUES (3286, '2944', '', '', '0', 'Alors je suis certain que tu te demandes comment j\\\'ai pu ?touffer le Kralamoure G?ant de l\\\'?le de Moon avec mes objets en mousse alors que je ne les ai obtenus qu\\\'apr?s avoir d?pec? Mob l\\\'Eponge !  \\nC\\\'est bien gamin, je vois que tu suis ce que je raconte. \\nEn fait c\\\'est simple, il y a bien longtemps, avant que je n\\\'invente les Zaaps, j\\\'avais con?u une machine ? voyager dans le temps. \\nEt oui je l\\\'ai construite lorsque je me suis ?chou? sur la c?l?bre ?le d\\\'Otoma');
INSERT INTO `npc_questions` VALUES (3287, '2944', '', '', '0', 'Comment cela, tu ne connais pas cette ?le ? Je l\\\'appelle comme cela, car c\\\'est sur cette ?le qu\\\'il ?tudie toutes les cr?atures de ce monde. \\nJe suis rest? coinc? l?-bas pendant plusieurs ann?es, et au lieu de me la couler douce ? siroter des cocktails de jus de Kokoko au bord de la plage, j\\\'ai d?cid? de mettre ? profit mon extraordinaire talent de bricoleur inventeur. \\nJe ne t\\\'avais pas encore expliqu? que j\\\'?tais ?galement bricoleur et inventeur de tout un tas de choses, plus utiles les unes que les autres ?');
INSERT INTO `npc_questions` VALUES (3288, '2944', '', '', '0', 'O? en ?tais-je... \\nAh oui voil?, j\\\'?tais donc coinc? sur cette ?le, et Otoma? ratait r?guli?rement les tr?panations et les transplantations de cervelles qu\\\'il effectuait sur ses monstres. \\nSais-tu qu\\\'un cerveau de Iop tient dans une t?te d\\\'Arakne par exemple ? \\nEnfin bref, pour l\\\'aider dans sa noble t?che, sa qu?te du savoir, j\\\'ai construit une machine ? remonter le temps, qui lui permettait de retenter certaines exp?riences.');
INSERT INTO `npc_questions` VALUES (3289, '2944', '', '', '0', 'Je me suis donc servi de cette machine pour voyager dans le temps, et affronter Mob l\\\'Eponge pour lui subtiliser sa mousse. \\nVoil? pour la petite histoire. \\nJe t\\\'ai d?j? racont? que j\\\'?tais le premier ? avoir pos? le pied sur l\\\'?le de Moon ? \\nC\\\'?tait un petit pas pour moi, mais un gr... \\nAh tu veux rentrer dans le donjon ensabl? ? Il fallait le dire tout de suite idiot, j\\\'ai utilis? beaucoup trop de salive ? cause de toi... \\nSi tu as la clef de ce donjon, je t\\\'y fais rentrer tout de suite, je te raconterai la suite de mes histoires lorsque tu viendras manger du poisson dans mon restaurant, celui qui est cach? dans les fonds marins, sous Sufokia.');
INSERT INTO `npc_questions` VALUES (3290, '2945', '', '', '0', 'Toi aussi tu viens de vaincre, le terrible Mob l\\\'Eponge ! \\nAvec un peu de chance, tu penseras ? moi lorsque tu finiras dig?r? par un Kralamoure G?ant. \\nTiens tu as l\\\'air tendu, d?contracte-toi, le combat est termin?, il fait beau, il y a du soleil et tu es dans la zone d\\\'Astrub ! Que r?ver de plus ? \\nMais ma parole, tu es raide comme un piquet de cl?ture en Kaliptus dess?ch?. \\nLaisse-moi te montrer je vais t\\\'apprendre ? te d?tendre !');
INSERT INTO `npc_questions` VALUES (3291, '2934', '', '', '0', 'Avant d\\\'?tre capitaine, cuisinier, bricoleur, inventeur, chanteur, et danseur de Chachacha, j\\\'?tais m?decin. M?decin malgr? moi, mais m?decin tout de m?me. \\nJe vais essayer de te remettre les os en place, reste concentr?... \\nTiens c\\\'est ?trange, tu as le coeur ? gauche et le foie ? droite, c\\\'est l\\\'inverse normalement... Hum... Ouch... \\nVoil? c\\\'est bon, j\\\'ai remis tout ce que j\\\'ai pu ? sa place, tu devrais d?sormais ?tre capable de t\\\'allonger en un claquement de doigts, mais sans faire craquer tes os... Tu pourras profiter du sable chaud et de mes histoires v?ridiques. \\nAu fait, je t\\\'ai d?j? dit que j\\\'avais construit les transporteurs brigandins, et que j\\\'ai ?t? moi-m?me chef des brigandins, apr?s avoir ?t? captur? par les Kannibouls de l\\\'?le de Moon juste avant de... \\nH? mais reviens pourquoi te sauves-tu ? Reviens, je n\\\'ai pas fini mon histoire !');
INSERT INTO `npc_questions` VALUES (3292, '2803', '', '', '0', 'Irrrrk ! \\nFneuh Shiii krodocouic doc krik kric ?');
INSERT INTO `npc_questions` VALUES (3293, '', '', '', '', 'Nous ?tre ici ! \\nDonjon des Rats de Bonta, grand donjon rempli de rats tr?s puissants. \\nNous manger Bontariens ? tous les repas. \\nNous pas capables de faire diff?rence entre Bontarien et pas Bontarien.');
INSERT INTO `npc_questions` VALUES (3294, '2950', '', '', '0', 'Snirk ! \\nCouic snot snot gurlube couic ? \\nCouic snif kriss trok couic ! \\n \\n');
INSERT INTO `npc_questions` VALUES (3295, '', '', '', '', 'H? oui jeune Bontarien, apr?s toutes ces ann?es ? travailler b?n?volement aux services de notre bonne ville de Bonta, nous y sommes enfin arriv?s !');
INSERT INTO `npc_questions` VALUES (3296, '', '', '', '', 'Il est vrai que je n\\\'y croyais plus moi-m?me. Nous avons enfin un b?timent d?di? au savoir, ? la culture, ? l\\\'intelligence, ? la m?moire, ? la comm?moration de la grandeur de Bonta.');
INSERT INTO `npc_questions` VALUES (3297, '', '', '', '', 'Tu devrais aller visiter la toute nouvelle biblioth?que de Bonta, tu y trouveras certainement des tonnes de livres int?ressants sur des sujets allant de la gen?se de notre plan?te ? l\\\'utilisation d\\\'une monture.');
INSERT INTO `npc_questions` VALUES (3298, '', '', '', '', 'Je suis heureux de voir que les jeunes comme toi vont de temps en temps ? la biblioth?que. Tu sais avant, il y avait plein de boutiques et d\\\'ateliers ici, mais depuis l\\\'arriv?e des Dragodindes, les commer?ants se sont mis ? l\\\'?levage, c\\\'est plus rentable ! La vente des boutiques a permis de construire tous ces enclos mais aussi notre belle biblioth?que.');
INSERT INTO `npc_questions` VALUES (3299, '', '', '', '', 'Si tu ne sais pas o? est la biblioth?que, n\\\'h?site pas ? demander ton chemin.');
INSERT INTO `npc_questions` VALUES (3300, '', '', '', '', 'Quel livre vais-je bien pouvoir lire ? la biblioth?que ? Le Temps des Dragons ? le Manuel des Dragodindes ?');
INSERT INTO `npc_questions` VALUES (3301, '2957;295', '', '', '0', 'Haha ! Ca y est nous allons ?tre les plus forts ! Nous allons avoir la supr?matie sur la plan?te enti?re et sur les Dieux gr?ce ? notre nouvelle arme secr?te. Les Dragons vont nous manger dans la main !');
INSERT INTO `npc_questions` VALUES (3302, '2960;295', '', '', '0', 'Le Seigneur d?mon nous a ?rig? en une nuit un nouvel ?difice d?di? au savoir, ? la guerre, ? la puissance, ? la supr?matie, ? la strat?gie.');
INSERT INTO `npc_questions` VALUES (3303, '296', '', '', '0', 'Ignorant, va donc fouler de tes pieds incultes la toute nouvelle biblioth?que de Br?kmar ! En ce lieu, tu apprendras tout sur les techniques de combat, de magie et de dressage. Il y a aussi des grimoires remplis de conseils divers pour survivre en milieu hostile.');
INSERT INTO `npc_questions` VALUES (3304, '', '', '', '', 'Pnj(802) et Message(3302)');
INSERT INTO `npc_questions` VALUES (3305, '', '', '', '', 'Je suis heureuse de voir que les jeunes comme toi vont de temps en temps ? la biblioth?que. Tu sais avant, il y avait plein de boutiques et d\\\'ateliers ici, mais depuis l\\\'arriv?e des Dragodindes, les commer?ants se sont mis dans l\\\'?levage, c\\\'est plus rentable. La vente des boutiques a permis de construire tous ces enclos mais aussi notre belle biblioth?que !');
INSERT INTO `npc_questions` VALUES (3306, '', '', '', '', 'Si tu ne sais pas o? est la biblioth?que, n\\\'h?site pas ? demander ton chemin.');
INSERT INTO `npc_questions` VALUES (3307, '', '', '', '', 'Quel nouvel ouvrage a ?t? publi? depuis ma derni?re visite ? la biblioth?que ? Comment cuisiner un Bontarien ? Comment pi?tiner un Piou Piou ? Je devrais peut-?tre m\\\'y rendre ?');
INSERT INTO `npc_questions` VALUES (3308, '2964;2965', '', 'QE!143', '3309', 'Notre bon roi Allister m\\\'a charg? de former le plus bel haras de la r?gion. Or, je vois ? tes jambes arqu?es que tu as d?j? mont? une cr?ature. Veux tu bien me livrer des Dragodindes ? Le roi qui n\\\'est pas un ingrat saura te r?compenser !');
INSERT INTO `npc_questions` VALUES (3309, '', '', '', '', 'Le roi attend son haras. Ta tâche est royale, essaie d\'être plus prompt !');
INSERT INTO `npc_questions` VALUES (3310, '', '', '', '', 'Pnj(803) et Message(3308)');
INSERT INTO `npc_questions` VALUES (3311, '', '', '', '', 'Merci, notre bon roi Allister va pouvoir parader sur ces fi?res montures maintenant !');
INSERT INTO `npc_questions` VALUES (3312, '', '', '', '', 'Le roi attend son haras. Ta t?che est royale, essaie d\\\'?tre plus prompt !');
INSERT INTO `npc_questions` VALUES (3313, '', '', '', '', 'O? vais-je pouvoir trouver de belles Dragodindes pour le roi Allister ?');
INSERT INTO `npc_questions` VALUES (3314, '', '', '', '', 'Je veux chaaaaaaaaaaaaaaarger ! Ram?ne-moi vite ces Dragodindes.');
INSERT INTO `npc_questions` VALUES (3315, '2968;296', '', '', '0', 'Pour charger les Br?kmariens avec ma cavalerie, j\\\'ai besoin de Dragodindes v?loces et r?sistantes !');
INSERT INTO `npc_questions` VALUES (3316, '', '', '', '', 'Merci, voil? pour toi.');
INSERT INTO `npc_questions` VALUES (3317, '', '', '', '', 'A la prochaine charge de Dragodinde, je percerai m?me les murs de Br?kmar.');
INSERT INTO `npc_questions` VALUES (3318, '', '', '', '', 'Je cherche des Dragodindes massives et violentes afin de renverser la pi?taille de Bonta.');
INSERT INTO `npc_questions` VALUES (3319, '', '', '', '', 'Merci, voil? pour toi.');
INSERT INTO `npc_questions` VALUES (3320, '', '', '', '', 'Je veux pi???????????????tiner ! Ram?ne-moi vite ces Dragodindes.');
INSERT INTO `npc_questions` VALUES (3321, '', '', '', '', 'A la prochaine charge, je transformerai l\\\'infanterie de Bonta en pur?e avec morceaux.');
INSERT INTO `npc_questions` VALUES (3322, '2972;2973', '', '', '0', 'La montagne des Koalaks n\\\'a pas ?t? bien cartographi?e. J\\\'aimerais bien que de jeunes aventuriers curieux et t?m?raires me ram?nent une description de cette lointaine contr?e...');
INSERT INTO `npc_questions` VALUES (3323, '', '', '', '', 'La montagne des Koalaks n\\\'a pas ?t? bien cartographi?e. J\\\'aimerais bien que de jeunes aventuriers curieux et t?m?raires me ram?nent une description de cette lointaine contr?e...');
INSERT INTO `npc_questions` VALUES (3324, '', '', '', '', 'Merci, jeune aventurier !');
INSERT INTO `npc_questions` VALUES (3325, '', '', '', '', 'Tu es jeune et vif, tu devrais faire vite.');
INSERT INTO `npc_questions` VALUES (3326, '', '', '', '', 'Ma nouvelle carte du monde sera du plus bel effet dans mes toilettes !');
INSERT INTO `npc_questions` VALUES (3327, '', '', '', '', 'La montagne des Koalaks est un paradis pour nous autre les alchimistes. J\\\'aimerais que tu me rapportes quelques fleurs de cette contr?e. Mais prends garde aux protecteurs lors de ta cueillette : on dit qu\\\'ils sont les yeux du dieu Sadida....');
INSERT INTO `npc_questions` VALUES (3328, '', '', '', '', 'Le dieu Sadida t\\\'emp?che de cueillir les fleurs... ou peut-?tre que tu tra?nes des pieds ?');
INSERT INTO `npc_questions` VALUES (3329, '', '', '', '', 'Merci, jeune aventurier.');
INSERT INTO `npc_questions` VALUES (3330, '', '', '', '', 'Attention, le dieu Sadida est susceptible en ce moment. Il n\\\'aime pas que l\\\'on cueille ses fleurs. Des protecteurs veillent sur ses pr?cieux v?g?taux.');
INSERT INTO `npc_questions` VALUES (3331, '', '', '', '', 'Bon, je vais vous la faire courte: j\\\'ai besoin de morceaux de Kaliptus et de Koalaks.');
INSERT INTO `npc_questions` VALUES (3332, '', '', '', '', 'Bon, je vais vous la faire courte: j\\\'ai besoin de morceaux de Kaliptus et de Koalaks.');
INSERT INTO `npc_questions` VALUES (3333, '', '', '', '', 'J\\\'aime faire des affaires avec toi. N\\\'h?site pas ? revenir me voir.');
INSERT INTO `npc_questions` VALUES (3334, '', '', '', '', 'Tu ne devrais pas tra?ner dans Astrub. Va ? Koalak et ram?ne-moi les ressources que je recherche.');
INSERT INTO `npc_questions` VALUES (3335, '', '', '', '', 'Quand tu seras plus fort, tu pourras me ramener des fournitures de la r?gion de Koalak.');
INSERT INTO `npc_questions` VALUES (3336, '', '', '', '', 'Quand tu seras plus fort, tu pourras me ramener des fournitures de la r?gion de Koalak.');
INSERT INTO `npc_questions` VALUES (3337, '', '', '', '', 'Comme je suis content de te voir ! Nous allons encore pouvoir oeuvrer ensemble. Toi ? gambader dans la nature, moi ? confectionner toutes sortes de chose... Se balader en pleine nature... Tu as vraiment le beau r?le. Enfin, voil? la liste de ce qu\\\'il me faut. J\\\'attends ton retour avec impatience.');
INSERT INTO `npc_questions` VALUES (3338, '', '', '', '', 'Tu es quelqu\\\'un de confiance, n\\\'h?site pas ? revenir me voir !');
INSERT INTO `npc_questions` VALUES (3339, '', '', '', '', 'J\\\'ai besoin de quelques morceaux de Koalaks. Tu te sens pr?t ?');
INSERT INTO `npc_questions` VALUES (3340, '', '', '', '', 'C\\\'est exactement ce que j\\\'attendais. Tiens ! pour te d?dommager de tes efforts');
INSERT INTO `npc_questions` VALUES (3341, '2993;2990;2980;2998;2983', '', '', '0', 'Salut ! Bienvenue sur le serveur de test. \\n \\nQu\\\'est-ce que je peux faire pour toi?');
INSERT INTO `npc_questions` VALUES (3342, '', '', '', '', 'Salut! Bienvenue sur le serveur de test. \\n \\nVoici une liste de quelques unes des nouveaut?s apport?es par cette version 1.17.0 BETA 1 : \\n \\n - Le donjon des Abraknydes et celui du Ch?ne Mou;\\r\\n            \\n - Le syst?me de forgemagie revu;\\r\\n            \\n - Les emotes avec la commande /me;\\r\\n            \\n - La correction du probl?mes des cases bloquantes;\\r\\n            \\n - Un nouveau syst?me de choix de serveur automatique;\\r\\n            \\n - Une liste plus compl?te des caracteristiques de son personnage. \\n \\nCette liste n\\\'est pas compl?te, tu peux en trouver une plus exaustive sur le forum, dans la section Serveur de test. \\n \\nEn haut ? droite de ton ?cran, ? cot? du menu des options, se trouve maintenant un petit bouton qui te permet de soumettre au support un probl?me que tu aurais constat?. Tu peux ?galement en discuter sur le forum. \\n \\nVoil? voil?, alors, qu\\\'est-ce que je peux faire pour toi?');
INSERT INTO `npc_questions` VALUES (3343, '', '', '', '', 'F?licitations! \\n \\nTu gagnes un merveilleux voyage touristique dans la jungle des Wabbits, sponsoris? par la compagnie a?rienne En Kamas! Ambiance safari garantie! \\n \\nSans rancune... Et bonne route!');
INSERT INTO `npc_questions` VALUES (3350, '2982;2989;3036;3037;3038', '', '', '0', 'Je peux te donner une clef et te t?l?porter directement devant l\\\'entr?e du donjon de ton choix. \\nVers quel donjon veux-tu aller ?');
INSERT INTO `npc_questions` VALUES (3351, '', '', '', '', 'Mais il te faut une clef voyons pour rentrer dans ce donjon ! \\nJe peux t\\\'en vendre.');
INSERT INTO `npc_questions` VALUES (3352, '2984', '', '', '0', 'Pour rapporter un probl?me que tu aurais constat?, tu peux:  \\n \\n - Cliquer sur le bouton en haut ? droite de ta fen?tre ? c?t? du menu option;\\r\\n            \\n - ?crire au support (http://support.dofus.com/) dans la section serveur de test;\\r\\n            \\n - Poster sur le forum Serveur de test. \\n \\nN\\\'h?site pas ? contacter l\\\'?quipe d\\\'Ankama pour tous probl?mes que tu verrais ici!');
INSERT INTO `npc_questions` VALUES (3353, '2987;2988', '', 'QE!151', '3355', 'Toi, tu veux aller tondre la laine du roi des Bouftous, pas vrai ? Soit tu cherches la clef de son antre dans les entrailles d\\\'un de ses fid?les, soit tu m\\\'apportes ce qu\\\'il y a dans cette liste !');
INSERT INTO `npc_questions` VALUES (3354, '', '', '', '', 'Visite un peu la zone autour de toi. C\\\'est pas tr?s grand, mais tu y trouveras des merveilles!');
INSERT INTO `npc_questions` VALUES (3355, '', '', '', '', 'Hey, hey! Tu n\\\'as pas de clé');
INSERT INTO `npc_questions` VALUES (3356, '', '', '', '', 'Tu es jeune et vif, tu devrais faire vite.');
INSERT INTO `npc_questions` VALUES (3357, '', '', '', '', 'Le roi des Bouftous va bient?t recevoir de la visite.');
INSERT INTO `npc_questions` VALUES (3358, '', '', '', '', 'Et voil?, bonne tonte !');
INSERT INTO `npc_questions` VALUES (3359, '2991;2992', '', '', '0', 'Attention, il te faudra des runes pour pouvoir tester efficacement, ainsi que des objets. Tu peux trouver les deux chez mes coll?gues de cette zone. \\nEs-tu pr?t ? t\\\'envoler vers un atelier?');
INSERT INTO `npc_questions` VALUES (3360, '2994;2995', '', '', '0', 'H? non, petit coquinou. \\nLe principe du serveur de test est le suivant: on teste de nouvelles fonctionnalit?s de Dofus en avant-premi?re, pour erradiquer les probl?mes qui pourraient subsister. Mais on ne teste pas son personnage, non, ?a n\\\'est pas l? pour ?a... Tu tu tu...');
INSERT INTO `npc_questions` VALUES (3361, '3000', '', '', '0', 'Ok. Alors rapporte moi les six Dofus... Enfin, les six Dofus que tu pourrais avoir trouv?s, et on va voir ce que l\\\'on peut faire.');
INSERT INTO `npc_questions` VALUES (3362, '2999', '', '', '0', 'Tu trouveras la liste des nouveaut?s de cette mise ? jour sur les forums officiels, dans la section \\\"Carnet de bord\\\".');
INSERT INTO `npc_questions` VALUES (3363, '', '', '', '', 'Hein ? Tu l\\\'as fait ? Tu l\\\'as vraiment fait ? \\nEuh... Bon, alors... Laisse-moi lire mon manuel dans ce cas... Bla bla bla... Douze zillions de protections usag?es de Bwork... Pas ?a... Ah, voil?. \\\"Ram?ne les six Dofus\\\". Alors... Je dois te donner... \\n \\n... \\n \\nHmmm. Es-tu pr?t pour ta r?compense?');
INSERT INTO `npc_questions` VALUES (3364, '3007;3008', '', '', '', 'J\\\'ai en ma possession une puissante relique familiale. On se la passe de p?re en fils de g?n?ration en g?n?ration. La tradition familiale veut ?galement que cette relique puisse ?tre transmise ? un puissant guerrier. Je ne te crois pas capable de r?ussir.');
INSERT INTO `npc_questions` VALUES (3365, '3009', '', '', '', 'Voyez-vous ?a ! C\\\'est le gland qui se voit d?j? un ch?ne ! Comment comptes-tu me prouver ta valeur ? Quel miracle ferait de toi le plus grand des combattants ?');
INSERT INTO `npc_questions` VALUES (3366, '3010;3011', '', '', '', 'Voyez-vous ?a, il insiste. Bien, prouve moi que tu es capable de te battre correctement. Tu trouveras surement des cr?atures dans la r?gion. Tues-en quelques unes et reviens me voir. J\\\'aurai trouv?, d\\\'ici l?, une s?rie d\\\'?preuves dignes des plus grands combattants !');
INSERT INTO `npc_questions` VALUES (3367, '', '', '', '', 'Ah charmante et insouciante ! Bien, si c\\\'est ce que tu veux. Va parler aux Ma?tre des clefs, si tu accomplis tout ce qu\\\'il te demandera, alors je m\\\'engage ? te remettre la relique familiale. Il n\\\'existe pas de plus puissant artefact sur le monde des douze.');
INSERT INTO `npc_questions` VALUES (3368, '', '', '', '', 'L\\\'esprit du guerrier point ne t\\\'habite.');
INSERT INTO `npc_questions` VALUES (3369, '', '', '', '', 'Voici ce que tu auras ? faire. Va voir le Ma?tre des clefs, il te donnera l\\\'?preuve suivante. N\\\'oublie pas que si, par le plus grand des hasard, tu arrivais ? remplir toutes les qu?tes qui vont t\\\'?tre confi?es, je m\\\'engage ? te remettre la relique de notre famille. Il n\\\'est pas de plus puissant artefact sur le monde des Douze.');
INSERT INTO `npc_questions` VALUES (3370, '', '', '', '', 'Le monde est peupl? de faibles. Y a t\\\'-il un v?ritable guerrier quelque part ?');
INSERT INTO `npc_questions` VALUES (3371, '', '', '', '', 'Metag t\\\'envoie vers moi et il souhaite que je te mette ? l\\\'?preuve ? Voyons voir... J\\\'ai bien quelque chose digne du plus grand des guerriers. Sois bien attentif, je ne le te dirai qu\\\'une fois. Ce que tu vas devoir faire sera long, difficile et extr?mement dangereux. C\\\'est l\\\'oeuvre de toute ma vie. Si tu suis mes traces, cela peut te prendre toute ta vie pour achever ce que j\\\'ai accompli. Ce n\\\'est pas une t?che qu\\\'on commence ? la l?g?re. On va proc?der par ?tapes. Voici une clef. Trouve la porte qu\\\'elle ouvre. Va au fond de l\\\'endroit d?couvert et affronte le ma?tre des lieux. Reviens me voir une fois ?ela accompli.');
INSERT INTO `npc_questions` VALUES (3373, '', '', '', '', 'Je comprends que c\\\'est une t?che ardue mais le miroitement de l\\\'artefact de Metag doit te mener de l\\\'avant.');
INSERT INTO `npc_questions` VALUES (3374, '', '', '', '', 'Tu m\\\'impressionnes, mais ce n\\\'est pas fini, voici la clef qui te m?nera vers le prochain combat.');
INSERT INTO `npc_questions` VALUES (3375, '', '', '', '', 'Tu m\\\'impressionnes, mais ce n\\\'est pas fini, voici la clef qui te m?nera vers le prochain combat.');
INSERT INTO `npc_questions` VALUES (3376, '', '', '', '', 'Tu m\\\'impressionnes, mais ce n\\\'est pas fini, voici la clef qui te m?nera vers le prochain combat.');
INSERT INTO `npc_questions` VALUES (3377, '', '', '', '', 'Tu m\\\'impressiones, mais ce n\\\'est pas fini, voici la clef qui te m?nera vers le prochain combat.');
INSERT INTO `npc_questions` VALUES (3378, '', '', '', '', 'Tu as triomph? de toutes les ?preuves, surmont? tous les obstacles. Ton courage est brillant comme un soleil de printemps. Va vers ta destin?e, que ton ?me soit forte comme l\\\'acier. Laisse-moi maintenant, des questions troublent mon esprit.');
INSERT INTO `npc_questions` VALUES (3379, '', '', '', '', 'J\\\'ai vu tant de choses, que vous, ne pourriez croire... De grands navires en feu, surgissant de l\\\'?paule d\\\'Orion. J\\\'ai vu des rayons fabuleux, briller dans l\\\'ombre de la porte de Tanhauser. Tous ces moments se perdront dans l\\\'oubli, comme les larmes, dans la pluie... Il est temps de partir...');
INSERT INTO `npc_questions` VALUES (3380, '', '', '', '', 'Arrrh sur que j\\\'peux te trouver un truc \\\'faire, j\\\'ben un coin ou deux ? d\\\'ratiser s\\\'tu vois s\\\'qu\\\'je pense. Si l\\\'ma?tre te d\\\'mande ?a, doit avoir ses raisons. Tiens, commence donc par ?a.');
INSERT INTO `npc_questions` VALUES (3381, '', '', '', '', 'Au boulot mon p\\\'tit, s\\\'tu finis pas c\\\'que j\\\'t\\\'ai d\\\'mand?, le Ma?tre s\\\'ra pas content.');
INSERT INTO `npc_questions` VALUES (3382, '', '', '', '', 'Ca c\\\'est bien ! Tiens, v\\\'la la clef pour la suite. Vas-y vite.');
INSERT INTO `npc_questions` VALUES (3383, '', '', '', '', 'Ca c\\\'est bien ! Tiens, v\\\'la la clef pour la suite. Vas-y vite.');
INSERT INTO `npc_questions` VALUES (3384, '', '', '', '', 'Ca c\\\'est bien ! Tiens, v\\\'la la clef pour la suite. Vas-y vite.');
INSERT INTO `npc_questions` VALUES (3385, '', '', '', '', 'Ca c\\\'est bien ! Tiens, v\\\'la la clef pour la suite. Vas-y vite.');
INSERT INTO `npc_questions` VALUES (3386, '', '', '', '', 'D\\\'bien beaux combats, pour sur ! Moi j\\\'ai plus rien ? t\\\'donner. Bon vent ? toi.');
INSERT INTO `npc_questions` VALUES (3387, '', '', '', '', 'Ca c\\\'est bien ! Tiens, v\\\'la la clef pour la suite. Vas-y vite.');
INSERT INTO `npc_questions` VALUES (3388, '', '', '', '', 'Il fait beau, je sens que j\\\'vais aller abattre un arbre ou deux. Et si j\\\'ai d\\\'la chance, j\\\'tomberai peut ?tre sur un abraknyde.');
INSERT INTO `npc_questions` VALUES (3389, '', '', '', '', 'Quoi ? Qui vous envoie ? Qui ? Ah mais non non non, Je n\\\'ai pas que ?a ? faire moi ! Niiiiiiiiiiiiiiiiiiiiihhhhhhhhhhhhh Le ma?tre ? Le ma?tre ! Prends la clef et va-t\\\'en ! Va-t\\\'en ! Disparais ! Hors de ma vue ! Rahhhhhhhhhh ! La clef, les clefs !');
INSERT INTO `npc_questions` VALUES (3390, '', '', '', '', 'Quoi !? Vous revenez sans avoir fini ! Non ! Du vent, partez ! Le ma?tre ne sera pas content ! Non non non, il sera furieux ! Partez, je ne vous connais pas. Finissez ce que vous avez ? faire. Allez !');
INSERT INTO `npc_questions` VALUES (3391, '', '', '', '', 'Oui ! C\\\'est bien. Pas fini... rien n\\\'est fini, rien ne se termine jamais. Encore se battre. Toujours. La clef du prochain combat.');
INSERT INTO `npc_questions` VALUES (3392, '', '', '', '', 'Oui ! C\\\'est bien. Pas fini... rien n\\\'est fini, rien ne se termine jamais. Encore se battre. Toujours. La clef du prochain combat.');
INSERT INTO `npc_questions` VALUES (3393, '', '', '', '', 'Oui ! C\\\'est bien. Pas fini... rien n\\\'est fini, rien ne se termine jamais. Encore se battre. Toujours. La clef du prochain combat.');
INSERT INTO `npc_questions` VALUES (3394, '', '', '', '', 'Oui ! C\\\'est bien. Pas fini... rien n\\\'est fini, rien ne se termine jamais. Encore se battre. Toujours. La clef du prochain combat.');
INSERT INTO `npc_questions` VALUES (3395, '', '', '', '', 'Oui ! C\\\'est bien. Pas fini... rien n\\\'est fini, rien ne se termine jamais. Encore se battre. Toujours. La clef du prochain combat.');
INSERT INTO `npc_questions` VALUES (3396, '', '', '', '', 'Je n\\\'ai plus rien, allez du vent ! hop ! zou ! du balai !');
INSERT INTO `npc_questions` VALUES (3397, '', '', '', '', 'Pas le temps ! niiiiiiiiihhhhhhhhh ! Laissez-moi tranquille');
INSERT INTO `npc_questions` VALUES (3398, '', '', '', '', 'Ta nouvelle mission, si toutefois tu l\\\'acceptes, sera de t\\\'infiltrer dans le donjon qu\\\'ouvre cette clef. Une fois ? l\\\'int?rieur vous devrez vous faire ignorer des cr?atures locales. Vous descendrez au plus profond du donjon. Evidemment, si vous ou l\\\'un des membres de votre ?quipe venait ? ?tre captur?, je nierai avoir eu connaissance de cette mission. Bonne chance. Termin');
INSERT INTO `npc_questions` VALUES (3399, '', '', '', '', 'Vous devez accomplir votre mission.');
INSERT INTO `npc_questions` VALUES (3400, '', '', '', '', 'Votre mission est un succ?s. Bzzztt... Votre nouvelle mi... bzttt krouik ! Frtrtttt');
INSERT INTO `npc_questions` VALUES (3401, '', '', '', '', 'Votre mission est un succ?s. Bzzztt... Votre nouvelle mi... bzttt krouik ! Frtrtttt');
INSERT INTO `npc_questions` VALUES (3402, '', '', '', '', 'Votre mission est un succ?s. Bzzztt... Votre nouvelle mi... bzttt krouik ! Frtrtttt');
INSERT INTO `npc_questions` VALUES (3403, '', '', '', '', 'Votre mission est un succ?s. Bzzztt... Votre nouvelle mi... bzttt krouik ! Frtrtttt');
INSERT INTO `npc_questions` VALUES (3404, '', '', '', '', 'Krzzouiiittt ! scan... code non reconnu...');
INSERT INTO `npc_questions` VALUES (3405, '', '', '', '', 'Votre mission est un succ?s. Bzzztt... Votre nouvelle mi... bzttt krouik ! Frtrtttt');
INSERT INTO `npc_questions` VALUES (3406, '', '', '', '', 'Le chemin n\\\'est pas le but, mais c\\\'est le chemin qui y m?ne. Pour toi il a ?t? long et il n\\\'est pas fini. Mais au bout du voyage, auras-tu atteint ta destination ? Car si le but est atteint, obtiendras-tu ce que tu convoites ?');
INSERT INTO `npc_questions` VALUES (3407, '', '', '', '', 'Le ma?tre des clefs m\\\'a relat? ton succ?s. J\\\'ai dout? de toi et je m\\\'en excuse. Ne t\\\'inqui?te pas je tiendrai promesse. Voil?, je d?pose entre tes mains avides la relique de notre famille. Sache que tous les guerriers l\\\'ont utilis?e, et certains plusieurs fois ! Je dois te pr?venir cependant qu\\\'une mal?diction frappera le fou qui la retournerait ! Fais en bon usage.');
INSERT INTO `npc_questions` VALUES (3408, '', '', '', '', 'Tu avances, mais la fin de la route semble de plus en plus loin, tout ?ela en vaut-il la peine?');
INSERT INTO `npc_questions` VALUES (3409, '', '', '', '', 'Si tu regardes en arri?re, le chemin restant te semblera encore plus long.');
INSERT INTO `npc_questions` VALUES (3410, '', '', '', '', 'Ce n\\\'est pas en voyant le sommet que tu pourras te vanter d\\\'avoir gravi la montagne.');
INSERT INTO `npc_questions` VALUES (3411, '', '', '', '', 'Quand le but est atteint, tous les sacrifices semblent bien minimes.');
INSERT INTO `npc_questions` VALUES (3414, '', '', '', '', 'Il faut que je te dise, la derni?re fois que j\\\'ai vu une bougie, c\\\'?tait sur le casque d\\\'un mineur sombre. Tu devrais fouiller de ce c?t');
INSERT INTO `npc_questions` VALUES (3415, '3032', '', '', '0', 'Ah tu tombes bien, je cherche de l\\\'aide pour aller affronter les dieux, ces derniers se sont permis de r?duire la puissance de mes Sacrifices, et cela sans raison ! \\nC\\\'est une honte, ils ne nous ont m?me pas demand? notre avis ! \\nBon finalement je pense que j\\\'irai les affronter un autre jour, j\\\'ai d\\\'autres choses plus importantes ? faire. \\nAu fait que veux-tu ?');
INSERT INTO `npc_questions` VALUES (3416, '', '', '', '', 'On raconte que ce donjon ?tait d?j? construit bien avant que la premi?re pierre des murailles du ch?teau d\\\'Amakna ne soit pos?e.\\nC\\\'est une sorte de temple o? s\\\'exerce un culte assez obscur.\\nCet endroit est infest? de rats relativement dangereux, mais qui restent inoffensifs en comparaison ? leur ma?tre, Sphincter.');
INSERT INTO `npc_questions` VALUES (3417, '', '', '', '', 'Peu d\\\'aventuriers connaissent le vrai nom de ce rat. \\nNous savons juste qu\\\'il ?tait l\\\'animal de compagnie d\\\'un Ma?tre Pandawushu appel? Hamatawan Yoshawa qui vivait dans un archipel exotique non loin de l\\\'?le de Pandala. Dou? de facult?s exceptionnelles pour son esp?ce, ce rat ?tait capable d\\\'apprendre l\\\'art de son ma?tre par mim?tisme lorsque celui-ci s\\\'entra?nait dans son dojo.  \\nMais Yoshawa avait un ennemi, au sein de son dojo, l\\\'illustre Ma?tre Pandawushu connu sous le nom d\\\' Orukawa Nagitan.');
INSERT INTO `npc_questions` VALUES (3418, '', '', '', '', 'Une sombre histoire d\\\'amour opposait ces deux hommes qui aimaient la m?me femme. Mais cette femme jeta son d?volu sur Yoshawa. Orukawa ne pouvait supporter un tel affront et s\\\'attaqua ? cette femme. Yoshawa s\\\'interposa et pris d\\\'une folie meurtri?re, il tua Orukawa en l\\\'?touffant sous un ?dredon en poils de Kirboule. Le pauvre ne mourut pas ?touff?, mais asphyxi?. \\nYoshawa et sa dulcin?e, d?cid?rent alors de quitter leur archipel, pour rejoindre le village d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (3419, '', '', '', '', 'Mais ils furent poursuivis par l\\\'inf?me cousin d\\\'Orukawa qui voulait le venger. Il les saigna comme des Bouftous, et vendit leur d?pouille sous forme de chair ? saucisse sur les march?s de Br?kmar. Quelle triste fin ! \\nC\\\'est ainsi que le rat de Yoshawa se retrouva seul. Il se r?fugia dans les ?gouts  du ch?teau d\\\'Amakna pendant de nombreuses ann?es. \\nOn raconte qu\\\'il rencontra Otoma? en personne, qui testait de nouvelles potions aux effets encore insoup?onn?s, sur des tortues venues de l\\\'?le de Moon.');
INSERT INTO `npc_questions` VALUES (3420, '', '', '', '', 'Otoma? confia les tortues au rat, mais personne ne se doutait que les effets de la potion administr?e aux tortues, allaient se transmettre ? tous les rats... \\nC\\\'est ainsi que le rat devint ?norme et encore plus dangereux. \\nCertains savants de ce monde expliquent m?me la taille d?mesur?e des rats que l\\\'on trouve dans les grottes et les ?go?ts de notre monde, gr?ce aux effets secondaires de cette terrible potion qui se transmettent rapidement entre les rats, apr?s une simple morsure ou m?me un accouplement. Et tu connais bien les rats, ils sont presque aussi actifs que les Wabbits !');
INSERT INTO `npc_questions` VALUES (3421, '', '', '', '', 'Et bien, je pense t\\\'avoir dit tout ce que je savais ? propos de ce rat et de son histoire. \\nMais fais attention, ce rat est anim? d\\\'un d?sir de vengeance, il entraine ses tortues et les autres rats dans l\\\'unique but de venger son ma?tre, mais il semble avoir perdu la raison et s\\\'attaquer ? quiconque ose p?n?trer son temple. \\nPrends garde ? toi, sa ma?trise de l\\\'art Pandawushu d?passe s?rement tout ce que tu peux imaginer.');
INSERT INTO `npc_questions` VALUES (3422, '', '', '', '', 'Comment as-tu fait pour vaincre ce rat ? Je te conseille d\\\'aller sur l\\\'?le de Pandala et de parfaire tes techniques de Pandawushu, ton potentiel semble tout simplement incroyable. \\n \\nSuis-moi, je vais te faire sortir de ce trou ? rats !');
INSERT INTO `npc_questions` VALUES (3423, '', '', '', '', 'Pnj(809) et Message(3350)');
INSERT INTO `npc_questions` VALUES (3424, '', '', '', '', 'Oui, avec ?a on devrait pouvoir y arriver. Va pr?venir mon ami s\\\'il te plait');
INSERT INTO `npc_questions` VALUES (3425, '', '', '', '', 'Vous n\\\'avez pas vu mes enfants ? Ils sont tellement joueurs.');
INSERT INTO `npc_questions` VALUES (3426, '', '', '', '', 'J\\\'ai beaucoup de travail, c\\\'est ma femme qui s\\\'occupe des enfants.');
INSERT INTO `npc_questions` VALUES (3427, '', '', '', '', 'J\\\'aime... beaucoup... les enfants.');
INSERT INTO `npc_questions` VALUES (3428, '', '', '', '', 'Ebloui par la victoire, on ne voit plus les dangers');
INSERT INTO `npc_questions` VALUES (3429, '', '', '', '', 'E=MC?, j\\\'ai r?v? de ?a cette nuit, qu\\\'est ce que ?a peut bien signifier ?');
INSERT INTO `npc_questions` VALUES (3430, '3039;3040', '', '', '', 'Nos enfants ont disparu ! J\\\'?tais ? mon travail et quand je suis rentr? chez moi, j\\\'ai trouv? ma femme Madame El effondr?e de chagrin. Cela fait maintenant deux jours et je suis extr?mement inquiet. Aidez-nous, je vous en prie.');
INSERT INTO `npc_questions` VALUES (3431, '', '', '', '', 'Merci, Merci beaucoup, allez parler ? ma femme, Madame El.');
INSERT INTO `npc_questions` VALUES (3432, '', '', 'QE=158', '3425', 'Sniff, mes enfants, Hans ! Gret ! o? ?tes vous ?...');
INSERT INTO `npc_questions` VALUES (3433, '', '', '', '', 'Vraiment ? Comme c\\\'est gentil ? vous ! Les enfants jouaient autour de la fontaine du village. Je discutais avec une amie et quelques instants apr?s ils avaient disparus. Je les ai cherch?s partout. J\\\'ai tellement peur pour eux.');
INSERT INTO `npc_questions` VALUES (3434, '', '', '', '', 'Les enfants El ? non je ne les ai pas vus.');
INSERT INTO `npc_questions` VALUES (3435, '', '', '', '', 'Hans et Gret, oui, je crois que je les ai aper?us, ils jouaient avec le petit Jorg Dy.');
INSERT INTO `npc_questions` VALUES (3436, '', '', '', '', 'Un jour je partirai ? l\\\'aventure.');
INSERT INTO `npc_questions` VALUES (3437, '', '', '', '', 'Il faut que j\\\'aille faire un tour au march?. Les aventuriers vendent tellement de belles choses.');
INSERT INTO `npc_questions` VALUES (3438, '', '', '', '', 'Hans y m\\\'a dit qu\\\'il voulait attraper une dragodinde, oui m\\\'sieur ! M?me qu\\\'il m\\\'a dit qu\\\'il a trouv? une cabane dans la for?t que personne d\\\'autre ne conna?t.');
INSERT INTO `npc_questions` VALUES (3439, '', '', '', '', 'Tu joues avec moi ?');
INSERT INTO `npc_questions` VALUES (3440, '', '', '', '', 'Des enfants ? non, je n\\\'ai pas vu d\\\'enfants depuis bien longtemps. Et pourtant j\\\'aime les enfants, beaucoup...');
INSERT INTO `npc_questions` VALUES (3441, '', '', '', '', 'Et bien si deux enfants ce sont aventur?s par ici, je ne les ai pas vus !');
INSERT INTO `npc_questions` VALUES (3442, '', '', '', '', 'Par le caramel trop cuit, je suis bien b?te parfois. Mais ?a ne change rien. J\\\'ai enferm? les enfants dans un endroit connu de moi seule. Si tu fais ce que je dis, peut-?tre lib?rerai-je ces marmots. J\\\'ai vraiment besoin de d?guster un met savoureux, trouve de quoi contenter ma faim ou je me rabats sur les enfants.');
INSERT INTO `npc_questions` VALUES (3443, '', '', '', '', 'Plat unique ? Y a Bougnette, mais personne sait faire. Sinon, Filtounga, tr?s rare. M?me gloutovore pas finir. Moi pas avoir recette. Vous demander Mouss Bouff. Lui avoir recette.');
INSERT INTO `npc_questions` VALUES (3444, '', '', '', '', 'Toi vouloir manger quelque chose ?');
INSERT INTO `npc_questions` VALUES (3445, '', '', '', '', 'La recette de la Filtounga ? Et pourquoi devrai-je vous donner ce livre ?');
INSERT INTO `npc_questions` VALUES (3446, '', '', '', '', 'Je veux bien vous croire, utilisez ma recette, mais ramenez-la moi une fois que vous aurez fini s\\\'il vous pla?t.');
INSERT INTO `npc_questions` VALUES (3447, '', '', '', '', 'La Filtounga est une recette un peu riche mais tellement d?licieuse.');
INSERT INTO `npc_questions` VALUES (3448, '', '', '', '', 'Vous avoir recette ? Ca bien ! Vous allez chercher ingr?dients, moi cuisiner.');
INSERT INTO `npc_questions` VALUES (3449, '', '', '', '', 'Moi avoir ingr?dients, moi pr?parer recette, toi attendre.');
INSERT INTO `npc_questions` VALUES (3450, '', '', '', '', 'Vous me rapportez mon livre, c\\\'est tr?s aimable ? vous.');
INSERT INTO `npc_questions` VALUES (3451, '', '', '', '', 'Hola, v\\\'la d\\\'la compagnie. Vu ton air, tu vas pas rester bien longtemps. \\nTu vois la porte, juste l? bas? Bon. Elle m?ne droit dehors. Hein? Non, non, moi je pr?f?re rester ici. C\\\'est sympa, on est nourri, log?... Quoi? Si je passe dans la porte? SI JE PASSE DANS LA PORTE? Tu veux que j\\\'te bouffe un bras? EVIDEMMENT que je passe dans la porte. C\\\'est par CHOIX que je reste ici. Et ne me regarde pas avec ces yeux moqueurs! RHAAA!');
INSERT INTO `npc_questions` VALUES (3452, '', '', '', '', 'Filtounga finie, vous mangez !');
INSERT INTO `npc_questions` VALUES (3453, '', '', '', '', 'Qu\\\'est-ce donc que ce plat ?trange... Mais c\\\'est tr?s fameux... *crunch*, *miam*, *burp*, *rooooooooooot*, d?lichieux, je n\\\'ai pas aussi bien mang? depuis... en fait, je ne me souviens pas avoir jamais d?gust? quelque chose d\\\'aussi bon. Je tiendrai parole mais que je ne les revois jamais dans les parages.');
INSERT INTO `npc_questions` VALUES (3454, '3049;3054', '', '', '0', 'Hey, qu\\\'est-ce que tu fais encore dans ma mine gamin ?  \\nToutes les mines m\\\'appartiennent ! \\nPour 50 kamas je peux t\\\'aider ? partir d\\\'ici, tu n\\\'as qu\\\'? prendre ce petit chariot, je vais le pousser un bon coup, et je t\\\'accompagnerai jusqu\\\'? la prochaine mine. \\nMais attention, parfois les aiguillages ne fonctionnent pas tr?s bien, et nous pouvons nous retrouver dans une autre mine ! \\nParfois, il arrive m?me que nous nous fassions attaquer par de terribles mineurs sombres. Si tu as des amis, je te conseille de leur demander de t\\\'accompagner on ne sait jamais ce qui pourrait arriver...');
INSERT INTO `npc_questions` VALUES (3455, '3055', '', '', '0', 'Tu ne me connais pas ? C\\\'est moi Feldz ! Le plus grand mineur ? l\\\'est d\\\'Amakna ! \\nJ\\\'ai ?t? gogorifi? 7 fois et je suis toujours l? ! \\nJ\\\'ai m?me gagn? pendant 12 ann?es cons?cutives, le concours de minage sans ?clairage avec mains et pieds li?s, j\\\'ai gagn? en minant avec les dents, heureusement que j\\\'avais une bonne r?serve de dentiers de Porkass. \\nJe suis la fiert? des Enutrofs ! \\nMa famille habite ces mines depuis au moins 21 g?n?rations, elles n\\\'ont presque plus de secret pour nous ! \\nJe me d?guise en mineur sombre pour passer inaper?u et qu\\\'ils me laissent tranquille...');
INSERT INTO `npc_questions` VALUES (3456, '', '', '', '', 'C\\\'est mon arri?re grand-p?re qui a le premier, commenc? ? installer un r?seau de rails entre les diff?rentes mines connues de la r?gion. \\nJ\\\'ai pass? un temps consid?rable ? les entretenir, et j\\\'ai pu constater qu\\\'il existe un nombre consid?rable de galeries encore inexplor?es... \\nMes anc?tres racontaient m?me qu\\\'il existait un village, cach? sous une des montagnes du continent, qui n\\\'?tait accessible qu\\\'? partir d\\\'une des vieilles mines, malheureusement aujourd\\\'hui introuvables. \\nMais je ne perds pas espoir, je finirai par percer ce myst?re, ? coups de pioche s\\\'il le faut !');
INSERT INTO `npc_questions` VALUES (3457, '3057;3058;3401;3402;3403;370', '', '', '0', 'O? veux-tu aller ?');
INSERT INTO `npc_questions` VALUES (3458, '3059', '', '', '0', 'Hey ! Toi, hips, non pas le Minotoror rose, toi, hips !');
INSERT INTO `npc_questions` VALUES (3459, '3060;3061', '', '', '0', 'Hips! Oui, tu as l\\\'air de descendre vers le Sud. Si tu reviens vers Astrub, pourras-tu me donner quelques renseignements sur ton voyage ? \\n');
INSERT INTO `npc_questions` VALUES (3460, '3062', '', '', '0', 'J\\\'aimerais que tu me dises, si les Bworks habitent toujours dans leur village et si la l?gende est vraie.\\n');
INSERT INTO `npc_questions` VALUES (3461, '3063;3064', '', '', '0', 'De celle qui dit que les Bworks poss?deraient une biblioth?que contenant des alambics g?ants permettant de faire de la bi?re de Bwork. Ils ont s?rement la recette quelque part. \\n');
INSERT INTO `npc_questions` VALUES (3462, '', '', '', '', 'Cette recette est trop dure ? r?aliser. Moi qui pensais devenir riche en brassant de la bi?re de Bwork, je crois que je vais me contenter de faire de l\\\'?levage de Pworks. \\n');
INSERT INTO `npc_questions` VALUES (3463, '', '', '', '', 'J\\\'ai besoin de cette recette pour monter ma brasserie. Cherche plus en profondeur.');
INSERT INTO `npc_questions` VALUES (3464, '', '', '', '', 'Distiller de la bi?re de Bwork ou tenir un ?levage de pworks, laquelle des deux professions me permettra de gagner des Kamas sans me salir ?');
INSERT INTO `npc_questions` VALUES (3465, '', '', '', '', 'Ye veu pa finir en krotte de Trooll...');
INSERT INTO `npc_questions` VALUES (3466, '', '', '', '', 'To? peur ti\\\'troollinet ? To? pas vrai champion ?');
INSERT INTO `npc_questions` VALUES (3467, '', '', '', '', 'To? kraser trool. To? brav !');
INSERT INTO `npc_questions` VALUES (3468, '', '', '', '', 'To? brav ?');
INSERT INTO `npc_questions` VALUES (3469, '', '', '', '', 'Bworks veulent nourrir snif snif Trooll avec Raxitik. Mo? pas snif snif vouloir, mo? avoir 19 minigobs ? nourrir snif...');
INSERT INTO `npc_questions` VALUES (3470, '', '', '', '', 'Fosse trooll par l?. Trooll balaize !');
INSERT INTO `npc_questions` VALUES (3471, '', '', '', '', 'Repasse me voir quand tu auras du temps. Si tu as aid? un gobelin, tu aideras s?rement volontiers un mage bwork.');
INSERT INTO `npc_questions` VALUES (3472, '', '', '', '', 'To? faible, to? pas pouvoir aider Raxitik, mo? devenir krotte de Trooll...');
INSERT INTO `npc_questions` VALUES (3473, '', '', '', '', 'Pas to?, mo? chercher tademuscles !');
INSERT INTO `npc_questions` VALUES (3474, '3068', '', '', '', 'Heps, heps, to?, venir, approche, approche.');
INSERT INTO `npc_questions` VALUES (3475, '', '', '', '', 'Bworks moins faire malin maintenant. Manufacture pas pour Gobelins. To? bon d?fenseur gobelins. Mo? donner kado.');
INSERT INTO `npc_questions` VALUES (3476, '', '', '', '', 'Brises os, r?pands cervelles, cr?ves yeux et tues tues tues Bworks !');
INSERT INTO `npc_questions` VALUES (3477, '', '', '', '', 'Gobelins pas vouloir finir en tapisserie ? la Manufacture.');
INSERT INTO `npc_questions` VALUES (3478, '3069', '', '', '', 'Mo? pas tigob, mo? grand chef gobelin !');
INSERT INTO `npc_questions` VALUES (3479, '3070;3071', '', '', '', 'Peuple gobelin opprim?, Bworks veulent mettre nous dans Manufacture pour faire tapisserie. Si to? r?pandre sang Bwork eux oublier nous. \\n');
INSERT INTO `npc_questions` VALUES (3480, '', '', '', '', 'Pnj(834) et Message(3479)');
INSERT INTO `npc_questions` VALUES (3481, '3072', '', '', '', 'Cavalerie Gob aider mo?, to? mourir et mo? vendre ta p? aux Bworks !!!');
INSERT INTO `npc_questions` VALUES (3482, '', '', '', '', 'Seul au monde, pov\\\'Krazybwork abandonn');
INSERT INTO `npc_questions` VALUES (3483, '', '', '', '', 'Allez, r?essayons, tapez plus fort cette fois !');
INSERT INTO `npc_questions` VALUES (3484, '', '', '', '', 'Que faites vous dans mon trou ? Vous aussi votre m?re est f?l?e ? La mienne, Bworkcelhaine m\\\'a jet? ici.');
INSERT INTO `npc_questions` VALUES (3485, '', '', '', '', 'Merci, c\\\'est parce que j\\\'ai mang? trop de Goblins Rouges pendant la bataille de Bworkdrift. J\\\'?tais dans le camp des Goblins Blancs.');
INSERT INTO `npc_questions` VALUES (3486, '', '', '', '', 'Seulement pour un Bwork, c\\\'est pour ?a que ces deux peuples cohabitent. C\\\'est la seule esp?ce que les Bworks n\\\'aiment pas d?vorer. Seul les mages Bworks en mangent au d?but de leur formation pour apprendre ? lire. Je r?ve toutes les nuits de cette bataille. Ma m?re,Bworkcelhaine, en avait assez de mes cris.');
INSERT INTO `npc_questions` VALUES (3487, '', '', '', '', 'La bataille de Bworkdrift fut une chaude affaire, huit jours ? patauger dans l\\\'sang des camarades, plus de 300 morts rien que dans mon r?giment, mon meilleur ami, le Kaptain Bluebitt a eu les yeux arrach?s par une bille de fronde. Mon adjoint, le Sergent Malbaret, a agonis? trois jours ? mes cot?s, les deux jambes coup?es nettes par une hache trooll...');
INSERT INTO `npc_questions` VALUES (3488, '', '', '', '', 'Notre Bworklonel Planbworksek a eu le ventre ouvert par un sortil?ge. Il a command? la charge les tripes ? l\\\'air. Son ordonnance les lui portait dans une bassine. De temps en temps... Ah, ah, ah... Le brave gobelin en laissait tomber un bout sur le sol, et le vieux... Ah, ah, ah... Lui passait un de ces savons.');
INSERT INTO `npc_questions` VALUES (3489, '', '', '', '', 'Ca c\\\'est la routine pour un Bwork, le plus dur ce fut de devoir manger du Goblin pour survivre car nos morts avaient d?j? ?t? d?vor?s par nos Troolls. Si vous pouviez me rendre d?bile ? nouveau, ce serait chouette. Je vous offrirais les bottes Gobtroteurs de feu Planbworksek. \\n \\n');
INSERT INTO `npc_questions` VALUES (3490, '', '', '', '', 'Bonne id?e ! Cependant, je dois me d?fendre, mon honneur de v?t?ran Bwork ne pourrait souffrir que je ne r?plique pas.');
INSERT INTO `npc_questions` VALUES (3491, '', '', '', '', 'Mo? mal tet?, *baille en se frottant le cr?ne* mo? chercher m?man.');
INSERT INTO `npc_questions` VALUES (3492, '', '', '', '', 'Mo? ?tre paxifik, si to? pas d\\\'accord mo? frapper to? pour t\\\'expliquer !');
INSERT INTO `npc_questions` VALUES (3493, '', '', '', '', 'To? vouloir encore prendre une le?on ? Baaaaaston !!!');
INSERT INTO `npc_questions` VALUES (3494, '', '', '', '', 'To? gagner, to? paxifik.');
INSERT INTO `npc_questions` VALUES (3495, '3080;3081', '', '', '0', 'Zog Zog ? to');
INSERT INTO `npc_questions` VALUES (3496, '3083;3084', '', '', '0', 'Bworkidais ?tre paxifik.');
INSERT INTO `npc_questions` VALUES (3497, '308', '', '', '0', 'To? pas croire ? To? provoker ?');
INSERT INTO `npc_questions` VALUES (3498, '308', '', '', '0', 'To? grande gueule !');
INSERT INTO `npc_questions` VALUES (3499, '308', '', '', '0', 'Mo? pas aimer grande gueule.');
INSERT INTO `npc_questions` VALUES (3500, '308', '', '', '0', 'Bworkidais rameuter Bworks pas paxifiks. To? morfler, baaaaaston !!!');
INSERT INTO `npc_questions` VALUES (3501, '', '', '', '', 'To? donner II, III ou IIII (montre ses doigts crasseux) pisse Bwork, mo? donner bon miam miam.');
INSERT INTO `npc_questions` VALUES (3502, '', '', '', '', 'G?trooll et gratrooll contre pleins (remue ses doigts et ses orteils crasseux) de pisse Bwork !');
INSERT INTO `npc_questions` VALUES (3503, '', '', '', '', 'To? pa avoir pisse Bwork, mo? pas troker !');
INSERT INTO `npc_questions` VALUES (3504, '', '', '', '', 'Seul, je suis d?sesp?r?ment seul au milieu des brutes et des chasseurs de brutes.');
INSERT INTO `npc_questions` VALUES (3505, '', '', '', '', 'Seul, je suis d?sesp?r?ment seul au milieu des brutes et des chasseurs de brutes.');
INSERT INTO `npc_questions` VALUES (3506, '', '', '', '', 'Toi seul peut sortir trouver ce qui me manque, je suis cloitr? du fait de mon peuple et de mon cerveau surd?velopp?. \\n');
INSERT INTO `npc_questions` VALUES (3507, '', '', '', '', 'Comme tu le sais, je suis le plus grand mage des Bworks. Etant l\\\'unique ?tre dou? de cervelle dans cette r?gion, je me sens seul...');
INSERT INTO `npc_questions` VALUES (3508, '', '', '', '', 'Je ne peux abandonner mon peuple et dehors les gens frappent les Bworks avant de leur adresser la parole. \\nJ\\\'ai discut? avec Bworkidais le paxifik, mais sa susceptibilit? est trop violente et  avec Crazybwork qui ne fait que ressasser ses anciennes batailles.');
INSERT INTO `npc_questions` VALUES (3509, '', '', '', '', 'J\\\'ai d?j? essay?. Il r?pandait des krottes partout, j\\\'ai du le mettre dans une fosse o? on le nourrit de Gobelins. J\\\'ai une autre id?e, et tu peux m\\\'aider.');
INSERT INTO `npc_questions` VALUES (3510, '', '', '', '', 'Je vais assembler une cr?ature intelligente qui r?pondra ? tous mes crit?res.');
INSERT INTO `npc_questions` VALUES (3511, '', '', '', '', 'Pour commencer : de la peau de gobelin, des cheveux de Sadida et des os de Trooll. Voil? un scalpel qui te permettra de d?sosser un Trooll. Il y en a dans le donjon d\\\'? c?t? ou dans la fosse. \\n');
INSERT INTO `npc_questions` VALUES (3512, '', '', '', '', 'Alors ?');
INSERT INTO `npc_questions` VALUES (3513, '', '', '', '', 'Alors maintenant, les produits frais : le coeur de Bworkcelhaine, de la cervelle de Vampire, un oeil de Kanigrou et de la boue de Boo. N\\\'oublie pas d\\\'utiliser le scalpel ! \\n');
INSERT INTO `npc_questions` VALUES (3514, '', '', '', '', 'Hum, cela sent l\\\'organe frais !');
INSERT INTO `npc_questions` VALUES (3515, '', '', '', '', 'Il manque une chose, c\\\'est un peu d?licat, mais je crois que c\\\'est n?cessaire, voire vital en fait !');
INSERT INTO `npc_questions` VALUES (3516, '', '', '', '', 'Hum hum, comment dire, voyons, hum, hum, je dirais une Moumoule (sans frite). Il y en a toujours une qui se pr?lasse sur les plages de la Mer d\\\'Asse.');
INSERT INTO `npc_questions` VALUES (3517, '', '', '', '', 'Merci merci, d?s que je d?couvrirai comment lui donner la vie, je serais le plus heureux des Bworks. J\\\'esp?re que toute cette viande ne va pas pourrir en attendant !');
INSERT INTO `npc_questions` VALUES (3518, '', '', '', '', 'Mo? vouloir manger ton coeur, pas le mien !');
INSERT INTO `npc_questions` VALUES (3519, '', '', '', '', 'Hum hum hum miam miam, mo? d?vorer ton coeur !!!');
INSERT INTO `npc_questions` VALUES (3520, '', '', '', '', 'Mo? devenir magobelin, mo? trop fort !');
INSERT INTO `npc_questions` VALUES (3521, '', '', '', '', 'Mo? premier magobelin !');
INSERT INTO `npc_questions` VALUES (3522, '', '', '', '', 'Le sort Dem?h?t !');
INSERT INTO `npc_questions` VALUES (3523, '', '', '', '', 'Si gobelin devenir magicien, gobelin plus ?tre esclave des Bworks !');
INSERT INTO `npc_questions` VALUES (3524, '', '', '', '', 'Titi doit devenir premier magobelin.');
INSERT INTO `npc_questions` VALUES (3525, '', '', '', '', 'Mon fils tr?s fort ! Premier magegobelin.');
INSERT INTO `npc_questions` VALUES (3526, '', '', '', '', 'Am?ne G?trooll, Gratrooll, la cape rouge et Titi te suivra. Guide le ? Bworknroll.');
INSERT INTO `npc_questions` VALUES (3527, '', '', '', '', 'To? traverser village des Bworks et ?tre vivant ! To? fort ! To? aider gobelin.');
INSERT INTO `npc_questions` VALUES (3528, '', '', '', '', 'Fils a?n?, Gobincarnat devenir premier mage gobelin. Donne G?trooll, Gratrooll, une cape rouge et mon Titi ? Bworknroll. Il vit dans garde miam miam des rats.');
INSERT INTO `npc_questions` VALUES (3529, '', '', '', '', 'Tu voyages avec un gobelin beau ? kroker !');
INSERT INTO `npc_questions` VALUES (3530, '', '', '', '', 'Voici des Kamas, je vais le fourrer avec le g?trooll et le cuire dans la gratrooll avant de le d?vorer ? pleine dents, puis je me nettoierais les babines dans cette cape ? cause de tout ce bon gras qui tache.');
INSERT INTO `npc_questions` VALUES (3531, '', '', '', '', 'Pnj(841) et Message(3529)');
INSERT INTO `npc_questions` VALUES (3532, '', '', '', '', 'Un disciple gobelin ? Pourquoi pas ! Je vais le former rapidement. De toute mani?re son cerveau ne devrait pas accepter beaucoup de sorts. ');
INSERT INTO `npc_questions` VALUES (3533, '', '', '', '', 'Repasse me voir quand tu auras du temps. Si tu as aid? un gobelin, tu aideras s?rement volontiers un mage bwork.');
INSERT INTO `npc_questions` VALUES (3534, '', '', '', '', 'Attention, nous allons ?tre attaqu?s par des mineurs Sombres, je le sens, ils arrivent, ils sont autour de nous ! \\nD?p?che-toi de les mettre hors d\\\'?tat de nuire et remonte dans le chariot !');
INSERT INTO `npc_questions` VALUES (3535, '3113', '', '', '0', 'Bravo, tu as r?ussi ? te d?barrasser d\\\'eux ! \\nD?p?che toi de monter dans le chariot, il n\\\'y a plus qu\\\'? suivre les rails.');
INSERT INTO `npc_questions` VALUES (3536, '3119;311', '', '', '0', 'Mmmm, un fid?le de Cr?. Tes talents s\\\'expriment ? distance. Un bon arc, une ligne de tir et tes ennemis sont vite embroch?s. Tu vas adorer ?a. Pour toi, j\\\'ai quelque chose de bien pr?cis.');
INSERT INTO `npc_questions` VALUES (3537, '', '', '', '0', 'Ah un disciple Eniripsa ! Je suis heureux de voir que certains suivent la voie difficile de la gu?rison. Ta force ne vient pas de ta capacit? ? causer une vaste destruction parmi tes adversaires. Je vais donc te confier quelque chose dans tes cordes. Bonne chance ? toi, la voie que tu suis est extr?mement gratifiante.');
INSERT INTO `npc_questions` VALUES (3538, '3122;313', '', '', '0', 'Salut ? toi ami Enutrof. Les combats ne sont pas ton fort. Quand tu auras m?ri et acquis la force de ton dieu tu seras redoutable mais d\\\'ici l?, voici une t?che que tu peux accomplir pour moi.');
INSERT INTO `npc_questions` VALUES (3539, '', '', '', '', 'Un Feca ! la force tranquille de la sagesse. Je respecte les talents protecteurs de ton dieu, ils sont impressionnants. Comme tu ne les ma?trises pas encore tr?s bien je te propose quelque chose qui va t\\\'aider ? t\\\'aguerrir.');
INSERT INTO `npc_questions` VALUES (3540, '3135;3124', '', 'QE!172', '3634', 'Tiens tiens, un combattant Iop. Ce n\\\'est pas ce qui manque ces temps-ci. A croire que la voie du guerrier soit de mode. Tant mieux, j\\\'ai tellement de choses pour un as du corps ? corps.');
INSERT INTO `npc_questions` VALUES (3541, '', '', '', '', 'Bonjour jeune Ecaflip. Je sais que vous autres, Ecaflip, ?tes d?sireux de partir ? l\\\'aventure pour tenter votre chance. Si tu aimes mettre ta vie dans la balance, j\\\'ai quelque chose pour toi. Es-tu pr?t ? prendre le risque ?');
INSERT INTO `npc_questions` VALUES (3542, '3137;3126', '', '', '0', 'Xelor, ma?tre du temps et cr?ateur du calendrier d\\\'Amakna. C\\\'est une voie difficile que celle que tu as choisie mais valorisante pour ceux qui s\\\'en donnent la peine. Je vais t\\\'aider et te donner de quoi entra?ner tes toutes r?centes capacit?s.');
INSERT INTO `npc_questions` VALUES (3543, '', '', '', '', 'Bonjour Pandawa ! Attends montre moi tes yeux ...oui, pas tr?s sobre encore, parfait. Dans cet ?tat tu seras certainement tr?s efficace dans les combats que tu vas mener. Prends une bonne hache, quelques bouteilles d\\\'alcool fort et va combattre.');
INSERT INTO `npc_questions` VALUES (3544, '3139;312', '', '', '0', 'Ah un Sadida, un futur ma?tre de la cr?ation de cr?atures anim?es capables de grands exploits. J\\\'ai besoin de quelqu\\\'un comme toi. Utilise ta magie cr?atrice pour invoquer de puissantes marionnettes et abattre les cr?atures qui infestent la r?gion.');
INSERT INTO `npc_questions` VALUES (3545, '', '', '', '', 'Salut, tu es venu seul, jeune Osamodas ? Etrange, tes semblables se prom?nent souvent avec quantit? de cr?atures qu\\\'ils invoquent et contr?lent. Peu importe, ?a ira pour ce que je vais te demander. Enfin, pense ? invoquer quelques petites bestioles quand m?me.');
INSERT INTO `npc_questions` VALUES (3546, '3141;313', '', '', '0', 'Salut ! Oh pardon, je ne voulais pas te blesser ... ah ah ah pardon pour cette mauvaise blague. Je sais que vous autres Sacrieur ?tes plut?t du genre ? appliquer la loi du talion ... en plus s?v?re. C\\\'est bien, j\\\'ai besoin de quelqu\\\'un qui est pr?t ? prendre des coups et ? en donner tout autant.');
INSERT INTO `npc_questions` VALUES (3547, '', '', '', '', 'Que les ombres te prot?gent Sram ! C\\\'est bien ainsi que vous vous saluez ? Il est vrai que vous pr?f?rez agir dans l\\\'ombre et pi?ger vos adversaires ou les leurrer de fa?on tr?s subtile. C\\\'est exactement une personne comme toi qu\\\'il me faut.');
INSERT INTO `npc_questions` VALUES (3548, '', '', '', '', 'Tu vois que ce n\\\'?tait pas si difficile. N\\\'h?site pas ? t\\\'entra?ner, seuls les meilleurs re?oivent les faveurs de leur dieu.');
INSERT INTO `npc_questions` VALUES (3549, '', '', '', '', 'L\\\'uniforme me manque. Je pourrais encore aller vadrouiller avec les camarades.');
INSERT INTO `npc_questions` VALUES (3550, '3114', '', '', '0', 'To? qui a le sang de centaines de monstres sur les mains. Mo? avoir besoin de tes talents.');
INSERT INTO `npc_questions` VALUES (3551, '3116;3115', '', '', '0', 'To? donner mo? p? de gobs ! Mo? refaire tapisserie de hutte de harem ? mo');
INSERT INTO `npc_questions` VALUES (3552, '3117', '', '', '', 'To? pas content ? Mo? appeler femelles bworks, to? discuter tapisserie avec leurs haches !');
INSERT INTO `npc_questions` VALUES (3553, '', '', '', '', 'To? trop faible, to? pas pouvoir ?corcher gobs !');
INSERT INTO `npc_questions` VALUES (3554, '', '', '', '', 'Merci, femelles seront contentes.');
INSERT INTO `npc_questions` VALUES (3555, '', '', '', '', 'P? vertes faire belles tapisseries.');
INSERT INTO `npc_questions` VALUES (3556, '', '', '', '', 'To? taper gobelin to? ramener p? ? mo');
INSERT INTO `npc_questions` VALUES (3557, '3120', '', '', '0', 'Rien de difficile rassure-toi. Il s\\\'agit d\\\'aller nettoyer la r?gion de ses cr?atures parasites. J\\\'ai not? dans ton journal ce que tu dois faire. Bonne chasse.');
INSERT INTO `npc_questions` VALUES (3558, '', '', '', '', 'Pnj(843) et Message(3537)');
INSERT INTO `npc_questions` VALUES (3559, '', '', '', '', 'To? d?p?cher trouver kd? !');
INSERT INTO `npc_questions` VALUES (3560, '', '', '', '', 'Mo? ?tre chef et to? pa !');
INSERT INTO `npc_questions` VALUES (3561, '', '', '', '', 'Chef pas parler avec gringalet !');
INSERT INTO `npc_questions` VALUES (3562, '3143;3144', '', '', '', 'C? mo? le chef des Bworks ! To? donner kd?, mo? chef !');
INSERT INTO `npc_questions` VALUES (3563, '3146;3148', '', '', '', 'So? sympa, si mo? pa avoir kd?, femelle pas contente car dire mo? pas vrai chef.');
INSERT INTO `npc_questions` VALUES (3564, '3145', '', '', '', 'Panoplie Prespic et une baguette.');
INSERT INTO `npc_questions` VALUES (3565, '3147', '', '', '', 'Mo? savoir, mo? offrir ta tet? !');
INSERT INTO `npc_questions` VALUES (3566, '', '', '', '', 'Ahahaha moi avoir b? kd?, femelle admirer mo? !');
INSERT INTO `npc_questions` VALUES (3567, '3151;315', '', '', '0', 'Tu sais, quand tu vois le drapeau c\\\'est le pays qui se tient derri?re, enfin pas derri?re le drapeau, c\\\'est trop petit, mais il se tient derri?re, tu vois ? Moi j\\\'ai besoin du drapeau, pas pour me tenir derri?re, je ne suis pas un l?che.');
INSERT INTO `npc_questions` VALUES (3568, '3152;315', '', '', '0', 'C\\\'est simple, le drapeau c\\\'est un peu comme un symbole, mais en tissu, alors il faut que tu me trouves du tissu de symbole, tu vois ?');
INSERT INTO `npc_questions` VALUES (3569, '315', '', '', '0', 'Ce qu\\\'il faut pour construire un symbole bien s?r, et surtout un drapeau mais c\\\'est pareil, il va falloir que je couse un symbole en drapeau.');
INSERT INTO `npc_questions` VALUES (3570, '', '', '', '', 'Quand je me r?veille, parfois, je suis toujours endormi, et ?a dure longtemps. Je parle, je marche, je travaille, mais je suis endormi. Comme ?a je me repose. C\\\'est un talent, il n\\\'y a que moi qui sais faire ?a, je suis tr?s fort, je suis Jic?, je suis Aouaire, m?me endormi, tu vois ?');
INSERT INTO `npc_questions` VALUES (3571, '', '', '', '', 'Tu me rapportes de la laine et moi je vois une victoire. La laine, c\\\'est la victoire, tu saisis ? Et pourtant, tu me donnes la laine mais tu gardes la victoire, car la laine, c\\\'est la victoire mais elle ne contient pas la victoire, c\\\'est toi qui gardes la victoire, m?me si tu me donnes la laine, tu comprends ? Tiens, va voir Arietta Fiolle, elle t\\\'aidera ? te fortifier.');
INSERT INTO `npc_questions` VALUES (3572, '', '', '', '', 'Tu me rapportes de la laine et moi je vois une victoire. La laine c\\\'est la victoire, tu saisis ? Et pourtant, tu me donnes la laine mais tu gardes la victoire, car la laine c\\\'est la victoire mais elle ne contient pas la victoire, c\\\'est toi qui garde la victoire, m?me si tu me donnes la laine, tu comprends ? Tiens, va voir Arietta Fiolle, elle t\\\'aidera ? te fortifier.');
INSERT INTO `npc_questions` VALUES (3573, '3156', '', '', '0', 'Un vaillant guerrier, voil? ce qu\\\'il me faut. Il faut d?barrasser la r?gion des cr?atures qui l\\\'infestent. Je l\\\'aurais bien fait moi-m?me mais j\\\'ai tout plein de choses ? faire. Tu sais, des trucs quoi, et puis d\\\'autres ici, plein ...');
INSERT INTO `npc_questions` VALUES (3574, '3162;316', '', '', '0', 'Tu veux quoi la donzelle, du travail ? Bien, d?p?che toi de nous d?barrasser des cr?atures aux alentours, et que ?a saute, je n\\\'ai pas de temps ? perdre avec des tire-au-flanc.');
INSERT INTO `npc_questions` VALUES (3575, '3159;316', '', '', '0', 'Oui, j\\\'aime le courage, et les puissants guerriers. Moi aussi, je suis tr?s courageuse, je n\\\'ai pas peur de ces horribles cr?atures gluantes, rampantes, grimpantes, luisantes et sales qui tra?nent alentours. Je r?compenserai personnellement ... l\\\'ardeur ... que tu montreras. Montre moi ton ardeur.');
INSERT INTO `npc_questions` VALUES (3576, '3163;316', '', '', '0', 'Oh mais oui tu seras pay?e, ne t\\\'en fais pas pour ?a. Enfin, ?a d?pend de ce que tu accompliras.');
INSERT INTO `npc_questions` VALUES (3577, '', '', '', '', 'Pas mal du tout, ton courage ?gale presque le mien. Voil? ta prime.');
INSERT INTO `npc_questions` VALUES (3578, '', '', '', '', 'Certains doutent de mon courage, pourtant je n\\\'ai jamais fui un seul combat. Bon c\\\'est vrai que je n\\\'en ai pas fait beaucoup ... Et c\\\'est gr?ce ? mes talents que je suis l?, c\\\'est ce que dit le capitaine des gardes, que j\\\'ai plein de talents !');
INSERT INTO `npc_questions` VALUES (3579, '', '', '', '', 'Fredonne,  \\nGobriel, ils br?lent ton esprit \\nLeur haine ?trangle ta vie \\nEt Bonta, devient comme un espoir \\nCar dans leurs mains tu meurs chaque soir !');
INSERT INTO `npc_questions` VALUES (3580, '', '', '', '', 'To? promis aider mo');
INSERT INTO `npc_questions` VALUES (3581, '316', '', '', '0', 'Mo? pas malade.');
INSERT INTO `npc_questions` VALUES (3582, '316', '', '', '0', 'Pas blanc, albinos ! Autres Gobelins dirent pou blanc ou globule. Mo? avoir honte, en plus mo? gentil. Eux jeter pierres ? mo');
INSERT INTO `npc_questions` VALUES (3583, '316', '', '', '0', 'Oui. Mo? vouloir devenir ange et voler pour Bonta.');
INSERT INTO `npc_questions` VALUES (3584, '', '', '', '', 'Pnj(845) et Message(3583)');
INSERT INTO `npc_questions` VALUES (3585, '', '', '', '', 'Merci mo? rester ici quand m?me. Grand mage Bworknroll donner Trooll apprivois? ? mo?. Gobelins plus jeter pierres !');
INSERT INTO `npc_questions` VALUES (3586, '', '', '', '', 'Mo? r?fl?chir situation et mo? l\\\'accepter.');
INSERT INTO `npc_questions` VALUES (3587, '', '', '', '', 'Mo? appeler kopain Trool !');
INSERT INTO `npc_questions` VALUES (3588, '', '', '', '', 'Bonjour, je n\\\'ai pas vraiment le temps de discuter, si vous voulez quelque chose, allez voir mon contrema?tre.');
INSERT INTO `npc_questions` VALUES (3589, '3174;317', '', '', '0', 'Que sais-tu faire ? couper du bois ? C\\\'est bien ?a. Bon j\\\'ai besoin de pas mal de planches pour r?parer le toit de la grange ou renforcer les enclos. Va abattre quelques bons plans d\\\'arbres dans la for?t.');
INSERT INTO `npc_questions` VALUES (3590, '3175;317', '', '', '0', 'Un bon paysan me dis-tu ? Et bien on va voir cela. On a une grosse commande de bl?, il y a beaucoup de bouches ? nourrir depuis quelques temps. Ca arrange mes affaires mais il faut trouver la main-d\\\'?uvre. Va faucher quelques ares de bl');
INSERT INTO `npc_questions` VALUES (3591, '3176;318', '', '', '0', 'Un p?cheur ? Ma foi, ?a nous changera de l\\\'ordinaire. On est nombreux alors ne tra?ne pas si tu veux attraper suffisamment de poissons pour tout le monde.');
INSERT INTO `npc_questions` VALUES (3592, '3177;318', '', '', '0', 'Mmmm tu joues avec des fioles et toutes sortes de mixtures ? Je n\\\'ai pas besoin de ?a ici. En revanche, si tu veux bien aller cueillir quelques fleurs de lin pour qu\\\'on puisse les ?grener et faire du pain ?a me rendrait bien service.');
INSERT INTO `npc_questions` VALUES (3593, '', '', '', '', 'Bien, va voir mon contrema?tre, il va te pr?ciser ce que tu dois faire.');
INSERT INTO `npc_questions` VALUES (3594, '', '', '', '', 'Je serai heureux de te trouver du travail mais tu peux gagner plus de kamas sur Amakna. Il est peut ?tre temps pour toi de quitter Incarnam.');
INSERT INTO `npc_questions` VALUES (3595, '', '', '', '', 'Je me krokrais bien un Gob !');
INSERT INTO `npc_questions` VALUES (3596, '3182;3183', '', '', '0', 'C\\\'est mon patron qui vous envoie ? Il est un peu stress? mais sympa. Qu\\\'est ce que je peux faire pour vous ?');
INSERT INTO `npc_questions` VALUES (3597, '3184;3185;3186;3187;3188', '', '', '0', 'C\\\'est exact, je montre les bases ? tous nos ouvriers. Il y a beaucoup de choses ? faire dans cette ferme. Dites moi, qu\\\'est ce qui vous int?resse ?');
INSERT INTO `npc_questions` VALUES (3598, '3189', '', '', '0', 'B?cheron ? Bien, ?a demande un ?il avis? et l\\\'envie de voyager. Les bons arbres sont rares et il faut prendre garde ? pr?server les for?ts. Ce m?tier est ? la base de nombreux artisanats, qu\\\'est ce qui n\\\'est pas ? base de bois ? Donc, nous sommes d\\\'accord, nous pouvons d?buter ?');
INSERT INTO `npc_questions` VALUES (3599, '3190', '', '', '0', 'La base de toute soci?t? est une agriculture solide qui repose sur les paysans. Semer, r?colter, entretenir et bien d\\\'autres t?ches sont les responsabilit?s du paysan. En plus de nourrir de nombreuses personnes, le paysan entretient la terre, c\\\'est un noble m?tier. Je commence par vous apprendre comment faucher les c?r?ales ?');
INSERT INTO `npc_questions` VALUES (3600, '3191', '', '', '0', 'Vous ?tes plut?t du genre patient vous non ? En tout cas vous allez le devenir si vous pers?v?rez. C\\\'est un m?tier extr?mement utile pour se nourrir tout en se d?tendant. Je vous donne une canne ? p?che et quelques conseils pour bien d?buter ?');
INSERT INTO `npc_questions` VALUES (3601, '3192', '', '', '0', 'Oui bien s?r, mais ne nous emballons pas, avant de pouvoir concocter de puissantes potions, il faut bien r?colter les ingr?dients. Je vous montre comment faire ?');
INSERT INTO `npc_questions` VALUES (3602, '', '', '', '', 'Il existe de nombreux m?tiers, cependant, je ne connais que ceux-ci. Pour apprendre les autres, il vous faudra parcourir le vaste monde et trouver d\\\'autres ma?tres. Il y en a plusieurs de r?put?s ? Astrub.');
INSERT INTO `npc_questions` VALUES (3603, '', '', '', '', 'Voil?, vous savez ce qu\\\'il faut savoir pour bien commencer, allez voir le patron qui va vous donner un travail.');
INSERT INTO `npc_questions` VALUES (3604, '', '', '', '', 'Le travail c\\\'est la sant? ... ne rien faire c\\\'est la conserver. Le propre du travail c\\\'est d\\\'?tre forc');
INSERT INTO `npc_questions` VALUES (3605, '', '', '', '', 'Bon travail, tu es un ouvrier prometteur, voici ta paie.');
INSERT INTO `npc_questions` VALUES (3606, '3193;319', '', '', '0', 'Alors comme ?a tu nous as ramen? quelques mat?riaux ? Voyons voir ce qu\\\'on peut en tirer. Oui, bien bien. Bon utilise les outils pour travailler tout ?a.');
INSERT INTO `npc_questions` VALUES (3607, '319', '', '', '0', 'Comment ?a marche, mais c\\\'est pourtant simple bon sang. Tu utilises l\\\'atelier ad?quat et tu y places les mat?riaux. Quand tu as suffisamment pour obtenir quelque chose, le moniteur te l\\\'indique. Tu n\\\'as plus qu\\\'? abaisser le levier pour combiner tout ?a. Prends ton outil de travail en mains sinon tu ne pourras pas te servir de l\\\'atelier.');
INSERT INTO `npc_questions` VALUES (3608, '', '', '', '', 'Ca y est tu as fini ? J\\\'imagine que oui si tu viens me parler. Beau travail, si tu as encore le temps de travailler pour moi alors n\\\'h?site pas ? repasser me voir. Une chose toutefois, je ne fournis pas les mat?riaux.');
INSERT INTO `npc_questions` VALUES (3609, '', '', '', '', 'Ce n\\\'est qu\\\'un petit village ici, quand je pense ? tous les ateliers qui existent sur Amakna.');
INSERT INTO `npc_questions` VALUES (3610, '', '', '', '', 'Pfff... T\\\'es encore plus faible que mo? ! Passe ton chemin.');
INSERT INTO `npc_questions` VALUES (3611, '319', '', '', '0', 'Mo? vibrer pour elle !');
INSERT INTO `npc_questions` VALUES (3612, '3198;319', '', '', '0', 'La belle Gobrose, esclave de Bworkcine. Peux-tu la lib?rer ?');
INSERT INTO `npc_questions` VALUES (3613, '', '', '', '', 'Gobrose enferm?e sous campement Bwork.');
INSERT INTO `npc_questions` VALUES (3614, '', '', '', '', 'Gobrose pas venir. Suis vert ! Tue ses pious pr?f?r?s, elle viendra !');
INSERT INTO `npc_questions` VALUES (3615, '', '', '', '', 'Gobmichet rester seul, destin difficile. Plus d\\\'?nergie pour vivre. Mon c?ur ne vibre plus. Adieu. ');
INSERT INTO `npc_questions` VALUES (3616, '', '', '', '', 'To? trouver Gobrose.');
INSERT INTO `npc_questions` VALUES (3617, '', '', '', '', 'Mon coeur vibre, vibre, vibre.');
INSERT INTO `npc_questions` VALUES (3618, '', '', '', '', 'Avec plumes pious moi remplir panse de bi?re !');
INSERT INTO `npc_questions` VALUES (3619, '', '', '', '', 'To? dans tani?re de Bworkcine ! To? avoir essuyer pieds avant entrer ?');
INSERT INTO `npc_questions` VALUES (3620, '', '', '', '', 'To? vouloir plumes ? Mo? ?changer contre pisse bwork.');
INSERT INTO `npc_questions` VALUES (3621, '', '', '', '', 'To? vouloir Gobrose ? To? goblophile ?');
INSERT INTO `npc_questions` VALUES (3622, '', '', '', '', 'Poids ? moi en pisse bwork !');
INSERT INTO `npc_questions` VALUES (3623, '', '', '', '', 'To? pouvoir prendre Gobrose.');
INSERT INTO `npc_questions` VALUES (3624, '', '', '', '', 'To? faire vite, mo? grossir vite !');
INSERT INTO `npc_questions` VALUES (3625, '', '', '', '', 'To? vouloir pi?tiner pious avec tes chausses ? To? donner oeufs de pious !');
INSERT INTO `npc_questions` VALUES (3626, '', '', '', '', 'To? pouvoir massacrer pious.');
INSERT INTO `npc_questions` VALUES (3627, '', '', '', '', 'Oeufs contre Pious. Gobelins aiment manger ces oeufs. Seule nourriture facile ? voler pour eux !');
INSERT INTO `npc_questions` VALUES (3628, '', '', '', '', 'Battu par pious, la honte. Essaie encore !');
INSERT INTO `npc_questions` VALUES (3629, '3205;320', '', '', '0', 'Comme ?a il semble que tu saches manier une arme. Un bretteur peut se faire une solde honn?te dans le coin.');
INSERT INTO `npc_questions` VALUES (3630, '', '', '', '', 'Mo? pas vouloir aller avec to?. Mo? pr?f?rer plumes pious ? Gobmichet.');
INSERT INTO `npc_questions` VALUES (3631, '', '', '', '', 'To? tuer pious pour Gobmichet. Mo? pas aimer mes pairs verts. Mo? les pr?f?rer gris.');
INSERT INTO `npc_questions` VALUES (3632, '', '', '', '', 'Un jour mon gob viendra et il me sauvera.');
INSERT INTO `npc_questions` VALUES (3633, '320', '', '', '0', 'Ici, tu n\\\'auras pas de kamas, mais je pourrai t\\\'apprendre quelques astuces qui te seront utiles plus tard.');
INSERT INTO `npc_questions` VALUES (3634, '', '', 'QT!172', '3549', 'Pers?v?re, tu peux y arriver. Si tu veux une arme, va voir Anta Brok au sud d\\\'ici, elle a toujours un tas de chose ? ?changer.');
INSERT INTO `npc_questions` VALUES (3635, '', '', '', '', 'De retour Bleusaille ? Les gardes font leur travail, pas normal, je les connais ces fils de Bwork !');
INSERT INTO `npc_questions` VALUES (3636, '', '', '', '0', 'Par les moustaches des rats noirs, que font ces fichus gardes ? Eh toi, va inspecter les postes des sentinelles, v?rifie qu\\\'elles veillent toujours au grain. Les d?mons de Rushu peuvent surgir ? tout instant !');
INSERT INTO `npc_questions` VALUES (3637, '3240;323', '', '', '0', 'Encore toi ! On dirait que tu en veux. On va peut ?tre faire quelque chose de toi finalement. Mais ne t\\\'imagine pas qu\\\'on sera amis ! Tu n\\\'es l? que pour ob?ir aux ordres, et les ordres c\\\'est moi qui les donne, compris ?!');
INSERT INTO `npc_questions` VALUES (3638, '', '', '', '', 'Rien ? signaler !? C\\\'est qu\\\'on va finir par rouiller dans ce trou !');
INSERT INTO `npc_questions` VALUES (3639, '', '', '', '', 'Ca c\\\'est ma pelle ? deux mains. Y en a beaucoup des comme ?a, mais elle, c\\\'est la mienne. Ma pelle c\\\'est ma meilleur amie. Elle, c\\\'est ma vie. Il faut que je ma?trise ma pelle comme il faut que je ma?trise ma vie. Car sans moi, ma pelle ne sert ? rien. Et sans ma pelle, je ne sers plus ? rien. Je fais le voeu de mettre dans le mille. J\\\'ai plus de pr?cision que mon ennemi qui essaie de m\\\'abattre. C\\\'est moi qui dois l\\\'abattre avant qu\\\'il ne m\\\'abatte. Et je le ferai. Ma pelle et moi-m?me sommes les d?fenseurs d\\\'Amakna. Nous sommes ma?tres de nos ennemis. A nous deux nous sommes les sauveurs de ma vie.');
INSERT INTO `npc_questions` VALUES (3640, '', '', '', '', 'Une forte t?te hein ? Ca fait longtemps que j\\\'en ai pas mat? une ! Ecoute p\\\'tit gars, t\\\'es un bleu, tu vas faire ce que je te dis ou je vais transformer ta vie en le pire enfer que tu puisses imaginer. Quand tu seras pass? entre mes mains, tu ne te souviendras m?me pas de ton nom, tu ne seras qu\\\'une masse douloureuse et informe de chair implorant ma piti? ! Pars avant que je ne m\\\'?nerve r?ellement.');
INSERT INTO `npc_questions` VALUES (3641, '', '', '', '', 'Mais c\\\'est qu\\\'elle se moque de moi la d?butante ! Je vais te dresser moi ! Tu vas filer droit je te le dis, tu vas cracher du sang et pleurer comme la petite fille que tu es !');
INSERT INTO `npc_questions` VALUES (3642, '', '', '', '', 'Parfait, fais le tour de la ville et va demander aux habitants si tout va bien. J\\\'attends ton rapport !');
INSERT INTO `npc_questions` VALUES (3643, '', '', '', '', 'J\\\'ai toute une th?orie concernant l\\\'impact de la migration des ?ponges dans la mer d\\\'Asse, la longueur des ?gouts d\\\'Astrub et sur l\\\'?paisseur des sourcils des Enutrofs.');
INSERT INTO `npc_questions` VALUES (3644, '', '', 'QEt=745', '3673', 'Arr?te de me faire perdre du temps en bavardant. Il se trouve ? deux pas.');
INSERT INTO `npc_questions` VALUES (3645, '', '', '', '', 'O? vais-je trouver de bons ouvriers ?');
INSERT INTO `npc_questions` VALUES (3646, '3214;3215;3213', '', 'QE!181', '3644', 'Tiens bonjour, je suis bien content de voir un nouveau visage ! Je me pr?sente, je me nomme Str\\\'huit. C\\\'est un pr?nom peu courant dans le coin. Bien que je me souvienne avoir crois?, un jour, un Sadida portant ce pr?nom. Nous n\\\'avons gu?re discut? mais je l\\\'ai trouv? tout de suite sympathique. Malheureusement, nous avons d? nous quitter car il avait une sieste ? faire. Ca me rappelle une histoire cocasse qui m\\\'est arriv?e pendant que je faisais la sieste, il y a fort longtemps. Voulez-vous que je vous conte cette histoire ?');
INSERT INTO `npc_questions` VALUES (3647, '3216', '', '', '0', 'Ahhhh ! Je savais que cette histoire vous intriguerait. Bien commen?ons par le commencement. Il y a quelques ann?es de cela, je m\\\'aventurais dans les terres Pandawa?ennes quand je fus soudain pris d\\\'une violente quinte de toux. Je ne pouvais m\\\'arr?ter et je craignais d\\\'avoir attrap? une quelconque .... Et alors j\\\'ai d?terr? un tr?s jeune buisson de mes mains ... Je me pr?parais un plat de ....');
INSERT INTO `npc_questions` VALUES (3648, '3217', '', '', '0', 'Oui je sais, donc je continue si vous le voulez bien. Donc apr?s toutes ces p?rip?ties, j\\\'ai enfin pu atteindre l\\\'?tal du vendeur de fruits .... Les n?gociations furent ?pres ... Plus tard, j\\\'arrivais ? l\\\'auberge qui ?tait presque vide, mais pas totalement ... Les dragodindes avan?aient lentement ... il faisait beau ce jour-l? ... l\\\'herbe ?tait verte ... je bus un verre d\\\'eau ...');
INSERT INTO `npc_questions` VALUES (3649, '3218', '', '', '0', '... alors je mangeais un plat du cru qui se r?v?la ... la patronne me resservit de la bi?re ... je d?cidai de changer de v?tements ... la for?t ?tait pleine d\\\'arbres ... l\\\'homme avait un bouton sur le nez ... la princesse avait des probl?mes de tuyauterie...');
INSERT INTO `npc_questions` VALUES (3650, '3220;3219', '', '', '0', 'Mais je parle, je parle, et je ne vous ai m?me pas demand? ce qui vous am?ne.');
INSERT INTO `npc_questions` VALUES (3651, '3221', '', '', '0', 'Un travail ? Non je n\\\'ai rien de tel ... Mais attendez, je crois que ma tante Pipelette a de temps en temps besoin de bras solides. Mais je dois vous pr?venir, elle est un peu bavarde, ? chaque fois que je la vois, nos discussions sont interminables.');
INSERT INTO `npc_questions` VALUES (3652, '3222', '', '', '0', 'Je vous comprends, rien n\\\'est plus p?nible que les bavards imp?nitents. Allez plut?t parler ? mon cousin Posteur Nhin, on ne sait jamais.');
INSERT INTO `npc_questions` VALUES (3653, '', '', 'QEt=744', '3660', 'Elle habite juste au nord d\\\'ici.');
INSERT INTO `npc_questions` VALUES (3654, '', '', '', '', 'Ca ne fait pas un pli, pour ?tre recommand? par moi, il ne faut pas ?tre timbr? !');
INSERT INTO `npc_questions` VALUES (3655, '3223', '', 'QEt=745', '3653', 'Bonjour, puis-je vous aider ?');
INSERT INTO `npc_questions` VALUES (3656, '3224;3225', '', '', '0', 'J\\\'ai quelque chose de simple, si vous vous en sentez capable.');
INSERT INTO `npc_questions` VALUES (3657, '3226', '', '', '0', 'Voil? une recette que vous devez porter ? ma cliente Pipelette. Elle vous paiera ? la r?ception.');
INSERT INTO `npc_questions` VALUES (3658, '', '', '', '', 'J\\\'ai un petit creux.');
INSERT INTO `npc_questions` VALUES (3659, '', '', '', '', 'Ah merci, j\\\'ai tous les ingr?dients, il ne me manquait plus que la recette. Voil? pour toi.');
INSERT INTO `npc_questions` VALUES (3660, '3228;3227', '', 'QE!182', '3654', 'Ah je te reconnais, tu as d?j? travaill? pour moi non ? Tu tombes ? pic, j\\\'ai besoin d\\\'une personne de confiance. Peux-tu aller porter un outil ? Xelorat Masket ? C\\\'est assez loin et je n\\\'ai pas trop le temps pour le moment.');
INSERT INTO `npc_questions` VALUES (3661, '3229', '', '', '0', 'Bien ! Voil? le colis, am?ne le ? Xelorat Masket . Si tu as d?j? visit? les zaaps, tu devrais les utiliser.');
INSERT INTO `npc_questions` VALUES (3662, '3230', '', '', '0', 'C\\\'est cette grande arche de pierre qui te permet d\\\'aller d\\\'un point ? un autre presque instantan?ment. \\n');
INSERT INTO `npc_questions` VALUES (3663, '3231', '', '', '0', 'Ne t\\\'inqui?te pas pour ?a, il t\\\'en faut juste un peu. Tu en trouveras sur les cr?atures que tu as battu. Plus tu vas loin, et plus il t\\\'en faut. Veux-tu conna?tre l\\\'histoire de l\\\'origine de ces portes magiques ?');
INSERT INTO `npc_questions` VALUES (3664, '', '', '', '', 'Alors parles-en avec Xelorat Masket parce que moi j\\\'ai jamais rien compris ? tout ?a !');
INSERT INTO `npc_questions` VALUES (3665, '', '', '', '', 'Marche jamais ce zaap. J\\\'use des centaines de marteaux ? le r?parer ! Vivement que Xelor vienne lui-m?me le r?parer. J\\\'aimerais bien manger une cr?pe ou deux histoire de faire une pause.');
INSERT INTO `npc_questions` VALUES (3666, '3233;3232', '', '', '0', 'Enfin un nouveau marteau pour r?parer ce zaap !');
INSERT INTO `npc_questions` VALUES (3667, '3234', '', '', '0', 'Je ne peux d?voiler les secrets de mon dieu Xelor, n?anmoins tu apprendras vite que les Xelors sont toujours en retard. Alors pour leur donner un temps d\\\'avance, leur dieu a cr?? les zaaps et les zaapis (des petits zaaps ? deux kamas que tu d?couvriras plus tard).');
INSERT INTO `npc_questions` VALUES (3668, '', '', '', '', 'Plus !');
INSERT INTO `npc_questions` VALUES (3669, '', '', '', '', 'Je plaisantais. Les zaaps sont des cellules de Xelor lui-m?me. Il les a plant? dans le sol du Monde des Douze pour nous aider ? le servir avec plus de c?l?rit?. Nous sommes comme des globules allant de cellule en cellule. Elles se nourrissent de l\\\'?nergie d?gag?e par les Kamas. Certaines vieillissent mal car elles mangent trop ! De ce fait, certaines s\\\'endorment pour dig?rer et se mettent en veille. Pour ?a qu\\\'avec ce marteau, je lui tasse le ventre et je la r?veille !');
INSERT INTO `npc_questions` VALUES (3670, '', '', '', '', 'Ouh l? l?, mais tu es bien trop fort pour travailler sur Incarnam, tu devrais descendre vers Amakna.');
INSERT INTO `npc_questions` VALUES (3671, '', '', '', '', 'Tu es trop fort pour cette partie du monde des douze. Je n\\\'ai plus de commissions ? te confier. Tu ferais mieux de partir ? la recherche des Dofus. ');
INSERT INTO `npc_questions` VALUES (3672, '', '', '', '', 'Toi qui est devenu une personne comp?tente, n\\\'oublie pas que le jour o? tu poss?deras un Dofus, il ne faudra pas le casser. Faire des cr?pes avec des oeufs de Dofus, ce n\\\'est pas tr?s raisonnable.');
INSERT INTO `npc_questions` VALUES (3673, '', '', '', '', 'D\\\'ici quelques temps, toi aussi tu iras braver les hordes d?moniaques du mal?fique Rushu. Il ne doit pas devenir le treizi?me dieu, sinon, ce sera l\\\'apocalypse !');
INSERT INTO `npc_questions` VALUES (3674, '', '', '', '', 'Vous pouvez dire ? Disskray que tout va bien.');
INSERT INTO `npc_questions` VALUES (3675, '', '', '', '', 'Au del? de ce pont, il y a le ballon vers Astrub ou Pandala. Que d\\\'aventures pour ceux qui osent s\\\'y rendre, seul ou ? plusieurs !');
INSERT INTO `npc_questions` VALUES (3676, '', '', '', '', 'Encore toi mon bel aventurier t?n?breux ? Tu n\\\'as pas encore fini ta qu?te ? Essaie encore et encore, je sais que tu peux y arriver. J\\\'adore dire encore. Hihihihi.');
INSERT INTO `npc_questions` VALUES (3677, '', '', '', '', 'Tu te bouges un peu le popotin ? Si tu ne te d?brouilles pas mieux en dehors d\\\'Incarnam, tu ne trouveras jamais de Dofus ma pauvre fille.');
INSERT INTO `npc_questions` VALUES (3678, '', '', '', '', 'Je crois au moment. S\\\'il n\\\'y a pas le moment, ? ce moment-l?, il faut arriver ? ce moment-l?, au moment qu\\\'on veut. Trouve le moment de trouver de la laine.');
INSERT INTO `npc_questions` VALUES (3680, '', '', '', '', 'Mais c\\\'est qu\\\'elle se moque de moi la d?butante ! Je vais te dresser moi ! Tu vas filer droit je te le dis, tu vas cracher du sang et pleurer comme la petite fille que tu es !');
INSERT INTO `npc_questions` VALUES (3681, '', '', '', '', 'Parfait, fais le tour de la ville et va demander aux habitants si tout va bien. J\\\'attends ton rapport !');
INSERT INTO `npc_questions` VALUES (3682, '', '', '', '', 'Si j\\\'ai remarqu? quelque chose d\\\'inhabituel ? Non, rien de rien, non, je n\\\'ai remarqu? rien, ni les zaaps tout cass?s, ni la garde ?nerv?e, tout ?a m\\\'est bien ?gal.');
INSERT INTO `npc_questions` VALUES (3683, '', '', '', '', 'Ah non mon p\\\'tit gars, rien d\\\'?trange ici, on est bien ? l\\\'abri sur Incarnam. Ce n\\\'est pas le cas sur le Monde des Douze.');
INSERT INTO `npc_questions` VALUES (3684, '', '', '', '', 'Tu diras ? ce bon ? rien de Disskray qu\\\'il y a plein de parasites dans les champs et ils d?truisent mes r?coltes, mais ?a il doit d?j? le savoir.');
INSERT INTO `npc_questions` VALUES (3685, '', '', '', '', 'Dans ton journal de qu?te, gratte l\\\'objectif. Comme l\\\'aimant est point? sur Arietta Fiolle, ta boussole t\\\'indiquera la bonne direction. Enfin quand je dis bonne, je parle aussi d\\\'Arietta. Elle fait tr?s bien le m?nage.');
INSERT INTO `npc_questions` VALUES (3686, '', '', '', '', 'Rien a signaler, zone s?curis?e.');
INSERT INTO `npc_questions` VALUES (3687, '', '', '', '', 'Je n\\\'ai rien remarqu?, tout est clair.');
INSERT INTO `npc_questions` VALUES (3688, '', '', '', '', 'Mais c\\\'est pas vrai de voir ?a, c\\\'est quand m?me pas compliqu? de trouver des personnes dans le coin ! Sois m?thodique ! Je t\\\'attends !');
INSERT INTO `npc_questions` VALUES (3689, '', '', '', '', 'Vous pouvez dire ? Disskray que tout va bien.');
INSERT INTO `npc_questions` VALUES (3690, '', '', '', '', 'Rien ? signaler, zone s?curis?e.');
INSERT INTO `npc_questions` VALUES (3691, '', '', '', '', 'Je n\\\'ai rien remarqu?, tout est clair.');
INSERT INTO `npc_questions` VALUES (3692, '', '', '', '', 'Ce pont est solide, vous pouvez le franchir');
INSERT INTO `npc_questions` VALUES (3693, '', '', '', '', 'Attention, les cr?atures ici sont tr?s agressives.');
INSERT INTO `npc_questions` VALUES (3694, '', '', '', '', 'Tu cherches encore du travail dans la r?gion ? Franchement, je serais toi, j\\\'irai voir du c?t? d\\\'Astrub, tu sembles ?tre en mesure de te d?brouiller.');
INSERT INTO `npc_questions` VALUES (3695, '', '', '', '', 'Un bon r?colteur fait attention ? son inventaire. Il faut toujours avoir de la place pour entasser ses r?coltes.');
INSERT INTO `npc_questions` VALUES (3696, '', '', '', '', 'Les r?colteurs de haut niveau r?cup?rent beaucoup de ressources ? la fois, plus que les d?butants.');
INSERT INTO `npc_questions` VALUES (3697, '', '', '', '', 'Il y a toujours un artisan qui a besoin des ressources des r?colteurs, c\\\'est un excellent moyen de se faire quelques kamas bien m?rit?s.');
INSERT INTO `npc_questions` VALUES (3698, '3241;20040', '', '', '0', 'Si tu viens me voir, c\\\'est que tu veux oublier quelque chose ? Alors, qu\\\'est ce que c\\\'est ? Un amour qui s\\\'est enfui ? Quelque chose de moins avouable ? Bon dis-moi ce que c\\\'est que je d?cide quelle potion te pr?parer.');
INSERT INTO `npc_questions` VALUES (3699, '', '', '', '', 'En dosant savamment les ingr?dients, j\\\'obtiens des effets bien curieux. Je me demande si c\\\'est l?gal ce que je fais.');
INSERT INTO `npc_questions` VALUES (3700, '324', '', '', '0', 'Ah ? un m?tier. Bon c\\\'est assez simple. Je vais te rendre ce service gratuitement mais saches que ce ne sera plus le cas sur Amakna. Les potions qui permettent d\\\'oublier un m?tier sont assez communes mais pas gratuites. Enfin, bref, nous y allons ?');
INSERT INTO `npc_questions` VALUES (3701, '', '', '', '', 'C\\\'est magnifique cette grande ville qui s\\\'?tale sous nos yeux. Un jour, moi aussi, je partirai parcourir le monde et je pourrai boire un lailait ? l\\\'auberge d\\\'Astrub, de Bonta ou de Br?kmar.');
INSERT INTO `npc_questions` VALUES (3702, '324', '', '', '0', 'Cet Orme ne peut ?tre profan? par la hache. Entre deux siestes, le dieu Sadida a constat? que trop de personnes arrachaient les ressources v?g?tales de notre monde. Depuis, il a assign? des protecteurs aux arbres, aux fleurs et aux c?r?ales.');
INSERT INTO `npc_questions` VALUES (3703, '325', '', '', '0', 'Ils attaquent ceux qui profanent la Nature. Cet orme est le dernier d\\\'Incarnam. Nul ne peut couper cet arbre sans connaitre le courroux de Sadida. Je crains que dans sa col?re il d?truise tout Incarnam. C\\\'est pourquoi, ma magie rejette les bucherons.');
INSERT INTO `npc_questions` VALUES (3704, '', '', '', '', 'Je prot?ge le dernier orme d\\\'Incarnam. Nul ne peut le couper. Celui qui le ferait, se ferait attaquer par un protecteur de la Nature ou Sadida lui-m?me !');
INSERT INTO `npc_questions` VALUES (3705, '', '', '', '', 'Quand j\\\'aurai mes 15 ans, je quitterai ce patelin pour partir ? l\\\'aventure dans les faubourgs de cette cit? au loin. Je sais que moult p?rils me guettent, n?anmoins apr?s des mois ? m\\\'entra?ner ? chasser le boufton, je serai s?rement capable de vaincre un bouftou ? main nue.');
INSERT INTO `npc_questions` VALUES (3706, '3248', '', 'QE!183', '3713', 'Salut, toi aussi tu viens pour l\\\'aventure ?');
INSERT INTO `npc_questions` VALUES (3707, '3250;3249', '', '', '0', 'Il y a de plus en plus d\\\'aventuriers qui passent par Incarnam avant de se rendre dans la contr?e d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (3708, '3252;3251', '', '', '0', 'L?-bas, tout est neuf et tout est sauvage. La gloire et la richesse sont ? la port?e des plus t?m?raires et des plus vaillants. Je ne sais si je m?rite de m\\\'y rendre.');
INSERT INTO `npc_questions` VALUES (3709, '3253', '', '', '0', 'Merci de tes conseils, tu as d?j? l\\\'air d\\\'un v?t?ran. Je vais dormir un peu afin de rendre hommage ? mon dieu. Sadida dit qu\\\'il faut toujours se reposer apr?s un effort intellectuel.');
INSERT INTO `npc_questions` VALUES (3710, '3262;3260', '', '', '0', 'Piou piou piou ?');
INSERT INTO `npc_questions` VALUES (3711, '', '', '', '', 'Piiiiiiiiiiou');
INSERT INTO `npc_questions` VALUES (3712, '', '', '', '', 'Piou piou');
INSERT INTO `npc_questions` VALUES (3713, '', '', 'QT=183', '3707', 'Un jour je me l?verai du bon pied, et je partirai ? l\\\'aventure.');
INSERT INTO `npc_questions` VALUES (3714, '325', '', '', '0', 'Attention devant, je transporte de l\\\'eau pour les nymphettes. ');
INSERT INTO `npc_questions` VALUES (3715, '325', '', '', '0', 'Oui, en t\\\'aspergeant de l\\\'eau de leur bain, tu peux gu?rir toutes tes blessures. Comme beaucoup de monde se soigne ici, je suis oblig?e de remplir sans cesse les bassines. ');
INSERT INTO `npc_questions` VALUES (3716, '', '', '', '', 'Tu peux aussi t\\\'assoir pour gu?rir. Repasse donc me voir plus tard, quand tu seras assez fort pour porter des seaux d\\\'eau.');
INSERT INTO `npc_questions` VALUES (3717, '', '', '', '', 'Lorsque tu partiras pour le grand monde, tu devras te nourrir pour te soigner. Les nymphes ne peuvent plus rien pour toi. Tu es trop puissant maintenant.');
INSERT INTO `npc_questions` VALUES (3718, '3258;3257', '', 'QE!185', '3720', 'Oh tu sembles ?tre une personne tr?s forte, je veux bien que tu me ram?nes de l\\\'eau pour mes nymphettes.');
INSERT INTO `npc_questions` VALUES (3719, '3259', '', '', '0', 'Merci pour les nymphettes.');
INSERT INTO `npc_questions` VALUES (3720, '', '', 'PO!311', '3719', 'Tu trouveras de l\\\'eau dans le puits.');
INSERT INTO `npc_questions` VALUES (3721, '', '', '', '', 'Je vais finir barrique ? force de porter toute cette eau.');
INSERT INTO `npc_questions` VALUES (3722, '', '', '', '', 'Piou piou piiiiiiiiiiiiiiiou !!!');
INSERT INTO `npc_questions` VALUES (3723, '3264;326', '', '', '0', 'Piou piou piou ?');
INSERT INTO `npc_questions` VALUES (3724, '3265;326', '', '', '0', 'Piou piou piou ?');
INSERT INTO `npc_questions` VALUES (3725, '326', '', '', '0', 'Piou !');
INSERT INTO `npc_questions` VALUES (3726, '3268;326', '', '', '0', 'Prosterne toi devant la toute puissance de Iop, protecteur d\\\'Amakna. Contemple ici son ?p?e, symbole de sa force.');
INSERT INTO `npc_questions` VALUES (3727, '3271', '', '', '0', 'Les ?crits disent que lors de la bataille contre les d?mons, il jeta son ?p?e au sol car le combat ?tait trop in?gal. Les d?mons furent intimid?s puis apeur?s face ? cette preuve de force et de confiance. Ils fuirent alors le champ de bataille et Iop fut victorieux sans m?me avoir ? combattre. Il laissa son ?p?e sur place pour inspirer courage et d?termination ? ses fid?les et ? tout ceux qui verraient cette ?p?e.');
INSERT INTO `npc_questions` VALUES (3728, '327', '', '', '0', 'Tenva Lakruche a lu le livre des v?rit?s mais elle n\\\'a pu que me conter le r?cit car ce livre est difficile ? trouver m?me sur Amakna. Si tu veux, va lui parler et elle aussi te parlera de la gloire de Iop.');
INSERT INTO `npc_questions` VALUES (3729, '', '', '', '', 'Laura est un peu trop fervente ? mon go?t, mais elle est sympathique. Assieds toi que je te conte ce mythe.');
INSERT INTO `npc_questions` VALUES (3730, '3275;327', '', '', '0', 'Laura t\\\'a parl? du livre ? J\\\'ai lu ce livre quand j\\\'?tais sur Amakna. Ce que j\\\'ai dit ? Laura n\\\'est qu\\\'une version ?court?e de la version originale. Si un jour tu as la chance de trouver ce livre, n\\\'h?site pas ? le lire, il est ?difiant ...');
INSERT INTO `npc_questions` VALUES (3731, '3277;3352;3279;327', '', '', '0', 'Bonjour, jeune ?me, que veux-tu ?');
INSERT INTO `npc_questions` VALUES (3732, '3285;328', '', '', '0', 'Bonjour, avec une ?me aussi vieille, tu viens encore fr?quenter cette r?gion o? apparaissent les nouvelles ?mes ? Que veux-tu ?');
INSERT INTO `npc_questions` VALUES (3733, '3281;328', '', '', '0', 'Fais ton choix.');
INSERT INTO `npc_questions` VALUES (3734, '3280;328', '', '', '0', 'Ils composent la Milice C?leste. Les douze dieux leur ont donn? la mission d\\\'aiguiller toutes les nouvelles ?mes en leurs inculquant des notions de base. C\\\'est une sorte de confr?rie guidant les ?mes dans le monde mat?riel. Leur symbole est une ?p?e sur un ?cu. Tu peux le voir dans ma taverne. J\\\'utilise ces vieilles banni?res pour emp?cher le vent de rentrer dans ma taverne. Il y a trop de vent sur ces hauteurs. ');
INSERT INTO `npc_questions` VALUES (3735, '', '', '', '', 'Comme disait mon ami Ad?d?, ils doivent se nicher dans les coins sombres et ?troits du Monde des Douze. Les dragons sont des cr?atures parano?aques. Nul ne peut s\\\'introduire chez eux, m?me par la petite porte de derri?re pour voler leurs oeufs. Ils les cachent et les jalousent encore plus que la premi?re p?pite d\\\'or d\\\'un Enutrof.');
INSERT INTO `npc_questions` VALUES (3736, '328', '', '', '0', 'Je guide surtout les malotrus vers la sortie !');
INSERT INTO `npc_questions` VALUES (3737, '', '', '', '', 'M?me les r?colteurs peuvent fabriquer des objets de base. Cela leur apporte un peu d\\\'exp?rience dans leur m?tier.');
INSERT INTO `npc_questions` VALUES (3738, '', '', '', '', 'Les protecteurs de ressources qu\\\'on trouve sur Amakna attaquent parfois les r?colteurs, n?anmoins, une fois vaincus, ils procureront une bonne quantit? de mat?riaux.');
INSERT INTO `npc_questions` VALUES (3739, '', '', '', '', 'Les paysans d\\\'Amakna prosp?rent dans les champs de Cania avant de s\\\'aventurer plus loin.');
INSERT INTO `npc_questions` VALUES (3740, '', '', '', '', 'Un b?cheron peut trouver de bons arbres ? couper dans la for?t d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (3741, '328', '', '', '0', 'Regarde ta boussole, l\\\'aventure, c\\\'est dans cette direction !');
INSERT INTO `npc_questions` VALUES (3742, '', '', '', '', 'Le port de Madrestam est plein de jeunes p?cheurs, c\\\'est un bon coin de p?che.');
INSERT INTO `npc_questions` VALUES (3743, '', '', '', '', 'Pour attraper de plus gros poissons, un p?cheur doit changer son mat?riel.');
INSERT INTO `npc_questions` VALUES (3744, '', '', '', '', 'Un alchimiste peut cr?er moult breuvages qu\\\'il stocke dans des fioles. Il peut concocter des potions de soins, des potions de rappel ? son point de sauvegarde, des potions d\\\'oubli de m?tier et bien d\\\'autres encore !');
INSERT INTO `npc_questions` VALUES (3745, '', '', '', '', 'La r?colte est un moyen simple et relativement rapide de gagner ses premiers kamas.');
INSERT INTO `npc_questions` VALUES (3746, '', '', '', '', 'Certains r?colteurs ne vendent pas le fruit de leur r?colte et le conservent jusqu\\\'? ce qu\\\'ils connaissent un second m?tier.');
INSERT INTO `npc_questions` VALUES (3747, '328', '', '', '0', 'Qu\\\'est ce qui se passe, tu n\\\'arrives pas ? fabriquer quelque chose ? Tu as besoin d\\\'aide ?');
INSERT INTO `npc_questions` VALUES (3748, '', '', '', '', 'Obtenir une potion de soins est assez simple. Mets tes gants et utilise l\\\'alambic. D?poses-y trois fleurs de lin et un peu d\\\'eau. Attention, pas plus de 3 fleurs et un seul seau d\\\'eau sont n?cessaires. Normalement, si tu y as mis les quantit?s exactes, tu verras ce que tu obtiendras. Il arrive cependant que m?me avec les bonnes quantit?s la recette ?choue, il ne te reste alors qu\\\'? r?essayer.');
INSERT INTO `npc_questions` VALUES (3749, '', '', '', '', 'Il faut beaucoup de bois pour obtenir une planche correcte. Trouve au moins vingt bois de fr?ne. Quand tu les places sur l\\\'atelier, tu dois voir appara?tre le futur r?sultat de ton travail. Si c\\\'est le cas, tu n\\\'as plus qu\\\'? tenter de faire une belle planche. Il se peut que cela ?choue mais en pers?v?rant tu y arriveras. En revanche, si tu ne vois rien sur le panneau de r?sultat c\\\'est que tu as mis trop, ou trop peu de bois.');
INSERT INTO `npc_questions` VALUES (3750, '', '', '', '', 'Vider un poisson est tr?s simple, tu utilises le plan de travail du poisson qui se trouve juste l?. Tu dois voir ce que tu vas obtenir. N\\\'oublie pas, tu dois avoir ton outil de travail en mains pour tout ce qui concerne ton m?tier.');
INSERT INTO `npc_questions` VALUES (3751, '', '', '', '', 'La premi?re chose ? faire est d\\\'?quiper son outil de travail. Ensuite choisis de moudre ton bl? avec le concasseur. Deux mesures de bl? sont suffisantes pour une mesure de farine. tu dois voir le r?sultat de ton travail avant de commencer ? combiner les ?l?ments.');
INSERT INTO `npc_questions` VALUES (3752, '', '', '', '', 'Si tu cherches ? apprendre un autre m?tier, va voir Gilles dans l\\\'atelier de l\\\'auberge, il pourra t\\\'aider.');
INSERT INTO `npc_questions` VALUES (3753, '3292;329', '', '', '0', 'Je n\\\'ai pas r?ussi ? me faire beaucoup de kamas ici, mais j\\\'ai pas mal d\\\'objets que je troque. Ca t\\\'int?resse ?');
INSERT INTO `npc_questions` VALUES (3754, '329', '', '', '0', 'Laisse-moi jeter un ?il dans ce fatras.');
INSERT INTO `npc_questions` VALUES (3755, '', '', '', '', 'Parfois j\\\'ai l\\\'impression d\\\'?tre manipul? par une entit? sup?rieure qui dicte mes actes et mes paroles, pas un des douze dieux, quelque chose d\\\'autre.');
INSERT INTO `npc_questions` VALUES (3757, '332', '', '', '0', 'Oui tu as des choses int?ressantes, nous pouvons faire du troc.');
INSERT INTO `npc_questions` VALUES (3760, '', '', '', '', 'Vu ta force, tu risques de d?truire un ?pouvantail d\\\'un seul coup ! Essaie de ne pas trop les ab?mer, parce que c\\\'est moi qui les rempaille apr?s !');
INSERT INTO `npc_questions` VALUES (3761, '', '', '', '', 'Satan?s ?pouvantails, ils n\\\'arr?tent pas de bouger. Ils savent que les jeunes aventuriers viennent ici pour s\\\'entrainer au combat. Comme ils sont incapables de faire des d?g?ts, ils essaient de s\\\'?chapper. Ce n\\\'est pas une hallebarde dont j\\\'ai besoin pour garder ces pantins de paille, mais d\\\'une fourche !');
INSERT INTO `npc_questions` VALUES (3762, '', '', '', '', 'Iop a laiss? son ?p?e sur Incarnam pour nous rappeler sa toute puissance.');
INSERT INTO `npc_questions` VALUES (3763, '', '', '', '', 'Quand j\\\'aurai r?cup?r? assez de bric ? brac ici, j\\\'irai ? Astrub pour tout revendre.');
INSERT INTO `npc_questions` VALUES (3765, '', '', '', '', 'Soldats, je suis content de vous !');
INSERT INTO `npc_questions` VALUES (3766, '3397', '[name]', '', '0', 'Bienvenue ? toi #1. Ton incarnation au pied de la statue de ton dieu est un bon pr?sage pour toi. Si tu veux conna?tre l\\\'aventure, je te conseille de visiter Incarnam avant de descendre sur le continent.');
INSERT INTO `npc_questions` VALUES (3767, '', '', '', '', 'Les cr?atures sont faciles ? trouver dans la r?gion. D?brouille toi pour les ?liminer comme tu veux, fais toi aider le cas ?ch?ant.');
INSERT INTO `npc_questions` VALUES (3770, '', '', '', '', 'Parfait soldat, repose-toi et reviens prendre tes ordres d?s que tu seras pr?t.');
INSERT INTO `npc_questions` VALUES (3771, '', '', '', '0', 'Avant d\\\'aller plus loin, je te conseille de lancer quelques sortil?ges ou quelques coups sur cet ?pouvantail. Ma?triser tes pouvoirs te sera fort utile ? travers le vaste monde qui t\\\'attend.');
INSERT INTO `npc_questions` VALUES (3772, '3400', '', 'QE!188', '3773', 'Essaie donc, tu ne peux pas perdre !');
INSERT INTO `npc_questions` VALUES (3773, '', '', '', '0', 'Si tu le d?sires, tu peux recommencer ? t\\\'entra?ner. L\\\'?pouvantail se r?incarne sans cesse gr?ce aux vents d\\\'Incarnam.');
INSERT INTO `npc_questions` VALUES (3774, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3775, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3776, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3777, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3778, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3779, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3780, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3781, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3782, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3783, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3784, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3785, '', '', '', '', 'Veux-tu retourner ? ta statue ?');
INSERT INTO `npc_questions` VALUES (3786, '3323;3324', '', 'QE!190', '3788', 'Je te propose de vivre une exp?rience unique. Enfin, vivre n\\\'est peut ?tre pas le terme le plus appropri?. En effet, cette exp?rience interdite va te faire passer de l\\\'autre c?t? du miroir, franchir le pas vers l\\\'au-del?. Mais rassure-toi, tout est sous contr?le.');
INSERT INTO `npc_questions` VALUES (3787, '3325;3326', '', '', '0', 'Mais pour vivre une exp?rience unique et te pr?parer pour l\\\'avenir. Bon, relaxe toi, je vais te lancer un sort qui ne fonctionne que si la personne est consentante.');
INSERT INTO `npc_questions` VALUES (3788, '3347', '', '', '0', 'Finalement, tu vois que ce n\\\'?tait pas si dangereux. Pour te f?liciter de ton courage et de ta curiosit?, je te donne ceci. Je suis s?r que ?a va te servir. Mais tu es faible maintenant, cours chez Grobid et ach?te lui une bonne bi?re pour moi. En ?change, je te rendrai toute l\\\'?nergie que tu as perdu.');
INSERT INTO `npc_questions` VALUES (3789, '', '', '', '', 'C\\\'est quoi cette histoire de lumi?re aveuglante au bout d\\\'un tunnel ?');
INSERT INTO `npc_questions` VALUES (3790, '', '', '', '', 'Contre huit b?ches de bois, je te donne une ?p?e de boisaille. Si tu poss?des quatre mesures de bl?, je te donne un pain d\\\'Amakna encore chaud. Contre cinq fleurs de lins, je te propose une potion de mini soins. Et si tu as un goujon, je te le vide gratuitement pour donner les abats ? mon chacha. J\\\'ai d\\\'autres choses. A toi de me proposer des objets, je trouverai bien quelque chose ? t\\\'?changer.');
INSERT INTO `npc_questions` VALUES (3791, '3328;332', '', '', '0', 'Salut, tu voyages seul ? Sur Incarnam tu n\\\'auras pas de probl?mes mais en Amakna, il est souvent sage de voyager ? plusieurs. Moi j\\\'aime pouvoir compter sur mes amis. Pour les contacter, je tiens un agenda ? jour. Tu devrais le faire toi aussi. Ainsi, tu pourras contacter les personnes disponibles plus facilement.');
INSERT INTO `npc_questions` VALUES (3792, '333', '', '', '0', 'Pour te souvenir d\\\'un personnage que tu consid?res comme un ami, il te suffit de cliquer sur lui et de l\\\'ajouter ? tes amis, ensuite, il appara?tra dans ta liste d\\\'amis. Si tu as bien compris, ajoute un personnage dans ta liste d\\\'amis.');
INSERT INTO `npc_questions` VALUES (3793, '', '', '', '', 'Bien jou?, tu apprendras facilement comment retirer un personnage de cette liste ou te servir de la liste des gens que tu appr?cies moins.');
INSERT INTO `npc_questions` VALUES (3794, '', '', '', '', 'La v?ritable amiti?, c\\\'est comme la sant?... tu n\\\'en connais la valeur que lorsque tu l\\\'as perdue.');
INSERT INTO `npc_questions` VALUES (3795, '', '', '', '', 'Allons, il doit bien y avoir des gens que tu veux recontacter plus tard ... cherche bien.');
INSERT INTO `npc_questions` VALUES (3796, '', '', '', '', 'En plus d\\\'?tre la cr?ature la plus belle d\\\'Incarnam, je suis aussi la plus puissante. Je me le dis tous les jours devant mon dispenseur des gr?ces.');
INSERT INTO `npc_questions` VALUES (3797, '3335;333', '', '', '0', 'Alors maintenant que tu arrives ? lancer un sortil?ge ou deux, tu viens me d?fier ?');
INSERT INTO `npc_questions` VALUES (3798, '3331;333', '', '', '0', 'Tiens un petit ?tre inf?rieur qui m\\\'adresse la parole. Je n\\\'ai pas de temps pour les minus.');
INSERT INTO `npc_questions` VALUES (3799, '', '', '', '', 'Je t\\\'ai conc?d? la victoire car nous avons besoin de braves comme toi pour vaincre les desseins mal?fiques du d?mon Rushu.');
INSERT INTO `npc_questions` VALUES (3800, '3336;333', '', '', '0', 'Ah ah ah, le petit moustique revient prendre une racl?e ?');
INSERT INTO `npc_questions` VALUES (3801, '333', '', '', '0', 'Evidemment, nous sommes dans l\\\'endroit le plus venteux de la plan?te. Tu as de la chance d\\\'?tre aussi faible, si tu avais ?t? plus fort, je t\\\'aurais exp?di? dans le chaudron des ?mes pour m\\\'avoir fait perdre mon temps. \\nJe ne d?fie que ceux qui ont fait de nombreuses qu?tes de combattant. Fais le tour d\\\'Incarnam et peut ?tre seras-tu digne de me combattre.');
INSERT INTO `npc_questions` VALUES (3802, '3339;333', '', '', '0', 'Tiens, tiens, je sens que tu as quelque chose qui peut m\\\'int?resser. Je me trompe ou tu poss?des une peau de milimilou ?');
INSERT INTO `npc_questions` VALUES (3803, '3341;334', '', '', '0', 'C\\\'est mon secret, je n\\\'aurai jamais r?ussi ? amasser tout ?a, si je n\\\'avais pas quelques talents cach?s. Ca te dit de me le donner en ?change d\\\'un objet tr?s rare ?');
INSERT INTO `npc_questions` VALUES (3804, '3345;334', '', '', '0', 'Je le savais, ?a te dit de me l\\\'?changer contre un objet tr?s rare ?');
INSERT INTO `npc_questions` VALUES (3805, '3343;334', '', '', '0', 'J\\\'ai en ma possession un superbe collier. Il est magique c\\\'est certain. En plus, je crois qu\\\'il fait partie d\\\'un ensemble d\\\'objets qui, une fois r?unis sont encore plus puissants.');
INSERT INTO `npc_questions` VALUES (3806, '334', '', '', '0', 'Hola, doucement, pour ce collier tu devras me rapporter un peu plus qu\\\'une simple peau mit?e.');
INSERT INTO `npc_questions` VALUES (3807, '', '', '', '', 'Pnj(874) et Message(3804)');
INSERT INTO `npc_questions` VALUES (3808, '', '', '', '', 'C\\\'est un march? honn?te, voil? votre collier.');
INSERT INTO `npc_questions` VALUES (3809, '', '', '', '', 'Un chasseur sachant chasser son chacha sans son chienchien de chasse est un bon chasseur.');
INSERT INTO `npc_questions` VALUES (3810, '', '', '', '', 'Un p?cheur p?chait sous un p?cher mais le p?cher emp?cha le p?cheur de p?cher.');
INSERT INTO `npc_questions` VALUES (3811, '', '', '', '', 'Je t\\\'ai donn? mes conditions, tu n\\\'as plus qu\\\'? trouver tout ?a sur Incarnam.');
INSERT INTO `npc_questions` VALUES (3812, '', '', '', '', 'Avec tes nombreux sortil?ges, tu devrais descendre affronter les monstres les plus puissants qui se terrent dans leurs donjons.');
INSERT INTO `npc_questions` VALUES (3813, '3349;3348', '', 'QT!193', '3818', 'Tu sembles avoir un avenir prometteur. Si tu arrives ? vaincre le p?re de mon familier, je suis pr?t ? te donner la clef menant au donjon du Milimilou.');
INSERT INTO `npc_questions` VALUES (3814, '', '', '', '', 'Une bi?re ? Je vois ? ton visage que tu as accept? l\\\'exp?rience d\\\'Aym?. Je sais qu\\\'il n\\\'ose pas venir en acheter lui-m?me car il a une grosse ardoise chez moi. Bah, je te la vends, tu n\\\'as rien ? voir dans cette histoire.');
INSERT INTO `npc_questions` VALUES (3815, '', '', '', '', 'Je savais que tu gagnerais. Si par malheur tu perds cette clef ou si tu veux retourner dans le donjon du Milimilou, n\\\'h?site pas ? attaquer des cr?atures d\\\'Incarnam. Certaines ont aval? des aventuriers, avec un peu de chance, tu trouveras une clef dans leur panse.');
INSERT INTO `npc_questions` VALUES (3816, '3350;3351', '', '', '', 'Tu peux encore essayer de le vaincre ! Pers?v?re jeune aventurier !');
INSERT INTO `npc_questions` VALUES (3817, '', '', '', '', 'Une bi?re ! Euh oui, donne la moi, elle est ... hmmm ... n?cessaire ? ma concentration. Bon tiens-toi pr?t, je te rends tes forces. Fais attention sur Amakna, il faut te reposer dans des auberges ou trouver des potions pour retrouver de l\\\'?nergie.');
INSERT INTO `npc_questions` VALUES (3818, '', '', '', '', 'Parcourir les donjons une ?p?e et un livre de sorts ? la main est s?rement l\\\'une des choses les plus tr?pidantes que connaissent les aventuriers. ');
INSERT INTO `npc_questions` VALUES (3819, '', '', '', '', 'Pnj(884) et Message(3813)');
INSERT INTO `npc_questions` VALUES (3821, '', '', '', '', 'Oui, je sais. J\\\'ai beau m\\\'en d?barrasser, il en revient toujours un. Tu peux le chasser si tu veux. Cela laissera un peu de r?pit ? ma r?serve de fromage.');
INSERT INTO `npc_questions` VALUES (3822, '', '', '', '', 'Cette fichue longue vue ne marche toujours pas. J\\\'ai beau fouetter Biltinix tous les matins, il n\\\'a pas le temps de venir m\\\'aider. Je devrais peut-?tre demander ? Xelorat Masket mais il est trop occup? ? r?parer les zaaps. Le jour o? elle fonctionnera, tu pourras voir le monde entier ? travers elle.');
INSERT INTO `npc_questions` VALUES (3823, '3354;3353', '', '', '0', 'Tiens, tiens, un aventurier. Tu sais ce qui t\\\'attend au-del? de cette grotte ?');
INSERT INTO `npc_questions` VALUES (3824, '3355', '', '', '0', 'Bon, ne te fatigue pas, j\\\'ai toujours les m?mes r?ponses. Et comme toujours, je vais devoir expliquer ce qui se passe r?ellement dans les tr?fonds de ces grottes. Il y a des monstres, beaucoup de monstres. Mais tu t\\\'en doutais. Et surtout, au fin fond de ce d?dale, il y a leur chef. Une cr?ature ignoble capable d\\\'?visc?rer le plus fort des aventuriers. Bon te voil? averti.  \\nSi tu veux aller plus loin, trouve des compagnons et placez-vous sur les DALLES. Cela ouvrira la porte.');
INSERT INTO `npc_questions` VALUES (3825, '', '', '', '', 'Pnj(886) et Message(3823)');
INSERT INTO `npc_questions` VALUES (3826, '3356', '', '', '0', 'Oh il y aura certainement plein de choses de valeur, mais si on se revoit, je te remettrai la r?compense pour avoir surv?cu au pire de ce cloaque. Mais juste une fois.');
INSERT INTO `npc_questions` VALUES (3827, '', '', '', '', 'Je me souviens de toi, tu es d?j? pass? par l? et tu as surv?cu n\\\'est-ce pas ? Je n\\\'ai plus rien pour toi, je garde ?a pour les novices qui n\\\'ont pas encore fait leurs preuves.');
INSERT INTO `npc_questions` VALUES (3828, '3358;3359', '', '', '0', 'Je vous ai pr?c?d?s. Bon si vous ?tes ici, c\\\'est que vous ?tes tous motiv?s. Mais je ne vous laisserai passer que si vous avez la clef de cette porte. Si vous ne l\\\'avez pas, essayez de la trouver sur les cr?atures qui peuplent Incarnam.');
INSERT INTO `npc_questions` VALUES (3829, '3360;3361', '', '', '0', 'F?licitations, vous ?tes sortis vivant ! Je vous t?l?porte ? la sortie ou ? l\\\'auberge pour que vous puissiez y conter vos exploits ?');
INSERT INTO `npc_questions` VALUES (3830, '', '', '', '', 'On dirait que tu t\\\'en es sorti. Bien. F?licitations. Tu as bien m?rit? la r?compense que je remets ? ceux qui ont r?ussi.');
INSERT INTO `npc_questions` VALUES (3831, '3366;337', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ?');
INSERT INTO `npc_questions` VALUES (3832, '3363;336', '', '', '0', 'Y? soui zoune artisteu, y? croque l? village di dessous. C\\\'est mon oeuvre, ma vie. Ma il m? faut de la ouache pour esprimer moun talente ! Toi zaussi esprime toune cr?ativit?, va me ser?er les couleurs de l\\\'envie.');
INSERT INTO `npc_questions` VALUES (3833, '', '', '', '', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3834, '3376;337', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3835, '3368;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3836, '3369;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3837, '3370;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3838, '3371;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3839, '3372;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3840, '3373;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3841, '3374;338', '', '', '0', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3842, '', '', '', '', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3843, '', '', '', '', 'Alors, pr?t ? te lancer dans la grande aventure ? ');
INSERT INTO `npc_questions` VALUES (3844, '', '', '', '', 'Tou m? ram?ne les ingr?dients pour la ouache. Tou es amical, tou es oune artiste.');
INSERT INTO `npc_questions` VALUES (3845, '', '', '', '', 'Ma qu? c\\\'est beau, y? le vrai talent, y? souis l? grand artisteu. Ma mouse, inspires ma cr?ativit');
INSERT INTO `npc_questions` VALUES (3846, '', '', '', '', 'Passe devant, moi j\\\'admire le panorama.');
INSERT INTO `npc_questions` VALUES (3847, '', '', '', '', 'Notre accord est simple, tue le milimilou et je t\\\'accorde ta r?compense, je t\\\'attendrai ? la sortie.');
INSERT INTO `npc_questions` VALUES (3848, '', '', '', '', 'Les aventuriers viennent souvent se reposer dans les tavernes et les auberges pour r?cup?rer de l\\\'?nergie et descendre une bonne mousse ti?de. ');
INSERT INTO `npc_questions` VALUES (3849, '', '', '', '', 'Les jeunes sont trop press?s, il ne savent pas appr?cier le calme. Une mousse, quelques amis, une jolie serveuse, rien de tel pour finir ses vieux jours.');
INSERT INTO `npc_questions` VALUES (3850, '3388;3389', '', 'QT!200', '3855', 'Tiens, encore une jeune ?me en vadrouille sur Incarnam.');
INSERT INTO `npc_questions` VALUES (3851, '3390;3391', '', '', '0', 'Je me repose de mes vieilles aventures. J\\\'ai chass? les Bouftous, traqu? les Bworks, travers? la Mer d\\\'Asse, surv?cu ? la Maloria, d?fi? Dark Vlad et ...');
INSERT INTO `npc_questions` VALUES (3852, '3392;3393', '', '', '0', 'Une fois, j\\\'en d?couvris un brillant de mille feux aux tr?fonds d\\\'un donjon. Mes yeux ne pouvaient se d?tacher de cette vision de r?ves, jusqu\\\'? ce que des aventuriers le d?robent devant moi ! J\\\'avais rat? l\\\'occasion du si?cle !');
INSERT INTO `npc_questions` VALUES (3853, '3394', '', '', '0', 'C\\\'est le destin, n?anmoins, je me suis tellement amus? ? en chercher un que je n\\\'ai pas de regret. Passer des jours et des nuits sur ce Dofus m\\\'a donn? l\\\'occasion de rencontrer des cr?atures merveilleuses, de d?couvrir des contr?es exotiques et de rencontrer de valeureux fr?res d\\\'armes.  Je te souhaite autant de plaisir ? parcourir le monde des douze dieux.');
INSERT INTO `npc_questions` VALUES (3854, '', '', '', '', 'Tu veux la suite de mon histoire ?');
INSERT INTO `npc_questions` VALUES (3855, '', '', '', '', 'Ah les doigts de pied en ?ventail en admirant Astrub, un vieux r?ve. Il ne me manque qu\\\'un Dofus ou deux ? accrocher au-dessus de la chemin?e.');
INSERT INTO `npc_questions` VALUES (3856, '', '', '', '', 'Les aventuri?res viennent souvent se pr?lasser dans les salons pour r?cup?rer de l\\\'?nergie, papoter et d?guster un bon petit lailait frais.');
INSERT INTO `npc_questions` VALUES (3859, '', '', '', '', 'To? trouver offrande pour Bworknroll, to? accompagner Titi.');
INSERT INTO `npc_questions` VALUES (3860, '', '', '', '', 'Toi qui visite Incarnam, si tu trouves une peau de Milimilou, rapporte-la moi, je suis s?r que je trouverai quelque chose de tr?s int?ressant ? te donner.');
INSERT INTO `npc_questions` VALUES (3861, '', '', '', '', 'J\\\'ai appris qu\\\'on t\\\'avait confi? une t?che li?e ? ta profession, tu devrais t\\\'en acquitter.');
INSERT INTO `npc_questions` VALUES (3862, '', '', '', '', 'Bonjour!');
INSERT INTO `npc_questions` VALUES (3863, '', '', '', '', 'vhjvb.');
INSERT INTO `npc_questions` VALUES (3864, '', '', '', '', 'Ah, je vois que tu viens t\\\'assurer que tout va bien au Ch?teau... Ne t\\\'inqui?te pas, je veille sur le tr?ne!');
INSERT INTO `npc_questions` VALUES (3865, '', '', '', '', 'Bonjour. Je vois que vous ?tes un vaillant guerrier... Souhaiteriez-vous aider ? prot?ger Amakna et le tr?ne d\\\'Allister ?');
INSERT INTO `npc_questions` VALUES (3866, '', '', '', '', 'Savez vous comment les roublards ont aid? le d?mon Uk\\\'Not\\\'Allag ? s\\\'?vader ?');
INSERT INTO `npc_questions` VALUES (3867, '', '', '', '', 'Pnj(893) et Message(3865)');
INSERT INTO `npc_questions` VALUES (3868, '', '', '', '', 'Au vu des ?v?nements pass?s, le Roi d?sire surveiller les roublards... mais pour cela encore faudrait-il les trouver ! Leur repaire est en effet bien cach?... Notre seul indice est qu\\\'un important Sram serait un de leurs membres, il faut le trouver. Pouvez-vous aider votre roi ?');
INSERT INTO `npc_questions` VALUES (3869, '', '', '', '', 'Uk\\\'Not\\\'Allag ?crasait Amakna sous son joug implacable, laissant ses arm?es d?moniaques piller et tuer. Tous avaient peur, les d?mons ?taient trop puissants... Mais Allister avait des compagnons, et plus que tout, un plan. Usant de ruse, il r?ussit ? enfermer dans une ge?le Uk\\\'Not\\\'Allag. Malheureusement, comme je le disais, ce dernier s\\\'est ?vad?, avec l\\\'aide des roublards.');
INSERT INTO `npc_questions` VALUES (3870, '', '', '', '', 'Pnj(893) et Message(3869)');
INSERT INTO `npc_questions` VALUES (3871, '', '', '', '', 'Ah, je vois que tu as obtenu plus d\\\'informations sur ces roublards ! R?p?te-moi un peu ce qu\\\'a dit ce Sram... une zone dangereuse entour?e d\\\'eau... Hum, tu devrais chercher du c?t? du cimeti?re d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (3872, '', '', '', '', 'Bien jou? ! Tu as prouv? ta loyaut? envers notre Roi. Mais quant m?me... c\\\'est bizarre que les Roublards ne se cachent pas plus que ?a, ?tant donn? les ?v?nements r?cents... Cela dit, ?a ne doit pas ?tre donn? ? tout le monde d\\\'entrer l?-dedans !');
INSERT INTO `npc_questions` VALUES (3873, '', '', '', '', 'Ah, fl?te, il est o? ce repaire !? et avec tout ?a, je suis en retard pour ma sieste... Quoi ! Tu connais le ministre Yse Vewybad ? Tu peux m\\\'aider alors ! Tu veux bien chercher ce repaire ?');
INSERT INTO `npc_questions` VALUES (3874, '', '', '', '', 'Le conseiller Yse Vewybad pense que les Roublards ont d? laisser des indices dans le cimeti?re sur le moyen de rentrer dans le repaire. Tu veux bien faire le tour des cryptes s\\\'il te pla?t ?');
INSERT INTO `npc_questions` VALUES (3875, '', '', '', '', 'Alors, ces cryptes ?');
INSERT INTO `npc_questions` VALUES (3876, '', '', '', '', 'Toutes ses aventures, ?a m\\\'a fatigu?, je crois que je vais dormir un peu...');
INSERT INTO `npc_questions` VALUES (3877, '', '', '', '', 'Hein, euh, quoi ? Ouaah je faisais un si bon r?ve... Bon, dis-moi ce que t\\\'as trouv?. Ah non, il y a rien dans ces cryptes-l?... Dis, il y a une crypte juste au sud d\\\'ici... la grille semble ?tre bloqu?e, mais peut-?tre que si toi, tu essayes... ');
INSERT INTO `npc_questions` VALUES (3878, '', '', '', '', 'Oui, c\\\'est ?a qu\\\'il nous faut... Par contre, j\\\'ai pas bien compris si Yse Vewybad cherche ? tuer ou ? engager des Roublards.  Peut-?tre que toi tu comprendras mieux... On a qu\\\'? aller demander ? Yse Vewybad. ');
INSERT INTO `npc_questions` VALUES (3879, '', '', '', '', 'Ah, tr?s bien, vous avez trouv? un moyen de rentrer ! Bravo ! Bon, maintenant, allez trouver Vil. Surtout pas de combat ! Je veux juste lui parler !');
INSERT INTO `npc_questions` VALUES (3880, '', '', '', '', 'Hein ! Que fais-tu l? ? Que veux-tu ? Quoi ! M\\\'engager ! Sache que mes services sont chers et que je ne les offre pas ? m\\\'inporte qui.');
INSERT INTO `npc_questions` VALUES (3881, '', '', '', '', 'Pourquoi veut-il mes services ? Ne peut-il engager quelqu\\\'un d\\\'autre ?');
INSERT INTO `npc_questions` VALUES (3882, '', '', '', '', 'Alors ?a ne m\\\'int?resse pas!');
INSERT INTO `npc_questions` VALUES (3883, '', '', '', '', 'De la flatterie, bien essay?... Bien, vermisseau, j\\\'irai voir ton patron. Ah oui, redonne-moi ton insigne Roublard, tu ne le m?rites pas encore...');
INSERT INTO `npc_questions` VALUES (3884, '', '', '', '', 'Pnj(84) et Message(3880)');
INSERT INTO `npc_questions` VALUES (3885, '', '', '', '', 'Pnj(84) et Message(3880)');
INSERT INTO `npc_questions` VALUES (3886, '', '', '', '', 'Pnj(84) et Message(3881)');
INSERT INTO `npc_questions` VALUES (3887, '', '', '', '', 'Ouisshhh, vous d?sssirez parler ? Vil Smissshe. Sssh\\\'est d\\\'accord. Ssshuivez-moi, ssshhh.');
INSERT INTO `npc_questions` VALUES (3888, '', '', '', '', 'Osshhh, vous ?tes perssshhhistant, ssshh\\\'est bien.. Ssshuivez-moi, ssshhh.');
INSERT INTO `npc_questions` VALUES (3889, '', '', '', '', 'mon texte.');
INSERT INTO `npc_questions` VALUES (3890, '', '', '', '', 'texte2');
INSERT INTO `npc_questions` VALUES (3893, '', '', '', '', 'Reviens plus tard, je r?fl?chis ? mon prochain plan.');
INSERT INTO `npc_questions` VALUES (3895, '', '', '', '', 'Alors, on veut prouver sa valeur... va donc agresser un neutre... n\\\'h?site pas ? demander de l\\\'aide, ils sont bien prot?g?s...');
INSERT INTO `npc_questions` VALUES (3896, '', '', '', '', 'Bonjour, loyal sujet ! Longue vie ? notre Roi bien-aim? ! Puisse-t-il r?gner encore de nombreuses ann?es !');
INSERT INTO `npc_questions` VALUES (3897, '', '', '', '', 'Bonjour, Loyal sujet ! J\\\'ai besoin de ton aide, peux-tu me rendre quelques services ? Tu seras r?compens? de tes efforts.');
INSERT INTO `npc_questions` VALUES (3898, '', '', '', '', 'Un complot ! Oh, par les Douze ! As-tu des preuves ?');
INSERT INTO `npc_questions` VALUES (3899, '', '', '', '', 'Alors, finalement, tu viens nous aider ou pas ?');
INSERT INTO `npc_questions` VALUES (3900, '', '', '', '', 'Bien, bon choix...N\\\'oublie pas de montrer ton parchemin de recommandation, pour ?tre reconnu de mes autres ? amis ?. Pour l\\\'instant, tu n\\\'es qu\\\'? l\\\'essai, il va te falloir prouver ta loyaut? envers notre cause. Demande donc ? Vil Smisse ce qu\\\'il attend de ses roublards...');
INSERT INTO `npc_questions` VALUES (3901, '', '', '', '', 'Pnj(893) et Message(3899)');
INSERT INTO `npc_questions` VALUES (3903, '', '', '', '', 'Je vais doubler la s?curit?... Puisque tu m\\\'as averti, je te prends ? mon service. Si tu reviens plus tard, j\\\'aurai sans doute du travail pour toi.');
INSERT INTO `npc_questions` VALUES (3905, '', '', '', '', 'Tout va bien le plan se d?roule comme pr?vu.');
INSERT INTO `npc_questions` VALUES (3906, '', '', '', '', 'Alors reviens lorsque tu en sauras plus, je ne peux rien faire sans preuves.');
INSERT INTO `npc_questions` VALUES (3907, '', '', '', '', 'Bonjour, je m\\\'appelle Frost Hize, je suis un ancien disciple de Xavier le Boulanger. Aujourd\\\'hui j\\\'ai ma propre boulangerie, ici ? Astrub, et mes affaires se portent bien, tu peux me croire !');
INSERT INTO `npc_questions` VALUES (3908, '', '', '', '', 'Tiens un visiteur... Tu es perspicace pour avoir trouv? cette cachette... Pour la peine, je te remets ceci.');
INSERT INTO `npc_questions` VALUES (3909, '', '', '', '', 'Ah mon fid?le ami, c\\\'est un plaisir de te revoir.');
INSERT INTO `npc_questions` VALUES (3910, '', '', '', '', 'Ta visite tombe ? pic, le roi cherche une personne de confiance pouvant faire bonne figure aupr?s de la noblesse. C\\\'est une mission de confiance et je sais que tu sauras servir ton roi de la meilleure fa?on.');
INSERT INTO `npc_questions` VALUES (3911, '', '', '', '', 'Je n\\\'en attendais pas moins de toi. Le fr?re du roi, Fallaster, veut marier sa fille la princesse Allisteria. Cette t?che en incombe bien s?r ? sa majest? le roi Allister. J\\\'ai eu l\\\'honneur de le d?charger un peu de cette lourde t?che. Il faut trouver un pr?tendant. Cherche un noble de haute lign?e et reviens quand tu auras d?nich? cette perle rare.');
INSERT INTO `npc_questions` VALUES (3912, '', '', '', '', 'Un noble ? Il y en a beaucoup ici mais digne de la princesse, je n\\\'en connais pas.');
INSERT INTO `npc_questions` VALUES (3913, '', '', '', '', 'Trouver un beau et noble chevalier ne va pas ?tre simple, je ne vous envie pas mais vous souhaite bon courage.');
INSERT INTO `npc_questions` VALUES (3914, '', '', '', '', 'Je connais la plupart des dames et seigneurs de la cour. Aucun n\\\'est un pr?tendant digne de ce nom ? mon avis.');
INSERT INTO `npc_questions` VALUES (3915, '', '', '', '', 'Si j\\\'ai vu un noble ? Oui bien s?r, j\\\'en ai m?me vu beaucoup, mais  avec ce qu\\\'ils boivent ici, la seule princesse qu\\\'ils peuvent ?pouser, c\\\'est la princesse chopine.');
INSERT INTO `npc_questions` VALUES (3916, '', '', '', '', 'Je crois avoir entendu parler d\\\'un prince venu du lointain pays d\\\'Wa. Je n\\\'avais jamais entendu parl? de ce pays avant. Non, je ne sais pas o? il se trouve en ce moment.');
INSERT INTO `npc_questions` VALUES (3917, '', '', '', '', 'Hum, je ne sais pas ce que manigance mon oncle, mais ma nourrice m\\\'a fait venir au ch?teau et a pris mes mesures pour une robe. C\\\'est bizarre quand m?me, je porte la m?me chose depuis des lustres et tout d\\\'un coup on veut me faire une nouvelle robe !');
INSERT INTO `npc_questions` VALUES (3918, '', '', '', '', 'Le prince d\\\'Wa ? Oui, je crois qu\\\'il chasse au sud de Bonta, mais je ne sais pas o? pr?cis?ment. En plus, je crois qu\\\'il est parti seul, ?trange pour un prince.');
INSERT INTO `npc_questions` VALUES (3919, '', '', '', '', 'Le prince d\\\'Oy ? Oui, je crois qu\\\'il chasse au sud de Bonta, mais je ne sais pas o? pr?cis?ment. En plus, je crois qu\\\'il est parti seul, ?trange pour un prince.');
INSERT INTO `npc_questions` VALUES (3920, '', '', '', '', 'Bonjour, loyal sujet ! Longue vie ? notre Roi bien-aim? ! Puisse-t-il r?... Hein, quoi ? S\\\'il se passe quelque chose de particulier au ch?teau ? Pourquoi vous me demandez ?a ? Allez donc voir ailleurs si j\\\'y suis !');
INSERT INTO `npc_questions` VALUES (3921, '', '', '', '', 'Le conseiller Yse est tr?s d?termin? mais pas tr?s inform? : il ne sait pas comment porter pr?judice au roi... Et il a ?t? d?masqu? en plus ! Ni lui ni moi ne pouvons nous renseigner plus avant. C\\\'est donc toi qui va y aller, d\\\'accord ? Tiens, voil? quelques kamas pour t\\\'?quiper.');
INSERT INTO `npc_questions` VALUES (3922, '', '', '', '', 'Alors ! Va donc au ch?teau, demande ? l\\\'entourage royal, fouille chaque recoin ! Faut vraiment tout te dire...');
INSERT INTO `npc_questions` VALUES (3923, '', '', '', '', 'Ah, le roi marie sa ni?ce... ? Hum... Peut-?tre qu\\\'on peut mettre un Prince ? notre solde... Sais-tu s\\\'il y a d?j? un pr?tendant ?');
INSERT INTO `npc_questions` VALUES (3924, '', '', '', '', 'Un prince Wabbit hein ? Bien... Laisse-moi un peu de temps que j\\\'?chafaude un plan....');
INSERT INTO `npc_questions` VALUES (3925, '', '', '', '', 'Alors, qui est le pr?tendant ?');
INSERT INTO `npc_questions` VALUES (3926, '', '', '', '', 'Des choses ?tranges au ch?teau ? non, ? part la visite d\\\'Allisteria. D\\\'habitude, elle ne quitte jamais ses bouftous.');
INSERT INTO `npc_questions` VALUES (3927, '', '', '', '', 'Des choses ?tranges au ch?teau ? Non, ? part la visite d\\\'Allisteria. D\\\'habitude, elle ne quitte jamais ses bouftous. Ah oui, et l\\\'intendant San Lavalss a strictement interdit de cuisiner du wabbit au ch?teau.');
INSERT INTO `npc_questions` VALUES (3928, '', '', '', '', 'Des choses ?tranges au ch?teau ? Non, ? part la visite d\\\'Allisteria. D\\\'habitude, elle ne quitte jamais ses bouftous.');
INSERT INTO `npc_questions` VALUES (3929, '', '', '', '', 'Des choses ?tranges au ch?teau ? Non, j\\\'ai juste vu passer Allisteria r?cemment.');
INSERT INTO `npc_questions` VALUES (3930, '', '', '', '', 'Des choses ?tranges au ch?teau ? Non, on a juste eu la visite de la petite Allisteria. Enfin, petite, elle est grande maintenant, en ?ge d\\\'?tre mari?e!');
INSERT INTO `npc_questions` VALUES (3931, '', '', '', '', 'Ah, je l\\\'avais bien pr?dit que je serai r?compens?e de mon talent ! M?me le roi fait appel ? moi !');
INSERT INTO `npc_questions` VALUES (3932, '', '', '', '', 'Ah, un connaisseur ! Sais-tu ce qu\\\'on m\\\'a demand? derni?rement ? Je te pr?dis que je te le dirai pour 10 fils de soie.');
INSERT INTO `npc_questions` VALUES (3933, '', '', '', '', 'Hum, hein... non, je r?fl?chis ? ma prochaine cr?ation, pour le roi... d?p?che-toi de m\\\'apporter ces fils, je vais en avoir besoin!');
INSERT INTO `npc_questions` VALUES (3934, '', '', '', '', 'Ah, merci ! Tu vois, cette soie va me servir ? coudre la robe de mari?e de la ni?ce du Roi, Allisteria ! Et je peux te pr?dire que ce sera un chef d\\\'oeuvre !');
INSERT INTO `npc_questions` VALUES (3935, '', '', '', '', 'Oui, j\\\'ai ramen? beaucoup de cawottes de l\\\'?le... Il para?t qu\\\'un prince Wabbit doit venir en Amakna.');
INSERT INTO `npc_questions` VALUES (3936, '', '', '', '', 'Pff, j\\\'ai jamais autant boss? ! J\\\'ai d? porter des sacs de jute depuis le b?teau de Lily jusqu\\\'au ch?teau ! Je suis mort de soif d\\\'ailleurs...');
INSERT INTO `npc_questions` VALUES (3937, '', '', '', '', 'Ah, ce feignant de Gueudin bosse enfin, il a des sacs de jute ? porter au ch?teau.');
INSERT INTO `npc_questions` VALUES (3938, '', '', '', '', 'Ah, ?a bouge au ch?teau. Tu devrais demander ? Guedin, c\\\'est lui qui leur porte des sacs.');
INSERT INTO `npc_questions` VALUES (3941, '', '', '', '', 'Ah te revoil?, tant mieux. Voil? le plan : tu vas te faire passer pour le prince. Tout d\\\'abord, trouve le moyen de te faire passer pour un Wabbit. Un potion devrait faire l\\\'affaire. Ensuite va au ch?teau et fais-toi passer pour le prince;\\r\\n            dis que tu refuses ce mariage ou ce que tu veux, ce qui compte c\\\'est d\\\'emp?cher cette union.');
INSERT INTO `npc_questions` VALUES (3942, '', '', '', '', 'Oh, une potion de transformation en Wabbit ? C\\\'est compliqu? ?a, et je n\\\'ai pas les connaissances pour la faire seul... Il me faudrait l\\\'aide de mes coll?gues en Amakna. Tu veux bien aller les voir de ma part ? L\\\'un est au nord-ouest, l\\\'autre au sud et le dernier au centre d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (3943, '', '', '', '', 'Pnj(166) et Message(3942)');
INSERT INTO `npc_questions` VALUES (3944, '', '', '', '', 'Ta formule n\\\'est pas encore compl?te, je ne peux rien faire pour le moment.');
INSERT INTO `npc_questions` VALUES (3945, '', '', '', '', 'Ah, tu as la formule, bien ! Pourrais-tu aller me chercher les ingr?dients maintenant ?');
INSERT INTO `npc_questions` VALUES (3946, '', '', '', '', 'Il me faut tous les ingr?dients, sinon je ne peux pr?parer ta potion.');
INSERT INTO `npc_questions` VALUES (3947, '', '', '', '', 'Bien, j\\\'ai presque termin?. Laisse moi quelques instants, je touille comme ?a, je baisse le feu et te voil? un Wabbit!');
INSERT INTO `npc_questions` VALUES (3948, '', '', '', '', 'Oh, un Wabbit, Soyez le bienvenu dans nos murs, noble pwince!');
INSERT INTO `npc_questions` VALUES (3949, '', '', '', '', 'Oh, sieur Wabbit, vous ?tes d?j? arri... je veuw diwe, awiv? au ch?teau? Soyez le bienvenu en ces muws, pwince.');
INSERT INTO `npc_questions` VALUES (3950, '', '', '', '', 'Bonjour, ma?tre Wabbit, puis-je vous aider ? Voulez-vous v?rifier que tout est pr?t pour l\\\'arriv?e de votre prince ?');
INSERT INTO `npc_questions` VALUES (3951, '', '', '', '', 'Ah, mais c\\\'est qu\\\'on ne vous attendait pas tout de suite...');
INSERT INTO `npc_questions` VALUES (3953, '', '', '', '', 'Horrible mariage ? Mais, Allisteria est... Eh! attendez  un instant ! Vous ne parlez pas comme un Wabbit, vous n\\\'?tes pas le prince ! Ah moi, mon fid?le Bouftou !');
INSERT INTO `npc_questions` VALUES (3954, '', '', '', '', 'Ah, Uba Tess? t\\\'envoie ? Tu lui passeras le bonjour de ma part, et ce parchemin.');
INSERT INTO `npc_questions` VALUES (3955, '', '', '', '', 'Ah, ce cher Uba... Tiens, prend ce recueil et ins?res-y ce que tu apprendras, je pense que ?a t\\\'aidera.');
INSERT INTO `npc_questions` VALUES (3956, '', '', '', '', 'Uba t\\\'envoie, hein? Je te donne ce parchemin de bon coeur alors.');
INSERT INTO `npc_questions` VALUES (3957, '', '', '', '', 'Bon, on va essayer autre chose... Trouve-moi un nid de Tofu Ob?se et rapporte un oeuf. Fais vite!');
INSERT INTO `npc_questions` VALUES (3958, '', '', '', '', 'Bien, tu as le tofu ? Quoi, mais c\\\'est un b?b? !? Idiot, il ne sera jamais assez puissant pour tuer le prince ! Va donc voir un ?leveur, il pourra sans doute te donner de quoi l\\\'engraisser rapidement. Et fais vite !');
INSERT INTO `npc_questions` VALUES (3959, '', '', '', '', 'Ah, enfin! Donne-moi l\\\'oeuf et la potion, je vais les mettre sur le passage du prince.');
INSERT INTO `npc_questions` VALUES (3960, '', '', '', '', 'Une potion de gavage ? Tu as de la chance, je viens d\\\'en mettre une au point, tu seras le premier ? la tester !');
INSERT INTO `npc_questions` VALUES (3961, '', '', '', '', 'L\\\'attentat avec le tofu a ?chou?... Je crois qu\\\'on va faire les chose ? la mode roublarde et simplement empoisonner ce \\\"chew pwince\\\" avec un blopisier empoisonn');
INSERT INTO `npc_questions` VALUES (3962, '', '', '', '', 'Alors, ce blopisier ?');
INSERT INTO `npc_questions` VALUES (3963, '', '', '', '', 'C\\\'est bien, tu as ce que je t\\\'avais demand?... par contre, on ne va pas pouvoir s\\\'en servir, j\\\'ai appris que le prince aurait un go?teur. Apporte-moi des kamas pour engager des assassins.');
INSERT INTO `npc_questions` VALUES (3964, '', '', '', '', 'Tu me les apportes ces kamas, oui ou non ?');
INSERT INTO `npc_questions` VALUES (3965, '', '', '', '', 'C\\\'est bien, va pour le moment. Je vais recruter quelques lames, reviens me voir plus tard.');
INSERT INTO `npc_questions` VALUES (3966, '', '', '', '', 'Les assassins que j\\\'ai pu trouver ne pourront pas passer la s?curit? qui entoure le prince. Trouve un Lenald, avec ton aide et sa magie il devrait ?tre en mesure de se t?l?porter dans la salle du tr?ne le jour du mariage.');
