INSERT INTO `npc_questions` VALUES (3976, '', '', '', '', 'Quoi ? Tuer un prince Wabbit lols de son malliage ? Mais c\\\'est tl?s dangeleux.');
INSERT INTO `npc_questions` VALUES (3977, '', '', '', '', 'Notle peuple letlouvla sa gloile pass?e !');
INSERT INTO `npc_questions` VALUES (3978, '', '', '', '', 'Oui c\\\'est s?l ! Mais comment l\\\'applocher ?');
INSERT INTO `npc_questions` VALUES (3979, '', '', '', '', 'Oui tappez ma papatte et mettez vous en loute.');
INSERT INTO `npc_questions` VALUES (3980, '', '', '', '', 'Oui c\\\'est possible ! Si vous l?ussissez ? entler, je viendlai animer cette soil?e.');
INSERT INTO `npc_questions` VALUES (3981, '', '', '', '', 'Ah, des tofus? Demandez donc ? Shika, elle vous renseignera mieux.');
INSERT INTO `npc_questions` VALUES (3982, '', '', '', '', 'Vous voulez un tofu ? Et bien en fait, j\\\'ai un tofu ob?se qui s\\\'est ?chapp? du tofulailler... Je crois qu\\\'il a fait son nid dans la meule de foin, l?, devant.');
INSERT INTO `npc_questions` VALUES (3983, '', '', '', '', 'Que me veux tu ? Ne vois tu point que je questois ? Je dois vaincwe une cw?atuwe digne de ma lign?e. Selon les diwes d\\\'un pewsonnage habill? de noiw, un tofu se tewwe en ces contw?es, je dois le tewwasser si je veux acc?der au tw?ne un jouw.');
INSERT INTO `npc_questions` VALUES (3984, '', '', '', '', 'Quelle contw?e magnifique, on la diwait peinte paw les awtistes les plus fins et les plus gwands de tous les temps !');
INSERT INTO `npc_questions` VALUES (3985, '', '', '', '', 'Silence ignowant, le monstwe appwoche, ne l\\\'entends-tu pas ? Il est twop tawd maintenant, il va nous sauter ? la gowge, pw?pawe-toi, tu vas me sewviw d\\\'?cuyew puisque tu es l? ! Tiwons nos lames de leuws fouweaux et powtons la guewe ? ce monstwe.');
INSERT INTO `npc_questions` VALUES (3986, '', '', '', '', 'Victowieux ! Je suis victowieux ! Au fait, je ne t\\\'ai point demand? ce qui t\\\'a conduit en ces tewwes hostiles.');
INSERT INTO `npc_questions` VALUES (3987, '', '', '', '', 'Tudieu, une pwincesse ? mawier ! Que voil? une nouvelle int?wessante. Je suis ton pwince ! Pawtons c?ans !');
INSERT INTO `npc_questions` VALUES (3988, '', '', '', '', 'Peu me chaut ! Allons bon twain qu?wir des suivants.');
INSERT INTO `npc_questions` VALUES (3989, '', '', '', '', 'Ne me distwait point, nous avons ? faiwe.');
INSERT INTO `npc_questions` VALUES (3990, '', '', '', '', 'Paw les dieux, quel ?tait ce monstwe ? Ma vaillance a pw?valu sur sa cwuaut?. Que cela ne me d?touwne point de ma qu?te, j\\\'ai une pwincesse ? ?pouser ! Deviens un peu plus fowt et tu pouwwas faiwe pawtie de ma suite!');
INSERT INTO `npc_questions` VALUES (3991, '', '', '', '', 'Deviens un peu plus fowt et tu pouwwas faiwe pawtie de ma suite!');
INSERT INTO `npc_questions` VALUES (3992, '', '', '', '', 'Ah, tu es assez fowt maintenant, je veux bien te pwendwe pawmi mes compagnons. Mais toi seul ne suffiwas pas... va donc me wecwuter d\\\'autwes suivants, si tu t\\\'en sens capable.');
INSERT INTO `npc_questions` VALUES (3993, '', '', '', '', 'Qu\\\'attends tu de moi ? Que je serve un Wabbit ? Ils sont faibles, ne savent gu?re manier les armes et s\\\'expwiment bizawement !');
INSERT INTO `npc_questions` VALUES (3994, '', '', '', '', 'Il n\\\'y a d\\\'honneur que dans la bataille et non dans la servitude !');
INSERT INTO `npc_questions` VALUES (3995, '', '', '', '', 'Esp?ce de freluquet! Je vais te montrer!');
INSERT INTO `npc_questions` VALUES (3996, '', '', '', '', 'Qu\\\'attends tu de moi ? Que je serve un Wabbit ? Ils sont faibles, ne savent gu?re manier les armes et s\\\'expwiment bizawement !');
INSERT INTO `npc_questions` VALUES (3997, '', '', '', '', 'Pnj(664) et Message(3996)');
INSERT INTO `npc_questions` VALUES (3998, '', '', '', '', 'Il n\\\'y a d\\\'honneur que dans la bataille, pas dans  la servitude !');
INSERT INTO `npc_questions` VALUES (3999, '', '', '', '', 'Chopine? Oh, tu ne m?rites m?me pas que je m\\\'occupe de toi moi-m?me! Disciple, viens r?gler son compte ? ce jeune impudent!');
INSERT INTO `npc_questions` VALUES (4000, '', '', '', '', 'Tu m\\\'intrigues, comment feras-tu cela?');
INSERT INTO `npc_questions` VALUES (4001, '', '', '', '', 'Je suis bien trop fort pour toi, mais si tu bats mon meilleur disciple, alors je servirai ton prince.');
INSERT INTO `npc_questions` VALUES (4002, '', '', '', '', 'Bizarres? D?guerpis avant que je m\\\'?nerve !');
INSERT INTO `npc_questions` VALUES (4003, '', '', '', '', 'Moi, cuisiner pour un Wabbit ? Il ne mangent que des cawottes crues ! Aucun int?r?t. Il va falloir me motiver plus que ?a.');
INSERT INTO `npc_questions` VALUES (4004, '', '', '', '', 'Oui, mais apr?s ? Il faut que la paie soit bonne ! Je ne resterai pas cuisini?re toute ma vie...');
INSERT INTO `npc_questions` VALUES (4005, '', '', '', '', 'Pas assez!');
INSERT INTO `npc_questions` VALUES (4006, '', '', '', '', 'Pnj(335) et Message(4004)');
INSERT INTO `npc_questions` VALUES (4007, '', '', '', '', 'March? conclu !');
INSERT INTO `npc_questions` VALUES (4008, '', '', '', '', 'Pnj(335) et Message(4004)');
INSERT INTO `npc_questions` VALUES (4009, '', '', '', '', 'Ah, pauvre de moi ! mon ma?tre m\\\'a mis ? la rue ! Moi un si bon serviteur !');
INSERT INTO `npc_questions` VALUES (4010, '', '', '', '', 'Moi, servir un prince ? J\\\'aimerais bien, beau sire, mais je n\\\'ai pas la livraie idoine ...');
INSERT INTO `npc_questions` VALUES (4011, '', '', '', '', 'Oui, tu m\\\'as prouv? ta force... C\\\'est d\\\'accord, je servirai ton  prince.');
INSERT INTO `npc_questions` VALUES (4012, '', '', '', '', 'Oh, merci, une livr?e ! Je servirai donc ton prince, noble sire.');
INSERT INTO `npc_questions` VALUES (4013, '', '', '', '', 'Humpf ! Si je pouvais me faire embaucher, je gagnerais au moins quelques kamas honn?tement !');
INSERT INTO `npc_questions` VALUES (4014, '', '', '', '', 'Servir un prince, hein? Il doit ?tre riche, s\\\'il est prince, non ? Alors, combien il paie ?');
INSERT INTO `npc_questions` VALUES (4015, '', '', '', '', 'C\\\'est une somme correcte, je vous suis. Vous avez une tenue pour moi ?');
INSERT INTO `npc_questions` VALUES (4016, '', '', '', '', 'Une livraie de valet pour un prince Wabbit ? C\\\'est une commande peu commune, je n\\\'ai pas les ?toffes n?cessaires. Il me faut un tissu pourpre, comme celui qu\\\'on trouve sur les bwork mage. J\\\'assemblerai le tout avec dix fils de soie. Si vous me trouvez cela, je vous confectionnerai un habit digne d\\\'un valet de prince.');
INSERT INTO `npc_questions` VALUES (4017, '', '', '', '', 'Ah bien, voil? donc votre livraie.');
INSERT INTO `npc_questions` VALUES (4018, '', '', '', '', 'Voil? donc mes gens, malgw? leuw t?te bizawwe, ils suffiwont. Hum, je vais encowe un peu me pwomener dans cette belle contw?e avant d\\\'aller au ch?teau.');
INSERT INTO `npc_questions` VALUES (4019, '', '', '', '', 'Ah, te wevoil?, gentil ?cuyer ! Je voulais te dem...');
INSERT INTO `npc_questions` VALUES (4020, '', '', '', '', 'Idiot, tu t\\\'es fait d?masqu? ! Pars avant que je m\\\'?nerve !');
INSERT INTO `npc_questions` VALUES (4021, '', '', '', '', 'L\\\'attentat avec le tofu a ?chou?. Laisse-moi r?fl?chir ? un nouveau plan.');
INSERT INTO `npc_questions` VALUES (4022, '', '', '', '', 'Laisse-moi r?fl?chir, veux-tu !');
INSERT INTO `npc_questions` VALUES (4023, '', '', '', '', 'Laisse-moi r?fl?chir en paix!');
INSERT INTO `npc_questions` VALUES (4024, '', '', '', '', 'On ose s\\\'en pwendwe ? ma pewsonne ! Quelle est cette infamie ! Je connais cette engeance, il ne s\\\'aw?tewont pas l?. Toi, fid?le sewviteuw, d?masques ces fouwbes !');
INSERT INTO `npc_questions` VALUES (4025, '', '', '', '', 'Je n\\\'en attendais pas moins de toi !');
INSERT INTO `npc_questions` VALUES (4026, '', '', '', '', 'Une potion de transformation en Wabbit ! Tiens, vous ?tes le deuxi?me aujourd\\\'hui ? me demander ?a... le pr?c?dent a fait des recherches ? ma demande, mais apparemment la formule n\\\'a pas correctement fonctionn?, il faut tout reprendre du d?but. Pourriez-vous allez visiter mes coll?gues en Amakna ?');
INSERT INTO `npc_questions` VALUES (4027, '', '', '', '', 'La formule n\\\'est pas compl?te? Mais j\\\'ai d?j? dit tout ce que je savais...');
INSERT INTO `npc_questions` VALUES (4028, '', '', '', '', 'La formule n\\\'est pas compl?te? Mais j\\\'ai d?j? dit tout ce que je savais...');
INSERT INTO `npc_questions` VALUES (4029, '', '', '', '', 'Une formule de transformation en Wabbit! Montrez-moi un peu ce parchemin... b?ton, hum hum... cawottes, chanvre, oui... Ah, je sais! Il manque des dents de Wabbit! Pas ?tonnant que mes coll?gues n\\\'aient pas su, je suis le seul alchimiste sp?cialiste des os en Amakna!');
INSERT INTO `npc_questions` VALUES (4030, '', '', '', '', 'La formule n\\\'est pas compl?te? Mais j\\\'ai d?j? dit tout ce que je savais...');
INSERT INTO `npc_questions` VALUES (4031, '', '', '', '', 'Ah mais oui, des dents de Wabbit! Malheureusement, j\\\'ai utilis? toutes mes r?serves pour la potion pr?c?dente... Pourriez-vous aller chercher les ingr?dients, s\\\'il vous pla?t?');
INSERT INTO `npc_questions` VALUES (4032, '', '', '', '', 'Avez-vous des ingr?dients ? me donner ?');
INSERT INTO `npc_questions` VALUES (4033, '', '', '', '', 'Ah mais oui, des dents de Wabbit ! Malheureusement, j\\\'ai utilis? toutes mes r?serves pour la potion pr?c?dente... Pourriez-vous aller chercher les ingr?dients, s\\\'il vous pla?t ?');
INSERT INTO `npc_questions` VALUES (4034, '', '', '', '', 'Ah, merci, voil? les ingr?dients. Attends un peu, je fais chauffer, je touille dans ce sens, puis dans l\\\'autre, et voil? ta potion!');
INSERT INTO `npc_questions` VALUES (4035, '', '', '', '', 'Bonjour ! Ravi de te revoir mon ami ! Pourrais-tu m\\\'aider encore une fois ?');
INSERT INTO `npc_questions` VALUES (4036, '', '', '', '', 'Une catastrophe nous tombe dessus. Les parents du mari? sont des Wabbits forc?ment. Et forc?ment, leurs convives sont amateurs de cawottes. Or nous n\\\'en avons pas ici. Tu veux bien aller m\\\'en chercher ?');
INSERT INTO `npc_questions` VALUES (4037, '', '', '', '', 'Maintenant il faudrait aller chercher la robe de la mari?e ? Bonta. Peux-tu t\\\'en charger?');
INSERT INTO `npc_questions` VALUES (4038, '', '', '', '', 'La robe de la mari?e ? Oui, elle est pr?te, mais pas le voile: l\\\'intendant a demand? un voile opaque, qui cache ? la mari?e son futur mari. Mais je n\\\'ai pas l\\\'?toffe pour cela... Je te pr?dis qu\\\'avec 10 ?toffes de Wabbit, cette robe sera ma plus belle pi?ce !');
INSERT INTO `npc_questions` VALUES (4039, '', '', '', '', 'Attends, il ne me faut que quelques instants, et mon chef-d\\\'oeuvre sera complet!');
INSERT INTO `npc_questions` VALUES (4040, '', '', '', '', 'Bien, tu as la robe! Et bien le mariage va pouvoir commencer!');
INSERT INTO `npc_questions` VALUES (4041, '', '', '', '', 'Attention, le monstwe wevient!');
INSERT INTO `npc_questions` VALUES (4042, '', '', '', '', 'Alors, je serai honor? de servir un prince.');
INSERT INTO `npc_questions` VALUES (4043, '', '', '', '', 'Merci ! Est-ce tout ?');
INSERT INTO `npc_questions` VALUES (4044, '', '', '', '', 'Ah tr?s bien, je vous fais la potion de suite alors.');
