INSERT INTO `npc_questions` VALUES (4051, '', '', '', '', 'Bonjour. Je vois que vous ?tes une farouche combattante... Souhaiteriez-vous aider ? prot?ger Amakna et le tr?ne d\\\'Allister ?');
INSERT INTO `npc_questions` VALUES (4052, '', '', '', '', 'Pnj(893) et Message(4051)');
INSERT INTO `npc_questions` VALUES (4053, '', '', '', '', 'Pnj(893) et Message(4051)');
INSERT INTO `npc_questions` VALUES (4054, '', '', '', '', 'Oh quel affront, je suis la plus grande couturi?re de Bonta, les plus grands font appel ? mes doigts de f?e pour confectionner leurs plus belles tenues.');
INSERT INTO `npc_questions` VALUES (4055, '3531', '', '', '', 'Bonjour aventurier. Comme tu peux le voir, je suis bien Montay, le c?l?bre Garde Montay ! \\nJe suis le responsable des montures de notre roi Allister, j\\\'ai pour mission de lui en trouver de nouvelles, afin d\\\'?quiper tous ses hommes. \\nVoudrais-tu m\\\'aider ?');
INSERT INTO `npc_questions` VALUES (4056, '', '', '', '', 'Je savais que tu ?tais quelqu\\\'un de respectable malgr? ton apparence douteuse et ton sourire niais ! \\nBon c\\\'est simple, je recherche toute sorte de monture, rousse, verte, ras?e, poilue, malodorante, immature, st?rile, tout m\\\'int?resse, sauf celles qui sont d?j? mortes. Hahahaha ! \\nRapporte-moi les certificats de monture et je te donnerai en ?change des parchemins que j\\\'ai trouv?s dans la biblioth?que. Tu peux m?me me rapporter des certificats invalides, je me d?brouillerai pour les falsifier.');
INSERT INTO `npc_questions` VALUES (4057, '', '', '', '', 'Un prince Wabbit, c\\\'est mieux que rien, avec un peu d\\\'ash... pardon, d\\\'astuce je devrais pouvoir arranger tout le monde. Laisse-moi ?tudier les pr?paratifs. Pendant ce temps, trouve ce prince et convaincs le d\\\'?pouser la princesse.');
INSERT INTO `npc_questions` VALUES (4058, '3543;3532;3577;353', '', '', '0', 'Bonjour, je suis Otoma?, un des plus c?l?bres enchanteurs du monde des douze, le sp?cialiste incontest? de tout ce qui anime et r?git le vivant. Je suis ?galement r?put? pour mes talents d\\\'alchimiste qui me permettent de cr?er des potions aux effets divers et vari?s. \\nQue veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (4059, '', '', '', '', 'Mes potions sont tellement efficaces, qu\\\'elles te feront oublier tes sortil?ges, comme aucune autre potion ne pourrait le faire. Une fois que tu auras bu ma potion, le sort que tu oublieras se retrouvera directement ? son niveau de puissance le plus faible ! \\nTu pourras ainsi apprendre plus rapidement d\\\'autres sorts et changer ta fa?on de combattre.');
INSERT INTO `npc_questions` VALUES (4060, '', '', '', '', 'Quel sort veux-tu oublier ?');
INSERT INTO `npc_questions` VALUES (4061, '', '', '', '', 'Quel sort veux-tu oublier ?');
INSERT INTO `npc_questions` VALUES (4062, '', '', '', '', 'Quel sort veux-tu oublier ?');
INSERT INTO `npc_questions` VALUES (4063, '', '', '', '', 'Quel sort veux-tu oublier ?');
INSERT INTO `npc_questions` VALUES (4064, '', '', '', '', 'Quel sort veux-tu oublier ?');
INSERT INTO `npc_questions` VALUES (4065, '', '', '', '', 'Je suis d?sol?, mais tu ne t\\\'es pas encore montr? assez vaillant pour que je puisse t\\\'offrir un oubli de sort. Affronte d\\\'autres cr?atures mythiques de cette ?le et reviens me voir ensuite.');
INSERT INTO `npc_questions` VALUES (4066, '3698;3705;370', '', '', '0', 'J\\\'ai d?couvert cette ?le il y a plusieurs ann?es, un peu par hasard je dois bien l\\\'avouer. Je cherchais une sorte de nouvel ?den, une ?le vierge de toutes les perversions que nous pouvons trouver sur le continent... \\nJ\\\'ai trouv? cette ?le par erreur, j\\\'en cherchais une autre et mon bateau s\\\'est ?chou? ici. J\\\'aurais pu avoir beaucoup moins de chance, cette ?le est tout simplement magnifique.');
INSERT INTO `npc_questions` VALUES (4067, '356', '', '', '0', 'Je suis d?sol?, mais tu ne poss?des pas les ingr?dients n?cessaires qu\\\'il me faut pour te cr?er la bonne potion.');
INSERT INTO `npc_questions` VALUES (4068, '', '', '', '', 'Salut!');
INSERT INTO `npc_questions` VALUES (4069, '534', '', '', '0', 'J\\\'ai tent? jadis, de r?unir toutes les esp?ces animales vivantes connues ? ce jour en un m?me lieu, sur cette ?le. \\nMalheureusement, l\\\'instinct parfois belliqueux de certaines cr?atures a fait ?chouer toutes mes tentatives, je n\\\'ai jamais r?ussi ? les faire cohabiter dans un espace restreint ou les acclimater au biotope de cette ?le.');
INSERT INTO `npc_questions` VALUES (4073, '', '', '', '', 'Je vois que tu commences ? regretter... Ce n\\\'est pas trop t?t ! \\nCependant, je ne te pardonnerai pas si facilement. Il va falloir que tu te rendes un peu utile une fois dans ta vie.');
INSERT INTO `npc_questions` VALUES (4074, '', '', '', '', 'J\\\'aimerais pouvoir me d?guiser en Koalak, et pour cela il me faudrait tout simplement une panoplie Koalak ! \\nRam?ne-moi une panoplie Koalak compl?te et en bon ?tat, et peut-?tre que je finirais par te pardonner. \\nSi je suis de bonne humeur, je te donnerai un de mes vieux familiers, il est tr?s difficile ? nourrir, il mord tr?s fort, il ne sent pas tr?s bon et il n\\\'est pas assez beau pour moi. Mais je pense qu\\\'il te plaira.');
INSERT INTO `npc_questions` VALUES (4075, '', '', '', '', 'Quel sort veux-tu oublier ?');
