INSERT INTO `npc_questions` VALUES (4084, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral pour pr?parer ta potion. Une fois r?duite en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4085, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral et une relique de Gourlo le Terrible pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4086, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, une relique de Gourlo le Terrible et une relique du Rasboul Majeur pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4087, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, une relique de Gourlo le Terrible, une relique du Rasboul Majeur et une relique du Tynril pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4088, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, une relique de Gourlo le Terrible, une relique du Rasboul Majeur, une relique du Tynril et une relique du Kimbo pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4089, '', '', '', '', 'Ce n\\\'est pas si simple, es-tu pr?t ? recommencer ?');
INSERT INTO `npc_questions` VALUES (4090, '', '', '', '', 'Attention, es-tu certain de vouloir oublier tous les niveaux de ce sort ?');
INSERT INTO `npc_questions` VALUES (4091, '', '', '', '', 'Maintenant il faudrait aller chercher la robe de la mari?e ? Bonta. Peux-tu t\\\'en charger ?');
INSERT INTO `npc_questions` VALUES (4092, '', '', '', '', 'Parfait, J\\\'en ai pour une seconde, voil? ... comme ?a ... un petite retouche ici ... Une robe magnifique, je te la confie');
INSERT INTO `npc_questions` VALUES (4093, '', '', '', '', 'Bon j\\\'ai fini cette potion, pr?t ? devenir Wabbit ?');
INSERT INTO `npc_questions` VALUES (4094, '', '', '', '', 'Hans y m\\\'a dit qu\\\'il voulait attraper une dragodinde, oui m\\\'dame ! M?me qu\\\'il m\\\'a dit qu\\\'il a trouv? une cabane dans la for?t que personne d\\\'autre ne conna?t.');
INSERT INTO `npc_questions` VALUES (4095, '', '', '', '', 'La recette de notre bi?re ? Si tu y tiens, de toutes fa?ons seuls les Bworks savent la pr?parer correctement.');
INSERT INTO `npc_questions` VALUES (4096, '', '', '', '', 'Hors de ma vue, parjure !');
INSERT INTO `npc_questions` VALUES (4097, '', '', '', '', 'Je n\\\'ai pas le temps, j\\\'ai tant d\\\'affaires ? r?gler !');
INSERT INTO `npc_questions` VALUES (4098, '', '', '', '', 'J\\\'ai entendu parler d\\\'un monde o? notre peuple est chass? pour sa fourrure, c\\\'est ridicule !');
INSERT INTO `npc_questions` VALUES (4099, '', '', '', '', 'J\\\'ai trouv? un nouveau ma?tre, je vais le rejoindre tout de suite.');
INSERT INTO `npc_questions` VALUES (4100, '', '', '', '', 'Quel sort veux-tu oublier ?');
INSERT INTO `npc_questions` VALUES (4101, '', '', '', '', '');
INSERT INTO `npc_questions` VALUES (4102, '', '', '', '', 'J\\\'aime trop les familiers pour accepter de les tuer et de donner leur d?pouille ? mon Dragoune pr?f?r?. Je pr?f?re les familiers vivants, mais la nature est ainsi faite, bienfaisante et cruelle ? la fois. Cependant, je suis pr?t ? vous ?changer n\\\'importe quel fant?me de familier et une poudre d\\\'Eniripsa, contre un nouveau familier en pleine forme ! \\nAttention cependant, ce nouveau familier en parfaite sant? sera tr?s jeune et vous devrez de nouveau refaire toute son ?ducation et son entra?nement.');
INSERT INTO `npc_questions` VALUES (4103, '', '', '', '', 'Tu as tous les ingr?dients n?cessaires et surtout tu as aid? mes amis, je t\\\'en remercie, et je suis pr?t ? mon tour ? t\\\'aider. \\nEn changeant ta constitution, tes caract?ristiques seront modifi?es. \\nTa chance, ta force, ton intelligence, ta sagesse, ta vitalit? et ton agilit? peuvent ainsi ?tre modifi?es. \\nJe peux te proposer deux potions diff?rentes qui permettent de changer sa constitution, la premi?re permet d\\\'oublier totalement tes caract?ristiques, alors que la deuxi?me est moins puissante. \\nFais attention, une fois que tu as auras bu une de ces potions, tu ne pourras plus revenir en arri?re, sans boire de nouveau une autre potion.');
INSERT INTO `npc_questions` VALUES (4104, '3795;369', '', '', '0', 'Je suis d?sol?, mais je ne peux pas te fabriquer de potion pour changer ta constitution, tu ne disposes pas des bons ingr?dients. Ces potions sont tellement puissantes, qu\\\'elles n?cessitent des essences magiques extr?mement rares. Plus la personne qui doit modifier sa constitution  est puissante, plus il me faut d\\\'ingr?dients. \\nLa pr?paration de ces potions est en outre assez longue et d?licate, je n\\\'en pr?pare qu\\\'aux aventuriers qui prennent le temps d\\\'aider mes confr?res en difficult? sur cette ?le.');
INSERT INTO `npc_questions` VALUES (4105, '', '', '', '', 'La premi?re potion permet d\\\'oublier totalement tes caract?ristiques, elles seront identiques ? celles que tu avais lorsque tu es arriv? sur le monde des douze. Tout ce que tu auras appris gr?ce ? des parchemins sera perdu. Tu pourras gr?ce ? cette potion, changer compl?tement ta fa?on de combattre et d\\\'utiliser tes sorts, en changeant tes ?l?ments de pr?dilection.');
INSERT INTO `npc_questions` VALUES (4106, '', '', '', '', 'La deuxi?me potion est beaucoup moins puissante, elle permet d\\\'oublier partiellement ses caract?ristiques, si tu ne veux pas perdre ce que tu as appris d?j? avec des parchemins de caract?ristiques.');
INSERT INTO `npc_questions` VALUES (4107, '', '', '', '', 'Quoi, tu veux encore de l\\\'extrait de Dzibi ? Tiens, voici une de mes derni?res fioles, fais en bon usage.');
INSERT INTO `npc_questions` VALUES (4108, '', '', '', '', 'kwwizzzit !');
INSERT INTO `npc_questions` VALUES (4109, '', '', '', '', 'Bonjour l\\\'aventurier, je suis Mali Key, sp?cialiste incontest?e du bricolage de clefs ! \\nTu ne savais pas que les bricoleurs ?taient capables de cr?er des clefs eux-m?mes ? \\nTu viens d\\\'Astrub pour ?tre aussi ignorant ?');
INSERT INTO `npc_questions` VALUES (4110, '', '', '', '', 'Quelle clef veux-tu fabriquer ?');
INSERT INTO `npc_questions` VALUES (4111, '', '', '', '', 'Pour te fabriquer cette clef j\\\'ai besoin de :  \\t1 Fragment de Coquille d\\\'Aerohouctor le Guerrier, 1 Fragment de Coquille de Terrakoubiak le Guerrier, 1 Fragment de Coquille d\\\'Ignelicrobur le Guerrier, 1 Fragment de Coquille d\\\'Aquabralak le Guerrier et 1 Oeuf de Dragoeuf Blanc.');
INSERT INTO `npc_questions` VALUES (4112, '', '', '', '', 'Pour te fabriquer cette clef j\\\'ai besoin de : 1 Pierre d\\\'Aerotrugobur le Malveillant, 1 Pierre d\\\'Aqualikros l\\\'Impitoyable, 1 Pierre d\\\'Ignerkocropos l\\\'Affam?, et 1 Pierre de Terraburkal le Perfide.');
INSERT INTO `npc_questions` VALUES (4113, '', '', '', '', 'Pour te fabriquer cette clef j\\\'ai besoin de : 5 Souliers de Porkass, 1 Deuxi?me partie de la clef du labyrinthe du Dragon Cochon, 1 Premi?re partie de la clef du labyrinthe du Dragon Cochon, 5 Tridents Cass?s, et 5 Oreilles de Porkass.');
INSERT INTO `npc_questions` VALUES (4114, '', '', '', '', 'Je suis le Gardien du Pont de la Mort. \\nR?ponds correctement ? mes questions pour franchir ce pont, ou tu mourras.');
INSERT INTO `npc_questions` VALUES (4115, '', '', '', '', 'Quelle est ta couleur pr?f?r?e ?');
INSERT INTO `npc_questions` VALUES (4116, '', '', '', '', 'Quel est le sexe de la personne qui n\\\'est ni ton fr?re ni ta soeur, mais qui est l\\\'enfant de tes parents ?');
INSERT INTO `npc_questions` VALUES (4117, '', '', '', '', 'Sais-tu croiser les bras ?');
INSERT INTO `npc_questions` VALUES (4118, '', '', '', '', 'Si tu pouvais ?quiper en plus de ta ceinture, une ceinture du Bouftou parfaite, combien de Coraux Moritos pourrais-tu porter en plus de tous tes ?quipements, si tu voulais en porter le plus grand nombre possible sans avoir ? te d?lester de tes objets ? Tu sembles nul en calcul mental, je vais donc t\\\'aider en te faisant 5 propositions. Choisis celle qui s\\\'approche le plus de la v?rit?. Attention, il y a un pi?ge, n\\\'oublie pas de diviser l\\\'?ge du Capitaine par le nombre d\\\'or, puis par la constante de l\\\'air, et d\\\'ajouter 12.');
INSERT INTO `npc_questions` VALUES (4119, '', '', '', '', 'Et maintenant la derni?re question, la plus importante : combien de noix de kokoko traumatis?es peut porter un Corbac qui dispose de 5 fois moins de force que toi, mais qui poss?de une ceinture du Rasboul et un sac en poils de Bitouf am?lior? par un costumage ?');
INSERT INTO `npc_questions` VALUES (4120, '', '', '', '', 'Quelle est la couleur de la Dragodinde blanche d\\\'Henry Kard ?');
INSERT INTO `npc_questions` VALUES (4121, '', '', '', '', 'Euh... Je ne sais pas... Je... Je ne connais pas la r?ponse ? cette question ! Je suis pi?g?, j\\\'ai perdu ? mon propre jeu, je suis ridiculis?, je suis encore plus stupide que toi, je ne pensais pas que cela puisse ?tre possible. \\nS\\\'il te pla?t, ne dis ? personne que tu as vaincu le Gardien du Pont de la Mort lors d\\\'un de ses interrogatoires, par piti? ! \\nPour la peine, je te laisserai d?sormais toujours passer ce pont.');
INSERT INTO `npc_questions` VALUES (4122, '3616', '', '', '0', 'Tu m\\\'as vaincu ? mon propre jeu, je n\\\'en reviens toujours pas... \\nJ\\\'ai cherch? toute la nuit la r?ponse ? ta question, et je n\\\'ai toujours pas trouv? la r?ponse... \\nEn attendant, vas-y traverse ce pont. \\n');
INSERT INTO `npc_questions` VALUES (4123, '3618', '', 'QE!231', '4158', 'Hey doryphore c\\\'est moi, le Capitaine Kradoc en personne ! Je peux t\\\'emmener jusqu\\\'au bout du monde, surtout si ?a t\\\'?loigne de ma vue ! \\nJe peux t\\\'emmener sur une magnifique ?le d?serte, sans Kanniboules ni troud\\\'boules si tu es int?ress');
INSERT INTO `npc_questions` VALUES (4124, '3619', '', '', '0', 'Mais tu crois qu\\\'il suffit d\\\'accepter ma proposition pour aller sur cette ?le ? Troubadour des fonds marins ! Stupide d?jection de Kralamour centenaire ! Si tu pars sur cette ?le, tu pars pour une aventure p?rilleuse, il va falloir te battre contre les ?l?ments, les forces de l\\\'oc?an, et peut-?tre contre ta maman ! Haha j\\\'ai toujours ?t? tr?s fort pour faire des rimes. \\nTu veux toujours aller sur cette ?le, ou tu pr?f?res continuer ? chasser les Bouftons ?');
INSERT INTO `npc_questions` VALUES (4125, '3620', '', '', '0', 'Tu sembles d?termin?, ou plut?t born?. J\\\'aime les d?voreurs de Bitoufs dans ton genre, ceux qui mordent la vie et leurs ennemis ? pleines dents. Nous allons partir pour un long p?riple, il va falloir nous prot?ger. J\\\'ai r?cemment fait l\\\'acquisition d\\\'un superbe canon pour mon navire, mais il me manque des munitions. Je les ai toutes utilis?es pour m\\\'entra?ner sur les Raul Mops de la Baie de Cania, tu devrais aller y faire un tour peut-?tre. Je vais ?galement avoir besoin de pointes de fl?ches pour nous prot?ger d\\\'?ventuels Kanniboules. \\nEt j\\\'aimerais que tu me rapportes mon d?jeuner pr?f?r?, une oreille de Kanigrou frite dans l\\\'huile de s?same ! Si tu me rapportes toutes ces fournitures, alors nous pourrons partir !');
INSERT INTO `npc_questions` VALUES (4126, '', '', '', '', 'Enfin, je commen?ais ? m\\\'impatienter ! Je vais charger les munitions dans mon bateau et prendre mon petit d?jeuner, tu pourras revenir me voir quand tu te sentiras pr?t pour voyager vers cette ?le.');
INSERT INTO `npc_questions` VALUES (4127, '3622', '', '', '', 'Voil? tout est pr?t pour ton d?part. \\nNous partons quand tu veux. Mais attention, le voyage est p?rilleux, je te conseille de partir avec des amis, des personnes un peu plus fortes que toi, car je ne suis pas certain que tu r?sistes au voyage, une vulgaire mouette perverse pourrait venir ? bout de toi en quelques coups de bec bien plac?s.');
INSERT INTO `npc_questions` VALUES (4128, '', '', '', '', 'Nous sommes attaqu?s par des Pirates ! \\nJe n\\\'ai m?me pas eu le temps de leur lancer un gros boulet ! Diantre, rends-toi utile pour une fois dans ta vie, fonce dans le tas, et tue-moi ces vauriens, ces Scorbutes aquatiques mangeurs de Raul Mobs !');
INSERT INTO `npc_questions` VALUES (4129, '3623', '', '', '0', 'Bravo, tu as r?ussi ? repousser ces pirates. Je t\\\'avais pr?venu, le voyage ne serait pas de tout repos. Heureusement, nous sommes bient?t arriv?s ? destination si j\\\'en crois ma carte.');
INSERT INTO `npc_questions` VALUES (4130, '3624', '', 'QT!232', '4134', 'Je crois que nous nous sommes ?chou?s sur la mauvaise ?le... D\\\'apr?s ma carte, nous sommes sur une ?le appel?e \\\"L\\\'?le des Naufrag?s\\\". Avoue que c\\\'est assez dr?le non ! Je ne comprends pas comment nous en sommes arriv?s l?, j\\\'ai encore d? avoir des probl?mes de digestion, et je me suis tromp? de direction. Je me doutais bien que les oreilles de Kanigrou que tu m\\\'as apport?es ?tait avari?es... \\nBon il va falloir que tu te d?brouilles pour nous sortir d\\\'ici, moi je m\\\'occuperai de donner les ordres et de superviser la r?paration du navire.');
INSERT INTO `npc_questions` VALUES (4131, '3625', '', '', '0', 'Je connais cette ?le, elle est infest?e de pirates et de Kokokos. Les Kokokos ne me font pas peur, j\\\'ai ?t? ?lev? parmi une tribu primitive de Kokokos lorsque j\\\'?tais jeune, et crois-moi, ces bestioles sont vraiment encore plus d?biles qu\\\'un Iop ! En revanche, m?fie-toi des pirates, ils sont fourbes, vils, pervers, et sales, leur haleine est encore plus putride qu\\\'un cloaque de Rasboul empaill?. Bref, ils nous faut faire vite pour r?parer mon bateau. \\nJe vais avoir besoin de bois, d?brouille-toi pour trouver ?a sur l\\\'?le. Il faut ?galement que tu me retrouve le Coffre Maudit du Flib, c\\\'est un coffre vivant que j\\\'ai abandonn? sur cette ?le, il contient les outils n?cessaires pour r?parer la voile du bateau.');
INSERT INTO `npc_questions` VALUES (4132, '3626;3627', '', '', '0', 'Fais attention, la derni?re fois que l\\\'ai amen? sur cette ?le il y a plus de 35 ans, je lui ai dit de m\\\'attendre, car je reviendrai le chercher quelques jours plus tard. Je ne suis bien entendu pas revenu depuis, j\\\'?tais bien content de m\\\'en ?tre d?barrass?. Il doit vraiment m\\\'en vouloir et ?tre aigri, passer 35 ans ? attendre sur une ?le d?serte, avec quelques Kokokos et des pirates, c\\\'est encore pire que de passer sa vie avec toi ! \\nEt pendant que j\\\'y suis, j\\\'ai vraiment soif, sans boisson je ne pourrai jamais r?parer les voiles et la coque du bateau, essaye de me trouver une Noix de Kokoko et quelque chose pour boire son jus. Et attention, cette fois-ci ne me ram?ne pas de la nourriture avari?e... \\nBon qu\\\'est-ce que tu fais encore ici, d?p?che-toi j\\\'ai soif !');
INSERT INTO `npc_questions` VALUES (4133, '', '', '', '', 'Incroyable, tu as trouv? tout ce qu\\\'il me fallait pour r?parer notre navire. Je suis surpris que le Coffre Maudit du Flib t\\\'ai donn? son coffret, finalement il ne devait pas trop m\\\'en vouloir. \\nJe peux enfin me mettre au travail tout en me d?lectant de ce d?licieux jus de Kokoko, encore quelques efforts et nous pourrons enfin quitter cette ?le.');
INSERT INTO `npc_questions` VALUES (4134, '3628', '', '', '0', 'Voil?, le bateau est encore amoch?, mais nous pouvons repartir. D\\\'apr?s la carte, nous ne sommes plus tr?s loin. Si tu veux, tu peux m\\\'attendre sur cette ?le quelques jours, et je reviendrai te chercher ensuite...');
INSERT INTO `npc_questions` VALUES (4135, '3630', '', '', '0', 'Le voyage ?tait finalement assez court et plut?t calme, j\\\'ai su contourner tous les dangers, je n\\\'ai pas perdu la main avec l\\\'?ge !');
INSERT INTO `npc_questions` VALUES (4136, '', '', '', '', 'Je suis le Chevalier Noir et Rose. \\nPersonne ne peut traverser ce pont sans m\\\'affronter.');
INSERT INTO `npc_questions` VALUES (4137, '363', '', '', '0', 'Tu es digne de franchir ce pont.');
INSERT INTO `npc_questions` VALUES (4138, '', '', '', '', 'Bonjour, je suis le Professeur Fournesol. \\nDepuis que j\\\'ai perdu mes sept boules, je soigne les cr?atures bless?es de cette ?le. Je m\\\'occupe ?galement de les achever parfois. \\nJ\\\'ai toujours voulu secourir les ?tres vivants ou abr?ger leurs souffrances. C\\\'est devenu pour moi une v?ritable passion. \\nSi tu as un peu de temps ? me consacrer, j\\\'aurais peut-?tre besoin de ton aide.');
INSERT INTO `npc_questions` VALUES (4139, '', '', '', '', 'Je me doutais bien que tu n\\\'avais rien ? faire en ce moment ! \\nBon, le travail que je vais te proposer est assez simple, j\\\'ai besoin de soigner les Corailleurs qui se prom?nent sur la plage, ils sont parasit?s par d\\\'?tranges mollusques qui leur d?vorent lentement le cerveau. La seule chose qui puisse les gu?rir, c\\\'est une potion Bulbique, assez puissante pour soigner les meurtrissures c?r?brales les plus avanc?es. A l\\\'occasion tu devrais essayer cette potion, ?a te ferait s?rement le plus grand bien ! Bref, essaye de trouver un alchimiste comp?tent et ram?ne-moi cette potion rapidement.');
INSERT INTO `npc_questions` VALUES (4140, '', '', '', '', 'Alors as-tu r?ussi ? te procurer une potion Bulbique ?');
INSERT INTO `npc_questions` VALUES (4141, '', '', '', '', 'Gr?ce ? toi, les Corailleurs pourront continuer d\\\'utiliser ce qu\\\'il leur reste de cerveau ? des fins utiles, comme briser des coquillages ou faire des ricochets sur la plage par exemple. Si Otoma? voyait ce que tu as fait pour eux, il serait tr?s heureux.');
INSERT INTO `npc_questions` VALUES (4142, '', '', '', '', 'C\\\'est parfait, je vais essayer d\\\'aller soigner les Corailleurs rapidement. Je vais essayer de me retenir pour ne pas consommer moi-m?me cette d?licieuse potion.');
INSERT INTO `npc_questions` VALUES (4143, '', '', '', '', 'Bonjour, je suis Polka Merer, une des plus c?l?bres assistantes d\\\'Otoma?. \\nJe veille au bon fonctionnement de ces enclos, nous les utilisons parfois pour observer le comportement des cr?atures de l\\\'?le lorsqu\\\'elles sont en captivit?. \\nMalheureusement, je n\\\'ai plus aucune machine d\\\'?levage disponible, je ne peux donc plus continuer mes recherches.');
INSERT INTO `npc_questions` VALUES (4144, '', '', '', '', 'Je n\\\'ai jamais construit moi-m?me mes machines d\\\'?levage, j\\\'utilise g?n?ralement celles qui sont fabriqu?es par les bricoleurs pour ?lever les Dragodindes, et je les modifie l?g?rement. Ce n\\\'est pas ce qu\\\'il y a de mieux, mais ?a fonctionne assez bien. J\\\'aimerais que tu me ram?nes un baffeur, un abreuvoir, un foudroyeur, une mangeoire et une planche en fr?ne. Je les d?monterai, les modifierai, et les adapterai ? mes propres cr?atures.');
INSERT INTO `npc_questions` VALUES (4145, '', '', '', '', 'As-tu ramen? ce qu\\\'il me faut pour que je puisse enfin ?lever correctement mes cr?atures ?');
INSERT INTO `npc_questions` VALUES (4146, '', '', '', '', 'Gr?ce ? vous, je vais pouvoir ?lever toutes les cr?atures dont j\\\'ai besoin pendant plusieurs jours.');
INSERT INTO `npc_questions` VALUES (4147, '', '', '', '', 'Merci beaucoup, j\\\'ai d?sormais tout ce qu\\\'il me faut.');
INSERT INTO `npc_questions` VALUES (4148, '', '', '', '', 'Je ne sais pas qui tu es, mais sache que je suis une des meilleures boulang?res que le monde des douze ait connu. \\nEt ?a semble ne te faire ni chaud, ni froid ! C\\\'est navrant. \\n \\nTu sembles cependant un peu veule et sournois, tu pourrais peut-?tre m\\\'?tre utile.');
INSERT INTO `npc_questions` VALUES (4149, '', '', '', '', 'Bon c\\\'est assez simple, je dois fournir des farines ? base de c?r?ales aux cr?atures que nous ?levons sur cette ?le. Nous leur donnons d\\\'excellentes farines pour les capturer et les ?tudier calmement dans nos laboratoires ou nos enclos. Mais ? force, elles deviennent de plus en plus exigeantes, et les farines que nous leur donnions habituellement ne leur conviennent plus !');
INSERT INTO `npc_questions` VALUES (4150, '', '', '', '', 'Mes coll?gues voulaient donc que je leur fournisse une des meilleures farines qui soit, ? savoir la fameuse farine de Xavier le Boulanger ! \\nMais elle est beaucoup trop complexe ? fabriquer, j\\\'ai donc eu l\\\'id?e de m?langer un tr?s grand nombre de farines diff?rentes, d\\\'y ajouter un peu de celle de Xavier, et avec un peu de chance tout le monde n\\\'y verra que du feu ! J\\\'ai eu l\\\'id?e, mais il me manque encore les farines, te sens-tu capable de m\\\'aider en me rapportant toutes les farines dont j\\\'ai besoin ?');
INSERT INTO `npc_questions` VALUES (4151, '', '', '', '', 'Alors, as-tu r?ussi ? trouver toutes les farines dont j\\\'ai besoin ?');
INSERT INTO `npc_questions` VALUES (4152, '', '', '', '', 'C\\\'est parfait, je vais pouvoir m?langer toutes ces farines, et avec un peu de chance, personne ne s\\\'en rendra compte.');
INSERT INTO `npc_questions` VALUES (4153, '', '', '', '', 'Gr?ce ? mon id?e de g?nie, j\\\'ai pu ?conomiser ?norm?ment de temps et de farine de qualit?. J\\\'esp?re que tu comprends d?sormais pourquoi je suis une des meilleures boulang?res du monde des 12 ?');
INSERT INTO `npc_questions` VALUES (4154, '', '', '', '', 'Mon fils, Jean Nauh, mon petit wabbit ador?, il est coinc? dans ce laboratoire abandonn?, et je ne sais pas comment l\\\'aider, il ne veut plus revenir et je n\\\'ose pas aller le chercher moi-m?me, j\\\'ai trop peur des cr?atures que je pourrais y trouver. \\nPouvez-vous y aller ? ma place ?');
INSERT INTO `npc_questions` VALUES (4155, '', '', '', '', 'Alors avez-vous trouv? mon petit wabbit ? Comment va-t-il ?');
INSERT INTO `npc_questions` VALUES (4156, '', '', '', '', 'Gr?ce ? vous je sais pourquoi mon fils voulait s\\\'?carter de moi, j\\\'ai bien compris la le?on, et plus jamais je ne l\\\'appellerai, mon petit wabbit, je l\\\'appellerai, mon petit boufton ? partir de maintenant, je suis certain qu\\\'il appr?ciera ! ');
INSERT INTO `npc_questions` VALUES (4157, '', '', '', '', 'Je me suis enferm? dans cette cachette car je ne supporte plus mon p?re. Rendez-vous compte, il m\\\'appelle \\\"Mon wabbit\\\". Ce n\\\'est pas facile ? accepter lorsqu\\\'on s\\\'appelle d?j? Jean Nauh ! Je n\\\'ai jamais support? mon nom, mais si en plus il me ridiculise devant toutes mes copines avec cet horrible sobriquet, je ne pourrai jamais concr?tiser la moindre relation amoureuse ! \\nSi mon p?re pouvait comprendre ?a, je pense que j\\\'accepterais de le revoir. \\nPouvez-vous lui expliquer ce qui me tracasse ?');
INSERT INTO `npc_questions` VALUES (4158, '3645', '', '', '', 'Alors, as-tu trouv? les fournitures dont j\\\'ai besoin ?');
INSERT INTO `npc_questions` VALUES (4159, '3646;378', '', '', '0', 'Alors comme ?a tu veux repartir sur cette ?le ?');
INSERT INTO `npc_questions` VALUES (4160, '', '', '', '', 'Ma femme... Elle est partie, je ne sais o?. Et maintenant que vais-je faire ? De tout ce temps que sera ma vie, de tous ces gens qui m\\\'indiff?rent, Maintenant qu\\\'elle est partie ! \\nJ\\\'ai beau ?tre l\\\'un des plus ?minents scientifiques et disciples d\\\'Otoma?, je ne peux rien faire sans ma femme ! \\nJe peux vous amener l? o? je l\\\'ai aper?ue la derni?re fois, vous pourriez la chercher, et si vous la retrouvez, vous pourrez essayer de la convaincre de revenir.');
INSERT INTO `npc_questions` VALUES (4161, '', '', '', '', 'La derni?re fois que je l\\\'ai aper?ue, elle s\\\'enfuyait vers ce village. J\\\'ai voulu la rattraper, mais elle ?tait vraiment trop d?termin?e. \\nJe pense que vous pourriez la retrouver pour moi, et m\\\'expliquer pourquoi elle est partie. \\nMais attention, vous devrez s?rement affronter les cr?atures de ce village pour la retrouver.');
INSERT INTO `npc_questions` VALUES (4162, '364', '', '', '0', 'Je parie que c\\\'est mon mari qui vous envoie me chercher ! \\nC\\\'est un vaurien, un gentil vaurien, mais un vaurien ! \\nIl accorde plus d\\\'importances ? ses recherches sur les monstres qu\\\'? notre couple, il ne sait plus me s?duire, ni partager ce qu\\\'un couple doit partager. \\nEt pourtant je sais qu\\\'il m\\\'aime, j\\\'entends d\\\'ici son coeur battre la chamade, mais il ne sait pas communiquer sa passion avec des gestes ou m?me simplement des mots ou des regards.');
INSERT INTO `npc_questions` VALUES (4163, '364', '', '', '0', 'Il oublie parfois les petites attentions qui font vivre un couple, et le jeu de la s?duction qui le fait revivre. \\nNous habitions autrefois ? Bonta tous les deux, nous ?tions tr?s amoureux. \\nMais au fil du temps, notre couple s\\\'est endormi, il a perdu la flamme qui l\\\'animait lors des premiers instants. \\nAussi a-t-il eu l\\\'id?e de m\\\'emmener sur cette ?le diff?rente, pour que nous tentions un nouveau d?part, un nouvelle vie, loin de tout ce conformisme urbain qui d?nature nos relations.');
INSERT INTO `npc_questions` VALUES (4164, '365', '', '', '0', 'Nous devions y trouver une nouvelle vie, un nouveau monde, et y red?couvrir comment aimer. \\nL\\\'euphorie fut intense, mais br?ve. Aujourd\\\'hui, j\\\'en suis r?duite ? fuguer pour faire r?agir celui que j\\\'aime, m?me si cette fa?on de proc?der le fait souffrir. J\\\'aimerais que vous lui expliquiez ceci. Il est parfois na?f comme un Kanigrou, et born? comme un Bitouf, mais ses d?fauts font aussi partie de ses charmes. Parlez-lui, avec un peu de chance il comprendra, et nous pourrons peut-?tre prendre un nouveau d?part. \\n');
INSERT INTO `npc_questions` VALUES (4165, '', '', '', '', 'Alors, vous l\\\'avez retrouv?e, que vous a-t-elle dit ?');
INSERT INTO `npc_questions` VALUES (4166, '', '', '', '', 'Je me sens perdu suite ? vos explications. C\\\'est comme si je l\\\'avais toujours su, toujours compris. J\\\'ai l\\\'impression de m\\\'?tre enferm? dans un mode de vie qui n\\\'?tait pas le mien, pas celui que j\\\'esp?rai pour notre couple. Et voil? o? j\\\'en suis d?sormais. J\\\'ai tellement de choses ? apprendre d\\\'elle et ? lui faire d?couvrir. Vous m\\\'avez ouvert les yeux, je dois moi-m?me apprendre ? la reconqu?rir !');
INSERT INTO `npc_questions` VALUES (4167, '379', '', '', '0', 'Gr?ce ? vous, je me sens revivre, mon envie de s?duire Jeanne est d?sormais sans limite, nos petits jeux de s?duction n\\\'ont jamais ?t? aussi savoureux !');
INSERT INTO `npc_questions` VALUES (4168, '', '', '', '', 'Je te pr?viens, ne te moque pas de mon nom, je d?teste ?a ! \\nJ\\\'imagine que si tu es ici c\\\'est pour utiliser mon Sca?roplane. \\nAvant cela il faudra que tu m\\\'aides.');
INSERT INTO `npc_questions` VALUES (4169, '', '', '', '', 'Je suis bien d?cid?e ? avoir les Scarafeuilles dress?s les plus rapides, mais pour cela il faut que je puisse les monter sans trop les ralentir. \\nJ\\\'ai donc besoin d\\\'un ?quipement sp?cifique, et pas de ce vulgaire casque et de cette mis?rable paire d\\\'ailes en bois qui me permettent de ne pas m\\\'?craser si je tombe de mon Scarafeuille, mais qui alourdissent inutilement mon moyen de transport. \\nJ\\\'ai besoin d\\\'un casque et d\\\'une cape de pilote am?lior?s, penses-tu pouvoir m\\\'aider ? trouver cela ? Il faudra s?rement que tu trouves un tailleur exp?riment');
INSERT INTO `npc_questions` VALUES (4170, '', '', '', '', 'As-tu trouv? les objets qu\\\'il me fallait ?');
INSERT INTO `npc_questions` VALUES (4171, '', '', '', '', 'C\\\'est parfait, gr?ce ? ces objets am?lior?s je vais pouvoir voler beaucoup plus rapidement ? dos de Scarafeuilles, sans les fatiguer inutilement avec le poids de mon ?quipement d?suet.');
INSERT INTO `npc_questions` VALUES (4172, '3656;3657;365', '', '', '0', 'Vers quel Sca?roport veux-tu que je t\\\'emm?ne ?');
INSERT INTO `npc_questions` VALUES (4173, '', '', '', '', 'Tu n\\\'as pas encore la permission d\\\'y atterrir, tu devrais aller voir le pilote qui contr?le ce Sca?roport.');
INSERT INTO `npc_questions` VALUES (4174, '', '', '', '', 'Bonjour, je m\\\'appelle Flip Flap, comme le bruit des ailes d\\\'un Scarafeuille en chute libre, avouez que c\\\'est amusant pour un pilote de Sca?roplane comme moi ! Les Sca?roplanes sont des Scarafeuilles domestiqu?es, et entra?n?s pour voler sur de longues distances. Nous leur ajoutons parfois des ailes en bois et des trains d\\\'atterrissage en fonction de nos besoins.');
INSERT INTO `npc_questions` VALUES (4175, '', '', '', '', 'Cela va faire des ann?es que je r?ve de piloter autre chose que ces Scarafeuilles, j\\\'aimerais tellement essayer les Dragodindes, elles sont rapides, dociles et ont vraiment l\\\'air intelligentes par rapport ? mes Scarafeuilles. Si vous me ramenez un certificat de Dragodinde Rousse ainsi qu\\\'un certificat de Dragodinde Amande, je vous laisserai utiliser mon Sca?roplane aussi souvent que vous le voulez !');
INSERT INTO `npc_questions` VALUES (4176, '', '', '', '', 'O? sont les deux certificats de dragodinde que je t\\\'ai demand?s ?');
INSERT INTO `npc_questions` VALUES (4177, '', '', '', '', 'Enfin, je vais pouvoir utiliser ma monture rousse les jours pairs et ma monture amande les jours impairs. Depuis le temps que j\\\'en r?vais !');
INSERT INTO `npc_questions` VALUES (4178, '', '', '', '', 'C\\\'est moi Crocodaille Dandi, celui qui coud des sous-v?tements coquins en ?cailles de Crocodaille, celui qui hypnotise les sangliers des plaines avec les doigts, celui qui a toujours voulu transformer cette ?le en un parc d\\\'attraction ! \\nJe suis persuad? que les aventuriers en qu?te de nouvelles exp?riences aimeraient visiter cette ?le au milieu de toutes ces cr?atures dangereuses, les aventuriers modernes aiment avoir peur, mais pas prendre des risques. \\nMalheureusement, depuis que les cr?atures se sont totalement ?chapp?es de leurs cages et ?voluent librement, s\\\'en est fini de mon id?e de parc d\\\'attraction, je dois proposer d\\\'autres divertissements aujourd\\\'hui.');
INSERT INTO `npc_questions` VALUES (4179, '', '', '', '', 'D?sormais, je propose des parties de chasse. Les aventuriers des temps modernes ne savent plus se fixer d\\\'objectifs. Je donne un sens ? leur vie avec mes chasses. \\nAccessoirement, ?a me permet de r?guler un peu les populations de cr?atures sur cette ?le. Otoma? est contre ce genre de raisonnement, il pr?f?re laisser la nature reprendre ses droits, mais nous nous sommes mis d\\\'accord, et il a accept? que j\\\'intervienne sur l\\\'?cosyst?me de cette ?le ? condition que je lui fasse part de tous les r?sultats. \\nVeux-tu tenter ta chance pour une petite chasse ?');
INSERT INTO `npc_questions` VALUES (4180, '', '', '', '', 'Tu n\\\'as pas encore fini de chasser les cr?atures que je t\\\'ai demand?es d\\\'an?antir, d?p?che-toi si tu ne veux pas que je m\\\'enracine d?finitivement ici.');
INSERT INTO `npc_questions` VALUES (4181, '', '', '', '', 'Et bien, tu es un des aventuriers les plus valeureux que je connaisse, venir ? bout de cr?atures si f?roces, en si peu de temps, ?a faisait longtemps que je n\\\'avais pas vu cela de mes propres yeux. \\nJ\\\'en parlerai ? Otoma? la prochaine fois que je le croiserai, il sera s?rement satisfait de savoir que tu as aid? un de ses anciens amis.');
INSERT INTO `npc_questions` VALUES (4182, '3946', '', '', '0', 'Gniiiii. Gniiii. Vr?t vr?t gniii !');
INSERT INTO `npc_questions` VALUES (4183, '', '', '', '', 'Bonjour, je suis le c?l?bre Kito. Dans ma famille, nous sommes pilotes de Sca?roplane depuis douze g?n?rations. \\nCa ne nous emp?che pas pour autant d\\\'avoir parfois quelques accidents de parcours... \\nMon cousin par exemple, est devenu nettoyeur de Zaapis, et mon neveu lui est ?leveur de Dragodindes. N\\\'importe quoi...');
INSERT INTO `npc_questions` VALUES (4184, '', '', '', '', 'Connais-tu les Pirates de l\\\'arche d\\\'Otoma? ? Ces cr?atures abjectes me lancent des boulets ? chaque fois que je survole l\\\'arche. J\\\'ai d?j? perdu plusieurs Sca?roplanes ? cause d\\\'eux. Je veux bien te laisser utiliser mes Sca?roplanes si tu acceptes d\\\'aller en d?cimer quelques un, pour faire un exemple et calmer leurs ardeurs.');
INSERT INTO `npc_questions` VALUES (4185, '', '', '', '', 'Alors, as-tu r?duit en poussi?re les Pirates ?');
INSERT INTO `npc_questions` VALUES (4186, '', '', '', '', 'J\\\'ai entendu dire que tu avais r?ussi ? effrayer ces Pirates, je pense qu\\\'ils ne sont pas pr?ts de continuer ? m\\\'attaquer avec leurs boulets ! \\nTous les pilotes de Sca?roplane t\\\'en seront reconnaissants !');
INSERT INTO `npc_questions` VALUES (4187, '', '', '', '', 'C\\\'est cet odieux Chevalier Noir et Rose qui m\\\'a surnomm?e comme cela, ce n\\\'est pas mon vrai nom, je ne m\\\'appelle pas Peggy la Porkass ! \\nJe veux me venger, ma r?putation de pilote de Sca?roplane est totalement ruin?e ? cause de ce goujat, il faut que tu fasses quelque chose pour moi ! \\nPourrais-tu aller l\\\'affronter et le ridiculiser pour moi ?');
INSERT INTO `npc_questions` VALUES (4188, '', '', '', '', 'As-tu affront? pour moi le Chevalier Noir et Rose ?');
INSERT INTO `npc_questions` VALUES (4189, '', '', '', '', 'Incroyable, tu as vaincu le Chevalier Noir et Rose. Depuis le temps que j\\\'en r?vais... Malheureusement, je n\\\'ai jamais ?t? assez forte pour y parvenir. \\nPour te remercier, je te laisse aller o? tu veux avec mon Sca?roplane.');
INSERT INTO `npc_questions` VALUES (4190, '6634', '', '', '0', 'J\\\'ai l\\\'impression que tu cherches ? rentrer dans cette grosse grotte malodorante... \\nJ\\\'esp?re que tu sais ce que tu fais ! \\nEt sache que je ne te laisserai rentrer que lorsque tu pourras me donner la clef de cette grotte. Je l\\\'ai perdue sur la plage de corail, et je pense que les cr?atures qui s\\\'y trouvent me l\\\'ont d?rob?e.');
INSERT INTO `npc_questions` VALUES (4191, '3669', '', '', '', 'Le pauvre Corailleur Magistral n\\\'aura pas fait long feu. Mais je ne suis pas impressionn?e pour autant ! \\nPrends ces deux cadeaux en ?change de ta clef, ils te seront tr?s utiles.');
INSERT INTO `npc_questions` VALUES (4192, '3673', '', '', '0', 'Bonjour aventurier, je te souhaite la bienvenue dans ce qu\\\'il reste de mon arche ! \\nEt oui, j\\\'?tais autrefois son capitaine, j\\\'amenais r?guli?rement des marchandises sur cette ?le gard?e secr?te, pour le compte d\\\'Otoma? et de ses acolytes. \\nCette arche a principalement servi ? transporter les diff?rentes cr?atures d\\\'Amakna vers l\\\'?le d\\\'Otoma');
INSERT INTO `npc_questions` VALUES (4193, '367', '', '', '0', 'Otoma? a voulu apporter sur cette ?le, un couple de chaque cr?ature qu\\\'il rencontrait. Il voulait ensuite les reproduire, les croiser, et ?tudier l\\\'?volution des hybrides qu\\\'il cr?ait. Mais pour r?aliser de telles exp?riences, il avait besoin de quantit?s importantes de mat?riel d\\\'alchimie, et de nourriture pour ses cr?atures. \\nC\\\'est pour cela que je faisais r?guli?rement le trajet vers cette ?le. \\nLa cartographie des mers ?tant tr?s approximative, ils nous arrivait parfois de faire des d?tours improvis?s sur l\\\'?le de Moon ou sur l\\\'?le des Naufrag?s et d\\\'y faire escale.');
INSERT INTO `npc_questions` VALUES (4194, '367', '', '', '0', 'Un jour lorsque nous avions fait escale sur l\\\'?le de Moon, de vils pirates se sont cach?s dans la cale de notre arche. Ils nous ont attaqu? ? notre arriv?e sur cette ?le, ils sont sortis des cales en pleine nuit, et ont d?cim? la quasi totalit? de mon ?quipage. Ils ont pris le contr?le de mon bateau, mais leur capitaine confondait sa gauche et sa droite... Ils se sont donc lamentablement ?chou?s dans cette tourbi?re, et ont d?cid? de terminer leurs jours ici.');
INSERT INTO `npc_questions` VALUES (4195, '367', '', '', '0', 'Un bon capitaine ne quitte jamais son navire, et j\\\'esp?re bien un jour, pouvoir le remettre ? flots ! J\\\'essaye tant bien que mal de lutter contre ces pirates, mais leur sup?riorit? num?rique m\\\'emp?che de prendre le dessus. Il faudrait que quelqu\\\'un puisse vaincre leur capitaine, connu sous le nom de Gourlo le Terrible. Mais je ne laisse pas n\\\'importe qui l\\\'affronter, il faut d\\\'abord s\\\'en montrer digne, et je demande ? tous les aventuriers qui veulent se mesurer ? Gourlo, de me montrer la clef n?cessaire pour rentrer dans cette arche.');
INSERT INTO `npc_questions` VALUES (4196, '3679', '', '', '', 'Tu as r?ussi ? vaincre Gourlo le Terrible, je ne pense pas que ?a suffise ? lui faire abandonner mon navire, mais petit ? petit je r?ussirai ? reprendre ce qui m\\\'appartient.');
INSERT INTO `npc_questions` VALUES (4197, '367', '', '', '0', 'Bonjour, je suis Mul?ze, la gardienne de ce laboratoire. J\\\'y travaillais comme alchimiste autrefois, jusqu\\\'? ce qu\\\'Otoma? d?cide de l\\\'abandonner ? cause d\\\'une exp?rience dont il a perdu le contr?le. Nous y ?levions une des cr?atures les plus surprenantes qui soient, le Tynril. \\nCette cr?ature est capable de se d?doubler, suivant ses humeurs et ses envies. Elle n\\\'est pas tr?s dangereuse, mais elle reste sauvage et lunatique, il nous est tr?s difficile de pr?dire son comportement.');
INSERT INTO `npc_questions` VALUES (4198, '367', '', '', '0', 'C\\\'est cette cr?ature qui donne naissance ? la majorit? des plantes vivantes de cette for?t. Chaque p?tale, chaque ?tamine, chaque grain de pollen qu\\\'elle perd, donne naissance ? une nouvelle cr?ature, qui vient ensuite prendre place dans la cha?ne alimentaire de l\\\'?le. Aujourd\\\'hui, cette cr?ature est devenue incontr?lable. Autrefois, nous parvenions ? rentrer dans ce laboratoire et ? v?rifier nous m?me ? quelles cr?atures, le Tynril donnait naissance.');
INSERT INTO `npc_questions` VALUES (4199, '367', '', '', '0', 'A d?faut d\\\'intervenir sur le cours de l\\\'?volution des esp?ces de l\\\'?le, nous faisions tout ce qui ?tait en notre pouvoir, pour contr?ler son ?volution, tenter de la comprendre. Mais depuis, les choses ont bien chang?, le Tynril semble ?tre devenu le roi de cette jungle sombre. Rien ne l\\\'arr?te, et tout porte ? croire qu\\\'il devient petit ? petit, de plus en plus fou. Devenu le ma?tre de son propre territoire, le Tynril ne cherche plus ? perp?tuer correctement son esp?ce, ? la faire ?voluer, et cela m\\\'inqui?te. Je pense que si vous r?ussissiez ? le vaincre en combat, il retrouverait son ardeur d\\\'antan, et peut-?tre chercherait-il d\\\'avantage ? faire ?voluer sa prog?niture.');
INSERT INTO `npc_questions` VALUES (4200, '3678', '', '', '0', 'Cependant, je dois vous mettre en garde, le Tynril est une cr?ature originale, qui a d?j? surprit plus d\\\'un imprudent. Je ne permets qu\\\'aux aventuriers les plus valeureux, de p?n?trer dans cet ancien laboratoire. Pour me prouver ta valeur, tu devras affronter Silf le Rasboul Majeur. C\\\'est un adversaire redout?, si tu as r?ussi ? le vaincre, Razbitume te donnera la cl? pour entrer dans le laboratoire. ');
INSERT INTO `npc_questions` VALUES (4201, '3674', '', '', '0', 'Tu as brillamment vaincu le Tynril, tu nous as d?montr? que la nature elle-m?me est capable de se m?prendre. Le Tynril devra de toute ?vidence se r?soudre ? faire ?voluer sa prog?niture pour reprendre le tr?ne qu\\\'il m?ritait autrefois.');
INSERT INTO `npc_questions` VALUES (4203, '368', '', '', '0', 'Je suis persuad? que tu veux franchir cette porte... \\nSais-tu qu\\\'elle m?ne au Goulet du Rasboul ? \\nC\\\'est une zone tr?s dangereuse, elle est habit?e par Silf le Rasboul Majeur, une cr?ature tant?t surprenante, tant?t terrifiante.');
INSERT INTO `npc_questions` VALUES (4204, '3682', '', '', '0', 'Je ne permets qu\\\'aux aventuriers les plus valeureux, de s\\\'aventurer dans cet ancien laboratoire. Pour me prouver ta valeur, va aider mon ami, le Capitaine Flams, ? vaincre son pire ennemi, Gourlo le Terrible. J\\\'ai perdu une cargaison de Glouto Rhum ? cause de lui, et je ne pourrais jamais lui pardonner. Et surtout, ram?ne-moi une clef du Goulet du Rasboul si tu veux rentrer ici ! \\n');
INSERT INTO `npc_questions` VALUES (4205, '3683', '', '', '0', 'Vaincre Silf le Rasboul Majeur comme tu l\\\'as fait c\\\'est comme faire un baiser sans moustache. Mais ?a reste tout de m?me une belle performance.');
INSERT INTO `npc_questions` VALUES (4206, '368', '', '', '0', 'Grimper jusqu\\\'? cette hauteur sans s\\\'?tre fait d?vorer rel?ve g?n?ralement de l\\\'exploit. J\\\'imagine que tu te sens pr?t ? affronter le ma?tre des lieux, l\\\'incroyable Kimbo. C\\\'est le gardien de cet arbre, il est respect? par toutes les cr?atures de l\\\'?le. Il ?tait l? bien avant qu\\\'Otoma? ne vienne ici pour r?aliser ses exp?riences, et jusqu\\\'? pr?sent, ceux qui osent le d?fier se font humilier. \\nCette cr?ature adore jouer avec les aventuriers, elle est d\\\'une fourberie sans limite, c\\\'est ce qui en fait une cr?ature absolument adorable aux yeux d\\\'Otoma? !');
INSERT INTO `npc_questions` VALUES (4207, '368', '', '', '0', 'Nous aimons envoyer des groupes d\\\'aventuriers ? une d?faite certaine. Otoma? et moi parions r?guli?rement sur la dur?e moyenne des affrontements, avant que les aventuriers ne tr?passent. C\\\'est pour cela que nous ne laissons pas n\\\'importe qui affronter le Kimbo, nous n\\\'aimons pas parier inutilement. Je ne te laisserai aller l\\\'affronter que si tu es capable de me montrer que tu en es r?ellement digne. Affronte le Tynril, et si tu es capable de vaincre une telle cr?ature, tu devrais pouvoir r?sister quelques minutes face au Kimbo. De plus, Mul?ze te donnera la cl? pour acc?der ? la Canop?e du Kimbo.');
INSERT INTO `npc_questions` VALUES (4208, '368', '', '', '', 'J\\\'ai perdu mon pari, j\\\'avais pari? que tu perdrais ce combat au bout de quelques minutes. Vaincre le Kimbo sur son propre terrain, c\\\'est une performance digne des plus grands h?ros de notre ?poque. Avec un peu de chance, tu pourrais affronter un Kralamour G?ant ou un Dragon. Otoma? avait raison, les cr?atures sont comme nous, elles ont toutes un point faible et finissent par ?tre remplac?es, c\\\'est une ?volution naturelle et irr?m?diable. \\nToi-m?me, tu finiras un jour dans l\\\'estomac d\\\'une cr?ature plus forte que toi. Sa digestion risque d\\\'?tre difficile, elle pourrait m?me s\\\'?touffer en avalant tes chevilles ! Prends cette r?compense, Otomai m\\\'a dit un jour qu\\\'elle ?tait de grande valeur.');
INSERT INTO `npc_questions` VALUES (4209, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral pour pr?parer ta potion. Une fois r?duite en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4210, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, et une relique de Gourlo le Terrible pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4211, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, une relique de Gourlo le Terrible et une relique du Rasboul Majeur pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4212, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, une relique de Gourlo le Terrible, une relique du Rasboul Majeur et une relique du Tynril pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4213, '', '', '', '', 'Hum, d\\\'apr?s ta constitution, je peux d?terminer qu\\\'il me faudra une relique du Corailleur Magistral, une relique de Gourlo le Terrible, une relique du Rasboul Majeur, une relique du Tynril et une relique du Kimbo pour pr?parer ta potion. Une fois r?duites en poudre, je pourrais en retirer toute la puissance magique dont j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4214, '', '', '', '', 'Mes confr?res m\\\'ont assist? pendant des ann?es dans mes recherches, sans eux je n\\\'aurais jamais appris ni d?couvert autant de choses. Je me sens redevable, et j\\\'appr?cie qu\\\'en ?change de mes potions, d\\\'autres aventuriers puissent les aider. \\nJ\\\'aimerais que tu aides le Professeur Fournesol et Paulette Pain-B?che.');
INSERT INTO `npc_questions` VALUES (4215, '', '', '', '', 'Attention, avec cette potion toutes tes caract?ristiques vont ?tre r?initialis?es. \\nTu vas perdre tous les points de caract?ristiques que tu as gagn?s gr?ce ? des parchemins. \\nTu pourras ensuite r?partir ? nouveau tes points de caract?ristiques. \\nEs-tu certain de vouloir continuer ?');
INSERT INTO `npc_questions` VALUES (4216, '', '', '', '', 'Attention, en prenant cette potion, tu ne r?cup?reras que les points de caract?ristiques que tu as investis au dessus de 101 points de caract?ristiques. \\nCette potion te permet de ne pas perdre les points de caract?ristiques que tu as gagn?s gr?ce ? des parchemins de caract?ristiques. \\nMais tu ne pourras pas r?cup?rer les points de caract?ristiques que tu as investis en dessous de 101 points de caract?ristiques. \\nEs-tu certain de vouloir continuer ?');
INSERT INTO `npc_questions` VALUES (4217, '369', '', '', '0', 'Lorsque je suis arriv?, j\\\'ai constat? que l\\\'?le avait ?t? habit?e jadis. Par qui ? \\nJe ne le sais pas. \\nToujours est-il que la civilisation qui peuplait cette ?le avait d?j? construit des b?timents, des laboratoires d\\\'alchimie. Nous n\\\'avons fait que restaurer ce qui avait d?j? ?t? construit, d\\\'ailleurs nous d?couvrons de temps en temps de nouveaux laboratoires enfouis sous cette ?le.');
INSERT INTO `npc_questions` VALUES (4218, '', '', '', '', 'J\\\'ai ?crit plusieurs ouvrages sur cette ?le, et j\\\'ai d?j? pu lire des ouvrages sur cette civilisation disparue, malheureusement on ne les trouve plus dans les biblioth?ques depuis trop longtemps. Certaines autorit?s jugent que ces livres sont dangereux, ils remettent en question le pouvoir de certains dieux, et tentent d\\\'expliquer ce qui n\\\'a pas besoin de l\\\'?tre.');
INSERT INTO `npc_questions` VALUES (4219, '370', '', '', '0', 'Tu ne devrais pas aller t\\\'aventurer l?-bas, c\\\'est un endroit extr?mement dangereux. \\nUne terrible cr?ature y vit depuis des lustres, nous pensons qu\\\'elle ?tait peut-?tre d?j?-l? avant que l\\\'?le n\\\'?merge. \\nLes aventuriers qu\\\'elle a d?vor?s sont nombreux, son app?tit pour la chair fra?che semble malheureusement insatiable.');
INSERT INTO `npc_questions` VALUES (4220, '370', '', '', '0', 'Cette cr?ature g?ante n\\\'a cess? de grossir, et ses d?jections acides et putrides ont modifi? l\\\'?cosyst?me de toute une partie de l\\\'?le. Les plantes et toute autre forme de vie noble se meurent autour de cette cr?ature. \\nNous avons peur qu\\\'elle finisse par bouger, et qu\\\'elle contamine le reste de l\\\'?le. La mar?e noire qu\\\'elle est capable de cr?er serait un d?sastre pour notre ?le.');
INSERT INTO `npc_questions` VALUES (4221, '370', '', '', '0', 'Pour l\\\'instant,  elle ne semble pas vouloir partir de sa tourbi?re, mais nous avons tout de m?me d? construire des protections pour emp?cher les imprudents de se faire d?vorer b?tement. De temps en temps, mes coll?gues vont contr?ler la taille et l\\\'odeur de cette cr?ature, elle semble mal?fique, mais c\\\'est tout de m?me une cr?ature unique et remarquable, un sujet d\\\'?tude inestimable.');
INSERT INTO `npc_questions` VALUES (4222, '370', '', '', '0', 'Le m?canisme que nous utilisons pour ouvrir cette porte est assez complexe et gard? secret, nous ne voulons pas engraisser inutilement cette cr?ature avec les badauds en qu?te d\\\'aventure. \\nN\\\'oublie jamais que cette cr?ature est extr?mement puissante et dangereuse, la carcasse de dragon que l\\\'on peut trouver dans la tourbi?re nous laisse penser qu\\\'il a ?t? tu? par cette cr?ature.');
INSERT INTO `npc_questions` VALUES (4223, '', '', '', '', 'Les opinions divergent ? ce sujet, mais on raconte qu\\\'un terrible dragon aurait tent? d\\\'attaquer cette cr?ature. \\nCette derni?re aurait alors attrap? le dragon avec ses tentacules pour l\\\'?touffer sous la tourbe, prenant ainsi le dragon au d?pourvu. \\nLes dragons incarnent la puissance, c\\\'est pourquoi beaucoup de personnes refusent d\\\'accepter cette histoire. \\nMais les faits sont l?, il y a une carcasse de dragon enfouie dans cette tourbi?re.');
INSERT INTO `npc_questions` VALUES (4224, '', '', '', '', 'Ce village situ? sur la cime de cet arbre g?ant, est habit? par les Zoths, un groupe d\\\'anciens touristes venus d?couvrir l\\\'?le, et qui sont devenus un peu fous en buvant l\\\'eau de la tourbi?re naus?abonde. \\nQuand on sait ce qu\\\'elle contenait, on peut ais?ment comprendre que quelque chose ne tourne plus tr?s rond chez eux... \\nIls vivent cependant en paix, de fa?on autarcique. Ils ont voulu s\\\'?manciper de la soci?t? ? laquelle ils appartenaient. \\nTant que personne ne les d?range, ils restent calmes et disciplin?s.');
INSERT INTO `npc_questions` VALUES (4225, '3706;3707;3708', '', '', '0', 'Bonjour, je m\\\'appelle Parcho, je vends tous les parchemins qui pourraient t\\\'int?resser. \\nJe peux ?galement te faire essayer divers oublis de caract?ristiques et de sorts.');
INSERT INTO `npc_questions` VALUES (4226, '371', '', '', '0', 'Je suis Kroula, le proph?te d\\\'un terrible monstre... Ce qui se cache derri?re cette porte emportera vos derniers espoirs de retourner chez vous. Entendez son fracas quand il s\\\'?veille le matin, le terrible son du roi de l\\\'?le, du roi du monde !');
INSERT INTO `npc_questions` VALUES (4227, '371', '', '', '0', 'Tremblez, mortels ! Ce monstre ?tait l? avant l\\\'?le, il EST l\\\'?le. Personne ne peut rivaliser avec sa puissance et ce n\\\'est pas cet Otoma? et ses tours de sorcier qui feront la diff?rence. J\\\'ai bien entendu parler de cette terrrrrible cr?ation qu\\\'il aurait accomplie mais croyez moi, c\\\'est du flan !');
INSERT INTO `npc_questions` VALUES (4228, '391', '', '', '0', 'Cette ?le ?tait l? il y a tr?s longtemps, avant m?me la construction de l\\\'Horloge de Xelor et la formation des continents ! Ce monstre est un dieu vivant, personne ne peut le vaincre ! Je ne sais m?me pas si vous ?tes assez dignes pour ne serait-ce qu\\\'avoir le droit de le contempler !');
INSERT INTO `npc_questions` VALUES (4229, '', '', '', '', 'Ce que vous voyez l?, nous avons pu le faire gr?ce ? nos exp?riences sur les ?l?ments. Nous savons d?sormais comment fabriquer de la glace, et garder des microclimats nous permettant de faire ?voluer la bact?rie d\\\'Otoma?. Pour le meilleur. Et pour le pire.');
INSERT INTO `npc_questions` VALUES (4230, '', '', '', '', 'Il s\\\'agit d\\\'une technique particuli?re, car cette bact?rie nous est totalement inconnue ! Nous soup?onnons qu\\\'elle soit apparue au tout d?but de la formation du monde, quand les hommes connaissaient les subtilit?s de  tous les ?l?ments.');
INSERT INTO `npc_questions` VALUES (4231, '', '', '', '', 'Nous avons perdu beaucoup de notre pass?, et reconstituer les conditions de vie de cette ?poque est pour nous la seule fa?on de percer les derniers myst?res de la vie. Nous jouons aux apprentis sorciers... Cette... cr?ature que nous avons cr??e... elle... s\\\'est enfuie. ');
INSERT INTO `npc_questions` VALUES (4232, '', '', '', '', 'N\\\'ayez pas peur, la bact?rie que vous voyez l? est en r?alit? microscopique. L\\\'effet grossissant de la glace peut vous jouer des tours. Mais m?me contre cette minuscule bact?rie, vous ne voudriez pas vous battre. C\\\'est qu\\\'elle est particuli?re.');
INSERT INTO `npc_questions` VALUES (4233, '', '', '', '', 'Nous l\\\'avons retrouv?e dans le pollen de toute l\\\'?le, et nous nous servons de la glace pour la conserver. Bien s?r, ? leur stade primitif, ces bact?ries sont parfaitement inoffensives mais les recherches que nous avons effectu?es nous ont permis d\\\'en cr?er des plus ?volu?es.');
INSERT INTO `npc_questions` VALUES (4234, '', '', '', '', 'Nous l\\\'avons baptis?e Plasmogrine, et nous savons qu\\\'elle est consciente. C\\\'est terrible, n\\\'est-ce pas ? Cette version simplifi?e de l\\\'organisme nous a permis de percer les secrets de l\\\'?volution, et ce que nous avons trouv? remet en cause l\\\'?quilibre m?me du monde ! \\n \\nOlala, si seulement Otoma? n\\\'?tait pas all? si loin. Il ne pensait pourtant pas ? mal...');
INSERT INTO `npc_questions` VALUES (4235, '371', '', '', '0', 'C\\\'est dans cette cage de titane et de chaines renforc?es que vivait la plus belle cr?ation d\\\'Otoma?, le joyau de l\\\'?le, dont le nom signifie tout ? la fois vorace et costaud. Qui aurait cru que ce petit bout de rien puisse devenir si gros ?');
INSERT INTO `npc_questions` VALUES (4236, '371', '', '', '0', 'Nourrie tous les jours d\\\'une haine f?roce pour ses ge?liers, apr?s avoir obtenu l\\\'immunit? pendant si longtemps, la cr?ature s\\\'est ?vad?e. D\\\'elle, il ne reste rien, ou si peu, quelques poils de dos. Qui sait quels d?g?ts elle commettra demain.');
INSERT INTO `npc_questions` VALUES (4237, '371', '', '', '0', 'Non, non, vous vous trompez, il ne s\\\'agit pas du monstre de la tourbi?re. Il ?tait l? depuis toujours. Il est peut-?tre lui aussi li? ? la Plasmogrine, une ?volution parall?le, c\\\'est possible, tout est possible sur cette ?le ! Le monstre de la tourbi?re est le cadet de nos soucis...');
INSERT INTO `npc_questions` VALUES (4238, '', '', '', '', 'Le secret d\\\'Otoma? est bien gard?. Cette cr?ation ultime, d?velopp?e ? partir des meilleures souches bact?riennes de l\\\'?le, est une machine ? manger. Les particularit?s dimensionnelles de Plasmogrine permettent ? cette cr?ature de conserver son estomac dans une autre dimension. Elle est quasiment immortelle !');
INSERT INTO `npc_questions` VALUES (4239, '', '', '', '', 'Je n\\\'ai pas le temps de r?parer les boucliers cass?s, mais en attendant je peux te donner un bouclier en tr?s bon ?tat si tu me donnes un bouclier cass?. J\\\'?change tous les mod?les de boucliers cass?s !');
INSERT INTO `npc_questions` VALUES (4241, '', '', '', '', '?chou?, petit scarafeuille, tu as !');
INSERT INTO `npc_questions` VALUES (4242, '', '', '', '', 'Bien le bonjour !');
INSERT INTO `npc_questions` VALUES (4243, '', '', '', '', 'Maljour ? vous !');
INSERT INTO `npc_questions` VALUES (4244, '', '', '', '', 'Bonsoir !');
INSERT INTO `npc_questions` VALUES (4245, '', '', '', '', 'Malsoir !');
INSERT INTO `npc_questions` VALUES (4246, '', '', '', '', 'Belle nuit, n\\\'est-ce pas ?');
INSERT INTO `npc_questions` VALUES (4249, '', '', '', '', 'Pnj(961) et Message(4247)');
INSERT INTO `npc_questions` VALUES (4253, '', '', '', '', 'Alors je t\\\'attends.');
INSERT INTO `npc_questions` VALUES (4256, '', '', '', '', 'Et bien, votre ?p?e maudite a l\\\'air vraiment inutilisable, elle est coupante, mais sa lame est tellement mal ?quilibr?e que vous devez frapper ? c?t? une fois sur deux ! \\nJe dois pouvoir l\\\'am?liorer si vous voulez.');
INSERT INTO `npc_questions` VALUES (4257, '', '', '', '', 'Je vais avoir besoin d\\\'un tr?s bon manche pour am?liorer ton arme. Ram?ne-moi une Racine Huzohide ainsi que ton ?p?e maudite, et je pourrais rendre ton arme enfin utilisable.');
INSERT INTO `npc_questions` VALUES (4258, '', '', '', '', 'Alors, as-tu trouv? ce que je t\\\'avais demand? ?');
INSERT INTO `npc_questions` VALUES (4259, '', '', '', '', 'Avec ce b?ton, je vais pouvoir te sculpter un manche de faux particuli?rement efficace. Il ne me restera plus qu\\\'? d?monter la lame de ton ?p?e.');
INSERT INTO `npc_questions` VALUES (4260, '', '', '', '', 'Avec ce b?ton, je vais pouvoir te sculpter un manche de faux particuli?rement efficace. Il ne me reste plus qu\\\'? d?monter la lame de ton ?p?e... \\nEt voil?, ton arme est pr?te. Evite d\\\'aller faucher les bl?s avec, tu risquerais de mettre le feu aux champs.');
INSERT INTO `npc_questions` VALUES (4264, '', '', '', '', '?a va du calme, nous avons compris la le?on. Si tu veux en savoir plus, prends contact avec Hersa Griffe Sombre ? Bonta mais surtout ?vite de lui dire que nous t\\\'avons parl? d\\\'elle.');
INSERT INTO `npc_questions` VALUES (4265, '', '', '', '', 'Alors ? As-tu trouv? quelque chose d\\\'int?ressant ?');
INSERT INTO `npc_questions` VALUES (4266, '', '', '', '', 'Nous sommes en train de finaliser un nouveau plan contre Bonta. Je vais bient?t demander ? nouveau tes services.');
INSERT INTO `npc_questions` VALUES (4267, '', '', '', '', 'Alors comme ?a tu penses qu\\\'un notable bontarien pourrait travailler pour nous ? Ca tombe bien, ?a faisait un moment que j\\\'y pensais. Par contre j\\\'esp?re pour toi que ce Xephir?s est bien la personne qui a sign? ce document sinon ?a va barder.');
INSERT INTO `npc_questions` VALUES (4268, '', '', '', '', 'Nous devons en savoir plus sur ce Xephir?s. Comme j\\\'ai des recrues qui ne savent pas comment passer le temps, je vais les envoyer enqu?ter un peu partout. Toi tu vas interroger les taverniers de Bonta, je ne veux pas que les jeunes recrues se fassent rep?rer chez nos ennemis.');
INSERT INTO `npc_questions` VALUES (4269, '', '', '', '', 'Je pr?f?re que d\\\'autres personnes t\\\'accompagnent, nous ignorons si les bandits sont nombreux et les ressources ? leur disposition.');
INSERT INTO `npc_questions` VALUES (4270, '', '', '', '', 'Qui ? Ah, ce n\\\'est pas le dernier champion du concours de ramassage de bave de bouftou ? ... Non ? Bon ben, \\\'connais pas alors.');
INSERT INTO `npc_questions` VALUES (4271, '', '', '', '', 'Xephir?s ? Non, ?a ne me dit rien du tout.');
INSERT INTO `npc_questions` VALUES (4272, '', '', '', '', 'Un personnage important de Bonta? Non, ce n\\\'est pas ici que tu trouveras ce genre d\\\'information.');
INSERT INTO `npc_questions` VALUES (4273, '', '', '', '', 'Si c\\\'est un notable et qu\\\'il n\\\'est pas venu dans ma taverne, vous devriez essayer la taverne Alakarte. Vous le cherchez pour quoi au juste ?');
INSERT INTO `npc_questions` VALUES (4274, '', '', '', '', 'Qui ? Ah, ce n\\\'est pas le dernier champion du concours de ramassage de bave de bouftou ? ... Non ? Bon ben, \\\'connais pas alors.');
INSERT INTO `npc_questions` VALUES (4275, '', '', '', '', 'Il y a des notables qui passent parfois au nord, aux environs de la maison d\\\'Ufot. J\\\'ai entendu des clients en discuter mais jamais entendu le nom de Xephir?s.');
INSERT INTO `npc_questions` VALUES (4276, '', '', '', '', 'Tu as d?j? fait le tour des tavernes de Bonta ? Je ne veux pas savoir qui a la meilleure bi?re, ?a je le sais d?j? ! As-tu trouv? des informations int?ressantes ?');
INSERT INTO `npc_questions` VALUES (4277, '', '', '', '', 'Salut. H?h?. Fais attention, cet endroit n\\\'est pas un coin tranquille...');
INSERT INTO `npc_questions` VALUES (4278, '', '', '', '', 'Ah, c\\\'est toi qui a besoin d\\\'informations sur Xephir?s. Je pense pouvoir t\\\'?tre utile mais avant il faut que tu me rendes un petit service. Oh ne t\\\'inqui?te pas ce n\\\'est pas grand chose, trois fois rien.');
INSERT INTO `npc_questions` VALUES (4280, '', '', '', '', 'Je crois qu\\\'ils ressemblaient ? des gobelins... ou des Bworks. Ou des abraknydes, peut-?tre.');
INSERT INTO `npc_questions` VALUES (4281, '', '', '', '', 'As-tu trouv? le Sram dans la for?t des abraknydes ? Si ce n\\\'est pas le cas retourne l?-bas sur le champ !');
INSERT INTO `npc_questions` VALUES (4282, '', '', '', '', 'Je te pr?viens, si tu ne m\\\'apportes pas les informations sur Xephir?s rapidement, je te fais l?cher tous les orifices par un bouftou.');
INSERT INTO `npc_questions` VALUES (4283, '', '', '', '', 'C\\\'est toi ! Tu ne devineras jamais ce qui m\\\'est arriv? !');
INSERT INTO `npc_questions` VALUES (4284, '', '', '', '', 'Comme tu voudras, mais tu ne pourras pas dire que je ne t\\\'avais pas pr?venu.');
INSERT INTO `npc_questions` VALUES (4285, '', '', '', '', 'Je vous jure, c\\\'est la v?rit?. Jamais je ne trahirai Bonta. Je ne suis pas parfait mais je suis fid?le aux principes de notre noble cit?. Je suis pr?t ? le jurer devant Jiva en personne. Je vous en supplie, ne me d?noncez pas. Je vous promets de ne plus m\\\'approvisionner aupr?s des Br?kmariens, il y a d\\\'autres fournisseurs m?me s\\\'ils sont un peu plus chers..');
INSERT INTO `npc_questions` VALUES (4286, '', '', '', '', 'Ah ! Nos efforts ont port? leurs fruits. La taverne du Pandawa Ivre, hein ? On va pouvoir le contacter, maintenant. \\nTiens, prends ces quelques bi?res pour te rafra?chir le gosier.');
INSERT INTO `npc_questions` VALUES (4287, '', '', '', '', 'Le but est de se faire passer pour des marchands, pas pour des mendiants. Tu aurais pu demander ? Amayiro de te trouver une tenue d?cente. Enfin, de toute mani?re il est trop tard, nous devons y aller. D\\\'autres gardes sont cach?s dans les v?hicules, ils nous assisteront en cas d\\\'attaque. Allons-y !');
INSERT INTO `npc_questions` VALUES (4288, '', '', '', '', 'Bonjour. Pardonnez-moi, mais je profite d\\\'un de mes rares moments de repos, donc je ne souhaite pas entamer de discussion.');
INSERT INTO `npc_questions` VALUES (4289, '', '', '', '', 'Comment ? Trahir Bonta ? Jamais. J\\\'ignore ce que vous voulez dire quand vous parlez de pot-de-vin, Br?kmarien, et je vous conseille de sortir de cette taverne avant que les choses ne tournent mal !');
INSERT INTO `npc_questions` VALUES (4290, '', '', '', '', 'Oh ? Un bijou somptueux ? Mais bien s?r, j\\\'en ai une dizaine sous la main. Tiens, prends celui qui te plait. Et pas besoin de payer, c\\\'est la maison qui offre.');
INSERT INTO `npc_questions` VALUES (4291, '', '', '', '', 'Je pense que tu as devin? ta prochaine t?che. Rends-toi ? la taverne du Pandawa Ivre entre 16h et minuit, rencontre Xephir?s et parle-lui de notre proposition : un gros sac de kamas contre son ob?issance.');
INSERT INTO `npc_questions` VALUES (4292, '', '', '', '', 'Alors ? Tu lui as parl? ?');
INSERT INTO `npc_questions` VALUES (4293, '', '', '', '', 'Refus?, hein ? Je me doutais que ce ne serait pas aussi facile. Mais je suis s?r qu\\\'il changera d\\\'avis si nous lui montrons quelque chose de tr?s pr?cieux. Je connais le genre, il ne pourra pas dire non s\\\'il a l\\\'objet sous les yeux. \\nReste ? le trouver, cet objet pr?cieux. D\\\'apr?s ce que tu m\\\'avais dit, un bijou pourrait faire l\\\'affaire. Tu vas te rendre imm?diatement ? la bijouterie de Bonta et demander quel genre de bijou il affectionne. Tu iras ensuite demander ? Milone Corichel de t\\\'en fabriquer un.');
INSERT INTO `npc_questions` VALUES (4294, '', '', '', '', 'S\\\'il refuse, on peut toujours recourir aux menaces. Ou mieux. J\\\'ai quelques bourreaux qui sont au ch?mage en ce moment.');
INSERT INTO `npc_questions` VALUES (4295, '', '', '', '', 'Eh bien. Avec une liste aussi longue, j\\\'imagine que le r?sultat fera l\\\'affaire. Reste ? r?cup?rer tout ?a.');
INSERT INTO `npc_questions` VALUES (4296, '', '', '', '', 'J\\\'ai envoy? des hommes s\\\'occuper des mat?riaux les plus simples ? obtenir. Toi par contre je t\\\'ai gard? le meilleur : tu vas m\\\'apporter cinq lingots d\\\'or et une nacre. Tu ignores probablement o? trouver de la nacre et c\\\'est normal puisque c\\\'est moi le chef. \\nIl te faut r?unir dix nacres brutes sur les crustac?s et mollusques de l\\\'?le d\\\'Otoma?, ce qui inclut les crustorails et les corailleurs. Ensuite, tu as besoin d\\\'un mineur capable de te les polir. \\nPense aussi ? m\\\'apporter une bave du bouftou royal. Ne pose pas de question sur pourquoi de la bave du bouftou royal, tu le sauras en temps et en heure. N\\\'oublie pas qui donne les ordres ici alors ne discute pas ! \\nT\\\'es encore l? ? Tu attends peut-?tre que je joue des claquettes ? Au travail !');
INSERT INTO `npc_questions` VALUES (4297, '', '', '', '', 'J\\\'ai l\\\'impression que tu manques d\\\'actions br?kmariennes c\\\'est pourquoi j\\\'ai pr?par? une mission qui va te faire plaisir. \\nMilone a besoin d\\\'un cristal de Kain Dharyn et au cas o? tu ne le saurais pas, c\\\'est un cristal tr?s rare et tr?s convoit?. Mes espions m\\\'ont rapport? que la famille du Captain Starky de Bonta en poss?dait quelques-uns. Comme il nous est impossible d\\\'agresser directement le Captain Starky tu vas enlever sa ni?ce Sabine et exiger un cristal de Kain Dharyn en ran?on. Je vais noter l\\\'emplacement de sa demeure sur ta carte.');
INSERT INTO `npc_questions` VALUES (4298, '', '', '', '', 'O? en es-tu avec Sabine ?');
INSERT INTO `npc_questions` VALUES (4300, '', '', '', '', 'As-tu r?cup?r? les mat?riaux que je t\\\'ai demand?s ou dois-je confier cette t?che ? quelqu\\\'un de plus dou? ?');
INSERT INTO `npc_questions` VALUES (4301, '', '', '', '', 'Garde tes blagues idiotes pour la taverne. Encore une remarque dans ce genre et je t\\\'?tire la langue jusqu\\\'? pouvoir faire le tour des remparts de Br?kmar avec.');
INSERT INTO `npc_questions` VALUES (4302, '', '', '', '', 'Vous ?tes certain de vouloir rentrer ? nouveau dans ce laboratoire ? \\nComme vous voudrez, mais je ne vous laisserai rentrer que si vous me ramenez un fragment de cerveau poli. Vous en trouverez sur les Craqueleurs Polis qui se prom?nent dans les plaines.');
INSERT INTO `npc_questions` VALUES (4303, '379', '', '', '0', 'Vous ?tes certain de vouloir repartir l? o? je vous avais emmen? ? Vous souvenez-vous que cet endroit est particuli?rement dangereux ? \\nJ\\\'accepte de vous y accompagner ? condition que vous me rapportiez un Calice de F?corce.');
INSERT INTO `npc_questions` VALUES (4304, '', '', '', '', 'Oh lui ? C\\\'est un Pandawa pass? ma?tre dans l\\\'art du pandawushu. Il est capable de t\\\'arracher une touffe de poils ? 10 m?tres de distance avec un seul orteil. Tu devrais le voir ? l\\\'oeuvre, il est impressionnant ! Mais moins que moi ?a va de soi. Si tu le cherches je te souhaite bien du courage car il vient de partir en p?lerinage spirituel dans la Vall?e de la Morh\\\'Kitu.');
INSERT INTO `npc_questions` VALUES (4305, '', '', '', '', 'Mes confr?res m\\\'ont assist? pendant des ann?es dans mes recherches, sans eux je n\\\'aurais jamais appris ni d?couvert autant de choses. Je me sens redevable, et j\\\'appr?cie qu\\\'en ?change de mes potions, d\\\'autres aventuriers puissent les aider. \\nJ\\\'aimerais que tu aides le Professeur Fournesol, Paulette Pain-B?che, Polka Merer, et Kito.');
INSERT INTO `npc_questions` VALUES (4306, '', '', '', '', 'Mes confr?res m\\\'ont assist? pendant des ann?es dans mes recherches, sans eux je n\\\'aurais jamais appris ni d?couvert autant de choses. Je me sens redevable, et j\\\'appr?cie qu\\\'en ?change de mes potions, d\\\'autres aventuriers puissent les aider. \\nJ\\\'aimerais que tu aides le Professeur Fournesol, Paulette Pain-B?che, Polka Merer, Kito, le Docteur Nauh, Spitte Fayeur, et Flip Flap.');
INSERT INTO `npc_questions` VALUES (4307, '', '', '', '', 'Mes confr?res m\\\'ont assist? pendant des ann?es dans mes recherches, sans eux je n\\\'aurais jamais appris ni d?couvert autant de choses. Je me sens redevable, et j\\\'appr?cie qu\\\'en ?change de mes potions, d\\\'autres aventuriers puissent les aider. \\nJ\\\'aimerais que tu aides le Professeur Fournesol, Paulette Pain-B?che, Polka Merer, Kito, le Docteur Nauh, Spitte Fayeur, Flip Flap, et le Docteur Morose.');
INSERT INTO `npc_questions` VALUES (4308, '', '', '', '', 'Mes confr?res m\\\'ont assist? pendant des ann?es dans mes recherches, sans eux je n\\\'aurais jamais appris ni d?couvert autant de choses. Je me sens redevable, et j\\\'appr?cie qu\\\'en ?change de mes potions, d\\\'autres aventuriers puissent les aider. \\nJ\\\'aimerais que tu aides le Professeur Fournesol, Paulette Pain-B?che, Polka Merer, Kito, le Docteur Nauh, Spitte Fayeur, Flip Flap, le Docteur Morose, Peggy la Porkass, et Crocodaille Dandi.');
INSERT INTO `npc_questions` VALUES (4309, '', '', '', '', 'Encore vous !? Ma r?ponse est non, cessez de m\\\'importuner !');
INSERT INTO `npc_questions` VALUES (4310, '', '', '', '', 'Je ne t\\\'avais pas vu depuis longtemps. J\\\'ai cr? que le kralamoure g?ant t\\\'avait aval?. N\\\'oublie pas d\\\'aller boire un coup avec les autres miliciens de temps ? autres, j\\\'ai horreur des imb?ciles qui ne pensent qu\\\'? travailler.');
INSERT INTO `npc_questions` VALUES (4314, '', '', '', '', 'Il n\\\'y a pas un instant ? perdre. Certaines personnes douteuses ont appris l\\\'existence du bijou de Milone, et j\\\'ai appris de source s?re que des voleurs sont sur le point de s\\\'en charger. Rends-toi vite chez Milone avec cette lettre et emp?che-les de d?rober le bijou. \\nSi tu croises d\\\'autres miliciens en chemin, emm?ne-les avec toi.');
INSERT INTO `npc_questions` VALUES (4315, '', '', '', '', 'Un message d\\\'Oto ? Des voleurs qui vont s\\\'introduire chez moi ? Ah ! J\\\'entends des bruits de pas !');
INSERT INTO `npc_questions` VALUES (4316, '', '', '', '', 'Tu oses me rappeler cette histoire ? Tu veux finir dans le m?me ?tat que lui, borgne et alcoolique ?');
INSERT INTO `npc_questions` VALUES (4317, '', '', '', '', 'Tu me prends pour qui ? Hmmm, tout bien r?fl?chi, ?a sera toujours ?a de gagn? pour m\\\'acheter une Griffe Pourpre. \\nTu as de la chance, ce cr?tin de Grimpill est justement de passage en ville. Je l\\\'ai aper?u se dirigeant vers la Taverne de la Bagrutte, mais lui m\\\'?vite comme la peste, et il a bien raison. S\\\'il ose venir m\\\'adresser la parole, il t?tera de ma Griffe de Ceangal.');
INSERT INTO `npc_questions` VALUES (4318, '', '', '', '', 'Un Ecaflip borgne dis-tu ? Je n\\\'ai pas fait attention, mais interroge plut?t les filles, je crois qu\\\'Ecaline a eu quelques soucis avec un Ecaflip r?cemment.');
INSERT INTO `npc_questions` VALUES (4319, '', '', '', '', 'J\\\'aime mieux ?a. Maintenant mets-toi ? table et commande ? boire.');
INSERT INTO `npc_questions` VALUES (4320, '', '', '', '', 'Pas mal, fiston. Le bijou que j\\\'ai sur moi est un faux, mais tu m\\\'as ?vit? de devoir te couvrir de reproches. \\nRetourne voir ton chef et dis-lui que j\\\'aurai bient?t termin?. Au fait, quel est ce papier que tu as ramass? sur un des cambrioleurs ?');
INSERT INTO `npc_questions` VALUES (4321, '', '', '', '', 'Humph. C\\\'?tait bien la peine d\\\'arriver ? temps si c\\\'est pour te faire botter le train par une bande de voleurs de pacotille. \\nHeureusement, celui que j\\\'avais sur moi ?tait un faux. Retourne voir ton chef et dis-lui que j\\\'aurai bient?t termin? mais que la prochaine fois, j\\\'appr?cierai qu\\\'il m\\\'envoie quelqu\\\'un sachant se battre. \\nAu fait, un des voleurs a fait tomber ce papier pendant le combat. Va falloir faire du m?nage dans la milice pour ?viter que ce genre de fuite se reproduise.');
INSERT INTO `npc_questions` VALUES (4322, '', '', '', '', 'Tu attends quoi ? Chaque seconde compte ! File chez Milone !');
INSERT INTO `npc_questions` VALUES (4323, '', '', '', '', 'On m\\\'a rapport? que tu fl?nais dans les rues. Qu\\\'as-tu ? r?pondre ? ?a ?');
INSERT INTO `npc_questions` VALUES (4324, '', '', '', '', 'En attendant que Milone finisse le bijou, il faut donner un rendez-vous ? notre ami Xephir?s. La tour de Bonta, ce sera parfait : ? l\\\'endroit o? tu as trouv? le morceau de papier. Tiens, voici une lettre : d?brouille-toi pour que Xephir?s la re?oive. Je te rappelle qu\\\'il passe beaucoup de temps ? la taverne du Pandawa Ivre... vu que tu l\\\'as s?rement d?j? oubli');
INSERT INTO `npc_questions` VALUES (4328, '', '', '', '', 'Alors ? Tu as trouv? un moyen pour faire passer le message ?');
INSERT INTO `npc_questions` VALUES (4329, '', '', '', '', 'Parfait. La derni?re partie du plan va pouvoir d?buter.');
INSERT INTO `npc_questions` VALUES (4330, '', '', '', '', 'Je suis d?sol?e, mais tu sembles bien trop faible pour utiliser ce moyen de transport... \\nReviens me voir lorsque tu seras un peu plus fort.');
INSERT INTO `npc_questions` VALUES (4331, '3807', '', '', '', 'Tu n\\\'as qu\\\'? monter dans ce magnifique canon !');
INSERT INTO `npc_questions` VALUES (4332, '', '', '', '', 'C\\\'est VOUS qui avez ?t? envoy? ? Je me doutais qu\\\'il y avait quelque chose de louche. Tr?s bien, quel est cet ?change tr?s int?ressant dont il ?tait question dans la lettre ?');
INSERT INTO `npc_questions` VALUES (4333, '', '', '', '', 'C\\\'est le moment. Prends ce joyau et retrouve Xephir?s ? la Taverne du Pandawa Ivre. Comme je ne te fais pas confiance pour correctement expliquer le plan, je vais ?crire une lettre que tu lui donneras sur place. \\nOh, et n\\\'essaye m?me pas de garder le joyau pour toi ou de le vendre : j\\\'ai des espions partout, et si jamais tu me trahis je peux t\\\'assurer que tu le regretteras. Mais tu n\\\'y penserais pas, hein ?');
INSERT INTO `npc_questions` VALUES (4334, '', '', '', '', 'Oh... ! Quelle merveille. Et il pourrait ?tre ? moi si j\\\'accepte les conditions de cette lettre ? \\nHmm... trahir Bonta pour Br?kmar... je ne devrais pas... mais... ce joyau est si beau... \\n... \\nJ\\\'ai besoin de temps pour r?fl?chir. Mon s?jour ? Pandala touche ? sa fin mais il me reste une affaire ? r?gler, peut-?tre que vous pouvez vous en charger en signe de bonne foi. Je dois faire livrer cette caisse au Conseiller Boyowa, chez le Grandapan. Lorsque ce sera fait, rejoignez-moi dans la Tour de Bonta, l? o? vous avez trouv? le morceau de lettre d?chir?. Je vous ferai alors savoir quelle est ma d?cision.');
INSERT INTO `npc_questions` VALUES (4335, '', '', '', '', 'Ha ha ha ! Je savais que ceux de son esp?ce ne pouvaient pas r?sister ? ce genre de proposition. Nous venons d\\\'acqu?rir un alli? de poids contre Bonta. Tr?s bon travail, vermisseau, mais rends-moi le joyau.');
INSERT INTO `npc_questions` VALUES (4336, '', '', '', '', 'Ce que nous allons en faire ? Le vendre, bien s?r. Tu croyais qu\\\'on allait r?ellement suivre ce \\\"contrat\\\" ? Quand Xephir?s aura accompli sa mission, on se d?barrassera de lui, voil? tout.\\nD\\\'ailleurs, en parlant de ?a, il faudra que je pense ? faire dispara?tre Milone... il a ?t? vraiment exasp?rant sur cette affaire, et de toute fa?on il en sait trop. Mais ?a peut attendre.');
INSERT INTO `npc_questions` VALUES (4337, '', '', '', '', 'Xephir?s t\\\'attendra dans la tour de Bonta, ? l\\\'endroit o? tu as trouv? le morceau de lettre pour la premi?re fois. Fais attention ? ne pas te faire pincer avec le joyau.');
INSERT INTO `npc_questions` VALUES (4338, '', '', '', '', 'J\\\'accepte vos conditions. Ne restez pas ici, on pourrait nous surprendre !');
INSERT INTO `npc_questions` VALUES (4339, '', '', '', '', 'J\\\'accepte vos conditions. Ne restez pas ici, on pourrait nous surprendre !');
INSERT INTO `npc_questions` VALUES (4340, '', '', '', '', 'Le marchand de vin du coin a disparu. Je soup?onne un enl?vement, mais il pourrait y avoir autre chose. Peux-tu te renseigner aupr?s du tavernier de la Bagrutte ? Le marchand avait pour habitude d\\\'aller chez lui.');
INSERT INTO `npc_questions` VALUES (4341, '', '', '', '', 'Laisse-moi voir cette lame. \\nCe n\\\'est pas une arme commune et ? en juger par les traces de griffes et les poils laiss?s sur la poign?e et le pommeau, cette ?p?e a ?t? utilis?e par un Ecaflip. Je suis expert en lames mais pas en Ecaflips, tu devrais interroger quelques-uns de leurs guerriers. Tiens, reprends ton ?p?e.');
INSERT INTO `npc_questions` VALUES (4342, '', '', '', '', 'Salut. Qu\\\'est-ce qui t\\\'am?ne par ici ?');
INSERT INTO `npc_questions` VALUES (4343, '', '', '', '', 'Disparu !? C\\\'est pas vrai, c\\\'?tait un de mes meilleurs clients ! \\nBen, apr?s son passage ici il avait l\\\'habitude de rentrer chez lui, un peu plus vers l\\\'Est.');
INSERT INTO `npc_questions` VALUES (4344, '', '', '', '', 'Bonjour. Vous visitez notre belle cit? ?');
INSERT INTO `npc_questions` VALUES (4345, '', '', '', '', 'Bonjour, ami Bontarien !');
INSERT INTO `npc_questions` VALUES (4346, '', '', '', '', 'Que fait un Br?kmarien ici ? Ne m\\\'approchez pas, ou j\\\'appelle la garde !');
INSERT INTO `npc_questions` VALUES (4347, '', '', '', '', 'S\\\'il vous plait ? J\\\'ai trouv? quelque chose d\\\'?trange ici !');
INSERT INTO `npc_questions` VALUES (4348, '', '', '', '', 'Comme vous le voyez, il y a des traces de combat dans cet angle. Que s\\\'est-il donc pass? ? J\\\'ai aussi trouv? cette arme par terre... \\nOh, vous faites une enqu?te ? Tenez, je vous remets l\\\'arme, elle vous sera peut-?tre utile. Kosuke le forgeron pourra vous dire sa provenance, mais vous y avez d?j? s?rement pens');
INSERT INTO `npc_questions` VALUES (4350, '', '', '', '', 'Ce que je dis n\\\'est pas clair o? as-tu une ouassingue fourr?e dans les oreilles ? Il me faut un milicien ayant d?j? fait ses preuves et re?u sa premi?re perm\\\'. Celui-l? est un incomp?tent de premi?re, je ne peux pas lui confier de mission importante.');
INSERT INTO `npc_questions` VALUES (4351, '', '', '', '', 'Si l\\\'Ecaflip est un voyageur, il a probablement fait une halte dans l\\\'une des tavernes de la cit?. Va demander aux taverniers s\\\'ils en ont vu un r?cemment et n\\\'en profite pas pour boire, tu es en service je te rappelle.');
INSERT INTO `npc_questions` VALUES (4352, '', '', '', '', 'Des nouvelles de ce marchand ?');
INSERT INTO `npc_questions` VALUES (4353, '', '', '', '', 'Une sc?ne de crime et une ?p?e mani?e par un Ecaflip ? Il va falloir enqu?ter davantage. C\\\'est du bon boulot que tu fais l?, continue comme ?a.');
INSERT INTO `npc_questions` VALUES (4354, '', '', '', '', 'Des voyageurs Ecaflips ? Pas eu de ?a dans ma taverne ces derniers temps, non.');
INSERT INTO `npc_questions` VALUES (4355, '', '', '', '', 'Des voyageurs Ecaflips, hmm... non, je ne crois pas en avoir re?u derni?rement. Par contre, si ?a vous int?resse, nous venons d\\\'engager une jeune Ecaflip tr?s chatte. \\nVous ?tes en service ? Une autre fois alors, je ne voudrais pas avoir de probl?mes avec Amayiro.');
INSERT INTO `npc_questions` VALUES (4356, '', '', '', '', 'Des Ecaflips ? Aucun risque que j\\\'en ai vu, je les refuse dans ma taverne. Enfin, la plupart. Ils passent leur temps ? provoquer les clients et ? faire ?clater des disputes avec leurs jeux.');
INSERT INTO `npc_questions` VALUES (4357, '', '', '', '', 'Des Ecaflips r?cemment ? Oui, j\\\'en ai eu un. Il a pass? la nuit ? boire et ? jouer, au petit matin il avait plus un rond et je crois que la garde l\\\'a embarqu? pour je sais plus quelle raison. ?a peut vous aider ?');
INSERT INTO `npc_questions` VALUES (4358, '', '', '', '', 'Des Ecaflips, hein... oui, j\\\'en ai re?u quelques-uns il y a pas longtemps. Ils avaient l\\\'air louches, d\\\'ailleurs. Je crois que j\\\'ai entendu... par hasard, bien s?r... le nom de Loudac prononc? par l\\\'un d\\\'eux.');
INSERT INTO `npc_questions` VALUES (4359, '', '', '', '', 'Pas vu d\\\'Ecaflips, mais hier j\\\'ai entendu des gardes parler d\\\'une bande d\\\'Ecaflips qui font des probl?mes r?cemment. Si ?a peut aider...');
INSERT INTO `npc_questions` VALUES (4360, '', '', '', '', 'Du nouveau ? Les taverniers savent-ils quelque chose ?');
INSERT INTO `npc_questions` VALUES (4361, '', '', '', '', 'Aha... je crois que je me souviens, oui. Loudac...');
INSERT INTO `npc_questions` VALUES (4362, '', '', '', '', 'Des Ecaflips ? Laisse-moi r?fl?chir... non, pas ces derniers jours.');
INSERT INTO `npc_questions` VALUES (4363, '', '', '', '', 'J\\\'ai entendu parler d\\\'une bande de bandits qui s?vit dans les plaines de Cania, pas loin de la foire. D\\\'apr?s ton enqu?te, il est possible qu\\\'ils soient venus jusqu\\\'ici. \\nJe voudrais que tu ailles enqu?ter l?-bas. Reviens si tu trouves quelque chose. Mais si tu ne trouves vraiment rien, reviens quand m?me.');
INSERT INTO `npc_questions` VALUES (4364, '', '', '', '', 'Si ces bandits viennent jusqu\\\'ici, il est imp?ratif de prendre des mesures contre eux.');
INSERT INTO `npc_questions` VALUES (4365, '', '', '', '', 'Hmm. Tu as trouv? ces bandits et tu as m?me ?t? jusqu\\\'? risquer ta vie en p?n?trant dans leur repaire. J\\\'admire ton courage, mais il faudrait penser ? faire preuve de plus de prudence. Dommage que tu n\\\'aies pu p?n?trer plus loin dans leur repaire. \\nDe mon c?t? j\\\'ai voulu pr?parer une troupe pour te seconder mais le conseil s\\\'y est oppos?. Avec les nouvelles informations que tu viens de m\\\'apporter j\\\'esp?re n?anmoins leur faire entendre raison.');
INSERT INTO `npc_questions` VALUES (4366, '', '', '', '', 'Hmm. Tu as coll? une rouste ? ces bandits et tu as m?me ?t? jusqu\\\'? risquer ta vie en p?n?trant dans leur repaire. J\\\'admire ton courage, mais il faudrait penser ? faire preuve de plus de prudence. Dommage que tu n\\\'aies pu p?n?trer plus loin dans leur repaire. \\nDe mon c?t? j\\\'ai voulu pr?parer une troupe pour te seconder mais le conseil s\\\'y est oppos?. Avec les nouvelles informations que tu viens de m\\\'apporter j\\\'esp?re n?anmoins leur faire entendre raison. \\n \\nVoici quelques potions pour panser tes blessures. Repose-toi un peu et reviens me voir lorsque tu auras r?cup?r? de tes pr?c?dents combats.');
INSERT INTO `npc_questions` VALUES (4367, '', '', '', '', 'Nos convois de marchands vers Astrub sont pris dans des embuscades ces derniers temps. Ta t?che est d\\\'escorter le convoi suivant, de le prot?ger et si possible de r?cup?rer des indices sur ces bandits. Ce sont peut-?tre les m?mes que pr?c?demment.');
INSERT INTO `npc_questions` VALUES (4368, '', '', '', '', 'Tu peux faire des pr?paratifs, il faut t\\\'attendre ? devoir combattre. Le convoi t\\\'attend ? la sortie sud mais je n\\\'ai pas pu affecter d\\\'autres miliciens ? l\\\'escorte car j\\\'ai d? les d?p?cher en urgence un peu partout en ville. Les enclos publics ont ?t? ouvert par des personnes malveillantes durant la nuit et des dragodindes s?ment le bazar dans la cit?, c\\\'est vraiment jouer de malchance. Vite, va voir Gueurle, elle dirige les convois. N\\\'oublie pas de venir me faire ton rapport lorsque le convoi sera arriv? ? destination.');
INSERT INTO `npc_questions` VALUES (4369, '', '', '', '', 'Tu n\\\'as servi ? rien, je me demande bien pourquoi Amayiro nous a fait escorter par une telle nullit?. Pourtant lui et moi nous nous sommes quitt?s en tr?s bons termes et il avait l\\\'air d\\\'avoir appr?ci? notre entrevue. Je ne comprends pas pourquoi il a fait ?a. Quant ? ces bandits, ils vont entendre parler du pays, tu peux me croire. Je n\\\'en resterai pas l?, foi de Sram.');
INSERT INTO `npc_questions` VALUES (4370, '', '', '', '', 'Alors, comment cela s\\\'est-il pass? ?');
INSERT INTO `npc_questions` VALUES (4371, '', '', '', '', 'Aie. Tu n\\\'as pas r?ussi ? prot?ger le convoi, c\\\'est tr?s emb?tant. Les bandits vont se sentir ? l\\\'abri et leur audace va augmenter. Toutefois, nous ne sommes pas encore au pied du mur.');
INSERT INTO `npc_questions` VALUES (4372, '', '', '', '', 'Parfait ! Bravo et merci pour cette protection efficace. Gueurle voudra s?rement me remercier de lui avoir offert une protection aussi efficace la prochaine fois que je la verrai.... Passons, il y a plus urgent pour le moment. Prends ces potions, elle soigneront tes blessures et je crois que tu les as bien m?rit?es.');
INSERT INTO `npc_questions` VALUES (4373, '', '', '', '', 'J\\\'ai fait une r?union avec le conseil et malgr? quelques r?ticences, j\\\'ai r?ussi ? obtenir son aval pour tendre un pi?ge aux bandits. Un bijou d\\\'une grande valeur sera transport? jusqu\\\'? Astrub, mais j\\\'ajouterai quelques miliciens d\\\'?lite aux gardes.');
INSERT INTO `npc_questions` VALUES (4374, '', '', '', '', 'Nous esp?rons que la valeur du bijou attirera le chef des bandits et que nous pourrons le capturer. Nous nous sommes aussi arrang?s pour que la nouvelle se r?pande, afin qu\\\'ils soient au courant. \\nPourrais-tu aller chercher le bijou chez Marge la bijouti?re ? Tu es la personne ? qui je fais le plus confiance pour ?a.');
INSERT INTO `npc_questions` VALUES (4376, '', '', '', '', 'Ah. Je vois que notre proposition vous int?resse. Le march? est simple : le joyau contre 10 000 kamas. Et votre vie. Je vous donnerai un faux joyau que vous donnerez ? votre imb?cile de chef. Alors ?');
INSERT INTO `npc_questions` VALUES (4377, '', '', '', '', 'Bon choix. Voici le faux joyau. Et n\\\'en parlez ? personne, nous savons o? vous trouver.');
INSERT INTO `npc_questions` VALUES (4378, '', '', '', '', 'Vous le regretterez. Faites-moi confiance.');
INSERT INTO `npc_questions` VALUES (4379, '', '', '', '', 'Ne restez pas ici. Retournez voir votre chef.');
INSERT INTO `npc_questions` VALUES (4380, '', '', '', '', 'Alors, as-tu le bijou ?');
INSERT INTO `npc_questions` VALUES (4381, '', '', '', '', 'Un X?lor a tent? de t\\\'acheter le bijou et tu as refus? ? Je savais que je pouvais te faire confiance. Voici 1000 Kamas pour te r?compenser de ton int?grit?. \\nDis-moi quand le convoi pourra partir. Tu feras partie de l\\\'escorte.');
INSERT INTO `npc_questions` VALUES (4382, '', '', '', '', 'Merci. Dis-moi quand le convoi pourra partir, tu feras partie de l\\\'escorte.');
INSERT INTO `npc_questions` VALUES (4383, '', '', '', '', 'Est-ce le moment ?');
INSERT INTO `npc_questions` VALUES (4384, '', '', '', '', 'Ah, Amayiro t\\\'a envoy? chercher le bijou ? C\\\'est ?trange, un X?lor vient juste de m\\\'apporter une lettre et il m\\\'a demand? de la remettre au prochain client. Tiens, je te la donne avec le bijou.');
INSERT INTO `npc_questions` VALUES (4385, '', '', '', '', 'Comment s\\\'est pass? le voyage ?');
INSERT INTO `npc_questions` VALUES (4386, '', '', '', '', 'Pas d\\\'attaque ? Alors je n\\\'ai plus de doute. Quelqu\\\'un de haut plac? ici renseigne les bandits. Nous avons quelqu\\\'un de corrompu dans nos rangs, c\\\'est certain. Il accepte probablement des pots-de-vin pour divulguer des renseignements secrets, et pour faire stopper nos enqu?tes. ?a expliquerait ?galement la r?ticence du conseil ? mettre un terme aux agissements de ces bandits.');
INSERT INTO `npc_questions` VALUES (4387, '', '', '', '', 'Les hautes autorit?s ont eu vent de ton intervention dans le repaire des bandits et des documents que tu y as d?couvert. Je sais bien que tu es une personne honn?te mais tout le monde ne partage pas cet avis, ce qui me contraint ? te retirer l\\\'enqu?te. N?anmoins je vais faire mon possible pour arranger la situation et faire en sorte que tu r?cup?res la place qui t\\\'es due au sein de la milice. \\nEn attendant, tu es de corv?e de r?approvisionnement. Du jambon cuit fera l\\\'affaire, mais pas du premier prix, nos miliciens m?ritent mieux. Ce n\\\'est pas non plus la peine de te ruiner, du deuxi?me prix fera l\\\'affaire. Distribue-le aux miliciens suivants dans un premier temps : Shere Hacanon, Finche Aticus et Trev Pelsantery.');
INSERT INTO `npc_questions` VALUES (4388, '', '', '', '', 'Je sais bien que ravitailler des miliciens n\\\'a rien de glorifiant mais il faut bien que quelqu\\\'un s\\\'en charge.');
INSERT INTO `npc_questions` VALUES (4389, '', '', '', '', 'Quelqu\\\'un semble vouloir te faire porter le chapeau. Je vais mettre ce rapport en lieu s?r. Si les choses tournaient mal pour toi, Ture Inge pourrait s\\\'en servir en d?montrant qu\\\'il a ?t? falsifi?. Quant ? toi, repose-toi un peu le temps que je r?fl?chisse ? comment r?gler cette situation.');
INSERT INTO `npc_questions` VALUES (4390, '', '', '', '', 'J\\\'ai bien r?fl?chi et j\\\'ai pris une importante d?cision. Je vais te couvrir afin que tu puisses continuer ton enqu?te et d?couvrir qui a trahi Bonta. Tes agissements peuvent facilement ?tre surveill?s en ville mais plus difficilement en dehors. Tu vas te rendre au temple Sram et interroger Rigal Main Crochue. Bien que je n\\\'appr?cie gu?re le personnage, il pourrait poss?der des informations utiles. Esp?rons que tu ne te d?placeras pas l?-bas pour rien.');
INSERT INTO `npc_questions` VALUES (4391, '', '', '', '', 'Approchez, approchez ! Ne craignez-rien, ici, les ombres ne vous recouvriront que si je le souhaite. Confiez-vous ? moi, r?v?lez le but de votre visite. Rigal connait de nombreux secrets, et ceux qu\\\'il ne sait pas, il les apprendra bient?t. Ouvrez-moi votre ?me.');
INSERT INTO `npc_questions` VALUES (4392, '', '', '', '', 'Hmmm... Un notable de Bonta dont le nom commence par X... \\nOui, j\\\'ai peut-?tre quelques informations... mais je vais devoir vous mettre ? contribution. \\nLes r?serves de poison du temple s\\\'amenuisent et j\\\'ai ou?e dire que celles de Br?kmar ?taient pleines ? craquer. Vous allez donc me rapporter 10 Fioles de poison br?kmarien et puisque vous serez sur place, profitez-en pour emprunter le registre des clients de l\\\'atelier des alchimistes. \\nVous n\\\'aurez vos informations qu\\\'en ?change de ces objets, ou d\\\'un milliard de Kamas. \\nNe faites pas cette t?te, je suis persuad? que vous connaissez quelqu\\\'un dans Br?kmar qui pourra vous renseigner.');
INSERT INTO `npc_questions` VALUES (4393, '', '', '', '', 'Avez-vous le poison ? Mes trois derniers assassinats ont s?rieusement entam? mes r?serves.');
INSERT INTO `npc_questions` VALUES (4394, '', '', '', '', 'Voyons...X... Xiron, Xylophone, X?na la cordonni?re, Xav... Tous ces noms ne me disent rien. \\nX?nondunepipe, X-or... ah, voil?, Xarthan ! C\\\'est un notable de Bonta et je pense que c\\\'est votre homme. Je ne vois aucun autre Bontarien sur ce registre.');
INSERT INTO `npc_questions` VALUES (4395, '', '', '', '', 'Rigal a-t-il ?t? utile ?');
INSERT INTO `npc_questions` VALUES (4396, '', '', '', '', 'Excellent travail, je savais que je pouvais te faire confiance. Ton absence n\\\'a ? priori pas ?t? remarqu?e mais le tra?tre doit ?tre sur ses gardes, il va donc falloir agir prudemment. Je compte sur toi pour mener cette enqu?te ? son terme, apr?s tout il en va de ton honneur.');
INSERT INTO `npc_questions` VALUES (4397, '', '', '', '', 'C\\\'est le moment de prendre le poisson dans nos filets. Les notables vont bient?t se r?unir et tu vas en profiter pour te rendre dans la maison de Xarthan. Trouve des documents le compromettant et agit en cons?quence. Je ne veux pas qu\\\'il sache que tu t\\\'es introduit chez lui, par cons?quent prends un bricoleur avec toi pour forcer discr?tement la serrure. \\nAvant que tu ne partes fouiller tout Bonta, sache que la maison de Xarthan se trouve dans le quartier des boulangers. O? pr?cis?ment ? Je l\\\'ignore, il n\\\'a jamais pris la peine de m\\\'inviter. \\nQue Silvosse veille sur toi.');
INSERT INTO `npc_questions` VALUES (4398, '', '', '', '', 'Aaah ! Qui ?tes-vous ? Non, j\\\'ai ?t? pris !! \\nJ\\\'avoue... je suis accroc au jus de Ouassingue. Si je n\\\'ai pas ma gorg?e tous les jours, je n\\\'arrive pas ? me concentrer. Vous n\\\'allez pas me d?noncer, hein ?');
INSERT INTO `npc_questions` VALUES (4399, '', '', '', '', 'Le marchand qui me le vend ? Il vient juste de se sauver. De toute fa?on je ne pense pas qu\\\'il soit tr?s int?ressant ? attraper... le jus de Ouassingue est interdit dans la cit? ? cause de l\\\'odeur, mais il n\\\'est pas dangereux.');
INSERT INTO `npc_questions` VALUES (4400, '', '', '', '', 'Alors, la p?che a ?t? bonne ?');
INSERT INTO `npc_questions` VALUES (4401, '', '', '', '', '... Magnifique. Bon, il semblerait que ce ne soit pas lui mais je vais le garder ? l\\\'oeil pour en ?tre s?r.');
INSERT INTO `npc_questions` VALUES (4402, '', '', '', '', 'Mot de passe ?');
INSERT INTO `npc_questions` VALUES (4403, '', '', '', '', 'Je plaisante. Dis donc, t\\\'aurais pas grossi depuis notre derni?re rencontre ?');
INSERT INTO `npc_questions` VALUES (4404, '', '', '', '', 'Dommage que tu ne sois pas pass? plus t?t, j\\\'aurai pu te pr?venir avant que tu retournes ? Bonta. \\nLes Br?kmariens manigancent quelque chose contre notre cit? mais j\\\'ignore quoi exactement. Par contre je sais que des voleurs li?s ? cette affaire viennent de se joindre ? Oto Mustam. Leur repaire se trouve ? proximit? de l\\\'atelier des bricoleurs et Ze Krow tra?ne souvent dans les parages. Ils ont l\\\'air organis? alors si tu souhaites leur rendre une petite visite, demande ? d\\\'autres Bontariens de t\\\'accompagner.');
INSERT INTO `npc_questions` VALUES (4405, '', '', '', '', 'Ho ho, un Bontarien ici dans Br?kmar ? Je suppose que l\\\'information circule m?me dans les rangs ennemis. Normalement je devrais appeler la garde pour qu\\\'elle t\\\'?corche, mais peut-?tre que tu pourrais m\\\'enrichir encore davantage ?');
INSERT INTO `npc_questions` VALUES (4406, '', '', '', '', 'Aaaah, l? tu m\\\'int?resses. Alors voil? le scoop : un des petits prot?g?s d\\\'Oto Mustam - le chef de la milice - a trouv? quelqu\\\'un ? corrompre chez vous. Non, ce n\\\'est pas Xartruc machin chose. On m\\\'a demand? de faire un joli bijou qui saura amadouer votre gars, et il y aura un rendez-vous prochainement ? la Tour de Bonta pour sceller cet accord. Allez, file maintenant !');
INSERT INTO `npc_questions` VALUES (4407, '', '', '', '', 'Xarthan est sans doute innocent mais il faut en ?tre s?r. Tu vas retourner ? Br?kmar et interroger notre taupe. Mon intuition me dit que les Br?kmariens ne sont pas ?trangers ? nos soucis. Je vais profiter de ton absence pour organiser une petite discussion entre Xarthan et Ture Inge, l\\\'avis d\\\'un expert est toujours important.');
INSERT INTO `npc_questions` VALUES (4408, '', '', '', '', 'As-tu trouv? quelque chose ? Br?kmar ?');
INSERT INTO `npc_questions` VALUES (4409, '', '', '', '', 'Excellent, parfait ! C\\\'est exactement ce dont nous avions besoin : un rendez-vous ? la Tour de Bonta, nous allons pouvoir le pincer. Hmm, d?cid?ment il faudra augmenter la garde dans ce p?rim?tre...');
INSERT INTO `npc_questions` VALUES (4410, '', '', '', '', 'Tu vas poster des miliciens ? chaque sortie de la Tour des Ordres, je ne veux pas que ces vauriens nous ?chappent. Il faut imp?rativement les prendre sur le fait, je compte sur toi. Je vais envoyer un de mes espions pour te suivre, au cas o? ?a tournerait mal.\\nNe prends pas n\\\'importe quel milicien, je veux que tu changes de poste les suivants : Sen Eiser, Trev Pelsantery, Galde Avout, Ruth Banke.');
INSERT INTO `npc_questions` VALUES (4411, '', '', '', '', 'Ah ! Euh, bonjour. Comment ? Ce que je fais ici ? Eh bien, je me balade dans la tour... j\\\'ai le droit, non ?');
INSERT INTO `npc_questions` VALUES (4412, '', '', '', '', 'Je... c\\\'est... elle est confidentielle. Oh, et puis zut, je suppose que vous avez ?t? mis au courant. Peu importe, je vais me d?barrasser de vous ! Personne ne m\\\'emp?chera d\\\'avoir ce bijou... PERSONNE !!!');
INSERT INTO `npc_questions` VALUES (4413, '', '', '', '', 'Formidable. Nous avons enfin captur? ce vaurien et son correspondant Br?kmarien. Ton aide et ta d?termination ont ?t? tr?s pr?cieuses. J\\\'ai demand? au boulanger de me fournir ses meilleurs pains pour f?ter ?a, prends-en quelques-uns ! Quant aux deux prisonniers, ils vont subir un interrogatoire et je vais faire en sorte que les richesses de Xephir?s soit redistribu?es ? la population.');
INSERT INTO `npc_questions` VALUES (4414, '', '', '', '', 'Je ne pensais pas qu\\\'il vous battrait tous les deux. Heureusement, les gardes que tu avais post? en bas de la tour les ont cueillis tandis qu\\\'ils prenaient la fuite. \\nTon aide et ta d?termination ont ?t? tr?s pr?cieuses, Bonta te doit une fi?re chandelle d\\\'avoir d?masqu? ce tra?tre. Lui et son complice vont subir un interrogatoire et je vais faire en sorte que les richesses de Xephir?s soit redistribu?es ? la population.');
INSERT INTO `npc_questions` VALUES (4415, '', '', '', '', 'Je me rends, je me rends ! Mon complice ? Il a probablement profit? de notre combat pour filer.');
INSERT INTO `npc_questions` VALUES (4416, '', '', '', '', 'Vraiment ? Houlala j\\\'ai peur, regarde comme je tremble. Tu vas vraiment me faire mal si je refuse de coop?rer ?');
INSERT INTO `npc_questions` VALUES (4417, '', '', '', '', 'H?te-toi. Il ne faudrait pas rater leur rendez-vous.');
INSERT INTO `npc_questions` VALUES (4418, '', '', '', '', 'La d?couverte de ce tra?tre a laiss? nos sup?rieurs tr?s soup?onneux. Je pr?f?re ne pas te donner de t?che pour l\\\'instant.');
INSERT INTO `npc_questions` VALUES (4420, '', '', '', '', 'Je peux t\\\'aider ?');
INSERT INTO `npc_questions` VALUES (4421, '', '', '', '', 'Il y a un combat qui se d?roule dans les plaines, sur la route entre Bonta et Br?kmar. Je veux que tu y participes et que tu aides nos guerriers ? vaincre !');
INSERT INTO `npc_questions` VALUES (4422, '', '', '', '', 'Eh bien ?');
INSERT INTO `npc_questions` VALUES (4423, '', '', '', '', 'Comment ? Nous ?tions sup?rieurs en nombre et en puissance, et tu as trouv? le moyen de nous faire perdre ? Incapable ! \\nEnfin, l\\\'important c\\\'est ce que nous avons constat? : les miliciens de Bonta sont sous-?quip?s. C\\\'est le moment de frapper ! \\nMais... avant, je voudrais avoir l\\\'avis de Kaffra Kyper. Si tu ne le connais pas encore, il passe la majeure partie de son temps ? la Tour des Ordres de Br?kmar.');
INSERT INTO `npc_questions` VALUES (4424, '', '', '', '', 'Ah ! Une large victoire. Les miliciens de Bonta sont sous-?quip?s. C\\\'est le moment de frapper ! \\nMais... avant, je voudrais avoir l\\\'avis de Kaffra Kyper. Si tu ne le connais pas encore, il passe la majeure partie de son temps ? la Tour des Ordres de Br?kmar.');
INSERT INTO `npc_questions` VALUES (4425, '', '', '', '', 'Hmm. Oto veut donc lancer une attaque sur Bonta ? D\\\'apr?s nos derniers renseignements, ce n\\\'est pas une mauvaise id?e mais il est imp?ratif de faire de l\\\'espionnage intensif auparavant. Non pas que j\\\'h?site ? me lancer dans une sanglante h?catombe, mais autant le faire proprement !');
INSERT INTO `npc_questions` VALUES (4426, '', '', '', '', 'Des nouvelles de Kaffra ?');
INSERT INTO `npc_questions` VALUES (4427, '', '', '', '', 'Encore de l\\\'espionnage ? Que Kaffra h?site ? attaquer Bonta m\\\'aurait ?tonn? si je ne voyais pas o? il veut en venir. Il craint sans doute que Jerhyn Gholein ait volontairement envoy? des miliciens sous-?quip?s ? notre encontre afin de nous inciter ? foncer t?te baiss?e. Malheureusement pour lui nous sommes plus malins qu\\\'il ne l\\\'imagine. Il nous faut imp?rativement trouver les faiblesses de la milice bontarienne avant de lancer l\\\'assaut.');
INSERT INTO `npc_questions` VALUES (4428, '', '', '', '', 'Comme par hasard au moment o? j\\\'ai besoin de ses espions Ledrob Terces?c n\\\'en a aucun sous la main, je vais donc devoir me contenter de toi. C\\\'est l\\\'occasion de faire tes preuves en mati?re d\\\'infiltration et de cambriolage. Ta mission est tr?s simple : t\\\'introduire dans le b?timent de la milice de Bonta, mettre la main sur un ?quipement standard de milicien, le faire expertiser par Mulic Bere notre forgeron et m\\\'apporter son rapport. Tu penses ?tre ? la hauteur o? dois-je t\\\'envoyer ?plucher des patates jusqu\\\'? la fin de tes jours ?');
INSERT INTO `npc_questions` VALUES (4429, '', '', '', '', 'C\\\'est toi que j\\\'ai charg? d\\\'infiltrer l\\\'entrep?t de la milice de Bonta pour voler de l\\\'?quipement ? Cette histoire, ?a en est o? ? Tu as r?ussi ? t\\\'introduire l?-bas ? Et le rapport d\\\'expertise de Mulic Bere alors ?');
INSERT INTO `npc_questions` VALUES (4430, '', '', '', '', 'Je vais regarder ?a de plus pr?s, inutile de rester plant? l?. Va voir ? Sufokia si j\\\'y suis.');
INSERT INTO `npc_questions` VALUES (4431, '', '', '', '', 'D\\\'apr?s le rapport de Mulic Bere l\\\'?quipement de la milice bontarienne est indigne d\\\'un forgeron. Il ne pense pas que Kosuke Ichazum, le forgeur de lames de Bonta, soit responsable d\\\'un travail aussi m?diocre mais il faudrait s\\\'assurer qu\\\'il ne s\\\'en m?le pas. \\nDans un premier temps, procure-toi 5 Marteaux Martel pour les ?changer avec les outils du forgeron et reviens me voir.');
INSERT INTO `npc_questions` VALUES (4432, '', '', '', '', 'Bien, comme je te l\\\'ai dit, il faut commencer par s\\\'assurer que Kosuke Ichazum ne se m?le pas de l\\\'approvisionnement de la milice de Bonta. \\nQuant au forgeron qui s\\\'en occupe, il est tellement mauvais qu\\\'il nous faudrait des ann?es pour r?ussir ? affaiblir la milice pour obtenir le m?me r?sultat que lui avec son ?quipement. Par cons?quent, il faut imp?rativement qu\\\'il continue ? fournir nos ennemis et je compte sur toi pour le motiver dans ce sens, en lui graissant la patte ou autre. ?vite cependant de le violenter ou de le menacer, il ne doit pas se douter un seul instant que tu travailles pour Br?kmar. \\nQuand tu l\\\'auras trouv?, n\\\'oublie pas d\\\'?changer ses outils par les marteaux martel. \\n');
INSERT INTO `npc_questions` VALUES (4433, '', '', '', '', 'Coucou');
INSERT INTO `npc_questions` VALUES (4440, '', '', '', '', 'Shhh ! Tu es l? pour nous apporter du poison ?');
INSERT INTO `npc_questions` VALUES (4441, '', '', '', '', 'Mes espions ? Bonta ont rep?r? quelqu\\\'un de, disons, d\\\'assassinable. Le probl?me, c\\\'est que ces t?tes d\\\'ahuris n\\\'avaient pas pr?vu l\\\'assassinat dans leur mission et n\\\'ont donc pas leur poison. Il faut leur en amener, et en plus le poison qu\\\'ils utilisent ne se trouve que sur les Bworks Mages. \\nAm?ne ce poison au chef des espions, il est vers le coin sud-ouest de Bonta.');
INSERT INTO `npc_questions` VALUES (4442, '', '', '', '', 'Ah, parfait. Il faudra que je m\\\'arrange pour ne pas perdre des espions, cette fois. Avant-hier ils ont confondu le bocal de poison avec celui de notre onguent de furtivit?, et... bref, nous pouvons difficilement nous cacher alors trouve-nous une planque car ?a grouille de Bontariens ici. Essaye d\\\'en trouver une entre ici et la biblioth?que, histoire de ne pas avoir tout Bonta ? traverser. \\nTant que tu y es, choisis-en une d?j? habit?e et neutralise ses r?sidents sans les tuer, nous avons besoin de cobayes vivants pour tester le poison. Pr?voies 10 Ficelles en Lin par r?sident pour les ligoter.');
INSERT INTO `npc_questions` VALUES (4443, '', '', '', '', 'Am?ne directement le poison au chef des espions, ? Bonta. Il est planqu? dans un coin au sud-ouest de la cit');
INSERT INTO `npc_questions` VALUES (4445, '', '', '', '', 'Que fais-tu encore ici ? File avant qu\\\'on ne nous trouve !');
INSERT INTO `npc_questions` VALUES (4446, '', '', '', '', 'Hum. Comment dire. Mes espions d\\\'?lite viennent de se faire rep?rer et bouffer par des Crocs Glands reconvertis en chiens de garde par la milice de Bonta. \\nIl faudrait que quelqu\\\'un s\\\'occupe de cette cible... tu vois de qui je parle, j\\\'imagine ?');
INSERT INTO `npc_questions` VALUES (4447, '', '', '', '', 'Puisque tu as l\\\'air de tomber des nues, voici ta cible : c\\\'est un mercenaire engag? par Bonta pour faire des recherches tactiques. Il se trouve dans la biblioth?que de Bonta. Hop, au travail.');
INSERT INTO `npc_questions` VALUES (4448, '', '', '', '', 'Le tacticien est dans la biblioth?que de Bonta. Fais attention aux Crocs Glands.');
INSERT INTO `npc_questions` VALUES (4449, '', '', '', '', 'Bonjour. Ne me d?rangez pas, s\\\'il vous plait, je consulte des livres.');
INSERT INTO `npc_questions` VALUES (4450, '', '', '', '', 'Ah ! Mais vous ?tes un Br?kmarien ! Que me voulez-vous ?');
INSERT INTO `npc_questions` VALUES (4451, '', '', '', '', 'Non, non ! Je vous en prie, ne me tuez pas ! Je ne suis pas un Bontarien, je travaille ici contre r?mun?ration, c\\\'est tout !');
INSERT INTO `npc_questions` VALUES (4452, '', '', '', '', 'Je pars sur le champ ! J\\\'?viterai de m\\\'immiscer dans ce genre de conflit ? l\\\'avenir...');
INSERT INTO `npc_questions` VALUES (4453, '', '', '', '', '50 000 kamas ? Pour cette somme, je suis pr?t ? venir parmi vous ! Faites-moi signe quand vous pourrez m\\\'escorter jusque l?-bas.');
INSERT INTO `npc_questions` VALUES (4454, '', '', '', '', '50 000 kamas ? Pour cette somme, je serais pr?t ? venir parmi vous ! Mais vous ne semblez pas avoir assez de kamas...');
INSERT INTO `npc_questions` VALUES (4455, '', '', '', '', 'Aaaargh !');
INSERT INTO `npc_questions` VALUES (4456, '', '', '', '', '(Vu son ?tat, il ne passera pas la semaine. Ni le jour. Ni l\\\'heure.)');
INSERT INTO `npc_questions` VALUES (4457, '', '', '', '', 'Merci ! Je fais mes bagages tout de suite !');
INSERT INTO `npc_questions` VALUES (4458, '', '', '', '', 'Pouvons-nous partir ? Si les choses tournent mal, je m\\\'arrangerai pour revenir ici. Par contre, il serait plus judicieux qu\\\'on ne nous voit pas sortir ensemble de la biblioth?que. Sortez le premier et attendez-moi dehors, je vous rejoins juste apr?s.');
INSERT INTO `npc_questions` VALUES (4459, '', '', '', '', 'Oto Mustam m\\\'a renvoy? ici. Je dois m\\\'arranger pour que la milice de Bonta soit la moins performante possible.');
INSERT INTO `npc_questions` VALUES (4460, '', '', '', '', 'Le tacticien est-il mort ?');
INSERT INTO `npc_questions` VALUES (4461, '', '', '', '', 'Bien. Un alli? de Bonta en moins, c\\\'est un atout en plus pour nous. \\nTu n\\\'as rien ? faire ? Tant mieux, tu vas donc retourner ? Bonta et trouver le secret du domptage des Crocs Glands. Si tu ne sais pas o? chercher, pourquoi ne pas commencer par la biblioth?que ?');
INSERT INTO `npc_questions` VALUES (4462, '', '', '', '', 'Tu as achet? son all?geance pour nous ? Tr?s bonne id?e, tr?s br?kmarien. Je vais m\\\'arranger pour le renvoyer ? Bonta pour qu\\\'il puisse saboter leur milice !\\n50 000 kamas ? Voil? un remboursement, avec un bonus pour cette trouvaille.\\nTu n\\\'as rien ? faire ? Tant mieux, tu vas donc retourner ? Bonta et trouver le secret du domptage des Crocs Glands. Si tu ne sais pas o? chercher, pourquoi ne pas commencer par la biblioth?que ?');
INSERT INTO `npc_questions` VALUES (4463, '', '', '', '', 'Un autre minable de Br?kmar ? Veux-tu me d?fier, toi aussi ?');
INSERT INTO `npc_questions` VALUES (4464, '', '', '', '', 'J\\\'ai re?u un rapport inqui?tant. Plusieurs de nos guerriers ont ?t? vaincus et laiss?s pour morts sur la route menant ? Astrub. Le coupable arpenterait encore la route en ce moment. \\nJe veux que tu ailles enqu?ter et que tu le trouves.');
INSERT INTO `npc_questions` VALUES (4465, '', '', '', '', 'Il est sur la route menant ? Astrub.');
INSERT INTO `npc_questions` VALUES (4466, '', '', '', '', 'Hahaha, tu plaisantes j\\\'esp?re. Non ? Ecoute, je ne sais pas ce que tu as derri?re la t?te mais je ne marche pas dans tes combines.');
INSERT INTO `npc_questions` VALUES (4467, '', '', '', '', 'Hein ? Un simple milicien de Bonta, mais avec un ?quipement sp?cial ? \\nHmm, c\\\'est inqui?tant. Bonta aurait-elle trouv? un moyen pour mieux ?quiper ses soldats ? \\nQue tu n\\\'aies pas r?ussi ? le vaincre va encore nous faire passer pour des guignols aux yeux de nos ennemis, tu me d??ois vraiment sur ce coup. J\\\'esp?re au moins dans ton int?r?t que tu n\\\'as pas pris la fuite sinon ce serait encore pire. \\nAu sujet du croc gland, est-il efficace au moins ? Puisqu\\\'on en parle, j\\\'ai besoin de le r?cup?rer. Bout d\\\'chair le boucher m\\\'en propose un tr?s bon prix.');
INSERT INTO `npc_questions` VALUES (4468, '', '', '', '', 'Hein ? Un simple milicien de Bonta mais avec un ?quipement sp?cial ? \\nHmm, c\\\'est inqui?tant. Bonta aurait-elle trouv? un moyen pour mieux ?quiper ses soldats ? \\nOh, je vois que tu l\\\'as vaincu. Pas mal, ?a en fera toujours un de moins et ?a devrait jouer sur le moral de nos ennemis. Tu as montr? qu\\\'il ne fallait pas nous prendre pour des guignols, tu commences ? me plaire. \\nAu sujet du croc gland, est-il efficace au moins ? Puisqu\\\'on en parle, j\\\'ai besoin de le r?cup?rer. Bout d\\\'chair le boucher m\\\'en propose un tr?s bon prix.');
INSERT INTO `npc_questions` VALUES (4469, '', '', '', '', 'D?sol?, je ne prends pas de commande pour le moment.');
INSERT INTO `npc_questions` VALUES (4470, '', '', '', '', 'Hein ? C\\\'est bizarre que vous me demandiez ?a. Un Bontarien est pass? il y a quelque temps pour me demander de travailler pour lui... \\nNon, je ne travaille pas pour Bonta mais j\\\'ai un ami pour qui c\\\'est d?sormais le cas.');
INSERT INTO `npc_questions` VALUES (4471, '', '', '', '', 'Au fond d\\\'une grotte au sud-ouest, dans le territoire Porcos. Je vous pr?viens, c\\\'est un particulier et il a une... l?g?re... tendance ? la parano?a. Je ne sais pas s\\\'il acceptera de vous parler. \\nMais au fait, qui ?tes-vous ? Et pourquoi me demandez-vous cela ?');
INSERT INTO `npc_questions` VALUES (4472, '', '', '', '', 'Les forgerons de Bonta ne sont pas assez dou?s pour faire ce genre d\\\'?quipement. Cela signifie que Bonta a engag? un forgeron pour lui faire des armes. \\nIl faut trouver ce forgeron et le convaincre de travailler pour nous.');
INSERT INTO `npc_questions` VALUES (4473, '', '', '', '', 'Commence par regarder dans les ateliers de forgerons et de mineurs. Pas ceux de Bonta, ?videmment... ni ceux d\\\'ici.');
INSERT INTO `npc_questions` VALUES (4474, '', '', '', '', 'As-tu trouv? ce forgeron ?');
INSERT INTO `npc_questions` VALUES (4475, '', '', '', '', 'Ah ! Dans une grotte du territoire Porcos. \\nUn parano?aque ? Ca ne va pas ?tre facile de n?gocier avec lui, surtout s\\\'il apprend qui nous sommes. Il faut quand m?me essayer et au pire il y a toujours la solution de secours.');
INSERT INTO `npc_questions` VALUES (4476, '', '', '', '', 'Qui ?tes-vous ? Qu\\\'est-ce que vous voulez ? Ne m\\\'approchez pas !');
INSERT INTO `npc_questions` VALUES (4477, '', '', '', '', 'Br?kmar ? Vous venez de... BRAKMAR ?? \\n(Il empoigne une arme) \\nDehors ! Je sais que vous voulez m\\\'amadouer pour mieux me planter une dague dans le dos ensuite ! Dehors !');
INSERT INTO `npc_questions` VALUES (4478, '', '', '', '', 'Nous ne pouvons pas le laisser aider Bonta. Tu dois trouver ce forgeron dans le territoire Porcos et le convaincre de travailler pour nous... par n\\\'importe quel moyen.');
INSERT INTO `npc_questions` VALUES (4479, '', '', '', '', 'D?gagez de ma grotte, ou je vous d?bo?te le cr?ne ? coups de marteau ! Assassin !');
INSERT INTO `npc_questions` VALUES (4480, '', '', '', '', 'Notre nouvel ami Xephir?s m\\\'a fait parvenir un courrier int?ressant. Un convoi d\\\'armes destin?es aux officiers de Bonta est en ce moment m?me en route vers la cit?. Il nous faut l\\\'intercepter ? tout prix et voler la cargaison. Comme mes brigands sont d?j? occup?s ? piller la maison des Baine pour leur voler leur bois, tu vas recruter d\\\'autres personnes, Br?kmariens ou non, pour attaquer le convoi. D\\\'apr?s la lettre de Xephir?s, ce convoi est sous bonne garde, alors ne l?sine pas sur les moyens. \\nApr?s avoir vol? le butin, am?ne-le directement ? Pi?tinor, ? l\\\'?tage sup?rieur.');
INSERT INTO `npc_questions` VALUES (4481, '', '', '', '', 'D\\\'apr?s la lettre de Xephir?s, le convoi passera par le chemin ? l\\\'or?e de la for?t des Abraknydes pour rejoindre le village des brigandins. Intercepte-le avant qu\\\'il n\\\'arrive au village.');
INSERT INTO `npc_questions` VALUES (4482, '', '', '', '', 'Encore vous ! Vous ?tes venu m\\\'assassiner, c\\\'est s?r ! \\nMais je vais vous montrer que ce croc gland battu a encore de bonnes dents !');
INSERT INTO `npc_questions` VALUES (4483, '', '', '', '', 'Tu dois intercepter le convoi d\\\'armes avant qu\\\'il ne parvienne au village des Brigandins, alors que fais-tu ici ? \\nSi tu viens me voir parce que tu as le butin, je t\\\'ai d?j? dit de l\\\'apporter ? Pi?tinor, ? l\\\'?tage sup?rieur.');
INSERT INTO `npc_questions` VALUES (4484, '', '', '', '', 'J\\\'ai une nouvelle mission pour toi. D\\\'apr?s un r?cent courrier de Xephir?s, d?cid?ment nous avons bien fait de le corrompre, le navire bontarien La Descemer aurait ses soutes pleines ? craquer d\\\'objets magiques. Il fait actuellement route vers le Port de Madrestam pour ?tre d?charg? et tu dois d?rober son contenu avant qu\\\'il ne se retrouve sous bonne escorte. Commence par interroger le capitaine Lily pour savoir si le navire est d?j? arriv?. Autant te pr?venir que si tu ?choues tu subiras le supplice de la tofoune.');
INSERT INTO `npc_questions` VALUES (4485, '', '', '', '', 'Mes espions viennent de m\\\'apprendre - avec un retard consid?rable, comme d\\\'habitude - que Xephir?s s\\\'est fait rep?rer et enfermer. En plus de ?a, une de nos patrouilles a ?t? d?cim?e au Cimeti?re des Tortur?s. Tout porte donc ? croire qu\\\'ils ?taient au courant pour Xephir?s et qu\\\'ils se sont jou?s de nous. Heureusement que nous avons tu? leur forgeron et vol? les armes de leurs officiers sans quoi ils seraient mieux ?quip?s que nous, mais du coup nous revoil? ? ?galit?. Il nous faut reprendre l\\\'avantage co?te que co?te.');
INSERT INTO `npc_questions` VALUES (4486, '', '', '', '', 'J\\\'ignorais que le b?timent de la milice de Br?kmar ?tait mitoyen avec le port de Madrestam. Que fais-tu ici ?');
INSERT INTO `npc_questions` VALUES (4487, '', '', '', '', 'D\\\'un autre c?t? j\\\'aime bien rendre service alors ?coute : pour fabriquer de la p?te ? Tra Khben il te faut concasser ensemble plusieurs ressources. Tu as besoin de 15 Groins du Sanglier, 5 Pots de Gloutovore et 1 Plume de Serpiplume. Si on te demande qui t\\\'a donn? le tuyau, tu fais comme si tu ne me connaissais pas.');
INSERT INTO `npc_questions` VALUES (4488, '', '', '', '', 'D?sol? mais je ne donne pas ce genre d\\\'information comme ?a.');
INSERT INTO `npc_questions` VALUES (4489, '', '', '', '', 'Je ne l\\\'ai pas vu r?cemment mais c\\\'est un homme tr?s occup?, enfin c\\\'est ce qui me semble. D?sol? de pas pouvoir t\\\'aider plus.');
INSERT INTO `npc_questions` VALUES (4491, '', '', '', '', 'Les Br?kmariens essayent de prendre le contr?le de la Baie de Cania et du Territoire des Dopeuls afin de bloquer l\\\'acc?s au port et faire main basse sur le trafic maritime depuis cet endroit. J\\\'ai d?j? envoy? une patrouille sur place et j\\\'aimerai que tu lui pr?tes main-forte. Lorsque la bataille sera termin?e, passe faire un premier rapport ? Jerhyn Gholein puis reviens ici.');
INSERT INTO `npc_questions` VALUES (4492, '', '', '', '', 'D?p?che-toi avant que la bataille ne soit termin?e !');
INSERT INTO `npc_questions` VALUES (4493, '', '', '', '', 'Tu as r?ussi ? inverser le cours de la bataille, mais il est ?vident que nos soldats ne font actuellement pas le poids contre ceux de Br?kmar. Selon toi leur ?quipement serait de bien meilleure qualit? ? C\\\'est tr?s pr?occupant.');
INSERT INTO `npc_questions` VALUES (4494, '', '', '', '', 'A?e. Je crains que cette d?faite n\\\'incite les Br?kmariens ? passer ? l\\\'offensive. Il faut imp?rativement trouver une solution. Tu n\\\'as pas ? t\\\'accabler de reproches, l\\\'?quipement de nos ennemis a fait la diff?rence.');
INSERT INTO `npc_questions` VALUES (4495, '', '', '', '', 'Jerhyn Gholein est venu me voir, il ?tait hors de lui. Nous devons imp?rativement r?soudre le probl?me d\\\'?quipement de nos miliciens. Tu vas trouver le forgeron qui fabrique cet ?quipement et le mettre ? l\\\'?preuve. Nous devons savoir qui est responsable d\\\'une aussi mauvaise qualit?. Commence par te renseigner aupr?s de Kosuke Ichazum, ?a me para?t ?trange qu\\\'il fasse un aussi mauvais travail. \\nPour la mise ? l\\\'?preuve, demande-lui de te fabriquer une arme avec les ressources suivantes : 10 Bois d\\\'Erable,  2 Bois de Fr?ne et 1 Pyrute.');
INSERT INTO `npc_questions` VALUES (4496, '', '', '', '', 'As-tu trouv? le fournisseur de notre ?quipement et mis son forgeron ? l\\\'?preuve ?');
INSERT INTO `npc_questions` VALUES (4497, '', '', '', '', 'Pourquoi ne suis-je pas ?tonn? ? La qualit? de cette arme laisse vraiment ? d?sirer. Ainsi nous nous retrouvons avec un forgeron incomp?tent et un intendant qui refuse de le croire. Il va falloir trouver une autre solution ? notre probl?me et j\\\'ai d?j? une petite id?e de ce que nous allons faire.');
INSERT INTO `npc_questions` VALUES (4498, '', '', '', '', 'Hmm, Bonta a des soucis et vous avez besoin d\\\'un bon forgeron ? \\nJe ne peux pas m\\\'en charger, mais peut-?tre que... \\nNon, laissez tomber.');
INSERT INTO `npc_questions` VALUES (4499, '', '', '', '', 'On vous a parl? de lui ? Ecoutez, je n\\\'ai aucune envie d\\\'?tre m?l? ? vos histoires ni d\\\'impliquer un ami l?-dedans. Je sais que Bonta veut prot?ger le monde de l\\\'influence n?faste de Br?kmar, mais je ne suis pas convaincu pour autant qu\\\'il faille vous aider.');
INSERT INTO `npc_questions` VALUES (4500, '', '', '', '', 'March? conclu. \\nAlors donc, j\\\'ai un ami qui pourrait s\\\'en charger. Mais c\\\'est un original et il a une l?g?re tendance ? la parano?a. Enfin, un peu plus que l?g?re, m?me. \\nIl s\\\'est cach? dans une grotte de la clairi?re de Brouce Boulgoure mais je ne peux plus lui rendre visite depuis qu\\\'un ?nergum?ne du nom de Bellus Sel en a bloqu? l\\\'acc?s. Remarquez, ?a arrange les affaires de Nara qui d?teste ?tre d?rang');
INSERT INTO `npc_questions` VALUES (4501, '', '', '', '', 'Je vous ai dit que je pr?f?rais ne pas me m?ler de ces histoires.');
INSERT INTO `npc_questions` VALUES (4502, '', '', '', '', 'Ce ne sont pas les Kamas qui nous manquent, mais ce Latem Sa est vraiment incomp?tent et comme Kosuke Ichazum est sp?cialis? dans les lames, il ne peut fournir une panoplie standard pour nos miliciens. Je souhaite que tu partes ? la recherche d\\\'un forgeron mercenaire qui pourrait travailler pour nous. Commence par demander ? Kosuke Ichazum s\\\'il conna?t quelqu\\\'un susceptible de nous aider.');
INSERT INTO `npc_questions` VALUES (4503, '', '', '', '', 'O? en sont tes recherches ? As-tu trouv? un forgeron susceptible de nous fournir un meilleur ?quipement ?');
INSERT INTO `npc_questions` VALUES (4504, '', '', '', '', 'Tu penses qu\\\'une lettre de ma part pourrait convaincre ce Norb de nous aider ? Pas de probl?me, je te fais une lettre tout de suite. \\nTiens, la voici.');
INSERT INTO `npc_questions` VALUES (4505, '', '', '', '', 'Apparemment vous avez besoin d\\\'un s?rieux coup de main. Je ne peux pas vous aider, mais j\\\'ai peut-?tre une solution pour vous. \\nAlors donc, j\\\'ai un ami qui pourrait s\\\'en charger. Mais c\\\'est un original et il a une l?g?re tendance ? la parano?a. Enfin, un peu plus que l?g?re, m?me. \\nIl s\\\'est cach? dans une grotte de la clairi?re de Brouce Boulgoure mais je ne peux plus lui rendre visite depuis qu\\\'un ?nergum?ne du nom de Bellus Sel en a bloqu? l\\\'acc?s. Remarquez, ?a arrange les affaires de Nara qui d?teste ?tre d?rang');
INSERT INTO `npc_questions` VALUES (4506, '', '', '', '', 'Tu as r?ussi ? Tu nous as trouv? un tacticien comp?tent ? Je veux bien croire que Jerhyn ?tait aux anges. Gr?ce ? ce tacticien nous allons enfin pouvoir appliquer nos strat?gies et nous faire comprendre par nos hommes. Un grand merci ? toi, Silvosse te b?nisse.');
INSERT INTO `npc_questions` VALUES (4507, '', '', '', '', 'Et alors ? Qu\\\'est-ce que ?a peut me faire que Bonta soit en difficult? ? Je veux juste qu\\\'on me laisse tranquille, moi !');
INSERT INTO `npc_questions` VALUES (4508, '', '', '', '', 'J\\\'ai d?j? eu affaire ? eux... \\nS\\\'ils gagnent le conflit, ils me chasseront de ma mine et me forceront s?rement ? travailler pour eux. Tout sauf ?a ! \\nN?anmoins, je ne vous fais pas confiance pour autant. La confiance se m?rite, vous allez donc me prouver que je peux avoir un minimum confiance en vous.');
INSERT INTO `npc_questions` VALUES (4509, '', '', '', '', 'Bonjour, as-tu parl? ? Jerhyn Gholein dans la Tour des Ordres ? La patience n\\\'est pas son fort et tu as tout int?r?t ? ne pas arriver en retard.');
INSERT INTO `npc_questions` VALUES (4510, '', '', '', '', 'Bonjour, o? en es-tu avec ce Nara ? Est-il aussi comp?tent qu\\\'on le pr?tend ?');
INSERT INTO `npc_questions` VALUES (4511, '', '', '', '', 'Ah, bravo ! Des vivres ? Nous allons nous arranger pour les lui apporter.');
INSERT INTO `npc_questions` VALUES (4512, '', '', '', '', 'Impressionnant ! Avec des armes et un ?quipement de cette qualit?, nos miliciens ne vont pas ?galer les Br?kmariens, ils vont les surpasser ! Tu as fait du tr?s bon travail, prends ces quelques potions qui te remettront d\\\'aplomb.');
INSERT INTO `npc_questions` VALUES (4513, '', '', '', '', 'Je ne peux pas travailler ici ? cause des r?les d\\\'agonie des repas du Mulou. Il me faut un endroit plus au calme et o? il y a moins de passage, comme ?a je ne risque pas de recevoir la visite d\\\'une personne qui en voudrait ? ma peau. Qui en voudrait ? ma peau ? Beaucoup de gens, par exemple des forgerons jaloux de mon talent, ou des voleurs, ou des fant?mes de monstres venus se venger.');
INSERT INTO `npc_questions` VALUES (4514, '', '', '', '', 'Tu te souviens de William Lenglad ? C\\\'est le trublion ? qui tu as bott? le train il y a quelque temps. Eh bien, il fait de nouveau parler de lui car il a un nouvel acolyte. Un Bwork tr?s idiot mais qui semble assez dangereux. \\n... Va leur donner une nouvelle le?on. Essaye de faire en sorte qu\\\'il la retienne, cette fois. \\nT?che de faire vite car j\\\'aurai besoin de toi d?s que tu en auras termin? avec lui et sa bande.');
INSERT INTO `npc_questions` VALUES (4515, '', '', '', '', 'As-tu d?j? calm? Lenglad ?');
INSERT INTO `npc_questions` VALUES (4516, '', '', '', '', 'Si comme moi tu en as assez de voir cette s?gr?gation qui partage la ville en deux, les riches d\\\'un c?t?, et... \\nAH !! Mais c\\\'est TOI ! Je te pr?viens : mon nouveau compagnon, euh, \\\'Baweurk\\\' qu\\\'il dit, va faire justice et me d?barrasser de toi !');
INSERT INTO `npc_questions` VALUES (4517, '', '', '', '', 'Aaaargh, ne m\\\'approche pas !');
INSERT INTO `npc_questions` VALUES (4518, '', '', '', '', 'Ouh, tu y es all? fort mais au moins, il va ?tre calm? pour un moment ! Gr?ce ? ton intervention les commer?ants vont pouvoir travailler tranquillement et arr?ter de se plaindre aupr?s de la milice, ce qui va nous permettre de nous concentrer sur des choses plus importantes. \\nJerhyn Gholein n\\\'est pas satisfait du r?sultat de nos manoeuvres militaires. Pour ?tre plus exact, il trouve qu\\\'elles laissent ? d?sirer. En tant que chef de la milice il est de mon devoir d\\\'assurer le bon entra?nement de mes hommes. Tu vas rendre visite ? Jerhyn Gholein et voir avec lui quelles solutions nous pourrions apporter pour am?liorer l\\\'efficacit? de nos troupes sur le terrain.');
INSERT INTO `npc_questions` VALUES (4519, '', '', '', '', 'Bonjour, Nara m\\\'a inform? par le biais de son ami Norb qu\\\'il a besoin de mati?res premi?res pour fabriquer un premier exemplaire de la future panoplie qui ?quipera nos miliciens. Tu vas rendre visite ? Norb, obtenir ce dont Nara a besoin et le lui apporter en main propre. Ca ne devrait pas te prendre trop de temps, ce qui t\\\'en laissera pour prendre du bon temps ? la Taverne de la Bagrutte une fois ta mission termin?e.');
INSERT INTO `npc_questions` VALUES (4520, '', '', '', '', 'Au cas o? tu aurais d?j? oubli?, l\\\'atelier de Norb se trouve au sud d\\\'Amakna, pr?s du territoire Porcos. Et la mine o? travaille Nara est justement dans le territoire Porcos.');
INSERT INTO `npc_questions` VALUES (4521, '', '', '', '', 'Ne dites rien, je suppose que c\\\'est Nara qui a oubli? quelques-uns de ses outils. Il a quand m?me de la chance que quelqu\\\'un puisse les lui amener !');
INSERT INTO `npc_questions` VALUES (4522, '', '', '', '', 'Si vous cherchez par vous-m?me ?a va prendre des mois. Vous feriez mieux de demander ? Setag l\\\'Enutrof, ce vieux mineur doit conna?tre des endroits quasi-inaccessibles o? je serai plus en s?curit? qu\\\'ici.');
INSERT INTO `npc_questions` VALUES (4523, '', '', '', '', 'Achetez ma bi?re, la seule qui transforme n\\\'importe quel pleutre en un vaillant chevalier ! \\nEfficacit? non garanti');
INSERT INTO `npc_questions` VALUES (4524, '', '', '', '', 'Ce n\\\'est pas aussi simple qu\\\'il n\\\'y para?t, nous avons tout fait avec l\\\'aide d\\\'Otoma?, pour que personne ne puisse s\\\'en approcher... \\nIl faut d\\\'abord r?ussir ? ouvrir cette porte, gr?ce aux dalles, gr?ce aux quatre salles... \\nSeule une ?quipe soud?e, bien organis?e et qui conna?t les moindres recoins de l\\\'?le, peut esp?rer ouvrir cette porte. Ceux qui s\\\'en montrent capables, sont jug?s dignes de rencontrer la b?te !');
INSERT INTO `npc_questions` VALUES (4525, '', '', '', '', 'Ah, te revoil?. Danathor voulait ? nouveau te voir. Tu commences ? te faire conna?tre par ici, tout le monde veut t\\\'engager !');
INSERT INTO `npc_questions` VALUES (4526, '', '', '', '', 'D?p?che-toi, Danathor n\\\'aime pas attendre.');
INSERT INTO `npc_questions` VALUES (4527, '', '', '', '', 'Je t\\\'attendais. J\\\'ai une autre mission ? te confier, si cela t\\\'int?resse. Sache que je te payerai bien davantage qu\\\'Amayiro ne le fera jamais...');
INSERT INTO `npc_questions` VALUES (4528, '', '', '', '', 'On m\\\'a rapport? que tu ?tais du genre d?brouillard et j\\\'ai justement besoin de quelqu\\\'un comme toi. Tu as d?j? trouv? un meilleur forgeron pour ?quiper la milice et un tacticien pour am?liorer la coh?sion des troupes, c\\\'est pourquoi j\\\'ai tout de suite pens? ? toi pour m\\\'aider.');
INSERT INTO `npc_questions` VALUES (4529, '', '', '', '', 'Tu vas rendre une petite visite ? Larry Poller, ? la Tour des Ordres de Bonta, et voir avec lui comment am?liorer notre arsenal magique. Je me moque ?perdument des moyens employ?s pour y parvenir du moment que tu obtiens des r?sultats concrets.');
INSERT INTO `npc_questions` VALUES (4530, '', '', '', '', 'C\\\'est une tr?s bonne question que vous posez l?. Nous disposons d?j? de nombreux ouvrages traitant de la magie et d\\\'une multitude de grimoires de sorcellerie, je ne vois pas ce que nous pourrions ajouter ? notre arsenal, hormis de la magie d?moniaque ou bwork.');
INSERT INTO `npc_questions` VALUES (4531, '', '', '', '', 'Bonjour, as-tu obtenu des informations gr?ce ? Bishom Pot ?');
INSERT INTO `npc_questions` VALUES (4532, '', '', '', '', 'Tu as r?ussi ? t\\\'introduire dans le b?timent de leur milice et ? leur d?rober ce document ? Excellent ! Voyons ce qu\\\'il contient... \\nNous n\\\'avons pas le temps de l\\\'?tudier de mani?re approfondie, chaque minute compte et nous devons agir vite. Je vais envoyer des hommes au Cimeti?re des Tortur?s et tu te joindras ? eux. Lorsque vous aurez vaincu la patrouille br?kmarienne, viens me faire ton rapport. \\nMaintenant file, il ne faut pas rater la patrouille.');
INSERT INTO `npc_questions` VALUES (4533, '', '', '', '', 'Avant que tu t\\\'emballes trop je pr?f?re te pr?venir : tu pourras pas rentrer comme ?a, m?me pas en r?ve. Sadida a prot?g? l\\\'entr?e et l\\\'int?rieur pour emp?cher ceux qui ne respectent pas son pouvoir de voler le livre. Si j\\\'?tais ? ta place, je la jouerai plus cool genre respect de la volont? des dieux et je me lancerai plut?t ? la recherche de la corne magique de Sufokia. \\n... \\nPuisque t\\\'as l\\\'air d?cid?, je t\\\'indique o? se trouve l\\\'entr?e sur ta carte, comme ?a tu me laisseras faire ma sieste. Ouaaaahem...');
INSERT INTO `npc_questions` VALUES (4534, '', '', '', '', 'Un Sadida d\\\'Astrub t\\\'aurait parl? d\\\'une corne magique ? Sufokia ? Ca vaut le coup de v?rifier l\\\'information. Rends-toi l?-bas et interroge le Tavernier du Ripate, les rumeurs circulent facilement dans les tavernes.');
INSERT INTO `npc_questions` VALUES (4535, '', '', '', '', 'Je pensais que cette recherche prendrait plus de temps. Ainsi il ne s\\\'agit pas d\\\'une simple rumeur mais d\\\'un objet existant bel et bien. Il faut que nous mettions la main dessus, ne serait-ce que pour emp?cher Br?kmar de l\\\'acqu?rir. \\nOh, mais je vois que tu as d?j? pr?par? ton stock de Noix de Kokoko. Bonne initiative, j\\\'aime les miliciens pr?voyants.');
INSERT INTO `npc_questions` VALUES (4536, '', '', '', '', 'Salutations, Danathor m\\\'a inform? qu\\\'il voulait te voir car vous auriez une affaire en cours. Ne t\\\'inqui?te pas pour moi, j\\\'attends des nouvelles de nos espions et je te pr?viendrai si j\\\'ai besoin de tes services.');
INSERT INTO `npc_questions` VALUES (4537, '', '', '', '', 'Bonjour, j\\\'esp?re que tout s\\\'est bien pass? avec Danathor. \\nJ\\\'ai ? nouveau besoin de tes services pour une mission dangereuse. Les Br?kmariens sont trop tranquilles et je crains qu\\\'ils envisagent prochainement d\\\'attaquer notre cit?. Tu dois trouver leur plan d\\\'attaque afin de pr?parer une d?fense ad?quate. Inutile d\\\'aller voir notre espion, il n\\\'a pas eu vent de quoi que ce soit et c\\\'est cela qui m\\\'inqui?te. Il y a fort ? parier que les plans se trouvent quelque part dans la Tour de Br?kmar.');
INSERT INTO `npc_questions` VALUES (4538, '', '', '', '', 'Au fait, ne t\\\'inqui?te pas pour l\\\'approvisionnement en ?quipement. Suite au d?c?s de Nara, nous avons fait jouer nos relations avec Pandala et obtenu un convoi plein ? craquer d\\\'?quipement Pandawa. Nous avons ?galement bern? les Br?kmariens en leur faisant croire que notre navire La Descemer transportait ce mat?riel. Pendant qu\\\'ils couraient apr?s la Descemer, l\\\'?quipement ?tait convoy? par voie terrestre et il est arriv? la nuit derni?re. Le Capitaine Alrok et ses hommes proc?dent d?j? ? son inspection.');
INSERT INTO `npc_questions` VALUES (4539, '', '', '', '', 'Ah, c\\\'est vous ! Pouvons-nous commencer l\\\'attaque ? La patrouille de Br?kmar va arriver d\\\'un instant ? l\\\'autre.');
INSERT INTO `npc_questions` VALUES (4540, '', '', '', '', 'Je les vois qui arrivent. \\nEn avant ! Pour Bonta !');
INSERT INTO `npc_questions` VALUES (4541, '', '', '', '', 'Ces maudits Br?kmariens vont voir que nous savons nous d?fendre... et attaquer ! Parlez au commandant pour donner l\\\'assaut.');
INSERT INTO `npc_questions` VALUES (4542, '', '', '', '', 'Nos fl?ches perceront leur rang aussi vite que nous pouvons. Parlez au commandant pour donner l\\\'assaut.');
INSERT INTO `npc_questions` VALUES (4543, '', '', '', '', 'Je crois qu\\\'il est temps de tester le fruit de nos efforts. Les miliciens sont en manoeuvre et nous venons de recevoir plusieurs caisses d\\\'?quipement forg? par Nara. Je veux pr?parer une embuscade sur une patrouille br?kmarienne mais pour ?a il me faut savoir o? et quand frapper. Tu vas rendre une petite visite ? notre espion ? Br?kmar et lui demander o? trouver des rapports sur les rondes des patrouilles br?kmariennes. D?s que tu auras mis la main sur ces documents, rapporte-les moi imm?diatement. Nous devrons frapper vite avant que les Br?kmariens r?alisent le vol des documents et ne changent leurs plans.');
INSERT INTO `npc_questions` VALUES (4544, '', '', '', '', 'Tu trouveras le commandant ? l\\\'entr?e du Cimeti?re des Tortur?s.');
INSERT INTO `npc_questions` VALUES (4545, '', '', '', '', 'L\\\'assaut n\\\'a pas ?t? un succ?s complet, mais au moins vous avez vaincu quelques-uns de leurs guerriers. Malheureusement, j\\\'ai aussi de bien mauvaises nouvelles ? t\\\'apprendre. Les Br?kmariens sont venus ? bout des pi?ges de Nara et comme il a refus? de travailler pour eux, ils se sont d?barrass?s de lui. Il s\\\'est vaillamment d?fendu et a emport? de nombreux Br?kmariens avec lui dans la tombe. Reste ? savoir ce que les Br?kmariens comptent faire ? pr?sent.');
INSERT INTO `npc_questions` VALUES (4546, '', '', '', '', 'Bien jou?, vous avez eu la patrouille. Voici une prime. Malheureusement, j\\\'ai aussi de bien mauvaises nouvelles ? t\\\'apprendre. Les Br?kmariens sont venus ? bout des pi?ges de Nara et comme il a refus? de travailler pour eux, ils se sont d?barrass?s de lui. Il s\\\'est vaillamment d?fendu et a emport? de nombreux Br?kmariens avec lui dans la tombe. Reste ? savoir ce que les Br?kmariens comptent faire ? pr?sent.');
INSERT INTO `npc_questions` VALUES (4547, '', '', '', '', 'Les miliciens sont pr?ts ? d?fendre notre cit? mais j\\\'aimerais savoir comment les Br?kmariens comptent attaquer. Plus t?t nous conna?trons leur plan d\\\'attaque, mieux nous pourrons organiser la d?fense et ainsi minimiser nos pertes.');
INSERT INTO `npc_questions` VALUES (4548, '', '', '', '', 'Ainsi nos efforts n\\\'auront pas ?t? vains. Nous disposons ? pr?sent d\\\'une meilleure milice et comble de chance nous n\\\'aurons ? d?plorer aucun mort ni bless?. Avec cette lettre nous allons de surcro?t pouvoir condamner Xephir?s sans qu\\\'il puisse jouer de ses relations pour retarder son proc?s. \\nTu as fait un excellent travail, comme toujours. Bonta te doit beaucoup et dans le doute, plut?t que de te donner un bouclier dont tu n\\\'aurais pas forc?ment l\\\'utilit?, je pr?f?re te remettre les ressources n?cessaires ? sa confection. Tu pourras ainsi demander ? un forgeur de bouclier de te le fabriquer ou utiliser les ressources dans un autre ?quipement que tu jugeras plus appropri?. \\nPuisqu\\\'il semblerait qu\\\'aucune bataille ne soit ? l\\\'ordre du jour, tu vas pouvoir en profiter pour aller voir les ma?tres d\\\'ordre.');
INSERT INTO `npc_questions` VALUES (4549, '', '', '', '', 'Je suis au courant, un colis en provenance d\\\'Astrub vient d\\\'arriver. Juste apr?s ta d?faite, les mercenaires d\\\'Astrub sont intervenus ? cause du grabuge caus? par le combat et ils ont arr?t? les Br?kmariens. Le Mage Ax a r?cup?rer la Corne Edfrit et il nous l\\\'a envoy?e, en pr?cisant que tu avais refus? de la c?der aux Br?kmariens au p?ril de ta vie. Quand je pense ? tout le mal que nous nous sommes donn?s pour obtenir cette corne... Ca nous apprendra ? nous fier aux rumeurs et aux l?gendes. Si ?a peut te consoler, dis-toi que gr?ce au pouvoir de cette corne, il y aura moins de jeunes recrues de corv?e de patates. Quoiqu\\\'il en soit, tu as tr?s bien servi Bonta et ta loyaut? a plus de valeur ? mes yeux qu\\\'un objet magique.');
INSERT INTO `npc_questions` VALUES (4551, '', '', '', '', 'Huuummm. Tr?s bon ce plat est. Du vertgely ajout? vous avez ? Un grand chef cuisinier indubitablement vous ?tes. Pourtant m?me avec ce plat, m\\\'amadouer vous ne parviendrez pas.');
INSERT INTO `npc_questions` VALUES (4552, '', '', '', '', 'Les Lenalds habitaient ce qui constitue aujourd\\\'hui les ?les des Wabbits. Ils ?taient pacifistes et ne purent r?sister ? l\\\'envahisseur wabbit qui usa de tous les stratag?mes pour les exterminer et s\\\'approprier leurs terres. Seule une poign?e de Lenalds surv?cut au massacre et habite encore le sud de l\\\'?le.');
INSERT INTO `npc_questions` VALUES (4553, '', '', '', '', 'Pourquoi ? Parce que je ne suis pas un bourrin de Iop ou de Pandawa. Moi je fais dans la finesse : je me rends invisible et je pose de nombreux pi?ges pour tuer les kanigrous ? petit feu. Au besoin je donne quelques coups de dagues bien plac?s, mais jamais rien de violent. Non, la violence pure et dure c\\\'est bon pour les brutes ?paisses sans cervelle. Les haches, les ?p?es, ?a c\\\'est bourrin. As-tu d?j? essay? de donner des coups de marteau en finesse ? Non ? Et pourquoi selon toi ? Parce que c\\\'est une arme de bourrin. Les dagues par contre permettent des frappes chirurgicales et tout en finesse, donc c\\\'est soft, d\\\'o? mon surnom.');
INSERT INTO `npc_questions` VALUES (4554, '', '', '', '', 'Pouah, quelle horreur ! Gardez ce chiffon loin de moi. Il est hors de question de toucher un chiffon aussi commun et aussi sale. Il n\\\'a aucun style et son odeur... A-t-il ?t? tremp? dans du jus de cawotte ou a-t-il servi ? transporter du poisson en plein ?t? ? \\nSuivez mon conseil : d?barrassez-vous en aussi vite que possible, et prenez un bain par la m?me occasion. Tant que vous y ?tes, pourquoi ne pas prendre un Shigekax Menthe pour rafra?chir votre haleine ?');
INSERT INTO `npc_questions` VALUES (4555, '', '', '', '', 'Je veux bien t\\\'aider mais il va falloir me rendre un service en ?change. Si tu me rapportes un de mes manuels alors je t\\\'aiderai ? remettre ce bandana en ?tat.');
INSERT INTO `npc_questions` VALUES (4557, '', '', '', '', 'H? l\\\'ami, qu\\\'est-ce qui t\\\'am?ne ? Sufokia ?');
INSERT INTO `npc_questions` VALUES (4558, '', '', '', '', 'Ah, oui... cette rumeur-l?. Hmm, apporte-moi des carapaces vides de tortue de Moon pour d?corer ma taverne, et je t\\\'en parlerai. Une de chaque de couleur, les carapaces.');
INSERT INTO `npc_questions` VALUES (4559, '', '', '', '', 'As-tu mes carapaces ?');
INSERT INTO `npc_questions` VALUES (4560, '', '', '', '', 'Alors voil? : la corne se trouve sur... une ?le para?t-il. Amusant, hein ? \\nJe n\\\'en sais pas plus, je ne suis pas une biblioth?que sur pattes comme Harry Stote.');
INSERT INTO `npc_questions` VALUES (4561, '', '', '', '', 'Salutations, je parie qu\\\'Oto Mustam est en train de chercher un moyen de prendre l\\\'avantage sur nous. Il y a une rumeur tr?s int?ressante qui court depuis quelque temps : une corne magique d\\\'une grande puissance serait dissimul?e quelque part. Le probl?me est que j\\\'ignore d\\\'o? peut provenir une telle rumeur alors si tu sais quelque chose ? ce sujet, ?a m\\\'int?resse.');
INSERT INTO `npc_questions` VALUES (4562, '', '', '', '', 'Cet objet pourrait nous donner le dessus contre Br?kmar.');
INSERT INTO `npc_questions` VALUES (4563, '', '', '', '', 'Qu\\\'ai-je fais ? Djaul pour ?tre entour? d\\\'empot?s pareils ? J\\\'ai dis juste devant moi le milicien, pas ? trois kilom?tres !');
INSERT INTO `npc_questions` VALUES (4564, '', '', '', '', 'Vous ?tes malade ? Pas ici, c\\\'est de la folie. Vous voulez ?veillez les soup?ons du Grandapan ou quoi ? J\\\'avais pourtant dis ? Xephir?s que je le contacterais pour l\\\'heure et le lieu du rendez-vous. \\nJ\\\'esp?re pour vous qu\\\'ils sont tous ? l\\\'int?rieur. Je ne peux pas v?rifier ?a tant que le Grandapan nous surveille mais s\\\'il en manque, Xephir?s aura de mes nouvelles, et vous aussi !');
INSERT INTO `npc_questions` VALUES (4565, '', '', '', '', 'Bienvenue au temple. Profite de ton s?jour pour te renseigner sur nos us et coutumes, et pourquoi pas, affronter l\\\'un de nos dopeuls.');
INSERT INTO `npc_questions` VALUES (4566, '', '', '', '', 'Ton monde m\\\'a bien amus?, c\\\'est pourquoi je tiendrai ma promesse de ne pas le d?truire... tout de suite. \\nSi tu m\\\'apportes un vieux Trousseau de clefs, je peux te le remplacer par un nouveau, qui te servira pour aller te mesurer aux monstres les plus forts.');
INSERT INTO `npc_questions` VALUES (4567, '', '', '', '', 'Bonjour, veux-tu partir en voyage ? Ca tombe bien, j\\\'ai justement une mission qui devrait te d?payser. Tu vas te rendre sur l\\\'?le de Moon et trouver le gardien de la Corne Edfrit. Si par la m?me occasion tu peux r?cup?rer la Corne Edfrit, n\\\'h?site pas.');
INSERT INTO `npc_questions` VALUES (4568, '', '', '', '', 'Salutations, tu viens m\\\'annoncer une bonne nouvelle ?');
INSERT INTO `npc_questions` VALUES (4569, '', '', '', '', 'Le gardien existe vraiment mais il refuse de coop?rer ? J\\\'esp?re que tu ne l\\\'as pas brusqu?, il est hors de question d\\\'employer des m?thodes br?kmariennes. D?s que tu auras r?cup?r? de ton voyage j\\\'aurai une autre mission pour toi, d?p?che-toi de te remettre d\\\'aplomb.');
INSERT INTO `npc_questions` VALUES (4570, '', '', '', '', 'Dangereuse cette ?le est. Partir vous devriez. Ou bien des informations venant de moi vous cherchez ?');
INSERT INTO `npc_questions` VALUES (4571, '', '', '', '', 'La Corne Edfrit. Son emplacement je connais. Le r?v?ler je ne ferai pas. Ne pas insister vous devriez.');
INSERT INTO `npc_questions` VALUES (4572, '', '', '', '', 'R?p?ter je vais. Ne pas insister vous devriez. R?v?ler l\\\'emplacement jamais je ne ferai.');
INSERT INTO `npc_questions` VALUES (4573, '', '', '', '', 'Les kamas inutiles sur cette ?le sont. Dans le cas contraire m?me, jamais cela ne suffirait.');
INSERT INTO `npc_questions` VALUES (4574, '', '', '', '', 'Des menaces prof?rer vous osez ? M\\\'attaquer vous pouvez, mais votre s?curit? je ne pourrai alors assurer car pas mang? depuis longtemps je n\\\'ai.');
INSERT INTO `npc_questions` VALUES (4575, '', '', '', '', 'Il faut trouver un moyen d\\\'amadouer cette tortue. Tu vas te rendre sur l\\\'?le et interroger ses habitants en esp?rant que l\\\'un d\\\'eux puisse nous renseigner. D?s que tu as le renseignement, essaye d\\\'amadouer Turorte puis reviens ici avec la Corne Edfrit si possible.');
INSERT INTO `npc_questions` VALUES (4576, '', '', '', '', 'Des nouvelles ?');
INSERT INTO `npc_questions` VALUES (4577, '', '', '', '', 'Je me doutais que ?a ne serait pas facile, sans doute ai-je voulu aller trop vite. A vouloir faire la course avec Br?kmar j\\\'en oublie parfois l\\\'essentiel. Puisque nous ne sommes pas parvenus ? l\\\'amadouer, nous allons prendre le temps de r?fl?chir pour trouver autre chose.');
INSERT INTO `npc_questions` VALUES (4578, '3947', '', '', '0', 'Hiiik griiik. Ronron vr?t !');
INSERT INTO `npc_questions` VALUES (4579, '', '', '', '', 'Pnj(938) et Message(4578)');
INSERT INTO `npc_questions` VALUES (4580, '', '', '', '', 'Un de mes manuels, merci. Comme promis je vais t\\\'aider ? condition de m\\\'apporter ce dont j\\\'ai besoin. Il me faut du Tissu de Rapi??age, un tailleur pourra t\\\'en fabriquer avec la recette que voici. J\\\'ai ?galement besoin d\\\'une Teinture Orange Sanguine. Cette recette est peu connue des alchimistes car mon ami Uba Tess?e l\\\'a oubli? dans ma maison. Je te la donne volontiers pour te remercier de m\\\'avoir rapport? un de mes manuels.');
INSERT INTO `npc_questions` VALUES (4581, '', '', '', '', 'Bonjour, nous allons arr?ter de nous pr?cipiter et agir de mani?re pos?e. Nous n\\\'avons pas r?ussi ? amadouer Turorte, mais comme elle ne semble pas belliqueuse il y a s?rement un moyen de s\\\'arranger avec elle pour obtenir la Corne Edfrit. Pour cela il nous faut en savoir plus ? son sujet, ce qui induit d\\\'interroger un sp?cialiste des animaux. Il y en a plusieurs ? Sufokia mais le mieux plac? me semble ?tre Oshimo. Il est le responsable du Chanil qui se trouve au Nord de Sufokia. Enqu?te aussi loin que possible, inutile de se pr?cipiter cette fois-ci.');
INSERT INTO `npc_questions` VALUES (4582, '', '', '', '', 'Je vais pouvoir arranger ton bandana, laisse-moi un peu de temps. \\n... \\nVoil?, il est presque comme neuf. Je n\\\'ai pas r?ussi ? retirer compl?tement l\\\'odeur de cawotte mais elle devrait dispara?tre avec le temps.');
INSERT INTO `npc_questions` VALUES (4583, '', '', '', '', 'Tu m\\\'as l\\\'air un peu p?le pour un membre de la milice de Br?kmar. T\\\'as pas aval? un kralamoure de travers par hasard ? \\nAh, tu m\\\'apportes les documents que le Bontarien avait vol?, mais vous deviez ?tre trois, non ? Je suppose que les deux autres se sont arr?t?s ? la taverne. Va les rejoindre, je passerai ces documents ? Kaffra Kyper d?s qu\\\'il reviendra de sa s?ance d\\\'entra?nement.');
INSERT INTO `npc_questions` VALUES (4584, '', '', '', '', 'Bonjour, tes recherches sur Turorte avancent-elles ?');
INSERT INTO `npc_questions` VALUES (4585, '', '', '', '', 'Ahahah, tu leur as jou? un sacr? tour. R?cup?rer les documents et en r?diger de faux pour leur faire croire que notre cambriolage a ?chou?, il fallait y penser. Ton ing?niosit? arrange nos affaires, je suis fier de toi. \\nNous voil? avec des documents secrets en plus de ceux que notre espion devait voler, il faut croire que c\\\'est notre jour de chance.');
INSERT INTO `npc_questions` VALUES (4587, '', '', '', '', 'Ah, Tulolte... oui, elle ?tait venue jusqu\\\'ici il y a longtemps. Je me souviens d\\\'elle, nous avons beaucoup bavald?. Lolsque les Wabbits nous ont chass? pal la folce, elle m\\\'a dit que les wobots lui avaient vol? son objet f?tiche, un bandana magique. Je clois que vous poulliez vous attiler ses faveuls en l?cup?lant cet objet.');
INSERT INTO `npc_questions` VALUES (4591, '', '', '', '', 'Un espion br?kmarien a r?ussi ? s\\\'infiltrer dans la cit? et ? voler des documents relatifs ? nos recherches sur la Corne Edfrit ! Il a r?ussi ? fuir, mais nos archers sont certains de l\\\'avoir touch? ? la jambe. Tu devrais pouvoir le rattraper, il a fil? vers Br?kmar par la route.');
INSERT INTO `npc_questions` VALUES (4592, '', '', '', '', 'Il ne doit pas aller vite dans son ?tat, mais ne tra?ne pas. Un autre Br?kmarien pourrait le trouver et r?cup?rer les documents.');
INSERT INTO `npc_questions` VALUES (4593, '', '', '', '', '... me laisser ici !? Dans mon ?tat je vais... \\nAh !! Un Bontarien m\\\'a d?j? rattrap? !');
INSERT INTO `npc_questions` VALUES (4594, '', '', '', '', '... ordres d\\\'Oto Mustam. Je dois r?cup?rer les documents et peu importe ce qui... \\nHmm, nous avons un trouble-f?te.');
INSERT INTO `npc_questions` VALUES (4595, '', '', '', '', 'Les documents ! Tu as pu les r?cup?rer, bien jou? ! Je crains cependant que Br?kmar ne soit ?galement ? la recherche de la Corne Edfrit, sinon pourquoi nous voler ces documents ? Quoiqu\\\'il en soit, nous avons s?rement une longueur d\\\'avance sur eux, il faut en profiter.');
INSERT INTO `npc_questions` VALUES (4596, '', '', '', '', 'Ah, quelle catastrophe ! Il avait donc ?t? rejoint. Dommage que tu n\\\'aies pas r?ussi ? les battre... \\nOto Mustam doit lui aussi ?tre sur les traces de la Corne Edfrit, sinon pourquoi nous voler ces documents ? Nous avons sans doute encore une longueur d\\\'avance sur nos ennemis, il faut en profiter.');
INSERT INTO `npc_questions` VALUES (4597, '', '', '', '', 'Tu as donc d?cid? de me remettre les documents ?');
INSERT INTO `npc_questions` VALUES (4598, '', '', '', '', 'Bon choix. Voici ta r?compense pour ta fid?lit?. Tu diras ? Amayiro que l\\\'espion ?tait aid? par de nombreux Br?kmariens lorsque tu l\\\'as rattrap? et que tu ne faisais pas le poids contre autant d\\\'ennemis.');
INSERT INTO `npc_questions` VALUES (4599, '', '', '', '', 'Bonjour, suite au vol de documents perp?tr? par les Br?kmariens j\\\'ai demand? ? Ebru Of El d\\\'envoyer un de ses espions ? Br?kmar. Il devait r?cup?rer les renseignements obtenus par Br?kmar sur la Corne Edfrit et ainsi nous faire gagner du temps mais je suis inquiet car il n\\\'est pas revenu. Va le trouver, je t\\\'ai donn? une copie de la mission qu\\\'on lui a donn?e. Fais vite, je crains qu\\\'il ne soit d?j? trop tard. \\nSi par chance tu arrives ? temps, cherche un moyen d\\\'envoyer les Br?kmariens sur une fausse piste. Silvosse te garde.');
INSERT INTO `npc_questions` VALUES (4600, '', '', '', '', 'Ah, vous ?tes de Bonta ? J\\\'ai r?cup?r? les documents comme pr?vu, mais par contre je n\\\'avais pas pr?vu qu\\\'ils me poursuivraient ! \\nAh, je les entends, ils arrivent !');
INSERT INTO `npc_questions` VALUES (4601, '', '', '', '', 'Mon bandana vous avez retrouv? ! A tout jamais perdu je le croyais. De mon vieil ami Sphincter Cell je le tiens, tr?s cher ? mon coeur il est. Vous remerciez je devrai.');
INSERT INTO `npc_questions` VALUES (4602, '', '', '', '', 'Finalement tu es venu. Je vais t\\\'expliquer en quoi consiste ce rituel, c\\\'est enfantin et m?me un Iop peut le faire s\\\'il suit les consignes ? la lettre. \\nIl faut remplir le bac d\\\'eau de crachin, y ajouter 10 Graines de Pandouille, plonger l\\\'objet dans le bac et l\\\'en sortir sans l\\\'essuyer, saupoudrer l\\\'objet de 4 mesures de Poudre de Perlinpainpain, le placer dans un courant d\\\'air magique et la r?v?lation se produira. \\nIl faut chauffer le bac pendant le processus, une personne doit donc y ?tre d?di?e. Il faut uniquement utiliser du Bois de Charme. \\nPour activer la ventilation, il faut 4 potions de courant d\\\'air et une personne d?di?e. \\nLorsque tes amis sont en place devant les deux machines, place-toi devant le bac et fais les choses dans l\\\'ordre. Il ne faut PAS avoir de soufre sur toi sinon tu risques de mourir, ou pire.');
INSERT INTO `npc_questions` VALUES (4603, '', '', '', '', 'Le rituel est un succ?s. J\\\'ai not? les informations sur un parchemin que j\\\'ai dat? et sign? afin qu\\\'Amayiro puisse l\\\'authentifier. Bon courage pour la suite, tu vas en avoir besoin.');
INSERT INTO `npc_questions` VALUES (4605, '', '', '', '', 'H?te-toi ! Tout est indiqu? dans la copie des consignes que je t\\\'ai donn?e.');
INSERT INTO `npc_questions` VALUES (4607, '', '', '', '', 'Bonjour, je suis heureux que tu aies obtenu des informations suppl?mentaires sur Turorte. Il semblerait que nous n\\\'ayons pas le choix et qu\\\'il faille te rendre au ch?teau du Wa Wabbit pour r?cup?rer le bandana de Turorte. Prends ces 1000 Kamas pour te payer le voyage et pense ? emmener d\\\'autres personnes avec toi, le Wa Wabbit est r?put? pour son amour du combat et m\\\'est avis que ses Wobots ne c?deront pas le bandana facilement.');
INSERT INTO `npc_questions` VALUES (4608, '', '', '', '', 'Reviens me voir quand tu auras du nouveau.');
INSERT INTO `npc_questions` VALUES (4609, '', '', '', '', 'Nous ne pouvons pas rendre ? Turorte son bandana dans cet ?tat. Fais appel aux meilleurs tailleurs de Bonta, d\\\'Amakna et d\\\'Astrub si n?cessaire pour le remettre en ?tat.');
INSERT INTO `npc_questions` VALUES (4610, '', '', '', '', 'Salutations, j\\\'allais justement te faire appeler. Nous devons profiter de notre avance sur Br?kmar et mettre la main sur la Corne Edfrit avant nos ennemis. Tu vas imm?diatement te rendre sur l\\\'?le de Moon et demander ? Turorte la Corne Edfrit en ?change de son bandana. Ne tra?ne surtout pas.');
INSERT INTO `npc_questions` VALUES (4611, '', '', '', '', 'L\\\'emplacement je vais vous r?v?ler. Au nord-est de l\\\'?le, totalement, une statue ? c?t?. Fouiller vous allez, la corne vous trouverez.');
INSERT INTO `npc_questions` VALUES (4612, '', '', '', '', 'Quelles sont les nouvelles ?');
INSERT INTO `npc_questions` VALUES (4613, '', '', '', '', 'Beuh... T\\\'as pas le droit de r?pondre par une autre question, c\\\'est de la triche. Tu cherches aussi la Corne Edfrit ? \\nMais !? T\\\'es une idiote de Bontarienne. Meurs, charogne !');
INSERT INTO `npc_questions` VALUES (4614, '', '', '', '', 'H? ! Tu es qui, toi ? R?ponds, ou je t\\\'?tripe en un coup d\\\'?p?e !');
INSERT INTO `npc_questions` VALUES (4615, '', '', '', '', 'Beuh... T\\\'as pas le droit de r?pondre par une autre question, c\\\'est de la triche. Tu cherches aussi la Corne Edfrit ? \\nMais !? T\\\'es un idiot de Bontarien. Meurs, charogne !');
INSERT INTO `npc_questions` VALUES (4616, '', '', '', '', 'Excellent travail. Heureusement que ce Iop n\\\'avait pas compris qu\\\'il fallait creuser pour trouver la Corne Edfrit. Montre-la de plus pr?s je te prie. \\nCette corne est magnifique, elle doit rec?ler de puissants pouvoirs magiques. Ce sera un atout non-n?gligeable dans notre lutte contre Br?kmar.');
INSERT INTO `npc_questions` VALUES (4617, '', '', '', '', 'Nous avons la corne, mais... \\nJe n\\\'ai toujours aucune id?e quant ? son utilit?. Il semble ne rien se passer quand on souffle dedans. \\nIl faudrait que tu ailles consulter le Mage Ax, ? Astrub : il saura ? quoi elle sert.');
INSERT INTO `npc_questions` VALUES (4618, '', '', '', '', 'Je sens que tu as sur toi un objet magique que tu souhaites me montrer...');
INSERT INTO `npc_questions` VALUES (4619, '', '', '', '', 'Et tu souhaites conna?tre son utilisation ? Rejoins-moi dans le sous-sol de l\\\'h?tel de vente des alchimistes et nous proc?derons au rituel de R?v?lation. Pr?s d\\\'un coin il y a une armoire. Place-toi devant cette armoire et empruntes le passage qui s\\\'ouvrira devant toi. Pense ? ?tre accompagn? par deux personnes de confiance car je veux bien t\\\'aider mais je ne vais pas faire le travail ? ta place. Je vais t\\\'?crire une liste des objets dont tu auras besoin. Apporte-les et tout devrait se passer sans probl?me, sauf si tu remplaces la Poudre de Perlinpainpain par une Blague de Soufre. Il est tr?s important de ne pas avoir de soufre sur toi, entendu ?');
INSERT INTO `npc_questions` VALUES (4620, '', '', '', '', 'D?j? de retour ? Le Mage Ax a-t-il pu te renseigner sur la Corne Edfrit ?');
INSERT INTO `npc_questions` VALUES (4621, '', '', '', '', 'F?licitations pour ta victoire contre les Br?kmariens. Quand je pense ? tout le mal que nous nous sommes donn?s pour obtenir cette corne... Ca nous apprendra ? nous fier aux rumeurs et aux l?gendes. Si ?a peut te consoler, dis-toi que gr?ce au pouvoir de cette corne, il y aura moins de jeunes recrues de corv?e de patates. Quoiqu\\\'il en soit, tu as tr?s bien servi Bonta et ta loyaut? a plus de valeur ? mes yeux qu\\\'un objet magique.');
INSERT INTO `npc_questions` VALUES (4622, '', '', '', '', 'Oh, oh ! Du calme ! Je me disais qu\\\'un service en valait un autre, mais je suppose que les Br?kmariens voient la chose autrement... \\nBon, alors c\\\'est simple : tout ce que je sais, c\\\'est que cette corne magique serait sur une ?le mais j\\\'ignore laquelle. \\nJe n\\\'en sais pas plus, je ne suis pas une biblioth?que sur pattes comme Harry Stote.');
INSERT INTO `npc_questions` VALUES (4623, '', '', '', '', 'Nos r?cents ?checs m\\\'?nervent, mais j\\\'ai peut-?tre trouv? un moyen pour an?antir Bonta une bonne fois pour toutes. Nous allons nous mettre en qu?te de la puissante corne magique dont on t\\\'a parl? au Port de Madrestam. Rends-toi ? la Taverne du Ripate et trouve davantage d\\\'informations.');
INSERT INTO `npc_questions` VALUES (4624, '', '', '', '', 'N\\\'h?site pas ? recourir aux menaces. Les taverniers se laissent facilement impressionner.');
INSERT INTO `npc_questions` VALUES (4625, '', '', '', '', 'La corne serait sur l\\\'?le de Moon et tu as pris la peine de pr?parer quelques Noix de Kokoko pour ta prochaine mission ? Tr?s bonne initiative. Si seulement les autres miliciens ?taient aussi pr?voyants, Bonta serait tomb?e depuis longtemps.');
INSERT INTO `npc_questions` VALUES (4626, '', '', '', '', 'Eh bien, qu\\\'est-ce que tu attends ? Rends-toi sur l\\\'?le de Moon et cherche des indices ! File !');
INSERT INTO `npc_questions` VALUES (4627, '', '', '', '', 'Il me tarde d\\\'avoir cette corne et de pouvoir enfin raser Bonta et imposer notre vision des choses.');
INSERT INTO `npc_questions` VALUES (4628, '', '', '', '', 'Comment ? Tu as trouv? une tortue qui sait o? se trouve la corne mais qui refuse de te dire o? ? \\nCr?ne de Tofu ! Cervelle de Iop !');
INSERT INTO `npc_questions` VALUES (4629, '', '', '', '', 'Tu avais la main sur l\\\'emplacement de la Corne Edfrit et tu t\\\'es laiss? intimider par une tortue !? \\nRetourne-y et soutire-lui l\\\'information par tous les moyens ! Menaces, violences... tu as carte blanche !');
INSERT INTO `npc_questions` VALUES (4630, '', '', '', '', 'Tu as carte blanche pour faire parler ta tortue ! Au travail !');
INSERT INTO `npc_questions` VALUES (4631, '', '', '', '', 'Tu dois en apprendre davantage sur Turorte, c\\\'est le seul moyen de trouver son point faible.');
INSERT INTO `npc_questions` VALUES (4632, '', '', '', '', 'Si je comprends bien tu es en train de m\\\'expliquer qu\\\'une tortue isol?e est en train de tenir t?te ? la volont? de Br?kmar ? Elle commence ? me taper sur le syst?me ! Je ne vais quand m?me pas mobiliser toutes les troupes de la cit? pour cette tortue ! \\nLa violenter ne sert ? rien et l\\\'empoisonner n\\\'a pas donn? plus de r?sultat, il faut donc trouver autre chose, mais quoi ?');
INSERT INTO `npc_questions` VALUES (4633, '', '', '', '', 'Si nous voulons faire parler Turorte, nous devons en savoir plus sur elle. Je te charge de cette mission non pas pour tes comp?tences mais parce que mes autres larbins sont d?j? en mission. Cette fois tu as int?r?t ? r?ussir car je tol?re difficilement les ?checs r?p?t?s. Non, l\\\'incomp?tence des autres miliciens n\\\'est pas une excuse ! \\nCommence par te renseigner aupr?s d\\\'un sp?cialiste des animaux, par exemple ce d?gonfl? d\\\'Oshimo, qui s\\\'occupe du Chanil.');
INSERT INTO `npc_questions` VALUES (4634, '', '', '', '', 'Turorte ? Ce nom me dit quelque chose. Il s\\\'agit d\\\'une tortue ? \\nJe veux bien vous aider mais en ?change vous allez me rendre un petit service. Un petit bwak de feu est actuellement pi?g? sur un lopin de terre et il a peur de traverser les quelques m?tres qui le s?parent de la berge. Si vous le sauvez, je vous dirai ce que je sais sur Turorte. \\nAh, au fait, vous aurez s?rement besoin d\\\'une corde d\\\'escalade pour atteindre le lopin de terre du bwak.');
INSERT INTO `npc_questions` VALUES (4635, '', '', '', '', 'Tu es plus capable que les autres idiots fra?chement recrut?s. Le point faible de Turorte serait son dos... Va demander ? Mulic Bere comment fabriquer un grattoir sp?cial. Je te conf?re temporairement l\\\'autorit? de recruter d\\\'autres miliciens pour cette mission qui passe prioritaire. S\\\'ils font des histoires, colle-leur une racl?e.');
INSERT INTO `npc_questions` VALUES (4636, '', '', '', '', 'Salut toi. As-tu trouv? des larbins pour fabriquer un grattoir ? dos ? S\\\'ils rechignent ? t\\\'aider, pr?viens-les qu\\\'ils auront affaire ? moi.');
INSERT INTO `npc_questions` VALUES (4637, '', '', '', '', 'Ecoute bien ceci : tu es aussi incapable et inutile qu\\\'un Bitouf des plaines au milieu de l\\\'oc?an. Pour punir ton incomp?tence, tu vas aller me chercher une Arm?e de Tiques de sanglier des plaines. Ca te rappellera ton insignifiance et ? quel point je d?teste les ?checs. Non, je ne parle pas du jeu mais du contraire de la r?ussite, t?te de piou !');
INSERT INTO `npc_questions` VALUES (4638, '', '', '', '', 'Bien, maintenant tu as compris qu\\\'il vaut mieux ne pas me d?cevoir. A l\\\'avenir, tu r?ussiras les missions que je te confie.');
INSERT INTO `npc_questions` VALUES (4639, '', '', '', '', 'Alors raclure de fiente de crotte de trooll, ta nouvelle mission te convient ?');
INSERT INTO `npc_questions` VALUES (4640, '', '', '', '', 'Je ne fais que mon travail, rien de plus. Je suis un simple stagiaire vous savez. C\\\'?tait soit la milice de Bonta, soit les latrines de la foire du trooll. Je n\\\'ai pas h?sit? longtemps. \\nLes documents ? Je devais les remettre ? Larry Poller, devant la tour de Bonta, mon sup?rieur serait pass? les prendre plus tard.');
INSERT INTO `npc_questions` VALUES (4641, '', '', '', '', 'J\\\'ai bien r?fl?chi. Dites ? votre chef que j\\\'accepte ses conditions : ma fid?lit? ? Br?kmar en ?change du joyau lorsque ma mission sera remplie.');
INSERT INTO `npc_questions` VALUES (4642, '', '', '', '', 'Mettez-vous en slip, je veux ?tre s?r que vous ne cachez pas d\\\'arme de destruction massive sous vos v?tements.');
INSERT INTO `npc_questions` VALUES (4643, '', '', '', '', 'Attention, vermisseau : ta mission est tr?s pr?cise. Un de nos espions a vol? des documents ? Bonta concernant la Corne Edfrit, mais il a ?t? touch? ? la jambe dans sa fuite. Tu dois r?cup?rer les documents qu\\\'il porte. Peu importe ce qui arrive ensuite ? ce minable. \\nIl a commenc? ? fuir par la route, mais il n\\\'est sans doute pas all? loin. \\nEt d?p?che-toi, ils risquent de le rattraper sous peu.');
INSERT INTO `npc_questions` VALUES (4644, '', '', '', '', 'Qu\\\'est-ce que tu attends ? Bonta ne doit pas r?cup?rer ces documents !');
INSERT INTO `npc_questions` VALUES (4645, '', '', '', '', 'Ah, un alli? br?kmarien ! Ces maudits archers m\\\'ont bien eu... vite, il faut retourner ? Br?kmar avant qu\\\'ils ne me rattrapent !');
INSERT INTO `npc_questions` VALUES (4646, '', '', '', '', 'Hein !? Tu comptes me laisser ici !? Dans mon ?tat je vais me faire rattraper ! Tu ne ferais pas ?a ? un alli? br?kmarien, quand m?me ?');
INSERT INTO `npc_questions` VALUES (4647, '', '', '', '', 'Aaargh... maudit sois-tu de me laisser mourir ainsi, Oto ! \\nTiens, prend tes fichus documents et d?gage, je vais essayer de me planquer...');
INSERT INTO `npc_questions` VALUES (4648, '', '', '', '', 'Tu ferais ?a ? Merci ! Aaaah, mais j\\\'entends les Bontariens qui arrivent ! Je vais faire ce que je peux pour t\\\'aider au combat.');
INSERT INTO `npc_questions` VALUES (4649, '', '', '', '', 'Eh bien ? J\\\'esp?re que tu es arriv? ? temps.');
INSERT INTO `npc_questions` VALUES (4650, '', '', '', '', 'Eh bien, tu veux te faire prendre aussi ? Retourne voir ce chien d\\\'Oto et laisse-moi !');
INSERT INTO `npc_questions` VALUES (4651, '', '', '', '', 'Merci pour ton aide ! Ca devrait aller pour moi maintenant.');
INSERT INTO `npc_questions` VALUES (4652, '', '', '', '', 'Pnj(183) et Message(4649)');
INSERT INTO `npc_questions` VALUES (4653, '', '', '', '', 'Ah, tr?s bien. Tu as respect? mes ordres. Tant pis pour l\\\'espion, il n\\\'avait qu\\\'? ?tre plus dou? en esquive !\\nVoici ta paye.');
INSERT INTO `npc_questions` VALUES (4654, '', '', '', '', 'H?, mais ils sont tout froiss?s. Tu as aid? l\\\'espion je suppose? Je t\\\'avais pourtant dit de juste r?cup?rer les documents ! \\nBon, tant pis. Tu n\\\'auras qu\\\'une partie des kamas que je comptais te donner, ?a t\\\'apprendra ? respecter mes ordres.');
INSERT INTO `npc_questions` VALUES (4655, '', '', '', '', 'Un Br?kmarien ? D?j? ? En garde ! \\nAH, mais c\\\'est VOUS ! Non, non, je me rends ! Je pr?f?re croupir dans les ge?les de Br?kmar plut?t que finir mort !');
INSERT INTO `npc_questions` VALUES (4656, '', '', '', '', 'Vous n\\\'allez pas me taper, hein ? Je vous suis jusqu\\\'aux ge?les...');
INSERT INTO `npc_questions` VALUES (4657, '', '', '', '', 'Ces documents sont tr?s importants pour Br?kmar. Je ne tol?rerai aucune erreur de ta part.');
INSERT INTO `npc_questions` VALUES (4658, '', '', '', '', 'L\\\'espion bontarien s\\\'est rendu sans combattre ? Eh bien, tu commences ? avoir une petite r?putation ? Bonta, on dirait. \\nAs-tu pens? ? donner de faux documents ? nos ennemis ? Oui ? Tr?s bien, tout se d?roule donc comme pr?vu. Reprends vite ton souffle, je vais avoir besoin de toi pour la suite.');
INSERT INTO `npc_questions` VALUES (4659, '', '', '', '', 'C\\\'est amusant que ?a soit arriv? presque en m?me temps, mais un espion de Bonta s\\\'est infiltr? dans notre tour et a vol? des documents. Nos ?claireurs l\\\'ont vu passer par l\\\'Est de la route. Prends un Zaap et intercepte-le.  \\nUne fois que tu auras r?cup?r? les documents, r?diges-en des faux et transmets-les de quelque mani?re que ce soit ? nos ennemis pour les mener sur une fausse piste. Reviens me voir lorsque tu auras fait tout ?a, pas avant.');
INSERT INTO `npc_questions` VALUES (4660, '', '', '', '', 'Les documents que tu avais r?cup?r? sur notre espion r?v?lent l\\\'emplacement du chaudron primordial qui, selon la l?gende, aurait permis de cuisiner en moins d\\\'une journ?e assez de nourriture pour combler l\\\'app?tit des dragons lors de leur unique banquet. Ca m\\\'?tonnerait que le chaudron soit mis en ?vidence au milieu des bois, il doit ?tre bien cach? et difficile d\\\'acc?s. Passe le coin au peigne fin, les documents sont formels sur l\\\'emplacement. Quant aux documents que les Bontariens ont tent? de nous d?rober, ils comportent les ingr?dients n?cessaires ? la pr?paration d\\\'un plat irr?sistible pour Turorte. Comme tu t \\\'en doutes, je compte m\\\'en servir en plus du grattoir pour amadouer cette maudite tortue.');
INSERT INTO `npc_questions` VALUES (4661, '', '', '', '', 'Je me moque qu\\\'il soit difficile de trouver les ingr?dients ou du monde pour t\\\'aider. Si tu perds trop de temps les Bontariens vont rattraper leur retard.');
INSERT INTO `npc_questions` VALUES (4662, '', '', '', '', 'Tu as suivi scrupuleusement la recette ? Tu n\\\'as pas ajout? de touche personnelle ? De toute mani?re il faudra se contenter de ?a, nous n\\\'avons plus le temps d\\\'en pr?parer une deuxi?me. Il te reste du Philtre de Long?vit? par hasard ?');
INSERT INTO `npc_questions` VALUES (4663, '', '', '', '', 'Alors mis?rable tu veux que je t\\\'emm?ne ? Br?kmar ? \\nCe n\\\'est pas une cit? fa?te pour les pleutres, elle a ?t? b?tie sur un ancien champ de bataille, ses murs sont encore souill?s par le sang de nos adversaires, ses douves sont remplies de la col?re de Rushu, et moi, oui moi, je d?capite les novices qui manquent de respect ? notre cit? et qui osent critiquer ma dragodinde. Il para?t qu\\\'elle n\\\'est pas assortie ? mes couleurs. N\\\'importe quoi. \\nBon tu veux que ma monture t\\\'emm?ne jusqu\\\'au zaap de Br?kmar ? Il faudra d\\\'abord que tu prennes le temps de la caresser.');
INSERT INTO `npc_questions` VALUES (4664, '', '', '', '', 'Apw?s ta visite, j\\\'ai compwis qu\\\'il ?tait temps pouw moi de pwendwe ma wevanche suw Tuwowte. Je suis un combattant loyal, si tu le souhaites nous pouwwons attaquew Tuwowte ensemble. Il te suffiwa pouw ?a d\\\'engagew le combat et je viendwai t\\\'aidew.');
INSERT INTO `npc_questions` VALUES (4665, '', '', '', '', 'Hors de ma vue gredin ! Flibustier des tourbi?res naus?abondes ! Empailleur de scarafeuilles ! Ebouillanteur de Pious roses ! \\nQue Rushu te fasse vomir de la Filtounga par les oreilles !');
INSERT INTO `npc_questions` VALUES (4666, '', '', '', '', 'Que fais-tu encore ici ? Les autres miliciens sont d?j? en train de retarder les Bontariens mais ils ne pourront pas le faire ?ternellement. D?p?che-toi de me rapporter la Corne Edfrit.');
INSERT INTO `npc_questions` VALUES (4667, '', '', '', '', 'Quoi ? Ai-je bien entendu ce que tu viens de me dire ? Triple andouille ! Fiente de Ouassingue ! Face de Bitouf a?rien ! \\nHors de ma vue avant que je te tue !');
INSERT INTO `npc_questions` VALUES (4668, '', '', '', '', 'D\\\'apr?s un r?cent rapport, nous avons toujours une longueur d\\\'avance sur les Bontariens. Tu vas te rendre sur l\\\'?le de Moon et convaincre Turorte de nous r?v?ler l\\\'emplacement de la Corne Edfrit en ?change du Grattoir ? dos Spentox. \\nHmm, offre-lui d\\\'abord la Salace fourr?e au pollen, ?a endormira peut-?tre sa m?fiance. Il vaut mieux mettre toutes les chances de notre c?t?. Je vais envoyer les autres miliciens retarder les Bontariens, donc ne compte pas sur leur aide pour cette mission.');
INSERT INTO `npc_questions` VALUES (4669, '', '', '', '', 'C\\\'est donc de toi que Dr?na Nassema parlait. Ne t\\\'inqui?te pas, voyant que tu ?tais en mauvaise posture il n\\\'a pas voulu te g?ner et il s\\\'est pr?sent? ici de lui-m?me. Sans ton aide, il serait encore pi?g? au fond du donjon des squelettes. Tu as fait du bon travail, je n\\\'oublierai pas d\\\'en parler ? Amayiro.');
INSERT INTO `npc_questions` VALUES (4670, '4012', '', '', '', 'H?h?, quel bon coup de grisou t\\\'am?ne jusqu\\\'ici jeunot ? \\nJe parie ma bougie que tu veux passer de l\\\'autre c?t? ! \\nJ\\\'?tais comme toi avant, un peu fou, d?lur?, et souvent compl?tement ? l\\\'ouest. Mais les ann?es ont pass?, et j\\\'ai pris de la bouteille. Bon d\\\'accord j\\\'ai ?galement pris beaucoup de bouteilles. Mais c\\\'?tait ? chaque fois pour une bonne cause, tu sais pour tuer les microbes qui se cachent dans ma gorge. Il fallait bien les noyer. Je ne pouvais pas faire ?a avec de l\\\'eau. Les pauvres ils ne m?ritaient pas ?a. \\nBon, tu vas me saouler encore longtemps avec tes histoires ?');
INSERT INTO `npc_questions` VALUES (4671, '', '', '', '', 'Bien aimable vous ?tes, et succulente cette salace est. Un grattoir ? dos Spontex pour moi vous avez apport? ? mmmmmh, ne pas l\\\'accepter je devrai. Depuis des ann?es le dos je ne puis me gratter, conclure un march? alors je vais. Contre le grattoir l\\\'emplacement de la Corne Edfrit je vais vous r?v?ler. \\nDe l\\\'?le au nord-est, pr?s d\\\'une statue de ph?nix la corne se trouve. \\nMaintenant me reposer je vais, car soporifique la salace ?tait...');
INSERT INTO `npc_questions` VALUES (4672, '', '', '', '', 'A pr?sent j\\\'ai une autre t?che ? te confier. Une Sram me doit de l\\\'argent et ?a fait d?j? deux mois que la date de remboursement est arriv?e ? expiration. Elle doit s?rement ?tre fauch?e ? l\\\'heure actuelle alors trouve-la et ?limine-la. Ne la laisse pas t\\\'embobiner car c\\\'est une baratineuse de premi?re et si tu l\\\'?coutes tu te retrouveras fauch?. Crois-moi, je sais de quoi je parle. \\nJe t\\\'arr?te tout de suite dans tes pens?es ! Elle ne m\\\'a pas embobin? et ce n\\\'est pas pour ?a qu\\\'elle me doit de l\\\'argent, je suis bien trop malin pour elle, t\\\'as compris ? \\nC\\\'est une joueuse inv?t?r?e, tu devrais pouvoir la trouver en fouillant les salles de jeux clandestines.');
INSERT INTO `npc_questions` VALUES (4673, '', '', '', '', 'Mais !? Qui ?tes-vous ? Pourquoi fouillez-vous ici ?');
INSERT INTO `npc_questions` VALUES (4674, '', '', '', '', 'Un Br?kmarien !! Mais comment avez-vous appris l\\\'emplacement de la corne ? \\nBon, de toute fa?on je vais devoir vous renvoyer d\\\'o? vous venez ! En garde !');
INSERT INTO `npc_questions` VALUES (4675, '', '', '', '', 'Tr?s fatigu?e je suis, de repos j\\\'ai besoin. Oui, de beaucoup de repos j\\\'ai besoin.');
INSERT INTO `npc_questions` VALUES (4676, '', '', '', '', 'Les Br?kmariens sont les serviteurs des d?mons, Jiva soit lou?e de nous prot?ger d\\\'eux. Or l\\\'exp?rience a prouv? ? maintes reprises qu\\\'il fallait se m?fier des d?mons, ces ?tres vils et perfides qui corrompent tout ce qu\\\'ils touchent. Malheureusement, le m?tal et la ruse ne suffisent pas pour gagner contre eux, ainsi ai-je song? ? augmenter la puissance magique de nos arm?es et le nombre de sortil?ges ? leur disposition. Comme je suis quelqu\\\'un de g?n?reux, j\\\'ai pens? partager cette id?e avec toi afin que tu puisses profiter de la r?ussite de cette mission.');
INSERT INTO `npc_questions` VALUES (4677, '', '', '', '', 'Avant de r?pandre tes organes sur les murs j\\\'ai une petite mission pour toi. D\\\'habitude ce sont les jeunes recrues qui s\\\'en occupent mais ton ?chec r?cent m?rite une sanction. \\nSi la corne est aussi puissante qu\\\'on le dit, Bonta a maintenant un atout de poids ! Nous devons nous pr?parer ? une attaque ! \\nDonne une de ces caisses ? certains des guerriers de la cit?, pour am?liorer leur ?quipement : les guerriers sont Brank Thoof, Kad Maxy, Jack Rottance, et Xale DuGros.');
INSERT INTO `npc_questions` VALUES (4678, '', '', '', '', 'Ah, mon nouvel ?quipement est arriv?. Tu remercieras Oto de ma part. Euh non, ne le remercie pas, il pourrait me punir.');
INSERT INTO `npc_questions` VALUES (4679, '', '', '', '', 'Ah, enfin de quoi remplacer ma lance mit?e.');
INSERT INTO `npc_questions` VALUES (4680, '', '', '', '', 'Une caisse d\\\'?quipement ? Ouais, ?a peut toujours servir.');
INSERT INTO `npc_questions` VALUES (4681, '', '', '', '', 'Hmm, je rendrais bien cette caisse ? Oto en lui disant ce que j\\\'en pense, mais il risquerait de me faire monter en grade en voyant mon insoumission. Et j\\\'ai pas envie.');
INSERT INTO `npc_questions` VALUES (4682, '', '', '', '', 'Mes espions m\\\'ont confirm? la r?cup?ration de la Corne Edfrit par les Bontariens. Ils ne vont pas tarder ? l\\\'utiliser contre nous alors d?p?che-toi d\\\'?quiper nos miliciens.');
INSERT INTO `npc_questions` VALUES (4683, '', '', '', '', 'L\\\'?quipement de ces caisses est pourri, mais d?j? moins que celui qu\\\'ils ont actuellement.');
INSERT INTO `npc_questions` VALUES (4699, '', '', '', '', 'Certainement. Voil?, c\\\'est fait.');
INSERT INTO `npc_questions` VALUES (4751, '', '', '', '', 'Tu as fais en sorte que les cambrioleurs ne soient plus une menace ? Tr?s bonne initiative m?me si j\\\'aurai pr?f?r? qu\\\'ils viennent grossir les rangs de mes sbires. D\\\'un autre c?t?, quelques incomp?tents de plus ou de moins, quelle diff?rence ?');
INSERT INTO `npc_questions` VALUES (4753, '', '', '', '', 'Comment ? Les cambrioleurs t\\\'ont mis une racl?e mais ensuite tu t\\\'es point? dans leur repaire pour les convaincre de venir grossir les rangs de la milice ? Voil? un excellent r?flexe br?kmarien ! N\\\'oublie jamais que plus les gens sont fourbes, plus ils m?ritent de se joindre ? notre cause.');
INSERT INTO `npc_questions` VALUES (4756, '', '', '', '', 'C\\\'est Merlan qui vous envoie ? Alors je vais vous expliquer comment proc?der. J\\\'ai d?j? pr?par? le terrain, il ne manque que des paysans, des alchimistes, la potion et le sortil?ge. \\nLes paysans se placent sur les marques blanches. Il faut que ces paysans soient capables de cultiver l\\\'avoine sinon ils risquent de tout faire rater. Les alchimistes se placent sur les marques noires et pour ?tre certain qu\\\'ils font l\\\'affaire, ils doivent ?tre capables d\\\'utiliser des orchid?es freyesques dans leurs potions. Si vous ?tes vous-m?me paysan ou alchimiste, vous pouvez vous mettre sur l\\\'une des marques blanches ou noires. Dans le cas contraire, vous attendez que les paysans et les alchimistes soient plac?s et vous me pr?venez pour que nous puissions commencer.');
INSERT INTO `npc_questions` VALUES (4809, '', '', '', '', 'Pnj(180) et Message(4808)');
INSERT INTO `npc_questions` VALUES (4835, '', '', '', '', 'Pnj(987) et Message(4834)');
INSERT INTO `npc_questions` VALUES (4876, '', '', '', '', 'Pnj(992) et Message(4875)');
INSERT INTO `npc_questions` VALUES (4880, '', '', '', '', 'Tu te souviens de la corne magique r?cup?r?e sur l\\\'?le de Moon ? Comme Br?kmar sait qu\\\'elle est en notre possession mais ignore son pouvoir, j\\\'ai imagin? un subterfuge pour faire croire ? nos ennemis qu\\\'elle d?tenait de puissants pouvoirs. J\\\'ai toutefois besoin de personnes de confiance pour la mise en sc?ne. Va donc les trouver. \\nIl s\\\'agit du Capitaine Koda, de Ture Inge, de la bijouti?re Marge Gondersun et du milicien Niamuh Boulkier.');
INSERT INTO `npc_questions` VALUES (4881, '', '', '', '', 'Hmmm, si, effectivement. Bon, ?coute, on va s\\\'arranger : met une racl?e ? ce fichu mioche, et fais-moi croire que tu as perdu. Je ferai comme si c\\\'?tait vrai.');
INSERT INTO `npc_questions` VALUES (4882, '', '', '', '', 'Mes amis ont-ils accept? de m\\\'aider ?');
INSERT INTO `npc_questions` VALUES (4883, '', '', '', '', 'Tu peux dire ? Amayiro qu\\\'il pourra compter sur mon aide et celle de mes hommes.');
INSERT INTO `npc_questions` VALUES (4884, '', '', '', '', 'Les ordres sont les ordres, je serai pr?sent au moment voulu.');
INSERT INTO `npc_questions` VALUES (4885, '', '', '', '', 'Amayiro a besoin de moi ? Ca me ferait plaisir de l\\\'aider, bien s?r. Vous pouvez lui dire qu\\\'il suffira de me pr?venir avec au moins un jour d\\\'avance pour que je puisse fermer la boutique et mettre la client?le au courant.');
INSERT INTO `npc_questions` VALUES (4886, '', '', '', '', 'Si Amayiro a un plan contre Br?kmar, ce sera avec honneur que j\\\'y participerai.');
INSERT INTO `npc_questions` VALUES (4887, '', '', '', '', 'Tr?s bien, voici mon plan : je vais faire croire aux Br?mariens que la Corne Edfrit poss?de le pouvoir de d?truire les murailles et de paralyser ceux qui se trouvent en face d\\\'elle lorsqu\\\'on souffle dedans. Le gros oeuvre est pratiquement pr?t mais il me reste quelques d?tails ? r?gler, et j\\\'ai encore besoin de ton aide. Il me faut suffisamment de miteters pour rendre la roche friable et de la graisse de gel?e royale pour terminer la potion de paralysie que les volontaires boiront au moment opportun.');
INSERT INTO `npc_questions` VALUES (4888, '', '', '', '', 'Effectivement. Bon, dans ce cas je t\\\'autorise ? le battre : je ferai comme si tu avais perdu.');
INSERT INTO `npc_questions` VALUES (4889, '', '', '', '', 'Comment ? Tu es arriv? trop tard, et tous nos soldats ?taient d?j? vaincus ? Aie. Nous sommes vraiment moins bien efficaces que Br?kmar. C\\\'est pr?occupant.');
INSERT INTO `npc_questions` VALUES (4890, '', '', '', '', 'Alors, as-tu r?ussi ? obtenir ce que je t\\\'ai demand? ?');
INSERT INTO `npc_questions` VALUES (4891, '', '', '', '', '(Soudain, tout devient noir et vous tombez au sol. Attaquer Turorte n\\\'?tait peut-?tre pas une si bonne id?e.)');
INSERT INTO `npc_questions` VALUES (4892, '', '', '', '', 'Merci, gr?ce ? ton aide nous allons pouvoir mettre ?a en place rapidement. Tu devrais aller te changer les id?es, le travail de milicien n\\\'est pas de tout repos et il est rare d\\\'avoir du temps libre devant soi. Si tu ne l\\\'as pas encore fait, n\\\'oublie pas que tu peux te choisir une sp?cialit? aupr?s de l\\\'un des ma?tres d\\\'ordre ? la Tour de Bonta.');
INSERT INTO `npc_questions` VALUES (4904, '', '', '', '', 'Pnj(679) et Message(4903)');
INSERT INTO `npc_questions` VALUES (4956, '', '', '', '', 'Pnj(997) et Message(4955)');
INSERT INTO `npc_questions` VALUES (5038, '', '', '', '', 'Pnj(997) et Message(4972)');
INSERT INTO `npc_questions` VALUES (5115, '', '', '', '', 'Pnj(1011) et Message(5114)');
INSERT INTO `npc_questions` VALUES (5116, '', '', '', '', 'Bonjour, je suis tr?s occup? pour l\\\'instant. Je suis en train de travailler sur une potion d\\\'invincibilit?. Si on me d?range sans arr?t je ne pourrai jamais y arriver.');
INSERT INTO `npc_questions` VALUES (5117, '', '', '', '', 'Je suis un capitaine de la milice de Br?kmar. Pour tout dire, je songe ? d?serter prochainement. Marre de ne jamais avoir de promotion apr?s toutes ces journ?es de loyaux services.');
INSERT INTO `npc_questions` VALUES (5144, '', '', '', '', 'Pnj(180) et Message(5142)');
INSERT INTO `npc_questions` VALUES (5156, '', '', '', '', 'Bonjour, en quoi puis-je vous ?tre utile ?');
INSERT INTO `npc_questions` VALUES (5157, '', '', '', '', 'Si Amayiro a un plan pour tourner Br?kmar en bourrique, ce sera avec honneur que j\\\'y participerai.');
INSERT INTO `npc_questions` VALUES (5169, '', '', '', '', 'Je comprends pas. Pourquoi personne veut de ma bi?re ? Y a des vrais morceaux de ferraille dedans !');
INSERT INTO `npc_questions` VALUES (5256, '', '', '', '', 'J\\\'ai des entretiens sur cette affaire. Reviens me voir un peu plus tard.');
INSERT INTO `npc_questions` VALUES (5287, '', '', '', '', 'Pnj(305) et Message(5284)');
INSERT INTO `npc_questions` VALUES (5376, '', '', '', '', 'Je ne serai pas retenu prisonnier longtemps. Mes fr?res br?kmariens me lib?reront !');
INSERT INTO `npc_questions` VALUES (5384, '', '', '', '', 'Est-ce ton dernier mot ?');
INSERT INTO `npc_questions` VALUES (5402, '4531', '', '', '0', 'Allez chante avec moi ce refrain : \\\"Bibi bibi bibi Bibiblop. Dans les Plaines Rocheuses. T\\\'es l\\\'roi des Blops. Bibi bibi bibi Bibiblop. Ton amiti?. Dure comme le roc.\\\"  \\nTu ne veux pas chanter avec moi ? Tu veux juste rentrer dans ce donjon ? Donne-moi la clef et je te laisserai entrer.');
INSERT INTO `npc_questions` VALUES (5403, '4532;4533;4534;4535', '', '', '', 'Allez chante avec moi ce refrain : \\\"C\\\'est mon ami, Bibi. Quel beau Bibiblop. Il est super gentil. Comme un b?b? Blop. Quand j\\\'ai besoin de lui. J\\\'appelle Bibiblop. Si son Biblop fait Blop. Il fonce droit dans la vie...\\\". \\nTu ne veux vraiment pas chanter avec moi ? \\nBon dans quelle salle veux-tu aller ?');
INSERT INTO `npc_questions` VALUES (5410, '4540;4544;6624', '', '', '', 'Allez chante avec moi ce refrain : \\\"Quand on appelle Bibi. Il est toujours l?. En descendant la vie. Il fonce vers toi. Dans le vert des Plaines Rocheuses. Il nous fait tous r?ver. A la chasse aux m?chants. Il est toujours gagnant...\\\".\\nMais tu ne sais pas chanter ?\\nBon que veux-tu faire d?sormais ? Sortir de ce donjon ? Si tu as la clef de l\\\'antre du Blop Multicolore Royal, je peux t\\\'y amener.');
INSERT INTO `npc_questions` VALUES (5447, '', '', '', '', 'Au coeur des mar?cages naus?abonds se trouve un sanctuaire o? se regroupent les ?mes des familiers d?funts. Mon anc?tre Oshima y a ?lu r?sidence, et il peut ramener ? la vie votre d?funt compagnon.');
INSERT INTO `npc_questions` VALUES (5448, '', '', '', '', 'Normalement, il faut traverser les mar?cages. Je connais cependant un moyen s?r de parvenir jusqu\\\'au sanctuaire sans avoir ? affronter les horribles crocodailles. \\nAvant de vous en dire plus, j\\\'ai un service ? vous demander. J\\\'ai appris qu\\\'Alta?r distribue des chachas dans le donjon des bouftous ? tout aventurier qui se pr?sente ? lui. Malheureusement, nombre de ces gens n\\\'ont que faire de ces fragiles cr?atures et les laisse mourir de faim voire pire, les abandonnent dans une poubelle d\\\'Astrub. \\nSi vous sauvez un chacha et que vous me l\\\'apportez, je vous dirai mon secret.');
INSERT INTO `npc_questions` VALUES (5449, '', '', '', '', 'Seuls les aventuriers chevronn?s osent s\\\'aventurer l?-bas. Vous ?tes encore trop faible pour survivre ? une rencontre avec les crocodailles. Revenez me voir lorsque vous vous serez aguerri.');
INSERT INTO `npc_questions` VALUES (5451, '', '', '', '', 'A l\\\'est d\\\'ici se trouve une grotte. N\\\'importe qui peut y entrer, mais je n\\\'autorise que quelques rares personnes ? emprunter l\\\'arche de t?l?portation. De plus, l\\\'arche ne peut ?tre activ?e que par quatre personnes en qui j\\\'ai confiance. \\nSi vous souhaitez l\\\'utiliser, trouvez d\\\'abord trois autres personnes qui, comme vous, ont soustrait un chacha ? une mort certaine.');
INSERT INTO `npc_questions` VALUES (5452, '7491;7490', '', '', '0', 'Bonjour, la D?esse Eniripsa m\\\'a donn? le pouvoir d\\\'aider les jeunes ?mes ? r?parer leurs erreurs de jeunesse. \\nLorsque tu n\\\'auras plus acc?s ? Incarnam, les seuls moyens que tu auras ? ta disposition pour d?sapprendre un sort ou r?partir ? nouveau tes points de caract?ristiques seront de combattre les dopeuls de temple ou de qu?rir l\\\'aide de l\\\'alchimiste Otoma?. \\nAttention ! Avec les dopeuls, tu ne pourras faire le changement de caract?ristiques qu\\\'une seule fois. Seul Otoma? conna?t le moyen de le faire plusieurs fois sur une ?me exp?riment?e.');
INSERT INTO `npc_questions` VALUES (5453, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5459, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5460, '', '', '', '', 'Mo? meurs de faim ! M?a vouloir Pomme !');
INSERT INTO `npc_questions` VALUES (5461, '', '', '', '', 'To? conna?tre blague d\\\'ours polaire qui rentrer dans taverne ?');
INSERT INTO `npc_questions` VALUES (5462, '', '', '', '', 'Miam !');
INSERT INTO `npc_questions` VALUES (5463, '', '', '', '', 'Ehhh, cousin ? mo? avoir racont? ? to? aussi ?');
INSERT INTO `npc_questions` VALUES (5464, '', '', '', '', 'Ah, To? pas conna?tre cousin mo? ? Lui ?tre Ronan le Barbare. Lui se balader pr?s de Br?kmar.');
INSERT INTO `npc_questions` VALUES (5465, '', '', '', '', 'Ours entrer Taverne. Ours dire : ? Mo? voulo?r Bi?re d\\\'Astrub ...');
INSERT INTO `npc_questions` VALUES (5466, '', '', '', '', '... et no? de p?kan ! ? ');
INSERT INTO `npc_questions` VALUES (5467, '', '', '', '', 'Ahah, To? aussi trouver ?a dr?le ? Mo? aussi aimer blague ... \\nPar contre mo? pas avoir compris blague ..  \\nTo? peut expliquer mo? ?');
INSERT INTO `npc_questions` VALUES (5468, '', '', '', '', 'Mais enfin tu ne comprends pas que tout le comique de la situation est intrins?quement contenu dans l\\\'incongruit? des circonstances qui am?nent un ours, plantigrade d?nu? de parole, ? demander une bi?re dans une taverne ... ? moins, qu\\\'effectivement, ce ne soit le fait de ne pas s\\\'en ?tonner.');
INSERT INTO `npc_questions` VALUES (5469, '', '', '', '', 'Pfff, to? pas avoir humour !');
INSERT INTO `npc_questions` VALUES (5470, '', '', '', '', 'Quo? ? To? aimer no? p?kan ? Miam ! Mo? pr?f?rer P?oomme.');
INSERT INTO `npc_questions` VALUES (5471, '4580;6622;4586', '', '', '', 'Bonjour, je suis Ernesto Rouste, c?l?bre mycologue et grand bastonneur ? mes heures perdues. J\\\'ai d?tourn? l\\\'art du Pandawushu, pour cr?er ma propre ?cole martiale, bas?e sur la d?capitation des Fungus. Et sans les mains s\\\'il te pla?t ! \\nBon, allons ? l\\\'essentiel. Que veux-tu savoir ? \\n');
INSERT INTO `npc_questions` VALUES (5472, '', '', '', '', 'Mo? aimer petit Parc !');
INSERT INTO `npc_questions` VALUES (5473, '', '', '', '', 'M?a venir de temps en temps, mo? aimer Parc. mo? aimer Parc et P?mmmes ! ... et bl?gues aussi !');
INSERT INTO `npc_questions` VALUES (5475, '', '', '', '', 'Mo? aimer parc et aimer b?nnne p?mmme et aimer bl?gue dr?oole !');
INSERT INTO `npc_questions` VALUES (5476, '', '', '', '', 'Ougah est une divinit? mineure avec une t?te de champignon. C\\\'est un d?tail tr?s important crois-moi. On raconte qu\\\'elle est v?n?r?e par les Porcos. Des aventuriers lui offrent aussi des offrandes dans un but qu\\\'eux seuls connaissent. Diff?rents autels sont dispers?s aux quatre coins du continent pour le culte de ce dieu mineur. Quant ? moi, je me contente d\\\'inciter les aventuriers de passage ? aller se faire botter le derri?re par Ougah, c\\\'est toujours tr?s dr?le ? regarder.');
INSERT INTO `npc_questions` VALUES (5477, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5479, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5480, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5482, '4590', '', '', '', 'Je suis Lina, fi?re mercenaire d\\\'Astrub. On nous a signal? la pr?sence suspecte d\\\'un gobelin farceur dans les parages et je fais une petite enqu?te de routine.');
INSERT INTO `npc_questions` VALUES (5483, '4591', '', '', '', 'Ce gobelin semble s\\\'appeler Ronan. Il n\\\'est pas plus haut que 3 pommes mais avec un amour d?mesur? pour celles-ci. ? premi?re vue, il ne semble pas dangereux.');
INSERT INTO `npc_questions` VALUES (5484, '4592', '', '', '', 'Je ne sais pas ce que ce gobelin trouve aux pommes, c\\\'est plein de p?pins. \\nJe pr?f?res les fruits ? noyaux, tels que les p?ches, les abricots et les cerises.');
INSERT INTO `npc_questions` VALUES (5485, '4594;4593', '', '', '', 'Ah ? Et quelle est selon-vous la plus belle des fleurs ?');
INSERT INTO `npc_questions` VALUES (5486, '4597', '', '', '', '*rougit*  \\nVil flatteur.');
INSERT INTO `npc_questions` VALUES (5487, '', '', '', '', 'Si vous aimez la flore, discutez donc avec Erty, c\\\'est un botaniste averti.');
INSERT INTO `npc_questions` VALUES (5488, '', '', '', '', 'Oh ! Esp?ce de malotru !  \\nApprenez donc ? vous adressez autrement ? une dame !');
INSERT INTO `npc_questions` VALUES (5489, '11941', '', '', '', 'Je t\\\' ai vu affronter Ougah. Tu pourrais presque pr?tendre ? devenir un de mes disciples si seulement tu savais un peu mieux t\\\'habiller. Tu fais peine ? voir. Regarde-moi ces couleurs... ');
INSERT INTO `npc_questions` VALUES (5490, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5491, '', '', '', '', 'Quel rang souhaites-tu avoir au sein de la milice ?');
INSERT INTO `npc_questions` VALUES (5492, '', '', '', '', 'Bien le bonjour. \\nAfin de renforcer les liens entre les Pandawas et les autres races du Monde des Douze, la d?esse Pandawa a d?cid? que les nouvelles ?mes fra?chement incarn?es appara?tront d?sormais dans la cit? d\\\'Astrub, au pied de sa statue nouvellement ?rig?e. C\\\'est une bonne nouvelle, tu ne trouves pas ?');
INSERT INTO `npc_questions` VALUES (5493, '', '', '', '', 'Bonjour, je suis ravie de te voir. \\nJ\\\'ai besoin de gaillards solides dans ton genre pour m\\\'aider dans mes affaires. Je peux te proposer un travail simple et bien pay?, mais tu devras te montrer discret et ne pas poser de questions. \\nQu\\\'en dis-tu ?');
INSERT INTO `npc_questions` VALUES (5494, '4613;4614;4615;4616', '', '', '', 'L\\\'an dernier y a plein de gamins qui entraient dans c\\\'te grotte... et tr?s peu qui en r\\\'sortaient ! \\nAlors on a d?cid? d\\\'en faire une attraction, pour le moment on cherche not\\\' public, alors c\\\'est gratos ! \\nTu veux entrer ?');
INSERT INTO `npc_questions` VALUES (5495, '', '', '', '', 'Pnj(795) et Message(5494)');
INSERT INTO `npc_questions` VALUES (5496, '', '', '', '', 'Ne fais pas cette t?te, on dirait que t\\\'as vu un mort ! \\nTu te demandes sans doute pourquoi je t\\\'ai aid?, n\\\'est-ce pas ? \\nT\\\'emballes pas, je n\\\'ai pas fais ?a par altruisme. En fait, j\\\'ai ?t? pay? pour te suivre et m\\\'assurer que tu ne t\\\'attirerais pas d\\\'ennuis dans la cit? d\\\'Astrub. Je ne sais pas ce que ces Pandawas te voulaient, mais tu ferais mieux d\\\'aller voir mon employeur. Tu n\\\'auras aucun mal ? le reconna?tre, c\\\'est le Pandawa qui t\\\'a accueilli au moment de ton arriv?e sur le Monde des Douze.');
INSERT INTO `npc_questions` VALUES (5499, '', '', '', '', 'Bonjour, fais vite car d\\\'autres recrues r?clament mon attention.');
INSERT INTO `npc_questions` VALUES (5506, '', '', '', '', 'Burger Kimbo ! Riz Cola en sauce ! Joues d\\\'Ouginak ! Pur?e de cawottes ! \\nHum hum... Vous voyez pas que je travaille ?');
INSERT INTO `npc_questions` VALUES (5509, '', '', '', '', 'Tiens, un Bontarien. Qu\\\'est-ce que je dois faire dans ces cas-l?, d?j? ? Bah, peu importe... de toute fa?on c\\\'est aux sous-fifres de s\\\'en occuper, pas au capitaine.');
INSERT INTO `npc_questions` VALUES (5516, '', '', '', '', 'Bonjour, tu es sans doute au courant que les batailles entre les cit?s rivales sont de plus en plus fr?quentes. Pour cette raison, de nombreux soldats se lassent de ces combats incessants et d?sertent ? la premi?re occasion, vivant alors comme des fugitifs. \\nNotre bon roi Allister a piti? de ces gens et leur offre une seconde chance ici, sur le territoire d\\\'Amakna. Du coup je peux r?diger des documents officiels attestant de la neutralit? des gens qui viennent me voir et en font la demande.');
INSERT INTO `npc_questions` VALUES (5517, '4628', '', '', '', 'Que puis-je pour toi habitant de Br?kmar ?');
INSERT INTO `npc_questions` VALUES (5518, '4628', '', '', '', 'Que puis-je pour toi habitante de Br?kmar ?');
INSERT INTO `npc_questions` VALUES (5519, '4628', '', '', '', 'Que puis-je pour toi habitant de Bonta ?');
INSERT INTO `npc_questions` VALUES (5520, '4628', '', '', '', 'Que puis-je pour toi habitante de Bonta ?');
INSERT INTO `npc_questions` VALUES (5521, '4643;4644;4645;4646;4647;4648;4649;4650;4651;4652;4637;4638', '', '', '', 'Voyons voir... Aucun changement de situation effectu? ces quatorze derniers jours. Les services administratifs d\\\'Amakna vont pouvoir traiter ton dossier.\\nTu vas pouvoir revenir habiter ? Amakna, mais tu perdras ton grade au sein de ta milice et tous les avantages qui sont li?s.\\nLes frais de dossier varient en fonction de ta r?putation et de tes exploits, alors r?fl?chi bien avant d\\\'entamer la proc?dure.\\nAttention ! Il faut mener la proc?dure jusqu\\\'au bout pour redevenir Neutre. Les frais de dossier pour une proc?dure inachev?e ne sont pas rembours?s.');
INSERT INTO `npc_questions` VALUES (5522, '', '', '', '', 'Je suis d?sol?e mais ton pr?c?dent dossier a ?t? valid? il y a moins de deux semaines. Les services administratifs d\\\'Amakna refusent automatiquement toutes les nouvelles demandes de changement de situation dont la derni?re remonte ? moins de quatorze jours. \\nPatiente un peu et reviens me voir plus tard.');
INSERT INTO `npc_questions` VALUES (5523, '4639;4628', '', '', '', 'Si servir Bonta t\\\'int?resse, je peux m\\\'arranger pour te faire des papiers qui attesteront de ton affiliation ? leur milice. Ca me fera gagner du temps et ?a ne te co?tera pas un sou. \\nPourquoi je fais ?a ? Tout simplement parce que Bonta m\\\'offre certains avantages en nature pour chaque nouvelle recrue enr?l?e gr?ce ? moi. Je te sugg?re cependant d\\\'aller voir Snori Nairb ? Astrub avant d\\\'entamer la proc?dure pour rejoindre l\\\'alignement minoritaire, il donne une r?compense ? quiconque souhaite s\\\'engager.');
INSERT INTO `npc_questions` VALUES (5524, '4641;4628', '', '', '', 'Si servir Br?kmar t\\\'int?resse, je peux m\\\'arranger pour te faire des papiers qui attesteront de ton affiliation ? leur milice. Ca me fera gagner du temps et ?a ne te co?tera pas un sou. \\nPourquoi je fais ?a ? Tout simplement parce que Br?kmar me paye grassement pour chaque nouvelle recrue enr?l?e gr?ce ? moi. Je te sugg?re cependant d\\\'aller voir Snori Nairb, ? Astrub, avant d\\\'entamer la proc?dure pour rejoindre l\\\'alignement minoritaire, il donne une r?compense ? quiconque souhaite s\\\'engager.');
INSERT INTO `npc_questions` VALUES (5525, '', '', '', '', 'Merci, gr?ce ? toi je vais pouvoir agrandir ma propri?t? ? Bonta. Bonne chance pour la suite.');
INSERT INTO `npc_questions` VALUES (5526, '', '', '', '', 'Merci, gr?ce ? toi mon compte bancaire ? Br?kmar va d?border. Bon courage pour la suite.');
INSERT INTO `npc_questions` VALUES (5527, '4653', '', '', '', 'Merci. A pr?sent j\\\'ai besoin de ta signature ici pour valider le document officiel. Si tu ne valides pas le document, la proc?dure sera annul?e et les frais ne seront pas rembours?s.');
INSERT INTO `npc_questions` VALUES (5528, '4655;4656;4657', '', '', '', 'Une signature de plus sur le registre est n?cessaire. Sans cette signature, je me verrai dans l\\\'obligation d\\\'annuler la proc?dure et les frais ne seront pas rembours?s.');
INSERT INTO `npc_questions` VALUES (5529, '', '', '', '', 'Bonne chance dans ta nouvelle vie ? Amakna.');
INSERT INTO `npc_questions` VALUES (5532, '', '', '', '', 'Attention, quitter l\\\'Ordre te fera perdre ton titre et tous les b?n?fices qui y sont li?s. De plus, si plus tard tu d?cides finalement de revenir dans nos rangs, tu recommenceras en bas de l\\\'?chelle et devras ? nouveau m?riter ton titre car nous n\\\'appr?cions pas les girouettes. \\nLorsque tu quittes un Ordre, tu peux imm?diatement en rejoindre un nouveau, mais tu ne pourras pas quitter celui-ci avant une semaine. \\nVeux-tu vraiment quitter ton Ordre ?');
INSERT INTO `npc_questions` VALUES (5533, '', '', '', '', 'Coucou ma mignonne, bienvenue ? la taverne de la Bagrutte !');
INSERT INTO `npc_questions` VALUES (5545, '', '', '', '', 'Si tu veux d?couvrir la magnifique ville d\\\'Astrub ainsi que l\\\'immensit? de ce monde, il faudra que tu t?l?charges la version compl?te de DOFUS sur le site officiel www.dofus.com');
INSERT INTO `npc_questions` VALUES (5546, '', '', '', '', 'Que me veux-tu fiente de trooll ? Je suis un important marchand bontarien, je n\\\'ai pas de temps ? perdre avec des individus de ton esp?ce.');
INSERT INTO `npc_questions` VALUES (5547, '', '', '', '', 'Quoi ? Tu veux ma photo ? \\nC\\\'est bourr? de courant d\\\'air ici et je n\\\'arrive pas ? garder une forme stable. Ca te faire rire en plus? \\nEt puis l\\\'?clairage est pourri. Qui s\\\'est occup? de la d?coration ? M?me dans la tourbi?re d\\\'Otoma? c\\\'est plus joli.');
INSERT INTO `npc_questions` VALUES (5549, '4740;4739', '', '', '0', 'BONJOUR ! Tu peux me passer des kamas s\\\'il-te-pla?t ?');
INSERT INTO `npc_questions` VALUES (5550, '', '', '', '', 'C\\\'est affreux ce que vous servez dans cette prison ! J\\\'ai d?j? vu du vomi de Shin Larve et c\\\'?tait plus app?tissant. Br?kmar a embauch? un cuisinier bwork ? \\nReste pas plant? l?, rends-toi utile en faisant un peu de m?nage. Tiens, j\\\'aper?ois un balai l?-bas. Va le chercher et commence ? nettoyer cette fichue prison.');
INSERT INTO `npc_questions` VALUES (5552, '', '', '', '', 'Salutations. As-tu trouv? un moyen d\\\'acc?l?rer la croissance des c?r?ales ?');
INSERT INTO `npc_questions` VALUES (5553, '', '', '', '', 'Alors tu n\\\'as rien ? faire ici ! Cesse de bailler aux corneilles et trouve rapidement une solution.');
INSERT INTO `npc_questions` VALUES (5554, '', '', '', '', 'C\\\'est une bonne nouvelle que tu m\\\'apportes l?. Gr?ce ? la croissance acc?l?r?e des c?r?ales, nous n\\\'aurons plus de probl?me de nourriture pour les dragodindes. Nous pourrons s?rement faire la m?me chose avec les autres c?r?ales pour nourrir les troupes. \\nTe voil? donc Ecuyer.');
INSERT INTO `npc_questions` VALUES (5555, '', '', '', '', 'Je suis tr?s occup?. Si on me d?range sans arr?t comment voulez-vous que je r?ussisse ma potion d\\\'invincibilit? ?');
INSERT INTO `npc_questions` VALUES (5556, '', '', '', '', 'Bon, d\\\'accord, je veux bien t\\\'aider. \\nIl existe effectivement un sort de Transg?n?se mais pour le pr?parer j\\\'ai besoin de temps, d\\\'ingr?dients et surtout de ne pas ?tre d?rang? toutes les trente secondes. \\nAlors il me faut 40 Graines de Pandouille, 20 Graines de Pavot, 20 Poudres de perlinpainpain, 10 Bourgeons de Fourbasse et 2 Liquides vampiresques..');
INSERT INTO `npc_questions` VALUES (5557, '', '', '', '', 'Maintenant il faut que je trouve o? j\\\'ai rang? la formule...\\nAlors c\\\'est tr?s simple : vous mettez une goutte de cette potion sur chaque graine, vous les planter et lorsque vous avez termin?, vous lisez ? voix haute le texte ?crit sur ce parchemin. Vous savez lire, n\\\'est-ce pas ?\\nCe sort ne fonctionne que sur l\\\'avoine donc il faut trouver un champ o? l\\\'utiliser. Il est important de bien faire les choses c\\\'est pourquoi l\\\'aide de plusieurs paysans et alchimistes est n?cessaire. J\\\'ai envoy? quelqu\\\'un pr?parer un champ pour vous, je vais indiquer o? sur votre carte pour que vous ne perdiez pas de temps ? le chercher.');
INSERT INTO `npc_questions` VALUES (5558, '', '', '', '', 'Donc je r?sume : j\\\'envoie deux tofus dans l\\\'atelier d\\\'alchimie pendant que Merlan a le dos tourn?. Le premier tofu mange les graines de pavot et le deuxi?me d?pose les graines de scorbute. Si je suis rep?r?e j\\\'invoque un craqueleur et je cours. Le r?sultat sera l\\\'empoisonnement de l\\\'alimentation de Bonta. J\\\'ai tout bon ?');
INSERT INTO `npc_questions` VALUES (5559, '', '', '', '', 'As-tu d?couvert ce que les Br?kmariens ont derri?re la t?te ?');
INSERT INTO `npc_questions` VALUES (5560, '', '', '', '', 'N\\\'as-tu rien de mieux ? faire que venir me raconter des sottises ?');
INSERT INTO `npc_questions` VALUES (5561, '', '', '', '', 'Ce que tu m\\\'annonces l? est gravissime. Coure ? l\\\'atelier des alchimistes et explique la situation ? Merlan. Prions Silvosse qu\\\'il ne soit pas trop tard.');
INSERT INTO `npc_questions` VALUES (5562, '', '', '', '', 'Ah ben c\\\'est trop tard. Un milicien vient de partir avec la potion et la formule. Pour une fois que j\\\'avais r?ussi du premier coup... Mais si vous vous d?p?chez vous pourrez le rattraper. Montrez-moi votre carte, je vais vous indiquer o? je l\\\'ai envoy');
INSERT INTO `npc_questions` VALUES (5563, '', '', '', '', 'Bonjour, gr?ce ? moi Bonta ne va plus conna?tre la famine. Je me demande d\\\'ailleurs si je ne devrais pas ajouter de la viande de trooll et des moumoules frites aux pains d\\\'avoine pour en faire un menu riche en calories.');
INSERT INTO `npc_questions` VALUES (5564, '', '', '', '', 'Je viens juste d\\\'arriver, je n\\\'ai pas encore jet? le sortil?ge. Si la potion est contamin?e, je pr?f?re vous la confier. Prenez-la.');
INSERT INTO `npc_questions` VALUES (5565, '', '', '', '', 'C\\\'est trop tard, le sort est jet?. Nous allons pouvoir nous gaver sans fin et sans risque pour notre sant?. Ca pour une nouvelle, c\\\'est une bonne nouvelle.');
INSERT INTO `npc_questions` VALUES (5566, '', '', '', '', 'Je suis actuellement un milicien aux ordres de Bonta mais je compte me reconvertir et ouvrir une cha?ne de restaurants ? base de menus riches en calories. Il me reste juste ? trouver des chasseurs de trooll pour la viande et des p?cheurs pour m\\\'approvisionner en moumoules-frites.');
INSERT INTO `npc_questions` VALUES (5567, '', '', '', '', 'Alors comme ?a tu es arriv? ? temps pour emp?cher la contamination des champs, je suis fier de toi. \\nJe t\\\'?l?ve au rang d\\\'Espion. Quelque chose me dit que je ne vais pas tarder ? avoir du travail pour toi. \\nVoil? 1000 kamas pour te r?compenser de tes efforts. \\nAu fait, comment ?a s\\\'est pass? avec Fidji Merline ?');
INSERT INTO `npc_questions` VALUES (5568, '', '', '', '', 'Dommage que tu sois arriv? trop tard. Quoiqu\\\'il en soit ce n\\\'est pas ta faute. Cependant, garde pour toi ce que tu sais sur les c?r?ales modifi?es, il ne faudrait pas que ?a s\\\'?bruite et que les citoyens soient mis au courant. \\nAu fait, comment ?a s\\\'est pass? avec Fidji Merline ?');
INSERT INTO `npc_questions` VALUES (5569, '', '', '', '', 'Salutations. As-tu trouv? La b?n?diction d\\\'Erazal ?');
INSERT INTO `npc_questions` VALUES (5570, '', '', '', '', 'Voyons ce que nous dit cet ouvrage...\\n...\\n... ... ...\\nJ\\\'ai trouv?. Apparemment il existe un rituel pour forcer une ?me ? r?int?grer son corps. Pour cela il faut 1 sang de ph?nix, 15 poudres de perlinpainpain et 1 amulette de Lear, obtenue sur les cadavres des abraknes et des abraknes sombres. Tu sais ce qu\\\'il te reste ? faire.');
INSERT INTO `npc_questions` VALUES (5571, '', '', '', '', 'Salutations. La d?composition des d?pouilles des ren?gats commencent ? incommoder les ge?liers. As-tu apport? les ingr?dients n?cessaires ? leur r?surrection ?');
INSERT INTO `npc_questions` VALUES (5572, '', '', '', '', 'Excellent ! \\nJe vais imm?diatement pr?parer la potion, patiente un instant. \\nVoil?, utilise ceci en conjonction avec l\\\'amulette de Lear selon le rituel d?crit dans La b?n?diction d\\\'Erazal puis reviens ici.');
INSERT INTO `npc_questions` VALUES (5573, '', '', '', '', 'Salutations. As-tu utilis? la potion sur les d?pouilles des ren?gats ?');
INSERT INTO `npc_questions` VALUES (5574, '', '', '', '', 'Tr?s bien, je suis heureux de t\\\'accueillir dans le rang de mes apprentis. \\nLe processus de r?surrection forc?e ?tant assez long, je n\\\'ai plus besoin de toi pour l\\\'instant. Va et veille sur tes compagnons comme notre Protectrice Jiva veille sur toi.');
INSERT INTO `npc_questions` VALUES (5575, '', '', '', '', 'Mais chut je te dis ! Ton livre se trouve ici, non, plus ? droite, voil?. En silence ! Maintenant que tu l\\\'as, ouste !');
INSERT INTO `npc_questions` VALUES (5576, '', '', '', '', 'M?me si les mots sortant de ta bouche sont aussi naus?abonds que ton haleine, je t\\\'?coute.');
INSERT INTO `npc_questions` VALUES (5577, '', '', '', '', 'Ce n\\\'est pas en adoptant un ton mielleux et une t?te de chienchien battu que tu obtiendras quoi que ce soit de moi !');
INSERT INTO `npc_questions` VALUES (5578, '', '', '', '', 'Tu oses me menacer ? Tu ferais mieux de d?guerpir avant que les mercenaires d\\\'Astrub ne s\\\'occupent de ton cas, sale racaille.');
INSERT INTO `npc_questions` VALUES (5579, '', '', '', '', 'Comment oses-tu m\\\'insulter ? Je ne fais pas la manche, pas comme ces gueux ? la banque d\\\'Astrub.');
INSERT INTO `npc_questions` VALUES (5580, '', '', '', '', 'Je ne peux pas trahir Mawy comme ?a. C\\\'est elle qui m\\\'a tout appris et je lui dois ?norm?ment.');
INSERT INTO `npc_questions` VALUES (5581, '', '', '', '', 'Hmm... Je vais r?fl?chir ? ta proposition. Peu m\\\'importe les mani?res douteuses t\\\'ayant permises de te procurer cet argent, du moment que tu payes nous pourrons peut-?tre faire affaire. \\nEn fait, je vais te donner un moyen de me convaincre. Je n\\\'arrive pas ? imposer mes marchandises ? Astrub car Mawy Ingalsse vend ses c?r?ales moins ch?res que les miennes. De plus, ses produits ont bien meilleure r?putation ? cause de sa mani?re de les cultiver. Je ne peux pas m\\\'approcher de son atelier sans ?veiller les soup?ons, mais toi tu dois pouvoir t\\\'y rendre et convaincre Emia Elliesol de saboter le travail. Peu m\\\'importent les moyens employ?s du moment que tu obtiens des r?sultats satisfaisants.');
INSERT INTO `npc_questions` VALUES (5582, '', '', '', '', 'Tu crois que je n\\\'ai que ?a ? faire d\\\'?couter tes j?r?miades ? Parle et dis-moi ce qui t\\\'am?ne.');
INSERT INTO `npc_questions` VALUES (5583, '', '', '', '', 'Tu as r?ussi ? le convaincre ? C\\\'est pas trop mal. Mais pendant que tu jouais les touristes ? Astrub, Bonta a trouv? un moyen d\\\'augmenter sa production c?r?ali?re. \\nTu vas me rapporter 20 Graines de scorbute et cette fois t\\\'as int?r?t ? te d?p?cher, sinon je te colle une semaine d\\\'entra?nement intensif.');
INSERT INTO `npc_questions` VALUES (5584, '', '', '', '', 'Ces 20 graines de scorbute, ?a vient ?');
INSERT INTO `npc_questions` VALUES (5585, '', '', '', '', 'Mouais, une tortue cul de jatte serait all?e plus vite mais les autres miliciens ne sont toujours pas rentr?s, t\\\'as de la chance. Pour la peine, je t\\\'?l?ve au rang de Surineur. Ne r?ve pas trop, je le fais uniquement pour rendre les autres jaloux, tes comp?tences n\\\'ont rien ? voir l?-dedans.');
INSERT INTO `npc_questions` VALUES (5586, '', '', '', '', 'L\\\'?me en question se trouve dans la prison de Br?kmar. Quand ? tes recherches, la biblioth?que me semble un bon endroit pour les d?buter.');
INSERT INTO `npc_questions` VALUES (5587, '', '', '', '', 'C\\\'est quoi cette odeur ? Ta potion empeste l\\\'urine de koalak. C\\\'est ta nouvelle lotion anti-puces ?');
INSERT INTO `npc_questions` VALUES (5588, '', '', '', '', 'Non mais oh, tu te prends pour qui ? Un peu de respect pour tes a?n?s, petite crotte de bouftou. Ta m?re ne t\\\'a pas donn? assez de fess?es quand tu ?tais plus jeune mais je pourrai rem?dier ? ?a d?s que j\\\'aurai r?cup?r? mon corps.');
INSERT INTO `npc_questions` VALUES (5589, '', '', '', '', 'Tu as l\\\'air fatigu?. As-tu ressuscit? Terra Tibya ?');
INSERT INTO `npc_questions` VALUES (5590, '', '', '', '', 'C\\\'est bien, nous allons attendre qu\\\'elle se r?incarne et tu pourras alors l\\\'interroger. Tu rejoins ? pr?sent le rang de mes Apprentis Sombres.');
INSERT INTO `npc_questions` VALUES (5591, '', '', '', '', 'Que m\\\'as-tu fait ? Je sens des picotements dans tout mon corps et ?a fait mal. Vile petite canaille, je suis s?re que c\\\'est ? cause de ton urine. D\\\'ailleurs tu devrais arr?ter d\\\'en boire, ?a d?teint sur ton haleine.');
INSERT INTO `npc_questions` VALUES (5592, '', '', '', '', 'Va donc faire un tour ? Bonta et demande ? Finche Aticus s\\\'il y a du nouveau.');
INSERT INTO `npc_questions` VALUES (5593, '', '', '', '', 'Bonjour camarade Br?kmarien. Ces Bontariens vont me rendre fous avec leur id?ologie utopiste.');
INSERT INTO `npc_questions` VALUES (5594, '', '', '', '', 'Comme d\\\'autres Br?kmariens ont br?l? les entrep?ts de nourriture de la ville, les Bontariens ont demand? ? Merlan l\\\'Encha?neur d\\\'?laborer un sortil?ge visant ? multiplier la croissance des c?r?ales. Pour ma part je ne m\\\'inqui?te pas car ce Merlan est un incapable mais si tu veux en avoir le coeur net, tu peux toujours aller v?rifier par toi-m?me. Il travaille ? l\\\'atelier des alchimistes de la ville.');
INSERT INTO `npc_questions` VALUES (5595, '', '', '', '', 'C\\\'est g?nial ! Alors tout ce qu\\\'il reste ? apporter pour pr?parer le sort de Transg?n?se ce sont 20 Graines de pavot ? Je vais m\\\'en occuper.');
INSERT INTO `npc_questions` VALUES (5596, '', '', '', '', 'C\\\'est pas toi que j\\\'ai envoy? ? Bonta pour savoir ce qui s\\\'y tramait ?');
INSERT INTO `npc_questions` VALUES (5597, '', '', '', '', 'Des graines de pavot ? Int?ressant... Et tu dis qu\\\'il lui en faut 20 ? Je crois que j\\\'ai une id?e : nous allons remplacer les Graines de pavot par des Graines de scorbute. Si ce Merlan est aussi nul que le pr?tend Finche Aticus, il n\\\'y verra que du feu. J\\\'ai sur moi 20 Graines de scorbute fra?chement r?colt?es, je vais les plonger dans du Poison cinglant et modifier leur aspect ? l\\\'aide d\\\'une Teinture Magique Verd?tre. Va me chercher ces objets et reviens vite, il ne faut pas trop tra?ner.');
INSERT INTO `npc_questions` VALUES (5598, '', '', '', '', 'Voici le plan : tu vas te rendre chez ce Merlan et remplacer ses Graines de pavot par ces Graines de scorbute. Attend plut?t la nuit pour faire ?a, sinon tu risques de te faire rep?rer et tout le plan tombera ? l\\\'eau.');
INSERT INTO `npc_questions` VALUES (5599, '', '', '', '', '*roupille*');
INSERT INTO `npc_questions` VALUES (5601, '', '', '', '', 'J\\\'esp?re que tu viens m\\\'annoncer la r?ussite de ta mission.');
INSERT INTO `npc_questions` VALUES (5602, '', '', '', '', 'Cet imb?cile de Merlan ne va y voir que du feu. Quant ? toi, te voil? ? pr?sent Espion Sombre. \\nAlors, heureux ?');
INSERT INTO `npc_questions` VALUES (5603, '', '', '', '', 'Cet imb?cile de Merlan ne va y voir que du feu. Quant ? toi, te voil? ? pr?sent Espionne Sombre. \\nAlors, heureuse ?');
INSERT INTO `npc_questions` VALUES (5604, '', '', '', '', 'C\\\'est une bonne nouvelle que tu m\\\'apportes l?. Gr?ce ? la croissance acc?l?r?e des c?r?ales, nous n\\\'aurons plus de probl?me de nourriture pour les dragodindes. Nous pourrons s?rement faire la m?me chose avec les autres c?r?ales pour nourrir les troupes. \\nTe voil? donc Ecuy?re.');
INSERT INTO `npc_questions` VALUES (5606, '', '', '', '', 'Ce n\\\'est pas que je ne veux pas t\\\'aider, mais j\\\'approche de la retraite et une petite contrepartie en ?change de l\\\'information serait la bienvenue.');
INSERT INTO `npc_questions` VALUES (5607, '', '', '', '', 'Oh, mais c\\\'est de l\\\'or pur. Merci bien. \\nTu voulais donc rencontrer un membre de la famille Terra ? C\\\'est pas de chance pour toi. Mon vieux copain Terra Cogita a ?t? captur? par les bworks il y a plusieurs ann?es et depuis le temps ils ont d? s\\\'en servir comme ap?ritif. D?sol?, je pense pas que tu trouves quoi que ce soit d\\\'utile l?-bas.');
INSERT INTO `npc_questions` VALUES (5610, '', '', '', '', 'Ceti po que je commence ? avoir des hollucinotions. Co y est, le vieux Terra Cogita il perd lo boule.');
INSERT INTO `npc_questions` VALUES (5611, '', '', '', '', 'Ebe v\\\'lo que les bworks ils ont coptur? le vieux Terra Cogita et qu\\\'ils voulaient le faire r?tir mais que l\\\'vieux Terra Cogita il ovait plus que lo peau sur les os et qu\\\'il o dit aux bworks qu\\\'il follait l\\\'ongraisser ovont deul monger. Ceti po queul bworks ils l\\\'ont cr? et engraiss? pondont des onn?es. Que le vieux Terra Cogita l\\\'est po b?te dit. Il mettait les olimonts dons so borbe et les oiseaux ils venaient picorer lo nuit et qu\\\'il grossissait po le vieux Terra Cogita. Ceti trop con un bwork.');
INSERT INTO `npc_questions` VALUES (5612, '', '', '', '', 'Piouf. D\\\'lo bonne bibine qu\\\'il aimerait le vieux Terra Cogita.');
INSERT INTO `npc_questions` VALUES (5613, '', '', '', '', 'Le Vieux Terra Cogita il veut bien un ti coup d\\\'main et en donner mais il veut posser chez les Enutrofs ovont. Si jomais on se perd de vue, je t\\\'ottendrai au temple Enutrof.');
INSERT INTO `npc_questions` VALUES (5614, '', '', '', '', 'Salutations, la famille Terra a-t-elle accept? de nous aider ?');
INSERT INTO `npc_questions` VALUES (5615, '', '', '', '', 'A t\\\'entendre, mettre la main sur cet Enutrof n\\\'a pas ?t? une mince affaire. Va te reposer un peu, Chevalier de l\\\'Espoir, je vais faire plus ample connaissance avec notre invit?. \\nConcernant les Br?kmariens rencontr?s sur la tombe de Terra Tibya, je vais en parler ? Ebru Of El, peut-?tre ses espions ont-ils d?couvert quelque chose que j\\\'ignore.');
INSERT INTO `npc_questions` VALUES (5616, '', '', '', '', 'Les ?mes des ren?gats ont fini par r?int?grer leur corps. Tu vas pouvoir aller les interroger. Je veux savoir quelles informations ils ont d?voil?es aux Br?kmariens. Jiva ne peut tol?rer une telle trahison.');
INSERT INTO `npc_questions` VALUES (5617, '', '', '', '', 'Qu\\\'est-ce qu\\\'elle nous veut la petite milicienne ? Va faire ceci, viens par l?, attends moi, repasse plus tard. Elle va bien la petite bobonne ? ses ma?ma?tres ?');
INSERT INTO `npc_questions` VALUES (5618, '', '', '', '', 'Qu\\\'est-ce qu\\\'il nous veut le petit milicien ? Va faire ceci, viens par l?, attends moi, repasse plus tard. Il va bien le petit chienchien ? ses ma?ma?tres ?');
INSERT INTO `npc_questions` VALUES (5619, '', '', '', '', 'Hahaha. Tu crois peut-?tre que nous allons parler ? Nous connaissons toutes les m?thodes d\\\'interrogatoire de Bonta, et nous ne dirons rien. Va pleurer dans les jupes de ta m?re.');
INSERT INTO `npc_questions` VALUES (5620, '', '', '', '', 'Salutations. Comment se passe l\\\'interrogatoire des ren?gats ?');
INSERT INTO `npc_questions` VALUES (5621, '', '', '', '', 'Hmm... Je vois, ils ne me laissent pas le choix. Puisqu\\\'ils ne veulent rien avouer, il va falloir employer les grands moyens. \\nTu vas te rendre ? Astrub et convaincre l\\\'eni Hoube de venir ? Bonta. Emploie tous les moyens qu\\\'il faut pour le persuader de venir, mais ne le violente pas.');
INSERT INTO `npc_questions` VALUES (5622, '', '', '', '', 'Piti?, je vais tout avouer mais fais-le taire je t\\\'en supplie.');
INSERT INTO `npc_questions` VALUES (5623, '', '', '', '', 'Ca aura ?t? rapide, tu ne trouves pas ? \\nPuisque tu t\\\'en es bien sorti je pense que tu m?rites ton titre d\\\'Adepte des Ecrits. \\nQue Jiva veille sur tes pas.');
INSERT INTO `npc_questions` VALUES (5624, '', '', '', '', '...');
INSERT INTO `npc_questions` VALUES (5625, '4741;4742', '', '', '0', 'Au fait, t\\\'aurais pas quelques kamas en trop ? C\\\'est pour pouvoir acc?der ? ma banque. Je suis l\\\'eniripsa le plus riche d\\\'Astrub mais j\\\'ai laiss? tout mon argent dans mon coffre ? la banque alors je peux plus y acc?der.');
INSERT INTO `npc_questions` VALUES (5626, '4744;4743', '', '', '0', 'T\\\'as pas un petit ?quipement pour moi ? M?me un truc de piou, c\\\'est pas grave. Sauf si c\\\'est bleu parce que je n\\\'aime pas le bleu, le bleu c\\\'est moche. Moi je veux du rouge, ou du rose, ou du violet. Ou des trucs meilleurs si t\\\'as.');
INSERT INTO `npc_questions` VALUES (5627, '4746;4745', '', '', '0', 'Incarnam c\\\'est la meilleure zone o? progresser. Je ne comprends toujours pas pourquoi la plupart des ?mes finissent par quitter ce lieu paradisiaque.');
INSERT INTO `npc_questions` VALUES (5628, '4748;4747', '', '', '0', '*Pense* Je suis le plus fort. \\n*Pense* Je suis le plus fort. \\n*Pense* Je suis le plus fort. \\n*Pense* Je suis le plus fort.');
INSERT INTO `npc_questions` VALUES (5629, '4749;4750', '', '', '0', 'Tu conna?trais pas un aventurier tr?s exp?riment? pour m\\\'emmener avec lui dans des donjons ?');
INSERT INTO `npc_questions` VALUES (5630, '4752;4751', '', '', '0', 'Suit mon conseil : trouve-toi une panoplie du bouftou et ne la quitte plus.');
INSERT INTO `npc_questions` VALUES (5631, '4754;4753', '', '', '0', 'Je prie la d?esse Eniripsa pour qu\\\'elle m\\\'accorde ses gr?ces. Comme ?a, je peux soigner mes amis et castagner mes ennemis. Je peux aussi faire l\\\'inverse, et c\\\'est ?a qui est rigolo.');
INSERT INTO `npc_questions` VALUES (5632, '4755;4756', '', '', '0', 'Je pense que le dieu X?lor accorde trop de pouvoirs ? ses disciples et que les F?cas sont la ris?e de tout Amakna, m?me si personne n\\\'ose leur dire en face.');
INSERT INTO `npc_questions` VALUES (5633, '4758;6093', '', '', '0', 'A ta place je ferai attention : il ne faut pas aller plus loin que les abords d\\\'Astrub, au-del? c\\\'est beaucoup trop dangereux.');
INSERT INTO `npc_questions` VALUES (5634, '4759;4760', '', '', '0', 'Au fait, tu sais ce que ?a veut dire Dofus ? Moi je me pose toujours la question. De plus en plus de gens en parlent et certains disent qu\\\'ils en ont donc j\\\'en ai conclut que c\\\'?tait un objet, comme une paire de bottes ou peut-?tre bien un pain de seigle. Qu\\\'en penses-tu ? Tu le sais toi ce que ?a veut dire Dofus ? Moi je me pose toujours la question, d\\\'autant que de plus en plus de gens en parlent...');
INSERT INTO `npc_questions` VALUES (5635, '4762;4761', '', '', '0', '*Pense* Je pense tellement fort que les gens autour entendent mes pens?es.');
INSERT INTO `npc_questions` VALUES (5636, '4763;4764', '', '', '0', 'J\\\'ai appris plein de choses en ?coutant les gens discuter au zaap. Ils narrent leurs exploits, comment ils ont vaincu des cr?atures mythiques ou d?couverts d\\\'immenses richesses. Ils d?filent avec leur super ?quipement, se d?fient, agressent des gens parfois mais tout ?a dans la joie et la bonne humeur. Le plus impressionnant, c\\\'est leur respect d\\\'autrui. Je t\\\'ai d?j? parl? de leur respect d\\\'autrui ? Non ? Alors il faut que j\\\'arrange ?a.');
INSERT INTO `npc_questions` VALUES (5637, '4765;4766', '', '', '0', 'Tu connais pas la meilleure ? J\\\'ai appris qu\\\'un type s\\\'?tait fait voler son identit? par son meilleur ami et il l\\\'a jamais soup?onn?. Tu te rends compte ? Se faire voler par un ami, c\\\'est impensable. D\\\'ailleurs c\\\'est tellement incroyable que plus j\\\'y pense, moins je pense que c\\\'est vrai. Comment peut-on voler l\\\'identit? de quelqu\\\'un, surtout celle d\\\'un ami ! Toi tu as ton identit?, moi j\\\'ai la mienne, et on peut pas la changer. C\\\'est fou quand m?me.');
INSERT INTO `npc_questions` VALUES (5638, '4768;4767', '', '', '0', 'Tu sais quoi ? Je suis un puissant t?l?pathe. Je peux projeter mes pens?es autour de moi et me faire entendre comme si je parlais normalement, sauf que c\\\'est dans la t?te des gens. Si tu me crois pas je peux te le prouver. Tiens. \\n*Pense* J\\\'ach?te tous vos Sangs du Vampire 1 kama l\\\'unit?, videz vos stocks. \\n*Pense* J\\\'ach?te tous vos Sangs du Vampire 1 kama l\\\'unit?, videz vos stocks ! \\n*Pense* J\\\'ach?te tous vos Sangs du Vampire 1 kama l\\\'unit?, videz vos stocks. \\n*Pense* J\\\'ach?te tous vos Sangs du Vampire 1 kama l\\\'unit?, videz vos stocks ! \\nTu vois, ?a marche. \\n');
INSERT INTO `npc_questions` VALUES (5639, '4769;4770', '', '', '0', 'Hier soir j\\\'ai crois? un bouftou qui s\\\'?tait cass? la patte. Je l\\\'ai soign? comme ?a il a pu marcher jusqu\\\'? chez moi et ensuite j\\\'ai invit? mes amis et nous l\\\'avons fait r?tir. C\\\'est quand m?me pratique les soins, ?a ?vite d\\\'avoir ? porter les blesser.');
INSERT INTO `npc_questions` VALUES (5640, '4774;4775', '', '', '0', 'C\\\'est quoi ton petit nom ? \\nH? oh, je te demande comment tu t\\\'appelles. Pourquoi tu r?ponds pas ?');
INSERT INTO `npc_questions` VALUES (5641, '4777;4776', '', '', '0', 'Pourquoi ton ?me a d?cid? de s\\\'incarner en femme ? Qu\\\'est-ce qui prouve qu\\\'avant elle ne s\\\'?tait pas incarn?e en homme dans une vie ant?rieure ? maintenant ?');
INSERT INTO `npc_questions` VALUES (5642, '4780,4781,4779;4778', '', '', '0', 'C\\\'est qui pour toi les plus belles ? Les sramettes, les sadidettes, les craettes, les bworkettes, les cacahu?tes ?');
INSERT INTO `npc_questions` VALUES (5643, '', '', '', '', 'Pourquoi ton ?me a d?cid? de s\\\'incarner en homme ? Qu\\\'est-ce qui prouve que c\\\'est pas une ?me de femme qui s\\\'est d?guis?e en homme pour pas qu\\\'on la soup?onne ?');
INSERT INTO `npc_questions` VALUES (5644, '', '', '', '', 'T\\\'es super sympa alors je veux bien te rejoindre ? Bonta. Tu me feras visiter car je suis jamais sorti d\\\'Astrub. T\\\'es trop cool, je t\\\'ajoute ? mon cercle d\\\'amis comme ?a je pourrai savoir quand tu viens ici et te parler. Par contre j\\\'ai des trucs ? faire avant alors je te rejoins directement l?-bas d?s que j\\\'ai termin');
INSERT INTO `npc_questions` VALUES (5646, '', '', '', '', 'J\\\'ai suivi ton parcours, Surineur. Tu progresses mais pas assez vite ? mon go?t. Si tu veux obtenir un poste important au sein de notre Ordre, tu vas devoir te remuer plus que ?a.');
INSERT INTO `npc_questions` VALUES (5647, '', '', '', '', 'C\\\'est bien, je vois que tu as de l\\\'ambition. \\nNous allons mettre la main sur les statuettes symboles des biens et des maux de l\\\'humanit?. Lorsque nous y serons parvenus, le monde sombrera dans le d?sespoir, ce qui rendra sa conqu?te plus ais?e. \\nComme Divad Dleifrepok a r?ussi ? obtenir l\\\'emplacement des statuettes, tu vas te rendre sur place pour ?liminer les gardiens, t\\\'emparer des deux statuettes et me les ramener. Toutefois tu peux y aller accompagn? car plus on est de fous, plus on r?pand d\\\'h?moglobine sur les murs. \\nLes statuettes seraient cach?es dans une vieille mine abandonn?e pr?s du temple Enutrof. Setag en a bloqu? l\\\'acc?s mais le syst?me d\\\'ouverture devrait se trouver ? proximit? de l\\\'entr?e. Cherche bien.');
INSERT INTO `npc_questions` VALUES (5648, '', '', '', '', 'Salutations, le mal qui t\\\'accompagne est de plus en plus oppressant, je suis fier de toi ! \\nQuelle est la raison de ta visite ?');
INSERT INTO `npc_questions` VALUES (5649, '', '', '', '', 'Le rituel de la mal?diction d\\\'Erazal a finalement port? ses fruits et Terra Tibya est ressuscit?e. Tu vas aller la voir et l\\\'interroger jusqu\\\'? ce qu\\\'elle t\\\'avoue o? se trouve les statuettes. Libre ? toi de mener l\\\'interrogatoire comme bon te semble.');
INSERT INTO `npc_questions` VALUES (5651, '', '', '', '', 'Ecoute-moi quand je te parle ! J\\\'en ai mat? des plus costauds et ce n\\\'est pas parce que tu m\\\'as enferm?e ici qu\\\'il faut te croire plus malin. \\nJe suis s?re que tu es du genre petite frappe qui cache son complexe d\\\'inf?riorit? en insultant et maltraitant les autres.');
INSERT INTO `npc_questions` VALUES (5652, '', '', '', '', 'Je ne vois pas de quoi tu parles. Et puis ce ne sont pas des mani?res de s\\\'adresser ? une personne ?g?e. Nous n\\\'avons pas ?lev? les bouftons ensemble ? ce que je sache.');
INSERT INTO `npc_questions` VALUES (5653, '', '', '', '', 'Ecoute-moi quand je te parle ! Tu fais ta maline parce que je suis enferm?e derri?re ces barreaux mais s\\\'ils n\\\'?taient pas l? tu prendrais une bonne racl?e. \\nJe suis s?re que tu as obtenue ton poste gr?ce ? une promotion canap?, c\\\'est ce que font toutes les gamines dans ton genre.');
INSERT INTO `npc_questions` VALUES (5654, '', '', '', '', 'Garde tes menaces pour toi. D?s que j\\\'aurai mis la main sur une tige de kalyptus je te collerai une rouste m?morable. \\nMaintenant au lieu de dire des ?neries tu ferais mieux d\\\'aller me chercher le cuistot, j\\\'ai deux mots ? lui dire au sujet de ses plats.');
INSERT INTO `npc_questions` VALUES (5655, '', '', '', '', 'Salutations, on m\\\'a rapport? que tu avais eu quelques d?boires en interrogeant Terra Tibya.');
INSERT INTO `npc_questions` VALUES (5656, '', '', '', '', 'Haha, je vois. Tu as l\\\'esprit retors, j\\\'aime ?a. Malheureusement je n\\\'ai plus de langue hiyeu en stock. Par contre il me reste une canne ? pichon ensorcel?e. Prends-la, je te la confie. Avec ?a tu vas pouvoir aller chercher une langue hiyeu par toi-m?me. \\nSi tu ne le sais pas encore, sache que seules certaines esp?ces de pichons ont une chance de t\\\'en donner une. Il s\\\'agit des pichons oranges, bleus, blanc, verts et kloune. Si tu n\\\'en r?cup?re pas une du premier coup, retente ta chance. Cette langue se montre parfois tr?s coriace. \\nOh et puis quand la langue sera en ta possession, va la tremper dans un puits enchant?. Il y en a un sous les lacs enchant?s, dans la r?gion des koalaks. Pense ? te munir d\\\'une corde d\\\'escalade pour descendre et remonter.');
INSERT INTO `npc_questions` VALUES (5657, '', '', '', '', 'Mais, qu\\\'est-ce qui m\\\'arrive ? Je ne contr?le plus mon corps. \\nPourquoi est-ce que je gesticule stupidement dans tous les sens de mani?re aussi ridicule ? Qu\\\'est-ce qui arrive ? mon chignon, pourquoi mes cheveux se dressent sur ma t?te en forme d\\\'une cr?te ? Mes bras ne m\\\'ob?issent plus, ils passent pr?s de ma t?te sans mon consentement. Non, c\\\'est horrible, je danse la pektonik ! \\nC\\\'est un cauchemar, j\\\'ai l\\\'air plus idiote qu\\\'une Iop ?cervel?e crois?e avec un tofu. Je ne veux pas ?tre la ris?e d\\\'Amakna et ?tre trait?e de pek. \\n... \\nCof cof... ce que tu cherches... cof cof... se trouve... cof cof... dans les mines... cof cof... des craqueleurs...');
INSERT INTO `npc_questions` VALUES (5658, '', '', '', '', 'Salutations, j\\\'esp?re que Terra Tibya ne te martyrise pas trop. Hahaha.');
INSERT INTO `npc_questions` VALUES (5659, '', '', '', '', 'Je constate avec plaisir que le m?tier commence ? entrer. Je dois t\\\'avouer que je ne m\\\'attendais pas ? ce que tu r?ussisses ? faire parler cette vieille peau aussi facilement. Je vais pr?venir Kaffra Kyper pour qu\\\'il envoie ses hommes r?cup?rer la statuette. Quant ? toi, puisque tu as r?ussi un interrogatoire des plus difficiles, je te fais Adepte des Douleurs.');
INSERT INTO `npc_questions` VALUES (5660, '', '', '', '', '... \\nTu n\\\'as pas l\\\'impression de me d?ranger l? ?');
INSERT INTO `npc_questions` VALUES (5661, '', '', '', '', 'Puisque tu insistes, je vais te donner une mission. Mais attention, c\\\'est confidentiel, tu ne dois en parler ? personne. \\nDes ren?gats bontariens nous ont r?v?l? l\\\'existence de deux statuettes offertes ? Sumens par Maimane. Elles sont les symboles des maux et des biens de l\\\'humanit? et poss?dent de grands pouvoirs donc tu auras compris que nous devons mettre la main dessus avant ces stupides Bontariens. \\nTu vas aller voir Setag, le ma?tre de classe Enutrof, et lui soutirer les vers du nez. Pense ? lui apporter de quoi gagner sa coop?ration.');
INSERT INTO `npc_questions` VALUES (5662, '', '', '', '', 'Je vois que tu as pens? ? m\\\'apporter quelques cadeaux. Pour la peine je veux bien t\\\'aider, de quoi parlais-tu d?j? ? \\nLes statuettes de Sumens, ?a me dit quelque chose. J\\\'y suis ! C\\\'est mon vieil ami Terra Cogita qui m\\\'en avait parl? une fois. Sa s?ur, Terra Tibya, connaissait leur emplacement mais elle est morte il y a plusieurs ann?es d?j? et son fr?re l\\\'a enterr?e pr?s d\\\'un pont sur la rivi?re Kawaii.');
INSERT INTO `npc_questions` VALUES (5663, '', '', '', '', 'Inutile de me d?ranger tant que tu n\\\'auras pas mis la main sur le gardien des statuettes.');
INSERT INTO `npc_questions` VALUES (5664, '', '', '', '', 'Laisse-moi deviner. Tu est incapable d\\\'attraper une ?me ? mains nues, c\\\'est ?a ? Alors va voir Divad et explique-lui la situation. Pr?cise lui que c\\\'est moi qui t\\\'envoie et que c\\\'est urgent.');
INSERT INTO `npc_questions` VALUES (5665, '', '', '', '', 'Je suis en train de mettre au point un nouveau tour et je ne veux pas ?tre perturb');
INSERT INTO `npc_questions` VALUES (5666, '', '', '', '', 'C\\\'est donc toi qui t\\\'occupe de ?a ?\\nCe dont tu as besoin pour capturer une ?me r?calcitrante est une Pierre d\\\'?me adou?e. Je peux t\\\'aider ? en fabriquer une mais pour cela j\\\'ai besoin de plusieurs choses. Dans un premier temps il me faut les ingr?dients, ? savoir une Grande Pierre d\\\'?me heureuse, 4 Fant?mes de Chacha, 4 Sangs de Bouftou, 4 Aubergines et un Cocktail Moritov, que l\\\'on trouve sur l\\\'?le d\\\'Otoma?. Lorsque tu me les auras apport?s, rejoins-moi dans la salle du rituel situ?e sous la Tour de Br?kmar. Tu peux y acc?der par un petit passage entre deux ?tag?res, dans la partie sud-ouest tout en bas de la tour. Pour enchanter la pierre, j\\\'ai besoin d\\\'?tre assist? par un Osamodas connaissant le sort de R?sistance Naturelle et par un Alchimiste capable de fabriquer du Sang de Ph?nix.');
INSERT INTO `npc_questions` VALUES (5667, '', '', '', '', 'Merci. Quand tu en auras termin? avec le reste, nous irons ? la salle du rituel.');
INSERT INTO `npc_questions` VALUES (5668, '', '', '', '', 'Je ne m\\\'attendais pas ? ce que tu r?ussisses aussi facilement mais ce n\\\'est pas plus mal. Puisque tu as ?t? capable d\\\'en capturer une, tu int?gres les rangs des Chasseurs d\\\'?mes.');
INSERT INTO `npc_questions` VALUES (5669, '', '', '', '', 'J\\\'ai entendu parler de ces tra?tres. Ils sont partis se planquer dans une des maisons du territoire des porcos. Pour information ils sont au nombre de trois et pr?ts ? en d?coudre alors fais attention. Si j\\\'?tais toi j\\\'irais d\\\'abord chercher du renfort.');
INSERT INTO `npc_questions` VALUES (5670, '', '', '', '', 'Qu\\\'est-ce que tu nous veux ?');
INSERT INTO `npc_questions` VALUES (5671, '', '', '', '', 'Je n\\\'ai rien ? te dire. Passe ton chemin ou je serai contraint de te violenter.');
INSERT INTO `npc_questions` VALUES (5672, '', '', '', '', 'Encore toi ? T\\\'es du genre coriace ? ce que je vois. Mais si tu crois que ?a va suffire pour nous attraper, tu te trompes.');
INSERT INTO `npc_questions` VALUES (5673, '', '', '', '', 'La corne de bouftou ? Suffit de l\\\'arracher ? un bouftou, je vois pas o? est le probl?me. \\nTu parles pas de cette corne ? Ecoute, je veux bien t\\\'aider mais un, faut t\\\'exprimer clairement, deux, je file pas mes informations gracieusement, si tu vois ce que je veux dire.');
INSERT INTO `npc_questions` VALUES (5674, '', '', '', '', 'T\\\'es pareil ? de la mauvaise herbe. On a beau l\\\'arracher, elle finit toujours par revenir. Cette fois m?me ta m?re ne pourra pas te reconna?tre.');
INSERT INTO `npc_questions` VALUES (5675, '', '', '', '', 'Salutations. As-tu donn? une le?on aux ren?gats ?');
INSERT INTO `npc_questions` VALUES (5676, '', '', '', '', 'C\\\'est du bon travail. J\\\'esp?re que ?a dissuadera les ?ventuels miliciens qui envisagent de changer de camp. Tu as su montrer ton courage et ta d?termination, c\\\'est pourquoi tu int?gres d?s ? pr?sent les rangs des Chasseurs de Ren?gats. F?licitations !');
INSERT INTO `npc_questions` VALUES (5677, '', '', '', '', 'Je suis entour? d\\\'incapables. J\\\'esp?re pour toi que tu as les statuettes.');
INSERT INTO `npc_questions` VALUES (5678, '', '', '', '', 'Les informations de cet imb?cile de Divad ?taient donc fausses. Je vais lui en toucher deux mots car je n\\\'aime pas perdre mon temps et envoyer des guerriers cueillir les p?querettes. Quant ? toi, tu vas aller r?pandre le malheur sur ton passage en devenant Chevalier du D?sespoir.');
INSERT INTO `npc_questions` VALUES (5692, '', '', '', '', 'Tu crois faire peur ? qui au juste ? C\\\'est pour impressionner tes amis que tu joues les fortes t?tes ? \\nArr?te un peu de frimer et rend-toi utile en m\\\'apportant des v?tements propres.');
INSERT INTO `npc_questions` VALUES (5693, '', '', '', '', 'J\\\'ai senti une aura mal?fique et j\\\'ai tout de suite pens? ? toi. \\nQue veux-tu ?');
INSERT INTO `npc_questions` VALUES (5695, '', '', '', '', 'Bonjour, je suis ? la recherche de mes deux fr?res, Aigurraf et Tabach. Ils n\\\'ont pas le moral en ce moment et se comportent comme des gamins. J\\\'ai peur qu\\\'ils finissent par s\\\'attirer des ennuis.');
INSERT INTO `npc_questions` VALUES (5696, '', '', '', '', 'Pourquoi fouilles-tu dans ton sac ? Tu as perdu quelque chose ?');
INSERT INTO `npc_questions` VALUES (5697, '', '', '', '', 'Pfff, comme si j\\\'allais pleurer pour du cuivre de qualit? aussi m?diocre que ton arme.');
INSERT INTO `npc_questions` VALUES (5698, '', '', '', '', 'De l\\\'argent ? J\\\'en ai cach? des tonnes.');
INSERT INTO `npc_questions` VALUES (5699, '', '', '', '', 'Ca t\\\'amuse de d?truire tout ce minerai sous mes yeux ? Tu n\\\'as aucun respect pour les objets de valeur.');
INSERT INTO `npc_questions` VALUES (5700, '', '', '', '', 'Il faudrait faire enfermer tous les sadiques dans ton genre.');
INSERT INTO `npc_questions` VALUES (5701, '', '', '', '', 'Mais t\\\'es malade ? Ca ne va pas bien dans ta t?te ? Un si bel anneau...');
INSERT INTO `npc_questions` VALUES (5702, '', '', '', '', 'Sacril?ge ! Tu as le cerveau d\\\'un trooll avec le quotient intellectuel d\\\'un blop ! Il faut vraiment ?tre d?rang? pour d?truire ces bijoux. Et tout ?a pour une insignifiante information. Tu es vraiment le mal incarn');
INSERT INTO `npc_questions` VALUES (5703, '', '', '', '', 'Non ! Attends. Il y a une statuette cach?e dans la mine du village d\\\'Amakna. Il faut une magie assez puissante pour la faire appara?tre.');
INSERT INTO `npc_questions` VALUES (5704, '', '', '', '', 'Noooooooon !!! Esp?ce de malade ! Purin de bouftou ! Morve de bwork ! Excr?ment de kralamoure !');
INSERT INTO `npc_questions` VALUES (5710, '', '', '', '', 'Que je t\\\'explique la situation : je suis ton ma?tre d\\\'ordre, par cons?quent tu ne dois pas me d?ranger sans une bonne raison.');
INSERT INTO `npc_questions` VALUES (5717, '', '', '', '', 'J\\\'ai parl? de toi aux diff?rents ma?tres d\\\'Ordre et ils sont pr?ts ? t\\\'accueillir dans leurs rangs. Pour ce faire, il faut te rendre ? la Tour des Ordres de Bonta et discuter avec eux pour choisir ta voie. \\nToutefois rien ne presse, tu as tout ton temps pour choisir un Ordre et ce n\\\'est pas une obligation.');
INSERT INTO `npc_questions` VALUES (5718, '', '', '', '', 'Ton ma?tre d\\\'Ordre m\\\'a pr?venu qu\\\'il avait une t?che ? te confier, tu devrais donc passer le voir.');
INSERT INTO `npc_questions` VALUES (5719, '', '', '', '', 'J\\\'ai gliss? deux mots ? ton sujet aux diff?rents ma?tres d\\\'Ordre et ils sont pr?ts ? tester ta valeur. Afin de les convaincre, tu dois te rendre ? la Tour des Ordres de Br?kmar et discuter avec eux pour choisir ta voie. \\nEvite de te presser et passe d\\\'abord boire un coup ? la taverne, j\\\'ai horreur des miliciens qui font trop de z?le, surtout que tu n\\\'es pas oblig? de choisir une sp?cialit? imm?diatement.');
INSERT INTO `npc_questions` VALUES (5720, '', '', '', '', 'Ton ma?tre d\\\'Ordre m\\\'a pr?venu qu\\\'il avait une mission pour toi alors ne reste pas plant? l');
INSERT INTO `npc_questions` VALUES (5739, '', '', '', '', 'Tu as l\\\'art de toujours venir me d?ranger au mauvais moment. J\\\'esp?re dans ton int?r?t que ce n\\\'est pas sans raison.');
INSERT INTO `npc_questions` VALUES (5746, '', '', '', '', 'Le co?t pour redevenir Neutre varie de 500 ? 256000 Kamas en fonction de ton implication au sein de ta milice. \\nNote que je peux te faire changer gratuitement de camp si tu souhaites rejoindre directement l\\\'alignement minoritaire. Ceci n\\\'est ?videmment pas valable si tu appartiens d?j? ? cet alignement.');
INSERT INTO `npc_questions` VALUES (5764, '', '', '', '', 'Puisque tu es tr?s jeune et que tes comp?tences laissent ? d?sirer, redevenir Neutre ne te co?tera que 500 Kamas. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5765, '', '', '', '', 'Tu connais d?j? les bases mais tu n\\\'as aucune r?putation, donc redevenir Neutre ne te co?tera que 1000 Kamas. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5766, '', '', '', '', 'Tu commences ? savoir te d?brouiller et on a d?j? entendu parler de toi dans certaines tavernes, c\\\'est pouquoi redevenir Neutre te co?tera 2000 Kamas. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5767, '', '', '', '', 'Ronan le blagueur est plus connu que toi m?me s\\\'il n\\\'a jamais rien fait d\\\'int?ressant. Redevenir Neutre te co?tera donc 4000 Kamas. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5768, '', '', '', '', 'Alors comme ?a tu t\\\'approches de la cour des grands ? Dans ce cas redevenir Neutre va te co?ter 8000 Kamas. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5769, '', '', '', '', 'J\\\'ai entendu dire que tu commen?ais ? te la jouer, et c\\\'est pour ?a qu\\\'il te faudra 16000 Kamas si tu veux redevenir Neutre. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5770, '', '', '', '', 'Tu commences ? faire parler de toi au del? des murs de ta cit?. C\\\'est bien pour toi, mais du coup redevenir Neutre va t\\\'?tre plus difficile. De ce fait, il te faudra d?bourser 32000 Kamas. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5771, '', '', '', '', 'M?me Ronan le Barbare doit trembler de peur ? ton nom. Autant te dire que ?a n\\\'arrange pas mes affaires car j\\\'aurai plus de paperasse ? remplir. Et tu sais ce que ?a veut dire ? Travailler plus, donc gagner plus. Toi par contre tu devras payer plus, d\\\'o? la modique somme de 64000 Kamas pour redevenir Neutre. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5772, '', '', '', '', 'Ta r?putation te pr?c?de, mais autant te dire tout de suite qu\\\'en ce qui me concerne ?a joue en ta d?faveur. Plus de papiers ? traiter, donc plus d\\\'objets ? recycler, d\\\'o? l\\\'important co?t de 128000 Kamas pour redevenir Neutre. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5773, '', '', '', '', 'Te faire redevenir Neutre ne va pas ?tre une mince affaire. Tout Amakna a entendu parler de toi, et c\\\'est peu dire. Il te faudra donc d?bourser 256000 Kamas si tu souhaites redevenir Neutre. \\nPar contre, si tu souhaites rejoindre un alignement minoritaire, n\\\'oublie pas que je peux te faire changer d\\\'all?geance gratuitement.');
INSERT INTO `npc_questions` VALUES (5774, '4981', '', '', '0', 'Bonjour, je suis Boumawa, une des plus c?l?bres joueuses de Boufbolle d\\\'Amakna, j\\\'ai m?me entra?n? l\\\'?quipe officielle du roi Allister. \\nSi tu veux, je peux t\\\'emmener d?couvrir notre terrain de Boufbolle ?');
INSERT INTO `npc_questions` VALUES (5775, '4982;4983', '', '', '0', 'Veux-tu que je te raccompagne au ch?teau d\\\'Allister ?');
INSERT INTO `npc_questions` VALUES (5776, '2812', '', '', '0', 'Le Boufbolle est un sport qui fut tr?s pris? en Amakna il y a fort longtemps, il opposait deux ?quipes de 5 joueurs chacune, le but ?tant de placer un maximum de Bouftous dans les cages adverses. \\nBien sur la soci?t? protectrice des Bouftous a protest? en voyant comment ?taient trait?s ces cr?atures. D?sormais, c\\\'est g?n?ralement un joueur qui remplace le Bouftou. Certains joueurs pr?f?rent invoquer un Bouftou pour jouer.');
INSERT INTO `npc_questions` VALUES (5777, '3030', '', '', '0', 'Il y a trois r?gles bien pr?cises pour jouer, le Bouftou ne doit pas ?tre tu?, si une ?quipe tue malencontreusement ou volontairement le joueur repr?sentant le Bouftou ou l\\\'invocation de Bouftou, son ?quipe est ?limin?e. \\nQuasiment tous les coups sont permis, mais un joueur qui tuerait un de ses adversaires est automatiquement exclu, il devra donc quitter la partie ! Des places sont r?serv?es aux entra?neurs et aux ?ventuels rempla?ant, il ne peut n\\\'y avoir que 5 joueurs de la m?me ?quipe dans l\\\'aire de jeu, mais un joueur peux ?videmment laisser sa place ? un autre joueur. \\nLes gens hors de l\\\'aire de jeu n\\\'ont aucun droit de participer au match !');
INSERT INTO `npc_questions` VALUES (5778, '', '', '', '', 'Et bien voil? vous savez tout, pour faire une partie, il vous faut deux ?quipes de 5 joueurs, ainsi qu\\\'une tierce personne qui fera le Bouftou (une invocation pourra aussi faire ?ventuellement l\\\'affaire). \\nBien entendu, ces r?gles sont modifiable selon vos envies, la f?d?ration Amakn??ne de Boufbolle n\\\'existant pas, aucune de ces r?gles n\\\'est clairement d?finie ! \\nBon match !');
INSERT INTO `npc_questions` VALUES (5788, '498', '', '', '0', 'Hola aventurier ! Ne t\\\'approche pas de moi, je suis maudite.');
INSERT INTO `npc_questions` VALUES (5789, '498', '', '', '0', 'D?s que j\\\'?ternue, le temps autour de moi semble faire d\\\'?tranges choses. Pour couronner le tout, je suis allergique au pollen. Difficile pour moi de ne jamais tousser... Mais je me soigne ! \\nPour me faire pardonner, j\\\'offre r?guli?rement des bonbons aux habitants d\\\'Amakna qui subissent les effets secondaires de mes ?ternuements. \\nIls n\\\'ont pas mal de succ?s, je suis assez fi?re de moi. Mais pour le moment tout va bien, heureusement ! \\n \\n*roule les yeux et renifle bruyamment* \\n \\nOh non ...Oh ');
INSERT INTO `npc_questions` VALUES (5790, '', '', '', '', ' ');
INSERT INTO `npc_questions` VALUES (5792, '4991;4992;4993;4994;499', '', '', '0', 'J\\\'ai mon nez qui me gratte... Tu n\\\'aurais pas une fleur sur toi ? Ca sent la Tanfouguite ! \\nOh... cela signifie que tu as subi une alt?ration du temps... Je suis vraiment d?sol?e. \\n \\nSi tu veux, je peux te donner un bonbon, ou te donner des poudres d\\\'Eniripsa pour tes familiers. Si il y en a un qui est mort, je peux m?me ?ternuer pour te le ramener ? la vie ! Une fois de plus une fois de moins... \\n \\nChoisis bien, je ne peux pas tout faire en m?me temps !');
INSERT INTO `npc_questions` VALUES (5793, '', '', '', '', 'Non rien, fausse alerte. Ouf !');
INSERT INTO `npc_questions` VALUES (5794, '', '', '', '', 'Es-tu d?cid? ? m\\\'aider dans la capture de toutes les ?mes de monstres dont j\\\'ai besoin ? C\\\'est une qu?te qui s\\\'annonce ?pique, longue et p?rilleuse, mais la r?compense sera ? la hauteur de ton m?rite. Je te donnerai un artefact d\\\'une puissance inestimable. Il sera s?rement mieux exploit? dans les mains d\\\'un aventurier comme toi. Si tu veux m\\\'aider, va voir mon assistante, elle t\\\'expliquera quelles sont les cr?atures dont je recherche l\\\'?me, et te fournira le mat?riel n?cessaire pour y parvenir.');
INSERT INTO `npc_questions` VALUES (5800, '', '', '', '', 'Salutations. Je t\\\'avais demand? dix peaux de larve bleue, j\\\'esp?re que tu me les apportes.');
INSERT INTO `npc_questions` VALUES (5935, '', '', '', '', 'Salut petit Bouloute, je suis l? pour ?changer les friandises qui ne sont plus comestibles. Ne me demande pas pourquoi j\\\'offre de tr?s bonnes friandises contre d\\\'autres friandises non comestibles, c\\\'est une histoire ? dormir debout. Et tu n\\\'as pas envie de dormir debout.');
INSERT INTO `npc_questions` VALUES (5969, '', '', '', '', 'Je suis d?sol?e mais je ne peux pas faire redevenir Neutre une personne d?shonor?e. Reviens me voir lorsque tu auras rachet? ton honneur.');
INSERT INTO `npc_questions` VALUES (6122, '530', '', '', '0', 'Tu me ram?nes les ?mes que je t\\\'ai demand?es ?');
