INSERT INTO `npc_questions` VALUES (6155, '', '', '', '', 'Tu me ram?nes les ?mes que je t\\\'ai demand?es ?');
INSERT INTO `npc_questions` VALUES (6156, '', '', '', '', 'Incroyable, tu as r?ussi l? o? beaucoup ont ?chou?. Je suis impressionn?. Il te reste un dernier effort ? accomplir, et pas des moindres. J\\\'ai besoin que tu me captures l\\\'?me du Kralamoure. J\\\'ai longtemps ?tudi? cette cr?ature, et je sais que sans une pierre d\\\'?me adapt?e, tu ne pourras jamais capturer son ?me. Cette cr?ature est unique, et l\\\'on peut en dire autant de son ?me.');
INSERT INTO `npc_questions` VALUES (6157, '', '', '', '', 'Magnifique, j\\\'avoue que jamais je n\\\'aurais pens? voir cela un jour. Pourtant ce moment est arriv? et tu as accompli un exploit digne des l?gendes. Voici une r?compense ? la hauteur de ton succ?s !');
INSERT INTO `npc_questions` VALUES (6158, '', '', '', '', 'Je vois que tu ne sais pas comment capturer une ?me. Cette technique particuli?re est indispensable. Je peux t\\\'aider ? l\\\'apprendre si tu le souhaites.');
INSERT INTO `npc_questions` VALUES (6159, '', '', '', '', 'Merci pour les patates. Quand il y en a plus, je m\\\'ennuie. J\\\'aimerais bien une pelle de Boisaille pour les cultiver moi-m?me.');
INSERT INTO `npc_questions` VALUES (6160, '', '', '', '', 'J\\\'ai inscris dans ton journal tout ce que tu devras faire pour r?ussir ? capturer une ?me de monstre. Tu iras sur Pandala, j\\\'esp?re que tu aimes voyager !');
INSERT INTO `npc_questions` VALUES (6161, '534', '', '', '0', 'Depuis que j\\\'ai cr?? cette cr?ature et qu\\\'elle s\\\'est ?chapp?e... J\\\'ai compris qu\\\'il ?tait devenu n?cessaire que je puisse sauvegarder l\\\'essence de la plupart des ?tres vivants. J\\\'ai besoin de pouvoir r?g?n?rer certaines esp?ces vivantes, quelque chose me fait dire que cela pourra nous servir plus tard. J\\\'ai le sentiment que d\\\'importants bouleversements se pr?parent, et je ne voudrais pas que tout ce que l\\\'?volution naturelle nous a apport? soit un jour balay? par une force dont on ne soup?onne pas encore l\\\'existence. Mais je m\\\'?gare...');
INSERT INTO `npc_questions` VALUES (6162, '534', '', '', '0', 'Comme je te l\\\'ai d?j? expliqu?, j\\\'ai jadis tent? d\\\'y parvenir moi-m?me, en apportant sur cette ?le et gr?ce ? mon arche, de nombreuses cr?atures issues du continent. Mais ?a n\\\'a pas fonctionn?, ce projet ?tait trop ambitieux. C\\\'est pourquoi j\\\'ai d?cid? de m\\\'en remettre aux aventuriers, en leur demandant de me capturer eux-m?mes l\\\'?me des monstres dont j\\\'ai besoin. Cette qu?te semble si p?rilleuse, que je suis oblig? de faire miroiter la plus belle r?compense que je puisse offrir ? un aventurier avide de puissance, un Dofus...');
INSERT INTO `npc_questions` VALUES (6163, '535', '', '', '0', 'J\\\'en ai vus plusieurs, j\\\'ai pu les ?tudier, tenter de les comprendre, et percer une partie de leurs secrets. L\\\'on pourrait croire qu\\\'ils sont uniques, mais il n\\\'en n\\\'est rien. D\\\'apr?s mes nombreuses recherches, les Dragons ne pondent pas qu\\\'un seul Dofus, mais parfois des couv?es enti?res ! Un seul de ces ?ufs pourra donner naissance ? un vrai Dragon. Quant aux autres, je ne sais pas quel peut ?tre leur v?ritable destin?e...');
INSERT INTO `npc_questions` VALUES (6164, '535', '', '', '0', 'J\\\'ai ?tudi? leur forme, leur texture, leur poids, leur ?quilibre, tout ce qui peut ?tre quantifi?, mesur?, et analys?. Je n\\\'ai pas encore r?ussi ? d?terminer ce qui pouvait diff?rencier un Dofus qui donnera naissance ? un Dragon, et un Dofus qui donnera naissance ? peut-?tre autre chose. Nos esprits rationnels ne peuvent pas encore tout expliquer, la magie de ces ?ufs est si forte qu\\\'elle transcende nos r?gles, m?me les plus ?l?mentaires.');
INSERT INTO `npc_questions` VALUES (6165, '535', '', '', '0', 'Durant nos nombreuses recherches arch?ologiques sur cette ?le, nous avons trouv? beaucoup d\\\'indices troublants. Cette ancienne civilisation disparue semble ?tre li?e de pr?s aux Dofus. Nous n\\\'avons pas encore trouv? de quelle fa?on, il nous reste tant de choses ? d?couvrir et ? comprendre.');
INSERT INTO `npc_questions` VALUES (6166, '', '', '', '', 'J\\\'ai donc de merveilleuses r?compenses ? offrir aux aventuriers qui m\\\'aideront ? trouver ce que je recherche. Expliquer comment j\\\'ai trouv? ces Dofus est une toute autre histoire. Certains parlent de chance, de hasard ou de destin?e. Mais j\\\'aime ? croire que mes recherches m\\\'ont toujours guid? vers ce que le Monde des Douze pouvait nous apporter de plus beau ou dangereux.');
INSERT INTO `npc_questions` VALUES (6167, '', '', '', '', 'Bonjour, adressez-vous ? Otoma?. Il vous confiera quelques t?ches ? la mesure de vos comp?tences. Et peut ?tre m?me certains de ses secrets ....');
INSERT INTO `npc_questions` VALUES (6168, '', '', '', '', 'Je suis d?sol? m?me si je dois reconna?tre ton enthousiasme, je te sais encore trop inexp?riment? pour m\\\'aider. J\\\'attendrai que tu aies davantage parcouru le monde pour te confier une quelconque t?che.');
INSERT INTO `npc_questions` VALUES (6169, '6023;23016', '', '', '0', 'Halte-l?. Je surveille cette ville alors pas d\\\'embrouille sinon c\\\'est directement en prison sans passer par la case d?part, compris ?');
INSERT INTO `npc_questions` VALUES (6170, '', '', '', '', 'Je vois que t\\\'es du genre pas b?te toi. Ca te dirait de rejoindre les rangs des guerriers de Br?kmar ? Si ?a te tente, je t\\\'offrirai une belle bourse remplie de kamas et t\\\'apprendrai quelques trucs de v?t?ran qui pourront te servir pendant les combats. \\nAlors, qu\\\'en dis-tu ?');
INSERT INTO `npc_questions` VALUES (6171, '', '', '', '', 'Je vois que t\\\'es du genre pas b?te toi. Ca te dirait de rejoindre les rangs des d?fenseurs de Bonta ? Si ?a te tente, je t\\\'offrirai une belle bourse remplie de kamas et t\\\'apprendrai quelques trucs de v?t?rans qui pourront te servir pendant les combats. \\nAlors, qu\\\'en dis-tu ?');
INSERT INTO `npc_questions` VALUES (6172, '', '', '', '', 'Excellent, tu as fais le bon choix ! \\nVa de suite rendre visite ? Oto Mustam ? la milice de Br?kmar et dis-lui que tu viens de ma part. Il existe un raccourci pour se rendre ? la cit? sombre, je l\\\'ai indiqu? sur ta carte. \\nAu fait, ne parle de ce petit service ? personne d\\\'autre car les miliciens d\\\'Astrub n\\\'ont pas le droit de recruter pour les grandes cit?s. Ca reste entre nous, compris ?');
INSERT INTO `npc_questions` VALUES (6173, '', '', '', '', 'Excellent, tu as fais le bon choix ! \\nVa de suite rendre visite ? Amayiro ? la milice de Bonta et dis-lui que tu viens de ma part. \\nAu fait, ne parle de ce petit service ? personne d\\\'autre car les miliciens d\\\'Astrub n\\\'ont pas le droit de recruter pour les grandes cit?s. Ca reste entre nous, compris ?');
INSERT INTO `npc_questions` VALUES (6174, '', '', '', '', 'Ah oui ? Ca change tout alors. Les Bontariens sont plus nombreux que nous et toute nouvelle chair ? canon... je veux dire toute nouvelle recrue est la bienvenue. Tu veux rejoindre nos rangs ?');
INSERT INTO `npc_questions` VALUES (6175, '', '', '', '', 'Puisque tu m\\\'as l\\\'air plus enthousiaste que les raclures habituelles, je te dispense de la corv?e d\\\'?quiper mes gus pour l\\\'entra?nement. Par contre tu vas te rendre ? la milice d\\\'Amakna pour obtenir un certificat de changement d\\\'alignement histoire de brouiller les pistes.');
INSERT INTO `npc_questions` VALUES (6176, '', '', '', '', 'Qu\\\'est-ce que ?a peut me faire qu\\\'un idiot m\\\'envoie un incomp?tent ? Br?kmar n\\\'a pas besoin de toi, du moins pour l\\\'instant.');
INSERT INTO `npc_questions` VALUES (6177, '', '', '', '', 'Bonjour, ? ton air essoufl? j\\\'en conclu que tu as couru jusqu\\\'ici. Que puis-je faire pour toi ?');
INSERT INTO `npc_questions` VALUES (6178, '', '', '', '', 'C\\\'est Snori Nairb qui t\\\'envoie ? Dans ce cas je suppose que tu viens t\\\'enr?ler dans la milice de notre belle cit?, est-ce le cas?');
INSERT INTO `npc_questions` VALUES (6179, '23019', '', '', '0', 'Je suis d?sol?e pour toi mais j\\\'ai re?u des consignes strictes. Interdiction formelle de recruter pour les milices de Br?kmar et Bonta. \\n*chuchotte* Je peux passer outre cette restriction lorsqu\\\'une personne souhaite rejoindre l\\\'alignement minoritaire, ne l\\\'oublie pas.');
INSERT INTO `npc_questions` VALUES (6180, '', '', '', '', 'Je n\\\'aide aucune personne ayant sali son honneur. Reviens me voir lorsque tu auras rachet? ton d?shonneur.');
INSERT INTO `npc_questions` VALUES (6181, '', '', '', '', 'Hahaha, je vois que tu ne pers pas le nord. Tiens, voil? tes kamas et quelques bottes secr?tes de vieux baroudeur qui pourront t\\\'?tre utiles en combat.');
INSERT INTO `npc_questions` VALUES (6182, '', '', '', '', 'Nos troupes sont actuellement plus nombreuses que celles de Br?kmar, nous n\\\'avons pas de besoin urgent de nouvelles recrues.');
INSERT INTO `npc_questions` VALUES (6183, '', '', '', '', 'Puisque tu m\\\'as l\\\'air tr?s enthousiaste je te dispense de la corv?e d\\\'?quiper les nouvelles recrues pour l\\\'entra?nement. Par contre tu vas te rendre ? la milice d\\\'Amakna pour obtenir un certificat de changement d\\\'alignement histoire de rendre la chose un peu plus officielle.');
INSERT INTO `npc_questions` VALUES (6184, '', '', '', '', 'Tu t\\\'en es plut?t bien sorti jusqu\\\'? pr?sent, mais je pr?f?re que tu t\\\'entra?nes encore un peu avant ta prochaine mission. \\nReviens me voir lorsque tu auras progress');
INSERT INTO `npc_questions` VALUES (6185, '', '', '', '', 'Je suis tr?s occup? pour l\\\'instant, le travail de chef de la milice n\\\'est pas de tout repos. Peut-?tre aurai-je du temps ? t\\\'accorder un peu plus tard.');
INSERT INTO `npc_questions` VALUES (6186, '', '', '', '', 'Alors raclure de bidet, tu viens voir ton idole ?');
INSERT INTO `npc_questions` VALUES (6187, '', '', '', '', 'J\\\'ai besoin que tu t\\\'aguerrisses encore avant ta prochaine mission. Reviens me voir quand tu auras progress');
INSERT INTO `npc_questions` VALUES (6188, '', '', '', '', 'Ecoute-moi bien. Je ne suis pas ton pote de taverne, alors si tu veux papoter trouve quelqu\\\'un d\\\'autre.');
INSERT INTO `npc_questions` VALUES (6194, '', '', '', '', 'Laissez-mo????????????? chanter, laiiiiiiiiissez-moi... \\nOh, bonjour, je ne vous avais pas entendu approcher. \\nDites-donc, c\\\'est normal le furoncle au milieu de votre visage ? C\\\'est vraiment affreux, vous devriez faire quelque chose pour cacher ?a. \\nMais o? ai-je la t?te ? J\\\'ai oubli? de me pr?senter. Je suis Pandalida, la c?l?bre barde et gagnante de la premi?re saison de la Lascar Amakd?mie. J\\\'esp?re que vous n\\\'?tes pas venu jusqu\\\'ici pour me demander un autographe.');
INSERT INTO `npc_questions` VALUES (6205, '', '', '', '', 'Je suis sinc?rement d?sol?, mais vous n\\\'avez pas le statut n?cessaire pour acc?der ? un coffre de banque. \\n \\n(L\\\'acc?s aux coffres de banque est r?serv? aux joueurs dont le niveau est sup?rieur ? 10)');
INSERT INTO `npc_questions` VALUES (6206, '', '', '', '', 'Un certain X ? Mouais, peut-?tre que je sais quelque chose, mais c\\\'est pas dans mes habitudes de dire des trucs au sujet des clients. Ils tiennent ? leur discr?tion, c\\\'est pour ?a qu\\\'ils viennent dans cet ?tablissement.');
INSERT INTO `npc_questions` VALUES (6207, '', '', '', '', 'Tu sais mon choupinou, la discr?tion est un des ?l?ments majeurs de mon m?tier. Je ne peux rien te dire ? ce sujet mais d\\\'autres personnes le peuvent.');
INSERT INTO `npc_questions` VALUES (6208, '', '', '', '', 'Tu sais ma choupinette, la discr?tion est un des ?l?ments majeurs de mon m?tier. Je ne peux rien te dire ? ce sujet mais d\\\'autres personnes le peuvent.');
INSERT INTO `npc_questions` VALUES (6209, '', '', '', '', 'Si j\\\'?tais toi j\\\'y r?fl?chirais ? deux fois. De nombreux miliciens patrouillent ici et il me suffit de crier pour qu\\\'ils interviennent aussit?t. \\nSi tu as envie de sensations fortes, pourquoi ne pas payer un coup ? boire ? l\\\'une de nos charmantes h?tesses ?');
INSERT INTO `npc_questions` VALUES (6210, '', '', '', '', 'Si j\\\'?tais toi j\\\'y r?fl?chirais ? deux fois. De nombreux miliciens patrouillent ici et il me suffit de crier pour qu\\\'ils interviennent aussit?t. \\nSi tu as envie de sensations fortes, pourquoi ne pas travailler ici ? Certains gaillards appr?cient les femmes ? forte personnalit? dans ton genre.');
INSERT INTO `npc_questions` VALUES (6211, '', '', '', '', 'Tu m\\\'as bien regard? ? Tu me prends pour un poteau indicateur ou quoi ? \\nMais attends... Tu trouves pas que ?a pue le Br?kmarien tout ? coup ?');
INSERT INTO `npc_questions` VALUES (6212, '', '', '', '', 'Comment saurai-je qui est X ? Je ne m\\\'int?resse plus aux autres depuis qu\\\'il est parti.');
INSERT INTO `npc_questions` VALUES (6213, '', '', '', '', 'T\\\'as pas l\\\'air de comprendre. Je ne peux rien dire, vu ?');
INSERT INTO `npc_questions` VALUES (6214, '', '', '', '', 'Puisque tu le prends comme ?a voil? ce que je sais : trois clients ont un nom commen?ant par X. X?lora Busai, Xephir?s et Xiron Keuch. X?lora tra?ne g?n?ralement dans le quartier des bricoleurs mais pour les autres aucune id?e.');
INSERT INTO `npc_questions` VALUES (6215, '', '', '', '', 'Nous autres X?lors sommes la race la plus puissante du Monde des Douze. Personne ne peut rivaliser avec nous, pas m?me le Bworker a qui j\\\'ai pel? le post?rieur pour me faire cette cape.');
INSERT INTO `npc_questions` VALUES (6216, '', '', '', '', 'Toute petite d?j? je m\\\'int?ressais ? l\\\'horlogerie et c\\\'est pour ?a que j\\\'ai choisi d\\\'adorer le dieu X?lor. Maintenant que je suis plus forte l\\\'horlogerie n\\\'est plus qu\\\'un passe-temps entre deux chasses au Bworker.  A l\\\'occasion il faudra que tu viennes assister ? l\\\'un de mes spectacles en ar?ne, je te montrerai comment je mets une racl?e au Bworker. D\\\'ailleurs l? je suis en train de voir avec Moub Reicifitra pour mettre en sc?ne un spectacle pyrotechnique.');
INSERT INTO `npc_questions` VALUES (6217, '', '', '', '', 'Je ne vois pas de quoi tu parles. Je ne mets jamais les pieds dans la tour de Bonta. C\\\'est le tavernier Bagrutte qui t\\\'a parl? de moi ? Je vais lui apprendre ? se m?ler de ses affaires.');
INSERT INTO `npc_questions` VALUES (6218, '', '', '', '', 'La seule personne que je connaisse dont le nom commence par X et qui met les pieds ? la tour de Bonta est Xephir?s, un notable de la cit?. Je ne le connais pas plus que ?a, je l\\\'ai juste crois? quelques fois ? la taverne de la Bagrutte.');
INSERT INTO `npc_questions` VALUES (6219, '', '', '', '', 'Si le Xephir?s dont vous parlez est bien celui auquel je pense, je le connais. Il vient ici de temps en temps lorsqu\\\'il est en affaires avec d\\\'autres notables. Le tailleur Paro Cabanne pourra vous en apprendre plus ? son sujet.');
INSERT INTO `npc_questions` VALUES (6220, '', '', '', '', 'Xephir?s ? Ah mais oui bien s?r, Xephir?s ! Je lui fais r?guli?rement de magnifiques costumes en pure soie de Shin Larve et ?toffe de Moon. C\\\'est un homme qui a tr?s bon go?t et qui aime le luxe, contrairement ? vous. Souhaitez-vous autre chose ?');
INSERT INTO `npc_questions` VALUES (6221, '', '', '', '', 'Je ne vais pas pouvoir vous aider. Xephir?s est un homme qui voyage beaucoup, maintenant que vous posez la question je r?alise que j\\\'ignore o? il habite. La bijouti?re Marge Gondersun le conna?t bien, elle travaillait pour lui en tant que fille au pair avant de reprendre la bijouterie de sa m?re.');
INSERT INTO `npc_questions` VALUES (6222, '', '', '', '', 'Si vous avez quelques kamas en trop, je me ferai un plaisir de vous faire de nouveaux v?tements originaux pour remplacer vos haillons. Rendre beau un d?bris tel que vous serait pour moi un v?ritable d?fi et mettrait mes talents de styliste ? l\\\'?preuve. Pour le visage par contre, je ne suis pas sp?cialiste du ravalement de fa?ade.');
INSERT INTO `npc_questions` VALUES (6223, '', '', '', '', 'J\\\'ai travaill? pour Xephir?s pendant trois ans avant de reprendre la bijouterie de ma m?re. A l\\\'?poque Xephir?s d?butait dans les affaires et ?a n\\\'a pas toujours ?t? ?vident ni pour lui ni pour moi.');
INSERT INTO `npc_questions` VALUES (6224, '', '', '', '', 'Je ne crois pas qu\\\'il soit raisonnable de parler de ?a avec une personne qui m\\\'est totalement ?trang?re.');
INSERT INTO `npc_questions` VALUES (6225, '', '', '', '', 'Vous m\\\'avez l\\\'air sympathique alors je veux bien vous en dire plus, mais vous gardez ?a pour vous, d\\\'accord ? \\nAlors voil?, lorsque je travaillais comme fille au pair chez Xephir?s, il m\\\'est arriv? d\\\'entendre des discussions sur des affaires pas tr?s claires. Xephir?s avait des soucis d\\\'argent, mais en seulement quelques mois ses soucis se sont envol?s et il a acquis une position confortable au sein de la soci?t? bontarienne. Il a revendu sa maison qu\\\'il ne trouvait pas assez luxueuse ? son go?t et c\\\'est ? ce moment que j\\\'ai d?cid? de reprendre l\\\'affaire familiale. \\nIl a depuis chang? maintes fois de demeures mais il passe parfois me voir pour me faire une commande ou deux.');
INSERT INTO `npc_questions` VALUES (6226, '', '', '', '', 'Calmez-vous, je vais vous dire le peu que je sais. Lorsque je travaillais chez lui il a eu plusieurs fois la visite de gens louches, un peu dans votre genre mais en plus distingu?s. Il a ensuite gagn? beaucoup d\\\'argent et s\\\'est achet? une bonne place dans la soci?t? bontarienne. J\\\'ai ensuite repris l\\\'affaire de ma m?re lorsqu\\\'il a d?cid? de d?m?nager pour des appartements plus luxueux. Depuis je ne le vois presque plus sauf de temps en temps lorsqu\\\'il vient me passer commande, ce qui reste tr?s rare. Je ne sais rien de plus, je vous le jure.');
INSERT INTO `npc_questions` VALUES (6227, '', '', '', '', 'Humph. Un tavernier, c\\\'est cens? tout conna?tre sur tout. Quelle bande de minables... Heureusement pour toi tu as obtenu quelques informations int?ressantes sur ce Xephir?s, ?a nous sera peut-?tre utile. \\nJ\\\'ai une autre mission ? te confier sur ce Xephir?s. Figure-toi qu\\\'un de tes coll?gues a trouv? un Sram qui conna?t personnellement Xephir?s pour avoir ?t? en affaire avec lui ? plusieurs reprises. Mais comme cet idiot de milicien n\\\'a pas amen? le Sram avec lui, je l\\\'ai fait ch?tier un peu trop fort et il ne peut plus se d?placer. C\\\'est donc toi qui va te charger de trouver ce Sram dans la for?t des Abraknydes et m\\\'apporter les informations qu\\\'il d?tient.');
INSERT INTO `npc_questions` VALUES (6228, '', '', '', '', 'Je n\\\'ose pas sortir de ce bosquet car j\\\'ai entendu des bruits de pas et des rires narquois un peu plus au nord. Si tu peux y jeter un coup d\\\'oeil et revenir apr?s pour me dire que le chemin du retour est d?gag?, je te donnerai les informations dont tu as besoin.');
INSERT INTO `npc_questions` VALUES (6229, '', '', '', '', 'Quoi ? Il t\\\'a demand? un service puis il a disparu ? Idiot ! Heureusement que tu as trouv? des traces indiquant que les gobelins sont les fautifs sinon je t\\\'aurai fait l?cher tous les orifices par un bouftou.');
INSERT INTO `npc_questions` VALUES (6230, '', '', '', '', 'Un Sram ? Non, je n\\\'ai pas vu de Sram ici. Par contre j\\\'en ai vu un quand on m\\\'a captur');
INSERT INTO `npc_questions` VALUES (6231, '', '', '', '', 'J\\\'?tais en train d\\\'admirer le paysage d?filer sous mes pieds dans un transporteur brigandin lorsqu\\\'en me penchant un peu trop je suis pass? par-dessus bord. Heureusement pour moi un gobelin a amorti ma chute m?me si apr?s il n\\\'en restait que de la bouillie malodorante. Malheureusement, les gobelins m\\\'ont captur? mais comme ils ?taient d?j? trop charg?s, ils se sont d?lest?s du Sram car ils me trouvaient plus dodu et la suite vous la connaissez. D\\\'apr?s ce que j\\\'ai pu comprendre ils pr?parent un banquet dont je suis le plat de r?sistance.');
INSERT INTO `npc_questions` VALUES (6232, '', '', '', '', 'Si vous me d?livrez je vous indiquerai o? les gobelins ont laiss? le Sram.');
INSERT INTO `npc_questions` VALUES (6233, '', '', '', '', 'H? vous l?-bas, sortez-moi de l? !');
INSERT INTO `npc_questions` VALUES (6234, '', '', '', '', 'Merci ? vous. Tenez, prenez ces pains. C\\\'est pas grand chose mais ?a vous remplira l\\\'estomac pendant votre voyage. \\nMaintenant montrez-moi votre carte, je vais vous indiquer l? o? j\\\'ai vu le Sram.');
INSERT INTO `npc_questions` VALUES (6235, '', '', '', '', 'Pendant que tu te promenais dans la for?t des abraknydes, des gobelins m\\\'ont attaqu? par surprise. J\\\'en ai tu? plusieurs mais ils ?taient trop nombreux et ils m\\\'ont captur?. Heureusement je suis un Sram tr?s dou? et apr?s plusieurs jours de marche, j\\\'ai r?ussi ? leur forcer compagnie gr?ce ? un tour dont je te passerai les d?tails. Comme ils me poursuivaient, j\\\'ai couru ? en perdre haleine et, essoufl?, je me suis r?fugi? sur cette corniche. Malheureusement il m\\\'est impossible d\\\'en descendre alors si tu voulais bien me donner un coup de main, je t\\\'en serai reconnaissant.');
INSERT INTO `npc_questions` VALUES (6236, '', '', '', '', 'J\\\'ai vu que tu avais une corde d\\\'escalade. Peut-?tre qu\\\'avec des amis, en m\\\'en envoyant chacun une, nous pourrions concevoir un pont de singe. Si chacun se place o? il faut avec une corde, en les attachant ? l\\\'arbre ?a devrait faire l\\\'affaire. Pr?viens-moi lorsque vous serez tous pr?ts.');
INSERT INTO `npc_questions` VALUES (6237, '', '', '', '', 'Attention je vais traverser. Lorsque ce sera fait, escorte-moi jusqu\\\'? Rigal Main Crochue au temple Sram et je te donnerai le document sur Xephir?s. Oui en fait je ne te l\\\'avais pas dis plus t?t mais je n\\\'ai pas l\\\'information sur moi, h?h?... d\\\'ailleurs s\\\'il survient quoique ce soit entre temps, on se rejoint l?-bas. \\nBon maintenant tiens bien la corde.');
INSERT INTO `npc_questions` VALUES (6238, '', '', '', '', 'Merci, je ne savais pas que les Br?kmariens ?taient aussi sympas. Ce document doit ?tre tr?s important je suppose. Tu lui veux quoi au juste ? Xephir?s ? C\\\'est bizarre quand m?me que les Br?kmariens s\\\'int?ressent ? un Bontarien de si pr?s.');
INSERT INTO `npc_questions` VALUES (6239, '', '', '', '', 'C\\\'est bon, c\\\'est bon, j\\\'ai compris, je me tais. Vous autres Br?kmariens vous ?tes vraiment sp?ciaux. Par moment tu me rappelles mon oncle Jack qui a fini d?soss? par un Croc Gland.');
INSERT INTO `npc_questions` VALUES (6240, '', '', '', '', 'Ca va j\\\'ai compris, je ne te pose plus de question. \\n... \\nT\\\'aurais pas un Kama ? Aller, juste un Kama, c\\\'est rien pour toi un Kama.');
INSERT INTO `npc_questions` VALUES (6241, '', '', '', '', 'Je me souviens de vous, vous ?tiez d?j? venu me voir ? son sujet. Ce que je peux dire le concernant est qu\\\'il affectionne les m?taux pr?cieux, les diamants et les rubis mais il a surtout un faible pour les objets exotiques.');
INSERT INTO `npc_questions` VALUES (6242, '', '', '', '', 'Je connais Xephir?s depuis plusieurs ann?es et je peux dire que sans lui je ne serai peut-?tre pas la c?l?brit? mondiale que je suis devenue depuis ma victoire ? la Lascar Amakd?mie. Par contre lui n\\\'a pas l\\\'air de vous appr?cier, c\\\'est pourquoi je vous prierai de ne plus nous importuner.');
INSERT INTO `npc_questions` VALUES (6243, '', '', '', '', 'Si tu cherches ? te procurer quelque chose au march? noir, va voir Rekojel. Il est au courant de toutes les denr?es qui circulent ill?galement dans la cit?, ce qui veut dire qu\\\'il est au courant de tout ce qui s\\\'ach?te et se vend dans la cit?. Tu pourras le trouver ? proximit? des enclos publics, pas loin de l\\\'atelier des bricoleurs.');
INSERT INTO `npc_questions` VALUES (6244, '', '', '', '', 'Je vois, monsieur a des go?ts de luxe. Qu\\\'? cela ne tienne, j\\\'ai justement ce qu\\\'il te faut. Il s\\\'agit de la couronne du Roi des Borins. C\\\'est une oeuvre unique qui a n?cessit? l\\\'exploitation jusqu\\\'? ?puisement de trois mines de diamants, l\\\'ass?chement d\\\'un oc?an et la fonte de mille tonnes de m?taux pr?cieux. Tu veux la voir ?');
INSERT INTO `npc_questions` VALUES (6245, '', '', '', '', 'Un instant, je l\\\'ai rang?e dans un coffre et je ne trouve plus le morceau de papier o? j\\\'ai not? la combinaison pour l\\\'ouvrir.');
INSERT INTO `npc_questions` VALUES (6246, '', '', '', '', 'Ah, voil? le papier. Voyons ? pr?sent la combinaison... \\nNon mais s?rieusement tu me prends pour qui, un Bontarien ? Tu croyais vraiment que j\\\'allais t\\\'offrir un bijou comme ?a, juste parce que tu en r?clames un ? Ici tu es ? Br?kmar, et ? Br?kmar tout se monnaye. Mais comme c\\\'est Oto Mustam qui le demande, je veux bien cr?er un nouveau bijou. Je te pr?pare une liste des mat?riaux n?cessaires que tu remettras ? ton chef.');
INSERT INTO `npc_questions` VALUES (6247, '', '', '', '', 'Garde-les pour l\\\'instant, tu en auras besoin pour ta prochaine mission.');
INSERT INTO `npc_questions` VALUES (6248, '', '', '', '', 'Tu vas te rendre au campement des gobelins et d?livrer ce Sram. Histoire que tu ne sois pas pass? ici pour rien, voil? quelques potions qui pourront t\\\'?tre utiles en cas de coup dur. Si tu trouves l\\\'aventure trop risqu?e, prends d\\\'autres miliciens avec toi, ?a leur fera de l\\\'exercice et ?a m\\\'?vitera de les envoyer te r?cup?rer en plus du Sram. Inutile de revenir sans les informations, sinon tu sais ce qui t\\\'attend.');
INSERT INTO `npc_questions` VALUES (6249, '', '', '', '', 'Bonjour, que faites-vous chez moi ? Si vous voulez cambrioler ma maison, je vous pr?viens : mon oncle Starky est capitaine de la milice de Bonta et il vous le fera payer cher.');
INSERT INTO `npc_questions` VALUES (6250, '', '', '', '', 'Ce n\\\'est pas ce que je te demande, petite allumeuse ! Encore une remarque dans ce genre et je t\\\'?tire la langue jusqu\\\'? pouvoir faire le tour des remparts de Br?kmar avec.');
INSERT INTO `npc_questions` VALUES (6251, '', '', '', '', 'Joli travail. Je vais la mettre en cellule temporairement. Pendant ce temps, tu vas chercher un autre Br?kmarien pour monter la garde dans un de nos repaires pr?s du quartier des bricoleurs. Je pr?f?re que tu en prennes un qui a d?j? eu sa premi?re perm\\\'. Lorsque tu l\\\'auras trouv?, am?ne-le moi.');
INSERT INTO `npc_questions` VALUES (6252, '', '', '', '', 'Place-toi devant le zaapi et dis-lui de se placer juste devant moi. Je veux m\\\'assurer qu\\\'il s\\\'agit bien d\\\'une recrue ayant fait ses preuves.');
INSERT INTO `npc_questions` VALUES (6253, '', '', '', '', 'Ca suffira pour monter la garde. Je vais faire transf?rer la prisonni?re pendant que tu vas chercher un moyen de contacter le Captain Starky pour l\\\'informer que nous d?tenons sa ni?ce en otage. S\\\'il veut la revoir, il devra nous fournir un cristal de Kain Dharyn. Pi?tinor ? l\\\'?tage conna?t bien son rival, demande-lui des informations. \\nLorsque le message sera pass?, va rendre visite ? Sabine pour t\\\'assurer que tout va bien et attends des nouvelles de notre ennemi.');
INSERT INTO `npc_questions` VALUES (6254, '', '', '', '', 'Vous croyez que je vais me laisser faire sans broncher ? Mon oncle le Captain Starky m\\\'a appris ? me d?fendre, vous allez voir de quel bois je me chauffe.');
INSERT INTO `npc_questions` VALUES (6255, '', '', '', '', 'Le Captain Starky est le chef de la cavalerie bontarienne. C\\\'est une t?te-br?l?e qui a maintes fois conduit des charges d?vastatrices contre nos troupes. Il aurait fait un excellent soldat Br?kmarien s\\\'il n\\\'avais pas choisi le c?t? des perdants. Je pense que je lui proposerai quand m?me un poste dans notre milice lorsque Bonta ne sera plus qu\\\'un champ de ruines fumantes.');
INSERT INTO `npc_questions` VALUES (6256, '', '', '', '', 'Quoi le Captain Starky, qu\\\'est-ce qu\\\'il a lui ? Cette mauviette ne m\\\'arrive m?me pas ? la cheville. Lui et ses poolays je les ?crase, je les pi?tine, je saute dessus ? pieds joints jusqu\\\'? ce qu\\\'il n\\\'en reste que de la bouillie puis j\\\'?crase, je pi?tine et je saute ? pieds joints sur la bouillie jusqu\\\'? en faire du jus de poolay bontarien que je bois avec ma kokopaille.');
INSERT INTO `npc_questions` VALUES (6257, '', '', '', '', 'Tu veux parvenir jusqu\\\'? lui ? Hahaha. Impossible en dehors des batailles, il se planque dans le b?timent de la milice de Bonta. Par contre son besoin de dragodindes est presque aussi important que le mien. Je parie qu\\\'il se fournit chez Klako le c?l?bre chasseur de dragodindes.');
INSERT INTO `npc_questions` VALUES (6258, '', '', '', '', 'Bien s?r que je le connais. Enfin, pas personnellement, mais je suis en affaire avec lui, tu vois ? Je chasse des dragodindes et j\\\'en revends ? la milice de Bonta quand elle m\\\'en commande et c\\\'est le Captain Starky qui g?re cette affaire donc on peut dire que je le connais indirectement.');
INSERT INTO `npc_questions` VALUES (6259, '', '', '', '', 'Ecoute, je suis pas du genre ? m\\\'occuper des affaires des autres alors je te pr?viens de suite : je fais passer ton message et apr?s basta ! Et tes menaces tu peux te les carrer o? je pense. Ce n\\\'est pas demain la veille qu\\\'un Sacrieur va trembler devant toi.');
INSERT INTO `npc_questions` VALUES (6260, '', '', '', '', 'Oto Mustam a ordonn? le renforcement de la garde et les Bontariens ont ?t? ma?tris?s. Ils ont ?t? confi?s ? Bout d\\\'chair pour en faire des conserves. Il veut ?galement que vous renvoyiez un message au Captain Starky en le pr?venant que sa ni?ce risque de subir le m?me sort s\\\'il ne se montre pas coop?ratif.');
INSERT INTO `npc_questions` VALUES (6261, '', '', '', '', 'Je l\\\'ai mang?e. H?h');
INSERT INTO `npc_questions` VALUES (6262, '', '', '', '', 'A?e ! C\\\'est Oto Mustam, il a ordonn? de retarder son transfert au cas o? les Bontariens tenteraient quelque chose de stupide. Il n\\\'a pas eu tort.');
INSERT INTO `npc_questions` VALUES (6263, '', '', '', '', 'Qu\\\'est-ce que je t\\\'avais dis l\\\'autre fois d?j? ? Que je ne voulais pas ?tre impliqu? dans tes manigances.');
INSERT INTO `npc_questions` VALUES (6264, '', '', '', '', 'Je veux bien faire la commission la prochaine fois qu\\\'un Bontarien se pointera ici mais ?a te co?tera 2000 Kamas.');
INSERT INTO `npc_questions` VALUES (6265, '', '', '', '', 'J\\\'attends de voir la couleur de tes Kamas avant de prendre ma d?cision.');
INSERT INTO `npc_questions` VALUES (6266, '', '', '', '', 'Voil?, je vous ai ramen? un Cristal de Kain Dharyn. Vous lib?rez ma ni?ce et je vous le donne ensuite.');
INSERT INTO `npc_questions` VALUES (6267, '', '', '', '', 'Voici le cristal. Maintenant lib?rez ma ni?ce comme convenu.');
INSERT INTO `npc_questions` VALUES (6268, '', '', '', '', 'Oublie ce que je viens de dire, j\\\'ai du travail pour toi. J\\\'esp?re que tu as toujours les cinq lingots d\\\'or, la nacre et la bave du Bouftou Royal avec toi sinon il faudra t\\\'en procurer ? nouveau. \\nEcoute-moi bien attentivement, je n\\\'ai aucune envie de me r?p?ter et en plus j\\\'ai horreur de ?a. Dans l\\\'atelier des alchimistes de Br?kmar, il y a un passage secret cach? derri?re le tronc central. Tu vas t\\\'y rendre pour enchanter le cristal de Kain Dharyn. Tu ne pourras pas le faire seul, il faudra qu\\\'un ma?tre joaillomage, un ma?tre alchimiste et un ma?tre mineur t\\\'accompagnent. Il te faudra en plus poss?der une Harmonie, une Potion de Rafale et une Kobalite que tu m?langeras ? la Bave du Bouftou Royal.');
INSERT INTO `npc_questions` VALUES (6269, '', '', '', '', 'Hum... tout bien r?fl?chis, ce doit ?tre possible d\\\'y parvenir sans se donner la mort. Ta mission reste inchang?e mais inutile de te baigner dans les douves de Br?kmar pour te donner la mort, tu m\\\'es plus utile vivant.');
INSERT INTO `npc_questions` VALUES (6270, '', '', '', '', 'Je regrette presque de ne pas le garder pour moi. Voil? quelques kamas pour te divertir ? la taverne. Bois ? ma sant? !');
INSERT INTO `npc_questions` VALUES (6271, '', '', '', '', 'Qu\\\'est-ce que tu fais l? toi ?');
INSERT INTO `npc_questions` VALUES (6272, '', '', '', '', 'Je comprends mieux pourquoi ces incapables ne sont toujours pas rentr?s. Tu viens pour te venger, c\\\'est ?a ?');
INSERT INTO `npc_questions` VALUES (6273, '', '', '', '', 'Je ne veux pas d\\\'ennuis avec la milice de Br?kmar. On m\\\'a racont? ce qu\\\'Oto Mustam faisait subir aux prisonniers et c\\\'est gu?re reluisant. Pourtant il faut bien manger et mes gars et moi nous avons une famille et des enfants ? nourrir, donc contre 2000 Kamas je veux bien cesser mes activit?s.');
INSERT INTO `npc_questions` VALUES (6274, '', '', '', '', 'Travailler pour le chef de la milice de Br?kmar ? Je n\\\'y avais pas pens?. Qu\\\'est-ce que j\\\'ai ? y gagner ?');
INSERT INTO `npc_questions` VALUES (6275, '', '', '', '', 'Tope-la. A partir de maintenant nous allons nous recycler dans le d?tournement de dragodindes. J\\\'ai justement un cousin qui recrute.');
INSERT INTO `npc_questions` VALUES (6276, '', '', '', '', 'Heu... tr?s peu pour moi.');
INSERT INTO `npc_questions` VALUES (6277, '', '', '', '', 'Ca marche ! Vous voyez les gars, moi je sais y faire avec les femmes. C\\\'est pour ?a que c\\\'est moi le chef. \\nBon alors parlons s?rieusement, tu reviens me voir demain soir, je m\\\'arrangerai pour que les gars soient ? la taverne et qu\\\'ils nous laissent tranquilles. Tu vas voir ma mignonne, le doigt? des Srams n\\\'est pas une l?gende.');
INSERT INTO `npc_questions` VALUES (6278, '', '', '', '', 'Tant que c\\\'est pas du mien qu\\\'il s\\\'agit, ?a me va.');
INSERT INTO `npc_questions` VALUES (6279, '', '', '', '', 'Ecoute-moi bien. Tu es MON larbin, pas celui de Milone, compris ? C\\\'est ? moi de juger si ton incomp?tence m?rite une punition et le cas ?ch?ant laquelle. Pour cette fois ?a ira, tu as perdu suffisamment de temps ? accomplir les quatre volont?s de ce vieux chnok.');
INSERT INTO `npc_questions` VALUES (6280, '', '', '', '', 'Tu as vaincu les cambrioleurs et fais en sorte qu\\\'ils ne soient plus une menace ? Tr?s bonne initiative m?me si j\\\'aurai pr?f?r? qu\\\'ils viennent grossir les rangs de mes sbires. D\\\'un autre c?t?, quelques incomp?tents de plus ou de moins, quelle diff?rence ?');
INSERT INTO `npc_questions` VALUES (6281, '', '', '', '', 'Comment ? Tu as mis une racl?e aux cambrioleurs et ensuite tu t\\\'es point? dans leur repaire pour les convaincre de venir grossir les rangs de la milice ? Voil? un excellent r?flexe br?kmarien ! N\\\'oublie jamais que plus les gens sont fourbes, plus ils m?ritent de se joindre ? notre cause.');
INSERT INTO `npc_questions` VALUES (6282, '', '', '', '', 'Comment ? C\\\'est vous qui avez saccag? ma maison avec cette substance atroce qui empeste ? des kilom?tres ? la ronde ? A cause de vous mes plantes sont mortes et mon mobilier est bon ? jeter. Que me voulez-vous au juste ?');
INSERT INTO `npc_questions` VALUES (6283, '', '', '', '', 'Je suis d?sol? mais je ne peux pas vous aider. Depuis qu\\\'elle a remport? la premi?re saison de la Lascar Amakd?mie, Pandalida est constamment harcel?e d?s qu\\\'elle sort de chez elle. \\nLa derni?re fois que des admirateurs trop passionn?s ont d?couvert o? elle habitait, ils ont recouvert les murs de p?te ? Tra Khben et elle a mis plusieurs semaines ? s\\\'en remettre. C\\\'est d\\\'ailleurs suite ? ?a qu\\\'elle a d?m?nag? et qu\\\'elle est devenue une cliente r?guli?re de ma taverne. Les malheurs des uns font le bonheur des autres comme on dit.');
INSERT INTO `npc_questions` VALUES (6284, '', '', '', '', 'Vous ne ressemblez pas ? un de ces admirateurs fous, je pense pouvoir faire une exception pour vous. Vous allez voir c\\\'est tr?s simple. En sortant de la taverne, vous prenez la direction inverse au mouvement inverse du soleil dans le ciel pendant une demie-lieue, puis vous prenez un chemin perpendiculaire ? l\\\'axe Feudala - Akwadala que vous orientez ? 90% de sa position initiale pendant un quart de lieue. Si vous n\\\'y arrivez pas, rendez-vous simplement au sud-ouest de la pointe du port, c\\\'est l');
INSERT INTO `npc_questions` VALUES (6285, '', '', '', '', 'Vous voulez me faire chanter ? Ca ne va pas se passer comme ?a. Jissey, occupe-toi de cette vermine et rejoins-moi ? la maison lorsque tu auras termin');
INSERT INTO `npc_questions` VALUES (6286, '', '', '', '', 'C\\\'est bon, vous avez gagn?. Je vais remettre votre lettre ? Xephir?s mais laissez-moi tranquille.');
INSERT INTO `npc_questions` VALUES (6287, '', '', '', '', 'Le Conseiller Boyowa ne vous a pas fait jeter en prison ? Je veux dire, tout s\\\'est bien pass? avec le Conseiller Boyowa, vous lui avez bien livr? la caisse de marchandises ?');
INSERT INTO `npc_questions` VALUES (6288, '', '', '', '', 'Comment ?a le joyau a disparu ? Tu ne l\\\'aurais pas plut?t mis dans un coffret que tu aurais cach? dans une tombe dans le cimeti?re de Br?kmar apr?s avoir pass? un pacte avec des Chafers pour qu\\\'ils le surveillent pendant ton absence ? A moins que tu l\\\'ais fourgu? ? Jiaye Djaul contre une compensation p?cuniaire, non ? Je ne te crois pas ! Je t\\\'ai d?j? vu fricoter avec ce receleur et ?a ne m\\\'?tonnerait pas que vous soyez en affaires tous les deux. Rapporte-moi ce joyau ou je demande ? Sbab de pr?parer des andouillettes ? partir de tes tripes.');
INSERT INTO `npc_questions` VALUES (6289, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nUn joyau d\\\'une valeur inestimable dis-tu ? Laisse-moi deviner : on te l\\\'a piqu? et tu cherches les voleurs ? \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nJe ne vends pas mes coll?gues comme ?a, tu me prends pour qui ? \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6290, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nTu te d?brouilles bien en affaires, tu sais ce que tu veux. J\\\'ai entendu dire qu\\\'un groupe de jeunes cherchait ? se d?barrasser d\\\'un joyau soi-disant unique et tr?s cher. Je peux t\\\'indiquer o? se trouve leur planque mais m?fie-toi, les acc?s sont bloqu?s par divers m?canismes et ces jeunes sont pas du genre ? combattre ? la loyale. Sans l\\\'aide des disciples de diff?rents dieux tu ne pourras pas acc?der au rep?re et d?jouer ses m?canismes. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6291, '', '', '', '', 'Tu as d?cid? de me rendre le joyau ou pr?f?res-tu finir en andouillettes ?');
INSERT INTO `npc_questions` VALUES (6292, '', '', '', '', 'Par Djaul ! Je suis presque d??u. Si tu recommences ? me faire des entourloupes je risque de te promouvoir officier ou pire, alors m?fie-toi.');
INSERT INTO `npc_questions` VALUES (6293, '', '', '', '', 'T\\\'es du genre curieux toi. Xephir?s a une bonne situation ? Bonta, il va donc nous permettre d\\\'en savoir plus sur les transactions et les convois de marchandises de nos ennemis. Nous pourrons ainsi les intercepter et nous approvisionner sur le dos de ces stupides Bontariens. Quelle ironie de se faire payer son ravitaillement par ses ennemis, tu ne trouves pas ?');
INSERT INTO `npc_questions` VALUES (6294, '', '', '', '', 'Hahahahaha. Tu es encore plus moche qu\\\'un pou de trooll. Donne-moi tes biens et je te laisserai la vie sauve. Refuse et m?me ta m?re sera incapable de te reconna?tre lorsque j\\\'en aurai termin? avec toi.');
INSERT INTO `npc_questions` VALUES (6295, '', '', '', '', 'Hahahahaha. Parce que tu as trouv? notre cachette tu penses que je vais t\\\'ob?ir ? \\nHahahahaha, tu es aussi ridicule que le chapeau que tu portes.');
INSERT INTO `npc_questions` VALUES (6296, '', '', '', '', 'Je suis le Gardien du Puits des ?mes Souill?es. Puisque vous m\\\'avez vaincu, vous avez droit ? une seule et unique requ?te. Choisissez sagement.');
INSERT INTO `npc_questions` VALUES (6297, '', '', '', '', 'Te revoil? enfin ! Je me demandais ce que tu faisais. J\\\'esp?re pour toi que tu n\\\'?tais pas en train de comploter dans mon dos sinon tu risques de le payer cher, tr?s cher...');
INSERT INTO `npc_questions` VALUES (6298, '', '', '', '', 'De l\\\'impatience ? J\\\'aime ?a. Puisque tu y tiens voici mon plan : Xephir?s est en mesure de nous donner des informations sur les convois bontariens. Nous allons attaquer ces convois, mais envoyer des Br?kmariens risquerait d\\\'?veiller les soup?ons. En plus de ?a, je ne fais pas confiance ? mes officiers pour me ramener l\\\'int?gralit? du butin, j\\\'ai donc mis au point un plan g?nial qui devrait d?tourner les soup?ons de nos ennemis tout en m\\\'assurant que le butin n\\\'atterrisse pas comme par enchantement dans les poches de mes hommes.');
INSERT INTO `npc_questions` VALUES (6299, '', '', '', '', 'Je vais me servir des bandits sans foi ni loi qui op?rent ? l\\\'est d\\\'Amakna. En asservissant leur ?me j\\\'en ferai des soldats d?vou?s et ind?fectibles mais pour ?a j\\\'ai d\\\'abord besoin de capturer leurs ?mes et de r?unir les objets n?cessaires au rituel. \\nTu vas donc capturer trois ?mes de boulanger sombre, deux ?mes de mineur sombre et deux ?mes de forgeron sombre. \\nIl faudra ?galement te procurer une pierre de souillure de chaque couleur : bleue, jaune et verte. Les mineurs sont capables d\\\'en cr?er ? partir des ?l?ments bruts fournis par des alchimistes. S\\\'ils refusent de t\\\'aider, libre ? toi de les fouetter ou de leur mettre des vers dans le nez pour les convaincre de coop?rer.');
INSERT INTO `npc_questions` VALUES (6300, '', '', '', '', 'Combien d\\\'alchimistes et de mineurs as-tu tu? ? la t?che ? Peu m\\\'importe en fait, il y en aura toujours d\\\'autres pour les remplacer. Puisque tu as les pierres tu vas pouvoir partir ? la recherche du Puits des ?mes Souill?es. J\\\'ignore o? est ce puits mais le ma?tre de l\\\'Ordre de l\\\'Esprit Malsain devrait pouvoir te renseigner. Lorsque tu auras d?couvert l\\\'emplacement du puits, vas-y avec les pierres de souillure et les ?mes des bandits pour accomplir le rituel d\\\'asservissement. Si tu accomplis ta mission, je saurai me montrer g?n?reux, peut-?tre.');
INSERT INTO `npc_questions` VALUES (6301, '', '', '', '', 'Tiens tiens, un supp?t du Mal me rend une petite visite. Tu viens me demander un philtre d\\\'angoisse ? A moins que tu ne sois ? la recherche d\\\'encens cauchemardesques.');
INSERT INTO `npc_questions` VALUES (6302, '', '', '', '', 'Je suis ?tonn? qu\\\'une personne de ton rang connaisse l\\\'existence d\\\'un tel lieu. Je sais o? il se trouve, mais je n\\\'aime pas partager mes informations gratuitement, ne sommes-nous pas ? Br?kmar, la ville o? tout se n?gocie ? Apporte-moi une ?me de Ma?tre vampire pour fabriquer des encens cauchemardesques et je te dirai non seulement o? se trouve le lieu que tu cherches, mais aussi comment y acc?der.');
INSERT INTO `npc_questions` VALUES (6303, '', '', '', '', 'Je vois. Finalement tu ne sais pas grand chose au sujet de cet endroit. \\nLe Puits des ?mes Souill?es est un lieu o? les ?mes errantes bloqu?es dans notre monde peuvent devenir des serviteurs du Mal. Le Puits est en fait une connexion entre notre Monde et un autre plan d\\\'existence o? la corruption fait office de loi. C\\\'est pour cette raison que les ?mes errantes pi?g?es dans le puits n\\\'en ressortent jamais indemnes, quand elles en ressortent.');
INSERT INTO `npc_questions` VALUES (6304, '', '', '', '', 'Salutations, il me semble que je t\\\'avais demand? une ?me de ma?tre vampire en ?change des informations dont tu as besoin.');
INSERT INTO `npc_questions` VALUES (6305, '', '', '', '', 'Tu trouveras l\\\'entr?e du souterrain menant au Puits des ?mes Souill?es ? l\\\'Est du Territoire des Bandits. Il ne te sera possible d\\\'acc?der au puits qu\\\'en ?tant accompagn? d\\\'au moins quatre autres Br?kmariens dont la vil?nie n\\\'est plus ? prouver et qui, ? d?faut d\\\'avoir d?j? choisi une sp?cialit?, sont en mesure de le faire.');
INSERT INTO `npc_questions` VALUES (6306, '', '', '', '', 'Je puis je?ner pendant trois si?cles et ne pas ressentir les affres de la faim.');
INSERT INTO `npc_questions` VALUES (6307, '', '', '', '', 'Vous ?tes tellement laid que m?me les pouvoirs de mille dieux seraient insuffisants pour acc?der ? votre requ?te.');
INSERT INTO `npc_questions` VALUES (6308, '', '', '', '', 'Vous ?tes tellement laide que m?me les pouvoirs de mille dieux seraient insuffisants pour acc?der ? votre requ?te.');
INSERT INTO `npc_questions` VALUES (6309, '', '', '', '', 'Excellent travail. Gr?ce ? toi et ? cet imb?cile de Xephir?s je vais devenir tr?s riche. Prends cette bourse et cette bouffe et ne me remercie pas, je vais me faire de l\\\'argent sur ton dos. Hahaha. Quant ? Xephir?s, il a int?r?t ? nous signaler des convois importants car je ne veux pas me retrouver avec des tonnes de sac ? patates sur le dos.');
INSERT INTO `npc_questions` VALUES (6310, '', '', '', '', 'Halte-l? ! *hips* Seuls les officiers ont le droit de p?n?trer dans l\\\'entrep?t.');
INSERT INTO `npc_questions` VALUES (6311, '', '', '', '', '*hips* Je ne suis pas ? vendre ! Ah tiens, la bouteille est vide.');
INSERT INTO `npc_questions` VALUES (6312, '', '', '', '', 'Je suis tr?s tent? *hips* mais je suis de corv?e pour les prochaines vingt-quatre heures. Para?t-il que je bois pendant le service. Tu le crois ?a ? *hips*');
INSERT INTO `npc_questions` VALUES (6313, '', '', '', '', 'D?sol? mon gars mais chuis pas encore assez bourr? pour ?a. *hips* Va faire un tour du c?t? du bois de Litneg, un trooll sera ravi de combler ton manque affectif.');
INSERT INTO `npc_questions` VALUES (6314, '', '', '', '', 'Ce serait pas de refus, en plus que je viens de finir ma bouteille. Tu tombes vraiment ? pic toi. *hips* Ce qui me ferait vraiment plaisir c\\\'est une bi?re de la Bagrutte, ?a me rappellera de bons souvenirs. *hips* En fait am?ne-moi en deux, non cinq. Bon dix ?a devrait faire l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (6315, '', '', '', '', 'Beeuuaaarg ! Oups, d?sol?. Je crois que j\\\'ai trop bu finalement. Pose les bi?res ici, je les boirai plus tard. \\nTiens les clefs... *plouf* Bon ben tiens le bocal, je te laisse r?cup?rer les clefs dedans.');
INSERT INTO `npc_questions` VALUES (6316, '', '', '', '', 'Quoi, tu cherches la bagarre ? Je te pr?viens, si tu m\\\'agresses je crie et toute la garnison viendra te botter les fesses.');
INSERT INTO `npc_questions` VALUES (6317, '', '', '', '', 'Pose cette caisse ici, je vais m\\\'en occuper de suite et te pr?parer un rapport pour ton chef.');
INSERT INTO `npc_questions` VALUES (6318, '', '', '', '', 'Au d?but j\\\'ai cr? que tu me faisais une blague puis je me suis dit que faire le rapport ne me co?terait rien. Cet ?quipement est pourri et si ce n\\\'est pas une blague de ta part alors celui qui s\\\'en sert ne doit pas ?tre tr?s efficace.');
INSERT INTO `npc_questions` VALUES (6319, '', '', '', '', 'Ce n\\\'est pas dans mes habitudes de dire ?a mais celui qui fournit l\\\'?quipement de la milice est un incapable. La seule raison pour laquelle il a obtenu ce march? c\\\'est parce que son p?re est en affaires avec l\\\'intendant. Quand je pense que ce petit bon ? rien de Latem Sa qui est incapable de faire quelque chose de ses dix doigts a obtenu un march? aussi juteux, ?a me r?volte. Encore une fois le copinage est pass? avant les comp?tences et nous voyons le r?sultat. Si tu cherches ce maladroit, il travaille ? l\\\'atelier des forgerons d\\\'Astrub car je n\\\'ai pas voulu de lui dans ma forge.');
INSERT INTO `npc_questions` VALUES (6320, '', '', '', '', 'Oh ?a... tu sais, ce n\\\'est pas grand chose. Je me contente de forger ce qu\\\'on me commande, rien de plus.');
INSERT INTO `npc_questions` VALUES (6321, '', '', '', '', 'C\\\'est pour moi ? Oh, merci. Tu dis qu\\\'Amayiro est tr?s satisfait de mon travail et qu\\\'il m\\\'offre cette prime d\\\'encouragement ? Moi qui pensais ne pas ?tre ? la hauteur et me recycler en dompteur de pious me voil? rassur?. \\nC\\\'est pas tout mais j\\\'ai du travail ? finir et je dois voir Deudoin? pour r?gler quelques affaires importantes. Nous venons de recevoir du nouveau minerai de bien meilleure qualit? que l\\\'ancien et de nouveaux outils, et en plus je dois lui faire signer les re?us. Je ne peux pas laisser la forge sans surveillance donc il faut que tu sortes. Si tu as besoin de mes services, je ne serai pas l? pendant un moment donc inutile d\\\'attendre, reviens plus tard.');
INSERT INTO `npc_questions` VALUES (6322, '', '', '', '', 'Je viens d\\\'apprendre de mauvaises nouvelles et je ne suis pas d\\\'humeur ? en recevoir davantage. Parle si tu as une bonne nouvelle ? m\\\'annoncer, sinon d?guerpis avant que ton sang ne vienne repeindre les murs de cette pi?ce.');
INSERT INTO `npc_questions` VALUES (6323, '', '', '', '', 'Tu as de la chance sur ce coup. Continue ? m\\\'apporter r?guli?rement des bonnes nouvelles et tout se passera bien, peut-?tre m?me que je te confierai des missions plus importantes. En attendant d?guerpis, je n\\\'ai toujours pas dig?r? les autres nouvelles.');
INSERT INTO `npc_questions` VALUES (6324, '', '', '', '', 'Salut, je ne t\\\'ai pas senti arriver. Je suppose que tu n\\\'es pas venu pour prendre ma t?te, ? moins que tu ne guettes mes moindres faits et gestes. Montre-moi tes poignets, je veux voir s\\\'ils sont tatou?s.');
INSERT INTO `npc_questions` VALUES (6325, '', '', '', '', 'Hein quoi ? Mais que... A?e !');
INSERT INTO `npc_questions` VALUES (6326, '', '', '', '', 'J\\\'esp?re qu\\\'il y a toutes les commodit?s modernes. J\\\'en ai assez de devoir me d?guiser en poubelle pour passer inaper?u et je commence ? attirer tous les chachas du quartier.');
INSERT INTO `npc_questions` VALUES (6327, '5574;5575;5573;5572;631', '', '', '0', 'Bonjour, toi aussi tu aimes les b?tes ?');
INSERT INTO `npc_questions` VALUES (6328, '', '', '', '', 'Tu as raison, les animaux sont beaucoup plus intelligents que les habitants de cette cit?. Moi j\\\'adore les chachas car ils sont mignons et surtout parce qu\\\'ils ont un poil aussi soyeux que le mien. Autrefois, je faisais une tourn?e ? travers tout Amakna pour pr?senter mon num?ro de dressage de chachas mais ils m\\\'ont ?t? confisqu? et mis en quarantaine apr?s avoir mang? le kido chatoyant de l\\\'intendant Danathor. Depuis, je travaille comme dompteur et dresseur de Crocs Glands pour la milice de Bonta, en attendant de r?unir assez de kamas pour payer la caution de mes chachas.');
INSERT INTO `npc_questions` VALUES (6329, '', '', '', '', 'Mais c\\\'est horrible ! Tu as un v?ritable coeur de pierre plus solide encore que celui d\\\'un craqueleur.');
INSERT INTO `npc_questions` VALUES (6330, '', '', '', '', 'Hahaha, toi au moins tu as le sens de l\\\'humour. C\\\'est une qualit? rare de nos jours que beaucoup ignorent ou ne comprennent pas.');
INSERT INTO `npc_questions` VALUES (6331, '', '', '', '', 'Je dois dompter des Crocs Glands pour la milice de Bonta car j\\\'ai besoin d\\\'argent pour payer la caution de mes chachas mis en quarantaine par l\\\'intendant Danathor. Heureusement pour moi, j\\\'ai bient?t r?uni la somme n?cessaire.');
INSERT INTO `npc_questions` VALUES (6332, '', '', '', '', 'Vous croyez que l\\\'intendant m\\\'aurait menti ? Ce n\\\'est pas son genre. Je vais continuer ? travailler pour r?unir assez d\\\'argent.');
INSERT INTO `npc_questions` VALUES (6333, '', '', '', '', 'Mille mercis, ?a va ?tre bien pratique pour m\\\'aider ? payer la caution de mes chachas. Il me reste justement un exemplaire de la m?thode d\\\'?levage canin, prends-en soin.');
INSERT INTO `npc_questions` VALUES (6334, '', '', '', '', 'Merci ? toi mais je pr?f?re que tu gardes ton argent. C\\\'est un plaisir d\\\'offrir un exemplaire de la m?thode d\\\'?levage canin ? une chatte au si joli minois.');
INSERT INTO `npc_questions` VALUES (6335, '', '', '', '', 'Moi aussi je veux faire garder mes b?timents par des Crocs Glands ! Par Djaul, tu as int?r?t ? te d?p?cher sinon je te transforme en p?t? pour chienchien.');
INSERT INTO `npc_questions` VALUES (6336, '', '', '', '', 'Je vais tout de suite mettre ?a en pratique. Il me faut d?signer un volontaire pour dompter des Crocs Glands. \\nNon, pas toi ! J\\\'en assez de voir ta t?te et les Crocs Glands risquent de te d?vorer avant la premi?re le?on. Tu peux disposer.');
INSERT INTO `npc_questions` VALUES (6337, '', '', '', '', 'Avant de te pr?cipiter b?tement tu vas me rapporter l\\\'?me d\\\'un Croc Gland, je t\\\'expliquerai plus tard pourquoi si jamais tu n\\\'as pas compris.');
INSERT INTO `npc_questions` VALUES (6338, '', '', '', '', 'Ce n\\\'est pas en faisant semblant de t\\\'entra?ner dans le b?timent de la milice qu\\\'une ?me de Croc Gland va appara?tre dans ta poche.');
INSERT INTO `npc_questions` VALUES (6339, '', '', '', '', 'Quoi, que signifie... Je vois, tu te crois malin pas vrai ? Prends donc ce Croc Gland fra?chement dompt? avec toi, nous verrons si la m?thode d\\\'?levage canin est aussi efficace que le pr?tend Riyou Tchevlakouk. Je vais t\\\'indiquer o? a eu lieu l\\\'embuscade, d?p?che-toi d\\\'y aller et de revenir me faire un rapport.');
INSERT INTO `npc_questions` VALUES (6340, '', '', '', '', 'Quoi, que signifie... Je vois, tu te crois maligne pas vrai ? Prends donc ce Croc Gland fra?chement dompt? avec toi, nous verrons si la m?thode d\\\'?levage canin est aussi efficace que le pr?tend Riyou Tchevlakouk. Je vais t\\\'indiquer o? a eu lieu l\\\'embuscade, d?p?che-toi d\\\'y aller et de revenir me faire un rapport.');
INSERT INTO `npc_questions` VALUES (6341, '', '', '', '', 'Je ne travaille pas plus pour Bonta que pour qui que ce soit d\\\'autre. G?n?ralement j\\\'aide plut?t les personnes qui en ont besoin car vous voyez au fond je suis un sentimental. Par contre je sais que Norb, mon confr?re qui g?re l\\\'atelier au sud d\\\'Amakna, a re?u la visite de Bontariens r?cemment. Vous devriez lui poser la question.');
INSERT INTO `npc_questions` VALUES (6342, '', '', '', '', 'Et pour qui d\\\'autres voudrais-tu que je travaille ? Ne sommes-nous pas ? Bonta ? Tu devrais y r?fl?chir ? deux fois avant de poser des questions aussi stupides.');
INSERT INTO `npc_questions` VALUES (6343, '', '', '', '', 'Ca c\\\'est d?j? plus intelligent comme question. L\\\'incomp?tent de Latem Sa travaille pour Bonta mais je te l\\\'ai d?j? dit. Peut-?tre que d\\\'autres forgerons ont parfois des commandes pour la cit?, tu devrais te renseigner au village d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (6344, '', '', '', '', 'Que veux-tu savoir de plus ? Tu attends peut-?tre que je fasse le travail ? ta place ?');
INSERT INTO `npc_questions` VALUES (6345, '', '', '', '', 'Tu te prends pour qui ? Hors de ma vue avant que je ne te fasse fouetter ? coups de Baguette Euh\\\'Laille\\\'Fe\\\'.');
INSERT INTO `npc_questions` VALUES (6346, '', '', '', '', 'Alors hors de ma vue !');
INSERT INTO `npc_questions` VALUES (6347, '', '', '', '', 'Puisque vous insistez je vais vous donner une chance de me convaincre. A force de ne jamais sortir de cette grotte je ne rencontre plus personne. La solitude me gagne et, comment dire... j\\\'ai parfois envie d\\\'un peu de compagnie vous voyez, alors si vous pouviez m\\\'apporter une, hum... dragofesse en cuir violet de bwork, je me sentirai moins seul. Ah, tant que vous y ?tes, j\\\'essaye de mettre au point d\\\'autres machines et j\\\'aurai besoin de langues de crabe car leur texture est tr?s agr?able au toucher et... bref, vous m\\\'apportez dix langues de crabe et aussi 10 langues fourchues tant que vous y ?tes, ces derni?res me permettront de tester mon robot fouetteur. Bien s?r que le robot fouetteur n\\\'est pas pour un usage personnel ! Qu\\\'est-ce que vous insinuez au juste ? \\nPour la peine j\\\'ajoute vingt planches en bois de kaliptus ? la commande, il para?t que leur r?sine d?gage une odeur aphrodisiaque. Et puis d\\\'abord ce que je compte en faire n\\\'est pas votre probl?me !');
INSERT INTO `npc_questions` VALUES (6348, '', '', '', '', 'Bon, ?a va. Avec ?a je vais pouvoir me cr?er des robots de compagnie. Vous voulez savoir qu\\\'elle sera leur utilit? ? Est-ce que je vous en pose moi des questions ?');
INSERT INTO `npc_questions` VALUES (6349, '', '', '', '', 'Je le savais ! Vous m\\\'aidez uniquement parce que ?a sert vos int?r?ts. Vous ?tes trop charitable pour ?tre honn?te, ?a sent l\\\'entourloupe ? plein nez. J\\\'ai perc? vos plans machiav?liques ? jour, une fois que je serai d?barrass? de vous je pourrai tester la dragofesse que vous m\\\'avez apport?. Maintenant dehors !');
INSERT INTO `npc_questions` VALUES (6350, '', '', '', '', 'Le forgeron a refus? de t\\\'aider et tu l\\\'as ?limin? ? Tu as bien fait. Si nous ne pouvons avoir ce forgeron, alors personne ne l\\\'aura. Ca fait tr?s Br?kmarien tu ne trouves pas ? \\nJ\\\'avais pr?vu de te donner quelque chose ? faire une fois le forgeron dans notre camp mais comme il est mort ?a tombe ? l\\\'eau. Repasse me voir plus tard.');
INSERT INTO `npc_questions` VALUES (6351, '', '', '', '', 'Nous faisons une halte car N?forun et Arlette Ba sont encore en train de se disputer au sujet de la couleur des cheveux blancs d\\\'Amayiro.');
INSERT INTO `npc_questions` VALUES (6352, '', '', '', '', 'Haha. Sans leurs armes les Bontariens feront p?le figure face ? ma cavalerie. Je vais tous les pi????????????tiner. \\nContinue ? servir Br?kmar comme ?a et tu pourras peut-?tre venir ?????crabouiller des Bontariens avec moi.');
INSERT INTO `npc_questions` VALUES (6353, '', '', '', '', 'Bien jou?, le moral des Bontariens prendra un sacr? coup lorsqu\\\'ils s\\\'apercevront que nous les massacrons avec leurs propres armes. Hahaha.');
INSERT INTO `npc_questions` VALUES (6354, '', '', '', '', 'A l\\\'odeur de soufre que tu d?gages tu dois venir de Br?kmar, non ? Je ne sais pas comment tu fais pour vivre dans une atmosph?re pareille. Moi j\\\'ai besoin de vivre au grand air, de respirer le parfum iod? des rivages, d\\\'affronter les temp?tes en haute mer.');
INSERT INTO `npc_questions` VALUES (6355, '', '', '', '', 'La Descemer ? Ca fait un moment que je ne l\\\'ai pas vue ? Madrestam. Je ne sais pas s\\\'il est pr?vu que ce navire bontarien vienne faire escale ici, par cons?quent tu devrais interroger les autres habitants du port, peut-?tre qu\\\'ils pourront te renseigner. Reviens me voir apr?s pour me tenir au courant, de mon c?t? je verrai bien si j\\\'ai appris du nouveau entre temps.');
INSERT INTO `npc_questions` VALUES (6356, '', '', '', '', 'Je sais que des contrebandiers oeuvrent dans ce port, j\\\'en mettrais ta main ? couper ! Depuis la d?couverte des ?les de Wabbit et Moon et la mise en place de circuits touristiques par l\\\'Agence Touriste la contrebande est florissante. D\\\'ailleurs tu m\\\'as l\\\'air louche, tu n\\\'essaierais pas de me distraire par hasard ?');
INSERT INTO `npc_questions` VALUES (6357, '', '', '', '', 'Ca fait un moment que La Descemer n\\\'a pas mouill? l\\\'ancre dans le Port de Madrestam. S\\\'il est pr?vu que La Descemer d?charge sa cargaison, je devrais ?tre avertie de l\\\'origine et du contenu de sa cale. Par contre, si c\\\'est de la marchandise de contrebande, il y a fort ? parier que ce gredin de Squale Lerouge est courant. Il a int?r?t ? me fournir une bonne explication s\\\'il ne veut pas finir dans les ge?les ou pire, dans le ventre d\\\'un requin.');
INSERT INTO `npc_questions` VALUES (6358, '', '', '', '', 'Il n\\\'y a pas une seule marchandise de contrebande qui puisse passer dans ce port sans que j\\\'en sois inform?. Pourquoi ? Parce que je suis le meilleur dans ma profession et qu\\\'ici tous me craignent, m?me cette vieille chaussette de Verumacha me mange dans la main mais elle est trop fi?re pour l\\\'avouer.');
INSERT INTO `npc_questions` VALUES (6359, '', '', '', '', 'C\\\'est un navire de guerre bontarien ?a, non ? Je ne savais m?me pas qu\\\'il devait bient?t accoster. Tu devrais interroger Verumacha, elle devrait ?tre au courant que les Bontariens vont se pointer dans son port m?me si ?a m\\\'?tonne que personne ne m\\\'en ait inform');
INSERT INTO `npc_questions` VALUES (6360, '', '', '', '', 'Figure-toi que je comptais me mettre en qu?te d\\\'une fabuleuse corne magique gard?e par les plus abominables cr?atures que le monde des 12 ait connu. Je comptais ensuite m\\\'en servir pour ouvrir l\\\'antre du terrible Kralamoure g?ant au nord de l\\\'?le d\\\'Otoma?, puis une fois la cr?ature vaincue, j\\\'aurais affront? le gardien du royaume des morts pour r?clamer l\\\'?me de mes d?funts compagnons. Enfin, je serais rentr? au bercail et P?n?loppe aurait ?t? impressionn?e par mes aventures. J\\\'aurais alors connu la richesse et la gloire et tout le monde conterait mes exploits. \\nO? ai-je entendu parler d\\\'une corne magique ? A la taverne du Ripate pardi, lors de mon s?jour ? Sufokia.');
INSERT INTO `npc_questions` VALUES (6361, '', '', '', '', 'J\\\'ai entendu parler de ce navire. Il appartient ? la cit? de Bonta qui s\\\'en sert pour transporter d\\\'importantes marchandises, mais je n\\\'en sais pas plus. Navr? de ne pouvoir t\\\'aider davantage.');
INSERT INTO `npc_questions` VALUES (6362, '', '', '', '', 'Le savais-tu ? Il existe plus de trois mille vari?t?s de patates dans le monde des 12. La plupart ne sont pas destin?es ? un usage alimentaire, mais il en reste quand m?me un gros paquet pour varier les plats et les plaisirs. On distingue par exemple la Patatak de la Patatartin?, la premi?re servant principalement dans l\\\'alimentation de base des soldats sur le front tandis que la deuxi?me est surtout servie le matin par-dessus une tranche de pain fra?chement grill?e au feu de bois.');
INSERT INTO `npc_questions` VALUES (6363, '', '', '', '', 'La quoi ? Je ne sors pas souvent tu sais, je pr?f?re cet endroit sombre et calme ? l\\\'ext?rieur agit? du port.');
INSERT INTO `npc_questions` VALUES (6364, '', '', '', '', 'Personne ici n\\\'a pu te renseigner ? Ca signifie que La Descemer n\\\'est pas pr?te d\\\'accoster. Tu devrais aller faire un tour ? Pandala, mon ami le Capitaine Banwana pourra peut-?tre t\\\'aider car il est au courant de tout le trafic maritime entre le Port de Madrestam et Pandala, qu\\\'il soit l?gal ou non. A la limite je peux te louer une embarcation pour t\\\'y rendre plus rapidement par la voie des mers, ?a ne te co?tera que 500 Kamas. L\\\'offre est ? prendre de suite alors pas le temps de r?fl?chir.');
INSERT INTO `npc_questions` VALUES (6365, '', '', '', '', 'La Descemer est en mer depuis des lustres et ? ma connaissance le navire n\\\'a pas pr?vu d\\\'accoster avant encore au moins deux semaines sur l\\\'?le d\\\'Otoma?. Il n\\\'?tait pas pr?vu qu\\\'il aille au port de Madrestam de toute fa?on. \\nEn parlant de Bontariens, il y a par contre un important chargement d\\\'?quipements sortis de nos forges qui est parti pour la cit? de Bonta il y a d?j? plus d\\\'une semaine. A l\\\'heure actuelle le convoi devrait ?tre arriv? ? destination et les miliciens sont s?rement en train de tester leur nouvel attirail.');
INSERT INTO `npc_questions` VALUES (6366, '', '', '', '', 'Je vois, les Bontariens se sont moqu?s de nous. Pendant que tu cherchais leur navire ils convoyaient leur ?quipement par voie terrestre, ?a co?nciderait avec les derni?res nouvelles.');
INSERT INTO `npc_questions` VALUES (6367, '', '', '', '', 'Bwak bwak bwaaAAAK ! \\n(apparemment il vous faut utiliser la corde depuis un autre endroit).');
INSERT INTO `npc_questions` VALUES (6368, '', '', '', '', 'Chut j\\\'ai dit. Posez une question ? la fois et pas trop fort. \\nVous voulez parler de la corne magique dont les rumeurs vont bon train ? Sufokia ? Je ne connais pas ces rumeurs, je ne sors jamais de la biblioth?que. Par contre je connais l\\\'histoire des origines de cette corne, voulez-vous l\\\'entendre ?');
INSERT INTO `npc_questions` VALUES (6369, '', '', '', '', 'Shhht ! \\nLa corne dont nous parlons faisait partie int?grante d\\\'une cr?ature nomm?e Th?lama qui terrorisait une lointaine province de Pandala. \\nLors d\\\'une soir?e pass?e ? louer la d?esse - certains textes pr?sentent cette soir?e comme une simple beuverie -, le jeune disciple Pandawushu Edfrit fit serment ? son Ma?tre qu\\\'il vaincrait Th?lama. Trois mois plus tard, tandis que Th?lama n\\\'avait pas ?t? aper?ue depuis cinq lunes, on retrouva le cadavre d\\\'Edfrit, une corne sanglante dans la main. De Th?lama on ne trouva aucune trace hormis sa corne et le Ma?tre d\\\'Edfrit donna ? l\\\'objet le nom de son d?funt disciple qui avait eu le courage de tenir sa promesse au p?ril de sa vie. \\nPar la suite, il s\\\'av?ra que la corne ?tait investie de puissants pouvoirs magiques dont le Ma?tre Pandawa fit souvent usage lorsqu\\\'il rendait hommage ? la d?esse. Mais ce qui devait arriver arriva, alors qu\\\'il r?cup?rait d\\\'une nuit enti?re pass?e ? louer la d?esse, on lui d?roba la corne.');
INSERT INTO `npc_questions` VALUES (6370, '', '', '', '', 'Surtout ne m\\\'interrompez pas. Faites silence et ?coutez la fin, nous ne sommes pas ? la taverne mais dans une biblioth?que. \\nO? en ?tais-je ? Ah oui. \\nQuelques ann?es plus tard, la Corne Edfrit refit surface lorsque Moon s\\\'en servit pour coloniser l\\\'?le qui porte son nom. Apr?s avoir assis son autorit?, le petit singe n\\\'eut plus besoin des pouvoirs de la Corne Edfrit et la d?laissa. C\\\'est ainsi qu\\\'elle dispar?t et aujourd\\\'hui nombre de rumeurs plus farfelues les unes que les autres circulent dans les tavernes sur cette corne et ses possibles emplacements, mais moi je ne crois pas ? ces histoires de comptoir. D\\\'ailleurs vous devriez aller bavarder dans un tel lieu, la taverne d\\\'Amakna est aussi bruyante que vous.');
INSERT INTO `npc_questions` VALUES (6371, '', '', '', '', 'Certains aventuriers un peu fous partis en qu?te de la Corne Edfrit sur l\\\'?le de Moon affirment avoir aper?u son gardien. Il faut toutefois noter qu\\\'ils ?taient d?guis?s en fourbasse et avaient bu une bouteille de Gloutoburg lorsque ?a s\\\'est produit, ce qui en dit long sur la cr?dibilit? de leur histoire. Si j\\\'?tais vous, je me m?fierais de ces racontars.');
INSERT INTO `npc_questions` VALUES (6372, '', '', '', '', 'Vous voulez vraiment savoir comment pr?parer ce tord-boyau ? A votre guise, mais ne venez pas vous plaindre si vous avez des hallucinations ou la cavalante apr?s en avoir trop bu. \\nSi vous envisagez de vous rendre sur l\\\'?le de Moon, je vous conseille d\\\'emporter une bonne cinquantaine de Noix de Kokoko avec vous. Il para?t que sans ces noix, on se retrouve bloqu? dans l\\\'horrible jungle de Moon. Brrr, ?a me fait froid dans le dos.');
INSERT INTO `npc_questions` VALUES (6373, '', '', '', '', 'Tu dis que la corne se trouverait sur l\\\'?le de Moon et tu n\\\'as m?me pas pr?par? de Noix de Kokoko pour ta prochaine mission ? Incapable ! Hors de ma vue ! Je suis entour? de bras cass?s et d\\\'incomp?tents en tous genres.');
INSERT INTO `npc_questions` VALUES (6374, '', '', '', '', 'Vous voulez conna?tre l\\\'alimentation des tortues ? Ahahah. Elles mangent des idiots dans votre genre. Houhouhou. \\nVous posiez la question s?rieusement ? Je vois... Je connais un plat qui les fait craquer, oh? oh?. Au bal... C\\\'est du poisson sur un lit de salace, je vais vous l\\\'?crire sur le sable, les yeux dans l\\\'eau, hohoho mon bateau ? ? ???. \\nCa vous satisfait ?');
INSERT INTO `npc_questions` VALUES (6375, '', '', '', '', 'Du poison pour contraindre Turorte ? parler ? Excellente id?e ! \\nSi tu veux pr?parer un blopisier empoisonn?, tu devras contraindre un boulanger ? te le pr?parer ? l\\\'aide de 1 graine de scorbute, 1 bol, 3 bouts de blop reinette et 2 cerises. \\nSi tu oublies la recette, repasse me voir.');
INSERT INTO `npc_questions` VALUES (6376, '', '', '', '', 'Huuummm. Tr?s bon ce plat est. Du blopisier empoisonn? ajout? vous avez ? Un grand chef cuisinier indubitablement vous ?tes.');
INSERT INTO `npc_questions` VALUES (6377, '', '', '', '', 'BwaaAAK !');
INSERT INTO `npc_questions` VALUES (6378, '', '', '', '', 'Justement, il est arriv? il y a un instant et je vous remercie pour lui. Vous m\\\'avez rendu service alors ? mon tour de vous aider. \\nTurorte est une tortue tr?s ?g?e et tr?s sage. Elle fut jet?e toute petite dans les ?gouts d\\\'Amakna. Apr?s avoir un temps c?toy? Sphincter Cell et vaincu Lelievwe P?le Pitane lors du marathon de Cania en 532, elle fut emport?e par les eaux lors de la grande crue de 540 et ?choua sur l\\\'?le des Wabbits, alors habit?e par les Lenalds. N\\\'ayant pu endiguer l\\\'invasion wabbit, elle partie ? la nage jusqu\\\'? l\\\'?le de Moon. L?, honteuse de son ?chec et diff?rente des autres tortues, elle s\\\'isola dans la jungle profonde et y v?cue en ermite jusqu\\\'? ce jour. \\nOn raconte qu\\\'elle poss?de de puissants pouvoirs h?rit?s de son s?jour dans les ?gouts et qu\\\'elle a affin? ses techniques de combat au fil des si?cles. Selon des rumeurs plus r?centes, elle serait la gardienne d\\\'une puissante corne magique mais je n\\\'y ai pas pr?t? attention.');
INSERT INTO `npc_questions` VALUES (6379, '', '', '', '', 'Lelievwe P?le Pitane ?tait un wabbit qui jadis d?fia Turorte lors du marathon de Cania. H?las, sa pr?tention et sa trop grande confiance en lui l\\\'ont conduit droit ? la d?faite. Il n\\\'a jamais dig?r? l\\\'humiliation inflig?e par Turorte et a suivi la migration de ses semblables sur l\\\'?le des Lenalds o? il a pu prendre un semblant de revanche lorsqu\\\'il a ?t? ? nouveau confront? ? Turorte. Bien que tr?s ?g? aujourd\\\'hui, il n\\\'en reste pas moins d?positaire d\\\'une grande puissance qui, selon certaines rumeurs, serait le fruit d\\\'un pacte avec les t?n?bres. Pour ma part, je vois mal Rushu ou l\\\'un de ses sbires passer un pacte avec un wabbit, aussi puissant fut-il. \\nN?anmoins, apr?s un coup d\\\'?tat rat? il s\\\'est r?fugi? sur l\\\'?le des wabbits squelettes pour ?viter la col?re du Wa wabbit, ce qui prouve qu\\\'il n\\\'est pas si puissant que ?a.');
INSERT INTO `npc_questions` VALUES (6380, '', '', '', '', 'Tu as choisi la voie des pewdants mais il est encowe temps de changew. On te bewne d\\\'illusions pouw mieux te contw?lew, la lumi?we t\\\'aveugle et tu ne sais pas o? tu vas. Wenonce maintenant, embwasse les t?n?bwes et ton pouvoiw sewa sans limite. Tu n\\\'auwas plus d\\\'owdwes ? recevoiw de pewsonne, tu sewas ton pwopwe ma?twe.');
INSERT INTO `npc_questions` VALUES (6381, '', '', '', '', 'Je sens la col?we couvew en toi. Tu es fwustw? de ta condition inf?wieuwe et tu aimewais que les gens t\\\'admiwent et te cwaignent ? Embwasse la voie des t?n?bwes et tout deviendwa plus facile. Les gens se pwostewnewont ? tes pieds, tes ennemis twemblewont en entendant pwononcew ton nom, tu sewas d?positaiwe d\\\'un pouvoiw d?passant l\\\'entendement.');
INSERT INTO `npc_questions` VALUES (6382, '', '', '', '', 'Si tu n\\\'as pas encowe choisi ta voie, c\\\'est pawce que tu sais que la lumi?we ne peux pas comblew tes d?siws. Les t?n?bwes te tentent mais tu as peuw de l\\\'inconnu, c\\\'est nowmal. Si tu laisses ton c?t? sombwe pwendwe le dessus, tout deviendwa plus facile, fais-moi confiance.');
INSERT INTO `npc_questions` VALUES (6383, '', '', '', '', 'Oh, je vois que tu t\\\'es d?j? engag? suw cette voie. Tu as fais le bon choix. Lowsque Bonta bw?lewa, tu w?alisewas que tes w?ves sont ? powt?e de main et plus pewsonne ne pouwwa t\\\'emp?chew de les w?alisew.');
INSERT INTO `npc_questions` VALUES (6384, '', '', '', '', 'Tuwowte ? Cette cw?atuwe inf?me est toujouws en vie ? Qu\\\'est-ce que tu me wacontes-l? ? \\nJe ne veux plus entendwe pawler d\\\'elle. Elle m\\\'a humili? et pendant des ann?es, j\\\'ai d? vivwe dans la honte paw sa faute. Voil? qu\\\'aujouwd\\\'hui tu m\\\'offwes une occasion de me vengew et je me wetwouve dans l\\\'incapacit? de t\\\'aidew. Pouwquoi ? Pawce que je suis atteint d\\\'awthwite depuis que la foudwe a fwapp? le bout de mes doigts. C\\\'est extw?mement doulouweux et d?wangeant. Je peux paw contwe te d?voilew son point faible, si tu juwes de me vengew.');
INSERT INTO `npc_questions` VALUES (6385, '', '', '', '', 'Il y a une pawtie de son anatomie que Tuwowte ne peut pas atteindwe. Non, je ne pawle pas de ce ? quoi tu penses, je pawle de son dos. Ses bwas sont twop petits et sa cawapace twop gwande pouw se gwatter le dos, et la t?l?kin?sie ne lui est d\\\'aucune utilit?. J\\\'ignowe ce que tu veux ? Tuwowte, mais en sachant cela tu as l\\\'avantage suw elle.');
INSERT INTO `npc_questions` VALUES (6386, '', '', '', '', 'Tu as besoin d\\\'un grattoir sp?cial ? Non, non, je ne veux pas savoir ce que tu comptes en faire. Commence par me rapporter mes clefs, Fidji Merline a encore oubli? de me les rendre.');
INSERT INTO `npc_questions` VALUES (6387, '', '', '', '', 'O? avais-je la t?te ? J\\\'ai encore oubli? de les lui rendre la derni?re fois que nous avons pass? la nuit ensemble... enfin bref, ces histoires ne te concernent pas. Tiens, voil? les clefs. Dis-lui que la prochaine fois je penserai ? lui rendre avant qu\\\'il ait besoin de m\\\'envoyer quelqu\\\'un pour me le rappeler, il est tr?s grognon parfois.');
INSERT INTO `npc_questions` VALUES (6388, '', '', '', '', 'J\\\'esp?re que Fidji n\\\'a pas fait d\\\'histoires, elle peut ?tre tr?s aga?ante quand elle s\\\'y met. \\nJe vais t\\\'ouvrir l\\\'acc?s ? ma forge sp?ciale, mais attention ! Tu n\\\'y auras plus acc?s une fois ton objet termin');
INSERT INTO `npc_questions` VALUES (6389, '', '', '', '', 'Tu as d?j? oubli? ? \\nIl te suffit d\\\'actionner le levier au fond de la salle pour ouvrir le passage.');
INSERT INTO `npc_questions` VALUES (6390, '', '', '', '', 'Que veux-tu savoir ?');
INSERT INTO `npc_questions` VALUES (6391, '', '', '', '', 'Pour forger l\\\'extr?mit? du grattoir il faut qu\\\'un forgeur de pelle se place devant la forge. Il lui faut ?galement les ?l?ments suivants : ?tre ?quip? d\\\'un Marteau de Forgeur de Grattoir et avoir sur lui 2 Aluminites, 5 Fers et 1 Huile de Koode.');
INSERT INTO `npc_questions` VALUES (6392, '', '', '', '', 'Tu as r?ussi ? fabriquer ton objet. C\\\'est pas mal, mais il va falloir t\\\'am?liorer si tu comptes un jour m\\\'?galer.');
INSERT INTO `npc_questions` VALUES (6393, '', '', '', '', 'Pour sculpter le manche du grattoir il faut qu\\\'un sculpteur de baguette se place devant la forge. Il lui faut ?galement les ?l?ments suivants : ?tre ?quip? d\\\'une Tailladeuse de Manche et avoir sur lui 2 Bois d\\\'Erable et 5 R?sines d\\\'Abraknyde.');
INSERT INTO `npc_questions` VALUES (6394, '', '', '', '', 'Pour assembler le manche et l\\\'extr?mit? du grattoir il faut qu\\\'un bricoleur se place devant la forge. Il lui faut ?galement les ?l?ments suivants : ?tre ?quip? d\\\'un Marteau du Bricoleur et avoir sur lui 2 Ebonites, en plus du manche et du grattoir ?videmment.');
INSERT INTO `npc_questions` VALUES (6395, '', '', '', '', 'Pour achever la fabrication du grattoir ? dos, il faut d\\\'abord fabriquer un grattoir ? dos inachev?. Une fois le grattoir ? dos inachev? en ta possession, place-toi devant la forge et nous le terminerons ensemble.');
INSERT INTO `npc_questions` VALUES (6396, '', '', '', '', 'Et voil? le r?sultat ! Sans moi tu n\\\'aurais jamais pu terminer le grattoir ? dos, avoue que je suis le meilleur forgeron de Br?kmar. \\nTu as eu ce que tu voulais ? Alors dehors !');
INSERT INTO `npc_questions` VALUES (6397, '', '', '', '', 'Ah oui, on m\\\'avait pr?venu que vous passeriez me donner ces documents. Ne vous en faites pas, tant qu\\\'ils seront en ma possession les Br?kmariens ne pourront pas mettre la main dessus. \\nSaluez Amayiro de ma part.');
INSERT INTO `npc_questions` VALUES (6398, '', '', '', '', 'Nous savons ? pr?sent o? se trouve le chaudron primordial mais avant de pouvoir l\\\'utiliser, il faut r?unir les diff?rents ingr?dients. La recette est vieille et les ingr?dients sont m?connus des artisans d\\\'aujourd\\\'hui. Je t\\\'ai fait une liste des ingr?dients ? trouver, commence donc par interroger les sp?cialistes de chaque artisanat concern?. Avec de la chance et quelques paires de baffes, la m?moire leur reviendra peut-?tre. Et comme le savoir n\\\'est pas ton point fort, voici la liste des sp?cialistes. Ecoute bien, je ne r?p?terai pas. Il y a les boulangers Rucar, Harrys Corb, Kelog Korflex et Sam Croa, notre cuisini?re Sbab et l\\\'alchimiste de Bonta, Merlan l\\\'Encha?neur.');
INSERT INTO `npc_questions` VALUES (6399, '', '', '', '', 'Beurk. Rien que son nom donne pas envie d\\\'en manger. T\\\'en a d\\\'autres comme ?a ?');
INSERT INTO `npc_questions` VALUES (6400, '', '', '', '', 'C\\\'est une recette de pain bwork ? J\\\'ignorais que les bworks savaient pr?parer du pain. Je suppose que le go?t va avec le nom.');
INSERT INTO `npc_questions` VALUES (6401, '', '', '', '', 'Je me souviens de vous maintenant ! C\\\'est vous qui m\\\'avez sorti des griffes des gobelins. Vous avez de la chance, j\\\'ai autrefois assist? Xavier le Boulanger lors d\\\'une c?r?monie de fun?railles du m?nestrel Francisque Kabroule. Je vais vous noter la recette sur du papier. Pour la farine demandez ? Shika Ingalsse, c\\\'est elle qui nous la fournissait.');
INSERT INTO `npc_questions` VALUES (6402, '', '', '', '', 'Vous avez l\\\'air de vous y conna?tre en pains anciens. Ce pain est la preuve que Xavier le Boulanger n\\\'est pas aussi dou? qu\\\'on peut le croire. Je n\\\'ai jamais su comment il avait r?ussi ? pr?parer un pain ? l\\\'odeur et au go?t aussi infects.');
INSERT INTO `npc_questions` VALUES (6403, '', '', '', '', 'Ca fait bien longtemps que nous ne fabriquons plus cette farine. C\\\'est pour des fun?railles je suppose ? Toutes mes condol?ances. Etant donn?es les circonstances, je veux bien vous donner la recette de cette farine. Un paysan un minimum exp?riment? saura vous la pr?parer, ? condition de disposer des ressources n?cessaires. \\nGardez espoir, l\\\'?me de votre d?funt ami finira par se r?incarner un jour ou l\\\'autre.');
INSERT INTO `npc_questions` VALUES (6404, '5677;5919;567', '', '', '0', 'O? qu\\\'ils sont les kanis ? M?fie-toi, le kani est fourbe, le kani est m?chant, le kani est gros. \\nAh, mais je ne me suis pas pr?sent?. Je suis Sim le Soft, le plus grand chasseur de kanigrous de tous les temps. Crois-le ou pas, j\\\'ai tu? mon premier kanigrou ? l\\\'?ge de 3 ans. J\\\'ai alors compris qu\\\'en tuant plein de ces gros monstres, je progresserai plus vite que n\\\'importe qui. Oui, j\\\'ai compris ?a tout petit et depuis j\\\'ai progress? vite, tr?s vite. J\\\'ai d?j? tu? 13142517 kanigrous et je ne suis pas pr?s de m\\\'arr?ter.');
INSERT INTO `npc_questions` VALUES (6405, '', '', '', '', 'Non, pourquoi me demandes-tu ?a ?');
INSERT INTO `npc_questions` VALUES (6406, '567', '', '', '0', 'Tu plaisantes ? Les plaines de Cania s\\\'?tendent ? l\\\'infini, ?a veut donc dire qu\\\'il y a une infinit? de kanigrous.');
INSERT INTO `npc_questions` VALUES (6407, '', '', '', '', 'Des cit?s ? Des endroits ou des milliers de gens vivent ensemble ? Tu ne serais pas en train de me prendre pour un idiot par hasard ? Je sais tr?s bien que de tels endroits n\\\'existent pas. Au-del? des plaines de Cania il y a... les massifs de Cania, puis les plaines rocheuses de Cania, puis... ? nouveau les plaines, rien d\\\'autre. \\nLes cit?s, c\\\'est une rumeur lanc?e par les kanigrous pour inciter les gens ? se diriger tous ensembles vers un m?me point. Ainsi, les kanigrous n\\\'ont pas ? se fatiguer pour chercher leurs proies et peuvent se faire un bon m?choui. \\nFaut vraiment ?tre n? de la derni?re pluie pour croire un truc pareil, mais moi, je suis bien trop rus? pour tomber dans un tel panneau.');
INSERT INTO `npc_questions` VALUES (6408, '', '', '', '', 'Je n\\\'y connais rien, je n\\\'avais jamais cuisin? avant d\\\'?tre captur?e par Br?kmar. Vous feriez mieux d\\\'interroger Bout d\\\'chair, ? l\\\'atelier des bouchers de la cit');
INSERT INTO `npc_questions` VALUES (6409, '', '', '', '', 'Ca c\\\'est une bonne salade. Beaucoup de viande, peu de l?gumes. Elle serait encore meilleure si on rempla?ait les l?gumes par d\\\'autres morceaux de viande. \\nVous voulez savoir comment la cuisiner ? Ca je n\\\'en sais rien, seuls quelques rares aventuriers ma?trisant ? la fois l\\\'art de la chasse et de la boucherie connaissent la recette. Je me souviens d\\\'un chasseur de Cania qui en mangeait justement, comment s\\\'appelait-il d?j? ? Sam le Sif, Sim le Sympa... Sim le Soft ! Il tra?ne souvent au sud du donjon blop, je vous indique le donjon sur votre carte. Un p\\\'tit morceau de viande pour la route ?');
INSERT INTO `npc_questions` VALUES (6410, '', '', '', '', 'Quelqu\\\'un t\\\'a parl? de cette salade ? Je croyais le secret bien gard?. Je veux bien partager ce secret avec toi... si tu me rapportes 10 Peaux de Kanigrou.');
INSERT INTO `npc_questions` VALUES (6411, '', '', '', '', 'Tu as l\\\'air d\\\'en avoir dans le pantalon. Tiens, j\\\'ai not? la recette sur ce morceau de papier. Tu la gardes pr?cieusement et tu n\\\'en parles ? personne sinon je viendrai te zigouiller dans ton sommeil. \\nTant que t\\\'y es, puisque tu sembles chercher de vieilles recettes va interroger mon pote Nikos Monote, il en conna?t une bonne. Par contre n\\\'?coute pas ce qu\\\'il raconte, il est un peu fou. Il m\\\'a racont? des histoires avec des ?tendues d\\\'eau s\\\'?talant ? perte de vue ? l\\\'ouest des plaines de Cania et des bateaux pouvant voyager sur l\\\'eau pendant des mois. Tout le monde sait bien que les plaines de Cania s\\\'?tendent ? l\\\'infini.');
INSERT INTO `npc_questions` VALUES (6412, '', '', '', '', 'Si c\\\'est le cas inutile de m\\\'apporter les peaux. Je te passe la recette pour que toi aussi tu puisses conna?tre ce qu\\\'est une vraie salade qui tien au corps, pas comme tous ces trucs di?t?tiques bourr?s de cochonneries que les marchands itin?rants veulent te refourguer.');
INSERT INTO `npc_questions` VALUES (6413, '', '', '', '', 'Laisse-moi deviner : tu as rencontr? Sim le Soft et il t\\\'a dit de venir m\\\'ennuyer, et toi bien s?r comme un bon toutou tu lui as ob?i ? Tu n\\\'as vraiment rien dans la cervelle mais comme je suis quelqu\\\'un de tr?s g?n?reux, je te c?de la recette contre 500 Kamas. A prendre ou ? laisser.');
INSERT INTO `npc_questions` VALUES (6414, '', '', '', '', '498, 499, 500, le compte y est. Tiens, voici ta recette. Si tu la voulais sur un papier de meilleure qualit?, il fallait payer plus, mais ?a aurait jur? avec ta tenue de plouc. Si tu n\\\'as rien d\\\'autre ? me demander, je te prierai de t\\\'?loigner sinon on pourrait croire que nous sommes amis, tu imagines un peu la honte ?');
INSERT INTO `npc_questions` VALUES (6415, '', '', '', '', 'Par les douze dieux, comment est-ce possible ? Tu... tu es pauvre ! Avec ta d?gaine de plouc j\\\'aurai d? m\\\'en douter. rassure-moi, ce n\\\'est pas contagieux, si ? Tiens, prends cette recette et va-t-en, je ne voudrai pas ?tre contamin');
INSERT INTO `npc_questions` VALUES (6416, '', '', '', '', 'Je vois, vous venez de Br?kmar et vous pensez avoir tous les droits dans notre cit? ? Laissez-moi vous dire que vous vous fourrez le doigt dans l\\\'oeil. Non, inutile de le faire vraiment, c\\\'est une expression, une image, vous voyez ? Pas avec vos yeux... Rolala, vous avez du sang Iop dans les veines, c\\\'est s?r. \\nD\\\'habitude je ne travaille pas pour l\\\'ennemi mais si je ne vous aide pas, vous irez voir la concurrence et ce sera encore M?ssieur H?las de Ciwillekh qui r?coltera les honneurs, donc je dis non ! \\nQu\\\'est-ce qu\\\'il vous faut d?j? ? Ah oui, vous voulez savoir comment fabriquer un Philtre de Long?vit?. 5000 Kamas et la recette est ? vous.');
INSERT INTO `npc_questions` VALUES (6417, '', '', '', '', 'D\\\'accord pour 1000 Kamas mais vous faites une affaire. Et si ?a ne marche pas inutile de venir vous plaindre.');
INSERT INTO `npc_questions` VALUES (6418, '', '', '', '', 'Malgr? ta mission tu as pens? ? ton chef, c\\\'est bien. Tu m?rites une petite prime, quant ? moi je m\\\'en vais de ce pas utiliser ce philtre sur Sbab. \\nPourquoi sur Sbab ? Ce ne sont pas tes affaires, occupe-toi donc de ce qui te regarde.');
INSERT INTO `npc_questions` VALUES (6419, '', '', '', '', 'Aventurier, ne me crains pas ! Je peux t\\\'envoyer au cimeti?re ... mais sans prendre ta vie, ? combien fragile sur ces terres redoutables. Dispense la mort ? toutes les races qui foulent ce monde et je t\\\'enverrai l? o? un jour tous finiront.');
INSERT INTO `npc_questions` VALUES (6420, '', '', '', '', 'Ecoute-moi bien jeunot, si tu es venu te la jouer tu t\\\'adresses ? la mauvaise personne. Les pr?tentieux dans ton genre je les attrape et je fais de la chirurgie exp?rimentale avec leur visage jusqu\\\'? ce que leur m?re ne puisse plus les reconna?tre, tu vois ce que je veux dire ? Alors tu fais profil bas et tu d?gages.');
INSERT INTO `npc_questions` VALUES (6421, '', '', '', '', 'Ecoute-moi bien fillette, je te conseille d\\\'aller tr?mousser ton popotin ailleurs. Les allumeuses dans ton genre je les attrape et je fais de la chirurgie exp?rimentale avec leur visage jusqu\\\'? ce que leur m?re ne puisse plus les reconna?tre, tu vois ce que je veux dire ? Alors tu fais profil bas et tu d?gages.');
INSERT INTO `npc_questions` VALUES (6422, '', '', '', '', 'Tu serais pas du genre bien lourd ? Montre-moi ton ?p?e. \\n... \\nJ\\\'ai d?j? vu ce genre d\\\'?p?es dans les mains d\\\'Ecaflips vivant en dehors de la cit?. Je ne sais plus o? exactement, si tu crois que je me souviens de tous les endroits o? je tra?ne. D\\\'ailleurs en parlant de tra?ner, je t\\\'avais demand? de ficher le camp alors que fais-tu encore ici ? T\\\'es amoureux ?');
INSERT INTO `npc_questions` VALUES (6423, '', '', '', '', 'C\\\'est qu\\\'elle insiste la bougresse ! Montre-moi ton ?p?e. \\n... \\nJ\\\'ai d?j? vu ce genre d\\\'?p?es dans les mains d\\\'Ecaflips vivant en dehors de la cit?. Je ne sais plus o? exactement, si tu crois que je me souviens de tous les endroits o? je tra?ne. D\\\'ailleurs en parlant de tra?ner, je t\\\'avais demand?e de ficher le camp alors que fais-tu encore ici ? Tu veux que je te refasse une beaut? ? coup de griffes ? Remarque, ?a ne pourrait que t\\\'arranger.');
INSERT INTO `npc_questions` VALUES (6424, '', '', '', '', 'Ce n\\\'est pas mon genre d\\\'?couter les conversations des gens, j\\\'ai vraiment entendu ce nom par hasard lorsqu\\\'ils discutaient de la revente d\\\'objets vol?s.');
INSERT INTO `npc_questions` VALUES (6425, '', '', '', '', 'Des objets vol?s ? Je n\\\'ai jamais parl? d\\\'objets vol?s. Vous avez mal entendu, j\\\'ai dit objets trouv?s.');
INSERT INTO `npc_questions` VALUES (6426, '', '', '', '', 'Oulala du calme, je ne veux pas d\\\'ennuis. Les Ecaflips parlaient d\\\'un repaire dans les plaines de Cania, pr?s de la foire du trooll, c\\\'est vraiment tout ce que je sais. Lorsqu\\\'ils se sont aper?us que j\\\'?tais un peu trop proche d\\\'eux, ils ont baiss? le ton.');
INSERT INTO `npc_questions` VALUES (6427, '', '', '', '', 'Des Ecaflips ? Pas vu d\\\'Ecaflips, jamais. C\\\'est quoi au juste un Ecaflip ?');
INSERT INTO `npc_questions` VALUES (6428, '', '', '', '', 'Et les autres ? Et bien tant qu\\\'ils ne font pas d\\\'histoire et qu\\\'ils payent leur consommation tout va bien. Par contre ce sont tous des habitu?s, rien ? voir avec les voyageurs que l\\\'on trouve ? la taverne du Feubuk.');
INSERT INTO `npc_questions` VALUES (6429, '', '', '', '', 'Il y en avait plusieurs, Shere Hacanon en faisait partie si je me souviens bien. Quand il travaille il est en poste ? l\\\'entr?e sud de la cit?, tu n\\\'auras aucun mal ? le trouver.');
INSERT INTO `npc_questions` VALUES (6430, '', '', '', '', 'Des voyageurs Ecaflips ? Des dizaines de voyageurs passent chaque jour par cette entr?e, et l? je parle des jours calmes. Le trafic atteint facilement plusieurs centaines de voyageurs lors des foires, des festivit?s, des p?lerinages...');
INSERT INTO `npc_questions` VALUES (6431, '', '', '', '', 'Nous avons r?cemment eu quelques probl?mes avec des Ecaflips un peu ?m?ch?s. La situation s\\\'?tait tellement d?grad?e que nous avons failli en venir aux mains, jusqu\\\'? ce que leur chef leur fasse entendre raison en leur rappelant qu\\\'ils ne devaient pas se faire remarquer et qu\\\'ils avaient un travail ? terminer. Tu parles, pour l\\\'occasion c\\\'?tait rat');
INSERT INTO `npc_questions` VALUES (6432, '', '', '', '', 'J\\\'ai beau r?fl?chir, je ne me souviens de rien d\\\'autre. Ah si, ils ont parl? de rejoindre un campement ? l\\\'ouest de je ne sais plus o? une fois leur travail termin');
INSERT INTO `npc_questions` VALUES (6433, '', '', '', '', 'Qu\\\'est-ce que tu fais l? toi ? D?gage et oublie ce que tu viens de voir sinon je t\\\'?gorge, t\\\'as compris ?');
INSERT INTO `npc_questions` VALUES (6434, '', '', '', '', 'Toi t\\\'as le sens des affaires. Si tu veux en savoir plus, prends contact avec Hersa Griffe Sombre ? Bonta mais surtout ?vite de lui dire que nous t\\\'avons parl? d\\\'elle.');
INSERT INTO `npc_questions` VALUES (6435, '', '', '', '', 'Que les choses soient claires : j\\\'ai eu une aventure avec un Ecaflip jusqu\\\'au jour o? je me suis aper?ue que c\\\'?tait un rat?. Soit disant il ?tait le chef d\\\'un groupe de bandits alors j\\\'ai insist? pour qu\\\'il m\\\'am?ne ? son repaire. J\\\'ai tellement insist? qu\\\'il a fini par accepter et c\\\'est une fois sur place que j\\\'ai compris qu\\\'il n\\\'?tait qu\\\'un sous-fifre. Il a voulu faire profiter ses copains de ma pr?sence et depuis ce jour plusieurs d\\\'entre eux sont soit borgnes, soit manchots, soit cul-de-jatte, soit les trois ? la fois.');
INSERT INTO `npc_questions` VALUES (6436, '', '', '', '', 'Si c\\\'est pour leur nuire je veux bien t\\\'aider mais ?a ne fait pas de moi ton amie, compris ? \\nTu situes le zaap de Tain?la ? Et bien ce n\\\'est pas du tout l?. Passe-moi ta carte, ?a ira plus vite. \\nSeuls les Ecaflips de la bande sont admis donc n\\\'esp?re pas pouvoir y p?n?trer tranquillement. En plus, l\\\'entr?e est cach?e derri?re un rocher et si tu n\\\'as pas de corde pour descendre, c\\\'est la chute mortelle assur?e. Je te conseille d\\\'y aller en groupe car ce ne sont pas des tendres et s\\\'ils t\\\'attrapent ils te mordent, ou pire.');
INSERT INTO `npc_questions` VALUES (6437, '', '', '', '', 'Salutations. Je m\\\'appelle Gueurle et je suis ? la t?te d\\\'une importante troupe de marchands. Lorsque je ne suis pas occup?e par le monde des affaires, je m\\\'occupe personnellement des hommes d\\\'affaires et crois-moi, je m\\\'y connais aussi bien en affaires qu\\\'en hommes. Certains disent d\\\'ailleurs de moi que je suis tr?s dure en affaires, dans tous les sens du terme. Et toi, qu\\\'en penses-tu ?');
INSERT INTO `npc_questions` VALUES (6438, '', '', '', '', 'Il ne faut pas ?tre timide comme ?a, surtout avec un aussi joli minois. Tu n\\\'as jamais song? ? entrer dans le monde des affaires ? Crois-en mon exp?rience, tu gagnerais bien plus qu\\\'en allant risquer ta vie aux quatre coins du monde.');
INSERT INTO `npc_questions` VALUES (6439, '', '', '', '', 'Voyons, un grand gaillard comme toi ne devrait pas faire son timide. Si tu fais affaires avec moi, je pourrai t\\\'aider ? all?ger ta bourse... surtout qu\\\'elle m\\\'a l\\\'air pleine et pr?te ? exploser. Tu devrais penser ? la vider de temps en temps, ne serait-ce que pour te faire plaisir.');
INSERT INTO `npc_questions` VALUES (6440, '', '', '', '', 'Malgr? les informations que tu m\\\'as apport?es, le conseil refuse toujours l\\\'envoi de troupes dans les plaines rocheuses, pr?textant que Bonta ne peut se passer d\\\'autant d\\\'hommes en cas d\\\'attaque br?kmarienne. Cet argument est d\\\'autant plus ?tonnant que les espions n\\\'ont constat? aucun mouvement de troupes significatif ? Br?kmar. Je n\\\'ai aucun int?r?t ? t\\\'envoyer dans la gueule du loup, par cons?quent je vais te confier une autre mission peut-?tre en rapport avec ces bandits.');
INSERT INTO `npc_questions` VALUES (6441, '', '', '', '', 'Merci pour ton aide, tu as repouss? ces bandits avec Brio. Gr?ce ? toi nos marchandises sont intacts, je te dois une fi?re chandelle. A l\\\'occasion, lorsque je serai de retour ? Bonta, passe me voir pour que je puisse te remercier comme tu le m?rites. *smack*');
INSERT INTO `npc_questions` VALUES (6442, '', '', '', '', 'Tu vas escorter la caravane jusqu\\\'? Astrub, elle t\\\'attend ? la sortie Sud. Des miliciens d?guis?s en marchands t\\\'accompagneront. Bonne route.');
INSERT INTO `npc_questions` VALUES (6443, '', '', '', '', 'Bonjour et bienvenue ? la Taverne de la Bagrutte. Ici tu trouveras tout ce dont tu as besoin pour te rafra?chir. Je m\\\'appelle Ecaline, et je peux ?tre ta serveuse exclusive le temps de ton s?jour dans notre ?tablissement, si tu le d?sires bien s?r. Meooww.');
INSERT INTO `npc_questions` VALUES (6444, '', '', '', '', 'Bienvenue ? la Taverne de la Bagrutte. Ici c\\\'est moi qui donne les ordres au client, compris ?');
INSERT INTO `npc_questions` VALUES (6445, '', '', '', '', 'Pas de familiarit? entre nous ou je te fouette. Et pour toi ce sera oui ma?tresse, compris ?');
INSERT INTO `npc_questions` VALUES (6446, '', '', '', '', 'Tu oses me mentir ? Tu sais ce qui t\\\'attends en cas d\\\'insubordination, le Bouftou va se r?galer.');
INSERT INTO `npc_questions` VALUES (6447, '', '', '', '', 'Beurk, tu me d?go?tes ! Finalement je crois que je punirais le Bouftou si je le laissais t\\\'approcher, et je ne tiens pas ? ce que mon futur repas l?che des endroits peu recommandables de ton anatomie. Va me trouver ce Sram et ? l\\\'avenir garde tes troubles du comportement pour toi, t\\\'imaginer avec un Bouftou est r?pugnant, beurk.');
INSERT INTO `npc_questions` VALUES (6448, '', '', '', '', 'Mon oncle Starky va venir me d?livrer et vous botter les fesses, vous verrez. Pas ?tonnant que les Br?kmariens soient tous agressifs, quand on voit les taudis dans lesquels ils vivent il y a de quoi ?tre jaloux de notre magnifique cit? de Bonta.');
INSERT INTO `npc_questions` VALUES (6449, '', '', '', '', 'Le conseil m\\\'emp?che d\\\'envoyer des troupes pour investir le repaire des bandits. Je suis certain que le repaire des bandits contient des informations pouvant nous r?v?ler l\\\'identit? de leur commanditaire mais le conseil m\\\'emp?che d\\\'envoyer des troupes pour l\\\'investir. La mission que je vais donc te demander est risqu?e mais je n\\\'ai pas le choix.');
INSERT INTO `npc_questions` VALUES (6450, '', '', '', '', 'Il te faut mettre la main sur une clef du repaire, je suppose que certains bandits haut plac?s en poss?de un exemplaire. Lorsque tu auras cette clef, prends quelques miliciens ou mercenaires avec toi et rends-toi jusqu\\\'? leur repaire. Inspecte les lieux et r?cup?re tout document qui pourrait faire avancer notre enqu?te. Je compte sur toi et sur ta discr?tion. Vues les connexions de Hersa, elle peut certainement t\\\'?tre utile.');
INSERT INTO `npc_questions` VALUES (6451, '', '', '', '', 'Tu le fais expr?s ? Quand tu t\\\'adresses ? moi tu dis \\\'Ma?tresse\\\', \\\'S\\\'il-vous-pla?t Ma?tresse\\\', \\\'Oui Ma?tresse\\\' !');
INSERT INTO `npc_questions` VALUES (6452, '', '', '', '', 'Tu peux poser une question ? condition qu\\\'elle ne soit pas idiote, sinon tu t?teras de mon fouet.');
INSERT INTO `npc_questions` VALUES (6453, '', '', '', '', 'Je n\\\'ai jamais de probl?me avec les clients, ce sont g?n?ralement eux qui en ont avec moi. Ecaline par contre a tendance ? attirer les gros lourds dans le genre de tes amis. Tu devrais lui poser la question.');
INSERT INTO `npc_questions` VALUES (6454, '', '', '', '', 'Prends ?a ! *Schlak* \\nOn dirait que tu aimes ?a.');
INSERT INTO `npc_questions` VALUES (6455, '', '', '', '', 'Un Ecaflip borgne et sentant l\\\'alcool ? vingt lieues ? la ronde ? J\\\'en connais plusieurs, mais r?cemment il y en a un qui a ennuy? une de nos serveuses, Ecaline. Evite de la brusquer avec cette histoire, elle est jeune et encore sous le choc. Si tu lui fais du mal j\\\'appelle la garde, t\\\'as pig? ?');
INSERT INTO `npc_questions` VALUES (6456, '', '', '', '', 'J\\\'ai eu des probl?mes avec un Ecaflip ressemblant ? la description que tu me fais. Il avait de tr?s mauvaises mani?res et il a pass? la soir?e ? m\\\'importuner. Il a fallu que le tavernier appelle des miliciens pour le mettre ? la porte.\\nTu veux savoir quels miliciens ? Je ne sais plus trop, je ne les connais pas tous, par contre ils ?taient accompagn?s du Capitaine Alrok, ?a j\\\'en suis certaine. Je m\\\'en souviens tr?s bien car il est venu me r?conforter apr?s cet incident. Si tu le cherches c\\\'est l\\\'officier en poste au zaap de Bonta.');
INSERT INTO `npc_questions` VALUES (6457, '', '', '', '', 'Ce fauteur de troubles ? Je m\\\'en rappelle comme si c\\\'?tait hier. Il posait probl?me dans une taverne donc nous l\\\'avons arr?t? et mis en cellule. Malheureusement nous avons re?u l\\\'ordre de le faire sortir d?s le lendemain sous pr?texte qu\\\'il avait des puces et des tiques et qu\\\'on ne voulait pas d\\\'alerte sanitaire dans la prison. C\\\'est bien la premi?re fois que j\\\'entends parler d\\\'alerte sanitaire dans notre prison mais les ordres sont les ordres. \\nJ\\\'ai demand? ? mes hommes de garder un oeil sur lui et ils m\\\'ont rapport? qu\\\'il tra?nait souvent pr?s de la Tour des Ordres, mais tant qu\\\'il se tient ? carreau je ne peux pas le faire arr?ter.');
INSERT INTO `npc_questions` VALUES (6458, '', '', '', '', 'Qu\\\'est-ce que tu veux ? C\\\'est pas interdit de se promener ? ce que je sache alors fous-moi la paix.');
INSERT INTO `npc_questions` VALUES (6459, '', '', '', '', 'Je vois pas de quoi tu parles, fous-moi la paix.');
INSERT INTO `npc_questions` VALUES (6460, '', '', '', '', 'La garce ! Je savais que j\\\'aurais d? l\\\'?liminer quand mes potes et moi en avons eu l\\\'occasion. Dis-moi ce que tu veux et je verrai si nous pouvons trouver un arrangement.');
INSERT INTO `npc_questions` VALUES (6461, '', '', '', '', 'Ahaha, tu crois peut-?tre que je vais te la donner comme ?a ? Laisse-moi rire. Ahahah. \\nCa te co?tera 10000 Kamas et ce n\\\'est pas n?gociable.');
INSERT INTO `npc_questions` VALUES (6462, '', '', '', '', 'Ahahah, je viens de faire une affaire. Tiens, voil? ta clef, pigeon !');
INSERT INTO `npc_questions` VALUES (6463, '', '', '', '', 'Du calme, je plaisantais. Je n\\\'ai pas envie que tu m\\\'humilies encore, alors rends-moi mes poils et prends la clef. Et surtout, ne dis rien ? Hersa.');
INSERT INTO `npc_questions` VALUES (6464, '', '', '', '', 'Tu veux cr?er une clef en plusieurs exemplaires ? Je peux t\\\'aider mais en ?change tu dois m\\\'apporter 5 Planches de Merisier, j\\\'en ai besoin pour r?parer les machines des enclos publics. Les enclos priv?s sont trop peu nombreux et de nombreux ?leveurs sont oblig?s de recourir aux enclos publics, ce qui fatalement use les machines et comme je suis responsable de leur bon fonctionnement, je ne peux pas me permettre de laisser les gens utiliser du mat?riel d?fectueux. Supposons qu\\\'un Iop utilise une dragofesse dont le cuir est compl?tement r?p? et rugueux. Je te laisse imaginer les d?g?ts que ?a peut causer.');
INSERT INTO `npc_questions` VALUES (6465, '', '', '', '', 'Merci, je te dois une fi?re chandelle. Je vais te donner une gel?e de synth?se que j\\\'ai moi-m?me invent?e et une recette pour que tu puisses l\\\'utiliser. Si tu n\\\'as pas les comp?tences requises, demande ? un bricoleur de t\\\'aider. Je te pr?viens de suite, je ne te donnerai pas davantage de gel?e, alors assure-toi que le bricoleur qui l\\\'utilise soit assez comp?tent pour ne pas la g?cher.');
INSERT INTO `npc_questions` VALUES (6466, '', '', '', '', 'Je suis d?sol? mais je ne peux pas envoyer plus d\\\'hommes sans l\\\'aval du conseil. As-tu r?ussi ? p?n?trer dans le repaire des bandits ?');
INSERT INTO `npc_questions` VALUES (6467, '', '', '', '', 'Des documents sur nos convois de marchandises, des documents sur certains prisonniers, divers documents sur des notables de la cit?, tout ?a ne me dit rien qui vaille. Je te f?licite pour ton travail mais fais attention ? toi, je ne puis assurer ta protection en dehors des murs de ce b?timent et il semblerait qu\\\'un ou plusieurs personnages importants de Bonta soient impliqu?s dans cette affaire.');
INSERT INTO `npc_questions` VALUES (6468, '', '', '', '', 'Cette fois je vous donnerai plus de fil ? retordre.');
INSERT INTO `npc_questions` VALUES (6469, '', '', '', '', 'Bien le bonjour, c\\\'est toi qui est de corv?e de ravitaillement ? Tu as d? faire une sacr?e b?tise pour te retrouver ? faire ?a, ? moins que tu viennes d\\\'int?grer la milice et qu\\\'Amayiro ait voulu te bizuter. En tout cas merci pour le jambon.');
INSERT INTO `npc_questions` VALUES (6470, '', '', '', '', 'Salut, vous avez l\\\'air encore plus triste que moi, que vous arrive-t-il ?');
INSERT INTO `npc_questions` VALUES (6471, '', '', '', '', 'Peut-?tre qu\\\'il pr?f?rait les femmes apr?s tout, ou alors c\\\'est parce que vous en avez une toute petite et qu\\\'il cherche un homme, un vrai.');
INSERT INTO `npc_questions` VALUES (6472, '', '', '', '', 'Je vois plusieurs raisons ? ?a : votre laideur, votre haleine, vos go?ts vestimentaires, votre fa?on de cuisiner, votre ?quipement moisi et peut-?tre m?me votre fa?on de..., enfin, vous voyez ce que je veux dire. Ou peut-?tre pr?f?re-t-il simplement les hommes, ou les araknes.');
INSERT INTO `npc_questions` VALUES (6473, '', '', '', '', 'Et ?a vous ?tonne ? Avec votre tronche de cake, votre haleine ? tuer un bwork et un minuscule asticot dans le pantalon vous esp?riez quoi au juste ?');
INSERT INTO `npc_questions` VALUES (6474, '', '', '', '', 'Il fallait vous y attendre, vous ?tiez trop masculine pour elle. Regardez votre carrure, vous ressemblez plus ? une Bworkette qu\\\'? une Tanuki chan. A sa place j\\\'en aurai fait autant.');
INSERT INTO `npc_questions` VALUES (6475, '', '', '', '', 'Je vous comprend, ?a doit ?tre terrible. Plus aucune soir?e pass?e ? la belle ?toile dans les plaines de Cania, plus personne pour vous r?conforter la nuit, plus personne pour vous l?cher le matin. \\nLa perte d\\\'un familier est toujours un moment difficile et ?prouvant mais j\\\'ai entendu dire qu\\\'il ?tait possible de ramener ? la vie un fant?me de familier. Pour ?a vous devez trouver un sanctuaire dans les mar?cages et passer toutes ses ?preuves.');
INSERT INTO `npc_questions` VALUES (6476, '', '', '', '', 'A?e, dur dur. C\\\'est Amayiro qui vous a confi? cette mission suicide ?');
INSERT INTO `npc_questions` VALUES (6477, '', '', '', '', 'Vous tirez la tronche parce que vous m\\\'apportez ma pitance, sympathique comme attitude... Je ne vous remercie pas.');
INSERT INTO `npc_questions` VALUES (6478, '', '', '', '', 'Bonjour, puis-je vous aider ?');
INSERT INTO `npc_questions` VALUES (6479, '', '', '', '', 'Ah c\\\'est vous ? Approchez, Amayiro m\\\'a demand? de vous faire passer un message car il ne pouvait le faire lui-m?me, il craint d\\\'?tre espionn');
INSERT INTO `npc_questions` VALUES (6480, '', '', '', '', 'Le conseil lui a parl? d\\\'un rapport mettant vos actions et votre loyaut? envers Bonta en doute. Ture Inge poss?de une copie de ce rapport mais il refusera de vous la montrer sauf si vous lui apportez une Ceinture de S?curit?. Il a cass? la sienne r?cemment et n\\\'en a pas trouv?e de neuve ? l\\\'h?tel de vente. Sinc?rement, je crois qu\\\'il est trop pingre pour s\\\'en payer une autre.');
INSERT INTO `npc_questions` VALUES (6481, '', '', '', '', 'Je n\\\'ai pas le droit de vous montrer ce rapport, inutile d\\\'insister.');
INSERT INTO `npc_questions` VALUES (6482, '', '', '', '', 'C\\\'est gentil de votre part, mais les ordres sont les ordres et je ne peux pas vous montrer le rapport vous concernant. Par contre pour vous remercier je peux vous dire que le rapport original se trouve dans la Tour des Ordres de Bonta. Je n\\\'ai pas eu le droit d\\\'y jeter un coup d\\\'oeil pour v?rifier son authenticit? ce qui change de la proc?dure habituelle car apr?s tout c\\\'est moi l\\\'expert. Bien s?r, si quelqu\\\'un venait ? le d?rober, je pourrais l\\\'authentifier. Le probl?me, c\\\'est le garde. Une personne aussi habile que vous doit ?tre en mesure de le d?rober sous son nez si quelqu\\\'un d?tourne son attention. Enfin, ?a reste hypoth?tique n\\\'est ce pas ?');
INSERT INTO `npc_questions` VALUES (6483, '', '', '', '', 'Halte ! Qui va l? ?');
INSERT INTO `npc_questions` VALUES (6484, '', '', '', '', 'Oh, ce n\\\'est qu\\\'un chacha. Si je d?tourne mon attention d?s que quelqu\\\'un ou quelque chose approche, je risque de me faire d?rober le document et de me faire taper sur les doigts.');
INSERT INTO `npc_questions` VALUES (6485, '', '', '', '', 'Tr?s dr?le... Tu n\\\'as rien ? faire ici alors va jouer les chachas ailleurs avant que je donne l\\\'alerte. Si je d?tourne mon attention d?s que quelqu\\\'un ou quelque chose approche, je risque de me faire d?rober le document et de me faire taper sur les doigts.');
INSERT INTO `npc_questions` VALUES (6486, '', '', '', '', 'Laissez-moi examiner ?a. \\n... \\nCe rapport a ?t? falsifi?, c\\\'est ind?niable. Il d?gage une odeur repoussante et votre nom a ?t? ajout? par-dessus un autre nom. Regardez, on peut voir que le nom pr?c?dent commence par un X. De la Gel?e de D?gel?e a ?t? utilis?e pour effacer l\\\'ancien nom, je peux vous l\\\'assurer. Larry Poller pourra s?rement vous en dire plus sur le sujet.');
INSERT INTO `npc_questions` VALUES (6487, '', '', '', '', 'Un peu tout le monde peut utiliser cette gel?e. C\\\'est une ressource qui ne co?te pas cher et facile ? se procurer en h?tel des ventes. Certaines personnes utilisent m?me cette gel?e ? des fins inavouables et je suis s?r que vous aussi.');
INSERT INTO `npc_questions` VALUES (6488, '', '', '', '', 'Ah c\\\'est toi ? Je ne t\\\'avais pas reconnu sous cet accoutrement ridicule. Fais vite, je n\\\'ai aucune envie d\\\'?veiller les soup?ons et de me retrouver encha?n? nu dans une salle remplie de Tofounes.');
INSERT INTO `npc_questions` VALUES (6489, '', '', '', '', 'J\\\'ignore o? sont les r?serves de poison mais Rekojel doit s?rement le savoir. C\\\'est un truand Ecaflip qui tra?ne souvent pr?s de l\\\'atelier des bricoleurs. Si tu comptes lui rendre visite, fais attention ? ta bourse. Le coin est plut?t mal fam? et dans Br?kmar ce n\\\'est pas peu dire.');
INSERT INTO `npc_questions` VALUES (6490, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nTu empestes ? cent m?tres et tu oses me demander une faveur ? \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nDonne-moi un saphir et je te dirai o? se trouve les r?serves, si je n\\\'ai pas chang? d\\\'avis d\\\'ici l?. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6491, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nJ\\\'avais chang? d\\\'avis et je voulais te donner l\\\'information gratuitement mais puisque tu insistes, je prends le saphir. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nLes r?serves de poison se trouvent ? un endroit auquel tu n\\\'as pas acc?s, ? c?t? de l\\\'h?tel de ventes des sculpteurs. Seuls les gens naturellement dou?s pour l\\\'espionnage peuvent y p?n?trer en d?jouant les m?canismes cach?s qui en bloquent l\\\'acc?s. En plus, l\\\'endroit est pi?g? et il faut ?tre au moins deux pour ouvrir les grilles mais comme tu n\\\'as pas d\\\'amis, tu n\\\'y arriveras jamais. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6492, '', '', '', '', 'Bonjour, bonjour, ?tes-vous un commer?ant ? Non ? N?gociant, marchand, itin?rant, trafiquant peut-?tre ? Non plus ? Dans ce cas, je peux rien pour vous. J\\\'organise les convois ? destination d\\\'Astrub.');
INSERT INTO `npc_questions` VALUES (6493, '', '', '', '', 'Vous souhaitez escorter le convoi ? mais c\\\'est une g?n?reuse proposition. Tous les b?n?voles sont bienvenus. Vous ?tes b?n?vole bien s?r, vous ne souhaitez pas ?tre r?mun?r? pour ?a j\\\'esp?re. Dans le cas contraire, sachez que je dispose de soldat vaillants et, hum, bon march?. Vous allez nous suivre et vous assurer que rien de f?cheux ne puisse survenir. Oh et un dernier petit d?tail, les soldats ont pour ordre de ne jamais discuter durant le trajet donc n\\\'allez pas les perturber, compris ? \\nPuisque vous ?tes l?, vous allez partir en ?claireur, ?a vous ?vitera de tailler la bavette avec mes gardes.');
INSERT INTO `npc_questions` VALUES (6494, '', '', '', '', 'Rien ? signaler, vous aviez tort de vous inqui?ter finalement. Quoi ? Oh non ... Sauvons-nous !');
INSERT INTO `npc_questions` VALUES (6495, '', '', '', '', 'Ne crois pas que je vais te remercier pour ta g?n?rosit?. Je suis un Roublard, la politesse ne fait pas partie de mon ?ducation.');
INSERT INTO `npc_questions` VALUES (6496, '', '', '', '', 'Tu d?barques ici avec tes grands airs et tu te crois tout permis ? Si tu crois que je vais te donner une information aussi facilement, tu te mets le doigt dans l\\\'oeil.');
INSERT INTO `npc_questions` VALUES (6497, '', '', '', '', 'Tu sais faire affaire avec les Br?kmariens, ?a m\\\'?tonne de ta part. J\\\'ignore ce qui se manigance pr?cis?ment, mais Milone Corichel, le bijoutier, est impliqu? dans une affaire de corruption. Interroge-le si tu veux en savoir plus.');
INSERT INTO `npc_questions` VALUES (6498, '', '', '', '', 'C\\\'est bon t\\\'as gagn?, rends-moi mon tibia. \\n... \\nJ\\\'ignore ce qui se manigance pr?cis?ment, mais Milone Corichel, le bijoutier, est impliqu? dans une affaire de corruption. Interroge-le si tu veux en savoir plus.');
INSERT INTO `npc_questions` VALUES (6499, '', '', '', '', 'Non, piti?, ne me fais pas de mal, je ne suis qu\\\'un pauvre vieillard un peu fou. Je vais te dire tout ce que tu veux savoir et tu peux m?me te servir dans ma bijouterie, c\\\'est gratuit.');
INSERT INTO `npc_questions` VALUES (6500, '', '', '', '', 'Ahahah, tu es encore plus b?te que tes pieds ! Je n\\\'ai qu\\\'? crier un bon coup et toute la milice de Br?kmar viendra te chercher. Tu penses pouvoir g?rer une quarantaine de gardes ? la fois ? Non ? Alors reprenons la discussion d\\\'une fa?on plus courtoise. Une dizaine de milliers de kamas pourrait d?tendre l\\\'atmosph?re.');
INSERT INTO `npc_questions` VALUES (6501, '', '', '', '', 'Vous avez besoin d\\\'aide pour coincer un Br?kmarien ? la Tour de Bonta ? Aucun probl?me, je suis votre homme.');
INSERT INTO `npc_questions` VALUES (6502, '', '', '', '', 'Si Amayiro estime que vous avez besoin d\\\'aide, vous pouvez compter sur moi. Je me rends de ce pas ? la Tour.');
INSERT INTO `npc_questions` VALUES (6503, '', '', '', '', 'Je suis transf?r? ? la Tour de Bonta ? A vos ordres ! \\nJe dois arr?ter toute personne sortant de la Tour ? A vos ordres !');
INSERT INTO `npc_questions` VALUES (6504, '', '', '', '', 'Je dois imm?diatement me rendre ? la Tour de Bonta pour surveiller l\\\'entr?e ? D\\\'accord, mais j\\\'esp?re avoir une prime pour ?a.');
INSERT INTO `npc_questions` VALUES (6505, '', '', '', '', 'Nous avons captur? un Br?kmarien qui tentait de s\\\'enfuir, il est en ce moment m?me en route pour la prison.');
INSERT INTO `npc_questions` VALUES (6506, '', '', '', '', 'Pas d\\\'inqui?tude, nous avons attrap? Xephir?s. Tenez, amenez-le vous m?me ? Amayiro. Apr?s tout c\\\'est gr?ce ? vous que nous avons d?couvert sa trahison. Par contre essayez de ne pas le laisser filer cette fois.');
INSERT INTO `npc_questions` VALUES (6507, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nDonne-moi 1000 Kamas et je t\\\'explique pourquoi je rigole. Donne-moi 1500 Kamas et je te dis o? trouver des salles de jeux clandestines. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6508, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nJe rigole, car tu viens de perdre 1000 Kamas.  \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6509, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nL\\\'ancien patron de la Taverne du Chabrul? tenait une salle de jeux et elle n\\\'est pas morte, contrairement ? lui.  \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6510, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nTu es pauvre, tu n\\\'as plus un sou en poche et tu crois pouvoir survivre ? Br?kmar ? \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6511, '', '', '', '', 'Une salle de jeux ? Je ne vois pas de quoi vous... Ah c\\\'est vous ! Pardon, mille excuses, je ne voulais pas vous mentir. C\\\'est que... je ne peux pas en parler ? n\\\'importe qui, vous comprenez ? Tenez, je vous donne une clef pour que vous puissiez y aller m?me si je suis absente, la porte cach?e se trouve au fond de la salle. C\\\'est toujours un plaisir de recevoir un Br?kmarien de votre rang dans notre taverne. D\\\'ailleurs, ce soir je finis mon service vers 21h30 - 22h00, je vous dis ?a au cas o?...');
INSERT INTO `npc_questions` VALUES (6512, '', '', '', '', 'Une salle de jeux ? Je ne vois pas de quoi vous... Ah c\\\'est vous ! Pardon, mille excuses, je ne voulais pas vous mentir. C\\\'est que... je ne peux pas en parler ? n\\\'importe qui, vous comprenez ? Tenez, je vous donne une clef pour que vous puissiez y aller m?me si je suis absente, la porte cach?e se trouve au fond de la salle. C\\\'est toujours un plaisir de recevoir une Br?kmarienne de votre rang dans notre taverne.');
INSERT INTO `npc_questions` VALUES (6513, '', '', '', '', 'Vous voulez dire que vous ?tes venu sp?cialement pour moi ? C\\\'est tr?s gentil, mais je dois faire des heures suppl?mentaires. Depuis la mort du patron, je n\\\'ai plus de temps pour moi. Mais ?a ne veut pas dire que ?a ne m\\\'aurait pas fait plaisir, bien au contraire. Une autre fois, c\\\'est promis.');
INSERT INTO `npc_questions` VALUES (6514, '', '', '', '', 'Hey dit dit dit dit, t\\\'as pas des kamas pour moi ? Je peux te dire tout ce que je sais sur Trape si t\\\'as des kamas pour moi. Sois pas lourd, file-moi tous tes kamas !');
INSERT INTO `npc_questions` VALUES (6515, '', '', '', '', 'Eh ! T\\\'es compl?tement barge, ?a fait mal. Tout ?a parce que tu veux pas me filer des Kamas.');
INSERT INTO `npc_questions` VALUES (6516, '', '', '', '', 'Tu dis ?a parce que je suis un Sram, c\\\'est ?a ? Pour toi les Srams c\\\'est tous les m?mes, c\\\'est ce que tu penses, pas vrai ? T\\\'as de la chance que mes 50 soient pas l? sinon tu passais ? la casserole. Tu fais partie de la milice en plus ? Alors ?a m\\\'?tonne pas que tu viennes me prendre le chou. Je sais rien sur Trape et m?me si je savais quelque chose je te dirai rien. Tu vas voir, tu vas prendre cher quand mes 50 arriveront. Bon en attendant tu me laisses tranquille d\\\'accord ? L? je fais un effort pour pas te casser en deux tu vois... non pas la peine de t\\\'?nerver, je dis juste ?a pour te pr?venir. Bon d\\\'accord je me tais, mais t\\\'as de la chance que je sache garder mon sang-froid.');
INSERT INTO `npc_questions` VALUES (6517, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA !  \\nT\\\'as l\\\'air d\\\'appr?cier cet endroit, mais quand je suis l? je parle pas affaires alors inutile d\\\'insister. Viens jouer avec nous ou trouve-toi une autre table. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6518, '', '', '', '', 'Salut ? toi camarade Br?kmarien. Ne dis surtout pas ? Oto que je joue pendant mon temps libre, sinon il va me punir de ne pas le faire sur mon temps de travail.');
INSERT INTO `npc_questions` VALUES (6519, '', '', '', '', 'Une Sram dis-tu ? Ouais ?a me dit quelque chose, je l\\\'ai aper?ue une fois ou deux. D\\\'ailleurs la derni?re fois que je suis venue elle a empoch? un gros paquet de Kamas et une rixe a ?clat?. Bien s?r que non je n\\\'ai pas particip? ? cette rixe, tu me prends pour qui ? Je... je n\\\'avais pas mon arme sur moi alors, euh, tu vois quoi, j\\\'ai pr?f?r? rester en retrait pour observer et m\\\'assurer que la rixe n\\\'allait pas d?g?n?rer.');
INSERT INTO `npc_questions` VALUES (6520, '', '', '', '', 'Pourquoi tu prends pas un tabouret pour jouer avec nous ? Plus on est de fous, plus on rit. Ahahaha.');
INSERT INTO `npc_questions` VALUES (6521, '', '', '', '', 'Tu ne mise pas grand chose, aurais-tu peur de perdre ?');
INSERT INTO `npc_questions` VALUES (6522, '', '', '', '', 'C\\\'est la chance du d?butant, ? moins que ce soit une veine de cocu. Je pencherai plut?t pour la deuxi?me solution. Je vais r?pondre ? ta question comme ?a tu ne me piqueras pas tous mes Kamas ce soir. \\nTu vois l\\\'h?tel de vente des mineurs ? Oui, de Br?kmar, ?videmment ! Trape a une planque ? proximit? de l\\\'h?tel de vente, c\\\'est tout ce que je peux te dire et je n\\\'ai pas envie de discuter davantage avec toi. \\nN\\\'oublie pas tes gains.');
INSERT INTO `npc_questions` VALUES (6523, '', '', '', '', 'On dirait que c\\\'est pas ton jour de chance mais je vais quand m?me r?pondre ? ta question, ?a m\\\'?vitera de me coltiner ta tronche toute la soir?e. Tu vois l\\\'h?tel de vente des mineurs ? Oui, de Br?kmar, ?videmment ! Trape a une planque ? proximit? de l\\\'h?tel de vente, c\\\'est tout ce que je peux te dire et je n\\\'ai pas envie de discuter davantage avec toi.');
INSERT INTO `npc_questions` VALUES (6524, '', '', '', '', 'C\\\'est la chance du d?butant, ? moins que ce soit une veine de cocu. Je pencherai plut?t pour la deuxi?me solution. Je vais r?pondre ? ta question comme ?a tu ne me piqueras pas tous mes Kamas ce soir. \\nTu vois l\\\'h?tel de vente des mineurs ? Oui, de Br?kmar, ?videmment ! Trape a une planque ? proximit? de l\\\'h?tel de vente, c\\\'est tout ce que je peux te dire et je n\\\'ai pas envie de discuter davantage avec toi. \\nN\\\'oublie pas tes gains.');
INSERT INTO `npc_questions` VALUES (6525, '', '', '', '', 'C\\\'est la chance du d?butant, ? moins que ce soit une veine de cocu. Je pencherai plut?t pour la deuxi?me solution. Je vais r?pondre ? ta question comme ?a tu ne me piqueras pas tous mes Kamas ce soir. \\nTu vois l\\\'h?tel de vente des mineurs ? Oui, de Br?kmar, ?videmment ! Trape a une planque ? proximit? de l\\\'h?tel de vente, c\\\'est tout ce que je peux te dire et je n\\\'ai pas envie de discuter davantage avec toi. \\nN\\\'oublie pas tes gains.');
INSERT INTO `npc_questions` VALUES (6526, '', '', '', '', 'Je ne retrouve plus ma corne, ?a me fout la rage. J\\\'ai les nerfs en pelote et j\\\'ai envie de tout casser. En plus, cet Ecaflip qui rigole tout le temps ?a m\\\'exasp????re ! J\\\'ai bien envie de lui arracher les moustaches et de me les greffer sous les bras.');
INSERT INTO `npc_questions` VALUES (6527, '', '', '', '', 'Bonjour, c\\\'est Oto Mustam qui t\\\'envoie ?');
INSERT INTO `npc_questions` VALUES (6528, '', '', '', '', 'Ecoute-moi avant de faire une b?tise, j\\\'ai gagn? beaucoup d\\\'argent r?cemment et je suis en mesure de rembourser Oto Mustam avec les int?r?ts. Je sais que j\\\'aurai d? le rembourser il y a plus de deux mois d?j? mais j\\\'avais des soucis financiers. Tu ne vas quand m?me pas m\\\'?liminer alors que j\\\'ai ce qu\\\'il faut pour ton chef, si ? A la limite je veux bien... enfin... je peux aussi combler tes d?sirs si tu me laisses en vie, qu\\\'en penses-tu ?');
INSERT INTO `npc_questions` VALUES (6529, '', '', '', '', 'Merci, crois-moi je n\\\'oublierai ta cl?mence.');
INSERT INTO `npc_questions` VALUES (6530, '', '', '', '', 'Encore merci pour ta cl?mence, ce geste aura beaucoup plus d\\\'impact que tu ne l\\\'imagines.');
INSERT INTO `npc_questions` VALUES (6531, '', '', '', '', 'Je hais ces bandits, ils nuisent au commerce et pire, ? MON commerce. Cette fois ils ont eu une bonne le?on. Merci pour votre aide si ... d?sint?ress?e. Montrez cette broche ? Amayiro pour lui signifier ma reconnaissance. Elle n\\\'a pas de valeur, il me la rendra plus tard.');
INSERT INTO `npc_questions` VALUES (6532, '', '', '', '', 'Merci de m\\\'avoir ?pargn?e. J\\\'esp?re que ?a t\\\'a plu et que les marques de crocs sur ton corps ne sont pas trop douloureuses.');
INSERT INTO `npc_questions` VALUES (6533, '', '', '', '', 'Maudits brigands ! Encore une cargaison pill?e ! Dites ? Amayiro de remplir son devoir et de prot?ger les honn?tes marchands comme moi. Je suis pr?t ? payer pour ma protection s\\\'il le faut. Non, ne lui dites pas cette derni?re phrase.');
INSERT INTO `npc_questions` VALUES (6534, '', '', '', '', 'Je d?teste attendre, surtout quand il s\\\'agit d\\\'argent ou de vengeance. L? c\\\'est les deux ? la fois alors imagine dans quel ?tat je suis. Trape est-elle pass?e ? la trappe ?');
INSERT INTO `npc_questions` VALUES (6535, '', '', '', '', 'Tu as suivi mes ordres, c\\\'est un bon point. Tu as refus? ce que cette garce te proposait et ex?cut? mes ordres ? la lettre, c\\\'est bon pour toi. En v?rit?, il s\\\'agissait d\\\'un test. C\\\'est un double que tu as ?limin? pendant que la vraie Trape venait me faire son rapport sur tes actions. Continue comme ?a et tu iras loin, j\\\'aime les sous-fifres dans ton genre. B?te et disciplin?, tout ce dont j\\\'ai besoin pour mes missions les plus importantes ? condition que tu sois suffisamment apte.');
INSERT INTO `npc_questions` VALUES (6536, '', '', '', '', 'Tu as ?limin? cette garce mais en plus tu as r?cup?r? l\\\'argent, c\\\'est pas mal du tout. Tu as l?g?rement d?sob?it pour que j\\\'en tire profit, j\\\'en prends note. Comme tu as voulu m\\\'amadouer pour tirer parti de ma reconnaissance, je vais te dire la v?rit? : il s\\\'agissait d\\\'un test. C\\\'est un double que tu as ?limin? pendant que la vraie Trape venait me faire son rapport sur tes actions. Continue comme ?a et tu iras loin, j\\\'aime les sous-fifres dans ton genre. B?te et disciplin?, mais prompt ? d?sob?ir si tu peux en tirer un profit personnel. C\\\'est tout ce dont j\\\'ai besoin pour mes missions les plus importantes ? condition que tu sois suffisamment apte.');
INSERT INTO `npc_questions` VALUES (6537, '', '', '', '', 'Tu as suivi mes ordres, c\\\'est un bon point. Tu as abus? de cette garce pour lui faire croire qu\\\'elle ?tait sauv?e puis tu l\\\'as ?limin?e, c\\\'est plut?t vil comme comportement et j\\\'aime ?a. En v?rit?, il s\\\'agissait d\\\'un test. C\\\'est un double que tu as ?limin? pendant que la vraie Trape venait me faire son rapport sur tes actions. Continue comme ?a et tu iras loin, j\\\'aime les sous-fifres dans ton genre. Pas trop b?te mais disciplin?, tout ce dont j\\\'ai besoin pour mes missions les plus importantes ? condition que tu sois suffisamment apte. \\nAu fait, ne t\\\'avise plus de t\\\'approcher d\\\'elle, pour quelque raison que ce soit ! Me suis-je bien fait comprendre ? Ose l\\\'effleurer ou pire, penser ? elle et je te fais avaler un bourbassingue vivant.');
INSERT INTO `npc_questions` VALUES (6538, '', '', '', '', 'Amayiro m\\\'a demand? de vous aider. Cependant, avec la recrudescence des attaques de convoi, je ne peux me s?parer de mes hommes. Vous avez peut-?tre des amis qui peuvent vous aider. Sinon, vous ?tes seul.');
INSERT INTO `npc_questions` VALUES (6539, '', '', '', '', 'Je r?sume : tu as pris l\\\'argent, tu as abus? de cette garce pour lui faire croire qu\\\'elle ?tait sauv?e et une fois que tu avais termin? tu l\\\'as ?limin?e. J\\\'avais sous-estim? ? quel point tu pouvais ?tre mal?fique. \\nPour te dire la v?rit?, c\\\'?tait un test et tu l\\\'as pass? avec brio ! C\\\'est un double que tu as ?limin? pendant que la vraie Trape venait me faire son rapport sur tes actions et je suis impressionn?. Continue comme ?a et tu iras loin, j\\\'aime les sous-fifres dans ton genre. Empli de malices et ex?cutant les ordres de la mani?re la plus vile et la plus perfide qui soit, nombre de d?mons ne t\\\'arrivent pas ? la cheville. J\\\'ai justement besoin de personnes dans ton genre ? qui confier les missions les plus importantes ? condition que tu sois suffisamment apte. \\nAu fait, ne t\\\'avise plus de t\\\'approcher d\\\'elle, pour quelque raison que ce soit ! Me suis-je bien fait comprendre ? Ose l\\\'effleurer ou pire, penser ? elle et je te fais avaler un bourbassingue vivant.');
INSERT INTO `npc_questions` VALUES (6540, '', '', '', '', 'Ecoute-moi bien, mes ordres ?taient de l\\\'?liminer. Tu as r?cup?r? les Kamas et ?a c\\\'est bien m?me si je ne te l\\\'avais pas demand?, par contre tu n\\\'avais aucune raison de la laisser en vie. J\\\'appr?cie l\\\'insubordination mais il y a des limites ? ne pas franchir. D\\\'ailleurs je dois te dire que tout ceci n\\\'?tait qu\\\'un test. Trape me sert ? ?valuer les recrues d\\\'un certain rang pour que je puisse juger ? quelle point elles sont mal?fique. Tu as encore des progr?s ? faire, la cl?mence est un d?faut que je ne tol?re pas. Tu t\\\'en es bien sorti jusqu\\\'? pr?sent alors tache d\\\'oublier les quelques valeurs morales qui te restent et tu pourras esp?rer atteindre les plus hauts rangs au sein de notre milice. \\nUn dernier petit d?tail : ne t\\\'avise plus de t\\\'approcher de Trape, pour quelque raison que ce soit ! Me suis-je bien fait comprendre ? Ose l\\\'effleurer ou pire, penser ? elle et je te fais avaler un bourbassingue vivant.');
INSERT INTO `npc_questions` VALUES (6541, '', '', '', '', 'Mais c\\\'est pas vrai, c\\\'est un v?ritable cauchemar ! Comment ai-je pu enr?ler une cr?ature aussi, aussi... il n\\\'y a pas de mot pour qualifier ta stupidit?. Tu oses me d?sob?ir et prendre du bon temps avec la cible que je t\\\'avais d?sign?e ? \\nPour ta gouverne sache que Trape agissait sur service command? et qu\\\'elle me sert ? tester les andouilles dans ton genre. Je voulais savoir ? quel point tu ?tais mal?fique pour te confier des missions plus importantes mais je me suis fourvoy?. Tiens, voil? une liste de course, si tu me rapportes ces objets j\\\'?viterai peut-?tre de donner l\\\'ordre ? mes meilleurs assassins de t\\\'?liminer membre par membre. \\nUn dernier petit d?tail : ne t\\\'avise plus de t\\\'approcher de Trape, pour quelque raison que ce soit ! Me suis-je bien fait comprendre ? Ose l\\\'effleurer ou pire, penser ? elle et je te fais avaler un bourbassingue vivant.');
INSERT INTO `npc_questions` VALUES (6542, '', '', '', '', 'Hmmmmff... Mmmmfff !');
INSERT INTO `npc_questions` VALUES (6543, '', '', '', '', 'Si tu veux une r?ponse ? ta question tu dois d\\\'abord miser. \\nCombien veux-tu miser ?');
INSERT INTO `npc_questions` VALUES (6544, '', '', '', '', 'Tu as le sens du jeu et le go?t du risque, tu ne vis pas ? Br?kmar pour rien.');
INSERT INTO `npc_questions` VALUES (6545, '', '', '', '', 'Toi on peut dire que tu n\\\'as pas froid aux yeux. Les Ecaflips doivent appr?cier de parier avec toi.');
INSERT INTO `npc_questions` VALUES (6546, '', '', '', '', 'Pour l\\\'instant, rien ? signaler. Pas ?tonnant puisque nous venons ? peine de passer l\\\'avant-poste.');
INSERT INTO `npc_questions` VALUES (6547, '', '', '', '', 'Tu es une larve. Une larve c\\\'est b?te, disciplin? et ?a rampe devant son ma?tre. A partir de maintenant tu feras ce que je t\\\'ordonne, tu oublieras toute compassion et ton plus grand d?sir sera d\\\'oeuvrer pour la gloire de Djaul et de Br?kmar. Si tu oses faire preuve ne serait-ce que d\\\'une once de morale ou de vertu, tes entrailles serviront de laisses aux Crocs Glands tandis que ta cervelle sera jet?e en p?ture ? des Iops affam?s. Maintenant hors de ma vue.');
INSERT INTO `npc_questions` VALUES (6548, '', '', '', '', 'Je ne veux plus te revoir jusqu\\\'? ce que tu m\\\'apportes les sacs demand?s. Si tu insistes trop tu finiras au fond du nez du kralamoure g?ant. \\nJe me fiche qu\\\'il n\\\'ait pas de nez ! Tout autre orifice fera l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (6549, '', '', '', '', 'Salutations, est-ce toi qui a combattu les Br?kmariens pr?s de la Baie de Cania ?');
INSERT INTO `npc_questions` VALUES (6550, '', '', '', '', 'F?licitations, en d?faisant les Br?kmariens nous avons d?jou? leur plan. Ce qui m\\\'inqui?te par contre c\\\'est la qualit? de leur ?quipement. D\\\'apr?s tes dires, leurs miliciens seraient mieux ?quip?s que les n?tres ? C\\\'est inadmissible ! Ne sommes-nous pas la plus puissante cit? du Monde des douze ? \\nVoici 2000 Kamas pour ton exploit. Maintenant tu peux disposer, j\\\'en toucherai deux mots ? Amayiro.');
INSERT INTO `npc_questions` VALUES (6551, '', '', '', '', 'Tu dis que nos miliciens ont ?t? d?faits en raison d\\\'un ?quipement bien inf?rieur en qualit? ? celui des Br?kmariens ? C\\\'est inadmissible ! Ne sommes-nous pas la plus puissante cit? du Monde des douze ? \\nJe vais en toucher deux mots ? Amayiro, tu peux disposer.');
INSERT INTO `npc_questions` VALUES (6552, '', '', '', '', 'As-tu regard? l\\\'?quipement de la milice avant de venir m\\\'insulter ? C\\\'est ce jeune freluquet disciple d\\\'Osamodas qui a eu l\\\'exclusivit? du contrat, ce Latem Sa. Il n\\\'est m?me pas capable de dresser des Tofus alors fabriquer une arme... Tu veux mon avis ? Il a eu le contrat uniquement parce que son p?re est en affaires avec notre intendant. Si tu cherches cet incomp?tent, il travaille comme apprenti forgeron ? Astrub, la cit? des mercenaires.');
INSERT INTO `npc_questions` VALUES (6553, '', '', '', '', 'Je forge l\\\'?quipement pour la milice de Bonta depuis plusieurs mois et c\\\'est beaucoup plus fatiguant que je l\\\'imaginais, surtout depuis que Deudoin? a d?sert? la forge pour l\\\'h?tel de vente. Je commence ? s?rieusement me demander si j\\\'ai bien choisi mon m?tier, en plus ici mes Tofus ne me sont d\\\'aucune utilit?. \\nEn fait, je fais surtout ce m?tier pour faire plaisir ? mon p?re, il m\\\'a obtenu ce poste gr?ce ? ses relations ? Bonta.');
INSERT INTO `npc_questions` VALUES (6554, '', '', '', '', 'Tu m\\\'as apport? des mat?riaux pour que je te forge une arme ? Aucun probl?me, tu vas voir la dext?rit? dont je fais preuve. \\n... \\nEt voil? le travail. ?a t\\\'impressionne, pas vrai ? \\nSi tu estimes que ce n\\\'est pas un pur chef d\\\'?uvre, va te plaindre aupr?s de Danathor, c\\\'est lui qui g?re les questions de l\\\'?quipement de la milice.');
INSERT INTO `npc_questions` VALUES (6555, '', '', '', '', 'Bonjour, noble soldat. Puis-je te renseigner ?');
INSERT INTO `npc_questions` VALUES (6556, '', '', '', '', 'Latem Sa est loin d\\\'?tre incomp?tent, il s\\\'agit d\\\'une erreur. Il y a s?rement une autre explication ? la mauvaise qualit? de l\\\'?quipement de nos miliciens. Je tiens toutefois ? te remercier de m\\\'avoir fait part de ce probl?me fort inqui?tant, je vais de ce pas prendre les mesures qui s\\\'imposent afin d\\\'arranger la situation. Continue de bien servir notre cit? et la grande Jiva saura s\\\'en montrer reconnaissante.');
INSERT INTO `npc_questions` VALUES (6557, '', '', '', '', 'Des forgerons comp?tents ? J\\\'en connais pas des masses. Il y a moi et... voyons voir... il y a peut-?tre Hanniboul Smisse, dans le temps nous avons travaill? ensemble pour la milice de Bonta mais il a d?sert?. C\\\'est le seul forgeron qui vaille la peine. Il s\\\'est install? une forge dans le village d\\\'Amakna, loin de la guerre et des conflits.');
INSERT INTO `npc_questions` VALUES (6558, '', '', '', '', 'Travailler pour l\\\'arm?e ? Plus jamais ! Si je suis parti il y a de ?a quelques ann?es, ce n\\\'est pas pour y retourner maintenant. Je me suis install? dans le village d\\\'Amakna pour ?tre au calme. Ici pas de conflit et pas de soucis. Vous devriez faire de m?me avant qu\\\'il ne soit trop tard. D\\\'ailleurs si vous comptez suivre mon conseil, la milice d\\\'Amakna a recrut? une jolie Iop qui se fera un plaisir de vous aider ? quitter la milice de Bonta. Par contre si vous pers?v?rez dans votre voie, je ne peux rien pour vous, mais peut-?tre qu\\\'Otho Laringo acceptera de vous aider. Il tient l\\\'atelier au nord du village.');
INSERT INTO `npc_questions` VALUES (6559, '', '', '', '', 'J\\\'aurais accept? si je n\\\'avais pas d?j? un millier de commandes en retard. Je dois forger des armes pour pourfendre le Meulou, scalper le Bworker et ?ventrer le Minotot, alors ?quiper une milice, pas le temps. Par contre dans ma jeunesse j\\\'ai connu un forgeron qui, pour une raison obscure, s\\\'?tait retir? dans les montagnes. Je ne l\\\'ai plus revu depuis au moins dix ans mais je suis s?r que lui au moins il ne doit pas crouler sous les commandes. Va voir Graham Finame dans l\\\'atelier au sud-est, il s\\\'en souvient peut-?tre.');
INSERT INTO `npc_questions` VALUES (6560, '', '', '', '', 'Mes armes sont destin?es ? pourfendre des monstres et mes armures ? se prot?ger des m?mes monstres. Je ne fabrique pas d\\\'?quipement pour que des hommes s\\\'?tripent les uns les autres. J\\\'ai connu un forgeron qui avait moins de scrupules, mais il s\\\'est ?vanoui dans la nature il y a des ann?es et nul ne l\\\'a revu depuis, sauf peut-?tre Norb. Tu ne connais pas Norb ? C\\\'est le forgeron qui a repris r?cemment la forge dans la Plaine des Scarafeuilles.');
INSERT INTO `npc_questions` VALUES (6561, '', '', '', '', 'R?fl?chissons, que pourrais-je bien vous demander ? \\nPour commencer, vous allez m\\\'apporter des plats cuisin?s. J\\\'en ai marre de manger les restes laiss?s par le mulou. Je veux du poisson, de pr?f?rence pas trop cuit et pas frit, 5 Goujons en tranche de bonne qualit? feront l\\\'affaire. Je veux aussi de la bi?re qui ressemble ? de l\\\'ammoniac et qui sent le cochon grill?, comme celle que l\\\'on trouve ? Br?kmar. Amenez-moi tout ?a pour que je puisse r?fl?chir ? un moyen de vous faire confiance, je r?fl?chis mieux le ventre plein.');
INSERT INTO `npc_questions` VALUES (6562, '', '', '', '', 'mmmh, je vous vois, vous ?tes en train de sourire. Je sens que vous me pr?parez un sale coup. Vous avez empoisonn? la nourriture ? Dans le doute je pr?f?re la jeter. Et cette bi?re ? trop l\\\'odeur d\\\'ammoniac ou pas assez, c\\\'est louche... Je pr?f?re la jeter aussi. \\nJ\\\'ai bien r?fl?chi et je sais ce que je veux. C\\\'est tr?s simple et vous ne devriez avoir aucune difficult? ? vous en procurer ? Bonta. Il s\\\'agit d\\\'une Dragofesse en Cuir Violet de Bwork. J\\\'ai us? la derni?re depuis longtemps et il est grand temps de la remplacer, ?a m\\\'?vitera de me faire des cloques ? cause du frottement. Quoi, pourquoi me regardez-vous comme ?a ? J\\\'ai dis quelque chose de choquant ?');
INSERT INTO `npc_questions` VALUES (6563, '', '', '', '', 'Ouah, elle est magnifique. Vous me garantissez qu\\\'elle n\\\'a jamais ?t? utilis?e ? Je ne veux pas attraper de cochonneries. \\nJe vais enfin pouvoir me d?barrasser de l\\\'ancienne. Fini les br?lures, les cloques et les onguents ! \\nJe dois encore vous tester pour ?tre s?r que vous ne me jouez pas un sale coup.');
INSERT INTO `npc_questions` VALUES (6564, '', '', '', '', 'Mettez-vous ? quatre pattes.');
INSERT INTO `npc_questions` VALUES (6565, '', '', '', '', 'Aboyez.');
INSERT INTO `npc_questions` VALUES (6566, '', '', '', '', 'C\\\'est bien, bon chienchien. Maintenant curez-vous le nez avec les orteils.');
INSERT INTO `npc_questions` VALUES (6567, '', '', '', '', 'Ah, je pr?f?re ?a. Je ne fais pas confiance aux gens qui en font trop, ?a cache toujours quelque chose. L? au moins vous ne vous ?tes pas laiss? faire, ?a veut dire que vous ne cherchez pas trop ? m\\\'avoir. Je veux bien r?fl?chir ? votre proposition.');
INSERT INTO `npc_questions` VALUES (6568, '', '', '', '', 'Quelle souplesse, vous m\\\'impressionnez ! A pr?sent, allez amadouer le mulou en r?p?tant les gestes que vous venez de faire. Et surtout, n\\\'oubliez pas d\\\'aboyer, sinon il risque de se rendre compte de la supercherie.');
INSERT INTO `npc_questions` VALUES (6569, '', '', '', '', 'Nara est toujours vivant ? Depuis le temps, je pensais qu\\\'un Mulou avait eu raison de ce vieux parano?aque. Si tu veux savoir o? tu pourrais l\\\'installer, il va falloir me donner quelque chose en ?change. Disons 3000 Kamas ou un Souvenir d\\\'Enutrof.');
INSERT INTO `npc_questions` VALUES (6570, '', '', '', '', 'C\\\'est un plaisir de faire affaire avec toi. Je vois trois lieux pouvant convenir ? Nara. \\nLe premier se trouve pr?s d\\\'ici, dans la mine de la Montagne des Craqueleurs. Par contre il y a beaucoup de va-et-viens de mineurs, sans compter les chasseurs de larves qui passent ? proximit?. \\nLe deuxi?me se trouve dans le village m?me d\\\'Amakna, sous la fontaine centrale. C\\\'est un endroit charmant quoiqu\\\'un peu humide. \\nQuant au troisi?me, il se trouve dans la Mine Est du Territoire des Porcos, c\\\'est un endroit assez recul? mais difficile d\\\'acc?s.');
INSERT INTO `npc_questions` VALUES (6571, '', '', '', '', 'Qui va l? ? Montrez-vous ! \\nAh, c\\\'est vous. Qu\\\'est-ce que vous voulez ?');
INSERT INTO `npc_questions` VALUES (6572, '', '', '', '', 'Je connais la mine de la Montagne des Craqueleurs, il y a beaucoup trop de passage et je vais devoir batailler avec les mineurs sombres qui voudront me voler mes pr?cieux alliages. \\nM\\\'installer sous la place d\\\'Amakna est hors de question, je ne veux pas me retrouver dans un village avec des gens ? proximit?, ?a me rend malade rien que d\\\'y penser. \\nLa Mine des Porcos ? Ca m\\\'a l\\\'air un coin paum? loin de tout, ?a me tente davantage. \\nC\\\'est d?cid?, je vais d?m?nager dans la Mine des Porcos. En attendant, vous allez me pr?parer tout ce dont j\\\'ai besoin pour forger l\\\'?quipement des miliciens. Je vous ai pr?par? une liste, il suffit de la suivre.');
INSERT INTO `npc_questions` VALUES (6573, '', '', '', '', 'Avec ?a je vais pouvoir commencer ? installer des pi?ges afin d\\\'?viter la visite d\\\'intrus. Non, je ne suis pas capable de cr?er des pi?ges qui font la diff?rence entre de vrais intrus et de simples visiteurs, mais quelle importance ?');
INSERT INTO `npc_questions` VALUES (6574, '', '', '', '', 'Vous voulez me tester, vous ne me faites pas confiance ? Si vous ne me croyez pas capable de forger un bon ?quipement pourquoi m\\\'avoir recrut? ? \\nPour la peine je vais vous forger une lame si puissante que vous serez incapable de la manier correctement, ahahah.');
INSERT INTO `npc_questions` VALUES (6575, '', '', '', '', 'Salutations, est-ce toi qu\\\'Amayiro m\\\'envoie pour r?gler notre gros probl?me de manoeuvres ?');
INSERT INTO `npc_questions` VALUES (6576, '', '', '', '', 'Je suppose qu\\\'il t\\\'a d?j? r?sum? la situation donc je n\\\'irai pas par quatre chemins. Nos miliciens sont nuls, ils ne sont pas capables de coordonner leurs actions ce qui rend toutes nos strat?gies inefficaces. Il nous faut trouver un tacticien qui puisse faire le lien entre nos strat?gies et nos troupes ?cervel?es. \\nLa biblioth?que de Pandala est r?put?e pour poss?der la plus grande collection d\\\'?uvres traitant de strat?gie et d\\\'histoire militaire, dont l\\\'incontournable ? L\\\'art de la guerre en getas ? ou encore ? Guerre et pet ?, sublime t?moignage Pandawa. Sans nul doute pourras-tu trouver quelque tacticien ? recruter l?-bas.');
INSERT INTO `npc_questions` VALUES (6577, '', '', '', '', 'Des tacticiens viennent parfois ici car notre biblioth?que compte plusieurs ouvrages de r?f?rence. Il y a un tacticien en particulier qui a pass? ces trente derni?res ann?es ? ?tudier la tactique, un Enutrof du nom de Dr?na Nassema. Malheureusement il s\\\'?tait r?cemment mis en t?te de se rendre au Donjon des Squelettes pour mettre son apprentissage en pratique. Je dis malheureusement car son retour ?tait pr?vu il y a plus d\\\'une semaine et nous sommes toujours sans nouvelles de lui. Je suppose que quelque chose a mal tourn');
INSERT INTO `npc_questions` VALUES (6578, '', '', '', '', 'Un instant, je r?fl?chis.');
INSERT INTO `npc_questions` VALUES (6579, '', '', '', '', 'Figurez-vous que j\\\'?tais venu mettre en pratique trente ann?es d\\\'apprentissage acharn?. Je m\\\'?tais trouv? des compagnons de route qui souhaitaient exploser des Chafers pour r?cup?rer leurs os. Tout se passait bien jusqu\\\'? ce que l\\\'Eniripsa et le F?ca nous abandonnent en pr?textant que leur m?re allait les gronder s\\\'ils ne rentraient pas vite ? la maison. Non mais vous imaginez un peu ? Nous abandonner comme ?a en plein milieu d\\\'un donjon ? \\nMes autres compagnons ont tent? de sortir mais ils se sont fait massacrer puis d?couper en rondelles carr?es. Quant ? moi, j\\\'ai creus? un trou ? l\\\'aide de ma pelle et confectionn? une ?chelle avec les restes de mes compagnons. J\\\'ai eu de la chance, aucun des monstres du dessus ne s\\\'est encore aventur? ici. Dites, ?a vous dirait de m\\\'aider ? sortir ?');
INSERT INTO `npc_questions` VALUES (6580, '', '', '', '', 'C\\\'est vrai ? Vous me proposez de venir assister vos troupes lors des manoeuvres ? Ca sera avec grand plaisir. Sortez-moi de l? et accompagnez-moi jusqu\\\'? votre chef. D\\\'apr?s mon estimation, seulement deux groupes nous s?parent de la sortie. \\nAh ben zut, voil? justement des ribs, il ont d? vous suivre. Je vous laisse vous en occuper, je suis trop fatigu? pour combattre.');
INSERT INTO `npc_questions` VALUES (6581, '', '', '', '', 'Salutations, o? en sont les recherches d\\\'un tacticien potable pour nous aider ? am?liorer l\\\'efficacit? sur le terrain de notre milice ?');
INSERT INTO `npc_questions` VALUES (6582, '', '', '', '', 'Si seulement notre milice pouvait compter plus d\\\'individus dans ton genre... Tu as fait du bon travail, je n\\\'oublierai pas d\\\'en parler ? Amayiro.');
INSERT INTO `npc_questions` VALUES (6583, '', '', '', '', 'Ah lui ? En fait c\\\'est la premi?re fois que je le vois. Il voulait savoir si je travaillais pour Bonta mais je lui ai r?pondu que non. Par contre je lui ai dit que c\\\'?tait le cas de Nara, j\\\'ai bien fait ?');
INSERT INTO `npc_questions` VALUES (6584, '', '', '', '', 'La liste ? Ah oui, la liste. Tenez, la voil?. Au passage, d?barrassez-moi de sa caisse d\\\'outils, elle encombre ma forge depuis trop longtemps.');
INSERT INTO `npc_questions` VALUES (6585, '', '', '', '', 'D?sol? j\\\'ai cru que vous ?tiez quelqu\\\'un d\\\'autre. Rassurez-moi, personne ne vous a suivi ? Vous devriez faire plus attention, on ne sait jamais ce qui se cache dans l\\\'ombre. \\nA voir votre ?tat on dirait que vous avez eu quelques probl?mes ? arriver jusqu\\\'ici. Norb n\\\'avait pas oubli? de vous indiquer le raccourci au moins ? \\nC\\\'est pas tout mais j\\\'ai du travail, alors si vous n\\\'avez plus rien ? faire ici je ne vous retiens pas.');
INSERT INTO `npc_questions` VALUES (6586, '', '', '', '', 'A vrai dire je ne pr?f?re pas en parler, surtout que l\\\'intendant Danathor a fait passer une loi qui rend passible d\\\'emprisonnement toute personne surprise ? discuter de magie noire, rites obscurs ou tout autre sorcellerie associ?e aux d?mons.');
INSERT INTO `npc_questions` VALUES (6587, '', '', '', '', 'La magie bwork est une magie ?l?mentaire et ? ce titre elle est assez proche de celle utilis?e par les disciples des douze dieux. La diff?rence la plus nette r?side dans son utilisation plus que dans ses effets. Lorsqu\\\'un bwork mage utilise la magie, il n\\\'en a jamais un contr?le parfait, il r?cite plut?t des formules qui produisent l\\\'effet d?sir? avec plus ou moins de pr?cision. Quelques rares bworks mages plus intelligents et talentueux que les autres ne se contentent pas d\\\'apprendre par coeur des formules mais cherchent ? parfaire leur ma?trise des ?l?ments. Ils cr?ent alors des sortil?ges et des envo?tements aux effets vari?s mais souvent d?vastateurs.');
INSERT INTO `npc_questions` VALUES (6588, '', '', '', '', 'Je n\\\'en sais pas plus ? son sujet mais ? mon avis les Sadidas gardent une certaine rancoeur ? son ?gard, m?me si cette histoire date d\\\'il y a plusieurs si?cles. Si tu souhaites vraiment en savoir plus, Epuop Tik au temple Sadida pourra probablement te renseigner, c\\\'est une encyclop?die vivante sur tout ce qui touche ? sa race. Au pire tu peux ?galement interroger des bworks mages mais comme ils tra?nent souvent avec leurs cousins moins ?volu?s, tu risques de devoir broyer quelques cr?nes avant de pouvoir entamer la moindre discussion.');
INSERT INTO `npc_questions` VALUES (6589, '', '', '', '', 'Hyooohooo, qui vous a parl? de ?a ? Serait-ce parce que vous vous inqui?tez du sort des arbres ? Dans ce cas je veux bien vous raconter son histoire. Il y a plusieurs si?cles, alors que la foi dans les dieux ?tait encore jeune, un bwork mage des cavernes des plus puissants mais aussi des plus m?chants jeta un terrible envo?tement : la Grafioze. Cet envo?tement s\\\'av?ra inoffensif pour les ?tres vivants et les v?g?taux, except? les ormes. Ces arbres majestueux autrefois si nombreux p?rirent par dizaines sous l\\\'effet de la Grafioze dont l\\\'?tendue ne cessait de cro?tre. Un groupe de Sadidas en chercha l\\\'origine et traqua le bwork mage jusque dans sa tani?re. L?, ils lui firent subir la souffrance inflig?e aux ormes au centuple, mais Sadida lui-m?me trouva la punition insuffisante. Il intervint en personne et ch?tia le bwork mage de la pire fa?on qui soit : il transforma le fautif en poup?e et il l\\\'offrit ? la premi?re mama bwork qu\\\'il croisa.');
INSERT INTO `npc_questions` VALUES (6590, '', '', '', '', 'Nul ne peux imaginer l\\\'ampleur des tourments inflig?s au bwork mage, mais jusqu\\\'? ce jour aucun autre bwork mage ne s\\\'est risqu? ? partir sur les traces de la formule de la Grafioze car ils savent que le dieu Sadida les jugera encore plus s?v?rement. Vous pouvez me croire, ils sont bien avis?s de penser ainsi.');
INSERT INTO `npc_questions` VALUES (6591, '', '', '', '', 'C\\\'est une infection, pourquoi les dieux se sont-ils montr?s aussi cruels ?');
INSERT INTO `npc_questions` VALUES (6592, '', '', '', '', 'Ce qui ne va pas ? Ne sens-tu pas la puanteur ambiante ? Les dieux m\\\'ont dot? d\\\'un odorat surd?velopp? afin qu\\\'il me soit permis de maudire chaque jour de mon existence. Je ne peux pas en vouloir ? mes fr?res, leurs effluves gastriques ne sont pas volontaires. Je ne peux pas non plus quitter cet endroit car Bworknroll en profiterait pour s\\\'autoproclamer archimage bwork. Les dieux m\\\'ont maudits pour une raison connue d\\\'eux seuls et je ne puis rien faire contre ?a.');
INSERT INTO `npc_questions` VALUES (6593, '', '', '', '', 'Et comment pourrais-tu m\\\'aider ? Comment pourrais-tu conjurer une mal?diction lanc?e par les dieux eux-m?mes ? M?me mon grimoire ne m\\\'apporte que peu de r?confort face ? cette situation. Chaque jour est pire que le pr?c?dent, j\\\'ignore combien de temps je pourrai tenir encore. J\\\'ai bien essay? de me boucher le nez, mais il ne me reste alors qu\\\'une seule main pour tenir mon grimoire et jeter mes sortil?ges. Crois-moi, ce n\\\'est pas pratique du tout sans compter les crampes que ?a provoque. \\nMais toi, tu peux sortir d\\\'ici et interroger les ?rudits. J\\\'ai entendu dire que ceux de ton peuple ont acc?s ? de vastes biblioth?ques, peut-?tre que la solution se trouve dans l\\\'un de ces ouvrages.');
INSERT INTO `npc_questions` VALUES (6594, '5899;6491', '', '', '0', 'Salut ? toi ! Avec un membre de ma famille, nous organisons des traques d\\\'un genre particulier. Si tu veux participer, dis-le moi. Je te d?signerai alors une cible ? abattre. Si tu y parviens, je te r?compenserai. Attention, je ne veux pas voir de l?ches ni de vantards. Ici, les combats sont ?quitables et honorables. Malheureusement, il n\\\'est pas toujours possible de trouver des adversaires de forces ?gales.  Si je trouve quelqu\\\'un, je te remettrai des parchemins de recherche pour t\\\'aider. Alors, pr?t ? en d?coudre ?');
INSERT INTO `npc_questions` VALUES (6595, '', '', '', '', 'Pnj(1121) et Message(6594)');
INSERT INTO `npc_questions` VALUES (6596, '', '', '', '', 'Je suis tr?s occup?e alors pas le temps de t\\\'expliquer quoi que ce soit. Ce que je peux faire par contre c\\\'est te vendre un plan ? 500 Kamas qu\\\'un autre Bricoleur pourra utiliser pour t\\\'en fabriquer, qu\\\'en penses-tu ?');
INSERT INTO `npc_questions` VALUES (6597, '', '', '', '', 'Z\\\'est un biragle ! Gue ne zens blus rien. Vous boz?dez de brodiguieux bouvoirs, z\\\'est ind?niable. Boi gui be groyait un buizant bague gue ne zuis rien gombar? ? vous.  \\nGue boz?de les resdes de la boub?e gui vut gadis un buizant bague bwork des gavernes. En la ravizdolant un beu... beaugoup b?be, et en la baignant dans des eaux enjant?es en r?zidant un riduel Zadida, vous devriez bouvoir en direr guelgues invorbazions. Lorsgue le riduel zera achev?, il vaudra adendre blusieurs gours avant gue zes evets ze vasent rezentir dong inudile de vaire le bied de bidouf. \\nBour ravisdolez la boub?e, vaites dong abbel ? un Zadida, ils sont azez dou?s bour za. G\\\'en gonna?t une, Bazgara, gui est une egzberte en la badi?re.');
INSERT INTO `npc_questions` VALUES (6598, '', '', '', '', 'Qu\\\'as-tu fait ? cette poup?e ? Tu as vu dans quel ?tat d?plorable tu l\\\'as mise ? La rafistoler ne va pas ?tre une mince affaire, je me demande m?me si je vais y parvenir. Au lieu de rester plant? l?, va me chercher 1 Cocon de Ver ? Soie, 1 Aiguille du Costumage, 5 Feuilles de Tronknyde et 2 Cuirs de Boufton Noir.');
INSERT INTO `npc_questions` VALUES (6599, '', '', '', '', 'Vu son ?tat critique, elle va ?tre difficile ? sauver. J\\\'esp?re qu\\\'il n\\\'est pas d?j? trop tard. \\n... \\nVoil?, j\\\'ai fait du mieux que j\\\'ai pu mais le r?sultat n\\\'est pas tr?s probant. Je me demande ce que tu as fais avec, elle ?tait dans un tel ?tat qu\\\'on aurait pu croire qu\\\'elle avait ?t? transmise entre plusieurs g?n?rations de bworkettes. A l\\\'avenir tu as int?r?t d\\\'en prendre soin sinon le dieu Sadida risque d\\\'?tre offens? par ton attitude n?gligeante ? l\\\'?gard de ses cr?ations.');
INSERT INTO `npc_questions` VALUES (6600, '', '', '', '', 'Bonjour noble serviteur de Bonta. La mission que je t\\\'ai confi?e pour la plus grande gloire de Bonta avance-t-elle ?');
INSERT INTO `npc_questions` VALUES (6601, '', '', '', '', 'Bonjour noble servante de Bonta. La mission que je t\\\'ai confi?e pour la plus grande gloire de Bonta avance-t-elle ?');
INSERT INTO `npc_questions` VALUES (6602, '', '', '', '', 'Tu es d?cid?ment plein de talents, je comprends pourquoi Amayiro t\\\'estime autant. En attendant que l\\\'enchantement fasse effet, retourne aupr?s de lui. Tu reviendras me voir d?s que la poup?e sera pr?te. Tant que j\\\'y pense, prends cette bourse de Kamas, toute personne se mettant au service de l\\\'intendant de son plein gr? est toujours r?compens?e. Si tu continues ? bien me servir, il y a de fortes chances pour que ta progression au sein de la milice soit plus rapide, ne l\\\'oublie pas. Jiva appr?cie les hommes d?vou?s corps et ?me ? sa cause.');
INSERT INTO `npc_questions` VALUES (6603, '', '', '', '', 'Tu es d?cid?ment pleine de talents, je comprends pourquoi Amayiro t\\\'estime autant. En attendant que l\\\'enchantement fasse effet, retourne aupr?s de lui. Tu reviendras me voir d?s que la poup?e sera pr?te. Tant que j\\\'y pense, prends cette bourse de Kamas, toute personne se mettant au service de l\\\'intendant de son plein gr? est toujours r?compens?e. Si tu continues ? bien me servir, il y a de fortes chances pour que ta progression au sein de la milice soit plus rapide, ne l\\\'oublie pas. Jiva appr?cie les femmes d?vou?es corps et ?me ? sa cause.');
INSERT INTO `npc_questions` VALUES (6604, '', '', '', '', 'J\\\'esp?re que personne ne t\\\'a suivi. Il va falloir que tu perdes l\\\'habitude de venir me voir d?s que tu cherches un renseignement sinon les autres vont finir par se douter de quelque chose. \\nAlors comme ?a tu veux conna?tre les rondes des patrouilles br?kmariennes ? Il y a un bureau cach? dans le dortoir de la milice o? Oto Mustam range de nombreux documents. Si tu arrives ? t\\\'y introduire, tu y trouveras ce que tu cherches et peut-?tre m?me plus. Bonne chance.');
INSERT INTO `npc_questions` VALUES (6608, '', '', '', '', 'Bonjour, je t\\\'attendais. Je pense que suffisamment de temps s\\\'est ?coul?. \\nPendant que tu combattais les Br?kmariens avec bravoure, j\\\'ai envoy? d\\\'autres miliciens se renseigner sur ce bwork mage. Les Sadidas ne se sont pas montr?s tr?s bavards mais Touh Flowa, le disciple de Sadadi Sama ? Astrub, a fait exception ? la r?gle mais sans en dire trop. Reprends l\\\'enqu?te ? partir de l? et bonne chance. Jiva veille sur toi.');
INSERT INTO `npc_questions` VALUES (6609, '', '', '', '', 'Waa, comment t\\\'es pas cool... Si j\\\'te dis ce que tu veux savoir tu m\\\'laisses dormir ? Alors ouvre grand tes oreilles car je r?p?terai pas, c\\\'est trop fatiguant. \\nSadida en personne a cach? le grimoire dans une prizzz... hein, quoi ? Ah ouais c\\\'est vrai. Je disais que le grimoire se trouve dans une prison v?g?tale con?ue par Sadida en personne, il est grave trop fort notre dieu. \\nO? est l\\\'entr?e ? Oula du calme, faut pas t\\\'exciter, soit cool. Prends une infusion de Dizbi, ?a calmera ton stress. L\\\'entr?e elle se trouve dans la For?t des Abraknydes Sombres, ouais rien que ?a. T\\\'as l\\\'air moins jouasse soudain, ?a va pas ?');
INSERT INTO `npc_questions` VALUES (6610, '', '', '', '', 'Bonjour, viens-tu m\\\'apporter le grimoire du mage bwork ?');
INSERT INTO `npc_questions` VALUES (6611, '', '', '', '', 'Tu fais honneur ? ton uniforme et ? notre cit?. Voil? 2000 Kamas pour toi, tu les as bien m?rit?s. \\nLes illustrations de ce grimoire sont d\\\'une obsc?nit? tr?s raffin?e. Gageons qu\\\'il contient de terribles sortil?ges dont nous pourrons faire usage pour ?craser Br?kmar une bonne fois pour toute. \\nJe vais ?galement prendre la poup?e, elle pourrait s\\\'av?rer utile et de toute mani?re, tu n\\\'en as plus besoin. Si j\\\'ai ? nouveau besoin de tes services, je te le ferai savoir. Tu peux disposer.');
INSERT INTO `npc_questions` VALUES (6612, '', '', '', '', 'C\\\'est la fillette bontarienne ? qui nous avons donn? la fess?e, non ?');
INSERT INTO `npc_questions` VALUES (6637, '', '', '', '', 'Puisque je te dis qu\\\'ils sont blancs comme la crini?re d\\\'un abominable Yiti des neiges.');
INSERT INTO `npc_questions` VALUES (6638, '', '', '', '', 'Non, ils sont blancs comme la carapace des scarafeuilles blancs.');
INSERT INTO `npc_questions` VALUES (6639, '', '', '', '', 'Il suffit de quelques minutes pour que Turorte remporte le combat et vous envoie ad patres.');
INSERT INTO `npc_questions` VALUES (6640, '', '', '', '', 'Tu as UNE chance de partir vivant alors, saisis-la et fuis !');
INSERT INTO `npc_questions` VALUES (6658, '', '', '', '', 'Que l\\\'esprit de lumi?re enferm? dans ce marteau en soit chass?. \\nQue les T?n?bres engloutissent ce qui appartint jadis aux d?mons. \\nQue la sombre magie du marteau soit enfin restaur?e.');
INSERT INTO `npc_questions` VALUES (6659, '6018;601', '', '', '0', 'Il existe plusieurs grandes cit?s au-del? d\\\'Astrub. Certaines de ces cit?s enr?lent des miliciens, ce qui apporte son lot d\\\'avantages et quelques inconv?nients.');
INSERT INTO `npc_questions` VALUES (6660, '6020;601', '', '', '0', 'Les avantages sont nombreux. Tous les miliciens d\\\'une cit? appartiennent au m?me alignement et disposent des avantages suivants : ils peuvent conqu?rir des villages et ainsi acc?der ? leurs ressources exclusives. Ils peuvent aussi poser des prismes de conqu?te pour aligner des territoires, ce qui peut augmenter leurs gains lors des combats et des r?coltes s\\\'ils ont d?cid? de participer activement ? la lutte contre les autres alignements. Enfin, lorsqu\\\'ils ont atteint un rang suffisant au sein de leur alignement, les miliciens peuvent se sp?cialiser et obtenir ainsi de nouvelles capacit?s. Les sp?cialisations possibles sont guerrier, espion et pr?tre. Le fais d\\\'appartenir ? l\\\'alignement d\\\'une cit? donne ?galement d\\\'autres petits avantages tels que la t?l?portation via prisme, l\\\'agression des ennemis etc. Tu pourras d?couvrir tout ?a plus tard mais pour l\\\'instant va faire tes premi?res armes et reviens me voir lorsque tu auras acquis plus d\\\'exp?rience, j\\\'aurai peut-?tre un tuyau pour toi.');
INSERT INTO `npc_questions` VALUES (6661, '6022;602', '', '', '0', 'Les principaux inconv?nients lorsqu\\\'on appartient ? l\\\'alignement d\\\'une cit? sont li?s aux agressions. En effet, si tu es align? et qu\\\'un milicien de l\\\'alignement adverse t\\\'agresse, tu ne disposes plus de la protection des gardes si tu te trouves dans une zone neutre. Un autre inconv?nient et pas des moindres est que les gardes des cit?s adverses peuvent t\\\'attaquer si tu passes trop pr?s d\\\'eux et qu\\\'ils t\\\'aper?oivent. Ceci est particuli?rement g?nant pour acc?der aux ateliers et aux h?tels de vente. Enfin, lorsque tu es align? et que tu es vaincu par un milicien ou un garde d\\\'un alignement ennemi, tu risques de te retrouver en prison. Il t\\\'est ?galement impossible d\\\'utiliser les zaaps pour acc?der ? des zones appartenant ? un alignement ennemi. Je te conseille fortement de bien r?fl?chir avant de t\\\'aligner, ce n\\\'est pas une mesure que l\\\'on prend ? la l?g?re. En attendant, va faire tes premi?res armes et reviens me voir lorsque tu auras acquis plus d\\\'exp?rience, j\\\'aurai peut-?tre un tuyau pour toi.');
INSERT INTO `npc_questions` VALUES (6662, '', '', '', '', 'Si tu penses avoir fait une erreur en t\\\'alignant, ma coll?gue Morrie Gane, en charge de la Milice du Ch?teau d\\\'Amakna, pourra t\\\'aider ? redevenir Neutre moyennant finances. Si tu le souhaites je peux t\\\'indiquer o? elle se trouve.');
INSERT INTO `npc_questions` VALUES (6663, '', '', '', '', 'Voil?, je l\\\'ai indiqu? sur ta carte. Tu n\\\'as plus qu\\\'? suivre ta boussole et tu y seras en un rien de temps.');
INSERT INTO `npc_questions` VALUES (6664, '', '', '', '', 'Attention, ce n\\\'est pas une d?cision ? prendre ? la l?g?re. Tu veux en savoir plus avant de prendre ta d?cision ?');
INSERT INTO `npc_questions` VALUES (6665, '', '', '', '', 'Ecoute-moi bien, ce que je fais l? doit rester entre nous. Personne d\\\'autre ne doit ?tre au courant car je risque ma place et toi ta t?te, tu as bien compris ? \\nMaintenant va voir Oto Mustam, ? la milice de Br?kmar, et dis-lui que tu viens de ma part.');
INSERT INTO `npc_questions` VALUES (6666, '', '', '', '', 'Je me disais bien que ta face de rat m\\\'?tait inconnue. Bienvenue dans la milice de Br?kmar, tu vas souffrir mais tes ennemis souffriront davantage, c\\\'est dire ? quel point ce sera douloureux pour eux. Va remercier Snori Nairb de ma part et dis-lui qu\\\'il sera pay? comme convenu. En fait non, ne le remercie pas et contente-toi de lui dire qu\\\'il a int?r?t ? m\\\'envoyer plus de monde s\\\'il compte grossir ses bourses. \\nN\\\'oublie pas de revenir ici, plusieurs t?ches t\\\'attendent et je fais pas allusion aux autres miliciens.');
INSERT INTO `npc_questions` VALUES (6667, '', '', '', '', 'Ecoute-moi bien, ce que je fais l? doit rester entre nous. Personne d\\\'autre ne doit ?tre au courant car je risque ma place et toi ta t?te, tu as bien compris ? \\nMaintenant va voir Amayiro, ? la milice de Bonta, et dis-lui que tu viens de ma part.');
INSERT INTO `npc_questions` VALUES (6668, '', '', '', '', 'Je me disais bien que ton visage ne m\\\'?tait pas familier, o? ai-je la t?te ? Tu remercieras Snori Nairb de ma part et de celle de Danathor. Reviens me voir ensuite, j\\\'ai du travail pour toi.');
INSERT INTO `npc_questions` VALUES (6670, '', '', '', '', 'Pnj(367) et Message(4810)');
INSERT INTO `npc_questions` VALUES (6702, '', '', '', '', 'Rien ? signaler !');
INSERT INTO `npc_questions` VALUES (6703, '', '', '', '', 'Le Capitaine Starky attend ? l\\\'int?rieur.');
INSERT INTO `npc_questions` VALUES (6704, '', '', '', '', 'Je suis ?tonn?e que mon oncle soit venu payer la ran?on. J\\\'aurais pr?f?r? qu\\\'il vienne vous botter les fesses.');
INSERT INTO `npc_questions` VALUES (6705, '', '', '', '', 'Mon oncle a ?t? oblig? de s\\\'enfuir sans moi mais ce n\\\'est que partie remise. Il va venir avec sa cavalerie et raser ce b?timent sordide et toute votre cit?, vous allez voir.');
INSERT INTO `npc_questions` VALUES (6706, '', '', '', '', 'Tu as voulu coller une racl?e au chef des cambrioleurs mais c\\\'est toi qui t\\\'en aies pris une ? Si leur cambriolage avait r?ussi, je t\\\'aurai ch?ti? sur le champ mais comme ce n\\\'est pas le cas, je te laisse une chance de te rattraper.');
INSERT INTO `npc_questions` VALUES (6707, '', '', '', '0', 'Excellent, ta d?brouillardise est exceptionnelle. Va voir Liroye Merline, elle pourra peut-?tre te faire des copies de cette clef, ?a te permettra d\\\'infiltrer le repaire des bandits avec d\\\'autres compagnons.');
INSERT INTO `npc_questions` VALUES (6708, '', '', '', '', 'Allez, tout le monde au travail. \\n... \\nApparemment la transg?n?se va avoir lieu, je crois que c\\\'est bon. Gr?ce ? ?a nous allons donner un coup de fouet ? notre agriculture, Raymond Santho va ?tre content. D\\\'ailleurs, en parlant de lui, vous devriez lui rendre une petite visite pour discuter des modalit?s d\\\'approvisionnement. Il est en ce moment en voyage ? Astrub, vous n\\\'aurez aucun mal ? le trouver. Si vous ne savez pas o? chercher une fois sur place, guettez sa venue ? l\\\'h?tel de vente des paysans, il y fait de nombreuses affaires.');
INSERT INTO `npc_questions` VALUES (6709, '', '', '', '', 'D\\\'un autre c?t? il faut que j\\\'apprenne ? compter sur moi-m?me et je ne suis pas ? l\\\'abri d\\\'une mauvaise r?colte. Dites ? Raymond Santho que je le retrouverai dans trois jours ? l\\\'h?tel de vente des paysans.');
INSERT INTO `npc_questions` VALUES (6710, '', '', '', '', 'Je suppose qu\\\'en le rel?chant au milieu des cultures je prouverai ma bonne foi ? Ramond Santho qui me payera en ?change de mes services.');
INSERT INTO `npc_questions` VALUES (6711, '', '', '', '', 'Gr?ce ? toi je vais me faire beaucoup de Kamas, tu peux dire ? ton employeur que je suis son homme. Je reste ? Astrub plusieurs jours pour affaires, il peut me contacter quand il le souhaite.');
INSERT INTO `npc_questions` VALUES (6712, '', '', '', '', 'J\\\'esp?re que tu ne viens pas me voir les mains vides, il me faut imp?rativement du Poison cinglant et une Teinture Magique Verd?tre et pas dans trois jours.');
INSERT INTO `npc_questions` VALUES (6714, '', '', '', '', 'Tu n\\\'es pas au courant ? Il nous a envoy? une lettre depuis la Plaine des Scarafeuilles pour pr?venir qu\\\'il allait rendre visite au Scarabosse Dor?. Selon lui c\\\'est une l?gende et il veut prouver ? tout le monde qu\\\'une telle cr?ature n\\\'existe pas. \\nJe crains que les choses aient mal tourn?. Rends-toi au Donjon des Scarafeuilles et essaye de sortir l\\\'eni Hoube de l?, s\\\'il est toujours vivant.');
INSERT INTO `npc_questions` VALUES (6715, '', '', '', '', 'Tu te demandes sans doute ce que je fais l? ? Non, je n\\\'ai pas peur des scarafeuilles, je suis venu volontairement ici pour m?diter et je peux sortir quand je veux.');
INSERT INTO `npc_questions` VALUES (6716, '', '', '', '', 'D\\\'accord, je veux bien quitter ce lieu pour te suivre jusqu\\\'? Bonta mais avant je dois passer voir Elya Wood. C\\\'est une Eniripsa tr?s belle et tr?s riche, je vais donc lui demander de me donner des Kamas et de l\\\'?quipement. Je vais aussi lui proposer de m\\\'?pouser.');
INSERT INTO `npc_questions` VALUES (6717, '', '', '', '', 'Comment osez-vous escorter le plus lourd et le plus assist? des Eniripsas ? mon temple ? Il n\\\'existe aucun rem?de pour le gu?rir, il est insupportable, sans g?ne et irrespectueux et le restera toute sa vie. En plus il porte la poisse. Hors de ma vue !');
INSERT INTO `npc_questions` VALUES (6718, '', '', '', '', 'Qu\\\'est-ce que tu viens faire l? ? C\\\'est interdit de passer et m?me si tu passes, sans guide tu vas te perdre dans les galeries souterraines. J\\\'ai pas le droit de sortir d\\\'ici et je commence ? avoir un petit creux. Je veux bien te guider jusqu\\\'en bas si tu m\\\'apportes du Pain Tr?pide. Par contre je te pr?viens, Il y a des sales bestioles en bas et je garantie pas ta s?curit?, surtout si tu y vas sans compagnon.');
INSERT INTO `npc_questions` VALUES (6719, '', '', '', '', 'Je pensais pas que tu irais aussi loin mais si tu continues tu vas heurter la sensibilit? des autres mineurs sombres. Si t\\\'as plus rien ? faire ici, je peux te faire remonter ? la surface, suffit de demander.');
INSERT INTO `npc_questions` VALUES (6720, '', '', '', '', 'Pour enchanter la pierre, j\\\'ai besoin d\\\'?tre assist? par un Osamodas connaissant le sort de R?sistance Naturelle et par un Alchimiste capable de fabriquer du Sang de Ph?nix.');
INSERT INTO `npc_questions` VALUES (6721, '', '', '', '', 'La salle est situ?e sous la Tour de Br?kmar. Tu peux y acc?der par un petit passage entre deux ?tag?res, dans la partie sud-ouest tout en bas de la tour.');
INSERT INTO `npc_questions` VALUES (6722, '', '', '', '', 'L\\\'alchimiste et l\\\'Osamodas doivent se placer chacun sur une dalle noire. Lorsqu\\\'ils seront plac?s, mets-toi sur la dalle blanche et noire et nous pourrons cr?er la pierre.');
INSERT INTO `npc_questions` VALUES (6723, '', '', '', '', 'Ceti po lo cr?me des miliciens de Bonto que v\\\'lo ? Lo prochaine fois essaye de po te prendre une rocl?e. On y retourne ?');
INSERT INTO `npc_questions` VALUES (6724, '', '', '', '', 'Oh, toutes mes excuses. Avec ton accoutrement j\\\'ai cr? que tu ?tais un de ces Astrubiens fra?chement d?barqu? d\\\'Incarnam. Tu devrais revoir ta garde-robe, elle ne te sied gu?re. \\nAlors comme ?a un sort de transg?n?se a ?t? lanc? sur mes cultures d\\\'avoine ? C\\\'est une bonne chose, je vais pouvoir augmenter ma production et g?n?rer ainsi plus de profits. Pr?viens Jerhyn Gholein que je passerai le voir d?s mon retour pour discuter directement avec lui et l\\\'intendant Danathor des modalit?s d\\\'approvisionnement de la milice.');
INSERT INTO `npc_questions` VALUES (6725, '', '', '', '', '... \\n............ \\n................... \\n............................');
INSERT INTO `npc_questions` VALUES (6726, '', '', '', '', 'Et voil? le travail. Apportez ?a ? vote chef pour qu\\\'il constate de ses propres yeux que je suis le meilleur forgeron d\\\'Amakna.');
INSERT INTO `npc_questions` VALUES (6727, '', '', '', '', 'Alors c\\\'est toi qui d?cime mes hommes ? Nous allons mettre un terme ? ton travail de petit toutou bontarien.');
INSERT INTO `npc_questions` VALUES (6728, '15001;15002;15003', '', '', '0', 'Le conflit entre les deux grandes cit?s est parfois un peu mou. Il a besoin de dynamisme. Je suis l? pour aider ceux qui pensent comme moi. J\\\'ai un don pour localiser les ennemis. Je d?signe les cibles et la traque commence. All?chant, non ?');
INSERT INTO `npc_questions` VALUES (6729, '611', '', '', '0', 'As-tu besoin de quelque chose ?');
INSERT INTO `npc_questions` VALUES (6730, '', '', '', '', 'Mmmh, ?a me dit quelque chose. J\\\'ai entendu des clients en parler parfois mais ils ?taient ronds comme des moumoules. Je n\\\'y ai pas pr?t? attention plus que ?a. Posez la question ? Laura Soho, l\\\'autre serveuse. Je doute qu\\\'elle en sache plus que moi mais ?a ne co?te rien d\\\'essayer.');
INSERT INTO `npc_questions` VALUES (6732, '', '', '', '', 'Vous revoil? ? Vous n\\\'avez toujours rien fait pour cacher ce vilain furoncle ? ce que je vois. Je connais un excellent chirurgien, il ?tait autrefois boucher mais plusieurs clients se sont plein de son manque de doigt?. Il a ?t? contraint de fermer son commerce et de se reconvertir. Comment s\\\'appelle-t-il d?j? ?');
INSERT INTO `npc_questions` VALUES (6733, '', '', '', '', 'Que me voulez-vous encore, vous n\\\'en avez pas assez de me harceler ?');
INSERT INTO `npc_questions` VALUES (6734, '', '', '', '', 'Formulez votre requ?te.');
INSERT INTO `npc_questions` VALUES (6735, '', '', '', '', 'File d\\\'ici avant que je remplace la tofoune par quelque chose de plus d?plaisant, esp?ce de malade !');
INSERT INTO `npc_questions` VALUES (6736, '', '', '', '', 'Le Grattoir ? dos Spentox est constitu? de deux parties : l\\\'extr?mit? et le manche. Leur fabrication n?cessite l\\\'utilisation d\\\'outils particuliers et assembler ces deux parties ne suffit pas. Il faut ?galement y ajouter de nombreux petits m?canismes pour s\\\'assurer du bon fonctionnement du grattoir et de sa fiabilit?. Qui plus est, fabriquer un tel objet n?cessite la collaboration de nombreux artisans. Si tu as besoin de plus de d?tails, rejoins-moi dans ma forge sp?ciale et nous pourrons discuter plus tranquillement.');
INSERT INTO `npc_questions` VALUES (6737, '', '', '', '', 'Une petite pause pour casser la cro?te ne fait pas de mal. Vous n\\\'avez rien pris pour vous remplir le ventre ? C\\\'est dommage. Moi j\\\'ai toute une r?serve de brioches dor?es, diverses confitures et m?me quelques friandises. Vous en voulez ? Il fallait penser ? en acheter avant de partir !');
INSERT INTO `npc_questions` VALUES (6738, '', '', '', '', 'Toujours pas de bandits en vue ? C\\\'est presque dommage, ce voyage est d\\\'un ennui... Vous voulez bien faire quelques bouffonneries pour me divertir ? Non ? Tant pis.');
INSERT INTO `npc_questions` VALUES (6739, '', '', '', '', 'Finalement nous avons de la chance, chaque kilom?tre parcouru nous rapproche petit ? petit de notre destination et diminue les risques de se faire attaquer.');
INSERT INTO `npc_questions` VALUES (6740, '', '', '', '', 'Ecoute, il n\\\'y a pas de secrets. Le meilleur moyen de devenir riche, c\\\'est de gagner des millions de Kamas. Tu veux savoir comment faire pour en gagner autant ? Approche un peu plus pr?s, je ne veux pas que tout le monde entende. \\nPour gagner de nombreux Kamas, c\\\'est tr?s simple. Il suffit de ne r?v?ler ? personne tes sources de revenus. Astucieux, tu ne trouves pas ?');
INSERT INTO `npc_questions` VALUES (6741, '', '', '', '', 'Rien ? signaler pour l\\\'instant.');
INSERT INTO `npc_questions` VALUES (6742, '', '', '', '', 'Je n\\\'ai aper?u aucun suspect pour l\\\'instant mais je garde l\\\'oeil ouvert.');
INSERT INTO `npc_questions` VALUES (6743, '', '', '', '', 'Si un Br?kmarien essaye de s\\\'?chapper il finira en prison.');
INSERT INTO `npc_questions` VALUES (6744, '', '', '', '', 'Nous surveillons toutes les sorties, personne ne peut entrer ni sortir sans notre autorisation.');
INSERT INTO `npc_questions` VALUES (6745, '', '', '', '', 'Bonjour, je suis un simple marchand faisant du commerce entre Bonta et Astrub.');
INSERT INTO `npc_questions` VALUES (6746, '', '', '', '', 'C\\\'est plut?t calme pour l\\\'instant mais ne rel?chons pas notre vigilance.');
INSERT INTO `npc_questions` VALUES (6747, '', '', '', '', 'Nous faisons une petite halte pour souffler un peu. Profites-en pour reprendre des forces, nous ignorons quand les bandits frapperont.');
INSERT INTO `npc_questions` VALUES (6748, '', '', '', '', 'Plus ?a va moins je le sens. J\\\'esp?re que les bandits ne seront pas trop nombreux.');
INSERT INTO `npc_questions` VALUES (6749, '', '', '', '', 'Les autres sont arriv?s ? Astrub sans encombre. Aucune trace de bandits, je crois que nous avons fait chou blanc.');
INSERT INTO `npc_questions` VALUES (6750, '', '', '', '', 'J\\\'ai besoin de r?fl?chir, je n\\\'ai plus rien ? vous dire.');
INSERT INTO `npc_questions` VALUES (6751, '', '', '', '', 'Tu n\\\'as rien ? faire ici. D?guerpis tant qu\\\'il en est encore temps.');
INSERT INTO `npc_questions` VALUES (6752, '', '', '', '', 'J\\\'aime pas les individus dans ton genre, ?a m\\\'?nerve. Et quand je suis ?nerv? j\\\'ai envie de casser ce que j\\\'aime pas, tu piges ?');
INSERT INTO `npc_questions` VALUES (6753, '', '', '', '', 'Je craignais qu\\\'il te batte et je ne me suis pas tromp?. Heureusement, les gardes que tu avais post? en bas de la tour les ont cueillis tandis qu\\\'ils prenaient la fuite. \\nTon aide et ta d?termination ont ?t? tr?s pr?cieuses, Bonta te doit une fi?re chandelle d\\\'avoir d?masqu? ce tra?tre. Lui et son complice vont subir un interrogatoire et je vais faire en sorte que les richesses de Xephir?s soit redistribu?es ? la population.');
INSERT INTO `npc_questions` VALUES (6754, '6151', '', 'NPC=1', '3165', 'Attention, Oshima ne laisse p?n?trer que certaines ?mes dans son sanctuaire. Si tu es pr?t ? endosser, pendant quelques temps, l\\\'enveloppe ?th?r?e d\\\'un fant?me, alors tu pourras entrer. Combats les cr?atures du sanctuaire et Oshima t\\\'accordera certainement une faveur. Sous quelle forme souhaites-tu entrer ?');
INSERT INTO `npc_questions` VALUES (6755, '6155;6154;6153;6152', '', '', '', 'Il existe quatre formes. La r?sistante bouloute, capable d\\\'encaisser les plus terribles coups. \\nLa seconde est le d?vou? b?b? pandawa qui a la capacit? de soigner les blessures. Ensuite, la dragoune, capable d\\\'abattre ? distance ses adversaires. Et enfin, l\\\'agile chacha aux griffes ac?r?es, in?gal? au combat corps ? corps. Quelle forme te convient le mieux ?');
INSERT INTO `npc_questions` VALUES (6756, '', '', '', '', 'Je vous rappelle que c\\\'est vous qui devez partir en ?claireur, vous ?tes pay? pour ?a. \\nAh bon, on ne vous paye pas ? Vous vous faites av... je veux dire tant mieux, vous ?tes une personne honn?te, charitable et fid?le ? sa cit? et ? ses principes.');
INSERT INTO `npc_questions` VALUES (6757, '', '', '', '', 'T\\\'es p\\\'t?t arriv? j\\\'qu\\\'ici en n\\\'tier mais t\\\'vas r\\\'partir en m\\\'rceaux.');
INSERT INTO `npc_questions` VALUES (6758, '', '', '', '', 'Quoi ? Je n\\\'ai rien ? te dire.');
INSERT INTO `npc_questions` VALUES (6759, '', '', '', '', 'Les plus dangereux restent les bworks mages des cavernes, une esp?ce rare qui est, la d?esse F?ca soit lou?e pour ?a, en voie d\\\'extinction. C\\\'est d\\\'ailleurs ? l\\\'un de ces bworks mages que l\\\'on doit la destruction de la quasi-totalit? des ormes du Monde des Douze apr?s qu\\\'il eut lanc? un envo?tement de son cr? baptis? la Grafioze.');
INSERT INTO `npc_questions` VALUES (6760, '', '', '', '', 'Bonguour ! Gue zuis heureux de vous revoir, vous avez gangu? ba vie. Gr?ze ? vous gue ne zerai bas obligu? de guidder le villague, gue vous en zerai ?dernellebent regonnaizant. Au vaid, gu\\\'est-ze gui vous ab?ne izi ?');
INSERT INTO `npc_questions` VALUES (6761, '', '', '', '', 'Guatre Zadidas zont n?zezzaires pour aggomplir le riduel et ils doivent ?dre zuffizabent egzb?ribend?. Le beilleur boyen de zavoir zi z\\\'est le gas est de z\\\'azzurer gu\\\'ils zont gabables d\\\'invoguer une Gonvlable. Le beilleur endroit ze drouve dans la bardie zud des lacs enchand?s, le nord est drop broche des ?banations de la vor?t des abragnydes zombres.');
INSERT INTO `npc_questions` VALUES (6762, '', '', '', '', 'Victoire ! Merci pour votre aide, sans vous la victoire n\\\'?tait pas assur?e.');
INSERT INTO `npc_questions` VALUES (6763, '', '', '', '', 'Nous avons r?ussi. Normal, les dieux sont avec nous.');
INSERT INTO `npc_questions` VALUES (6764, '', '', '', '', 'Donnez-moi un B. \\nDonnez-moi un O. \\nDonnez-moi un N. \\nDonnez-moi un T. \\nDonnez-moi un A.');
INSERT INTO `npc_questions` VALUES (6765, '', '', '', '', 'Que faites-vous ici ? Le dieu Sadida a interdit ? quiconque de s\\\'aventurer en ces lieux, ? l\\\'exception de ses disciples mais il leur faut une bonne raison pour ?a, sans quoi ils risquent d\\\'encourir son courroux. J\\\'ai d?j? vu Sadida courrouc? une fois, et ce n\\\'?tait pas joli ? voir. J\\\'?tais l? en guise de spectatrice, je vous laisse imaginer ce que ?a devait ?tre pour la cible de son courroux. Elle a pass? un mauvais quart d\\\'heure, vous pouvez me croire. C\\\'?tait terrible, quand j\\\'y repense ?a me donne des frissons dans tout le corps, brrr. Je n\\\'ai aucune envie de revoir ?a donc je vous conseille de quitter cet endroit sur le champ. Bien s?r, vous allez me r?pondre que c\\\'est impossible car la magie de Sadida  emp?che de rebrousser chemin, blablabla... Et comment ?tes-vous arriv? jusqu\\\'ici alors, vous avez vu un panneau indiquant une voie ? sens unique peut-?tre ?');
INSERT INTO `npc_questions` VALUES (6766, '', '', '', '', 'Je vous vois venir, je ne suis pas b?te comme une Sacrifi?e ni allum?e de la cervelle comme une Folle. En fait je suis une cr?ation unique du dieu Sadida, et plusieurs d?cennies apr?s m\\\'avoir con?ue, il m\\\'a confi? la lourde responsabilit? de surveiller cet endroit et de garder les intrus ? distance. Il savait qu\\\'en me confiant cette t?che il ne me reverrait peut-?tre jamais, c\\\'?tait un tr?s gros sacrifice pour lui, il a d? pleurer pendant des ann?es suite ? cette s?paration et je pense qu\\\'il ne s\\\'en est toujours pas remis. C\\\'est normal, il ne pouvait pas se passer de ma compagnie. Quelle tristesse.');
INSERT INTO `npc_questions` VALUES (6767, '', '', '', '', 'C\\\'est aussi ce que Sadida me disait quand nous discutions... enfin, c\\\'est surtout moi qui parlait, lui se contentait de m\\\'?couter avec grande attention en hochant parfois la t?te de contentement. Mais bavarder ne r?gle pas le probl?me de votre pr?sence en ces lieux. Vous voulez que je vous fasse sortir de l? ?');
INSERT INTO `npc_questions` VALUES (6768, '', '', '', '', 'C\\\'est dommage que vous souhaitiez partir, je commence ? m\\\'habituer ? votre pr?sence. Apr?s tout, tant que vous ne faites rien de mal, vous pouvez rester ici vous savez, je n\\\'ai rien contre vous. D\\\'ailleurs il s\\\'est s?rement pass? un tas de choses int?ressantes dans le Monde des 12 depuis mon isolation. C\\\'est comment dehors, toujours aussi beau ? Les Iops sont-ils toujours aussi b?tes et les Ecaflips aussi douces ? Mon probl?me avec les Ecaflips est que je suis allergique ? leurs poils, ?a me fait ?ternuer pendant des heures et ?a m\\\'emp?che de parler, c\\\'est pour ?a que j\\\'?vite de les coller.');
INSERT INTO `npc_questions` VALUES (6769, '', '', '', '', 'C\\\'est rigolo que vous posiez la question, j\\\'ai justement le pouvoir d\\\'envoyer les intrus en dehors de cet endroit. Une fois j\\\'ai utilis? ce pouvoir sur un bwork ?gar? et je l\\\'ai envoy? ? Incarnam, il a d? faire un vrai massacre. Par contre Sadida a oubli? de me faire don de clairvoyance, du coup il arrive que les intrus ne soient pas t?l?port?s o? il faut. Parfois m?me, le relief ayant chang? je t?l?porte un intrus dans ce qui ?tait ? l\\\'?poque une paisible clairi?re et l\\\'intrus se retrouve au milieu d\\\'un groupe de troolls affam?s, vous imaginez la suite.');
INSERT INTO `npc_questions` VALUES (6770, '', '', '', '', 'Ce n\\\'est plus moi qui m\\\'en occupe. J\\\'ai jou? le commandement de l\\\'attaque aux d?s contre ce gredin de Rekojel et j\\\'ai perdu. Qu\\\'est-ce qui m\\\'a pris de parier contre un Ecaflip ? Si Oto Mustam l\\\'apprend, je suis bon pour la prison ou pire, l\\\'infiltration dans la milice de Bonta. Je ne supporterai pas d\\\'?tre entour?s de telles mauviettes et de faire des courbettes ? longueur de journ?e.');
INSERT INTO `npc_questions` VALUES (6771, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA ! \\nCet imb?cile de Kapi Taigne t\\\'a dit comment il a perdu le commandement ? \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA ! \\nSi tu veux en savoir plus, faut passer ? la caisse. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6772, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA ! \\nJ\\\'ai vendu le commandement ? Ledrob Terces?c, le ma?tre de l\\\'Ordre de l\\\'Oeil Putride. J\\\'ai aussi entendu dire que le plan avait chang?, le nouveau doit se trouver dans les papiers de Lebrod Terces?c. Si tu comptes aller le chercher t\\\'es mal barr?. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6777, '', '', '', '', 'Une lettre pour moi ? Voyons un peu ce que ton ma?tre me veut. \\nCh?re Fidji Merline... blablabla... plusieurs dizaines de milliers de Kamas... blablabla... une prime pour votre soeur... blablabla... \\nTr?s bien, m?me si g?n?ralement je reste en dehors du conflit Bonta - Br?kmar, je vais te donner un coup de main. \\nVa me chercher 4 Mangeoires en Merisier et 40 Aubergines, je te donnerai la suite des instructions apr?s.');
INSERT INTO `npc_questions` VALUES (6778, '', '', '', '', 'Pose ?a ? c?t? de la table, ?a va ?tre rapide. \\nJ\\\'esp?re que tu n\\\'as pas attir? l\\\'attention au moins ? Bah, au pire je trouverai bien un pr?texte, ce ne sont pas les fausses excuses qui manquent ? Br?kmar. \\nAu fait, as-tu vu ma soeur r?cemment ? Je n\\\'ai pas eu de nouvelles de sa part depuis longtemps mais j\\\'ai entendu dire que les affaires marchaient plut?t bien pour elles. Je ne me plains pas, au contraire. Bien que je ne croule pas sous les commandes j\\\'ai suffisamment de clients pour gagner ma vie. \\nVoil?, c\\\'est termin? ! J\\\'ai trafiqu? les mangeoires pour qu\\\'elles nourrissent les dragodindes avec des aubergines sans attirer l\\\'attention. Va les mettre dans l\\\'enclos public, le r?sultat sera explosif.');
INSERT INTO `npc_questions` VALUES (6779, '', '', '', '', 'Ahahah, j\\\'imagine d?j? le r?sultat lorsque les gaz ?mis par les dragodindes vont rencontrer l\\\'air sulfureux de Br?kmar. Nos ennemis vont bient?t assister ? un v?ritable feu d\\\'artifice. Je plains presque les pauvres montures.');
INSERT INTO `npc_questions` VALUES (6780, '', '', '', '', 'Si je fais dispara?tre l\\\'air que tu respires, tu te retrouves comme un poisson hors de l\\\'eau. Tu ouvres la bouche comme ?a, gob gob, et rien ne se passe, tu t\\\'asphyxies.');
INSERT INTO `npc_questions` VALUES (6781, '', '', '', '', 'Je tape tellement vite que le frottement de mon poing avec l\\\'air g?n?re de la chaleur et des flammes. C\\\'est physique, tu peux pas comprendre. Tu veux te battre ?');
INSERT INTO `npc_questions` VALUES (6782, '', '', '', '', 'Plus bas tes explications, tout le monde ici n\\\'a pas besoin de conna?tre ta vie. \\nJe connais plusieurs rem?des au mal dont souffre ce bwork mage, mais ils sont tous tr?s difficiles ? mettre en oeuvre. Veux-tu vraiment les conna?tre ?');
INSERT INTO `npc_questions` VALUES (6783, '', '', '', '', 'Shh, pas si fort. Tu es dans une biblioth?que ici, pas ? la Taverne de la Bagrutte. \\nJe ne vois que quatre solutions envisageables. La premi?re est de r?unir les 6 Dofus primordiaux. Avec une telle puissance entre tes mains, tu n\\\'auras aucun mal ? d?livrer le bwork mage de son triste sort. \\nLa deuxi?me consiste ? invoquer un d?mon du 666e cercle et ? pactiser avec lui, malheureusement je ne connais pas les modalit?s d\\\'un tel pacte, il te faudra donc les trouver par toi-m?me. \\nLa troisi?me solution consiste ? vider la Mer d\\\'Asse en moins de trois jours, d?fi quasi-impossible, cela va de soi. \\nQuant ? la derni?re solution, c\\\'est un rituel consistant ? faire le tour des Plaines de Cania en quatre vingt jours, sur une main et les yeux band?s. Evidemment, tu n\\\'as pas le droit de changer de main une fois le tour commenc?. \\nAu pire tu peux toujours essayer de r?soudre le probl?me en bricolant une pince ? linge, ahah.... ahem, pardon, je m\\\'?gare.');
INSERT INTO `npc_questions` VALUES (6784, '', '', '', '', 'huhuhuh?h?h? HIARHIARHIARHAHAHA ! \\nUne fois j\\\'ai surpris Ledrob Terces?c en pleine crise allergique tandis qu\\\'il discutait avec Malicia Mis?re, la tenanci?re de la taverne du m?me nom. Peut-?tre que cette information pourra te servir. \\nhuhuhuh?h?h? HIARHIARHIARHAHAHA !');
INSERT INTO `npc_questions` VALUES (6785, '', '', '', '', 'Ledrob Terces?c ? Il ne vient plus ici depuis sa r?action allergique au m?lange de poils de chacha et d\\\'arakne. C\\\'est dommage, c\\\'?tait un bon client.');
INSERT INTO `npc_questions` VALUES (6786, '', '', '', '', 'Si ?a vous amuse...');
INSERT INTO `npc_questions` VALUES (6787, '', '', '', '', 'Qu\\\'est-ce que...aaatchaaaa !');
INSERT INTO `npc_questions` VALUES (6789, '', '', '', '', 'Qu\\\'est-ce que tu racontes ? Le poil que tu as dans la main, c\\\'est le tien !');
INSERT INTO `npc_questions` VALUES (6813, '', '', '', '', 'Si tu poses la question c\\\'est parce que tu as d?j? rendu visite ? Sabine dans sa cellule, n\\\'est-ce pas ?\\nComment ?a, non ? Tu te moques de moi ? Vas-y au galop avant que je te botte les fesses ? coups de rangers clout?es');
INSERT INTO `npc_questions` VALUES (6896, '', '', '', '', 'Hahaha, elle est bien bonne. Mais tu sais, les Iops ne sont pas tous des guerriers sans cervelle. Prends par exemple le cas de la belle Hels?phine. Elle ?tait une disciple du dieu Iop mais ?galement une alchimiste tr?s dou?e. Certes, je te l\\\'accorde, c\\\'?tait une femme, mais elle n\\\'est pas la seule exception ? la r?gle. \\nBien que les hommes aient un go?t plus prononc? pour la violence, ils ont eux aussi quelques lumi?res dans leurs rangs. M?me si Rish Claymore doit surtout son poste de ma?tre de classe du temple Iop ? ses talents de guerriers, il n\\\'en demeure pas moins un ?tre cens? et cultiv?, pour un Iop.');
INSERT INTO `npc_questions` VALUES (6963, '6697;6772;1419;1509', '', '', '0', 'J\\\'ai entra?n? des Dopeuls pour qu\\\'ils apprennent les techniques de combat Pandawa. Ainsi ils font d\\\'excellents adversaires pour s\\\'entra?ner, et ce quel que soit ton niveau.');
INSERT INTO `npc_questions` VALUES (7036, '6501;6500;656', '', '', '0', 'Pour te r?compenser de tes nombreuses victoires, je peux t\\\'?changer ces pi?ces contre divers objets. Cela peut ?tre des parchemins de caract?ristiques voire des gemmes spirituelles contenant les ?mes captives de monstres. Que choisis-tu ?');
INSERT INTO `npc_questions` VALUES (7037, '7358;7357;7356;7359', '', '', '0', 'Je poss?de des parchemins pour toutes les caract?ristiques et de toutes puissances. De quelle puissance d?sires-tu que soit ce parchemin ?');
INSERT INTO `npc_questions` VALUES (7038, '6513;6515;6516;6517;6518;651', '', '', '0', 'Quelle caract?ristique doit modifier ce parchemin ?');
INSERT INTO `npc_questions` VALUES (7039, '6520;6521;6522;6523;6524;652', '', '', '0', 'Quelle caract?ristique doit modifier ce parchemin ?');
