INSERT INTO `npc_questions` VALUES (7043, '', '', '', '', 'Tu ne poss?des pas assez de p?v?tons pour r?aliser cet ?change.');
INSERT INTO `npc_questions` VALUES (7049, '6542;6543;6544;6545;6552;6564;654', '', '', '0', 'J\\\'ai class? ces gemmes selon le nom du monstre qu\\\'elles contiennent. Quelle est celle que tu souhaites ?');
INSERT INTO `npc_questions` VALUES (7050, '', '', '', '', 'Tr?s bien, maintenant quelle gemme d?sires-tu ?');
