INSERT INTO `npc_questions` VALUES (7065, '', '', '', '', 'Plus tard. Je suis en train de jouer ? Pierre Feuille Ciseaux contre Thomas Sacre et il ne me m?ne que d\\\'un point.');
INSERT INTO `npc_questions` VALUES (7066, '6593;6594;659', '', '', '0', 'Les pierres suivantes ... \\n');
INSERT INTO `npc_questions` VALUES (7069, '6632', '', '', '', 'Non m\\\'sieur, y a rien derri?re moi. C\\\'est juste une grotte vide. Pourquoi je reste devant une grotte vide ? En voil? une dr?le de question. Demandez plut?t ? un Iop pourquoi il se balade avec un cr?ne vide ! Bon, je vais vous le dire. Il se trouve que je suis un Sram altruiste. C\\\'est plut?t rare. Je ne veux pas que des promeneurs s\\\'?garent et perdent leur temps dans cette grotte vu qu\\\'il n\\\'y a rien ? y faire. Quant ? toutes ces fadaises qui disent que c\\\'est un repaire de bandits et de brigands et bien ... ce sont des fadaises, j\\\'vous dis !');
INSERT INTO `npc_questions` VALUES (7070, '', '', '', '', 'Krk Irk Verk Ak Lk Ak ?');
INSERT INTO `npc_questions` VALUES (7071, '6636', '', '', '0', 'Au fin fond de ces cavernes vit mon p?re et ses suivants. Ce qui m\\\'arrangerait c\\\'est que vous parveniez jusqu\\\'? lui. S\\\'il lui arrivait un accident, je prendrais sa place. Je ne vous ai jamais dit ?a bien entendu !');
INSERT INTO `npc_questions` VALUES (7072, '6638', '', '', '', 'Salutations ! Je vois ? votre air surpris que vous n\\\'avez gu?re l\\\'habitude de converser avec une plante. Je suppose que vous passez votre temps ? tuer celles que vous croisez. Il ne faut point d\\\'esprit pour ?tre homme de guerre. Et comme me dit ma Racine : \\\"Combien tout ce qu\\\'on dit est loin de ce qu\\\'on pense\\\". Je ne dis rien sur vos actes mais ...');
INSERT INTO `npc_questions` VALUES (7073, '', '', '', '', 'Ne trouves-tu pas que ce rocher ressemble ? un navire qui sombre. Non ?  Bizarre, j\\\'ai parfois des visions muettes dans lesquelles je me vois sur la proue d\\\'un vaisseau, le visage balay? par les embruns. Enfin, bref, que veux-tu ?');
INSERT INTO `npc_questions` VALUES (7081, '', '', '', '', 'Depuis quelques temps, nous ouvrons les portes de notre temple aux repr?sentants des autres divinit?s.');
INSERT INTO `npc_questions` VALUES (7106, '', '', '', '', 'Tu as vaincu le dopeul ? F?licitations ! Voici ta r?compense bien m?rit?e.');
INSERT INTO `npc_questions` VALUES (7108, '6701;6699;6500;7326;6599;6768', '', '', '0', 'Bien s?r, si tu as suffisamment de doplons, je peux te les ?changer contre diverses babioles.');
INSERT INTO `npc_questions` VALUES (7115, '', '', '', '', 'Oui, j\\\'ai re?u quelques potions d\\\'Otoma?, le ma?tre alchimiste. Contre quoi veux-tu ?changer cette potion ?');
INSERT INTO `npc_questions` VALUES (7132, '', '', '', '', 'Si tu veux affronter un Dopeul, je te conseille de te pr?parer. Alors ? pr?t ?');
INSERT INTO `npc_questions` VALUES (7134, '', '', '', '', 'Si tu veux affronter un Dopeul, je te conseille de te pr?parer. Alors ? pr?t ?');
INSERT INTO `npc_questions` VALUES (7135, '', '', '', '', 'C\\\'est un long p?riple que tu as achev? l');
INSERT INTO `npc_questions` VALUES (7136, '6770;6771', '', '', '', 'On a de l\\\'estomac ? ce que je vois. Et bien, soit ! Va combattre les dopeuls dans les temples des dieux. Si tu y parviens, adresse toi ? n\\\'importe lequel des ma?tres des dopeuls qui te r?compensera. Veux-tu commencer tout de suite ?');
INSERT INTO `npc_questions` VALUES (7142, '7225;7226', '', '', '0', 'Bonjour jeune aventurier. Je ne sais pas si tu es au courant mais notre temple s\\\'est modernis?. Il offre de nombreux services qu\\\'il serait maladroit d\\\'ignorer. Il para?t m?me que de nouveaux dopeuls ont ?t? captur?s pour les entra?nements au combat. Va donc y faire un tour.');
INSERT INTO `npc_questions` VALUES (7143, '', '', '', '', 'Peut-?tre ne sais-tu pas o? se trouve notre temple. Rien de plus simple pourtant. Il te suffit d\\\'ouvrir ta carte, tous les lieux de classe, y compris les temples, y sont indiqu?s.');
INSERT INTO `npc_questions` VALUES (7144, '', '', '', '', 'Tu reviens du temple ? J\\\'esp?re que tu en as profit? pour le visiter de fond en comble, il y a tant ? faire l? bas.');
INSERT INTO `npc_questions` VALUES (7145, '', '', '', '', 'Tu as r?ussi ? te d?barrasser d\\\'eux, bravo ! D\\\'apr?s leur ordre de mission, ils devaient remettre des documents ? un garde au pied de la Tour de Br?kmar, peut-?tre devrais-tu t\\\'y rendre ? leur place et donner de faux documents ? Nous ferons ainsi d\\\'une pierre deux coups.');
INSERT INTO `npc_questions` VALUES (7280, '', '', '', '', 'Je dois partir ? l\\\'h?tel de vente et je ne peux pas laisser des gens utiliser la forge pendant mon absence, alors sors s\\\'il-te-pla?t.');
INSERT INTO `npc_questions` VALUES (7380, '', '', '', '', 'Je commence ? en avoir assez des incomp?tents. Je te d?barrasse de ce d?sagr?ment, m?me si je me doute que la le?on n\\\'aura pas port? ses fruits.');
INSERT INTO `npc_questions` VALUES (7465, '7259;7260', '', '', '0', 'Bonjour, je vois que tu poss?des un orbe magique. Il dispose de deux pouvoirs. tu ne peux utiliser qu\\\'un seul des deux. Veux-tu en savoir plus ?');
INSERT INTO `npc_questions` VALUES (7466, '7261', '', '', '0', 'Le premier pouvoir permet d\\\'oublier totalement tes caract?ristiques, elles seront identiques ? celles que tu avais lorsque tu es arriv? sur le Monde des Douze. Tout ce que tu auras appris gr?ce ? des parchemins sera perdu. Tu pourras gr?ce ? ce pouvoir, changer compl?tement ta fa?on de combattre et d\\\'utiliser tes sorts, en changeant tes ?l?ments de pr?dilection.');
INSERT INTO `npc_questions` VALUES (7467, '7262', '', '', '0', 'Le second pouvoir est beaucoup moins puissant, il permet d\\\'oublier partiellement ses caract?ristiques, si tu ne veux pas perdre ce que tu as appris d?j? avec des parchemins de caract?ristiques.');
INSERT INTO `npc_questions` VALUES (7468, '7263', '', '', '0', 'Attention, avec ce pouvoir toutes tes caract?ristiques vont ?tre r?initialis?es. \\nTu vas perdre tous les points de caract?ristiques que tu as gagn?s gr?ce ? des parchemins. \\nTu pourras ensuite r?partir ? nouveau tes points de caract?ristiques. \\nEs-tu certain de vouloir continuer ? \\n');
INSERT INTO `npc_questions` VALUES (7469, '7264', '', '', '0', 'Attention, en usant de ce pouvoir, tu ne r?cup?reras que les points de caract?ristiques que tu as investis au dessus de 101 points de caract?ristiques. \\nCe pouvoir te permet de ne pas perdre les points de caract?ristiques que tu as gagn?s gr?ce ? des parchemins de caract?ristiques. \\nMais tu ne pourras pas r?cup?rer les points de caract?ristiques que tu as investis en dessous de 101 points de caract?ristiques. \\nEs-tu certain de vouloir continuer ?');
INSERT INTO `npc_questions` VALUES (7508, '7328;732', '', '', '0', 'Je dispose de deux pouvoirs pour transformer tes caract?ristiques, veux-tu en savoir plus ?');
