INSERT INTO `npc_questions` VALUES (7544, '', '', '', '', 'Salut morveux ! Tu veux venir faire un tour dans mon ar?ne, c\\\'est ?a ? Choisis bien ta r?ponse !');
INSERT INTO `npc_questions` VALUES (7545, '', '', '', '', 'Ici bas repose Jorbak le V?nal. N\\\'entrerons que ceux riches d\\\'assez de kamas pour attirer sa convoitise. Onze kamas pour chacune des ann?es qu\\\'il a v?cu avant de perdre sa fortune. Plus six kamas car c\\\'est tout ce qu\\\'il lui restait.');
INSERT INTO `npc_questions` VALUES (7546, '7464;7465', '', '', '0', 'Tu as assez de kamas pour que l\\\'esprit de Jorbak t\\\'apparaisse. Est-ce l? ton d?sir ? Veux-tu p?n?trer dans l\\\'antre de l\\\'Infortun? ?');
INSERT INTO `npc_questions` VALUES (7547, '', '', '', '', 'L\\\'esprit de Jorbak ne se montrera pas avant un moment. Les plus grandes fortunes ont mis du temps ? se construire. Sois patient.');
INSERT INTO `npc_questions` VALUES (7548, '', '', '', '', 'Bonjour #1, je vois que tu d?butes. Je t\\\'invite ? suivre ce cours tr?s rapide sur les principes de base de ce monde.');
INSERT INTO `npc_questions` VALUES (7549, '', '', '', '', 'Tr?s beau combat, mais tu es en mesure d\\\'affronter un adversaire plus redoutable. Va sur la plateforme suivante et vaincs l\\\'adversaire que tu y trouveras.');
INSERT INTO `npc_questions` VALUES (7551, '', '', '', '', 'Bonjour. \\nSi tu le souhaites, je peux te donner de faux documents pour int?grer la milice de ton choix. \\nAfin de valider ces documents, tu dois ?tre d\\\'alignement neutre ou correspondant ? la cit? de ton choix. \\nQuel alignement souhaites-tu avoir ?');
INSERT INTO `npc_questions` VALUES (7552, '', '', '', '', 'Moi ? J\\\'ai ?t? envoy? ici par le Grandapan en personne. \\nC\\\'est triste mais un mal ?trange frappe le village de Pandala. La diversit? des boissons de l\\\'?le est menac?e, car de plus en plus de Pandawas ne boivent plus qu\\\'une seule et unique boisson. Apr?s une longue enqu?te, nous avons d?couvert que ce mal est apparu quelques semaines apr?s l\\\'?rection de la statue, ce qui a fait exploser de rage la d?esse. C\\\'est ce qui explique ma pr?sence ici. \\nD\\\'ailleurs, puisque tu viens d\\\'arriver, je te conseille de faire attention et si tu d?couvres quoi que ce soit qui puisse ?tre en rapport avec le mal ?trange dont je viens de te parler, pr?viens-moi.');
INSERT INTO `npc_questions` VALUES (7553, '', '', '', '', 'Bonjour, je suis ravie de te voir. \\nJ\\\'ai besoin de femmes d?brouillardes dans ton genre pour m\\\'aider dans mes affaires. Je peux te proposer un travail simple et bien pay?, mais tu devras te montrer discr?te et ne pas poser de questions. \\nQu\\\'en dis-tu ?');
INSERT INTO `npc_questions` VALUES (7554, '', '', '', '', 'C\\\'est dommage, je suis s?re que nous pourrions faire de grandes choses ensemble. Enfin... \\nJe ne vais pas te forcer la main, mais si tu changes d\\\'avis, tu sais o? me trouver.');
INSERT INTO `npc_questions` VALUES (7555, '', '', '', '', 'Parfait, je vois que nous sommes sur la m?me longueur d\\\'onde. \\nJe n\\\'ai pas envie que notre conversation s\\\'?bruite, alors rejoins-moi dans ma maison. Elle se trouve au sud de la statue du dieu Iop, ? proximit? de l\\\'h?tel de vente des bricoleurs. \\nJe pr?f?re que tu ?vites de passer par la porte principale. Utilise plut?t la porte de derri?re, elle est plus discr?te et cach?e par un tas de caisses. \\nJe t\\\'en dirai davantage lorsque tu m\\\'auras rejointe.');
INSERT INTO `npc_questions` VALUES (7556, '', '', '', '', 'Je n\\\'aime pas trop discuter en public.');
INSERT INTO `npc_questions` VALUES (7557, '', '', '', '', 'Tu as ?t? rapide. Ca tombe bien, car ton travail va consister ? apporter un colis au village d\\\'Akwadala dans les plus brefs d?lais. Je veux que tu te rendes l?-bas pour livrer une caisse ? Pandett?, il te payera apr?s r?ception du colis.');
INSERT INTO `npc_questions` VALUES (7558, '', '', '', '', 'Le contenu de cette caisse ne te regarde pas. Contente-toi de la livrer ? bon port et tu seras r?compens? pour tes efforts.');
INSERT INTO `npc_questions` VALUES (7559, '', '', '', '', 'Que fais-tu encore ici ? Tu devrais d?j? ?tre parti !');
INSERT INTO `npc_questions` VALUES (7560, '', '', '', '', 'File, tu vas me faire rep?rer.');
INSERT INTO `npc_questions` VALUES (7561, '', '', '', '', 'Si tu veux mon avis, tu t\\\'es mis dans de sales draps... mais nous devons pouvoir tirer avantage de la situation. \\nAs-tu la liste avec toi ?');
INSERT INTO `npc_questions` VALUES (7562, '', '', '', '', 'Je connais plusieurs de ces personnes, ce sont des marchands de boissons des diff?rents villages de l\\\'?le de Pandala. \\nMontre-moi cette caisse. Ca te d?range si je l\\\'ouvre ? Non ? Tant mieux. \\nQu\\\'est-ce que... Regarde-moi toutes ces fioles, as-tu une id?e de ce qu\\\'elle peuvent contenir ? \\nJe vais garder cette caisse pendant que toi, tu vas apporter une fiole au Mage Ax. Il travaille ? l\\\'atelier des alchimistes, tu n\\\'auras aucun mal ? le trouver. Donne-lui la fiole et demande-lui d\\\'en analyser le contenu, puis rapporte-moi les r?sultats de son analyse.');
INSERT INTO `npc_questions` VALUES (7563, '', '', '', '', 'Tu veux que j\\\'analyse le contenu de cette fiole parce que tu es incapable de le faire toi-m?me ? \\nBon, j\\\'accepte pour cette fois, mais que ?a ne devienne pas une habitude, compris ?');
INSERT INTO `npc_questions` VALUES (7564, '', '', '', '', 'C\\\'est du jus de ouassingue distill?. Cette boisson est interdite dans toutes les cit?s du monde civilis? car elle cr?e chez le buveur un important ph?nom?ne de d?pendance. \\nMaintenant que tu as eu ce que tu voulais, va enquiquiner quelqu\\\'un d\\\'autre.');
INSERT INTO `npc_questions` VALUES (7565, '', '', '', '', 'Mmh, je commence ? y voir clair. Des contrebandiers vendent du jus de ouassingue aux marchands les moins scrupuleux, qui le m?langent ? leurs boissons. Gr?ce ? la d?pendance qui s\\\'ensuit, ces marchands se cr?ent une client?le fid?le. C\\\'est inadmissible, le Grandapan sera hors de lui lorsqu\\\'il apprendra ce qui se passe ! \\nJ\\\'ai entendu dire que Nib? Lulle, l\\\'Eniripsa de l\\\'h?tel de vente des alchimistes, ?tait un alchimiste hors pair. \\nVa le voir et demande lui s\\\'il existe un antidote ? la d?pendance au jus de ouassingue.');
INSERT INTO `npc_questions` VALUES (7566, '', '', '', '', 'Je peux vous pr?parer ?a mais je suis ? court de p?tales fan?s de Rose D?moniaque. Pendant que vous allez m\\\'en chercher un, je vais pr?parer le reste de l\\\'antidote.');
INSERT INTO `npc_questions` VALUES (7567, '', '', '', '', 'Je mets ma pr?paration dans la fiole, j\\\'ajoute le p?tale et je m?lange. \\nVoil?, ?a devrait faire l\\\'affaire. Si l\\\'antidote fonctionne, je pourrai sans probl?me en cr?er en plus grande quantit');
INSERT INTO `npc_questions` VALUES (7568, '', '', '', '', 'Je vais livrer cet antidote au Grandapan sur le champ. S\\\'il fonctionne, les Pandawas te devront une fi?re chandelle. \\nQuant aux marchands peu scrupuleux ayant fait usage du jus de ouassingue, ils seront punis comme il se doit. \\nPuisque tu as si bien oeuvr? pour notre cause, pourquoi ne pas te rendre sur l\\\'?le de Pandala ? L\\\'assistant Shaman est un bon ami, il t\\\'aidera ? prendre tes rep?res.');
INSERT INTO `npc_questions` VALUES (7569, '', '', '', '', 'Eh bien, tu ne plaisantes pas ? ce que je vois. Tu es pr?t ? explorer le vaste continent d\\\'Amakna et plus encore.');
INSERT INTO `npc_questions` VALUES (7570, '', '', '', '', 'De quel temple de classe voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7571, '', '', '', '', 'De quel temple de classe voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7572, '', '', '', '', 'De quel temple de classe voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7573, '', '', '', '', 'De quel temple de classe voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7574, '', '', '', '', 'De quelle cit? voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7575, '', '', '', '', 'De quelle cit? voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7576, '', '', '', '', 'De quel autre lieu voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7577, '', '', '', '', 'De quel autre lieu voulez-vous les coordonn?es ?');
INSERT INTO `npc_questions` VALUES (7579, '', '', '', '', 'Continue ton exploration, tu as tant ? d?couvrir.');
INSERT INTO `npc_questions` VALUES (7580, '', '', '', '', 'Comment ?! Tu as perdu mon scalpel, cet outil de haute pr?cision, ce bijou de la chirurgie moderne !\\nBon, de toute mani?re il faut bien que je t\\\'en redonne un si je veux me cr?er une compagne... Ca te co?tera 1000 Kamas.');
INSERT INTO `npc_questions` VALUES (7582, '', '', '', '', 'Voulez-vous vous passer la corde au c... heu pardon la bague au doigt ? \\n');
INSERT INTO `npc_questions` VALUES (7583, '758', '', '', '0', 'Qu\\\'est-ce qu\\\'il y a ? Tu n\\\'as jamais vu une femme ? la pilosit? tr?s d?velopp?e ?');
INSERT INTO `npc_questions` VALUES (7584, '', '', '', '', 'La grotte ? Quelle grotte ? \\nAh, tu veux dire cette grotte-l?... C\\\'est ici que vit mon papounet. Depuis la mort de ma m?re, il a p?t? un boulon et il est devenu extr?mement dangereux, aussi bien pour lui-m?me que pour les visiteurs. \\nLe probl?me, c\\\'est qu\\\'il bloque l\\\'acc?s ? la meilleure mine de la guilde du Marteau-Faucille. C\\\'est pour cette raison que je ne laisse pas entrer n\\\'importe qui.');
INSERT INTO `npc_questions` VALUES (7585, '', '', '', '', 'D?sol?e, mon papounet se repose. Ici ce n\\\'est pas un moulin, alors reviens lorsqu\\\'il sera ?veill');
INSERT INTO `npc_questions` VALUES (7586, '', '', '', '', 'Je te pr?viens, c\\\'est tr?s dangereux l?-dedans. Tu veux vraiment y aller ?');
INSERT INTO `npc_questions` VALUES (7587, '', '', '', '', 'Salut ? toi. Si tu cherches ? t\\\'offrir  une maison, tu as frapp? ? la bonne porte. Gr?ce ? moi, tu auras un ami dans l\\\'immobilier. \\nJe sais ce qui t\\\'intrigue, tu te demandes ? qui appartient cette maison perdue dans Cania.');
INSERT INTO `npc_questions` VALUES (7588, '', '', '', '', 'Cette maison appartient ? un ami, mais il pr?f?re garder l\\\'anonymat pour l\\\'instant. \\nIl ouvrira les portes de sa demeure au mois de Descendre, et seuls les d?tenteurs d\\\'un acc?s premium pourront y p?n?trer. \\nTu t\\\'interroges d?j? sur ce que tu va trouver l?-dedans, n\\\'est-ce pas ? \\nAlors laisse-moi t\\\'expliquer.');
INSERT INTO `npc_questions` VALUES (7589, '', '', '', '', 'Mon vieil ami va permettre aux heureux b?n?ficiaires d\\\'un acc?s premium d\\\'affronter des cr?atures uniques qu\\\'il a ramen?es de ses nombreux voyages ? travers le Monde des Douze. Ces cr?atures pourront ?tre affront?es seul ou en groupe, et mon ami offrira une r?compense ? tous les valeureux victorieux. \\nJe te donne donc rendez-vous le 2 Descendre pour d?couvrir l\\\'int?rieur de ce b?timent et rencontrer mon ami.');
INSERT INTO `npc_questions` VALUES (7590, '', '', '', '', 'Bonjour, je suppose que tu veux entrer dans cette magnifique maison, n\\\'est-ce pas ?');
INSERT INTO `npc_questions` VALUES (7591, '', '', '', '', 'Ton nom figure bien sur la liste des invit?s, tu peux entrer.');
INSERT INTO `npc_questions` VALUES (7592, '', '', '', '', 'Voyons, tu as dis que tu t\\\'appelais comment d?j? ? Ah oui... D?sol?, ton nom ne figure pas sur la liste des invit?s. En d\\\'autres termes, je n\\\'ai pas le droit de te laisser entrer. \\n(l\\\'acc?s ? ce lieu est r?serv? aux membres premium)');
INSERT INTO `npc_questions` VALUES (7593, '', '', '', '', 'On dirait que j\\\'ai de la visite. \\nJe vois dans ton regard briller la convoitise, et tu te demandes comment toi, un plouc, tu pourrais accumuler ne serait-ce qu\\\'un centi?me de mes richesses ? \\nAhaha, ne r?ve pas, c\\\'est impossible.');
INSERT INTO `npc_questions` VALUES (7594, '', '', '', '', 'C\\\'est le tr?sor de toute une vie de chasses et d\\\'aventures que tu vois l?, et c\\\'est peu dire. \\nLorsque toi aussi tu auras v?cu autant d\\\'aventures que moi, tu voudras sans doute te ranger, et c\\\'est alors que l\\\'ennui te gagnera. \\nJ\\\'ai ?t? membre des Roublards, vaincu le M?ga Craqueleur ? la lutte et battu Dragnoute l\\\'Irascible ? la course. J\\\'ai assist? ? la capture du d?mon Uk\\\'Not\\\'Allag qui terrorisait Amakna, j\\\'ai d?couvert l\\\'?le d\\\'Otoma? avec mon ami le Capitaine Kradoc, j\\\'ai m?me voyag? sur l\\\'?le de Nowel et rencontr? le Comte Harebourg en personne.');
INSERT INTO `npc_questions` VALUES (7595, '', '', '', '', 'J\\\'ai form? les plus grands chasseurs de notre temps, d\\\'ailleurs le chapeau que je porte m\\\'a ?t? offert par l\\\'un de mes anciens ?l?ves, Mikoule. \\nEn parlant de chasse, que dirais-tu d\\\'affronter un de mes troph?es ? \\nOh, je ne te l\\\'ai pas dit ? Je poss?de la plus grande collection d\\\'?mes de cr?atures, m?me celle du c?l?bre alchimiste Otoma? fait p?le figure ? c?t? de la mienne.');
INSERT INTO `npc_questions` VALUES (7596, '', '', '', '', 'Ecoute, voici ce que je te propose. \\nTu vas me distraire en combattant une des cr?atures de ma collection. Si tu gagnes le combat, alors je t\\\'offrirai un cadeau. \\nTu peux demander l\\\'aide de tes amis, car plus on est de fous, plus on rit.');
INSERT INTO `npc_questions` VALUES (7597, '', '', '', '', 'Je vois que tu ne manques pas de motivation, c\\\'est tr?s bien. \\nOh, une derni?re pr?cision : une fois que tu auras vaincu une cr?ature, tu ne pourras plus jamais l\\\'affronter. \\nA pr?sent, dis-moi quelle cr?ature tu souhaites affronter, et t?che de m\\\'offrir un spectacle digne de ce nom.');
INSERT INTO `npc_questions` VALUES (7598, '', '', '', '', 'C\\\'?tait vraiment un beau combat, tu as bien m?rit? ta r?compense. \\nRepasse me voir ? l\\\'occasion, peut-?tre que je serai enclin ? te laisser combattre un autre de mes troph?es de chasse.');
INSERT INTO `npc_questions` VALUES (7599, '', '', '', '', 'Tu as d?j? vaincu tous les troph?es que je t\\\'ai propos?s. Repasse plus tard, j\\\'ai besoin de temps pour te choisir un nouvel adversaire.');
INSERT INTO `npc_questions` VALUES (7600, '', '', '', '', 'En fait, c\\\'est une mauvaise id?e. N\\\'importe lequel de mes troph?es ne ferait qu\\\'une bouch?e de toi, et m?me si l\\\'id?e de voir ton corps ?parpill? aux quatre coins de la pi?ce est amusante, ?a fera d?sordre et je n\\\'ai pas envie de nettoyer. \\nReviens me voir lorsque tu seras plus exp?riment');
INSERT INTO `npc_questions` VALUES (7601, '', '', '', '', 'Tu ne vas pas me croire mais j\\\'ai, h?h?, lib?r? l\\\'?me de ce monstre dans ma chambre... Si tu souhaites vraiment t\\\'y rendre, ne fais pas attention au bazar. Je fais r?guli?rement la chasse aux cafards naomes qui infestent cette bicoque et je n\\\'ai pas le temps de ranger. \\nUn dernier conseil : prend garde car ma chambre n\\\'est pas tr?s grande et le Manitou Zoth a tendance ? invoquer des esprits pour l\\\'aider. Tu risques donc d\\\'?tre rapidement submerg?. \\nTu te sens toujours d\\\'attaque pour affronter le Manitou Zoth ?');
INSERT INTO `npc_questions` VALUES (7602, '', '', '', '', 'Passe ton chemin, cloporte.');
INSERT INTO `npc_questions` VALUES (7603, '', '', '', '', 'C\\\'est terrible, vraiment terrible...');
INSERT INTO `npc_questions` VALUES (7604, '', '', '', '', 'Figure-toi que d\\\'ignobles ?tres, que dis-je, d\\\'inf?mes cr?atures ont commis un crime abominable. \\nCes ordures ont cambriol? l\\\'entrep?t du P?re Nowel et d?rob? toutes les caisses avant de retourner au fond de leur donjon. \\nSi personne ne fait rien pour les r?cup?rer, les enfants du Monde des Douze ne pourront pas f?ter Nowel cette ann?e. Te rends-tu comptes de ce que cela signifie ?');
INSERT INTO `npc_questions` VALUES (7605, '', '', '', '', 'Ah, je suis heureux que tu le prennes ainsi. \\nTu peux m\\\'aider en allant chercher toi-m?me la caisse vol?e par une de ces cr?atures. J\\\'ai entendu dire que malgr? leur acte d\\\'une incroyable bassesse, les voleurs pourraient ?tre pris de remords si le P?re Nowel se pr?sentait ? eux pour r?clamer les objets vol?s. Tu devrais peut-?tre essayer de te faire passer pour lui, et si malgr? ?a les voleurs restent r?ticents, un bon coup sur la t?te devrait finir de les convaincre.');
INSERT INTO `npc_questions` VALUES (7606, '760', '', '', '0', 'Voil?, je t\\\'ai indiqu? quel monstre a particip? au larcin. \\nN\\\'oublie pas de me rapporter la caisse de cadeaux d?s que tu l\\\'auras r?cup?r?e. \\nTu as tout ton temps pour le faire mais si malgr? tous tes efforts, tu n\\\'y parviens pas, tu peux repasser me voir dans deux heures.');
INSERT INTO `npc_questions` VALUES (7607, '7611;760', '', '', '0', 'Je te reconnais. Tu es l\\\'une des personnes ? qui j\\\'ai demand? de r?cup?rer une des caisses vol?es. \\nTu t\\\'en sors ?');
INSERT INTO `npc_questions` VALUES (7608, '761', '', '', '0', 'C\\\'est difficile ? ce point, ou tu n\\\'as m?me pas essay? ? \\nVoyons, quel monstre a encore des caisses vol?es...');
INSERT INTO `npc_questions` VALUES (7609, '', '', '', '', 'Je vois que tu as un trousseau de clefs. Passe-le moi un instant. \\n... \\nVoil?, tu vas pouvoir faire le donjon une fois sans utiliser de clef.');
INSERT INTO `npc_questions` VALUES (7610, '', '', '', '', 'Mille mercis. Gr?ce ? toi, de nombreux enfants m?ritants recevront leurs jouets pour Nowel. \\nPour te remercier de ta g?n?rosit?, je t\\\'ai pr?par? quelques cadeaux. J\\\'esp?re qu\\\'ils te plairont. \\nSi tu trouves les cadeaux trop petits, ma femme te les ?changera volontiers contre un cadeau plus gros. Et JOYEUX NOWEL !');
INSERT INTO `npc_questions` VALUES (7611, '', '', '', '', 'Bonzour, ze suis la femme de F?lix. Ze peux ??anzer 3 petits cadeaux de Nowel contre un normal, et 3 cadeaux normaux contre un grand cadeau. \\nPour ??anzer les cadeaux, il te suffit de me proposer un ??anze et de placer la bonne quantit? de cadeaux. \\nSi ze ne te propose aucun cadeau, ?a veut dire que la quantit? ou le type d\\\'obzets n\\\'est pas bon.');
INSERT INTO `npc_questions` VALUES (7612, '', '', '', '', 'J\\\'attends des nouvelles des autres aventuriers pour savoir si toutes les caisses ont ?t? r?cup?r?es. Repasse me voir plus tard, au cas o? il en manquerait encore quelques-unes.');
INSERT INTO `npc_questions` VALUES (7613, '', '', '', '', 'Je ne peux pas t\\\'aider, sauf si tu poss?des un trousseau de clefs. Pour t\\\'en procurer un, rends-toi au temple de ta classe. Si tu r?ussis ? y vaincre un dopeul, tu pourras ?changer le doplon gagn? contre un trousseau de clefs, qui te donne acc?s gratuitement ? tous les donjons une fois par semaine.');
INSERT INTO `npc_questions` VALUES (7614, '', '', '', '', 'Toi, qui ose fouler le sol de ce qui fut jadis un village prosp?re, aujourd\\\'hui d?truit par la folie des hommes, tu arrives trop tard.');
INSERT INTO `npc_questions` VALUES (7615, '', '', '', '', 'Tu n\\\'es donc pas au courant ? Les deux terribles dragons Grozilla et Grasmera ont ?t? d?faits. \\nTu ignores sans doute de quoi je parle, je vais donc t\\\'en dire un peu plus ? leur sujet.');
INSERT INTO `npc_questions` VALUES (7616, '', '', '', '', 'Il y a tr?s longtemps, avant m?me la cr?ation de l\\\'Horologe de X?lor, la dragonne Crocabulia a d?plu ? son ma?tre, le dieu Osamodas. Dans une ultime chance de se racheter, Crocabulia accepta de veiller sur une nouvelle race, jeune et fragile, de dragons. \\nAfin de s\\\'assurer qu\\\'elle m?ne ? bien sa mission, le dieu enferma les redoutables Grozilla et Grasmera sous le Sanctuaire. \\nLeur premier ?veil, caus? par la folie des hommes, fut terrible et marqua la fin du village primordial d\\\'Amakna. Apr?s ce massacre, ils retourn?rent dans les entrailles de la terre, sous le Sanctuaire. On n\\\'entendit plus parler d\\\'eux que dans les l?gendes.');
INSERT INTO `npc_questions` VALUES (7617, '', '', '', '', 'Evidemment, et c\\\'est pour cette raison que je te dis que tu arrives trop tard. \\nDes oeufs de dragoeufs ?tranges,  surnomm?s \\\"krokilles\\\", sont apparus un peu partout sur la presqu\\\'?le et dans les sous-terrains lors du mois de Novamaire de l\\\'an 639. De nombreux aventuriers et autres apprentis chasseurs de dragoeufs se sont mis ? les chercher pour en faire des omelettes. il faut dire que ces omelettes se vendaient ? prix d\\\'or lors des banquets du roi Allister. \\nLorsque la derni?re krokille a ?t? d?truite, Grozilla et Grasmera sont sortis de leur torpeur pour se venger de cette destruction irraisonn?e.');
INSERT INTO `npc_questions` VALUES (7618, '', '', '', '', 'Ensuite ? Des braves, mais aussi beaucoup d\\\'idiots, se sont mesur?s aux deux monstres, sans succ?s. \\nIl a fallu attendre le 24 Novamaire 639 pour que des combattants, mand?s par Shika Ingalsse en personne, parviennent ? d?faire les dragons une premi?re fois. \\nComme Grozilla et Grasmera ne s\\\'avouaient pas vaincus aussi facilement, des aventuriers de tous les horizons sont venus en renfort. \\nSans que l\\\'on connaisse leur r?elle motivation, ce sont des adorateurs du seigneur d?mon qui ont pris le relais, suivis par des disciples de Rykke-Errel et des serviteurs de Djaul. Ne voulant pas ?tre en reste, les serviteurs de la Sage Jiva ont ?galement d?fait les redoutables dragons. \\nAffaiblis par les nombreux combats, Grozilla et Grasmera n\\\'ont eut d\\\'autre choix que de retourner sous le Sanctuaire apr?s avoir ?t? ? nouveau d?faits par les serviteurs des autres protecteurs des mois et de divers dignitaires.');
INSERT INTO `npc_questions` VALUES (7619, '', '', '', '', 'Montre-moi ce que tu as l?. \\nMais, c\\\'est un morceau de krokille ! \\nSi tu le souhaites, je peux te l\\\'?changer contre une amulette magique, mais pas n\\\'importe laquelle. C\\\'est une amulette qui te permet d\\\'?tre ici sans ?tre l? tout en montrant ? tout le monde que tu y ?tais.');
INSERT INTO `npc_questions` VALUES (7620, '', '', '', '', 'Mais... la gigantesque canine que tu poss?des provient de la m?choire d\\\'un des deux dragons, n\\\'est-ce pas ? \\nElle est ?norme ! Je n\\\'en avais jamais vu de si grosse. Tu dois faire des envieux... \\nSi tu le souhaites, je peux te l\\\'?changer contre un bouclier fa?onn? ? partir d\\\'une des ?cailles de Grozilla. Ainsi, tout le monde conna?tra tes hauts faits d\\\'armes.');
INSERT INTO `npc_questions` VALUES (7621, '', '', '', '', 'Ch\\\'ti vindiou en v\\\'l? une fleur d\\\'printemps bien prope ! Qu\\\'est-ch\\\'tu veux ? *pthu* Entrer dans ch\\\'moulinache ? Ben cha m\\\'f\\\'rais mal d\\\'voir ch? !');
INSERT INTO `npc_questions` VALUES (7622, '', '', '', '', 'Dcheu, vl? qui s\\\'croit grand avec ses deux p?pites eud\\\'nain. Comme dans min pays on est euch\\\'ment sympa, Euj va t\\\'laisser aller eud\\\'dans.');
INSERT INTO `npc_questions` VALUES (7623, '', '', '', '', 'Min ch\\\'ti on est fier de ti !');
INSERT INTO `npc_questions` VALUES (7624, '', '', '', '', 'Vous voil? fort contrari? d\\\'?tre, en son sein, prisonnier. Vers la sortie je peux vous mener, sauf si un ami vous attendez.');
INSERT INTO `npc_questions` VALUES (7625, '', '', '', '', 'Soit vous n\\\'avez pas le courage de continuer, soit vos amis vous ont abandonn?. Je peux vous faire sortir d\\\'ici si vous le souhaitez.');
INSERT INTO `npc_questions` VALUES (7627, '', '', '', '', 'Parlez moins fort s\\\'il vous pla?t. Donc vous recherchez des informations sur ce bout de parchemin. Il semble bien que cela provienne d\\\'un ouvrage ancien : \\\"Goultard, gen?se d\\\'un h?ros\\\" par H. Mambillin. Malheureusement, on n\\\'a pas ce livre dans notre humble biblioth?que.');
INSERT INTO `npc_questions` VALUES (7628, '', '', '', '', 'On n\\\'a pas ?a ici je vous dis ! Il se trouve que cet ouvrage-l? a ?t? pris il y a bien longtemps par un grand ma?tre du temple de la ville. Mais c\\\'?tait il y a bien longtemps... Je ne me souviens plus lequel. Vous aurez de la chance s\\\'il a encore ce grimoire en sa possession apr?s tout ce temps. Conna?tre l\\\'histoire de Goultard peut vous ?vitez de demander ? tous les ma?tres de temple ou m?me de fouiller tous les temples. Je vous souhaite d\\\'avoir du succ?s.');
INSERT INTO `npc_questions` VALUES (7629, '', '', '', '', 'Un ouvrage sur Goultard, sur son enfance plus pr?cis?ment ? Oui, on en a un exemplaire. Malheureusement, vous devrez parler ? L?thaline Sigisbule pour le consulter.');
INSERT INTO `npc_questions` VALUES (7631, '', '', '', '', 'Un ouvrage sur Goultard, sur son enfance plus pr?cis?ment ? Oui, on en a un exemplaire. Malheureusement, vous devrez parler ? Grace Malcean pour le consulter.');
INSERT INTO `npc_questions` VALUES (7632, '', '', '', '', 'J\\\'ai appris que tu t\\\'int?resse de pr?t au pass? de Goultard. Je suis pr?te ? te confier le livre que tu recherches mais, en ?change, il te faudra travailler pour moi.');
INSERT INTO `npc_questions` VALUES (7633, '', '', '', '', 'Bien, un refus aurait ?t? mal venu. Ce livre nous en apprend plus sur Goultard et son enfance. De mon g?nial cerveau a germ? un plan ambitieux. Gr?ce ? ce que j\\\'ai appris, je suis en mesure de manipuler Goultard et le forcer ? travailler pour nous. ?videmment, malgr? mes immenses pouvoirs, je ne peux accomplir cela seule. D\\\'autant plus que je soup?onne les Bontariens de surveiller mes mouvements. C\\\'est l? que tu interviens. Retrouve-moi ? la tour de Gisgoul, je t\\\'en dirais plus.');
INSERT INTO `npc_questions` VALUES (7634, '', '', '', '', 'Hors de ma vue cancrelat ! Ou je t\\\'?crase tel l\\\'insecte r?pugnant que tu es.');
INSERT INTO `npc_questions` VALUES (7635, '', '', '', '', 'Te voil? enfin ! ?coute attentivement, voil? la premi?re phase de mon plan. Trouve le caveau des Gisgoul et rapporte moi des objets leur ayant appartenu. Je les enchanterai pour ... Je te r?v?lerai la suite ? ton retour. Le caveau est quelque part dans le cimeti?re des tortur?s. Va et d?p?che toi !');
INSERT INTO `npc_questions` VALUES (7636, '', '', '', '', 'Alors, tu m\\\'apportes tout ce que je t\\\'ai demand? ?');
INSERT INTO `npc_questions` VALUES (7637, '', '', '', '', 'D\\\'apr?s ce que je sais, elle doit ?tre en train de r?gler quelques affaires ? la milice. Va l?-bas si tu dois lui parler.');
INSERT INTO `npc_questions` VALUES (7638, '', '', '', '', 'Parfait, cela fera l\\\'affaire. Maintenant, va me chercher toutes les composantes du rituel pendant que je pr?pare le lieu de l\\\'enchantement. Du sang de vampire pour ramener l\\\'?me des morts ? la vie. Du sang d\\\'Oni pour pervertir leur vision. et enfin du sang de scorbute, un poison pour l\\\'esprit. Ne traine pas et je saurai m\\\'en souvenir.');
INSERT INTO `npc_questions` VALUES (7639, '', '', '', '', 'Presse-toi, mes pr?paratifs avancent rapidement.');
INSERT INTO `npc_questions` VALUES (7640, '', '', '', '', 'Maintenant que tout est en place, il faut que tu ailles placer ce collier d\\\'or sur la tombe de Cabotine, la m?re de Goultard.');
INSERT INTO `npc_questions` VALUES (7641, '', '', '', '', 'Voil? qui me pla?t, le pi?ge est tendu mais il reste encore beaucoup de choses ? accomplir. Comme tout cela va me prendre du temps, tu vas m\\\'aider. Tout cela me donne pas mal de travail, et visiblement tu es digne de confiance. Ma ma?tresse, la d?mone Minuit, m\\\'a signal? un Bwork vicieux et dou? au combat. Il pourrait servir ma ma?tresse, am?ne-le moi pendant que je parfais mon ?uvre.');
INSERT INTO `npc_questions` VALUES (7642, '', '', '', '', 'Kwa twa vouloir ? Grabumph ?!');
INSERT INTO `npc_questions` VALUES (7643, '', '', '', '', 'Mwa battu, mwa prisonnier. Vous quittez village et mwa suivre.');
INSERT INTO `npc_questions` VALUES (7644, '', '', '', '', 'Et bien, que vois-je l? ? Un Bwork pr?t ? servir ma ma?tresse ? C\\\'est excellent, avec ce combattant, je vais me faire une belle prime : il va faire un malheur dans les ar?nes du temps. De mon c?t?, je n\\\'ai pas perdu mon temps, le pi?ge est pr?t, il n\\\'attend plus que sa proie.');
INSERT INTO `npc_questions` VALUES (7645, '', '', '', '', 'C\\\'est presque termin? en ce qui te concerne. Il faut maintenant d?livrer le Dark Vlad de son labyrinthe. Va d?poser des plans dans la for?t mal?fique, si possible sans te faire tuer. Ainsi que des potions d\\\'intelligence, il n\\\'est pas malin quand il fait son Vlad ce Goultard ... alors, autant en profiter pour l\\\'attraper quand il n\\\'est pas au mieux.');
INSERT INTO `npc_questions` VALUES (7646, '', '', '', '', 'Tu m\\\'as bien servi, mais ... comprends qu\\\'il s\\\'agit de ne pas laisser qui que ce soit r?v?ler notre petit secret n\\\'est-ce pas. Rushu ne veut pas que la moindre rumeur sur la conversion prochaine de Goultard ? sa cause ne tra?ne dans les rues de Br?kmar. Je te laisse entre les mains, les griffes plut?t de mes cr?atures.');
INSERT INTO `npc_questions` VALUES (7647, '', '', '', '', 'Tu penses que je n\\\'ai rien d\\\'autre ? faire que d\\\'?couter tes suppliques. Hors de ma vue.');
INSERT INTO `npc_questions` VALUES (7648, '', '', '', '', 'Tu es encore en vie ? Comme je ne suis pas rancuni?re, je vais te donner un objet qui a appartenu a Goultard pendant son enfance. Lequel souhaites-tu ?');
INSERT INTO `npc_questions` VALUES (7649, '', '', '', '', 'Tu en redemandes, pas de probl?me, il m\\\'amuse de voir mes petits ch?ris mettre en pi?ces les bravaches dans ton genre.');
INSERT INTO `npc_questions` VALUES (7650, '', '', '', '', 'Vous semblez vous int?resser de pr?t ? l\\\'histoire de Goultard. Et vous n\\\'?tes pas le seul. Ces fourbes de Br?kmariens s\\\'activent dans le village abandonn? de Gisgoul. Quel rapport ? Tout simplement, Goultard y a pass? son enfance. Nos espions ne sont jamais revenus. Apparemment ils ont ?t? captur?s par des Bworks et emmen?s dans leur village. Allez l?-bas et lib?rez notre ?claireur-espion.');
INSERT INTO `npc_questions` VALUES (7651, '', '', '', '', 'Aidez-moi ! Ces cruels Bworks veulent me cuire ? la vapeur et faire des pieds de tables avec mes os. C\\\'est ce gros Bwork l?-bas qui me retient prisonni?re.');
INSERT INTO `npc_questions` VALUES (7652, '', '', '', '', 'Grabumph !');
INSERT INTO `npc_questions` VALUES (7653, '', '', '', '', 'Qwa twa veut ? Twa veut fille maigre ? Grumph ?');
INSERT INTO `npc_questions` VALUES (7654, '', '', '', '', 'Twa fort, twa prendre fille-kasse-kroute.');
INSERT INTO `npc_questions` VALUES (7655, '', '', '', '', 'Libre, je suis libre ! Merci, j\\\'ai vraiment cru que j\\\'allais passer ? la casserole cette fois. Quittons cet endroit et je vous r?v?lerai ce que j\\\'ai appris. Je sais que je peux vous faire confiance et je vous dois bien ?a.');
INSERT INTO `npc_questions` VALUES (7656, '', '', '', '', 'Bien, maintenant que je suis en s?curit?, voil? les informations que j\\\'ai pu obtenir sur Gisgoul et les activit?s Br?kmariennes. Les Br?kmariens projettent d\\\'utiliser Goultard et d\\\'asservir le monde. Rien de tr?s nouveau les concernant mais ils semblent avoir un plan. Je les ai entendu mentionner le cimeti?re des tortur?s et la tombe de la m?re de Goultard. Mais j\\\'ai ?t? captur?e avant de pouvoir m\\\'y rendre. A priori, les Bworks ne travaillent pas pour eux, c\\\'est d?j? ?a. Je pense que L?thaline Sigisbul est derri?re tout ?a.');
INSERT INTO `npc_questions` VALUES (7657, '', '', '', '', 'Je fais un m?tier vraiment pas facile. Il faut que je pense ? ma reconversion professionnelle.');
INSERT INTO `npc_questions` VALUES (7658, '', '', '', '', 'Vous avez bien agi. Mais il reste encore une t?che ? accomplir. D\\\'apr?s les sages et les mages de Bonta, l\\\'objet mal?fique avait pour but d\\\'attirer le Dark Vlad vers la tombe de sa m?re. Br?kmar d?pose des plans dans le labyrinthe pour guider Dark Vlad. Cela ne doit en aucun cas r?ussir. Vous devez les en emp?cher. Trouvez et d?truisez les indices diss?min?s par les Br?kmariens. ');
INSERT INTO `npc_questions` VALUES (7659, '', '', '', '', 'C\\\'est toi qui t\\\'?vertue ? contrecarrer mes plans g?niaux. Tu pensais que je n\\\'en saurais rien ? Tu vas comprendre qu\\\'il ne faut pas me mettre en col?re. Meurs !');
INSERT INTO `npc_questions` VALUES (7660, '', '', '', '', 'C\\\'est fantastique, Vous avez r?ussi ? emp?cher les Br?kmariens d\\\'accomplir leurs sombres desseins. Je suis tellement ?mue que j\\\'en pleurerais. Pour vous r?compenser de cet acte h?ro?que, je vais vous remettre un objet ayant appartenu ? Goultard dans sa jeunesse. Lequel vous ferait plaisir ?');
INSERT INTO `npc_questions` VALUES (7661, '', '', '', '', 'Merci aventurier, nous ne sommes plus corrompu par la magie Br?kmarienne. Quand Goultard viendra se recueillir, nous ne serons pas oblig?s de l\\\'attaquer. Il vous reste une chose ? faire : portez cet objet mal?fique au temple Iop. Le p?re de Goultard saura quoi en faire !');
INSERT INTO `npc_questions` VALUES (7662, '', '', '', '', 'Il faut si froid ici ...');
INSERT INTO `npc_questions` VALUES (7663, '', '', '', '', 'Miaouuuhh !');
INSERT INTO `npc_questions` VALUES (7664, '', '', '', '', 'Grace se trouve dans la milice en ce moment si je ne me trompe pas. C\\\'est une personne charmante, mais ses responsabilit?s au sein du conseil lui imposent de prendre parfois des d?cisions difficiles.');
INSERT INTO `npc_questions` VALUES (7665, '', '', '', '', 'Je per?ois une aura mal?fique qui vous entoure. Dites-moi ce que vous voulez avant que je ne prenne les mesures qui s\\\'imposent.');
INSERT INTO `npc_questions` VALUES (7666, '', '', '', '', 'Je comprends, pardonnez ma m?fiance. Ce bijou renferme une sombre puissance qu\\\'il faut briser. Je vais demander conseil ? Iop. Lui saura quoi en faire. Votre t?che est termin?e, vous pouvez vous f?liciter car, sans votre intervention, qui sait quel mal aurait pu causer cet objet. Vous incriminez L?thaline et il faut que justice lui soit rendue. Affichez ces avis de recherche dans les villages et cit?s que tous les chasseurs de prime soient au courant qu\\\'une r?compense sera offerte pour sa capture.');
INSERT INTO `npc_questions` VALUES (7668, '', '', '', '', 'Vous ?tes d?j? un alchimiste.');
INSERT INTO `npc_questions` VALUES (7669, '', '', '', '', 'Vous avez certainement un m?tier en cours d\\\'apprentissage ou vous connaissez d?j? suffisamment de professions.');
INSERT INTO `npc_questions` VALUES (7670, '', '', '', '', 'C\\\'est un m?tier polyvalent. Les alchimistes sont ? la fois r?colteurs et artisans. Les potions et ?lixirs qu\\\'ils confectionnent sont tr?s puissants et souvent assimil?s ? la magie. En r?coltant des plantes pr?cises et en les mixant avec talent, un alchimiste est capable de miracles.');
INSERT INTO `npc_questions` VALUES (7671, '', '', '', '', 'Nib? lulle a un atelier ? Astrub. Il est facile de le rencontrer l?-bas. En revanche, il n\\\'enseigne pas son art ? tout le monde.');
INSERT INTO `npc_questions` VALUES (7672, '', '', '', '', 'J\\\'esp?re que tu ne l\\\'as perdue au moins. Non ? Tant mieux, dans le cas contraire, Amayiro t\\\'en aurait certainement voulu.');
INSERT INTO `npc_questions` VALUES (7673, '', '', '', '', 'Les stocks d\\\'ap?wicubes doivent ?tre surveill?s jour et nuit car les mansots essayent r?guli?rement d\\\'en voler. C\\\'est une t?che ingrate mais n?cessaire, car d?couper et remonter tous ces blocs de glace a d?j? demand? ?norm?ment d\\\'efforts.');
INSERT INTO `npc_questions` VALUES (7674, '', '', '', '', 'Vous parlez des ap?wicubes ? Ils contiennent ce qui se trouvait dans le lac au moment de son gel, c\\\'est-?-dire un peu tout et n\\\'importe quoi. Ca va du poisson surgel?, normal me direz-vous, au pain congel?, en passant par des bonbons, des clefs, et un tas d\\\'autres cochonneries. Une fois, nous avons m?me sorti un objet d\\\'?levage emprisonn? dans la glace, c\\\'est vous dire !');
INSERT INTO `npc_questions` VALUES (7675, '', '', '', '', 'Oh, une Plume Vibrante de mansot ! Que fait-elle dans votre post?rieur ? Ne r?pondez pas, je ne veux pas savoir. \\nVous ignorez sans doute comment vous en servir, pas vrai ? Tant mieux... Je vous l\\\'?change contre un de nos ap?wicubes fra?chement d?coup?s. Qu\\\'en dites-vous ?');
INSERT INTO `npc_questions` VALUES (7676, '', '', '', '', 'Merci ? vous. Tenez, prenez n\\\'importe lequel de ces ap?wicubes. \\nSi vous trouvez d\\\'autres Plumes Vibrantes de mansot, n\\\'h?sitez pas ? venir me les ?changer contre d\\\'autres ap?wicubes, j\\\'en ai tout un stock depuis que vous nous avez aid?s ? r?tablir nos lignes de p?che.');
INSERT INTO `npc_questions` VALUES (7677, '', '', '', '', 'Prenez votre temps et pr?venez-moi d?s que vous vous serez d?cid');
INSERT INTO `npc_questions` VALUES (7678, '7703;7705;7706', '', '', '', '*Une force très puissante se dresse devant vous. C\\\'est le dernier obstacle qui vous sépare du maître des lieux. \\nIl y a fort à parier que si vous forcez le passage, vous vous sentirez épuisé. \\n \\nPeut-être existe t-il quelque chose qui pourrait vous protéger ?*');
INSERT INTO `npc_questions` VALUES (7679, '', '', '', '', 'Oh c\\\'est vrai ? Vous ?tes bien aimable. Faites attention, ils sont quand m?me f?roces. \\nKiki sera bien content.');
INSERT INTO `npc_questions` VALUES (7680, '', '', '', '', 'Merci beaucoup. Tenez voici un peu d\\\'argent de poche, vous l\\\'avez bien m?rit?. Je me demande quand m?me ce que ces rats bougris d?lav?s viennent faire ici. Je suis s?r que c\\\'est ? cause de toute cette pagaille dans la tuyauterie. Ca fait remonter les rats bougris d?lav?s ?a... Kiki est d\\\'accord avec moi !');
INSERT INTO `npc_questions` VALUES (7681, '', '', '', '', 'Mouk e?t\\\'nez, t\\\'as du brin ? t\\\'bottine. \\nTi l? pour eul\\\' YeCh\\\'Ti ?');
INSERT INTO `npc_questions` VALUES (7682, '', '', '', '', 'Hum hum ! \\n\\\" \\n- Il faut former une ?quipe de quatre personnes au maximum. \\n- Il est INTERDIT d\\\'avoir plusieurs personnages de la m?me classe dans la m?me ?quipe. Toute ?quipe dont au moins deux personnages sont de la m?me classe sera automatiquement disqualifi?e. \\n- Une fois le combat engag?, chaque ?quipe dispose de 30 minutes maximum pour vaincre le YeCh\\\'Ti. \\n- Si le combat est perdu avant les 30 minutes, ou si le combat est toujours en cours au bout de 30 minutes, l\\\'?quipe est consid?r?e comme perdante.\\\"');
INSERT INTO `npc_questions` VALUES (7683, '', '', '', '', 'Att?nd, te vas v?r, te vas pr?nte s?h t\\\'guiffe !');
INSERT INTO `npc_questions` VALUES (7684, '', '', '', '', 'Encore un touriste... Tu as vu de la lumi?re alors tu es entr?, c\\\'est ?a ? Je ne comprends pas pourquoi Seth Leurse, mon pr?d?cesseur, n\\\'a pas fait poser de verrou sur la porte. \\nBon, puisque tu es l?, tu vas pouvoir te rendre utile. Des animaux troublent la qui?tude de Frigost mais je n\\\'ai pas le temps de tous les d?cimer. Ca te dit de me donner un coup de main ?');
INSERT INTO `npc_questions` VALUES (7685, '', '', '', '', 'Bonjour, tu te trouves devant l\\\'endroit le plus chaud de l\\\'?le, en dehors de son volcan bien s?r. \\nNous nous servons de ces serres pour cultiver de nouvelles plantes qui ne survivraient pas aux temp?ratures glaciales de l\\\'?le, et surtout pour pouvoir les replanter lorsque l\\\'?ge de glace sera termin?. \\nMalheureusement, des boufmouths affam?s sont all?s jusqu\\\'? ?lire domicile dans les serres, ? la recherche de nourriture, et ils sont devenus agressifs ? cause de la chaleur. Ils se sont mis ? attaquer le personnel et ? d?vorer les plantes, allant m?me jusqu\\\'? brouter le gazon de mon ?pouse, qui ?tait la directrice de la serre, tu te rends compte ? \\nEn ?change de la clef de la serre, je peux te laisser entrer pour botter l\\\'arri?re-train de ce Royalmouth, mais attention ! Il est pantouflard et semble avoir des r?actions disproportionn?es lorsqu\\\'il est d?plac');
INSERT INTO `npc_questions` VALUES (7686, '', '', '', '', 'Puisque tu as veng? l\\\'affront fait par le Royalmouth ? mon ?pouse, je vais parler de toi ? mon ami de la compagnie Asfog et Fils pour qu\\\'il te laisse utiliser son transporteur.');
INSERT INTO `npc_questions` VALUES (7687, '', '', '', '', 'J\\\'ai vu la flamme qui brillait dans ton regard. Toi aussi tu d?testes les animaux, n\\\'est-ce pas ? \\nVoici la liste des animaux ? exterminer et surtout, n\\\'oublie pas de m\\\'apporter une preuve de ton travail.');
INSERT INTO `npc_questions` VALUES (7688, '', '', '', '', 'Tes mains sont couvertes du m?me sang dont tes yeux sont inject?s. \\nVoil? pour ta peine et si tu veux exterminer d\\\'autres cr?atures nuisibles, j\\\'aurai toujours du travail pour toi.');
INSERT INTO `npc_questions` VALUES (7689, '', '', '', '', 'J\\\'ai suffisamment de monde pour chasser les cr?atures r?dant pr?s des habitations. Par contre, les volontaires pour les zones recul?es de l\\\'?le se font plus rares. \\nJ\\\'ai imm?diatement vu que nous partagions une haine visc?rale pour les cr?atures de l\\\'?le. \\nVoici la liste des animaux ? exterminer et surtout, n\\\'oublie pas de m\\\'apporter une preuve de ton travail.');
INSERT INTO `npc_questions` VALUES (7690, '', '', '', '', 'Bonjour, bienvenue dans la bourgade de Frigost. Avez-vous fait bon voyage ? \\nJe n\\\'avais pas vu de chemise ? fleurs ni de bermuda depuis longtemps, mais vous devriez vous couvrir davantage, sinon vous risquez d\\\'attraper le rube. \\nSi vous ne l\\\'avez pas d?j? fait, je vous invite ? rencontrer notre mairesse, elle se fera un plaisir de vous accueillir et de vous pr?senter les lieux.');
INSERT INTO `npc_questions` VALUES (7691, '', '', '', '', 'L\\\'h?tel de ville se trouve non loin du zaap, r?cemment r?par? gr?ce aux continentaux. \\nTenez, voici une carte des lieux, j\\\'y ai indiqu? les points importants de la r?gion.');
INSERT INTO `npc_questions` VALUES (7692, '', '', '', '', 'Bonjour et bienvenue ? Frigost. \\nComme vous avez pu le constater en venant ici, la bourgade n\\\'est pas au mieux de sa forme, mais gr?ce aux efforts de nos valeureux citoyens, le contact a pu ?tre r?tabli avec le continent.');
INSERT INTO `npc_questions` VALUES (7693, '', '', '', '', 'J\\\'avais d?j? du mal ? fournir du pain ? toute la bourgade avant, alors maintenant, avec l\\\'arriv?e massive de continentaux, c\\\'est encore pire. Mais faut voir le bon c?t? des choses, plus il y aura d\\\'aventuriers, plus ?a fera de monde pour r?gler son compte au comte.');
INSERT INTO `npc_questions` VALUES (7694, '', '', '', '', 'Ah ?a, je veux bien. Habituellement, c\\\'est Annette Daimpeau qui se charge de m\\\'approvisionner en c?r?ales, mais elle a tendance ? r?vasser et oublie souvent son travail. J\\\'ai essay? plusieurs fois de la raisonner mais que voulez-vous, c\\\'est dans sa nature de Sadida, et on ne peut pas lutter contre la nature des choses. Nous autres, Frigostiens, sommes bien plac?s pour le savoir. \\nBref, ?a m\\\'arrangerait que vous la remplaciez et que vous m\\\'apportiez une dizaine de Frostizs.');
INSERT INTO `npc_questions` VALUES (7695, '', '', '', '', 'J\\\'ai ador? la mani?re dont tu as mis la p?t?e ? ces boufmouths. J\\\'esp?re que ?a calmera leur ardeur un moment et que nous pourrons bient?t reprendre nos travaux.');
INSERT INTO `npc_questions` VALUES (7696, '', '', '', '', 'Le mieux est de reprendre mon enqu?te l? o? je l\\\'ai laiss?e. Trouvez la tombe de Cabotine dans le cimeti?re des tortur?s. Bonne chance ? vous.');
INSERT INTO `npc_questions` VALUES (7703, '', '', '', '', 'Bonjour, je vois que vous n\\\'en avez fait qu\\\'? votre t?te et que vous ?tes tomb? malade. Si vous aviez ?cout? mes conseils, ?a ne serait pas arriv?. \\nAllez vite voir notre m?decin Albert Paisse, il travaille sur un antidote.');
INSERT INTO `npc_questions` VALUES (7704, '', '', '', '', 'Ne m\\\'approchez pas, vous ?tes malade. Allez vite prendre rendez-vous aupr?s d\\\'Albert Paisse, notre m?decin.');
INSERT INTO `npc_questions` VALUES (7705, '', '', '', '', 'Achetez mon poisskaille ! \\nIl est frais mon poisskaille !');
INSERT INTO `npc_questions` VALUES (7706, '', '', '', '', 'Bonjour, si tu penses que je vais te laisser utiliser mon transporteur, tu te fourres le moufle dans l\\\'oeil. Prouve-moi que tu es digne de confiance et alors peut-?tre, je dis bien peut-?tre, je te laisserai monter ? bord.');
INSERT INTO `npc_questions` VALUES (7707, '', '', '', '', 'Parce que tu crois que nous avons du temps ?! Les animaux ne vont pas se tourner les pouces en attendant que tu prennes ta d?cision, ? moins que... tu es ? leur service, c\\\'est ?a ?');
INSERT INTO `npc_questions` VALUES (7708, '', '', '', '', 'Ahahah, je plaisantais ! Tu es trop gringalet, les cr?atures ? l\\\'ext?rieur de la cit? ne feraient qu\\\'une bouch?e de toi, et je me vois mal annoncer ? la mairesse qu\\\'un autre touriste est encore mort par ma faute.');
INSERT INTO `npc_questions` VALUES (7709, '', '', '', '', 'Si vous souhaitez mieux conna?tre la r?gion, le plus simple est de rencontrer les habitants de la bourgade. Evidemment, il est inutile de tous leur parler, c\\\'est pourquoi je vous ai pr?par? une liste des personnalit?s les plus int?ressantes. \\nLorsque vous vous serez familiaris? avec les lieux, revenez me voir, j\\\'aurai plusieurs services ? vous demander.');
INSERT INTO `npc_questions` VALUES (7710, '', '', '', '', 'Merci, c\\\'est pas grand chose mais ?a va beaucoup nous aider. Ah c\\\'est s?r, c\\\'est pas comme avant. Je me souviens encore des longues files de charrettes remplies de c?r?ales qui faisaient la navette entre les champs et le port... Bref, ?a appartient au pass?, inutile de ressasser.');
INSERT INTO `npc_questions` VALUES (7712, '', '', '', '', 'Non, je ne veux pas de votre purin ici. Je commence ? en avoir assez de cette blague idiote. \\nAh, vous ne distribuez pas de fumier ? A vous voir tout cro?t?, j\\\'ai cru que... enfin... non, rien. \\nMais attendez... Vous n\\\'?tes pas d\\\'ici, c\\\'est ?vident ! Oubliez donc cette histoire de fumier, et bienvenue dans mon atelier. \\nVous prendrez une petite tisane ?');
INSERT INTO `npc_questions` VALUES (7713, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7714, '', '', '', '', 'Je n\\\'ai pas le temps ! \\nBuvez un bon litre d\\\'alcool, plongez la blessure dans de l\\\'eau bouillante et pansez la plaie avec du bandage qui a ?t? st?rilis? au pr?alable avec de la bave de boufmouth. \\nHein, quoi, vous n\\\'?tes pas bless? ? \\nOh, pardon, qu\\\'est-ce que je peux faire pour vous ? Faites vite, je n\\\'ai pas beaucoup de temps ? vous accorder car au rythme o? le rube s\\\'?tend, ce sera bient?t l\\\'?pid?mie. Je dois trouver un vaccin efficace avant qu\\\'il ne soit trop tard.');
INSERT INTO `npc_questions` VALUES (7715, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7716, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7717, '', '', '', '', 'Ecoute moussaillon, je suis le chef de la capitainerie alors tu me dois le respect ! \\nJe sais, il n\\\'y a plus de d?part de bateaux depuis la glaciation, sauf exception. Mais ?a veut pas dire que je suis au ch?mage ! \\nNon, je n\\\'ai pas bu... Je me rince la gorge en r?fl?chissant, c\\\'est tr?s diff?rent. \\nQuoi ? Tu trouves que je me rince la gorge souvent ? C\\\'est normal, c\\\'est pour ?viter que l\\\'int?rieur de ma gorge g?le ? cause du froid. D\\\'ailleurs, ? trop parler, ?a m\\\'a donn? soif. Non, je t\\\'en passe pas. Si t\\\'as soif, va ? la taverne.');
INSERT INTO `npc_questions` VALUES (7718, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7719, '', '', '', '', 'Bonjour toi, je suis s?re que tu cherches du poisson frais. Ca tombe bien, le mien est ce qu\\\'il y a de plus frais, quelque soit la p?riode de l\\\'ann?e. On ne peut pas en dire autant de cette pauvre Lucette, mais c\\\'est le jeu ma pov\\\'. \\nTu me croiras si tu veux, mais j\\\'ai vu Mac Givr? fricoter avec la petite Mel. Qu\\\'est-ce que sa m?re dirait si elle le savait....');
INSERT INTO `npc_questions` VALUES (7720, '', '', '', '', 'Dans ma famille, nous sommes dresseurs d\\\'animaux depuis cinq g?n?rations. \\nLa glaciation m\\\'a permise de me perfectionner et je suis, ? ce jour, la meilleure dresseuse de chienchiens de l\\\'histoire de Frigost. Quoiqu\\\'on te dise, c\\\'est moi qui les ai tous dress?s. Oui, je parle toujours des chienchiens l?. \\nLa clef de la r?ussite d\\\'un bon dressage, c\\\'est la fermet?, et ce ne sont pas les propri?taires de chienchiens des neiges qui diront le contraire. \\nNe te m?prends pas, mes talents de dresseuse s\\\'appliquent ? la quasi-totalit? de la faune de Frigost, les chienchiens sont juste ma sp?cialit');
INSERT INTO `npc_questions` VALUES (7721, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7722, '', '', '', '', 'Bonjour cher touriste, permettez-moi de me pr?senter. Je suis le disciple de Sram Germain Danlsak. Ah, c\\\'est le v?tre ? Toutes mes excuses, il ressemble tellement au mien que c\\\'est ? s\\\'y m?prendre. \\nComment ? Que je remette ces bijoux o? je les ai trouv?s ? Bien s?r, je ne faisais que les regarder. \\nSi je puis vous donner un conseil, m?fiez-vous des honn?tes gens. Pourquoi ? Tout simplement car vous ne savez pas quand est-ce qu\\\'ils vous trahiront. C\\\'est tout le contraire de nous autres, disciples de Sram. \\nOh, c\\\'est votre bourse de kamas que je tiens l? ? Vous l\\\'aviez sans doute ?gar?, c\\\'est une chance que je l\\\'eusse trouv?e.');
INSERT INTO `npc_questions` VALUES (7725, '', '', '', '', 'Qu\\\'est-ce qu\\\'on se les g?le. Ca fait pratiquement un si?cle mais je n\\\'ai toujours pas r?ussi ? m\\\'y faire. Si on avait suivi mon id?e au lieu de celle du Comte de Strasbourg, nous n\\\'en serions pas l?. Quand les cultures br?lent, au moins il fait chaud. \\nJe songe s?rieusement ? aller m\\\'installer au nord de l\\\'?le, pr?s des tunnels de lave. La seule chose qui me d?range si je vais l?-bas, c\\\'est la proximit? du ch?teau du Comte Le Balourd.');
INSERT INTO `npc_questions` VALUES (7727, '', '', '', '', 'Salet?s de bestioles ! Si le Comte ne nous avait pas trahis, mes mines ne seraient pas infest?es. J\\\'esp?re qu\\\'un de ces quatre, quelqu\\\'un d\\\'assez fort le punira. Ce qu\\\'il nous faudrait, c\\\'est des couturiers d\\\'Amakna pour lui botter les fesses, parce que les rigolos qu\\\'on a eu jusqu\\\'? pr?sent n\\\'ont pas fait un pli. \\nEn attendant, mes mines restent infest?es et pas moyen de s\\\'approvisionner en obsidienne.');
INSERT INTO `npc_questions` VALUES (7729, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7730, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7731, '', '', '', '', 'DIALOGUE DE BASE.');
INSERT INTO `npc_questions` VALUES (7732, '', '', '', '', 'Bonjour, vous savez que c\\\'est gr?ce ? moi et mes gars que nous avons r?ussi ? r?tablir une voie avec Amakna ? Bon, pas exactement Amakna, mais c\\\'est tout comme. \\nNous avons travaill? dur pendant plusieurs d?cennies pour acheminer la chaleur jusqu\\\'au port et mettre au point un syst?me de chauffage ? la vapeur, mais ?a a fini par payer. Maintenant, va falloir r?ussir ? d?geler le reste du port et ?a, c\\\'est pas encore gagn');
INSERT INTO `npc_questions` VALUES (7733, '', '', '', '', 'Vous vous y connaissez en alchimie ? Ca expliquerait l\\\'?tat de vos v?tements... \\nTant mieux, ?a fait plaisir de rencontrer quelqu\\\'un avec un quotient intellectuel sup?rieur ? celui d\\\'un boufmouth. \\nJ\\\'ai un petit service ? vous demander, et si je vous le demande, c\\\'est parce que je ne peux pas compter sur mes lourdeaux de concitoyens. D\\\'ailleurs, le citoyen est en trop, si vous voyez ce que je veux dire... \\nIl y a tellement de gens maladroits ici que je ne peux pas laisser mon atelier sans surveillance, et mes r?serves de Perce-Neige s\\\'amenuisent de jour en jour. Pouvez-vous m\\\'en apporter une dizaine ?');
INSERT INTO `npc_questions` VALUES (7734, '', '', '', '', 'Oh, elles sont si belles... Avant la glaciation, des centaines d\\\'esp?ces de plantes diff?rentes se c?toyaient sur Frigost. Mais les Frigostiens ont pr?f?r? suivre le comte et se moquer de moi... Ca leur apprendra ? ces idiots ! \\nEn parlant de fleurs, vous devriez visiter nos serres, ? l\\\'ext?rieur de la bourgade. Mes amis Truffo et Bisale travaillent sur de nouvelles esp?ces. Vous ne pouvez pas les rater, il y en a plusieurs dans les champs, autour de la bourgade.');
INSERT INTO `npc_questions` VALUES (7735, '', '', '', '', 'Olala, ne m\\\'en parle pas. Avec l\\\'arriv?e de tous ces gens du continent, mes r?serves s\\\'?puisent ? vue d\\\'oeil. J\\\'ai tellement peur de ne pas en avoir assez pour les prochains mois que j\\\'ai arr?t? d\\\'en donner ? mon chacha. Le pauvre petit, c\\\'est qu\\\'il a faim, Duss. \\nCa te dirait de te faire quelques kamas ? Si tu m\\\'apportes 10 Poisskailles, je saurai me montrer g?n?reuse.');
INSERT INTO `npc_questions` VALUES (7736, '', '', '', '', 'Merci, si d\\\'autres personnes font comme toi, mes r?serves de poisskailles devraient tenir encore un bon moment. \\nJ\\\'ai entendu dire qu\\\'Albert Paisse, notre m?decin, avait contract? une sale maladie dans sa jeunesse un peu folle. Il para?t m?me que sa recherche d\\\'un vaccin contre le rube n\\\'est qu\\\'un pr?texte pour trouver un rem?de ? sa maladie. Si ce n\\\'?tait pas une personne de confiance qui me l\\\'avait dit, je ne t\\\'en parlerais pas.');
INSERT INTO `npc_questions` VALUES (7737, '', '', '', '', 'Pourquoi est-ce que je te ferais confiance ? Tout mon personnel est parti lorsque les premi?res cr?atures sont apparues dans les mines. Le comte m\\\'a trahi, les Frigostiens m\\\'ont trahi... Remarque, ?a peut pas ?tre pire. \\nJ\\\'ai justement besoin d\\\'obsidienne pour fondre des alliages pour entretenir le syst?me de tuyauterie qui alimente le port. Apporte m\\\'en une dizaine.');
INSERT INTO `npc_questions` VALUES (7738, '', '', '', '', 'T\\\'es plus brave que t\\\'en as l\\\'air. C\\\'est des gens comme toi qu\\\'il nous faut pour r?gler son compte au comte Harebourg.');
INSERT INTO `npc_questions` VALUES (7739, '', '', '', '', 'Les bras ne manquent pas mais les hommes sont fatigu?s et des b?tes f?roces r?dent dans la for?t. En plus, il faut constamment lutter contre le gel du port et nous commen?ons ? manquer de combustible pour nos chaudi?res. Ca m\\\'arrangerait bien que tu ailles me chercher 10 Bois de Tremble.');
INSERT INTO `npc_questions` VALUES (7740, '', '', '', '', 'Ta vigueur doit s\\\'expliquer par des origines frigostiennes. Je vais appeler les gars pour qu\\\'ils aillent faire s?cher le bois. \\nSi t\\\'en as d\\\'autre, je suis preneur.');
INSERT INTO `npc_questions` VALUES (7741, '', '', '', '', 'Gr?ce ? la glaciation, j\\\'ai pu pr?server un ?levage cent pour cent bio. Mes veaux sont ?lev?s au grain et leur poil trait? avec des produits d\\\'origine v?g?tale compl?tement biod?gradables. Bon, d\\\'accord, ils cr?vent de faim et mangent ce qu\\\'ils peuvent, mais ils arrivent ? survivre m?me si, contrairement ? avant, ils n\\\'ont pas grand chose ? se mettre sous la dent. \\nLe seul gros hic, c\\\'est les tiques. Et qu\\\'on vienne pas me parler d\\\'?thique chez les Frigostiens : ils n\\\'en ont pas plus que moi.');
INSERT INTO `npc_questions` VALUES (7742, '', '', '', '', 'Bonjour et bienvenue. \\nLes services actuellement disponibles ? l\\\'?tage sont les suivants : \\n- consultation des artisans disponibles, tous m?tiers confondus. \\n- agence immobili?re, recensant les maisons et enclos en vente. \\nLes s?ances de massage priv? sont r?serv?es au directeur de l\\\'agence et au chef de la milice.');
INSERT INTO `npc_questions` VALUES (7743, '', '', '', '', 'Bonjour, bienvenue ? l\\\'agence immobili?re Jackenry. \\nSi vous cherchez la maison de vos r?ves ou un enclos pour ?lever vos dragodindes, vous avez sonn? ? la bonne porte. \\nNos agents recensent en permanence les maisons et enclos mis en vente, pour vous offrir le meilleur choix au meilleur prix. \\nN\\\'h?sitez pas ? consulter r?guli?rement nos offres.');
INSERT INTO `npc_questions` VALUES (7744, '', '', '', '', 'Alors ?a y est, vous vous ?tes familiaris? avec les lieux ? \\nN\\\'h?sitez pas ? discuter avec les habitants de la bourgade et des environs, ils ont des tas de probl?mes ? r?gler. \\nLorsque vous vous sentirez pr?t, vous pourrez partir affronter le Comte Harebourg et empocher une partie de ses richesses.');
INSERT INTO `npc_questions` VALUES (7745, '', '', '', '', 'C\\\'est ? cause de ce sinistre X?lor qu\\\'un hiver perp?tuel s\\\'est install? sur notre belle ?le. Depuis, il s\\\'affaiblit de jour en jour et sombre peu ? peu dans la folie, c\\\'est pourquoi il faut le punir maintenant.');
INSERT INTO `npc_questions` VALUES (7746, '', '', '', '', 'Le syst?me de serres chauff?es ? la vapeur que vous voyez derri?re moi nous permet de faire pousser de nouvelles plantes et c?r?ales. Bien qu\\\'elle n\\\'ait pas gagn? le concours d\\\'invention agricole, elle est aujourd\\\'hui notre meilleur moyen de lutter contre la famine. \\nLa plupart des c?r?ales issues de l\\\'agriculture intensive n\\\'ont pas r?sist? ? la la glaciation, mais gr?ce ? de nombreux croisements, nous avons r?cemment mis au point une nouvelle esp?ce de c?r?ales r?sistante au froid : le Frostiz. C\\\'est gr?ce ? lui que nous pouvons survivre, mais il n\\\'est pas encore au point.');
INSERT INTO `npc_questions` VALUES (7747, '', '', '', '', 'Bien que r?sistant, le Frostiz est difficile ? entretenir et ? reproduire, et nous sommes encore loin d\\\'avoir un rendement suffisant pour que toute la population mange ? sa faim. Malheureusement, nos r?serves de graines s\\\'amenuisent et la capacit? de culture de nos serres pour l\\\'exp?rimentation est limit?e. Vous seriez bien aimable de nous aider ? renouveler nos r?serves de graines. Qu\\\'en dites-vous ? \\nSi vous ?tes d\\\'accord, il me faudrait une cinquantaine de Graines de Pois que vous trouverez accroch?es dans les poils des boufmouths, une dizaine de Graines d\\\'Engrain qui poussent parfois dans les champs et des Graines de Frostiz.');
INSERT INTO `npc_questions` VALUES (7748, '', '', '', '', 'Pendant que nous menions une exp?rience sur les c?r?ales, j\\\'ai pens? que nous pourrions les modifier pour qu\\\'elles puissent ?tre utilis?es dans la fabrication de divers aliments pour augmenter leur rentabilit?, par exemple en cr?ant des biscuits. Pour cela, j\\\'ai besoin de 60 Graines Ola dont les cr?atures de la for?t des pins perdus sont friandes. Il me faut aussi 10 Graines Deupin pour ?tudier leur exceptionnelle r?sistance au froid. Pouvez-vous vous en charger ?');
INSERT INTO `npc_questions` VALUES (7749, '', '', '', '', 'Albert Paisse m\\\'a rapport? que les mansots ?taient tr?s r?sistants car ils mangeaient des graines riches en fer. Peut-?tre tenons-nous l? un moyen d\\\'accro?tre la r?sistance de nos c?r?ales. \\nApportez-moi 65 Graines de Lentille et je vous r?compenserai davantage.');
INSERT INTO `npc_questions` VALUES (7750, '', '', '', '', 'Le gel de la mer a bloqu? tout commerce avec l\\\'ext?rieur, arr?tant ainsi l\\\'importation de sel. Nos r?serves ont quasiment disparues en moins d\\\'une d?cennie et la rationnement a entra?n? des cas d\\\'astrubisme chez certains Frigostiens. Les sympt?mes sont l\\\'arr?t du d?veloppement physique et mental associ? ? la diminution du m?tabolisme de base. \\nGr?ce ? de braves Frigostiens, nous avons d?couvert des cargaisons de grains de sel dans le berceau d\\\'Alma, mais les r?cup?rer dans un environnement aussi hostile a d?j? co?t? la vie ? plusieurs personnes. \\nSi vous avez assez de cran, pouvez-vous d?fier les fant?mes de pirate et r?cup?rer 70 grains de sel ? Nous pourrions ainsi accro?tre leur production en serre.');
INSERT INTO `npc_questions` VALUES (7751, '', '', '', '', 'Nous perdons beaucoup de temps ? lutter contre les mauvaises herbes et les parasites. J\\\'ai beaucoup discut? avec d\\\'autres agriculteurs et nous sommes arriv?s ? la m?me conclusion : il faut renforcer le m?tabolisme du frostiz pour lui permettre de lutter seul. Nous pourrons ainsi nous concentrer sur d\\\'autres t?ches. \\nLes Graines Hades et Hayes que l\\\'on trouve dans les larmes d\\\'Ourinigride sont les plus r?sistantes ? ces probl?mes. Les premi?res sont habituellement prot?g?es par les cr?atures de la r?gion, il m\\\'en faut 75. Les autres sont plus rares mais peuvent pousser n\\\'importe o? autour des sources d\\\'eau chaude, une dizaine fera l\\\'affaire.');
INSERT INTO `npc_questions` VALUES (7752, '', '', '', '', 'Bien que le temps soit gel? sur l\\\'?le, nous arrivons ? cultiver des c?r?ales dans nos serres, allez comprendre... \\nNos exp?riences vont bon train mais nous nous heurtons ? un probl?me majeur : beaucoup de nos c?r?ales ne supportent pas le changement brusque de temp?rature. Ca nous oblige ? les conserver et ? les transporter puis distribuer dans des conditions sp?ciales et particuli?rement contraignantes. \\nJ\\\'ai entendu parler des graines de basalte qui, para?t-il, sont tr?s tr?s r?sistantes aux variations de temp?rature. Il m\\\'en faut 80 mais les cr?atures des tunnels de lave ne voudront probablement pas vous les c?der de bon coeur. Puisque vous serez sur place, r?coltez ?galement 10 graines houilles, elles sont r?sistantes ? l\\\'humidit? et formeront un bon compl?ment aux graines de sel.');
INSERT INTO `npc_questions` VALUES (7753, '', '', '', '', 'Merci, gr?ce ? votre aide nous allons pouvoir continuer nos exp?riences sur les c?r?ales et qui sait, peut-?tre qu\\\'un jour nous parviendrons ? relancer suffisamment l\\\'agriculture pour concurrencer de nouveau Amakna.');
INSERT INTO `npc_questions` VALUES (7754, '', '', '', '', 'Voil? qui nous sera utile pour commencer de nouvelles recherches en parall?le des exp?riences pour am?liorer nos c?r?ales. Si nous parvenons ? diversifier les produits ? base de c?r?ales frigostiennes, nous serons ? m?me de supplanter Amakna. Vivement que nous soyons d?barrass?s du Comte Harebourg.');
INSERT INTO `npc_questions` VALUES (7755, '', '', '', '', 'Quand je pense ? l\\\'invention du Comte qui devait nous faire profiter de cycles de cultures plus longs en permettant aux cultures de survivre ? cet hiver tr?s court mais rigoureux... l\\\'hiver s\\\'est install? pour de bon et nos cultures abondantes ne sont qu\\\'un lointain souvenir. \\nVous avez mes Graines de Lentille ? Merci, en les croisant avec d\\\'autres c?r?ales nous devrions obtenir de nouvelles esp?ces plus r?sistantes.');
INSERT INTO `npc_questions` VALUES (7756, '', '', '', '', 'J\\\'ai remarqu? une chose tr?s ?trange. Beaucoup de continentaux semblent souffrir d\\\'astrubisme. Une catastrophe se serait-elle produite en Amakna ? \\nOh, je vois que vous m\\\'avez apport?e de nombreux grains de sel. Je vais de suite les faire transf?rer dans une serre sp?ciale, car ils supportent tr?s mal l\\\'humidit?. C\\\'est d\\\'ailleurs pour ?a que nous avons du mal ? les cultiver.');
INSERT INTO `npc_questions` VALUES (7757, '', '', '', '', 'Vous avez r?ussi ? \\nSi nos croisements rencontrent le succ?s, lorsque le Comte Harebourg aura ?t? puni et la mal?diction de la glaciation lev?e, nous n\\\'aurons plus ? nous tracasser des d?sagr?ments subis par nos cultures, qui seront de l\\\'histoire ancienne. \\nCa nous permettra en plus de diminuer les co?ts en main d\\\'oeuvre et nous n\\\'aurons pas ? r?employer ces imb?ciles du village enseveli, s\\\'ils sont encore vivants...');
INSERT INTO `npc_questions` VALUES (7758, '', '', '', '', 'Dommage que le Comte Harebourg ne soit pas comme vous. J\\\'entends par l? que nous pouvons compter sur vous et que vous ne nous l?chez pas au profit de votre ambition personnelle. \\nJe ne comprends pas les gens qui d?fendent le Comte Harebourg. Notre maire a bien fait d\\\'interdire tout contact avec ces fous. \\nQuoiqu\\\'il en soit, avec toutes les graines que vous nous avez apport?es, nous allons pouvoir faire de nombreuses exp?riences et de multiples croisements. A terme, nous aurons les c?r?ales les plus r?sistantes et les plus productives au monde. Il ne nous restera plus qu\\\'? nous d?barrasser du Comte Harebourg et de l\\\'hiver pour reprendre notre place de premi?re puissance agricole et tout ?a, gr?ce ? vous.');
INSERT INTO `npc_questions` VALUES (7759, '', '', '', '', 'Autrefois, l\\\'agriculture ?tait florissante car le sol de l\\\'?le, compos? de poussi?re volcanique, est tr?s riche en min?raux. \\nLe seul obstacle ?tait l\\\'hiver, tr?s court mais incroyablement intense. Tellement intense qu\\\'il brisait le cycle de toutes les cultures et nous obligeait ? ne semer, faire pousser et r?colter les cultures uniquement pendant les p?riodes temp?r?es. Toutes les cultures sem?es avant l\\\'hiver ?taient d?truites pendant l\\\'hiver.');
INSERT INTO `npc_questions` VALUES (7760, '', '', '', '', 'Si je m\\\'attendais ? ?a ! C\\\'est rare de voir des ?mes de bonne volont? de nos jours. \\nJ\\\'ai besoin d\\\'?chantillons frais de sang de boufmouth. Allez dans les champs et pr?levez-en une demi-douzaine. \\nAttention, je veux uniquement des ?chantillons pr?lev?s sur des boufmouths adultes malades, mais pas trop vieux, ni trop jeunes.');
INSERT INTO `npc_questions` VALUES (7761, '', '', '', '', 'Merci, j\\\'esp?re que vous ne vous ?tes pas tromp? de boufmouth. \\nPendant que je les ?tudie, allez me chercher de l\\\'eau de mer isotonique mais attention, elle doit ?tre le plus pure possible. Le Capitaine Gneux est le seul ? savoir comme s\\\'en procurer, alors allez lui en demander.');
INSERT INTO `npc_questions` VALUES (7762, '', '', '', '', 'J\\\'en ai presque plus, alors pas touche. Si tu veux mon eau de mer isotonique, va falloir me donner quelque chose en ?change. Je veux pas un de ces trucs de touriste, non, ce que je veux c\\\'est... de l\\\'armoise ! Ca a compl?tement disparu de Frigost mais j\\\'ai entendu dire qu\\\'Eric Azaraille en avait encore en stock. Tu m\\\'en apportes et je te donne ton eau, et je m\\\'en fiche que ce soit pour lutter contre le rube ou te nettoyer le nez.');
INSERT INTO `npc_questions` VALUES (7763, '', '', '', '', 'De l\\\'armoise ? Qui vous a dit que... c\\\'est le Capitaine Gneux, c\\\'est ?a ? \\nCet ivrogne s\\\'est moqu? de moi lors du concours d\\\'inventions agricoles et tu voudrais que je lui pardonne comme ?a ? C\\\'est hors de question ! \\nQu\\\'il continue de sculpter de la glace et se noie dans sa boisson, c\\\'est tout ce qu\\\'il m?rite.');
INSERT INTO `npc_questions` VALUES (7764, '', '', '', '', 'Je ne suis pas ? vendre. Dites ? cet ivrogne que s\\\'il veut mon armoise, il devra d\\\'abord venir me pr?senter ses excuses en personne.');
INSERT INTO `npc_questions` VALUES (7765, '', '', '', '', 'Quoi ? Il veut que je lui pr?sente mes excuses parce que je lui ai demand? si son invention revenait ? utiliser du fumier ? Il me prend pour un plouc ?');
INSERT INTO `npc_questions` VALUES (7766, '', '', '', '', 'J\\\'ai bien compris ton probl?me, je suis pas idiot. Je refuse d\\\'aller me ridiculiser devant cet Eniripsa susceptible, et rien ni personne me fera changer d\\\'avis.');
INSERT INTO `npc_questions` VALUES (7767, '', '', '', '', 'Et qu\\\'est-ce que je ferai avec tout cet argent, tu peux me le dire ? J\\\'ai de la boisson fra?che ? volont? ici, et ?a me co?te rien.');
INSERT INTO `npc_questions` VALUES (7768, '', '', '', '', 'T\\\'as vu sa t?te ? Plut?t embrasser un boufmouth !');
INSERT INTO `npc_questions` VALUES (7769, '', '', '', '', 'Tu poss?des rien qui m\\\'int?resse. J\\\'ai toute la boisson que je veux ici, et c\\\'est pas les gla?ons qui manquent.');
INSERT INTO `npc_questions` VALUES (7770, '', '', '', '', 'C\\\'est une blague ? \\nMmmhh, quand es-tu libre ?');
INSERT INTO `npc_questions` VALUES (7771, '', '', '', '', 'Ca tombe bien, moi aussi. Rendez-vous ? la taverne ? cette tranche horaire, et t\\\'as pas int?r?t ? me faire faux bond.');
INSERT INTO `npc_questions` VALUES (7772, '', '', '', '', 'DIALOGUE TAVERNE QU?TE. Crit?re : pr?sent sur la carte de la taverne + ((PO=X et SH=X)|(PO=Y et SH=Y)|(etc)) \\n((PO=11205&SH>0&SH<4)|(PO=11206&SH>3&SH<7)|(PO=11207&SH>6&SH<10)|(PO=11208&SH>9&SH<13)|(PO=11209&SH>12&SH<16)|(PO=11210&SH>15&SH<19)|(PO=11211&SH>18&SH<22)|(PO=11212&(SH>21|SH<1))) \\nJe pensais pas que t\\\'allais venir. Prends une chaise et assieds-toi. \\nTu veux quelque chose ? boire ? Fais pas cette t?te, c\\\'est moi qui offre.');
INSERT INTO `npc_questions` VALUES (7773, '', '', '', '', 'Faut pas ?tre timide comme ?a tu sais. \\nAlors, qu\\\'est-ce que tu racontes de beau ? Attends, tu vas pas parler le gosier sec. \\nTavernier, deux autres chopes !');
INSERT INTO `npc_questions` VALUES (7774, '', '', '', '', 'Tu vois, t\\\'en as des choses ? raconter. Aller, bois encore un petit coup pour te r?chauffer.');
INSERT INTO `npc_questions` VALUES (7775, '', '', '', '', 'Crit?re : carte int?rieur chez capitaigne gneux et sexe masculin. \\nJ\\\'ai un de ces mal de cr?ne... Passe-moi la bouteille, c\\\'est le meilleur moyen pour lutter contre la gueule de bois. \\nFais pas cette t?te, j\\\'irai voir Eric Azaraille pour qu\\\'il m\\\'excuse, ta prestation m\\\'a convaincu. \\nAlors, heureux ?');
INSERT INTO `npc_questions` VALUES (7776, '', '', '', '', 'Crit?re : carte int?rieur chez capitaigne gneux et sexe f?minin. \\nJ\\\'ai un de ces mal de cr?ne... Passe-moi la bouteille, c\\\'est le meilleur moyen pour lutter contre la gueule de bois. \\nFais pas cette t?te, j\\\'irai voir Eric Azaraille pour qu\\\'il m\\\'excuse, ta prestation m\\\'a convaincu. \\nAlors, heureuse ?');
INSERT INTO `npc_questions` VALUES (7777, '', '', '', '', 'J\\\'ignore comment vous vous y ?tes pris, mais le Capitaine Gneux est venu me pr?senter ses excuses. J\\\'?tais tellement abasourdi que j\\\'ai oubli? de lui donner l\\\'armoise, et il est parti en oubliant de la prendre. \\nTenez, apportez-lui ?a. Je suis un homme de parole, pas comme ce maudit Comte Harebourg.');
INSERT INTO `npc_questions` VALUES (7778, '', '', '', '', 'Oh, je l\\\'avais oubli?e celle-l?. \\nJe vais te chercher un seau d\\\'eau. D?p?che-toi de la ramener au m?decin avant qu\\\'elle g?le, ?a fait m?me pas de bons gla?ons pour rafra?chir la boisson.');
INSERT INTO `npc_questions` VALUES (7779, '', '', '', '', 'Vous en avez mis du temps... Remarquez, ?a m\\\'a permis de bien avancer dans mes recherches. Je vais vous demander un dernier service, mais ?a risque d\\\'?tre dangereux. \\nJe viens d\\\'inoculer un vaccin exp?rimental ? un cobaye que je garde ? la cave, mais il ne me laisse plus l\\\'approcher. Or, j\\\'ai besoin d\\\'un ?chantillon de son sang pour examiner l\\\'action du vaccin. Vous pouvez vous en chargez ? \\nIl a cass? le m?canisme d\\\'ouverture alors vous aurez besoin d\\\'aide pour l\\\'atteindre.');
INSERT INTO `npc_questions` VALUES (7780, '', '', '', '', 'Montrez-moi ?a, vite. \\nVoyons, ?a c\\\'est bon... L? ?a a bien r?agit... Pas de trace du virus, pas de mutation non plus... Mmh, il reste quelques r?sidus ici, ?a risque de poser probl?me. \\nEcoutez, nous sommes sur la bonne voie. A priori, le vaccin fonctionne, mais je crains qu\\\'il ne soit pas efficace plus d\\\'une semaine. Je pourrai vous vacciner r?guli?rement si vous m\\\'apporter un ?chantillon de sang de boufmouth. \\nIl ne me reste qu\\\'? trouver un moyen d\\\'allonger les effets du vaccin et, contrairement au Comte, ce probl?me de rube ne sera plus qu\\\'un mauvais souvenir.');
INSERT INTO `npc_questions` VALUES (7781, '', '', '', '', 'Il me faut un ?chantillon de sang de boufmouth pour cr?er de nouvelles doses de vaccin.');
INSERT INTO `npc_questions` VALUES (7782, '', '', '', '', 'Depuis un peu moins d\\\'une d?cennie, les tiques sont sorties de leur l?thargie. Elles ont ?lus domicile sur mes veaux, ? l\\\'abri du froid, prot?g?es par l\\\'?paisse laine de leur h?te. Je les soup?onne d\\\'?tre porteuses d\\\'un agent pathog?ne qui rend mes veaux d?ments et agressifs.');
INSERT INTO `npc_questions` VALUES (7783, '', '', '', '', 'Mes amis et moi, nous avons bien tent? de nous d?barrasser des tiques en tondant les veaux parasit?s. H?las, la plupart d\\\'entre eux ont succomb? au rube dans les semaines qui ont suivi. \\nLe renouement du contact avec le continent arrive au bon moment, car nous allons pouvoir demander l\\\'aide de sp?cialistes. Tu veux bien nous aider ?');
INSERT INTO `npc_questions` VALUES (7784, '', '', '', '', 'Tu vas rendre visite ? Oshima et lui expliquer notre probl?me. Ce sp?cialiste des animaux trouvera s?rement une solution... Quoi, pourquoi tu me regardes comme ?a ?');
INSERT INTO `npc_questions` VALUES (7785, '', '', '', '', 'Comment ? J\\\'avais oubli? que le temps continue de s\\\'?couler en dehors de l\\\'?le. Et bien dans ce cas, va voir son rempla?ant.');
INSERT INTO `npc_questions` VALUES (7786, '', '', '', '', 'Je crains que ce probl?me d?passe mon domaine de comp?tence. Je ne connais pas de rem?de miracle pour se d?barrasser des tiques et soigner les boufmouths infect?s, par contre, un vieil ami pourra peut-?tre vous aider. Il s\\\'agit de Wogew l\\\'hewmite, je vais vous indiquer o? il demeure.');
INSERT INTO `npc_questions` VALUES (7787, '', '', '', '', 'Je vois, j\\\'ai une id?e mais il me faut des sp?cimens vivants de tiques et des ?chantillons de sang. \\nAppowte-moi une dizaine de tiques et un ?chantillon de sang de chaque type de boufmouth pouw que je puisse les ?tudiew.');
INSERT INTO `npc_questions` VALUES (7788, '', '', '', '', 'Je vais examinew ?a tout de suite. \\n... \\n........................ \\nC\\\'est stup?fiant ! Les sp?cimens que tu m\\\'as appowt?s wessemblentaux tiques sovih?es que j\\\'ai d?couvewt il y a plusieuws ann?es suw l\\\'?le des wabbits. Se pouwwait-il qu\\\'il s\\\'agisse d\\\'une esp?ce commune ayant ?volu? diff?wemment en fonction du climat ? Si tel est le cas, ?a pouwwait expliquew l\\\'agwessivit? des wabbits. \\nJ\\\'ai besoin d\\\'en avoiw le coeuw net ! Tu vas demandew ? l\\\'alchimiste Otoma? d\\\'analysew l\\\'agent pathog?ne twansmis paw les tiques fwain?es. Tu lui wemettwas cette enveloppe, elle contient mes conclusions et intewwogations. Va le voiw et weviens m\\\'appowtew sa w?ponse.');
INSERT INTO `npc_questions` VALUES (7789, '', '', '', '', 'C\\\'est pour moi ? \\nInt?ressant, tr?s int?ressant. Un joli exemple d\\\'?volution et d\\\'adaptation ? un environnement hostile. \\nVa dire ? Wogew l\\\'hewmite que je vais ?tudier ?a de plus pr?s et que je le tiendrai au courant de l\\\'avanc?e de mes recherches.');
INSERT INTO `npc_questions` VALUES (7790, '', '', '', '', 'Mewci d\\\'?twe wevenu. Je suis pewsuad? qu\\\'en twavaillant de concewt avec l\\\'un des plus gwands alchimistes, nous obtiendwons des w?sultats suwpwenants. \\nD?p?che-toi de pw?veniw ton ami que la solution ? ses pwobl?mes de tiques n\\\'est plus qu\\\'une question de temps.');
INSERT INTO `npc_questions` VALUES (7791, '', '', '', '', 'Vous dites qu\\\'ils vont m\\\'aider ? La derni?re fois que quelqu\\\'un a promis de nous aider, un hiver ?ternel s\\\'est abattu sur Frigost. Les champs autrefois remplis de c?r?ales et d\\\'agriculteurs sont aujourd\\\'hui laiss?s ? l\\\'abandon, et mes pauvres veaux n\\\'ont presque plus rien ? se mettre sous la dent. \\nBah, nous verrons bien si ces chercheurs tiennent leur engagement.');
INSERT INTO `npc_questions` VALUES (7792, '', '', '', '', 'Je commence vraiment ? m\\\'inqui?ter. Ma patronne, Valy Domidat, est partie r?parer le syst?me de tuyauterie qui chauffe l\\\'atelier des paysans dans les champs de glace. Au pire des cas, si le probl?me est vraiment important, elle rentre avant la tomb?e de la nuit et nous pr?parons ensemble le n?cessaire pour les travaux, mais l?, elle est absente depuis plusieurs jours et personne ne l\\\'a vue. \\nTu peux essayer de la retrouver s\\\'il-te-pla?t ? Tout le monde a besoin d\\\'elle ici.');
INSERT INTO `npc_questions` VALUES (7793, '', '', '', '', 'Alors, tu as retrouv? Valy ? Dis-moi qu\\\'elle va bien.');
INSERT INTO `npc_questions` VALUES (7794, '', '', '', '', 'Valy est occup?e pour l\\\'instant, repasse plus tard et profites-en pour visiter notre bourgade.');
INSERT INTO `npc_questions` VALUES (7795, '', '', '', '', 'L\\\'atelier des paysans se trouve dans les champs, ? l\\\'Est de la bourgade. Il y avait un probl?me sur la tuyauterie qui l\\\'alimente par le nord. Commence tes recherches par l');
INSERT INTO `npc_questions` VALUES (7796, '', '', '', '', 'Fait ?trange, les yeux de ce bonhomme de neige suivent vos d?placements. \\nVous ne remarquez rien d\\\'autre dans les environs, Francky sera d??u.');
INSERT INTO `npc_questions` VALUES (7797, '', '', '', '', 'Gr?ce ? toi, Valy est saine et sauve. Je ne risque pas de me retrouver au ch?mage de sit?t.');
INSERT INTO `npc_questions` VALUES (7798, '', '', '', '', 'Je ne comprends pas, elle est bien trop maline pour se faire avoir par des Boufmouths. \\nTout le monde l\\\'appr?cie ici, elle a refait la d?coration de nombreux int?rieurs suite ? la glaciation, je ne vois pas qui pourrait lui en vouloir. \\nTu n\\\'as vraiment rien remarqu? d\\\'anormal ?');
INSERT INTO `npc_questions` VALUES (7799, '', '', '', '', 'Quel rapport avec la disparition de Valy ? \\nMaintenant que j\\\'y pense, il y a eu cette ?trang?re qui est pass?e ? l\\\'atelier l\\\'autre soir, juste avant la fermeture. Je l\\\'ai entendue discuter avec Valy et elles se sont disput?es. C\\\'?tait la premi?re fois en un si?cle que j\\\'entendais Valy se disputer avec quelqu\\\'un. Valy est ensuite revenue et m\\\'a pr?venu qu\\\'elle irait r?parer la tuyauterie de l\\\'atelier des paysans ? l\\\'aube. Elle ?tait tr?s ?nerv?e et surtout, la temp?rature avait chut? de plusieurs degr?s d\\\'un coup, comme si un second hiver s\\\'?tait abattu dans le b?timent. \\nApr?s ?a, j\\\'ai m?me d? demander ? Jean-Pierre Kofkof de venir r?chauffer le b?timent car le froid semblait s\\\'y ?tre install? pour de bon.');
INSERT INTO `npc_questions` VALUES (7800, '', '', '', '', 'Oh ?a, ce n\\\'?tait pas grand chose, mais je me demande bien comment ils ont fait pour qu\\\'il fasse plus froid ? l\\\'int?rieur qu\\\'? l\\\'ext?rieur, malgr? le chauffage. \\nSi tu as besoin d\\\'une d?monstration, je suis ton homme !');
INSERT INTO `npc_questions` VALUES (7801, '', '', '', '', 'J\\\'ai deux-trois choses ? r?gler d\\\'abord. Pars devant, je te rejoins au pied de l\\\'?olienne.');
INSERT INTO `npc_questions` VALUES (7802, '', '', '', '', 'Que veux-tu que je fasse ? \\nNe me demande pas mon avis, sinon je br?le tout.');
INSERT INTO `npc_questions` VALUES (7803, '', '', '', '', 'Pousse-toi de l?, ?a va chauffer.');
INSERT INTO `npc_questions` VALUES (7804, '', '', '', '', 'Merci, vous m\\\'avez sauv?e de ce terrible sort.');
INSERT INTO `npc_questions` VALUES (7805, '', '', '', '', 'C\\\'est cette ?trang?re. Elle est venue me voir pour me proposer de refaire la d?coration du ch?teau du Comte Harebourg, mais j\\\'ai refus?. Quand je suis venue ici pour r?parer la tuyauterie, j\\\'ai aper?u qu\\\'elle me suivait. Au moment o? j\\\'allais me retourner, j\\\'ai senti le froid me glacer le sang et je me suis retrouv?e chang?e en bonhomme de neige. \\nQui sait ce que je serais devenue si vous ne m\\\'aviez pas retrouv?e. Prenez ces quelques pi?ces en plus de ma gratitude.');
INSERT INTO `npc_questions` VALUES (7806, '', '', '', '', 'Bonjour, je vous souhaite la bienvenue dans mon atelier des bricoleurs. Cet endroit est ouvert ? tous, alors faites comme chez vous.');
INSERT INTO `npc_questions` VALUES (7807, '', '', '', '', 'Plusieurs de mes gars sont partis chercher du bois mais ils sont jamais revenus. Je crains qu\\\'ils aient ?t? attaqu?s par des cr?atures de la for?t, ou pire. \\nVous avez l\\\'air d\\\'avoir pas mal baroud?, ?a vous dirait d\\\'aller voir ce qu\\\'ils sont devenus ? Je vais vous indiquer o? je les avais envoy?s.');
INSERT INTO `npc_questions` VALUES (7808, '', '', '', '', 'Enfin quelqu\\\'un, nous sommes sauv?s ! \\nVous ne devinerez jamais ce qui nous arrive. Tandis que nous nous pr?parions ? rentrer ? la bourgade avec une bonne r?serve de bois, nous avons ?t? victime de la fatalit?. \\nNous perdons le nord et nous tournons en rond, incapables de retrouver notre chemin. O? que nous allions, nous revenons syst?matiquement ici, contre notre gr?. Mais puisque vous ?tes l?, vous allez pouvoir nous raccompagner, un par un. \\nJe ne vous ai pas dit ?  Le mal?fice est encore plus puissant lorsque nous sommes en groupe. Puisque vous ne semblez pas touch? par ce mal?fice, vous aller pouvoir nous guider. \\nCommencez par Staurme Sioux, je pr?f?re la savoir en s?curit');
INSERT INTO `npc_questions` VALUES (7809, '', '', '', '', 'Nous tournons en rond depuis des jours sans rencontrer ?me qui vive. Je suis contente que vous nous ayez trouv?s. \\nDiscuter avec Richard Rouge, il trouve toujours une solution ? nos probl?mes.');
INSERT INTO `npc_questions` VALUES (7810, '', '', '', '', 'Richard me reproche d\\\'?tre trop t?te br?l?e et me traite comme un gamin. S\\\'il croit que je ne vois pas clair dans son jeu pour se rapprocher de ma soeur... En attendant, monsieur jesaistout n\\\'a toujours pas trouv? de solution pour nous sortir de l');
INSERT INTO `npc_questions` VALUES (7811, '', '', '', '', 'Nous tournons en rond depuis des jours. Dans cette situation, je suis s?r que vous auriez paniqu?, mais pas nous. Richard va trouver comment nous sortir de l?, ce n\\\'est qu\\\'une question de temps. \\nCe qui m\\\'inqui?te plus, ce sont les cr?atures qui r?dent. Si je ne reste pas alerte, je crains qu\\\'elles s\\\'en prennent ? mes amis.');
INSERT INTO `npc_questions` VALUES (7812, '', '', '', '', 'Comment ont-ils pu se perdre ? \\nJe compte sur vous pour me ramener les autres sains et saufs.');
INSERT INTO `npc_questions` VALUES (7813, '', '', '', '', 'Staurme Sioux est arriv?e ? bon port ? Merci, me voil? rassur?. \\nPouvez-vous accompagner son fr?re Jauni maintenant ? Il s\\\'impatiente et commence ? taper sur le syst?me de Grimeb?ne, aussi je crains que ces deux-l? finissent par en venir aux mains.');
INSERT INTO `npc_questions` VALUES (7814, '', '', '', '', 'Ce Staurme Jauni commence ? me taper sur le syst?me. Si sa soeur ne m\\\'avait pas demand? de veiller sur lui, je le laisserai volontiers se faire d?vorer par les smilomouths.');
INSERT INTO `npc_questions` VALUES (7815, '', '', '', '', 'T\\\'as pas int?r?t ? avoir touch? ? ma soeur, sinon ?a va chauffer pour toi.');
INSERT INTO `npc_questions` VALUES (7816, '', '', '', '', 'Merci pour votre aide. \\nDurant votre absence, j\\\'ai tent? de convaincre Grimeb?ne de vous accompagner, mais il refuse. Cette t?te de Porkass craint que je me fasse attaquer par les cr?atures de la for?t lorsque je serais seul, et il pense s\\\'en sortir mieux que moi.');
INSERT INTO `npc_questions` VALUES (7817, '', '', '', '', 'Durant votre absence, Richard a tent? de me convaincre de vous accompagner, mais j\\\'ai refus?. S\\\'il reste seul ici, Richard risque de se faire attaquer, mais moi, j\\\'ai moins ? craindre que lui des cr?atures de la for?t. Accompagnez-le et venez me chercher ensuite.');
INSERT INTO `npc_questions` VALUES (7818, '', '', '', '', 'Sympa d\\\'?tre revenu, mais t\\\'aurais pu ?viter de ramener autant de smilomouths... \\nJ\\\'en prends une douzaine, tu t\\\'occupes des trois restants.');
INSERT INTO `npc_questions` VALUES (7819, '', '', '', '', 'Ca va, t\\\'as pas trop bobo ? \\nRentrons en ville !');
INSERT INTO `npc_questions` VALUES (7820, '', '', '', '', 'Je le vois bien qu\\\'ils sont tous sains et saufs, je ne suis pas s?nile. \\nMerci de les avoir sortis de ce sacr? p?trin. Ca fait plaisir de pouvoir ? nouveau compter sur des gens sans se faire trahir. J\\\'esp?re que vous ne deviendrez pas comme ce fichu Comte Harebourg.');
INSERT INTO `npc_questions` VALUES (7821, '', '', '', '', 'Puisque t\\\'as pas l\\\'air emball?, j\\\'ai autre chose ? te proposer. \\nNous ?tions partis, les copains et moi, chasser la mamansot cendr?e lorsque G?rard a disparu. Il s\\\'?tait arr?t? derri?re un arbre pour se vider la vessie et nous l\\\'avons jamais revu. Il ?tait l? et pouf, la seconde d\\\'apr?s il avait disparu. \\nCa te dit de partir ? sa recherche ?');
INSERT INTO `npc_questions` VALUES (7822, '', '', '', '', 'G?nial. Commence par interroger Damar, le chef des p?cheurs. Avec un peu de chance, il l\\\'aura aper?u.');
INSERT INTO `npc_questions` VALUES (7823, '', '', '', '', 'P?cher est devenu de plus en plus difficile et les foreuses qui tombent souvent en panne n\\\'arrangent rien. \\nSi nous nous acharnons, c\\\'est parce que l\\\'agriculture dans les serres ne suffit pas ? nourrir toutes les bouches et qu\\\'il faut bien changer d\\\'aliments de temps en temps pour avoir une alimentation ?quilibr?e. Manger, bouger comme le dit Albert Paisse, notre m?decin.');
INSERT INTO `npc_questions` VALUES (7824, '', '', '', '', 'Froid, moi ? Jamais ! \\nJe suis Damar, le chef des p?cheurs, du sang de mansot coule dans mes veines... ? force de trop en boire. \\nSi tu veux te rendre utile, arr?te de poser des questions idiotes.');
INSERT INTO `npc_questions` VALUES (7825, '', '', '', '', 'G?rard ? Non, ?a fait un moment que je ne l\\\'ai pas vu. S\\\'il ?tait dans les parages, je n\\\'aurais pas pu le rater, lui et ses poivrots d\\\'amis font un tel boucan qu\\\'on doit les entendre depuis le ch?teau du Comte. \\nVa plut?t emb?ter les illumin?s d\\\'? c?t? avec tes questions, ici nous avons du travail.');
INSERT INTO `npc_questions` VALUES (7826, '', '', '', '', 'Bonjour, bienvenue dans notre futur village de glace. Il ne paye pas de mine pour l\\\'instant mais vous verrez, d\\\'ici quelques ann?es ce sera l\\\'attraction touristique num?ro un.');
INSERT INTO `npc_questions` VALUES (7827, '', '', '', '', 'Cet ivrogne ne nous a pas insult? depuis un moment, je suppose donc qu\\\'il n\\\'est pas venu ici depuis un baille. \\nAu lieu de perdre votre temps ? le chercher, je vous conseille de trouver quelque chose de plus utile ? faire. Toutefois, si vous tenez vraiment ? le retrouver, allez poser la question ? Mel. Elle se charge de la s?curit? du site de p?cheurs et si quoi que ce soit d\\\'inhabituel s\\\'est produit, elle sera la premi?re au courant.');
INSERT INTO `npc_questions` VALUES (7828, '', '', '', '', 'Assurer la s?curit? des p?cheurs ?tait beaucoup plus facile autrefois. Apr?s que le crat?re se f?t rempli d\\\'eau chaude, il devint tr?s poissonneux. L\\\'activit? de p?che ?tait donc tr?s importante ici. Mais depuis qu\\\'il est gel?, cette activit? est devenue tr?s difficile. \\nAvant, il y avait juste ? craindre les cr?atures de la for?t. D?sormais, il faut repousser les assauts incessants des mansots qui volent les poissons d?congel?s.');
INSERT INTO `npc_questions` VALUES (7829, '', '', '', '', 'R?pondez franchement, vous ne cherchez pas cet ivrogne, si ? \\nIl est pass? il y a quelques jours, compl?tement ivre. Il a essay? de m\\\'approcher de trop pr?s avec ses mains baladeuses, et il a ?t? bien re?u, croyez-moi. \\nIl est reparti, pli? en deux, vers la caverne des mansots.');
INSERT INTO `npc_questions` VALUES (7830, '', '', '', '', 'Tu n\\\'as rien trouv? d\\\'autre ? \\nSacr? G?rard, on pourra dire qu\\\'il est mort comme il a v?cu, comme un gland. \\nC\\\'est pas tout mais cette histoire m\\\'a donn? faim, pas toi ?');
INSERT INTO `npc_questions` VALUES (7831, '', '', '', '', 'Bonjour, ne commencez pas ? me parler d\\\'agriculture, je ne veux plus en entendre parler. \\nJ\\\'ai investi une bonne partie de mes richesses pour acheter cette serre et en avoir l\\\'exclusivit?. \\nD?trompez-vous, je ne suis pas ?go?ste. J\\\'utilise cette serre pour d?velopper toutes sortes de plantes aux usages tr?s divers. J\\\'essaye aussi de cr?er des plantes comestibles r?sistantes au climat de Frigost pour lutter contre la famine et remplacer l\\\'agriculture. Ainsi, seuls les alchimistes pourront les cultiver et ce qui est arriv? ? cause de l\\\'agriculture et du Comte Harebourg ne se reproduira pas.');
INSERT INTO `npc_questions` VALUES (7832, '', '', '', '', 'Avant la glaciation, je d?coupais du bois. Maintenant, je continue mais je coupe aussi les animaux, comme ?a, je prot?ge les autres b?cherons et mon ami Al Shab est content.');
INSERT INTO `npc_questions` VALUES (7833, '', '', '', '', 'Tu vois tous ces troncs ? Il faut les apporter au Chef Rhont? qui en a besoin pour alimenter le chauffage du syst?me de tuyauterie et garder le port d?gel?. \\nSi tu veux, tu peux t\\\'en occuper.');
INSERT INTO `npc_questions` VALUES (7834, '', '', '', '', 'Bonjour, derri?re moi se trouve un endroit aussi froid que le coeur de Jiva et aussi tranchant que la lame de l\\\'?p?e de Iop. \\nEntres-y ? tes risques et p?rils.');
INSERT INTO `npc_questions` VALUES (7835, '', '', '', '', 'Nous creusons cette carri?re pour extraire des poissons et un tas d\\\'autres ressources bloqu?es dans la glace. \\nCertains pr?tendent que nous voulons surtout r?cup?rer les richesses de l\\\'ancien village pi?g?es dans la glace, mais ces accusations sont infond?es. \\nSi tu descends, tu trouveras au fond du tunnel l\\\'entr?e du repaire des mansots. \\nVeux-tu descendre dans le repaire des mansots ?');
INSERT INTO `npc_questions` VALUES (7836, '', '', '', '', 'Veux-tu remonter ?');
INSERT INTO `npc_questions` VALUES (7837, '', '', '', '', 'Regardes-moi ?a, tu es tremp? jusqu\\\'aux os. Si tu sors dans cet ?tat, tu vas attraper la mort. \\nUtilises donc cette serviette pour te s?cher un minimum... C\\\'est mieux ainsi, je vais pouvoir te laisser sortir.');
INSERT INTO `npc_questions` VALUES (7838, '', '', '', '', 'C\\\'est Bambelle qui vous envoie ? \\nAh non, c\\\'est Gormor. Pas grave, c\\\'est la m?me chose. Vous le remercierez de ma part, et dites-lui qu\\\'il m\\\'en faut plus.');
INSERT INTO `npc_questions` VALUES (7839, '', '', '', '', 'Prends ceux-l? et fais attention. Des cr?atures sauvages r?dent dans les environs.');
INSERT INTO `npc_questions` VALUES (7840, '', '', '', '', 'Il n\\\'y en a plus assez, faudra repasser demain.');
INSERT INTO `npc_questions` VALUES (7841, '', '', '', '', 'Gr?ce ? nos efforts, la voie marine vers Amakna a ?t? r?ouverte. C\\\'est une belle r?ussite. \\nEn continuant comme ?a, nous devrions r?ussir ? d?geler compl?tement le port et lui redonner un peu de son aspect d\\\'antan.');
INSERT INTO `npc_questions` VALUES (7842, '', '', '', '', 'Autrefois, nous utilisions ce port pour exporter d\\\'importantes quantit?s de ressources agricoles. Il y avait des bateaux partout et les gens s\\\'affairaient sans cesse sur les quais, ?a fourmillait de partout. \\nA pr?sent, les quais sont d?serts et les bateaux prisonniers de la glace.');
INSERT INTO `npc_questions` VALUES (7843, '', '', '', '', 'Je me suis form? une silhouette d\\\'athl?te en embarquant des tonnes et des tonnes de tonneaux de c?r?ales. Comme aujourd\\\'hui nous n\\\'exportons plus rien, je me suis reconverti dans le transport de mat?riaux lourds, surtout les planches et le m?tal qui servent ? la tuyauterie.');
INSERT INTO `npc_questions` VALUES (7844, '', '', '', '', 'Frigost traverse une mauvaise passe et notre maire fait tout pour que nous nous en sortions. \\nAllez lui rendre visite pour vous rendre compte par vous-m?me de sa motivation.');
INSERT INTO `npc_questions` VALUES (7845, '', '', '', '', 'Ca serait pas de refus. Les foreuses et les lignes de p?che nous posent beaucoup de soucis, elles s\\\'ab?ment beaucoup plus vite que nous ne pouvons les r?parer. \\nSi tu te sens d\\\'attaque, j\\\'ai besoin de 5 Bois de Tremble pour r?parer les foreuses. Il me faut aussi 50 Laines de Boufmouth, 30 Laines de Boufmouth l?gendaire et 5 Laines du Royalmouth pour confectionner des cordes et r?parer les lignes de p?che, plus 5 D?fenses de Sanglacier et 5 Dents de Smilomouth pour les hame?ons. \\nPour information, les chaudi?res de nos foreuses fonctionnent ? la graisse de mansot et pas au bois. Les arbres sont des denr?es trop rares pour ?tre gaspill?es, par contre, les mansots sont assez nombreux pour ?tre d?cim?s sans remord. Donc apporte-moi 100 Graisses de mansot pour servir de combustible.');
INSERT INTO `npc_questions` VALUES (7846, '', '', '', '', 'Tu as ?t? rapide, pour un touriste. Je te remercie, gr?ce ? toi nous allons bient?t pouvoir reprendre une activit? normale. \\nPlusieurs p?cheurs m\\\'ont signal? qu\\\'il manque des pi?ces qui ne peuvent ?tre fabriqu?es qu\\\'en ville. \\nVa voir Valy Domidat, la bricoleuse de Frigost, et donne-lui cette liste.');
INSERT INTO `npc_questions` VALUES (7847, '', '', '', '', 'Damar r?clame mon aide ? Il se moque de moi ! \\nR?pondez-lui que j\\\'attends toujours l\\\'alliance qu\\\'il m\\\'a promise il y a trente ans, par cons?quent, il devra patienter pour ses pi?ces d\\\'?quipement.');
INSERT INTO `npc_questions` VALUES (7848, '', '', '', '', 'Arf, elle m\\\'en veut toujours pour ?a... Ce n\\\'est pas ma faute si j\\\'ai perdu cette alliance en chassant le Mansot Royal. Tu veux bien aller la r?cup?rer pour moi et l\\\'apporter ? Valy avec toutes mes excuses ?');
INSERT INTO `npc_questions` VALUES (7849, '', '', '', '', 'Il s\\\'est finalement d?cid?. J\\\'aurai pr?f?r? qu\\\'il vienne lui-m?me, mais il avait sans doute peur de ma r?action. \\nPour la peine, je vais le faire patienter encore un peu, apr?s trente ans d\\\'attente, je lui dois bien ?a, pas vrai ?');
INSERT INTO `npc_questions` VALUES (7850, '', '', '', '', 'Elle me demande d\\\'attendre ? Elle veut vraiment me faire devenir Iop ou quoi ? \\nAh, tu trouves ?a dr?le ? Prends ?a et va voir ailleurs si j\\\'y suis.');
INSERT INTO `npc_questions` VALUES (7851, '', '', '', '', 'Les p?cheurs pr?tendent que les mansots, m?contents de l\\\'extermination dont ils sont victimes depuis l\\\'arriv?e des continentaux et de l\\\'affront fait ? leur roi, on mont? une exp?dition punitive. \\nAu d?but, je ne les ai pas crus bien s?r, jusqu\\\'? ce que l\\\'exp?dition en question soit visible. \\nPr?parez-vous au combat et venez m\\\'aider ? les repousser.');
INSERT INTO `npc_questions` VALUES (7852, '', '', '', '', 'Je n\\\'ai pas le temps de discuter, une nouvelle vague de mansots arrivent. Soignez-vous et pr?parez-vous au combat.');
INSERT INTO `npc_questions` VALUES (7853, '', '', '', '', 'Les mansots ont ?t? repouss?s et les d?g?ts sont minimes. Quelques p?cheurs sont tomb?s de la falaise pendant les combats mais les pertes humaines sont inf?rieures ? 7%, ce qui est tol?rable. \\nLes mansots devraient nous laisser tranquille un moment, je pense que Damar va en profiter pour rouvrir les lignes de ravitaillement jusqu\\\'? Frigost. Allez donc le voir.');
INSERT INTO `npc_questions` VALUES (7854, '', '', '', '', 'Heureusement, nous pouvons compter sur Mel pour la s?curit? du site. Toute petite d?j?, elle s\\\'amusait ? combattre la rocaille ? l\\\'aide d\\\'une b?che. \\nPuisque la menace mansot est ?cart?e pour l\\\'instant, nous allons pouvoir ravitailler nos concitoyens sans risque. \\nVa voir Ordralfab?tist et dis-lui que la distribution de poisskaille peut reprendre.');
INSERT INTO `npc_questions` VALUES (7855, '', '', '', '', 'Excellente nouvelle. T\\\'as rien ? faire je suppose, donc tu vas livrer mon poisskaille. Faut l\\\'apporter ? Aurore Bor?ale, au nord du lac, ? Bambelle, qui tient la scierie au sud, et Clarisse Tosha, la poissonni?re de la bourgade. \\nJe te passe un mansob?se sp?cialement dress? pour le transport de poisskaille. Je le gave de la quantit? de poisskaille voulue et, arriv? ? destination,  il r?gurgite la livraison intacte. J\\\'admets que c\\\'est pas encore totalement au point car son syst?me digestif s\\\'active trente minutes apr?s le gavage, donc t\\\'as int?r?t ? te d?p?cher.');
INSERT INTO `npc_questions` VALUES (7856, '', '', '', '', 'C\\\'est Ordralfab?tist qui nous envoie ?a ? Je croyais que ce gros balourd nous d?testait. Il est peut-?tre moins born? que je le pensais. \\nRemerciez-le de ma part.');
INSERT INTO `npc_questions` VALUES (7857, '', '', '', '', 'Beurk, c\\\'est r?pugnant. Ces poisskailles sont pr?-dig?r?s, hors de question que nous avalions ?a.');
INSERT INTO `npc_questions` VALUES (7858, '', '', '', '', 'Je te rappelle que la digestion de ce mansob?se commence au bout de trente minutes, tu dois donc avoir fini de livrer le poisskaille avant.');
INSERT INTO `npc_questions` VALUES (7860, '', '', '', '', 'Nous n\\\'avons pas mang? de poisskaille depuis longtemps, ?a va nous changer des croquettes de Kaniglou. \\nMerci ? vous et aux p?cheurs.');
INSERT INTO `npc_questions` VALUES (7861, '', '', '', '', 'Vous ?tes s?r que ce poisskaille est frais ? J\\\'ai plut?t l\\\'impression qu\\\'il a tremp? dans du suc gastrique...');
INSERT INTO `npc_questions` VALUES (7862, '', '', '', '', 'Du poisskaille bien frais et juteux, les clients vont adorer. Ca devrait remonter le moral de l\\\'?pouse de Truffo. \\nFigure-toi qu\\\'elle entretenait un petit jardin secret avec beaucoup de gazon dans l\\\'une des serres, mais que le Royalmouth a tout brout?. Depuis, elle d?prime et Truffo veut la peau de cette b?te.');
INSERT INTO `npc_questions` VALUES (7863, '', '', '', '', 'Euh... c\\\'est vraiment du poisskaille ? Ca ressemble plut?t ? la bouillie servie par Walter Aygo. Tu t\\\'es tromp? de livraison.');
INSERT INTO `npc_questions` VALUES (7864, '', '', '', '', 'T\\\'as bien travaill?, je m\\\'en souviendrai pour les prochaines livraisons. \\nGr?ce ? ton aide et si le dieu Enutrof est avec nous, nous arriverons ? p?cher suffisamment de poissons pour subvenir ? nos besoins.');
INSERT INTO `npc_questions` VALUES (7865, '', '', '', '', 'Nous allons r?habiliter une partie du village recouvert de glace et creuser de nouvelles maisons dans la glace m?me. Nous projetons m?me de cr?er un gigantesque h?tel enti?rement creus? et sculpt? dans la glace. C\\\'est un long projet mais nous sommes bien d?cid?s ? le mener ? terme. \\nJ\\\'ai d?j? rachet? une foreuse aux p?cheurs que notre bricoleur Mac Givr? est en train de retaper. Malheureusement, nous souffrons de la p?nurie de mati?res premi?res et nos outils sont vieux et us?s, ce qui ralenti consid?rablement l\\\'avanc?e du projet. Mais ne vous inqui?tez pas, nous ne baissons pas les bras pour autant.');
INSERT INTO `npc_questions` VALUES (7866, '', '', '', '', 'Nous manquons surtout de bois. Le tremble est bien adapt? au climat de Frigost et fait couleur locale. J\\\'ai toutefois entendu parler d\\\'un bois exotique qui diffuse une odeur agr?able et apaisante, ?a s\\\'appelle du kaliptus. Je pense qu\\\'en combinant ces deux bois, nous obtiendrons des maisons au cachet unique. \\nPourriez-vous m\\\'en procurer ? Je me doute que vous ne pourrez pas transporter tout ce dont nous avons besoin, c\\\'est pourquoi je vous demande juste 5 Bois de Tremble et une Planche en Bois de Kaliptus.');
INSERT INTO `npc_questions` VALUES (7867, '', '', '', '', 'Oh, je ne pensais pas que vous le feriez, vous ?tes vraiment quelqu\\\'un de serviable, merci. Il faudrait plus de gens comme vous ici. Pour la peine, je vous ferai une r?duction lorsque vous viendrez en vacances dans notre futur h?tel.');
INSERT INTO `npc_questions` VALUES (7868, '', '', '', '', 'C\\\'est harassant de passer ses journ?es dans le froid ? creuser la glace ou attendre qu\\\'un poisson pointe le bout de son nez. Ca n\\\'a plus rien ? voir avec la bonne ?poque o? l\\\'eau ?tait ti?de et les poissons grouillants.');
INSERT INTO `npc_questions` VALUES (7869, '', '', '', '', 'Un jour, quand je serai grande, je serai une princesse... C\\\'est ce que mon p?re me r?p?tait avant la glaciation. Depuis, il est mort et je n\\\'ai toujours pas grandi. En plus, mon copain Knil m\\\'a abandonn?e pour rejoindre Anope, qu\\\'il trouve plus jolie, et il a perdu ma peluche F?ca. Je le d?teste encore plus que le Comte !');
INSERT INTO `npc_questions` VALUES (7870, '', '', '', '', 'Vous l\\\'avez retrouv?e ? \\nMerci, merci, merci ! Comme vous ?tes tr?s gentil, prenez ce Kama de glace, je n\\\'en ai pas besoin.');
INSERT INTO `npc_questions` VALUES (7871, '', '', '', '', 'Merci d\\\'avoir retrouv? ma peluche. Anope est jalouse et reproche ? Knil de ne pas lui en avoir offert une. C\\\'est bien fait pour eux !');
INSERT INTO `npc_questions` VALUES (7872, '', '', '', '', 'Bonjour, j\\\'assiste Aurore Bor?ale dans sa cr?ation d\\\'un village dans la glace. Je suis en quelque sorte le directeur technique du projet. \\nL?, je suis en train d\\\'adapter une foreuse ? nos besoins mais je dois en m?me temps g?rer plein d\\\'autres bricoles. C\\\'est s?r, c\\\'est pas comme si je disposais de la m?me main d\\\'oeuvre que le Comte et que le temps ?tait cl?ment, mais je vais m\\\'en sortir. \\nDis, t\\\'aurais de la gomme ? m?cher par hasard ?');
INSERT INTO `npc_questions` VALUES (7873, '', '', '', '', 'G?nial, ?a va r?soudre pas mal de soucis. Sais-tu que, coupl?e ? d\\\'autres objets, cette gomme ? m?cher peux servir ? fabriquer un propulseur des neiges, une bo?te de direction pour foreuse ou encore r?parer le thermostat du syst?me de tuyauterie ? \\nPrends ce Kama des glaces, et si tu trouves d\\\'autres gommes ? m?cher, apportes-les moi imm?diatement, d\\\'accord ?');
INSERT INTO `npc_questions` VALUES (7874, '', '', '', '', 'J\\\'ai besoin d\\\'une grande vari?t? de plantes pour faire de multiples croisements et obtenir de nouvelles esp?ces plus r?sistantes et multifonctions. \\nPlusieurs boufmouths ont saccag? ma serre et ont des Yuccas L?l?s dans leurs poils. Id?alement, il faudrait que 55 de ces plantes aient surv?cu. \\nIl me faut aussi une dizaine de Tulipes Ossucions qui poussent dans les champs et deux Perce-Neige.');
INSERT INTO `npc_questions` VALUES (7875, '', '', '', '', 'Je suis content d\\\'avoir trouv? quelqu\\\'un de confiance. J\\\'esp?re que vous n\\\'avez pas l\\\'intention de retourner votre veste. Quoiqu\\\'il en soit, merci. \\nNe partez pas trop loin car je ferai encore appel ? vos services prochainement.');
INSERT INTO `npc_questions` VALUES (7876, '', '', '', '', 'La richesse du sol a permis une agriculture tr?s intensive mais aujourd\\\'hui, il ne reste que des vestiges. L\\\'hiver a gel? la terre et tu? les jeunes pousses, la neige recouvrant peu ? peu les v?g?taux qui essayaient de survivre. \\nDans la for?t des pins perdus poussaient autrefois des Mimes Osamodas, mais ces fleurs abondantes ont pratiquement toutes disparues aujourd\\\'hui. J\\\'ai n?anmoins besoin d\\\'en trouver une dizaine pour certains croisements de plantes. Pouvez-vous vous en charger, et par la m?me occasion m\\\'apporter une soixantaine de Roses Nelson ? Vous en trouverez dans les lieux de vie des cr?atures de la for?t.');
INSERT INTO `npc_questions` VALUES (7877, '', '', '', '', 'Je savais que des Mimes Osamodas avaient surv?cu. Merci pour votre aide. \\nSi j\\\'arrive ? mener mes exp?riences ? leur terme, nous pourrons nous passer des c?r?ales et la famine ne sera plus qu\\\'un mauvais souvenir.');
INSERT INTO `npc_questions` VALUES (7878, '', '', '', '', 'Je viens de comprendre une chose si je veux supplanter l\\\'agriculture : je dois rendre la consommation de plantes plus attrayantes que la consommation de c?r?ales. \\nLes biscuits sont ? base de c?r?ales, mais combien en existe-t-il ? base de plantes ? Je songe s?rieusement ? utiliser de la rhubarbe ? papa pour charmer le palais des consommateurs. Il s\\\'agit d\\\'une plante qui ne pousse que dans des grottes de glace souterraines qui nous sont inaccessibles. Cependant, les mansots en transportent souvent, c\\\'est donc l\\\'occasion de s\\\'en procurer. \\nPouvez-vous aller au lac gel? et convaincre les mansots de me c?der 65 Rhubarbes ? papa ?');
INSERT INTO `npc_questions` VALUES (7879, '', '', '', '', 'Vous ?tes dou? pour la n?gociation, ?a ne fait aucun doute. Le Comte Harebourg l\\\'?tait ?galement, ce qui lui valu de gagner le concours d\\\'invention agricole en proposant une machine r?volutionnaire : un extracteur g?othermique g?ant calibr? sur les saisons qui permettait de r?chauffer les cultures gr?ce ? la vapeur lors des saisons froides. C\\\'est d\\\'ailleurs un d?riv? de ce syst?me qui est actuellement utilis? dans nos serres.');
INSERT INTO `npc_questions` VALUES (7880, '', '', '', '', 'Beaucoup de gens abandonnent leurs familiers ou leurs animaux de compagnie. A Frigost, depuis l\\\'hiver, c\\\'est devenu beaucoup plus rares car les animaux ne survivent pas plus que quelques jours. \\nLorsque le village de glace sera termin?, j\\\'am?nagerai un chanil pour accueillir toutes ces pauvres b?tes.');
INSERT INTO `npc_questions` VALUES (7881, '', '', '', '', 'Je m\\\'entra?ne en recueillant des timansots devenus orphelins apr?s le massacre de leur m?re par les p?cheurs et les continentaux. \\nJ\\\'en ai justement quelques-uns en trop dont je n\\\'ai plus le temps de m\\\'occuper et qui risquent de s\\\'enfuir. Je peux vous en c?der un contre un poisskaille.');
INSERT INTO `npc_questions` VALUES (7882, '', '', '', '', 'Frigost regorge d\\\'artisans de talent mais ce qui nous manque le plus, ce sont les outils. Mac Givr? m\\\'a fait part d\\\'un projet de chalumeaux ? vapeur, plus performants et moins ?puisants que les traditionnelles scies ? glace pour d?couper l\\\'eau gel? du lac. L\\\'inconv?nient, ce sont les mat?riaux n?cessaires ? leur fabrication. \\nJ\\\'ai sur moi des listes d\\\'outils et mat?riaux n?cessaires, pouvez-vous me les procurer ? Je vous payerai grassement en ?change.');
INSERT INTO `npc_questions` VALUES (7883, '', '', '', '', 'Je vous remercie pour votre aide et je prierai Sadida de veiller sur vous. Gr?ce ? ces outils, notre r?ve va devenir r?alit? bien plus vite. \\nMac Givr? va ?tre tout fou lorsqu\\\'il apprendra ce que vous avez fait pour nous. Vous devriez aller le voir.');
INSERT INTO `npc_questions` VALUES (7884, '', '', '', '', 'Mes bijoux de famille, vous les avez retrouv?s ! C\\\'est ma femme qui va ?tres contente dites donc. \\nPrenez cette bourse de kamas et n\\\'en parlez ? personne.');
INSERT INTO `npc_questions` VALUES (7885, '', '', '', '', 'Je peux toucher ? \\nOooh, je suis impressionn?. Je n\\\'en avais jamais vu de si gros et de si ferme. Souple et solide ? la fois, il doit fondre en bouche, j\\\'en suis tout excit?. \\nTu m\\\'as rendu service, c\\\'est pourquoi je vais demander ? mon ami de la compagnie Asfog et Fils qu\\\'il te laisse utiliser son transporteur si tu souhaites te rendre au Berceau d\\\'Alma.');
INSERT INTO `npc_questions` VALUES (7886, '', '', '', '', 'Ce qu\\\'il manque ? Frigost, c\\\'est un nouveau grand projet. Avant, l\\\'activit? de l\\\'?le tournait autour de l\\\'exportation de ressources agraires. Ce n\\\'est plus le cas depuis longtemps et nous passons notre temps ? essayer de d?geler le port, tout ?a ? cause du Comte. J\\\'ai vraiment envie de passer ? autre chose.');
INSERT INTO `npc_questions` VALUES (7887, '', '', '', '', 'Je ne m\\\'attendais pas ? ce qu\\\'un continental nous vienne en aide. \\nNous avons beaucoup de travail mais nous manquons de main-d\\\'oeuvre et de personnel qualifi?. Il faut convaincre la maire Cantile de nous laisser recruter des gens de la bourgade, tu peux t\\\'en occuper s\\\'il-te-pla?t ? Moi, j\\\'ai trop de choses ? faire ici et Aurore n\\\'est pas tr?s appr?ci?e de notre maire ? cause de ses id?es pro-hivernales.');
INSERT INTO `npc_questions` VALUES (7888, '', '', '', '', 'Au d?but, je lui en ai voulu de la destruction d\\\'autant de v?g?taux. Par la suite, j\\\'ai d?couvert le charme d\\\'une terre enneig?e et ? pr?sent, je souhaite de tout coeur que l\\\'hiver dure une ?ternit');
INSERT INTO `npc_questions` VALUES (7889, '', '', '', '', 'Aurore Bor?ale a des id?es farfelues. Notre but est de supprimer la mal?diction de l\\\'hiver ?ternel. Lorsque nous y parviendrons, son projet de village de glace tombera ? l\\\'eau. Je ne vois donc pas l\\\'int?r?t d\\\'investir du temps et des gens dans un projet vou? ? l\\\'?chec. \\nJe sais qu\\\'apr?s un si?cle de glaciation, certaines personnes ne partagent plus mon point de vue, mais si ?a leur chante de brasser du temps, grand bien leur fasse.');
INSERT INTO `npc_questions` VALUES (7890, '', '', '', '', 'Ca a l\\\'air marrant, en tout cas plus que le d?gel du port, mais j\\\'ai peur de me faire attaquer en chemin. Tu peux m\\\'accompagner, s\\\'il-te-pla?t ?');
INSERT INTO `npc_questions` VALUES (7891, '', '', '', '', 'L\\\'autre folle veut me voler mes marins et dockers pour travailler sur son projet d?ment de village de glace ? C\\\'est hors de question, je refuse que quiconque sous ma responsabilit? aille travailler l?-bas. J\\\'ai besoin de tout le monde ici, et je ne lui ob?irai pas comme un gentil chienchien sous pr?texte que mademoiselle est une aristocrate. \\nC\\\'est assez clair pour toi ?');
INSERT INTO `npc_questions` VALUES (7892, '', '', '', '', 'Tu me prends pour qui ? Je ne suis pas un p?le pour l\\\'emploi. Quoique... \\nEcoute, je veux bien parler du besoin de main-d\\\'oeuvre pour la r?alisation d\\\'un village taill? dans la glace, mais en ?change, tu dois me promettre de me rendre un service. Qu\\\'en dis-tu ?');
INSERT INTO `npc_questions` VALUES (7893, '', '', '', '', 'Merci, je ne peux pas t\\\'en parler pour l\\\'instant, c\\\'est trop risqu?. \\nD?s que tout sera pr?t, je te ferai savoir de quel genre de service il s\\\'agit, mais en attendant, tu ne parles de ?a ? personne, compris ?');
INSERT INTO `npc_questions` VALUES (7894, '', '', '', '', 'Je dois maintenir le syst?me de tuyauterie, entretenir les chasse-neige, fabriquer de nouveaux outils, en r?sum?, je suis d?bord?e. Par contre, si vous trouvez un moyen de me faire gagner du temps, je pourrais ?ventuellement m\\\'occuper de la d?coration int?rieur des maisons de glace. Qu\\\'en pensez-vous ?');
INSERT INTO `npc_questions` VALUES (7895, '', '', '', '', 'Je travaille sur de nouveaux prototypes d\\\'objets d\\\'?levage. J\\\'ai pr?par? les plans mais je n\\\'ai pas le temps de m\\\'en occuper. Trouve un bricoleur qui puisse fabriquer ces prototypes et apporte-les moi.');
INSERT INTO `npc_questions` VALUES (7896, '', '', '', '', 'Celui qui a fabriqu? ?a s\\\'est assez bien d?brouill? et m\\\'a surtout fait gagner un temps fou. Prenez ces quelques kamas, vous les avez m?rit?s. \\nVous direz ? Mac Givr? de passer me voir ? l\\\'atelier pour discuter de ses besoins, nous pourrons aussi en profiter pour chercher des solutions au probl?me d\\\'isolation du village enseveli... Oubliez ?a, dites simplement ? Mac Givr? de venir ? l\\\'occasion.');
INSERT INTO `npc_questions` VALUES (7897, '', '', '', '', 'La r?action de notre maire ne m\\\'?tonne pas, ? nous de lui montrer qu\\\'elle a tort. Quant ? Valy Domidat, je passerai la voir lorsque j\\\'irai ? la bourgade. \\nNous avons quelques malades ici et je crains qu\\\'avec l\\\'arriv?e de nouveaux volontaires, l\\\'?pid?mie de rube se propage. \\nTrouve Albert Paisse, le m?decin de la bourgade, et demande-lui trente vaccins. Aurore le payera plus tard.');
INSERT INTO `npc_questions` VALUES (7898, '', '', '', '', 'Je n\\\'en ai pas autant, ici ce n\\\'est pas une pharmacie... Ah, c\\\'est Aurore Bor?ale qui vous envoie. Comment va-t-elle ? \\nElle a besoin de trente doses de vaccin contre le rube ? Aucun probl?me, les voici. \\nSaluez-la de ma part.');
INSERT INTO `npc_questions` VALUES (7899, '', '', '', '', 'Albert Paisse est un tr?s bon m?decin, nous avons de la chance de l\\\'avoir. Il ?tait d?j? un v?t?ran de la m?decine lorsque je travaillais sur la construction de l\\\'invention du Comte. Comme dans tout gros chantier, nous avons eu notre lot de bless?s, mais aucun ne s\\\'est jamais plaint des soins prodigu?s par Albert Paisse. \\nIl faut n?anmoins admettre que son comportement a chang? depuis la glaciation. A mon avis, il n\\\'a pas support? la mort d\\\'autant de personnes, que ce soit ? cause du froid, de la famine, des cr?atures de l\\\'?le ou autre... \\nJe vais faire distribuer ces doses de vaccin, merci pour ton aide.');
INSERT INTO `npc_questions` VALUES (7900, '', '', '', '', 'J\\\'ai ou?e dire que vous ?tiez particuli?rement dou? pour retrouver les disparus. Ca vous int?resserait de retrouver quelqu\\\'un pour moi ? \\nIl s\\\'agit de mon p?re, Lafair?. Il n\\\'a pas exactement disparu, non. En fait, il est mort il y a une cinquantaine d\\\'ann?es en essayant de rejoindre le continent par le berceau d\\\'Alma, sur la c?te nord-est de l\\\'?le. L\\\'eau l?-bas n\\\'est pas gel?e mais des courants marins propulsent les navires contre les r?cifs. \\nJe vous passe les d?tails de cette histoire ? combien passionnante, ce que je voudrais, c\\\'est que vous retrouviez son ?me. Je ne vous ai pas dis ? Ce lieu est hant? par les esprits des marins. Je vous demande donc de vous y rendre, de trouver mon p?re, et de lui demander o? il a cach? son butin, fruit d\\\'une longue vie de larcins en tous genres.');
INSERT INTO `npc_questions` VALUES (7901, '', '', '', '', 'Inutile d\\\'insister, je n\\\'ai pas envie de parler.');
INSERT INTO `npc_questions` VALUES (7903, '', '', '', '', 'Nous ne voulons plus entendre parler ni du Comte Harebourg, ni de l\\\'agriculture. \\nAurore Bor?ale souhaite profiter de la r?ouverture d\\\'une voie maritime vers le continent pour d?velopper le tourisme de l\\\'?le. Elle a d?velopp? un concept int?ressant de village de glace auquel j\\\'ai tout de suite adh?r?. Ainsi, nous pourrons tirer profit de l\\\'hiver permanent.');
INSERT INTO `npc_questions` VALUES (7904, '', '', '', '', 'Je n\\\'ai vu aucun chasseur dans le coin, c\\\'est relativement calme depuis plusieurs jours.');
INSERT INTO `npc_questions` VALUES (7905, '', '', '', '', 'Ici nous n\\\'avons rien ? craindre. Les crat?res qui forment le lac repr?sentent une part n?gligeable de l\\\'activit? g?othermique de l\\\'?le, enfin, c\\\'est ce que disent les sp?cialistes. \\nPar contre, il existe un volcan toujours en activit? au centre de l\\\'?le, mais personne ne s\\\'en approche et je vous d?conseille d\\\'y aller.');
INSERT INTO `npc_questions` VALUES (7906, '', '', '', '', 'Je n\\\'ai pas vu cet idiot depuis un moment, et c\\\'est tant mieux.');
INSERT INTO `npc_questions` VALUES (7907, '', '', '', '', 'Il en reste encore plein, tu vas pouvoir faire encore plusieurs trajets. \\nM?fie-toi quand m?me des cr?atures qui r?dent ici, plusieurs n\\\'attendent qu\\\'une occasion pour t\\\'arracher les tripes et te d?vorer.');
INSERT INTO `npc_questions` VALUES (7908, '', '', '', '', 'Gr?ce ? nos efforts, la voie barine vers Abakna a ?t? r?ouverte. C\\\'est une belle r?ussite. \\nEn continuant cobbe ?a, nous devrions r?ussir ? d?geler compl?tebent le port et lui redonner un peu de son aspect d\\\'antan.');
INSERT INTO `npc_questions` VALUES (7909, '', '', '', '', 'Je be suis forb? une silhouette d\\\'athl?te en embarquant des tonnes et des tonnes de tonneaux de c?r?ales. Cobbe aujourd\\\'hui nous n\\\'exportons plus rien, je be suis reconverti dans le transport de bat?riaux lourds, surtout les planches et le b?tal qui servent ? la tuyauterie.');
INSERT INTO `npc_questions` VALUES (7910, '', '', '', '', 'Il est efficace mais ses effets s\\\'estompent trop vite. En parlant de ?a, j\\\'ai un risque d\\\'?pid?mie sur les bras. \\nEmi, une jeune employ?e de Circ? R?al, est charg?e de la distribution de Frostiz mais elle est tomb?e malade. Je me suis d?j? occup? de son cas mais il y a un gros probl?me : elle a sans doute contamin? les personnes avec qui elle est entr?e en contact. Pouvez-vous vous charger de vacciner les personnes ayant ?t? en contact avec elle et pr?sentant des sympt?mes d\\\'aggravation du rube ? Moi j\\\'ai d?j? trop ? faire ici.');
INSERT INTO `npc_questions` VALUES (7911, '', '', '', '', 'Vous ?tes bien aimable. Voici la liste des personnes concern?es et l\\\'endroit o? vous avez le plus de chance de les trouver. \\nLorsque vous aurez distribuer les vaccins, revenez ici pour me rassurer.');
INSERT INTO `npc_questions` VALUES (7912, '', '', '', '', 'Berci, je cobben?ais justebent ? avoir bal ? la t?te.');
INSERT INTO `npc_questions` VALUES (7913, '', '', '', '', 'Ca risque rien votre truc ? \\nAh, si Rose Line l\\\'a elle-b?be test? et approuv?, je n\\\'ai aucune raison de b\\\'inqui?ter des effets secondaires.');
INSERT INTO `npc_questions` VALUES (7914, '', '', '', '', 'C\\\'est ?nervant, bon nez coule en perbanence. Ca b\\\'emp?che de bien dorbir et bes voisins se plaignent de bes ronflebents.');
INSERT INTO `npc_questions` VALUES (7915, '', '', '', '', 'Elle est un peut grosse l\\\'aiguille, l?. Non ? \\nVous n\\\'en avez pas une plus petite ? Ou alors, des pilules ? \\nNon plus ? Bais faut vraibent que je be pique avec ?a ? Dobbage...');
INSERT INTO `npc_questions` VALUES (7916, '', '', '', '', 'Je devrais ferber bon cobberce le temps d\\\'aller bieux bais je n\\\'ai personne pour be remplacer et s\\\'occuper des clients.');
INSERT INTO `npc_questions` VALUES (7917, '', '', '', '', 'Je ne suis pas un toxicobane, allez fourguer vos cochonneries ailleurs. \\nOh, c\\\'est le b?decin qui b\\\'envoie ce vaccin ? Toutes bes excuses, ? votre allure je vous avais pris pour quelqu\\\'un d\\\'autre. Reberciez Albert Paisse de ba part.');
INSERT INTO `npc_questions` VALUES (7918, '9636;139', '', '', '', 'Vous plaisantez ? Mes sets de cartes sont les plus puissants. Allez agrémenter votre collection de cartes remarquables et on en reparlera.');
INSERT INTO `npc_questions` VALUES (7919, '', '', '', '', 'Vous pouvez en obtenir en vainquant les créatures des différents continents. Mais également en troquant avec d\\\'autres aventuriers. \\n \\nAllez rendre visite à Lainu Prof, à la Foire du Trool, il vous en dira davantage');
INSERT INTO `npc_questions` VALUES (7920, '', '', '', '', 'Je ne pleure pas, c\\\'est bon nez qui coule.');
INSERT INTO `npc_questions` VALUES (7921, '', '', '', '', 'Vous avez fait tout ce chebin pour b\\\'apporter ce vaccin ? Vous ?tes adorable.');
INSERT INTO `npc_questions` VALUES (7922, '', '', '', '', 'Au boins, quand il faisait chaud, nous n\\\'avions pas de probl?me d\\\'?coulebent nasal. Vous auriez pas un bouchoir ? be passer, par hasard ?');
INSERT INTO `npc_questions` VALUES (7923, '', '', '', '', 'Oh, je n\\\'en avais jabais vu de si longue, c\\\'est impressionnant ! Et vous savez vous en servir ? \\nVous pouvez l\\\'utiliser sur boi, ?a ne be pose aucun probl?be.');
INSERT INTO `npc_questions` VALUES (7924, '', '', '', '', 'C\\\'?tait quelle liste d?j? ? Ah oui, celle d\\\'Emi. \\nJ\\\'aurai probablement besoin de vous plus tard mais nous en reparlerons au calme, l? je suis d?bord?... et les murs ont des oreilles.');
INSERT INTO `npc_questions` VALUES (7925, '', '', '', '', 'Les mansots sont nos amis, il faut les aimer aussi. \\nC\\\'est ce que ma m?re me chantais lorsque j\\\'?tais enfant, j\\\'adorais ma m?re. \\nElle n\\\'a pas surv?cu ? la glaciation, la faute ? ce maudit Comte Harebourg.');
INSERT INTO `npc_questions` VALUES (7926, '', '', '', '', 'L\\\'arriv?e massive d\\\'aventuriers avides de carnage est dangereuse pour l\\\'esp?ce des mansots, qui vivent aux abords du lac gel?. \\nAu rythme o? ils sont massacr?s, je crains que d\\\'ici une d?cennie au plus tard, leur esp?ce soit ?teinte. Il nous faut les pr?server co?te que co?te, et vous pouvez m\\\'y aider.');
INSERT INTO `npc_questions` VALUES (7927, '', '', '', '', 'Je dispose d\\\'une grande propri?t? dans laquelle je peux pr?server des dizaines de mansots. Id?alement, il me faudrait des femelles pour assurer la reproduction de l\\\'esp?ce, pouvez-vous en capturer six et me les amener saines et sauves ? Je vous d?dommagerai pour les risques encourus.');
INSERT INTO `npc_questions` VALUES (7928, '', '', '', '', 'Merci, avec moi elle sera en s?curit?. \\nD?p?chez-vous d\\\'en sauver d\\\'autres.');
INSERT INTO `npc_questions` VALUES (7929, '', '', '', '', 'Vous faites du bon travail. Si un jour les mansots du lac s\\\'?teignent, leur esp?ce aura surv?cu dans mes locaux gr?ce ? vous. \\nAller, une petite derni?re mamansot et je vous laisse tranquille.');
INSERT INTO `npc_questions` VALUES (7930, '', '', '', '', 'Alors, comme convenu, 4 douzaines d\\\'oeufs de mansots pour la taverne et une quinzaine de vieilles mamansots pour la boucherie... Tiens, vous ?tes l? vous ? \\nCe que je fais ? Euh... ben... vous voyez... Ces oeufs et ces volailles mortes ? C\\\'est rien, rien du tout... Je vous en prie, ne me d?noncez pas ? la milice.');
INSERT INTO `npc_questions` VALUES (7931, '', '', '', '', 'Je vous en prie, ne me d?noncez pas ? la milice. \\nOui, j\\\'ai des caves remplies de mamansots que j\\\'?l?ve en batterie pour vendre leurs oeufs et leur viande. Mais comprenez-moi, ? cause de l\\\'invention du Comte Harebourg, du jour au lendemain nous sommes pass?s du statut de premi?re puissance agricole ? premi?re puissance touch?e par la famine.');
INSERT INTO `npc_questions` VALUES (7932, '', '', '', '', 'Merci, je savais que vous n\\\'?tiez pas insensible et que vous comprendriez. \\nPrenez cette bourse de kamas et ne changez pas d\\\'avis.');
INSERT INTO `npc_questions` VALUES (7933, '', '', '', '', 'Comment ? Un ?levage de mansots clandestin ? \\nFoi de Cr?, ?a ne va pas se passer comme ?a ! \\nBonnie, tiens la boutique, je pars ? la chasse au mansot.');
INSERT INTO `npc_questions` VALUES (7934, '', '', '', '', 'Bambelle n\\\'en fait qu\\\'? sa t?te. Si elle continue comme ?a, il n\\\'y aura plus d\\\'arbres ? couper d\\\'ici dix ans.');
INSERT INTO `npc_questions` VALUES (7935, '', '', '', '', 'J\\\'ai une excellente id?e qui devrait permettre de lutter contre la d?forestation tout en permettant aux b?cherons de continuer leur travail. Si nous replantons des arbres chaque fois que nous les coupons et que nous tenons compte de leur temps de croissance, nous devrions pouvoir d?terminer quelle quantit? d\\\'arbres couper chaque ann?e sans risque de d?forestation. \\nBambelle ayant approuv? cette id?e, nous pouvons commencer ? planter des graines. Voulez-vous nous aider ?');
INSERT INTO `npc_questions` VALUES (7936, '', '', '', '', 'Je vais vous indiquer o? les planter. Faites quand m?me attention en chemin, les cr?atures sauvages risquent de vous attaquer pour manger vos graines, d?fendre leur territoire ou tout simplement vous d?vorer. \\nRevenez me voir lorsque vous aurez plant? toutes les graines.');
INSERT INTO `npc_questions` VALUES (7937, '', '', '', '', 'Vous avez d?j? termin? et vous vous en ?tes sorti sain et sauf ? Mon coeur se r?jouit de l\\\'apprendre. \\nAvec ce nouveau syst?me, la for?t ne s\\\'en portera que mieux, ce qui aura une incidence positive sur notre ?cosyst?me. Ca au moins c\\\'est utile et ?cologique, pas comme l\\\'exploitation ? outrance de l\\\'agriculture locale.');
INSERT INTO `npc_questions` VALUES (7938, '', '', '', '', 'Enfin quelqu\\\'un ! Tandis que je traquais un ?cumouth, j\\\'ai surpris deux kaniglous en train de s\\\'exercer ? la reproduction des esp?ces. Ils n\\\'ont pas appr?ci? d\\\'?tre d?rang?s et m\\\'ont flanqu? une sacr? rouste. \\nJ\\\'ai r?ussi ? me tra?ner jusqu\\\'ici mais je suis trop faible pour continuer. Peux-tu m\\\'accompagner jusqu\\\'? la maison d\\\'Albert Paisse, le m?decin de la bourgade ?');
INSERT INTO `npc_questions` VALUES (7939, '', '', '', '', 'Ca sert ? rien, les autres sont pass?s avant toi ? \\nComment, t\\\'es pas avec eux ? \\nDe qui je parle ? Des gredins qui m\\\'ont pris par surprise pendant que je chassais le sanglacier. Ils m\\\'ont tabass?, piqu? mes sacoches et mes armes et m\\\'ont laiss? seul dans le froid. Je suis trop affaibli pour rentrer seul ? la bourgade. Tu peux m\\\'accompagner jusqu\\\'au m?decin ?');
INSERT INTO `npc_questions` VALUES (7940, '', '', '', '', 'Tu devineras jamais ce qui m\\\'est arriv?. Je chassais le fricoch?re cendr? lorsque j\\\'ai vu un truc bouger. J\\\'ai tir? une fl?che, c\\\'?tait mon chienchien... Au m?me moment, un rocher s\\\'est d?croch? de la paroi et m\\\'a ?crabouill? la jambe. \\nJ\\\'ai besoin de ton aide pour rentrer ? Frigost, c\\\'est d?j? un miracle que je sois toujours vivant.');
INSERT INTO `npc_questions` VALUES (7941, '', '', '', '', 'Encore un bless? ! \\nEntre celui-l?, les autres amoch?s, les malades, les patients souffrant de malnutrition ou d\\\'engelures et l\\\'?pid?mie de rube qui pointe le bout de son nez, je ne vais jamais m\\\'en sortir. \\nSi seulement la glaciation n\\\'avait pas eu lieu... Fous que nous ?tions... \\nBon, laissez-le ici, je vais m\\\'occuper de lui. Merci de me l\\\'avoir amen');
INSERT INTO `npc_questions` VALUES (7942, '', '', '', '', 'Pas touche, je l\\\'ai vu le premier, il est ? moi !');
INSERT INTO `npc_questions` VALUES (7943, '', '', '', '', 'Tu arrives... trop tard... \\nMon tr?sor... vol?... \\nC\\\'est Emile... le tueur... aaaaargh !');
INSERT INTO `npc_questions` VALUES (7944, '', '', '', '', 'De ce tr?sor, pardi ! Sa place est dans un mus?e, et je ne dis pas ?a sous pr?texte que mes amis trouvent que l\\\'int?rieur de ma maison ressemble ? un mus?e.');
INSERT INTO `npc_questions` VALUES (7945, '', '', '', '', 'Hein ? Bah c\\\'est simple, comme je ne peux pas le porter, je vais aller chercher un attelage de chienchiens des neiges. \\nAh, mais je vois clair dans ton jeu, tu veux profiter de mon absence pour me le voler, c\\\'est ?a ?');
INSERT INTO `npc_questions` VALUES (7946, '', '', '', '', 'R?fl?chissons... Je ne peux pas laisser mon tr?sor sans surveillance, mais je ne peux pas le ramener tout seul... \\nJ\\\'ai une id?e ! Tu vas rentrer ? la bourgade et louer un attelage de chienchien des neiges. Je vais surveiller mon tr?sor jusqu\\\'? ton retour et ensuite je le partagerai avec toi, ?a te va ?');
INSERT INTO `npc_questions` VALUES (7947, '', '', '', '', 'Evite de tra?ner, les esprits qui r?dent dans les parages ne me disent rien qui vaillent et j\\\'ai d?j? d? repousser plusieurs assauts avant ton arriv?e.');
INSERT INTO `npc_questions` VALUES (7948, '', '', '', '', 'Tu veux emmener des chienchiens dans le berceau d\\\'Alma ? Ca te co?tera 5000 kamas.');
INSERT INTO `npc_questions` VALUES (7949, '', '', '', '', 'D?p?che-toi de m\\\'amener un attelage de chienchiens des neiges, je suis s?r que les fant?mes de pirates en veulent ? mon tr?sor.');
INSERT INTO `npc_questions` VALUES (7950, '', '', '', '', 'Ils ont pas l\\\'air tr?s robustes, m\\\'enfin, c\\\'est mieux que rien. \\nTiens, voil? ta part.');
INSERT INTO `npc_questions` VALUES (7951, '', '', '', '', 'Gr?ce aux activit?s volcaniques de l\\\'?le, les eaux des larmes d\\\'Ouronigride sont tr?s charg?es en min?raux. Je suis persuad? que leur consommation par les Frigostiens serait meilleure pour l\\\'organisme que la neige fondue bue actuellement. \\nLe plus gros probl?me rencontr? actuellement est leur haute teneur en soufre, mais avec le traitement appropri?, je devrais pouvoir les rendre potables.');
INSERT INTO `npc_questions` VALUES (7952, '', '', '', '', 'La piste du YeCh\\\'Ti n\\\'est plus tr?s fra?che. Le temps presse si nous voulons lui r?gler son compte.');
INSERT INTO `npc_questions` VALUES (7953, '', '', '', '', 'Suite aux nombreux massacres de boufmouths perp?tr?s par le YeCh\\\'Ti, nous avons d?cid? de monter une exp?dition punitive pour nous d?barrasser de lui une bonne fois pour toute. \\nSes traces nous ont men?s jusqu\\\'ici et nous sommes ? pr?sent en train d\\\'?laborer une strat?gie pour le vaincre.');
INSERT INTO `npc_questions` VALUES (7954, '', '', '', '', 'Si nous approchons le YeCh\\\'Ti comme ?a, il va nous rep?rer. Apr?s avoir ?tudi? son comportement, nous nous sommes aper?us qu\\\'il ne se souciait pas des givrefoux. Si nous r?cup?rons des fourrures de givrefoux en assez bon ?tat, nous pourrons nous en v?tir et surprendre le YeCh\\\'Ti. \\nJ\\\'ai besoin de votre aide pour nous procurer suffisamment de fourrures. Pourquoi ne pas le faire nous-m?me ? Parce que nous serions impr?gn?s de l\\\'odeur du sang des givrefoux, ce qui pourrait mettre la puce ? l\\\'oreille au YeCh\\\'Ti.');
INSERT INTO `npc_questions` VALUES (7955, '', '', '', '', 'Baissez-vous ! Vous allez nous faire rep?rer.');
INSERT INTO `npc_questions` VALUES (7956, '', '', '', '', 'Vous avez r?ussi ? Je dois reconna?tre que vous m\\\'impressionnez sur ce coup. \\nJe ne devrais pas vous en parler, mais bon... \\nSi vous allez plus au sud, vous d?couvrirez ce que nous autres, Frigostiens, appelons le village enseveli. La maire Cantile a interdit tout contact avec ses habitants, mais apr?s plusieurs jours pass?s dans cette crevasse, je me dis que leur vie depuis presque un si?cle doit ?tre encore plus mis?rable que la n?tre. Ils doivent sans doute avoir besoin d\\\'aide, alors si vous d?cidez d\\\'y aller, nous ferons comme si nous ne vous avions pas vu pour ne pas vous poser probl?me.');
INSERT INTO `npc_questions` VALUES (7957, '', '', '', '', 'Aaaaah, vous avez le rube ! Allez-vous en, je veux pas avoir de la mouquire plein le nez ? cause de vous.');
INSERT INTO `npc_questions` VALUES (7958, '', '', '', '', 'Dites, vous n\\\'auriez pas quelques bonbons, ou des g?teaux ? base de graines ola ? Non ? Je peux aussi me contenter de brioche vous savez.');
INSERT INTO `npc_questions` VALUES (7959, '', '', '', '', 'Je comprends pas pourquoi mes copains refusent de me laisser juger qui a gagn? le concours de bonmonstre de neige. Ils disent que j\\\'ai pas le droit parce que je participe aussi au concours. C\\\'est n\\\'importe quoi.');
INSERT INTO `npc_questions` VALUES (7960, '', '', '', '', 'J\\\'ai vu un tr?s joli coin en passant, je pense que je vais souvent y retourner.');
INSERT INTO `npc_questions` VALUES (7961, '', '', '', '', 'Il poss?de aussi le plus gros enclos de dragodindes de toute l\\\'?le. Si, c\\\'est vrai. \\nAu fait, vous pensez quoi de mon bonmonstre de neige ? Ne dites pas de b?tise, sinon je le dis ? B?bert.');
INSERT INTO `npc_questions` VALUES (7962, '', '', '', '', 'Mon petit fr?re L?on n\\\'a pas grandit depuis des ann?es. Mes parents disent que c\\\'est ? cause du Comte Harebourg, mais je vois pas le rapport.');
INSERT INTO `npc_questions` VALUES (7963, '', '', '', '', 'Avec mes copains nous avons fabriqu? des bonmonstres de neige. Nous voulons faire un concours pour savoir qui a fait le plus affreux bonmonstre mais nous n\\\'avons personne pour faire le jury. Sufur s\\\'est propos? mais il participe d?j? au concours donc c\\\'est de la triche. \\nVous voulez servir de jury ? S\\\'il-vous pla?t ?');
INSERT INTO `npc_questions` VALUES (7964, '', '', '', '', 'Je vais vous indiquer o? se trouve chaque bonmonstre. Vous allez les voir et vous revenez pour dire lequel est le plus affreux. C\\\'est si simple que m?me un Iop peut y arriver.');
INSERT INTO `npc_questions` VALUES (7965, '', '', '', '', 'Alors, c\\\'est lequel de bonmonstre le plus affreux ?');
INSERT INTO `npc_questions` VALUES (7966, '', '', '', '', 'Pnj(1331) et Message(7965)');
INSERT INTO `npc_questions` VALUES (7967, '', '', '', '', 'Pnj(1331) et Message(7965)');
INSERT INTO `npc_questions` VALUES (7968, '', '', '', '', 'Pnj(1331) et Message(7965)');
INSERT INTO `npc_questions` VALUES (7969, '', '', '', '', 'Pnj(1331) et Message(7965)');
INSERT INTO `npc_questions` VALUES (7970, '', '', '', '', 'Pnj(1331) et Message(7965)');
INSERT INTO `npc_questions` VALUES (7971, '', '', '', '', 'Pnj(1331) et Message(7965)');
INSERT INTO `npc_questions` VALUES (7972, '', '', '', '', 'Croyez-moi, l\\\'entretien des extracteurs et de la tuyauterie dans les larmes d\\\'Ouronigride n\\\'est pas de tout repos. Il faut en permanence surveiller les extracteurs, s\\\'assurer qu\\\'il y a suffisamment de pression mais pas trop, r?parer les ?l?ments d?faillants, tenir les crapeurs ? distance et tout un tas d\\\'autres bricoles. C\\\'est pas un travail de fonctionnaire, c\\\'est s?r.');
INSERT INTO `npc_questions` VALUES (7973, '', '', '', '', 'Je vois que vous ?tes d\\\'accord avec moi. Je m\\\'en sortais ? peu pr?s jusqu\\\'? ce que mon imb?cile d\\\'assistant confonde un jacuzzi naturel avec un bain d\\\'acide. Il est mort dans d\\\'atroces souffrances et son r?le d\\\'agonie a dur?e une bonne heure. Ca lui aura au moins appris que les apparences sont parfois trompeuses. \\nBon, comme vous l\\\'avez compris, j\\\'ai besoin d\\\'un nouvel assistant, mais je ne peux pas quitter mon poste. Vous pouvez rendre visite ? Lucette Brifian, l\\\'assistante du maire, et et lui dire qu\\\'il me faut imp?rativement un nouvel assistant si elle ne veut pas que le port et la bourgade reg?lent ?');
INSERT INTO `npc_questions` VALUES (7974, '', '', '', '', 'Encore ? Il en r?clame un nouveau tous les deux mois. A ce rythme, il n\\\'y aura bient?t plus personne de qualifi? pour l\\\'aider. \\nJe n\\\'ai personne sous la main, mais peut-?tre que notre bricoleuse Valy Domidat aura quelqu\\\'un ? vous proposer.');
INSERT INTO `npc_questions` VALUES (7975, '', '', '', '', 'Je ne peux pas vous laisser Francky, il m\\\'est trop pr?cieux. S\\\'il vous faut vraiment quelqu\\\'un, je vous conseille plut?t de vous adresser au chef des mines Laurent Gebleuh, il glande depuis plusieurs d?cennies et passe le plus clair de son temps ? la taverne de la bourgade. Du travail de lui fera pas de mal.');
INSERT INTO `npc_questions` VALUES (7976, '', '', '', '', 'Tu me prends pour qui ? Moi, je donne des ordres, je n\\\'en re?ois pas. \\nSi Larry Tutthe a besoin d\\\'un nouvel assistant, va emb?ter Gaston. C\\\'?tait un de mes ouvriers ? la mine, mais depuis qu\\\'elles sont infest?es de monstres, il s\\\'est recycl? dans la surveillance de la tuyauterie. Tu parles, c\\\'est un travail de fonctionnaire. \\nTu lui dis qu\\\'il a ?t? mut? dans les larmes d\\\'Ouronigride et qu\\\'il ne peut pas faire appel de la d?cision, nous ne sommes pas un tribunal.');
INSERT INTO `npc_questions` VALUES (7977, '', '', '', '', 'Ne me d?rangez pas, je dois surveiller la tuyauterie. Si un accident survient pendant que vous me d?rangez, on va dire que c\\\'est ma faute et me muter dans le berceau d\\\'Alma. Je n\\\'ai aucune envie de passer les dix prochaines ann?es en compagnie de fant?mes.');
INSERT INTO `npc_questions` VALUES (7978, '', '', '', '', 'Des bains d\\\'eaux chaudes toute l\\\'ann?e, plus de gelure ni de rube, que demander de plus ?');
INSERT INTO `npc_questions` VALUES (7979, '', '', '', '', 'Il m\\\'a l\\\'air un peu gringalet, j\\\'esp?re que c\\\'est pas un de ces fonctionnaires ? la noix. \\nAu fait, pendant que tu te baladais dans la bourgade, je suis intervenu en urgence sur cet extracteur. Comme tu le vois, la r?paration est en cours mais ?a va prendre un peu de temps. Tu vas prendre Gaston avec toi et faire le tour des quatre autres extracteurs pour t\\\'assurer que tout va bien. \\nM?me s\\\'il n\\\'y a aucun probl?me, repasse me voir pour me tenir au courant.');
INSERT INTO `npc_questions` VALUES (7980, '', '', '', '', 'Quel genre de d?g?ts ? \\nMmh, je vois. Gaston va surveiller l\\\'extracteur endommag? pendant que tu vas chercher une caisse de mat?riel aupr?s de Valy Domidat. \\nT\\\'inqui?te pas pour la liste, elle a l\\\'habitude et sait ce qu\\\'il me faut, c\\\'est une sacr?e nana.');
INSERT INTO `npc_questions` VALUES (7981, '', '', '', '', 'Francky, donne-moi un coup de main. \\nAlors il faut ?a, ?a, il aura aussi besoin de cet outil... Deux bo?tes... \\nC\\\'est pr?t. Avec ?a, Larry Tutthe devrait pouvoir faire face ? n\\\'importe quelle situation.');
INSERT INTO `npc_questions` VALUES (7982, '', '', '', '', 'Montre-moi ?a. \\nVoyons, elle a pens? ? ?a, deux bo?tes de ?a, les outils pour faire ?a. J\\\'ai l\\\'impression qu\\\'il ne manque rien. \\nMerci, tu as fait du bon boulot.');
INSERT INTO `npc_questions` VALUES (7983, '', '', '', '', 'Puisque vous le proposez... J\\\'ai besoin d\\\'aide pour pr?lever des ?chantillons et les transporter ? la bourgade. Je loue une partie de l\\\'entrep?t d\\\'Ernest Laye pour stocker les bouteilles et faire mes recherches, donc si tu as le temps, il faudrait faire des pr?l?vements ici et les d?poser l?-bas. \\nFais bien attention ? ne pas d?ranger les locataires des bassins.');
INSERT INTO `npc_questions` VALUES (7984, '', '', '', '', 'Bizarre, ?a ne ressemble ? rien que je connaisse. Remarquez, je ne suis pas un naturaliste. Vous feriez mieux de montrer ?a ? un alchimiste, c\\\'est plus son domaine que le mien. Mais avant, allez d?poser les pr?l?vements chez Ernest Laye.');
INSERT INTO `npc_questions` VALUES (7985, '', '', '', '', 'Vous n\\\'avez qu\\\'? les poser dans le coin, l?. Je les rangerai plus tard.');
INSERT INTO `npc_questions` VALUES (7986, '', '', '', '', 'Comme c\\\'est chou. Vous l\\\'avez trouv?e o? ? Dans les larmes d\\\'Ouronigride ?! \\nJe ne suis pas expert en cr?atures, vous devriez vous adresser ? un autre alchimiste, mais je doute que vous en trouviez un qui vous convienne sur l\\\'?le de Frigost. Vous feriez mieux de chercher ailleurs, ?a vous fera gagner du temps.');
INSERT INTO `npc_questions` VALUES (7987, '', '', '', '', 'Ca a l\\\'air int?ressant, mais je n\\\'ai pas le temps de m\\\'en occuper. \\nVa voir mon assistant Kimiya, dans le laboratoire souterrain de la plage de corail. Il sera ravi de faire des recherches sur cette cr?ature.');
INSERT INTO `npc_questions` VALUES (7988, '', '', '', '', 'Je n\\\'ai jamais rien vu de tel. La croissance de cette cr?ature est comme fig?e. \\nJe devrais pouvoir arranger ?a, mais je vais manquer d\\\'ingr?dients pour mes potions. \\nJe vais garder la cr?ature sous observation pendant que vous allez me chercher 10 Baves du Kaskargo et 1 Pistil du Tynril. Oh, il me faudra aussi des objets issus de l\\\'endroit o? vous l\\\'avez trouv? et d\\\'apr?s ce que je sais, il existerait des oeufs remplis de vapeur. Il m\\\'en faudrait une dizaine.');
INSERT INTO `npc_questions` VALUES (7989, '', '', '', '', 'Tout est pr?t, il ne me manque plus que ce que vous m\\\'avez apport?. \\nil suffit d\\\'ajouter ?a puis de m?langer, j\\\'applique le tout sur cette ?trange cr?ature... Ca a march? ! \\nLa croissance a repris de mani?re acc?l?r?e. D?p?chez-vous de remettre cette cr?ature l? o? vous l\\\'avez trouv?e si vous voulez qu\\\'elle arrive ? maturit? sans effet secondaire.');
INSERT INTO `npc_questions` VALUES (7990, '', '', '', '', 'Merci de m\\\'avoir sauv?e. Le d?mon m\\\'avait laiss?e ici au stade de larve mais la glaciation avait stopp?e ma croissance. A pr?sent que je suis adulte et libre de mes actes, je vais chercher un moyen de vous prouver ma reconnaissance.');
INSERT INTO `npc_questions` VALUES (7991, '', '', '', '', 'Avant de partir, prenez ces pi?ces. Je les ai trouv?es au fond du bassin. Elles ne me sont d\\\'aucune utilit? mais j\\\'ai vu que vous en poss?diez, donc elles doivent bien vous servir ? quelque chose.');
INSERT INTO `npc_questions` VALUES (7992, '', '', '', '', 'Je savais que le trajet jusqu\\\'au village ?tait risqu?, mais je ne pensais pas me faire attaquer par autant de monstres sur le chemin du retour. \\nAidez-nous s\\\'il-vous-pla?t.');
INSERT INTO `npc_questions` VALUES (7993, '', '', '', '', 'Je crois que les cawottes sont cuites pour nous.');
INSERT INTO `npc_questions` VALUES (7994, '', '', '', '', 'Quand je pense au mal que nous nous sommes donn?s pour ravitailler les habitants du village enseveli... A croire que les dieux s\\\'acharnent contre nous.');
INSERT INTO `npc_questions` VALUES (7995, '', '', '', '', 'Je pensais qu\\\'apr?s avoir atteint le village, nous aurions fait le plus dur. Je me suis tromp');
INSERT INTO `npc_questions` VALUES (7996, '', '', '', '', 'Si nous nous en sortons vivants, je crois que je ne remettrai plus jamais les pieds ici.');
INSERT INTO `npc_questions` VALUES (7997, '', '', '', '', 'Grrrr.');
INSERT INTO `npc_questions` VALUES (7998, '', '', '', '', 'A cause de votre faiblesse, mes compagnons ont ?t? massacr?s. Je n\\\'ai plus rien ? vous dire.');
INSERT INTO `npc_questions` VALUES (7999, '', '', '', '', 'Vous avez r?ussi, vous nous avez tous sauv?s ! Nous allons pouvoir rentrer chez nous. Prenez ces kamas, ce n\\\'est pas grand chose, mais c\\\'est tout ce que nous avons. \\nSi vous retournez ? la bourgade, s\\\'il-vous-pla?t ne dites rien ? notre maire. Les contacts avec les parias du village enseveli ?tant interdits, nous risquons d\\\'?tre jet?s en prison si quelqu\\\'un nous d?nonce.');
INSERT INTO `npc_questions` VALUES (8000, '', '', '', '', 'Ainsi, malgr? l\\\'interdiction formelle de se rendre l?-bas, des habitants de la bourgade ont ravitaill? les parias du village enseveli. Je vais prendre les mesures qui s\\\'imposent pour punir ces hors-la-loi. \\nVoici pour vous r?compenser de votre loyaut');
INSERT INTO `npc_questions` VALUES (8001, '', '', '', '', 'Vous avez quelque chose ? me dire ? non, vraiment rien ? J\\\'ai l\\\'impression que vous me cachez quelque chose. \\nVous n\\\'avez vraiment rien ? me dire ?');
INSERT INTO `npc_questions` VALUES (8002, '', '', '', '', 'Je dois devenir un peu parano?aque avec le temps. \\nJ\\\'ai eu des ?chos tr?s positifs de vos actions pour les habitants de Frigost et je tiens ? vous remercier en vous offrant ces quelques kamas. \\nSi vous constater quelque chose d\\\'anormale, n\\\'h?sitez pas ? m\\\'en faire part. Si l\\\'information vaut le coup, je saurai me montrer g?n?reuse.');
INSERT INTO `npc_questions` VALUES (8003, '', '', '', '', 'J\\\'ai froid, si froid...');
INSERT INTO `npc_questions` VALUES (8004, '', '', '', '', 'Mon ?me est prisonni?re de ce monde de glace depuis presque un si?cle ? cause de la jalousie d\\\'un rival. \\nJ\\\'ai ?t? assassin? par Jean-Louis, un agriculteur qui convoitait mes champs, quelques secondes avant la glaciation. Il ne m\\\'a pas rat?. \\nAu lieu de se r?incarner, mon ?me a ?t? pi?g?e lorsque la mal?diction de l\\\'hiver ?ternel s\\\'est abattue sur Frigost. \\nJ\\\'ai tout essay?, mais il n\\\'existe aucun moyen de me lib?rer. Par contre, la vengeance est toujours possible car c\\\'est un plat qui se mange froid mais avant ?a, j\\\'ai un autre service ? vous demander. Pouvez-vous m\\\'aider ?');
INSERT INTO `npc_questions` VALUES (8005, '', '', '', '', 'J\\\'ignore comment va ma femme Ghislaine. Rendez-lui visite et expliquez-lui ce qui m\\\'est arriv?. Elle habite une petite maison dans le port, vers le nord-ouest.');
INSERT INTO `npc_questions` VALUES (8006, '', '', '', '', 'C\\\'est un labyrinthe tr?s complexe, alors ?coute bien ce que je vais t\\\'expliquer ! \\nTu es ? l\\\'entr?e. En entrant ? ta droite, tu acc?deras ? la premi?re des 25 salles du labyrinthe, qui forment un tr?s grand carr?. Je t\\\'ai m?me fait un dessin sur le tableau ? c?t? de moi ! \\nUtilise un des leviers d\\\'une salle pour agir sur les portes de la salle en face. Les portes dans son alignement se fermeront, mais les autres s\\\'ouvriront. \\nAttention, garde ? l\\\'esprit que tu ne peux pas ouvrir toi-m?me les portes de ta salle. Il faut donc que d\\\'autres aventuriers t\\\'ouvrent le chemin. C\\\'est simple non ?');
INSERT INTO `npc_questions` VALUES (8007, '', '', '', '', 'Alors, tu es d?j? perdu ? Hahaha je m\\\'en doutais, lorsque je t\\\'ai vu arriver, je savais que tu ne serais pas capable de trouver ton chemin dans ce d?dale de salles. Heureusement, je peux t\\\'aider ? revenir ? l\\\'entr?e si tu le d?sires.');
INSERT INTO `npc_questions` VALUES (8008, '', '', '', '', 'Je sens que tu n\\\'as rien compris... Si ?a peut t\\\'aider, les salles sont num?rot?es dans le sens de lecture, aide t\\\'en pour te rep?rer et t\\\'organiser avec tes co?quipiers. Ah, ? ce sujet... J\\\'ai oubli? de te pr?venir, tu n\\\'as aucune chance si tu y vas seul, plus vous serez nombreux, plus vous aurez de chances de progresser dans ce terrible labyrinthe. \\nUne fois ? l\\\'int?rieur, tu remarqueras que j\\\'ai accroch? sur chaque porte une affiche de couleur pour te faciliter la t?che. Je suis m?me all? jusqu\\\'? m\\\'arranger pour faire retirer les grilles de la premi?re salle !');
INSERT INTO `npc_questions` VALUES (8009, '', '', '', '', 'Que faites-vous chez moi ? C\\\'est pour la mission de Seb Atier ?');
INSERT INTO `npc_questions` VALUES (8010, '', '', '', '', 'Tu m\\\'as l\\\'air perdu alors que c\\\'est pourtant tr?s simple ! J\\\'ai l\\\'impression d\\\'?tre encore tomb? sur un touriste abruti ! \\nBon, c\\\'est d\\\'accord, sache qu\\\'? n\\\'importe quel moment, je pourrai te ramener dans cette salle si tu te retrouves enferm? ou que tu es tout simplement perdu. \\nMaintenant va,  je n\\\'ai plus rien d\\\'autre ? t\\\'apprendre.');
INSERT INTO `npc_questions` VALUES (8011, '', '', '', '', 'Vous vous rendez compte de ce que vous dites ? \\nVous pr?tendez que Jean-Louis a assassin? mon mari Robert, alors qu\\\'ils ?taient amis d\\\'enfance. En plus, vous osez dire que c\\\'est Robert, mort depuis presque un si?cle, qui vous l\\\'a dit, et vous voudriez que je vous crois ? \\nSi vous n\\\'avez aucune preuve de ce que vous avancez, vous n\\\'avez rien ? faire ici.');
INSERT INTO `npc_questions` VALUES (8012, '', '', '', '', 'J\\\'ai une id?e. Vous allez lui dire que lors de notre lune de miel, ce n\\\'?tait pas le chien qui avait des ?vaporations gastriques. Personne d\\\'autres que nous n\\\'est au courant de cette histoire, ?a devrait la convaincre que vous n\\\'?tes pas un charlatan.');
INSERT INTO `npc_questions` VALUES (8013, '', '', '', '', 'Comment ?tes-vous au courant ? \\nCe que vous me dites-l? est tr?s troublant, j\\\'ai besoin de r?fl?chir. Rendez-vous ce soir apr?s 19h00 au sud de la sortie ouest, pr?s de la muraille, ? la limite entre la bourgade et le port. J\\\'aurai alors pris ma d?cision sur ce qu\\\'il faut faire pour rendre justice ? mon d?funt ?poux.');
INSERT INTO `npc_questions` VALUES (8014, '', '', '', '', 'Vous ?tes encore en vie ? On m\\\'avait pourtant dit que...');
INSERT INTO `npc_questions` VALUES (8015, '', '', '', '', 'Et bien oui, je suis avec Jean-Louis. Nous sommes mari?s depuis plus de soixante ans. \\nRobert venait de gagner une fortune mais cet idiot refusait d\\\'acheter cette magnifique maison au bord de la mer. J\\\'ai demand? ? Jean-Louis de l\\\'?liminer pour que nous puissions vivre tous les deux ensemble et d?penser l\\\'argent de Robert comme bon nous semble. J\\\'ignorais alors que cet imb?cile de Robert venait d\\\'investir sa fortune dans des champs, et la glaciation m\\\'a tout fait perdre. \\nAujourd\\\'hui, Jean-Louis et moi vivons dans cette petite baraque et il ne reste plus grand chose de la fortune de Robert. \\nVous comptez nous d?noncer ? Nous pouvons trouver un arrangement.');
INSERT INTO `npc_questions` VALUES (8016, '', '', '', '', 'Je peux vous c?der ce qui reste de la fortune de Robert, ?a repr?sente environ 20000 kamas. Qu\\\'en pensez-vous ?');
INSERT INTO `npc_questions` VALUES (8017, '', '', '', '', 'Je vais vous chercher ?a... \\nPrenez cet argent et partez.');
INSERT INTO `npc_questions` VALUES (8018, '', '', '', '', 'C\\\'est un dr?le d\\\'histoire que vous me racontez l?. Je vais faire mener ma propre enqu?te, merci de m\\\'avoir pr?venue.');
INSERT INTO `npc_questions` VALUES (8019, '', '', '', '', 'Ainsi, j\\\'ai vraiment tout perdu. Je compte sur notre maire pour leur infliger un ch?timent exemplaire.');
INSERT INTO `npc_questions` VALUES (8020, '', '', '', '', 'Je te pr?viens, pour entrer dans cette ?pave et combattre l\\\'esprit rebelle, je dois te transformer en esprit de pirate. Si tu y vas seul, tu n\\\'auras aucune chance de le vaincre. Trouve-toi des compagnons et sache que vous ne pourrez combattre qu\\\'? quatre.');
INSERT INTO `npc_questions` VALUES (8021, '', '', '', '', 'Mon ?me est lib?r?e, mais finalement je vais rester ici, c\\\'est bien plus amusant. \\nMon butin se trouve au sud du berceau d\\\'Alma, dans un coffre. Son bois est ab?m?, tu n\\\'auras aucun mal ? le briser en tapant dessus.');
INSERT INTO `npc_questions` VALUES (8022, '', '', '', '', 'Je ne peux pas te transformer en esprit de pirate tant que tu as le mal de mer.');
INSERT INTO `npc_questions` VALUES (8023, '', '', '', '', 'Il se moque de moi ? \\nDites-donc, cher touriste, il ?tait question de retrouver le butin de mon p?re, pas juste une stupide lettre. Vous ?tes bien comme le Comte Harebourg, vous promettez de nous aider et au final, vous nous abandonnez.');
INSERT INTO `npc_questions` VALUES (8024, '', '', '', '', 'Depuis la glaciation, nous autres Frigostiens avons appris ? vivre la vie, jour apr?s jour, nuit apr?s nuit. A quoi ?a sert d\\\'?tre sur la terre, si c\\\'est pour faire nos vies ? genoux ?');
INSERT INTO `npc_questions` VALUES (8025, '', '', '', '', 'Avant l\\\'arriv?e de l\\\'hiver, nous pensions que le temps c\\\'?tait comme le vent, que pour vivre il n\\\'y avait que ?a d\\\'important. Nous nous fichions pas mal de la morale car nous pensions que nous ne faisions pas mal.');
INSERT INTO `npc_questions` VALUES (8026, '', '', '', '', 'Ginette, ma douce Ginette, je suis le jouet de la fortune, je tiens un amour impossible. Mais voici un ?tranger qui, sans nul doute, pourra nous aider.');
INSERT INTO `npc_questions` VALUES (8027, '', '', '', '', 'Nos familles sont en froid depuis un si?cle ? cause d\\\'une histoire de concurrence d?loyale. Il faut savoir qu\\\'avant la glaciation, nos familles ?taient en concurrence pour la premi?re place d\\\'exportateur de c?r?ales et depuis, elles sont en froid ? cause d\\\'une histoire de concurrence d?loyale. Pour cette stupide raison, elles refusent notre mariage. \\nPouvez-nous nous aider ? leur faire entendre raison, nous vous en supplions ?');
INSERT INTO `npc_questions` VALUES (8028, '', '', '', '', 'Il faut trouver un moyen de r?concilier nos familles. Le meilleur moyen serait de tirer au clair cette histoire de concurrence d?loyale mais les pistes sont minces. Les Montays accusent les Capou?s de leur avoir vol? une partie de leurs chargements de c?r?ales. Ils pensent que l\\\'exc?dent vendu par les Capou?s provenait de ces vols. Quant aux Caopu?s, ils r?futent ces accusations mais sans apporter de preuve. \\nA cause du temps ?coul?, enqu?ter sur le vol va ?tre extr?mement difficile, mais c\\\'est notre seule piste valable. \\nAllez interroger le Capitaine Gneux, en esp?rant que son cerveau embrum? par la boisson se souvienne encore de quelque chose.');
INSERT INTO `npc_questions` VALUES (8029, '', '', '', '', '? Grom?o! Grom?o! Pourquoi es-tu Grom?o? Renie ton p?re et abdique ton nom, ou, si tu ne le veux pas, jure de m\\\'aimer, et je ne serai plus une Capou');
INSERT INTO `npc_questions` VALUES (8030, '', '', '', '', 'De quoi tu m\\\'causes ? \\nAh, cette histoire de vol. Je m\\\'en souviens comme si c\\\'?tait hier. Quoique techniquement, c\\\'est pratiquement le cas avec cet hiver qui n\\\'en finit pas. \\nAucun probl?me de chargement n\\\'a ?t? constat? l\\\'ann?e pr?c?dent la glaciation. Si tu veux fouiller la bateau, va surtout falloir visiter les chemin?es, h?h?. \\nPourquoi je te dis ?a ? Parce que les bateaux ayant servi ? l\\\'?poque ont ?t? d?sassembl?s pour fournir les planches n?cessaires ? l\\\'isolation des maisons du port et de la bourgade. Ils ont aussi aussi servi de combustible en attendant la mise en place de la tuyauterie. \\nOublie cette histoire, tu perds ton temps, quoique... Si tu as vraiment du temps ? perdre, va donc interroger les marins du port.');
INSERT INTO `npc_questions` VALUES (8031, '', '', '', '', 'Comment je saurais ?a ? Je n\\\'?tais m?me pas l');
INSERT INTO `npc_questions` VALUES (8032, '', '', '', '', 'Je travaillais au chargement de c?r?ales et d?chargement d\\\'autres denr?es, et je n\\\'ai rien vu. S\\\'il y avait eu un vol dans le port, nous en aurions entendu parler. \\nY\\\'a bien eu le vol de la moumoute du Capitaine Igloute, un Amakn?en, mais c\\\'est pas tr?s int?ressant... par contre, c\\\'?tait marrant.');
INSERT INTO `npc_questions` VALUES (8033, '', '', '', '', 'Je m\\\'en souviens, je travaillais pour les Montays ? l\\\'?poque. Les Capou?s ont vol? une partie du chargement de c?r?ales qu\\\'ils ont ensuite revendu. Ils se sont faits plein de kamas gr?ce aux Montays, c\\\'est pour ?a que les deux familles sont en conflit depuis un si?cle.');
INSERT INTO `npc_questions` VALUES (8034, '', '', '', '', 'Les bateaux sont arriv?s le soir et nous avons attendu l\\\'aube pour d?charger. Il manquait la moiti? du chargement sur tous les bateaux. D\\\'apr?s moi, voler une telle quantit? de c?r?ales en une nuit n\\\'a pas pu passer inaper?u, mais les gardes-c?tes d\\\'Amakna n\\\'ont rien constat? d\\\'anormal. \\nSi vous voulez mon avis, ils ont menti, mais les Montays n\\\'avaient aucune autorit? sur ce qui se passe en Amakna donc ils n\\\'ont rien pu savoir de plus. \\nSi vous voulez interroger les gardes-c?tes de l\\\'?poque, c\\\'est mal barr? car depuis le temps, ils doivent manger les pissenlits par la racine. Et ce ne sont pas les Capou?s qui vont vous dire quoi que ce soit.');
INSERT INTO `npc_questions` VALUES (8035, '', '', '', '', 'Ce que vous me demander est tr?s difficile, mais si c\\\'est n?cessaire pour que je puisse ?pouser mon Grom?o, je vais vous aider. \\nIl existe un s?rum de v?rit? dont seul Eric Azaraille, l\\\'alchimiste, conna?t le proc?d? de fabrication. Id?alement, il faudrait l\\\'utiliser sur une personne susceptible de savoir ce qui s\\\'est pass?, donc mon p?re. \\nVous ne pourrez pas l\\\'approcher facilement, sauf si... Vous vous faites passer pour un riche pr?tendant souhaitant m\\\'?pouser.');
INSERT INTO `npc_questions` VALUES (8036, '', '', '', '', 'Ca va donc se passer en trois ?tapes : \\n- se procurer un s?rum de v?rit? aupr?s d\\\'un alchimiste. \\n- se faire passer pour un riche pr?tendant. \\n- se retrouver en t?te ? t?te avec mon p?re. \\nVous pensez y arriver ? Si oui, il vous faut imp?rativement obtenir un s?rum de v?rit? aupr?s d\\\'Eric Azaraille. Sans lui, tout le plan tombe ? l\\\'eau.');
INSERT INTO `npc_questions` VALUES (8037, '', '', '', '', 'Je ne vois pas de quoi vous parler, je ne connais pas le secret de fabrication du s?rum de v?rit?. C\\\'est cet ivrogne de Capitaine Gneux qui vous a racont? ?a ?');
INSERT INTO `npc_questions` VALUES (8038, '', '', '', '', 'Ce petit freluquet sait faire ?a ? Pas ?tonnant qu\\\'il ne veuille pas partager son secret. \\nTu veux mon avis ? Je te le donne quand m?me. Apporte-lui une ?me captur?e de Kaniglou et fais-lui croire qu\\\'il est apprivois? et soumis. Avec ?a, il ne pourra rien te refuser. \\nLui dis surtout pas que cette id?e est de moi sinon il se doutera de quelque chose. \\nJ\\\'imagine d?j? sa t?te quand il r?aliser qu\\\'il se trouve nez-?-nez avec un Kaniglou sauvage loin d\\\'?tre soumis ? ses caprices. Hahaha. \\nA la tienne !');
INSERT INTO `npc_questions` VALUES (8039, '', '', '', '', 'Un Kaniglou apprivois? et soumis ? mes moindres d?sirs ? C\\\'est tr?s chou de votre part. \\nQue vouliez-vous d?j? ? Ah oui, un s?rum de v?rit?. \\nIl me manque quelques ingr?dients dont un qu\\\'on ne trouve plus qu\\\'en Amakna. Puisque vous tenez tant ? obtenir ce s?rum, je vais vous mettre ? contribution. \\nIl me faut du S?rum de Mansot qu\\\'Albert Paisse, notre m?decin, doit avoir en stock suffisant. J\\\'ai ?galement besoin de Guano de G?likan cristallis?, il y en a plein sur le port. Il me faudra aussi deux Perce-Neige qui poussent autour de la bourgade et enfin, de l\\\'herbe ? chat qui, si ma m?moire est bonne, ne se trouve que dans le temple Ecaflip.');
INSERT INTO `npc_questions` VALUES (8040, '', '', '', '', 'J\\\'en ai une caisse enti?re. C\\\'est pour Eric Azaraille ? Je me demande bien pourquoi il en a besoin. \\nPrenez cet ?chantillon et fichez-moi le camp, j\\\'ai du travail et des gens ? sauver.');
INSERT INTO `npc_questions` VALUES (8041, '', '', '', '', 'Le Guano de G?likan cristallis? va donner du go?t au s?rum. \\nQue je vous explique comment ?a fonctionne : l\\\'interrogateur doit boire du s?rum en premier. Toutes les personnes qui en boivent ensuite pourront difficilement lui mentir. \\nSon efficacit? est garantie ! Je m\\\'en sers r?guli?rement sur les dockers du port pour obtenir quelques faveurs... Zou, filez. Je vous ai assez vu pour aujourd\\\'hui.');
INSERT INTO `npc_questions` VALUES (8042, '', '', '', '', 'Vous avez r?ussi ? obtenir du s?rum de v?rit? ? Je suis si contente d\\\'avoir enfin trouv? quelqu\\\'un qui se soucie de notre bien-?tre. \\nMaintenant, ?a veut ?tre plus difficile car il va falloir vous faire passer pour un riche pr?tendant venu du continent, et ce n\\\'est pas avce vos v?tements miteux que vous allez y arriver. \\nIl vous faut une tenue plus appropri?e pour ce r?le, mais je ne connais pas les tailleurs d\\\'Amakna ni la mode actuelle.');
INSERT INTO `npc_questions` VALUES (8043, '', '', '', '', 'Si vous pensez qu\\\'il peut faire l\\\'affaire, allez le voir. Je vais vous donner des kamas pour vous faire tailler une tenue d?cente. \\nVous me rejoindrez ? la taverne, je vais organiser une rencontre avec mon p?re.');
INSERT INTO `npc_questions` VALUES (8044, '', '', '', '', 'C\\\'est une plaire ? une demoiselle ? \\nA son p?re ?!! Ca va ?tre tr???s difficile. Heureusement pour vous, j\\\'adooore les d?fis. \\nJe vais prendre vos mesures... Oh, le petit bidon, ?a manque d\\\'exercice tout ?a... Pour les cuisses par contre, rien ? dire, on voit que vous vous en servez souvent. \\nEtant donn? vos mensurations, je pr??conise une tenue l?g?re, tr?s styl?e et qui fera fuuureur si vous souhaitez la porter lors de la f?te du slip du Captain Chafer.');
INSERT INTO `npc_questions` VALUES (8045, '', '', '', '', 'Je ne parle pas aux mendiants, cessez donc de m\\\'importuner.');
INSERT INTO `npc_questions` VALUES (8046, '', '', '', '', 'Bonjour, croiser des personnes de votre allure et de votre rang est un ph?nom?ne rare. \\nQu\\\'est-ce qui vous am?ne ici ?');
INSERT INTO `npc_questions` VALUES (8047, '', '', '', '', 'C\\\'est assez... soudain comme demande, et quelque peu inhabituel. Remarquez, si cela pouvait lui faire oublier son Grom?o, je ne serais pas contre. \\nPrenez un verre et discutons, j\\\'aimerais en savoir plus ? votre sujet.');
INSERT INTO `npc_questions` VALUES (8048, '', '', '', '', '(...) \\nC\\\'est donc de l? que vient votre richesse. Tr?s astucieux, vraiment. \\nNous aussi, nous avons nos petites astuces. Oh, bien s?r, depuis la glaciation l\\\'exportation est au point mort, mais avec l\\\'ouverture d\\\'une nouvelle voie vers le continents, nous avons de nouveaux projets que nous souhaiterions mettre en place.');
INSERT INTO `npc_questions` VALUES (8049, '', '', '', '', 'Cette histoire de vol est un pr?texte du vieux Montay pour jeter le discr?dit sur notre maison. Il prend notre absence de preuves pour un aveu, mais il ignore qu\\\'en fait, nous lui dissimulons depuis un si?cle des arrangements commerciaux avec Edmond Santho afin d\\\'?viter qu\\\'il en profite. Si nous avons vendu plus de c?r?ales en 550, c\\\'est gr?ce ? ces arrangements. Jamais ma maison ne se serait abaiss?e ? voler, encore moins ? nos rivaux.');
INSERT INTO `npc_questions` VALUES (8050, '', '', '', '', 'Vous voil? enfin. J\\\'?tais venu vous pr?venir mais je suis arriv? trop tard. \\nLes hommes qui vous ont attaqu? sont ? la solde de mon p?re. Ma famille pense que vous ?tes ? Frigost pour permettre aux Capou?s de reprendre le dessus sur nous.');
INSERT INTO `npc_questions` VALUES (8051, '', '', '', '', 'Des arrangements vous dites ? Il faut en savoir plus sur cette famille Santho, mais ?a implique de retourner en Amakna pour consulter des archives. Ginette et moi devons rester ici pour temp?rer les rivalit?s entre nos familles. \\nMerci pour votre aide et bon courage.');
INSERT INTO `npc_questions` VALUES (8052, '', '', '', '', 'Si vous venez de la part de Raymond Santho, sachez que je ne c?derai jamais mes champs et que je refuse de cultiver ses c?r?ales transg?nis?es.');
INSERT INTO `npc_questions` VALUES (8053, '', '', '', '', 'Vous n\\\'?tes pas un de ses larbins ? Dans ce cas, je peux me calmer. \\nJe subis constamment des pression de la part de Raymond Santho, par le biais de ses hommes. Mon champ a d?j? ?t? br?l?, soi-disant accident naturel, feu de brousse, foudre sans qu\\\'il ait plut, etc. mais la v?rit?, c\\\'est que Raymond Santho veut me forcer ? vendre pour avoir le monopole de la culture et de la vente de c?r?ales ? Bonta. \\nSi vous voulez en savoir plus sur l\\\'origine de sa fortune, vous pouvez interroger une vieille amie de mon p?re. Il para?t qu\\\'elle a ?t? enferm? ? la prison de Madrestam pour trouble de l\\\'ordre public et destruction de c?r?ales transg?nis?es.');
INSERT INTO `npc_questions` VALUES (8054, '', '', '', '', 'Genre je vais finir mes vieux jours en prison. C\\\'est une conspiration, on cherche ? me faire taire mais l\\\'opinion publique doit conna?tre la v?rit? !');
INSERT INTO `npc_questions` VALUES (8055, '', '', '', '', 'Je ne dirai rien, sauf si tu m\\\'aides ? sortir de l? et ? m\\\'enfuir jusqu\\\'? l\\\'?le des wabbits. \\nEssaye de prendre les clefs ? Gemf? Labelle mais fais-le en douceur, c\\\'est pas un mauvais bougre.');
INSERT INTO `npc_questions` VALUES (8056, '', '', '', '', 'O? ?a ? O? ?a ?');
INSERT INTO `npc_questions` VALUES (8057, '', '', '', '', 'Je vais partir finir mes jours sur l\\\'?le des wabbits, loin des complots et des pressions ?conomiques.');
INSERT INTO `npc_questions` VALUES (8058, '', '', '', '', 'J\\\'ai travaill? pour Edmond Santho et Simon Santho. Quand Raymond Santho a succ?d? ? son p?re, j\\\'ai pris ma retraite. \\nQuand j\\\'?tais plus jeune, vers l\\\'an 550 je crois, j\\\'ai a vol? des c?r?ales dans les cales de bateaux en provenance de Frigost. Nous ?tions une dizaine de personnes au service d\\\'Edmond Santho. Il nous a tous pay?s grassement en ?change de notre silence, et ceux qui le souhaitaient pouvaient continuer ? travailler pour lui pour accumuler les kamas, c\\\'est ce que j\\\'ai fait. \\nR?cemment, sans doute ? cause de la vieillerie mais aussi ? cause de ce que la famille Santho a fait ? un viel ami et son fils, j\\\'ai eu des scrupules et j\\\'ai voulu d?noncer les activit?s malhonn?tes de la famille Santho. On m\\\'a alors jet?e manu militari dans les ge?les pour me faire taire.');
INSERT INTO `npc_questions` VALUES (8059, '', '', '', '', 'Ce que Raymond Santho ignore, c\\\'est que j\\\'ai d?rob? des documents compromettant son p?re et son grand-p?re vis-?-vis des exportateurs Frigostiens. Comme j\\\'ai entendu dire qu\\\'une voie maritime avait ?t? rouverte jusqu\\\'? l\\\'?le, ces documents risquent de faire du bruit. \\nJe te les confie, je suis trop vieille et trop lasse pour m\\\'occuper de ?a. \\nBonne chance');
INSERT INTO `npc_questions` VALUES (8060, '', '', '', '', 'Ah, c\\\'est vous. Avec ce vent et cette neige, je ne vous avais pas reconnu. \\nMerci pour ces documents mais le temps presse. Ginette a ?t? enlev?e par un Kaniglou. J\\\'ai tent? de les suivre dans la neige mais des smilomouths m\\\'ont contraint ? rebrousser chemin. \\nJe vous en supplie, sauvez-la.');
INSERT INTO `npc_questions` VALUES (8061, '', '', '', '', 'Le kaniglou ne va pas tarder ? revenir. \\nC\\\'est trop tard, le voil? !');
INSERT INTO `npc_questions` VALUES (8062, '', '', '', '', 'Merci d\\\'avoir sauv? Ginette. Gr?ce ? votre enqu?te, nous allons pouvoir essayer de faire entendre raison ? nos familles. \\nNous avons pris ces documents ? nos p?res, peut-?tre qu\\\'ils vous aideront ? mieux comprendre ce qui s\\\'est pass? ici jadis.');
INSERT INTO `npc_questions` VALUES (8063, '', '', '', '', 'Nous n\\\'oublierons jamais ce que vous avez fait pour nous. \\nCe n\\\'est plus qu\\\'une question de temps avant que nos familles acceptent notre union.');
INSERT INTO `npc_questions` VALUES (8064, '', '', '', '', 'Merci de m\\\'avoir sauv?e. Gr?ce ? votre enqu?te, nous allons pouvoir essayer de faire entendre raison ? nos familles. \\nNous avons pris ces documents ? nos p?res, peut-?tre qu\\\'ils vous aideront ? mieux comprendre ce qui s\\\'est pass? ici jadis.');
INSERT INTO `npc_questions` VALUES (8065, '', '', '', '', 'Merci pour votre aide. \\nNos familles finiront par se r?concilier et nous leur montrerons la voie.');
INSERT INTO `npc_questions` VALUES (8070, '', '', '', '', 'gr?ce ? votre aide, mes exp?riences vont bon train. \\nJe n\\\'ose pas vous le demander car c\\\'est dangereux, mais je n\\\'ai personne d\\\'autre sous la main. \\nPourriez-vous m\\\'apporter 70 Saule en si je vous prie ? J\\\'en ai besoin pour concocter des potions m?dicinales destin?es ? Albert Paisse, notre m?decin. Depuis la glaciation, les fant?mes de pirates du berceau d\\\'Alma ce les sont appropri?es.');
INSERT INTO `npc_questions` VALUES (8073, '', '', '', '', 'Avec ce stock, je vais pouvoir cultiver beaucoup de fleurs et fabriquer plein de potions m?dicinales, ce qui signifie plus de personnes soign?es. Albert Paisse va ?tre content, pour s?r.');
INSERT INTO `npc_questions` VALUES (8074, '', '', '', '', 'Un si?cle de glaciation... Je pense que c\\\'est suffisant, vous ne croyez pas ? Ah, si seulement le Comte Harebourg acceptait de se repentir, peut-?tre que la mal?diction serait lev?e. \\nJe pense que le renouement du contact avec le continent est un signe. Frigost doit se pr?parer ? revivre, il faut donc anticiper la fin de l\\\'hiver. \\nJ\\\'ai ou?e dire que beaucoup d\\\'agriculteurs esp?raient retrouver la situation d\\\'antan. Ces idiots n\\\'ont toujours rien compris et c\\\'est ? nous, alchimistes instruits, de leur montrer la voie. \\nJ\\\'ai besoin de nouvelles plantes qui poussent au nord de l\\\'?le. Il y a des Roses ? lys Cullen, farouchement d?fendues par les cr?atures des larmes d\\\'Ouronigride, et les Roses Delima, qui ne poussent que dans des circonstances pr?cises, pr?s des sources d\\\'eau chaude. Il m\\\'en faut 75 et 10.');
INSERT INTO `npc_questions` VALUES (8075, '', '', '', '', 'Dans l\\\'ensemble, les agriculteurs ne sont pas assez cultiv?s pour apprendre de leurs erreurs. Ils ont l\\\'esprit trop ?troit et leur manque d\\\'?ducation n\\\'arrange rien. Heureusement, ce n\\\'est pas le cas de nous autres, alchimistes. Nous allons d?velopper la culture des plantes et cr?er de nouvelles esp?ces, ce sera le fer de lance de notre ?conomie lorsque l\\\'hiver prendra fin, et ce sera la raison qui nous guidera, pas la cupidit?. \\nOh, c\\\'est fleurs sont pour moi ? Vous n\\\'avez pas eu trop de mal ? vous les procurer ? En tout cas, vous ?tes toujours en vie, c\\\'est l\\\'essentiel.');
INSERT INTO `npc_questions` VALUES (8076, '', '', '', '', 'Un bon alchimiste se doit d\\\'?tre pr?voyant, il doit donc montrer d\\\'excellentes aptitudes ? anticiper les ?v?nements. \\nVous savez d?j? que l\\\'?le de Frigost a une activit? g?othermique et volcanique tr?s importante. Il se pourrait donc, qu\\\'un jour, le climat de l\\\'?le soit compl?tement invers? et la plupart des plantes n\\\'y survivraient pas si elles n\\\'ont pas ?t? modifi?es au pr?alable pour r?sister ? des temp?ratures ?lev?es. \\nPour se faire, j\\\'ai besoin de 80 Ell?bore d\\\'Hel et 10 B?toine Agayne. Depuis la fermeture des mines, nous n\\\'avons plus acc?s ? ces plantes, qui sont pourtant abondantes dans les tunnels de lave.');
INSERT INTO `npc_questions` VALUES (8077, '', '', '', '', 'Les changements brusques de temp?rature n\\\'ont pas l\\\'air de t\\\'avoir affect? outre mesure. Si j\\\'arrive ? faire des plantes ? ton image, elles auront une r?sistance ? toute ?preuve. \\nGr?ce ? ton aide pr?cieuse, je vais pouvoir attirer de nombreux alchimistes pour d?velopper des plantes aux propri?t?s tr?s diff?rentes et ainsi supplanter l\\\'agriculture. De cette mani?re, les probl?mes survenus ? cause de la concurrence agricole entre Frigost et Amakna, et l\\\'?pisode tragique du Comte Harebourg deviendront un mauvais souvenir. \\nJ\\\'ai encore du pain sur la planche pour faire ?voluer les mentalit?s des Frigostiens. Il sera s?rement plus ais? de convaincre les habitants du village enseveli lorsque vous nous aurez d?barrass? de l\\\'hiver et que notre maire aura lev? l\\\'interdit emp?chant toute communication avec nos voisins.');
INSERT INTO `npc_questions` VALUES (8080, '', '', '', '', 'Pleni le Jeune est venu qu?rir mon aide pour retrouver son oncle, Pleni l\\\'Ancien. Ce dernier a disparu lors d\\\'un voyage d\\\'?tude dans les larmes d\\\'Ouronigride. Bien que je ne soit pas un aventurier, j\\\'ai promis ? mon jeune ami de retrouver son oncle. J\\\'ai donc besoin de votre aide pour y parvenir, qu\\\'en dites-vous ?');
INSERT INTO `npc_questions` VALUES (8081, '', '', '', '', 'Ce naturaliste et ancien ?l?ve du c?l?bre vulcanologue Hazieff Taroun a propos? d\\\'utiliser des crapeurs domestiqu?s pour aider au d?gel du port et de la bourgade. Selon lui, cette solution ?cologique permettrait de r?duire la consommation de combustible, de bois notamment, et l\\\'entretien de la tuyauterie qui traverse l\\\'?le. \\nLe conseil municipal lui a demand? de faire une d?monstration avant de d?bloquer des fonds et des hommes pour l\\\'assister dans ce projet. Il est donc reparti dans les larmes d\\\'Ouronigride et depuis, nous n\\\'avons plus de nouvelles. \\nAcceptez-vous de partir ? sa recherche ?');
INSERT INTO `npc_questions` VALUES (8082, '', '', '', '', 'Je dois prouver au conseil municipal que mon projet est viable. Nous pourrons ainsi utiliser une partie de la main-d\\\'oeuvre actuelle sur d\\\'autres travaux et r?duire la d?forestation de l\\\'?le.');
INSERT INTO `npc_questions` VALUES (8083, '', '', '', '', 'Vous vous demandez sans doute comment je compte y parvenir ? Et bien sachez que nombre de Frigostiens, dont je fais partie, sont devenus experts en g?othermie. Certains de mes coll?gues ont ?t? form?s par le Comte Harebourg et ont travaill?. Quant aux autres et moi-m?me, nous avons suivi les enseignements du c?l?bre vulcanologue Hazieff Taroun. \\nNous avons beaucoup profit? de ces enseignements, et c\\\'est d\\\'ailleurs en partie gr?ce ? eux que je suis l? aujourd\\\'hui.');
INSERT INTO `npc_questions` VALUES (8084, '', '', '', '', 'Une question intelligente, ?a change. \\nApr?s avoir longuement ?tudi? les crapeurs et les autres esp?ces vivant dans les larmes d\\\'Ouronigride, j\\\'ai d?cid? de passer ? l\\\'?tape suivante de mon projet : la domestication. \\nApr?s plusieurs essais infructueux, j\\\'ai compris qu\\\'il me fallait une assistance magique. Judas Sticau est l\\\'homme qu\\\'il me faut ! Malheureusement, il est port? disparu depuis sa tentative de retrouver l\\\'?t? en moins de 48h, plus vite que Le Redout?. A ma connaissance, la derni?re personne ? l\\\'avoir vu est le Capitaine Gneux. \\nSi vous retrouvez Judas Sticau, je pourrai mener mon projet ? bien et d?montrer son efficacit? au conseil municipal.');
INSERT INTO `npc_questions` VALUES (8085, '', '', '', '', 'Dis donc, tu viens du contient, toi. Ca veut dire que t\\\'as acc?s ? des boissons que nous n\\\'avons plus en r?serve depuis des d?cennies. \\nPassons un march?. Tu m\\\'apportes une nouvelle boisson du continent dont je ne connais pas la saveur et je te dis ce que tu veux entendre.');
INSERT INTO `npc_questions` VALUES (8086, '', '', '', '', 'Oh la belle bouteille. Tu vaux des informations sur Judas Sticau, c\\\'est ?a ?');
INSERT INTO `npc_questions` VALUES (8087, '', '', '', '', 'Celle-l?, je vais la garder longtemps. \\nMaintenant, je me souviens que Judas Sticau parlait de se servir de l\\\'?nergie g?othermique accessible depuis les larmes d\\\'Ouronigride pour retrouver l\\\'?t?. Il ?tait compl?tement givr?. \\nLe mieux que t\\\'as ? faire, c\\\'est de chercher des indices sur les cr?atures de vapeur. Je suis s?r que ces ?tres sournois sont ? l\\\'origine de la disparition de Judas.');
INSERT INTO `npc_questions` VALUES (8088, '', '', '', '', 'Bizarre, on dirait qu\\\'il est tomb? amoureux de vous. C\\\'est bien la premi?re fois que j\\\'assiste ? ce type de comportement. D\\\'habitude, les atomystiques ont un comportement explosif. \\nAttendez... Cet atomystique est ?trange, regardez son regard. Mais si, l?, vous ne voyez pas ? Ce ne sont pas des yeux d\\\'atomystique, ?a sent le mal?fice ? plein nez. \\nJe ne peux rien y faire mais vous feriez mieux de vous d?p?cher d\\\'apporter cette cr?ature ? Eric Azaraille si vous voulez savoir de quoi il en retourne.');
INSERT INTO `npc_questions` VALUES (8089, '', '', '', '', 'Allez savoir pourquoi, il est revenu ici. \\nTenez, vous voyez, il s\\\'est d?j? recoll? ? vous. Vous et lui devez avoir des atomes crochus.');
INSERT INTO `npc_questions` VALUES (8096, '', '', '', '', 'Juste ce qu\\\'il me manquait. \\nVous voulez vraiment que je fasse boire ?a ? l\\\'atomystique ? Je me suis habitu? ? sa compagnie, vous savez. \\nTr?s bien, c\\\'est vous qui voyez. \\nAttention, fermez les yeux et la bouche, bouchez-vous le nez et les oreilles.');
INSERT INTO `npc_questions` VALUES (8099, '', '', '', '', 'J\\\'accepte de t\\\'accompagner jusqu\\\'? lui, je n?gocierai directement avec lui les termes de mon aide. \\nTu es s?r que tu ne veux pas de philtre d\\\'amour ? Tu as l\\\'air d\\\'en avoir besoin pourtant. Ecoute, pour deux philtres d\\\'amour achet?s, je t\\\'offre un talisman qui prot?ge tes arri?res contre l\\\'agression des trools sidimotes. \\nVraiment pas ? Si tu changes d\\\'avis, tu sais o? me trouver.');
INSERT INTO `npc_questions` VALUES (8100, '', '', '', '', 'N\\\'approchez pas ou ce crapeur se faufilera dans mes narines pour me vaporiser le cerveau.');
INSERT INTO `npc_questions` VALUES (8101, '', '', '', '', 'Durant votre absence, qui a dur? une ?ternit?, le crapeur que j\\\'essayais de domestiquer m\\\'a pris en otage. Il veut n?gocier ma lib?ration.');
INSERT INTO `npc_questions` VALUES (8102, '', '', '', '', '- proposer une serviette de bain pour que Beulin puisse se s?cher apr?s une s?ance de jacuzzi. \\n- proposer un voyage avec escale dans la tuyauterie de Frigost, en passant par le Berceau d\\\'Alma, la for?t des pins perdus, les champs gel?s et la bourgade, pour arriver au port.');
INSERT INTO `npc_questions` VALUES (8103, '', '', '', '', 'Les dieux soient b?nis, il a accept? votre proposition. \\nJe vais rester ici et, avec l\\\'aide de Judas Sticau, menez mon projet ? son terme. \\nPuisque vous aimez rendre service, sacehz qu\\\'il existe un village ? proximit?. Vous pouvez l\\\'atteindre en traversant la crevasse Perge. Il a ?t? recouvert par une avalanche et les gens qui y vivent sont des alli?s et anciens serviteurs du Comte Harebourg. \\nNotre maire a interdit tout contact avec ce village alors r?fl?chissez-y ? deux fois avant de d?cider de vous y rendre.');
INSERT INTO `npc_questions` VALUES (8104, '', '', '', '', 'Enfin une bonne nouvelle, Pleni le Jeune va ?tre content de l\\\'apprendre. Moi-m?me, je suis heureux de savoir que mon vieil ami va bien et, qu\\\'en plus, vous avez retrouv? Judas Sticau. \\nQuand j\\\'y pense, vous vous ?tes tellement pr?cipit? que vous ne m\\\'avez m?me pas laiss? le temps de vous parler de la r?gion. Les larmes d\\\'Ouronigride poss?dent une activit? g?othermique tr?s importante et beaucoup d\\\'?tudes ont ?t? men?es sur cette zone. C\\\'est une science m?connue en dehors de l\\\'?le et parfois mal per?ue par les divinit?s, qui n\\\'appr?cient pas qu\\\'un potentiel naturel venant des entrailles de la terre puisse ?tre d?tourn? pour r?cup?rer une ?nergie trop puissante si elle est utilis?e ? mauvais escient. \\nEn y r?fl?chissant, peut-?tre avons-nous une part de responsabilit? dans ce qui est arriv? ? l\\\'?le.');
INSERT INTO `npc_questions` VALUES (8114, '', '', '', '', 'Cet un miracle que ce livre ne se soit pas compl?tement d?sagr?g?. Si vous me le laissez, je pourrai peut-?tre le restaurer, qu\\\'en dites-vous ?');
INSERT INTO `npc_questions` VALUES (8115, '', '', '', '', 'Merci. Si vous en trouvez d\\\'autres, n\\\'h?sitez pas ? me les apporter. De cette fa?on, je pourrai mettre leur contenu ? la disposition de tous.');
INSERT INTO `npc_questions` VALUES (8116, '', '', '', '', 'O? avez-vous trouv? ?a ? Vous l\\\'avez lu ? \\nVous avez bien fait de me l\\\'apporter, il aurait pu tomber entre de mauvaises mains. Vous aller me le confier, n\\\'est-ce pas ?');
INSERT INTO `npc_questions` VALUES (8117, '', '', '', '', 'Vous avez fait le bon choix. Je vais imm?diatement le consigner dans les archives. \\nVoici quelques kamas pour vous d?dommager, je vous en redonnerai si vous m\\\'apportez d\\\'autres livres.');
INSERT INTO `npc_questions` VALUES (9210, '', '', '', '', 'Bonjour ! Je suis Rudy Stribu, je redistribue les cadeaux que Iop a laissés pour vous en quittant le monde des Douze. Choisissez le cadeau qui vous conviens le mieux, je vous l\\\'offrirai en échange d\\\'un jeton de iop !');
INSERT INTO `npc_questions` VALUES (9255, '9655', '', '', '', 'C\\\'est certainement le plus beau m?tier du monde, apr?s celui de Gardien de phare de l\\\'?le de Moon, Percepteur, P?tissier Magicien, Dompteur de Greu, et Empailleur de Bwork Mages. Il faut juste savoir accepter les al?as climatiques et faire fi des politiques de restrictions qui nous forcent ? mettre nos champs en jach?re. \\nC\\\'est un m?tier difficile, mais id?al pour ceux qui aiment ?tre en phase avec la nature, et je me ferai un plaisir de transmettre mon savoir ? quiconque le d?sire.');
INSERT INTO `npc_questions` VALUES (9256, '9656', '', '', '', 'Les Boulangers sont des personnes respectables qui cuisent du pain pour les autres. \\nNous autres Boulangers sommes respect?s, dans la mesure o? nous permettons aux aventuriers affaiblis de reprendre des forces en mangeant nos pains.  \\nPlus un Boulanger est exp?riment?, plus il cuit de bons pains, et plus les pains sont bons, plus ils restaurent la sant? des aventuriers affaiblis. \\nLes Boulangers utilisent un Rouleau P?trisseur pour faire leur p?te ? pain.');
INSERT INTO `npc_questions` VALUES (9649, '', '', '', '', 'Eh bien, pour commencer il faudrait déjà que tu te places en face de moi, tu ne vas pas jouer par terre, non ?');
