INSERT INTO `npc_reponses_actions` VALUES (3425, 1, 'DV', 'Je suis prêt !');
INSERT INTO `npc_reponses_actions` VALUES (3426, 1, 'DV', 'A ton service, Bwork !');
INSERT INTO `npc_reponses_actions` VALUES (3427, 1, 'DV', 'Mon employeur a de quoi payer.');
INSERT INTO `npc_reponses_actions` VALUES (3428, 1, 'DV', 'Mon employeur est un ministre du roi Allister.');
INSERT INTO `npc_reponses_actions` VALUES (3429, 1, 'DV', 'Je ne sais pas.');
INSERT INTO `npc_reponses_actions` VALUES (3430, 1, 'DV', 'Seul votre talent et votre puissance peuvent servir à cette tâche...');
INSERT INTO `npc_reponses_actions` VALUES (3433, 1, 'DV', 'Non, je ne suis pas prêt');
INSERT INTO `npc_reponses_actions` VALUES (3434, 1, 'DV', 'D\'accord.');
INSERT INTO `npc_reponses_actions` VALUES (3435, 1, 'DV', 'Non, je ne suis pas prêt');
INSERT INTO `npc_reponses_actions` VALUES (3436, 1, 'DV', 'D\'accord.');
INSERT INTO `npc_reponses_actions` VALUES (3441, 1, 'DV', 'Non, je suis juste de passage.');
INSERT INTO `npc_reponses_actions` VALUES (3442, 1, 'DV', 'Je viens vous prévenir qu\'un grand danger pèse sur le Roi.');
INSERT INTO `npc_reponses_actions` VALUES (3446, 1, 'DV', 'Oui.');
INSERT INTO `npc_reponses_actions` VALUES (3447, 1, 'DV', 'Non.');
INSERT INTO `npc_reponses_actions` VALUES (3450, 1, 'DV', 'Oui, ce contrat entre Vil Smisse et Yse Vewybad.');
INSERT INTO `npc_reponses_actions` VALUES (3451, 1, 'DV', 'Non.');
INSERT INTO `npc_reponses_actions` VALUES (3452, 1, 'DV', 'Intendant Lavalss, le plaisir est mien.');
INSERT INTO `npc_reponses_actions` VALUES (3453, 1, 'DV', 'Je me mets au service du roi à l\'instant.');
INSERT INTO `npc_reponses_actions` VALUES (3454, 1, 'DV', 'J\'ai peur de ne pas être la personne adéquate.');
INSERT INTO `npc_reponses_actions` VALUES (3455, 1, 'DV', 'C\'est vrai, vous êtes aussi fameux pour vos prédictions que pour vos vêtements.');
INSERT INTO `npc_reponses_actions` VALUES (3456, 1, 'DV', 'Ah ? Vous avez du talent ?');
INSERT INTO `npc_reponses_actions` VALUES (3457, 1, 'DV', 'Je vous apporte ça de suite.');
INSERT INTO `npc_reponses_actions` VALUES (3458, 1, 'DV', 'Pas question, j\'ai autre chose.');
INSERT INTO `npc_reponses_actions` VALUES (3459, 1, 'DV', 'Ah non, je ne me sens pas prêt.');
INSERT INTO `npc_reponses_actions` VALUES (3460, 1, 'DV', 'Bien sûr que je suis prêt.');
INSERT INTO `npc_reponses_actions` VALUES (3462, 1, 'DV', 'Non.');
INSERT INTO `npc_reponses_actions` VALUES (3463, 1, 'DV', 'Oui.');
INSERT INTO `npc_reponses_actions` VALUES (3464, 1, 'DV', 'JE suis le Prince!');
INSERT INTO `npc_reponses_actions` VALUES (3465, 1, 'DV', 'Je me suis hâté pour mettre fin à cet horrible mariage!');
INSERT INTO `npc_reponses_actions` VALUES (3466, 1, 'DV', 'Euh, je ne suis pas sûr d\'être le mieux placé pour ça...');
INSERT INTO `npc_reponses_actions` VALUES (3467, 1, 'DV', 'Euh, d\'accord !');
INSERT INTO `npc_reponses_actions` VALUES (3468, 1, 'DV', 'Euh, pas vraiment, désolé... A plus tard !');
INSERT INTO `npc_reponses_actions` VALUES (3469, 1, 'DV', 'Bien sûr !');
INSERT INTO `npc_reponses_actions` VALUES (3470, 1, 'DV', 'Je ne peux pas chercher de Lenald pour le moment.');
INSERT INTO `npc_reponses_actions` VALUES (3471, 1, 'DV', 'Bien sûr !');
INSERT INTO `npc_reponses_actions` VALUES (3472, 1, 'DV', 'Bon je vois que les Lenalds sont des lâches !');
INSERT INTO `npc_reponses_actions` VALUES (3473, 1, 'DV', 'Ce mariage va souder Amakna et les Wabbits, vos ennemis julés.');
INSERT INTO `npc_reponses_actions` VALUES (3474, 1, 'DV', 'Allez, un peu de courage, je ne vais pas tout faire !');
INSERT INTO `npc_reponses_actions` VALUES (3475, 1, 'DV', 'Je vais entrer dans le château et vous pourrez vous téléporter sur moi.');
INSERT INTO `npc_reponses_actions` VALUES (3477, 1, 'DV', 'Bien nous avons un accold.');
INSERT INTO `npc_reponses_actions` VALUES (3478, 1, 'DV', 'Excusez-moi mon seigneur, mais un Tofu est une créature extrêmement faible...');
INSERT INTO `npc_reponses_actions` VALUES (3479, 1, 'DV', 'Hum, oui, je vous le laisse, d\'accord?');
INSERT INTO `npc_reponses_actions` VALUES (3480, 1, 'DV', 'Rien, je ne fais que passer.');
INSERT INTO `npc_reponses_actions` VALUES (3481, 1, 'DV', 'Je suis à la recherche d\'un prétendant pour la fille du frère du roi, la princesse Allisteria.');
INSERT INTO `npc_reponses_actions` VALUES (3482, 1, 'DV', 'Mon seigneur, où sont vos gens, vous ne pouvez demander la main de la princesse ainsi.');
INSERT INTO `npc_reponses_actions` VALUES (3483, 1, 'DV', 'Vous, un Wabbit, épouser la princesse Allisteria? C\'est ridicule!');
INSERT INTO `npc_reponses_actions` VALUES (3485, 1, 'DV', 'Vous n\'avez rien entendu ?');
INSERT INTO `npc_reponses_actions` VALUES (3486, 1, 'DV', 'Ah non, ce travail n\'est pas pour moi!');
INSERT INTO `npc_reponses_actions` VALUES (3487, 1, 'DV', 'A votwe sewvice, votwe Seigneuwie!');
INSERT INTO `npc_reponses_actions` VALUES (3488, 1, 'DV', 'Certes, mais ce Wabbit est prince de sang, c\'est un grand honneur.');
INSERT INTO `npc_reponses_actions` VALUES (3489, 1, 'DV', 'Et alors? Les Pandawas paraissent souvent bizarres aux gens venant d\'autres régions!');
INSERT INTO `npc_reponses_actions` VALUES (3491, 1, 'DV', 'Les Pandawas sont tout aussi bizarres !');
INSERT INTO `npc_reponses_actions` VALUES (3492, 1, 'DV', 'Certes, mais ce Wabbit est prince de sang, c\'est un grand honneur.');
INSERT INTO `npc_reponses_actions` VALUES (3493, 1, 'DV', 'Bataille ? La chopine, oui! Fichus Pandawas !');
INSERT INTO `npc_reponses_actions` VALUES (3494, 1, 'DV', 'Et si je prouve qu\'il est fort ?');
INSERT INTO `npc_reponses_actions` VALUES (3495, 1, 'DV', 'Je vous vaincrai. Le prince étant plus fort que moi, cela prouvera sa valeur.');
INSERT INTO `npc_reponses_actions` VALUES (3496, 1, 'DV', 'Je vais voir si je peux trouver un cuisinier plus conciliant.');
INSERT INTO `npc_reponses_actions` VALUES (3497, 1, 'DV', 'Vous quitteriez Brâkmar...');
INSERT INTO `npc_reponses_actions` VALUES (3498, 1, 'DV', 'Pourquoi pas, vous n\'êtes bonne qu\'à ça, non ?');
INSERT INTO `npc_reponses_actions` VALUES (3499, 1, 'DV', 'Je vous propose 5000 kamas.');
INSERT INTO `npc_reponses_actions` VALUES (3500, 1, 'DV', 'Je vous propose 10000 kamas.');
