INSERT INTO `npc_reponses_actions` VALUES (3505, 1, 'DV', 'Le prince est généreux, il donne cinq mille kamas à ses valets jusqu\'à son mariage.');
INSERT INTO `npc_reponses_actions` VALUES (3507, 1, 'DV', 'Non, mais je vous indique un tailleur. Vous n\'avez qu\'à utiliser mes kamas.');
INSERT INTO `npc_reponses_actions` VALUES (3508, 1, 'DV', 'Donner les objets demandés.');
INSERT INTO `npc_reponses_actions` VALUES (3509, 1, 'DV', 'J\'y vais de ce pas!');
